D[7722] = {[1]="What the Flux?",[2]={{14624}},[3]={{14624}},[4]=45,[5]=50,[8]={"Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge."},[10]={[3]={{18922,nil,0}}},[17]=51,[23]=8}
D[7723] = {[1]="Curse These Fat Fingers",[2]={{14627}},[3]={{14627}},[4]=45,[5]=49,[8]={"Hansel Heavyhands wants you to kill 20 Heavy War Golems.","","The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge."},[10]={{{5854,nil,0}}},[17]=51,[23]=8}
D[7724] = {[1]="Fiery Menace!",[2]={{14627}},[3]={{14627}},[4]=45,[5]=49,[8]={"Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.","","Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders."},[10]={{{5858,nil,0}}},[17]=51,[23]=8}
D[7725] = {[1]="Again With the Zapped Giants",[2]={{14637}},[3]={{14637}},[4]=45,[5]=55,[8]={"Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas."},[10]={[3]={{18956,nil,0}}},[11]=18904,[13]={7003},[17]=357,[23]=256,[24]=1}
