D[7840] = {[1]="Lard Lost His Lunch",[2]={{14731}},[3]={{14731}},[4]=44,[5]=49,[6]=690,[8]={"Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.","","Lard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls."},[10]={[3]={{19034,nil,0}}},[17]=47,[23]=8}
D[7841] = {[1]="Message to the Wildhammer",[2]={{14738}},[3]={{14738}},[4]=44,[5]=48,[6]=690,[8]={"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.","","You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands."},[10]={{{2692,nil,0},{2691,nil,0},{2694,nil,0},{2693,nil,0}}},[17]=47,[22]=7842,[23]=8}
D[7842] = {[1]="Another Message to the Wildhammer",[2]={{14738}},[3]={{14738}},[4]=44,[5]=48,[6]=690,[8]={"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.","","Gryphons are known to inhabit every region of the Hinterlands."},[10]={[3]={{4589,nil,0}}},[13]={7841},[17]=47,[22]=7843}
D[7843] = {[1]="The Final Message to the Wildhammer",[2]={{14738}},[3]={{14738}},[4]=44,[5]=50,[6]=690,[8]={"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.","","Beware of angry Wildhammer dwarves and unruly members of the Alliance."},[11]=19036,[13]={7842},[17]=47,[23]=2,[24]=2}
D[7844] = {[1]="Cannibalistic Cousins",[2]={{14739}},[3]={{14739}},[4]=44,[5]=48,[6]=690,[8]={"Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 15 Vilebranch Scalpers and 10 Vilebranch Soothsayers. Return to her when this task is complete.","","Yayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands."},[10]={{{4466,nil,0},{4467,nil,0}}},[17]=47,[23]=8}
D[7845] = {[1]="Kidnapped Elder Torntusk!",[2]={{14736}},[3]={{14757}},[4]=46,[5]=51,[6]=690,[8]={"Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.","","You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands."},[17]=47,[22]=7846,[23]=8}
D[7846] = {[1]="Recover the Key!",[2]={{14757}},[3]={{14757}},[4]=46,[5]=51,[6]=690,[8]={"Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key."},[10]={[3]={{19064,nil,0}}},[13]={7845},[17]=47,[22]=7847}
