D[710] = {"Element-Studie: Fels",{"Sucht 10 kleine Felssplitter und bringt sie Lotwil Veriatus im Ödland."}}
D[711] = {"Element-Studie: Fels",{"Bringt Lotwil Veriatus im Ödland 3 große Steinplatten."}}
D[712] = {"Element-Studie: Fels",{"Bringt Lotwil Veriatus im Ödland 5 Armschienen der Steinbindung."}}
