D[719] = {"Ein Zwerg und sein Werkzeug",{"Sucht Roggendols Glückshacke und bringt sie Ausgrabungsleiter Roggendol in der Hammerzehs Grabungsstätte."}}
D[720] = {"Ein Hoffnungsschimmer",{"Sucht Ausgrabungsleiter Roggendol und teilt ihm mit, dass Hammerzeh Grez noch am Leben ist."}}
D[721] = {"Ein Hoffnungsschimmer",{"Sucht in Uldaman nach Hammerzeh Grez."}}
D[722] = {"Amulett der Geheimnisse",{"Sucht Hammerzehs Amulett und bringt es ihm nach Uldaman."}}
D[723] = {"Ein Funken Hoffnung",{"Bringt Ausgrabungsleiter Roggendol im Ödland Hammerzehs Amulett."}}
D[724] = {"Ein Funken Hoffnung",{"Bringt Historiker Karnik in Eisenschmiede Hammerzehs Amulett."}}
D[725] = {"Kunde über die Bedrohung breitet sich aus",{"Sucht Berater Belgrum und gebt ihm die Notiz."}}
D[726] = {"Kunde über die Bedrohung breitet sich aus",{"Sprecht mit Historiker Karnik."}}
D[727] = {"Auf nach Eisenschmiede zu 'Yagyins Zusammenstellung'",{"Gebt Gerrig Knochengriff im düsteren Viertel von Eisenschmiede das Siegelzeichen des Hammers."}}
D[728] = {"Auf nach Unterstadt zu 'Yagyins Zusammenstellung'",{"Bringt dem Bewahrer Bel'dugur in Unterstadt das Siegelzeichen des Hammers."}}
