D[730] = {"Ärger in Dunkelküste?",{"Reist nach Auberdine und sucht nach Hinweisen auf das Zwergenausgrabungsteam."}}
D[731] = {"Der geistesabwesende Ausgrabungsleiter",{"Beschützt Ausgrabungsleiter Wirrbart, während er nach dem rätselhaften Fossil sucht, und kehrt dann zur Archäologin Hollee in Auberdine zurück."}}
D[732] = {"Erdbeben",{"Beschafft für Garek das Zeichen der Erde."}}
D[733] = {"Schnorrerei",{"Bringt Sigrun 7 Teile Metallschrott."}}
D[734] = {"Das wird schwierig",{"Sprecht im Ödland mit Lucien Knobelzang."}}
D[735] = {"Der Stern, die Hand und das Herz",{"Bringt Gerrig Knochengriff in Eisenschmiede die Gegenstände in Knochengriffs Notiz."}}
D[736] = {"Der Stern, die Hand und das Herz",{"Bringt dem Bewahrer Bel'dugur in Unterstadt die Gegenstände von Bel'dugurs Notiz."}}
D[737] = {"Verbotenes Wissen",{"Bringt Theldurin 'Yagyins Zusammenstellung'."}}
D[738] = {"Sucht Agmond",{"Sucht Agmond."}}
D[739] = {"Murdaloc",{"Tötet Agmonds Mörder Murdaloc.","","Tötet 12 Knochenknacker der Steingrufttroggs.","","Erstattet Ausgrabungsleiter Eisenband am Loch Modan Bericht."}}
D[741] = {"Der geistesabwesende Ausgrabungsleiter",{"Bringt dem Chefarchäologen Grauflaum in Darnassus das rätselhafte Fossil."}}
D[742] = {"Die Jagd im Eschental",{"Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental."}}
D[743] = {"Windfuriengefahr",{"Bringt Ruul Adlerklaue im Dorf der Bluthufe 8 Windfurienkrallen."}}
D[744] = {"Vorbereitungen auf die Zeremonie",{"Sammelt 6 azurblaue und 6 bronzene Federn und bringt sie Eyahn Adlerklaue in Donnerfels."}}
D[745] = {"Gemeinsame Nutzung des Landes",{"Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Baine Bluthuf ins Dorf der Bluthufe zurück."}}
D[746] = {"Zwergenbuddelei",{"Sammelt 5 Ausgrabungsleiterhacken ein.","","Zerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.","","Bringt Baine Bluthuf im Dorf der Bluthufe 5 zerbrochene Werkzeuge."}}
D[747] = {"Die Jagd beginnt",{"Grull Falkenwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt."}}
D[748] = {"Vergiftetes Wasser",{"Bringt Mull Donnerhorn im Dorf der Bluthufe 6 Präriewolftatzen und 4 Ebenenschreiterkrallen."}}
D[749] = {"Die überfallene Karawane",{"Morin Wolkenpirscher möchte, dass Ihr den Inhalt einer Nachschubkiste der überfallenen Karawane untersucht."}}
D[750] = {"Die Jagd geht weiter",{"Grull Falkenwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt."}}
D[751] = {"Die überfallene Karawane",{"Bringt Morin Wolkenpirscher in der Nähe des Dorfs der Bluthufe die Dokumente der Venture Company."}}
D[752] = {"Eine bescheidene Bitte",{"Häuptling Falkenwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht."}}
D[753] = {"Eine bescheidene Bitte",{"Holt eine Wasserkanne vom Wasserbrunnen.","","Bringt die Kanne zu Häuptling Falkenwind im Camp Narache, das nordwestlich des Wasserbrunnens liegt."}}
