D[768] = {"Leder sammeln",{"Bringt Veren Weitschreiter in Donnerfels 12 Stücke leichtes Leder."}}
D[769] = {"Kodobalgtasche",{"Bringt Veren Weitschreiter in Donnerfels 4 Einheiten leichtes Leder und 4 grobe Fäden."}}
D[770] = {"Der Dämonennarbenumhang",{"Sucht jemanden, der etwas über Geistheuler weiß."}}
D[771] = {"Ritus der Sicht",{"Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Zwillingsmond ins Dorf der Bluthufe."}}
D[772] = {"Ritus der Sicht",{"Trinkt vor dem Stammesfeuer im Dorf der Bluthufe das Wasser der Seher und folgt der Vision, sobald sie erscheint."}}
D[773] = {"Ritus der Weisheit",{"Reist von Donnerfels gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist."}}
