D[837] = {"Übergriff",{"Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Klingenmähnen, 4 Späher der Klingenmähnen, 4 Staubläufer der Klingenmähnen und 4 Schlachtwachen der Klingenmähnen."}}
D[838] = {"Scholomance",{"Sprecht mit Apotheker Zitters am Bollwerk, westliche Pestländer."}}
D[840] = {"Freiwilliger der Horde",{"Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke.","","Macht bei dem Außenposten der Orcs auf der anderen Seite Halt.","","Gebt Kargal Schlachtnarbe im Brachlandaußenposten Euren Anwerbungsbrief."}}
D[841] = {"Eine weitere Kraftquelle?",{"Bringt Chefingenieur Bilgenritzel in Gadgetzan 10 Wasserbeutel eines Wüstenläufers im Austausch gegen eine weitere Kraftquelle."}}
D[842] = {"Wegekreuzwehrpflicht",{"Folgt der Straße von Kargals Fernwacht nach Westen.","","Wendet Euch bei der Einmündung nach links und folgt dann der Straße in südliche Richtung.","","Sucht Sergra Dunkeldorn an der Kreuzung zweier Straßen innerhalb der Siedlung des Wegekreuzes auf."}}
D[843] = {"Ganns Rekultivierung",{"Gann Steinkeil möchte, dass Ihr 15 Ausgräber von Bael'dun und 5 Großknechte von Bael'dun tötet.","","Bringt Gann Steinkeil dann Khazgorms Tagebuch."}}
