D[846] = {"Ganns Rache",{"Gann Steinkeil möchte, dass Ihr ihm 6 Phiolen Nitroglyzerin, 6 Teile Holzbrei und 6 Proben Natriumnitrat bringt."}}
D[847] = {"Arglist des Raptors",{"Sprecht mit Tor'gan."}}
D[848] = {"Pilzsporen",{"Bringt dem Apotheker Helbrim beim Wegekreuz 4 Pilzsporen."}}
D[849] = {"Ganns Rache",{"Zerstört den Flugapparat bei Bael Modan und kehrt dann zu Gann Steinkeil zurück."}}
D[850] = {"Anführer der Kolkar",{"Bringt Regthar Totenfurt westlich des Wegekreuzes Baraks Kopf."}}
D[851] = {"Verog der Derwisch",{"Bringt Regthar Totenfurt westlich des Wegekreuzes Verogs Kopf."}}
D[852] = {"Hezrul Blutmal",{"Bringt Regthar Totenfurt westlich des Wegekreuzes Hezruls Kopf."}}
D[853] = {"Apothekerin Zamah",{"Bringt der Apothekerin Zamah in Donnerfels die weiterverarbeiteten Sporen, bevor die Zeit abgelaufen ist."}}
D[854] = {"Reise zum Wegekreuz",{"Sprecht mit Thork beim Wegekreuz im Brachland."}}
D[855] = {"Zentaurenarmschienen",{"Bringt Regthar Totenfurt westlich des Wegekreuzes 15 Zentaurenarmschienen."}}
D[857] = {"Die Träne der Monde",{"Feegly der Verbannte möchte, dass Ihr ihm die Träne der Monde zurückbringt."}}
D[858] = {"Zündung",{"Holt den Zündschlüssel und bringt ihn Kurbelwizz."}}
D[860] = {"Sergra Dunkeldorn",{"Sprecht beim Wegekreuz mit Sergra Dunkeldorn."}}
D[861] = {"Der Weg der Jäger",{"Bringt Melor Steinhuf in Donnerfels 4 Flachlandstreunerklauen."}}
D[862] = {"Grubenratteneintopf",{"Bringt Grub östlich des Wegekreuzes 8 Grubenratten."}}
D[863] = {"Die Flucht",{"Schützt Kurbelwizz und den gestohlenen Goblinschredder auf dem Weg zu Stotterspritter in Ratschet."}}
D[864] = {"Kehrt zu Apothekerin Zinge zurück",{"Bringt das versiegelte Feldtestset nach Unterstadt zu Apothekerin Zinge."}}
D[865] = {"Raptorhörner",{"Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratschet."}}
D[866] = {"Wurzelproben",{"Bringt Mebok Mizzyrix in Ratschet 8 Wurzelproben."}}
D[867] = {"Räuberische Harpyien",{"Sammelt 8 Krallen der Hexenschwingen.","","Bringt sie Darsok Schnelldolch beim Wegekreuz."}}
D[868] = {"Eierjagd",{"Bringt Korran beim Wegekreuz 12 Silithideneier und die Grabgabel."}}
D[869] = {"Raptorendiebe",{"Bringt Gazrog beim Wegekreuz 12 Raptorenköpfe."}}
D[870] = {"Die vergessenen Teiche",{"Berichtet Tonga Runentotem von Euren Entdeckungen."}}
D[871] = {"Vereitelung der Angriffe",{"Tötet 8 Wassersucher, 8 Dornwirker sowie 3 Jäger des Klingenmähnenstamms und kehrt dann zu Thork beim Wegekreuz zurück."}}
