D[873] = {"Isha Awak",{"Bringt Mahren Himmelsdeuter das Herz von Isha Awak."}}
D[874] = {"Mahren Himmelsdeuter",{"Sprecht mit Mahren Himmelsdeuter."}}
D[875] = {"Offiziere der Harpyien",{"Sammelt 6 Harpyienoffiziersringe von den Tötern der Hexenschwingen und kehrt dann zu Darsok Schnelldolch beim Wegekreuz zurück."}}
D[876] = {"Serena Blutfeder",{"Erschlagt Serena Blutfeder und bringt Darsok Schnelldolch beim Wegekreuz ihren Kopf."}}
D[877] = {"Die brackige Oase",{"Kehrt zu Tonga beim Wegekreuz zurück, nachdem Ihr die brackige Oase untersucht habt."}}
D[878] = {"Stämme im Krieg",{"Erledigt 6 Wassersucher der Borstennacken, 12 Dornenwirker der Borstennacken sowie 12 Geomanten der Borstennacken und kehrt zu Quetschzahn im Camp Taurajo im Brachland zurück."}}
D[879] = {"Verräter in den eigenen Reihen",{"Tötet Nak, Kuz und Lok Orcfluch und bringt Quetschzahn im Camp Taurajo im Brachland ihre Schädel."}}
D[880] = {"Veränderte Wesen",{"Bringt Tonga Runentotem beim Wegekreuz 8 veränderte Schnappkieferschalen."}}
D[881] = {"Echeyakee",{"Bringt Sergra Dunkeldorn beim Wegekreuz Echeyakees Balg."}}
D[882] = {"Ishamuhale",{"Bringt Jorn Himmelsdeuter im Camp Taurajo Ishamuhales Fangzahn."}}
D[883] = {"Lakota'mani",{"Bringt Jorn Himmelsdeuter im Camp Taurajo Lakota'manis Huf."}}
D[884] = {"Owatanka",{"Bringt Jorn Himmelsdeuter im Camp Taurajo Owatankas Schwanzstachel."}}
D[885] = {"Washte Pawne",{"Bringt Jorn Himmelsdeuter im Camp Taurajo Washte Pawnes Feder."}}
D[886] = {"Die Oasen des Brachlandes",{"Sprecht beim Wegekreuz mit Tonga Runentotem."}}
D[887] = {"Südmeerfreibeuter",{"Tötet für Gazlowe in Ratschet 12 Briganten der Südmeerfreibeuter und 6 Kanoniere der Südmeerfreibeuter."}}
D[888] = {"Gestohlene Beute",{"Bringt Gazlowe in Ratschet die Stiefellieferung und die Teleskoplinse zurück."}}
D[889] = {"Geist des Windes",{"Bringt Quetschzahn 10 Blutsplitter und ich werde Euch mit großer Geschwindigkeit segnen. Ihr werdet mit den Zhevras laufen und der Wind wird eifersüchtig auf Euch sein.","","Es wird nicht lange anhalten, aber es sollte lange genug sein, um Euch zu helfen, durch das Brachland zu reisen."}}
D[890] = {"Die verloren gegangene Lieferung",{"Bringt Werftmeister Flunkerblick Gazlowes Geschäftsbuch."}}
D[891] = {"Die Kanonen von Nordwacht",{"Kapitän Thalo'thas Blendsonn aus Ratschet möchte, dass Ihr 10 Medaillen von Theramore sammelt und Hauptmann Hellstieg, Kanonier Knoch und Kanonier Hecksler tötet."}}
D[892] = {"Die verloren gegangene Lieferung",{"Bringt Gazlowe in Ratschet sein Geschäftsbuch zurück."}}
D[893] = {"Ausgewählte Waffen",{"Bringt Tatternack Stahlformer im Camp Taurajo im Brachland einen Klingenmähnenrückenstecher, einen verkohlten Klingenmähnenzauberstab und einen Klingenmähnenkriegsschild."}}
D[894] = {"Samophlang",{"Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company."}}
D[895] = {"GESUCHT: Baron Küstenschipper",{"Bringt Gazlowe in Ratschet Baron Küstenschippers Kopf."}}
D[896] = {"Des Minenarbeiters Vermögen",{"Beschafft Euch von einem der Vorarbeiter oder Vollstrecker der Venture Company den Katzenaugensmaragd und bringt ihn zu Werftmeister Flunkerblick in Ratschet."}}
D[897] = {"Der Ernter",{"Bringt den Ernterkopf zu Jorn Himmelsdeuter."}}
D[898] = {"Aus der Gefangenschaft befreit",{"Begleitet Gilthares Feuerzweig sicher zurück zu Kapitän Blendsonn in Ratschet."}}
D[899] = {"Von Hass zerfressen",{"Bringt Mankrik beim Wegekreuz 60 Stacheleberhauer der Borstennacken."}}
D[900] = {"Samophlang",{"Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole."}}
D[901] = {"Samophlang",{"Besorgt Euch bei Tüftler Kichers den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen."}}
D[902] = {"Samophlang",{"Bringt das Samophlang zu Stotterspritter in Ratschet."}}
D[903] = {"Streuner des Brachlandes",{"Besorgt für Sergra Dunkeldorn beim Wegekreuz 7 Streunerklauen von den Savannenstreunern."}}
D[905] = {"Die wütenden Sensenklauen",{"Tötet Bluthornraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sensenklauennestern. Kehrt zu Sergra Dunkeldorn beim Wegekreuz zurück."}}
D[906] = {"Verräter in den eigenen Reihen",{"Bringt Loks Schädel zu Thork beim Wegekreuz im Brachland."}}
D[907] = {"Wütende Donnerechsen",{"Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Himmelsdeuter."}}
D[908] = {"Inmitten der Ruinen",{"Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
D[909] = {"Baron Aquanis",{"Bringt die seltsame Wasserkugel zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
D[910] = {"Unten an den Docks",{"Bringt Euren Schützling in die Docks von Ratschet im Brachland."}}
D[911] = {"Das Tor zur Grenze",{"Begleitet Euren Schützling zum Schutzwall von Mor'shan im nördlichen Teil des Brachlands, kurz bevor man das Eschental betritt."}}
D[913] = {"Der Ruf des Donnerfalken",{"Sucht und erschlagt einen Donnerfalken und bringt Jorn Himmelsdeuter in Camp Taurajo seine Flügel."}}
D[914] = {"Anführer der Giftzähne",{"Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Donnerfels zu Nara Wildmähne."}}
D[915] = {"Lecker Eis",{"Besorgt für Euren Schützling etwas Erdbeereis. Der kleine scheint die Marke 'Tigule und Forors Eiscreme' zu bevorzugen."}}
D[916] = {"Waldwebergift",{"Bringt Gilshalan Windwandler in Aldrassil 10 Waldwebergiftbeutel."}}
D[917] = {"Waldweberei",{"Bringt Gilshalan in Aldrassil ein Waldweberei."}}
D[918] = {"Bäumlingssamenkörner",{"Bringt Denalan am Al'Amethsee 8 Bäumlingssamenkörner."}}
D[919] = {"Bäumlingssprosse",{"Bringt Denalan am Al'Amethsee 12 Bäumlingssprosse."}}
D[920] = {"Tenarons Einladung",{"Sprecht im Laubschattental über den Dächern von Aldrassil mit Tenaron Sturmgewalt."}}
D[921] = {"Krone der Erde",{"Füllt die Kristallphiole und bringt sie Tenaron Sturmgewalt über den Dächern von Aldrassil."}}
D[922] = {"Rellian Grünwipfel",{"Bringt Rellian Grünwipfel in Darnassus ein Bäumlingssamenkorn."}}
D[923] = {"Tumore",{"Bringt Rellian Grünwipfel in Darnassus 5 moosartige Tumore."}}
D[924] = {"Die Dämonensaat",{"Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück."}}
D[925] = {"Cairnes Hufabdruck",{"Reist nach Donnerfels und versucht für Euren Schützling einen Hufabdruck von Cairne Bluthuf zu ergattern."}}
D[926] = {"Fehlerhafter Kraftstein",{"Diese Steine sind von magischer Energie erfüllt, aber absichtlich fehlerhaft. Sie sind nicht sehr stabil, und sobald sie vom Tisch genommen werden, vernichten sie sich schnell selbst."}}
D[927] = {"Das moosumschlungene Herz",{"Bringt Denalan am Al'Amethsee das moosumschlungene Herz."}}
D[928] = {"Krone der Erde",{"Bringt Corithras Mondzorn in Dolanaar das teilweise gefüllte Gefäß."}}
D[929] = {"Krone der Erde",{"Füllt die Jadephiole und bringt sie Corithras Mondzorn in Dolanaar zurück."}}
D[930] = {"Die leuchtende Frucht",{"Bringt Denalan am Al'Amethsee die leuchtende Frucht."}}
D[931] = {"Der schimmernde Wedel",{"Bringt Denalan am Al'Amethsee einen der schimmernden Wedel."}}
D[932] = {"Krankhafter Hass",{"Tötet Lord Melenas und bringt Tallonkai Flinkwurzel in Dolanaar seinen Kopf."}}
D[933] = {"Krone der Erde",{"Füllt die Turmalinphiole und bringt sie Corithras Mondzorn in Dolanaar."}}
D[934] = {"Krone der Erde",{"Füllt die Amethystphiole und bringt sie Corithras Mondzorn in Dolanaar."}}
D[935] = {"Krone der Erde",{"Bringt dem Erzdruiden Fandral Hirschhaupt in Darnassus das gefüllte Gefäß."}}
D[936] = {"Erzdruide Runentotem helfen",{"Sprecht in Donnerfels mit Erzdruide Hamuul Runentotem."}}
D[937] = {"Die verzauberte Lichtung",{"Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Wolkenbruch in der Lichtung des Orakels."}}
D[938] = {"Nebel",{"Begleitet Nebel zur Schildwache Arynia Wolkenbruch beim Mondbrunnen in der Nähe des Orakelbaums."}}
D[939] = {"Flöte des Xavaric",{"Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Blauwind im südlichen Teil des Teufelswalds."}}
D[940] = {"Teldrassil",{"Überbringt dem Erzdruiden Fandral Hirschhaupt in Darnassus den Bericht des Orakelbaums."}}
D[941] = {"Das Einpflanzen des Herzens",{"Pflanzt das besudelte Herz in Denalans Blumentopf ein."}}
D[942] = {"Der geistesabwesende Ausgrabungsleiter",{"Bringt das rätselhafte Fossil zum Archäologen Magenbitter im Hafen von Menethil."}}
D[943] = {"Der geistesabwesende Ausgrabungsleiter",{"Der Archäologe Magenbitter im Hafen von Menethil möchte, dass Ihr ihm den Stein von Relu und Magenbitters Fossil bringt."}}
D[944] = {"Die Meistergleve",{"Tragt Informationen zusammen und benutzt dann die Wahrsagephiole, um eine Wahrsageschale zu erschaffen. Benutzt die Schale, um mit Onu zu sprechen."}}
D[945] = {"Therylunes Flucht",{"Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist."}}
D[947] = {"Höhlenpilze",{"Bringt Barithras Mondschatten in Auberdine 5 Schorfstänglinge und 1 Todeskappe."}}
D[948] = {"Onu",{"Sprecht im Hain der Uralten mit Onu."}}
D[949] = {"Das Lager des Schattenhammers",{"Sucht im Lager des Schattenhammerklans in der Meistergleve nach einem Hinweis."}}
D[950] = {"Rückkehr zu Onu",{"Bringt Onu das irrsinnige Gekritzel, das Ihr gefunden habt."}}
D[951] = {"Relikte von Mathystra",{"Bringt 6 Relikte von Mathystra zu Onu in den Hain der Uralten."}}
D[952] = {"Der Hain der Uralten",{"Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine."}}
D[953] = {"Der Untergang von Ameth'Aran",{"Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Mondklinge in Dunkelküste zurück."}}
D[954] = {"Bashal'Aran",{"Sucht in den Ruinen von Bashal'Aran nach der Quelle der seltsamen blauen Aura."}}
D[955] = {"Bashal'Aran",{"Beschafft für Asterion in Bashal'Aran 8 Grellohrringe."}}
D[956] = {"Bashal'Aran",{"Beschafft das alte Mondsteinsiegel und bringt es Asterion in Bashal'Aran."}}
D[957] = {"Bashal'Aran",{"Zerstört das alte Mondsteinsiegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück."}}
D[958] = {"Werkzeuge der Hochgeborenen",{"Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine."}}
D[959] = {"Ärger auf den Docks",{"Kranführer Moppelfuzz in Ratschet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99 Jahre altem Portwein wieder abnehmt."}}
D[960] = {"Onu meditiert"}
D[961] = {"Onu meditiert"}
D[962] = {"Schlangenflaum",{"Die Apothekerin Zamah in Donnerfels möchte, dass Ihr zehn Schlangenflaum für sie sammelt."}}
D[963] = {"In ewiger Liebe",{"Befreit den Geist von Anaya Dämmerflucht und bringt ihren Anhänger zu Cerellean Weißklaue in Auberdine."}}
D[964] = {"Skelettfragmente",{"Bringt 15 Skelettfragmente zu Apotheker Zitters am Bollwerk, westliche Pestländer."}}
D[965] = {"Der Turm von Althalaxx",{"Sucht Balthule Schattenhieb in der Nähe des Turms von Althalaxx in Dunkelküste."}}
D[966] = {"Der Turm von Althalaxx",{"Sammelt 4 abgenutzte Pergamentfetzen für Balthule Schattenhieb in der Nähe des Turms von Althalaxx."}}
D[967] = {"Der Turm von Althalaxx",{"Überbringt Delgren dem Läuterer im Eschental Balthules Brief."}}
D[968] = {"Die Macht in der Tiefe",{"Bringt das Buch: 'Die Macht in der Tiefe' zu Gerrig Knochengriff im düsteren Viertel in Eisenschmiede."}}
D[969] = {"Das Glück sei mit Euch",{"Sammelt 4 Frosthagelsplitter für die Hexendoktorin Mau'ari in der Ewigen Warte."}}
D[970] = {"Der Turm von Althalaxx",{"Beschafft einen leuchtenden Seelenedelstein und bringt ihn Delgren dem Läuterer in Maestras Posten."}}
D[971] = {"Wissen in der Tiefe",{"Bringt das Manuskript von Lorgalis zu Gerrig Knochengriff in Eisenschmiede."}}
D[972] = {"Wassersapta",{"Nehmt das Wassersapta und sucht in Silberwald nach dem verderbten Teich, <Name>. Ich habe großes Vertrauen in Eure Fähigkeiten."}}
D[973] = {"Der Turm von Althalaxx",{"Bringt Delgren dem Läuterer in Maestras Posten Ilkrud Magskluves Folianten."}}
D[974] = {"Die Quelle finden",{"Krakle im Krater von Un'Goro möchte, dass Ihr den heißesten Bereich des Feuersäulengrats findet.","","Immer, wenn Ihr eine heiße Stelle findet, klickt Ihr das Thermometer mit der rechten Maustaste an, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt."}}
D[975] = {"Behälter von Mau'ari",{"Wartet einen Moment und sprecht dann erneut mit Hexendoktorin Mau'ari, um den Glücksbringer zu erhalten."}}
D[976] = {"Nachschub für Auberdine",{"Sprecht mit Delgren dem Läuterer bei Maestras Posten, nachdem Ihr Feero sicher durch das Eschental geführt habt."}}
D[977] = {"Sind wir endlich da, Yeti?",{"Sammelt 2 makellose Yetihörner für Umi Rumpelkicher in der Ewigen Warte."}}
D[978] = {"Mondbestrahltes Wildekin",{"Sammelt 10 mondbestrahlte Federn aus Winterquell und kehrt dann zu Erelas Himmelsbern in Rut'theran zurück."}}
D[979] = {"Ranshalla suchen",{"Sucht nach Ranshalla im östlichen Winterquell."}}
D[980] = {"Die neuen Quellen",{"Reist nach Winterquell und sprecht mit Donova Schneeweh."}}
D[981] = {"Der Turm von Althalaxx",{"Sprecht mit Delgren dem Läuterer in Maestras Posten."}}
D[982] = {"Tiefer Ozean, weites Meer",{"Beschafft die Schließkassette der Silbermorgen und die Schließkassette der Nebelschleier für Gorbold Stahlhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes."}}
D[983] = {"Dröhnkiste 827",{"Sammelt 6 Kriecherbeine und baut sie in Dröhnkiste 827 ein."}}
D[984] = {"Wie groß ist die Bedrohung?",{"Sucht in Dunkelküste nach einem verderbten Furbolglager und kehrt dann zu Terenthis in Auberdine zurück."}}
D[985] = {"Wie groß ist die Bedrohung?",{"Tötet 8 Pfadfinder der Schwarzfelle und 5 Windsprecher und kehrt dann zu Terenthis in Auberdine zurück."}}
D[986] = {"Ein verirrter Meister",{"Sucht 5 feine Mondpirscherpelze und bringt sie Terenthis in Auberdine."}}
D[990] = {"Marsch ins Eschental",{"Sucht Raene Wolfsläufer im Eschental auf."}}
D[991] = {"Raenes Säuberung",{"Sucht im Eschental nach Teronis."}}
D[992] = {"Gadgetzan Wassersondierung",{"Benutzt den unangezapften Wünschelrutenapparat in der Nähe des Teichs bei der Sandmarterwache. Bringt den angezapften Wünschelrutenapparat zum Leitenden Feldmesser Rutenwünschels nach Gadgetzan zurück, wenn Ihr die Probe entnommen habt."}}
D[993] = {"Ein verirrter Meister",{"Sucht Volcor in Dunkelküste und gebt ihm den verzauberten Mondpirscherumhang."}}
D[994] = {"Flucht durch Gewalt",{"Beschützt Volcor, bis Ihr die Straße erreicht habt und sprecht dann mit Terenthis in Auberdine."}}
D[995] = {"Flucht durch Verstohlenheit",{"Flieht aus der Furbolghöhle und trefft Euch in Auberdine mit Terenthis."}}
D[996] = {"Verderbte Windblüte",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[997] = {"Denalans Erde",{"Bringt Denalan am Al'Amethsee das Gebinde rarer Erde."}}
D[998] = {"Verderbte Windblüte",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
