D[1002] = {"Dröhnkiste 323",{"Sammelt 6 Mondpirscherfangzähne und baut sie in Dröhnkiste 323 ein."}}
D[1003] = {"Dröhnkiste 525",{"Sammelt 4 ergraute Skalps von ergrauten Distelbären südlich von Auberdine und legt sie in die Dröhnkiste 525."}}
D[1004] = {"Die neue Grenze",{"Sprecht auf der Anhöhe der Ältesten in Donnerfels mit dem Erzdruiden Hamuul Runentotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}}
