D[1006] = {"Was dahinter liegt"}
D[1007] = {"Die antike Statuette",{"Bringt Talen im Lager in der Nähe des Zoramstrands die antike Statuette."}}
D[1008] = {"Der Zoramstrand",{"Bringt Shindrell Feuerflink in Astranaar 20 Köpfe von Rächerflossen."}}
D[1009] = {"Ruuzel",{"Bringt Talen im Lager in der Nähe des Zoramstrands den Ring von Zoram."}}
D[1010] = {"Bathranshaar",{"Bringt Orendil Rundblatt im Eschental 5 Bathranshaar-Pflanzen."}}
D[1011] = {"Verlassenenkrankheit",{"Bringt Kayneth Stillwind in Waldeslied eine Krankheitsflasche."}}
D[1012] = {"Irrsinnige Druiden",{"Tötet die Druiden Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch und kehrt dann zu Kayneth Stillwind in Waldeslied zurück."}}
D[1013] = {"Das Buch von Ur",{"Bringt dem Bewahrer Bel'dugur im Apothekarium in Unterstadt das Buch von Ur."}}
D[1014] = {"Arugal muss sterben",{"Tötet Arugal und bringt Dalar Morgenweber in dem Grabmal seinen Kopf."}}
D[1015] = {"Die neue Grenze",{"Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Hirschhaupt über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}}
D[1016] = {"Elementararmschienen",{"Sammelt 5 intakte Elementararmschienen und wendet die Rolle der Bestimmung darauf an. Bringt danach der Schildwache Velene Sternenschlag in der Silberwindzuflucht die bestimmte Rolle."}}
D[1017] = {"Magier-Beschwörer",{"Erschlagt Sarilus Faulmut und bringt Schildwache Velene Sternenschlag in der Silberwindzuflucht seinen Kopf."}}
D[1018] = {"Die neue Grenze",{"Sprecht auf der Anhöhe der Ältesten in Donnerfels mit dem Erzdruiden Hamuul Runentotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}}
D[1019] = {"Die neue Grenze",{"Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Hirschhaupt über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}}
D[1020] = {"Orendils Heilmittel",{"Bringt Pelturas Weißmond in Astranaar Orendils Heilmittel."}}
D[1021] = {"Elende Satyrn! Die Dryaden sind in Gefahr!",{"Sucht in Xavian nach Anilia."}}
D[1022] = {"Das heulende Tal",{"Begebt Euch ins heulende Tal, studiert den Folianten von Mel'Thandris und kehrt dann zur Schildwache Melyria Frostschatten in Waldeslied zurück."}}
D[1023] = {"Raenes Säuberung",{"Sucht den leuchtenden Edelstein und bringt ihn zusammen mit Teronis' Tagebuch zu Raene Wolfsläufer in Astranaar."}}
D[1024] = {"Raenes Säuberung",{"Sucht Shael'dryn beim Mondbrunnen im Nordosten auf."}}
D[1025] = {"Eine aggressive Verteidigung",{"Tötet 1 Höhlenbehüter, 2 Ursa, 10 Totemiker sowie 12 Krieger der Fäulnisklauen und kehrt dann zu Raene Wolfsläufer in Astranaar zurück."}}
D[1026] = {"Raenes Säuberung",{"Sucht den Holzschlüssel und das Teil von Dartols Rute, bevor Ihr zu Shael'dryn beim Mondbrunnen zurückkehrt."}}
D[1027] = {"Raenes Säuberung",{"Sucht das letzte Teil von Dartols Rute und bringt es Shael'dryn beim Mondbrunnen."}}
D[1028] = {"Raenes Säuberung",{"Sucht den verborgenen Schrein und verzaubert Dartols Rute erneut."}}
D[1029] = {"Raenes Säuberung",{"Kehrt zu Raene Wolfsläufer in Astranaar zurück."}}
D[1030] = {"Raenes Säuberung",{"Sucht einen nicht verderbten Furbolg und benutzt die Macht von Dartols Rute der Transformation, um mit ihm zu sprechen."}}
D[1031] = {"Der Zweig des Cenarius",{"Tötet Geltharis und bringt Illiyana in Waldeslied den Zweig des Cenarius."}}
D[1032] = {"Satyrn schlachten!",{"Bringt Illiyana in Waldeslied 16 Satyrhörner."}}
D[1033] = {"Elunes Träne",{"Bringt Pelturas in Astranaar die Träne von Elune."}}
D[1034] = {"Die Sternenstaubruinen",{"Bringt Pelturas in Astranaar 5 Hand voll Sternenstaub."}}
D[1035] = {"Der Himmelssturzsee",{"Holt von dem Schattendickichtorakel einen gefallenen Mondstein und bringt ihn Pelturas in Astranaar."}}
D[1036] = {"Hierher, Taugenichts",{"Sprecht mit Flottenmeister Firallon an Bord der Purpurschleier vor der Küste des Schlingendorntals."}}
D[1037] = {"Velinde Sternensang",{"Sprecht auf der Terrasse der Krieger in Darnassus mit Thyn'tel Klingenweber."}}
D[1038] = {"Velindes Besitztümer",{"Durchsucht Velindes Truhe nach ihrem Tagebuch und bringt es zusammen mit dem Schlüssel nach Darnassus zu Thyn'tel Klingenweber."}}
D[1039] = {"Der Brachlandhafen",{"Sprecht in Ratschet mit Werftmeister Flunkerblick."}}
D[1040] = {"Passage nach Beutebucht",{"Nehmt ein Schiff nach Beutebucht und sprecht dort mit dem Karawanenführer Ruzzgot."}}
D[1041] = {"Die Karawanenstraße",{"Sprecht in Dunkelhain mit Amtmann Daltry."}}
D[1042] = {"Die Familie Treuwein",{"Sprecht mit Jonathan Treuwein in Dunkelhain."}}
D[1043] = {"Die Sense von Elune",{"Sucht nach Hinweisen auf die Sense von Elune und kehrt dann zu Jonathan Treuwein in Dunkelhain zurück."}}
D[1044] = {"Beantwortete Fragen",{"Kehrt nach Darnassus zu Thyn'tel Klingenweber zurück."}}
D[1045] = {"Raenes Säuberung",{"Tötet Ran Blutreißer sowie 4 Wachen von Blutreißer und kehrt dann zu Krolg in der Nähe des Mystralsees zurück."}}
D[1046] = {"Raenes Säuberung",{"Bringt Raene Wolfsläufer in Astranaar Ran Blutreißers Schädel und Dartols Rute der Transformation."}}
D[1047] = {"Die neue Grenze",{"Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Hirschhaupt über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."}}
D[1048] = {"In das Scharlachrote Kloster",{"Tötet Hochinquisitorin Weißsträhne, den scharlachroten Kommandant Mograine, Herod, den scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Varimathras in Unterstadt."}}
D[1049] = {"Kompendium der Gefallenen",{"Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu dem Weisen Wahrspruch in Donnerfels."}}
D[1050] = {"Mythologie der Titanen",{"Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Bleichstaub in Eisenschmiede."}}
D[1051] = {"Vorrels Rache",{"Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz."}}
D[1052] = {"Auf dem scharlachroten Pfad",{"Bringt Raleigh dem Andächtigen in Süderstade Bruder Antons Empfehlungsschreiben."}}
D[1053] = {"Im Namen des Lichts",{"Tötet Hochinquisitorin Weißsträhne, den scharlachroten Kommandant Mograine, Herod, den scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Süderstade."}}
D[1054] = {"Die Auswahl der Bedrohung",{"Bringt Raene Wolfsläufer in Astranaar Dal Blutklaues Schädel."}}
