D[1092] = {"Gerenzos Befehle",{"Bringt Ziz Fizziks im Steinkrallengebirge das unbekannte Erz."}}
D[1093] = {"Superschnitter 6000",{"Besorgt für Ziz Fizziks im Steinkrallengebirge die Superschnitter-6000-Blaupause."}}
