D[1146] = {"Der Schwarm wächst",{"Stellt Belgroms versiegelte Notiz Moktar Krin in Tausend Nadeln zu."}}
D[1147] = {"Der Schwarm wächst",{"Tötet 5 Silithidsucher, 5 Silithidschwarmdrohnen sowie 5 Silithideindringlinge und kehrt zu Moktar Krin in Tausend Nadeln zurück."}}
D[1148] = {"Teile des Schwarms",{"Bringt 1 Silithidenherz, 5 Silithidenkrallen und 3 intakte Silithidenknochenpanzer zu Korran beim Wegekreuz."}}
