D[1150] = {"Test der Belastbarkeit",{"Bringt Grenkas Klaue zu Dorn Ebenenpirscher in Tausend Nadeln."}}
D[1151] = {"Test der Kraft",{"Bringt Fragmente von Rok'Alim zu Dorn Ebenenpirscher in Tausend Nadeln."}}
D[1152] = {"Test der Lehre",{"Sucht Braug Dämmergeist in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge."}}
D[1153] = {"Eine neue Erzprobe",{"Sucht eine unbearbeitete Erzprobe bei einem Buddler oder Feldmesser der Bruchschnauzen und bringt sie zu Tatternack Stahlformer im Camp Taurajo im Brachland."}}
D[1154] = {"Test der Lehre",{"Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dämmergeist in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück."}}
D[1159] = {"Test der Lehre",{"Sucht Parqual Fintallas in Unterstadt."}}
