D[1164] = {"Von Dieben stehlen",{"Bringt Kenata, Fardel und Marcel Dabyries Köpfe zu Genavie Kahler in Unterstadt."}}
D[1166] = {"Oberanführer Mok'Morokks Sorgen",{"Oberanführer Mok'Morokk in Brackenwall möchte, dass Ihr seinen Grog, seinen Schnupftabak und seine Geldkassette aus dem Sumpf der Düstermarschen holt."}}
D[1167] = {"Der Turm von Althalaxx",{"Sprecht mit Balthule Schattenhieb beim Turm von Althalaxx."}}
D[1168] = {"Armee des schwarzen Großdrachen",{"Tharg in Brackenwall möchte, dass Ihr 10 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet."}}
D[1169] = {"Die Brut identifizieren",{"Draz'Zilb in Brackenwall hätte gern, dass Ihr ihm 7 sengende Zungen und 7 sengende Herzen bringt."}}
D[1170] = {"Die Brut von Onyxia",{"Sprecht mit Oberanführer Mok'Morokk in Brackenwall."}}
