D[1173] = {"Fordert Oberanführer Mok'Morokk heraus",{"Besiegt Mok'Morokk und bringt die Nachricht zu Draz'Zilb in Brackenwall."}}
D[1175] = {"Eine Straßenunebenheit",{"Tötet 10 Salzsteinbasilisken, 10 Salzsteinkristallhäute und 6 Salzsteinstarrer für Rennstreckenleiter Zherin in der schimmernden Ebene."}}
D[1176] = {"Gewicht reduzieren",{"Beschafft 10 hohle Geierknochen für Pozzik in der schimmernden Ebene."}}
D[1177] = {"Hunger!",{"Schlammpatsch Dreckfuß in den nördlichen Düstermarschen möchte 8 Schlammflossenköpfe."}}
D[1178] = {"Goblinsponsoring",{"Sprecht mit Gazlowe in Ratschet."}}
D[1179] = {"Die Brüder Kupferbolz",{"Bringt die Kiste mit Schutzhelmen zu Wizzel Kupferbolz in der schimmernden Ebene."}}
D[1180] = {"Goblinsponsoring",{"Sprecht mit Werftmeister Lozgil in Beutebucht."}}
D[1181] = {"Goblinsponsoring",{"Sprecht mit Baron Revilgaz in Beutebucht."}}
D[1182] = {"Goblinsponsoring",{"Bringt die Treibstoffreglerblaupausen zu Baron Revilgaz in Beutebucht."}}
