D[1205] = {"Schlammwühler",{"Bringt Schlammwühlers Zahn zu Melor in Donnerfels."}}
D[1206] = {"Jarl braucht Augen",{"Bringt 20 unzerplatzte Graunebelaugen zu \"Sumpfauge\" Jarl im Irrlichtanwesen."}}
D[1218] = {"Marschenfroschschenkel",{"Bringt 10 Marschenfroschschenkel zu \"Sumpfauge\" Jarl in den Düstermarschen."}}
D[1219] = {"Der Orcbericht",{"Bringt den Bericht des Spions zu Leutnant Aden in Theramore."}}
D[1220] = {"Hauptmann Mumm",{"Bringt den Bericht des Spions zu Hauptmann Garran Mumm."}}
D[1221] = {"Blaulaubknollen",{"Schnappt Euch eine Kiste mit Löchern.","Schnappt Euch einen Schnüffelnasenleitstecken.","Schnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.","","Benutzt im Kral der Klingenhauer die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.","","Bringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratschet."}}
D[1222] = {"Stinkis Flucht",{"Begleitet \"Stinki\" Ignatz und sprecht dann mit Morgan Stern in Theramore."}}
D[1238] = {"Der verlorene Bericht",{"Bringt den Bericht des Spions zu Nazeer Blutlanze in Brackenwall."}}
D[1239] = {"Der abgetrennte Kopf",{"Bringt den Kopf des aufsässigen Orcs zu Nazeer Blutlanze in Brackenwall."}}
D[1240] = {"Der Trollhexendoktor",{"Bringt den Kopf des aufsässigen Orcs zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol."}}
D[1241] = {"Der vermisste Diplomat",{"Sucht Jorgen in der Stadt Sturmwind."}}
D[1242] = {"Der vermisste Diplomat",{"Bringt Jorgens versiegelte Notiz zu Elling Trias in der Stadt Sturmwind."}}
D[1243] = {"Der vermisste Diplomat",{"Gebt Behüter Backus im Dämmerwald die versiegelte Notiz."}}
D[1244] = {"Der vermisste Diplomat",{"Sucht die Liste der Defias und kehrt zu Behüter Backus im Dämmerwald zurück."}}
D[1245] = {"Der vermisste Diplomat",{"Bringt die Liste der Defias zu Elling Trias in Sturmwind."}}
D[1246] = {"Der vermisste Diplomat",{"Sprecht mit Dashel Steinfaust in Sturmwind."}}
D[1247] = {"Der vermisste Diplomat",{"Sprecht mit Elling Trias in Sturmwind."}}
