D[1530] = {"Ruf des Wassers",{"Sucht Brine im südlichen Brachland."}}
D[1531] = {"Ruf der Luft",{"Sucht Prate Wolkendeuter in Tausend Nadeln."}}
D[1532] = {"Ruf der Luft",{"Sucht Prate Wolkendeuter in Tausend Nadeln."}}
D[1534] = {"Ruf des Wassers",{"Füllt den leeren blauen Wasserschlauch bei den Sternenstaubruinen im Eschental und kehrt zu Brine im Brachland zurück."}}
D[1535] = {"Ruf des Wassers",{"Füllt den leeren braunen Wasserschlauch im Wasserloch unterhalb von Brines Hütte und kehrt damit zu Brine im Brachland zurück."}}
D[1536] = {"Ruf des Wassers",{"Füllt den leeren roten Wasserschlauch am Brunnen in Tarrens Mühle und kehrt zu Brine im Brachland zurück."}}
D[1558] = {"Der Steinwerkdamm",{"Begleitet Euren Schützling zum Steinwerkdamm in Loch Modan. Geht mit ihm zur Mitte des Damms, damit er auf den riesigen Wasserfall heruntersehen kann."}}
D[1559] = {"Blitzstrahlbombenanleitung",{"Ihr seid also Ingenieur, hm? Als Dank für Eure Hilfe bei der Beschaffung der Perlen bekommt Ihr eine Anleitung für Blitzstrahlbomben.","","Viel Glück und versucht, Euch nicht selbst zu blenden!"}}
D[1560] = {"Toogas Bitte",{"Zeigt Tooga den Weg zurück zu seiner Frau Torta."}}
D[1578] = {"Nachschub für die Front",{"Bringt 6 Kupferäxte und 6 kupferne Kettengürtel zu Thorvald im südlichen Wachturm des Loch Modan."}}
D[1579] = {"Klemmmuffen",{"Bringt 8 Klemmmuffen zu Hexknall Kurbeldreh in Auberdine."}}
D[1580] = {"Elektropeller",{"Bringt 12 Elektropeller zu Hexknall Kurbeldreh in Auberdine."}}
D[1581] = {"Elixiere für die Messerblatts",{"Bringt 6 Elixiere der Löwenstärke und 2 Elixiere der schwachen Verteidigung zu Syral Messerblatt in Dolanaar."}}
D[1582] = {"Mondscheinweste",{"Bringt 1 geprägten Lederhandschuh, 5 geprägte Lederstiefel und 5 geprägte Lederumhänge zu Lotherias in Darnassus."}}
D[1598] = {"Der gestohlene Foliant",{"Holt \"Die Macht der Leere\" für Drusilla La Salle zurück."}}
D[1599] = {"Anfänge",{"Bringt 3 Federglücksbringer zu Alamar Grimm in Ambossar."}}
D[1618] = {"Die Aufrüstung im Rotkammgebirge",{"Tormus Tiefenschmied möchte, dass Ihr 4 runenverzierte Kupfergürtel und 4 schwere Kupferschlägel zu Verner Gutmark ins Rotkammgebirge bringt."}}
D[1638] = {"Die Ausbildung eines Kriegers",{"Sprecht mit Harry Burlwacht."}}
D[1639] = {"Bartleby der Trunkenbold",{"Sprecht mit Bartleby."}}
D[1640] = {"Besiegt Bartleby",{"Besiegt Bartleby und redet dann mit ihm."}}
D[1641] = {"Der Foliant der Offenbarung",{"Hier in Stormwind bin ich dafür verantwortlich, die Paladine auf den Pfad der größten Tugend zu bringen, sobald sie sich dem Weg des Lichts verschreiben und Azeroth vor der Geißel und anderen Bedrohungen verteidigen.","","Die Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch das Buch der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen."}}
D[1642] = {"Der Foliant der Offenbarung",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[1643] = {"Der Foliant der Offenbarung",{"Sucht im Handelsdistrikt von Sturmwind nach Stephanie Turner."}}
D[1644] = {"Der Foliant der Offenbarung",{"Bringt 10 Stück Leinenstoff zu Stephanie Turner in Sturmwind."}}
D[1645] = {"Der Foliant der Offenbarung",{"Welche Freude, Euch zu sehen, <Name>. Ich bringe die Paladine auf den Pfad der Tugend, wenn sie sich dem Weg des Lichts verschreiben und Azeroth vor der Geißel und anderen Bedrohungen beschützen.","","Die Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch den Folianten der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen."}}
D[1646] = {"Der Foliant der Offenbarung",{"Sprecht mit Tiza Kriegshammer in Eisenschmiede."}}
D[1647] = {"Der Foliant der Offenbarung",{"Sucht im äußeren Ring von Eisenschmiede nach John Turner."}}
D[1648] = {"Der Foliant der Offenbarung",{"Bringt 10 Stück Leinenstoff zu John Turner in Eisenschmiede."}}
D[1649] = {"Der Foliant der Ehre",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[1650] = {"Der Foliant der Ehre",{"Sucht Daphne Stillbrunn in Westfall."}}
D[1651] = {"Der Foliant der Ehre",{"Verteidigt Daphne Stillbrunn vor dem Angriff der Defias.","","Keiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.","","Sprecht erneut mit Daphne Stillbrunn, wenn Ihr erfolgreich wart."}}
D[1652] = {"Der Foliant der Ehre",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[1653] = {"Die Prüfung der Rechtschaffenheit",{"Sprecht mit Jordan Stillbrunn in Eisenschmiede."}}
D[1654] = {"Die Prüfung der Rechtschaffenheit",{"Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Koredelstein und bringt alles zusammen zu Jordan Stillbrunn in Eisenschmiede."}}
D[1655] = {"Bailors Erzlieferung",{"Bringt Jordans Erzlieferung zu Bailor Steinhand am Loch Modan."}}
D[1656] = {"Eine unvollendete Aufgabe",{"Bringt das Bündel Felle zu Gastwirt Kauth ins Dorf der Bluthufe."}}
D[1657] = {"Die Verpestung von Süderstade",{"Werft drei Stinkbomben der Verlassenen ins Herz von Süderstade im Hügelland und kehrt zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück."}}
D[1658] = {"Bespitzelt das Fest des Weidenmanns",{"Macht das Fest des Weidenmanns der Verlassenen in Tirisfal ausfindig. Kehrt zu Unteroffizier Hartman in Süderstade zurück, sobald Ihr Eure Mission erfüllt habt."}}
D[1661] = {"Der Foliant des Adels",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[1665] = {"Bartlebys Becher",{"Bringt Bartlebys Becher zu Burlwacht."}}
D[1666] = {"Marschall Haggard",{"Sprecht mit Marschall Haggard."}}
D[1667] = {"Stumpfzahn Jack",{"Holt Marschall Haggards Abzeichen aus Stumpfzahn Jacks Lager und kehrt zu Marschall Haggard zurück."}}
D[1678] = {"Vejrek",{"Bringt Vejreks Kopf zu Muren Sturmlanze in Eisenschmiede."}}
D[1679] = {"Muren Sturmlanze",{"Sprecht mit Muren Sturmlanze."}}
D[1680] = {"Tormus Tiefenschmied",{"Sprecht mit Tormus Tiefenschmied."}}
D[1681] = {"Eisenbands Truppenlager",{"Bringt eine Ladung Umbralerz zu Tormus Tiefenschmied in Eisenschmiede."}}
D[1682] = {"Waffen aus grauem Eisen",{"Hier ein paar Waffen, frisch vom Amboss und aus dem neuen Umbralerz gefertigt, das Ihr mir gebracht habt!","","Bitte, <Name>, sucht Euch eine aus!"}}
D[1683] = {"Vorlus Elendshuf",{"Bringt das Horn von Vorlus zu Elanaria in Darnassus."}}
D[1684] = {"Elanaria",{"Sprecht mit Elanaria."}}
D[1685] = {"Gakins Beschwörung",{"Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind."}}
D[1686] = {"Eluras Schemen",{"Bringt 8 Ladungen Eluniterz und das Medaillon von Elura zu Elanaria in Darnassus."}}
D[1687] = {"Der gruselige Leuchtturm",{"Besucht mit Eurem Schützling den Leuchtturm an der Küste von Westfall."}}
D[1688] = {"Surena Caledon",{"Beschafft Surenas Kropfband für Gakin den Dunkelbinder in Sturmwind."}}
D[1689] = {"Die Bindung",{"Beschwört mit Hilfe des Blutsteinkropfband einen Leerwandler, unterwerft ihn und bringt dann den Blutsteinkropfband zu Gakin dem Dunkelbinder in Sturmwind zurück."}}
D[1690] = {"Wüstenläufergerechtigkeit",{"Erledigt 10 Banditen und Diebe der Wüstenläufer östlich von Gadgetzan und meldet Euch dann wieder bei Chefingenieur Bilgenritzel."}}
D[1691] = {"Noch mehr Wüstenläufergerechtigkeit",{"Erledigt 10 Schattenmagier der Wüstenläufer, 8 Schurken der Wüstenläufer und 6 Auftragsmörder der Wüstenläufer für Chefingenieur Bilgenritzel in Gadgetzan."}}
D[1692] = {"Schmied Mathiel",{"Bringt die Kiste mit Elunit zu Schmied Mathiel."}}
D[1693] = {"Waffen aus Elunit",{"<Name>, ich habe mit dem Elunit, das Ihr mir brachtet, diese Waffen hergestellt. Bitte nehmt die, die Euch am angenehmsten ist.","","Und ich muss Euch danken. Es ist eine Ehre und Freude, mit Elunit zu arbeiten."}}
D[1698] = {"Yorus Gerstenbräu",{"Sprecht mit Yorus Gerstenbräu."}}
D[1699] = {"Der Rethbanspießrutenlauf",{"Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.","","Ihr dürft nicht sterben und Euren Geist befreien."}}
D[1700] = {"Grimand Elmore",{"Bringt Furens Notizen zu Grimand Elmore."}}
D[1701] = {"Feuergehärteter Panzer",{"Sammelt die Materialien, die Furen Langbart benötigt, und bringt sie zu ihm nach Sturmwind."}}
D[1702] = {"Der Schildschmied",{"Bringt das Fässlein mit Gerstenbräu zu Furen Langbart."}}
D[1703] = {"Mathiel",{"Bringt Furens Notizen zu Mathiel."}}
D[1704] = {"Klockmort Spannersplint",{"Bringt Furens Notizen zu Klockmort Spannersplint."}}
D[1705] = {"Brennendes Blut",{"Bringt 20 Phiolen brennendes Blut und 1 brennenden Fels zu Grimand Elmore in Sturmwind."}}
D[1706] = {"Grimands Rüstung",{"Ich kann es kaum glauben! Furens Technik war ein Erfolg. Seine Rüstung sollte ungeheuren Belastungen standhalten können.","","Da habt Ihr sie, <Name>. Und habt Dank. Ich hätte nicht an Furens Entdeckung geglaubt, wenn Ihr nicht die Materialien gesammelt hättet, die ich für einen Test brauchte."}}
D[1707] = {"Wasserbeutelkopfgeld",{"Bringt Leitungshahnmaschinist Lochbeutel in Gadgetzan 5 Wasserbeutel eines Wüstenläufers."}}
D[1708] = {"Eisenkoralle",{"Bringt 20 Ladungen Sengkoralle zu Klockmort Spannersplint in Eisenschmiede."}}
D[1709] = {"Klockmorts Kreation",{"Hier ist Eure Rüstung, <Name>. Furens Prozess hat ausgezeichnet funktioniert! Perfekt! Wunderbar, ehrlich!","","Man könnte mit einer Belagerungsmaschine über diese Rüstung fahren und sie würde wieder ihre alte Form annehmen!"}}
D[1710] = {"Sonnenverbrannte Schalen",{"Bringt 20 sonnenverbrannte Schalen zu Mathiel in Darnassus."}}
D[1711] = {"Mathiels Rüstung",{"Ich habe Eure Rüstung vollendet und bin recht zufrieden. Furens neue Techniken passen ausgezeichnet zu meinen. Ich bin sicher, diese Rüstung wird sehr widerstandsfähig sein.","","Danke, <Name>. Möge sie Euch in künftigen Kämpfen nützlich sein."}}
D[1712] = {"Cyclonian",{"Bringt die Gegenstände auf Bath'rahs Pergament zu Bath'rah dem Windbehüter in Alterac."}}
D[1713] = {"Die Beschwörung",{"Bringt das Wirbelherz zu Bath'rah dem Windbehüter."}}
D[1714] = {"Essenz der Verbannung",{"Der Kessel blubbert. Seine Dämpfe locken..."}}
D[1715] = {"Zum Geschlachteten Lamm",{"Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind."}}
D[1716] = {"Verschlinger der Seelen",{"Sprecht mit Takar dem Seher im Brachland."}}
D[1717] = {"Gakins Beschwörung",{"Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind."}}
D[1718] = {"Der Inselbewohner",{"Sprecht mit Klannoc Macleod."}}
D[1719] = {"Der Ringkampf",{"Tötet Big Will und sprecht mit Klannoc Macleod auf dem Prügeleiland."}}
D[1738] = {"Herzholz",{"Holt das Herzholz aus dem Eschental und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Sturmwind."}}
D[1739] = {"Die Bindung",{"Beschwört mit Hilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück."}}
D[1740] = {"Die Kugel von Soran'ruk",{"Sucht 3 Fragmente von Soran'ruk und 1 großes Fragment von Soran'ruk und bringt sie zu Doan Karhan im Brachland."}}
D[1758] = {"Foliant der Kabale",{"Sprecht mit Krom Starkarm in Eisenschmiede."}}
D[1778] = {"Der Foliant der Offenbarung",{"Sprecht mit Tiza Kriegshammer in Eisenschmiede."}}
D[1779] = {"Der Foliant der Offenbarung",{"Nehmt das Symbol des Lebens und sprecht mit Muiredon Kriegshammer in Eisenschmiede."}}
D[1780] = {"Der Foliant der Offenbarung",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[1781] = {"Der Foliant der Offenbarung",{"Bringt das Symbol des Lebens zu Gazin Tenorm in Sturmwind."}}
D[1782] = {"Furens Rüstung",{"Hier ist Eure Rüstung, <Name>. Sie wird dem stärksten Angriff standhalten, oder ich will nicht mehr Furen Longbeard heißen!","","Und ich habe Euch zu danken. Ich habe bei der Arbeit mit dem Material, das Ihr mir brachtet, viel gelernt. Ich glaube, eines Tages werde ich einen weiteren Durchbruch schaffen!","","Ich werde das, was ich gelernt habe, den anderen Schmieden der Allianz schicken.","","Ich sage ihnen, was für eine große Hilfe Ihr wart. Vielleicht möchten sie den Gefallen erwidern."}}
D[1783] = {"Der Foliant der Offenbarung",{"Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben."}}
D[1784] = {"Der Foliant der Offenbarung",{"Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbettsee und kehrt zu Muiredon Kriegshammer in Eisenschmiede zurück."}}
D[1785] = {"Der Foliant der Offenbarung",{"Sprecht mit Tiza Kriegshammer in Eisenschmiede."}}
D[1786] = {"Der Foliant der Offenbarung",{"Nehmt das Symbol des Lebens und erweckt Henze Faulk in Elwynn wieder zum Leben."}}
D[1787] = {"Der Foliant der Offenbarung",{"Beschafft eine Schrift der Defias von den abtrünnigen Hexern der Defias in Elwynn und kehrt zu Gazin Tenorm in Sturmwind zurück."}}
D[1788] = {"Der Foliant der Offenbarung",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[1789] = {"Das Symbol des Lebens",{"Solltet Ihr es nicht schaffen, Narm zu helfen, nachdem Ihr das Symbol des Lebens benutzt habt, <Name>, dann kommt zu mir zurück und ich werde Euch ein weiteres geben.","","Es ist sowohl für meinen Ehemann als auch für mich wichtig, dass Ihr erfolgreich zurückkehrt. Bitte sputet Euch."}}
D[1790] = {"Das Symbol des Lebens",{"Sputet Euch, <Name>, mehr als ein Leben steht auf dem Spiel, wenn Ihr scheitert.","","Wenn Ihr Gazin und Henze aus irgendeinem Grund nicht helfen könnt, dann kommt zu mir zurück und ich gebe Euch ein weiteres Symbol des Lebens für Eure Reisen.","","Versteht meine Unterstützung nicht als reine Wohltätigkeit. Ihr müsst Euch wie jeder andere <Klasse> beweisen, und wenn Ihr ständig scheitert, fällt das später auf Euch zurück."}}
D[1791] = {"Der Windbehüter",{"Sprecht mit Bath'rah dem Windbehüter."}}
D[1792] = {"Wirbelwaffe",{"Ich habe das Wirbelherz und bin bereit, es in ein Gefäß Eurer Wahl zu legen.","","Wählt eine Waffe, <Name>, und wisset, dass ihre Macht die Macht des Cyclonian ist."}}
D[1793] = {"Der Foliant der Ehre",{"Es steht fest, dass das Licht mit Euch ist, <Name>, doch da die Zeiten zunehmend gefährlicher werden, ist es wichtig zu wissen, welche Kräfte dem Fleische innewohnen. Wenn Dämonen, Großdrachen oder ein anderes Übel einen Fuß in unser Land setzen, wird Eure Tapferkeit auf die Probe gestellt. Werdet Ihr stark genug sein?","","Tapferkeit in jedweder Situation gehört ebenso zu einem <Klasse> wie das Licht, seine Rüstung und seine Waffe. Die Schwachen beschützen und den Glauben nicht verlieren, sind zwei weitere Lektionen, die Ihr meistern müsst, wenn Ihr in der Kathedrale des Lichts studiert."}}
D[1794] = {"Der Foliant der Ehre",{"Es steht fest, dass das Licht mit Euch ist, <Name>, doch da die Zeiten zunehmend gefährlicher werden, ist es wichtig zu wissen, welche Kräfte dem Fleische innewohnen. Wenn Dämonen, Großdrachen oder ein anderes Übel einen Fuß in unser Land setzen, wird Eure Tapferkeit auf die Probe gestellt. Werdet Ihr stark genug sein?","","Tapferkeit in jedweder Situation gehört ebenso zu einem <Klasse> wie das Licht, seine Rüstung und seine Waffe. Die Schwachen beschützen und den Glauben nicht verlieren, sind zwei weitere Lektionen, die Ihr meistern müsst, wenn Ihr in der Kathedrale des Lichts studiert."}}
D[1795] = {"Die Bindung",{"Beschwört mit Hilfe des 'Folianten der Kabale' einen Teufelsjäger, unterwerft ihn und bringt den 'Folianten der Kabale' zu Strahad Farsan in Ratschet zurück."}}
D[1796] = {"Komponenten für die verzauberte Goldblutrobe",{"Bringt die Roben von Arcana zu Menara Leerbringer im Brachland."}}
D[1798] = {"Die Suche nach Strahad",{"Sprecht mit Strahad Farsan im Brachland."}}
D[1799] = {"Fragmente der Kugel von Orahil",{"Sprecht mit Menaras Akolythen im Inneren des Turms über Ratschet und wählt einen ihrer Wege, um ihm zu folgen.","","Bringt danach eine Höllenkugel zu Tabetha in den Düstermarschen."}}
D[1800] = {"Der Thronsaal von Lordaeron",{"Besucht mit Eurem Schützling den alten Thronsaal in Lordaeron. Er befindet sich kurz vor dem Abgang nach Unterstadt."}}
D[1801] = {"Foliant der Kabale",{"Sprecht mit Jorah Annison in Unterstadt."}}
D[1802] = {"Foliant der Kabale",{"Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Krom Starkarm in Eisenschmiede."}}
D[1803] = {"Foliant der Kabale",{"Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Jorah Annison in Unterstadt."}}
D[1804] = {"Foliant der Kabale",{"Bringt den rekonstruierten Folianten und 3 Kanalisierungsruten zu Strahad Farsan in Ratschet."}}
D[1805] = {"Foliant der Kabale",{"Bringt den rekonstruierten Folianten und 3 Ruten des Kanalisierens zu Strahad Farsan in Ratschet."}}
D[1806] = {"Die Prüfung der Rechtschaffenheit",{"Wartet, bis Jordan Stillbrunn eine Waffe für Euch geschmiedet hat."}}
D[1818] = {"Gespräch mit Dillinger",{"Sprecht mit Todeswache Dillinger in Brill."}}
D[1819] = {"Ulag der Spalter",{"Tötet Ulag den Spalter und sprecht dann mit Todeswache Dillinger."}}
D[1820] = {"Gespräch mit Coleman",{"Sprecht mit Coleman Heller."}}
D[1821] = {"Agamanderbstücke",{"Bringt Coleman Heller die Axt, das Schwert, den Streitkolben und den Dolch der Familie Agamand."}}
D[1822] = {"Erbstückwaffe",{"Ich behalte drei der Waffen, die Ihr mir gebracht habt, als Andenken an meinen Schmerz und Verlust. Aber bitte, <Name>, wählt Euer Lieblingserbstück und behaltet es für Euch.","","Möge es Euch besser dienen als seinen verfluchten vorherigen Besitzern."}}
D[1823] = {"Gespräch mit Ruga",{"Sprecht mit Ruga Rachtotem."}}
D[1824] = {"Prüfung auf dem Feld der Riesen",{"Bringt 5 zuckende Fühler zu Ruga Rachtotem im Camp Taurajo."}}
D[1825] = {"Gespräch mit Thun'grim",{"Sprecht mit Thun'grim Brandblick im Brachland."}}
D[1838] = {"Brutale Rüstung",{"Bringt Thun'grim Brandblick 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole mit Phlogiston."}}
D[1839] = {"Ula'elek und die brutalen Stulpen",{"Sprecht mit Ula'elek in Durotar."}}
D[1840] = {"Orm Steinhuf und der brutale Helm",{"Sprecht mit Orm Steinhuf in Donnerfels."}}
D[1841] = {"Velora Nachtens und die brutalen Beinschützer",{"Sprecht in Unterstadt mit Velora Nachtens."}}
D[1842] = {"Satyrhufe",{"Bringt 7 ungespaltene Satyrhufe zu Ula'elek in Sen'jin in Durotar."}}
D[1843] = {"Brutale Stulpen",{"Danke, <Name>. Diese Stulpen sind meine beste Arbeit. Nehmt sie. Wenn Ihr sie tragt, bringt es mir und meinen Vorfahren Ehre."}}
D[1844] = {"Schimärenhorn",{"Bringt ein galvanisiertes Horn zu Orm Steinhuf in Donnerfels."}}
D[1845] = {"Brutaler Helm",{"Ich gebe Euch diesen Helm.","","Große Taten brachten Euch zu mir, <Name>, und wenn es der Erdenmutter gefällt... liegen noch größere vor Euch."}}
D[1846] = {"Schienbeinknochen der Drachenmalorcs",{"Bringt 8 stabile Schienbeinknochen eines Drachenmalorcs zu Velora Nachtens in Unterstadt."}}
D[1847] = {"Brutale Beinschützer",{"Hier sind Eure Beinschützer, <Name>. Lasst mich wissen, ob sie passen oder geändert werden müssen. Ich möchte zufriedene Kunden! Zumindest früher wollte ich das.","","Heutzutage liegt mir nicht mehr viel an meinem Handwerk. Aber immer noch besser, als eine hirnlose Dienerin der Geißel zu sein!","","Denke ich."}}
D[1848] = {"Brutale Halsberge",{"Ich bin sicher, Ihr habt bei dieser Aufgabe viele Unannehmlichkeiten erduldet und viel Blut vergossen, <Name>. Hier ist das Produkt Eurer Mühsal.","","Möge es Euch gute Dienste leisten und möget Ihr eines Tages wiederkommen und erzählen, wie nützlich sie Euch waren."}}
D[1858] = {"Die Zerschmetterte Hand",{"Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar."}}
D[1859] = {"Therzok",{"Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar."}}
D[1860] = {"Gespräch mit Jennea",{"Sprecht in Sturmwind mit Jennea Haubitz."}}
D[1861] = {"Spiegelsee",{"Bringt eine Probe des Spiegelseewassers zu Jennea Haubitz in Sturmwind."}}
D[1878] = {"Wasserbeutelkopfgeld",{"Ihr seid ja schon wieder da, <Name>! Wenn Ihr noch fünf Wasserbeutel eines Wüstenläufers für mich habt, dann habe ich hier ein kleines Paket, das nur auf Euch wartet!"}}
D[1879] = {"Gespräch mit Bink",{"Sprecht mit Bink in Eisenschmiede."}}
D[1880] = {"Magitastischer Gizmonitor",{"Bringt Bink ihren magitastischen Gizmonitor."}}
D[1881] = {"Gespräch mit Anastasia",{"Sprecht mit Anastasia Hirschbrunn."}}
D[1882] = {"Balnirs Bauernhof",{"Bringt Balnirlöwenmäulchen zu Anastasia Hirschbrunn im Magierviertel von Unterstadt."}}
D[1883] = {"Gespräch mit Un'thuwa",{"Sprecht mit Un'thuwa."}}
D[1884] = {"Jujuhaufen",{"Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück."}}
D[1885] = {"Mennet Carkad",{"Sprecht mit Mennet Carkad im Schurkenviertel von Unterstadt."}}
D[1886] = {"Die Todespirscher",{"Beschafft Astors Vorstellungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel."}}
D[1898] = {"Die Todespirscher",{"Sprecht mit Andron Gant in Unterstadt."}}
D[1899] = {"Die Todespirscher",{"Bringt Androns Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Unterstadt."}}
D[1918] = {"Das beschmutzte Element",{"Bringt die beschmutzte Wasserkugel zu Mastok Wutfauch im Splitterholzposten im Eschental."}}
D[1919] = {"Meldung bei Jennea",{"Sprecht in Sturmwind mit Jennea Haubitz."}}
D[1920] = {"Untersuchungen im Blauen Eremiten",{"Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Haubitz. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum."}}
D[1921] = {"Materialsammlung",{"Bringt 10 Leinenstoff und 6 aufgeladene Rissedelsteine zu Wynne Larson in Sturmwind."}}
D[1938] = {"Urs Abhandlung über Schattenmagie",{"Bringt 'Urs Abhandlung über Schattenmagie' zu Zaubermeister Andromath in Sturmwind."}}
D[1939] = {"Zaubermeister Andromath",{"Sprecht mit Zaubermeister Andromath."}}
D[1940] = {"Makellose Spinnenseide",{"Bringt 8 Rollen makelloser Spinnenseide zu Wynne Larson in Sturmwind."}}
D[1941] = {"Managewirkte Robe",{"Hier ist Eure Robe. Er ist eine meiner besten bisher! Tragt sie voller Stolz, und wenn die Leute Euch fragen... sagt ihnen, Ihr habt sie vom Konfektionsgeschäft Larson."}}
D[1942] = {"Astralknotengewand",{"Euer Gewand ist fertig! Die Seide, die Ihr mir gebracht hattet, war so hübsch... es stört Euch doch nicht, dass ich es etwas kürzer gemacht habe, damit noch etwas Seide für mich übrig bleibt, oder?","","Das war nur ein Witz. Das Gewand wird sitzen wie angegossen und es eignet sich gleichermaßen gut, um damit in Abenteuer zu ziehen oder zu einem Empfang zu gehen. Viel Spaß damit!"}}
D[1943] = {"Gespräch mit Deino",{"Sprecht mit Deino."}}
D[1944] = {"Wasser von Xavian",{"Bringt die Wasserprobe von Xavian zu Deino in Orgrimmar."}}
D[1945] = {"Lachende Schwestern",{"Bringt 12 Haarlocken der lachenden Schwestern zu Kil'hala beim Wegekreuz."}}
D[1946] = {"Netherspitzengewand",{"Hier habt Ihr Euer Gewand aus Netherspitze, <Name>. Es ist bequem und strapazierfähig und enthält die Magie des Haars der lachenden Schwestern.","","Viel Spaß damit, und wenn Euch das Gewand zusagt, dann lasst es doch bitte auch Deino wissen. Sie ist eine Magierin, mit der ich es mir nicht verderben möchte ..."}}
D[1947] = {"Reise in die Marschen",{"Sprecht mit Tabetha."}}
D[1948] = {"Gegenstände der Macht",{"Bringt 1 Stück Jade und den vom Blitz aufgeladenen Dornbusch zu Tabetha in den Düstermarschen."}}
D[1949] = {"Verborgene Geheimnisse",{"Sprecht mit Magus Tirth in der schimmernden Ebene."}}
D[1950] = {"Der Knüller schlechthin",{"Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück."}}
D[1951] = {"Rituale der Macht",{"Bringt das Buch 'Rituale der Macht' zu Tabetha in den Düstermarschen."}}
D[1952] = {"Der Zauberstab des Magiers",{"Sprecht nach ihrem Ritual mit Tabetha."}}
D[1953] = {"Rückkehr in die Marschen",{"Sprecht mit Tabetha."}}
D[1954] = {"Die Höllenkugel",{"Bringt eine Höllenkugel zu Tabetha in den Düstermarschen."}}
D[1955] = {"Die Austreibung",{"Tötet den Dämon der Kugel und sprecht dann mit Tabetha."}}
D[1956] = {"Macht in Uldaman",{"Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Düstermarschen zu Tabetha."}}
D[1957] = {"Manawogen",{"Vernichtet 12 Manawogen innerhalb des Zeitlimits."}}
D[1958] = {"Himmlische Macht",{"Ihr solltet stolz auf Euch sein, <Name>. Viele <Klasse> fielen den Kreaturen zum Opfer, denen Ihr getrotzt habt.","","Die Himmelskugel ist fertig. Wenn Ihr möchtet, kann ich sie oben an einem Stab anbringen. Es liegt bei Euch. Mir persönlich wäre die Kugel allein ja lieber, aber wer bin ich, mir ein Urteil zu erlauben?"}}
D[1959] = {"Meldung bei Anastasia",{"Sprecht mit Anastasia Hirschbrunn."}}
D[1960] = {"Untersuchungen im Alchimistenladen",{"Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hirschbrunn. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Unterstadt."}}
D[1961] = {"Materialsammlung",{"Bringt 10 Leinenstoff und 6 Manaedelsteine aus Dalaran zu Josef Gregorian."}}
D[1962] = {"Roben des Zauberfeuers",{"Hier sind Eure Roben, <Name>. Tragt sie mit Bedacht."}}
D[1963] = {"Die Zerschmetterte Hand",{"Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar."}}
D[1978] = {"Die Todespirscher",{"Bringt Androns Geschäftsbuch zu Varimathras in der Halle der dunklen Fürstin in Unterstadt."}}
D[1998] = {"Fenwick Thatros",{"Tötet Fenwick Thatros und bringt seinen Kopf zu Mennet Carkad im Schurkenviertel von Unterstadt."}}
D[1999] = {"Werkzeuge des Handwerks",{"Sucht den Statusbericht von Dalaran und bringt ihn zu Mennet Carkad im Schurkenviertel von Unterstadt."}}
D[2000] = {"Rokar Klingenschatten",{"Sprecht mit Rokar Klingenschatten in Durotar."}}
D[2018] = {"Rokars Test",{"Tötet Vorarbeiter Glibby und bringt seine Pfeife zu Rokar Klingenschatten in Durotar."}}
D[2019] = {"Werkzeuge des Handwerks",{"Kehrt zu Therzok in der Kluft der Schatten in Orgrimmar zurück."}}
D[2038] = {"Bingles' verschwundene Werkzeuge",{"Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:","","Bingles' Schraubenschlüssel, Bingles' Schraubendreher, Bingles' Hammer und Bingles' Superspreng."}}
D[2039] = {"Sucht Bingles",{"Sucht Bingles Blastenheimer am Loch Modan."}}
D[2040] = {"Unterirdischer Angriff",{"Holt das Gnoamsprenkelspross aus den Todesminen und bringt es Shoni der Schtillen in Sturmwind."}}
D[2041] = {"Sprecht mit Shoni",{"Sprecht mit Shoni der Schtillen in Sturmwind."}}
D[2078] = {"Gyromasts Rache",{"Sucht Gelkaks Ersten Maat, den Dreschonator 4100, und führt ihn zu Gelkak zurück."}}
D[2098] = {"Gyromasts Rettung",{"Sucht die drei Stücke von Gelkaks Schlüssel und bringt sie Gelkak Gyromast."}}
D[2118] = {"Verseuchtes Land",{"Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun.","","Solltet Ihr keinen tollwütigen Distelbären fangen können und Eure Falle verlieren, dann kehrt zu Tharnariun Baumwahrer zurück und bittet um eine neue Falle."}}
D[2138] = {"Ausrottung der Infizierten",{"Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Baumwahrer in Dunkelküste zurück."}}
D[2139] = {"Tharnariuns Hoffnung",{"Sucht und tötet die Höhlenmutter."}}
D[2158] = {"Ruhe und Entspannung",{"Sprecht im Gasthaus Zur Höhle des Löwen mit Gastwirt Farley."}}
D[2159] = {"Lieferung für Dolanaar",{"Bringt die Lieferung für Dolanaar zu Gastwirt Keldamyr."}}
D[2160] = {"Vorräte für Tannok",{"Bringt die Kiste mit Gasthausvorräten zu Tannok Frosthammer in Kharanos."}}
D[2161] = {"Die Bürde eines Peons",{"Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel."}}
D[2178] = {"Schreitereintopf",{"Bringt 5 Stücke Schreiterfleisch zu Alanndarian Nachtweise in Auberdine."}}
D[2198] = {"Die zerrissene Halskette",{"Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren."}}
D[2199] = {"Lehren haben ihren Preis",{"Bringt fünf Silberbarren zu Talvash del Kissel in Eisenschmiede."}}
D[2200] = {"Rückkehr nach Uldaman",{"Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt."}}
D[2201] = {"Suche nach den Edelsteinen",{"Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.","","Aus dem Tagebuch, wisst Ihr...","* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.","* Der Topas steckt in einer Urne in einem der Trogggebiete, in der Nähe einiger Zwerge der Allianz.","","* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."}}
D[2202] = {"Reagenzsuche in Uldaman",{"Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Moosblut."}}
D[2203] = {"Reagenziensuche im Ödland II",{"Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Jarkal Moosblut in Kargath."}}
D[2204] = {"Restaurierung der Halskette",{"Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Eisenschmiede ab."}}
D[2205] = {"Aufsuchen des SI: 7",{"Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Sturmwind."}}
D[2206] = {"Schneller Eingriff",{"Sucht den Dockmeister der Defias und beschafft den Lieferzeitplan für Meister Mathias Shaw."}}
D[2218] = {"Straße der Rettung",{"Sprecht mit Hulfdan Schwarzbart in Eisenschmiede."}}
D[2238] = {"Einfache List",{"Sucht Onin MacHammar bei Gnomeregan."}}
D[2239] = {"Onins Bericht",{"Bringt Onins Bericht zu Hulfdan in Eisenschmiede."}}
D[2240] = {"Die geheime Kammer",{"Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Sturmlanze Bericht."}}
D[2241] = {"Der Apfel fällt",{"Bringt Jannoks Rose zu Syurna in Darnassus."}}
D[2242] = {"Das Schicksal ruft",{"Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna."}}
D[2258] = {"Reagenziensuche im Ödland",{"Bringt Jarkal Moosblut in Kargath im Ödland 5 Bussardmuskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter."}}
D[2259] = {"Erion Schattenflüsterer",{"Kontaktiert Erion Schattenflüsterer in Darnassus."}}
D[2260] = {"Erions Befehl",{"Reist zur Stadt Sturmwind und meldet Euch bei Renzik \"Das Messer\"."}}
D[2278] = {"Die Platinscheiben",{"Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon."}}
D[2279] = {"Die Platinscheiben",{"Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Eisenschmiede."}}
D[2280] = {"Die Platinscheiben",{"Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Donnerfels."}}
D[2281] = {"Rendezvous im Rotkammgebirge",{"Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius."}}
D[2282] = {"Althers Mühle",{"Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain."}}
D[2283] = {"Wiederbeschaffung der Halskette",{"Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt."}}
D[2284] = {"Wiederbeschaffung der Halskette, Teil 2",{"Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine."}}
D[2298] = {"Königliche Erpressung",{"Reist nach Sturmwind und sucht Renzik \"Das Messer\" auf."}}
D[2299] = {"Auf Hulfdan!",{"Reist nach Eisenschmiede und sprecht mit Hulfdan Schwarzbart."}}
D[2300] = {"Der SI:7",{"Reist nach Sturmwind und sucht Renzik \"Das Messer\" auf."}}
D[2318] = {"Übersetzung des Tagebuchs",{"Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland."}}
D[2338] = {"Übersetzung des Tagebuchs",{"Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen."}}
D[2339] = {"Findet die Edelsteine und die Kraftquelle",{"Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Moosblut nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.","","Aus dem Tagebuch, wisst Ihr...","* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.","* Der Topas steckt in einer Urne in einem der Trogggebiete, in der Nähe einiger Zwerge der Allianz.","* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."}}
D[2340] = {"Ablieferung der Edelsteine",{"Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab."}}
D[2341] = {"Wiederbeschaffung der Halskette, Teil 3",{"Besucht Jarkal Moosblut in Kargath, um festzustellen, ob er Erfolg gehabt hat."}}
D[2342] = {"Wiederbeschaffte Schätze",{"Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Unterstadt."}}
D[2358] = {"Hörner von Nez'ra",{"Bringt die Hörner von Nez'ra zu Arantir nach Seenhain."}}
D[2359] = {"Klavens Turm",{"Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Sturmwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen."}}
D[2360] = {"Mathias und die Defias",{"Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten."}}
D[2361] = {"Restaurierung der Halskette",{"Ich gebe Euch diese Halskette gern, <Klasse>. Ihr habt mir einen unschätzbaren Dienst erwiesen und dafür danke ich Euch. Tragt die Kette mit Stolz und vergesst nicht, immer wieder in der gebührenden Lautstärke zu verkünden, wer sie für Euch gemacht hat!","","Und wenn Ihr auch beiläufig erwähnen könntet, dass die Kette nicht verflucht ist, dann wäre das wirklich wunderbar."}}
D[2378] = {"Suche nach der Zerschmetterten Hand",{"Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul."}}
D[2379] = {"Zando'zan",{"Sprecht an der Kluft der Schatten mit Zando'zan."}}
D[2380] = {"Nach Orgrimmar!",{"Sprecht an der Kluft der Schatten in Orgrimmar mit Shenthul."}}
D[2381] = {"Das Ausplündern der Plünderer",{"Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratschet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrenix' Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden.","","Wenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!"}}
D[2382] = {"Wrenix aus Ratschet",{"Reist nach Ratschet und sprecht mit Wrenix dem Jämmerlichen."}}
D[2383] = {"Einfaches Pergament",{"Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen."}}
D[2398] = {"Die verschollenen Zwerge",{"Sucht in Uldaman nach Baelog."}}
D[2399] = {"Die sprießenden Wedel",{"Die Wedel, die Denalan in seinem Garten angepflanzt hat, sind gesprossen und gediehen. Sie zittern leicht, als wollten sie gepflückt werden..."}}
D[2418] = {"Kraftsteine",{"Bringt Riggelfuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum."}}
D[2438] = {"Der smaragdgrüne Traumfänger",{"Bringt den smaragdgrünen Traumfänger zu Tallonkai Flinkwurzel in Dolanaar."}}
D[2439] = {"Die Platinscheiben",{"Bringt Euren Belohnungsgutschein zu Dinita Zasterstein im Tresor von Eisenschmiede."}}
D[2440] = {"Die Platinscheiben",{"Bringt den Belohnungsgutschein zu Bena Winterhuf nach Donnerfels."}}
D[2458] = {"Undercover",{"Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Zerschmetterten Hand, Zuchtmeister Fitzel.","","Sobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fitzel Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fitzel und zeigt den Gruß der Zerschmetterten Hand.","","Es ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fitzel jede Person, die er nicht erkennt, angreift und eliminiert."}}
D[2459] = {"Ferocitas der Traumfresser",{"Tallonkai Flinkwurzel aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet."}}
D[2460] = {"Der Gruß der Zerschmetterten Hand",{"Führt Shenthul gegenüber den Gruß der Zerschmetterten Hand aus."}}
D[2478] = {"Mission: möglich, aber nicht sehr wahrscheinlich",{"Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.","","Eliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Behälter mit Zanzils veränderter Mixtur. Bringt den Behälter und Gallywix' Kopf zu Shenthul nach Orgrimmar; er wird Euch weitere Anweisungen geben."}}
D[2479] = {"Hinotts Hilfe",{"Reist nach Tarrens Mühle im Vorgebirge des Hügellands und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.","","Um nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Unterstadt nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hügellandhof reisen. Folgt den Schildern!"}}
D[2480] = {"Hinotts Hilfe",{"Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen."}}
D[2498] = {"Rückkehr zu Denalan",{"Rellian Grünwipfel möchte, dass Ihr am Al'Amethsee mit Denalan sprecht."}}
D[2499] = {"Grimmeiche",{"Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt."}}
D[2500] = {"Reagenziensuche im Ödland",{"Beschafft die Reagenzien, die Ghak Heilsegen aus dem Ödland braucht, und bringt sie ihm nach Thelsamar."}}
D[2501] = {"Reagenziensuche im Ödland II",{"Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Heilsegen in Thelsamar."}}
D[2518] = {"Tränen des Mondes",{"Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt."}}
D[2519] = {"Der Tempel des Mondes",{"Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht."}}
D[2520] = {"Sathrahs Opferung",{"Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt."}}
D[2521] = {"Ein Dienst für Kum'isha",{"Falls Ihr auf Euren Reisen durch die verwüsteten Lande je auf eine fehlerlose Draenethystsphäre stoßen solltet, bringt sie zu Kum'isha dem Sammler.","","Doch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben.","","Ihr erhaltet eine Belohnung für jede fehlerlose Draenethystsphäre, die Ihr beschaffen könnt."}}
D[2522] = {"Kum'ishas Bemühungen",{"Findet eine fehlerlose Draenethystsphäre und bringt sie Kum'isha dem Sammler."}}
D[2523] = {"Verderbte Liedblume",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[2541] = {"Der schlafende Druide",{"Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil."}}
D[2561] = {"Druide der Klaue",{"Oben Zornklaue möchte, dass Ihr seinen seelenlosen Körper tötet und dann den Voodooglücksbringer anwendet."}}
D[2581] = {"Kicherfangunterkiefer",{"Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange."}}
D[2582] = {"Wut der Zeiten",{"Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange."}}
D[2583] = {"Lebenskraft des Ebers",{"Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn."}}
D[2584] = {"Geist des Ebers",{"Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn."}}
D[2585] = {"Der Entscheidungsschlag",{"Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge."}}
D[2586] = {"Salz der Skorpok",{"Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge."}}
D[2601] = {"Der Biss des Basilisken",{"Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen."}}
D[2602] = {"Unfehlbare Gedanken",{"Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen."}}
D[2603] = {"Lebensenergie des Geiers",{"Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer."}}
D[2604] = {"Geistige Beherrschung",{"Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer."}}
D[2605] = {"Der durstige Goblin",{"Beschafft Euch eine gefüllte Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger."}}
D[2606] = {"Dem guten Geschmacke",{"Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkel sprecht."}}
D[2607] = {"Die Berührung von Zanzil",{"Sprecht im Keller der Kaserne mit Dok Mixilpixil."}}
D[2608] = {"Die Berührung von Zanzil",{"Ihr solltet Euch /hinlegen, damit Dok Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?"}}
D[2609] = {"Die Berührung von Zanzil",{"Bringt Dok Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, <junger Herr/junge Dame>."}}
D[2621] = {"Der Entehrte",{"Sprecht in Steinard mit Zentralenkommandant Ruag."}}
D[2622] = {"Die fehlenden Befehle",{"Sprecht mit Bengor."}}
D[2623] = {"Der Sumpfredner",{"Beschafft die Befehle des Kriegshäuptlings wieder und gebt sie dem gefallenen Helden der Horde zurück."}}
D[2641] = {"Sprinkels Geheimzutat",{"Sprinkel in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt."}}
D[2661] = {"Lieferung für Marin",{"Sprinkel möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt."}}
D[2662] = {"Noggenfoggers Elixier",{"Marin Noggenfogger möchte, dass Ihr ihn nochmals ansprecht, wenn er sein Elixier fertiggestellt hat."}}
D[2681] = {"Die Steine, die uns binden",{"Befreit 9 Diener von Razelikh, 3 Diener von Sevine, 3 Diener von Allistarj und 3 Diener von Grol. Kehrt zum gefallenen Helden zurück, sobald Ihr die Aufgabe erfüllt habt. Ihr müsst nahe bei den Steinen bleiben, sonst habt Ihr keinen Erfolg."}}
D[2701] = {"Helden der Vergangenheit",{"Öffnet die Truhe und nehmt Euch Eure Belohnung."}}
D[2702] = {"Helden der Vergangenheit",{"Sprecht mit Korporal Thund Spalthuf."}}
D[2721] = {"Kirith",{"Findet heraus, was aus Leutnant Kirith geworden ist."}}
D[2741] = {"Der Super-Ei-O-Mat",{"Der Super-Ei-O-Mat ist die neueste Erfindung von Curgle Cranklehop. Es ist eine ziemlich beeindruckende Maschine.","","Der Super-Ei-O-Mat fängt wild an zu spucken und zu zischen, als Ihr Euch der Steuerkonsole nähert."}}
D[2742] = {"Rin'ji steckt in der Falle!",{"Eskortiert Rin'ji aus der Jagdhütte von Quel'Danil heraus und findet dann das, was er bei den Aussichtsklippen im Osten versteckt hat."}}
D[2743] = {"Der Mantel der Dunkelheit",{"Kehrt mit Euren neuen Erkenntnissen zum gefallenen Helden der Horde zurück."}}
D[2744] = {"Der Dämonenjäger",{"Sprecht mit Loramus Thalipedes in Azshara."}}
D[2745] = {"Eindringen ins Schloss",{"Sprecht in Schloss Sturmwind mit Tyrion."}}
D[2746] = {"Nicht unwichtige Gegenstände",{"Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Sturmwind zu Tyrion."}}
D[2747] = {"Ein außergewöhnliches Ei",{"Ich habe bisher nur sehr wenige Eier gesehen, die in außergewöhnlich gutem Zustand aus Feralas geholt wurden. Diese Eier sind extrem selten..."}}
D[2748] = {"Ein gutes Ei",{"Ein gutes Ei ist ein Ei, aus dem idealerweise ein Jungtier schlüpft, das frei von den bösen Auswirkungen der Beschwörungen der Oger der Gordunni ist."}}
D[2749] = {"Ein gewöhnliches Ei",{"Normalerweise schlüpft etwa aus jedem zweiten Hippogryphen-Ei auch ein Jungtier. Wir hegen und pflegen die Eier nach besten Kräften, und wenn wir Glück haben, dann schlüpft am Ende etwas da raus."}}
D[2750] = {"Ein schlechtes Ei",{"Diese Eier können nicht gerettet werden - aus ihnen wird niemals etwas schlüpfen."}}
D[2751] = {"Barbarische Waffenschmiedekunst",{"Bringt 2 gemusterte bronzene Armschienen, 2 bronzene Großschwerter und 2 scharfe Klauen zu Orokk Omosh in Orgrimmar."}}
D[2752] = {"Über Eisenschulterstücke",{"Bringt 4 bronzene Streitäxte und 4 bronzene Kriegshämmer zu Orokk Omosh in Orgrimmar."}}
D[2753] = {"In den Boden getrampelt",{"Bringt 4 grüne Eisenhelme, 4 grüne Eisenarmschienen und 2 grüne Eisengamaschen zu Orokk Omosh in Orgrimmar."}}
D[2754] = {"Hörner der Raserei",{"Bringt 2 robuste Eisenschlägel, 2 bronzene Stiefel mit Versilberung und 2 bronzene Stulpen mit Versilberung zu Orokk Omosh in Orgrimmar."}}
D[2755] = {"Freude der Omoshs",{"Seht zu und lernt den Freudentanz der Omoshs."}}
D[2756] = {"Die alten Traditionen",{"Bringt 4 Stahlbrustplatten und 4 Stahlplattenhelme zu Aturk dem Amboss in Orgrimmar."}}
D[2757] = {"Auf nach Beutebucht!",{"Sprecht mit McGavan in Beutebucht."}}
D[2758] = {"Die Herkunft der Schmiedekunst",{"Bringt 6 goldene Schuppenarmschienen zu Hank dem Hammer in Sturmwind."}}
D[2759] = {"Auf der Suche nach Galvan",{"Sprecht in Beutebucht mit McGavan."}}
D[2760] = {"Der Mithrilorden",{"Sprecht mit Galvan dem Alten im Schlingendorntal."}}
D[2761] = {"Hier verhütten, da verhütten",{"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 40 Eisenbarren."}}
D[2762] = {"Der große silberne Betrüger",{"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 5 Echtsilberbarren."}}
D[2763] = {"Die Kunst der Magieerfüllung",{"Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 4 Citrine."}}
D[2764] = {"Galvans bester Schüler",{"Sprecht in Gadgetzan mit Trenton Lichthammer."}}
D[2765] = {"Schmiedkunstexperte!",{"Fordert Eure Belohnung von Galvan dem Alten ein!"}}
D[2766] = {"Findet OOX-22/FE!",{"Bringt das Notrufsignal zu Glotz' Leitroboter in einer Höhle in der Nähe des Wildschrammtals."}}
D[2767] = {"Die Rettung von OOX-22/FE",{"Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Glotz Widrikus in Beutebucht."}}
D[2768] = {"Wünschel-mato-Rute",{"Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgenritzel."}}
D[2769] = {"Die Brüder Kupferbolz",{"Sprecht mit Wizzel Kupferbolz in der schimmernden Ebene."}}
D[2770] = {"Gahz'rilla",{"Bringt Wizzel Kupferbolz in der schimmernden Ebene Gahz'rillas elektrisierte Schuppe."}}
D[2771] = {"Ein schlauer Kopf auf den Schultern",{"Bringt Trenton Lichthammer 2 Mithrilhelmkappen und 1 verschnörkelte Mithrilschulter."}}
D[2772] = {"Die Welt zu Euren Füßen",{"Bringt Trenton Lichthammer 2 schwere Mithrilstiefel und 1 verschnörkelte Mithrilhose."}}
D[2773] = {"Mithril-Kid",{"Bringt Trenton Lichthammer 2 schwere Mithrilbrustplatten und 1 verschnörkelten Mithrilhandschuh."}}
D[2781] = {"GESUCHT: Kalif Skorpidstich",{"Bringt Chefingenieur Bilgenritzel in Gadgetzan den Kopf von Kalif Skorpidstich."}}
D[2782] = {"Rin'jis Geheimnis",{"Oran Schlangenfuß, eine bekannte Gelehrte auf dem Gebiet der Bleichborkentrolle, könnte die Tafel vielleicht übersetzen. Normalerweise hält sie sich im Magierviertel von Unterstadt auf."}}
D[2783] = {"Kleinliches Gezänk",{"Sprecht mit dem gefallenen Helden der Horde im Grenzgebiet zwischen den verwüsteten Landen und dem Sumpf."}}
D[2784] = {"In Ungnade fallen",{"Lauscht der Geschichte des gefallenen Helden der Horde."}}
D[2801] = {"Eine Geschichte voller Leid",{"Lauscht der Geschichte des gefallenen Helden der Horde."}}
D[2821] = {"Das Zeichen der Qualität",{"Bringt Pratt McGrubben in der Mondfederfeste 10 dicke Yetibälge."}}
D[2822] = {"Das Zeichen der Qualität",{"Bringt Jangdor Flinkschreiter im Camp Mojache 10 dicke Yetibälge."}}
D[2841] = {"Maschinenkriege",{"Besorgt die Maschinenblaupausen und Thermadrahts Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar."}}
D[2842] = {"Chefingenieur Scooty",{"Sprecht mit Scooty in Beutebucht."}}
D[2843] = {"Gnomer-weeeeg!",{"Wartet, bis Scooty den Goblintransponder kalibriert hat."}}
D[2844] = {"Der Riesenwächter",{"Findet das verlorene Nachtelfenmädchen."}}
D[2845] = {"Streunende Shay",{"Nehmt Shays Glocke aus der Truhe.","","Begleitet Shay Laubschleicher zu Felsbeißers Lager."}}
D[2846] = {"Tiara der Tiefen",{"Bringt die Tiara der Tiefen zu Tabetha in den Düstermarschen."}}
