D[2855] = {"Wildlederschultern",{"Bringt Jangdor Flinkschreiter im Camp Mojache 6 dicke Rüstungssets und eine Wildranke."}}
D[2856] = {"Wildlederweste",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Schildkrötenschuppenbrustplatten, 2 Schildkrötenschuppenhandschuhe und eine Wildranke."}}
D[2857] = {"Wildlederhelm",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke."}}
D[2858] = {"Wildlederstiefel",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken."}}
D[2859] = {"Wildledergamaschen",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken."}}
D[2860] = {"Meister des Wildleders",{"Gebt Una, der Lederverarbeitungsmeisterin von Donnerfels, Jangdors Schreiben."}}
D[2861] = {"Tabethas Aufgabe",{"Sprecht mit Tabetha in den Düstermarschen."}}
D[2862] = {"Krieg gegen die Waldpfoten",{"Bringt Hadoken Flinkschreiter im Camp Mojache 10 Mähnen eines Waldpfotengnolls."}}
D[2863] = {"Schlag gegen die Alphas",{"Tötet 5 Alphas der Waldpfoten und kehrt innerhalb einer Stunde zu Hadoken Flinkschreiter zurück."}}
D[2864] = {"Tran'rek",{"Sprecht mit Tran'rek in Gadgetzan."}}
D[2865] = {"Skarabäuspanzerschalen",{"Bringt Tran'rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen."}}
D[2866] = {"Die Ruinen von Solarsal",{"Erforscht die Ruinen von Solarsal und findet etwas über die Anwesenheit der Naga dort heraus."}}
D[2867] = {"Kehrt zur Mondfederfeste zurück",{"Kehrt zu Shandris Mondfeder in der Mondfederfeste zurück und berichtet von Euren Entdeckungen."}}
D[2869] = {"Gegen die Hasskämme",{"Bringt Latronicus Mondspeer in der Mondfederfeste 10 Nagaschuppen der Hasskämme."}}
D[2870] = {"Gegen Lord Shalzaru",{"Vernichtet Lord Shalzaru und bringt dann Latronicus Mondspeer in der Mondfederfeste das geheimnisvolle Relikt, das er entdeckt hat."}}
D[2871] = {"Überbringung des Relikts",{"Bringt das geheimnisvolle Relikt zu Vestia Mondspeer in der Mondfederfeste."}}
D[2872] = {"Stoleys Schuld",{"Sprecht mit Stoley beim Dampfdruckpier."}}
D[2873] = {"Stoleys Lieferung",{"Bringt Stoleys Lieferung zu Stoley beim Dampfdruckpier."}}
D[2874] = {"Lieferung für MacKinley",{"Bringt Stoleys Flasche zu \"Seewolf\" MacKinley in Beutebucht."}}
D[2875] = {"GESUCHT: Andre Feuerbart",{"Bringt Sicherheitschef Bilgenritzel beim Dampfdruckpier Andres Kopf."}}
D[2876] = {"Schiffzeitpläne",{"Berichtet den Behörden des Dampfdruckpiers von den Schiffzeitplänen."}}
D[2877] = {"Den Lauerfels aufräumen",{"Tötet 10 grüne Schlämme sowie 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei Fraggar Donnermantel beim Nistgipfel."}}
D[2878] = {"Verderbte Liedblume",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[2879] = {"Der Stock von Equinex",{"Aktiviert Troyas Stock und findet den Monolithen von Equinex."}}
D[2880] = {"Kopfgeld für Trollhalsketten",{"Bringt Fraggar Donnermantel beim Nistgipfel 5 Trollstammeshalsketten."}}
D[2881] = {"Kopfgeld für Trollhalsketten",{"Ihr habt das zwar bereits erledigt, aber wir nehmen weiterhin alle Troll-Stammeshalsketten an, die Ihr findet und eintauschen wollt. Indem Ihr sie bei mir eintauscht, verbessert Ihr weiter Eure Stellung unter den Wildhammers. Wenn Ihr für uns kämpft, dann kämpfen wir auch für Euch!","","Ich benötige 5 Troll-Stammeshalsketten, damit ich es gelten lassen kann, <Name>."}}
D[2882] = {"Cuergos Gold",{"Findet Cuergos Gold!"}}
D[2902] = {"Waldpfotennachforschung",{"Findet die Schlachtpläne der Gnolle irgendwo in den Gnoll-Lagern südlich vom Camp Mojache."}}
D[2903] = {"Die Schlachtpläne",{"Bringt die Schlachtpläne der Waldpfoten zu Hadoken Flinkschreiter ins Camp Mojache."}}
D[2904] = {"Eine schöne Bescherung",{"Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Beutebucht."}}
D[2922] = {"Rettet Techbots Hirn!",{"Bringt Techbots Speicherkern zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[2923] = {"Tüftlermeister Oberfunks",{"Sprecht mit Tüftlermeister Oberfunks in Eisenschmiede."}}
D[2924] = {"Grundlegende Artifixe",{"Bringt Klockmort Spannersplint in Eisenschmiede 12 grundlegende Artifixe."}}
D[2925] = {"Klockmorts Grundlagen",{"Sprecht mit Klockmort Spannersplint in Eisenschmiede."}}
D[2926] = {"Gnogaine",{"Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Wechselvolt nach Kharanos zurück."}}
D[2927] = {"Der Tag danach",{"Sprecht mit Ozzie Wechselvolt in Kharanos."}}
D[2928] = {"Gyrobohrmatische Exkavation",{"Bringt 24 robomechanische Innereien zu Shoni nach Sturmwind."}}
D[2929] = {"Der große Verrat",{"Reist nach Gnomeregan und tötet Robogenieur Thermadraht. Kehrt zu Hochtüftler Mekkadrill zurück, wenn der Auftrag ausgeführt ist."}}
D[2930] = {"Datenrettung",{"Bringt Mechanikermeister Gussmuff in Eisenschmiede eine Prismalochkarte."}}
D[2931] = {"Gussmuffs Auftrag",{"Sprecht mit Mechanikermeister Gussmuff in Eisenschmiede."}}
D[2932] = {"Grausige Botschaft",{"Sammelt Schädel der Bleichborken und hängt sie an Nimboyas Pike. Platziert Nimboyas behängte Pike in einem der Bleichborkendörfer im Hinterland und kehrt dann zu Nimboya ins Schlingendorntal zurück."}}
D[2933] = {"Giftflaschen",{"Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle."}}
D[2934] = {"Unbeschädigter Giftbeutel",{"Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel."}}
D[2935] = {"Konsultiert Meister Gadrin",{"Sprecht mit Meister Gadrin in Sen'jin."}}
D[2936] = {"Der Spinnengott",{"Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Bleichborken zu erfahren, und kehrt dann zu Meister Gadrin zurück."}}
D[2937] = {"Die Beschwörung von Shadra",{"Besiegt Shadra am Altar von Shadra'Alor und bringt sein Gift zu Apotheker Lydon nach Tarrens Mühle."}}
D[2938] = {"Gift für Unterstadt",{"Bringt Faranells Päckchen zu Apothekermeister Faranell nach Unterstadt."}}
D[2939] = {"Auf der Suche nach Wissen",{"Sprecht mit Daryn Leuchtwind im Dorf Rut'theran."}}
D[2940] = {"Feralas: Ein historischer Abriss",{"Fragt Daryn Leuchtwind, ob Ihr Euch ihr Buch ausleihen dürft."}}
D[2941] = {"Der Borger",{"Bringt den Brief zu Curgle Kurbelhüpf nach Tanaris."}}
D[2942] = {"Der Morgenstein",{"Bringt den funkelnden Stein und den Stock von Equinex zu Troyas Mondhauch in die Mondfederfeste."}}
D[2943] = {"Rückkehr zu Troyas",{"Liefert das Buch bei Troyas Mondhauch in der Mondfederfeste ab."}}
D[2944] = {"Der Superschnapper FX",{"Benutzt den Superschnapper FX, um einen Schnappschuss von Gammerita zu machen, und kehrt dann zu Daryn Leuchtwind nach Rut'theran zurück."}}
D[2945] = {"Schmutzverkrusteter Ring",{"Findet einen Weg, den schmutzverkrusteten Ring zu säubern."}}
D[2946] = {"Mal sehen, was passiert...",{"Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem."}}
D[2947] = {"Die Rückkehr des Rings",{"Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."}}
D[2948] = {"Gnomenverbesserungen",{"Bringt Talvash del Kissel in Eisenschmiede den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen."}}
D[2949] = {"Die Rückkehr des Rings",{"Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."}}
D[2950] = {"Noggs Ringerneuerung",{"Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen."}}
D[2951] = {"Der Funkelmat 5200!",{"Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren."}}
D[2952] = {"Der Funkelmat 5200!",{"Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.","","Tja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht..."}}
D[2953] = {"Mehr Spaß mit dem Funkelmaten",{"Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!"}}
D[2954] = {"Der Steinbehüter",{"Findet den Zweck des Steinbehüters von Norgannon heraus und interagiert dann mit dem Podest von Uldum in der Tanariswüste."}}
D[2962] = {"Das einzige Heilmittel ist mehr grünes Leuchten",{"Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.","","Ozzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist."}}
D[2963] = {"Omen von Uldum",{"Sprecht mit Historiker Karnik in der Halle der Forscher in Eisenschmiede."}}
D[2964] = {"Eine zukünftige Aufgabe",{"Sprecht mit Hochforscher Magellas in Eisenschmiede."}}
D[2965] = {"Omen von Uldum",{"Sprecht mit Nara Wildmähne auf der Anhöhe der Ältesten in Donnerfels."}}
D[2966] = {"Mal sehen, was passiert...",{"Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem."}}
D[2967] = {"Rückkehr nach Donnerfels",{"Sprecht mit Nara Wildmähne in Donnerfels."}}
D[2968] = {"Eine zukünftige Aufgabe",{"Sprecht mit dem Weisen Wahrspruch in Donnerfels."}}
D[2969] = {"Freiheit für alle Kreaturen",{"Befreit mit dem Bambuskäfigschlüssel die Grimmlingflitzer aus dem Pferch im Grimmtotemlager. Kindal Mondweber sowie mindestens 6 Grimmlingflitzer müssen überleben.","","Ihr habt 6 Minuten, bis Kindal beschließt, dass es Zeit zum Rückzug und Eure Aufgabe gescheitert ist."}}
D[2970] = {"Gerechtigkeit üben",{"Tötet 12 Naturalisten der Grimmtotem, 10 Räuber der Grimmtotem sowie 6 Schamanen der Grimmtotem und kehrt dann zu Jer'kai Mondweber nach Feralas zurück."}}
D[2972] = {"Gerechtigkeit üben",{"Bringt Jer'kais Siegelring zu Hohepriesterin Tyrande Wisperwind nach Darnassus."}}
D[2973] = {"Schimmer für einen neuen Umhang",{"Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Schädelspalter nach Camp Mojache."}}
D[2974] = {"Eine grausige Entdeckung",{"Bringt 20 Grimmtotemhörner zu Krueg Schädelspalter nach Camp Mojache."}}
D[2975] = {"Die Oger von Feralas",{"Rok Orhan im Camp Mojache will, dass Ihr 10 Oger der Gordunni, 10 Magier der Gordunni und 5 Schläger der Gordunni tötet."}}
D[2976] = {"Eine grausige Entdeckung",{"Bringt die Kiste mit Grimmtotemhörnern zu Belgrom Felshammer nach Orgrimmar."}}
D[2977] = {"Rückkehr nach Eisenschmiede",{"Sprecht mit Historiker Karnik in Eisenschmiede."}}
D[2978] = {"Die Gordunnischriftrolle",{"Bringt die Gordunnischriftrolle zu Rok Orhan ins Camp Mojache."}}
D[2979] = {"Dunkle Zeremonie",{"Rok Orhan im Camp Mojache will, dass Ihr eine Gordunnikugel findet."}}
D[2980] = {"Die Oger von Feralas",{"Rok Orhan im Camp Mojache will, dass Ihr 10 Schamanen der Gordunni, 10 Hexenmeister der Gordunni und 5 Raufer der Gordunni tötet."}}
D[2981] = {"Eine Bedrohung in Feralas",{"Belgrom Felshammer will, dass Ihr mit Rok Orhan im Camp Mojache sprecht."}}
D[2982] = {"Die obere Wildnis",{"Angelas Mondhauch will, dass Ihr 8 Hexenmeister der Gordunni, 8 Schamanen der Gordunni und 8 Schläger der Gordunni tötet."}}
D[2983] = {"Ruf des Feuers",{"Sucht Kranal Fiss im Brachland."}}
D[2984] = {"Ruf des Feuers",{"Sucht Kranal Fiss im Brachland."}}
D[2985] = {"Ruf des Wassers",{"Sucht Islen Wasserdeuter im Brachland."}}
D[2986] = {"Ruf des Wassers",{"Sucht Islen Wasserdeuter im Brachland."}}
D[2987] = {"Gordunnikobalt",{"Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt."}}
D[2988] = {"Käfige der Bleichborken",{"Durchsucht die Käfige in den beiden Dörfern der Bleichborken und kehrt dann zu Greifenmeister Krallenaxt zurück."}}
D[2989] = {"Der Altar von Zul",{"Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Krallenaxt zurück."}}
D[2990] = {"Thadius Grimmschatten",{"Bringt Scharfschnabels Feder zu Thadius Grimmschatten in die verwüsteten Lande."}}
D[2991] = {"Nekrums Medaillon",{"Bringt Thadius Grimmschatten in den verwüsteten Landen Nekrums Medaillon."}}
D[2992] = {"Der Rutengang",{"Wartet, bis Grimmschatten das Rutengangritual durchgeführt hat."}}
D[2993] = {"Rückkehr ins Hinterland",{"Sprecht mit Greifenmeister Krallenaxt."}}
D[2994] = {"Scharfschnabels Rettung",{"Kämpft Euch bis zum Gipfel von Jintha'Alor durch, tötet die üble Priesterin Hexx, um an den Schlüssel zu Scharfschnabels Käfig zu kommen, und rettet Scharfschnabel."}}
D[2995] = {"Nachrichtenwege",{"Oran Schlangenfuß in Unterstadt will, dass Ihr ins Hinterland reist und die Hochtalaufzeichnungen, Hochtalberichte und Hochtalnotizen verbrennt."}}
D[2996] = {"Die Suche nach Strahad",{"Sprecht mit Strahad Farsan in Ratschet."}}
D[2997] = {"Foliant der Offenbarung",{"Sprecht mit Tiza Kriegshammer in Eisenschmiede."}}
D[2998] = {"Foliant der Offenbarung",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[2999] = {"Foliant der Offenbarung",{"Sprecht mit Tiza Kriegshammer in Eisenschmiede."}}
D[3000] = {"Foliant der Offenbarung",{"Sprecht mit Tiza Kriegshammer in Eisenschmiede."}}
D[3001] = {"Die Suche nach Strahad",{"Findet Strahad Farsan in Ratschet."}}
D[3002] = {"Die Gordunnikugel",{"Bringt die Gordunnikugel zu Uthel'nay in die Dunkeldornenlodge in Orgrimmar."}}
D[3022] = {"Vorsichtig behandeln",{"Bringt die sorgfältig verpackte Kiste zu Erelas Himmelsbern in das Dorf Rut'theran."}}
D[3042] = {"Trollaushärter",{"Bringt 20 Phiolen Trollaushärter zu Trenton Lichthammer in Gadgetzan."}}
D[3062] = {"Dunkles Herz",{"Talo Dornhuf im Camp Mojache will das dunkle Herz von Edana Hasskralle."}}
D[3063] = {"Rache an den Nordschwingen",{"Talo Dornhuf möchte, dass Ihr 4 Harpyien der Nordschwingen, 4 Wildfedern der Nordschwingen, 4 Windruferinnen der Nordschwingen und 4 Töter der Nordschwingen erschlagt."}}
D[3065] = {"Einfache Schrifttafel",{"Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen."}}
D[3082] = {"Geätzte Schrifttafel",{"Sprecht mit Jen'shan im Tal der Prüfungen."}}
D[3083] = {"Verschlüsselte Schrifttafel",{"Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen."}}
D[3084] = {"Mit Runen beschriftete Schrifttafel",{"Sprecht mit Shikrik im Tal der Prüfungen."}}
D[3085] = {"Geheiligte Schrifttafel",{"Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen."}}
D[3086] = {"Glyphenschrifttafel",{"Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen."}}
D[3087] = {"Geätztes Pergament",{"Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen."}}
D[3088] = {"Verschlüsseltes Pergament",{"Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen."}}
D[3089] = {"Mit Runen beschriftetes Pergament",{"Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen."}}
D[3090] = {"Besudeltes Pergament",{"Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}}
D[3091] = {"Einfache Notiz",{"Lest die einfache Nachricht und sprecht mit Harutt Donnerhorn im Camp Narache."}}
D[3092] = {"Geätzte Notiz",{"Lest die geätzte Nachricht und sprecht mit Lanka Weitschuss auf der Hochwolkenebene."}}
D[3093] = {"Mit Runen beschriftete Notiz",{"Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Morgenwandler im Camp Narache."}}
D[3094] = {"Tiefgrüne Notiz",{"Lest die tiefgrüne Notiz und sprecht mit Gart Nebelläufer im Camp Narache."}}
D[3095] = {"Einfache Rolle",{"Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Todesend."}}
D[3096] = {"Verschlüsselte Rolle",{"Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Todesend."}}
D[3097] = {"Geheiligte Rolle",{"Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Todesend."}}
D[3098] = {"Glyphenrolle",{"Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Todesend."}}
D[3099] = {"Besudelte Rolle",{"Lest die besudelte Schriftrolle und sprecht mit Maximillion in Todesend."}}
D[3100] = {"Einfacher Brief",{"Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain."}}
D[3101] = {"Geweihter Brief",{"Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain."}}
D[3102] = {"Verschlüsselter Brief",{"Lest den verschlüsselten Brief und sprecht mit Jorik Kerridan im Stall hinter der Abtei von Nordhain."}}
D[3103] = {"Geheiligter Brief",{"Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain."}}
D[3104] = {"Glyphenbrief",{"Lest den mit Glyphen versehenen Brief und sprecht mit Khelden Bremen in der Abtei von Nordhain."}}
D[3105] = {"Besudelter Brief",{"Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain."}}
D[3106] = {"Einfache Rune",{"Lest die einfache Rune und sprecht mit Thran Khorman im Eisklammtal."}}
D[3107] = {"Geweihte Rune",{"Lest die geweihte Rune und sprecht mit Bromos Grummler im Eisklammtal."}}
D[3108] = {"Geätzte Rune",{"Lest die geätzte Rune und sprecht mit Thorgas Grimson im Eisklammtal."}}
D[3109] = {"Verschlüsselte Rune",{"Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Eisklammtal."}}
D[3110] = {"Geheiligte Rune",{"Lest die geheiligte Rune und sprecht mit Branstock Khalder in Ambossar."}}
D[3112] = {"Einfaches Memorandum",{"Lest das einfache Memorandum und sprecht mit Thran Khorman im Eisklammtal."}}
D[3113] = {"Verschlüsseltes Memorandum",{"Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Eisklammtal."}}
D[3114] = {"Glyphenmemorandum",{"Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Ambossar oberhalb des Eisklammtals."}}
D[3115] = {"Besudeltes Memorandum",{"Lest das besudelte Memorandum und sprecht mit Alamar Grimm in Ambossar oberhalb des Eisklammtals."}}
D[3116] = {"Einfaches Siegelzeichen",{"Lest das einfache Siegelzeichen und sprecht mit Alyissia im Laubschattental."}}
D[3117] = {"Geätztes Siegelzeichen",{"Lest das geätzte Siegelzeichen und sprecht mit Ayanna Immerlauf oben auf Aldrassil im Laubschattental."}}
D[3118] = {"Verschlüsselte Siegelzeichen",{"Lest das verschlüsselte Siegelzeichen und sprecht mit Frahun Schattenflüsterer im Laubschattental."}}
D[3119] = {"Geheiligtes Siegelzeichen",{"Lest das geheiligte Siegel und sprecht mit Shanda in Aldrassil."}}
D[3120] = {"Tiefgrünes Siegelzeichen",{"Lest das tiefgrüne Siegel und sprecht mit Mardant Starkeiche im großen Baum Aldrassil im Laubschattental."}}
D[3121] = {"Eine seltsame Anforderung",{"Bringt den Schrumpfkopf zu Neeru Feuerklinge in Orgrimmar."}}
D[3122] = {"Kehrt zu Hexendoktor Uzer'i zurück",{"Bringt Neerus Kräuterbeutel zu Hexendoktor Uzer'i in Feralas."}}
D[3123] = {"Das Gefäß wird getestet",{"Reist ins Hinterland und spürt die Wildekin auf. Schaltet 10 davon aus und benutzt dann das Muisekgefäß, um die gefallenen Wildekin zu schrumpfen und einzufangen.","","Bringt anschließend 10 Einheiten Muisek von Wildekin und das Muisekgefäß zu Hexendoktor Uzer'i in Feralas."}}
D[3124] = {"Muisek von Hippogryphen",{"Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen."}}
D[3125] = {"Muisek von Feendrachen",{"Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen."}}
D[3126] = {"Muisek von Treants",{"Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen."}}
D[3127] = {"Muisek von Bergriesen",{"Schaltet 7 Landgänger oder Klippenriesen aus. Benutzt das Muisekgefäß, um die gefallenen Bergriesen zu schrumpfen und einzufangen."}}
D[3128] = {"Natürliche Materialien",{"Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache."}}
D[3129] = {"Waffen des Geistes",{"Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet."}}
D[3130] = {"Gegen die Hasskämme",{"Meldet Euch bei Latronicus Mondspeer in der Mondfederfeste."}}
D[3141] = {"Loramus",{"Lasst Loramus Thalipedes seine Geschichte erzählen."}}
D[3161] = {"Gahz'ridian",{"Marvon Nietensucher in Tanaris möchte, dass Ihr 30 Ornamente von Gahz'ridian sammelt."}}
D[3181] = {"Das Horn der Bestie",{"Bringt Margols gigantisches Horn zu Gebirgsjägerin Feinkiesel."}}
D[3182] = {"Beweisurkunde",{"Bringt Margols gigantisches Horn zu Kurator Thorius in Eisenschmiede."}}
D[3201] = {"Endlich!",{"Bringt die Beweisurkunde zurück zu Gebirgsjägerin Feinkiesel."}}
D[3221] = {"Sprecht mit Renferrel",{"Sprecht mit Apotheker Renferrel in dem Grabmal."}}
D[3261] = {"Jorn Himmelsdeuter",{"Sprecht im Camp Taurajo mit Jorn Himmelsdeuter."}}
D[3281] = {"Gestohlenes Silber",{"Bringt das gestohlene Silber zu Gazrog beim Wegekreuz."}}
D[3301] = {"Mura Runentotem",{"Sprecht mit Mura Runentotem in dem Grabmal."}}
D[3321] = {"Habt Ihr das verloren?",{"Wartet, bis Trenton seine Arbeit erledigt hat."}}
D[3341] = {"Das Ende bringen",{"Andrew Braunell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt."}}
D[3361] = {"Dilemma eines Flüchtlings",{"Bringt Felix Windenbolz in Ambossar den Kasten, die Truhe und den Bolzeneimer von Felix."}}
D[3362] = {"Disteltal",{"Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt."}}
D[3363] = {"Verderbte Liedblume",{"Blah."}}
D[3364] = {"Lieferung des kochend heißen Morgengebräus",{"Bringt ein kochend heißes Morgengebräu zu Durnan Pelznaht in Ambossar hinein, bevor es innerhalb von fünf Minuten kalt wird!"}}
D[3365] = {"Den Becher zurückbringen",{"Bringt Nori Stolzmut den Becher zurück."}}
D[3366] = {"Der leuchtende Splitter",{"Reist nach Ratschet, um die Bedeutung des Alptraumsplitters herauszufinden."}}
D[3367] = {"Suntarasteine",{"Helft Dorius, zurück nach Eisenschmiede zu kommen."}}
D[3368] = {"Suntarasteine",{"Bringt den angesengten Brief zu Thorius in Eisenschmiede. Er befindet sich in der Halle der Forscher."}}
D[3369] = {"Alptraum",{"Bringt den Alptraumsplitter zu Hamuul Runentotem auf der Anhöhe der Ältesten."}}
D[3370] = {"Alptraum",{"Bringt den Alptraumsplitter zu Mathrengyl Bärenfährte in Darnassus."}}
D[3371] = {"Zwergengerechtigkeit",{"Kehrt zur sengenden Schlucht zurück und sucht Dorius' Archäologenteam."}}
D[3372] = {"Erlöst sie",{"Sucht das geheimnisvolle Artefakt, das im nordwestlichen Teil der Sengenden Schlucht von den Götzendienern des Schattenhammerklans bewacht wird, und bringt es zum Altar von Suntara in der Schlackengrube."}}
D[3373] = {"Die Essenz des Eranikus",{"Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet."}}
D[3374] = {"Die Essenz des Eranikus",{"Bringt den Schwurstein von Yseras Drachenschwarm sowie die gebundene Essenz des Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht."}}
D[3375] = {"Ersatzphiole",{"Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Eisenschmiede, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen."}}
D[3376] = {"Tötet Spitzhauer!",{"Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheldin Windfeder auf der Hochwolkenebene."}}
D[3377] = {"Gebet an Elune",{"Hört Zamaels Geschichte."}}
D[3378] = {"Gebet an Elune",{"Findet das Gebet an Elune und bringt es zu Astarii Sternsucher in Darnassus."}}
D[3379] = {"Schattenweber",{"Tötet die Gruppe der Schattenseidewilderer, die in der sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen."}}
D[3380] = {"Der Versunkene Tempel",{"Sucht Marvon Nietensucher in Tanaris."}}
D[3381] = {"Ein Treffen mit dem Meister",{"Bringt 2 unbeschädigte Hippogryphenfedern zu Sanath Lim-yo in Azshara, wenn Ihr mit seinem Meister sprechen wollt."}}
D[3382] = {"Eine Mannschaft in Bedrängnis",{"Verteidigt Kapitän Vanessa Beltis, ihre Mannschaft und die Passagiere der Herrin des Horizonts gegen den Angriff der Naga. Kapitän Vanessa Beltis muss überleben."}}
D[3385] = {"Der Untermarkt",{"Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Nehmt den Händlerranzen von seinem Leichnam und bringt ihn zu Nilith."}}
D[3402] = {"Der Untermarkt",{"Sprecht mit Vizzklick in Gadgetzan."}}
D[3421] = {"Rückreise",{"Ich werde Euch jetzt zu Sanaths Lager zurückbringen.","","Macht Euch nichts aus seinen schlechten Manieren - er ist zu allen unhöflich, außer zum Meister. Vielleicht wird er seine Lektion eines Tages lernen."}}
D[3441] = {"Göttliche Vergeltung",{"Lasst Kalaran Windklinge seine Geschichte erzählen."}}
D[3442] = {"Die fehlerlose Flamme",{"Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Kalaran Windklinge."}}
D[3443] = {"Das Schmieden des Schafts",{"Bringt 8 mit Thorium beschichtete Dolche zu Kalaran Windklinge."}}
D[3444] = {"Der Steinreif",{"Holt den Steinreif aus Marvon Nietensuchers Werkstatt in Ratschet."}}
D[3445] = {"Der Versunkene Tempel",{"Sucht Marvon Nietensucher in Tanaris."}}
D[3446] = {"In die Tiefen",{"Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends."}}
D[3447] = {"Das Geheimnis des Kreises",{"Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt."}}
D[3448] = {"Die Bürde weitergeben",{"Sprecht mit Magier Tymor in Eisenschmiede."}}
D[3449] = {"Arkane Runen",{"Verwendet das Abschriftenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Luntenzünder signalisiert, dass er sie abholen kann."}}
D[3450] = {"Eine einfache Ladung",{"Sprecht mit Xiggs Luntenzünder in Eisenschmiede."}}
D[3451] = {"Signal zum Abholen",{"Sprecht mit Xiggs Luntenzünder in Eisenschmiede und erhaltet von ihm eine Standardleuchtpistole."}}
D[3452] = {"Die Ummantelung der Flamme",{"Bringt ein Symbol von Ragnaros zu Kalaran Windklinge."}}
D[3453] = {"Die Fackel der Vergeltung",{"Wartet bis Kalaran Windklinge die Fackel der Vergeltung vollendet hat."}}
D[3454] = {"Die Fackel der Vergeltung",{"Nehmt die Fackel der Vergeltung."}}
D[3461] = {"Rückkehr zu Magier Tymor",{"Bringt Magier Tymors Abschriftenset zu ihm zurück nach Eisenschmiede."}}
D[3462] = {"Knappe Malzdarr",{"Sprecht mit dem Knappen Malzdarr."}}
D[3463] = {"Setzt sie in Brand!",{"Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt."}}
D[3481] = {"Plunder...",{"Öffnet die Truhe."}}
D[3482] = {"<NYI> <TXT> The Pocked Black Box",{"Bringt diesen Flugschreiber zu Kravel."}}
D[3483] = {"Signal zum Abholen",{"Ah, noch eine Leuchtfeuerwaffe, hm? Die kann ich Euch geben.","","Und vergesst nicht, Südspitze von Azshara. Es ist eine kleine Insel, die in eine Landungsplattform verwandelt wurde. Ihr könnt sie gar nicht verfehlen, wenn Ihr an der richtigen Stelle sucht."}}
D[3501] = {"Im Dutzend besser",{"Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt."}}
D[3502] = {"Des einen Draeneis Plunder...",{"Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den verwüsteten Landen könnte ein Fragment bei sich tragen."}}
D[3503] = {"Treffen mit dem Meister",{"Es gab Zeiten, in denen ich alles von denen, die meinen Meister aufsuchen wollten, verlangen konnte. Heute ist es anders, Ihr müsst nur nach ihm fragen und ich schicke Euch zu ihm.","","Es ist ärgerlich für mich, aber ich stelle seine Befehle nicht in Frage. Ich kann mich lediglich an Eurer lächerlichen Aufmachung oder Eurem jämmerlichen Gesichtsausdruck erfreuen. Selbst das langweilt mich...","","Sogar dieses Geschwafel langweilt mich! Möchtet Ihr meinen Meister sehen oder nicht?"}}
D[3504] = {"Verraten",{"Bringt den versiegelten Brief zu Ag'tor Blutfaust nach Azshara."}}
D[3505] = {"Verraten",{"Tötet 10 Blutelfeneintreiber und 10 Blutelfenfeldmesser, bevor Ihr Magus Rimtoris Lager sucht. Sobald Ihr es gefunden habt, sucht nach etwas, das für sie von Bedeutung ist und das wir nehmen können, um sie in einen Kampf zu locken."}}
D[3506] = {"Verraten",{"Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Blutfaust nach Azshara."}}
D[3507] = {"Verraten",{"Sprecht mit Belgrom Felshammer in Orgrimmar."}}
D[3508] = {"Den Zauberschutz brechen",{"Wartet, bis Loramus den Erleuchtungszauber vollendet hat."}}
D[3509] = {"Der Name der Bestie",{"Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden."}}
D[3510] = {"Der Name der Bestie",{"Erschlagt Hetaera und bringt den blutigen Kopf Hetaeras, den geschlagenen Kopf Hetaeras und den verwundeten Kopf Hetaeras zu Lord Arkkoroc."}}
D[3511] = {"Der Name der Bestie",{"Bringt den Härter zurück zu Loramus Thalipedes."}}
D[3512] = {"Mit Eranikus' eigenen Worten",{"Reist in den östlichen Teil von Winterquell und sprecht mit Umbranse, dem Geistsprecher."}}
D[3513] = {"Die runenverzierte Rolle",{"Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes."}}
D[3514] = {"Hordenpräsenz",{"Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin."}}
D[3517] = {"Wissen stehlen",{"Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt."}}
D[3518] = {"Lieferung an Magatha",{"Bringt die Schrifttafel von Beth'Amara zu Magatha in Donnerfels."}}
D[3519] = {"Ein Freund in Not",{"Sprecht mit Dirania Silberschein im Laubschattental."}}
D[3520] = {"Kreischergeister",{"Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya beim Dampfdruckpier zurück."}}
D[3521] = {"Iverrons Gegengift",{"Sammelt 7 Hyazinthpilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silberschein im Laubschattental."}}
D[3522] = {"Iverrons Gegengift",{"Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden."}}
D[3523] = {"Geißel der Niederungen",{"Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab."}}
D[3524] = {"An Land gespült",{"Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück."}}
D[3525] = {"Ausschalten des Götzen",{"Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln der Klingenhauer.","","Beschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."}}
D[3526] = {"Gobliningenieurskunst",{"Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan."}}
D[3527] = {"Die Prophezeiung von Mosh'aru",{"Bringt die erste und die zweite Schrifttafel von Mosh'aru zu Yeh'kinya nach Tanaris."}}
D[3528] = {"Der Gott Hakkar",{"Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris."}}
D[3541] = {"Lieferung an Jes'rimon",{"Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar."}}
D[3542] = {"Lieferung an Andron Gant",{"Bringt die Schrifttafel von Markri zu Andron Gant nach Unterstadt."}}
D[3561] = {"Lieferung für Erzmagier Xylem",{"Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara."}}
D[3562] = {"Magathas Bezahlung für Jediga",{"Bringt Magathas Notiz zu Jediga in Azshara."}}
D[3563] = {"Jes'rimons Bezahlung für Jediga",{"Bringt Jes'rimons Notiz zu Jediga in Azshara."}}
D[3564] = {"Androns Bezahlung für Jediga",{"Bringt Androns Notiz zu Jediga in Azshara."}}
D[3565] = {"Xylems Bezahlung für Jediga",{"Bringt Xylems Notiz zu Jediga in Azshara."}}
D[3566] = {"Erhebt Euch, Obsidion!",{"Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Eisenschmiede mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion."}}
D[3567] = {"An die Spitze",{"Würdet Ihr den Ausblick von einem der Zwillingskolosse bevorzugen? Ich kann Euch dorthin schicken, <Volk>.","","Aber überlegt, wie Ihr wieder herunterkommt. Ich kann Euch nur nach oben schicken."}}
D[3568] = {"Verbreitete Verderbnis",{"Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Miesmut zurück."}}
D[3569] = {"Verbreitete Verderbnis",{"Gebt Miesmuts Elixier Thersa Windweise in Unterstadt."}}
D[3570] = {"Verbreitete Verderbnis",{"Ich hätte mir nie träumen lassen, dass das Elixier so schnell Wirkung zeigen würde. Danke, <Name>. Ich werde mich sofort an die Untersuchung der restlichen Proben machen. Bestimmt werden sie für Lady Silvanas und die Verlassenen schon bald von Nutzen sein."}}
D[3601] = {"Kim'jael, fürwahr!",{"Durchsucht den thalassischen Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Knobelwizz und bringt ihm dann alles nach Azshara zurück."}}
D[3602] = {"Azsharit",{"Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.","","Kehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[3621] = {"Die Herstellung von Teufelsbann",{"Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal."}}
D[3625] = {"Verzauberte Azsharitteufelswaffe",{"Wartet, bis Galvan die Waffen fertig geschmiedet hat."}}
D[3626] = {"Rückkehr in die verwüsteten Lande",{"Kehrt zum Gefallenen Helden der Horde zurück."}}
D[3627] = {"Das zerbrochene Amulett vereinen",{"Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.","","Denkt daran, Eure Verzauberte Azsharitteufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise..."}}
D[3628] = {"Ihr seid Rakh'likh, Dämon",{"Vernichtet Razelikh den Entweiher und bringt das abgetrennte Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt."}}
D[3629] = {"Gobliningenieurskunst",{"Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt das Handbuch der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan."}}
D[3630] = {"Gnomeningenieurskunst",{"Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[3631] = {"Teufelsross beschwören",{"Sprecht mit Strahad Farsan im Brachland."}}
D[3632] = {"Gnomeningenieurskunst",{"Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[3633] = {"Gobliningenieurskunst",{"Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan."}}
D[3634] = {"Gnomeningenieurskunst",{"Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[3635] = {"Gnomeningenieurskunst",{"Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht."}}
D[3636] = {"Das Licht bringen",{"Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln der Klingenhauer tötet."}}
D[3637] = {"Gnomeningenieurskunst",{"Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht."}}
D[3638] = {"Der Schwur der Geheimhaltung",{"Wenn Ihr ein Gobliningenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Nixx Sprossfeder in Gadgetzan sprechen."}}
D[3639] = {"Zeigt Eure Arbeit",{"Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprossfeder nach Gadgetzan."}}
D[3640] = {"Der Schwur der Geheimhaltung",{"Wenn Ihr ein Gnomeningenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Oberfunks in Eisenschmiede sprechen."}}
D[3641] = {"Zeigt Eure Arbeit",{"Bringt 6 Mithrilrohre, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Oberfunks in Eisenschmiede."}}
D[3642] = {"Der Schwur der Geheimhaltung",{"Wenn Ihr ein Gnomeningenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Glotz Widrikus in Beutebucht sprechen."}}
D[3643] = {"Zeigt Eure Arbeit",{"Bringt 6 Mithrilrohre, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Glotz Widrikus in Beutebucht."}}
D[3644] = {"Mitgliedskarten-Erneuerung",{"Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen."}}
D[3645] = {"Mitgliedskarten-Erneuerung",{"Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen."}}
D[3646] = {"Mitgliedskarten-Erneuerung",{"Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen."}}
D[3647] = {"Mitgliedskarten-Erneuerung",{"Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen."}}
D[3661] = {"Elunes Lieblinge?",{"Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Himmelsbern in Rut'theran."}}
D[3681] = {"Foliant der Offenbarung",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[3701] = {"Die glimmenden Ruinen von Thaurissan",{"Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Relikte von Thaurissan. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt."}}
D[3702] = {"Die glimmenden Ruinen von Thaurissan",{"Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan."}}
D[3721] = {"Ein eigener OOX",{"Ihr habt drei meiner OOX-Leitroboter gefunden! Ihr habt viel mehr als das getan, worum ich Euch gebeten hatte. Daher will ich Euch etwas Besonderes für Eure Hilfe geben. Dies ist eine Miniaturversion jenes Roboters, den Ihr jetzt kennt und liebt, den OOX!","","Ich würde normalerweise niemandem solch ein potenziell tödliches Gerät anvertrauen, aber Ihr wart eine wirklich große Hilfe. Außerdem wurden die Kampfmechanismen und die Leitlogik dieses Exemplars deaktiviert.","","Aber abgesehen davon ist das ein echter OOX!"}}
D[3741] = {"Hilarys Halskette",{"Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück."}}
D[3761] = {"Erde von Un'Goro",{"Bringt 20 Erdproben von Un'Goro zu Ghede auf der Anhöhe der Ältesten in Donnerfels."}}
D[3762] = {"Erzdruide Runentotem helfen",{"Sprecht in Donnerfels mit Erzdruide Hamuul Runentotem."}}
D[3763] = {"Erzdruide Hirschhaupt helfen",{"Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus."}}
D[3764] = {"Erde von Un'Goro",{"Bringt 20 Erdproben von Un'Goro zu Jenal in der Enklave des Cenarius in Darnassus."}}
D[3765] = {"Verderbnis in der Fremde",{"Reist zu Gershala Nachtraunen in Auberdine."}}
D[3781] = {"Morgenkornforschung",{"Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bärenfährte in der Enklave des Cenarius des Darnassus."}}
D[3782] = {"Morgenkornforschung",{"Bringt den Samenkorngutschein zu Bashana Runentotem in Donnerfels."}}
D[3783] = {"Sind wir endlich da, Yeti?",{"Sammelt 10 dicke Yetifelle für Umi Rumpelkicher in der Ewigen Warte."}}
D[3784] = {"Erzdruide Runentotem helfen",{"Sprecht in Donnerfels mit Erzdruide Hamuul Runentotem."}}
D[3785] = {"Morgenkornforschung",{"Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Erdproben von Un'Goro, um Morgenkorn zu kultivieren.","","Bringt 10 Einheiten Morgenkorn zu Mathrengyl Bärenfährte in Darnassus."}}
D[3786] = {"Morgenkornforschung",{"Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Erdproben von Un'Goro, um Morgenkorn zu kultivieren.","","Bringt 10 Einheiten Morgenkorn zu Bashana Runentotem in Donnerfels."}}
D[3787] = {"Lebenshands Bitte",{"Sprecht mit Quintis Lebenshand in der Mondfederfeste."}}
D[3788] = {"Lebenshands Bitte",{"Sprecht mit Quintis Lebenshand in der Mondfederfeste."}}
D[3789] = {"Erzdruide Hirschhaupt helfen",{"Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus."}}
D[3790] = {"Erzdruide Hirschhaupt helfen",{"Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus."}}
D[3791] = {"Das Geheimnis des Morgenkorns",{"Bringt 10 Einheiten Morgenkorn zu Quintis Lebenshand in der Mondfederfeste."}}
D[3792] = {"Morgenkorn für die Mondfederfeste",{"Abermals hallo, <Name>. Meine Forschung macht gute Fortschritte, aber wenn Ihr fünf weitere Einheiten Morgenkorn habt, würde ich Euch die sehr gern abnehmen. Na ja... 'gern' ist nicht wirklich der richtige Ausdruck dafür; je länger ich mich in seiner Umgebung befinde, desto unwohler fühle ich mich. Aber für meine Forschungen ist es nun mal nötig, dass ich mich zusammenreiße und weiterarbeite."}}
D[3801] = {"Dunkeleisenerbe",{"Sprecht mit Franclorn Schmiedevater, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten."}}
D[3802] = {"Dunkeleisenerbe",{"Erschlagt Fineous Dunkelader und bergt den großen Hammer Eisenhölle. Bringt Eisenhölle zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Schmiedevater."}}
D[3803] = {"Morgenkorn nach Darnassus",{"Der Erzdruide sucht ständig nach mehr Morgenkorn für die weiteren Forschungsarbeiten des Zirkels des Cenarius. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen."}}
D[3804] = {"Morgenkorn nach Donnerfels",{"Der Erzdruide sucht ständig nach mehr Morgenkorn für das Forschungsprojekt des Zirkels des Cenarius über den Un'Goro Krater. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen."}}
D[3821] = {"Schreckensfels",{"Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Ehrenhauer geworden ist."}}
D[3822] = {"Krom'Grul",{"Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels."}}
D[3823] = {"Die Feuermagenoger auslöschen",{"Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid."}}
D[3824] = {"Gor'tesh der Schläger-Lord",{"Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück."}}
D[3825] = {"Ogerkopf auf einem Pfahl = Party",{"Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen."}}
D[3841] = {"Waise sucht Zuhause",{"Sprecht mit Quentin in Tausend Nadeln."}}
D[3842] = {"Kurz vor dem Schlüpfen",{"Bringt 2 Elixiere der Seelenstärke zu Quentin in Tausend Nadeln."}}
D[3843] = {"Das neueste Mitglied der Familie",{"Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Tiermeister, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei."}}
D[3844] = {"Es ist für jeden ein Geheimnis",{"Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte."}}
D[3845] = {"Es ist für jeden ein Geheimnis",{"Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer."}}
D[3861] = {"GLUCK!",{"Beschafft Euch etwas Spezialhühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezialhühnerfutter gebt."}}
D[3881] = {"Rettungsexpedition",{"Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marschall im Krater von Un'Goro."}}
D[3882] = {"Knochenklappern",{"Bringt 8 Dinosaurierknochen zu Funks Nilminer im Krater von Un'Goro."}}
D[3883] = {"Eine fremdartige Ökologie",{"Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Krater von Un'Goro zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.","","Bringt die Schwarmbauwandprobe zu Hol'anyee Marschall im Krater von Un'Goro."}}
D[3884] = {"Willidens Tagebuch",{"Bringt das Tagebuch zu Williden Marschall zurück. Er befindet sich irgendwo im Krater von Un'Goro."}}
D[3901] = {"Klappernde Skelette",{"Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Todesend zurück, wenn Ihr fertig seid."}}
D[3902] = {"Beutesuche in Todesend",{"Durchsucht Todesend und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück."}}
D[3903] = {"Milly Geltmark",{"Sprecht mit Milly Geltmark."}}
D[3904] = {"Millys Ernte",{"Bringt 8 Kisten mit Millys Ernte zu Milly Geltmark in der Nähe der Abtei von Nordhain."}}
D[3905] = {"Traubenliste",{"Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain."}}
D[3906] = {"Disharmonie der Flamme",{"Reist zum Steinbruch am Schwarzfels und tötet Übermeister Pyron. Kehrt zu Donnerherz zurück, sobald Ihr den Auftrag erledigt habt."}}
D[3907] = {"Disharmonie des Feuers",{"Betretet die Schwarzfelstiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Donnerherz."}}
D[3908] = {"Es ist für jeden ein Geheimnis",{"Bringt Linkens Schwert zu Donova Schneeweh in Winterquell."}}
D[3909] = {"Das Videre-Elixier",{"Sucht nach Gregan Hopfenspei im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Schneeweh nach Winterquell zurück."}}
D[3911] = {"Das letzte Element",{"Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hin gemurmelt hat."}}
D[3912] = {"Treffen am Grab",{"Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden."}}
D[3913] = {"Grabesstille",{"Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat."}}
D[3914] = {"Linkens Schwert",{"Liefert Linkens überragendes Schwert bei Linken im Krater von Un'Goro ab."}}
D[3921] = {"Wenikee Kübelbolz",{"Bringt das zerbrochene Samophlang zu Wenikee Kübelbolz."}}
D[3922] = {"Schraubnieten",{"Bringt 15 Schraubnieten zu Wenikee Kübelbolz im Brachland."}}
D[3923] = {"Rilli Schmierklump",{"Bringt das zerbrochene und ramponierte Samophlang nach Orgrimmar zu Rilli Schmierklump."}}
D[3924] = {"Samophlanghandbuch",{"Bringt das Samophlanghandbuch nach Orgrimmar zu Rilli Schmierklump."}}
D[3941] = {"Die Hilfe des Gnoms",{"Sucht J.D. Collie in der Höhle in Marschalls Zuflucht auf."}}
D[3942] = {"Linkens Andenken",{"Sucht Eridan Blauwind im südlichen Teil des Teufelswalds."}}
D[3961] = {"Linkens Abenteuer",{"Bringt das Silbertotem von Aquementas zu Linken in Marschalls Zuflucht."}}
D[3962] = {"Allein ist es gefährlich",{"Begebt Euch zum Feuersäulengrat südlich von Marschalls Zuflucht.","","Sucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle."}}
D[3981] = {"Kommandant Gor'shak",{"Sucht Kommandant Gor'shak in den Schwarzfelstiefen.","","Ihr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen."}}
D[3982] = {"Was ist los?",{"Verteidigt Gor'shak."}}
D[4001] = {"Was ist los?",{"Sprecht mit Kharan Hammermacht und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebart. Bringt diese Informationen dann zu Thrall nach Orgrimmar.","","Ihr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten."}}
D[4002] = {"Das östliche Königreich",{"Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen."}}
D[4003] = {"Die königliche Rettung",{"Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebart von seinem bösen Zauber."}}
D[4004] = {"Ist die Prinzessin gerettet?",{"Kehrt zu Thrall zurück!"}}
D[4005] = {"Aquementas",{"Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.","","Benutzt das Buch von Aquor, um Aquementas zu beschwören.","","Wenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marschalls Zuflucht zurück."}}
D[4021] = {"Gegenangriff!",{"Bringt ein Teil von Krom'zars Flagge zu Regthar Totenfurt, westlich des Wegekreuzes."}}
D[4022] = {"Eine Kostprobe der Flamme",{"Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windklinge erhalten habt."}}
D[4023] = {"Eine Kostprobe der Flamme",{"Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.","","Ihr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid."}}
D[4024] = {"Eine Kostprobe der Flamme",{"Begebt Euch in die Schwarzfelstiefen und tötet Bael'Gar.","","Ihr wisst lediglich, dass der Riese irgendwo in den Schwarzfelstiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.","","Bringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück."}}
D[4041] = {"Das Videre-Elixier",{"Klar, wenn Ihr mir eine Evowurzel bringt, dann kann ich Euch auch das Videre-Elixier machen.","","Ich weiß alle möglichen Dinge über Kräuter und Alchimie... Ich könnte Euch Geschichten erzählen... zum Beispiel, wie ich mal Gold aus dem Käse gemacht habe, den ich eigentlich zum Mittagessen... he! Wo wollt Ihr hin?"}}
D[4061] = {"Aufstieg der Maschinen",{"Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.","","Euch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter."}}
D[4062] = {"Aufstieg der Maschinen",{"Bringt die Elementarsplitterprobe zu Lotwil Veriatus.","","Ihr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert."}}
D[4063] = {"Aufstieg der Maschinen",{"Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt."}}
D[4081] = {"SOFORT TÖTEN: Dunkeleisenzwerge",{"Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!","","Kriegsherr Bluthauer möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[4082] = {"SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge",{"Begebt Euch in die Schwarzfelstiefen und vernichtet die üblen Aggressoren!","","Kriegsherr Bluthauer möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[4083] = {"Der spektrale Kelch",{"Der spektrale Kelch schwebt in der Luft, leicht ansteigend und dann absinkend, so, als bewege er sich im Takt eines sterbenden Herzens."}}
D[4084] = {"Silberherz",{"Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Blauwind im Teufelswald."}}
D[4101] = {"Den Teufelswald säubern",{"Bringt 15 Einheiten Blutharz zu Arathandris Silberwolke im Teufelswald."}}
D[4102] = {"Den Teufelswald säubern",{"Bringt 15 Einheiten Blutharz zu Maybess Flussbrise im Teufelswald."}}
D[4103] = {"Salbe durch Jagd",{"Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.","","Im Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[4104] = {"Salbe durch Bergbau",{"Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.","","Wenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[4105] = {"Salbe durch Sammlung",{"Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.","","Wenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben."}}
D[4106] = {"Salbe durch Kürschnerei",{"Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.","","Sobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe."}}
D[4107] = {"Salbe durch Entzauberung",{"Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.","","Ich brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen."}}
D[4108] = {"Salbe durch Jagd",{"Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.","","Im Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[4109] = {"Salbe durch Bergbau",{"Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.","","Wenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[4110] = {"Salbe durch Sammlung",{"Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Läuterungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.","","Wenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben."}}
D[4111] = {"Salbe durch Kürschnerei",{"Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.","","Sobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch einige cenarische Pflanzensalben dafür, die ich bereits hergestellt habe."}}
D[4112] = {"Salbe durch Entzauberung",{"Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.","","Ich brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen."}}
D[4113] = {"Verderbte Liedblume",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4114] = {"Verderbte Liedblume",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4115] = {"Verderbte Windblüte",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4116] = {"Verderbte Liedblume",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4117] = {"Verderbte Peitscherwurzel",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4118] = {"Verderbte Liedblume",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4119] = {"Verderbter Nachtdrache",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4120] = {"Die Kraft der Verderbnis",{"Talo Dornhuf im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt."}}
D[4121] = {"Gefährliche Zwickmühle",{"Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Schwarzfels in die sengende Schlucht.","","Euch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.","","Ihr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen."}}
D[4122] = {"Grark Lorkrub",{"Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung des Schwarzfelsklans gesehen worden.","","Wenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Schwarzfels in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen."}}
D[4123] = {"Das Herz des Berges",{"Bringt das 'Herz des Berges' zu Maxwort Funkelglanz in der brennenden Steppe."}}
D[4124] = {"Der vermisste Kurier",{"Sprecht mit Ginro Herdfeuer in der Mondfederfeste."}}
D[4125] = {"Der vermisste Kurier",{"Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas."}}
D[4126] = {"Hurley Pestatem",{"Bringt Ragnar Donnerbräu in Kharanos das verlorene Donnerbräurezept."}}
D[4127] = {"Havarie",{"Kehrt zur Mondfederfeste zurück und zeigt Ginro Herdfeuer das gefundene Messer."}}
D[4128] = {"Ragnar Donnerbräu",{"Sprecht mit Ragnar Donnerbräu."}}
D[4129] = {"Das wieder aufgetauchte Messer",{"Bringt Quintis Lebenshand in der Mondfederfeste das gefundene Messer."}}
D[4130] = {"Psychometrie-Sitzung",{"Sprecht mit Ginro Herdfeuer in der Mondfederfeste."}}
D[4131] = {"Die Waldpfotengnolle",{"Durchsucht die Lager der Waldpfotengnolle im Süden von Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten."}}
D[4132] = {"Operation: Tod dem Zornesschmied",{"Begebt Euch zu den Schwarzfelstiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Bluthauer zurück, sobald Ihr diese Aufgabe erledigt habt."}}
D[4133] = {"Vivian Lagrave",{"Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath."}}
D[4134] = {"Verlorenes Donnerbräurezept",{"Bringt Vivian Lagrave in Kargath das verlorene Donnerbräurezept."}}
D[4135] = {"Die verwundene Tiefe",{"Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen."}}
D[4136] = {"Ribbly Schraubstutz",{"Bringt Yuka Schraubstutz in der brennenden Steppe Ribblys Kopf."}}
D[4141] = {"Muigin und Larion",{"Sammelt 15 Blutblüten und kehrt zu Muigin zurück."}}
D[4142] = {"Ein Besuch bei Gregan",{"Bringt Gregan Hopfenspei in Feralas eine Blutblüte."}}
D[4143] = {"Der Dunst des Bösen",{"Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Krater von Un'Goro."}}
D[4144] = {"Blutblütensprösslinge",{"Das ist mein Plan, <Name>: Zieht los und sammelt ein paar Blutblütensprösslinge - Ihr wisst schon, das sind Pflanzen, die noch nicht ganz ausgetrieben haben, und bringt sie mir. Dann werde ich sehen, was man mit dem Dunst der Atal'ai anfangen kann.","","Ihr haltet mich vielleicht für rachsüchtig ... Und damit liegt Ihr absolut richtig!","","Die Wahrheit ist, ich weiß, wie man hier wegkommt, aber solange Larion nicht zugibt, dass ich Recht habe, rühre ich mich nicht von der Stelle!","","Und nun hinfort mit Euch. Sucht diese Blutblütensprösslinge, dann gönnen wir uns ein bisschen Spaß!"}}
D[4145] = {"Larion und Muigin",{"Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marschalls Zuflucht."}}
D[4146] = {"Schrumpftreibstoff",{"Bringt Larion in Marschalls Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai."}}
D[4147] = {"Marvons Werkstatt",{"Reist zu Marvon Nietensuchers Werkstatt in Ratschet."}}
D[4148] = {"Blutblütenschrumpfer",{"Damit der Schrumpfer funktioniert, brauchen wir ein Exemplar der Kreaturen, für die er eingestellt werden soll. Geht zum Krater und holt einen Blutblütensprössling. Dann kann ich ihn so einstellen, dass er bei Muigins kleinen Freunden funktioniert...","","Wenn der Typ nicht so stur wäre, könnten wir alle schon längst auf dem Heimweg sein. Aber jetzt muss ich ihm erst einmal beweisen, dass mir seine Faxen nicht das Geringste ausmachen!"}}
D[4161] = {"Rezept der Kaldorei",{"Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar."}}
D[4181] = {"Gobliningenieurskunst",{"Wenn Ihr mehr über die Gobliningenieurskunst wissen wollt, dann bringt das Handbuch der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan."}}
D[4182] = {"Drachkin-Bedrohung",{"Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 Schwarzwyrmkins und 1 Schwarzdrachen. Kehrt zu Helendis Flusshorn zurück, sobald die Aufgabe erledigt ist."}}
D[4183] = {"Die wahren Meister",{"Reist nach Seenhain und händigt Magistrat Solomon Helendis Flusshorns Brief aus."}}
D[4184] = {"Die wahren Meister",{"Reist nach Sturmwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.","","Bolvar residiert in der Burg Sturmwind."}}
D[4185] = {"Die wahren Meister",{"Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon."}}
D[4186] = {"Die wahren Meister",{"Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus."}}
D[4201] = {"Der Liebestrank",{"Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Schwarzfelstiefen."}}
D[4221] = {"Verderbte Windblüte",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4222] = {"Verderbte Windblüte",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4223] = {"Die wahren Meister",{"Sprecht mit Marschall Maxwell in der brennenden Steppe."}}
D[4224] = {"Die wahren Meister",{"Sprecht mit dem struppigen John, um etwas über Marschall Windsors Schicksal zu erfahren, und kehrt dann zu Marschall Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.","","Ihr erinnert Euch daran, dass Marschall Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen."}}
D[4241] = {"Marschall Windsor",{"Reist zum Schwarzfels im Nordwesten und dann weiter zu den Schwarzfelstiefen. Findet heraus, was aus Marschall Windsor geworden ist.","","Ihr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt."}}
D[4242] = {"Verlorene Hoffnung",{"Überbringt Marschall Maxwell die schlechten Neuigkeiten."}}
D[4243] = {"Chasing A-Me 01",{"Sucht im Krater von Un'Goro nach A-Me 01."}}
D[4244] = {"Chasing A-Me 01",{"Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Krater von Un'Goro."}}
D[4245] = {"Chasing A-Me 01",{"Begleitet A-Me 01 zu Karna Wirrbart im Krater von Un'Goro."}}
D[4261] = {"Alter Geist",{"Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Waldeslied, im Osten des Eschentals."}}
D[4262] = {"Übermeister Pyron",{"Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.","","Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?"}}
D[4263] = {"Incendius!",{"Sucht Lord Incendius in den Schwarzfelstiefen und vernichtet ihn!"}}
D[4264] = {"Eine zusammengeknüllte Notiz",{"Soeben seid Ihr auf etwas gestoßen, das Marschall Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung."}}
D[4265] = {"Flucht aus dem Schwarmbau",{"Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.","","Kehrt zu Ginro Herdfeuer in der Mondfederfeste zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht."}}
D[4266] = {"Der Empfang eines Helden",{"Sprecht mit Shandris Mondfeder in der Mondfederfeste."}}
D[4267] = {"Aufstieg der Silithiden",{"Bringt Raschals Bericht zu Gracina Glaubensmacht in Darnassus."}}
D[4281] = {"Thalanaar-Lieferung",{"Bringt das nicht ausgelieferte Paket zu Falfindel Wegeshut in Thalanaar."}}
D[4282] = {"Ein Funken Hoffnung",{"Holt Marschall Windsors verlorene Informationen zurück.","","Marschall Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden."}}
D[4283] = {"FÜNFZIG! Jawoll!",{"Oralius will 50 Medaillons des Schwarzfelsklans haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet."}}
D[4284] = {"Machtkristalle",{"Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marschalls Zuflucht."}}
D[4285] = {"Der Nordpylon",{"Findet den Standort des nördlichen Kristallpylonen im Krater von Un'Goro."}}
D[4286] = {"Feine Sachen",{"Reist in die Schwarzfelstiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Schwarzfelstiefen diese 'Gürteltaschen'-Dinger tragen."}}
D[4287] = {"Der Ostpylon",{"Findet den Standort des östlichen Kristallpylonen im Krater von Un'Goro."}}
D[4288] = {"Der Westpylon",{"Findet den Standort des westlichen Kristallpylonen."}}
D[4289] = {"Die Affen von Un'Goro",{"Bringt Torwa Pfadfinder am Eingang zum Krater von Un'Goro 2 Gorillapelze von Un'Goro, 2 Stampferpelze von Un'Goro und 2 Donnererpelze von Un'Goro."}}
D[4290] = {"Lar'korwis Mahl",{"Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pfadfinder im Krater von Un'Goro zurück."}}
D[4291] = {"Lar'korwis Fährte",{"Bringt Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro 2 Pheromondrüsen eines Ravasaurus."}}
D[4292] = {"Ein Köder für Lar'korwi",{"Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro."}}
D[4293] = {"Eine Brühschleimerprobe...",{"Sammelt Teufelswaldschleimproben von den Brühschlammern im Teufelswald. Verwendet dann die Testausrüstung neben Chemiker Brenner in Unterstadt, um zu sehen, welche Eurer Proben am verderbtesten sind. Bringt 5 der verderbten Teufelswaldproben, die Ihr findet, zu Chemiker Brenner."}}
D[4294] = {"...und eine Menge Brühschlammer",{"Sammelt Brühschleimerprobe von Un'Goro von jedem der Brühschleimer im Krater von Un'Goro. Verwendet dann die Testausrüstung neben Chemiker Brenner in Unterstadt, um zu sehen, welche Eurer Proben am reinsten sind. Bringt 5 der reinen Proben von Un'Goro, die Ihr findet, zu Chemiker Brenner."}}
D[4295] = {"Rocknots Bier",{"Oh, Bier! Was würde ich nicht für etwas Dunkeleisenbier geben! Schnell, ich werde langsam nüchtern! Das weiß ich, weil mir die Nüchternheit die Sinne trübt... und weil es Euch aussehen lässt wie der <Volk>, den ich letzte Woche erschlagen habe!"}}
D[4296] = {"Schrifttafel der Sieben",{"Bringt Maxwort Funkelglanz in der brennenden Steppe die Abschrift der Schrifttafel."}}
D[4297] = {"Essen für das Baby",{"Bringt Agnar Tiermeister im Hinterland 5 Silbermähnenpirscherflanken."}}
D[4298] = {"Elternfreuden",{"Sprecht mit Agnar Tiermeister im Hinterland."}}
D[4300] = {"Knochenklingenwaffen",{"Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen."}}
D[4301] = {"Der mächtige U'cha",{"Bringt U'chas Pelz zu Torwa Pfadfinder am Eingang des Kraters von Un'Goro."}}
D[4321] = {"Die Sache verstehen",{"Sprecht demnächst mit J. D. Collie."}}
D[4322] = {"Gefängnisausbruch!",{"Helft Marschall Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marschall Maxwell zurück, wenn Ihr Erfolg hattet."}}
D[4324] = {"Yuka Schraubstutz",{"Sprecht mit Yuka Schraubstutz in der brennenden Steppe."}}
D[4341] = {"Kharan Hammermacht",{"Begebt Euch in die Schwarzfelstiefen und findet Kharan Hammermacht.","","Der König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten."}}
D[4342] = {"Kharans Geschichte",{"Lasst Kharan Hammermacht seine Geschichte erzählen."}}
D[4343] = {"Verderbte Windblüte",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4361] = {"Der Überbringer schlechter Botschaften...",{"Kehrt nach Eisenschmiede zurück und überbringt König Magni Bronzebart die schlechten Nachrichten."}}
D[4362] = {"Das Schicksal des Königreichs",{"Kehrt in die Schwarzfelstiefen zurück und rettet Prinzessin Moira Bronzebart aus den Fängen des bösen Imperators Dagran Thaurissan."}}
D[4363] = {"Die Überraschung der Prinzessin",{"Kehrt nach Eisenschmiede zurück und sprecht mit König Magni Bronzebart."}}
D[4381] = {"Kristallflicker",{"Mit Hilfe der Pylon-Tafel könnt Ihr grüne und gelbe Machtkristalle miteinander verbinden.","","Laut J.D.s Handbuch könnt Ihr mit dieser Kombination Euch oder Eure Verbündeten heilen."}}
D[4382] = {"Kristallkraft",{"Mit Hilfe der Pylon-Tafel könnt Ihr grüne und blaue Machtkristalle miteinander verbinden.","","Laut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Geist steigern."}}
D[4383] = {"Kristallbarriere",{"Mit Hilfe der Pylon-Tafel könnt Ihr grüne und rote Machtkristalle miteinander verbinden.","","Laut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Schutz vor körperlichem Schaden stärken."}}
D[4384] = {"Kristallschwächer",{"Mit Hilfe der Pylon-Tafel könnt Ihr rote und blaue Machtkristalle miteinander verbinden.","","Laut J.D.s Handbuch könnt Ihr mit dieser Kombination die Verteidigung eines Gegners schwächen."}}
D[4385] = {"Kristallsprengladung",{"Mit Hilfe der Pylon-Tafel könnt Ihr rote und gelbe Machtkristalle miteinander verbinden.","","Laut J.D.s Handbuch könnt Ihr mit dieser Kombination eine starke Explosion auslösen, die Euren Feinden Schaden zufügt."}}
D[4386] = {"Kristallspitze",{"Mit Hilfe der Pylon-Tafel könnt Ihr blaue und gelbe Machtkristalle miteinander verbinden.","","Laut J.D.s Handbuch könnt Ihr mit dieser Kombination einen Schild erschaffen, der Euren Feinden Schaden zufügt."}}
D[4401] = {"Verderbte Liedblume",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4402] = {"Galgars Kaktusapfel Surprise",{"Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen."}}
D[4403] = {"Verderbte Windblüte",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
D[4421] = {"Die Verderbnis der Jadefeuer",{"Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Blauwind im Teufelswald zurück, sobald die Aufgabe erledigt ist."}}
D[4441] = {"Gebundene Urtume",{"Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück."}}
D[4442] = {"Geläutert!",{"Sprecht Eridan gleich noch einmal an."}}
D[4443] = {"Verderbte Peitscherwurzel",{"Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll."}}
