D[4481] = {"Buchband der Konstitution",{"Für jedes Ding auf dieser Welt gilt es, einen Preis zu bezahlen. Und der Preis für den speziellen Gegenstand, den Ihr wünscht, beläuft sich auf dreißig Goldstücke.","","Selbstverständlich werde ich den Großteil der Komponenten, die Ihr eingesammelt habt, für mich selbst zurückbehalten. Doch sorgt Euch nicht, Ihr sollt Euren Plunder erhalten."}}
D[4482] = {"Buchband der Hartnäckigkeit",{"Dreißig Goldstücke, <Volk>. Dreißig Goldstücke und die benötigten Komponenten."}}
D[4483] = {"Buchband der Abhärtung",{"Wenn es Widerstandsfähigkeit ist, die Ihr wünscht, so benötige ich dreißig Goldstücke."}}
D[4484] = {"Buchband der Gier",{"Vergeudet meine Zeit nicht, <Volk>. Gebt mir das, was ich benötige. Dreißig Goldstücke und die Komponenten."}}
D[4485] = {"Der Foliant des Adels",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[4486] = {"Der Foliant des Adels",{"Sprecht mit Duthorian Rall in Sturmwind."}}
D[4487] = {"Teufelsross beschwören",{"Sprecht mit Strahad Farsan in Ratschet."}}
D[4488] = {"Teufelsross beschwören",{"Sprecht mit Strahad Farsan in Ratschet."}}
D[4489] = {"Teufelsross beschwören",{"Sprecht mit Strahad Farsan in Ratschet."}}
D[4490] = {"Teufelsross beschwören",{"Sprecht in Ratschet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört."}}
D[4491] = {"Etwas Hilfe von guten Freunden",{"Führt Ringo zu Spraggel Frock in Marschalls Zuflucht.","","Falls Ringo ohnmächtig werden sollte, verwendet Spraggles Feldflasche, um ihn zu beleben."}}
D[4492] = {"Verloren!",{"Sucht Ringo am Feuersäulengrat."}}
D[4493] = {"Der Marsch der Silithiden",{"Sprecht in Gadgetzan mit Alchimist Stößelbruch."}}
D[4494] = {"Der Marsch der Silithiden",{"Sprecht in Gadgetzan mit Alchimist Stößelbruch."}}
D[4495] = {"Ein guter Freund",{"Sucht Iverron an der Höhle im Norden."}}
D[4496] = {"Dschungelei",{"Bringt eine Gorishiduftdrüse und 5 Erdproben von Un'Goro zu Alchimist Stößelbruch in Gadgetzan."}}
D[4501] = {"Vorsicht, Pterrordax!",{"Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggel Frock in Marschalls Zuflucht."}}
D[4502] = {"Vulkanische Aktivität",{"Sammelt 9 Proben der Asche von Un'Goro von den Feuerelementaren am Vulkan im Krater von Un'Goro ein und bringt die Proben zu Liv Ritzelflick in Ratschet."}}
D[4503] = {"Sappalots Flieger",{"Sammelt 8 eingesponnene Dimetrodonschuppen und 8 eingesponnene Pterrordaxschuppen für Sappalot in Marschalls Zuflucht."}}
D[4504] = {"Superkleber",{"Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan."}}
D[4505] = {"Brunnen der Verderbnis",{"Beschafft eine Probe verderbten Wassers vom Mondbrunnen der Jadefeuersatyrn und bringt sie zu Winna Hazzard am Blutgiftposten."}}
D[4506] = {"Verderbte Säbler",{"Bringt Winnas Kätzchen zum verderbten Mondbrunnen, lasst es dort frei und bringt es dann wieder zu Winna zurück.","","Sobald Ihr wieder bei Winna seid, klickt auf die Katze, um sie Winna zu übergeben."}}
D[4507] = {"Bauer schlägt Dame",{"Besiegt die Schwarmkönigin der Gorishi, sobald sie erscheint.","","Bringt das Gehirn der Schwarmkönigin zu Alchimist Stößelbruch nach Gadgetzan."}}
D[4508] = {"Die Ruhe vor dem Sturm",{"Bringt Stößelbruchs Bericht von Un'Goro zu Gracina Glaubensmacht in Darnassus."}}
D[4509] = {"Die Ruhe vor dem Sturm",{"Bringt Stößelbruchs Bericht von Un'Goro zu Zilzibin Tomtom in Orgrimmar."}}
D[4510] = {"Die Ruhe vor dem Sturm",{"Bringt den Bankgutschein zu Idriana in der Bank von Darnassus."}}
D[4511] = {"Die Ruhe vor dem Sturm",{"Bringt den Bankgutschein zu Karus in der Bank von Orgrimmar."}}
D[4512] = {"Brühschlammer auf Abwegen",{"Bringt 6 gefüllte verfluchte Brühschlammergläser und 6 gefüllte besudelte Brühschlammergläser zu Laris Bummelritzel in Eisenschmiede."}}
D[4513] = {"Brühschlammer auf Abwegen",{"Bringt 10 gefüllte reine Probengläser zu Laris Bummelritzel in Eisenschmiede.","","Falls Ihr Probleme habt, fündig zu werden, dann kann Laris Euch vielleicht noch den einen oder anderen Hinweis geben."}}
D[4521] = {"Wilde Wächter",{"Trull Scheiterbann im Teufelswald möchte, dass Ihr 15 tobende Eulenbestien und 15 struppige Eulenbestien tötet."}}
D[4542] = {"Nachricht zum Freiwindposten",{"Bringt Klippenbehüter Langhorn am Freiwindposten die dringende Nachricht."}}
D[4561] = {"Test auf Unreinheiten - Krater von Un'Goro",{"Ihr nehmt eine Brühschleimerprobe aus dem Un'Goro Krater und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Brühschleimer seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure geläuterten Un'Goro-Brühschleimerproben sowie einige andere Rückstände enthält."}}
D[4581] = {"Kayneth Stillwind",{"Bringt Shindrells Notiz zu Kayneth Stillwind in Waldeslied."}}
D[4601] = {"Der Funkelmat 5200!",{"Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren."}}
D[4602] = {"Der Funkelmat 5200!",{"Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren."}}
D[4603] = {"Funkelmatastisch",{"Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!"}}
D[4604] = {"Funkelmatastisch",{"Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!"}}
D[4605] = {"Der Funkelmat 5200!",{"Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.","","Tja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht..."}}
D[4606] = {"Der Funkelmat 5200!",{"Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.","","Tja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht..."}}
D[4621] = {"Holla, Admiral!",{"Tötet Flottenmeister Seehorn und Baron Revilgaz aus Beutebucht und kehrt dann zu Flottenmeister Firallon zurück. Er befindet sich auf der Purpurschleier vor der Küste des Schlingendorntals."}}
D[4641] = {"Euer Platz in der Welt",{"Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen."}}
D[4642] = {"Vereinigung von Einflüssen",{"Bringt eine verschmolzene Brühschlammerprobe zum Chemiker Brenner in Unterstadt."}}
D[4661] = {"Test für Verderbnis - Teufelswald",{"Ihr nehmt eine Brühschlammerprobe aus dem Teufelswald und gebt etwas davon in die verschiedenen Röhren und Bechergläser auf dem Tisch. Als alles Mögliche zu blubbern und zu zischen anfängt, verändert der Schleim seine Farbe. Dann kommt der Prozess zum Abschluss. Die Flüssigkeiten beruhigen sich wieder und Ihr seht eine kleine Petrischale, die Eure veränderten Teufelswaldschleimproben und einige andere Rückstände enthält."}}
D[4681] = {"An Land gespült",{"Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde."}}
D[4701] = {"Stellt sie ab",{"Begebt Euch zur Schwarzfelsspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs."}}
D[4721] = {"Wilde Wächter",{"Trull Scheiterbann im Teufelswald möchte, dass Ihr in Winterquell 10 Berserkereulenbestien jagt."}}
D[4722] = {"Gestrandete Meeresschildkröte",{"Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4723] = {"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4724] = {"Die Herrin der Meute",{"Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte."}}
D[4725] = {"Gestrandete Meeresschildkröte",{"Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4726] = {"Brutlingessenz",{"Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Kesseldampf am Flammenkamm in der brennenden Steppe."}}
D[4727] = {"Gestrandete Meeresschildkröte",{"Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4728] = {"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4729] = {"Kiblers Exotische Tiere",{"Begebt Euch zur Schwarzfelsspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler."}}
D[4730] = {"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4731] = {"Gestrandete Meeresschildkröte",{"Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4732] = {"Gestrandete Meeresschildkröte",{"Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4733] = {"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}}
D[4734] = {"Ei-Frosten",{"Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst."}}
D[4735] = {"Eiersammlung",{"Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Kesseldampf am Flammenkamm in der brennenden Steppe."}}
D[4736] = {"Auf der Suche nach Menara Leerbringer",{"Sprecht mit Menara Leerbringer im Brachland."}}
D[4737] = {"Auf der Suche nach Menara Leerbringer",{"Sprecht mit Menara Leerbringer im Brachland."}}
D[4738] = {"Auf der Suche nach Menara Leerbringer",{"Sprecht im Brachland mit Menara Leerbringer."}}
D[4739] = {"Auf der Suche nach Menara Leerbringer",{"Sprecht mit Menara Leerbringer im Brachland."}}
D[4740] = {"GESUCHT: Gurgelbacke!",{"Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.","","Informiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod."}}
D[4741] = {"Wilde Wächter",{"Trull Scheiterbann im Teufelswald möchte, dass Ihr in Winterquell 13 mondbestrahlte Eulenbestien jagt."}}
D[4742] = {"Siegel des Aufstiegs",{"Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.","","Vaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten."}}
D[4743] = {"Siegel des Aufstiegs",{"Reist zum Drachensumpf in den Düstermarschen. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.","","In genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!"}}
D[4761] = {"Thundris Windwirker",{"Sprecht mit Thundris Windwirker in Auberdine."}}
D[4762] = {"Der Klippenquell",{"Geht von Auberdine aus nach Norden zum ersten Wasserfall des Klippenquell und entnehmt aus dem Teich dort eine Probe.","","Kehrt mit der Probe des Klippenquells zu Thundris Windwirker nach Auberdine zurück."}}
D[4763] = {"Die verderbten Schwarzfelle",{"Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.","","Holt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.","","Mischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Klippenquell auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.","","Nehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine."}}
D[4764] = {"Doomriggers Schnalle",{"Bringt Mayara Wolkenglanz in der brennenden Steppe Doomriggers Schnalle."}}
D[4765] = {"Lieferung an Kronenbrunn",{"Bringt Kronenbrunns Kiste zu Remington Kronenbrunn nach Sturmwind."}}
D[4766] = {"Mayara Wolkenglanz",{"Sprecht mit Mayara Wolkenglanz in der brennenden Steppe."}}
D[4767] = {"Windreiter",{"Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen."}}
D[4768] = {"Die Dunkelsteinschrifttafel",{"Bringt der Schattenmagierin Vivian Lagrave in Kargath die Dunkelsteinschrifttafel."}}
D[4769] = {"Vivian Lagrave und die Dunkelsteinschrifttafel",{"Sprecht mit Schattenmagierin Vivian Lagrave."}}
D[4770] = {"Auf der Heimreise",{"Begleitet Pao'ka Bergrausch aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Feuermähne."}}
D[4771] = {"Dämmerungstrickfalle",{"Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Moppelzink zurück."}}
D[4781] = {"Komponenten für die verzauberte Goldblutrobe",{"Bringt Xizk Gutstich im Schlingendorntal einen Goldbarren."}}
D[4782] = {"Komponenten für die verzauberte Goldblutrobe",{"Kehrt zu Menara Leerbringer im Brachland zurück."}}
D[4783] = {"Komponenten für die verzauberte Goldblutrobe",{"Bringt Menara Leerbringer im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein."}}
D[4784] = {"Komponenten für die verzauberte Goldblutrobe",{"Bringt Menara Leerbringer im Brachland feinen Goldfaden, 2 glimmende Kohlen und einen Seelensplitter."}}
D[4785] = {"Feiner Goldfaden",{"Bitte sehr, <Name>. Und bitte richtet doch Menara Grüße von uns aus.","","Wir erwarten große Dinge von Euch. Wenn die Legion in die Knie gezwungen ist, wird man bestimmt Euren Namen rufen und Eure Kraft preisen. Ich kann es kaum erwarten!"}}
D[4786] = {"Die fertiggestellte Robe",{"Wartet, bis Menara Leerbringer Eure Robe fertiggestellt hat, und sprecht dann noch einmal mit ihr."}}
D[4787] = {"Das uralte Ei",{"Bringt das uralte Ei zu Yeh'kinya nach Tanaris."}}
D[4788] = {"Die letzten Schrifttafeln",{"Bringt Ausgrabungsleiter Eisenschuh in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru."}}
D[4801] = {"E'ko der Frostsäbler",{"In Winterspring da werdeta gegen große Katzens kämpfen müssen, das sin' de Frostsäblers. Diese Biesties sin' unglaublich schnell un' gerissen. Wenn Ihr auch so schnell wie 'n Frostsäbler sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.","","Nich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt."}}
D[4802] = {"E'ko der Winterfelle",{"In Winterspring da werdeta gegen fehlgeleitete Kreaturens kämpfen, das sin' de Winterfellfurbolgse. Weil ihr Anführer das so wollt', ham die unglaubliche Kraft gekriegt. Wenn Ihr auch so stark wie 'n Winterfell sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.","","Nich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt."}}
D[4803] = {"E'ko eines Splitterzahns",{"In Winterspring, da sin' große Bärens mit extrem dicken Bälgens. Diese Splitterzahnbären kriegen davon so viel Schutz, dasse unheimlich viel Zeugs widerstehen könn'. Wenn Ihr gegen Feuer auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'nem Splitterzahn kriegt.","","Nich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt."}}
D[4804] = {"E'ko der Eiswindschimären",{"In Winterspring, da müssta gegen große fliegende Kreaturens kämpfen, das sin' de Eiswindschimären. Diese Biesties könn' Frostmagie wirken. Wenn Ihr gegen Frost auch so widerstandsfähig sein wollt, dann bringt mir das E'ko, das Ihr von 'ner Eiswindschimäre kriegt.","","Nich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt."}}
D[4805] = {"E'ko der Eisdistelyetis",{"In Winterspring, da müssta gegen große Kreaturens kämpfen, das sin' de Eisdistelyetis. Diese Viecher bewegen sich nur langsam, aber se könn' Dank dem dicken Fell 'ne Menge Prügel einstecken. Wenn Ihr auch so gut wie die Angriffen ausweich'n wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.","","Nich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt."}}
D[4806] = {"E'ko der Frosthagelriesen",{"In Winterspring habta gegen de großen Eisriesens gekämpft, de Frosthagel. Die verlassen sich auf rohe Gewalt und Kraft. Wenn Ihr auch so stark wie 'n Frosthagelriese sein wollt, dann bringt mir das E'ko, das Ihr von ihnen kriegt.","","Nich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt."}}
D[4807] = {"E'ko der Wildekin",{"In Winterspring, da müssta gegen Kreaturens kämpfen, die ham anscheinend angeborene magische Fertigkeitens. Diese Wildekinses könn' echt starke Magie anwenden. Wenn Ihr Euren Intellekt erweitern wollt, dann bringt mir das E'ko von allen denen Eulenbiesters, die Ihr dort findet.","","Nich' vergessen: Ihr müsst 'n Behälter von Mau'ari in Eurem Inventar haben, wenn Ihr Euch E'ko schnappen wollt."}}
D[4808] = {"Felnok Stahlfeder",{"Gebt Felnok Stahlfeder Tinkees Brief."}}
D[4809] = {"Hörner der Eiswindschimären",{"Bringt Felnok Stahlfeder 8 unbeschädigte Hörner einer Eiswindschimäre."}}
D[4810] = {"Rückkehr zu Tinkee",{"Bringt Tinkee Kesseldampf in der brennenden Steppe Felnoks Paket."}}
D[4811] = {"Der rote Kristall",{"Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."}}
D[4812] = {"Wenn das Wasser fließt",{"Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste."}}
D[4813] = {"Die Fragmente im Inneren",{"Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."}}
D[4821] = {"Fremdartiges Ei",{"Bringt Hagar Blitzhuf am Freiwindposten das fremdartige Ei."}}
D[4822] = {"Lecker Eis",{"Besorgt für Euren Schützling etwas Erdbeereis. Der kleine scheint die Marke 'Tigule und Forors Eiscreme' zu bevorzugen."}}
D[4841] = {"Befriedung der Zentauren",{"Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Langhorn am Freiwindposten zurück."}}
D[4842] = {"Sonderbare Quellen",{"Befolgt Donova Schneewehs Anweisungen und meldet Euch dann wieder bei ihr."}}
D[4861] = {"Wütende Wildekin",{"Findet Jaron Steinschleifers ruiniertes Lager samt dessen Vorräte im südlichen Winterquell."}}
D[4862] = {"Be-Öh-Es-Eh",{"Reist zur Schwarzfelsspitze und sammelt 15 Spitzenspinneneier für Kibler.","","Logischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden."}}
D[4863] = {"Wütende Wildekin",{"Sucht Jaron Steinschleifers zerstörten Wagen."}}
D[4864] = {"Wütende Wildekin",{"Klaubt Jarons Ladung aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.","","Bringt Jaron Steinschleifer in der Lodge in Winterquell dessen Ladung und das blaugefiederte Amulett."}}
D[4865] = {"Wilde Schlange",{"Berichtet Motega Feuermähne von Euren Entdeckungen."}}
D[4866] = {"Muttermilch",{"Ihr findet Mutter Glimmernetz im Herzen der Schwarzfelsspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann."}}
D[4867] = {"Urok Schreckensbote",{"Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh."}}
D[4881] = {"Auftragsmordplan",{"Warnt Kanati Grauwolke am Weißgipfelposten, dass man vorhat, ihn zu töten."}}
D[4882] = {"Geheimnisse bewachen",{"Bringt Trull Scheiterbann beim Blutgiftposten das blaugefiederte Amulett."}}
D[4883] = {"Geheimnisse bewahren",{"Bringt Nara Wildmähne das blaugefiederte Amulett."}}
D[4901] = {"Wächter des Altars",{"Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Himmelsbern in Rut'theran von Eurem Fund."}}
D[4902] = {"Wildekin von Elune",{"Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus."}}
D[4903] = {"Befehl des Kriegsherrn",{"Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Schwarzfelsdokumente. Kehrt zum Kriegsherrn Bluthauer nach Kargath zurück, sobald Ihr diese Mission erledigt habt."}}
D[4904] = {"Endlich frei",{"Geleitet Lakota Windweise vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Bernhaut."}}
D[4906] = {"Weitere Verderbnis",{"Eridan Blauwind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[4907] = {"Tinkee Kesseldampf",{"Sprecht mit Tinkee Kesseldampf."}}
D[4921] = {"In der Schlacht vermisst",{"Sucht Mankriks Frau und kehrt dann zu ihm in die Siedlung beim Wegekreuz zurück."}}
D[4941] = {"Etriggs Weisheit",{"Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.","","Ihr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt."}}
D[4961] = {"Die Säuberung der Kugel von Orahil",{"Tötet den Dämon der Kugel und sprecht dann mit Tabetha."}}
D[4962] = {"Splitter eines Teufelshundes",{"Nehmt den Teufelsrubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Leerbringer im Brachland den eingekerkerten Teufelshundgeist und den Teufelsrubin."}}
D[4963] = {"Splitter einer Höllenbestie",{"Nehmt den Infussmaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Leerbringer im Brachland den eingekerkerten Höllenbestiengeist und den Infussmaragd."}}
D[4964] = {"Die fertiggestellte Kugel von Dar'Orahil",{"Wartet, bis Menara Leerbringer die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr."}}
D[4965] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Leerbringer im Brachland."}}
D[4966] = {"Kanati Grauwolke schützen",{"Beschützt Kanati Grauwolke vor den Angriffen der Zentauren."}}
D[4967] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Leerbringer im Brachland."}}
D[4968] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Leerbringer im Brachland."}}
D[4969] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Leerbringer im Brachland."}}
D[4970] = {"Frostsäblerverpflegung",{"Sammelt 5 Splitterzahnfleischstücke und 5 Fleischstücke einer Eiswindschimäre für Rivern Frostwind in Winterquell."}}
D[4971] = {"Eine Frage der Zeit",{"Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.","","Tötet 10 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den westlichen Pestländern."}}
D[4972] = {"Tempus fugit",{"Sucht 5 Uhren von Andorhal, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den westlichen Pestländern zurück."}}
D[4973] = {"Tempus fugit",{"Sucht 5 Uhren von Andorhal in den Ruinen der Stadt und bringt sie Chromie im Gasthaus Andorhal in den westlichen Pestländern."}}
D[4974] = {"Für die Horde!",{"Begebt Euch zur Schwarzfelsspitze und tötet den Kriegshäuptling Rend Schwarzfaust. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück."}}
D[4975] = {"Die fertiggestellte Kugel von Noh'Orahil",{"Wartet, bis Menara Leerbringer die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr."}}
D[4976] = {"Ablieferung der gesäuberten Kugel",{"Bringt die gesäuberte Höllenkugel zu Menara Leerbringer ins Brachland."}}
D[4981] = {"Agentin Bijou",{"Begebt Euch zur Schwarzfelsspitze und findet heraus, was aus Bijou geworden ist."}}
D[4982] = {"Bijous Habseligkeiten",{"Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben."}}
D[4983] = {"Bijous Aufklärungsbericht",{"Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath."}}
D[4984] = {"Die Tierwelt leidet auch",{"Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Tiefenfurt auf dem trostlosen Feld in den westlichen Pestländern zurück."}}
D[4985] = {"Die Tierwelt leidet auch",{"Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Tiefenfurt auf dem trostlosen Feld in den westlichen Pestländern zurück."}}
D[4986] = {"Glyphenverzierter Eichenast",{"Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe."}}
D[4987] = {"Glyphenverzierter Eichenast",{"Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Donnerfels bringt. Bittet einen der Druiden dort um Hilfe."}}
D[5001] = {"Bijous Habseligkeiten",{"Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!"}}
D[5002] = {"Nachricht an Maxwell",{"Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marschall Maxwell weiter."}}
D[5021] = {"Besser spät als nie",{"Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts."}}
D[5022] = {"Besser spät als nie",{"Wendet Euch an die königlichen Disponenten von Sturmwind, um etwas über den Aufenthaltsort von Emma Teufelsstein herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus."}}
D[5023] = {"Besser spät als nie",{"Wendet Euch an die königlichen Vorarbeiter von Unterstadt, um etwas über den Aufenthaltsort von Jeremiah Teufelsstein herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung."}}
D[5041] = {"Vorräte für das Wegekreuz",{"Findet die Vorratskisten des Wegekreuzes und bringt sie zu Thork im Brachland zurück."}}
D[5042] = {"Agammagans Kraft",{"Ich benötige 4 Blutsplitter, wenn Ihr Agammagans Kraft wünscht, <Volk>.","","Eure Feinde werden vor Eurer Kraft erzittern, wenn Ihr über diesen Segen verfügen würdet.","","Die größten Krieger der Grimmhauer sind mit solcher Stärke ausgestattet!"}}
D[5043] = {"Agammagans Beweglichkeit",{"Man sagt, dass die größten Späher meines Stammes in ihrer Genauigkeit unübertroffen seien und kein Schurke <schnaubt> ihrer Schnelligkeit im Kampf standhalten könne.","","Bringt mir 4 Blutsplitter und ich werde Euch noch flinker machen als jeder lebende Stacheleber."}}
D[5044] = {"Weisheit von Agammagan",{"Die Schamanen und Geomanten der Stacheleberstämme <schnaubt> nutzen die Kraft von Agammagan im Kampf und bei ihren Ritualen, <Volk>.","","Wenn auch Ihr die zusätzliche Macht von Agammagans Segen für Eure Zauber wünscht, dann bringt mir 4 Blutsplitter, und Quetschzahn wird Euch helfen."}}
D[5045] = {"Steigerung des Geistes",{"Krieger aller Art <schnaubt> benötigen einen starken Geist. Er treibt Euch zu größeren Leistungen, wenn alle Hoffnung verloren ist. Das ist den Grimmhauern nicht <schnaubt> unbekannt. Wir sind ein spiritueller Stamm... wir sind stolzer auf unsere Verbindung zu Agammagan als auf unsere Leistungsfähigkeit <schnaubt> im Kampf.","","Bringt mir 4 Blutsplitter und ich werde Euch für den Kampf segnen. <schnaubt>"}}
D[5046] = {"Klingenhaut",{"Alle, die <schnaubt> in den Kampf eintreten, benötigen Schutz. Ihre Knochen müssen stark sein. Ihre Haut zäh. <schnaubt> Mein Stamm weiß das auch und um den natürlichen Schutz zu verstärken, den wir durch unsere Stacheln und unsere Haut erhalten, <schnaubt> rufen wir Agammagan an, uns vor Schaden zu schützen, bevor wir in den Krieg ziehen.","","Bringt mir 4 Blutsplitter <schnaubt> und ich werde Euch den gleichen Schutz gewähren."}}
D[5047] = {"Finkle Einhorn, zu Euren Diensten!",{"Sprecht mit Malyfous Düsterhammer in der Ewigen Warte."}}
D[5048] = {"Emma die Nette",{"Sucht die alte Emma in Sturmwind und findet heraus, ob sie tatsächlich Emma Teufelsstein ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Teufelsstein für sie gepackt hat."}}
D[5049] = {"Der Jammer des Jeremiah",{"Sucht Jeremiah Lohnson in Unterstadt und findet heraus, ob er tatsächlich Jeremiah Teufelsstein ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Teufelsstein für ihn gepackt hat."}}
D[5050] = {"Glücksbringer",{"Bringt Janice Teufelsstein in den westlichen Pestländern die Hälfte ihres Glücksbringers zurück."}}
D[5051] = {"Zwei Hälften vereint",{"Sucht auf dem Teufelssteinfeld in den westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.","","Gebt den Glücksbringer Janice Teufelsstein auf dem Teufelssteinfeld in den westlichen Pestländern."}}
D[5052] = {"Blutsplitter von Agammagan",{"Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.","","Sammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet."}}
D[5054] = {"Ursius von den Splitterzahnbären",{"Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Ursius tötet."}}
D[5055] = {"Brumeran von den Eiswindschimären",{"Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Brumeran tötet."}}
D[5056] = {"Shy-Rotam",{"Storm Schattenhuf in der Ewigen Warte in Winterquell möchte, dass Ihr Shy-Rotam besiegt."}}
D[5057] = {"Frühere Abenteuer",{"Bringt Storm Schattenhufs Gutschein zu Melor Steinhuf in Donnerfels."}}
D[5058] = {"Frau Dalsons Tagebuch",{"Ein Tagebuch mit vergilbten Seiten liegt aufgeschlagen da, sodass man den letzten Eintrag lesen kann:","","\"Ich weiß nicht, was passieren wird, jetzt, wo Harold sich verwandelt hat. Es hat mich meine ganze Kraft gekostet, ihn zu dem einzigen Ort zu schleppen, den ich finden konnte, in dem er sicher eingesperrt ist und nicht herauskommen kann. Den Schlüssel habe ich bei mir und ich kann nur beten, dass es funktionieren wird ...","","Ich hoffe, ich schaffe es, hier herauszukommen, aber dazu brauche ich Geld. Unsere ganzen Sachen sind alle im Schrank, glaube ich ... und jetzt, wo ich darüber nachdenke - trägt Harold den Schlüssel dazu nicht bei sich?","","Ich muss darüber schlafen. Im Augenblick bin ich todmüde.\""}}
D[5059] = {"Weggeschlossen",{"Der von Splittern gezeichnete Türrahmen des Plumpsklos sieht aus, als ob wiederholt und unablässig versucht worden wäre, die Tür gewaltsam zu öffnen. Sie ist derzeit von außen fest verschlossen.","","Als Ihr an der Tür rüttelt, hört Ihr aus dem Inneren ein kehliges Stöhnen! Was auch immer sich im Inneren befindet, es klingt nicht freundlich."}}
D[5060] = {"Weggeschlossen",{"Vor Euch steht ein sehr stabiler Schrank, sicher verschlossen mit einem eingebauten Schloss. Die Vorderseite des Schranks ist mit tiefen Kratzern und Riefen übersät. Offensichtlich sind das die Zeichen zahlreicher und gewaltsamer fehlgeschlagener Versuche, die Geheimnisse zu enthüllen, die der Schrank derzeit verbirgt.","","Wenn Ihr diesen Schrank öffnen wollt, müsst Ihr den Schlüssel finden."}}
D[5061] = {"Wassergestalt",{"Kehrt nach Darnassus zurück und zeigt Mathrengyl Bärenfährte den Anhänger des Seelöwen."}}
D[5062] = {"Hochheiliges Feuer",{"Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Donnerfels."}}
D[5063] = {"Kappe des scharlachroten Wissenden",{"Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden.","","Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen."}}
D[5064] = {"Grimmtotemspionage",{"Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück."}}
D[5065] = {"Die verlorenen Schrifttafeln von Mosh'aru",{"Bringt Ausgrabungsleiter Eisenschuh in Tanaris die dritte und vierte Schrifttafel von Mosh'aru."}}
D[5066] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges."}}
D[5067] = {"Gamaschen von Arcana",{"Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit.","","Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen."}}
D[5068] = {"Brustplatte des Blutdurstes",{"Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Düsterhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens.","","Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen."}}
D[5081] = {"Maxwells Mission",{"Reist zur Schwarzfelsspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marschall Maxwell zurück, wenn Eure Aufgabe erledigt ist."}}
D[5082] = {"Bedrohung durch die Winterfelle",{"Donova Schneeweh in Winterquell möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt."}}
D[5083] = {"Feuerwasser der Winterfelle",{"Bringt das leere Feuerwasserfläschchen zu Donova Schneeweh in Winterquell."}}
D[5084] = {"Der Verderbnis erliegen",{"Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis."}}
D[5085] = {"Geheimnisvoller Glibber",{"Berichtet Donova Schneeweh von Euren Entdeckungen."}}
D[5086] = {"Toxinschrecken",{"Sammelt 3 Toxinschreckentropfen für Donova Schneeweh in Winterquell."}}
D[5087] = {"Läufer der Winterfelle",{"Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen."}}
D[5088] = {"Arikara",{"Erschlagt Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Feuermähne im Weißgipfelposten als Beweis für Eure Tat."}}
D[5089] = {"General Drakkisaths Befehl",{"Bringt den Befehl von General Drakkisath zu Marschall Maxwell in der brennenden Steppe."}}
D[5090] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges."}}
D[5091] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges."}}
D[5092] = {"Den Weg räumen",{"Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Trauerhügel.","","Kehrt zu Kommandant Ashlam Ehrenschlag am Zugwindlager, westliche Pestländer, zurück."}}
D[5093] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt."}}
D[5094] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt."}}
D[5095] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt."}}
D[5096] = {"Scharlachrote Ablenkung",{"Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.","","Lasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den westlichen Pestländern zurück."}}
D[5097] = {"Turm um Turm",{"Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.","","Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Ehrenschlag am Zugwindlager, westliche Pestländer, zurück."}}
D[5098] = {"Turm um Turm",{"Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.","","Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, westliche Pestländer, zurück."}}
D[5101] = {"Lee's Ultimate Test Quest... of Doom!",{"Tötet 6 Schafe für Benny... und dann nehmt die Füße in die Hand und rennt weg, was das Zeug hält!","","War nur 'n Scherz... was das Rennen angeht."}}
D[5102] = {"General Drakkisaths Niedergang",{"Begebt Euch zur Schwarzfelsspitze und schaltet General Drakkisath aus. Kehrt zu Marschall Maxwell zurück, wenn Eure Aufgabe erledigt ist."}}
D[5103] = {"Heißer, feuriger Tod",{"Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!"}}
D[5121] = {"Oberhäuptling der Winterfelle",{"Donova Schneeweh in Winterquell möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt."}}
D[5122] = {"Das Medaillon des Glaubens",{"Die Macht dieser Kapelle gibt mir die Kraft, der Verderbnis in meinem Herzen zu widerstehen. Wenn ich sie verlasse, werde ich zu einem Todesritter. Aber es gibt ein Medaillon, das Medaillon des Glaubens, das mir so viel Kraft geben wird, dass ich trotzdem gehen kann.","","Bitte, <Name>, findet das Medaillon für mich. Es wird von Malor dem Eifrigen bewacht, einem wahnsinnigen Mitglied der Scharlachroten Bruderschaft. Er lebt tief in der scharlachroten Bastion im westlichen Stratholme."}}
D[5123] = {"Das letzte Stück",{"Bringt das kunstlos geschriebene Logbuch zu Donova Schneeweh in Winterquell."}}
D[5124] = {"Feurige Plattenstulpen",{"Bringt Malyfous Düsterhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben."}}
D[5125] = {"Aurius' Abrechnung",{"<Name>, ich sterbe... aber meine Seele ist gerettet. Dafür schulde ich Euch mehr, als man mit Worten ausdrücken kann. Bitte, nehmt dies... und kämpft weiter so mutig, <Klasse>!"}}
D[5126] = {"Lorax' Geschichte",{"Sprecht mit Lorax. Hört, was er zu sagen hat."}}
D[5127] = {"Die Dämonenschmiede",{"Begebt Euch zur Schwarzfelsspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.","","Ihr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.","","Bringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterquell."}}
D[5128] = {"Worte des Oberhäuptlings",{"Bringt das kunstlos geschriebene Logbuch zu Kelek Himmelshüter im südlichen Teil des Teufelswalds."}}
D[5141] = {"Drachenlederverarbeitung",{"Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.","","Ihr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5142] = {"Klein-Pamela",{"Sucht Pamela Rotpfad."}}
D[5143] = {"Stammeslederverarbeitung",{"Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Jägermond in Feralas.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5144] = {"Elementarlederverarbeitung",{"Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Gerber in die sengende Schlucht.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5145] = {"Drachenlederverarbeitung",{"Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Drachenaug im Ödland.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.","","Ihr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5146] = {"Elementarlederverarbeitung",{"Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhuf in den Arathibergen.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5147] = {"GESUCHT: Arnak Grimmtotem",{"Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Langhorn im Freiwindposten."}}
D[5148] = {"Stammeslederverarbeitung",{"Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5149] = {"Pamelas Puppe",{"Sucht Pamelas Puppe."}}
D[5150] = {"Dadanga ist hungrig!",{"Dadanga sieht zu Euch auf, während Ihr auf sie zu geht. Sie scheint auf etwas zu hoffen...","","Sie hat wahrscheinlich Hunger!","","Im Krater muss irgendetwas wachsen, was die perfekte Leckerei für einen riesigen Pflanzenfresser ist. Dadanga ist ein großes Mädchen; was immer Ihr ihr bringt... es muss viel davon sein!"}}
D[5151] = {"Hyperkondensator-Dingsda",{"Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Lagerputzer zurück."}}
D[5152] = {"Tante Marlene",{"Sprecht mit Marlene, südlich der Ruinen von Andorhal."}}
D[5153] = {"Ein seltsamer Historiker",{"Bringt Josephs Ehering zu Chromie."}}
D[5154] = {"Die Annalen von Darroheim",{"Bringt die 'Annalen von Darroheim' zu Chromie in Andorhal."}}
D[5155] = {"Streitmacht von Jaedenar",{"Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mooshuf im Teufelswald zurückkehrt."}}
D[5156] = {"Die Verderbnis überprüfen",{"Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr den Narbengrund erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Wasser gefüllt sind, kehrt zu Taronn Rotfeder im Teufelswald zurück."}}
D[5157] = {"Verderbtes Wasser sammeln",{"Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mooshuf im Teufelswald zurückkehrt."}}
D[5158] = {"Spirituelle Hilfe suchen",{"Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Wasserdeuter."}}
D[5159] = {"Gesäubertes Wasser wird zum Teufelswald gebracht",{"Bringt das geläuterte Mondbrunnenwasser zu Greta Mooshuf im Teufelswald."}}
D[5160] = {"Die oberste Beschützerin",{"Begebt Euch nach Winterquell und sucht Haleh. Gebt ihr Awbees Schuppe."}}
D[5161] = {"Der Zorn des blauen Drachenschwarms",{"Sprecht mit Haleh, wenn Ihr weitermachen wollt."}}
D[5162] = {"Der Zorn des blauen Drachenschwarms",{"Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal."}}
D[5163] = {"Sind wir endlich da, Yeti?",{"Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:","","Legacki in der Ewigen Warte (Winterquell)nSprinkel in Gadgetzan (Tanaris)nQuixxil in Marschalls Zuflucht (Krater von Un'Goro)","","Wenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück."}}
D[5164] = {"Verzeichnis der Abtrünnigen",{"Lest das 'Verzeichnis der Abtrünnigen'."}}
D[5165] = {"Übergießen der Flammen des Schutzes",{"Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser und kehrt danach zu Greta Mooshuf im Smaragdrefugium zurück."}}
D[5166] = {"Brustplatte des chromatischen Drachenschwarms",{"Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:","","1 chromatischen Knochenpanzer.","","10 glänzende chromatische Schuppen.","","10 Einheiten Blut von Helden.","","10 ausgefranste Monstrositätenstickereien."}}
D[5167] = {"Beinplatten des chromatischen Widersetzers",{"Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:","","1 chromatischer Knochenpanzer.","","10 glänzende chromatische Schuppen.","","10 Einheiten Blut von Helden.","","5 Häute des Schattens."}}
D[5168] = {"Helden von Darroheim",{"Bringt Davils Buchband und Rotpfads Schild zu Carlin Rotpfad."}}
D[5181] = {"Bösewichte von Darroheim",{"Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Rotpfad in der Kapelle des hoffnungsvollen Lichts."}}
D[5201] = {"Eindringlinge der Winterfelle",{"Rivern Frostwind möchte, dass Ihr 5 Schamanen der Winterfelle und 5 Ursa der Winterfelle erschlagt."}}
D[5202] = {"Ein merkwürdiger roter Schlüssel",{"Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird."}}
D[5203] = {"Rettung aus Jaedenar",{"Bringt Arko'narin dorthin, wo Lichtschmied und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Mondsichel im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist."}}
D[5204] = {"Vergeltung des Lichts",{"Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lichtschmied sucht."}}
D[5206] = {"Marodeure von Darroheim",{"Bringt 5 widerhallende Schädel und den Mystikerkristall zu Carlin Rotpfad in den östlichen Pestländern."}}
D[5210] = {"Bruder Carlin",{"Bringt die erweiterten 'Annalen von Darroheim' zu Carlin Rotpfad in den östlichen Pestländern."}}
D[5211] = {"Verteidiger von Darroheim",{"Befreit 15 Geister von Darroheim und kehrt dann zu Carlin Rotpfad zurück."}}
D[5212] = {"Das Fleisch lügt nicht",{"Sammelt 10 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Moppelzink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt."}}
D[5213] = {"Der aktive Wirkstoff",{"Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Moppelzink zurück."}}
D[5214] = {"Der große Fras Siabi",{"Sucht Fras Siabis Raucherladen in Stratholme und bergt einen Kasten von Siabis Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist."}}
D[5215] = {"Die Geißelkessel",{"Sprecht mit der Hohepriesterin MacDonnell an der Zugwindspitze, westliche Pestländer."}}
D[5216] = {"Ziel: Teufelssteinfeld",{"Geht zum Teufelssteinfeld in den westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}}
D[5217] = {"Rückkehr zum Zugwindlager",{"Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell am Zugwindlager, westliche Pestländer."}}
D[5218] = {"Der Kessel des Teufelssteinfelds",{"Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.","","Da Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen."}}
D[5219] = {"Ziel: Dalsons Tränenfeld",{"Begebt Euch zu Dalsons Tränenfeld in den westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}}
D[5220] = {"Rückkehr zum Zugwindlager",{"Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell am Zugwindlager, westliche Pestländer."}}
D[5221] = {"Der Kessel von Dalsons Tränenfeld",{"Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.","","Da Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen."}}
D[5222] = {"Ziel: Das trostlose Feld",{"Begebt Euch zum trostlosen Feld in den westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}}
D[5223] = {"Rückkehr zum Zugwindlager",{"Bringt die gefüllte Flasche: Das trostlose Feld zur Hohepriesterin MacDonnell am Zugwindlager, westliche Pestländer."}}
D[5224] = {"Der Kessel des trostlosen Felds",{"Der Seuchenkessel der Geißel steht vor Euch und speit große Mengen Toxin in die Luft. Eine kleine, unauffällige Zugangsklappe befindet sich in der großen Plattform des Kessels.","","Da Ihr den Kessellord bereits besiegt und seinen Schlüssel an Euch genommen habt, könnt Ihr die geeigneten Reagenzien in den Kessel geben, um ein Gegenmittel gegen die Seuche zu schaffen."}}
