D[5633] = {"Heimkehr",{"Sprecht mit der Priesterin Alathea in Darnassus."}}
D[5634] = {"Verzweifeltes Gebet",{"Ihr habt dem Licht einen großen Dienst erwiesen, indem Ihr ein leuchtendes Beispiel für diejenigen wurdet, die durch dieses gefährliche Land und in die Ferne reisen. Bitte, nehmt diese Lektion als Dank für all das an, was Ihr getan habt."}}
D[5635] = {"Verzweifeltes Gebet",{"Sprecht mit der Hohepriesterin Laurena in Sturmwind."}}
D[5636] = {"Verzweifeltes Gebet",{"Sprecht mit der Hohepriesterin Laurena in Sturmwind."}}
D[5637] = {"Verzweifeltes Gebet",{"Sprecht mit der Hohepriesterin Laurena in Sturmwind."}}
