D[5639] = {"Verzweifeltes Gebet",{"Sprecht mit der Hohepriesterin Laurena in Sturmwind."}}
D[5641] = {"Furchtlos",{"Aus Euch könnte ein großartiger <Klasse> werden, <Name>. Leistet weiter so gute Arbeit!","","Ihr habt bereits bewiesen, dass Ihr bereit für die Schlacht seid. Vielleicht ist es an der Zeit, Euch ein wenig mehr beizubringen."}}
D[5642] = {"Schattenwache",{"Sprecht mit Ur'kyo in Orgrimmar."}}
D[5643] = {"Schattenwache",{"Sprecht mit Ur'kyo in Orgrimmar."}}
D[5644] = {"Verschlingende Seuche",{"Sprecht mit Aelthalyste in Unterstadt."}}
D[5645] = {"Furchtlos",{"Sprecht mit Hohepriester Rohan in Eisenschmiede."}}
