D[5647] = {"Furchtlos",{"Sprecht mit Hohepriester Rohan in Eisenschmiede."}}
D[5648] = {"Gewänder der Spiritualität",{"Findet die Grunzerin Kor'ja und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück."}}
D[5649] = {"Der Spiritualität geneigt",{"Sprecht mit Tai'jin in Durotar."}}
D[5650] = {"Gewänder der Dunkelheit",{"Findet die Todeswache Kel und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryll in Brill zurück."}}
D[5651] = {"Der Dunkelheit geneigt",{"Sprecht mit dem Dunklen Kleriker Beryll in Tirisfal."}}
D[5652] = {"Verhexung der Schwäche",{"Ihr tätet gut daran, diese Lektion zu beachten. Die Verhexung der Schwäche wird Euch im Kampf von großem Nutzen sein. Später werde ich Prüfungen für Euch bereithalten, mit Hilfe derer Ihr Euch weiterentwickeln und Euren Wert für den Stamm beweisen könnt."}}
D[5654] = {"Verhexung der Schwäche",{"Sprecht mit Ur'kyo in Orgrimmar."}}
D[5655] = {"Verhexung der Schwäche",{"Sprecht mit Ur'kyo in Orgrimmar."}}
D[5656] = {"Verhexung der Schwäche",{"Sprecht mit Ur'kyo in Orgrimmar."}}
D[5657] = {"Verhexung der Schwäche",{"Sprecht mit Ur'kyo in Orgrimmar."}}
D[5658] = {"Berührung der Schwäche",{"Ah, junger <Klasse>, ich bin froh, dass Ihr hierher zurückgekehrt seid. Ich würde Euch gerne eine Lektion lehren, die Ihr besser nicht vergessen solltet. Seid Ihr bereit?"}}
D[5660] = {"Berührung der Schwäche",{"Sprecht mit Aelthalyste in Unterstadt."}}
D[5661] = {"Berührung der Schwäche",{"Sprecht mit Aelthalyste in Unterstadt."}}
D[5662] = {"Berührung der Schwäche",{"Sprecht mit Aelthalyste in Unterstadt."}}
D[5663] = {"Berührung der Schwäche",{"Sprecht mit Aelthalyste in Undercity."}}
D[5672] = {"Elunes Anmut",{"Indem Ihr Euch Elune und unserem Volk widmet, habt Ihr einen Status erreicht, den nicht alle von uns erlangen können. Es ist Tradition, dass Euch nun noch größere Fähigkeiten für Eure Hingabe gelehrt werden sollen. Nehmt Ihr an?"}}
D[5673] = {"Elunes Anmut",{"Sprecht mit der Priesterin Alathea in Darnassus."}}
D[5674] = {"Elunes Anmut",{"Sprecht mit der Priesterin Alathea in Darnassus."}}
D[5675] = {"Elunes Anmut",{"Sprecht mit der Priesterin Alathea in Darnassus."}}
D[5676] = {"Arkane Rückkopplung",{"Wir waren gezwungen, einige Magien zu lernen, um uns vor dem zu schützen, was üblicherweise unser stärkster Feind genannt wird: dem Arkanen.","","Ich würde Euch einen Zauber beibringen, um Euch und Euren Kameraden bei der Verteidigung gegen diejenigen zu helfen, die diese Macht einsetzen."}}
D[5677] = {"Arkane Rückkopplung",{"Sprecht mit der Hohepriesterin Laurena in Sturmwind."}}
D[5679] = {"Verschlingende Seuche",{"Ich würde Euch 'Verschlingende Seuche' beibringen, wenn Ihr Euch bereit dazu fühlt, <Name>. Dieser Spruch ist nicht gerade von kleiner Macht und wird Euch in den kommenden Schlachten helfen. Übt damit - es wird später Prüfungen dazu geben."}}
D[5680] = {"Schattenwache",{"Eure Riten werden bald kommen. Fürs Erste lehre ich Euch einen Zauber, der Euch von großem Nutzen sein wird, wenn Ihr mit Euren Feinden kämpft."}}
D[5713] = {"Ein Schuss, ein Treffer",{"Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten im Eschental."}}
D[5721] = {"Die Schlacht um Darroheim",{"Legt das Reliktbündel auf den Marktplatz von Darroheim.","","Verhindert Davil Lichterscheins Tod, bis Horgus stirbt.","","Verhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.","","Besiegt Rotpfad den Verderbten.","","Sprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause."}}
D[5722] = {"Die Suche nach dem verloren gegangenen Ranzen",{"Sucht im Flammenschlund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen."}}
D[5723] = {"Die Kraft des Feindes wird auf die Probe gestellt",{"Sucht in Orgrimmar nach dem Flammenschlund, tötet dann 8 Flammenschlundtroggs und 8 Schamanen der Flammenschlundtroggs und kehrt anschließend zu Rahauro in Donnerfels zurück."}}
D[5724] = {"Wiederbeschaffung des verloren gegangenen Ranzens",{"Bringt den Grimmtotemranzen zu Rahauro nach Donnerfels."}}
D[5725] = {"Die Macht der Zerstörung...",{"Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Unterstadt."}}
D[5726] = {"Verborgene Feinde",{"Bringt das Insigne eines Offiziers zu Thrall nach Orgrimmar."}}
D[5727] = {"Verborgene Feinde",{"Bringt Neeru Feuerklinge das Insigne des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Brennenden Klinge seid, und kehrt dann zu Thrall nach Orgrimmar zurück."}}
D[5728] = {"Verborgene Feinde",{"Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt."}}
D[5729] = {"Verborgene Feinde",{"Sprecht mit Neeru Feuerklinge in Orgrimmar."}}
D[5730] = {"Verborgene Feinde",{"Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt."}}
D[5741] = {"Szepter des Lichts",{"Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor."}}
D[5742] = {"Erlösung",{"Hört Euch an, was Tirion Fordring zu sagen hat."}}
D[5761] = {"Vernichtung der Bestie",{"Begebt Euch in den Flammenschlund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Feuerklinge nach Orgrimmar."}}
D[5762] = {"Hemet Nesingwary Jr.",{"Bringt Kravels Kiste zu Hemet Nesingwary Jr. ins Schlingendorntal."}}
D[5763] = {"Jagd im Schlingendorntal",{"Bringt Roons Kodohorn zu Hemet Nesingwary Jr. ins Schlingendorntal."}}
D[5781] = {"Von vergessenen Erinnerungen",{"Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}}
D[5801] = {"Feuersäulen geschmiedet",{"Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.","","Bringt den unvollendeten Skelettschlüssel dann zum Alchimisten Arbington an der Zugwindspitze in den westlichen Pestländern."}}
D[5802] = {"Feuersäulen geschmiedet",{"Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.","","Bringt den unvollendeten Skelettschlüssel zu Apotheker Zitters im Bollwerk, westliche Pestländer."}}
D[5803] = {"Arajs Skarabäus",{"Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchimisten Arbington an der Zugwindspitze in den westlichen Pestländern."}}
D[5804] = {"Arajs Skarabäus",{"Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Zitters im Bollwerk, in den westlichen Pestländern."}}
D[5805] = {"Willkommen!",{"Bringt Merissa Stillbrunn in Goldhain den Goldhaingeschenkgutschein."}}
D[5821] = {"Leibwache zu mieten",{"Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten."}}
D[5841] = {"Willkommen!",{"Bringt Yori Bruchhelm in Kharanos den Geschenkgutschein von Kharanos."}}
D[5842] = {"Willkommen!",{"Bringt Orenthil Wisperwind in Dolanaar den Geschenkgutschein von Dolanaar."}}
D[5843] = {"Willkommen!",{"Bringt Magga auf dem Klingenhügel den Geschenkgutschein des Klingenhügels."}}
D[5844] = {"Willkommen!",{"Bringt Vorn Himmelsdeuter im Dorf der Bluthufe den Geschenkgutschein der Bluthufe."}}
D[5845] = {"Von verlorener Ehre",{"Reist ins Nordtal im nordöstlichsten Gebiet der östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}}
D[5846] = {"Von Liebe und Familie",{"Begebt Euch zur Insel Darrowehr im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte."}}
D[5847] = {"Willkommen!",{"Bringt Claire Weidner in Brill den Geschenkgutschein von Brill."}}
D[5848] = {"Von Liebe und Familie",{"Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.","","Bringt das Gemälde zu Tirion Fordring."}}
D[5861] = {"Myranda suchen",{"Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk."}}
D[5862] = {"Scharlachrote Täuschung",{"Sprecht mit Myranda, um die scharlachrote Illusion zu erhalten. Begebt Euch nach Herdweiler, während Ihr unter dem Einfluss der scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk.","","Herdweiler liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten."}}
D[5863] = {"Das Truppenlager der Dünenbrecher",{"Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet."}}
D[5881] = {"Hinzurufen der Reserve",{"Maggran möchte, dass Ihr Grish Fernläufer am großen Aufzug im Brachland einen Brief zustellt."}}
D[5882] = {"Salbe durch Jagd",{"Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.","","Im Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[5883] = {"Salbe durch Bergbau",{"Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.","","Wenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[5884] = {"Salbe durch Sammlung",{"Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.","","Wenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben."}}
D[5885] = {"Salbe durch Kürschnerei",{"Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.","","Sobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe."}}
D[5886] = {"Salbe durch Entzauberung",{"Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.","","Ich brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen."}}
D[5887] = {"Salbe durch Jagd",{"Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.","","Im Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[5888] = {"Salbe durch Bergbau",{"Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.","","Wenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe."}}
D[5889] = {"Salbe durch Sammlung",{"Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.","","Wenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben."}}
D[5890] = {"Salbe durch Kürschnerei",{"Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.","","Sobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe."}}
D[5891] = {"Salbe durch Entzauberung",{"Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.","","Ich brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen."}}
D[5892] = {"Vorräte der Eisenschachtmine",{"Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Allianz in Dun Baldar."}}
D[5893] = {"Vorräte der Eisbeißermine",{"Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf."}}
D[5901] = {"Eine Plage komme über Euch",{"Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück."}}
D[5902] = {"Eine Plage komme über Euch",{"Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen."}}
D[5903] = {"Eine Plage komme über Euch",{"Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Nathaniel Dumah im Zugwindlager in den westlichen Pestländern zurück."}}
D[5904] = {"Eine Plage komme über Euch",{"Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen."}}
D[5921] = {"Mondlichtung",{"Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen."}}
D[5922] = {"Mondlichtung",{"Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen."}}
D[5923] = {"Dem Ruf folgen",{"Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus."}}
D[5924] = {"Dem Ruf folgen",{"Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus."}}
D[5925] = {"Dem Ruf folgen",{"Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus."}}
D[5926] = {"Dem Ruf folgen",{"Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels."}}
D[5927] = {"Dem Ruf folgen",{"Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels."}}
D[5928] = {"Dem Ruf folgen",{"Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels."}}
D[5929] = {"Großer Bärengeist",{"Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück."}}
D[5930] = {"Großer Bärengeist",{"Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück."}}
D[5931] = {"Zurück nach Darnassus",{"Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius."}}
D[5932] = {"Zurück nach Donnerfels",{"Kehrt nach Donnerfels zurück und sprecht mit Turak Runentotem auf der Anhöhe der Ältesten."}}
D[5941] = {"Rückkehr zu Chromie",{"Bringt das Reliktbündel zu Chromie nach Andorhal."}}
D[5942] = {"Versteckte Schätze",{"Bringt Josephs Schlüssel zu Josephs Truhe."}}
D[5943] = {"Gizeltons Karawane",{"Geleitet Gizeltons Karawane am Zirkel der Mannoroc vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten."}}
D[5944] = {"In den Träumen",{"Geleitet Taelan Fordring aus Herdweiler hinaus."}}
D[5961] = {"Der Champion der Bansheekönigin",{"Sprecht mit Nathanos Pestrufer in den östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte."}}
D[5981] = {"Tobende Riesen",{"Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt."}}
D[6001] = {"Körper und Herz",{"Benutzt den Mondstaub des Cenarius mit dem Mondkinstein von Auberdine, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Mathrengyl Bärenfährte in Darnassus, wenn Ihr fertig seid."}}
D[6002] = {"Körper und Herz",{"Benutzt den Lunarstaub des Cenarius mit dem Mondkinstein zwischen Mulgore und dem Brachland, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Turak Runentotem in Donnerfels, wenn Ihr fertig seid."}}
D[6004] = {"Offene Rechnungen",{"Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magier und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Grubenschatten in den westlichen Pestländern zurückkehrt."}}
D[6021] = {"Zaeldarr der Ausgestoßene",{"Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts."}}
D[6022] = {"Töten zu einem bestimmten Zweck",{"Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis."}}
D[6023] = {"Offene Rechnungen",{"Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Grubenschatten in den westlichen Pestländern zurückkehrt."}}
D[6024] = {"Hameyas Bitte",{"Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe."}}
D[6025] = {"Offene Rechnungen",{"Geht nach Herdweiler, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Grubenschatten in den westlichen Pestländern zurück."}}
D[6026] = {"Das ist viel verlangt",{"Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.","","Für diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden."}}
D[6027] = {"Buch der Uralten",{"Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück."}}
D[6028] = {"Der Bericht der Ewigen Warte",{"Bringt den Bericht der Ewigen Warte zu Argentumoffizier Reinherz im Zugwindlager in den westlichen Pestländern."}}
D[6029] = {"Der Bericht der Ewigen Warte",{"Bringt den Bericht der Ewigen Warte zu Argentumoffizier Garush im Bollwerk in den westlichen Pestländern."}}
D[6030] = {"Fürst Nicholas Zverenhoff",{"Bringt das Buch 'Studien über das Geistsprechen' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[6031] = {"Runenstoff",{"Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste."}}
D[6032] = {"Hochheiliger Stoff",{"Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste."}}
D[6041] = {"When Smokey Sings, I Get Violent",{"Reist in den Pestwald, nordwestlich der Hoffnung des Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.","","Wenn ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.","","Übrigens, Smokeys spezielles Präparat ist recht...instabil."}}
D[6042] = {"Die kleinen Ärgernisse des Un-Lebens",{"Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr fertig seid."}}
D[6061] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe."}}
D[6062] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel."}}
D[6063] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar."}}
D[6064] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos."}}
D[6065] = {"Der Weg des Jägers",{"Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe."}}
D[6066] = {"Der Weg des Jägers",{"Sprecht mit Yaw Sharpmane in Bloodhoof."}}
D[6067] = {"Der Weg des Jägers",{"Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe."}}
D[6068] = {"Der Weg des Jägers",{"Sprecht mit Thotar in Klingenhügel."}}
D[6069] = {"Der Weg des Jägers",{"Sprecht mit Thotar in Klingenhügel."}}
D[6070] = {"Der Weg des Jägers",{"Sprecht mit Thotar in Klingenhügel."}}
D[6071] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar."}}
D[6072] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar."}}
D[6073] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar."}}
D[6074] = {"Der Weg des Jägers",{"Sprecht mit Grif Wildherz in Kharanos."}}
D[6075] = {"Der Weg des Jägers",{"Sprecht mit Grif Wildherz in Kharanos."}}
D[6076] = {"Der Weg des Jägers",{"Sprecht mit Grif Wildherz in Kharanos."}}
D[6081] = {"Die Ausbildung des Tiers",{"Sprecht mit Ormak Grimmschlag in Orgrimmar."}}
D[6082] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück."}}
D[6083] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel."}}
D[6084] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildherz in Kharanos zurück."}}
D[6085] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos."}}
D[6086] = {"Die Ausbildung des Tiers",{"Sprecht mit Belia Donnerstein in Eisenschmiede."}}
D[6087] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe."}}
D[6088] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe."}}
D[6089] = {"Die Ausbildung des Tiers",{"Sprecht mit Holt Donnerhorn auf der Anhöhe der Jäger in Donnerfels."}}
D[6101] = {"Die Zähmung der Bestie",{"Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar."}}
D[6102] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar."}}
D[6103] = {"Die Ausbildung des Tiers",{"Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus."}}
D[6121] = {"Neue Lektionen",{"Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen."}}
D[6122] = {"Die eigentliche Ursache",{"Benutzt das leere Gefäß bei den Klippenquellfällen und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.","","Bringt die gefüllte Probe der Klippenquellfälle zu Alanndarian Nachtweise nach Auberdine in Dunkelküste."}}
D[6123] = {"Das Heilmittel sammeln",{"Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nachtweise in Auberdine, damit sie eine Heilsalbe machen kann."}}
D[6124] = {"Heilung der Kranken",{"Benutzt die heilende Tiersalbe bei 10 kränklichen Rehen in ganz Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass kränkliche Rehe südlich des Klippenquells, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo das Eschental beginnt, aufgetaucht ist."}}
D[6125] = {"Macht über Gift",{"Kehrt zu Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus zurück."}}
D[6126] = {"Neue Lektionen",{"Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen."}}
D[6127] = {"Die eigentliche Ursache",{"Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.","","Bringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runentotem beim Wegekreuz im Brachland."}}
D[6128] = {"Das Heilmittel sammeln",{"Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runentotem beim Wegekreuz, damit er eine Heilsalbe machen kann."}}
D[6129] = {"Heilung der Kranken",{"Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße beim Wegekreuz gesehen."}}
D[6130] = {"Macht über Gift",{"Kehrt zu Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels zurück."}}
D[6131] = {"Verbündeter der Holzschlundfeste",{"Grazle möchte, dass Ihr Euch beweist, indem Ihr 5 Krieger der Totenwaldfelle, 5 Pfadfinder der Totenwaldfelle und 5 Gärtner der Totenwaldfelle besiegt."}}
D[6132] = {"Holt mich hier raus!",{"Eskortiert Melizza Brummsumms und sprecht anschließend mit Hornizz Brummsumms beim Kodofriedhdof Desolace."}}
D[6133] = {"Das Ersuchen des Waldläuferlords",{"Begebt Euch zur nördlichsten Grenze der östlichen Pestländer und bringt die Registratur von Quel'Thalas zurück. Der Gegenstand befindet sich irgendwo in der Jagdhütte von Quel'Lithien.","","Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten."}}
D[6134] = {"Geisterplasmasuche",{"Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brummsumms in Desolace."}}
D[6135] = {"Dämmerschwinge, oh, wie ich Euch hasse...",{"Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Pestrufer.","","Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift."}}
D[6136] = {"Der Korpulente",{"Sucht in den nördlichen Wüsten der östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Pestrufer zurück, sobald Ihr diese Mission erledigt habt."}}
D[6141] = {"Bruder Anton",{"Sprecht mit Bruder Anton in Desolace."}}
D[6142] = {"Muschelköder",{"Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Schattenflucht."}}
D[6143] = {"Andere Fische zu grillen",{"Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberhexerinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Schattenflucht."}}
D[6144] = {"Der Befehl",{"Reist in die Unterstadt und sprecht mit Varimathras."}}
D[6145] = {"Der Purpurrote Kurier",{"Kehrt in die östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des obersten Kreuzzüglers.","","Bringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen."}}
D[6146] = {"Nathanos' List",{"Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des obersten Kreuzzüglers."}}
D[6147] = {"Kehrt zu Nathanos zurück.",{"Kehrt mit der neuen Information zu Nathanos Pestrufer zurück."}}
D[6148] = {"Das scharlachrote Orakel Demetria",{"Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr erfolgreich wart."}}
D[6161] = {"Nehmt Rackmores Schatz!",{"Sucht Rackmores Silberschlüssel. Sucht Rackmores goldenen Schlüssel. Sucht und öffnet Rackmores Truhe."}}
D[6162] = {"Eines Ehemanns letzter Kampf",{"Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald."}}
D[6163] = {"Ramstein",{"Reist nach Stratholme und tötet Ramstein den Verschlinger. Bringt seinen Kopf als Souvenir zu Nathanos."}}
D[6164] = {"Augustus' Quittungsbuch",{"Bringt Augustus' Quittungsbuch zu Augustus dem Meschuggenen im Schreckenstal."}}
D[6181] = {"Eine eilige Nachricht",{"Bringt Lewis' Notiz zu Thor dem Greifenmeister."}}
D[6182] = {"Der Erste und Letzte",{"Sprecht mit Meister Mathias Shaw in der Altstadt von Sturmwind. Er wohnt in der Kaserne."}}
D[6183] = {"Ehret die Toten",{"Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt."}}
D[6184] = {"Flint Schattenmoor",{"Reist zum Zugwindlager in den westlichen Pestländern und trefft Euren Kontaktmann Flint Schattenmoor."}}
D[6185] = {"Die östlichen Pestländer",{"Sucht in den östlichen Pestländern nach Hinweisen auf den 'Pestrufer' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Schattenmoor am Zugwindlager."}}
D[6186] = {"Der Pestrufer kommt",{"Kehrt nach Sturmwind zurück und informiert Hochlord Bolvar Fordragon über das Schicksal von Nathanos Marris."}}
D[6187] = {"Ordnung muss wieder hergestellt werden",{"Stellt eine Armee auf und reist zu den östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Pestrufer und jeden Abschaum der Horde, der ihn beschützen mag.","","Bewahrt einen klaren Kopf, <Name>. Die Horde wird den Waldläuferlord mit dem Leben verteidigen."}}
D[6221] = {"Totenwaldfelle des Nordens",{"Nafien möchte, dass Ihr 5 Höhlenbehüter der Totenwaldfelle, 5 Rächer der Totenwaldfelle und 5 Schamanen der Totenwaldfelle besiegt."}}
D[6241] = {"Aktivität der Winterfelle",{"Salfa möchte, dass Ihr 6 Totemiker der Winterfelle, 6 Höhlenbehüter der Winterfelle und 6 Pfadfinder der Winterfelle erledigt."}}
D[6261] = {"Dungar Trinkfest",{"Bringt Osrics Kiste zu Dungar Trinkfest dem Greifenmeister."}}
D[6281] = {"Weiter nach Sturmwind",{"Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in Sturmwind."}}
D[6282] = {"Harpyien drohen",{"Maggran Erdbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt."}}
D[6283] = {"Blutfuriengeschlecht",{"Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt."}}
D[6284] = {"Arachnophobie",{"Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels."}}
D[6285] = {"Zurück zu Lewis",{"Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Lewis an der Späherkuppe."}}
D[6301] = {"Zyklus der Wiedergeburt",{"Tammra Windfeld in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt."}}
D[6321] = {"Nachschub für das Grabmal",{"Bringt Podrigs Anforderungsliste zu Karos Razok."}}
D[6322] = {"Michael Garrett",{"Bringt Gordons Kiste zu Michael Garrett."}}
D[6323] = {"Flug nach Unterstadt",{"Bucht einen Fledermausritt zur Unterstadt bei Fledermausmeister Karos Razok und bringt dann Podrigs Anforderungsliste zu Gordon Wendheim in Unterstadt."}}
D[6324] = {"Rückkehr zu Podrig",{"Bucht einen Fledermausritt zum Grabmal bei Fledermausmeister Michael Garrett und bringt dann Gordons Kiste zu Todeswache Podrig beim Grabmal."}}
D[6341] = {"Die Arten von Teldrassil",{"Bringt Nessas Sammlung zu Vesprystus."}}
D[6342] = {"Flug nach Auberdine",{"Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird."}}
D[6343] = {"Rückkehr zu Nessa",{"Bringt Lairds Antwort zu Nessa Schattensang."}}
D[6344] = {"Nessa Schattensang",{"Sprecht mit Nessa Schattensang."}}
D[6361] = {"Ein Bündel Bälge",{"Bringt das Bündel Bälge zu Windreitermeister Devrak beim Wegekreuz."}}
D[6362] = {"Flug nach Donnerfels",{"Bucht einen Windreiter nach Donnerfels bei Windreitermeister Devrak und bringt dann das Bündel Bälge zu Ahanu in Donnerfels."}}
D[6363] = {"Tal der Windreitermeister",{"Bringt Ahanus Lederwaren zu Tal in Donnerfels."}}
D[6364] = {"Rückkehr zu Jahan",{"Bucht einen Windreiter zum Wegekreuz bei Windreitermeister Tal und bringt dann Ahanus Lederwaren zu Jahan Falkenschwinge."}}
D[6365] = {"Fleisch für Orgrimmar",{"Bringt Zarghs Fleischwaren zu Devrak beim Wegekreuz."}}
D[6381] = {"Neues Leben",{"Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und bringt Tammra in Sonnenfels dann die restlichen verzauberten Gaeasamenkörner zurück."}}
D[6382] = {"Die Jagd im Eschental",{"Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental."}}
D[6383] = {"Die Jagd im Eschental",{"Es gibt drei legendäre Kreaturen, die die Jagd in Ashenvale bilden. Ihr könnt sie suchen und Euch mit ihrer List und Kraft messen. Dabei werdet Ihr hoffentlich auch etwas über Euch selbst lernen. Die Kreaturen sind: der Bär Ursangus, die Nachtsäblerkatze Schattumbra und der Hippogryph Scharfkralle.","","Die Kreaturen der Jagd in Ashenvale sind mächtig; möglicherweise benötigt Ihr Unterstützung, um sie zu bezwingen. Wenn Ihr sie besiegt habt, dann bringt mir Beweise Eurer Tat."}}
D[6384] = {"Flug nach Orgrimmar",{"Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Devrak und bringt dann Zarghs Fleischwaren zu Gryshka in Orgrimmar."}}
D[6385] = {"Doras der Windreitermeister",{"Bringt Gryshkas Brief zu Doras in Orgrimmar."}}
D[6386] = {"Kehrt zum Wegekreuz zurück",{"Bucht einen Windreiter zum Wegekreuz bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Zargh beim Wegekreuz."}}
D[6387] = {"Ehrenstudenten",{"Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar."}}
D[6388] = {"Gryth Thurden",{"Bringt die Ehrenhacken zu Gryth Thurden in Eisenschmiede."}}
D[6389] = {"Eine Plage komme über Euch",{"Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestlandtermiten zu Nathaniel Dumah im Zugwindlager in den westlichen Pestländern zurück."}}
D[6390] = {"Eine Plage komme über Euch",{"Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück."}}
D[6391] = {"Flug nach Eisenschmiede",{"Bucht einen Greifen nach Eisenschmiede von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Geröllzeh in Eisenschmiede."}}
D[6392] = {"Rückkehr zu Brock",{"Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Steinsucher in Thelsamar."}}
D[6393] = {"Krieg der Elementare",{"Bringt 10 Pyrophore zu Tsunaman in Sonnenfels."}}
D[6394] = {"Thazz'rils Hacke",{"Bringt Thazz'rils Hacke zu Großknecht Thazz'ril."}}
D[6395] = {"Marlas letzter Wunsch",{"Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück."}}
D[6401] = {"Kaya lebt",{"Teilt Tammra Windfeld, die in Sonnenfels lebt, die gute Nachricht mit."}}
D[6402] = {"Treffen in Sturmwind",{"Reist nach Sturmwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marschall Windsor über Eure Ankunft informiert."}}
D[6403] = {"Die große Maskerade",{"Folgt Reginald Windsor durch Sturmwind. Schützt ihn vor Gefahren!"}}
D[6421] = {"Steinschlagklamm",{"Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann."}}
D[6441] = {"Satyrhörner",{"Sammelt für Pixel im Splitterholzposten 16 Satyrhörner."}}
D[6442] = {"Die Naga am Zoramstrand",{"Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen."}}
D[6461] = {"Blutfresser",{"Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet."}}
D[6462] = {"Trollglücksbringer",{"Bringt Mitsuwa beim Außenposten von Zoram'gar 8 Trollglücksbringer."}}
D[6481] = {"Der Irdene erhebt sich",{"Öffnet das Resonitfässlein mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück."}}
D[6482] = {"Freiheit für Ruul",{"Begleitet Ruul und sprecht dann mit Yama Schneehuf im Splitterholzposten."}}
D[6501] = {"Das Großdrachenauge",{"Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert."}}
D[6502] = {"Drachenfeueramulett",{"Ihr müsst das Blut des schwarzen Drachenhelden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Schwarzfelsspitze."}}
D[6503] = {"Die Kundschafter des Eschentals",{"Tötet 9 Kundschafter des Eschentals und kehrt dann zu Kuray'bin im Splitterholzposten zurück."}}
D[6504] = {"Die verlorenen Seiten",{"Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen. Bringt die Seiten zu Gurda Zornnarbe in der Nähe des Splitterholzpostens zurück."}}
D[6521] = {"Eine unheilige Allianz",{"Bringt den Kopf von Botschafter Malcin zu Varimathras nach Unterstadt."}}
D[6522] = {"Eine unheilige Allianz",{"Bringt die kleine Rolle zu Varimathras nach Unterstadt."}}
D[6523] = {"Schützt Kaya",{"Begleitet Kaya Flachhuf zum Camp Aparaje und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6541] = {"Meldung bei Kadrak",{"Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak."}}
D[6542] = {"Meldung bei Kadrak",{"Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak."}}
D[6543] = {"Die Berichte des Kriegshymnenklans",{"Öffnet die gebündelten Berichte. Bringt die Berichte des Kriegshymnenklans dem Späher des Kriegshymnenklans, dem Läufer des Kriegshymnenklans und der Vorhut des Kriegshymnenklans. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands."}}
D[6544] = {"Toreks Angriff",{"Eskortiert Torek bei seinem Angriff auf den Außenposten der Silberschwingen und Duriel Mondfeuer. Erstattet dann Ertog Zornhauer im Splitterholzposten Bericht."}}
D[6545] = {"Update für Läufer des Kriegshymnenklans",{"Ihr bringt mir also meine Befehle? Es ist immer wieder schön, einen neuen Rekruten mit Temperament und starkem Willen kennen zu lernen.","","Ihr solltet besser schnell lernen, wenn Ihr hier am Leben bleiben wollt. Die Gefahr durch die Naga wächst, <Name>. Ich habe alles beobachtet und mich, seit ich hier in diesem Außenposten eintraf, gegen mehrere Angriffe verteidigen müssen.","","Wenn Ihr Euch entschließen wollt, uns bei unseren Bemühungen beizustehen, sprecht mit einem der anderen hier im Außenposten."}}
D[6546] = {"Update für Vorhut des Kriegshymnenklans",{"Auf diesem Weg lauern viele Gefahren, <Name>. Daran solltet Ihr immer denken, wenn Ihr diese Lande bereist. Die Bedrohung durch die Allianz ist nahe.","","Wir sehen uns an allen Fronten dem Feind gegenüber. Die Satyrn sind eine ernsthafte und verbreitete Macht im östlichen Ashenvale. Ich habe weiterhin herausgefunden, dass die Naga ein großes Gebiet von Azshara übernommen haben.","","Es ist schön zu sehen, dass wir unsere Reihen immer noch aufstocken können ... seid auf das gefasst, was vor Euch liegt, <Name>."}}
D[6547] = {"Update für Späher des Kriegshymnenklans",{"Haltet die Augen offen, <Volk>. Oftmals verstecken sich Elfen in den Schatten...","","Wir müssen immer wachsam sein. Wir haben sehr hart daran gearbeitet, dieses Land zu erobern, und die Elfen suchen nur nach einer Gelegenheit, es uns abzunehmen.","","Ich nehme an, Ihr habt neue Befehle von Kadrak für mich?"}}
D[6548] = {"Rächt mein Dorf",{"Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6561] = {"Schurkerei in der Tiefschwarzen Grotte",{"Bringt den Kopf von Lord des Schattenhammers Kelris zu Bashana Runentotem in Donnerfels."}}
D[6562] = {"Ärger in der Tiefe",{"Sprecht im Eschental mit Je'neu Sancrea."}}
D[6563] = {"Die Essenz von Aku'mai",{"Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea im Eschental."}}
D[6564] = {"Treue zu den Alten Göttern",{"Bringt die durchfeuchtete Notiz zu Je'neu Sancrea im Eschental."}}
D[6565] = {"Treue zu den Alten Göttern",{"Tötet Lorgus Jett in der Tiefschwarzen Grotte und kehrt dann zu Je'neu Sancrea ins Eschental zurück."}}
D[6566] = {"Was der Wind erzählt",{"Hört Thrall zu."}}
D[6567] = {"Der Champion der Horde",{"Sucht in Schattenflucht in Desolace nach Rokaro."}}
D[6568] = {"Meisterin der Illusionen",{"Überbringt Myranda der Vettel in den westlichen Pestländern Rokaros Brief."}}
D[6569] = {"Oculus-Illusionen",{"Reist zur Schwarzfelsspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[6570] = {"Aschenschwinge",{"Reist zum Drachensumpf in den Düstermarschen und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge."}}
D[6571] = {"Nachschub des Kriegshymnenklans",{"Tragt den Nachschub des Kriegshymnenklans zusammen: Sägeblätter des Kriegshymnenklans, ein Holzfällerseil, Öl des Kriegshymnenklans und die Axtlieferung des Kriegshymnenklans für Locke Okarr im Splitterholzposten."}}
D[6581] = {"Sägeblätter des Kriegshymnenklans",{"Direkt aus Ratchet, die Warsongsägeblätter! Jau, die hab ich hier...","","Aber womit wollt Ihr das bezahlen? Ihr könnt sie nicht einfach so mitnehmen, wisst Ihr! Meine Zeit ist kostbar!","","Was ich wirklich brauche, ist eine gute Schusswaffe, die ich auf meine Reisen mitnehmen kann. Ein Mädchen muss sich doch schließlich verteidigen können, wisst Ihr? Es gibt da eine Schusswaffe, die mir wirklich gefällt, und ich bin mir sicher, dass ein Ingenieur kein Problem hätte, so eine anzufertigen.","","Wenn Ihr mir also eine dieser tödlichen Donnerbüchsen bringen würdet, gebe ich Euch die Sägeblattlieferung. Abgemacht?"}}
D[6582] = {"Die Prüfung der Schädel, Seher",{"Ihr müsst Seher, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.","","Ihr wisst, dass Seher in Winterquell zu finden ist."}}
D[6583] = {"Die Prüfung der Schädel, Somnus",{"Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück."}}
D[6584] = {"Die Prüfung der Schädel, Chronalis",{"Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge."}}
D[6585] = {"Die Prüfung der Schädel, Axtroz",{"Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück."}}
D[6601] = {"Aufstieg...",{"Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Schwarzfelsspitze nicht funktioniert. Vielleicht solltet Ihr Rokaro aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist."}}
D[6602] = {"Blut des schwarzen Großdrachenhelden",{"Begebt Euch zur Schwarzfelsspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rokaro."}}
D[6603] = {"Probleme in Winterquell",{"Findet Donova Schneeweh bei den Thermalquellen in Winterquell."}}
D[6604] = {"Wütende Wildekin",{"Sprecht mit Jaron Steinschleifer in Sternfall."}}
D[6605] = {"Eine seltsame Person",{"Sprecht im Teufelswald mit Winna Hazzard."}}
D[6606] = {"Ein bisschen Glück",{"Sprecht in der Ewigen Warte mit Hexendoktorin Mau'ari."}}
D[6607] = {"Nat Pagle, Extremangler",{"Nat Pagle möchte, dass Ihr folgende Fische fangt:","","Nebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends.","","Einen Sar'therisbarsch vom Sar'therisstrand in Desolace.","","Feralas-Ahi aus dem Verdantis in Feralas.","","Blauwimpel von der ungezähmten Küste im Schlingendorntal.","","Kehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!"}}
D[6608] = {"Ihr zu gut",{"Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht."}}
D[6609] = {"Ich hab nix mehr!",{"Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!"}}
D[6610] = {"Muschelette Surprise",{"Dirge Schnetzelhack möchte, dass Ihr folgende Dinge besorgt:","","12 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten.","","10 Stück scharfes Muschelfleisch. Die findet Ihr natürlich in Muscheln!","","20 Stück Alteraclochkäse. Begebt Euch zu einer Käserei!","","Sammelt all diese Gegenstände und kehrt dann zu Dirge zurück."}}
D[6611] = {"Ab mit Euch nach Gadgetzan!",{"Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere."}}
D[6612] = {"Ich kenne einen Typen...",{"Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere."}}
D[6621] = {"König der Fäulnisklauen",{"Platziert Karangs Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Karang Amakkar in Zoram'gar."}}
D[6622] = {"Triage",{"Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.","","Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt."}}
D[6623] = {"Traumachirurg der Horde",{"Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt."}}
D[6624] = {"Triage",{"Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.","","Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt."}}
D[6625] = {"Traumachirurg der Allianz",{"Reist nach Theramore in die Düstermarschen und sprecht mit Doktor Gustaf van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt."}}
D[6626] = {"Ein Hort des Bösen",{"Tötet 8 Schlachtwachen der Klingenhauer, 8 Dornenwirker der Klingenhauer und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Mondsang nahe dem Eingang zu den Hügeln der Klingenhauer zurück."}}
D[6627] = {"Test der Lehre",{"Beantwortet Braug Dämmergeists Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid."}}
D[6628] = {"Test der Lehre",{"Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Unterstadt sein, wenn Ihr bereit seid."}}
D[6629] = {"Tötet Grundig Finsterwolke",{"Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6641] = {"Vorsha die Peitscherin",{"Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft.","","Wenn Ihr erfolgreich gewesen seid, kehrt zum Außenposten von Zoram'gar zurück und informiert den Läufer des Kriegshymnenklans über den Tod von Vorsha der Peitscherin."}}
D[6642] = {"Gunst der Bruderschaft, Dunkeleisenerz",{"Dunkeleisen, das in der Tiefe zwar reichlich vorkommt, ist innerhalb der Bruderschaft dennoch ein hoch geschätztes Gut. Für die hochheiligen Waffen und Ausrüstungen von Ragnaros wird bevorzugt Dunkeleisen verwendet.","","Für 10 Stück Dunkeleisenerz, die Ihr anbietet, steigt Ihr in der Gunst der Bruderschaft."}}
D[6643] = {"Gunst der Bruderschaft, Feuerkern",{"Wehe denen, die im geschmolzenen Kern das Schicksal herausfordern. Der Tod kommt schnell - die Strafe erfolgt ohne Gnade.","","Viele Anhänger der Bruderschaft sind auf der Suche nach Feuerkernen gefallen.","","Bietet einen Feuerkern an, dann steigt Ihr in der Gunst der Bruderschaft."}}
D[6644] = {"Gunst der Bruderschaft, Lavakern",{"Die Thoriumbruderschaft versteht Eure Notlage, <Volk>. Deshalb haben wir Lokthos zu einem Handel ermächtigt.","","Bietet 4 Lavakerne an, dann steigt Ihr in der Gunst der Bruderschaft."}}
D[6645] = {"Gunst der Bruderschaft, Kernleder",{"Für viele der hochheiligen Rezepte ist die Haut von Ragnaros' Lieblingstieren erforderlich.","","Bietet 4 Kernhäute an, die Ihr den glimmenden Kadavern der Kernhunde des geschmolzenen Kerns abgezogen habt, dann steigt Ihr in der Gunst der Bruderschaft."}}
D[6646] = {"Gunst der Bruderschaft, Blut des Berges",{"Die Tränen des Feuerlords sind wahrlich ein seltener Fund.","","Bietet 1 Blut des Berges an, dann steigt Ihr in der Gunst der Bruderschaft."}}
D[6661] = {"Tiefenbahn-Ratten-Razzia",{"Fangt mit Hilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty. Und vergesst nicht, die Flöte zurückzugeben, wenn Ihr fertig seid."}}
D[6662] = {"Mein Bruder Nipsy...",{"Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Sturmwind."}}
D[6681] = {"Das Anwesen, Rabenholdt",{"Bringt das Siegel von Rabenholdt zu Fahrad im Rabenholdtanwesen, das versteckt in den Hügeln des Hügellands liegt.","","Unterwegs wird man Eure Schlauheit testen. Seid darauf gefasst."}}
D[6701] = {"Syndikatsembleme",{"Wir liegen schon seit Jahren mit dem Syndikat im Clinch. Was denen an Fertigkeit mangelt, machen sie durch ihre große Zahl wett. Es ist unmöglich, sie schnell genug zu töten, um auch nur den geringsten Rückgang ihrer Population feststellen zu können!","","Wir haben herausgefunden, dass die beste Möglichkeit, ihrer großen Zahl Herr zu werden, darin besteht, ihnen die Embleme zu stehlen. Hat man einem das Emblem gestohlen, 'kümmern' sie sich intern um das mit Schande bedeckte Mitglied.","","Raubt Ihnen die Taschen aus und bringt die Embleme mir oder einer der anderen Wachen.","","Beginnt in Durnholde südlich von hier."}}
D[6721] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar."}}
D[6722] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar."}}
D[6741] = {"Mehr Beute!",{"Wenn Ihr gegen den Feind kämpft, sammelt die Stücke seiner Rüstung und bringt sie mir. Ich werde diese Stücke nutzen, um Rüstungen für unsere eigenen Truppen herzustellen!"}}
D[6761] = {"Die neue Grenze",{"Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius von Darnassus."}}
D[6762] = {"Rabine Saturna",{"Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung. Die Mondlichtung liegt zwischen dem Teufelswald und Winterquell, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt."}}
D[6781] = {"Mehr Rüstungsfetzen",{"Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Ironforge bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.","","Wenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann helft den Kriegsbemühungen und bringt mir diese Stücke!"}}
D[6801] = {"Lokholar der Eislord",{"Ich komme aus Thunder Bluff, <Volk>. Cairne selbst hat dafür gesorgt, dass ich den Frostwolfklan in diesen schrecklichen Zeiten unterstütze.","","Doch lasst uns nicht noch mehr Zeit verschwenden. Ihr müsst unsere Feinde niederstrecken und mir ihr Blut bringen. Wenn Ihr ausreichend Blut gesammelt habt, dann kann das Ritual der Beschwörung beginnen.","","Der Sieg ist uns sicher, wenn der Lord der Elementare auf die Stormpike-Armee losgelassen wird."}}
D[6804] = {"Vergiftetes Wasser",{"Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara."}}
D[6805] = {"Stürmer und Rumpler",{"Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück."}}
D[6821] = {"Auge des Glutsehers",{"Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara."}}
D[6822] = {"Der geschmolzene Kern",{"Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück."}}
D[6823] = {"Agent von Hydraxis",{"Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara."}}
D[6824] = {"Hände des Feindes",{"Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara."}}
D[6825] = {"Ruf der Lüfte - Guses Luftflotte",{"Wir müssen die neue Flotte von Kriegsreitern vorbereiten, <Volk>! Meine Reiter sind bereit, einen Schlag auf dem zentralen Schlachtfeld zu landen, aber zuerst muss ich ihnen den Mund wässrig machen - sie auf den Angriff vorbereiten.","","Ich benötige ausreichend Soldatenfleisch der Allianz, um eine Flotte zu ernähren! Hunderte Pfund! Ihr könnt das doch sicherlich übernehmen, nicht wahr? Geht schon!"}}
D[6826] = {"Ruf der Lüfte - Jeztors Luftflotte",{"Ihr habt hart gearbeitet, <Name>, aber wir haben gerade erst begonnen!","","Meine Kriegsreiter müssen das Fleisch ihrer Ziele schmecken. Damit wird ein chirurgischer Schlag gegen unsere Feinde sichergestellt!","","Meine Flotte ist die zweitmächtigste in unserem Luftkommando. Daher wird sie beim mächtigsten unserer Gegner zuschlagen. Und dafür benötigt sie das Fleisch der Lieutenants der Allianz.","","Sputet Euch!"}}
D[6827] = {"Ruf der Lüfte - Mulvericks Luftflotte",{"Ich war tagelang in einem Höllenloch der Zwerge eingesperrt. Und das schreit geradezu nach Rache!","","Wir müssen alles sorgfältig planen.","","Zuerst benötigen meine Kriegsreiter Ziele, auf die sie sich konzentrieren können - Ziele von hoher Priorität. Ich muss das Fleisch der Kommandanten der Allianz an sie verfüttern. Leider haben sich diese kleinen Mistkerle tief hinter den feindlichen Linien verschanzt! Diese Arbeit ist wahrlich wie geschaffen für Euch."}}
D[6843] = {"Da Foo"}
D[6844] = {"Umber, Archivar",{"Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nachthafen auf der Mondlichtung."}}
D[6845] = {"Enthüllung von Geheimnissen der Vergangenheit",{"Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung."}}
D[6846] = {"Der Angriff soll beginnen!"}
D[6847] = {"Meister Rysons Allsehendes Auge",{"Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.","","Seid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!"}}
D[6848] = {"Meister Rysons Allsehendes Auge",{"Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.","","Seid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!"}}
D[6861] = {"Zinnzischelix's tragbare Schreddereinheit",{"Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:","","*30 Thoriumbarren.","","*50 Mithrilbarren.","","*75 Eisenbarren.","","*1 Dampfsäge."}}
D[6862] = {"Zinnzischelix's tragbare Schreddereinheit",{"Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:","","*30 Thoriumbarren.","","*50 Mithrilbarren.","","*75 Eisenbarren.","","*1 Dampfsäge."}}
D[6881] = {"Ivus der Waldfürst",{"Der Frostwolfklan wird durch eine Besudelung aus Elementarenergie geschützt. Ihre Schamanen stümpern mit Mächten herum, die uns sicherlich alle vernichten werden, wenn sie nicht im Zaum gehalten werden.","","Der Schaden ist zu groß geworden, als dass der Kreis ihn noch kontrollieren kann! Wir müssen Ivus zu Hilfe rufen.","","Die Soldaten der Frostwolf tragen Elementarglücksbringer, die Sturmkristalle genannt werden. Wir können diese Glücksbringer nutzen, um Ivus zu beschwören. Zieht los und holt die Kristalle, <Name>!"}}
D[6901] = {"Startet den Angriff!"}
D[6921] = {"Inmitten der Ruinen",{"Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
D[6922] = {"Baron Aquanis",{"Bringt die seltsame Wasserkugel zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
D[6941] = {"Ruf der Lüfte - Vipores Luftflotte",{"Die Eliteeinheiten der Horde, die die Linien bewachen, müssen erledigt werden! Ich vertraue Euch die Aufgabe an, diese Herde von Wilden auszudünnen. Kehrt mit den Medaillen ihrer Offiziere und Legionäre zu mir zurück. Wenn ich das Gefühl habe, dass ausreichend Gesindel erledigt wurde, werde ich den Luftschlag anordnen."}}
D[6942] = {"Ruf der Lüfte - Slidores Luftflotte",{"Meine Greifen sind bereit, an den Frontlinien zuzuschlagen, können den Angriff aber erst vornehmen, wenn die Linien ausgedünnt sind.","","Die Krieger der Horde, die mit dem Halten der Frontlinien betraut sind, tragen stolz Verdienstmedaillen an ihrer Brust. Reißt diese Medaillen von ihren verfaulten Körpern und bringt sie mir.","","Wenn die Frontlinie ausreichend ausgedünnt wurde, werde ich den Luftschlag anordnen! Tod von oben!"}}
D[6943] = {"Ruf der Lüfte - Ichmans Luftflotte",{"Ihr Mut ist auf einem Tiefpunkt, Soldat. Nach unserem letzten fehlgeschlagenen Luftschlag gegen die Horde wollten sie nicht mehr fliegen! Es liegt an Euch, ihre Moral wieder aufzubauen.","","Kehrt zum Schlachtfeld zurück und schlagt im Herzen des Befehlsstabs der Horde zu. Erledigt ihre Kommandanten und Wächter. Kehrt mit so vielen ihrer Medaillen zu mir zurück, wie Ihr in Eurem Beutel unterbringen könnt! Ich verspreche Euch, wenn meine Greifen die Beute sehen und das Blut unserer Feinde riechen, werden sie wieder fliegen! Geht jetzt!"}}
D[6961] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[6962] = {"Leckereien für Altvater Winter",{"Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Orgrimmar."}}
D[6963] = {"Gestohlene Winterhauchleckereien",{"Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird."}}
D[6964] = {"Der Anlass für die Feiertage",{"Sprecht mit Sagorne Gratläufer im Tal der Weisheit von Orgrimmar über das Winterhauchfest."}}
D[6981] = {"Der leuchtende Splitter",{"Begebt Euch nach Ratschet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.","","Liefert dann den Splitter ab, wie Ihr angewiesen wurdet."}}
D[6982] = {"Vorräte der Eisbeißermine",{"Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Allianz in Dun Baldar."}}
D[6983] = {"So was Gemeines...",{"Sucht die gestohlenen Leckereien und bringt sie zu Kaymard Kupferzwick nach Orgrimmar. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet."}}
D[6984] = {"Ein Dankeschön von Kokelwälder!",{"Sprecht mit Altvater Winter in Orgrimmar."}}
D[6985] = {"Vorräte der Eisenschachtmine",{"Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Horde in die Burg Frostwolf."}}
D[7001] = {"Verwaiste Ställe",{"Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden."}}
D[7002] = {"Widderledernes Zaumzeug",{"Während einige unserer Soldaten damit beschäftigt sind, Wölfe für den Stallmeister einzufangen, müssen andere für die einfachsten Sachen sorgen, die man beim Reiten braucht. Ich meine Geschirre, klar?","","Ihr müsst die einheimischen Widder jagen. Genau die Widder, die die Stormpike-Kavallerie als Reittiere benutzt.","","Tötet sie und bringt mir ihre Häute. Sobald wir genug Häute gesammelt haben, können wir daraus Geschirre für unsere Reiter machen. Die Frostwolfreiter werden wieder reiten!"}}
D[7003] = {"Geschrumpfte Riesen",{"Benutzt Zorbins Ultraschrumpfer um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin von Schiller 15 Schrumpfüberreste von diesen Riesen. Ihr findet Ihn bei den Docks, an der vergessenen Küste in Feralas."}}
D[7021] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[7022] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede."}}
D[7023] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede."}}
D[7024] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[7025] = {"Leckereien für Altvater Winter",{"Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Eisenschmiede."}}
D[7026] = {"Widderzaumzeug",{"Die Stormpikegarde kann sich nicht ohne Sättel in die Schlacht stürzen! Wir brauchen Geschirre für unsere Reittiere, schließlich sind wir keine Wilden!","","Wir könnten zwar einfach die Widder jagen, die in der Nähe unserer Basis herumstreifen, aber das wäre idiotisch. Wenn wir aus ihrem Leder die Geschirre machen, dann haben wir keine Reittiere mehr.","","Ihr müsst zur Basis des Feindes vorrücken und dort die Frostwölfe töten, die sie als Reittiere benutzen. Bringt mir ihre Häute, damit wir daraus die Geschirre für unsere Kavallerie fertigen können. Geht!"}}
D[7027] = {"Verwaiste Ställe",{"Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Zähmungshalsband der Sturmlanzen um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden."}}
D[7028] = {"Dunkles Böses",{"Sammelt 15 theradrische Kristallschnitzereien für Trista in Desolace."}}
D[7029] = {"Schlangenzunges Verderbnis",{"Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.","","Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.","","Heilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Vark Schlachtnarbe in Schattenflucht zurück."}}
D[7041] = {"Schlangenzunges Verderbnis",{"Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.","","Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.","","Heilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Talendria an der Nijelspitze zurück."}}
D[7042] = {"Gestohlene Winterhauchleckereien",{"Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird."}}
D[7043] = {"So was Gemeines...",{"Sucht die gestohlenen Leckereien und bringt sie zu Wulmort Klingeltaschen nach Eisenschmiede. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet."}}
D[7044] = {"Legenden von Maraudon",{"Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.","","Findet einen Weg, um mit Celebras zu sprechen."}}
D[7045] = {"Ein Dankeschön von Kokelwälder!",{"Sprecht mit Altvater Winter in Ironforge."}}
D[7046] = {"Das Szepter von Celebras",{"Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.","","Sprecht mit ihm, nachdem das Ritual vollendet ist."}}
D[7061] = {"Das Winterhauchfest",{"Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, bringt es zu Cairne Bluthuf in Donnerfels."}}
D[7062] = {"Der Anlass für die Feiertage",{"Sprecht mit dem Historiker Karnik in der Forscherliga von Eisenschmiede über das Winterhauchfest."}}
D[7063] = {"Das Winterhauchfest",{"Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, dann bringt es zu König Magni Bronzebart nach Eisenschmiede."}}
D[7064] = {"Verderbnis von Erde und Samenkorn",{"Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Schattenflucht in Desolace zurück."}}
D[7065] = {"Verderbnis von Erde und Samenkorn",{"Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück."}}
D[7066] = {"Samenkorn des Lebens",{"Sucht Remulos bei der Mondlichtung auf und gebt ihm das Samenkorn des Lebens."}}
D[7067] = {"Die Anweisungen des Pariahs",{"Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace."}}
D[7068] = {"Schattensplitter",{"Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar."}}
D[7070] = {"Schattensplitter",{"Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Düstermarschen."}}
D[7081] = {"Die Friedhöfe im Alteractal",{"Erobert einen Friedhof und kehrt zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück."}}
D[7082] = {"Die Friedhöfe von Alterac",{"Erobert einen Friedhof und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück."}}
D[7101] = {"Türme und Bunker",{"Erobert einen gegnerischen Turm und kehrt anschließend zu Korporal Teeka Murrblut ins Dorf der Frostwölfe zurück."}}
D[7102] = {"Türme und Bunker",{"Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück."}}
D[7121] = {"Der Rüstmeister",{"Sprecht mit dem Rüstmeister der Sturmlanzen."}}
D[7122] = {"Mine besetzen",{"Erobert eine Mine, die die Sturmlanzen noch nicht kontrollieren, und kehrt dann zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück."}}
D[7123] = {"Sprecht mit unserem Rüstmeister",{"Sprecht mit dem Rüstmeister der Frostwölfe."}}
D[7124] = {"Eine Mine besetzen",{"Erobert eine Mine und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück."}}
D[7141] = {"Die Schlacht um Alterac",{"Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Steinhauer im Alteracgebirge zurück."}}
D[7142] = {"Die Schlacht um Alterac",{"Betretet das Alteractal und bezwingt den Zwergengeneral, Vanndar Sturmlanze. Kehrt anschließend zu Voggah Todesgriff im Alteracgebirge zurück."}}
D[7161] = {"Flaggenjagd",{"Begebt Euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt im Alteractal und findet das Banner der Frostwölfe. Bringt anschließend Kriegsmeister Laggrond das Banner."}}
D[7162] = {"Flaggenjagd",{"Begebt Euch in die Eisschwingenhöhle südwestlich von Dun Baldar im Alteractal und findet das Banner der Sturmlanzen. Bringt anschließend Leutnant Haggerdin im Alteracgebirge das Banner."}}
D[7163] = {"Aufstieg und Anerkennung",{"<Kriegsmeister Laggrond salutiert vor Euch.>","","Jetzt ist eure Zeit gekommen, <Name>. Ihr habt viel für den Frostwolfklan getan und habt Euch dabei nicht nur als ein Soldat der Frostwolf, sondern auch als Freund bewiesen.","","Gut gemacht! Zeigt mir Euer Abzeichen!"}}
D[7164] = {"Ehre innerhalb des Klans",{"Es ist gut, Euch wiederzusehen, <Klasse>. Ich hatte nicht erwartet, dass Ihr zurückkehren würdet. Ihr habt Euch als tapferer und ehrbarer Soldat der Frostwolf erwiesen.","","Wieder ist eure Zeit gekommen, <Name>. Ihr hab einen neuen Rang verdient und damit auch ein neues Abzeichen, das diesen Aufstieg anzeigt.","","Zeigt mir euer Abzeichen!"}}
D[7165] = {"Verdiente Ehrerbietung",{"So viele Gefallene. Blut tränkt die Felder. Aber... Ihr lebt... Ihr habt durchgehalten. Ihr habt unsere Armee zu vielen Siegen geführt. Dafür, Soldat, habt Ihr einen neuen Rang verdient..","","Zeigt mir euer Abzeichen!"}}
D[7166] = {"Legendäre Helden",{"Ihr strahlt Macht und Befehlsgewalt aus, <Klasse>. Erhaben in den Augen der Frostwolf - der Feind duckt sich, wenn Euer Name genannt wird.","","Erhebt Euch, Held der Frostwolf. Erhebt Euch und lasst Euch ehren!","","Zeigt mir euer Abzeichen!"}}
D[7167] = {"Das Auge der Führung",{"Drek'Thar singt Euch zu Ehren Heldenweisen und in ganz Kalimdor erzählt man sich von Euren Heldentaten. Der Kriegshäuptling blickt stolz auf Euch herab - Eure unerschütterliche Verteidigung unseres Klans hat ihn tief berührt.","","Ihr habt Euch das Auge der Führung redlich verdient.","","Präsentiert Eure Abzeichen, Kommandant <Name>."}}
D[7168] = {"Aufstieg und Anerkennung",{"Die Meisten leben nicht lange genug um sich aus ihrer eigenen Mittelmäßigkeit zu erheben. Ihr habt euch als ein mustergültiger Soldat erwiesen, <Klasse>. Die Zeit ist da!","","Präsentiert Euer Abzeichen!"}}
D[7169] = {"Ehre innerhalb der Garde",{"Die ganze Basis spricht von Euren Taten auf dem Feld der Ehre! Ihr habt dem Feind schwere Treffer zugefügt und ihre Moral zerschmettert! Dafür habt Ihr einen Ehrenplatz unter den Stormpike verdientnnPräsentiert Euer Abzeichen!"}}
D[7170] = {"Verdiente Ehrerbietung",{"Ich muss es wissen, <Name>. Wenn Ihr dem Feind direkt ins Auge blickt, seht Ihr dort Furcht? Ducken sie sich in Eurer Gegenwart? Ihnen muss klar sein, dass sie verloren sind!","","Ihr habt Euch die Ehrerbietung der Garde verdient. Präsentiert Euer Abzeichen!"}}
D[7171] = {"Legendäre Helden",{"Vor mir steht ein erhabener Held der Allianz.","","<Lieutenant Haggerdin salutiert.>","","Wenige haben solch einen Rang unter den Stormpike verdient. Ich habe gesehen wie der Feind vor Euch fiel. Ich habe ihre Entschlossenheit wanken sehen in Eurer Gegenwart. Wenn Ihr Euch ins Kampfgetümmel stürzt, seid ihr ein leuchtendes Fanal der Hoffnung für unsere Streitkräfte!","","Präsentiert Euer Abzeichen!"}}
D[7172] = {"Das Auge der Führung"}
D[7181] = {"Die Legende von Korrak",{"Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.","","Solltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Kriegsmeister Laggrond im Alteracgebirge zurück."}}
D[7201] = {"Das letzte Element",{"Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat."}}
D[7202] = {"Korrak der Blutrünstige",{"Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.","","Solltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Leutnant Haggerdin im Alteracgebirge zurück."}}
D[7221] = {"Sprecht mit Ausgrabungsleiter Steinhauer",{"Sprecht mit Ausgrabungsleiter Steinhauer in der Garnison von Dun Baldar."}}
D[7222] = {"Sprecht mit Voggah Todesgriff",{"Sprecht mit Voggah in Burg Frostwolf."}}
D[7223] = {"Rüstungsfetzen",{"Bringt Murgot Tiefenschmied in Dun Baldar 20 Rüstungsfetzen."}}
D[7224] = {"Beutezug im Feindesland",{"Bringt 20 Rüstungsfetzen zu Schmied Regzar im Dorf der Frostwölfe."}}
D[7241] = {"Die Verteidigung der Frostwölfe",{"Reist ins Alteractal, das sich im gleichnamigen Gebirge befindet. Sucht dort außerhalb des Tunneleingangs Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwölfe. Das Alteractal findet Ihr nördlich von Tarrens Mühle am Fuß des Alteracgebirges."}}
D[7261] = {"Die hoheitliche Anordnung",{"Reist ins Alteractal im Vorgebirge des Hügellands. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.","","Für den Ruhm von Bronzebart!"}}
D[7281] = {"Bruderliebe",{"Begebt Euch ins Gebiet der Sturmlanzen und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[7282] = {"Bruderliebe",{"Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[7301] = {"Gefallene Himmelsstürmer",{"Begebt Euch ins Frostwolfterritorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt."}}
D[7302] = {"Gefallene Himmelsstürmer",{"Findet heraus was aus Schwadronskommandant Guse, Schwadronskommandant Jeztor, und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück."}}
D[7321] = {"Milde Schildkrötensuppe",{"Bringt 10 Stücke Schildkrötenfleisch und einige feine Gewürze zu Christoph Jeffkott in Tarrens Mühle."}}
D[7341] = {"Ein fairer Handel",{"Seid gegrüßt, <Volk>. Ich bin Kolark, Kopfgeldjäger aus Thunder Bluff. Ich habe viele Teile der Welt bereist und so manches erlebt.","","Auf meinen Reisen über die südlichen Meere entdeckte ich diese wunderbaren Thoriumpfeile. Zwar besitze ich einen endlosen Vorrat dieser Pfeile, aber dafür keine einzige Patrone mehr. Bah, kein Tauren mit Selbstachtung würde sich je dabei erwischen lassen, wie er einen dieser dürren Bögen benutzt. Die Pfeile sind nutzlos!","","Ich schlage Euch einen Handel vor: Einen eins zu eins Tausch von Thoriumpatronen gegen meine Thoriumpfeile. Sind wir im Geschäft?"}}
D[7342] = {"Pfeile sind was für Memmen",{"Habt Ihr schon einmal so einen verdammten Mist erlebt?! Die letzte Munitionslieferung aus Kharanos ist völlig verbockt worden. Alles was wir jetzt noch an Munition haben, sind diese schwachen, nutzlosen Pfeile! Was zur Hölle soll ich mit 500.000 Thoriumpfeilen anfangen?","","Ich sag dir was, Kind. Wenn du es schaffst mir Thoriumpatronen zu bringen, gebe ich dir im Austausch dafür Thoriumpfeile. Sind wir im Geschäft?"}}
D[7361] = {"Die Gunst der Dunkelspeere",{"Ihr wurdet beauftragt gegnerische Nachtelfenspieler im Alteractal zu töten.","","Tötet einen Nachtelfen und bringt einen abgeschlagenen Nachtelfenkopf zu Najak Hexxen in Burg Frostwolf."}}
D[7362] = {"Verbündeter der Tauren",{"Ihr wurdet beauftragt gegnerische Gnomspieler im Alteractal zu töten.","","Tötet einen Gnom und bringt ein Büschel Gnomhaar zu Ravak Grimmtotem in Burg Frostwolf."}}
D[7363] = {"Die menschliche Existenz",{"Ihr wurdet beauftragt gegnerische Menschenspieler im Alteractal zu töten.","","Tötet einen Menschen und bringt dessen Knochensplitter zu Kommandant Louis Philips (er bewegt sich zwischen den Frontlinien und Burg Frostwolf hin und her).","","Die Heilung für die menschliche Existenz ist zum Greifen nahe!"}}
D[7364] = {"Gnomeregan Kopfgeld",{"Ihr wurdet beauftragt gegnerische Taurenspieler im Alteractal zu töten.","","Tötet einen Tauren und bringt dessen Taurenhuf zu Dirk Schwindel in Dun Baldar."}}
D[7365] = {"Hirschhaupts Requiem",{"Ihr wurdet beauftragt gegnerische Trollspieler im Alteractal zu töten.","","Tötet einen Troll und bringt Athramanis in Dun Baldar etwas Trollmojo der Dunkelspeere."}}
D[7366] = {"Die Gnade des Erzbischofs",{"Ihr wurdet beauftragt gegnerische Verlassenen-Spieler im Alteractal zu töten.","","Tötet einen Verlassenen und bringt dessen Herz zu Kommandant Karl Philips (er bewegt sich zwischen dem Sägewerk und der Mine hin und her)."}}
D[7367] = {"Die Gefahr bannen",{"Findet den Sprengmeister der Frostwölfe und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Sturmlanzen zurück."}}
D[7368] = {"Die Gefahr bannen",{"Findet den Sprengmeister der Sturmlanzen und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Frostwölfe zurück."}}
D[7381] = {"Korraks Rückkehr",{"Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.","","Bringt Korraks Schädel zu Kriegsmeister Laggrond auf Burg Frostwolf."}}
D[7382] = {"Korrak der Unsterbliche",{"Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.","","Bringt Korraks Schädel zu Leutnant Haggerdin in Dun Baldar."}}
D[7383] = {"Krone der Erde",{"Füllt die Amethystphiole und bringt sie Corithras Mondzorn in Dolanaar."}}
D[7385] = {"Eine Gallone Blut",{"Wenn Ihr Euch nützlich machen wollt, spendet mir große Mengen Feindesblut. Ich wäre hocherfreut, Gallonen von Blut entgegen zu nehmen, <Name>."}}
D[7386] = {"Haufenweise Kristalle",{"Es gibt hier Zeiten, in denen Ihr Tage oder sogar Wochen auf den Schlachtfeldern zubringt. Vielleicht könnt Ihr während dieser Zeit nach größeren Gruppen von Frostwolf Sturmkristallen Ausschau halten.","","Der Zirkel wäre hocherfreut über derartige Spenden, <Name>."}}
D[7401] = {"GESUCHT: Zwerge!",{"Ihr wurdet damit beauftragt, alle feindlichen Zwergenspieler im Alteractal zu töten.","","Tötet einen Zwerg und schneidet ihm sein Rückgrat heraus. Bringt anschließend das Zwergenrückgrat zu Unteroffizierin Yazra Murrblut in Burg Frostwolf."}}
D[7402] = {"GESUCHT: ORCS!",{"Ihr wurdet damit beauftragt, alle feindlichen orcischen Spieler im Alteractal zu töten.","","Tötet einen Orc und bringt seinen Zahn zurück zu Korporal Noreg Sturmlanze in Dun Baldar."}}
D[7421] = {"Verteidigung der Dunkelspeere"}
D[7422] = {"Mehr Gnomhaar"}
D[7423] = {"Knochensplitterjagd"}
D[7424] = {"Was zum Huf?"}
D[7425] = {"Hirschhaupts Mojo-Fete"}
D[7426] = {"Die Liebe eines Mannes"}
D[7427] = {"GESUCHT: MEHR ZWERGE"}
D[7428] = {"GESUCHT: MEHR ORCS!"}
D[7429] = {"Befreit Knot!",{"Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...","","Was erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!"}}
D[7441] = {"Pusillin und der Älteste Azj'Tordin",{"Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.","","Kehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück."}}
D[7461] = {"Der innere Wahnsinn",{"Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.","","Betretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.","","Kehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück."}}
D[7462] = {"Der Schatz der Shen'dralar",{"Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!"}}
D[7463] = {"Arkane Erfrischung",{"Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück."}}
D[7481] = {"Elfische Legenden",{"Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei dem Weisen Korolusk in Camp Mojache."}}
D[7482] = {"Elfische Legenden",{"Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei der Gelehrten Runendorn in der Mondfederfeste."}}
D[7483] = {"Buchband der Schnelligkeit",{"Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2 mal das Blut von Helden, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten."}}
D[7484] = {"Buchband des Fokus",{"Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2 mal Schattenhaut, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten."}}
D[7485] = {"Buchband des Schutzes",{"Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten."}}
D[7486] = {"Die Belohnung eines Helden",{"Nehmt Eure Belohnung aus Hydraxis' Kasten."}}
D[7487] = {"Abstimmung mit dem Kern",{"Begebt Euch zum Portal in den Schwarzfelstiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Felsspalter am Schwarzfels zurück."}}
D[7488] = {"Lethtendris' Netz",{"Bringt Lethtendris' Netz zu Latronicus Mondspeer in der Mondfederfeste in Feralas."}}
D[7489] = {"Lethtendris' Netz",{"Bringt Lethtendris' Netz zu Talo Dornhuf im Camp Mojache in Feralas."}}
D[7490] = {"Sieg für die Horde",{"Bringt Onyxias Kopf zu Thrall in Orgrimmar."}}
D[7491] = {"Für alle sichtbar",{"Sucht Oberanführer Runthak im Tal der Stärke auf."}}
D[7492] = {"Camp Mojache",{"Sprecht mit Talo Dornhuf in Camp Mojache, in Feralas."}}
D[7493] = {"Die Reise beginnt erst",{"Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.","","Bitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.",""," Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian."}}
D[7494] = {"Die Mondfederfeste",{"Sprecht mit Latronicus Mondspeer in der Mondfederfeste in Feralas."}}
D[7495] = {"Sieg für die Allianz",{"Bringt Onyxias Kopf zu Hochlord Bolvar Fordragon in Sturmwind."}}
D[7496] = {"Gute Zeiten feiern",{"Sucht Major Mattingly im Tal der Helden auf."}}
D[7497] = {"Die Reise beginnt erst",{"Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.","","Bitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.",""," Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian."}}
D[7498] = {"Garona: Eine Studie über Heimlichkeit und Verrat",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7499] = {"Kodex der Verteidigung",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7500] = {"Das Arkanistenkochbuch",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7501] = {"Vom Licht und wie man es schwingt",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7502] = {"Schatten einspannen",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7503] = {"Das größte Volk von Jägern",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7504] = {"Heiliger Fleischklops: Was das Licht Dir nicht erzählt",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7505] = {"Frostschock und Du",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7506] = {"Der Smaragdgrüne Traum",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7507] = {"Forors Kompendium",{"Bringt Forors Kompendium des Drachentötens zurück in das Athenaeum."}}
D[7508] = {"Das Schmieden von Quel'Serrar",{"Bringt dem Hüter des Wissens Lydros, die stumpfe und glanzlose Elfenklinge."}}
D[7509] = {"Das Schmieden von Quel'Serrar",{"Bringt Onyxia dazu, ihren Feueratem auf die noch unerhitzte Klinge zu benutzen. Sobald dies geschehen ist, hebt die erhitzte Klinge wieder auf. Doch seid gewarnt, die erhitzte Klinge wird nicht auf ewig erhitzt bleiben - behaltet also die Zeit im Auge.","","Zuletzt müsst Ihr das Biest töten und die uralte erhitzte Klinge in ihren Leib rammen. Kehrt anschließend zu mir zurück und Quel'Serrar wird Euer sein."}}
D[7521] = {"Donneraan der Windsucher",{"Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen."}}
D[7522] = {"Untersuchung des Gefäßes",{"Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian."}}
D[7541] = {"Dienst an der Horde",{"Unsere Gelehrten werden einige Zeit brauchen, um den Anhänger, den Ihr uns gebracht habt, zu studieren. Allerdings möchte ich Euch für Euren Dienst an der Horde eine kleine Belohnung geben.","","Danke, <Name>. Eure Taten ehren Euch und uns."}}
D[7562] = {"Mor'zul Blutbringer",{"Sprecht mit Mor'zul Blutbringer in der brennenden Steppe."}}
D[7563] = {"Kochendes Blut",{"Mor'zul Blutbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt."}}
D[7564] = {"Wildaug",{"Bringt den Behälter mit Blut zu Gorzeeki Wildaug in der brennenden Steppe."}}
D[7581] = {"Das Fundament des Gefängnisses",{"Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der faulenden Narbe zurück."}}
D[7582] = {"Die Gefängnishülle",{"Reist in die flüsternde Schlucht in Winterquell und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt."}}
D[7583] = {"Unterdrückung",{"Wagt Euch in die faulende Narbe heraus und macht einen Kommandant der Verdammniswache ausfindig.","","Wendet das leuchtende Kristallgefängnis auf den Kommandanten der Verdammniswache an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird.","","Solltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der faulenden Narbe."}}
D[7601] = {"Nibys Anweisungen",{"Sprecht mit Impsy im Teufelswald."}}
D[7602] = {"Reine Teufelsessenz",{"Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.","","Die Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den verwüsteten Landen bergen die Teufelsessenz ihrer Region.","","Findet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald."}}
D[7603] = {"Kroshius Höllenbestienkern",{"Sucht im Narbengrund im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.","","Bringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald."}}
D[7604] = {"Ein verbindlicher Vertrag",{"Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Düsterfeilsch, wenn Ihr die Pläne für das Sulfuron erhalten möchtet."}}
D[7621] = {"Eine Warnung",{"<Klasse>, Ihr seid dabei eine entscheidene Reihe von Ereignissen zu durchleben, die alle Eure Fähigkeiten auf die Probe stellen sollen.","","Ich schlage vor, dass Ihr Euch erst einmal anhört, was ich zu erzählen habe.","","Lasst Euch gewarnt sein, Ihr müsst diese Aufgabe alleine lösen. Es ist ratsam, dass Eure Verbündeten Abstand halten. Die Einmischung anderer wird eine harte Bestrafung zur Folge haben.","","Das Schicksal hat Euch, Euch alleine, hierher geführt. Kämpft mit Ehre. Macht Euch das Licht zu Nutze."}}
D[7622] = {"Die Waage von Licht und Schatten",{"Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Himmelsfeuer, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.","","Konsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden."}}
D[7623] = {"Lord Schattenfluch",{"Erwerbt schattenhafte Tränke von Gorzeeki in der brennenden Steppe.","","Benutzt die Tränke um durch Jaedenar zu reisen und sprecht mit Lord Schattenfluch."}}
D[7624] = {"Ulathek der Verräter",{"Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Schattenfluch in Jaedenar."}}
D[7625] = {"Xorothianischer Sternenstaub",{"Erwerbt xorothianischen Sternenstaub von Ur'dan. Bringt es anschließend Gorzeeki Wildaug in der brennenden Steppe."}}
D[7626] = {"Die Glocke von Dethmoora",{"Bringt 2 Elixiere der Schattenmacht zu Gorzeeki Wildaug in die brennende Steppe."}}
D[7627] = {"Das Rad des Schwarzen Marsches",{"Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildaug in die brennende Steppe."}}
D[7628] = {"Die Altarkerze des Jüngsten Gerichts",{"Bringt 3 Schuppen eines schwarzen Drachen zu Gorzeeki Wildaug in der brennenden Steppe."}}
D[7629] = {"Wichtellieferung",{"Bringt den Wichtel im Gefäß in das Alchimielabor in der Scholomance. Bringt nach der Herstellung des Pergaments, dass Gefäß zurück zu Gorzeeki Wildaug."}}
D[7630] = {"Arkanit",{"Bringt 1 Arkanitbarren zu Gorzeeki in der brennenden Steppe."}}
D[7631] = {"Schreckensross von Xoroth",{"Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch."}}
D[7632] = {"Das uralte Blatt",{"Findet den Besitzer des uralten, versteinerten Blatts. Viel Glück, <Name>; die Welt ist groß."}}
D[7633] = {"Eine Einführung",{"Euer Eifer und Eure Rechtschaffenheit wurden zur Kenntnis genommen, <Klasse>.","","Wir sind die Uralten, Beschützer dieses einst bedeutenden Waldes. Unsere körperlichen Formen wurden vor 10.000 Jahren zerstört, als Archimonde und die Brennende Legion gegen Hyjal aufmarschierten. Dennoch, unsere Geister blieben unversehrt.","","Wir haben Aufgaben zu vergeben. Werden diese erfüllt, so werden sie Euch die Geheimnisse der Uralten preisgeben.","","Wisset, solltet Ihr diese Aufgaben vollenden, so kehrt lediglich zu diesem Felsen zurück und wir werden Euren Ruf erhören."}}
D[7634] = {"Uraltes in Sehnen eingewickeltes Laminablatt",{"Hastat der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, blauen Drachen gebeten. Solltet Ihr diese Sehne finden, kehrt zu Hastat im Teufelswald zurück."}}
D[7635] = {"Die passende Sehne",{"Stoma der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, schwarzen Drachen gebeten. Solltet Ihr diese Sehne finden, kehrt zu Stoma im Teufelswald zurück."}}
D[7636] = {"Holzstab der Uralten",{"Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören:","","Simone die Verführerin.","","Klinfran der Wahnsinnige.","","Solenor der Schlächter.","","Artorius der Verhängnisvolle.","","Vernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück.","","Haltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten.","","Ihr MÜSST diese Aufgabe eigenständig erledigen."}}
D[7637] = {"Ein Opfer darbieten",{"Reist nach Eisenschmiede und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen."}}
D[7638] = {"Lord Grayson Schattenbruch",{"Sprecht mit Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind."}}
D[7639] = {"Lass Gerechtigkeit walten",{"Bringt den Weihrauchschwenker zu Lord Grayson Schattenbruch in Sturmwind zurück."}}
D[7640] = {"Der Exorzismus des Schreckenstals",{"Vertreibt mit Hilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind zurück."}}
D[7641] = {"Grimand Elmores Werk",{"Sprecht mit Grimand Elmore im Zwergendistrikt von Sturmwind."}}
D[7642] = {"Fünf Dinge",{"Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Arthas' Tränen, 5 Phiolen Weihwasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Sturmwind."}}
D[7643] = {"Der uralte Pferdegeist",{"Beschafft spezielles Pferdefutter, mit dem man ein Geisterpferd füttern kann. Merideth Carlson in Süderstade scheint dafür eine recht gute Quelle zu sein.","","Reist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen."}}
D[7644] = {"Gesegnetes Arkanitpferdegeschirr",{"Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Schattenbruch in das Kathedralenviertel von Sturmwind zurück."}}
D[7645] = {"Mit Manna angereichertes Pferdefutter",{"Treibt 20 angereicherte Mannakekse - die ausschlaggebende Zutat für die Herstellung von mit Manna angereichertem Pferdefutter - für Merideth Carlson aus Süderstade in dem Vorgebirge des Hügellands auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt.","","Zusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen."}}
D[7646] = {"Das Orakel der Anrufung",{"Bringt Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind einen azerothischen Diamanten und einen makellosen schwarzen Diamanten."}}
D[7647] = {"Gerechtigkeit und Erlösung",{"Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das Besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses.","","Gebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück."}}
D[7648] = {"Grimands feinste Arbeit",{"Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind."}}
D[7649] = {"Verzauberter Thoriumplattenpanzer: Band I",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7650] = {"Verzauberter Thoriumplattenpanzer: Band II",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7651] = {"Verzauberter Thoriumplattenpanzer: Band III",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7652] = {"Ein Sonderangebot",{"Okay, Junge, ich habe da ein heißes Angebot für dich.",""," Ich habe hier einige Pläne zur Herstellung von imperialen Plattenrüstungen, die ich gerne loswerden möchte. Das einzige, was ich als Gegenleistung verlange, sind einige Thoriumbarren. Klingt doch gut, oder?"}}
D[7653] = {"Imperialer Plattengürtel",{"Das macht 20 Thoriumbarren für die Pläne des Plattengürtels, Junge."}}
D[7654] = {"Imperiale Plattenstiefel",{"Thoriumbarren, Junge. Genau 40! Heulst du gleich? Soll ich dich in den Arm nehmen?","","<Malyfous lacht lauthals.>"}}
D[7655] = {"Imperiale Plattenarmschienen",{"Du willst die Pläne für die Armschienen? Das ganze kostet dich nur 20 Thoriumbarren."}}
D[7656] = {"Imperiale Plattenrüstung",{"Junge, für die Pläne der Plattenrüstung krieg' ich 60 Thoriumbarren.","","Jetzt geht das wieder los. Gleich rennst du wohl wieder zu deinen ach so mächtigen Göttern und jammerst! Stell dich nicht so an, Weichei! Niemand hat behauptet, dass das Leben fair wäre!"}}
D[7657] = {"Imperialer Plattenhelm",{"Gib mir einfach 50 Thoriumbarren und die Pläne für den Helm gehören dir."}}
D[7658] = {"Imperiale Plattengamaschen",{"Reich mir einfach 60 Thoriumbarren 'rüber und die Pläne für die Gamaschen gehören dir.",""," Ja, ja ich bin dein Ruin. Diese Geschichten muss ich mir jedes mal anhören. Also spar dir den Mist, Weichei."}}
D[7659] = {"Imperiale Plattenschultern",{"Du willst die Pläne für die Plattenschultern? Das macht 20 Thoriumbarren."}}
D[7660] = {"Wolfstausch - arktischer Wolf"}
D[7661] = {"Wolfstausch - Roter Wolf"}
D[7662] = {"Neuer Kodo - Graublauer"}
D[7663] = {"Neuer Kodo - Grün"}
D[7664] = {"Austausch Eures elfenbeinfarbigen Raptors"}
D[7665] = {"Austausch Eures roten Raptors"}
D[7666] = {"Erneut im großen Ossuarium",{"Wart Ihr schon zurück in Scholomance, <Name>? Ihr habt bereits teuer für die Verwendung des Orakels der Anrufung bezahlt - vielleicht möchtet Ihr ja noch ein weiteres mit Euch nehmen. Ihr wäret damit in der Lage, Euch den Gefahren des großen Ossuariums erneut zu stellen.","","Für alle Fälle, hier habt Ihr es. Ihr habt es Euch redlich verdient."}}
D[7667] = {"Materielle Unterstützung",{"Wenn Ihr Sagorne Gratläufer im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothischen und einen makellosen schwarzen Diamanten."}}
D[7668] = {"Die Bedrohung durch Schattensichel",{"Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.","","Bringt Schattensichels Kopf zu Sagorne Gratläufer im Tal der Weisheit in Orgrimmar."}}
D[7669] = {"Erneut im großen Ossuarium",{"Wart Ihr schon zurück in Scholomance, <Name>? Ihr habt bereits teuer für die Verwendung des Orakels der Anrufung bezahlt - vielleicht möchtet Ihr ja noch ein weiteres mit Euch nehmen. Ihr wäret damit in der Lage, Euch den Gefahren des großen Ossuariums erneut zu stellen.","","Für alle Fälle, hier habt Ihr es. Ihr habt es Euch redlich verdient."}}
D[7670] = {"Lord Grayson Schattenbruch",{"Sprecht mit Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind."}}
D[7671] = {"Ersatz für Euren Frostsäbler"}
D[7672] = {"Austausch Eures Nachtsäblers"}
D[7673] = {"Austausch Eures Frostwidders"}
D[7674] = {"Austausch Eures schwarzen Widders"}
D[7675] = {"Eisblauer Roboschreiter-Austausch"}
D[7676] = {"Ersatz für Euren weißen Roboschreiter"}
D[7677] = {"Austausch Eures Schimmels"}
D[7678] = {"Austausch Eures Palominos"}
D[7681] = {"Hunter test quest",{"Füttert Euer Tier und sprecht dann mit Eurem Questgeber."}}
D[7682] = {"Hunter test quest2",{"Füttert Euer Tier und sprecht dann mit Eurem Questgeber."}}
D[7701] = {"GESUCHT: Aufseher Maltorius",{"Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.","","Tötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Hauptmann des Ausgucks Lolo Langhieb in der sengenden Schlucht für eine Belohnung."}}
D[7703] = {"Die offene Rechnung der Gordok",{"Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.","","Krombruch zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat."}}
D[7721] = {"Treibstoff fürs Schrumpfen",{"Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin von Schiller in der Nähe des dortigen Docks."}}
D[7722] = {"Was zum Fluxus?!",{"Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht."}}
D[7723] = {"Verdammt seien diese fetten Finger",{"Hansel Bleihand möchte, dass Ihr 20 Schwere Kriegsgolems tötet.","","Die Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück."}}
D[7724] = {"Feurige Bedrohung!",{"Hansel Bleihand möchte, dass Ihr 20 große Lavaspinnen in der sengenden Schlucht tötet.","","Die großen Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der sengenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück."}}
D[7725] = {"Und wieder unter den geschrumpften Riesen",{"Benutzt Zorbins Ultraschrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt 10 Schrumpfüberreste, die auf den kleineren handlicheren Riesen liegen zu Zorbin von Schiller am Dock der Vergessenen Küste in Feralas."}}
D[7726] = {"Neuer Treibstoff fürs Schrumpfen",{"Sammelt 6 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin von Schiller in der Nähe des dortigen Docks."}}
D[7727] = {"Incendosaurier? Was-auch-immer-Saurier?",{"Hansel Bleihand möchte, dass Ihr 20 Incendosaurier tötet.","","Die Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der sengenden Schlucht.","","Sobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Bleihand in der sengenden Schlucht zurück."}}
D[7728] = {"GESTOHLEN: Schmiedewindform und ein Ausguckhandfernrohr",{"Sucht die Schmiedewindform und das Ausguckhandfernrohr. Bringt diese Gegenstände zu Zuchtmeister Skrange in der sengenden Schlucht.","","Die einzigen Informationen die Ihr habt sind: Die Schmiedewindform ist ein Schmiedewerkzeug welches von Schmieden verwendet wird und das Ausguckhandfernrohr ist ein unverzichtbares Werkzeug für Spähposten."}}
D[7729] = {"STELLE ZU VERGEBEN: Erledige die Konkurrenz",{"Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Skrange in der sengenden Schlucht zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[7730] = {"Zukk'ash-Plage",{"Bringt Hadoken Flinkschreiter im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer."}}
D[7731] = {"Zornstachel",{"Besiegt Zornstachel in der verwundenen Tiefe und bringt seine Drüsen zu Hadoken Flinkschreiter im Camp Mojache in Feralas zurück."}}
D[7732] = {"Bericht über die Zukk'ash",{"Bringt den Bericht über die Zukk'ash aus Camp Mojache zu Zilzibin Tomtom. Er wohnt in der Gasse von Orgrimmar."}}
D[7733] = {"Beste Qualität",{"Bringt Pratt McGrubben in der Mondfederfeste in Feralas 10 Wutschrammyetibälge."}}
D[7734] = {"Beste Qualität",{"Bringt Jangdor Flinkschreiter im Camp Mojache in Feralas 10 Wutschrammyetibälge."}}
D[7735] = {"Makelloser Yetibalg",{"Bringt Pratt McGrubben in der Mondfederfeste in Feralas den makellosen Yetibalg."}}
D[7736] = {"Nachschub an feurigem Fluxus: Königsblut",{"Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, <Volk>. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.","","Ich brauche Euch, um mir folgendes zu beschaffen:","","*Incendosaurierschuppen.","","*Königsblut.","","*Kohle.","","Ich nehme alles was Ihr kriegen könnt!","","Und seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?"}}
D[7737] = {"Erlangte Anerkennung",{"Ihr habt Euch erfolgreich in der Hierarchie der Bruderschaft hochgearbeitet, <Volk>. Wir haben begonnen, Euch mit Wohlwollen zu betrachten. Eine respektable Leistung!","","Wenn Ihr Euch weiteren Respekt und Arbeit verschaffen wollt, hört genau zu.","","Wir können den feurigen Fluxus noch weiter veredeln, indem wir ihm simple Dunkeleisenrückstände hinzufügen. Diese Rückstände sind hauptsächlich in den Blackrocktiefen zu finden.","","Bringt mir alle Dunkeleisenrückstände, die Ihr finden könnt!"}}
D[7738] = {"Perfekter Yetibalg",{"Bringt Jangdor Flinkschreiter im Camp Mojache in Feralas den makellosen Yetibalg."}}
D[7741] = {"Lob des Smaragdkreises <NYI> <TXT>"}
D[7761] = {"Schwarzfausts Befehl",{"Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.","","Dem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen."}}
D[7781] = {"Der Herrscher des Schwarzfels",{"Bringt Hochlord Bolvar Fordragon in Sturmwind den Kopf von Nefarian."}}
D[7782] = {"Der Herrscher des Schwarzfels",{"Reist in nach Sturmwind in das Tal der Helden und sprecht mit Feldmarschall Afrasiabi."}}
D[7783] = {"Der Herrscher des Schwarzfels",{"Bringt Thrall in Orgrimmar den Kopf von Nefarian."}}
D[7784] = {"Der Herrscher des Schwarzfels",{"Sprecht mit Hochfürst Saurfang in Orgrimmar. Er wartet im Tal der Stärke auf Euch."}}
D[7785] = {"Untersuchung des Gefäßes",{"Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian."}}
D[7786] = {"Donneraan der Windsucher",{"Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian in Silithus die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen."}}
D[7787] = {"Donnerzorn erwache!",{"Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge."}}
D[7788] = {"Besiegt die Eindringlinge!",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück."}}
D[7789] = {"Bezwingt die Eindringlinge der Silberschwingen",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück."}}
D[7791] = {"Spendet Wolle",{"Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Stormwind einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.","","Wenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen."}}
D[7792] = {"Spendet Wolle",{"Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Darnassus einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.","","Wenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen."}}
D[7793] = {"Spendet Seide",{"Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.","","Eine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen."}}
D[7794] = {"Spendet Magiestoff",{"Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Stormwind nicht unbeachtet bleiben würde!","","Wenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen."}}
D[7795] = {"Spendet Runenstoff",{"<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.","","Solltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter."}}
D[7796] = {"Noch mehr Runenstoff",{"Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber Stormwind erhaltet.","","Wann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen."}}
D[7797] = {"Dimensionszerfetzer: Ewige Warte"}
D[7798] = {"Spendet Seide",{"Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.","","Eine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen."}}
