D[8078] = {"Symbole der Macht: Der Gürtel des Vollstreckers",{"Bringt einen urzeitlichen Hakkarigurt zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.","","Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8079] = {"Symbole der Macht: Die Brustplatte des Vollstreckers",{"Bringt einen urzeitlichen Hakkarikosak zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.","","Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8080] = {"Die Ressourcen des Arathibeckens",{"Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht."}}
D[8081] = {"Noch mehr Vorratskisten"}
D[8101] = {"Der Stein des Kajaro",{"<Volk>, der Stein, der von diesem Talisman umrahmt wird, kommt vom Berg Kajaro in den südlichen Meeren. Das Gebiet rund um den Berg Kajaro wird von Unbeständigkeit geplagt; insbesondere durch heftige und oft auch magische Vulkanausbrüche.","","Je stärker Euer Bund mit den Trollen Zandalars wird, umso mächtiger wird dieser Stein. Nutzt die Macht des Steins, um unsere Feinde zu vernichten. Seid wie der Berg: schnell, explosiv, tödlich..."}}
D[8102] = {"Der Stein des Kajaro",{"Willkommen zurück, <Klasse>. Ich kann sehen, dass der Stein häufig Anwendung fand. Viele unserer Feinde wurden Opfer Eurer jenseitigen Fähigkeiten. Ihr Leiden war groß. Es ist an der Zeit, dass ich die Macht des Steins verstärke. Gebt ihn mir."}}
D[8103] = {"Der Stein des Kajaro",{"Die Hakkari fürchten Euch, <Name>. Sie sprechen von Grausamkeiten, die sie bis jetzt nur ihrem gesichtslosen Gott zutrauten. Ihr habt sie mit der Macht des Kajaro gezeichnet. Sie kennen jetzt die beiden Seiten der Furcht.","","Es ist an der Zeit, den Stein noch weiter zu stärken. Gebt mir den Talisman."}}
D[8104] = {"Das Juwel von Kajaro",{"Gebt mir den Talisman, <Name>. Ich muss Euch etwas zeigen."}}
D[8105] = {"Die Schlacht um das Arathibecken!",{"Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht."}}
D[8106] = {"Kezans Schmach",{"Bitte nehmt diesen Talisman, <Klasse>. Nutzt seine Macht, um unsere gemeinsamen Feinde niederzuschmettern.","","Seid Euch bewusst, dass Ihr ein Stück Geschichte um Euren Hals tragt. Kezan war einst ein großes Territorium des Imperiums von Zandalar. Doch im Laufe der Zeit zwang der schändliche Einfluss der Goblin-Handelsfürsten meine stolzen Brüder und Schwestern, Kezan den Rücken zu kehren.","","Kezan beherbergt jetzt Undermine, die Hauptstadt der Goblins; doch wisset, dass sie einst wahre Größe ausstrahlte. Noch heute gilt Kezan meinem Volk als heiliges Land."}}
D[8107] = {"Kezans Schmach",{"Ihr habt Euch bei den Trollen Zandalars Ehre verdient, <Name>. Mit Ehre kommt auch Entlohnung, Freundschaft, Verbundenheit...","","Gebt mir den Talisman, damit ich seine Macht verstärken kann."}}
D[8108] = {"Kezans Schmach",{"Ich bin für euch bereit, <Klasse>. Noch einmal werde ich Euren Talisman verstärken. Ich bitte Euch nur mit Eurer Zerstörung von Hakkar und seinen Dienern fortzufahren.","","Gebt mir den Talisman."}}
D[8109] = {"Kezans unaufhaltsame Schmach",{"Ruft Eure Dämonen hervor, <Klasse>. Lasst sie in der Energie von Kezans Schmach schwelgen. Führt sie auf's Schlachtfeld! Vernichtet den Feind!","","Ja... die Zeit ist gekommen, um Kezans Schmach endgültig zu verstärken. Gebt mir den Talisman."}}
D[8110] = {"Verzauberter Südmeertang",{"Unglaublich! Ihr habt sie gefunden! Ihr seid ein wahrer Held, <Name>!","","Das ist eine gute Sache, denn ich habe die Schrifttafeln gelesen, die Ihr mir zuvor gebracht habt, und nach dem, was ich herausgefunden habe... tja, da werden wir wohl einen Helden brauchen, der aufhält, was kommt..."}}
D[8111] = {"Verzauberter Südmeertang",{"Hey Ihr! Gut Euch wieder zu sehen. Der Stamm spricht von Eurer Vernichtung der Hakkari und all dem. Molthor hat mir zugesichert, dass ich Eurem Talisman mehr Mojo hinzufügen kann. Gebt ihn einfach her und Maywiki wird ihn besser machen."}}
D[8112] = {"Verzauberter Südmeertang",{"Wie ist der Talisman? Es sieht aus, als wäre es an der Zeit dem Tang etwas mehr Magie und Mojo zuzufügen. Er benötigt eine kleine Auffrischung. Gebt in her und Maywiki wird's schon machen."}}
D[8113] = {"Reiner verzauberter Südmeertang"}
D[8114] = {"Kontrolliert vier Stützpunkte",{"Betretet das Arathibecken, erobert und kontrolliert gleichzeitig vier Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Lichtmark in der Zuflucht zurück."}}
D[8115] = {"Kontrolliert fünf Stützpunkte",{"Kontrolliert gleichzeitig fünf Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Lichtmark in der Zuflucht zurück."}}
D[8116] = {"Vision von Voodress",{"Ihr und Maywiki haben etwas gemeinsam. Wir sind beide Schamanen! Auch wenn Maywiki eher geheimnisvoll ist und Ihr vielmehr grob daher kommt. Trotzdem, wir wissen beide von der Macht der Geister.","","Ich gebe Euch diese Kugel als Geschenk, tragt sie um den Hals. Schaut tief in sie hinein und seht die Stadt von Voodress in den südlichen Meeren! Lasst sie Eure Geister beflügeln!"}}
D[8117] = {"Vision von Voodress",{"Sha-mann! Maywiki macht Witze!","","<Maywiki lacht.>","","So, Ihr habt also die Geister und Elemente gegen unsere Feinde in Zul'Gurub eingesetzt, hä? Die Geister seien gelobt!","","Maywiki wird Eure Kugel aufpolieren. Gebt sie mir, <Name>."}}
D[8118] = {"Vision von Voodress",{"Gute Neuigkeiten, <Name>. Molthor hat Lob über Euch verkündet. Er erzählte, wie Ihr Euch in einen wahren Helden der Zandalar verwandelt habt.","","Er wies mich auch an, Eure Kugel noch etwas aufzupolieren! Gebt sie her, damit Maywiki die Vision noch weiter aufhellen kann."}}
D[8119] = {"Die unversehrte Vision von Voodress",{"<Maywiki zeigt auf Euren Talisman.>","","Schaut, <Name>! Er ist zum Leben erwacht. Die Geister tanzen um die Kugel.","","Gebt ihn Maywiki, damit sie die letzte Anpassung vornehmen kann."}}
D[8120] = {"Die Schlacht um das Arathibecken!",{"Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe im Arathibecken und kehrt dann zu Todesmeister Dunkels in Hammerfall zurück."}}
D[8121] = {"Erobert vier Stützpunkte",{"Haltet vier Stützpunkte zur selben Zeit im Arathibecken und kehrt danach zu Todesmeister Dunkels nach Hammerfall zurück."}}
D[8122] = {"Erobert fünf Stützpunkte",{"Haltet fünf Stützpunkte zur selben Zeit im Arathibecken und kehrt danach zu Todesmeister Dunkels nach Hammerfall zurück."}}
D[8123] = {"Zerschlagt die Versorgungslinien Arathors",{"Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall."}}
D[8124] = {"Noch mehr Vorratskisten"}
D[8141] = {"Zandalarischattentalisman",{"Ihr macht rasch Fortschritte, <Klasse>. Vielleicht ist es an der Zeit Euch in Shera Ali'kh einzuweihen - zandalarianisch für die Hand des Todes. Tausende von Jahren übernahmen wir die Rolle der Meuchelmörder für das Imperium der Zandalar. Zu lange saßen wir untätig herum und erlaubten es den Hakkari an Macht zu gewinnen. Noch einmal stehen wir Hakkar gegenüber, aber diesmal ohne die Unterstützung einer vereinten Trollfront. Ihr und Eure Verbündeten müssen uns dabei helfen den Blutgott und seine Diener zu vernichten!","","Tragt diesen Talisman und lasst ihn Euch bei Euren Taten unterstützen."}}
D[8142] = {"Zandalarischattentalisman",{"Ich spüre, dass Ihr zahlreiche Todesopfer unter den Hakkari gefordert habt, <Name>. Ihr tragt den Geruch ihres Mojos.","","Ich vermute, dass Euch der Schattentalisman beim Ausmerzen behilflich war? Gebt ihn mir, ich werde seine Macht noch einmal verstärken."}}
D[8143] = {"Zandalarischattentalisman",{"Beeindruckend, <Name>. Ihr habt ein Händchen für's Töten, so etwas ist mir schon seit Jahren nicht mehr untergekommen. Sogar Molthor hat von Euren Taten für Zandalar Notiz genommen. Lasst mich Euren Talisman weiter verstärken, es ist an der Zeit... gebt ihn mir."}}
D[8144] = {"Zandalarischattentalisman der Beherrschung",{"Er sehnt sich nach Wachstum, <Name>. Der Talisman hat all das in sich aufgenommen, was Ihr vollbracht habt. Die unzähligen Trollkadaver, die Zul'Gurub beschmutzen, haben seine Macht angeheizt. Gebt ihn mir und ich werde ihn endgültig verstärken."}}
D[8145] = {"Die Mahlstromranke",{"Unter den Zandalarianern wird der Stand des Jägers hoch verehrt. Die mächtigsten unserer <Klasse> reisen bis an den Rand des Maelstroms, um ihre Entschlossenheit unter Beweis zu stellen.","","Aus dem tiefsten Herzen der See, ernten sie eine seltene Seetangart, die Maelstromranke. Die Seetangstränge werden in einen Talisman gewoben, welcher anschließend verzaubert wird, um die Treffsicherheit und Macht des Trägers zu verstärken.","","Ich werde Euch jetzt die erste Maelstromranke in einen Talisman einweben. Wenn Euer Bund mit den Zandalar stärker wird, werde ich Euch mehr Ranken in den Talisman weben und so dessen Macht verstärken."}}
D[8146] = {"Die Mahlstromranke",{"Ah, <Name>, es ist schön Euch mal wieder zu riechen.","","Ihr müsst meinen Humor entschuldigen, zuweilen nimmt er abstruse Formen an.","","Ich fühle, dass Ihr unter unseren Feinden Angst und Schrecken verbreitet habt. Hakkars Gefolgsleute sprechen Euren Namen nur noch im Zorn aus. Hervorragend.","","Ihr habt es verdient, dass ich Euch eine weitere Ranke in Euren Talisman einwebe. Gebt ihn mir."}}
D[8147] = {"Die Mahlstromranke",{"Selbst jetzt höre ich noch, wie Eure Geschosssalven unter Euren Feinden ein Blutbad anrichten. Ich vernehme das Echo der Todesqualen in ihren Schreien.","","Ich habt Euch wahrlich einen Namen unter den Trollen der Zandalar gemacht, <Name>. Wir sind Euch für Eure Taten sehr dankbar.","","Gebt mir Euren Talisman, damit ich eine weitere Ranke hineinweben kann."}}
D[8148] = {"Mahlstroms Zorn",{"<Name>, Molthor brachte uns eine Botschaft von König Rastakhan. Der königliche Hof ist beeindruckt davon, wie sehr Ihr die Hakkaristreitkräfte dezimiert habt. Ich bin ermächtigt worden, die letzte Verstärkung in Euren Talisman einzuweben. Gebt ihn mir."}}
D[8149] = {"Die Ehrung eines Helden",{"Reist zu Uthers Grabmal in den westlichen Pestländern und benutzt Uthers Tribut an seiner Statue. Kehrt zu Wagner Hammerschlag außerhalb von Eisenschmiede zurück, bevor das Erntedankfest endet."}}
D[8150] = {"Die Ehrung eines Helden",{"Reist zu Groms Monument im Dämonensturz im Eschental und benutzt Groms Tribut am Fuße seines Monuments. Kehrt zu Javnir Nashak außerhalb von Orgrimmar zurück, bevor das Erntedankfest endet."}}
D[8151] = {"Der Talisman des Jägers",{"Sprecht mit Ogtinc in Azshara."}}
D[8153] = {"Gehörnte Renner",{"Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath."}}
D[8154] = {"Die Ressourcen des Arathibeckens",{"Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht."}}
