D[8193] = {"Anglermeister"}
D[8194] = {"Anglerlehrling",{"Wir haben zwar schon einen Gewinner ermittelt, aber ich kaufe Euch dennoch Eure restlichen Leckerfische ab. Ich zahl' Euch einen angemessenen Preis, na, was sagt Ihr!"}}
D[8195] = {"Münzen der Razzashi, Hakkari und zulianische Münzen",{"Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.","","Es gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an."}}
D[8196] = {"Essenzmangos",{"Die extrem wirksamen Essenzmangos wachsen auf vielen Inseln der südlichen Meere. Eine einzelne Mango erfrischt denjenigen, der davon isst, körperlich wie auch geistig. Solltet Ihr noch nie eine gekostet haben, dann erweist Ihr Euch damit keinen Dienst!","","Hier auf der Insel verfügen wir über einen ausreichend großen Vorrat, um Euch ein paar davon im Austausch gegen eine zandalarianische Ehrenmünze geben zu können. Sprecht mit Vinchaxa, wenn Ihr wissen wollt, wie Ihr an Ehrenmünzen gelangt; ansonsten, lasst uns gleich Geschäfte machen!"}}
D[8201] = {"Die Schädelsammlung",{"Reiht die Köpfe der 5 Kanalisierer auf der heiligen Kordel aneinander. Bringt dann die Trollschädelsammlung zu Exzhal auf der Insel Yojamba."}}
D[8221] = {"Besonderer Fisch - Kiefers Engelfisch",{"*Surrr* *PLIIING*nnIch suche besondere Fische, um sie für Fischereimeister Bluegill zu katalogisieren. Bringt mir einen Keefers Engelfisch und ich werde Euch eine feine Belohnung zuteil werden lassen.","","*KLING**Bzzzz*"}}
D[8222] = {"Leuchtendes Skorpidblut",{"In all der Zeit, in der ich nun mit dem Jahrmarkt reise, habe ich viel über unsere Kunden gelernt. Eine Kostprobe meiner Weisheit gefällig? Kunden lieben alles, was leuchtet. Es ist völlig egal was! Ihr könntet ein abgebrochenes Stuhlbein nehmen und es zum Leuchten bringen und schon würde jedes Kind von egal wieweit her kommen, nur um darauf einen Blick werfen zu können!","","Tja <Name>, ich brauche also leuchtendes Skorpidblut. Bei den Skorpiden in Silithus, in den verwüsteten Landen oder der brennenden Steppe solltet Ihr fündig werden."}}
D[8223] = {"Mehr leuchtendes Skorpidblut"}
D[8224] = {"Besonderer Fisch - Dezianischer Königinnenfisch"}
D[8225] = {"Besonderer Fisch - Braunells blaugestreifter Flitzerfisch"}
D[8227] = {"Nats Maßband",{"Bringt Nats Maßband zu Nat Pagle in den Düstermarschen zurück."}}
D[8228] = {"Könnte ich einen Flugzettel für den Angelwettbewerb bekommen?",{"Es wird diesen Sonntag einen Angelwettbewerb in Booty Bay geben! Hier sind die Regeln für den Wettbewerb, falls Ihr daran teilnehmen möchtet!"}}
D[8229] = {"Könnte ich einen Flugzettel für den Angelwettbewerb bekommen?",{"Es wird einen Angelwettbewerb in Booty Bay geben, diesen Sonntag! Hier sind die Regeln für Euch!"}}
D[8230] = {"Collins Test Quest"}
D[8231] = {"Wellenjagd",{"Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath."}}
D[8232] = {"Der grüne Drache",{"Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath."}}
D[8233] = {"Ein simples Anliegen",{"Sprecht mit Lord Jorach Rabenholdt im Rabenholdtanwesen."}}
D[8234] = {"Die versiegelte azurblaue Tasche",{"Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist."}}
D[8235] = {"Verschlüsselte Fragmente",{"Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente."}}
D[8236] = {"Der azurblaue Schlüssel",{"Bringt den azurblauen Schlüssel zu Lord Jorach Rabenholdt."}}
D[8238] = {"Münzen der Gurubashi, Blutfratzen und Bleichborken",{"Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.","","Es gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an."}}
D[8239] = {"Münzen der Sandwüter, Schädelspalter und Blutskalpe",{"Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.","","Es gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im Tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an."}}
D[8240] = {"Ein Schmuckstück für Zanza",{"Zerstört jedes Schmuckstück der Hakkari, das Ihr in Zul'Gurub findet, am Altar von Zanza auf der Insel Yojamba. Sobald Ihr dies getan habt, sprecht ganz in der Nähe mit Vinchaxa."}}
D[8241] = {"Nachschub an feurigem Fluxus: Eisen",{"Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, <Volk>. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.","","Ich brauche Euch, um mir folgendes zu beschaffen:","","*Incendosaurierschuppen.","","*Eisenbarren.","","*Kohle.","","Ich nehme alles was Ihr kriegen könnt!","","Und seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?"}}
D[8242] = {"Nachschub an feurigem Fluxus: Schweres Leder",{"Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, <Volk>. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.","","Ich brauche Euch, um mir folgendes zu beschaffen:","","*Incendosaurierschuppen.","","*Schweres Leder.","","*Kohle.","","Ich nehme alles was Ihr kriegen könnt!","","Und seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?"}}
D[8243] = {"Zanzas wirksame Tränke",{"Mit Eurem verbesserten Ruf innerhalb unseres Stammes, bekommt Ihr auch Zugang zu einigen unserer wirksamsten Tränke. Nehmt Euch in Acht... diese Gebräue sind stark im Mojo - gesegnet von Zanza und für Abenteurer jeglicher Herkunft gemacht!","","Ich lasse Euch einen aus den drei Tränken, die ich anbiete, auswählen; im Gegenzug verlange ich eine zandalarianische Ehrenmünze. Seid Euch im Klaren, dass nur jeweils die Effekte eines Tranks zu einer beliebigen Zeit durch Euren Geist jagen können.","","Lasst mich wissen, wenn Ihr zum Tauschhandel bereit seid!"}}
D[8246] = {"Das Siegel der Zandalar",{"Für jemanden, der bei den Zandalar so angesehen ist wie Ihr <Name>, habe ich etwas sehr Besonderes. Direkt aus unserer Heimat in den südlichen Meeren... die Siegel der Zandalar! Diese Siegel werden zum Aufwerten eines beliebigen Schultergegenstands, den Ihr besitzt, verwendet. Solltet Ihr nach Macht, Mojo oder Gelassenheit suchen - dann habe ich genau das, was Ihr braucht!","","Ich gebe Euch ein Siegel Eurer Wahl im Austausch gegen fünfzehn zandalarianische Ehrenmünzen. Sobald Ihr die Münzen habt, können wir Geschäfte machen!"}}
D[8249] = {"Plunderkisten benötigt",{"Meine Schurken müssen ihre Fertigkeiten im Schlossknacken noch verbessern und ich brauche dafür noch Schlösser mit entsprechendem Schwierigkeitsgrad -- das Zeug, das Zan für uns herstellt, taugt lediglich für totale Anfänger.","","Ich sag' Euch was, wenn Ihr mir 5 schwere Plunderkisten besorgt, dann gebe ich Euch dafür die feinsten Wurfmesser, die in Schurkenkreisen bekannt sind.","","Ihr könnt die Kisten öffnen und durchstöbern, aber lasst wenigstens ein paar Münzen übrig... auch ein <Klasse>, der sich in Ausbildung befindet, braucht etwas Motivation."}}
D[8250] = {"Geschick der Magier",{"Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem."}}
D[8251] = {"Magischer Staub",{"Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben."}}
D[8252] = {"Die Koralle der Sirenen",{"Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem."}}
D[8253] = {"Vernichtet Morphaz",{"Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück."}}
D[8254] = {"Cenarische Hilfe",{"Sucht Ogtinc in Azshara auf."}}
D[8255] = {"Renner für einen höheren Zweck",{"Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."}}
D[8256] = {"Sekret des Untodes",{"Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."}}
D[8257] = {"Morphaz' Blut",{"Tötet Morphaz im Versunkenen Tempel von Atal'Hakkar und bringt Greta Mooshuf im Teufelswald sein Blut. Der Eingang zum Versunkenen Tempel liegt in den Sümpfen des Elends."}}
D[8258] = {"Die Bedrohung durch Schattensichel",{"Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.","","Bringt Schattensichels Kopf zu Sagorne Gratläufer im Tal der Weisheit in Orgrimmar."}}
D[8259] = {"Eine angemessenere Belohnung"}
D[8260] = {"Basisüberlebenspaket von Arathor"}
D[8261] = {"Standardüberlebenspaket von Arathor"}
D[8262] = {"Verbessertes Überlebenspaket von Arathor",{"Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, <Name>. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb des Arathibecken verwendet werden können.","","Bewährt Ihr Euch noch weiter im Arathibecken, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt."}}
D[8263] = {"Basisüberlebenspaket der Entweihten"}
D[8264] = {"Standardüberlebenspaket der Entweihten"}
D[8265] = {"Verbessertes Überlebenspaket der Entweihten",{"Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, <Name>. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb des Arathibecken verwendet werden können.","","Bewährt Ihr Euch noch weiter im Arathibecken, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn Ihr unser Wohlwollen erlangt habt, sowie Verbände, wenn Ihr Euch unseren Respekt verdient habt."}}
D[8266] = {"Aufopferungsabzeichen"}
D[8267] = {"Aufopferungsabzeichen"}
D[8268] = {"Aufopferungsabzeichen"}
D[8269] = {"Aufopferungsabzeichen"}
D[8271] = {"Held der Sturmlanzen",{"Als ein Held der Stormpike, dürft Ihr Euch eines dieser erst kürzlich geplün… äh, wiederentdeckten Schätze, aussuchen."}}
D[8272] = {"Held der Frostwölfe",{"Was ist das für ein Gefühl, <Name>? Wie fühlt es sich an, die Linien des Feindes zu zerschmettern und jeglichen Widerstand auszulöschen? Es ist ein gutes Gefühl, nicht wahr?","","Für Eure Heldentat habt Ihr eine große Belohnung verdient."}}
D[8273] = {"Orans Dankbarkeit",{"Ach das ist ja interessant! Ihr sagt, Ihr habt diese Schrifttafel auf einer kleinen, unbewohnten Insel nahe der Aussichtsklippen im Hinterland gefunden, <Klasse>? Wirklich äußerst interessant.","","Ich danke Euch für Eure Bemühungen in dieser Angelegenheit. Unsere dunkle Fürstin wird mit dieser Entdeckung sehr zufrieden sein. Erlaubt mir, Euch angemessen zu belohnen."}}
D[8275] = {"Die Rückeroberung von Silithus",{"Sprecht mit Windruferin Prachthorn auf Burg Cenarius in Silithus."}}
D[8276] = {"Die Rückeroberung von Silithus",{"Sprecht mit Windruferin Prachthorn auf Burg Cenarius in Silithus."}}
D[8277] = {"Tödliches Wüstengift",{"Beetix Wankelhupf von der Burg Cenarius in Silithus möchte, dass Ihr 8 Stachel von Steinpanzerskorpiden und 8 Giftzähne von Sandhuschern für sie sammelt. Kehrt zu ihr zurück, sobald Ihr diese Aufgabe erfüllt habt."}}
D[8278] = {"Noggles letzte Hoffnung",{"Beetix Wankelhupf von der Burg Cenarius in Silithus möchte, dass Ihr je 3 Stachel von Steinpanzerzangen und Steinpanzerschindern, sowie 3 Felspirschergiftzähne für sie sammelt."}}
D[8279] = {"Das Lexikon des Schattenhammerklans",{"Bringt Ortell dem Einsiedler in Silithus die drei Kapitel des Lexikons des Schattenhammerklans."}}
D[8280] = {"Sicherung der Versorgungslinien",{"Windruferin Prachthorn auf Burg Cenarius in Silithus möchte, dass Ihr 15 Baggerschläger tötet."}}
D[8281] = {"Verstärkte Sicherheit",{"Windruferin Prachthorn auf Burg Cenarius in Silithus möchte, dass Ihr 20 Baggerbrecher tötet."}}
D[8282] = {"Noggles verlorener Ranzen",{"Spürt Noggles Ranzen im südlichen Gebirge von Silithus auf und bringt ihn zu ihm, auf Burg Cenarius, zurück."}}
D[8283] = {"GESUCHT: Totenstachel, Terror der Wüste",{"Bringt Totenstachels Zange zu Vish Kozus, Hauptmann der Wache."}}
D[8284] = {"Das Geheimnis des Schattenhammerklans",{"Geologin Lerchenbann auf Burg Cenarius in Silithus möchte, dass Ihr ihr 8 Schrifttafelfragmente des Schattenhammerklans bringt."}}
D[8285] = {"Der Deserteur",{"Bringt die wiederhergestellte Schrifttafel zu Ortell dem Einsiedler in Silithus."}}
D[8286] = {"Was uns morgen erwartet",{"Reist zu den Höhlen der Zeit in Tanaris und findet Anachronos, Nachkomme Nozdormus."}}
D[8287] = {"Ein teuflischer Plan",{"Bringt Kommandant Mar'alith die entschlüsselte Abschrift der Schrifttafel."}}
D[8288] = {"Nur einer kann sich erheben",{"Bringt Brutwächter Dreschbringers Kopf zu Baristolth der Sandstürme in die Burg Cenarius in Silithus."}}
D[8289] = {"Verdienstabzeichen"}
D[8290] = {"Besiegt die Eindringlinge!",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück."}}
D[8291] = {"Besiegt die Eindringlinge!",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück."}}
D[8292] = {"Verdienstabzeichen"}
D[8293] = {"Ehrenabzeichen"}
D[8294] = {"Bezwingt die Eindringlinge der Silberschwingen",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück."}}
D[8295] = {"Bezwingt die Eindringlinge der Silberschwingen",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück."}}
D[8296] = {"Ehrenabzeichen"}
D[8297] = {"Die Ressourcen des Arathibeckens",{"Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht."}}
D[8298] = {"Noch mehr Vorratskisten"}
D[8299] = {"Zerschlagt die Versorgungslinien Arathors",{"Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall."}}
D[8300] = {"Noch mehr Vorratskisten"}
D[8301] = {"Der Pfad des Gerechten",{"Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt."}}
D[8302] = {"Die Hand der Gerechtigkeit",{"Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt."}}
D[8303] = {"Anachronos",{"Sucht nach Anachronos bei den Höhlen der Zeit in Tanaris."}}
D[8304] = {"Liebste Natalia",{"Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr die Bewohner von Bronzebarts Lager befragt. Das Lager befindet sich südlich von Burg Cenarius.","","Kehrt zu Kommandant Mar'alith zurück, wenn Ihr die benötigten Informationen gesammelt habt."}}
D[8305] = {"Lang Vergessenes",{"Sucht die Kristallträne in Silithus und blickt in ihr Innerstes."}}
D[8306] = {"Der Schlund des Wahnsinns",{"Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr seine geliebte Natalia wiederfindet. Die von Euch gesammelten Informationen deuten darauf hin, dass Ihr sie im Bau des Regalschwarms im Süden finden könntet.","","Sprecht noch einmal mit den Zwergen in Bronzebarts Lager, bevor Ihr Euch in den Schwarmbau begebt. Ihr Wissen könnte sich als hilfreich erweisen und sicherlich, haben sie noch einige Aufgaben für Euch.","","Und <Name>, denkt an die Worte des Kommandanten: \"Tut, was Ihr tun müsst...\""}}
D[8307] = {"Wüstenrezept",{"Haltet beim Lager des Schattenhammerklans westlich von Burg Cenarius nach Informationen zum Zubereiten von Sandwurmfleisch Ausschau."}}
D[8308] = {"Der verlorene Brief von Brann Bronzebart",{"Liefert Brann Bronzebarts verlorenen Brief in Bronzebarts Lager im südlichen Silithus ab."}}
D[8309] = {"Glyphenjagd",{"Rutgar Glyphenschnitzer in Bronzebarts Lager in Silithus möchte, dass Ihr in den Bau des Ashischwarms, Bau des Zoraschwarms und Bau des Regalschwarms eindringt und dort Abpausbilder von den glyphenverzierten Kristallen anfertigt.","","Benutzt das Abschriftenset für Geologen, um Abpausbilder der uralten Glyphen herzustellen. Kehrt nach Abschluss der Aufgabe zu Rutgar Glyphenschnitzer zurück."}}
D[8310] = {"Knackt den Kode",{"Frankal Steinsteg in Bronzebarts Lager in Silithus möchte, dass Ihr ihm jeweils ein Silithidengehirn des Zoraschwarms, Ashischwarms und des Regalschwarms bringt. Kehrt nach der Erfüllung Eurer Aufgabe zu Frankal zurück."}}
D[8311] = {"Schlotternachtssüßigkeiten für Jesper!",{"Sprecht mit den Gastwirten in Sturmwind, Eisenschmiede und Darnassus, sowie mit Talvash del Kissel in Eisenschmiede. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.","","Kehrt zu Jesper ins Waisenhaus von Sturmwind mit einem Marzipan aus Darnassus, einer Kaugummikugel aus Gnomeregan, Nugat aus Sturmwind und einem Pfefferminzbonbon aus Eisenschmiede zurück."}}
D[8312] = {"Schlotternachtssüßigkeiten für Spuks!",{"Sprecht mit den Gastwirten in Orgrimmar, Unterstadt und Donnerfels, sowie mit Kali Remik in Sen'jin. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.","","Kehrt zu Spuks ins Waisenhaus von Orgrimmar mit einem Marzipan aus Donnerfels, einer Kaugummikugel der Dunkelspeere, Nugat aus Orgrimmar und einem Pfefferminzbonbon aus Unterstadt zurück."}}
D[8313] = {"Geteiltes Wissen",{"Bringt die ausgerissene Rezeptseite zu Calandrath ins Gasthaus der Burg Cenarius."}}
D[8314] = {"Des Rätsels Lösung",{"Rutgar Glyphenschnitzer in Bronzebarts Lager möchte, dass Ihr Geologin Lerchenbann auf Burg Cenarius in Silithus das glyphenverzierte Kristallprisma bringt."}}
D[8315] = {"Die Anrufung",{"Geologin Lerchenbann auf Burg Cenarius in Silithus möchte, dass Ihr ihr den Kristallentriegelungsmechanismus vom Abgesandten der Qiraji beschafft.","","Nehmt die Glyphen der Anrufung, begebt Euch zu den Knochen von Grakkarond südlich von Burg Cenarius und zeichnet sie dort in den Sand. Sollte der Abgesandte der Qiraji erscheinen, tötet ihn und nehmt den Kristallentriegelungsmechanismus an Euch. Kehrt anschließend zu Geologin Lerchenbann zurück.","","Für diese Aufgabe werdet Ihr eine kleine Armee benötigen, <Name>!"}}
D[8316] = {"Kriegsausrüstung",{"Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.","","Sollte diese… diese Prophezeiung jemals wahr werden…","","Das könnte das Ende für unser aller Zukunft bedeuten.","","Diese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein."}}
D[8317] = {"Küchengehilfe",{"Calandrath von der Burg Cenarius braucht 10 geräucherte Wüstenknödel."}}
D[8318] = {"Geheime Nachrichten",{"Bringt Bor Wildmähne auf Burg Cenarius 10 verschlüsselte Schattenhammertexte."}}
D[8319] = {"Verschlüsselte Schattenhammertexte",{"Bringt mir weitere Texte. Es dauert nicht mehr lange, und wir haben die Twilight-Hammer aus Silithus vertrieben."}}
D[8320] = {"Geolords des Schattenhammers",{"Tötet 10 Geolords des Schattenhammers und kehrt anschließend zu Huum Wildmähne auf Burg Cenarius zurück."}}
D[8321] = {"Vyral der Üble",{"Bringt Vyrals Siegelring zu Huum Wildmähne auf Burg Cenarius."}}
D[8322] = {"Faule Eier",{"Werft die faulen Eier in den großen Braukessel im Gasthaus von Süderstade."}}
D[8323] = {"Wahrer Glauben",{"Ortell der Einsiedler möchte, dass Ihr ihm 10 verschlüsselte Schattenhammertexte beschafft."}}
D[8324] = {"Fester Glauben",{"Konntet Ihr noch mehr verschlüsselte Texte finden? Die Entschlüsselung wird noch eininge Zeit brauchen, also bringt mir ruhig einen großen Stapel Texte."}}
D[8325] = {"Rückeroberung der Insel der Sonnenwanderer",{"Tötet 8 Manawyrm; sie halten sich rund um die brennenden Kristalle auf, die man nahe des Turms und des Vorbaus findet. Kehrt zu Magistrix Erona beim Turm auf der Insel der Sonnenwanderer zurück, sobald Ihr Eure Aufgabe erfüllt habt."}}
D[8326] = {"Bedauerliche Maßnahmen",{"Sammelt 8 Luchshalsbänder von erlegten Bachtatzenluchsen und Bachtatzenjungen ein. Kehrt zu Magistrix Erona auf der Insel der Sonnenwanderer zurück, sobald Ihr Eure Aufgabe erfüllt habt."}}
D[8327] = {"Berichterstattung an Lanthan Perilon",{"Sprecht mit Lanthan Perilon auf der Insel der Sonnenwanderer. Er steht in der Nähe des Pfads, der vom Sonnenturm Richtung Westen verläuft."}}
D[8328] = {"Ausbildung zum Magier",{"Sprecht mit Julia Sonnensturm - der Magielehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer."}}
D[8329] = {"Ausbildung zum Krieger",{"Sprecht mit Delios - dem Kriegerlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer."}}
D[8330] = {"Solanians Habe",{"Sammelt Brunnenbehüter Solanians Seherkugel, seine Rolle der Geißelmagie und sein Tagebuch ein. Ihr findet die Gegenstände auf der Insel der Sonnenwanderer bei dem Tümpel, dem Brunnen und bei einem der brennenden Kristalle. Bringt sie zu dem Brunnenbehüter oben im Sonnenturm auf der Insel der Sonnenwanderer, sobald Ihr alle gefunden habt."}}
D[8331] = {"Aurel Goldblatt",{"Sprecht mit Aurel Goldblatt auf Burg Cenarius."}}
D[8332] = {"Fürsten des Rates",{"Bringt Aurel Goldblatt auf Burg Cenarius 1 großen glänzenden Splitter und 3 Abyssische Wappen."}}
D[8333] = {"Das Standesmedaillon",{"Falls Ihr ein weiteres Standesmedaillon eines Twilightkultisten braucht, helfe ich Euch gerne weiter. In jedem Fall benötige ich jedoch einen weiteren glänzenden Splitter und einige abyssische Wappen…"}}
D[8334] = {"Aggressivität",{"Tötet 7 Borklinge und 7 wilde Borklinge. Kehrt dann zu Lanthan Perilon auf der Insel der Sonnenwanderer zurück."}}
D[8335] = {"Felendren der Verbannte",{"Tötet 8 Arkangespenster, 2 besudelte Arkangespenster und Felendren den Verbannten. Ihr findet sie in der Akademie von Falthrien. Bringt Felendrens Kopf zu Lanthan Perilon auf der Insel der Sonnenwanderer."}}
D[8336] = {"Für eine Handvoll Fragmente",{"Sammelt 6 Arkanspäne und bringt sie zu Arkanist Ithanas auf der Insel der Sonnenwanderer. Derartige Fragmente findet man bei allen Mana benutzenden Kreaturen auf der Insel."}}
D[8338] = {"Besudelter Arkanspan",{"Bringt den besudelten Arkanspan zu Arkanist Helion beim Vorbau des Sonnenturms auf der Insel der Sonnenwanderer."}}
D[8339] = {"Royalty of the Council <NYI> <TXT> UNUSED",{"Bringt die Gegenstände zu Aurel Goldblatt in der Burg Cenarius"}}
D[8340] = {"Siegelring des Schattenhammers"}
D[8341] = {"Lords des Rates",{"Bringt Aurel Goldblatt auf Burg Cenarius 5 große glänzende Splitter und 3 abyssische Siegel."}}
D[8342] = {"Herrschaftsring des Schattenhammerklans"}
D[8343] = {"Goldblatts Entdeckung",{"Sprecht mit Aurel Goldblatt auf Burg Cenarius."}}
D[8344] = {"Schlüssel zur Macht",{"Bring 4 Essenzen eines Gespenstes und 1 Essenz eines besudelten Gespenstes zu Beschwörer Teli'Larien beim Sonnenturm auf der Insel der Sonnenwanderer."}}
D[8345] = {"Der Schrein von Dath'Remar",{"Lest die Tafel am Schrein von Dath'Remar und kehrt anschließend zu Brunnenbehüter Solanian beim Sonnenturm auf der Insel der Sonnenwanderer zurück."}}
D[8346] = {"Unstillbarer Durst",{"Verwendet die Fähigkeit Manadurst sechsmal auf Kreaturen, die über Mana verfügen und kehrt anschließend zu Arkanist Helion zurück."}}
D[8347] = {"Unterstützung für die Kundschafter",{"Sprecht mit Kundschafterin Alarion nahe der Brücke, die in den Süden der Insel der Sonnenwanderer führt."}}
D[8348] = {"Siegel der Fürsten",{"Bringt Bor Wildmähne auf Burg Cenarius das abyssische Siegel."}}
D[8349] = {"Bor Wildmähne",{"Sprecht mit Bor Wildmähne auf Burg Cenarius."}}
D[8350] = {"Erfolgreiche Lieferung",{"Bringt Eronas Päckchen zu Gastwirtin Delaniel im Gasthaus beim Falkenplatz im Immersangwald."}}
D[8351] = {"Bor möchte Euch sprechen",{"Sprecht mit Bor Wildmähne auf Burg Cenarius."}}
D[8352] = {"Szepter des Rates",{"Bringt Bor Wildmähne auf Burg Cenarius ein abyssisches Szepter."}}
D[8353] = {"Hühnchengegacker für ein Pfefferminzbonbon",{"Spielt Gastwirt Feuerbräu ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Eisenschmiede geben!"}}
D[8354] = {"Hühnchengegacker für ein Pfefferminzbonbon",{"Spielt Gastwirt Norman ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Unterstadt geben!"}}
D[8355] = {"Kaugummikugelexpress",{"Ahmt für Talvash del Kissel einen Zug nach und er wird Euch dafür eine Kaugummikugel aus Gnomeregan geben!"}}
D[8356] = {"Muskelspiel für Nugat",{"Ihr müsst vor Gastwirtin Allison angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Sturmwind gibt!"}}
D[8357] = {"Tanzen für Marzipan",{"Tanzt für Gastwirtin Saelienne und Ihr werdet im Gegenzug etwas von dem Marzipan aus Darnassus bekommen!"}}
D[8358] = {"Kaugummikugelexpress",{"Ahmt für Kali Remik einen Zug nach und sie wird Euch dafür eine Kaugummikugel der Dunkelspeere geben!"}}
D[8359] = {"Muskelspiel für Nugat",{"Ihr müsst vor Gastwirtin Gryshka angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Orgrimmar gibt!"}}
D[8360] = {"Tanzen für Marzipan",{"Tanzt für Gastwirtin Pala und Ihr werdet im Gegenzug etwas von dem Marzipan aus Donnerfels bekommen!"}}
D[8361] = {"Abyssische Kontakte",{"Bor Wildmähne auf Burg Cenarius in Silithus möchte, dass Ihr einen abyssischen Templer vernichtet und ihm dessen abyssisches Wappen als Beweis für Eure Tat bringt."}}
D[8362] = {"Abyssische Wappen",{"Ihr habt Eure Fähigkeiten im Kampf mehrfach bewiesen, <Name>. Wir müssen den Druck auf die Twilight-Hammer weiter aufrecht erhalten. Zieht los und bekämpft weitere abyssische Templer. Eure Mühen sollen nicht umsonst sein, und ich werde Euch mit einigen der Sachen entlohnen, die Huum und ich in der Schlacht erbeutet haben."}}
D[8363] = {"Abyssische Siegel",{"Ihr habt bewiesen, dass Ihr mehr als fähig seid, es mit einem abyssischen Fürsten aufzunehmen, <Name>. Ich fördere gerne jemanden, der sich als so tapfer erweist. Bringt mir mehr Siegelringe und ich werde Euch reichlich belohnen."}}
D[8364] = {"Abyssische Szepter",{"Ihr habt all meine Erwartungen bei weitem übertroffen, <Name>. Ihr habt Euch Gegnern gestellt, bei denen Huum und ich lange und gründlichst über einen Angriff nachdenken würden. Das Beste, was ich in dieser Sache wohl tun kann, ist, Eure Bemühungen im Kampf gegen die Twilight-Hammer und ihre Oberanführer auch weiterhin zu belohnen. Bringt mir noch mehr abyssische Szepter und ich werde mein Bestes tun, um Euch gebührend zu entlohnen."}}
D[8365] = {"Piratenhüte Ahoy!",{"Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin beim Dampfdruckpier in Tanaris."}}
D[8366] = {"Gaunerei und Erpressung im Südmeer",{"Sicherheitschef Bilgenritzel beim Dampfdruckpier in Tanaris beauftragt Euch, 10 Piraten der Südmeerfreibeuter, 10 Seeräuber der Südmeerfreibeuter, 10 Dockarbeiter der Südmeerfreibeuter und 10 Schwadroneure der Südseefreibeuter zu töten."}}
D[8367] = {"Große Ehre",{"Bringt 1 Ehrenabzeichen des Alteractals, 1 Ehrenabzeichen des Arathibeckens, 1 Ehrenabzeichen der Kriegshymnenschlucht und 1 Ehrenabzeichen vom Auge des Sturms zu einem Kriegshetzer der Horde in einer der Hauptstädte oder in Shattrath."}}
D[8368] = {"Schlacht der Kriegshymnenschlucht",{"Bringt 3 Ehrenabzeichen des Kriegshymnenklans zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
D[8369] = {"Die Invasoren des Alteractals",{"Bringt 3 Ehrenabzeichen des Alteractals zu einem der Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
D[8370] = {"Eroberung des Arathibeckens",{"Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
D[8371] = {"Gemeinsames Bestreben",{"Bringt 1 Ehrenabzeichen des Alteractals, 1 Ehrenabzeichen des Arathibeckens, 1 Ehrenabzeichen der Kriegshymnenschlucht und 1 Ehrenabzeichen vom Auge des Sturms zu einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath."}}
D[8372] = {"Kampf um die Kriegshymnenschlucht",{"Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder."}}
D[8373] = {"Die Kraft der Pinie",{"Verwendet einen Stinkbombenreiniger, um alle Stinkbomben der Verlassenen zu vernichten, die hier in Süderstade losgelassen wurden. Kehrt zu Unteroffizier Hartman in Süderstade zurück, wenn Ihr fertig seid."}}
D[8374] = {"Inbesitznahme des Arathibeckens",{"Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen."}}
D[8375] = {"Vergesst das Alteractal nicht!",{"Bringt 3 Ehrenabzeichen des Alteractals zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen."}}
D[8376] = {"Kriegsausrüstung",{"Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.","","Sollte diese... diese Prophezeiung jemals wahr werden...","","Das könnte das Ende für unser aller Zukunft bedeuten.","","Diese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein."}}
D[8377] = {"Kriegsausrüstung",{"Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.","","Sollte diese… diese Prophezeiung jemals wahr werden…","","Das könnte das Ende für unser aller Zukunft bedeuten.","","Diese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein."}}
