D[8383] = {"Vergesst das Alteractal nicht!",{"Die Schlacht im Alteractal tobt noch immer, <Name>! Habt Ihr schon Euren Teil zum Sieg beigetragen, <Name>?"}}
D[8384] = {"Inbesitznahme des Arathibeckens"}
D[8385] = {"Gemeinsames Bestreben",{"Ah, <Name>. Ich hoffe Ihr gebt Eure Erfahrung auch noch auf weiteren Schlachtfeldern weiter. Viele unserer Jungens und Mädels sehen mit Ehrfurcht zu erfahrenen Veteranen wie Euch auf."}}
D[8386] = {"Kampf um die Kriegshymnenschlucht"}
D[8387] = {"Die Invasoren des Alteractals",{"Die Schlacht im Alteractal tobt noch immer, <Name>! Ihr müsst schnellstmöglich in das Alteractal zurückkehren und die Invasoren aus dem Gebiet der Frostwolf vertreiben."}}
D[8388] = {"Große Ehre",{"Viele mutige Kämpfer sehen zu Euch auf, <Name>. Ihr seid auch weiterhin ein Vorbild für alle, die sich in den Schlachten gegen die Allianz schlagen. Welche Neuigkeiten bringt Ihr mir von Euren Reisen?"}}
D[8389] = {"Schlacht der Kriegshymnenschlucht",{"Der Kampf um die Warsongschlucht geht weiter, <Name>. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!"}}
D[8390] = {"Eroberung des Arathibeckens"}
D[8391] = {"Inbesitznahme des Arathibeckens",{"Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen."}}
D[8392] = {"Inbesitznahme des Arathibeckens",{"Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen."}}
D[8393] = {"Inbesitznahme des Arathibeckens",{"Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen."}}
D[8394] = {"Inbesitznahme des Arathibeckens",{"Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen."}}
