D[8635] = {"Urahne Splitterfels",{"Die Kämpfe vergangener Zeiten sind die Saat aus der Legenden entstehen. Eure Zeit ist die der Helden, mein Kind. Möge Eure Legende Wurzeln fassen und gedeihen.","","Ich wünsche Euch viel Glück, <Name>, und bitte, nehmt dies als Zeichen meiner Dankbarkeit..."}}
D[8636] = {"Urahne Rumpelfels",{"Die Dinge des Lebens sind zum Sterben verdammt und kehren zur Erde zurück. Das Geistliche lebt jedoch für immer weiter. Ich wünsche Euch viel Glück, <Name>, und bitte, nehmt dies als Zeichen meiner Dankbarkeit..."}}
D[8637] = {"Stiefel des Todesboten",{"Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Kampfes, 5 Kristallskarabäen und 5 Knochenskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus."}}
