D[8760] = {"Der Pfad des Herbeirufers",{"Eine derartige Hingabe für eine gerechte Sache ist selten. Ihr habt die Umbeugsamkeit Eures Willens bewiesen, <Name>! Dafür, dass Euer wacher Geist und Euer scharfer Verstand über diese Welt wacht, sollt Ihr reichhaltig belohnt werden.","","Übergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann."}}
D[8761] = {"Der große Herbeirufer",{"Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!","","Übergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann."}}
D[8762] = {"Metzen das Rentier",{"Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.","","Wenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.","","Bringt den Beutel zu Wulmort Klingeltaschen in Eisenschmiede zurück, sobald Ihr Metzen befreit habt."}}
D[8763] = {"Der Held des Tages",{"Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten."}}
D[8764] = {"Den Pfad wechseln - Kein Beschützer mehr"}
D[8765] = {"Den Pfad wechseln - Kein Herbeirufer mehr"}
D[8766] = {"Den Pfad wechseln - Kein Eroberer mehr"}
D[8767] = {"Ein leicht geschütteltes Geschenk",{"Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:BnFür <Name>, einen ganz besonderen Helden."}}
D[8768] = {"Ein fröhlich verpacktes Geschenk",{"Auf diesem festlich verpackten Geschenk steht Euer Name!",""," Hat sich das etwa gerade bewegt?"}}
D[8769] = {"Ein tickendes Geschenk",{"Ein wundervolles Winterhauchfest wünschen Euch Eure Freunde bei Kokelwälder."}}
D[8770] = {"Ziel: Verteidiger des Ashischwarms",{"Tötet 30 Verteidiger des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz I, um diese Aufgabe abschließen zu können."}}
D[8771] = {"Ziel: Sandpirscher des Ashischwarms",{"Tötet 30 Sandpirscher des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz II, um diese Aufgabe abschließen zu können."}}
D[8772] = {"Ziel: Wegbehüter des Zoraschwarms",{"Tötet 30 Wegbehüter des Zoraschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VI, um diese Aufgabe abschließen zu können."}}
D[8773] = {"Ziel: Häscher des Zoraschwarms",{"Tötet 30 Häscher des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IV, um diese Aufgabe abschließen zu können."}}
D[8774] = {"Ziel: Wegelagerer des Regalschwarms",{"Tötet 30 Wegelagerer des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VIII, um diese Aufgabe abschließen zu können."}}
D[8775] = {"Ziel: Feuerspucker des Regalschwarms",{"Tötet 30 Feuerspucker des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IX, um diese Aufgabe abschließen zu können."}}
D[8776] = {"Ziel: Sklavenjäger des Regalschwarms",{"Tötet 30 Sklavenjäger des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz X, um diese Aufgabe abschließen zu können."}}
D[8777] = {"Ziel: Einbuddler des Regalschwarms",{"Tötet 30 Einbuddler des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XI, um diese Aufgabe abschließen zu können."}}
D[8778] = {"Die Eisenschmiedebrigade braucht Sprengstoff!",{"Bringt Arkanist Sprinkelstaub nahe des Zoraschwarmbaus in Silithus 6 Öle des Feuerbrandes, 5 Einheiten Goblinraketentreibstoff und 10 Einheiten dichtes Sprengpulver. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können."}}
D[8779] = {"Magische Materialien",{"Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und einen gewaltigen Smaragd zu Geologin Lerchenbann auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können."}}
D[8780] = {"Rüstungssets für den Feldeinsatz",{"Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau in Silithus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können."}}
D[8781] = {"Waffen für den Feldeinsatz",{"Bringt 2 Mondstahlbreitschwerter zu Janela Starkhammer am Posten der Eisenschmiedebrigade beim Zoraschwarmbau. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können."}}
D[8782] = {"Uniformnachschub",{"Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können."}}
D[8783] = {"Besondere Materialien",{"Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können."}}
D[8784] = {"Geheimnisse der Qiraji",{"Bringt das uralte Qirajiartefakt zu den Drachen, die sich nahe des Tempeleingangs versteckt halten."}}
D[8785] = {"Die Orgrimmarlegion braucht Mojo!",{"Bringt Schattenpriesterin Shai nahe des Regalschwarmbaus in Silithus 6 Einheiten mächtiges Mojo, 6 Fläschchen großes Mojo und 8 Öle des Feuerbrandes. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können."}}
D[8786] = {"Waffen für den Feldeinsatz",{"Bring 3 massive Eisenäxte zu Merok Langschreiter im Lager der Orgrimmarlegion außerhalb des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können."}}
D[8787] = {"Rüstungssets für den Feldeinsatz",{"Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Merok Langschreiter nahe des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können."}}
D[8788] = {"Ein leicht geschütteltes Geschenk",{"Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:","","Für <Name>, einen ganz besonderen Helden."}}
D[8789] = {"Imperiale Qirajiwaffen",{"Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Einheiten Elementiumerz bringt."}}
D[8790] = {"Imperiale Qirajiinsignien",{"Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Einheiten Elementiumerz."}}
D[8791] = {"Der Untergang von Ossirian",{"Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus."}}
D[8792] = {"Die Horde braucht Euch!",{"Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar."}}
D[8793] = {"Die Horde braucht Euch!",{"Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar."}}
D[8794] = {"Die Horde braucht Euch!",{"Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar."}}
D[8795] = {"Die Allianz braucht Euch!",{"Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede."}}
D[8796] = {"Die Allianz braucht Euch!",{"Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede."}}
D[8797] = {"Die Allianz braucht Euch!",{"Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede."}}
D[8798] = {"Euer eigener Yeti",{"Hey! Wisst Ihr was?! Ihr seid auch Ingenieur! So, da Ihr mir dabei geholfen habt meinen Freunden eine Lektion zu erteilen, werde ich Euch jetzt lehren, wie Ihr Euren eigenen mechanischen Yeti herstellt! Jetzt kann der Spaß für immer weitergehen und Ihr könnt wem immer Ihr wollt einen Schrecken einjagen! Vorausgesetzt Ihr treibt die benötigten Teile dafür auf.","","Na, was sagt Ihr, <Name>? Wollt Ihr, dass ich Euch in das Geheimnis der Herstellung eines mechanischen Yetis einweihe?"}}
D[8799] = {"Der Held des Tages",{"Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten."}}
D[8800] = {"Schlachtrüstung des Cenarius",{"Sprecht mit Vargus auf Burg Cenarius in Silithus."}}
D[8801] = {"C'Thuns Vermächnis",{"Bringt Caelastrasz im Tempel von Ahn'Qiraj das Auge von C'Thun."}}
D[8802] = {"Der Retter von Kalimdor",{"Bringt Anachronos in den Höhlen der Zeit das Auge von C'Thun."}}
D[8803] = {"Ein Festtagsgeschenk",{"Auf dem Schildchen des Geschenks steht:","","Für <Name>,nnIch hoffe, dieses Geschenk wird Euch dabei helfen, einen Hauch von Gemütlichkeit und Festtagsfreude in ganz Azeroth zu verbreiten.","","Altvater Winte"}}
D[8804] = {"Wüstenüberlebenspaket",{"Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können."}}
D[8805] = {"Stiefel für die Wache",{"Bringt 3 Paar verschnörkelte Mithrilstiefel zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz II, um diese Aufgabe abschließen zu können."}}
D[8806] = {"Schleifsteine für die Wache",{"Bringt 10 verdichtete Schleifsteine, 10 robuste Schleifsteine und 10 schwere Schleifsteine zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz III, um diese Aufgabe abschließen zu können."}}
D[8807] = {"Magische Materialien",{"Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und 1 gewaltigen Smaragd zu Geologin Lerchenbann auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können."}}
