D[8912] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Deliana in Eisenschmiede."}}
D[8913] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Mokvar in Orgrimmar zurück."}}
D[8914] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Mokvar in Orgrimmar zurück."}}
D[8915] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bindungen des Magisters zu Mokvar in Orgrimmar zurück."}}
