D[8919] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Furcht zu Mokvar in Orgrimmar zurück."}}
D[8920] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Giftproben aus Silithus und bringt es zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Mokvar in Orgrimmar zurück."}}
D[8921] = {"Der Ektoplasmadestillierer",{"Kehrt mit einem empfindlichen Arkanitwandler, 4 großen ewigen Essenzen, 10 Flaschen Steinschuppenöl, 25 Einheiten Vulkanasche und 40 Gold im Gepäck zu Mux Manamix in Gadgetzan zurück."}}
D[8922] = {"Ein übernatürlicher Apparat",{"Bringt den versiegelten Blutbehälter zu Mux Manamix in Gadgetzan in Tanaris."}}
D[8923] = {"Ein übernatürlicher Apparat",{"Bringt den versiegelten Giftbehälter zu Mux Manamix in Gadgetzan."}}
D[8924] = {"Ektoplasmajagd",{"Benutzt den Ektoplasmadestillierer in der Nähe von schemenhaften Untoten, um 12 Einheiten versengtes Ektoplasma in Silithus, 12 Einheiten gefrorenes Ektoplasma in Winterquell und 12 Einheiten stabiles Ektoplasma in den östlichen Pestländern zu erhalten. Bringt das Ektoplasma dann mitsamt des Ektoplasmadestillierers zu Mux Manamix in Gadgetzan zurück."}}
D[8925] = {"Eine portable Energiequelle",{"Findet Magmafürst Bokk in der brennenden Steppe, nehmt seinen Magmakern an Euch und bringt ihn zu Mux Manamix in Gadgetzan."}}
D[8926] = {"Die angemessene Entlohnung",{"Bringt Deliana in Eisenschmiede einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens."}}
D[8927] = {"Die angemessene Entlohnung",{"Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens."}}
D[8928] = {"Ein verschlagener Händler",{"Sucht den Wichtel in der Höhle in der Nähe der flüsternden Schlucht im Süden von Winterquell. Kauft ihm einen teufelselementaren Brennstab ab und kehrt zu Mux Manamix in Gadgetzan zurück."}}
D[8929] = {"Suche nach Anthion",{"Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon."}}
D[8930] = {"Suche nach Anthion",{"Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon."}}
