D[8932] = {"Die angemessene Entlohnung",{"Bringt Deliana in Eisenschmiede einen Gürtel des Magisters und ein Paar Handschuhe des Magisters."}}
D[8933] = {"Die angemessene Entlohnung",{"Bringt Deliana in Eisenschmiede einen Gürtel des Lichts und ein Paar Stulpen des Lichts."}}
D[8934] = {"Die angemessene Entlohnung",{"Bringt Deliana in Eisenschmiede einen Gürtel des Gläubigen und ein Paar Handschuhe des Gläubigen."}}
D[8935] = {"Die angemessene Entlohnung",{"Bringt Deliana in Eisenschmiede einen Gürtel der Schattenkunst und ein Paar Handschuhe der Schattenkunst."}}
