D[8942] = {"Die angemessene Entlohnung",{"Bringt Mokvar in Orgrimmar eine Kordel der Elemente und ein Paar Stulpen der Elemente."}}
D[8943] = {"Die angemessene Entlohnung",{"Bringt Mokvar in Orgrimmar einen Gürtel der Furcht und ein Paar Wickeltücher der Furcht."}}
D[8944] = {"Die angemessene Entlohnung",{"Bringt Mokvar in Orgrimmar einen Gürtel der Ehre und ein Paar Stulpen der Ehre."}}
D[8945] = {"Die letzte Bitte eines toten Mannes",{"Geht nach Stratholme und befreit Ysida Harmon aus den Fängen von Baron Totenschwur."}}
D[8946] = {"Lebensbeweis",{"Bringt Anthion Harmon in den östlichen Pestländern Ysidas Medaillon."}}
D[8947] = {"Anthions merkwürdige Anforderung",{"Bringt Anthion Harmon in den östlichen Pestländern 3 Dunkeleisenbarren, 20 verzaubertes Leder, 3 Mondstoff und 4 geschmeidige unverwüstliche Bälge"}}
D[8948] = {"Anthions alter Freund",{"Bringt Falrin Rankenweber in der Bibliothek von Düsterbruch das unvervollständigte Banner der Provokation."}}
D[8949] = {"Falrins Rachefeldzug",{"Nehmt den Ogern in der Schwarzfelsspitze oder in Düsterbruch 25 Ogerkriegsperlen ab und bringt sie zu Falrin Rankenweber im Athenaeum, der Bibliothek von Düsterbruch."}}
D[8950] = {"Die Verzauberung des Aufhetzers",{"Bringt Falrin Rankenweber in Düsterbruch 1 Essenz eines spöttischen Geisterwesens, 4 Dunkelrunen und 8 große glänzende Splitter."}}
D[8951] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Deliana in Eisenschmiede zurück."}}
D[8952] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Bestienjägerstiefeln, einer Bestienjägerhose und einem Bestienjägermantel zu Deliana in Eisenschmiede zurück."}}
D[8953] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Stiefel des Magisters, Gamaschen des Magisters und einem Mantel des Magisters zu Deliana in Eisenschmiede zurück."}}
D[8954] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Stiefel des Lichts, Beinplatten des Lichts, und einer Schiftung des Lichts zu Deliana in Eisenschmiede zurück."}}
D[8955] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Sandalen des Gläubigen, einem Rock des Gläubigen und einem Mantel des Gläubigen zu Deliana in Eisenschmiede zurück."}}
D[8956] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Stiefel der Schattenkunst, einer Hose der Schattenkunst und einer Schiftung der Schattenkunst zu Deliana in Eisenschmiede zurück."}}
D[8957] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und Schulterstücken der Elemente zu Mokvar in Orgrimmar zurück."}}
D[8958] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Deliana in Eisenschmiede zurück."}}
