D[9208] = {"Der Greuelwächter - Arkanum des Schutzes",{"Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Schutzes."}}
D[9209] = {"Der Greuelwächter - Arkanum der Schnelligkeit",{"Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum der Schnelligkeit."}}
