D[9215] = {"Bringt mir Kel'gashs Kopf!",{"Bringt den Kopf von Kel'gash dem Boshaften zu Hauptmann Helios bei der Enklave der Weltenwanderer in den Geisterlanden."}}
D[9216] = {"Faulende Herzen",{"Bringt 10 faulende Herzen zu Magistrix Aminel in Tristessa."}}
D[9217] = {"Mehr faulende Herzen"}
D[9218] = {"Wirbelknochenstaub",{"Bringt 10 Einheiten Wirbelknochenstaub zu Magistrix Aminel in Tristessa."}}
D[9219] = {"Mehr Wirbelknochenstaub"}
D[9220] = {"Krieg gegen die Todesfestung",{"Tötet in der Todesfestung 5 Augen von Dar'khan, 6 nerubische Zenturio und 6 Wehklagende und kehrt anschließend zu Magister Idonis beim Sanktum der Sonne in den Geisterlanden zurück."}}
D[9221] = {"Überragende Kampfausrüstung - Freund der Dämmerung",{"Für 30 Insignien der Dämmerung und 30 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen."}}
D[9222] = {"Epische Kampfausrüstung - Freund der Dämmerung",{"Für 110 Insignien der Dämmerung und 110 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen."}}
D[9223] = {"Überragende Kampfausrüstung - Wohlwollen der Dämmerung",{"Für 20 Insignien der Dämmerung und 20 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen."}}
