D[9225] = {"Epische Kampfausrüstung - Respekt der Dämmerung",{"Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen."}}
D[9226] = {"Überragende Kampfausrüstung - Respekt der Dämmerung",{"Für 7 Insignien der Dämmerung und 7 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen."}}
D[9227] = {"Überragende Kampfausrüstung - Ehrfurcht der Dämmerung",{"Für 6 Insignien der Dämmerung und 6 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen."}}
D[9228] = {"Epische Kampfausrüstung - Ehrfurcht der Dämmerung",{"Für 27 Insignien der Dämmerung und 27 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen."}}
D[9229] = {"Ramaladnis Schicksal",{"Betretet Naxxramas und bringt Ramaladnis Schicksal in Erfahrung."}}
D[9230] = {"Ramaladnis eisiger Griff",{"Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte, dass Ihr ihm 1 gefrorene Rune, 1 blauen Saphir und 1 Arkanitbarren bringt."}}
D[9232] = {"Das Einzige, das ich kann...",{"Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt."}}
D[9233] = {"Omarions Leitfaden",{"Bringt Omarions Leitfaden zu Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
