D[9247] = {"Der Ruf des Bewahrers",{"Bringt den Brief vom Bewahrer der Schriften zu ihm, in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9248] = {"Eine bescheidene Darbringung",{"Aurel Goldblatt auf Burg Cenarius in Silithus möchte, dass Ihr ihr 1 abyssisches Szepter bringt. Euer Ruf bei dem Zirkel des Cenarius muss außerdem wohlwollend sein."}}
D[9249] = {"40 Lose - Bauplan: Dampfpanzersteuerung"}
D[9250] = {"Grundstab von Atiesh",{"Findet jemanden, der Euch dabei hilft, die letzten beiden Teile des Stabs zu finden und das Böse daraus zu vertreiben."}}
D[9251] = {"Atiesh, der korrumpierte Hohestab",{"Anachronos in den Höhlen der Zeit in Tanaris möchte den Stabkopf und -fuß von Atiesh."}}
D[9252] = {"Die Verteidigung von Morgenluft",{"Tötet 4 Moderknochenmarodeure und 4 dunkle Gespenster. Kehrt anschließend zu Waldläuferin Sareyn in Morgenluft im Immersangwald zurück."}}
D[9253] = {"Runenwächter Deryan",{"Sprecht mit Runenwächter Deryan im Immersangwald nahe der Grenze zu den Geisterlanden."}}
D[9254] = {"Der eigensinnige Lehrling",{"Sprecht mit Lehrling Mirveda beim Sanktum des Ostens im Immersangwald."}}
D[9255] = {"Forschungsnotizen",{"Bringt die Forschungsnotizen zu Magistrix Landra Morgenwandler in Morgenluft im Immersangwald."}}
D[9256] = {"Morgenluft",{"Sprecht mit Waldläufer Degolien in Morgenluft im Immersangwald."}}
D[9257] = {"Atiesh, Hohestab des Wächters",{"Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück."}}
D[9258] = {"Der versengte Hain",{"Findet Larianna Flusswind nahe des versengten Hains, südwestlich des Immersangwalds."}}
D[9259] = {"Verrat am Blutsegel"}
D[9260] = {"Erforscht die Geißel von Sturmwind",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren Sturmwinds. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9261] = {"Erforscht die Geißel von Eisenschmiede",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Eisenschmiede. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9262] = {"Erforscht die Geißel von Darnassus",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Darnassus. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9263] = {"Erforscht die Geißel von Orgrimmar",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Orgrimmar. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9264] = {"Erforscht die Geißel von Donnerfels",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel außerhalb von Donnerfels. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9265] = {"Erforscht die Geißel von Unterstadt",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Unterstadt. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9266] = {"Wiedergutmachung"}
D[9267] = {"Heilen alter Wunden"}
D[9268] = {"Krieg zur See"}
D[9269] = {"Atiesh, Hohestab des Wächters",{"Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück."}}
D[9270] = {"Atiesh, Hohestab des Wächters",{"Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück."}}
D[9271] = {"Atiesh, Hohestab des Wächters",{"Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück."}}
D[9272] = {"Kleider machen Seebären"}
D[9274] = {"Geister der Ertrunkenen",{"Waldläufer Krenn'an aus der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr beim nahegelegenen See 8 rachsüchtige Erscheinungen und 8 ruhelose Erscheinungen tötet."}}
D[9275] = {"In der Würze liegt der Tod",{"Vergiftet die Trollnahrungsvorräte in den Lagern von Zeb'Nowa. Kehrt anschließend zu Apotheker Venustus bei der Enklave der Weltenwanderer in den Geisterlanden zurück."}}
D[9276] = {"Angriff auf Zeb'Tela",{"Tötet 8 Schattenzauberer der Waldschattentrolle und 8 Kopfjäger der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück."}}
D[9277] = {"Angriff auf Zeb'Nowa",{"Tötet 10 Pantherlords der Waldschattentrolle und 10 Verhexer der Waldschattentrolle. Kehrt anschließend zu Weltenwanderin Solanna bei der Enklave der Weltenwanderer in den Geisterlanden zurück."}}
D[9278] = {"Willkommen!",{"Bringt den Geschenkgutschein der Azurwacht zu Jaeleil in der Azurwacht."}}
D[9279] = {"Ihr habt überlebt!",{"Sprecht mit Proenitus bei der Absturzstelle im Am'mental."}}
D[9280] = {"Wiederaufladen der Heilkristalle",{"Beschafft Euch 8 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am'mental."}}
D[9281] = {"Den Weg frei machen",{"Lehrling Vor'el von Andiliens Grund in den Geisterlanden möchte, dass Ihr 10 Große Spindelweber und 10 Geisterklauenverheerer tötet."}}
D[9282] = {"Die Enklave der Weltenwanderer",{"Magister Kaendris beim Sanktum der Sonne möchte, dass Ihr mit Waldläuferin Vynna bei der Enklave der Weltenwanderer in den Geisterlanden sprecht."}}
D[9283] = {"Rettet die Überlebenden!",{"Wendet Eure Gabe der Naaru an, um einen der Überlebenden der Draenei zu heilen, die über das ganze Am'mental verstreut sind. Kehrt dann zu Zalduun bei der Absturzstelle im Am'mental zurück."}}
D[9284] = {"Aldor Faction Test"}
D[9285] = {"Consortium Faction Test"}
D[9286] = {"Scryers Faction Test"}
D[9287] = {"Ausbildung zum Paladin"}
D[9288] = {"Ausbildung zum Jäger",{"Ich bin froh, dass Ihr zu mir gekommen seid. Ich bin schon eine ganze Weile für die Ausbildung junger <Klasse> verantwortlich, eine Aufgabe, die ich auch in dieser neuen Welt noch weiter erfüllen möchte. Ich beobachte Euch bereits seit geraumer Zeit und es wäre eine Ehre für mich, wenn ich Euch die Künste des Jägers lehren dürfte.","","Sollen wir beginnen?"}}
D[9289] = {"Ausbildung zum Krieger"}
D[9290] = {"Ausbildung zum Magier"}
D[9291] = {"Ausbildung zum Priester"}
D[9292] = {"Gesprungener nekrotischer Kristall",{"Bringt den gesprungenen nekrotischen Kristall zu Leutnant Orrin außerhalb der Tore von Sturmwind."}}
D[9293] = {"Was getan werden muss...",{"Sammelt 10 Peitscherproben ein und bringt sie zu Botanikerin Taerix bei der Absturzstelle im Am'mental."}}
D[9294] = {"Die Heilung des Sees",{"Verwendet den Neutralisierungswirkstoff bei dem strahlenden Energiekristall und kehrt anschließend zu Botanikerin Taerix bei der Absturzstelle im Am'mental zurück."}}
D[9295] = {"Brief von der Front",{"Bringt den zerfledderten Brief zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9299] = {"Notiz von der Front",{"Bringt die verblichene Notiz zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9300] = {"Seite von der Front",{"Bringt die zerfranste Seite zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9301] = {"Umschlag von der Front",{"Bringt den blutbefleckten Umschlag zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9302] = {"Schreiben von der Front",{"Bringt das zerknitterte Schreiben zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9303] = {"Immunisierung",{"Wendet den Immunisierungskristall auf 6 Nisteleulkin an. Kehrt anschließend zu Verteidiger Aldar bei der Absturzstelle im Am'mental zurück."}}
D[9304] = {"Dokument von der Front",{"Bringt das verschmierte Dokument zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9305] = {"Ersatzteile",{"Beschafft 4 Emitterersatzteile und kehrt anschließend zu Technikerin Zhanaa bei der Absturzstelle im Am'mental zurück."}}
D[9309] = {"Der vermisste Späher",{"Sprecht mit Tolaan im Schattenkamm im Am'mental."}}
D[9310] = {"Schwacher nekrotischer Kristall",{"Bringt den schwachen nekrotischen Kristall zu Leutnant Rukag im Hof von Unterstadt."}}
D[9311] = {"Blutelfenspionage",{"Tötet Gutachterin Kandress und informiert anschließend Verteidiger Aldar bei der Absturzstelle im Am'mental über die Ereignisse."}}
D[9312] = {"Der Emitter",{"Sprecht mit Technikerin Zhanaa bei der Absturzstelle im Am'mental."}}
D[9313] = {"Reise zur Azurwacht",{"Sprecht mit Techniker Dyvuun bei der Azurwacht auf der Azurmythosinsel."}}
D[9314] = {"Nachricht von der Azurwacht",{"Sprecht mit Versorgerin Chellan bei der Azurwacht auf der Azurmythosinsel."}}
D[9315] = {"Anok'suten",{"Tötet Anok'suten und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück."}}
D[9317] = {"Geweihte Wetzsteine",{"Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein."}}
D[9318] = {"Gesegnetes Zauberöl",{"Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben."}}
D[9319] = {"Licht im Dunkeln",{"Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück."}}
D[9320] = {"Erheblicher Manatrank",{"Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben."}}
D[9321] = {"Erheblicher Heiltrank"}
D[9322] = {"Glühende Feuer in Kalimdor",{"Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Krater von Un'Goro und Winterquell auf. Kehrt dann zum Flammenbewahrer zurück."}}
D[9323] = {"Glühende Feuer in den östlichen Königreichen",{"Reist zu den Lagern des Sonnenwendfests in den verwüsteten Landen, den östlichen Pestländern, dem Hinterland und der sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück."}}
D[9324] = {"Raubt die Flamme von Orgrimmar",{"Bringt die Flamme von Orgrimmar zum Meister der Lehren."}}
D[9325] = {"Raubt die Flamme von Donnerfels",{"Bringt die Flamme von Donnerfels zum Meister der Lehren."}}
D[9326] = {"Raubt die Flamme von Unterstadt",{"Bringt die Flamme von Unterstadt zum Meister der Lehren."}}
D[9327] = {"Die Verlassenen",{"Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden."}}
D[9328] = {"Held der Sin'dorei",{"Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond."}}
D[9329] = {"Die Verlassenen",{"Sprecht mit Hochexekutor Mavren in Tristessa in den Geisterlanden."}}
D[9330] = {"Raubt die Flamme von Sturmwind",{"Bringt die Flamme von Sturmwind zum Geschichtenerzähler."}}
D[9331] = {"Raubt die Flamme von Eisenschmiede",{"Bringt die Flamme von Eisenschmiede zum Geschichtenerzähler."}}
D[9332] = {"Raubt die Flamme von Darnassus",{"Bringt die Flamme von Darnassus zum Geschichtenerzähler."}}
D[9333] = {"Handschuhe der Argentumdämmerung",{"Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen."}}
D[9334] = {"Gesegnetes Zauberöl",{"Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben."}}
D[9335] = {"Geweihte Wetzsteine",{"Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein."}}
D[9336] = {"Erheblicher Heiltrank"}
D[9337] = {"Erheblicher Manatrank",{"Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben."}}
D[9338] = {"Treue zum Zirkel des Cenarius",{"Selbst wenn Ihr keinen Bedarf an unseren materiellen Belohungen habt, sind diese Abzeichen ein Symbol für gegenseitiges Vertrauen und Freundschaft.","","Bringt sie mir. Außerordentliche Dienste von Euch werde ich sorgsam vermerken."}}
D[9339] = {"Der Lohn des Diebes"}
D[9340] = {"Die große Kluft",{"Waldläuferhauptmann Venn'ren in der Falkenwacht möchte, dass Ihr 8 Steinsichelwelpen und 3 Steinsichelalphas bei der großen Kluft östlich der Falkenwacht erlegt."}}
D[9341] = {"Wappenrock der Argentumdämmerung",{"Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen."}}
D[9342] = {"Plündernde Krustenbohrer",{"Großknecht Razelcraz bei den Minen in der Nähe von Thrallmar möchte, dass Ihr 15 plündernde Krustenbohrer tötet. Die Würmer haben die Angewohnheit, unplötzlich aus ihren unterirdischen Tunneln anzugreifen."}}
D[9343] = {"Wappenrock der Argentumdämmerung",{"Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen."}}
D[9344] = {"Der überstürzte Aufbruch",{"Scharfseherin Regulkut möchte, dass Ihr ihren Schüler Grelag findet."}}
D[9345] = {"Herstellung der Salbe",{"Grelag im Rückenbrecherposten möchte, dass Ihr ihm 12 Höllenwirbelkräuter für seine Salbe bringt."}}
D[9346] = {"Wenn Hölleneber fliegen",{"Wachtkommandant Krunk in Thrallmar möchte, dass Ihr ihm 10 klobige Hölleneberkadaver von verhungernden Höllenebern bringt."}}
D[9349] = {"Felshetzereier sammeln",{"Bringt 12 Felshetzereier zu Legassi bei der Zeppelinabsturzstelle auf der Höllenfeuerhalbinsel."}}
D[9351] = {"Wilde Leerwandler",{"Bringt 10 kondensierte Leerwandleressenzen zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle."}}
D[9352] = {"Darnassische Eindringlinge",{"Reist zum Sanktum des Westens südwestlich vom Falkenplatz und vernichtet jegliche Eindringlinge, die Ihr dort findet. Berichtet anschließend Leybewahrerin Velania."}}
D[9355] = {"Eine Aufgabe für einen intelligenten Helden",{"Tötet 15 plündernde Krustenbohrer und kehrt dann zu Großknecht Biggums in der Ehrenfeste zurück."}}
D[9356] = {"So weich wie Butter",{"Bringt 12 fleischige Bussardflügel zu Legassi bei der Zeppelinabsturzstelle."}}
D[9357] = {"Meldet Euch bei Aeldon Sonnenmal",{"Meldet Euch bei Aeldon Sonnenmal beim inneren Elfentor im Immersangwald."}}
D[9358] = {"Waldläuferin Sareyn",{"Meldet Euch bei Waldläuferin Sareyn außerhalb von Morgenluft im Immersangwald."}}
D[9359] = {"Zuflucht der Weltenwanderer",{"Meldet Euch bei Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer im Immersangwald."}}
D[9360] = {"Angriff der Amani",{"Bringt die Invasionspläne der Amani zu Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer."}}
D[9361] = {"Hölleneber, die etwas andere Delikatesse",{"Legassi bei der Zeppelinabsturzstelle möchte, dass Ihr 8 Stück geläutertes Hölleneberfleisch sammelt. Um das Fleisch zu reinigen, schüttet die Läuterungsmischung über das besudelte Hölleneberfleisch, das Ihr von den Höllenebern gesammelt habt."}}
D[9362] = {"Kriegsherr Krellian",{"Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara."}}
D[9363] = {"Warnt Morgenluft",{"Reist nach Morgenluft im Immersangwald und sprecht mit Waldläufer Degolien."}}
D[9364] = {"Gespaltene Magie",{"Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück."}}
D[9365] = {"Der Lohn des Diebes"}
D[9366] = {"Die Suche nach Teufelsblut",{"Ryathen der Düstere an der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 6 Teufelsblutproben von den Terrorbestien bringt, die bei den Teichen von Aggonar umherstreifen"}}
D[9367] = {"Das Fest des Feuers",{"Wärmt Euch an den Freudenfeuern in Sturmwind, Eisenschmiede und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte."}}
D[9368] = {"Das Fest des Feuers",{"Wärmt Euch an den Freudenfeuern in Orgrimmar, Donnerfels und Unterstadt. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte."}}
D[9369] = {"Wiederaufladen der Heilkristalle",{"Beschafft Euch 8 Phiolen mit Mottenblut von den in der Nähe hausenden Talmotten und bringt sie zu Proenitus bei der Absturzstelle im Am'mental."}}
D[9370] = {"Stoppt das Säuberungsritual",{"Platziert den Signalstein bei den Teichen von Aggonar am Altar von Aggonar und besiegt alle Anachoreten der Draenei, die auf Eure Signal reagieren. Kehrt anschließend mit dem Signalstein zu Ryathen dem Düsteren bei der Falkenwacht zurück."}}
D[9371] = {"Botanikerin Taerix",{"Sprecht mit Botanikerin Taerix bei der Absturzstelle im Am'mental."}}
D[9372] = {"Dämonische Verderbnis",{"Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel möchte, dass Ihr 6 Blutproben eines Höllenebers von titanischen Höllenebern sammelt."}}
D[9373] = {"Fehlender Schriftverkehr",{"Bringt den zerfressenen Lederkoffer zu Thiah Rotmähne in der Nähe der Ruinen von Sha'naar im westlichen Teil der Höllenfeuerhalbinsel."}}
D[9374] = {"Arelions Tagebuch",{"Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Teichen von Aggonar reist und Arelions Tagebuch sucht."}}
D[9375] = {"Der Weg zur Falkenwacht",{"Beschützt die verwundete Blutelfenpilgerin auf Ihrem Weg zur Falkenwacht und sprecht dann mit Taleris Morgenblick."}}
D[9376] = {"Die Pflicht eines Pilgers",{"Die verletzte Blutelfpilgerin wurde von giftigen Stachelklauenfelshetzern angegriffen, als sie die Staubstachelschlucht erkunden wollte. Findet ihr Lager und haltet nach dem vermissten Beutel Ausschau."}}
D[9378] = {"Die Zitadelle des Schreckens - Naxxramas",{"Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein."}}
D[9380] = {"Die Hatz nach mehr",{"Beschafft 6 unversehrte Sphärenhundkadaver und bringt sie zu Ausgrabungsleiter Murantus in der Ehrenfeste."}}
D[9381] = {"Treffsichere Pfeile",{"Sammelt 8 Schwanzfedern eines Knochenhäuters von den Knochenhäutergeiern und bringt sie Falknerin Drenna Flusswind in der Falkenwacht."}}
D[9382] = {"Das Schicksal der Grollhufe",{"Tötet 15 borstige Grollhufe und kehrt dann zu Amaan dem Weisen im Tempel von Telhamat zurück."}}
D[9383] = {"Ein gewagter Plan",{"Wendet den geweihten Kristall auf einen verwundeten unkontrollierten Leerwandler an. Kehrt anschließend zu Elsaana beim Tempel von Telhamat zurück."}}
D[9385] = {"Tobende Felshetzer",{"Tötet 10 Stachelklauenfelshetzer und kehrt anschließend zu Gremni Langbart auf der Höllenfeuerhalbinsel zurück."}}
D[9386] = {"Licht im Dunkeln",{"Findet und berührt die Freudenfeuer innerhalb der Schwarzfelsspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer."}}
D[9387] = {"Die Quelle der Verderbtheit",{"Reist zu den Ruinen von Sha'naar auf der Höllenfeuerhalbinsel und besorgt 5 dämonische Essenzen von den Zuchtmeistern der Illidari. Kehrt zu Apotheker Azethen in der Falkenwacht zurück, wenn Ihr die Aufgabe erfüllt habt."}}
D[9388] = {"Lodernde Flammen in Kalimdor",{"Sucht die Freudenfeuer im Eschental, dem Brachland, der Dunkelküste und dem Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer."}}
D[9389] = {"Lodernde Flammen in den östlichen Königreichen",{"Sucht die Freudenfeuer im Vorgebirge des Hügellands, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer."}}
D[9390] = {"Die Suche nach Sedai",{"Anachoret Obadei möchte, dass Ihr östlich von hier auf der Höllenfeuerhalbinsel nach seinem Bruder Sedai Ausschau haltet."}}
D[9391] = {"Den Weg kennzeichnen",{"Waldläuferhauptmann Venn'ren an der Falkenwacht möchte, dass Ihr auf der Höllenfeuerhalbinsel die große Kluft aufsucht und dort das südliche Leuchtsignal, westliche Leuchtsignal und das zentrale Leuchtsignal entzündet. Kehrt anschließend mit der brennenden Fackel zu ihm zurück."}}
D[9392] = {"Ausbildung zum Schurken",{"Sprecht mit Pfadpirscher Kariel - dem Schurkenlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer."}}
D[9393] = {"Ausbildung zum Jäger",{"Sprecht mit Waldläuferin Sallina - der Jägerlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer."}}
D[9394] = {"Wo ist Wyllithen?",{"Findet Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald."}}
D[9395] = {"Saltherils Hafen",{"Sprecht mit Lord Saltheril in Saltherils Hafen im Immersangwald."}}
D[9396] = {"Die Magie der Arakkoa",{"Bringt 4 Rollen der Haal'eshi zu Arkanist Calesthris Morgenstern bei der Falkenwacht auf der Höllenfeuerhalbinsel."}}
D[9397] = {"Kommt ein Vogel geflogen",{"Reist zum Haal'eshbau auf der Höllenfeuerhalbinsel und durchsucht die Kalirinester nach einem jungen Kaliriweibchen. Benutzt den leeren Vogelkäfig, um es zu fangen, und kehrt anschließend zu Falknerin Drenna Flusswind in der Falkenwacht zurück."}}
D[9398] = {"Tödliche Raubtiere",{"Späher Vanura im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr 8 Steinsichelwelpen und 4 Steinsichelalpha tötet."}}
D[9399] = {"Die Grausamkeit der Zuchtmeister",{"Reist zu den Ruinen von Sha'naar und erschlagt 4 Zuchtmeister der Illidari. Kehrt anschließend zu Ikan zum Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück."}}
D[9400] = {"Der Assassine",{"Nazgrel möchte, dass Ihr zu der Straße nördlich der Höllenfeuerzitadelle reist und nach einem Assassinen namens Krun Rückenbrecher Ausschau haltet."}}
D[9401] = {"Eine seltsame Waffe",{"Bringt die schwere Steinaxt zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9402] = {"Fangt!",{"Taucht auf den Grund des Stillwispertümpels und holt die Azurphiole für Instrukteur Antheol."}}
D[9403] = {"Das reinste Wasser",{"Instrukteur Antheol möchte, dass Ihr die Azurphiole bei den Elrendarfällen auffüllt."}}
D[9404] = {"Noch lebendig",{"Tötet die Immersangwaldbehüter bis Ihr einen lebendigen Zweig für Instrukteur Antheol findet."}}
D[9405] = {"Das Anliegen des Kriegshäuptlings",{"Bringt die schwere Steinaxt zu Scharfseherin Regulkut in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9406] = {"Die Mag'har",{"Bringt den Brief von den Mag'har zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9407] = {"Durch das Dunkle Portal",{"Reist durch das Dunkle Portal und meldet Euch bei Generalleutnant Orion. Er erwartet Euch auf der anderen Seite - in der Scherbenwelt."}}
D[9408] = {"Vergessene Helden",{"Sprecht mit Truppenkommandant Danath Trollbann in der Ehrenfeste."}}
D[9409] = {"Eilige Lieferung!",{"Bringt die Phiolensammlung zu Zalduun bei der Absturzstelle im Am'mental."}}
D[9410] = {"Spirituelle Führung",{"Verwendet das Wolfstotem an dem Ort, wo Ihr Krun Rückenbrechers Leichnam gefunden habt und folgt dem Ahnengeistwolf."}}
D[9415] = {"Meldung bei Marschall Himmelswand",{"Sprecht mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus."}}
D[9416] = {"Meldung bei General Kirika",{"Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus."}}
D[9417] = {"Die Arakkoabedrohung",{"Gremni Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Windspäher der Haal'eshi und 6 Krallenwachen der Haal'eshi tötet."}}
D[9418] = {"Avruus Kugel",{"Bringt Avruus Kugel zum Altar der Haal'eshi südöstlich des Haal'eshbaus auf der Höllenfeuerhalbinsel und gebt sie Aeranas, sobald er frei ist."}}
D[9419] = {"Durchkämmen der Wüste",{"Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Himmelswand beim Lager der Allianz in der Nähe des Zoraschwarmbaus."}}
D[9420] = {"Feinste Daunen",{"Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 8 Kalirifedern von den Kaliris im Haal'eshbau bringt."}}
D[9421] = {"Ausbildung zum Schamanen",{"Ich bin Firmanvaar und mich aufzusuchen war weise von Euch. Ich bin dazu berufen, Schamanen den richtigen Weg zu weisen, besonders denen, die wie Ihr noch unerfahren sind.","","Der Schamanismus wird von uns <Volk> gerade erst wiederentdeckt, <Name>. Ihr seid wahrhaft mutig, dieser Lehre zu folgen, denn unter Unseresgleichen wird sie mit Argwohn betrachtet.","","Ich bin hier, solltet Ihr meine Unterweisung wünschen."}}
D[9422] = {"Durchkämmen der Wüste",{"Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus."}}
D[9423] = {"Rückkehr zu Obadei",{"Kehrt zu Anachoret Obadei beim Tempel von Telhamat auf der Höllenfeuerhalbinsel zurück und berichtet ihm von Sedais Tod."}}
D[9424] = {"Makurus Rache",{"Makuru im Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 10 Ahnenperlen der Mag'har bringt."}}
D[9425] = {"Bericht an Tarrens Mühle",{"Reist nach Tarrens Mühle im Vorgebirge des Hügellands und sprecht mit Beraterin Morgenabend."}}
D[9426] = {"Die Teiche von Aggonar",{"Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar geht und 6 Teufelsblutschrecken und 6 mörderische Faulschleime tötet."}}
D[9427] = {"Reinigung des Wassers",{"Amaan der Weise möchte, dass Ihr zu den Teichen von Aggonar reist und die Reinigungsphiole bei Aggonars Leiche benutzt. Kehrt zu ihm zurück, wenn Ihr das Wasser von Aggonars Essenz befreit habt."}}
D[9428] = {"Bericht an den Splitterholzposten",{"Reist zum Splitterholzposten im Eschental und sprecht mit Berater Sonnenschwur."}}
D[9429] = {"Reist nach Dunkelhain",{"Reist nach Dunkelhain im Dämmerwald und sprecht mit Anachoret Delan."}}
D[9430] = {"Relikte von Sha'naar",{"Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr zu den Ruinen von Sha'naar reist und 10 Relikte von Sha'naar einsammelt."}}
D[9431] = {"Eine andere Lösung",{"Sammelt 2 Handvoll reinigende Erde von den donnernden Felskloppern und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten."}}
D[9432] = {"Reist nach Astranaar",{"Reist nach Astranaar im Eschental und sprecht mit Verteidigerin Palanaar."}}
D[9433] = {"Ein Tauchgang im Mondbrunnen",{"Benutzt die Bedienungseinheit für Robotron in der Nähe der versteckten Steuerungskonsole in einer kleinen Gruppe von Büschen am Rand der Nadel, die sich am dichtesten an Thalanaar befindet, und übernehmt die Steuerung des Robotron 3000. Steuert den Roboter zum westlichen Ende von tausend Nadeln zum Allianzaußenposten von Thalanaar. Benutzt den Roboter, um eine Probe Mondbrunnenwasser zu besorgen und bringt sie zu Wizlo Lagerputzer beim Weißgipfelposten."}}
D[9434] = {"Das Tonikum testen",{"Bringt die Kiste mit Reagenzien zu Magistrix Elosai im Freiwindposten."}}
D[9435] = {"Vermisste Kristalle",{"Besorgt die Lieferung seltener Kristalle von den Verlassenen und bringt sie zu Huraan in Süderstade zurück."}}
D[9436] = {"Erkenntnisse über die Blutskalpe",{"Nemeth Falkenauge im Basislager von Grom'gol möchte, dass Ihr ihm ein Totem der Blutskalpe von einem Schamanen der Blutskalpe bringt."}}
D[9437] = {"Der Untergang der Morgenbö",{"Balandar Sternenlicht in Brackenwall möchte, dass Ihr die Fracht der Morgenbö wiederholt und den Ersten Maat Ithania von den Streitkräften von Theramore in der Nordwacht befreit."}}
D[9438] = {"Bote für Thrall",{"Reist nach Orgrimmar und übergebt Thrall Nazgrels Brief."}}
D[9439] = {"Unabgeholtes Gepäck",{"Holt den Beutel des Beraters und das Rapier des Beraters aus der Festung Angor und kehrt dann zu Berater Sarophas in Kargath zurück."}}
D[9440] = {"Kleine Häppchen",{"Verfüttert die teuflischen Häppchen an die gefangenen Tiere der Verirrten. Bringt die Überbleibsel zu Cersei Abendsänger in Steinard in den Sümpfen des Elends."}}
D[9441] = {"Entsandt zu den Mag'har",{"Kehrt zu Gorkan Blutfaust beim Posten der Mag'har auf der Höllenfeuerhalbinsel zurück und bietet ihm im Namen Thralls Eure Dienste an."}}
D[9442] = {"Eine erschöpfende Krankheit",{"Erdruferin Ryga beim Posten der Mag'har auf der Höllenfeuerhalbinsel möchte, dass Ihr 1 Trockenkappe aus einer Höhle in der großen Kluft besorgt."}}
D[9443] = {"Das sogenannte Mal des Lichtbringers",{"Nehmt das Mal des Lichtbringers an Euch und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den westlichen Pestländern zurück."}}
D[9444] = {"Entweiht Uthers Grabmal",{"Entweiht Uthers Grabmal und kehrt anschließend zu Mehlar Dämmerklinge beim Bollwerk in den westlichen Pestländern zurück."}}
D[9446] = {"Das Grab des Lichtbringers",{"Begleitet Anachoret Truuen zu Uthers Grabmal in den westlichen Pestländern. Sprecht danach mit Hohepriesterin MacDonnell im Zugwindlager in den westlichen Pestländern."}}
D[9447] = {"Salbe verabreichen",{"Erdruferin Ryga möchte, dass Ihr die Heilsalbe 10 entkräfteten Grunzern beim Posten der Mag'har auf der Höllenfeuerhalbinsel verabreicht."}}
D[9448] = {"Mitleid mit den Verfluchten",{"Tötet 3 Verfluchte der Verirrten und kehrt dann zu Anachoret Avuun im sicheren Hafen in den Sümpfen des Elends zurück."}}
D[9449] = {"Ruf der Erde",{"Sprecht mit dem Geist des Tals beim heiligen Hain im Am'mental."}}
D[9450] = {"Ruf der Erde",{"Tötet 4 ruhelose Erdgeister und kehrt zum Geist des Tals beim heiligen Hain im Am'mental zurück."}}
D[9451] = {"Ruf der Erde",{"Bringt den Erdkristall zu Firmanvaar bei der Absturzstelle im Am'mental."}}
D[9452] = {"Schnapper - sehr, sehr lecker!",{"Verwendet das Fischernetz der Draenei, um 10 Schnapper zu fangen. Bringt die Fische und das Netz anschließend zu Diktynna auf der Azurmythosinsel zurück."}}
D[9453] = {"Findet Acteon!",{"Bringt die Ladung Schnapper zu Acteon bei der Azurwacht."}}
D[9454] = {"Die große Mondweidenjagd",{"Acteon bei der Azurwacht möchte, dass Ihr ihm 6 Mondweidenhirschlenden bringt."}}
D[9455] = {"Seltsame Funde",{"Bringt den schwach leuchtenden Kristall zu Exarch Menelaous bei der Azurwacht."}}
D[9456] = {"Nachtpirscherjagd",{"Exarch Menelaous bei der Azurwacht möchte, dass Ihr 8 infizierte Nachtpirscherjungen tötet."}}
D[9457] = {"Ein ungewöhnlicher Patron",{"Benutzt Naias' Gabe in der Nähe des Altars von Naias, um den Wasserelementar Naias zu rufen. Besiegt ihn und kehrt dann zu Nemeth Falkenauge im Basislager von Grom'gol mit dem Herz von Naias zurück."}}
D[9460] = {"Mit vereinten Kräften",{"Keltus Dunkellaub möchte, dass Ihr das spitzenverzierte Taschentuch von der Anführerin der Schildwachen stehlt und zu ihm bringt."}}
D[9461] = {"Ruf des Feuers",{"Geht zu Prophet Velen in der Halle des Lichts in der Exodar."}}
D[9462] = {"Ruf des Feuers",{"Geht zu Tuluun in der Azurwacht auf der Azurmythosinsel."}}
D[9463] = {"Medizinische Notwendigkeit",{"Anachoret Fateema bei der Azurwacht möchte, dass Ihr für sie 8 Lauerwurzranken sammelt."}}
D[9464] = {"Ruf des Feuers",{"Sprecht mit Glutos beim Glutgrund auf der Azurmythosinsel."}}
D[9465] = {"Ruf des Feuers",{"Erlangt die Ritualfackel wieder und bringt sie zu Glutos beim Glutgrund auf der Azurmythosinsel."}}
D[9466] = {"Gesucht: Schwarzkralle die Wilde",{"Bringt Schwarzkralles Klauen zu Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel."}}
D[9467] = {"Ruf des Feuers",{"Besorgt Euch Hauteurs Asche und bringt sie zusammen mit der Ritualfackel zu Glutos beim Glutgrund auf der Azurmythosinsel. Vergesst nicht, dass Ihr die Kugel der Rückkehr verwenden könnt, um zu Glutos zurückzukehren, sobald Ihr die Asche habt."}}
D[9468] = {"Ruf des Feuers",{"Bringt Hauteurs Asche zu Tuluun in der Azurwacht auf der Azurmythosinsel."}}
D[9469] = {"Federbarts Unterstützung",{"Geht zu Federbarts Hütte und stattet dem Zwerg dort einen Besuch ab. Solltet Ihr ihn nicht dort antreffen, so sucht nach Hinweisen auf seinen Verbleib."}}
D[9470] = {"Eine Geste des guten Willens",{"Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr Hexendoktor Mai'jin und seine Spinne Tcha'kaz tötet."}}
D[9471] = {"Die Raubtiere zur Beute machen",{"Botschafter Rualeth auf dem Nistgipfel möchte, dass Ihr 10 räudige Silbermähnen und 5 Silbermähnenwölfe tötet."}}
D[9472] = {"Arelions Geliebte",{"Magistrix Carinda bei der Falkenwacht auf der Höllenfeuerhalbinsel möchte, dass Ihr Viera Sonnenwisper aus der Siedlung herauslockt und Carindas Rolle der Vergeltung auf sie anwendet."}}
D[9473] = {"Eine alternative Alternative",{"Daedal bei der Azurwacht möchte, dass Ihr für ihn 5 Azurlöwenmäulchen sammelt."}}
D[9474] = {"Das Mal des Lichtbringers",{"Besorgt das Mal des Lichtbringers und kehrt dann zu Anachoret Truuen im Zugwindlager in den westlichen Pestländern zurück."}}
D[9475] = {"Wiedererlangen der Eier",{"Erlangt 5 Greifeneier und bringt sie zu Botschafter Rualeth beim Nistgipfel."}}
D[9476] = {"Suche nach Federbart",{"Reist nach Shadra'Alor und sucht nach Spuren von Federbart."}}
D[9483] = {"Die feinen Freuden im Leben",{"Nur weil wir auf dieser Pilgerfahrt sind, heißt das noch lange nicht, dass wir alle Freuden im Leben aufgeben müssen. Ich hatte schon seit Ewigkeiten keinen guten Wein mehr.","","Ich könnte im wahrsten Sinne des Wortes für einen gute Flasche Cenarischer Geistertropfen töten!","","Ich weiß, ich weiß, wie unpassend von mir, ein Nachtelfengebräu zu genießen."}}
D[9484] = {"Die Zähmung der Bestie",{"Verwendet die Zähmerrute, um einen wahnsinnigen Drachenfalken zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück."}}
D[9485] = {"Die Zähmung der Bestie",{"Verwendet die Zähmerrute, um eine Nebelfledermaus zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück."}}
D[9486] = {"Die Zähmung der Bestie",{"Verwendet die Zähmerrute, um eine alte Bachtatze zu zähmen. Kehrt anschließend zu Leutnant Dämmerflucht zurück."}}
D[9487] = {"Arkanhäscher",{"Arkanist Vandril möchte, dass Ihr 10 Arkantrümmer für ihn sammelt."}}
D[9488] = {"Eine einfache Robe",{"Arkanist Vandril möchte, dass Ihr ihm 15 Leinenstoff und eine Seidendrüse der Spindelweber bringt."}}
D[9489] = {"Ordnung in der Schneise",{"Wirkt das Machtwort: Seelenstärke auf 6 Waldläufer von Immersang in der Todesschneise."}}
D[9490] = {"Die Felsklauenmatriarchin",{"Besorgt Schwarzkralles Klauen von Schwarzkralle der Wilden in der großen Kluft und bringt sie zu Ikan beim Tempel von Telhamat auf der Höllenfeuerhalbinsel."}}
D[9491] = {"Gier",{"Eralan in Tristessa möchte, dass Ihr ihr einen gekörnten Goldring aus den Amanikatakomben bringt."}}
D[9492] = {"Das Schicksal wenden",{"Bringt Kriegshäuptling Kargaths Faust zu Truppenkommandant Danath Trollbann in der Ehrenfeste."}}
D[9493] = {"Der Stolz der Höllenhorde",{"Feldkommandeur Romus in der Ehrenfeste möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet."}}
D[9494] = {"Teufelsglut",{"Magus Zabraxis in der Ehrenfeste möchte, dass Ihr ihr ein Stück Teufelsglut bringt."}}
D[9495] = {"Der Wille des Kriegshäuptlings",{"Bringt Kriegshäuptling Kargaths Faust zu Nazgrel in Thrallmar."}}
D[9496] = {"Der Stolz der Höllenhorde",{"Schattenjäger Ty'jin in Thrallmar möchte, dass Ihr 8 Legionäre der Zerschmetterten Hand, 4 Zenturios der Zerschmetterten Hand und 4 Champions der Zerschmetterten Hand tötet."}}
D[9498] = {"Falkenwacht",{"Meldet Euch bei Waldläuferhauptmann Venn'ren bei der Falkenwacht auf der Höllenfeuerhalbinsel."}}
D[9499] = {"Falkenwacht",{"Reist zur Falkenwacht im Südwesten der Höllenfeuerhalbinsel und meldet Euch bei Waldläuferhauptmann Venn'ren."}}
D[9500] = {"Ruf des Wassers",{"Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel."}}
D[9501] = {"Ruf des Wassers",{"Sprecht mit Aqueous im versteckten Riff bei der Blutmythosinsel."}}
D[9502] = {"Ruf des Wassers",{"Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel."}}
D[9503] = {"Ruf des Wassers",{"Sammelt 6 besudelte Essenzen ein und bringt sie zu Aqueous im versteckten Riff bei der Blutmythosinsel."}}
D[9504] = {"Ruf des Wassers",{"Füllt den leeren Botabeutel und kehrt anschließend zu Aqueous im versteckten Riff bei der Blutmythosinsel zurück."}}
D[9505] = {"Die Prophezeiung von Velen",{"Daedal möchte, dass Ihr nach Süden reist und die Personen aufsucht, von denen das verletzte Wesen gesprochen hat."}}
D[9506] = {"Ein kleiner Anfang",{"Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr den von der Venture Co. gestohlenen nautischen Kompass und die nautische Karte wiederbeschafft."}}
D[9508] = {"Ruf des Wassers",{"Bringt Tel'athions Kopf zu Aqueous im versteckten Riff bei der Blutmythosinsel zurück."}}
D[9509] = {"Ruf des Wassers",{"Nehmt das Fläschchen mit reinstem Wasser zu Weissager Nobundo innerhalb der Exodar auf der Azurmythosinsel."}}
D[9510] = {"Bälge eines borstigen Grollhufs",{"Versorger Braknar beim Mag'harposten auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 5 Bälge eines borstigen Grollhufs bringt."}}
D[9511] = {"Kargaths Schlachtpläne"}
D[9512] = {"Kräckas Jumboeintopf",{"\"Kräcka\" Aschebäscha bei Odesyus' Ankerplatz möchte, dass Ihr ihm 6 Stücke Raubkriecherfleisch bringt."}}
D[9513] = {"Die Rückeroberung der Ruinen",{"Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr 5 Myrmidonen der Hasspranken, 5 Naga der Hasspranken und 5 Sirenen der Hasspranken tötet."}}
D[9514] = {"Runenbesetzte Schrifttafel",{"Bringt die runenbesetzte Schrifttafel zu Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel."}}
D[9515] = {"Kriegsherr Sriss'tiz",{"Priesterin Kyleen Il'dinare bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr Kriegsherr Sriss'tiz tötet."}}
D[9516] = {"Zerstört die Legion",{"Tötet 6 Mannorocpeitscher, 6 Teufelswachen und 6 Sengende Höllenbestien und kehrt dann zu Verteidiger Vedaar in Waldeslied im Eschental zurück."}}
D[9517] = {"Eine schändliche Verschwendung",{"Bringt 15 Stück Holz des Kriegshymnenklans und 5 Stück verdorbenes Satyrnaarholz zu Knorre in Waldeslied."}}
D[9518] = {"Agenten der Zerstörung",{"Schildwache Luciel Sternwisper in Waldeslied möchte, dass Ihr Vorarbeiter Gorthak, 2 Schredder des Kriegshymnenklans, 5 Roder der Horde und 10 Späher der Horde tötet."}}
D[9519] = {"Elunes Kelch",{"Bringt Elunes Kelch zu Kayneth Stillwind in Waldeslied."}}
D[9520] = {"Teuflische Pläne",{"Bringt die teuflischen Pläne zu Verteidiger Vedaar in Waldeslied im Eschental."}}
D[9521] = {"Bericht von der Nordfront",{"Bringt Schildwache Luciels Bericht zu Schildwache Weltensang im Hain der Silberschwingen."}}
D[9522] = {"Nie wieder!",{"Tötet Gorgannon und Diathorus den Sucher und kehrt danach zu Verteidiger Vedaar in Waldeslied im Eschental zurück."}}
D[9523] = {"Besondere Handhabung für kostbare und zerbrechliche Dinge",{"Archäologe Adamant Eisenherz bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm 8 uralte Relikte bringt."}}
D[9524] = {"Gefangene der Zitadelle",{"Rettet Hauptmann Alina aus der Höllenfeuerzitadelle, bevor sie hingerichtet wird.","","Um diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad 'Heroisch' betreten."}}
D[9525] = {"Gefangene der Zitadelle",{"Rettet Hauptmann Knochenbrecher aus der Höllenfeuerzitadelle, bevor er hingerichtet wird.","","Um diese Aufgabe zu beenden, müsst Ihr den Dungeon auf dem Schwierigkeitsgrad 'Heroisch' betreten."}}
D[9526] = {"Die Rückeroberung des Dämonenhügels",{"Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen und kehrt dann zu Knorre in Waldeslied im Eschental zurück."}}
D[9527] = {"Was noch bleibt",{"Cowlen auf der Azurmythosinsel möchte, dass Ihr ihm die Überreste von Cowlens Familie bringt."}}
D[9528] = {"Ein Hilferuf",{"Begleitet Magwin über die Insel zu ihrem Zuhause."}}
D[9529] = {"Der Stein",{"Beschafft Euch einen Leerstein von der Todesschneise."}}
D[9530] = {"Einen Plan aus Hecken",{"Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr ihm einen ausgehöhlten Stamm und 5 Laubhaufen bringt."}}
D[9531] = {"Laubangriff",{"Admiral Odesyus bei Odesyus' Ankerplatz auf der Azurmythosinsel möchte, dass Ihr das Treffen beobachtet, das Geezle und der Verräter gemeinsam ausgemacht haben.","","Kehrt zu ihm zurück, wenn Ihr ihm die Identität des Verräters mitteilen könnt."}}
D[9532] = {"Findet Keltus Dunkellaub",{"Macht Keltus Dunkellaub ausfindig."}}
D[9533] = {"Eine helfende Hand",{"Geht nach Waldeslied und sprecht mit Architekt Nemos."}}
D[9534] = {"Zerstört die Legion",{"Tötet 6 Mannorocpeitscher, 6 Teufelswachen und 6 sengende Höllenbestien und kehrt dann zu Valusha im Splitterholzposten in Eschental zurück."}}
D[9535] = {"Teuflische Pläne",{"Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental."}}
D[9536] = {"Nie wieder!",{"Tötet Gorgannon und Diathorus den Sucher und kehrt danach zu Velusha im Splitterholzposten im Eschental zurück."}}
D[9537] = {"Keine Gnade mit dem Gnom",{"Admiral Odesyus bei Odesyus' Ankerplatz möchte, dass Ihr die Mitteilung des Verräters von Ingenieur \"Funks\" Oberschleif an Euch bringt."}}
D[9538] = {"Erlernen der Sprache",{"Lest die Übersetzungsfibel der Tannenruhfeste, die Aurren Euch gegeben hat. Kommuniziert anschließend mit dem Totem von Akida bei der Azurwacht."}}
D[9539] = {"Totem von Coo",{"Findet das Totem von Coo, indem Ihr den Hinweisen folgt."}}
D[9540] = {"Totem von Tikti",{"Findet das Totem von Tikti, indem Ihr den Hinweisen folgt."}}
D[9541] = {"Totem von Yor",{"Findet das Totem von Yor, indem Ihr den Hinweisen folgt."}}
D[9542] = {"Totem von Vark",{"Findet das Totem von Vark, indem Ihr den Hinweisen folgt."}}
D[9543] = {"Sühne",{"Sprecht mit Amaan dem Weisen beim Tempel von Telhamat auf der Höllenfeuerhalbinsel."}}
D[9544] = {"Die Prophezeiung von Akida",{"Befreit 8 gefangene Furbolgs der Tannenruhfeste aus den Käfigen im Dorf der Sichelklauen. Kehrt anschließend zu Arugoo der Tannenruhfeste bei der Azurwacht zurück."}}
D[9545] = {"Das Relikt des Sehers",{"Amaan der Weise beim Tempel von Telhamat auf der Höllenfeuerhalbinsel möchte, dass Ihr Sedais Leichnam erneut aufsucht, um dort das Relikt des Sehers zu benutzen. Kehrt nach Abschluss der Aufgabe zu ihm zurück."}}
D[9547] = {"Ruf der Luft",{"Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel."}}
D[9548] = {"Gestohlene Ausrüstung",{"Bringt Kloppers Ausrüstung zurück zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält."}}
D[9549] = {"Schwarzschlammartefakte",{"Bringt 3 kunstlose Murlocgötzen und 6 kunstlose Murlocmesser zu Klopper Knacksklug, der sich in einem angespülten Schildkrötenpanzer versteckt hält."}}
D[9550] = {"Wohin führt die Karte?",{"Macht den auf der Karte beschriebenen Pavillon ausfindig und sucht, auf was der Verfasser der Karte hinweisen wollte."}}
D[9551] = {"Ruf der Luft",{"Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel."}}
D[9552] = {"Ruf der Luft",{"Sprecht mit Velaada beim Wildwindgipfel auf der Azurmythosinsel."}}
D[9553] = {"Ruf der Luft",{"Sprecht mit Susurrus beim Wildwindgipfel auf der Azurmythosinsel."}}
D[9554] = {"Ruf der Luft",{"Kehrt mit dem Luftwirbel zu Weissager Nobundo bei der Exodar auf der Azurmythosinsel zurück."}}
D[9555] = {"Ruf des Feuers",{"Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar."}}
D[9556] = {"Dem Sieger...",{"Sucht nach einer Phiole mit heiligem Wasser in Stratholme und bringt sie zu dem Magier von Lordaeron im Magierviertel von Sturmwind oder in Unterstadt, falls Eure Seite in den östlichen Pestländern erfolgreich war."}}
D[9557] = {"Entziffern des Buchs",{"Bringt das alte Tagebuch zu Anachoret Paetheus bei der Blutwacht."}}
D[9558] = {"Die Langbarts",{"Sucht nach Gremni Langbart nordwestlich des Haal'eshbaus, weit im Westen der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[9559] = {"Tannenruhfeste",{"Sprecht mit dem Oberhäuptling bei der Tannenruhfeste."}}
D[9560] = {"Biester aus der Apokalypse!",{"Moordo bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr ihm 8 Felshetzerbälge bringt."}}
D[9561] = {"Nolkais Worte",{"Findet den in Nolkais Tagebuch beschriebenen Ort und sucht nach seinen seit langem vergrabenen Besitztümern."}}
D[9562] = {"Murlocs... Warum hier? Warum jetzt?",{"Gurf bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr 5 Säcke mit Tannenruhgetreide wiedererlangt."}}
D[9563] = {"Mirrens Vertrauen erlangen",{"Mirren Langbart auf der Höllenfeuerhalbinsel möchte, dass Ihr ihm 1 Nethergarde Bitter bringt. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Ehrenfeste."}}
D[9564] = {"Gurfs Würde",{"Bringt Gurfs Würde zu Gurf bei der Tannenruhfeste auf der Azurmythosinsel."}}
D[9565] = {"Sucht in der Tannenruhfeste",{"Sucht in der Tannenruhfeste nach Hinweisen."}}
D[9566] = {"Blutkristalle",{"Sprecht mit dem Oberhäuptling bei der Tannenruhfeste."}}
D[9567] = {"Kenne deinen Feind",{"Findet das Monument der Nazzivus in Nazzivian und beschafft Euch eine Glyphe vom Monument der Nazzivus. Kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück, sobald Ihr die Glyphe habt."}}
D[9568] = {"In der Offensive",{"Verteidigerin Aalesia bei der Blutwacht möchte, dass Ihr 10 Satyrn der Nazzivus, 5 Schurken der Nazzivus und 5 Teufelsanbeter der Nazzivus tötet."}}
D[9569] = {"Die Bedrohung bekämpfen",{"Tötet 5 Schattenpirscher von Axxarien, 5 Höllenrufer von Axxarien und Zevrax. Sammelt außerdem 5 verderbte Kristalle ein und kehrt zu Verteidigerin Aalesia bei der Blutwacht zurück."}}
D[9570] = {"Kurken lauert",{"Kurz der Weise bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Kurken tötet und dass Ihr ihm Kurkens Balg bringt."}}
D[9571] = {"Kurkens Balg",{"Bringt Kurkens Balg zu Moordo bei der Tannenruhfeste."}}
D[9572] = {"Die Bollwerke schwächen",{"Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Caza'rez in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9573] = {"Häuptling Oomooroo",{"Der Jüngling Tannenruh bei der Tannenruhfeste auf der Azurmythosinsel möchte, dass Ihr Häuptling Oomooroo und 9 wahnsinnige Wildekin tötet."}}
D[9574] = {"Opfer der Verderbnis",{"Bringt 6 Stücke kristallisierte Rinde zu Morae bei der Blutwacht."}}
D[9575] = {"Die Bollwerke schwächen",{"Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[9576] = {"Schandflosses Anhänger",{"Bringt den roten Kristallanhänger zu Morae bei der Blutwacht."}}
D[9578] = {"Suche nach Galaen",{"Sucht nach Moraes Mann Galaen."}}
D[9579] = {"Galaens Schicksal",{"Bringt Galaens Amulett zu Morae bei der Blutwacht."}}
D[9580] = {"Bärdarfsgüter",{"Bringt 8 Flanken eines alten Braunbären zu Fährtenleser Lyceon bei der Blutwacht."}}
D[9581] = {"Von den Kristallen lernen",{"Benutzt die Kristallspitzhacke, um eine Kristallprobe der Absturzstelle von einem Kristall der Absturzstelle zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht."}}
D[9582] = {"Die Stärke des Einen",{"Öffnet den Felshetzerkäfig und tötet den darin befindlichen Todesfelshetzer. Kehrt dann zu Ruada in der Azurwacht auf der Azurmythosinsel zurück."}}
D[9584] = {"Die zweite Probe",{"Benutzt die Kristallspitzhacke, um eine Veränderte Kristallprobe von einem veränderten Blutmythoskristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht."}}
D[9585] = {"Die letzte Probe",{"Benutzt die Kristallspitzhacke, um eine Axxarienkristallprobe von einem Axxarienkristall zu nehmen. Bringt die Probe zu Herold Mikolaas bei der Blutwacht."}}
D[9586] = {"Helft Tavara",{"Guvan bei der Azurwacht möchte, dass Ihr Tavara findet und ihre Wunden heilt."}}
D[9587] = {"Düstere Neuigkeiten",{"Bringt den unheilvollen Brief zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[9588] = {"Düstere Neuigkeiten",{"Bringt den unheilvollen Brief zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9589] = {"Blut bedeutet Leben",{"Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[9590] = {"Blut bedeutet Leben",{"Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Zenturio Caza'rez in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9591] = {"Die Zähmung der Bestie",{"Benutzt das Zähmertotem, um einen Stachelkriecher zu bändigen. Kehrt nach gelungenem Unterfangen zu Jägerin Kella Nachtbogen zurück."}}
D[9592] = {"Die Zähmung der Bestie",{"Benutzt das Zähmertotem, um einen großen Grünschreiter zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück."}}
D[9593] = {"Die Zähmung der Bestie",{"Benutzt das Zähmertotem, um einen Nachtpirscher zu bändigen und kehrt anschließend zu Jägerin Kella Nachtbogen zurück."}}
D[9594] = {"Zeichen der Legion",{"Tötet 8 Satyrn der Nazzivus und 8 Teufelsanbeter der Nazzivus. Bringt anschließend Tzeraks Panzerplatte zu Verteidigerin Aalesia bei der Blutwacht."}}
D[9595] = {"Kontrolle",{"Vernichtet die Murlocs der Schlickerküste, um einen Magiergeist der Quel'dorei zu rufen, und vernichtet ihn. Sprecht dann mit Bati in der Halle des Lichts in der Exodar."}}
D[9598] = {"Erlösung",{"Lest das Buch der Offenbarung und sprecht mit Jol."}}
D[9599] = {"<UNUSED>",{"Sprecht mit Jol in der Exodar."}}
D[9600] = {"Erlösung",{"Jol möchte, dass Ihr einen jungen Schamanen der Furbolgs mit dem Symbol des Lebens wieder zum Leben erweckt und dass Ihr anschließend wieder zu ihr zurückkehrt."}}
D[9601] = {"Zum Bollwerk",{"Sprecht mit Mehlar Dämmerklinge beim Bollwerk."}}
D[9602] = {"Unheilvolle Mitteilung",{"Bringt die Mitteilung des Verräters zu Exarch Menelaous bei der Azurwacht."}}
D[9603] = {"Betten, Verbände und noch viel mehr",{"Bringt Tophers Liste zu Laando, dem Hippogryphenmeister bei der Blutwacht."}}
D[9604] = {"Auf dem Rücken eines Hippogryphen",{"Erwerbt bei Laando einen Hippogryphenritt zur Exodar. Bringt Tophers Liste nach der Landung zu Nurguni im Sitz der Naaru der Exodar."}}
D[9605] = {"Hippogryphenmeister Stephanos",{"Geht zu Stephanos in der Exodar und erwerbt einen Hippogryphenritt zurück zur Blutwacht."}}
D[9606] = {"Zurück zu Topher Loaal",{"Sprecht mit Stephanos und erwerbt einen Hippogryphenritt zurück zur Blutwacht. Bringt Nurgunis Vorräte nach Eurer Ankunft zu Versorger Topher Loaal."}}
D[9607] = {"Im Herzen des Hasses",{"Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[9608] = {"Im Herzen des Hasses",{"Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9609] = {"Helft Behüter Biggs",{"Sucht Behüter Biggs in den Sümpfen des Elends."}}
D[9610] = {"Der Tränenteich",{"Besorgt 10 Artefakte der Atal'ai und bringt sie zu Holaaru im sicheren Hafen in den Sümpfen des Elends."}}
D[9612] = {"Herzlichen Dank!",{"Sprecht mit Exarch Menelaous bei der Azurwacht."}}
D[9616] = {"Banditen!",{"Nehmt das Blutelfendokument zu Exarch Menelaous bei der Azurwacht."}}
D[9617] = {"Sucht die Weltenwanderer auf",{"Sprecht mit Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer."}}
D[9618] = {"Überbringen der Berichte",{"Bringt Keltus Dunkellaubs Berichte zu Zelanis in Silbermond."}}
D[9619] = {"Beschwörungsrune",{"Verwendet den Leerstein, um einen Leerwandler in Goldnebel zu beschwören. Bezwingt ihn und kehrt zu Talionia in Silbermond zurück."}}
D[9620] = {"Das vermisste Vermessungsteam",{"Herold Mikolaas möchte, dass Ihr das Vermessungsteam findet, das er zu den Ruinen von Loreth'Aran entsendet hatte, und dass Ihr dem Team so gut es geht zur Seite steht."}}
D[9621] = {"Gesandter zur Horde",{"Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal."}}
D[9622] = {"Warnt vor der Gefahr",{"Sprecht mit Exarch Menelaous bei der Azurwacht."}}
D[9623] = {"Reiferwerden",{"Exarch Menelaous bei der Azurwacht hat Euch gebeten, die Befehle des Exarchen zu Torallius dem Herdentreiber, der außerhalb der Exodar steht, zu bringen."}}
D[9624] = {"Lieblingsleckerli",{"Aonar bei Kessels Wegelager möchte, dass Ihr ihm 10 Sandbirnen bringt."}}
D[9625] = {"Elekk sind starker Tobak",{"Sprecht mit Vorkhan dem Elekktreiber auf der Blutmythosinsel."}}
D[9626] = {"Ein Treffen mit dem Kriegshäuptling",{"Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zu Thrall nach Orgrimmar, Hauptstadt von Durotar, bringt."}}
D[9627] = {"Treue gegenüber der Horde",{"Kehrt nach Silbermond zurück und erstattet Lor'themar Theron Bericht."}}
D[9628] = {"Bergung der Daten",{"Erlangt den Vermessungsdatenkristall von den Hasspranken nahe der toten Kartografen wieder und bringt ihn zu Herold Mikolaas bei der Blutwacht."}}
D[9629] = {"Kurz geschnappt",{"Morae bei der Blutwacht möchte, dass Ihr 6 Späher der Schwarzschlammküste mit einem Murlocsender 'markiert'."}}
D[9630] = {"Medivhs Tagebuch",{"Erzmagier Alturus am Gebirgspass der Totenwinde möchte, dass Ihr nach Karazhan geht und mit Wravien sprecht."}}
D[9631] = {"Hilfe unter Kollegen",{"Bringt das verkohlte Knochenfragment zu Kalynna Lathred in Area 52 im Nethersturm."}}
D[9632] = {"Neue Verbündete",{"Bringt das Vorstellungsschreiben zu Jägerin Kella Nachtbogen."}}
D[9633] = {"Der Weg nach Auberdine",{"Nehmt das Schiff in der Nähe von Jägerin Kella Nachtbogen nach Auberdine. Bringt das Vorstellungsschreiben zu Thundris Windwirker, sobald Ihr in Auberdine angekommen seid."}}
D[9634] = {"Raubtiere aus einer anderen Welt",{"Tötet 10 junge Blutfelshetzer und kehrt danach zu Vorkhan dem Elekktreiber bei Kessels Wegelager auf der Blutmythosinsel zurück."}}
D[9635] = {"Der schockdrosselnde Partikelextraktor!",{"Bringt 15 Dampfpumpenteile zu Mack Dyver in Zabra'jin in den Zangarmarschen."}}
D[9636] = {"Der schockdrosselnde Partikelextraktor!",{"Bringt 15 Dampfpumpenteile zu K. Lee Kleinfrey in Telredor in den Zangarmarschen."}}
D[9637] = {"Kalynnas Bitte",{"Kalynna Lathred möchte, dass Ihr den Dämmerfolianten vom Großhexenmeister Nethekurse in den Zerschmetterten Hallen der Höllenfeuerzitadelle und das Buch der vergessenen Namen von Dunkelwirker Syth in den Sethekkhallen in Auchindoun besorgt.","","Ihr müsst diese Quest auf dem Schwierigkeitsgrad 'Heroisch' abschließen."}}
D[9638] = {"In guten Händen",{"Sprecht mit Gradav in der Bibliothek des Wächters in Karazhan."}}
D[9639] = {"Kamsis",{"Sprecht mit Kamsis in der Bibliothek des Wächters in Karazhan."}}
D[9640] = {"Arans Schemen",{"Beschafft Medivhs Tagebuch und kehrt zu Kamsis in der Bibliothek des Wächters in Karazhan zurück."}}
D[9641] = {"Bestrahlte Kristallsplitter",{"Verteidiger Boros bei der Blutwacht möchte, dass Ihr ihm 10 bestrahlte Kristallsplitter bringt."}}
D[9642] = {"Mehr bestrahlte Kristallsplitter",{"Solltet Ihr noch über mehr bestrahlte Kristallsplitter verfügen, tausche ich sie gerne gegen einen weiteren meiner Kristalle ein."}}
D[9643] = {"Würgeranken",{"Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr ihm 6 dornige Würgeranken bringt."}}
D[9644] = {"Schrecken der Nacht",{"Geht zur Terrasse des Meisters in Karazhan und benutzt Kalynnas Urne, um den Schrecken der Nacht zu rufen. Entzieht dem Körper des Schreckens die schwache arkane Essenz und bringt sie zu Erzmagier Alturus."}}
D[9645] = {"Die Terrasse des Meisters",{"Geht zur Terrasse des Meisters in Karazhan und lest Medivhs Tagebuch. Kehrt danach mit Medivhs Tagebuch zu Erzmagier Alturus zurück."}}
D[9646] = {"GESUCHT: Todespranke",{"Bringt Todesprankes Tatze zu Herold Mikolaas bei der Blutwacht."}}
D[9647] = {"Ausmerzen der Falter",{"Fährtenleser Lyceon bei der Blutwacht möchte, dass Ihr 10 königliche blaue Falter tötet."}}
D[9648] = {"Pilzsammlung von Mac'Aree",{"Jessera von Mac'Aree bei der Blutwacht möchte 1 Wasserstinkmorchel, 1 Blutpilz, 1 ruinösen Birkensporling und 1 Teufelszapfenfungus."}}
D[9649] = {"Yseras Tränen",{"Jessera von Mac'Aree bei der Blutwacht möchte 2 Yseras Tränen."}}
D[9663] = {"Der Korsallauf",{"Kessel bei Kessels Wegelager möchte, dass Ihr den Oberhäuptling der Tannenruhfeste, Exarch Menelaous bei der Azurwacht und Admiral Odesyus bei Odesyus' Ankerplatz vor der unmittelbar bevorstehenden Blutelfeninvasion warnt. Ihr habt 15 Minuten. Kehrt anschließend zu Kessel zurück. Denkt daran, dass Elekks wasserscheu sind!"}}
D[9664] = {"Mehr Befestigungen",{"Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Weißbart bei der Kapelle des hoffnungsvollen Lichts zurück."}}
D[9665] = {"Verstärkung der Verteidigung",{"Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Gormok bei der Kapelle des hoffnungsvollen Lichts zurück."}}
D[9666] = {"Demonstration der Macht",{"Kessel bei Kessels Wegelager auf der Blutmythosinsel möchte, dass Ihr Lord Xiz bei der Hassprankenzuflucht tötet und das Banner der Draenei durch seinen Körper stoßt."}}
D[9667] = {"Rettet die Prinzessin der Tannenruhfeste",{"Befreit die Prinzessin der Tannenruhfeste aus ihrem Käfig und sprecht anschließend mit Botschafter Frasaboo der Tannenruhfeste bei der Blutwacht.","","Ihr müsst den Oberhäuptling der Sichelklauen töten, um an den Schlüssel für den Käfig zu gelangen."}}
D[9668] = {"Erstattet Exarch Admetius Bericht",{"Sprecht mit Exarch Admetius bei der Blutwacht."}}
D[9669] = {"Forschungsreise in den Tod",{"Tötet 8 Mythosspinner, 8 Mythosfänger und ihre Anführerin Zarakh. Kehrt anschließend zu Achelus bei der Blutwacht zurück."}}
D[9670] = {"Sie leben! Vielleicht...",{"Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien."}}
D[9671] = {"Dringende Nachricht",{"Seid Ihr <Name>? Es wurde auch Zeit! Ich war gerade dabei, die Suche nach Euch aufzugeben!","","Beim Briefkasten wartet eine dringende Nachricht auf Euch. Die Person, die sie mir übergeben hatte, war ein Admiral der Menschen von der Azurmythosinsel. Admiral Odesy-irgendwas... der Name ist mir entfallen. Er sagte, Ihr würde wissen, wer er sei."}}
D[9672] = {"Das Vermächtnis des Blutfluchs",{"Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen."}}
D[9673] = {"Wildtierausbildung",{"Sprecht mit Halthenis in Silbermond."}}
D[9674] = {"Die Naga des Blutfluchs",{"Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 10 Naga des Blutfluchs tötet."}}
D[9675] = {"Wildtierausbildung",{"Sprecht mit Ganaar bei der Händlertreppe der Exodar."}}
D[9676] = {"Ausbildung zum Paladin",{"Sprecht mit Jesthenis Sonnensturm - dem Paladinlehrer - im Sonnenturm auf der Insel der Sonnenwanderer."}}
D[9677] = {"Aufforderung des Ritterfürsten Heldenblut",{"Sprecht mit Ritterfürst Heldenblut beim Platz der Weltenwanderer in Silbermond."}}
D[9678] = {"Die erste Prüfung",{"Reist zu der Insel, die Euch Ritterfürst Heldenblut beschrieben hat, sucht die Höhle und entzündet die Kohlepfanne. Kehrt, nachdem Ihr die erste Prüfung bestanden habt, zu Ritterfürst Heldenblut in Silbermond zurück."}}
D[9680] = {"Die Vergangenheit aufwühlen",{"Erzmagier Alturus möchte, dass Ihr zu den Bergen südlich von Karazhan im Gebirgspass der Totenwinde geht und ein verkohltes Knochenfragment besorgt."}}
D[9681] = {"Eine Studie der Macht",{"Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen."}}
D[9682] = {"Die Hoffnungslosen...",{"Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr 4 Seelen des Blutfluchs zu ihm bringt."}}
D[9683] = {"Beendigung des Blutfluchs",{"Kapitän Edward Hanes auf der Insel Drachenfels möchte, dass Ihr die Statue der Königin Azshara zerstört und Atoph des Blutfluchs tötet."}}
D[9684] = {"Die Beherrschung des Lichts",{"Wendet das schimmernde Gefäß auf die Magister der Blutelfen an, um es zu füllen und kehrt anschließend zu Ritterfürst Heldenblut in Silbermond zurück."}}
D[9685] = {"Die Erlösung der Toten",{"Bringt das gefüllte schimmernde Gefäß zum Gasthaus von Silbermond und verwendet seine Magie, um Sangrias Stillstreich wiederzubeleben."}}
D[9686] = {"Die zweite Prüfung",{"Besteht die zweite Prüfung und besiegt Champion Rachblut, Champion Lichtrend, Champion Schnellklinge und Champion Sonnensturm im Pavillon in der Nähe von Meister Kelerun Blutpein."}}
D[9687] = {"Wiederherstellung der Heiligkeit",{"Prinz Toreth auf der Insel Drachenfels möchte, dass Ihr 8 Drachenknochen wiedererlangt."}}
D[9688] = {"Im Traum",{"Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr 5 Viridianwelpen und 5 Viridianbrutlinge tötet."}}
D[9689] = {"Messerrachen",{"Prinz Toreth auf der Insel Drachenfels hat von Euch verlangt, dass Ihr Messerrachen tötet."}}
D[9690] = {"Die zweite Prüfung",{"Meldet Euch bei Meister Kelerun Blutpein."}}
D[9691] = {"Rückkehr nach Silbermond",{"Kehrt zu Ritterfürst Heldenblut nach Silbermond zurück."}}
D[9692] = {"Der Pfad des Adepten",{"Bringt Ritterfürst Heldenblut in Silbermond einen verderbten Koredelstein, eine Kiste mit blutgeschmiedeten Blöcken, etwas Blut des Hasserfüllten und ein Insigne der Blutritter."}}
D[9693] = {"Was Argus für mich bedeutet",{"Exarch Admetius bei der Blutwacht wies Euch an, mit Verteidiger Boros zu sprechen."}}
D[9694] = {"Blutwacht",{"Verteidiger Boros bei der Blutwacht möchte, dass Ihr 10 Spione der Sonnenfalken tötet."}}
D[9696] = {"Übersetzungen...",{"Bringt das Schreiben der Sonnenfalken zur Vernehmungsbeauftragten Elysia bei der Blutwacht."}}
D[9697] = {"Behüterin Leesa'oh",{"Sprecht mit Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen."}}
D[9698] = {"Audienz beim Propheten",{"Bringt das übersetzte Schreiben der Sonnenfalken zum Propheten Velen bei der Exodar."}}
D[9699] = {"Was ist wahr?",{"Bringt Velens Anordnungen zu Verteidiger Boros bei der Blutwacht."}}
D[9700] = {"Licht ins Dunkel bringen",{"Verteidiger Boros bei der Blutwacht möchte, dass Ihr die Lage des Sonnenportals ausfindig macht und 5 Anomalien der Leere tötet."}}
D[9701] = {"Sporlinge beobachten",{"Untersucht das Pilzgeflecht in den Zangarmarschen und berichtet danach Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen von Euren Beobachtungen."}}
D[9702] = {"Eine Frage der Fressgier",{"Sammelt 10 Stück liegengelassene Nahrung und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück."}}
D[9703] = {"Der Kryokern",{"Verteidiger Kuros bei der Blutwacht möchte, dass Ihr 12 Kisten mit Heilvorräten sichert."}}
D[9704] = {"Von den Getriebenen getötet",{"Geht nach Süden zu den Ruinen von Silbermond und haltet nach der getöteten Kundschafterin beim Dämmerweg Ausschau."}}
D[9705] = {"Bergung des Päckchens",{"Kehrt mit Eronas Päckchen zu Kundschafterin Alarion zurück."}}
D[9706] = {"Galaens Tagebuch - Das Schicksal von Verteidiger Saruan",{"Bringt Galaens Tagebuch zu Verteidiger Kuros bei der Blutwacht."}}
D[9707] = {"Das Schmieden der Waffe",{"Bringt die Kiste mit Rohmaterialien zu Bemarrin in Silbermond."}}
D[9708] = {"Bekannter Pilz",{"Sammelt 15 Pilzproben und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück."}}
D[9709] = {"Die Pilze zurückstehlen",{"Sammelt 10 Kisten Pilze und kehrt dann zu Behüterin Leesa'oh im Wachposten des Cenarius in den Zangarmarschen zurück."}}
D[9710] = {"Der blutgehärtete Ranseur",{"Wartet, während Bemarrin Eure Waffe schmiedet."}}
D[9711] = {"Matis der Grausame",{"Verteidiger Kuros bei der Blutwacht möchte, dass Ihr Matis den Grausamen gefangen nehmt."}}
D[9712] = {"Das thalassische Schlachtross",{"Sprecht mit Ritterfürst Heldenblut, um zu erfahren, wie Ihr Euer thalassisches Schlachtross beschwören könnt."}}
D[9713] = {"Glowcap Harvesting Enabling Flag"}
D[9714] = {"Bringt mir ein weiteres Gebüsch!",{"Wir können immer noch mehr Bluthibiskus von den Schlurfern, Sumpfriesen und Tiefenfledermäusen im Echsenkessel gebrauchen. Bringt sie mir in Bündeln zu je fünf, und ich werde Euch sehr dankbar sein."}}
D[9715] = {"Bringt mir ein Gebüsch!",{"Sammelt 5 Stück Bluthibiskus und bringt sie zu Gzhun'tt in Sporeggar in den Zangarmarschen."}}
D[9716] = {"Anomalie am Umbrafennsee",{"Untersucht den Grund für die sinkenden Wasserspiegel am Umbrafennsee. Kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück."}}
D[9717] = {"Los geht's!",{"Besorgt einen Tiefensporenfarn und bringt ihn zu T'shu in Sporeggar in den Zangarmarschen."}}
D[9718] = {"Der Flug der Krähe",{"Ysiel Windsänger möchte, dass Ihr das Sturmkrähenamulett benutzt, um die größeren Seen in den Zangarmarschen zu erkunden."}}
D[9719] = {"Tötet die Mutter",{"Bringt das Gehirn der Schattenmutter zu Khn'nix in Sporeggar in den Zangarmarschen."}}
D[9720] = {"Das Gleichgewicht muss erhalten bleiben",{"Ysiel Windsänger möchte, dass Ihr die Eisenrankensamenkörner benutzt, um die Dampfpumpensteuerungen am Schlangensee, Umbrafennsee, Sumpflichtsee und der Lagune zu zerstören. Kehrt danach mit den übrigen Samen zu ihr in die Zuflucht des Cenarius in den Zangarmarschen zurück."}}
D[9721] = {"Aufforderung von Lord Solanar",{"Sprecht mit Lord Solanar Blutzorn in Silbermond."}}
D[9722] = {"Der Pfad des Meisters",{"Sprecht nochmals mit Lord Solanar Blutzorn, um seine angebotene Unterstützung für Eure Aufnahme zu akzeptieren."}}
D[9723] = {"Eine Geste der Hingabe",{"Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lord Solanar Blutzorn in Silbermond."}}
D[9724] = {"Den Zirkel des Cenarius warnen",{"Sprecht mit Amythiel Nebelgänger beim Posten des Cenarius auf der Höllenfeuerhalbinsel."}}
D[9725] = {"Eine Demonstration Eurer Loyalität",{"Lord Solanar Blutzorn in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet."}}
D[9726] = {"Jetzt, da wir Freunde sind...",{"Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun'tt in Sporeggar in den Zangarmarschen zurück."}}
D[9727] = {"Jetzt, da wir immer noch Freunde sind...",{"Tötet 12 Sklaventreiber der Blutschuppen und 6 Verzauberinnen der Blutschuppen und kehrt dann zu Gzhun'tt in Sporeggar in den Zangarmarschen zurück."}}
D[9728] = {"Ein herzliches Willkommen",{"Bringt 30 Nagaklauen zu Aufseher Hamuht in der Zuflucht des Cenarius."}}
D[9729] = {"Fhwoor zerschmettern!",{"Begleitet Fwoohr in das Gebiet bei der Dampfpumpe am Sumpflichtsee, um die Lade von Ssslith zu holen. Bringt Fhwoor und die Lade sicher zurück und meldet Euch bei Gzhun'tt in Sporeggar in den Zangarmarschen."}}
D[9730] = {"Anführer der Dunkelkämme",{"Tötet Rajah Haghazed bei der Lagune und kehrt danach zu Aufseher Hamuht bei der Expedition des Cenarius in den Zangarmarschen zurück, um eine Belohnung zu erhalten."}}
D[9731] = {"Kanalisationspläne",{"Durchsucht den Grund des Schlangensees nach einem Ablauf. Kehrt mit Neuigkeiten über Eure Entdeckung zu Ysiel Windsänger in der Zuflucht des Cenarius zurück."}}
D[9732] = {"Rückkehr in die Marschen",{"Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück."}}
D[9733] = {"Warnung an den Zirkel des Cenarius",{"Sprecht mit Mahuram Starkhuf in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[9734] = {"Rückkehr in die Marschen",{"Kehrt zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück."}}
D[9735] = {"Wahre Meister des Lichts",{"Bringt Lord Solanar Blutzorn in Silbermond eine Phiole Weihwasser von Tyrs Hand."}}
D[9736] = {"Wahre Meister des Lichts",{"Bringt Lord Solanar Blutzorn in Silbermond 1 arkanen Katalysator, 1 Einheit krepuskulares Pulver, 1 azerothischen Diamanten und 1 makellosen schwarzen Diamanten."}}
D[9737] = {"Wahre Meister des Lichts",{"Verwendet die Löschmischung in der Nähe der ewigen Flamme in der Alonsuskapelle, um den Schutz des Lichts zu brechen. Seid bereit, jeden zu töten, der versucht, die Kapelle zu verteidigen."}}
D[9738] = {"Bei der Arbeit verschollen",{"Findet heraus, was mit Erdbinder Rayge, Naturalist Biss, Jäter Gründaum und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang im Echsenkessel in den Zangarmarschen zurück."}}
D[9739] = {"Die Misere der Sporlinge",{"Fahssn im Pilzgeflecht möchte, dass Ihr 10 reife Sporenbeutel sammelt."}}
D[9740] = {"Das Sonnentor",{"Verteidiger Aesom bei der Blutwacht möchte, dass Ihr das Sonnentor zerstört."}}
D[9741] = {"Geschöpfe aus der Leere",{"Tötet 12 Geschöpfe der Leere und erstattet Verteidiger Aesom bei der Blutwacht Bericht."}}
D[9742] = {"Noch ein paar Sporensäcke",{"Habt Ihr noch mehr Sporensäcke gerettet, <Volk>?"}}
D[9743] = {"Natürliche Feinde",{"Bringt 6 Sumpflordranken zu Fahssn im Pilzgeflecht in den Zangarmarschen."}}
D[9744] = {"Mehr Ranken!",{"Ihr habt viele Riesen getötet, aber es sind immer noch viele übrig. Und sie greifen immer noch unsere Sporenbeutel an!"}}
D[9746] = {"Grenze der Erschöpfung",{"Verteidiger Aesom bei der Blutwacht möchte, dass Ihr 10 Pyromanten der Sonnenfalken und 10 Verteidiger der Sonnenfalken tötet."}}
D[9747] = {"Der Umbrafennstamm",{"Ikeyen in der Zuflucht des Cenarius möchte, dass Ihr nach Umbrafenn reist und Kataru, 8 Seher von Umbrafenn, 6 Hexendoktoren von Umbrafenn und 6 Orakel von Umbrafenn tötet."}}
D[9748] = {"Trinkt nicht das Wasser",{"Verteidiger Aesom bei der Blutwacht möchte, dass Ihr den Wasserprobenbehälter verwendet, um eine Wasserprobe der Blutmythosinsel zu entnehmen."}}
D[9749] = {"Sie leben! Vielleicht...",{"Forscher Cornelius hat Euch darum gebeten, 5 Expeditionsforscher zu befreien."}}
D[9750] = {"UNUSED Urgent Delivery"}
D[9751] = {"Das Vermächtnis des Blutfluchs",{"Admiral Odesyus hat Euch gebeten, nach Kapitän Edward Hanes zu suchen und mit ihm zu sprechen."}}
D[9752] = {"Flucht aus Umbrafenn",{"Begleitet Kayra Langmähne zur Zuflucht des Cenarius in den Zangarmarschen. Gebt Ysiel Windsänger Bescheid, sobald Ihr diese Aufgabe erledigt habt."}}
D[9753] = {"Was wir wissen...",{"Sprecht mit Exarch Admetius bei der Blutwacht."}}
D[9756] = {"Was wir nicht wissen...",{"Sprecht mit einem gefangenen Agenten der Sonnenfalken bei der Blutwacht und eignet Euch Informationen der Sonnenfalken an. Kehrt zu Exarch Admetius zurück, sobald Ihr Eure Aufgabe erfüllt habt."}}
D[9757] = {"Sucht Jägerin Kella Nachtbogen auf",{"Sprecht mit Jägerin Kella Nachtbogen nahe Valaars Steg."}}
D[9758] = {"Rückkehr zu Arkanist Vandril",{"Kehrt zu Arkanist Vandril in Tristessa in den Geisterlanden zurück."}}
D[9759] = {"Ihre Welt enden lassen",{"Folgt und beschützt Demolierer Legoso, während er versucht, die Vektorspule zu zerstören und tötet Sironas. Kehrt zu Exarch Admetius bei der Blutwacht zurück, sobald Ihr Eure Aufgabe erfüllt habt."}}
D[9760] = {"Verteidigers Ruh'",{"Sprecht mit Verteidigerin Corin bei Verteidigers Ruh' auf der Blutmythosinsel."}}
D[9761] = {"Den Weg frei machen",{"Verteidigerin Corin bei Verteidigers Ruh' möchte, dass Ihr 8 Saboteure der Sonnenfalken und 8 Agenten der Sonnenfalken tötet."}}
D[9762] = {"Die ungeschriebene Prophezeiung",{"Diese Inseln werden für Tausende ein Zuhause sein. Die meisten werden ihr gesamtes Leben hier verbringen. Ihr könntet das auch, aber es ist nicht, was Ihr wollt, oder <Name>?","","nnIhr werdet in Eurem Leben noch viele großartige Taten vollbringen. Ihr müsst Euer Schicksal umarmen und es willkommen heißen!","","Bevor Ihr geht, möchte ich Euch noch zwei Geschenke überreichen: Dieser Wappenrock wird nur von denen getragen, die den höchsten Respekt der Hand von Argus genießen; und nur die Weisesten besitzen diesen Siegelring. Tragt beides mit Stolz, <Name>."}}
D[9763] = {"Das Versteck des Kriegsherren",{"Behüterin Jhang möchte, dass Ihr Kriegsherr Kalithresh im Echsenkessel findet und tötet."}}
D[9764] = {"Befehle von Lady Vashj",{"Bringt die Befehle von Lady Vashj zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen."}}
D[9765] = {"Kriegsvorbereitungen",{"Besorgt die Waffen des Echsenkessels von den Naga im Echsenkessel und kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück."}}
D[9766] = {"Waffen des Echsenkessels",{"Wir werden den eigenen Stahl der Naga in Waffen gegen sie umschmieden. Bringt mir alle Waffen, die Ihr aus dem Echsenkessel besorgen könnt."}}
D[9767] = {"Den Feind kennen",{"Besorgt ein Zauberbuch des Echsenkessels von den Naga im Echsenkessel und bringt es zu Ashyen in der Zuflucht des Cenarius in den Zangarmarschen."}}
D[9769] = {"Mode kann man nicht erklären",{"Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Magasha im Sumpfrattenposten."}}
D[9770] = {"Bedrohliche Marschenfänge",{"Reavij im Sumpfrattenposten möchte, dass Ihr 10 Marschfangreißer tötet."}}
D[9771] = {"Auf der Suche nach Späher Jyoba",{"Sucht Späher Jyoba."}}
D[9772] = {"Jyobas Bericht",{"Besorgt Späher Jyobas Bericht von den siechenden Riesen und kehrt dann zu Zurai im Sumpfrattenposten zurück."}}
D[9773] = {"Keine Pilze mehr!",{"Bringt 8 Aalfilets von Umbrafennaalen zu Magasha im Sumpfrattenposten."}}
D[9774] = {"Dicke Hydraschuppen",{"Bringt 12 dicke Hydraschuppen zu Zurai im Sumpfrattenposten."}}
D[9775] = {"Bericht an Schattenjäger Denjai",{"Bringt Zurais Bericht zu Schattenjäger Denjai in Zabra'jin."}}
D[9776] = {"Die Oreborzuflucht",{"Sprecht mit Ikuti in der Oreborzuflucht."}}
D[9777] = {"Fulgorsporen",{"Bringt 6 Fulgorsporen zu Ruam in Telredor."}}
D[9778] = {"Aufseher Hamuht",{"Meldet Euch bei Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen."}}
D[9779] = {"Abfangen der Nachricht",{"Tötet die Elfen der Sonnenfalken, bis Ihr das Schreiben der Sonnenfalken findet, und bringt es zu Verteidiger Boros bei der Blutwacht."}}
D[9780] = {"Aalfilets von Umbrafenn",{"Bringt 8 Aalfilets zu Noraani in Telredor."}}
D[9781] = {"Zu viele Mäuler zu stopfen",{"Tötet 10 Morasthydras und kehrt zu Haalrun in Telredor zurück."}}
D[9782] = {"Das Todesmoor",{"Bringt eine Erdprobe vom Todesmoor zu Verteidiger Idaar in Telredor."}}
D[9783] = {"Eine unnatürliche Dürre",{"Verteidiger Idaar in Telredor möchte, dass Ihr 12 siechende Riesen tötet."}}
D[9784] = {"Pflanzenteile identifizieren",{"Ich könnte noch mehr Pflanzenteile brauchen. Jetzt, da die Seen ihr Wasser verlieren, befürchte ich, dass die fremden Arten zunehmen werden. Ich brauche aber mehr Beweise, um meine Theorie zu untermauern."}}
D[9785] = {"Der Segen der Uralten",{"Windruferin Schwarzhuf möchte, dass Ihr mit den Urtumen Ashyen und Keleth in der Zuflucht des Cenarius sprecht und um ihren Segen bittet."}}
D[9786] = {"Die Ruinen von Boha'mu",{"Anachoret Ahuurn in Telredor möchte, dass Ihr die Ruinen von Boha'mu erforscht."}}
D[9787] = {"Götzen des Wildfennstamms",{"Sammelt 6 Wildfenngötzen und kehrt dann zu Anachoret Ahuurn in Telredor zurück."}}
D[9788] = {"Ein feuchter, düsterer Ort",{"Sucht nach Ikeyens Habseligkeiten in einer Höhle südlich von Umbrafenn. Bringt sie zurück zu Ikeyen in der Zuflucht des Cenarius in den Zangarmarschen."}}
D[9789] = {"Beherrschen der Grollhufjagd",{"Erlegt 30 Grollhufe und kehrt anschließend zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand zurück, um Euch zu beweisen."}}
D[9790] = {"Lichtdurchlässige Flügel",{"Bringt 8 lichtdurchlässige Flügel von einer beliebigen Glühwürmchenart der Zangarmarschen zu Haalrun in Telredor."}}
D[9791] = {"Bedrohliche Marschenfänge",{"Tötet 10 Marschenfangreißer und kehrt dann zu Noraani in Telredor zurück."}}
D[9792] = {"Eine Botschaft für Telaar",{"Sprecht mit Nahuud in Telaar in Nagrand."}}
D[9793] = {"Das Schicksal von Tuurem",{"Bringt Verteidiger Idaars Brief zu Andarl in Allerias Feste in den Wäldern von Terokkar."}}
D[9794] = {"Keine Zeit für Neugier",{"Bringt Timothys Brief zu Kialon in Sylvanaar im Schergrat."}}
D[9795] = {"Die Ogerbedrohung",{"Reist zur Donnerfeste im Schergrat und sprecht mit Nekthar."}}
D[9796] = {"Nachricht aus den Zangarmarschen",{"Sprecht mit Mokasa in der Steinbrecherfeste in den Wäldern von Terokkar."}}
D[9797] = {"Verstärkung für Garadar",{"Sprecht mit Hauptmann Kroghan in Garadar in Nagrand."}}
D[9798] = {"Blutelfenpläne",{"Bringt die Blutelfenpläne zu Verteidiger Aldar bei der Absturzstelle im Am'mental."}}
D[9799] = {"Botanische Hilfsarbeit",{"Sammelt 3 verderbte Blumen und kehrt zu Lehrling Vishael bei der Absturzstelle im Am'mental zurück."}}
D[9800] = {"Eine seltene Bohne",{"Bringt 15 verdaute Caracolibohnen zu Elementarist Lo'ap am Thron der Elemente in Nagrand."}}
D[9801] = {"Die Reagenzien sammeln",{"Anachoret Ahuurn in Telredor möchte, dass Ihr ihm 4 Sporensegleraugen und 4 Fennschreitertentakel bringt."}}
D[9802] = {"Pflanzen der Zangarmarschen",{"Bringt 10 unbekannte Pflanzenteile zu Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen."}}
D[9803] = {"Botschaft für den Wildfennstamm",{"Trinkt Ahuurns Elixier in den Ruinen von Boha'mu. Sprecht mit dem Ältesten Kuruti in der Form eines Arakkoas."}}
D[9804] = {"Aufgebrachte Geister des Himmelsweisensees",{"Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 12 Seegeister tötet."}}
D[9805] = {"Segen des Incineratus",{"Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr die große Hütte, die westliche Hütte, die südliche Hütte und die östliche Hütte in Schilftanz zerstört.","","Bringt das beseelte Feuer zurück zu Elementarist Lo'ap, wenn Ihr fertig seid."}}
D[9806] = {"Fruchtbare Sporen",{"Sammelt 6 fruchtbare Sporen von den Sporenseglern und den Marschenläufern der Zangarmarschen und kehrt danach zu Gshaff in Sporeggar zurück."}}
D[9807] = {"Noch mehr fruchtbare Sporen"}
D[9808] = {"Glühkappenpilze",{"Bringt 10 Glühkappen zu Msshi'fn in Sporeggar in den Zangarmarschen."}}
D[9809] = {"Noch mehr Glühkappen",{"Wenn Ihr noch mehr Glühkappen habt, nehme ich sie Euch gerne ab. Unser Dorf kann sie immer gut gebrauchen."}}
D[9810] = {"Der verschmutzte Geist",{"Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr Watoosuns verschmutzte Essenz und 10 Seewoger tötet."}}
D[9811] = {"Freund der Sin'dorei",{"Bringt Dar'Khans Kopf zu Lor'themar Theron in Silbermond."}}
D[9812] = {"Gesandter zur Horde",{"Bringt den Brief von Lor'themar Theron zu Fürstin Sylvanas Windläufer in Unterstadt, der Hauptstadt der Verlassenen in Tirisfal."}}
D[9813] = {"Ein Treffen mit dem Kriegshäuptling",{"Fürstin Sylvanas Windläufer möchte, dass Ihr den Brief mit Sylvanas' Siegel zu Thrall nach Orgrimmar, Hauptstadt von Durotar, bringt."}}
D[9814] = {"Berstkappenpilze, Mann!",{"Bringt Hexendoktor Tor'gash 6 Berstkappen."}}
D[9815] = {"Schlammtauchen",{"Elementarist Lo'ap am Thron der Elemente in Nagrand möchte, dass Ihr 5 schlammbesudelte Kerne besorgt."}}
D[9816] = {"Habt Ihr sowas schon mal gesehen?",{"Bringt den Murlockäfig nach Dolchfenn und stellt ihn auf den flachen Stein in der Nähe des Dorfs."}}
D[9817] = {"Anführerin der Blutschuppen",{"Tötet Rajis Fyashe am Schlangensee und kehrt dann zu Aufseher Hamuht in der Zuflucht des Cenarius in den Zangarmarschen zurück, um eine Belohung zu erhalten."}}
D[9818] = {"Im Untergrund",{"Kommuniziert mit Gordawg."}}
D[9819] = {"Die gequälte Erde",{"Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr 15 gequälte Erdgeister tötet."}}
D[9820] = {"GESUCHT: Boss Grog'ak",{"Bringt Boss Grog'aks Kopf zu Schattenjäger Denjai in Zabra'jin."}}
D[9821] = {"Verdammnis schmecken",{"Gordawg am Thron der Elemente in Nagrand möchte, dass Ihr ihm 15 Kerne eines wütenden Zermalmers bringt."}}
D[9822] = {"Drohender Angriff",{"Bringt die Angriffspläne der Ango'rosh zu Schattenjäger Denjai in Zabra'jin."}}
D[9823] = {"Sie oder wir",{"Tötet Oberanführer Schmetterfaust, 10 Raufer der Ango'rosh, 10 Seelenfresser der Ango'rosh und meldet Euch dann bei Schattenjäger Denjai in Zabra'jin zurück."}}
D[9824] = {"Arkane Störungen",{"Benutzt den violetten Aufzeichnungskristall in der Nähe von unterirdischen Wasserquellen im Keller des Meisters und kehrt zu Erzmagier Alturus außerhalb von Karazhan zurück."}}
D[9825] = {"Rastlose Aktivität",{"Bringt 10 geisterhafte Essenzen zu Erzmagier Alturus außerhalb von Karazhan."}}
D[9826] = {"Dalarankontaktpersonen",{"Bringt Alturus' Bericht zu Erzmagier Cedric am Rande von Dalaran."}}
D[9827] = {"Siechendes Basidium",{"Bringt das siechenden Basidium zu Ruam in Telredor."}}
D[9828] = {"Siechendes Basidium",{"Bringt das siechende Basidium zu Reavij im Sumpfrattenposten."}}
D[9829] = {"Khadgar",{"Bringt Alturus' Bericht zu Khadgar in Shattrath in den Wäldern von Terokkar."}}
D[9830] = {"Blutergift",{"Bringt 6 Einheiten Sumpflichtblutergift zu Puluu in der Oreborzuflucht."}}
D[9831] = {"Nach Karazhan",{"Khadgar möchte, dass Ihr das Schattenlabyrinth von Auchindoun betretet und das erste Schlüsselfragment aus einem versteckten arkanen Behälter besorgt."}}
D[9832] = {"Das zweite und das dritte Fragment",{"Besorgt das zweite Schlüsselfragment aus einem arkanen Behälter im Echsenkessel und das dritte Schlüsselfragment aus einem arkanen Behälter in der Festung der Stürme. Kehrt dann zu Khadgar in Shattrath zurück."}}
D[9833] = {"Verbesserung der Kommunikation",{"Puluu in der Oreborzuflucht möchte, dass Ihr 12 Marschenfangschlitzer tötet."}}
D[9834] = {"Natürliche Rüstung",{"Bringt 8 Fennklauenbälge zu Maktu in der Oreborzuflucht."}}
D[9835] = {"Vordringen der Ango'rosh",{"Tötet 10 Oger der Ango'rosh und 5 Schamanen der Ango'rosh und kehrt dann zu Ikuti in der Oreborzuflucht zurück."}}
D[9836] = {"Die Berührung des Meisters",{"Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren."}}
D[9837] = {"Rückkehr zu Khadgar",{"Kehrt zu Khadgar in Shattrath zurück und zeigt ihm den Schlüssel des Meisters."}}
D[9838] = {"Das Violette Auge",{"Sprecht mit Erzmagier Alturus außerhalb von Karazhan."}}
D[9839] = {"Oberanführer Schmetterfaust",{"Ikuti möchte, dass Ihr Oberanführer Schmetterfaust und 10 Raufer der Ango'rosh tötet. Kehrt zur Oreborzuflucht zurück, wenn Ihr die Aufgabe erfüllt habt."}}
D[9840] = {"Einschätzung der Situation",{"Findet Koren in Karazhan."}}
D[9841] = {"Tückische Mücken",{"Tötet 8 Sumpflichtbluter und kehrt dann zu Gambarinka in Zabra'jin zurück."}}
D[9842] = {"Die schärfsten Klingen",{"Bringt 10 Marschenfangschlitzerklingen zu Gambarinka in Zabra'jin."}}
D[9843] = {"Keannas Aufzeichnungen",{"Durchsucht die Gästezimmer in Karazhan nach Keannas Aufzeichnungen und bringt sie zu Erzmagier Alturus außerhalb von Karazhan."}}
D[9844] = {"Eine dämonische Präsenz",{"Erzmagier Alturus möchte, dass Ihr die dämonische Präsenz an der Turmspitze von Karazhan zerstört."}}
D[9845] = {"Anglerunglück",{"Tötet 10 Fennklauenhauer und kehrt dann zu Zurjaya in Zabra'jin zurück."}}
D[9846] = {"Geister der Wildfenn",{"Bringt 10 Schutztotems von Wildfenn zu Seherin Janidi in Zabra'jin."}}
D[9847] = {"Ein verbündeter Geist?",{"Bringt das Wildfenntotem an den Fuß der Treppe in den Ruinen von Boha'mu und verankert es im Boden. Berichtet Seherin Janidi in Zabra'jin von Euren Beobachtungen."}}
D[9848] = {"Geheimnisse des Dolchfennstamms",{"Bringt das Gifthandbuch von Dolchfenn und eine Giftphiole von Dolchfenn zu Timothy Daniels in der Oreborzuflucht."}}
