D[10099] = {"Das Genie",{"Sucht und tötet Z'kral in den Minen unter der Ehrenfeste und meldet Euch dann bei Großknecht Biggums zurück."}}
D[10100] = {"Das Genie",{"Sucht und tötet Urga'zz in den Minen unter Thrallmar und kehrt dann zu Großknecht Razelcraz zurück."}}
D[10101] = {"Wenn Geister sprechen",{"Mutter Kashur im Ahnengrund in Nagrand bittet Euch, Eurer Vision auf den Grund zu gehen. Findet K'ure in Oshu'gun."}}
D[10102] = {"Ein gelüftetes Geheimnis",{"Sprecht mit A'dal in Shattrath."}}
D[10103] = {"Bericht an Zurai",{"Meldet Euch bei Zurai im Sumpfrattenposten in den Zangarmarschen."}}
D[10104] = {"Sorgen um Tuurem",{"Sprecht mit Andarl in Allerias Feste in den Wäldern von Terokkar."}}
D[10105] = {"Nachrichten für Rakoria",{"Sprecht mit Rakoria in der Steinbrecherfeste in den Wäldern von Terokkar."}}
D[10106] = {"Höllenfeuerbefestigungen",{"Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück."}}
