D[10469] = {"Der Schwur des Bewahrers",{"Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt."}}
D[10470] = {"Der Schwur des Helden",{"Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt."}}
D[10471] = {"Der Schwur des Verteidigers",{"Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt."}}
D[10472] = {"Das Bündnis des Weisen",{"Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt."}}
D[10473] = {"Das Bündnis des Bewahrers",{"Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt."}}
D[10474] = {"Das Bündnis des Helden",{"Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt."}}
D[10475] = {"Das Bündnis des Verteidigers",{"Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen ehrfürchtigen Ruf bei den Wächtern der Sande erlangt habt."}}
D[10476] = {"Grimmige Feinde",{"Aufseher Moi'bff Jill in Telaar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt."}}
D[10477] = {"Mehr Kriegsperlen",{"Habt Ihr noch mehr Obsidiankriegsperlen dabei, <Name>?"}}
D[10478] = {"Mehr Kriegsperlen!",{"Habt Ihr noch mehr Obsidiankriegsperlen besorgt, <Name>?"}}
D[10479] = {"Stärke beweisen",{"Aufseher Bullrok in Garadar möchte, dass Ihr 10 Obsidiankriegsperlen von den verschiedenen Ogern in Nagrand besorgt."}}
D[10480] = {"Wütende Geister des Wassers",{"Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 5 Wasserseelen einzufangen."}}
D[10481] = {"Wütende Geister der Luft",{"Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 10 Luftseelen einzufangen."}}
D[10482] = {"Plünderer der Höllenorcs",{"Tötet 20 Orcs der Knochenmalmer und kehrt danach zu Amadi in der Ehrenfeste zurück."}}
D[10483] = {"Schwarze Magie",{"Leutnant Amadi in der Ehrenfeste möchte, dass Ihr einen verfluchten Talisman zu Korporal Eisengrat im Expeditionsposten bringt."}}
D[10484] = {"Verfluchte Talismane",{"Bringt 12 verfluchte Talismane zu Korporal Eisengrat am Expeditionsposten."}}
D[10485] = {"Kriegsherr des Blutenden Auges",{"Bringt Kriegsherr Morkhs zerschmetterte Rüstung zu Korporal Eisengrat im Expeditionsposten."}}
D[10486] = {"Die nahende Wildnis",{"Gor'drek möchte, dass Ihr 12 Messerschwingenblutvergießer tötet. Kehrt zu ihm in der Donnerfeste im Schergrat zurück, wenn Ihr Eure Aufgabe erledigt habt."}}
D[10487] = {"Drachenstaub",{"Gor'drek möchte, dass Ihr 4 Einheiten Siechdrachenstaub sammelt. Kehrt danach zu ihm in der Donnerfeste im Schergrat zurück."}}
D[10488] = {"Die Eigenen schützen",{"Wendet Gor'dreks Salbe an 5 Terrorwölfen der Donnerfürsten an, um sie stärker zu machen und die Verteidigung des Zackengrats zu unterstützen. Kehrt danach zu Gor'drek in der Donnerfeste im Schergrat zurück."}}
D[10489] = {"Einen uralten Baum fällen",{"Besorgt Starkast Tiefenwurz' Stumpf und bringt ihn zu Tor'chunk Zweiklaue in der Donnerfeste im Schergrat."}}
D[10490] = {"Ruf des Wassers",{"Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel."}}
D[10491] = {"Ruf der Luft",{"Sprecht mit Weissager Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel."}}
D[10492] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bindungen der Elemente zu Deliana in Eisenschmiede."}}
D[10493] = {"Ein aufrichtiges Angebot",{"Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Lichts zu Mokvar in Orgrimmar zurück."}}
D[10494] = {"Die angemessene Entlohnung",{"Bringt Deliana in Eisenschmiede eine Kordel der Elemente und ein Paar Stulpen der Elemente."}}
D[10495] = {"Die angemessene Entlohnung",{"Bringt Mokvar in Orgrimmar einen Gürtel des Lichts und ein Paar Stulpen des Lichts."}}
D[10496] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Stiefel der Elemente, einem Kilt der Elemente und einem Paar Schulterstücke der Elemente zu Deliana in Eisenschmiede zurück."}}
D[10497] = {"Anthions Abschiedsworte",{"Kehrt mit einem Paar Stiefel des Lichts, ein Paar Beinplatten des Lichts und einer Schiftung des Lichts zu Mokvar in Orgrimmar zurück."}}
D[10498] = {"Das Beste gibt's zum Schluss",{"Gebt Deliana Eure Helmkappe der Elemente und Eure Weste der Elemente."}}
D[10499] = {"Das Beste gibt's zum Schluss",{"Gebt Mokvar Euren Helm des Lichts und Eure Brustplatte des Lichts."}}
D[10500] = {"Die Horde braucht Euch!",{"Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar."}}
D[10501] = {"Die Allianz braucht Euch!",{"Sprecht mit Feldmarschall Schneefall im Militärviertel von Eisenschmiede."}}
D[10502] = {"Die Oger der Blutschläger",{"Kommandant Himmelsschatten möchte, dass Ihr 30 Oger der Blutschläger im Außenposten der Blutschläger vernichtet. Kehrt zu ihm in Sylvanaar im Schergrat zurück, wenn Ihr die grauenvolle Aufgabe erledigt habt."}}
D[10503] = {"Die Speerspießerbedrohung",{"Tor'chunk Zweiklaue möchte, dass Ihr 30 Oger der Speerspießer und 10 Raptoren der Speerspießer in der Wehr der Speerspießer und im Grund der Speerspießer vernichtet. Kehrt zu ihm in der Donnerfeste im Schergrat zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[10504] = {"Die Oger der Speerspießer",{"Kommandant Himmelsschatten bittet Euch, 30 Oger der Speerspießer in der Wehr der Speerspießer und dem Grund der Speerspießer zu töten. Kehrt danach zu ihm in Sylvanaar im Schergrat zurück."}}
D[10505] = {"Die Oger der Blutschläger",{"Tor'chunk Zweiklaue bittet Euch, 30 Oger der Blutschläger beim Außenposten der Blutschläger zu töten. Kehrt zu ihm in der Donnerfeste im Schergrat zurück, wenn Ihr erfolgreich wart."}}
D[10506] = {"Eine düstere Lage",{"Rina Mondquell möchte, dass Ihr ihr Schwächungspulver auf 5 Terrorwölfe der Blutschläger im Außenposten der Blutschläger in der Blutschlägerklamm streut. Kehrt danach zu ihr in Sylvanaar im Schergrat zurück."}}
D[10507] = {"Der Wendepunkt",{"Benutzt Socrethars Teleportationsstein beim Invasionspunkt: Oberanführer im Norden der Konstruktionsbasis: Vergessenheit, um Eure Gruppe zu Socrethars Sitz zu bringen. Wenn Ihr dort seid, benutzt Voren'thals Präsenz, um Socrethar zu besiegen.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10508] = {"Ein Geschenk für Voren'thal",{"Spionagemeister Thalodien in Area 52 möchte, dass Ihr die erste Hälfte von Socrethars Stein von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit und die zweite Hälfte des Steins von Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna besorgt.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10509] = {"Für Ruhm bestimmt",{"Bringt Socrethars Teleportationsstein zu Voren'thal dem Seher auf der Sehertreppe in Shattrath.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10510] = {"In die Draenethystmine",{"Bronwyn Starkhammer bittet Euch, 5 Kristalle der Draenethystmine zu sammeln. Kehrt danach zu ihr in Sylvanaar im Schergrat zurück."}}
D[10511] = {"Merkwürdiges Gebräu",{"Borgrim Starkhammer möchte, dass Ihr 11 Einheiten von Blutschlägers Hauweggebräu besorgt. Wenn Ihr fertig seid, kehrt zu ihm in Sylvanaar im Schergrat zurück."}}
D[10512] = {"Die Speerspießer abfüllen",{"Nehmt Blutschlägers Hauweggebräu und versucht 5 Oger der Speerspießer damit betrunken zu machen. Meldet Euch bei Borgrim in Sylvanaar im Schergrat zurück, wenn Ihr erfolgreich wart."}}
D[10513] = {"Oronok Herzeleid",{"Sucht Oronok Herzeleid auf dem zerschlagenen Vorsprung nördlich der Zisterne der Echsennarbe."}}
D[10514] = {"Ich war schon vieles...",{"Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr 10 Schattenmondknollen aus den zerschlagenen Weiten besorgt.","","Bringt Oronoks Eberpfeife zu ihm zurück, wenn Ihr fertig seid."}}
D[10515] = {"Eine Lektion gelernt",{"Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr 10 Eier eines gefräßigen Schinders in den zerschlagenen Weiten zerstört."}}
D[10516] = {"Die Gefangenschaft der Verteidigerin",{"Holt Verteidigerin Vuuleens Klinge und Verteidigerin Vuuleens Schild zurück. Kehrt dann zu Verteidigerin Vuuleen in der Wehr der Speerspießer im Schergrat zurück."}}
D[10517] = {"Eure Zeit ist gekommen, Gorr'Dim...",{"Verteidigerin Vuuleen bittet Euch, Gorr'Dim, den Anführer der Oger bei der Wehr der Speerspießer, zu töten. Wenn Ihr fertig seid, kehrt zu Ihr in der Wehr der Speerspießer im Schergrat zurück."}}
D[10518] = {"Das Banner aufstellen",{"Benutzt das Banner der Speerspießer auf dem Nordschlägerturm, um Gurn Grubnosh anzulocken. Bringt das Banner und Gurn Grubnoshs Helm zu Kommandant Himmelsschatten in Sylvanaar im Schergrat."}}
D[10519] = {"Die Litanei der Verdammnis - Wahrheit und Geschichte",{"Oronok Herzeleid bei Oronoks Hof im Schattenmondtal möchte, dass Ihr Euch seine Geschichte anhört. Sprecht mit Oronok, um ihm zusagen, dass er mit der Geschichte beginnen kann."}}
D[10520] = {"Erzdruide Hirschhaupt helfen",{"Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus."}}
D[10521] = {"Grom'tor, Sohn von Oronok",{"Sucht Grom'tor, Sohn von Oronok in der Echsennarbe im Schattenmondtal."}}
D[10522] = {"Die Litanei der Verdammnis - Grom'tors Angriff",{"Grom'tor, Sohn von Oronok, in der Echsennarbe im Schattenmondtal möchte, dass Ihr den ersten Teil der Litanei der Verdammnis besorgt."}}
D[10523] = {"Die Litanei der Verdammnis - Erster Teil",{"Bringt Grom'tors Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal."}}
D[10524] = {"Artefakte der Donnerfürsten",{"Beschafft die Trommel der Donnerfürsten, den Pfeil der Donnerfürsten und die Schrifttafel der Donnerfürsten. Bringt sie zusammen mit dem Artefakt der Donnerfürsten zu Rokgah Blutgriff in der Donnerfeste im Schergrat."}}
D[10525] = {"Wegweisende Visionen",{"Benutzt das feurige Seelenfragment, um Euren Geist in eine wegweisende Vision zu versetzen. Sprecht mit Rokgah Blutgriff in der Donnerfeste, nachdem Euch die Vision zum Aufenthaltsort des letzten Artefakts der Donnerfürsten geführt hat."}}
D[10526] = {"Die Donnerlanze",{"Rokgah Blutgriff möchte, dass Ihr die Donnerlanze zurückholt. Bringt sie zu ihr in der Donnerfeste im Schergrat zurück."}}
D[10527] = {"Ar'tor, Sohn von Oronok",{"Findet Ar'tor, Sohn von Oronok, bei der Stätte der Illidari im Schattenmondtal."}}
D[10528] = {"Dämonische Kristallgefängnisse",{"Sucht und tötet Schmerzensmeisterin Gabrissa in der Stätte der Illidari und kehrt mit dem kristallenen Schlüssel zum Leichnam von Ar'tor, Sohn von Oronok, zurück."}}
D[10529] = {"Der Pfad des Jägers",{"Sprecht mit Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer."}}
D[10530] = {"Der Pfad des Jägers",{"Sprecht mit Leutnant Dämmerflucht in der Zuflucht der Weltenwanderer."}}
D[10531] = {"Die Schlacht um das Arathibecken!",{"Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht."}}
D[10532] = {"Zerschlagt die Versorgungslinien Arathors",{"Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall."}}
D[10533] = {"Noch mehr Vorratskisten"}
D[10534] = {"Rückkehr nach Hause",{"Caedmos in der Exodar wünscht Euch zu sehen."}}
D[10535] = {"Die Ressourcen des Arathibeckens",{"Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht."}}
D[10536] = {"Noch mehr Vorratskisten"}
D[10537] = {"Lohn'goron, Bogen des Herzeleid",{"Der Geist von Ar'tor bei der Stätte der Illidari im Schattenmondtal möchte, dass Ihr Lohn'goron, den Bogen des Herzeleid, von den Dämonen in der Gegend beschafft."}}
D[10538] = {"Kochendes Blut",{"Benutzt den Verfluchten Kessel, um das Blut des Blutenden Auges in gekochtes Blut zu verwandeln. Bringt danach 12 Einheiten gekochtes Blut zu Apotheker Albreck im Rückenbrecherposten."}}
D[10539] = {"Rückkehr nach Hause",{"Caedmos in der Exodar wünscht Euch zu sehen."}}
D[10540] = {"Die Litanei der Verdammnis - Ar'tors Angriff",{"Der Geist von Ar'tor bei der Stätte der Illidari im Schattenmondtal möchte, dass Ihr den zweiten Teil der Litanei der Verdammnis von Veneratus dem Vielgesichtigen besorgt.","","Kreaturen, die vom Geistjäger angegriffen werden oder Schaden erleiden, gewähren Euch keine Beute oder Erfahrung."}}
D[10541] = {"Die Litanei der Verdammnis - Zweiter Teil",{"Bringt Ar'tors Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal."}}
D[10542] = {"Die ham meine Pfeife und mein Gesöff geklaut!",{"Holt T'chalis Wasserpfeife und 10 Einheiten von Blutschlägers Hauweggebräu zurück. Bringt sie zu T'chali dem Hexendoktor in der Blutschlägerklamm im Schergrat."}}
D[10543] = {"Grimnok und Korgaah, ich komm' Euch holen!",{"T'chali der Hexendoktor hat Euch gebeten, seine Quäler, Grimnok Schlachttaufe und Korgaah, zu töten. Wenn Ihr fertig seid, kehrt zu ihm in der Blutschlägerklamm im Schergrat zurück."}}
D[10544] = {"Verflucht seien Eure beiden Klans!",{"Benutzt den heimtückischen mächtigen Fetisch, um 5 Gebäude in der Wehr der Speerspießer und 2 Gebäude im Außenposten der Blutschläger zu verfluchen. Kehrt zu T'chali dem Hexendoktor in der Blutschlägerklamm im Schergrat zurück, wenn Ihr fertig seid."}}
D[10545] = {"Saufgelage der Speerspießer",{"T'chali bittet Euch, Blutschlägers Hauweggebräu zu benutzen, um 5 Oger der Speerspießer betrunken zu machen. Wenn Ihr Erfolg hattet, kehrt zu T'chali dem Hexendoktor in der Blutschlägerklamm im Schergrat zurück."}}
D[10546] = {"Borak, Sohn von Oronok",{"Sucht Borak, Sohn von Oronok, in der Nähe der Stätte der Mondfinsternis im Schattenmondtal."}}
D[10547] = {"Von Distelköpfen und Eiern...",{"Borak, Sohn von Oronok, bei der Brücke nördlich der Stätte der Mondfinsternis möchte, dass Ihr ein verfaultes Arakkoaei besorgt und es zu Tobias dem Faulfraß in Shattrath, nordwestlich der Wälder von Terokkar, bringt."}}
D[10548] = {"Die traurige Wahrheit",{"Eralan in Tristessa möchte, dass Ihr den Schrumpfkopf des Archäologen aus einer der Truhen in Zeb'Tela oder Zeb'Nowa besorgt."}}
D[10550] = {"Ein Bündel von Blutdisteln",{"Bringt das Blutdistelbündel zurück zu Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal."}}
D[10551] = {"Loyalität gegenüber den Aldor",{"Seid Ihr Euch Eurer Wahl sicher, <Name>? Die Aldor heißen Euch gerne als Verbündeten willkommen, aber die Seher werden Euch Eure Entscheidung nicht so leicht vergeben."}}
D[10552] = {"Loyalität gegenüber den Sehern",{"Seid Ihr Euch Eurer Wahl sicher, <Name>? Die Seher heißen Euch gerne als Verbündeten willkommen, aber die Aldor werden Euch Eure Entscheidung nicht so leicht vergeben."}}
D[10553] = {"Voren'thal der Seher",{"Sprecht mit Voren'thal dem Seher in der Bibliothek der Seher bei der Sehertreppe in Shattrath.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10554] = {"Ishanah",{"Sprecht mit Ishanah im Schrein des unendlichen Lichts auf der Aldorhöhe in Shattrath.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10555] = {"Fauler Zauber",{"Sammelt 18 ausgezupfte Federn der Lashh'an und lest den Folianten der Lashh'an in den Baumwipfeln des Lashhverstecks."}}
D[10556] = {"Gekritzel",{"Benutzt die Hand voll Federn im Zauberzirkel der Lashh'an und kehrt zu Daranelle in Sylvanaar zurück, bevor der Zauber nachlässt."}}
D[10557] = {"Testflug: Das Zephyriumkapazitorium",{"Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Kehrt danach zu Tally Zapschnapper in Toshleys Station zurück."}}
D[10558] = {"Respektvoller Ruf in der Ehrenfeste",{"Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr Euch einen respektvollen Ruf in der Ehrenfeste verschafft, indem Ihr die Höllenorcs in den Zerschmetterten Hallen der Höllenfeuerzitadelle tötet."}}
D[10559] = {"Respektvoller Ruf in Thrallmar",{"Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr Euch einen respektvollen Ruf in Thrallmar verschafft, indem Ihr die Höllenorcs in den Zerschmetterten Hallen der Höllenfeuerzitadelle tötet."}}
D[10560] = {"Respektvoller Ruf bei den Sha'tar",{"A'dal in Shattrath möchte, dass Ihr Euch einen respektvollen Ruf bei den Sha'tar verschafft, indem Ihr Kael'thas Streitkräfte in der Festung der Stürme tötet."}}
D[10561] = {"Respektvoller Ruf bei den Hütern der Zeit",{"Andormu in den Höhlen der Zeit in Tanaris möchte, dass Ihr Euch einen respektvollen Ruf bei den Hütern der Zeit verdient, indem Ihr weiterhin die Ereignisse im Alten Hügelland und dem Schwarzen Morast in den Höhlen der Zeit verteidigt."}}
D[10562] = {"Belagert!",{"Schwadronskommandant Nuainn außerhalb der Wildhammerfeste möchte, dass Ihr 10 angreifende Höllenbestien tötet."}}
D[10563] = {"Zur Feste der Legion",{"Begebt Euch zur Feste der Legion und findet das Kommunikationsgerät der Legion. Benutzt die Verkleidung, während Ihr in der Nähe des Kommunikationsgeräts steht, um mehr über die Pläne der Legion herauszufinden. Kehrt danach zu Schwadronskommandant Nuainn in der Wildhammerfeste zurück."}}
D[10564] = {"Jagt die Höllenbestien in die Luft!",{"Zündet die Teufelsbombe, während Ihr auf der grünen Glyphe in der Feste der Legion steht. Meldet Euch bei Schwadronskommandant Nuainn in der Wildhammerfeste zurück, wenn Ihr Euren Auftrag erledigt habt."}}
D[10565] = {"Die Steine der Vekh'nir",{"Sammelt einen Kristall der Vekh'nir und benutzt ihn beim Zauberzirkel der Vekh'nir. Kehrt mit dem aufgeladenen Kristall der Vekh'nir zu Dertrok im Dorf der Mok'Nathal zurück."}}
D[10566] = {"Probieren geht über Studieren",{"Probiert jeden von Dertroks Zauberstäben an einem Ogersklaven der Arakkoa aus und kehrt danach zu Dertrok zurück. Ihr benötigt einen energieerfüllten Kristall der Vekh'nir für jeden Stab, den Ihr benutzen wollt."}}
D[10567] = {"Die Herstellung des Anhängers",{"Sammelt 6 Klauen der Ruuan'ok und benutzt sie bei dem Orakelkreis der Ruuan'ok, um einen Herold des Raben herbeizurufen. Tötet ihn und bringt den Anhänger des Herolds zu Timeon im Ruuanwald."}}
D[10568] = {"Schrifttafeln von Baa'ri",{"Anachoret Ceyla beim Altar der Sha'tar möchte, dass Ihr 12 Schrifttafeln von Baa'ri vom Boden und von den Arbeitern der Aschenzungen in den Ruinen von Baa'ri sammelt.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10569] = {"Das Wrack der Sketh'lon",{"Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Greifenreiter Kieran."}}
D[10570] = {"Einen Distelsüchtigen fangen",{"Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr Sturmgrimms Schriftwechsel beschafft."}}
D[10571] = {"Oronu der Älteste",{"Anachoret Ceyla beim Altar der Sha'tar möchte, dass Ihr die Befehle von Akama von Oronu dem Ältesten in den Ruinen von Baa'ri besorgt.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10572] = {"Die Bombe bauen",{"Besorgt Euch einen Teufelshäscherkraftkern und eine Teufelshäscherrüstungsplatte und bringt sie zu Schwadronskommandant Nuainn in der Wildhammerfeste."}}
D[10573] = {"Die Todesschmiede",{"Meldet Euch bei Sturmrufer Ewan Wildschwinge im Turm der Todesschmiede."}}
D[10574] = {"Die Verderber der Aschenzungen",{"Beschafft die vier Medaillonfragmente von Haalum, Eykenen, Lakaan und Uylaru und kehrt danach zu Anachoret Ceyla beim Altar der Sha'tar im Schattenmondtal zurück.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10575] = {"Der Kerker des Wächters",{"Anachoret Ceyla möchte, dass Ihr den Kerker des Wächters südlich der Ruinen von Baa'ri betretet und Sanoru befragt, um Akamas Aufenthaltsort herauszufinden.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Seher."}}
D[10576] = {"Unterwürfigkeit in Schattenmond",{"Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr 6 Teile der Rüstung der Mondfinsternis besorgt."}}
D[10577] = {"Was Illidan will, soll Illidan bekommen...",{"Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr Großkommandant Ruusk in der Stätte der Mondfinsternis Illidans Nachricht überbringt."}}
D[10578] = {"Die Litanei der Verdammnis - Boraks Angriff",{"Borak, Sohn von Oronok, bei der Brücke in der Nähe der Stätte der Mondfinsternis im Schattenmondtal möchte, dass Ihr den dritten Teil der Litanei der Verdammnis von Ruul dem Verfinsterer besorgt.","","Für diesen Auftrag werdet Ihr eine Gruppe benötigen."}}
D[10579] = {"Die Litanei der Verdammnis - Dritter Teil",{"Bringt Boraks Schließkassette zu Oronok Herzeleid bei Oronoks Hof im Schattenmondtal."}}
D[10580] = {"Wo sind diese verdammten Gnome hin?",{"Kommandant Himmelschatten möchte, dass Ihr im südlichen Teil des Zackengrats im Schergrat nach Hinweisen auf den Verbleib von Toshley und seinen Gnomenfreunden sucht."}}
D[10581] = {"Folget den Brotkrumen",{"Auf eine verquere Art hat R-3D0 Euch gesagt, dass Ihr der Spur aus Ersatzteilen den Weg hinauf zum Messergrat folgen müsst, um die Gnome an einem Ort namens Toshleys Station zu finden.","","Sprecht mit Toshley, wenn Ihr ihn findet."}}
D[10582] = {"Diener des Schattenrats",{"Sturmrufer Ewan Wildschwinge beim Turm der Todesschmiede möchte, dass Ihr 10 Wächter der Todesschmiede und 5 Beschwörer der Todesschmiede tötet."}}
D[10583] = {"Flanis' Schicksal",{"Sturmrufer Ewan Wildschwinge beim Turm der Todesschmiede möchte, dass Ihr die Todesschmiede nach Flanis Flinkschwinge absucht und Flanis' Beutel zurückholt."}}
D[10584] = {"Ein paar Stromwandler besorgen",{"Toshley möchte, dass Ihr den protovoltaischen Magnetsammler benutzt, um 5 Elektromentare einzufangen. Kehrt danach zu Toshleys Station im Schergrat zurück."}}
D[10585] = {"Die Beschwörungskammer",{"Besorgt Euch eine Elementarsteuerung von einem Schmied der Todesschmiede oder einem Tüftler der Todesschmiede. Benutzt sie, um das Ritual in der Beschwörungskammer zu unterbrechen. Meldet Euch danach bei Sturmrufer Ewan Wildschwinge im Turm der Todesschmiede zurück."}}
D[10586] = {"Nieder mit dem Kriegshetzer!",{"Besiegt Kriegshetzer Razuun, beschafft Razuuns Befehle und meldet Euch bei Schwadronskommandant Nuainn in der Wildhammerfeste."}}
D[10587] = {"Ausbildungsgelände von Karabor",{"Exarch Onaala beim Altar der Sha'tar möchte, dass Ihr 8 Gleven des Sonnenzorns von den Bittstellern der Dämonenjäger und den Initianden der Dämonenjäger in den Ruinen von Karabor, südöstlich des Altars der Sha'tar, beschafft.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10588] = {"Die Litanei der Verdammnis",{"Benutzt die Litanei der Verdammnis am Altar der Verdammnis um Cyrukh den Feuerlord zu rufen.","","Vernichtet Cyrukh den Feuerlord und sprecht danach mit Erdheiler Torlok, der sich ebenfalls am Altar der Verdammnis befindet."}}
D[10589] = {"Zugang erlangen",{"Bringt eine Teleportersteuerung der Legion zu Schwadronskommandant Nuainn in der Wildhammerfeste. Bekanntlich tragen die Waffenschmiede der Mo'arg in der Feste der Legion diese Geräte bei sich."}}
D[10590] = {"Beweist Euren Hass!",{"Mehlar Dämmerklinge beim Bollwerk möchte, dass Ihr ihm 20 Geißelsteine des Dieners bringt."}}
D[10592] = {"Die Weisheit der Bansheekönigin",{"Bringt die Geißelsteinfragmente zu Fürstin Sylvanas Windläufer in Unterstadt."}}
D[10593] = {"Das uralte Böse",{"Lüftet die Geheimnisse des Versunkenen Tempels und befreit Atal'alarion. Tötet ihn und schneidet die Fäulnisranke aus seinem Fleisch. Kehrt danach zu Mehlar beim Bollwerk zurück."}}
D[10594] = {"Die Klangfrequenz messen",{"Schartwinkel der Metrognom möchte, dass Ihr die oszillierenden Schwingungsmesser so anordnet, dass Ihr, wenn Ihr in ihrer Mitte steht, von fünf sich überlappenden Schwingungsfeldern berührt werdet.","","Kehrt danach zu Schartwinkel bei Toshleys Station im Schergrat zurück."}}
D[10595] = {"Belagert!",{"Blutwache Gulmok außerhalb von Schattenmond möchte, dass Ihr 10 angreifende Höllenbestien tötet."}}
D[10596] = {"Zur Feste der Legion",{"Begebt Euch zur Feste der Legion, findet ein Kommunikationsgerät der Legion und benutzt es, um mehr über die Pläne der Legion herauszufinden, während Ihr verkleidet seid. Kehrt danach zu Blutwache Gulmok in Schattenmond zurück."}}
D[10597] = {"Die Bombe bauen",{"Besorgt Euch einen Teufelshäscherkraftkern und eine Teufelshäscherrüstungsplatte und bringt sie zu Blutwache Gulmok in Schattenmond."}}
D[10598] = {"Jagt die Höllenbestien in die Luft!",{"Zündet die Teufelsbombe, während Ihr auf der grünen Glyphe in der Feste der Legion steht. Meldet Euch bei Blutwache Gulmok in Schattenmond zurück, wenn Ihr Euren Auftrag erledigt habt."}}
D[10599] = {"Die Todesschmiede",{"Meldet Euch bei Späher Zagran in der Schlackenwacht."}}
D[10600] = {"Diener des Schattenrats",{"Späher Zagran in der Schlackenwacht möchte, dass Ihr 10 Wächter der Todesschmiede und 5 Beschwörer der Todesschmiede tötet."}}
D[10601] = {"Kagroshs Schicksal",{"Späher Zagran in der Schlackenwacht möchte, dass Ihr die Todesschmiede nach Kagrosh absucht und Kagroshs Beutel zurückholt."}}
D[10602] = {"Die Beschwörungskammer",{"Besorgt Euch eine Elementarsteuerung von einem Schmied der Todesschmiede oder einem Tüftler der Todesschmiede. Benutzt sie, um das Ritual in der Beschwörungskammer zu unterbrechen. Meldet Euch danach bei Späher Zagran in der Schlackenwacht zurück."}}
D[10603] = {"Nieder mit dem Kriegsrufer!",{"Besiegt Kriegshetzer Razuun, beschafft Razuuns Befehle und meldet Euch bei Blutwache Gulmok in Schattenmond."}}
D[10604] = {"Zugang erlangen",{"Bringt eine Teleportersteuerung der Legion zu Blutwache Gulmok in Schattenmond. Bekanntlich tragen die Waffenschmiede der Mo'arg in der Feste der Legion diese Geräte bei sich."}}
D[10605] = {"Carendin ruft",{"Sprecht mit Carendin Halgar in Unterstadt."}}
D[10606] = {"Die Kunst der Teufelshäscherwartung",{"Tötet Doktor Gutrick und beschafft Euch den Schlüssel des Doktors. Benutzt den Schlüssel, um die Geldkassette des Doktors zu öffnen und 'Die Kunst der Teufelshäscherwartung' daraus zu entnehmen. Bringt das Buch zu Plexi beim Invasionspunkt: Katastrophe."}}
D[10607] = {"Das Flüstern des Rabengottes",{"Tötet die Arakkoa der Grishna, um für 2 Minuten den Zauber 'Rabensprache verstehen' zu erhalten. Hört Euch die Prophezeiungen aller vier Schreine an, solange der Zauber aktiv ist, und kehrt danach zurück."}}
D[10608] = {"Kristallklar",{"Schartwinkel der Metrognom möchte, dass Ihr 10 Kristallfelsklauen tötet. Kehrt danach zu ihm bei Toshleys Station im Schergrat zurück."}}
D[10609] = {"Was war zuerst da, der Drache oder das Ei?",{"Sammelt 3 Essenzen eines Protonetherdrachen, 3 Essenzen eines heranwachsenden Netherdrachen und 3 Essenzen eines ausgewachsenen Netherdrachen und bringt sie zu Fizit \"Dok\" Kuckuck bei Toshleys Station im Schergrat."}}
D[10610] = {"Grundlagen des Sondierens"}
D[10611] = {"Die Kunst der Teufelshäscherwartung",{"Tötet Doktor Maleficus und beschafft Euch den Schlüssel des Doktors. Benutzt den Schlüssel, um die Geldkassette des Doktors zu öffnen und 'Die Kunst der Teufelshäscherwartung' daraus zu entnehmen. Bringt das Buch zu Nakansi beim Invasionspunkt: Katastrophe."}}
D[10612] = {"Teufelshäscherdrift",{"Benutzt die Teufelshäscherfernsteuerung, um eine Schildwache der Teufelshäscher zu steuern. Zerstört 60 todesgeschmiedete Höllenbestien bevor Euer Teufelshäscher versagt. Meldet Euch danach bei Plexi am Invasionspunkt: Katastrophe."}}
D[10613] = {"Teufelshäscherdrift",{"Benutzt die Teufelshäscherfernsteuerung, um eine Schildwache der Teufelshäscher zu steuern. Zerstört 60 todesgeschmiedete Höllenbestien bevor Euer Teufelshäscher versagt. Meldet Euch danach bei Nakansi am Invasionspunkt: Katastrophe."}}
D[10614] = {"Das Flüstern im Wind",{"Sucht nach Leoroxx im Dorf der Mok'Nathal im Schergrat."}}
D[10615] = {"Der Ruuanwald",{"Sprecht mit Timeon im ewigen Hain im Ruuanwald des Schergrats."}}
D[10617] = {"Seidenflügelkokons",{"Taerek im Dorf der Mok'Nathal möchte, dass Ihr 8 Seidenflügelkokons von Seidenflügellarven besorgt.","","Tötet die Larven schnell, da sie sich sonst in Seidenflügel verwandeln und ihre Kokons zerstören."}}
D[10618] = {"Die weichsten Flügel",{"Silmara im Dorf der Mok'Nathal möchte, dass Ihr 12 schillernde Flügel sammelt."}}
D[10619] = {"Die Aschenzungen",{"Verteidiger Aluumen möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10620] = {"Gratwirbelbedrohung",{"Taumel Dina möchte, dass Ihr 10 Gratwirbelpirscher tötet. Kehrt danach zu ihr in Toshleys Station im Schergrat zurück."}}
D[10621] = {"Splitter des Illidaribanns",{"Bringt den Splitter des Illidaribanns zu Ordinn Donnerfaust in der Wildhammerfeste."}}
D[10622] = {"Ein Beweis der Treue",{"Tötet Zandras im Kerker des Wächters im Schattenmondtal und kehrt danach zu Sanoru zurück."}}
D[10623] = {"Splitter des Illidaribanns",{"Bringt den Splitter des Illidaribanns zu Grokom Totauge in Schattenmond."}}
D[10624] = {"Eine Spukgeschichte",{"Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr ihr 15 Einheiten ewig brennende Asche bringt."}}
D[10625] = {"Geisterbrille",{"Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr 12 Zeloten des Schattenmondklans tötet."}}
D[10626] = {"Beschafft die Waffen",{"Ordinn Donnerfaust in der Wildhammerfeste möchte, dass Ihr ihm Makazradons Gleve und Morgrorons Gleve bringt."}}
D[10627] = {"Beschafft die Waffen",{"Grokom Totauge im Schattenmondtal möchte, dass Ihr ihm Makazradons Gleve und Morgrorons Gleve bringt."}}
D[10628] = {"Akama",{"Sprecht mit Akama in der verborgenen Kammer im Kerker des Wächters."}}
D[10629] = {"Drecksarbeit",{"Benutzt die Teufelshundepfeife, um einen teuflischen Wachhund zu rufen. Führt den teuflischen Wachhund Gassi und tötet ein paar Hölleneber. Durchsucht dann die Haufen des teuflischen Wachhunds nach den Schlüsseln. Wenn Ihr die Schlüssel gefunden habt, bringt sie zu Großknecht Razelcraz bei der Mine nordwestlich von Thrallmar."}}
D[10630] = {"Unter Thrallmar",{"Tötet Urga'zz und kehrt dann zu Großknecht Razelcraz in der Mine nordwestlich von Thrallmar zurück."}}
D[10632] = {"Zähne zeigen",{"Razak Eisenflanke möchte, dass Ihr 5 besonders scharfe Dolchrachenzähne sammelt. Kehrt danach zu ihm in Toshleys Station im Schergrat zurück."}}
D[10633] = {"Teron Blutschatten - Geschichte und Mythos",{"Chefapothekerin Hildagard in Schattenmond im Schattenmondtal möchte, dass Ihr den uralten Schattenmondgeist findet.","","Wenn Ihr Eure Geisterbrille verlieren solltet, kann Euch Hildagard ein neues Paar herstellen."}}
D[10634] = {"Hellsicht: Blutschattens Rüstung",{"Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Rüstung besorgt."}}
D[10635] = {"Hellsicht: Blutschattens Umhang",{"Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Umhang besorgt."}}
D[10636] = {"Hellsicht: Blutschattens Schlagstock",{"Der uralte Schattenmondgeist am Altar der Schatten im südöstlichen Schattenmondtal möchte, dass Ihr Blutschattens Schlagstock besorgt."}}
D[10637] = {"Eine notwendige Ablenkung",{"Exarch Onaala möchte, dass Ihr zu den Ruinen von Karabor zurückkehrt und Azaloth auf seine Kerkermeister hetzt.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10638] = {"NOT A QUEST",{"Seek <NAME> in the <DISTRICT> of Silvermoon City."}}
D[10639] = {"Ich bin Teron Blutschatten...",{"Der uralte Schattenmondgeist hat Euch benutzt! Nun, da Ihr alle Gegenstände, die er wollte, gesammelt habt, hat er sich als Teron Blutschatten offenbart. Um von seinem Bann loszukommen, müsst Ihr seinen Willen erfüllen und Karsius den uralten Wächter töten.","","Wenn Ihr erfolgreich wart, meldet Euch bei Chefapothekerin Hildagard in Schattenmond."}}
D[10640] = {"Altruis",{"Reist in den Westen Nagrands und sucht Altruis den Leider.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10641] = {"Gegen die Legion",{"Altruis der Leider möchte, dass Ihr das frisch gezapfte Blut einer Zornpriesterin der Konstruktionsbasis: Gehenna im Nethersturm besorgt. Schüttet es auf den Boden und tötet den Avatar von Sathal. Kehrt zu Altruis dem Leider zurück, wenn Ihr fertig seid."}}
D[10642] = {"Spiritus ex machina",{"Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr ihm 15 Proben ewig brennende Asche bringt."}}
D[10643] = {"Herolde des Schattenmondklans",{"Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 12 Herolde des Schattenmondklans tötet."}}
D[10644] = {"Teron Blutschatten - Geschichte und Mythos",{"Zorus der Richter in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr den uralten Schattenmondgeist findet.","","Wenn Ihr Eure Geisterbrille verlieren solltet, kann Euch Zorus der Richter eine neue herstellen."}}
D[10645] = {"Ich bin Teron Blutschatten...",{"Der uralte Schattenmondgeist hat Euch benutzt! Nun, da Ihr alle Gegenstände, die er wollte, gesammelt habt, hat er sich als Teron Blutschatten offenbart. Um von seinem Bann loszukommen, müsst Ihr seinen Willen erfüllen und Karsius den uralten Wächter töten.","","Wenn Ihr erfolgreich wart, meldet Euch bei Zorus dem Richter in der Wildhammerfeste."}}
D[10646] = {"Illidans Schüler",{"Hört Euch Altruis' Geschichte an."}}
D[10647] = {"Gesucht: Uvuros, Geißel von Schattenmond",{"Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Sardon Treuschnitt in Schattenmond im Schattenmondtal."}}
D[10648] = {"Gesucht: Uvuros, Geißel von Schattenmond",{"Tötet Uvuros und beschafft Uvuros' feurige Mähne. Bringt sie zu Kriegsrufer Bierschnut in der Wildhammerfeste im Schattenmondtal."}}
D[10649] = {"Das Buch der teuflischen Namen",{"Reist in das Schattenlabyrinth von Auchindoun und besorgt das Buch der teuflischen Namen von Schwarzherz dem Hetzer. Kehrt danach zu Altruis in Nagrand zurück."}}
D[10650] = {"Rückkehr zu den Aldor",{"Sprecht mit Exarch Onaala beim Altar der Sha'tar im Schattenmondtal.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10651] = {"Varedis muss aufgehalten werden",{"Exarch Onaala möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Exarch Onaala zurück.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10652] = {"Hinter feindlichen Linien",{"Sprecht mit Veronia, wenn Ihr bereit seid, zur Manaschmiede Coruu aufzubrechen. Meldet Euch dort bei Caledis Morgenhell.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10653] = {"Mal des Sargeras",{"Bringt 10 Male des Sargeras zu Adyen dem Lichtwächter in Shattrath.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10654] = {"Mehr Male des Sargeras",{"Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Die Brennende Legion ist auch weiterhin eine Bedrohung, und wir verfolgen sie überall, wo wir sie finden können."}}
D[10655] = {"Einzelne Male des Sargeras",{"Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben."}}
D[10656] = {"Siegel des Sonnenzorns",{"Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10657] = {"Lasst sie abblitzen!",{"Toshley möchte, dass Ihr die repolarisierte Magnetsphäre benutzt, um 25 Blitzschläge von Schuppenflügelschlangen abzufangen. Des Weiteren möchte er, dass Ihr 5 Blitzschlagdrüsen eines Schuppenflügels sammelt. Kehrt danach zu Toshley in Toshleys Station im Schergrat zurück."}}
D[10658] = {"Mehr Siegel des Sonnenzorns",{"Was habt Ihr in letzter Zeit für uns getan, <Name>? Der Krieg gegen Kael'thas kämpft sich nicht von alleine, verstanden?"}}
D[10659] = {"Einzelne Siegel des Sonnenzorns",{"Sogar der kleinste Beitrag zu unserer Sache wird bemerkt, <Name>. Unsere Feinde sind stark, aber wir werden siegen!"}}
D[10660] = {"Welch merkwürdige Wesen...",{"Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt."}}
D[10661] = {"Demilziös!",{"Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 8 Teufelsfeuermilzen besorgt."}}
D[10662] = {"Der Wanderschmied",{"Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar."}}
D[10663] = {"Der Wanderschmied",{"Bringt den Kasten mit Barren zu David Wayne in Waynes Zuflucht in den Wäldern von Terokkar."}}
D[10664] = {"Zusätzliche Materialien",{"David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm einen Adamantitrahmen, 4 Stück schweres Knotenhautleder und ein Dämonenschutztotem bringt."}}
D[10665] = {"Frisch von der Mechanar",{"David Wayne bei Waynes Zuflucht möchte, dass Ihr ihm eine überladene Manazelle bringt."}}
D[10666] = {"Encyclopaedia Daemonica",{"Beschafft die Encyclopaedia Daemonica von Großmeister Vorpil und bringt sie zu David Wayne in Waynes Zuflucht."}}
D[10667] = {"Unterweltlehm",{"Beschafft Euch ein Gefäß mit Unterweltlehm von Wasserbeschwörerin Thespia und bringt es zu David Wayne in Waynes Zuflucht."}}
D[10668] = {"Gegen die Illidari",{"Altruis der Leider möchte, dass Ihr Lothros in der Stätte der Illidari im Schattenmondtal tötet."}}
D[10669] = {"Gegen jede Chance",{"Altruis der Leider möchte, dass Ihr den magieerfüllten Silberspeer bei der Portalsicherung in der Nähe des Sumpflichtsees in den Zangarmarschen verwendet, um Xeleth zu wecken. Kehrt zu Altruis zurück, wenn Ihr den Dämon erlegt habt."}}
D[10670] = {"Träne der Erdenmutter",{"Besorgt die Träne der Erdenmutter von Kriegshetzer O'mrogg und bringt sie zu David Wayne in Waynes Zuflucht."}}
D[10671] = {"Ein Pfund Geschnetzeltes",{"Taumel Dina möchte, dass Ihr 5 Einheiten astralisiertes Fleisch besorgt und zu ihr in Toshleys Station im Schergrat bringt."}}
D[10672] = {"Das ergibt echt keinen Sinn...",{"Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr zu dem Lavastrom in der Nähe der Ruinen von Baa'ri reist und die Arkanosteuereinheit benutzt, um einen Arkanoskorp zu steuern. Schwimmt mit dem Arkanoskorp durch die Lava und markiert 8 große Teufelsfeuerdimetrodons."}}
D[10673] = {"Teufelsbuckel der Große",{"Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr Teufelsbuckel den Großen tötet und Teufelsbuckels Balg beschafft."}}
D[10674] = {"Das Licht der Phantasie einfangen",{"Toshley möchte, dass Ihr die Lichtfalle benutzt, um 15 Lichtkugeln der Razaani zu fangen. Kehrt danach zu Toshley in Toshleys Station im Schergrat zurück."}}
D[10675] = {"Ein Gnom kennt kein Erbarmen!",{"Toshley möchte, dass Ihr die Seelensammlung beschafft. Kehrt danach zu Toshley in Toshleys Station im Schergrat zurück."}}
D[10676] = {"Bann der Illidari",{"Wartet, bis David Wayne das Schwert für Euch fertig geschmiedet hat."}}
D[10677] = {"Der zweite Gang...",{"Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr einen überentwickelten Teufelsfeuermuskelmagen besorgt."}}
D[10678] = {"Das Hauptgericht!",{"Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr Teufelsbuckels Balg besorgt."}}
D[10679] = {"Die Waffe härten",{"Reist zu den siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan und härtet die geschmiedete Klinge des Illidaribanns in den Lavabecken. Kehrt dann mit der gehärteten Klinge des Illidaribanns zu David Wayne in Waynes Zuflucht zurück."}}
D[10680] = {"Die Hand von Gul'dan",{"Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal."}}
D[10681] = {"Die Hand von Gul'dan",{"Sprecht mit Erdheiler Torlok am Altar der Verdammnis im Schattenmondtal."}}
D[10682] = {"Zeit zu verhandeln...",{"Baumhüter Chawn möchte, dass Ihr mit Aufseher Nuaar verhandelt. Kehrt danach zu dem Baumhüter im ewigen Hain im Schergrat zurück."}}
D[10683] = {"Schrifttafeln von Baa'ri",{"Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr 12 Schrifttafeln von Baa'ri vom Boden und von den Arbeitern der Aschenzungen in den Ruinen von Baa'ri sammelt.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10684] = {"Oronu der Älteste",{"Arkanist Thelis beim Sanktum der Sterne möchte, dass Ihr die Befehle von Akama von Oronu dem Ältesten in den Ruinen von Baa'ri besorgt.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10685] = {"Die Verderber der Aschenzungen",{"Beschafft die vier Medaillonfragmente von Haalum, Eykenen, Lakaan und Uylaru und kehrt danach zu Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal zurück.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10686] = {"Der Kerker des Wächters",{"Arkanist Thelis möchte, dass Ihr den Kerker des Wächters südlich der Ruinen von Baa'ri betretet und Sanoru über Akamas Aufenthaltsort befragt.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10687] = {"Ausbildungsgelände von Karabor",{"Larissa Sonnenhieb beim Sanktum der Sterne möchte, dass Ihr 8 Gleven des Sonnenzorns von den Bittstellern der Dämonenjäger und den Initianden der Dämonenjäger in den Ruinen von Karabor, nordöstlich des Sanktums der Sterne, beschafft.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10688] = {"Eine notwendige Ablenkung",{"Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor zurückkehrt und Azaloth auf seine Kerkermeister hetzt.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10689] = {"Altruis",{"Reist in den Westen Nagrands und sucht Altruis den Leider.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10690] = {"Die Höhlenmutter",{"Tötet Rema und meldet Euch dann bei Kommandant Himmelsschatten in Sylvanaar im Schergrat."}}
D[10691] = {"Rückkehr zu den Sehern",{"Sprecht mit Larissa Sonnenhieb beim Sanktum der Sterne im Schattenmondtal.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10692] = {"Varedis muss aufgehalten werden",{"Larissa Sonnenhieb möchte, dass Ihr zu den Ruinen von Karabor geht und Alandien, Theras, Netharel und Varedis tötet. Benutzt das Buch der teuflischen Namen, während Varedis die Fähigkeit 'Metamorphose' einsetzt, um ihn zu schwächen. Kehrt danach mit dem Buch der teuflischen Namen zu Larissa Sonnenhieb zurück.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
