D[10701] = {"Netherbrock zerschmettern",{"Tötet Netherbrock und meldet Euch danach bei Raketenchef Doppeldecker in Area 52 im Nethersturm."}}
D[10702] = {"Routinearbeiten",{"Oberanführer Or'barokh in Schattenmond im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.","","Dazu gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig."}}
D[10703] = {"Zieht Eure Knieschoner an...",{"Than Yoregar in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr 20 Wildtiere des Schattenmondtals tötet.","","Darunter gehörten Teufelseber, Finsterflügelschimären und Sengpanzerzangen. Jede Kombination ist zulässig."}}
D[10704] = {"Wie man in Arkatraz einbricht",{"A'dal bittet Euch, das obere und das untere Fragment des Schlüssels zur Arkatraz zu besorgen. Bringt beide Fragmente zu ihm zurück, damit er sie für Euch zum Schlüssel zur Arkatraz zusammenfügen kann."}}
D[10705] = {"Seher Udalo",{"Sucht Seher Udalo in der Arkatraz in der Festung der Stürme."}}
D[10706] = {"Ein mysteriöses Omen",{"Kehrt zu Akama im Kerker des Wächters im Schattenmondtal zurück."}}
D[10707] = {"Die Terrasse von Ata'mal",{"Begebt Euch auf die Terrasse von Ata'mal im Schattenmondtal und beschafft das Herz des Zorns. Kehrt danach zu Akama beim Kerker des Wächters im Schattenmondtal zurück."}}
D[10708] = {"Akamas Versprechen",{"Bringt das Medaillon von Karabor zu A'dal in Shattrath."}}
D[10709] = {"Zusammenführung",{"Kehrt zu Rexxar in der Donnerfeste im Schergrat zurück."}}
D[10710] = {"Testflug: Der singende Bergrücken",{"Unterzeichnet Tallys Haftungsausschluss und sprecht mit Rally Zapschnapper, um das Zephyriumkapazitorium zu benutzen. Kehrt danach zu Tally Zapschnapper in Toshleys Station zurück."}}
D[10711] = {"Testflug: Razaans Landeplatz",{"Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Kehrt danach zu Tally Zapschnapper in Toshleys Station zurück."}}
D[10712] = {"Testflug: Ruuanwald",{"Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Lasst auf Eurem Flug die Netherwetterfahne rotieren. Bringt die rotierende Netherwetterfahne zu O'Mally Zapschnapper im Ruuanwald."}}
D[10713] = {"...und Zeit zu Handeln",{"Begebt Euch in den Ruuanwald und tötet 10 Roder des Wyrmkults. Kehrt danach zu Baumhüter Chawn im ewigen Hain im Schergrat zurück."}}
D[10714] = {"Auf geisterhaften Schwingen",{"Sucht einen Zuchtmeister der Blutschläger und einen Sterndeuter der Blutschläger, die sich gerade unterhalten. Benutzt Rexxars Pfeife, um Geisterschwinge zu rufen und sie durch ihn zu belauschen. Meldet Euch danach bei Rexxar in der Donnerfeste im Schergrat."}}
D[10715] = {"In die Grabenschlucht",{"Baron Zobelmähne möchte, dass Ihr 7 Giftdrüsen eines Krustenbohrers sammelt, damit er das Gift für Rexxar herstellen kann. Kehrt danach zu ihm beim Zirkel des Blutes im Schergrat zurück."}}
D[10716] = {"Testflug: Rabenwald",{"Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Kehrt danach zu Tally Zapschnapper in Toshleys Station zurück."}}
D[10717] = {"Wilderer wildern",{"Samia Weißwas bittet Euch, 5 Netze des Wyrmkults zu ihr im ewigen Hain im Schergrat zu bringen."}}
D[10718] = {"Die Stimme der Geister",{"Garm Wolfsbruder hat Euch berichtet, wo die Mok'Nathal, Rexxars Volk, leben. Erzählt Rexxar in der Donnerfeste im Schergrat davon."}}
D[10719] = {"Ihr seid eingeladen!",{"Bringt die Einladung zum Treffen zu Baumhüter Chawn im ewigen Hain im Schergrat."}}
D[10720] = {"Die kleinsten Wesen",{"Begebt Euch zum Murmeltierbau und schlagt die Kodobalgtrommel. Vergiftet die drei Fässer im Lager der Blutschläger, während Ihr das Murmeltier kontrolliert. Kehrt zu Rexxar in der Donnerfeste im Schergrat zurück, wenn Ihr Eure Aufgabe erledigt habt."}}
D[10721] = {"Grulloc einen Eber aufbinden",{"Beschafft Grullocs Sack und bringt ihn zu Baron Zobelmähne beim Zirkel des Blutes im Schergrat."}}
D[10722] = {"Treffen am Pechschwingenkoven",{"Sammelt genügend Gewandfetzen von verschiedenen Wyrmkultisten, um eine Aufseherverkleidung herzustellen. Benutzt die Verkleidung, um am Treffen mit Kolphis Dunkelschuppe teilzunehmen. Meldet Euch mit Euren Erkenntnissen bei Baumhüter Chawn im ewigen Hain im Schergrat zurück."}}
D[10723] = {"Gorgrom der Drachenfresser",{"Geht nach Fels'mok und sammelt 3 grausige Totems von den Ogern von Fels'mok. Stellt danach Zobelmähnes Falle bei Gorgroms Altar auf, um Gorgrom den Drachenfresser zu rufen und zu töten.","","Wenn Grogrom tot ist, platziert die drei grausigen Totems in der Nähe seiner Leiche. Kehrt danach zu Rexxar in der Donnerfeste im Schergrat zurück."}}
D[10724] = {"Gefangener der Speerspießer",{"Tötet die Oger der Speerspießer, um an den Flügeldrachenkäfigschlüssel zu kommen. Sobald Ihr ihn habt, benutzt Geisterschwinges Pfeife, um Geisterschwinge zu rufen, der den Käfig öffnen wird. Kehrt zu Rexxar in der Donnerfeste im Schergrat zurück, sobald Ihr Leokk befreit habt."}}
D[10725] = {"Geachtet vom Violetten Auge",{"Bringt Euren violetten Siegelring zu Erzmagierin Leryda in Gebirgspass der Totenwinde, nachdem Ihr einen ehrfürchtigen Ruf bei dem Violetten Auge erlangt habt."}}
