D[10742] = {"Finale",{"Benutzt Rexxars Kampfhorn beim Altar von Goc und tötet Goc. Kehrt danach zu Rexxar in der Donnerfeste im Schergrat zurück."}}
D[10744] = {"Nachricht vom Sieg",{"Kehrt zur Wildhammerfeste zurück und sprecht mit Kurdran Wildhammer."}}
D[10745] = {"Nachricht vom Sieg",{"Kehrt nach Schattenmond zurück uns sprecht mit Oberanführer Or'barokh."}}
D[10747] = {"Welpen des Wyrmkults",{"Samia Weißwas möchte, dass Ihr das Schwarzwelpennetz benutzt, um 10 Schwarzwelpen des Wyrmkults zu fangen. Bringt sie zu ihr im ewigen Hain im Schergrat."}}
D[10748] = {"Maxnar muss sterben!",{"Baumhüter Chawn bittet Euch im Namen der Druiden des Cenarius des ewigen Hains sowie der einheimischen Lebewesen im Ruuanwald Maxnar den Aschenmagen zu töten. Kehrt danach zu ihm im ewigen Hain im Schergrat zurück."}}
D[10749] = {"Baron Zobelmähnes Gift",{"Bringt Baron Zobelmähnes Gift zu Rexxar in der Donnerfeste im Schergrat."}}
D[10750] = {"Der Pfad der Eroberung",{"Reist zum Pfad der Eroberung im Schattenmondtal. Sobald Ihr einen ersten Eindruck von der Gegend habt, benutzt die Leuchtpistole der Kor'kron um einen Windreiter der Kor'kron herbeizurufen.","","Falls Ihr Eure Leuchtpistole der Kor'kron verliert, bittet Oberanführer Or'barokh um eine neue."}}
D[10751] = {"Den Pfad bereinigen",{"Tötet 20 Soldaten der Mondfinsternis, 10 Chevaliers der Mondfinsternis und 10 Zauberbinder der Mondfinsternis. Benutzt die Leuchtpistole der Kor'kron, um einen weiteren Windreiter der Kor'kron zu rufen, wenn Ihr die Aufgabe erfüllt habt.","","Falls Ihr Eure Leuchtpistole der Kor'kron verliert, bittet Oberanführer Or'barokh in Schattenmond im Schattenmondtal um eine neue."}}
D[10752] = {"Auf ins Eschental!",{"Sprecht mit Raene Wolfsläufer in Astranaar."}}
D[10753] = {"Die Verderbnis ausmerzen",{"Tötet 4 Wesen der Schuppenflügelteufelsbrut, 4 Wesen der Dolchrachenteufelsbrut und 2 Teufelsverderber."}}
D[10754] = {"Zugang zur Zitadelle",{"Bringt die präparierte Schlüsselform zu Truppenkommandant Danath in der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[10755] = {"Zugang zur Zitadelle",{"Bringt die präparierte Schlüsselform zu Truppenkommandant Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[10756] = {"Großmeister Rohok",{"Bringt die präparierte Schlüsselform zu Rohok in Thrallmar."}}
D[10757] = {"Rohoks Bitte",{"Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Rohok in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[10758] = {"Heißer als die Hölle",{"Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Rohok in Thrallmar."}}
D[10759] = {"Findet den Deserteur",{"Sucht Parshah in den Magmafeldern und sprecht mit ihm."}}
D[10760] = {"Das Wrack der Sketh'lon",{"Besorgt das Tagebuch des Kommandanten der Sketh'lon - Seite 1, das Tagebuch des Kommandanten der Sketh'lon - Seite 2 und das Tagebuch des Kommandanten der Sketh'lon - Seite 3 von den Arakkoa des Dunklen Rats beim Wrack der Sketh'lon und bringt die Seiten zu Unteroffizier Kargrul in Schattenmond."}}
D[10761] = {"Findet den Deserteur",{"Sucht Parshah in den Magmafeldern und sprecht mit ihm."}}
D[10762] = {"Großmeister Dumphry",{"Bringt die präparierte Schlüsselform zu Dumphry in der Ehrenfeste."}}
D[10763] = {"Dumphrys Bitte",{"Bringt 4 Teufelseisenbarren, 2 Einheiten arkaner Staub und 4 Feuerpartikel zu Dumphry in der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[10764] = {"Heißer als die Hölle",{"Zerstört einen Teufelshäscher auf der Höllenfeuerhalbinsel und haltet die ungebrannte Schlüsselform in seine Überreste. Bringt die verkohlte Schlüsselform danach zu Dumphry in der Ehrenfeste."}}
D[10765] = {"Wenn Welten kollidieren...",{"Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung. Benutzt die Leuchtpistole der Kor'kron, um einen weiteren Windreiter der Kor'kron zu rufen, wenn Ihr die Aufgabe erfüllt habt.","","Falls Ihr Eure Leuchtpistole der Kor'kron verliert, bittet Oberanführer Or'barokh in Schattenmond im Schattenmondtal um eine neue."}}
D[10766] = {"Invasionspunkt: Katastrophe",{"Meldet Euch bei Plexi im Invasionspunkt: Katastrophe."}}
D[10767] = {"Invasionspunkt: Katastrophe",{"Meldet Euch bei Nakansi im Invasionspunkt: Katastrophe."}}
D[10768] = {"Wappenröcke der Illidari",{"Sammelt 10 Wappenröcke der Illidari und benutzt dann die Leuchtpistole der Kor'kron, um einen weiteren Windreiter der Kor'kron herbeizurufen.","","Falls Ihr Eure Leuchtpistole der Kor'kron verliert, bittet Oberanführer Or'barokh in Schattenmond im Schattenmondtal um eine neue."}}
D[10769] = {"Zwietracht in den Rängen...",{"Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Oberanführer Or'barokh in Schattenmond im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Kor'kron zurück."}}
D[10770] = {"Kleine Funken",{"Moosborke der Uralte möchte, dass Ihr 8 Sengwichtel tötet und danach zu ihm im Ruuanwald zurückkehrt."}}
D[10771] = {"Aus der Asche",{"Moosborke der Uralte möchte, dass Ihr nach Skald reist und Eisenwurzelsamen in drei verschiedene Hügel fruchtbarer Vulkanerde pflanzt. Kehrt danach zu ihm im Ruuanwald zurück."}}
D[10772] = {"Der Pfad der Eroberung",{"Reist zum Pfad der Eroberung im Schattenmondtal. Sobald Ihr einen ersten Eindruck von der Gegend habt, benutzt die Leuchtpistole der Wildhämmer, um einen Greifenreiter der Wildhämmer herbeizurufen.","","Falls Ihr Eure Leuchtpistole der Wildhämmer verliert, bittet Than Yoregar in der Wildhammerfeste um eine neue."}}
D[10773] = {"Den Pfad bereinigen",{"Tötet 20 Soldaten der Mondfinsternis, 10 Chevaliers der Mondfinsternis und 5 Söhne des Corok. Benutzt die Leuchtpistole der Wildhämmer, um einen weiteren Greifenreiter der Wildhämmer zu rufen, wenn Ihr die Aufgabe erfüllt habt.","","Falls Ihr Eure Leuchtpistole der Wildhämmer verliert, bittet Than Yoregar in der Wildhammerfeste im Schattenmondtal um eine neue."}}
D[10774] = {"Blutelf +  Riese = ???",{"Tötet Kanzlerin Blutblatt und Corok den Mächtigen und beschafft Illidans Anordnung. Benutzt die Leuchtpistole der Wildhämmer, um einen weiteren Greifenreiter der Wildhämmer zu rufen, wenn Ihr die Aufgabe erfüllt habt.","","Falls Ihr Eure Leuchtpistole der Wildhämmer verliert, bittet Than Yoregar in der Wildhammerfeste im Schattenmondtal um eine neue."}}
D[10775] = {"Wappenröcke der Illidari",{"Sammelt 10 Wappenröcke der Illidari und benutzt dann die Leuchtpistole der Wildhämmer, um einen weiteren Greifenreiter der Wildhämmer herbeizurufen.","","Falls Ihr Eure Leuchtpistole der Wildhämmer verliert, bittet Than Yoregar in der Wildhammerfeste im Schattenmondtal um eine neue."}}
D[10776] = {"Zwietracht in den Rängen...",{"Tötet 5 wahnsinnige Kolosse, während Ihr als Anhänger Illidans verkleidet seid, und meldet Euch danach bei Than Yoregar in der Wildhammerfeste im Schattenmondtal. Bringt ihm auch seine Leuchtpistole der Wildhämmer zurück."}}
D[10777] = {"Asghars Totem",{"Bringt das Kriegstotem der Sketh'lon zu Parshah in den Magmafeldern."}}
D[10778] = {"Die Rute von Lianthe",{"Besorgt Euch den Schlüssel von Lianthe von den Blutelfen in der Stätte der Mondfinsternis und benutzt ihn, um die Schließkassette von Lianthe zu öffnen und die Rute von Lianthe an Euch zu nehmen. Bringt die Rute zu Parshah in den Magmafeldern."}}
D[10779] = {"Der Pfad des Jägers",{"Sprecht mit Kella Nachtbogen auf der Azurmythosinsel."}}
D[10780] = {"Federn der Sketh'lon",{"Sammelt 8 Federn der Sketh'lon und bringt sie zu Parshah in den Magmafeldern."}}
D[10781] = {"Die Schlacht an der Purpurwacht",{"Bekämpft Illidans Truppen bei der Purpurwacht und überlebt!","","Kehrt zu A'dal in Shattrath zurück, wenn Ihr als Sieger aus der Schlacht hervorgehen solltet."}}
D[10782] = {"Das Kopfstück mit Magie erfüllen",{"Legt das unfertige Kopfstück an und reist zum Altar der Verdammnis. Benutzt das Kopfstück, während Ihr in der Nähe von Gul'dan steht, und kehrt zu Parshah in den Magmafeldern zurück, wenn Ihr es aufgeladen habt."}}
D[10783] = {"Baron Zobelmähne",{"Sprecht mit Baron Zobelmähne beim Zirkel des Blutes im Schergrat."}}
D[10784] = {"Vernichtet das Lager der Blutschläger!",{"Tor'chunk Zweiklaue möchte, dass Ihr 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger tötet. Kehrt zu ihm in der Donnerfeste im Schergrat zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[10785] = {"Das ist eine Falle!",{"Bringt die Drachenfeuerfalle zu Rexxar in der Donnerfeste im Schergrat."}}
D[10786] = {"Gemetzel in Fels'mok",{"Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok. Kehrt danach zu Tor'chunk Zweiklaue in der Donnerfeste im Schergrat zurück."}}
D[10788] = {"Rückkehr to Talionia",{"Sprecht mit Talionia in Silbermond."}}
D[10789] = {"Rückkehr zu Carendin Halgar",{"Sprecht mit Carendin Halgar in Unterstadt."}}
D[10790] = {"Rückkehr zu Gan'rul Blutauge",{"Sprecht mit Gan'rul Blutauge in Orgrimmar."}}
D[10791] = {"Willkommen Wolfgeist!",{"Benutzt den zeremoniellen Weihrauch in der Nähe der Kerzen in Malukaz' Hütte und beobachtet die Zeremonie. Sprecht erneut mit Malukaz, wenn die Zeremonie vorbei ist."}}
D[10792] = {"Zeth'Gor muss brennen!",{"Tötet Peons des Blutenden Auges, um an ihre Fackeln zu kommen. Entzündet sie an der Schmiede von Zeth'Gor und werft die brennenden Fackeln auf die Gebäude von Zeth'Gor."}}
D[10793] = {"Val'zareqs Tagebuch: Vorboten des Krieges",{"Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht.","","Sucht ihn in einem Kristallgefängnis."}}
D[10794] = {"Schurken der Zerschmetterten Hand",{"Sprecht mit Shenthul in Orgrimmar."}}
D[10795] = {"Ein Treffen mit Dorgok",{"Kommandant Haephus Steinwall bittet Euch, Dorgok im Lager der Blutschläger zu vernichten. Kehrt danach zu ihm im ewigen Hain im Schergrat zurück."}}
D[10796] = {"Vernichtet das Lager der Blutschläger!",{"Leutnant Schönwetter möchte, dass Ihr 10 Raufer der Blutschläger und 5 Hexenmeister der Blutschläger tötet. Kehrt danach zu ihr im ewigen Hain im Schergrat zurück."}}
D[10797] = {"Die Gunst der Gronn",{"Bringt Gorgroms Gunst zu Kommandant Haephus Steinwall im ewigen Hain im Schergrat."}}
D[10798] = {"Dem Baron einen Besuch abstatten",{"Sprecht mit Baron Zobelmähne und bittet ihn, eine Falle herzustellen. Er befindet sich beim Zirkel des Blutes im Schergrat."}}
D[10799] = {"In die Grabenschlucht",{"Baron Zobelmähne möchte, dass Ihr ihm 7 Giftdrüsen eines Krustenbohrers bringt. Kehrt danach zu ihm beim Zirkel des Blutes im Schergrat zurück."}}
D[10800] = {"Gute Nacht, Gronn",{"Baron Zobelmähne möchte, dass Ihr Grullocs Sack stehlt und zu ihm beim Zirkel des Blutes im Schergrat bringt."}}
D[10801] = {"Das ist eine Falle!",{"Bringt die Drachenfeuerfalle zu Kommandant Haephus Steinwall im ewigen Hain im Schergrat."}}
D[10802] = {"Gorgrom der Drachenfresser",{"Geht nach Fels'mok und sammelt 3 grausige Totems von den Ogern von Fels'mok. Benutzt danach Zobelmähnes Falle bei Gorgroms Altar, um Gorgrom den Drachenfresser zu rufen und zu töten.","","Platziert die 3 grausigen Totems in der Nähe seines Körpers, wenn er gestorben ist. Kehrt danach zu Kommandant Haephus Steinwall im ewigen Hain im Schergrat zurück."}}
D[10803] = {"Gemetzel in Fels'mok",{"Tötet 5 Schläger von Fels'mok und 3 Schamanen von Fels'mok. Kehrt danach zu Leutnant Schönwetter im ewigen Hain im Schergrat zurück."}}
D[10804] = {"Freundlichkeit",{"Mordenai bei den Netherschwingenfeldern im Schattenmondtal möchte, dass Ihr 8 ausgewachsene Drachen der Netherschwingen füttert."}}
D[10805] = {"Massaker in Gruuls Unterschlupf",{"Baron Zobelmähne möchte, dass Ihr und Eure Freunde 10 Vollstrecker der Speerspießer, 5 Kampfmagier der Speerspießer, 5 Felshetzer der Speerspießer und ihren Anführer Fingrom tötet. Kehrt zu dem Baron beim Zirkel des Bluts im Schergrat zurück, wenn Ihr Eure Aufgabe erledigt habt."}}
D[10806] = {"Finale",{"Benutzt Zobelmähnes Siegelring beim Altar von Goc und tötet Goc. Kehrt danach zu Baron Zobelmähne beim Zirkel des Blutes im Schergrat zurück."}}
D[10807] = {"Die Aschenzungen",{"Varen der Fordernde möchte, dass Ihr zu den Ruinen von Baa'ri geht und 3 Antreiber der Aschenzungen, 4 Krieger der Aschenzungen und 6 Schamanen der Aschenzungen tötet.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10808] = {"Dem Dunklen Rat in die Quere kommen",{"Tötet die Ritualisten des Dunklen Rats und benutzt Parshahs Stab, um das Beschwörungsritual des Dunklen Rats zu beenden. Kehrt danach zu Parshah in den Magmafeldern zurück."}}
D[10809] = {"Gesucht: Worgmeister Kruush",{"Tötet Worgmeister Kruush und bringt seinen Kopf zu Hauptmann Nachtheul im Rückenbrecherposten."}}
D[10810] = {"Die beschädigte Maske",{"Bringt die beschädigte Maske zu O'Mally Zapschnapper im Ruuanwald."}}
D[10811] = {"Sucht Neltharaku auf",{"Sucht Neltharaku, den Patron des Drachenschwarms der Netherschwingen auf."}}
D[10812] = {"Die geheimnisvolle Maske",{"Bringt die geheimnisvolle Maske zu Wildfürst Antelarion im Ruuanwald."}}
D[10813] = {"Die Augen von Grillok",{"Benutzt Zezzaks Splitter, um ein Auge von Grillok zu fangen und nähert Euch damit Zezzaks Kessel. Bringt den Splitter zu Zezzak zurück, wenn Ihr das Auge dem Kessel übergeben habt."}}
D[10814] = {"Neltharakus Geschichte",{"Sprecht mit Neltharaku und hört Euch seine Geschichte an."}}
D[10815] = {"Val'zareqs Tagebuch: Vorboten des Krieges",{"Findet Marcus Auralion, Hochgeneral der Sha'tar, bei der Purpurwacht."}}
D[10816] = {"Rückforderung geheiligten Bodens",{"Verteidiger Aluumen möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.","","Das Abschließen von Aufgaben für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10817] = {"Die große Vergeltung",{"Varen der Fordernde möchte, dass Ihr 8 Töter des Schattenmondklans, 8 Auserwählte des Schattenmondklans und 4 Dunkelwirker des Schattenmondklans tötet.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10818] = {"Baron Zobelmähne verlangt nach Euch",{"Ihr habt eine Einladung erhalten, um in einer Angelegenheit von höchster Wichtigkeit mit Baron Zobelmähne zu sprechen. Sucht ihn beim Zirkel des Blutes im Schergrat auf."}}
D[10819] = {"Die Gasmaske der Teufelsbrut",{"Setzt die Gasmaske der Teufelsbrut auf und benutzt den Legionskommunikator im Konstruktionslager: Groll."}}
D[10820] = {"Täuscht den Feind",{"Tötet 4 Knechte der Schicksalsschmiede und 4 Ingenieure der Schicksalsschmiede."}}
D[10821] = {"Ihr seid gefeuert!",{"Tötet Schicksalsruferin und meldet Euch dann bei Wildfürst Antelarion im ewigen Hain."}}
D[10822] = {"Einzelne Siegel des Sonnenzorns"}
D[10823] = {"Mehr Siegel des Sonnenzorns"}
D[10824] = {"Siegel des Sonnenzorns",{"Kampfmagierin Vyara beim Sanktum der Sterne möchte, dass Ihr ihr 10 Siegel des Sonnenzorns bringt.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10825] = {"Die kugellose Wahrheit",{"Bringt die Kugel der Grishna zu Baumhüter Chawn im Ruuanwald im Schergrat."}}
D[10826] = {"Male des Sargeras",{"Bringt 10 Male des Sargeras zu Herold Saronen im Schattenmondtal.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10827] = {"Mehr Male des Sargeras",{"Tragt Ihr noch mehr Insignien des Feindes bei Euch, <Name>? Wir bekämpfen die Legion, bis das Licht siegt!"}}
D[10828] = {"Einzelne Male des Sageras",{"Ich nehme Euch alle übrigen Male, die Ihr habt, ab. Keine Sorge, Eure Taten werden nicht unbemerkt bleiben."}}
D[10829] = {"Baumriese muss es wissen",{"Baumhüter Chawn bittet Euch, Baumriese aufzusuchen und mit ihm zu sprechen. Ihr findet das Urtum im Rabenwald im Schergrat."}}
D[10830] = {"Der Exorzismus der Bäume",{"Sammelt 5 Kugeln von Grishnath und 5 Terrorfederkiele und stellt daraus Exorzismusfedern her. Benutzt die Federn, um 5 Koikoigeister von den Laubbärten des Rabenwaldes zu exorzieren und zu töten. Sobald Ihr die Aufgabe erledigt habt, kehrt zu Baumriese im Rabenwald im Schergrat zurück."}}
D[10831] = {"Wie man ein Mondstoffschneider wird",{"Benutzt das magieerfüllte Netherstoffstück während Ihr im Mondbrunnen der Zuflucht des Cenarius steht, um eine Urmondstoffprobe herzustellen. Bringt die fertige Urmondstoffprobe zu Nasmara Mondweise im unteren Viertel von Shattrath.","","ACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen."}}
D[10832] = {"Wie man ein Zauberfeuerschneider wird",{"Bringt eine Probe einer Nethergespenstessenz zu Gidge Spruchwirker im unteren Viertel von Shattrath.","","ACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen."}}
D[10833] = {"Wie man ein Schattenzwirnschneider wird",{"Benutzt den Kristall der tiefen Schatten in der Nähe des Altars der Schatten, um Eure Verbindung zu dem Altar zu stärken. Kehrt danach zu Andrion Dunkelweber im unteren Viertel in Shattrath zurück.","","ACHTUNG! Ihr könnt nur eine Schneidereispezialisierung auswählen."}}
D[10834] = {"Grillok 'Finsterauge'",{"Tötet Grillok Finsterauge und bringt Grilloks Augenklappe zu Zezzak im Rückenbrecherposten."}}
D[10835] = {"Apotheker Antonivich",{"Bringt Albrecks Befund zu Apotheker Antonivich in Thrallmar."}}
D[10836] = {"Unterwanderung der Festung des Drachenmals",{"Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 15 Orcs des Drachenmals tötet.","","Sämtliche Orcs des Drachenmals in der Festung des Drachenmals kommen dafür in Frage."}}
D[10837] = {"Zur Netherschwingenscherbe!",{"Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 12 Netherrankenkristalle auf der Netherschwingenscherbe sammelt."}}
D[10838] = {"Der dämonische Seher",{"Benutzt den dämonischen Seher im Höllenfeuerbecken, wartet, bis er sich eingestellt hat und führt dann eine Messung durch.","","Bringt den dämonischen Seher und die Messungen des dämonischen Sehers zu Apotheker Antonivich in Thrallmar."}}
D[10839] = {"Dunkelstein des Skithverstecks",{"Benutzt die Rute der Läuterung bei Terokks Dunkelstein im Skithversteck und kehrt danach zu Kirrik bei der Flüchtlingskarawane in der Knochenwüste zurück."}}
D[10840] = {"Das Grab des Lichts",{"Hohepriester Orglum möchte, dass Ihr zum Grab des Lichts reist und 10 astrale Nethermanten und 10 astrale Brandschatzer tötet. Kehrt danach zu ihm bei der Flüchtlingskarawane zurück."}}
D[10841] = {"Der rachsüchtige Herold",{"Aktiviert das Gerät."}}
D[10842] = {"Der rachsüchtige Herold",{"Hohepriester Orglum möchte, dass Ihr in das Grab des Lichts reist und das Grabrelikt der Draenei in der Nähe des uralten Draeneialtars benutzt.","","Verteidigt den Grabwächter und vernichtet den rachsüchtigen Herold. Sprecht mit dem Draeneivorfahren beim uralten Draeneialtar, wenn das Ritual vollendet ist."}}
D[10843] = {"Seit ich denken kann...",{"Um Euch den Mok'Nathal gegenüber zu beweisen, hat Leoroxx Euch aufgetragen, Gnosh Brognat, den Anführer der Oger im Außenposten der Speerspießer zu töten. Kehrt zu Leoroxx im Dorf der Mok'Nathal im Schergrat zurück, wenn Ihr es geschafft habt, oder kehrt gar nicht mehr zurück."}}
D[10844] = {"Konstruktionslager: Groll"}
D[10845] = {"Tötet die Brutmutter",{"Leoroxx fordert Euch auf, Unheilschwinge zu töten. Kehrt zu ihm im Dorf der Mok'Nathal zurück, wenn Ihr es geschafft habt."}}
D[10846] = {"Verständnis für die Mok'Nathal",{"Um die Mok'Nathal zu verstehen, müsst Ihr Vekh, den Anführer der Arakkoa der Vekh'nir töten. Kehrt danach zu Leoroxx im Dorf der Mok'Nathal im Schergrat zurück."}}
D[10847] = {"Die Augen von Skettis",{"Bringt das Auge des Reskkverstecks und das Auge des Shienorverstecks zu Rilak dem Erlösten im unteren Viertel von Shattrath."}}
D[10848] = {"Das untote Böse des Rhazeverstecks",{"Tötet 4 Todeskrallengeister, 4 kreischende Geister und 2 Geistraben und kehrt danach zu Kirrik bei der Flüchtlingskarawane zurück."}}
D[10849] = {"Sucht Kirrik",{"Bringt Rilaks Schreiben zu Kirrik bei der Flüchtlingskarawane in der Knochenwüste."}}
D[10850] = {"Nethergas in einem Teufelsfeuermotor",{"Ihr findet die Öffnung, durch die der Teufelshäscher betankt wird."}}
D[10851] = {"Die Totems meines Feindes",{"Sammelt 5 Totems der Speerspießer für Geistrufer Dohgar im Dorf der Mok'Nathal im Schergrat."}}
D[10852] = {"Vermisste Freunde",{"Ethan möchte, dass Ihr 12 seiner vermissten Freunde im Skithversteck findet und sie zu ihm bei der Flüchtlingskarawane zurückbringt."}}
D[10853] = {"Geisteranrufung",{"Geistrufer Dohgar bittet Euch, das Totem der Geisteranrufung zu benutzen, um 8 Geister eines geringen Netherdrachen zu sammeln. Kehrt danach zu ihm im Dorf der Mok'Nathal im Schergrat zurück."}}
D[10854] = {"Die Macht Neltharakus",{"Neltharaku, der hoch über den Netherschwingenfeldern im Schattenmondtal seine Kreise zieht, möchte, dass Ihr 5 versklavte Drachen der Netherschwingen befreit."}}
D[10855] = {"Teufelshäscher, nein Danke!",{"Beschafft Euch 5 Einheiten kondensiertes Nethergas von den Robogenieuren der Gan'arg in der Konstruktionsbasis: Vergessenheit und füllt sie in einen deaktivierten Teufelshäscher. Kehrt danach zu Netherpirscher Nauthis zurück."}}
D[10856] = {"Die beste Verteidigung",{"Netherpirscher Nauthis möchte, dass Ihr 12 Zornschaffer in der Konstruktionsbasis: Gehenna nördlich der Sturmsäule vernichtet."}}
D[10857] = {"Teleportiert das!",{"Netherpirscher Nauthis möchte, dass Ihr den Stab der geistigen Beeinflussung bei den Mo'arg in der Konstruktionsbasis: Gehenna einsetzt und ihre Fähigkeit 'Teleporter sprengen' bei den drei Teleportern in der Konstruktionsbasis benutzt."}}
D[10858] = {"Karynaku",{"Sucht nach Karynaku in der Festung des Drachenmals."}}
D[10859] = {"Sammelt die Kugeln",{"Geistrufer Dohgar bittet Euch, das Kugelfängertotem zu benutzen, um 15 Lichtkugeln der Razaani zu sammeln. Kehrt danach zu ihm im Dorf der Mok'Nathal im Schergrat zurück."}}
D[10860] = {"Leckerbissen der Mok'Nathal",{"Matrone Varah hat Euch eine Liste mit Zutaten für die Zubereitung ihrer beiden Lieblingsgerichte gegeben. Darunter befinden sich 3 Raptorenrippchen und 3 Stück Schlangenfleisch. Bringt sie zu ihr im Dorf der Mok'Nathal im Schergrat."}}
D[10861] = {"Präventivschlag gegen das Lithicversteck",{"Zerbrecht die verfluchten Eier im Lithicversteck. Erlöst 3 Jungtiere und tötet 3 bösartige Jungtiere. Kehrt danach zu Kirrik bei der Flüchtlingskarawane zurück."}}
D[10862] = {"Auslieferung an die Horde",{"Rokag möchte, dass Ihr Rilak den Erlösten in Shattrath aufsucht und von ihm fordert, dass er und sein Volk sich der Horde ausliefern."}}
D[10863] = {"Geheimnisse der Arakkoa",{"Lady Dena Kennedy möchte, dass Ihr Rilak den Erlösten aufsucht und herausfindet, welche Geheimnisse der Arakkoa er mit Euch teilen wird."}}
D[10864] = {"Eine Last auf der Seele",{"Tötet 20 Orcs der Zerschmetterten Hand und kehrt danach zu Apotheker Antonivich in Thrallmar zurück."}}
D[10865] = {"Informiert Leoroxx!",{"Geistrufer Dohgar fleht Euch an, Leoroxx über die Taten der Astralen der Razaani zu informieren. Ihr findet ihn im Dorf der Mok'Nathal im Schergrat."}}
D[10866] = {"Zuluhed der Geschlagene",{"Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien."}}
D[10867] = {"Es kann nur eine Antwort geben",{"Leoroxx fleht Euch an, die Seelensammlung zu beschaffen und sie zu Geistrufer Dohgar im Dorf der Mok'Nathal im Schergrat zu bringen."}}
D[10868] = {"Der Kriegspfad der Arakkoa",{"Beraterin Faila bittet Euch, 14 Krallaniere der Shienor und 6 Zauberhexer der Shienor zu töten. Kehrt danach zu ihr in der Steinbrecherfeste zurück."}}
D[10869] = {"Die Herde ausdünnen",{"Leutnant Kieshammer bittet Euch, 14 Krallaniere der Shienor und 6 Zauberhexer der Shienor zu töten. Kehrt danach zu ihm in Allerias Feste zurück."}}
D[10870] = {"Verbündeter der Netherschwingen",{"Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen."}}
D[10871] = {"Verbündeter der Netherschwingen",{"Lasst Euch von Karynaku zurück zu Mordenai in den Netherschwingenfeldern bringen."}}
D[10872] = {"Zuluhed der Geschlagene",{"Tötet Zuluhed den Geschlagenen und beschafft Euch Zuluheds Schlüssel. Benutzt Zuluheds Schlüssel, um Zuluheds Fesseln zu öffnen und Karynaku zu befreien."}}
D[10873] = {"Bei Nacht verschleppt",{"Späher Navrin möchte, dass Ihr zum Netherweberkamm reist und 6 eingesponnene Verteidiger der Sha'tar befreit. Kehrt danach zu Navrin im Außenposten der Sha'tari zurück."}}
D[10874] = {"Signalfeuer des Shalasverstecks",{"Kirrik bei der Flüchtlingskarawane möchte, dass Ihr die vier Signalfeuer des Shalasverstecks löscht."}}
D[10875] = {"Bericht an Nazgrel",{"Sprecht mit Nazgrel in Thrallmar."}}
D[10876] = {"Am Fuße der Zitadelle",{"Tötet Truppenkommandant Gorax, platziert die Herausforderung der Horde auf seinem Leichnam. Tötet danach die Hand von Kargath und bringt den Kopf der Hand von Kargath zu Nazgrel in Thrallmar."}}
D[10877] = {"Das Schreckensrelikt",{"Oakun möchte, dass Ihr nach Osten zur herrenlosen Karawane reist und das Schreckensrelikt besorgt. Kehrt zu Oakun zurück, wenn Eure Aufgabe erledigt ist."}}
D[10878] = {"Bevor die Dunkelheit sich senkt",{"Mekeda bei der Flüchtlingskarawane in den Wäldern von Terokkar möchte, dass Ihr 8 Scharmützler der Kabale, 4 Zauberwirker der Kabale und 2 Initianden der Kabale tötet."}}
D[10879] = {"Offensive aus Skettis",{"Haltet die Angreifer auf und sprecht mit Rilak."}}
D[10880] = {"Befehle der Kabale",{"Bringt die Befehle der Kabale zu Mekeda bei der Flüchtlingskarawane in den Wäldern von Terokkar."}}
D[10881] = {"Das Schattengrab",{"Geht in das Schattengrab westlich der Flüchtlingskarawane und beschafft Euch Arunens Tuch, K'alens Hammer und Atalors Schriftrolle. Kehrt danach zu Mekeda bei der Flüchtlingskarawane zurück."}}
D[10882] = {"Herold der Verdammnis",{"Ihr wurdet beauftragt, zur Arkatraz in der Festung der Stürme zu reisen und Herold Horizontiss zu töten. Kehrt danach zu A'dal auf der Terrasse des Lichts in Shattrath zurück."}}
D[10883] = {"Der Schlüssel der Stürme",{"Sprecht mit A'dal in Shattrath."}}
D[10884] = {"Die Prüfung der Naaru: Erbarmen",{"A'dal in Shattrath möchte, dass Ihr die unbenutzte Axt des Henkers aus den Zerschmetterten Hallen der Höllenfeuerzitadelle besorgt.","","Diese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[10885] = {"Die Prüfung der Naaru: Stärke",{"A'dal in Shattrath möchte, dass Ihr Kalithreshs Dreizack und Murmurs Essenz besorgt.","","Diese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[10886] = {"Die Prüfung der Naaru: Zuverlässigkeit",{"A'dal in Shattrath möchte, dass Ihr Millhaus Manasturm aus der Arkatraz in der Festung der Stürme rettet.","","Diese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[10887] = {"Flucht aus dem Grab",{"Helft Akuno zur Flüchtlingskarawane in den Wäldern von Terokkar zu gelangen. Sprecht danach mit Mekeda."}}
D[10888] = {"Die Prüfung der Naaru: Magtheridon",{"A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet."}}
D[10889] = {"Rückkehr nach Shattrath",{"Reist nach Shattrath und Sprecht mit Rilak."}}
D[10891] = {"Imperiale Plattenrüstung",{"Sprecht Derotain Matschnipper in Gadgetzan."}}
D[10892] = {"Imperiale Plattenrüstung",{"Sprecht Derotain Matschnipper in Gadgetzan."}}
D[10893] = {"Langschweif ist der springende Punkt",{"Vernichtet Draaca Langschweif, die Anführerin der Wyrmkultisten im Tunnel des Wyrmschädels. Meldet Euch danach bei Behüter Mondschatten beim Tunnel des Wyrmschädels im Schergrat zurück."}}
D[10894] = {"Behüter des Wyrmschädels",{"Bringt die Einladung zum Treffen zu Behüter Mondschatten beim Eingang des Tunnels des Wyrmschädels im Schergrat."}}
D[10895] = {"Zeth'Gor muss brennen!",{"Benutzt das Rauchsignal unter jedem Wachturm in Zeth'Gor und kehrt danach zu Schwadronskommandant Dabir'ee beim Expeditionsposten zurück."}}
D[10896] = {"Die verseuchten Beschützer",{"Lakotae möchte, dass Ihr 25 Baummilben tötet und danach zu ihm bei der Flüchtlingskarawane zurückkehrt. Ihr findet die Milben in den Körpern der faulenden Waldwüter und befallenen Wurzelwandler."}}
D[10897] = {"Meister der Tränke",{"Lauranna Thar'well möchte, dass Ihr die Botanika der Festung der Stürme betretet und den Naturführer der Botanika von Hochbotaniker Freywinn besorgt. Zusätzlich möchte sie, dass Ihr ihr 5 erstklassige Heiltränke, 5 erstklassige Manatränke und 5 erhebliche Tränke des traumlosen Schlafs bringt.","","ACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen."}}
D[10898] = {"Wolkenschwinge",{"Begleitet Wolkenschwinge und meldet Euch dann bei Rilak dem Erlösten in Shattrath."}}
D[10899] = {"Meister der Transmutation",{"Zarevhi in der Sturmsäule im Nethersturm möchte, dass Ihr ihm 4 Einheiten Urmacht bringt.","","ACHTUNG! Ihr könnt nur eine Alchimiespezialisierung wählen."}}
D[10900] = {"Das Mal von Vashj",{"Brennt es nieder, <Volk>! Brennt alles nieder! Sie haben nichts verdient. Habt Ihr mich verstanden? NICHTS! Sie müssen für ihre Taten bezahlen. Auch für ihre zukünftigen.","","Ich würde Vashj selbst töten, wenn ich von diesen verdammten Fesseln frei wäre.","","Oder wollt Ihr vielleicht Neptulons Arbeit erledigen? Ihr Tod ist uns beiden dienlich, Weichhaut. Werdet Ihr mir dabei helfen, den heiligen Knüppel herzustellen?"}}
D[10901] = {"Der Knüppel von Kar'desh",{"Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt."}}
D[10902] = {"Meister der Elixiere",{"Begebt Euch in den Schwarzen Morast in den Höhlen der Zeit und besorgt 10 Essenzen der Unendlichkeit von den Fürsten der Zeitenrisse und den Bewahrerinnen der Zeitenrisse. Bringt die Essenzen zusammen mit 5 Elixieren der erheblichen Verteidigung, 5 Elixieren des Meisters und 5 Elixieren der erheblichen Beweglichkeit zu Lorokeem im unteren Viertel von Shattrath.","","ACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchimie wählen!"}}
D[10903] = {"Rückkehr zur Ehrenfeste",{"Sprecht mit Gehilfe Klatu im Gasthaus der Ehrenfeste."}}
D[10904] = {"Teufelsmunition",{"Der Druide des ewigen Hains hat Euch aufgetragen, 5 Teufelskanonenkugeln zu sammeln. Sobald Ihr fertig seid, benutzt das Druidensignal, um den Druiden des ewigen Hains zur Schwelle des Todes im Schergrat zu rufen."}}
D[10905] = {"Meister der Tränke",{"Sprecht mit Lauranna Thar'well in der Zuflucht des Cenarius in den Zangarmarschen.","","ACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchimie erlernen."}}
D[10906] = {"Meister der Elixiere",{"Sprecht mit Lorokeem im unteren Viertel von Shattrath.","","ACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchimie erlernen."}}
D[10907] = {"Meister der Transmutation",{"Sprecht mit Zarevhi in der Sturmsäule im Nethersturm.","","ACHTUNG! Ihr könnt nur eine Spezialisierung in der Alchimie erlernen."}}
D[10908] = {"Sprecht mit Rilak dem Erlösten",{"Kirrik der Erwachte möchte, dass Ihr mit Rilak dem Erlösten im unteren Viertel von Shattrath sprecht."}}
D[10909] = {"Höllengeister",{"Klatu in der Ehrenfeste möchte, dass Ihr das Relikt des Anachoreten beim Außenposten von Gor'gaz benutzt, die Orcs der Zerschmetterten Hand in der Nähe des Relikts tötet und dann 10 freigesetzte Höllengeister vernichtet, um Oberst Jules zu rächen."}}
D[10910] = {"Die Schwelle des Todes",{"Wildfürst Antelarion fleht Euch an, zur Schwelle des Todes zu reisen. Sobald Ihr dort angekommen seid, benutzt das Druidensignal, um einen Druiden des ewigen Hains zu rufen und mit ihm zu sprechen."}}
D[10911] = {"Feuer frei!",{"Benutzt die naturalisierte Munition, um die Kontrolle über die Teufelskanonen der Schwelle des Todes zu erlangen. Benutzt sie, um das südliche Warpportal und das nördliche Warpportal zu zerstören. Benutzt danach das Druidensignal, um einen Druiden des ewigen Hains zu rufen und ihm von Eurem Erfolg zu berichten."}}
D[10912] = {"Der Hundehetzer",{"Der Druide des ewigen Hains hat Euch aufgetragen, als letzte Aufgabe Baelmon den Hundehetzer zu töten. Kehrt danach zum ewigen Hain im Schergrat zurück und berichtet Wildfürst Antelarion von Eurem Erfolg."}}
D[10913] = {"Ein unangemessenes Begräbnis",{"Kommandant Ra'vaj beim Außenposten der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 8 getötete Kämpfer der Auchenai und 8 getötete Verteidiger der Sha'tar verbrennt."}}
D[10914] = {"Wir brauchen einen Helden!",{"Kommandant Ra'vaj beim Außenposten der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr 12 Initianden der Auchenai und 5 Verdammnisverkünder der Auchenai tötet."}}
D[10915] = {"Der gefallene Exarch",{"Kommandant Ra'vaj beim Außenposten der Sha'tari in der Knochenwüste der Wälder von Terokkar möchte, dass Ihr den Inhalt des Sargs der Auchenai vernichtet."}}
D[10916] = {"Nach Gebetsperlen graben",{"Sucht die Gebetsperlen der Draenei und bringt sie zu Gehilfe Klatu in der Ehrenfeste."}}
D[10917] = {"Die Pflicht eines Ausgestoßenen",{"Bringt 30 Arakkoafedern zu Vekax im unteren Viertel von Shattrath."}}
D[10918] = {"Mehr Federn"}
D[10919] = {"Fei-Feis Belohnung",{"Fei-Fei schaut Euch erwartungsvoll an..."}}
D[10920] = {"Für die Gefallenen",{"Verteidiger Haylen möchte, dass Ihr 20 Schreckenswitwen tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt."}}
D[10921] = {"Terokkarantula",{"Verteidiger Haylen möchte, dass Ihr Terokkarantula tötet und danach zu ihm westlich des Netherweberkamms zurückkehrt."}}
D[10922] = {"In den Knochen wühlen",{"Begleitet Letoll und seine Truppe und beschützt sie, während sie ihre Ausgrabung durchführen. Kehrt danach zu Zwergowitz beim Außenposten der Sha'tari zurück."}}
D[10923] = {"Das Böse rückt näher",{"Oakun möchte, dass Ihr das Schreckensrelikt zum gequälten Hügel bringt. Tötet dort die Todessprecher und Verdammnisverkünder der Auchenai, um 20 Verdammnisschädel zu sammeln. Sucht danach den Beschwörungskreis des gequälten Hügels auf und benutzt das Schreckensrelikt, um Teribus den Verfluchten zu beschwören und zu vernichten. Kehrt zu Oakun zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[10924] = {"Verwichtelt und zugenäht!",{"Bringt 8 Phiolen Sphärenhetzerblut zu Sab'aoth in Kosmozang."}}
D[10925] = {"Das Böse rückt näher"}
D[10926] = {"Rückkehr zum Basislager der Sha'tari",{"Verteidiger Haylen möchte, dass Ihr zum Basislager der Sha'tari zurückkehrt und mit Späher Navrin sprecht."}}
D[10927] = {"Die Krabbler erschlagen",{"Schildwache Mondwisper beim Tunnel zwischen den Zangarmarschen und dem Schergrat möchte, dass Ihr 6 Höhlenkrabbler tötet. Meldet Euch danach bei Kommandant Himmelsschatten in Sylvanaar."}}
D[10928] = {"Die Krabbler erschlagen",{"Grunzer Grahk beim Tunnel zwischen den Zangarmarschen und dem Schergrat möchte, dass Ihr 6 Höhlenkrabbler tötet. Meldet Euch danach bei Tor'chunk Zweiklaue in der Donnerfeste."}}
D[10929] = {"Stampfen",{"Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm 8 Kadaver eines ausgewachsenen Knochenwühlers bringt."}}
D[10930] = {"Der große Knochenwurm",{"Zwergowitz beim Basislager der Sha'tari in der Knochenwüste möchte, dass Ihr ihm riesige Knochenwurmorgane bringt.","","Bringt auch den Stampfer zu ihm zurück."}}
D[10931] = {"Rückkehr zur Exodar",{"Sprecht mit Caedmos in der Exodar."}}
D[10932] = {"Rückkehr zur Exodar",{"Sprecht mit Caedmos in der Exodar."}}
D[10933] = {"Rückkehr nach Silbermond",{"Sprecht mit Aldrae in Silbermond."}}
D[10934] = {"Rückkehr nach Silbermond",{"Sprecht mit Aldrae in Silbermond."}}
D[10935] = {"Der Exorzismus des Oberst Jules",{"Sprecht mit Anachoret Barada. Benutzt die Gebetsperlen, um bei dem Ritual zu helfen und sprecht mit Oberst Jules, wenn er gerettet wurde. Kehrt danach zu Gehilfe Klatu zurück."}}
D[10936] = {"Trollbann sucht Euch",{"Gehilfe Klatu hat Euch informiert, dass Truppenkommandant Danath Trollbann nach Euch sucht. Sprecht mit ihm in der Kaserne der Ehrenfeste auf der Höllenfeuerhalbinsel."}}
D[10937] = {"Die Züchtigung des Drillmeisters",{"Truppenkommandant Danath Trollbann befiehlt Euch, Drillmeister Zurok so schnell wie möglich zur Strecke zu bringen. Kehrt zu dem Truppenkommandanten in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück, wenn der Drillmeister tot ist."}}
D[10938] = {"Segenskartenset des Dunkelmond-Jahrmarkts",{"Gebt das Segenskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist."}}
D[10939] = {"Sturmkartenset des Dunkelmond-Jahrmarkts",{"Gebt das Sturmkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist."}}
D[10940] = {"Furienkartenset des Dunkelmond-Jahrmarkts",{"Gebt das Furienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist."}}
D[10941] = {"Deliriumkartenset des Dunkelmond-Jahrmarkts",{"Gebt das Deliriumkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist."}}
D[10942] = {"Die Kinderwoche",{"Benutzt die Pfeife des Blutelfenwaisenkinds, um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet."}}
D[10943] = {"Die Kinderwoche",{"Benutzt die Pfeife des Draeneiwaisenkinds um Euren Schützling zu rufen, um den Ihr Euch während der Kinderwoche kümmern werdet."}}
D[10944] = {"Das gefährdete Geheimnis",{"Reist zum Kerker des Wächters im Schattenmondtal und sprecht mit Akama."}}
D[10945] = {"Hch'uu und das Pilzvolk",{"Bringt Euer Waisenkind Salandria nach Sporeggar in den Zangarmarschen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt. Sprecht danach mit Hch'uu."}}
D[10946] = {"Die List der Aschenzungen",{"Reist in die Festung der Stürme und tötet Al'ar, während Ihr die Gugel der Aschenzungen tragt. Kehrt nach Abschluss der Aufgabe zu Akama ins Schattenmondtal zurück."}}
D[10947] = {"Ein Artefakt aus der Vergangenheit",{"Reist zu den Höhlen der Zeit in Tanaris und verschafft Euch Zugang zur Schlacht um den Berg Hyjal. Habt Ihr dies geschafft, so bezwingt Furor Winterfrost und bringt das zeitverzerrte Phylakterium zu Akama im Schattenmondtal."}}
D[10948] = {"Die Seelengeisel",{"Reist nach Shattrath und erzählt A'dal von Akamas Bitte."}}
D[10949] = {"Zutritt zum Schwarzen Tempel",{"Reist zum Eingang des Schwarzen Tempels im Schattenmondtal und sprecht mit Xi'ri."}}
D[10950] = {"Auchindoun und der Ring der Beobachtung",{"Bringt Euer Waisenkind Dornaa zum Versammlungsstein beim Ring der Beobachtung in der Mitte von Auchindoun. Auchindoun liegt inmitten der Knochenwüste der Wälder von Terokkar. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt."}}
D[10951] = {"Eine Reise zum Dunklen Portal",{"Geht mit Eurem Waisenkind Salandria die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt."}}
D[10952] = {"Eine Reise zum Dunklen Portal",{"Geht mit Eurem Waisenkind Dornaa die Stufen des Schicksals hinauf und besucht das Dunkle Portal auf der Höllenfeuerhalbinsel. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt."}}
D[10953] = {"Besuch beim Thron der Elemente",{"Bringt Euer Waisenkind Salandria zum Thron der Elemente in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Elementarist Sharvak."}}
D[10954] = {"Jheel ist beim Aerissteg!",{"Bringt Euer Waisenkind Dornaa zum Aerissteg in Nagrand. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt. Sprecht dann mit Jheel."}}
D[10955] = {"Morthis Flügelraunen",{"Sucht nach Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen."}}
D[10956] = {"Der Sitz der Naaru",{"Bringt Euren Schützling Dornaa zu O'ros im unteren Teil des Sitzes der Naaru in der Exodar auf der Azurmythosinsel. Ruft sie herbei, falls sie nicht bei Euch sein sollte, wenn Ihr dort ankommt.","","Vergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt."}}
D[10957] = {"Die Erlösung der Aschenzungen",{"Helft Akama die Kontrolle über seine Seele wieder zu erlangen, indem Ihr Akamas Schemen im Schwarzen Tempel besiegt. Kehrt anschließend zu Seher Kanai zurück."}}
D[10958] = {"Sucht die Aschenzungen auf",{"Sucht Akamas Todeshörige im Schwarzen Tempel."}}
D[10959] = {"Der Sturz des Verräters",{"Seher Kanai möchte, dass Ihr Illidan im Schwarzen Tempel besiegt."}}
D[10960] = {"Wenn ich groß bin...",{"Bringt Euren Schützling Salandria zu den Paladinlehrern auf dem Platz der Weltenwanderer in Silbermond. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt. Sprecht danach mit Lady Liadrin, der Matriarchin der Blutritter.","","Vergesst nicht, dass Ihr in der Stadt Eure Karte verwenden und die Wachen nach den Paladinlehrern fragen könnt."}}
D[10961] = {"Der Zauber des Erwachens",{"Bringt 10 Sumpfblüten, 10 Urflechten und 10 Traumwinden zu Morthis Flügelraunen in der Zuflucht des Cenarius."}}
D[10962] = {"Zeit die Höhlen zu besuchen",{"Bringt Euren Schützling Dornaa zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.","","Erwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels."}}
D[10963] = {"Zeit die Höhlen zu besuchen",{"Bringt Euren Schützling Salandria zu Zaladormu, dem Drachen auf der Anhöhe in den Höhlen der Zeit. Ruft sie zu Euch, falls sie nicht anwesend ist, wenn Ihr ankommt.","","Erwerbt danach für sie einen Spielzeugdrachen bei Alurmi, dem Rüstmeister der Hüter der Zeit, in der Nähe des Endes des Eingangstunnels."}}
D[10964] = {"Den Schläfer wecken",{"Benutzt den Zauber des Erwachens um Clintar Traumwandler aus dem Smaragdgrünen Traum zu holen. Sprecht mit ihm, sobald er zu sich kommt."}}
D[10965] = {"Mehr als ein Traum",{"Beschützt Clintar Traumwandlers Geist während er die Relikte von Aviana sammelt. Sprecht danach mit Traumwächter Lurosa."}}
D[10966] = {"Zurück zum Waisenhaus",{"Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im Unteren Viertel."}}
D[10967] = {"Zurück zum Waisenhaus",{"Kehrt zum Waisenhaus in Shattrath zurück und übergebt die Pfeife Eures Schützlings an Waisenmatrone Gnädig im Unteren Viertel."}}
D[10968] = {"Besucht den Scharfseher",{"Bringt Euren Schützling Dornaa zu Scharfseher Nobundo in der Kristallhalle der Exodar auf der Azurmythosinsel. Ruft sie zu Euch, falls sie nicht anwesend sein sollte, wenn Ihr ankommt.","","Vergesst nicht, dass Ihr in der Stadt Eure Karte verwenden könnt."}}
D[10969] = {"Sucht Ameer!",{"Sucht Kommandant Ameer beim Wachposten des Protektorats auf."}}
D[10970] = {"Ein barmherziger Auftrag",{"Beschafft Euch den sichergestellten Gefängnisschlüssel des Astraleums und bringt ihn zu Kommandant Ameer beim Wachposten des Protektorats im Nethersturm."}}
D[10971] = {"Geheimnisse des Astraleums",{"Kommandant Ameer beim Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm eine Identifizierungsmarke eines Gefangenen des Astraleums bringt."}}
D[10972] = {"Katalog der Gefangenen des Astraleums",{"Ich brauche mehr Identifikationsmarken, <Name>. Ich konnte bisher herausfinden, dass sie nicht nur die Gefangenen katalogisieren, sondern auch Aussagen über ihre Aufenthaltsorte machen!","","Sobald wir diesen Code entschlüsselt haben, können wir genau feststellen, wo unsere Verbündeten festgehalten werden und sie mit minimalem Gewalteinsatz befreien."}}
D[10973] = {"Tausend Welten",{"Kommandant Ameer am Wachposten des Protektorats im Nethersturm möchte, dass Ihr ihm 5 Gefängnisschlüssel des Astraleums bringt."}}
D[10974] = {"Stasiskammern von Bash'ir",{"Benutzt die Schlüsseltafel des Astraleums – Alpha, um die Stasiskammer Alpha im Landeplatz von Bash'ir im Schergrat zu öffnen.","","Bringt Beweisstücke aus Alpha zum Bild von Kommandant Ameer beim Landeplatz von Bash'ir."}}
D[10975] = {"Die Reinigung der Kammern von Bash'ir",{"Wir sitzen in der Sackgasse, <Name>. Die Daten, die Ihr gesammelt habt, haben uns genügend Informationen geliefert, um unsere Verbündeten aus den kleineren Gefängnissen des Nethersturms retten zu können. Wir müssen uns jedoch dringend um die Bedrohung kümmern, die von den Kammern hier im Ladeplatz von Bash'ir ausgeht.","","Schließt Euch dem Kampf gegen das Astraleum an! Bringt mir die Gefängnisschlüssel des Astraleums, damit ich Stasiskammerschlüssel für die Stasiskammern von Bash'ir für Euch herstellen kann."}}
D[10976] = {"Das Abzeichen des Nexuskönigs",{"Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr ihm ein Abzeichen des Nexuskönigs bringt."}}
D[10977] = {"Stasiskammern der Managruft",{"Das Bild von Kommandant Ameer beim Landeplatz von Bash'ir im Schergrat möchte, dass Ihr den Stasiskammerschlüssel der Managruft verwendet, um die Stasiskammer in der Managruft Auchindouns zu öffnen.","","Diese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[10978] = {"Rückkehr zu Morthis Flügelraunen",{"Bringt die Relikte von Aviana zu Morthis Flügelraunen in der Zuflucht des Cenarius in den Zangarmarschen."}}
D[10979] = {"Zum Ewigen Hain",{"Sprecht mit Arthorn Windweise im Ewigen Hain im Schergrat."}}
D[10980] = {"Das Buch des Raben",{"Benutzt das Auge eines Ätherrochen in Verbindung mit Eurem Stein des Sehers, um die Geister des Rabenkultes sehen zu können. Sucht beim Vortexgipfel nach dem Geist von Sai'kkal dem Ältesten und fragt ihn über das 'Buch des Raben' aus. Kehrt danach zu Arthorn Windweise zurück."}}
D[10981] = {"Nexusprinz Shaffars persönliche Kammer"}
D[10982] = {"Das Auge des Haramad",{"Ihr habt viel für das Protektorat und das Konsortium getan, <Name>. Daher ist es nur gerecht, dass einer unserer neuen Schlüssel an Euch geht. Mit diesem Schlüssel könnt Ihr Shaffars persönliche Stasiskammer jederzeit öffnen, ohne den Schlüssel dabei zu zerstören.","","Er ist von Dauer und wird auf ewig Euch gehören."}}
D[10983] = {"Mog'dorg der Weise",{"Besucht Mog'dorg den Weisen auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat."}}
D[10984] = {"Sprecht mit dem Oger",{"Sprecht mit dem Oger Grok im unteren Viertel von Shattrath."}}
D[10985] = {"Ein Ablenkungsmanöver für Akama",{"Stellt sicher, dass Akama und Maiev den Schwarzen Tempel betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben."}}
D[10986] = {"Blick zum Himmel",{"Sprecht mit Behüterin Elaira bei der Zwielichthöhe in Nagrand."}}
D[10987] = {"Der Spatz in der Hand",{"Benutzt das Sperbernetz um einen wilden Sperber zu fangen und bringt ihn zu Behüterin Elaira auf der Zwielichthöhe."}}
D[10988] = {"Die Rabensteine",{"Sammelt 8 Rabensteine in Skettis und bringt sie zu Arthorn Windweise im Ewigen Hain im Schergrat."}}
D[10989] = {"Mog'dorg der Weise",{"Besucht Mog'dorg den Weisen auf der Spitze des Turms außerhalb des Zirkels des Blutes im Schergrat, bei dem Chort sich aufhält."}}
D[10990] = {"Die Essenz des Adlers",{"Besiegt den Wächter des Adlers und erlangt die Essenz des Adlers. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.","","Wenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im Ewigen Hain auf."}}
D[10991] = {"Die Essenz des Falken",{"Besiegt den Wächter des Falken und erlangt die Essenz des Falken. Benutzt Arthorns Sperberpfeife, um Arthorns Sperber zu rufen, damit dieser die Kunde von Eurem Erfolg übermittelt.","","Wenn Ihr die Pfeife verloren habt und Ersatz benötigt, sucht Arthorn Windweise im Ewigen Hain auf."}}
D[10992] = {"Die Essenz des Habichts",{"Besiegt den Wächter des Habichts und bringt die Essenz des Habichts zu Arthorn Windweise im Ewigen Hain."}}
D[10993] = {"Rückkehr zur Zuflucht des Cenarius",{"Bringt Arthorns Päckchen zu Morthis Flügelraunen in der Zuflucht des Cenarius."}}
D[10994] = {"Auf der Jagd nach dem Mondstein",{"Bringt einen Mondstein des Südstroms zu Morthis Flügelraunen in der Zuflucht des Cenarius."}}
D[10995] = {"Grulloc hat zwei Schädel",{"Beschafft Grullocs Drachenschädel und bringt ihn zu Mog'dorg dem Weisen auf dem Turm beim Zirkel des Blutes im Schergrat."}}
D[10996] = {"Maggocs Schatztruhe",{"Beschafft Euch Maggocs Schatztruhe und bringt sie zu Mog'dorg dem Weisen auf dem Turm beim Zirkel des Blutes im Schergrat."}}
D[10997] = {"Sogar ein Gronn hat Standards",{"Besorgt Euch Slaags Standarte und bringt sie zu Mog'dorg dem Weisen auf dem Turm beim Zirkel des Blutes im Schergrat."}}
D[10998] = {"In den übelsten Kreisen",{"Ihr müsst Vim'gols üblen Zauberfolianten beschafften. Bringt ihn zu Mog'dorg dem Weisen auf dem Turm beim Zirkel des Blutes im Schergrat."}}
D[11000] = {"Schänder der Seelen",{"Beschafft Euch Skullocs Seele und bringt ihn zu Mog'dorg dem Weisen auf dem Turm beim Zirkel des Blutes im Schergrat."}}
D[11001] = {"Vernichtet den Rabengott",{"Tötet den Rabengott und kehrt dann zu Morthis Flügelraunen bei der Zuflucht des Cenarius zurück.","","Diese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11002] = {"Magtheridons Untergang",{"Bringt Magtheridons Kopf zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück."}}
D[11003] = {"Magtheridons Untergang",{"Bringt Magtheridons Kopf zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."}}
D[11004] = {"Schattenwelt",{"Severin möchte, dass Ihr nach Skettis reist und 6 Einheiten Schattenstaub von den dort lebenden Arakkoa sammelt."}}
D[11005] = {"Die Geheimnisse der Krallenpriester",{"Beschafft Euch von Severin ein Elixier der Schatten und verwendet es, um Krallenpriester Ishaal, Krallenpriester Skizzik und Krallenpriester Zellek in Skettis ausfindig zu machen und sie zu töten. Kehrt nach Abschluss Eurer Aufgabe zu Kommandant Adaris zurück."}}
D[11006] = {"Mehr Schattenstaub",{"Der Kommandant scheint doch nicht aus einem Fieberwahn heraus gesprochen zu haben. Bringt mir mehr Staub und ich werde ein weiteres Elixier für Euch herstellen."}}
D[11007] = {"Kael'thas und die tiefgrüne Sphäre",{"Bringt die tiefgrüne Sphäre zu A'dal in Shattrath."}}
D[11008] = {"Feuer über Skettis",{"Haltet nach monströsen Kalirieiern oben in den Siedlungen von Skettis Ausschau und benutzt die Sprengladungen der Himmelswache, um sie in die Luft zu sprengen. Kehrt danach zu Himmelsoffizier Doryn zurück."}}
D[11009] = {"Ogerhimmel",{"Mog'dorg der Weise hat Euch gebeten, mit Chu'a'lor in Ogri'la im Schergrat zu sprechen."}}
D[11010] = {"Bomberangriff",{"Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln."}}
D[11011] = {"Ewige Wachsamkeit",{"Sprecht mit Morthis Flügelraunen, um einen mit Essenz erfüllten Mondstein zu erhalten."}}
D[11012] = {"Der Blutschwur der Netherschwingen",{"Unser Land ist verloren. Man entführt unsere Kinder in der Nacht, versklavt sie... oder schlimmer...","","<Mordenais Stimme wirkt angespannt.>","","Es ist an der Zeit, mein Freund. Zeit, uns zurückzuholen, was einst unser war! Ihr habt Euch als tapferer Kämpfer und verständnisvolle Seele erwiesen.","","Werdet Ihr schwören, dem Drachenschwarm der Netherschwingen beim Kampf um unser Land und dem Wiederaufbau unserer Heimstätten zu helfen? Werdet Ihr schwören, über den Schwarm zu wachen, damit unser Fleisch und Blut aufs Neue zum Leben erwachen kann? Schwört und lasst uns im Namen unserer Heimat und unserer Familien kämpfen!"}}
D[11013] = {"Im Dienste der Illidari",{"Reist zur Netherschwingenscherbe und überreicht Oberanführer Mor'ghor beim Basislager des Drachenmals das Empfehlungsschreiben der Illidari."}}
D[11014] = {"In der Höhle des Löwen",{"Sprecht mit Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals."}}
D[11015] = {"Kristalle der Netherschwingen",{"Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 30 Kristalle der Netherschwingen bringt."}}
D[11016] = {"Balg eines Netherminenschinders",{"Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 35 Bälge eines Netherminenschinders bringt."}}
D[11017] = {"Netherstaubpollen",{"Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Netherstaubpollen bringt."}}
D[11018] = {"Netheriterz",{"Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Einheiten Netheriterz bringt."}}
D[11019] = {"Freund unter Feinden",{"Ihr habt doch nicht etwa geglaubt, dass wir Euch den Armeen der Höllenorcs ganz alleine überlassen würden, oder?","","<Yarzills Augen flackern in einem durchscheinenden Blau.>","","Genau, wir sind hier an Eurer Seite, <Name>. Bei jedem Dienst, den Ihr den Höllenorcs bei Eurem Versuch, die Weiten der Netherschwingen zurückzuerobern, erweist, werden wir dafür sorgen, dass sie einen ausreichenden Rückschlag erleiden.","","Ihr müsst Euch sehr unauffällig verhalten, um keinerlei Aufmerksamkeit während Euren Sabotageeinsätzen auf Euch zu ziehen."}}
D[11020] = {"Ein langsamer Tod",{"Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr Yarzills Hammel zusammen mit den Teufelsdrüsen verwendet, um 12 Peonlager des Drachenmals zu vergiften."}}
D[11021] = {"Ishaals Almanach",{"Bringt Ishaals Almanach zu Himmelskommandant Adaris im Norden von Skettis."}}
D[11022] = {"Sprecht mit Mog'dorg",{"Sprecht mit Mog'dorg dem Weisen. Er steht oben auf dem Turm auf der Ostseite des Zirkels des Blutes im Schergrat."}}
D[11023] = {"Und wieder ein Bombenangriff!",{"Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln."}}
D[11024] = {"Ein Verbündeter im Unteren Viertel",{"Bringt Ishaals Almanach zu Rilak dem Erlösten im Unteren Viertel in Shattrath."}}
D[11025] = {"Die Kristalle",{"Chu'a'lor möchte, dass Ihr 5 Apexissplitter einsammelt. Bringt sie zu ihm in Ogri'la hoch oben im Schergrat."}}
D[11026] = {"Bannt die Dämonen",{"Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen."}}
D[11027] = {"Habt Ihr die Rune der Dunkelheit?"}
D[11028] = {"Countdown des Schicksals",{"Kehrt zu Himmelskommandant Adaris ins Schattenwindlager in den Wäldern von Terokkar zurück und erzählt ihm die Neuigkeiten über Terokks Rückkehr."}}
D[11029] = {"Eine schäbige Verkleidung",{"Verwendet die schäbige Arakkoaverkleidung, um den Stammbaum der Feinde von Sahakk zu beschaffen. Kehrt anschließend zu Hazzik zurück."}}
D[11030] = {"Unser Junge möchte der Himmelswache beitreten",{"Beschafft ein instabiles Fläschchen der Bestie."}}
D[11031] = {"Nicht mehr Erzmagier"}
D[11032] = {"Nicht mehr Beschützer"}
D[11033] = {"Nicht mehr Assassine"}
D[11034] = {"Nicht mehr Bewahrer",{"Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.","","Es wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben."}}
D[11035] = {"Ein Schatten am Horizont",{"Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 10 Relikte der Netherschwingen sicherstellt."}}
D[11036] = {"Außerirdische Früchte!",{"Bringt die konservierten Früchte zu Raketenchef Doppeldecker in Area 52."}}
D[11037] = {"Eine seltsame Vision",{"Sprecht mit Raketenchef Doppeldecker in Area 52."}}
D[11038] = {"Unterstützung für Exarch Orelis",{"Sprecht mit Exarch Orelis in Area 52."}}
D[11039] = {"Meldung bei Spionagemeister Thalodien",{"Meldet Euch bei Spionagemeister Thalodien in Area 52."}}
D[11040] = {"Ersatzteile für den Raketenchef",{"Bringt Bossis Ersatzteile zu Raketenchef Doppeldecker in Area 52."}}
D[11041] = {"Eine unerledigte Aufgabe...",{"Tötet 10 Felslandschinder und Barash die Höhlenmutter. Kehrt nach erfolgreicher Erledigung zu Oberanführer Mor'ghor beim Basislager des Drachenmals zurück."}}
D[11042] = {"Eine verblüffende Vision",{"Sprecht mit Raketenchef Doppeldecker in Area 52."}}
D[11043] = {"Ein besserer Greif",{"Sprecht mit Brunn Flammenbart in der Wildhammerfeste."}}
D[11044] = {"Visionen voller Zerstörung",{"Sprecht mit Schwadronskommandant Nuainn in der Wildhammerfeste."}}
D[11045] = {"Zorus der Richter",{"Sprecht mit Zorus dem Richter in der Wildhammerfeste."}}
D[11046] = {"Chefapothekerin Hildagard",{"Sprecht mit Chefapothekerin Hildagard in Schattenmond."}}
D[11047] = {"Die Bitte des Gesellen",{"Sprecht mit Dama Wildmähne im Dorf Schattenmond."}}
D[11048] = {"Kroghans Bericht",{"Sprecht mit Blutwache Gulmok im Dorf Schattenmond."}}
D[11049] = {"Die große Eierjagd",{"Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ein Ei der Netherschwingen einsammelt."}}
D[11050] = {"Immer her mit den Eiern",{"Diese Eier dürfen auf keinen Fall in die falschen Hände geraten, <Name>. Wenn Ihr noch mehr Eier findet, bringt sie mir.","","Verhaltet Euch auf jeden Fall unauffällig und erregt bloß keinen Verdacht!"}}
D[11051] = {"Bannt mehr Dämonen",{"Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen."}}
D[11052] = {"Akamas Versprechen",{"Bringt das Medaillon von Karabor zu A'dal in Shattrath."}}
D[11053] = {"Erhebt Euch, Aufseher!",{"Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal."}}
D[11054] = {"Aufsehen und Ihr: Die richtige Wahl treffen",{"Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 10 Einheiten Knotenhautleder und 1 gehärteten Balg von Tyrantus bringt."}}
D[11055] = {"Der Schuhmerang: Das Mittel gegen den wertlosen Peon",{"Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 faule Peons des Drachenmals zur Ordnung ruft. Gebt anschließend auch Euren Schuhmerang wieder zurück."}}
D[11056] = {"Hazziks Handel",{"Sucht nach Hazziks Päckchen bei seiner Behausung im östlichen Skettis und kehrt damit zu ihm zurück."}}
D[11057] = {"Schwierigkeiten in der Tiefe",{"Sprecht mit Mog'dorg dem Weisen. Ihr findet ihn auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat."}}
D[11058] = {"Ein Apexisrelikt",{"Erlangt Apexisschwingungen von einem Apexisrelikt."}}
D[11059] = {"Wächter des Monuments",{"Beschafft den Kopf eines Apexiswächters."}}
D[11060] = {"Eine kristallgeschmiedete Rune der Dunkelheit"}
D[11061] = {"Die Pflichten eines Vaters",{"Beschafft ihm ein instabiles Fläschchen des Zauberers."}}
D[11062] = {"Der Außenposten der Himmelswache",{"Sprecht mit Himmelskommandant Keller beim Außenposten der Himmelswache im Schergrat."}}
D[11063] = {"Sich Flügel verdienen...",{"Ihr möchtet also zu den Himmelsteilern gehören, ja? Ihr habt Euch mit Sicherheit als fähiger Anhänger des Drachenmals bewiesen, aber in den Lüften der Scherbenwelt ist dies bedeutungslos. Es gibt eine Frage zu klären: KÖNNT IHR FLIEGEN?","","Und ich frage nicht etwa, ob Ihr auf einen Netherdrachen steigen und wie diese Transportertrottel eine Ladung Kristalle zu der Festung liefern könnt. Ich rede davon, der Beste zu sein... der Toporc...","","Dort drüben im Westen gibt es sechs Reiter. Besiegt sie alle und ich werde Euch Flügel der Himmelsteiler geben."}}
D[11064] = {"Drachenmalrennen: Murg \"Grufti\" Moorbiss",{"Folgt Murg \"Grufti\" Moorbiss und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Murg \"Grufti\" Moorbiss besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg."}}
D[11065] = {"Bändigt ein paar Ätherrochen!",{"Bändigt mithilfe des Bändigungsseils 5 Ätherrochen."}}
D[11066] = {"Bändigt noch mehr Ätherrochen!",{"Bändigt mithilfe des Bändigungsseils 5 Ätherrochen."}}
D[11067] = {"Drachenmalrennen: Trope der Rußhuster",{"Folgt Trope dem Rußhuster und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Trope den Rußhuster besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg."}}
D[11068] = {"Drachenmalrennen: Corlok der Veteran",{"Folgt Corlok dem Veteranen und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Corlok den Veteranen besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg."}}
D[11069] = {"Drachenmalrennen: Schwadronskommandant Ichman",{"Folgt Schwadronskommandant Ichman und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Ichman besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg."}}
D[11070] = {"Drachenmalrennen: Schwadronskommandant Mulverick",{"Folgt Schwadronskommandant Mulverick und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Mulverick besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg."}}
D[11071] = {"Drachenmalrennen: Hauptmann Himmelsdonner",{"Folgt Hauptmann Himmelsdonner und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Hauptmann Himmelsdonner besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg."}}
D[11072] = {"Feindesblut",{"Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück."}}
D[11073] = {"Terokks Fall",{"Bringt die Zeitverlorene Opfergabe, die Hazzik angefertigt hat, zu dem Schädelhaufen im Zentrum von Skettis. Beschwört Terokk und bezwingt ihn. Habt Ihr Eure Aufgabe erfüllt, kehrt zu Himmelskommandant Adaris zurück."}}
D[11074] = {"Zeichen der Nachfahren",{"Sammelt zeitverlorene Schriftrollen von den zeitverlorenen Arakkoa in Skettis ein und bringt sie zu den Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört und bezwingt die Nachfahren der Gegner Terokks und kehrt zu Hakkiz mit Akkarais Kralle, Garokks Stachel, Vekkaz' Schuppe und Gezzaraks Klaue zurück."}}
D[11075] = {"Die Netherschwingenminen",{"Sucht die Herrin der Minen auf der Netherschwingenscherbe auf."}}
D[11076] = {"Die Dinge in den Griff bekommen...",{"Die Herrin der Minen bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Kisten mit Fracht der Netherminen einsammelt."}}
D[11077] = {"Drachen sind unsere geringste Sorge",{"Der Vorarbeiter des Drachenmals bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Netherminenschinder und 5 Netherminenhetzer tötet."}}
D[11078] = {"Den Himmel beherrschen",{"Beschafft Euch Drachenzähne."}}
D[11079] = {"Eine Teufelspeitsche für Gahk",{"Beschafft Euch eine Teufelspeitsche."}}
D[11080] = {"Die Strahlung des Relikts",{"Erlangt Apexisstrahlung von einem Apexisrelikt."}}
D[11081] = {"Der große Aufstand der Finsterblut",{"Bringt die Fluchtpläne der Finsterblut zur Herrin der Minen."}}
D[11082] = {"Suche nach der Wahrheit",{"Findet einen Aufpasser der Finsterblut und verhört ihn. Kehrt mit den Informationen der Finsterblut und mit der Hand des Aufpassers zur Herrin der Minen zurück."}}
D[11083] = {"Verrückt und verwirrt",{"Ronag der Sklaventreiber in den Netherschwingenminen im Schattenmondtal möchte, dass Ihr den verrückten Vorarbeiter der Finsterblut und 5 verrückte Minenarbeiter der Finsterblut tötet."}}
D[11084] = {"Seid gegrüßt, Hauptmann!",{"Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal."}}
D[11085] = {"Flucht aus Skettis",{"Begleitet die gefangene Himmelswache in Sicherheit und meldet Euch anschließend bei Himmelsoffizier Doryn."}}
D[11086] = {"Schwächt das Portal des Zwielichts",{"Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 Agenten der Todesschatten tötet."}}
D[11089] = {"Die Seelenkanone Reth'hedrons",{"Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 2 Teufelsstahlbarren, 1 Adamantitrahmen, 1 Khoriumkraftkern und 1 makellose arkane Essenz bringt."}}
D[11090] = {"Unterdrückt den Unterdrücker",{"Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal hat Euch den Auftrag gegeben, die Seelenkanone auf Reth'hedron den Unterdrücker in Nagrand anzuwenden.","","Bringt auch die Seelenkanone wieder zurück."}}
D[11091] = {"Ein besonderer Dank an Euch",{"Sprecht mit Jho'nass in Ogri'la im Schergrat."}}
D[11092] = {"Glück auf, Kommandant!",{"Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal."}}
D[11093] = {"Hungrige Netherrochen",{"Benutzt den Netherrochenkäfig in den Wäldern südlich des Schattenwindlagers und erlegt in der Nähe des hungrigen Netherrochens einige Schattenwindhetzer. Kehrt anschließend zu Deesak dem Tierführer der Himmelswache zurück."}}
D[11094] = {"Tötet sie alle!",{"Überbringt Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals."}}
D[11095] = {"Kommandant Hobb",{"Bringt die Leuchtpistole des Drachenmals zu Kommandant Hobb beim Sanktum der Sterne im Schattenmondtal."}}
D[11096] = {"Bedrohung von oben",{"Tötet bei der Hügelwand 20 Oger der Gordunni und kehrt anschließend zu Yuula in Shattrath zurück."}}
D[11097] = {"Die tödlichste Falle aller Zeiten",{"Helft Kommandant Hobb und den Sehern bei der Verteidigung des Sanktums der Sterne. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Seher zurück."}}
D[11098] = {"Nach Skettis!",{"Bringt das Paket mit Sprengladungen zu Himmelsoffizier Doryn beim Schattenwindlager außerhalb von Skettis."}}
D[11099] = {"Tötet sie alle!",{"Überbringt Anachoretin Ceyla beim Altar der Sha'tar die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals."}}
D[11100] = {"Kommandant Arcus",{"Bringt die Leuchtpistole des Drachenmals zu Kommandant Arcus beim Altar der Sha'tar im Schattenmondtal."}}
D[11101] = {"Die tödlichste Falle aller Zeiten",{"Helft Kommandant Arcus und den Aldor bei der Verteidigung des Altars der Sha'tar. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Aldor zurück."}}
D[11102] = {"Bomberangriff",{"Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln."}}
D[11103] = {"Nicht mehr Weise",{"Man kann die Kräfte Eures Ringes neu formen, doch wird es nicht einfach, Eure Auswahl rückgängig zu machen. Seid Ihr sicher, dass Ihr seine momentane Form durch eine andere ersetzen möchtet?"}}
D[11104] = {"Nicht mehr Bewahrer"}
D[11105] = {"Nicht mehr Held"}
D[11106] = {"Nicht mehr Verteidiger"}
D[11107] = {"Verneigt Euch vor dem Hochlord",{"Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal."}}
D[11108] = {"Fürst Illidan Sturmgrimm",{"Trefft Euch mit Illidan Sturmgrimm. Solltet Ihr überleben, sucht Barthamus im Unteren Viertel von Shattrath auf."}}
D[11109] = {"Jorus, der kobaltblaue Drache der Netherschwingen",{"Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.","","Wenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.","","Ihr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern."}}
D[11110] = {"Malfas, der lila Drache der Netherschwingen"}
D[11111] = {"Onyxien, der onyxfarbene Drache der Netherschwingen",{"Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.","","Wenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.","","Ihr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern."}}
D[11112] = {"Suraku, der azurblaue Drache der Netherschwingen"}
D[11113] = {"Voranaku, der violette Drache der Netherschwingen"}
D[11114] = {"Zoya, der viridiangrüne Drache der Netherschwingen",{"Es ist eine Ehre, Euch zu treffen, <Name>. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.","","Wenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.","","Ihr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern."}}
D[11117] = {"Fangt die wilden Wolpertinger!",{"Goldark Spatzenjäger möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr einen ordentlichen Rausch braucht, um die Biester sehen zu können."}}
D[11118] = {"Parade der rosa Elekks",{"Reist zu den Biergärten außerhalb von Sturmwind, Darnassus und der Exodar, zappt an jedem Ort drei Elekks und kehrt anschließend zu Goldark Spatzenjäger zurück. Um die rosa Elekks sehen zu können, müsst Ihr betrunken sein."}}
D[11119] = {"Angriff auf den Landeplatz von Bash'ir!",{"Sprecht mit dem Äthertechnikerlehrling im Außenposten der Himmelswache im Schergrat."}}
D[11120] = {"Parade der rosa Elekks",{"Reist zu den Biergärten außerhalb von Silbermond, Donnerfels und Unterstadt, zappt an jedem Ort drei Elekks und kehrt anschließend zu Glodrak Jägerspatz zurück. Um die rosa Elekks sehen zu können, müsst Ihr betrunken sein."}}
D[11122] = {"Hin und zurück",{"Holt ein Fässchen von Flynn Feuerbräu in Kharanos und bringt es zu Pol Bernruh zurück. Wenn Ihr Euren Widder verliert, könnt Ihr Neill Ramstein nach Ersatz fragen."}}
D[11123] = {"Untersuchung der Ruinen",{"Sprecht mit Inspektor Tarem beim Gasthaus Zur süßen Ruh."}}
D[11124] = {"Untersuchung der Ruinen",{"Sprecht mit Inspektor Tarem beim Gasthaus Zur süßen Ruh."}}
D[11126] = {"Verräter unter uns",{"Konfrontiert 5 Aufwiegler der Deserteure und kehrt zu Calia Hastings nahe der Docks in Theramore zurück."}}
D[11128] = {"Propagandakrieg",{"Bringt das Propagandamaterial der Deserteure zu Calia Hastings nahe der Docks in Theramore."}}
D[11129] = {"Kyle wird vermisst!",{"Ahab Weizhuf beim Dorf der Bluthufe in Mulgore möchte, dass Ihr seinen geliebten Hund Kyle den Wilden füttert.","","Füttert Kyle mit zartem Schreiterfleisch und kehrt anschließend zu Ahab Weizhuf zurück."}}
D[11130] = {"Oh, es glitzert!",{"Gaunah möchte, dass Ihr Gaunahs Notiz zu Budd in den Geisterlanden, direkt außerhalb von Zul'Aman, bringt."}}
D[11131] = {"Löscht das Feuer!",{"Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind."}}
D[11132] = {"Versprechen, Versprechen...",{"Budd Winterhäldler in den Axthügeln möchte, dass Ihr bei Hohepriester Nalorakks Terrasse in Zul'Aman nach seiner Karte sucht."}}
D[11133] = {"Diskreditierung der Deserteure",{"Calia Hastings möchte, dass Ihr verfälschte Handzettel an 6 Wachen von Theramore verteilt. Erstattet ihr anschließend Bericht nahe der Docks in Theramore."}}
D[11134] = {"Das Ende der Deserteure",{"Nehmt Gavis Grauschild gefangen und erstattet anschließend Bericht bei Calia Hastings nahe der Docks in Theramore."}}
D[11135] = {"Der kopflose Reiter",{"Sucht nach dem Kürbisschrein des kopflosen Reiters."}}
D[11136] = {"Beunruhigende Berichte",{"Erstattet Hauptmann Wymor bei der Späherwacht Bericht."}}
D[11137] = {"Defias in den Düstermarschen?",{"Besorgt Euch die Befehle der Defias von Garn Mathers und bringt sie zu Hauptmann Wymor bei der Späherwacht."}}
D[11138] = {"Renn McGill",{"Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe der Schreckensmoorküste."}}
D[11139] = {"Tauchausrüstung aus zweiter Hand",{"Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in den Düstermarschen."}}
D[11140] = {"Bergt die Fracht!",{"Bringt 6 geborgene Geldkassetten zu Renn McGill in den Düstermarschen."}}
D[11141] = {"Jaina muss davon erfahren",{"Sprecht mit Lady Jaina Prachtmeer in Theramore."}}
D[11142] = {"Beobachtet die Insel Alcaz",{"Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten. Sprecht mit Lady Jaina Prachtmeer in Theramore, wenn Ihr die Beobachtung abgeschlossen habt."}}
D[11143] = {"Der entscheidende Grimmweis",{"Erstattet Hauptmann Darill bei der Nordwacht Bericht."}}
D[11144] = {"Bestätigung des Verdachts",{"Bringt die Schlachtpläne der Grimmtotem zu Hauptmann Darill bei der Nordwacht."}}
D[11145] = {"Gefangene der Grimmtotem",{"Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 5 Gefangene von Theramore befreit."}}
D[11146] = {"Raptorenfänger",{"Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 6 Raptoren einfangt. Ihr könnt entweder Blutsumpfraptoren oder Blutsumpfkreischer einfangen."}}
D[11147] = {"Lasst die Raptoren los",{"Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr den Raptorenköder bei der Windmühle im Dorf der Schwarzhufe platziert."}}
D[11148] = {"Waffen der Grimmtotem",{"Hauptmann Darill bei der Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt."}}
D[11149] = {"Tabethas Unterstützung",{"Sprecht mit Tabetha auf ihrem Hof."}}
D[11150] = {"Brennt den Grollhornposten nieder!",{"Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück."}}
D[11151] = {"Gerechtigkeit im Namen der Familie Hyal",{"Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore."}}
D[11152] = {"Endlich Frieden",{"Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt."}}
D[11156] = {"Räuber des Grollhornpostens",{"Tötet 12 Grimmtotem des Grollhornpostens und kehrt zu Lehrling Morlann auf Tabethas Hof zurück."}}
D[11158] = {"Blutsumpffedern",{"Bringt 5 Blutsumpffedern zu Brogg in Morastwinkel."}}
D[11159] = {"Geister der Steinbrecherfeste",{"Brogg in Morastwinkel möchte, dass Ihr 10 Geister der Steinbrecher tötet, um sie so ihrer letzten Ruhe zu überantworten."}}
D[11160] = {"Das Banner der Steinbrecher",{"Beschafft das Banner der Steinbrecher und bringt es Brogg in Morastwinkel."}}
D[11161] = {"Die Essenz der Feindschaft",{"Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel."}}
D[11162] = {"Herausforderung für den schwarzen Drachenschwarm",{"Stellt das Banner der Steinbrecher nahe des Eingangs zu Onyxias Hort auf, wartet auf ihre Reaktion und kehrt anschließend zu Brogg in Morastwinkel zurück."}}
D[11163] = {"Agentin mit Herz",{"Meldet Euch bei Donna Brascoe, um eine Belohnung für Euer Heldentum in Zul'Aman zu erhalten. Donna hält sich momentan in den Geisterlanden, direkt außerhalb von Zul'Aman auf."}}
D[11164] = {"Jäger der verlorenen Hauer",{"Prigmon möchte, dass Ihr 10 Hauer eines Waldtrolls von Trollen in Zul'Aman einsammelt. Bringt sie zu ihm bei Budds Lager in den Geisterlanden."}}
D[11165] = {"Ein Troll unter Trollen",{"Prigmon möchte, dass Ihr seinen Vetter Zungam in Zul'Aman ausfindig macht und ihm zur Seite steht."}}
D[11166] = {"Das X markiert Euren Untergang!",{"Betretet Zul'Aman und erkundet Halazzis Kammer, Jan'alais Plattform und Akil'zons Plattform. Berichtet Budd bei seinem Lager in den Geisterlanden von den Details dieser Bereiche."}}
D[11169] = {"Die Waffe der Grimmtotem",{"Lehrling Garion bei Tabethas Hof möchte, dass Ihr das erbeutete Totem an 10 scheckigen Staubsuhlerkrokilisken oder Staubsuhlerdolchrachen ausprobiert."}}
D[11171] = {"Hexlord? Pah!",{"Budd Winterhäldler in den Axthügeln möchte, dass Ihr Hexlord Malacrass in Zul'Aman tötet."}}
D[11172] = {"Der Zeppelinabsturz",{"Sprecht mit Moxie Stahlgrill bei Beezils Wrack."}}
D[11173] = {"Der Reagenziendieb",{"Bringt 6 Phiolen Marschengift zu Lehrling Garion bei Tabethas Hof."}}
D[11174] = {"Korrosionsschutz",{"Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 10 Brühschlammer auflöst."}}
D[11177] = {"Der Einsiedler beim Irrlichtanwesen",{"Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen."}}
D[11178] = {"Blut des Kriegsherren",{"Bringt Zul'jins Blut zu Budd bei seinem Lager in den Geisterlanden, direkt außerhalb von Zul'Aman."}}
D[11180] = {"Was sucht den Hexenhügel heim?",{"Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr Informationen von 10 auferstandenen Gebeinen oder auferstandenen Geistern sammelt."}}
D[11181] = {"Der Hexenfluch",{"Bringt 9 Zweige Hexenfluch zu Mordant Grimsby beim Irrlichtanwesen."}}
D[11183] = {"Reinigungsritual des Hexenhügels",{"Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr die Fackel am Ende des Docks aufstellt und alles bezwingt, was daraufhin erscheint."}}
D[11184] = {"GESUCHT: Schlächterklaue der Gefräßige",{"Tötet Schlächterklaue den Gefräßigen und meldet Euch anschließend bei Drazzit Tropfhahn in Morastwinkel."}}
D[11185] = {"Brief der Apothekerin",{"Bringt den versiegelten Brief zu Andello Porter auf Tabethas Hof."}}
D[11186] = {"Zeichen des Verrats?",{"Bringt den versiegelten Brief zu Nazeer Blutlanze in Brackenwall."}}
D[11191] = {"Der alte Leuchtturm",{"Sprecht mit Babs Zischeldrill bei dem Leuchtturm auf der Insel östlich von Theramore."}}
D[11192] = {"Drescheröl",{"Bringt 4 Behälter mit Drescheröl zu Babs Zischeldrill beim Leuchtturm in der Nähe von Theramore."}}
D[11193] = {"Heimtückische Bewohner der Tiefe",{"Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore."}}
D[11194] = {"Ist das wahr?",{"Sprecht mit Nat Pagle bei Nats Angelplatz in der Tidenbucht."}}
D[11195] = {"Das Spiel mit der Puppe",{"Bringt die zerlumpte Voodoopuppe zu Gaunah in Shattrath."}}
D[11196] = {"Der Kriegsherr der Amani",{"Besiegt den neuen Kriegsherrn der Amani, Daakara."}}
D[11198] = {"Bezwingt Tethyr!",{"Major Mühlens bei den Docks von Theramore möchte, dass Ihr Tethyr bezwingt."}}
D[11200] = {"Kein bloßer Zufall",{"Krog in Brackenwall möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt."}}
