(function() local D = SUIQuestScopeData.L10n.esES.Quest
D[1] = {"Alexander's Quest",{"Find the forgotten location and cast the magical spell."}}
D[2] = {"La garfa de Garrafilada",{"Llévale la garra de Garrafilada a Senani Truenozón en el Puesto del Hachazo, Vallefresno."}}
D[5] = {"La hambruna de Alterio",{"Habla con el Chef Grual."}}
D[6] = {"La recompensa por Garrick Piesuaves",{"Mata a Garrick Piesuaves y lleva su cabeza al ayudante de alguacil Willem a la Abadía de Villanorte."}}
D[7] = {"La limpieza del campamento kóbold",{"Mata 10 alimañas kóbold y ve a hablar con el alguacil McBride."}}
D[8] = {"Un trato de pícaro",{"Lleva la carta anodina a Claros de Tirisfal y entrégasela a la tabernera Renee."}}
D[9] = {"Campos de la muerte",{"El granjero Saldean quiere que mates 20 vigías de la cosecha."}}
D[10] = {"La redención de Patagolpe",{"Descubre qué le ha ocurrido al perito adjunto Patagolpe y llévalo a él o su equipo de análisis ante el perito jefe Picoflojo, que está en Gadgetzan."}}
D[11] = {"Recompensas por los gnolls Zarparrío",{"Lleva 8 bandas gnoll pintadas al ayudante de alguacil Rainer al Cuartel."}}
