D[338] = {"Las verdes colinas de Tuercespina",{"Reúne las páginas perdidas del manuscrito Las verdes colinas de Tuercespina. Cuando los cuatro capítulos estén completos, llévaselos a Barnil."}}
D[339] = {"Capítulo I",{"Lleva las páginas 1, 4, 6 y 8 de Las verdes colinas de Tuercespina de Decautela a Barnil Jarropetra para completar el capítulo I."}}
D[340] = {"Capítulo II",{"Lleva las páginas 10, 11, 14 y 16 de Las verdes colinas de Tuercespina de Decautela a Barnil Jarropetra para completar el capítulo II."}}
D[341] = {"Capítulo III",{"Lleva las páginas 18, 20, 21 y 24 de Las verdes colinas de Tuercespina de Decautela a Barnil Jarropetra para completar el capítulo III."}}
D[342] = {"Capítulo IV",{"Lleva las páginas 25, 26, y 27 de Las verdes colinas de Tuercespina de Decautela a Barnil Jarropetra para completar el capítulo IV."}}
