D[1948] = {"Objetos de poder",{"Lleva 1 jade y la zarza electrificada a Tabetha en el Marjal Revolcafango."}}
D[1949] = {"Secretos escondidos",{"Habla con Magus Tirth en El Desierto de Sal."}}
D[1950] = {"Santo y seña",{"Averigua la frase para la caja fuerte de Tirth y regresa con Tirth."}}
D[1951] = {"Rituales de poder",{"Lleva el libro Rituales de poder a Tabetha en el Marjal Revolcafango."}}
D[1952] = {"Varitas de mago",{"Habla con Tabetha cuando termine su ritual."}}
D[1953] = {"Regreso al pantano",{"Habla con Tabetha."}}
D[1954] = {"El orbe infernal",{"Lleva un orbe infernal a Tabetha en el Marjal Revolcafango."}}
D[1955] = {"El exorcismo",{"Mata al demonio del orbe y habla con Tabetha."}}
D[1956] = {"Poder en Uldaman",{"Hazte con una fuente de poder obsidiano y llévasela a Tabetha en el Marjal Revolcafango."}}
D[1957] = {"Oleadas de maná",{"Mata 12 oleadas de maná dentro del tiempo permitido."}}
D[1958] = {"Poder celestial"}
D[1959] = {"Preséntate ante Anastasia",{"Habla con Anastasia Pozovenado."}}
D[1960] = {"Investiga la tienda de alquimia",{"Detrás de Anastasia Pozovenado encontrarás un Canto de manifestación y un cofre de arcas de contención. Cógelos y lleva 3 arcas de contención llenas, el cofre de arcas de contención y el canto de manifestación a Anastasia en Entrañas."}}
D[1961] = {"Recolección de materiales",{"Consigue 10 trozos de paño de lino y 6 gemas de maná de Dalaran para Josef Gregorian."}}
D[1962] = {"Toga fuego de hechizo",{"Aquí tienes tu toga, <nombre>. Utilízala bien."}}
D[1963] = {"Mano Destrozada",{"Mata a Tazan y llévale su cartera a Therzok al Circo de las Sombras, en Orgrimmar."}}
D[1978] = {"Los Mortacechadores",{"Entrégale el libro de contabilidad de Andron a Varimathras, que está en la Cámara de la Dama Oscura en Entrañas."}}
D[1998] = {"Fenwick Thatros",{"Mata a Fenwick Thatros y llévale su cabeza a Mennet Carkad, que está en el Barrio de los Pícaros de Entrañas."}}
D[1999] = {"Herramientas de comercio",{"Encuentra el informe de estado de Dalaran y devuélveselo a Mennet Carkad, que está en el Barrio de los Pícaros de Entrañas."}}
D[2000] = {"Rokar Filosombra",{"Habla con Rokar Filosombra en Durotar."}}
D[2018] = {"La prueba de Rokar",{"Mata al vigía Glibby y llévale su silbato a Rokar Filosombra a Durotar."}}
D[2019] = {"Herramientas de comercio",{"Habla con Therzok en el Circo de las Sombras de Orgrimmar."}}
D[2038] = {"Suministros de Bingles",{"Localiza las herramientas de Bingles y devuélveselas:","","llave inglesa, destornillador, martillo y cartucho."}}
D[2039] = {"Encuentra a Bingles",{"Encuentra a Bingles Pimpampum en Loch Modan."}}
D[2040] = {"Asalto subterráneo",{"Recupera la dentrituradora goblin de Las Minas de la Muerte y devuélvesela a Shoni la Shilenshiosha en Ventormenta."}}
D[2041] = {"Habla con Shoni",{"Habla con Shoni la Shilenshiosha en Ventormenta."}}
D[2078] = {"La venganza de Gyromast",{"Encuentra el Trillomajareitor 4100, el contramaestre de Gelkak, y condúcelo hasta él."}}
D[2098] = {"La búsqueda de Gyromast",{"Encuentra los tres fragmentos de la llave de Gelkak Gyromast y llévaselas."}}
D[2118] = {"Tierras apestadas",{"Captura un Oso Cardo rabioso vivo y llévaselo a Tharnariun","","Si no consigues capturar un Oso Cardo rabioso y pierdes la trampa, pídele otra a Tharnariun Espinarbolado."}}
D[2138] = {"La limpieza de la infección",{"Libra al bosque de 20 osos Cardo rabiosos y ve a buscar a Tharnariun Espinarbolado a Costa Oscura."}}
D[2139] = {"La esperanza de Tharnariun",{"Encuentra a la madre del cubil y mátala."}}
D[2158] = {"Descanso y relajación",{"Habla con el tabernero Farley de la Posada Orgullo de León."}}
D[2159] = {"Paquete de Dolanaar",{"Llévale el paquete de Dolanaar al tabernero Keldamyr."}}
D[2160] = {"Suministros para Tannok",{"Lleva a Kharanos el cajón de suministros del mesón y entrégaselo a Tannok Martilloescarcha."}}
D[2161] = {"Un cargamento de peón",{"Lleva la carga de Ukor al tabernero Grosk a Cerrotajo."}}
D[2178] = {"Guiso de zancudo",{"Llévale 5 piezas de carne de zancudo a Alanndarian Arrullanoche a Auberdine."}}
D[2198] = {"El collar hecho añicos",{"Busca al creador del collar hecho añicos y descubre para qué sirve."}}
D[2199] = {"Esa información tiene un precio",{"Lleva 5 lingotes de plata a Talvash del Kissel a Forjaz."}}
D[2200] = {"El regreso a Uldaman",{"Busca pistas sobre el paradero del collar de Talvash en Uldaman. Dijo que un paladín muerto fue su último dueño."}}
D[2201] = {"Encuentra las gemas",{"Encuentra el rubí, el zafiro y el topacio que están desperdigados por Uldaman. Cuando los tengas, contacta con Talvash del Kissel mediante la ampolla de adivinación que él te dio","","A través del diario, sabes que...","*El rubí está escondido en una zona de Forjatiniebla con barricadas.","*El topacio permanece oculto en una urna en una de las zonas de los troggs, cerca de algunos enanos de la Alianza","","*El zafiro obra en poder de Grimlok, el líder de los enanos, según él mismo afirma."}}
D[2202] = {"Componentes de Uldaman",{"Llévale 12 setas magenta a Jarkal Musgofusión en Kargath."}}
D[2203] = {"Componentes de Tierras Inhóspitas II",{"Usa las vasijas de taumaturgia vacías con los dragones guardianes agostados de las Tierras Inhóspitas. Cuando las hayas llenado, llévaselas a Jarkal Musgofusión en Kargath."}}
D[2204] = {"Restaurar el collar",{"Obtén una fuente de energía del constructo más poderoso que encuentres en Uldaman, y entrégasela a Talvash del Kissel en Forjaz."}}
D[2205] = {"Busca el SI: 7",{"Entrega el paquete de Keryn Sylvius al maestro Mathias Shaw que está en el Cuartel de Ventormenta."}}
D[2206] = {"El robo",{"Encuentra al maestro de embarcadero Defias y recupera el calendario de envíos para el maestro Mathias Shaw."}}
D[2218] = {"El camino hacia la salvación",{"Ve a Forjaz y habla con Hulfdan Barbanegra."}}
D[2238] = {"Un simple subterfugio",{"Encuentra a Onin MacHammar cerca de Gnomeregan."}}
D[2239] = {"El informe de Onin",{"Lleva el informe de Onin a Hulfdan a Forjaz."}}
D[2240] = {"La cámara oculta",{"Lee el diario de Baelog, inspecciona la cámara oculta y ve a informar al prospector Pico Tormenta."}}
D[2241] = {"Cuando cae la manzana",{"Llévale la rosa de Jannok a Syurna, que está en Darnassus."}}
D[2242] = {"La llamada del destino",{"Encuentra a Sethir el Ancestro y ve a contarle todo lo que descubras a Syurna."}}
D[2258] = {"Componentes de Tierras Inhóspitas",{"Llévale 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de roca a Jarkal Musgofusión en Kargath, en las Tierras Inhóspitas."}}
D[2259] = {"Erion Sombrusurro",{"Localiza a Erion Sombrusurro en Darnassus."}}
D[2260] = {"La orden de Erion",{"Viaja a la Ciudad de Ventormenta y habla con Renzik \"Renzik \"Chafarote\"."}}
D[2278] = {"Los discos de platino",{"Habla con el vigía de piedra y descubre qué conocimiento antiguo alberga. Cuando hayas adquirido el conocimiento que te ofrece, activa los Discos de Norgannon."}}
D[2279] = {"Los discos de platino",{"Lleva la reproducción en miniatura de los Discos de Norgannon a la Liga de Expedicionarios de Forjaz."}}
D[2280] = {"Los discos de platino",{"Lleva la reproducción en miniatura de los Discos de Norgannon a uno de los sabios de Cima del Trueno."}}
D[2281] = {"Cita en Crestagrana",{"Adéntrate en Villa del Lago, en las Montañas Crestagrana, y habla con Lucius."}}
D[2282] = {"Molino de Alther",{"Abre el arcón de Lucius y llévale la muestra de robo a Villa del Lago."}}
D[2283] = {"La recuperación del collar",{"Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar. Puede que el collar esté estropeado."}}
D[2284] = {"La recuperación del collar, 2ª parte",{"Busca pistas sobre el paradero de las gemas en las profundidades de Uldaman."}}
D[2298] = {"Una regia sacudida",{"Viaja a Ventormenta y busca a Renzik \"Chafarote\"."}}
D[2299] = {"¡Ve a hablar con Hulfdan!",{"Viaja a Forjaz y habla con Hulfdan Barbanegra."}}
D[2300] = {"IV:7",{"Viaja a Ventormenta y busca a Renzik \"Chafarote\"."}}
D[2318] = {"La traducción del diario",{"Encuentra a alguien que pueda traducir el diario del paladín. El lugar más cercano en el que podrás encontrar a alguien es Kargath, en las Tierras Inhóspitas."}}
D[2338] = {"La traducción del diario",{"Préstale el collar a Jarkal. A cambio, te traducirá el diario."}}
D[2339] = {"Encuentra las gemas y la fuente de alimentación",{"Recupera las 3 gemas y una fuente de energía para el collar de Uldaman y llévalo todo a Jarkal Musgofusión en Kargath. Jarkal cree que es posible que la fuente de energía más poderosa se halle en un constructo de Uldaman","","Por el diario sabes...","* Que han ocultado el rubí en una zona cerrada con barricadas en Forjatiniebla.","* Que el topacio se ha ocultado en una urna en un área trogg, cerca de los enanos de la Alianza.","* Que Grimlok, el jefe trogg, se ha quedado con el zafiro."}}
D[2340] = {"Entregar las gemas",{"Entrégale el collar y la gema salvaje a Dran Droffers en Orgrimmar."}}
D[2341] = {"La recuperación del collar, 3ª parte",{"Habla con Jarkal Musgofusión en Kargath."}}
D[2342] = {"Los tesoros reclamados",{"Coge el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas."}}
D[2358] = {"Cuernos de Nez'ra",{"Lleva los Cuernos de Nez'ra a Arantir a Villa del Lago."}}
D[2359] = {"La torre de Klaven",{"Roba la Llave de la Torre Defias, entra en la Torre Defias y descubre qué contiene el Cofre del Bosque del Ocaso. Lleva toda la información que encuentres a Mathias Shaw de Ventormenta. Lee el diario de Kearnen para saber cómo acceder a la torre."}}
D[2360] = {"Mathias y los Defias",{"Ve a Páramos de Poniente y encuentra a la agente Kearnen para dar parte."}}
D[2361] = {"Restaurar el collar"}
D[2378] = {"Encuentra a los Mano Destrozada",{"Viaja a Orgrimmar y habla con Shenthul, que estará en el Circo de las Sombras."}}
D[2379] = {"Zando'zan",{"Habla con Zando'zan en el Circo de las Sombras."}}
D[2380] = {"Ve a Orgrimmar",{"Ve a Orgrimmar, al Circo de las Sombras, y habla con Shenthul."}}
D[2381] = {"Saquear a los saqueadores",{"Llévale el tesoro de los Mares del Sur a Desdio el Desdichado en Trinquete. No olvides conseguir una G.E.A.Q. y herramientas de ladrón del aparato Gizmotrónico de Wrenix. Necesitarás todo eso para completar tu misión","","Si te atacaran unos loros anormalmente agresivos, ¡usa la G.E.A.Q.!"}}
D[2382] = {"Desdio de Trinquete",{"Ve a Trinquete y habla con Desdio el Desdichado."}}
D[2383] = {"Papiro simple",{"Lee el papiro simple y habla con Frang en el Valle de los Retos."}}
D[2398] = {"Los enanos desaparecidos",{"Encuentra a Baelog en Uldaman."}}
D[2399] = {"Flora en brote",{"Las hojas que Denalan plantó en su jardín han retoñado y crecido. Esperan con impaciencia a que alguien las coja..."}}
D[2418] = {"Las piedras de energía",{"Llévale 8 piedras de energía de dentrio y 8 piedras de energía An'Alleum a Aparejez en las Tierras Inhóspitas."}}
D[2438] = {"El cazasueños esmeralda",{"Llévale el cazasueños esmeralda a Tallonkai Cruzarraíz, que está en Dolanaar."}}
D[2439] = {"Los discos de platino",{"Lleva tu vale de recompensa a Dinita Mantopétreo, que está en las Arcas de Forjaz."}}
D[2440] = {"Los discos de platino",{"Llévale este vale de recompensa a Bena Pezuña Invernal, que está en Cima del Trueno."}}
D[2458] = {"Agente encubierto",{"Ve a la torre de Ventura y Cía., al norte de El Fangal, y localiza al capataz Fizzule, el agente de Mano Destrozada","","Cuando veas la torre, usa la pistola de bengalas para avisar de tu llegada al capataz Fizzule. Lanza 2 bengalas y acércate al capataz para darle el /saludo de los Mano Destrozada","","Tienes que hacerlo en este orden, porque Fizzule te matará si no te reconoce."}}
D[2459] = {"Ferocitas el Comesueños",{"Tallonkai Cruzarraíz de Dolanaar quiere que mates a 7 místicos Tuercepinos y encuentres la joya perdida."}}
D[2460] = {"El saludo de los Mano Destrozada",{"Da el saludo de los Mano Destrozada a Shenthul."}}
D[2478] = {"Misión: posible, pero no probable",{"Roba la llave de la torre del supervisor Silixiz, mata a 2 zánganos mutados de Ventura y Cía., 2 patrullas de Ventura y Cía. y 2 oteadores de Ventura y Cía","","Asesina al Gran Supervisor Puzik Gallywix y quédate con su cabeza, fuerza la cerradura del arcón de Gallywix y roba la carretilla de mezcla de Zanzil modificada que allí está oculta. Lleva el alijo y la cabeza de Gallywix a Shenthul en Orgrimmar; él te dará más instrucciones."}}
D[2479] = {"La ayuda de Hinott",{"Ve a Molino Tarren, en Laderas de Trabalomas, para entregar la muestra de la mezcla de Zanzil a Serge Hinott","","Para ir, coge el zepelín a Entrañas y sigue el camino hacia el sur por el Bosque de Argénteos. ¡Sigue las indicaciones!"}}
D[2480] = {"La ayuda de Hinott",{"Espera a que Serge Hinott te cure."}}
D[2498] = {"El regreso a Denalan",{"Rellian Verdeguja quiere que hables con Denalan, que está en el Lago Al'Ameth."}}
D[2499] = {"Roblegüello",{"Denalan, que está en el Lago Al'Ameth, quiere que cojas el tumor gigantesco que tiene Roblegüello."}}
D[2500] = {"Componentes de Tierras Inhóspitas",{"Ve a las Tierras Inhóspitas a buscar los ingredientes que te ha pedido Ghak Sanadón y llévaselos a Thelsamar."}}
D[2501] = {"Componentes de Tierras Inhóspitas II",{"Usa las vasijas de taumaturgia en los dragones guardianes agostados de las Tierras Inhóspitas. Llévaselas a Ghak Sanadón a Thelsamar."}}
D[2518] = {"Las lágrimas de la Luna",{"La sacerdotisa A'moora del Templo de la Luna de Darnassus quiere que le lleves las espineretas de plata de Lady Sathrah."}}
D[2519] = {"El templo de la Luna",{"La hermana Aquinne quiere que hables con la sacerdotisa A'moora en el Templo de la Luna."}}
D[2520] = {"El Sacrificio de Sathrah",{"La sacerdotisa A'moora quiere que coloques las espineretas de plata de Lady Sathrah en la fuente que hay en el interior del templo, y que después vayas a verla de nuevo."}}
D[2521] = {"Al servicio de Kum'isha",{"En tus viajes por Las Tierras Devastadas, si te encontraras con una esfera draenetista perfecta, llévasela a Kum'isha el Coleccionista","","Ten cuidado, esta gema es uno de los cristales más raros de todo Azeroth. Cualquier criatura de estas tierras podría tener una","","Se te recompensará por cada esfera draenetista perfecta que consigas."}}
D[2522] = {"Los esfuerzos de Kum'isha",{"Encuentra una esfera draenetista perfecta y llévasela a Kum'isha el Coleccionista."}}
D[2523] = {"Melodía corrupta",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una melodía. De la planta emana un olor acre y malsano. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[2541] = {"El druida durmiente",{"Llévale un talismán de vudú chamán a Oben Garrafuria al Túmulo de Ban'ethil."}}
D[2561] = {"El druida de la Zarpa",{"Oben Garrafuria quiere que mates su cuerpo desalmado y que después utilices el talismán de vudú."}}
D[2581] = {"Papadas de hiena risitas",{"Llévale 3 papadas de hiena risitas, 2 pulmones de jabalí maldito y 1 pinza de scorpok al mago sangriento Drazial."}}
D[2582] = {"La cólera de las edades",{"Llévale 3 papadas de hiena risitas, 2 pulmones de jabalí maldito y 1 pinza de scorpok al mago sangriento Drazial."}}
D[2583] = {"La vitalidad del jabalí",{"Llévale 3 pulmones de jabalí maldito, 2 pinzas de scorpok y 1 cerebro de basilisco al mago sangriento Drazial."}}
D[2584] = {"El espíritu del jabalí",{"Llévale 3 pulmones de jabalí maldito, 2 pinzas de scorpok y 1 cerebro de basilisco al mago sangriento Drazial."}}
D[2585] = {"El golpe decisivo",{"Llévale 3 pinzas de scorpok, 2 mollejas de buitre y 1 pulmón de jabalí maldito al mago sangriento Drazial."}}
D[2586] = {"La sal del Scorpok",{"Llévale 3 pinzas de scorpok, 2 mollejas de buitre y 1 pulmón de jabalí maldito al mago sangriento Drazial."}}
D[2601] = {"El bocado de basilisco",{"Llévale 10 cerebros de basilisco y 2 mollejas de buitre a la maga sangrienta Lynnore."}}
D[2602] = {"La mente infalible",{"Llévale 10 cerebros de basilisco y 2 mollejas de buitre a la maga sangrienta Lynnore."}}
D[2603] = {"El vigor del buitre",{"Llévale 10 mollejas de buitre y 2 papadas de hiena risitas a la maga sangrienta Lynnore."}}
D[2604] = {"Dominación espiritual",{"Llévale 10 mollejas de buitre y 2 papadas de hiena risitas a la maga sangrienta Lynnore."}}
D[2605] = {"El goblin sediento",{"Consigue una glándula cargada de rocío y llévasela a Marin Tragonublo a Gadgetzan."}}
D[2606] = {"Un buen sabor",{"Marin Tragonublo quiere que hables con Roxio en Gadgetzan."}}
D[2607] = {"Toque de Zanzil",{"Habla con Doc Mixilpixil en el sótano de los Cuarteles."}}
D[2608] = {"Toque de Zanzil",{"Túmbate para que te examine Doc Mixilpixil. ¿Cómo va a encontrar la cura si no encuentra la causa?"}}
D[2609] = {"Toque de Zanzil",{"Lleva a Doc Mixilpixil un ramo de flores silvestres simples, un vial emplomado, un tubo de bronce y una bobina de hilo de seda chartreuse. La 'itis' no se cura sola, <jovencito/jovencita>."}}
D[2621] = {"El deshonrado",{"Habla con el comandante de despachos Ruag en Rocal."}}
D[2622] = {"Las órdenes perdidas",{"Habla con Bengor."}}
D[2623] = {"La Voz del pantano",{"Recupera las órdenes del Jefe de Guerra y vuelve junto al Héroe caído de la Horda."}}
D[2641] = {"El ingrediente secreto de Roxio",{"Roxio de Gadgetzan quiere que consigas un tragano violeta y se lo lleves."}}
D[2661] = {"Un envío para Marin",{"Roxio quiere que le lleves las partículas violeta a Marin Tragonublo a Gadgetzan."}}
D[2662] = {"El elixir de Tragonublo",{"Marin Tragonublo quiere que hables con él cuando acabe de preparar el elixir."}}
D[2681] = {"Las piedras que nos vinculan",{"Libera a 9 sirvientes de Razelikh, 3 sirvientes de Sevine, 3 sirvientes de Allistarj y 3 sirvientes de Grol. Vuelve junto al Héroe Caído cuando hayas acabado la tarea. Debes permanecer cerca de las piedras o el proceso no funcionará."}}
D[2701] = {"Los héroes de los antiguos",{"Abre el cofre y reclama tu recompensa."}}
D[2702] = {"Los héroes de los antiguos",{"Habla con el cabo Thund Pezuña Quebrada."}}
D[2721] = {"Kirith",{"Averigua qué le ha ocurrido al teniente Kirith."}}
D[2741] = {"El Superhuevomático",{"El Superhuevomático es uno de los últimos inventos de Curgle Saltamanivela. Se trata de una máquina impresionante","","El Superhuevomático chisporrotea cuando te acercas al panel de control."}}
D[2742] = {"¡Capturaron a Rin'ji!",{"Ayuda a Rin'ji a salir de la Avanzada Quel'Danil y encuentra su secreto oculto en los Acantilados Dominantes."}}
D[2743] = {"La cubierta de la Oscuridad",{"Vuelve junto al Héroe caído de la Horda con tus hallazgos."}}
D[2744] = {"El cazademonios",{"Habla con Loramus Thalimedes en Azshara."}}
D[2745] = {"Infíltrate en el castillo",{"Habla con Tyrion en el Castillo de Ventormenta."}}
D[2746] = {"Objetos importantes",{"Lleva 3 paños de seda y 2 manzanas frescas de Clara a Tyrion en Ventormenta."}}
D[2747] = {"Un huevo muy especial"}
D[2748] = {"Un huevo de primera"}
D[2749] = {"Un huevo normal"}
D[2750] = {"Un huevo pasado",{"Estos huevos no tienen salvación; son huevos que nunca eclosionarán."}}
D[2751] = {"Almenas barbáricas",{"Lleva 2 brazales de bronce estampados, 2 espadas magnas de bronce y 2 garras afiladas a Orokk Omosh a Orgrimmar."}}
D[2752] = {"Espaldares de hierro",{"Lleva 4 hachas de batalla de bronce y 4 martillos de guerra de bronce a Orokk Omosh a Orgrimmar."}}
D[2753] = {"¡Aplástalos!",{"Lleva 4 yelmos de hierro verdes, 4 brazales de hierro verdes y 2 pares de leotardos de hierro verdes a Orokk Omosh a Orgrimmar."}}
D[2754] = {"Cuernos de frenesí",{"Lleva 2 grandes mazas de hierro sólido, 2 botas de bronce bañadas en plata y 2 guanteletes de bronce bañados en plata a Orokk Omosh en Orgrimmar."}}
D[2755] = {"Las alegrías de los Omosh",{"Mira la danza de la alegría de los Omosh."}}
D[2756] = {"Los viejos hábitos",{"Lleva 4 corazas de acero y 4 yelmos de placas de acero a Aturk el Yunque a Orgrimmar."}}
D[2757] = {"¡Bahía del Botín o nada!",{"Habla con McGavan en Bahía del Botín."}}
D[2758] = {"El origen de la herrería",{"Lleva seis brazales de escamas doradas a Hank el Martillo en Ventormenta."}}
D[2759] = {"Buscando a Galvan",{"Habla con McGavan en la Bahía del Botín."}}
D[2760] = {"La Orden del mitril",{"Habla con Galvan el Antiguo en la Vega de Tuercespina."}}
D[2761] = {"Funde o no funde",{"Lleva cuarenta barras de mitril y cuarenta barras de hierro a Galvan el Antiguo en Tuercespina."}}
