D[3108] = {"Runa con grabados",{"Lee la runa con grabados, luego ve al Valle de Crestanevada y habla con Thorgas Grimson."}}
D[3109] = {"Runa codificada",{"Lee la runa codificada, luego ve al Valle de Crestanevada y habla con Solm Hargrin."}}
D[3110] = {"Runa sacralizada",{"Lee la runa sacralizada, luego ve a Yunquemar y habla con Silo Khalder."}}
D[3112] = {"Memorándum simple",{"Lee el memorándum simple, luego ve al Valle de Crestanevada y habla con Thran Khorman."}}
D[3113] = {"Memorándum encriptado",{"Lee el memorándum encriptado, luego ve al Valle de Crestanevada y habla con Solm Hargrin."}}
D[3114] = {"Memorándum glífico",{"Lee el memorándum glífico, luego ve a hablar con Marryk Nurribit, dentro de Yunquemar, sobre el Valle de Crestanevada."}}
D[3115] = {"Memorándum corrupto",{"Lee el memorándum corrupto, luego ve a hablar con Alamar Grimm que está en Yunquemar, sobre el Valle de Crestanevada."}}
D[3116] = {"El sigilo simple",{"Lee el sigilo simple y habla con Alyissia en Cañada Umbría."}}
D[3117] = {"El sigilo con grabados",{"Lee el sigilo con grabados y habla con Ayanna Semprerguida en Aldrassil, en Cañada Umbría."}}
D[3118] = {"El sigilo cifrado",{"Lee el sigilo cifrado y habla con Frahun Sombrusurro en Cañada Umbría."}}
D[3119] = {"Sigilo sacralizado",{"Lee el sigilo sacralizado y habla con Shanda en Aldrassil."}}
D[3120] = {"El sigilo verdeante",{"Lee el sigilo verdeante y habla con Mardant Fuerterroble en Aldrassil, en Cañada Umbría."}}
D[3121] = {"Una extraña petición",{"Lleva la cabeza reducida a Neeru Hojafuego a Orgrimmar."}}
D[3122] = {"Vuelve con el médico brujo Uzer'i",{"Entrega la faltriquera de hierbas al médico brujo Uzer'i en Feralas."}}
D[3123] = {"Probar la vasija",{"Viaja a las Tierras del Interior y localiza a los lechúcicos salvajes. Mata a 10 de ellos y luego utiliza la vasija de muisek para reducir y capturar a los lechúcicos salvajes caídos","","Lleva 10 lechúcicos salvajes muisek y la vasija de muisek al médico brujo Uzer'i a Feralas."}}
D[3124] = {"Muisek hipogrifo",{"ACaba con 10 hipogrifos Plumavieja de cualquier tipo y utiliza la vasija de muisek para encogerlos y capturarlos."}}
D[3125] = {"Dragones feéricos muisek",{"Mata a 8 duendes dardo o duendes dragón. Utiliza la vasija de muisek para reducir y capturar a los dragones feéricos caídos."}}
D[3126] = {"Antárboles muisek",{"Mata a 3 Caminabosques deambulantes. Utiliza el recipiente de miniatura antárbol para reducir y capturar a los Antárboles caídos."}}
D[3127] = {"Muisek gigante de montaña",{"Mata a 7 caminantes de la tierra o gigantes del risco. Utiliza la vasija de muisek para reducir y capturar a los gigantes de montaña caídos."}}
D[3128] = {"Materiales naturales",{"Lleva 2 troncos astillados, 6 minerales taraceados, 20 tendones resistentes y 40 trozos metálicos al médico brujo Uzer'i al Campamento Mojache."}}
D[3129] = {"Armas del espíritu",{"El médico brujo Uzer'i quiere que esperes mientras prepara las armas."}}
D[3130] = {"En contra de los Crestafuria",{"Preséntate ante Latronicus Lanzaluna, en el Bastión Plumaluna."}}
D[3141] = {"Loramus",{"Escucha la historia de Loramus Thalipedes."}}
D[3161] = {"Gahz'rilo",{"Marvon Buscarroblones de Tanaris quiere que reúnas 30 adornos de gahz'rilo."}}
D[3181] = {"El cuerno de la bestia",{"Lleva el cuerno enorme de Margol a la montaraz Guijarro."}}
D[3182] = {"Certificado de autenticidad",{"Lleva el cuerno enorme de Margol al comisario Thorius a Forjaz."}}
D[3201] = {"¡Al fin!",{"Lleva el certificado de autenticidad a la montaraz Guijarro."}}
D[3221] = {"Habla con Renferrel",{"Habla con el boticario Renferrel en El Sepulcro."}}
D[3261] = {"Jorn Videncielo",{"Habla con Jorn Videncielo en el Campamento Taurajo."}}
D[3281] = {"La plata robada",{"Llévale la plata robada a Gazrog en El Cruce."}}
D[3301] = {"Mura Runatótem",{"Habla con Mura Runatótem en El Sepulcro."}}
D[3321] = {"¿Has perdido esto?",{"Espera a que Trenton acabe su trabajo."}}
D[3341] = {"Acaba con la amenaza",{"Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su cráneo."}}
D[3361] = {"Las penurias de un refugiado",{"Lleva la caja de Félix, el cofre de Félix, y el cubo de tornillos de Félix Rayaullido a Yunquemar."}}
D[3362] = {"El Valle Cardizal",{"Tran'rek de Gadgetzan quiere que mates a 8 Cardizales nudosos y a 8 enraizadores Cardizales."}}
D[3363] = {"Melodía corrupta"}
D[3364] = {"Entrega una infusión de albaza hirviendo",{"Lleva la infusión de albaza hirviendo a Durnan Cortapieles a Yunquemar antes de que se enfríe, ¡tienes 5 minutos!"}}
D[3365] = {"Devuelve la jarra",{"Devuelve la jarra a Nori Rumborgullo."}}
D[3366] = {"El fragmento resplandeciente",{"Viaja hasta Trinquete para averiguar el significado oculto tras el Fragmento de Pesadilla."}}
D[3367] = {"Piedras de Suntara",{"Ayuda a Dorius a volver a Forjaz."}}
D[3368] = {"Piedras de Suntara",{"Lleva la carta chamuscada a Thorius a Forjaz. Está en la Sala de los Exploradores."}}
D[3369] = {"En las pesadillas",{"Lleva el Fragmento de Pesadilla a Hamuul Runatótem en el Alto de los Ancestros."}}
D[3370] = {"En las pesadillas",{"Lleva el Fragmento de Pesadilla a Mathrengyl Garroso de Darnassus."}}
D[3371] = {"La justicia de los enanos",{"Vuelve a La Garganta de Fuego y libera al equipo de Dorius."}}
D[3372] = {"Libéralos",{"Encuentra el artefacto misterioso que protegen los idólatras de Martillo Crepuscular en el cuadrante noroeste de La Garganta de Fuego y tráelo al altar de Suntara en la Fosa de la Escoria."}}
D[3373] = {"Esencia de Eranikus",{"Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido."}}
D[3374] = {"La esencia de Eranikus",{"Llévale la piedra de juramento del Vuelo de Ysera y la esencia encadenada de Eranikus a Itharius, que está en el Pantano de las Penas. Una vez allí, deberás decidir si quieres ayudar al Vuelo de Ysera o no."}}
D[3375] = {"Otra ampolla",{"Lleva 1 poción de maná, 1 trozo de carbón y néctar dulce a Talvash del Kissel a Forjaz. Te dará una ampolla de adivinación."}}
D[3376] = {"La cabeza de Cornapunta",{"Lleva la cabeza del Jefe Cornapunta Mantospina a la Valiente Ventopluma en Mesa de la Nube Roja."}}
D[3377] = {"El Rezo a Elune",{"Escucha a Zamael."}}
D[3378] = {"El rezo a Elune",{"Lleva el rezo a Elune a Astarii Buscaestelar a Darnassus."}}
D[3379] = {"Las tejedoras de sombra",{"Mata a los furtivos Sedaumbría de La Garganta de Fuego. Nilith cree que son 5. Ve a ver a Nilith en La Garganta de Fuego cuando hayas terminado."}}
D[3380] = {"El Templo Sumergido",{"Encuentra a Marvon Buscarroblones en Tanaris."}}
D[3381] = {"Un encuentro con el maestro",{"Llévale 2 plumas de hipogrifo intactas a Sanath Lim-yo en Azshara si deseas hablar con su maestro."}}
D[3382] = {"Un equipo bajo el fuego enemigo",{"Defiende a la capitana Vanessa Beltis, su tripulación y los pasajeros del Explorador del horizonte frente al ataque de los nagas. La capitana Vanessa Beltis tiene que sobrevivir."}}
D[3385] = {"El Mercado Negro",{"Mata al maestro de comercio Kovic y a su esbirro, Clonk. Lleva su cartera a Nilith."}}
D[3402] = {"El Mercado Negro",{"Habla con Vizzklick en Gadgetzan."}}
D[3421] = {"El viaje de vuelta",{"Te haré volver al campamento de Sanath ahora","","No hagas caso de su mala educación, es así con todos a excepción del maestro. Quizás algún día le den una lección."}}
D[3441] = {"Castigo divino",{"Escucha a Kalaran Espada del Viento."}}
D[3442] = {"La llama pura",{"Lleva 4 corazones de llama y 4 globos de aceite gólem a Kalaran Espada del Viento."}}
D[3443] = {"Forjar el mango",{"Lleva 8 dagas bañadas en torio a Kalaran Espada del Viento."}}
D[3444] = {"El círculo de piedra",{"Recupera el círculo de piedra del taller de Marvon Buscarroblones, en Trinquete."}}
D[3445] = {"El Templo Sumergido",{"Encuentra a Marvon Buscarroblones en Tanaris."}}
D[3446] = {"En las profundidades",{"Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas."}}
D[3447] = {"El secreto del círculo",{"Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas."}}
D[3448] = {"Encargarse de la investigación",{"Habla con Tymor en Forjaz."}}
D[3449] = {"Runas Arcanas",{"Haz calcos de la Runa de Beth'Amara, la Runa de Jin'yael, la Runa de Markri y la Runa de Sael'hai. Luego ve a la isla frente a la península meridional de Azshara y avisa al piloto Xiggs Luzfusil para que recoja los calcos."}}
D[3450] = {"Un simple envío",{"Habla con Xiggs Luzfusil en Forjaz."}}
D[3451] = {"Una señal para el envío",{"Habla con Xiggs Luzfusil para que te dé una pistola de bengalas en Forjaz."}}
D[3452] = {"El soporte para la llama",{"Lleva un Símbolo de Ragnaros a Kalaran Espada del Viento."}}
D[3453] = {"La antorcha de reprensión",{"Espera a que Kalaran Espada del Viento termine la antorcha de reprensión."}}
D[3454] = {"La antorcha de reprensión",{"Coge la antorcha de reprensión."}}
D[3461] = {"Vuelve con Tymor",{"Devuelve el juego de calco a Tymor, que está en Forjaz."}}
D[3462] = {"Escudero Maltrake",{"Habla con mi enviado, el escudero Maltrake."}}
D[3463] = {"¡Préndelas fuego!",{"Entra en las 4 torres del centinela e incéndialas con la antorcha de reprensión."}}
D[3481] = {"Abalorios...",{"Abre el cofre."}}
D[3482] = {"<NYI> <TXT> The Pocked Black Box",{"Llévale esta caja a Kravel."}}
D[3483] = {"Una señal para el envío",{"¿Otra pistola de bengalas? Por supuesto","","Y recuerda que debes ir a la punta sur de Azshara. Es una islita reconvertida en pista de aterrizaje; seguro que la ves."}}
D[3501] = {"Todo cuenta en grandes cantidades",{"Llévale a Kum'isha trozos draenetistas imperfectos y te recompensará por cada fragmento entregado."}}
D[3502] = {"Un trasto de Draenei...",{"Llévale a Kum'isha trozos draenetistas imperfectos. Cualquier forma de monstruo de Las Tierras Devastadas podría llevar uno de estos fragmentos."}}
D[3503] = {"Encuentro con el maestro",{"Hubo un tiempo en que podía pedirles lo que fuera a los que buscaban a mi maestro. Pero ahora, solo tienes que pedirlo y te haré llegar hasta él","","Me molesta pero no cuestiono sus órdenes. Solo puedo disfrutar de hacer bromas sobre tu ridículo atuendo o esa estúpida mirada que luces. Hasta eso me aburre..","","¡Hasta esta divagación me aburre! Bueno, ¿quieres ver a mi maestro o no?"}}
D[3504] = {"Traición",{"Entrega la carta lacrada a Ag'tor Puñosangre en Azshara."}}
D[3505] = {"Traición",{"Mata a 10 reivindicadores y 10 peritos elfos de sangre antes de buscar el campamento de Maga Rimtori. Una vez allí, busca algo que sea importante para ella, algo con lo que provocar un combate."}}
D[3506] = {"Traición",{"Destruye el cristal de enfoque arcano de Maga Rimtori y entonces mátala. Lleva su cabeza a Ag'tor Puñosangre a Azshara."}}
D[3507] = {"Traición",{"Habla con Belgrom Destrozarroca en Orgrimmar."}}
D[3508] = {"Romper el amuleto",{"Espera que Loramus acabe el hechizo de ilustración."}}
D[3509] = {"El nombre de la bestia",{"Habla con Lord Arkkoroc en Azshara. Empieza tu búsqueda en la orilla para encontrar el Templo de Arkkoran."}}
D[3510] = {"El nombre de la bestia",{"Mata a Hetaera y lleva la cabeza ensangrentada, la cabeza golpeada y la cabeza amoratada a Lord Arkkoroc."}}
D[3511] = {"El nombre de la bestia",{"Llévale el temple a Loramus Thalipedes."}}
D[3512] = {"Como diría Eranikus...",{"Viaja a la parte este de Cuna del Invierno y habla con Umbranse el Contacto Espiritual."}}
D[3513] = {"El pergamino rúnico",{"Llévale el pergamino rúnico de la torre de vigilancia norte en Los Baldíos."}}
D[3514] = {"La presencia de la Horda",{"Mata a la jefa de El Cubil del Espolón, Rynthariel la Maestra de llaves."}}
D[3517] = {"El robo de conocimientos",{"Encuentra la tablilla de Beth'Amara, la tablilla de Jin'yael, la tablilla de Markri y la tablilla de Sael'hai antes de volver junto a Jediga en Azshara."}}
D[3518] = {"Entrega a Magatha",{"Llévale la tablilla de Beth'Amara a Magatha en Cima del Trueno."}}
D[3519] = {"Un amigo en apuros",{"Habla con Dirania Brillargente en Cañada Umbría."}}
D[3520] = {"Los espíritus de los estridadores",{"Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor."}}
D[3521] = {"El antídoto de Iverron",{"Reúne 7 champiñones jacinto, 4 lirios alunados y 1 icor Tejemadera para Dirania Brillargente, que está en Cañada Umbría."}}
D[3522] = {"El antídoto de Iverron",{"Llévale el antídoto de Iverron a Iverron antes de que se acabe el tiempo. Lo encontrarás junto a la cueva situada al norte."}}
D[3523] = {"La plaga de la Zahúrda",{"Si decides ayudar a Belnistrasz, habla con él otra vez y devuélvele la piedra de juramento."}}
D[3524] = {"Varado",{"Recoge huesos de la criatura marina varada que está al sur de Auberdine y llévaselos a Gwennyth Bly'Leggonde a Auberdine."}}
D[3525] = {"Extinguir el ídolo",{"Acompaña a Belnistrasz al ídolo jabaespín en Zahúrda Rajacieno","","Protégelo mientras realiza el ritual para inutilizar el ídolo."}}
D[3526] = {"Ingeniería goblin",{"Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan."}}
D[3527] = {"La profecía de Mosh'aru",{"Llévale la primera y segunda tablillas Mosh'aru a Yeh'kinya, que está en Tanaris."}}
D[3528] = {"El dios Hakkar",{"Llévale el huevo de Hakkar relleno a Yeh'kinya, que está en Tanaris."}}
D[3541] = {"Entrega a Jes'rimon",{"Envía la tablilla de Jin'yael a Jes'rimon en Orgrimmar."}}
D[3542] = {"Entrega a Andron Gant",{"Llévale la tablilla de Markri a Andron Gant en Entrañas."}}
D[3561] = {"Entrega al archimago Xylem",{"Llévale la tablilla de Sael'hai al archimago Xylem en Azshara."}}
D[3562] = {"El pago de Magatha a Jediga",{"Entrega la nota de Magatha a Jediga en Azshara."}}
D[3563] = {"El pago de Jes'rimon a Jediga",{"Entrega la nota de Jes'rimon a Jediga en Azshara."}}
D[3564] = {"El pago de Andron a Jediga",{"Entrega la nota de Andron a Jediga en Azshara."}}
D[3565] = {"El pago de Xylem a Jediga",{"Entrega la nota de Xylem a Jediga en Azshara."}}
D[3566] = {"¡Arriba, Obsidion!",{"Lleva la cabeza de Lathoric el Negro y el corazón de Obsidion a Thorius a Forjaz."}}
D[3567] = {"A la cima",{"¿Quieres ver la vista desde uno de los colosos gemelos? Porque puedo mandarte allí arriba, <raza>","","Pero tendrás que pensar tú en cómo harás para bajar. Yo te ofrezco solo el viaje de ida."}}
D[3568] = {"La filtración de la Corrupción",{"Llena los 4 viales vacíos en las pozas de las mareas que se encuentran a lo largo de la costa de las Ruinas de Eldarath en Azshara y después ve a ver al químico Cuely."}}
D[3569] = {"La filtración de la Corrupción",{"Dale el elixir de Cuely a Thersa Canzalvaje, que está en Entrañas."}}
D[3570] = {"La filtración de la Corrupción",{"Nunca hubiera imaginado que el elixir hiciera efecto tan rápido. Gracias, <nombre>. Ahora me pondré manos a la obra con las demás muestras. Seguro que muy pronto les resultan de utilidad a Lady Sylvanas y a los Renegados."}}
D[3601] = {"¡Kim'jael, claro!",{"Busca en el Campamento base thalassiano la brújula de Kim'jael, la mira, el pollo relleno y el cachivache y llévaselo todo a Azshara."}}
D[3602] = {"Azsharita",{"Recupera 20 azsharitas cristalizadas del sur de Azshara. Puede que encuentres canes manáfagos dispuestos a ayudarte a rastrear la ubicación de los depósitos hábilmente escondidos","","Vuelve con Loramus cuando hayas completado la tarea."}}
D[3621] = {"La formación de Felbane",{"Llévale el envío a Galvan el Antiguo en la Vega de Tuercespina."}}
D[3625] = {"Armas Fel en Azsharita encantada",{"Espera que Galvan acabe de forjar las armas."}}
D[3626] = {"El regreso a Las Tierras Devastadas",{"Vuelve junto al Héroe caído de la Horda."}}
D[3627] = {"Juntar pedazos del amuleto",{"Mata a Grol el Destructor, a Lady Sevine y al archimago Allistarj. De sus cadáveres coge el amuleto de Grol, el amuleto de Sevine y el amuleto de Allistarj","","Acuérdate de USAR tus armas Fel en Azsharita encantada para debilitar a la tríade. Es la única forma de matarlos, pero úsalas con moderación..."}}
D[3628] = {"Eres Rakh'likh, demonio",{"Destruye a Razelikh el Rapiñador y llévale el cuerno de Rapiñador cortado al Héroe caído de la Horda. También tendrás que devolver la Resguardo del Rapiñador para que el Héroe caído pueda destruirlo y así impedir que caiga en las manos equivocadas."}}
D[3629] = {"Ingeniería goblin",{"Si quieres aprender más sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería a Nixx Muellepiñón en Gadgetzan."}}
D[3630] = {"Ingeniería gnómica",{"Si quieres aprender más sobre ingeniería gnoma, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz."}}
D[3631] = {"Invoca a un corcel vil",{"Habla con Strahad Farsan en Los Baldíos."}}
D[3632] = {"Ingeniería gnómica",{"Si quieres saber más sobre el tema, llévale el Manual de disciplinas de ingeniería aI maestro manitas Sobrechispa a Forjaz."}}
D[3633] = {"Ingeniería goblin",{"Si quieres aprender más cosas sobre la ingeniería de los goblins, lleva el Manual de disciplinas de ingeniería a Nixx Muellepiñón en Gadgetzan."}}
D[3634] = {"Ingeniería gnómica",{"Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería al maestro manitas Sobrechispa en Forjaz."}}
D[3635] = {"Ingeniería gnómica",{"Si quieres saber más sobre ingeniería gnómica, llévale el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus de Bahía del Botín."}}
D[3636] = {"Trae la Luz",{"El Arzobispo Bendictus quiere que mates a Amnennar el Gélido en Zahúrda Rajacieno."}}
D[3637] = {"Ingeniería gnómica",{"Si quieres aprender más cosas sobre ingeniería gnómica, lleva el Manual de disciplinas de ingeniería a Oglethorpe Obnoticus en Bahía del Botín."}}
D[3638] = {"Compromiso de secreto perpetuo",{"Si quieres convertirte en <un ingeniero/una ingeniera> goblin, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y habla de nuevo con Nixx Muellepiñón de Gadgetzan."}}
D[3639] = {"Muestra tus creaciones",{"Llévale 20 bombas grandes de hierro, 20 cartuchos de dinamita sólida y 5 ovejas explosivas a Nixx Muellepiñón de Gadgetzan."}}
D[3640] = {"La promesa del secreto",{"Si decides dedicarte a la ingeniería gnómica, haz clic con el botón derecho en el compromiso de secreto perpetuo y vuelve a hablar con el maestro manitas Sobrechispa en Forjaz."}}
D[3641] = {"Muestra tu trabajo",{"Lleva 6 tubos de mitril, 1 escopo y 2 objetivos de prueba al maestro manitas Sobrechispa a Forjaz."}}
D[3642] = {"La promesa del secreto",{"Si quieres convertirte en <un ingeniero/una ingeniera> gnomo, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y vuelve a hablar con Oglethrope Obnoticus en la Bahía del Botín."}}
D[3643] = {"Muestra tu trabajo",{"Lleva 6 tubos de mitril, un escopo preciso y 2 muñecos-diana avanzados a Oglethorpe Obnoticus en la Bahía del Botín."}}
D[3644] = {"Renovación de la tarjeta de miembro",{"Para renovar tu tarjeta de miembro tendrás que pagar las cuotas de renovación, que son dos piezas de oro."}}
D[3645] = {"Renovación de la tarjeta de miembro"}
D[3646] = {"Renovación de la tarjeta de miembro"}
D[3647] = {"Renovación de la tarjeta de miembro",{"In order to renew your membership card, you will need to pay the renewal fee of two gold pieces."}}
D[3661] = {"¿Creados por Elune?",{"Recoge 15 plumas de lechúcico salvaje de las Tierras del Interior y llévaselas a Erelas Cieloámbar a la Aldea Rut'theran."}}
D[3681] = {"Escrito sobre divinidad",{"Ve a Ventormenta y habla con Duthorian Rall."}}
D[3701] = {"Las humeantes Ruinas de Thaurissan",{"Ve a las Ruinas de Thaurissan, en Las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa al historiador real Archesonus."}}
D[3702] = {"Las humeantes Ruinas de Thaurissan",{"Escucha al historiador real Archesonus relatar la historia de Thaurissan."}}
D[3721] = {"Tu propio OOX",{"¡Has recuperado tres de mis robots mensajeros OOX! Has hecho mucho más de lo que tenías que hacer, así que te daré algo especial por toda tu ayuda. Es una versión miniatura del robot que tan bien conoces, ¡el OOX!","","Normalmente, no dejaría que nadie tuviese un dispositivo tan potencialmente letal, pero tú has sido de gran ayuda. Además, el mecanismo de combate y las funciones de búsqueda de este robot están desactivados","","Por todo lo demás, ¡es un OOX auténtico!"}}
D[3741] = {"El collar de Hilary",{"Encuentra el collar de Hilary y llévaselo a Villa del Lago."}}
D[3761] = {"Tierra de Un'Goro",{"Llévale 20 muestras de la tierra de Un'Goro a Ghede, que está en el Alto de los Ancestros de Cima del Trueno."}}
D[3762] = {"Ayuda al archidruida Runatótem",{"Habla con el archidruida Hamuul Runatótem en Cima del Trueno."}}
D[3763] = {"Ayuda al archidruida Corzocelada",{"Ve a Darnassus y habla con el archidruida Fandral Corzocelada."}}
D[3764] = {"La tierra de Un'Goro",{"Lleva 20 muestras de tierra de Un'Goro Soil a Jenal, que está en el Enclave Cenarion de Darnassus."}}
D[3765] = {"Lejana corrupción",{"Ve a ver a Gershala Noctusurro en Auberdine."}}
D[3781] = {"Investigar la mañagrana",{"Lleva el vale para semillas del archidruida a Mathrengyl Garroso al Enclave Cenarion de Darnassus."}}
D[3782] = {"Investigar la mañagrana",{"Llévale este vale para semillas a Bashana Runatótem, que está en Cima del Trueno."}}
D[3783] = {"Yeti... ¿ya hemos llegado?",{"Reúne 10 pelajes de yeti gruesos para Umi Risitas en Vista Eterna."}}
D[3784] = {"Ayuda al archidruida Runatótem",{"Habla con el archidruida Hamuul Runatótem en Cima del Trueno."}}
D[3785] = {"Investigar la mañagrana",{"Utiliza una faltriquera de siempreverde con 1 paquete de semillas de Tharlendris y 2 muestras de tierra de Un'Goro para intentar cultivar mañagrana","","Lleva 10 plantas de mañagrana a Mathrengyl Garroso a Darnassus."}}
D[3786] = {"Investigar la mañagrana",{"Mete en la bolsa de siempreverde un paquete de Tharlendris y dos muestras de tierra de Un'Goro para cultivar muestras de mañagrana","","Llévale 10 mañagranas a Bashana Runatótem, que está en Cima del Trueno."}}
D[3787] = {"La petición de Jonguja",{"Habla con Quintis Jonguja en el Bastión Plumaluna."}}
D[3788] = {"La petición de Jonguja",{"Habla con Quintis Jonguja del Bastión Plumaluna."}}
D[3789] = {"Ayuda al archidruida Corzocelada",{"Habla con el archidruida Fandral Corzocelada en Darnassus."}}
D[3790] = {"Ayuda al archidruida Corzocelada",{"Habla con el archidruida de Darnassus, Fandral Corzocelada."}}
D[3791] = {"El misterio de mañagrana",{"Lleva 10 plantas de mañagrana a Quintis Jonguja al Bastión Plumaluna."}}
D[3792] = {"Mañagrana a Bastión Plumaluna"}
D[3801] = {"El legado de los Hierro Negro",{"Habla con Franclorn Forjador si te interesa obtener una llave de la ciudad."}}
D[3802] = {"El legado de los Hierro Negro",{"Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjador."}}
D[3803] = {"Mañagrana para Darnassus"}
D[3804] = {"Mañagrana para Cima del Trueno",{"El archidruida siempre está buscando mañagrana para el proyecto de investigación sobre el Cráter de Un’Goro que lleva a cabo el Círculo Cenarion. La recogemos en lotes de 10 y recompensamos a quien la trae con un conjunto de objetos muy útiles. Si reúnes 10 plantas de mañagrana, tráemelas y te daré tu recompensa."}}
D[3821] = {"Roca Machacamiedo",{"Adéntrate en Las Estepas Ardientes y averigua qué le ha ocurrido a Sha'ni Colmorgullo."}}
D[3822] = {"Krom'Grul",{"Recupera el aro de la nariz de Sha'ni de Krom'Grul y llévasela a Thal'trak en Kargath. Busca por las diferentes cuevas y minas de la Roca Machacamiedo."}}
D[3823] = {"El exterminio de los Pirontraña",{"Mata a 15 magos ogros Pirontraña, 7 ogros Pirontraña y 7 ogros toscos Pirontraña y vuelve junto a Oralius cuando hayas acabado."}}
D[3824] = {"Gor'tesh, el Señor de los toscos",{"Encuentra a Gor'tesh, en el algún lugar al oeste de la Roca Machacamiedo. Mata a Gor'tesh y llévale entonces la cabeza cortada de Gor'tesh a Oralius en Las Estepas Ardientes."}}
D[3825] = {"Una cabeza ogro empalada = FIESTA",{"Coge la cabeza cortada de Gor'tesh y colócala en lo alto de la Roca Machacamiedo. Busca un montículo de tierra blanda para clavar la pica."}}
D[3841] = {"Un huérfano que busca un hogar",{"Ve a Las Mil Agujas y habla con Quentin."}}
D[3842] = {"Una corta incubación",{"Lleva 2 elixires de entereza a Quentin a Las Mil Agujas."}}
D[3843] = {"Un nuevo miembro en la familia",{"Lleva tu huevo de duende dardo frágil a las Tierras del Interior y habla con Agnar Domabestias, pero date prisa: si tardas más de 1 hora en encontrarlo, la cría que hay en el huevo morirá."}}
D[3844] = {"Un secreto bien guardado",{"Busca alrededor del estanque alguna pista sobre a quién perteneció la balsa destrozada."}}
D[3845] = {"Un secreto bien guardado",{"Examina los objetos de la talega y devuélveselos a su propietario."}}
D[3861] = {"¡CLOQUEA!",{"Consigue comida para pollos especial y vuelve junto a tu nuevo amigo pollo. Cuando lo encuentres, anímalo con el comando /animar antes de darle la comida para pollos especial."}}
D[3881] = {"Expedición Salvación",{"Lleva un cajón de comestibles y el equipo de investigación a Williden Marshal en el Cráter de Un'Goro."}}
D[3882] = {"Choca esos huesos",{"Lleva 8 huesos de dinosaurio a Chispik Nilminer en el Cráter de Un'Goro."}}
D[3883] = {"Ecología alienígena",{"Utiliza el vial de raspadura para recoger una Muestra de pared de colmena de uno de los criaderos Gorishi del Cráter de Un'Goro. Busca las cámaras con los huevos de larva colgantes","","Lleva la Muestra de pared de colmena a Hol'anyee Marshal en el Cráter de Un'Goro."}}
D[3884] = {"Diario de Williden",{"Devuelve el diario a Williden Marshal en algún lugar del Cráter de Un'Goro."}}
D[3901] = {"Sacudir esqueletos",{"Mata a 12 esqueletos armadóseos y cuando lo hayas hecho, vuelve a buscar al sacerdote de las Sombras Sarvis a Camposanto."}}
D[3902] = {"Hurgar en Camposanto",{"Busca 6 piezas de mercancías extraviadas por Camposanto y los alrededores y llévaselas al Guardia de la Muerte Saltain."}}
D[3903] = {"Milly Osworth",{"Habla con Milly Osworth."}}
D[3904] = {"La cosecha de Milly",{"Lleva 8 cajas de cosecha a Milly Osworth a la Abadía de Villanorte."}}
D[3905] = {"Informe de la vendimia",{"Lleva el Informe de la vendimia al hermano Neals a la Abadía de Villanorte."}}
D[3906] = {"La discordia de las llamas",{"Ve a la cantera de la Montaña Roca Negra y ejecuta al Maestro Supremo Pyron. Vuelve junto a Truenozón cuando hayas completado este encargo."}}
D[3907] = {"La discordia de las llamas",{"Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Truenozón."}}
D[3908] = {"Un secreto bien guardado",{"Lleva la Espada de Linken a Donova Cubilnevado en Cuna del Invierno."}}
D[3909] = {"El Elixir de Videre",{"Busca a Gregan Vomitabrebaje en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno."}}
D[3911] = {"El último elemento",{"Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los golems y a los creadores de golems. Recuerdas que Vivian La tumba también murmuró entre dientes algo sobre los elementales."}}
D[3912] = {"Encuentro en la tumba",{"Ve al cementerio a las afueras de Gadgetzan y utiliza el Elixir de Videre. Sigue las demás instrucciones de Donova para encontrar a Gaeriyan."}}
D[3913] = {"Una situación mortal",{"Resucita y busca la lápida de la que te habló Gaeriyan."}}
D[3914] = {"La Espada de Linken",{"Entrega la Espada superior a Linken en el Cráter de Un'Goro."}}
D[3921] = {"Wenikee Tuercasmil",{"Llévale el churumbele roto a Wenikee Tuercasmil."}}
D[3922] = {"Engranajes",{"Llévale 15 engranajes a Wenikee Tuercasmil en Los Baldíos."}}
D[3923] = {"Rilli Gapegajoso",{"Llévale el churumbele roto y maltrecho a Rilli Gapegajoso en Orgrimmar."}}
D[3924] = {"El manual del churumbele",{"Llévale el manual del churumbele a Rilli Gapegajoso en Orgrimmar."}}
D[3941] = {"La ayuda de una gnoma",{"Encuentra a J.D. Collie en la cueva del Refugio de Marshal."}}
D[3942] = {"Recuerdos de Linken",{"Encuentra a Eridan Vientoazul en el sur de Frondavil."}}
D[3961] = {"La aventura de Linken",{"Lleva el Tótem plateado de Aquementas a Linken, en el Refugio de Marshal."}}
D[3962] = {"Ir solo es peligroso",{"Viaja a Cresta del Penacho en Llamas, al sur del Refugio de Marshal","","Busca a Correfuego y utiliza el Tótem para eliminar su aura protectora. Cuando le hayas derrotado, coge la Llama Dorada de la cueva."}}
D[3981] = {"Comandante Gor'shak",{"Encuentra al comandante Gor'shak en las Profundidades de Roca Negra","","Recuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar."}}
D[3982] = {"¿Qué pasa?",{"Defiende a Gor'shak."}}
D[4001] = {"¿Qué pasa?",{"Habla con Kharan Martillazo y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar","","Recuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana."}}
D[4002] = {"Los Reinos del Este",{"Si aceptas la misión, habla con Thrall."}}
D[4003] = {"El rescate real",{"Mata al emperador Dagran Thaurissan para liberar a la princesa Moira Barbabronce del hechizo."}}
D[4004] = {"¿Princesa salvada?",{"¡Vuelve junto a Thrall!"}}
D[4005] = {"Aquementas",{"Lleva el Libro de Aquor, las zarpas plateadas y el corazón de Troncoferro a Tanaris","","Utiliza el Libro de Aquor para invocar Aquementas","","Cuando tengas el tótem completo llévaselo a J.D. Collie en el Refugio de Marshal."}}
D[4021] = {"¡Contraataca!",{"Llévale una pieza del estandarte de Krom'zar a Regthar Portamorta, al oeste de El Cruce."}}
D[4022] = {"Un sabor a llamarada",{"Enséñale a Cyrus Therepentio la escama de Vuelo Negro que recibiste de Kalaran Espada del Viento."}}
D[4023] = {"Un sabor a llamarada",{"Demuéstrale a Cyrus Therepentio lo que vales","","Te da la impresión de que Cyrus ya sabe que no eres digno."}}
D[4024] = {"Un sabor a llamarada",{"Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar","","Solo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia ígnea","","Llévale la esencia ígnea encerrada a Cyrus Therepentio."}}
D[4041] = {"El Elixir de Videre",{"Tráeme una raíz del mal y te haré ese Elixir Videre","","Sé mucho sobre hierbas y alquimia... ¡Podría contarte una de historias! Por ejemplo, un día transformé el queso que iba a desayunar en oro... ¡Eh! ¿Adónde vas?"}}
D[4061] = {"La revuelta de las máquinas",{"Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos elementales fracturados para Hierofante Theodora Mulvadania","","Recuerdas que Theodora mencionó que los golems y elementales de esa región eran la fuente de estos fragmentos."}}
D[4062] = {"La revuelta de las máquinas",{"Lleva el ejemplar de fragmento de Elemental a Lotwil Veriatus","","Recuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este."}}
D[4063] = {"La revuelta de las máquinas",{"Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los golems Furiatracadores y de los ensamblajes belisario que protegen a Argelmach. Lo sabes porque eres un adivino."}}
D[4081] = {"MATAR INMEDIATAMENTE: enanos Hierro Negro",{"Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!","","El señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea."}}
D[4082] = {"MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango",{"Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!","","El señor de la guerra Dientegore quiere que mates a 10 médicos de Yunque Colérico, 10 soldados de Yunque Colérico y 10 oficiales de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea."}}
D[4083] = {"El cáliz espectral",{"El cáliz espectral flota en el aire, ascendiendo y descendiendo lentamente… como el latido de un corazón moribundo."}}
D[4084] = {"Corazón de plata",{"Recoge 11 zarpas plateadas y 1 corazón de Troncoferro para Eridan Vientoazul de Frondavil."}}
D[4101] = {"Limpiar Frondavil",{"Lleva 15 unidades de ámbar de sangre a Arathandris Cielargente a Frondavil."}}
D[4102] = {"Limpiar Frondavil",{"Lleva 15 unidades de ámbar de sangre a Maybess Brisafluvial a Frondavil."}}
D[4103] = {"Bálsamo por caza",{"Una antorcha Cenarion te permite ver un fragmento de alma corrupto en esas bestias corruptas que deben ser sacrificadas por un bien mayor. Yo pulverizo los fragmentos y los convierto en un componente con el que se crea el bálsamo de planta de Cenarion. Y es lo que utilizaremos para sanar a las plantas corruptas","","A cambio de esos fragmentos, te daré algunos bálsamos de planta de Cenarion que ya tengo preparados."}}
D[4104] = {"Bálsamo por minería",{"Si llevas una antorcha Cenarion mientras trabajas en los yacimientos de Frondavil, podrás ver el vitriolo contaminado que corrompe una veta del metal. Yo sé cómo purificar ese vitriolo y cómo convertirlo en un componente del bálsamo de planta de Cenarion. Un bálsamo que podrás utilizar para salvar las plantas que encuentres en el bosque","","Si me traes algo de vitriolo contaminado, te daré un bálsamo de planta de Cenarion que tengo preparado."}}
D[4105] = {"Bálsamo por recolección",{"Una antorcha Cenarion permite a un herborista experimentado detectar cualquier agente máculo insidioso, un criminal producto de la corrupción de Frondavil. Trabajando aquí he aprendido a purificar el agente máculo y convertirlo en un agente purificador... uno que se usa en lo que ahora llamamos bálsamo de planta de Cenarion","","Si llevas la antorcha contigo mientras recoges hierbas en Frondavil, deberías poder ver el agente máculo. A cambio de lo que me traigas, te daré un poco de bálsamo de planta de Cenarion que tengo ya preparado."}}
D[4106] = {"Bálsamo por desuello"}
D[4107] = {"Bálsamo por desencantamiento"}
D[4108] = {"Bálsamo por caza",{"Una antorcha Cenarion te permite ver un fragmento de alma corrupto en esas bestias corruptas que deben ser sacrificadas por un bien mayor. Yo pulverizo los fragmentos y los convierto en un componente con el que se crea el bálsamo de planta de Cenarion. Y es lo que utilizaremos para sanar a las plantas corruptas","","A cambio de esos fragmentos, te daré algunos bálsamos de planta de Cenarion que ya tengo preparados."}}
D[4109] = {"Bálsamo por minería",{"Si llevas una antorcha Cenarion mientras trabajas en los yacimientos de Frondavil, podrás ver el vitriolo contaminado que corrompe una veta de metal. Yo sé cómo purificar ese vitriolo y cómo convertirlo en un componente del bálsamo de planta de Cenarion. Un bálsamo que podrás utilizar para salvar las plantas que encuentres en el bosque","","Si me traes algo de vitriolo contaminado, te daré un bálsamo de planta de Cenarion que tengo preparado."}}
D[4110] = {"Bálsamo por recolección",{"Una antorcha Cenarion permite a un herborista experimentado detectar cualquier agente máculo insidioso, ese criminal producto de la corrupción de Frondavil. Trabajando aquí he aprendido a purificar el agente máculo y convertirlo en un agente purificador... uno que se usa en lo que ahora llamamos bálsamo de planta de Cenarion","","Si llevas la antorcha contigo mientras recoges hierbas en Frondavil, deberías poder ver el agente máculo. A cambio de lo que me traigas, te daré un poco de bálsamo de planta de Cenarion que tengo ya preparado."}}
D[4111] = {"Bálsamo por desuello",{"Una antorcha Cenarion permite a un desollador experto detectar parches de piel manchados en las presas cazadas en Frondavil. Yo convierto esos parches aparentemente inútiles en una pasta espesa que utilizo después como agente acelerador para el bálsamo de planta Cenarion. Cuando desuelles las presas que caces en Frondavil, asegúrate de llevar una antorcha contigo","","Si recoges parches manchados, tráemelos y te daré unos bálsamos de planta Cenarion que tengo preparados."}}
D[4112] = {"Bálsamo por desencanto"}
D[4113] = {"Melodía corrupta",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una melodía. De la planta emana un olor acre y malsano. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[4114] = {"Melodía corrupta",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una melodía. De la planta emana un olor acre y malsano. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[4115] = {"Flor del viento corrupta"}
D[4116] = {"Melodía corrupta",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una melodía. De la planta emana un olor acre y malsano. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[4117] = {"Blancoria corrupta",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una blancoria. De la planta cuelga una sustancia viscosa y las raíces visibles parecen endurecidas, como si fueran de cuero. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[4118] = {"Melodía corrupta",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una melodía. De la planta emana un olor acre y malsano. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[4119] = {"Dragón nocturno corrupto",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una planta dragón nocturno. Los frutos que cuelgan de la planta están podridos y envenenados. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[4120] = {"La fuerza de la corrupción",{"Talo Pezuñahendida, del Campamento Mojache de Feralas, quiere que mates a 12 pardos Zarpira y 12 devastadores Zarpayel de Frondavil."}}
D[4121] = {"¡Estás en un aprieto!",{"Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego","","Recuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido","","También tendrás que entregarle a Lexlort los grilletes de torio."}}
D[4122] = {"Grark Lorkrub",{"Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra","","Cuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido."}}
D[4123] = {"El corazón de la montaña",{"Llévale el corazón de la montaña a Maxwort Suprandor en Las Estepas Ardientes."}}
D[4124] = {"El mensajero desaparecido",{"Ve al Bastión Plumaluna y habla con Ginro Mechogar."}}
D[4125] = {"El mensajero desaparecido",{"Localiza el bote del mensajero por la costa de Feralas."}}
D[4126] = {"Hurley Negrálito",{"Llévale la receta de Cebatruenos perdida a Ragnar Cebatruenos en Kharanos."}}
D[4127] = {"Los restos del bote",{"Vuelve al Bastión Plumaluna y enseña a Ginro Mechogar el cuchillo perdido que encontraste."}}
D[4128] = {"Ragnar Cebatruenos",{"Habla con Ragnar Cebatruenos."}}
D[4129] = {"La revelación del cuchillo",{"Lleva el cuchillo perdido a Quintis Jonguja al Bastión Plumaluna."}}
D[4130] = {"Lectura psicométrica",{"Ve al Bastión Plumaluna y habla con Ginro Mechogar."}}
D[4131] = {"Los gnolls Zarpaleña",{"Busca el rastro del mensajero o sus pertenencias en los campamentos de los gnoll Zarpaleña del sur de Feralas."}}
D[4132] = {"Operación: muerte a Forjainquina",{"Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjainquina! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea."}}
D[4133] = {"Vivian Latumba",{"Habla con la taumaturgo oscuro Vivian Latumba en Kargath."}}
D[4134] = {"La receta de Cebatruenos perdida",{"Llévale la receta de Cebatruenos perdida a Vivian Latumba en Kargath."}}
D[4135] = {"Las Galerías Retorcidas",{"Ahora que has descubierto el rastro de Raschal, adéntrate en Las Galerías Retorcidas y encuéntrale... o encuentra lo que quede de él. Según la nota, debes dirigirte al sur de los campamentos de los Zarpaleña."}}
D[4136] = {"Ribbly Llavenrosca",{"Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes."}}
D[4141] = {"Muigin y Larion",{"Recoge 15 pétalos de sangre y ve a ver a Muigin."}}
D[4142] = {"Visita a Gregan",{"Llévale un pétalo de sangre a Gregan Vomitabrebaje de Feralas."}}
D[4143] = {"Bruma del mal",{"Reúne 5 muestras de calima Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro."}}
D[4144] = {"Brote pétalo de sangre"}
D[4145] = {"Larion y Muigin",{"Caza 5 azotadores Pétalo de Sangre, 5 trilladores Pétalo de Sangre, 5 desolladores Pétalo de Sangre y 5 tramperos Pétalo de Sangre para Larion en el Refugio de Marshal."}}
D[4146] = {"Combustible de irradior",{"Entrega el Controlador descargado y 5 muestras de calima Atal'ai a Larion, en el Refugio de Marshal."}}
D[4147] = {"El taller de Marvon",{"Viaja hasta el taller de Marvon Buscarroblones en Trinquete."}}
D[4148] = {"Liquidador de pétalos de sangre",{"Para poder funcionar, el controlador necesita una muestra de la criatura elegida. Ve al cráter y recoge un brote Pétalo de Sangre. Cuando lo tenga podré calibrar el controlador para que funcione con los amiguitos de Muigin..","","Si no fuera tan cabezota ya podríamos estar de camino a casa... ¡Pero hasta entonces tendré que enseñarle que su broma no me molesta del todo!"}}
D[4161] = {"La receta de los Kaldorei",{"Recoge 7 patas de araña pequeña para Zarrin, que está en Dolanaar."}}
D[4181] = {"Ingeniería goblin",{"Si quieres saber más sobre el tema, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón a Gadgetzan."}}
D[4182] = {"La amenaza de los dragonantes",{"Mata 15 estirpes negras, 10 dragauros negros, 4 vermintes negros y 1 draco negro. Vuelve junto a Helendis Rivacuerno cuando hayas acabado la tarea."}}
D[4183] = {"Los verdaderos maestros",{"Viaja a Villa del Lago y entrégale la carta de Helendis Rivacuerno al magistrado Solomon."}}
D[4184] = {"Los verdaderos maestros",{"Ve a Ventormenta para entregar la petición de ayuda de Solomon al Gran Señor Bolvar Fordragon","","Vive en el Castillo de Ventormenta."}}
D[4185] = {"Los verdaderos maestros",{"Habla con el Alto Señor Bolvar Fordragón después de hablar con Lady Katrana Prestor."}}
D[4186] = {"Los verdaderos maestros",{"Lleva el decreto de Bolvar al magistrado Solomon en la Villa del Lago."}}
D[4201] = {"La poción de enamoramiento",{"Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la maestra Nagmara en las Profundidades de Roca Negra."}}
D[4221] = {"Flor del viento corrupta"}
D[4222] = {"Flor del viento corrupta",{"Has encontrado una versión enfermiza y corrupta de lo que parece ser una flor del viento. Los frutos que cuelgan de la planta están podridos y envenenados. Necesita desesperadamente ser atendida para recuperar su estado normal."}}
D[4223] = {"Los verdaderos maestros",{"Habla con el mariscal Maxwell en Las Estepas Ardientes."}}
D[4224] = {"Los verdaderos maestros",{"Habla con John Andrajoso para averiguar el destino del mariscal Windsor y vuelve junto al mariscal Maxwell cuando hayas completado la tarea","","Recuerdas que el mariscal Maxwell comentó algo sobre buscarlo en una cueva hacia el norte."}}
D[4241] = {"El mariscal Windsor",{"Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al mariscal Windsor","","Recuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor."}}
D[4242] = {"Esperanza perdida",{"Dale las malas noticias a mariscal Maxwell."}}
D[4243] = {"Buscando a Memo 01",{"Encuentra a Memo 01 en el Cráter de Un'Goro."}}
D[4244] = {"Buscando a Memo 01",{"Encuentra una envoltura de mitril y reúnete de nuevo con Memo 01 en el Cráter de Un'Goro."}}
D[4245] = {"Buscando a Memo 01",{"Lleva a Memo 01 de vuelta con Karna Tripirrem al Cráter de Un'Goro."}}
D[4261] = {"El espíritu de un Ancestro",{"Escolta a Arei y luego habla con Kayneth Ventoleve que está en Canción del Bosque, en la parte este de Vallefresno."}}
D[4262] = {"Maestro supremo Pyron",{"Mata al Maestro Supremo Pyron y vuelve junto a Jalinda Espiga","","Recuerdas que Jalinda dijo que Pyron guardaba la cantera. Quizás deberías empezar a buscar allí."}}
D[4263] = {"¡Incendius!",{"Encuentra a Lord Incendius en las Profundidades de Roca Negra ¡y acaba con él!"}}
D[4264] = {"Una nota arrugada",{"Puede que acabes de toparte con algo que le interesaría ver al mariscal Windsor. Puede que haya esperanza, después de todo."}}
D[4265] = {"Liberado de la colmena",{"Libera a Raschal de la vaina de los Zukk'ash","","Vuelve al Bastión Plumaluna con Ginro Mechogar e infórmale de que Raschal está bien."}}
D[4266] = {"La bienvenida de un héroe",{"Habla con Shandris Plumaluna del Bastión Plumaluna."}}
D[4267] = {"El alzamiento de los silítidos",{"Lleva el informe de Raschal a Gracina Poderespíritu a Darnassus."}}
D[4281] = {"Una entrega en Thalanaar",{"Lleva el paquete sin entregar a Díscolo Falfindel a Thalanaar."}}
D[4282] = {"Una esperanza hecha trizas",{"Devuélvele al mariscal Windsor la información perdida","","El mariscal Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjainquina."}}
D[4283] = {"¡CINCUENTA! ¡SÍ!",{"Oralius quiere 50 medallones Roca Negra. Con toda probabilidad encontrarás estos medallones en los orcos de Las Estepas Ardientes."}}
D[4284] = {"Cristales de poder",{"Recoge 7 cristales de poder de cada color: rojo, azul, amarillo y verde. Llévaselos a J.D. Collie en el Refugio de Marshal."}}
D[4285] = {"La Torre de cristal del Norte",{"Descubre la localización de la Torre de Cristal del Norte en el Cráter de Un'Goro."}}
D[4286] = {"Buena mercancía",{"Viaja a las Profundidades de Roca Negra y recupera 20 riñoneras Hierro Negro. Vuelve junto a Oralius cuando hayas completado esta tarea. Se da por sentado que los enanos Hierro Negro de las Profundidades de Roca Negra llevan estos inventos de riñoneras."}}
D[4287] = {"La Torre de cristal del Este",{"Descubre la localización de la Torre de Cristal del Este en el Cráter de Un'Goro."}}
D[4288] = {"La Torre de cristal del Oeste",{"Descubre la localización de la Torre de Cristal del Oeste."}}
D[4289] = {"Los simios de Un'Goro",{"Llévale 2 pelambres de gorila de Un'Goro, 2 pelambres de vapuleador de Un'goro y 2 pelambres de tronador de Un'Goro a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro."}}
D[4290] = {"La comida de Lar'korwi",{"Encuentra la última presa muerta de Lar'korwi y roba un trozo de trillanodonte muerto, y después ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro."}}
D[4291] = {"Un aroma irresistible para Lar'korwi",{"Llévale 2 glándulas de feromonas de ravasaurio a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro."}}
D[4292] = {"El cebo para Lar'korwi",{"Utiliza el contenido de la faltriquera de Torwa para atraer la presencia de Lar'korwi y derrótalo. Después llévale la cabeza de Lar'korwi a Torwa Abrecaminos, que está cerca de la entrada del Cráter de Un'Goro."}}
D[4293] = {"Muestras de babosa...",{"Recoge muestras de babosa de Frondavil de cualquiera de las babosas que encuentres en Frondavil. Después utiliza el equipo de estudio que el químico Fuely tiene al lado, en Entrañas, para ver qué muestras están más corruptas. Llévale 5 de las muestras de Frondavil corruptas que encuentres al químico Fuely."}}
D[4294] = {"... y unos mocos",{"Recoge muestras de babosa de Un'Goro de cualquiera de las babosas que encuentres en el Cráter de Un'Goro. Después utiliza el equipo de estudio que el químico Fuely tiene al lado, en Entrañas, para ver qué muestras son más puras. Llévale 5 de las muestras de Un'Goro puras que encuentres al químico Fuely."}}
D[4295] = {"La cerveza de Sinrosca",{"¡Oh, cerveza! ¡¡Mataría por algo de cerveza Hierro Negro!! ¡Rápido, que me estoy poniendo sobrio! Lo sé porque la sobriedad me nubla la vista... ¡y eso hace que te parezcas al <raza> que maté la semana pasada!"}}
D[4296] = {"La tablilla de los Siete",{"Llévale la trascripción de tablilla a Maxwort Suprandor en Las Estepas Ardientes."}}
D[4297] = {"Comida para el bebé",{"Lleva 5 costillas de acechador melenargenta a Agnar Domabestias a las Tierras del Interior."}}
D[4298] = {"El amor parental",{"Habla con Agnar Domabestias en las Tierras del Interior."}}
D[4300] = {"Armas con filo de hueso",{"Lleva 8 garras blancas de ravasaurio a Jes'rimon a Orgrimmar."}}
D[4301] = {"El poderoso U'cha",{"Llévale la pelambre de U'cha a Torwa Abrecaminos, que está a la entrada del Cráter de Un'Goro."}}
