D[4492] = {"¡Perdido!",{"Encuentra a Ringo en la Cresta del Penacho en Llamas."}}
D[4493] = {"La marcha de los silítidos",{"Ve a Gadgetzan y habla con el alquimista Morterozugg."}}
D[4494] = {"La marcha de los silítidos",{"Habla con el alquimista Morterozugg en Gadgetzan."}}
D[4495] = {"Un buen amigo",{"Encuentra a Iverron cerca de la cueva que hay al norte."}}
D[4496] = {"Que jungla tan chunga",{"Llévale una glándula secretora de olor Gorishi y 5 muestras de la tierra de Un'Goro al alquimista Morterozugg de Gadgetzan."}}
D[4501] = {"Cuidado con los pterrordáctilos",{"Mata a 10 pterrordáctilos y a 15 pterrordáctilos demenciados. Cuando lo hayas hecho habla con Spraggle Habitus en el Refugio de Marshal."}}
D[4502] = {"Actividad volcánica",{"Lleva 9 muestras de ceniza de los elementales de fuego del Cráter de Un'Goro a Liv Rizzlefix a Trinquete."}}
D[4503] = {"El aparato volador de Shizzle",{"Recoge 8 escamas de diemetradón palmeadas y 8 escamas de pterrordáctilo palmeadas para Shizzle, en el Refugio de Marshal."}}
D[4504] = {"Superpegajoso",{"Reúne 12 muestras de alquitrán muy pegajoso para Tran'rek de Gadgetzan."}}
D[4505] = {"El pozo de la corrupción",{"Recoge una muestra de agua corrupta de la Poza de la Luna de los sátiros Fuego de Jade y llévasela a Winna Riessgo al Puesto del Veneno."}}
D[4506] = {"Dientes de sable corruptos",{"Lleva el gatito de Winna a la Poza de la Luna corrupta, libéralo allí y luego llévaselo a Winna","","Cuando hayas vuelto con Winna, haz clic en el felino para dárselo."}}
D[4507] = {"El señuelo atrapa a la reina",{"Derrota a la reina de la colmena Gorishi cuando hayas conseguido que salga al exterior","","Llévale el cerebro de la reina Gorishi al alquimista Morterozugg de Gadgetzan."}}
D[4508] = {"La calma que precede a la tormenta",{"Llévale el informe de Un'Goro de Morterozugg a Gracina Poderespíritu, que está en Darnassus."}}
D[4509] = {"La calma que precede a la tormenta",{"Llévale el informe de Un'Goro de Morterozugg a Zilzibin Tambor Sabio, que está en Orgrimmar."}}
D[4510] = {"La calma que precede a la tormenta",{"Lleva el vale del banco a Idriana, al banco de Darnassus."}}
D[4511] = {"La calma que precede a la tormenta",{"Lleva el vale a Karus al banco de Orgrimmar."}}
D[4512] = {"Un largo camino para unas babosas",{"Consigue 6 jarros llenos de moco maldito y 6 jarros llenos de moco corrupto pra Laris Cadenapartida en Forjaz."}}
D[4513] = {"Un largo camino para unas babosas",{"Lleva 10 tarros de muestra pura a Laris Cadenartida a Forjaz","","Si no los encuentras, habla con Laris."}}
