D[4542] = {"Mensaje para el Poblado Viento Libre",{"Entrégale el mensaje urgente a Vigiarisco Cuernolargo en el Poblado Viento Libre."}}
D[4561] = {"Pruebas de impureza: Cráter de Un'Goro",{"Coges una muestra de babosa del Cráter de Un'Goro y colocas un poco en los diversos tubos y vasos de precipitados que se encuentran sobre la mesa. A medida que todo empieza a hervir, la babosa cambia de color. Cuando el proceso comienza a detenerse y los líquidos dejan de bullir, ves una placa de Petri que contiene tus muestras de babosa de Un'Goro purificadas y algunos restos."}}
D[4581] = {"Kayneth Ventoleve",{"Llévale la nota de Shindrell a Kayneth Ventoleve en Canción del Bosque."}}
D[4601] = {"¡El Destellamatic 5200!",{"Inserta un objeto sucio en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano."}}
D[4602] = {"¡El Destellamatic 5200!",{"Inserta un objeto sucio en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano."}}
D[4603] = {"El Destellamatic en acción",{"El Destellamatic 5200 parece estar esperando un objeto sucio que limpiar y 3 monedas de plata para activarse."}}
D[4604] = {"El Destellamatic en acción",{"El Destellamatic 5200 parece estar esperando un objeto sucio que limpiar y 3 monedas de plata para activarse."}}
D[4605] = {"¡El Destellamatic 5200!",{"La máquina se para tan bruscamente como había arrancado. Se oye un \"ping\" y se abre la boca de la máquina. Dentro del Destellamatic 5200 hay una cajita con un lazo; parece que envuelve para regalo además de limpiar","","Solo hay una forma de saber si el objeto está bien limpio..."}}
D[4606] = {"¡El Destellamatic 5200!",{"La máquina se para tan bruscamente como había arrancado. Se oye un \"ping\" y se abre la boca de la máquina. Dentro del Destellamatic 5200 hay una cajita con un lazo; parece que envuelve para regalo además de limpiar","","Solo hay una forma de saber si el objeto está bien limpio..."}}
D[4621] = {"¡Adelante, almirante!",{"Mata al maestro de flota Cuernomarino y al Barón Revilgaz de la Bahía del Botín y, a continuación, vuelve a reunirte con el maestro de flota Firallon abordo del Velo Carmesí, cerca de la costa de la Vega de Tuercespina."}}
D[4641] = {"Tu lugar en el mundo",{"Habla con Gornek. Recuerda que Kaltunk marcó en tu mapa su ubicación y que te mencionó que Gornek reside en El Cubil, un edificio que está al oeste."}}
D[4642] = {"Fusión de influencias",{"Llévale una muestra del moco fusionado al químico Fuely de Entrañas."}}
D[4661] = {"Pruebas de Corrupción: Frondavil",{"Coges una muestra de babosa de Frondavil y colocas un poco en los diversos tubos y vasos de precipitados que se encuentran sobre la mesa. A medida que todo empieza a hervir, la babosa cambia de color. Cuando el proceso comienza a detenerse y los líquidos dejan de bullir, ves una placa de Petri que contiene tus muestras de babosa de Frondavil modificadas y algunos restos."}}
