D[4740] = {"SE BUSCA: ¡Viscoso!",{"Encuentra y mata al múrloc conocido como Viscoso. Se cree que la criatura está defendiendo el emplazamiento múrloc al sur de Auberdine, cerca del agua","","Informa de la muerte de Viscoso a la centinela Glynda Nal'Shea, en Auberdine."}}
D[4741] = {"Guardianes salvajes",{"Trull Fallarruina de Frondavil quiere que caces 13 lechubestias lunadón."}}
D[4742] = {"El sello de ascensión",{"Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el sello de ascensión sin adornar a Vaelan","","Los generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el Alto Señor Omokk de los Cumbrerroca y el Señor Supremo Vermiothalak de los Hacha de Sangre."}}
D[4743] = {"El Sello de ascensión",{"Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad","","Este es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!"}}
D[4761] = {"Thundris Tejevientos",{"Ve a Auberdine y habla con Thundris Tejevientos."}}
D[4762] = {"El Río Fonroca",{"Viaja al norte de Auberdine hasta la primera cascada del Río Fonroca y recoge una muestra de agua","","Vuelve a Auberdine a buscar a Thundris Tejevientos con la muestra del Río Fonroca."}}
D[4763] = {"La corrupción de los Bosque Negro",{"Llena el cuenco purificador vacío en la Poza de la Luna de Auberdine","","Recoge una muestra de fruta, nueces y grano del campamento del norte de los fúrbolg Bosque Negro","","Mezcla todo en el cuenco, llévalo al campamento norte y colócalo cerca de la hoguera más cercana al Río Fonroca; así convocarás al sátiro corruptor","","Coge el dije de corrupción y llévaselo a Thundris Tejevientos a Auberdine."}}
D[4764] = {"El Broche de Equipasino",{"Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes."}}
D[4765] = {"Entrega a Bonacresta",{"Llévale el cajón de Crestabuena a Remington Crestabuena en Ventormenta."}}
D[4766] = {"Mayara Alasol",{"Habla con Mayara Alasol en Las Estepas Ardientes."}}
D[4767] = {"Jinete del viento",{"Consigue 10 huevos de dracoleón Nido Alto para Elu en el Poblado Viento Libre."}}
D[4768] = {"La tablilla de Rocanegra",{"Llévale la tablilla de Rocanegra a la maga oscura Vivian Latumba en Kargath."}}
D[4769] = {"Vivian Latumba y la tablilla de Rocanegra",{"Habla con la maga oscura Vivian Latumba."}}
D[4770] = {"De vuelta a casa",{"Saca a Pao'ka Velocimontés de Nido Alto y después habla con Motega Pirocabello en Campamento del Tramo Blanco."}}
D[4771] = {"Gambito del Alba",{"Coloca el Gambito del Alba en la Sala de la Visión de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink."}}
D[4781] = {"Los componentes para la toga de sangre dorada encantada",{"Llévale un lingote de oro a Xizk Cortefino en la Vega de Tuercespina."}}
D[4782] = {"Los componentes para la toga de sangre dorada encantada",{"Regresa junto a Menara Nadiz en Los Baldíos."}}
D[4783] = {"Los componentes para la toga de sangre dorada encantada",{"Llévale 10 viales de sangre Odio Feroz y 1 piedra Infernal inferior a Menara Nadiz en Los Baldíos."}}
D[4784] = {"Los componentes para la toga de sangre dorada encantada",{"Llévale unos hilos finos de oro, 2 trozos de ascuas humeantes y 1 fragmento de alma a Menara Nadiz en Los Baldíos."}}
D[4785] = {"Hilo de oro refinado",{"Aquí tienes, <nombre>. Y saluda a Menara de nuestra parte","","Tenemos grandes esperanzas contigo. Quizás cuando la Legión caiga de rodillas, se pronunciará tu nombre en voz alta y se alabará tu poder. ¡Cómo ansío ese momento!"}}
D[4786] = {"Toga terminada",{"Espera a que Menara Nadiz complete tu túnica y vuelve entonces a hablar con ella."}}
D[4787] = {"El huevo antiguo",{"Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris."}}
D[4788] = {"Las últimas tablillas",{"Llévale la quinta y sexta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris."}}
D[4801] = {"E'ko de Sable de Hielo"}
D[4802] = {"E'ko de los Nevada",{"En Cuna del Invierno combatirás con unas criaturas descarriadas conocidas como los furbolgs Nevada. Siguiendo los deseos de su líder se han hecho increíblemente fuertes. Si quieres el poder de los Nevada tráeme el E'ko que encontrarás en ellos","","Recuerda, debes tener el Alijo de Mau'ari en tu inventario si quieres conseguir E'ko."}}
D[4803] = {"E'ko Dentoesquirla",{"En Cuna del Invierno encontrarás grandes osos con unas pieles extremadamente duras y gruesas. Los osos dentoesquirla obtienen mucha protección de lo que pueden resistir. Si quieres resistencia al Fuego, tráeme el E'ko que encontrarás en los dentoesquirla","","Recuerda, debes tener el Alijo de Mau'ari en tu inventario para poder obtener E'ko."}}
D[4804] = {"E'ko Orvallo",{"En Cuna del Invierno combatirás con unas criaturas voladoras llamadas quimeras. Esas bestias pueden dominar la magia de hielo. Si quieres ganar resistencia a la Escarcha tráeme el E'ko que encontrarás en ellas","","Recuerda, debes tener el Alijo de Mau'ari en tu inventario para poder conseguir E'ko."}}
D[4805] = {"E'ko de los Cardo Nevado"}
D[4806] = {"E'ko de los Machacahielo",{"En Cuna del Invierno combatirás con unos enormes gigantes de hielo llamados Machacahielo. Suyos son el poder y la fuerza más puros. Si quieres ganar la fuerza del Machacahielo tráeme el E'ko que encontrarás en ellos","","Recuerda, debes tener el Alijo de Mau'ari en tu inventario si quieres conseguir E'ko."}}
D[4807] = {"E'ko de lechúcico salvaje",{"En Cuna del Invierno, combatirás con unas criaturas que parecen tener una habilidad mágica innata. Los lechúcicos pueden utilizar magia muy poderosa. Si quieres aumentar tu intelecto tráeme el E'ko que encontrarás en las lechubestias","","Recuerda, debes tener el Alijo de Mau'ari en tu inventario si quieres obtener E'ko."}}
D[4808] = {"Felnok Acerovera",{"Entrégale la carta de Tinkee a Felnok Acerovera."}}
D[4809] = {"Cuernos de Orvallo",{"Llévale 8 cuernos de quimera del Orvallo intactos a Felnok Acerovera."}}
D[4810] = {"Vuelve con Tinkee",{"Llévale el paquete de Felnok a Tinkee Vaporio en Las Estepas Ardientes."}}
D[4811] = {"El cristal rojo",{"Viaja al este de Auberdine y busca un gran cristal rojo en la zona montañosa que hay al este de Costa Oscura. Vuelve a Auberdine e informa de lo que has encontrado a la centinela Glynda Nal'Shea."}}
D[4812] = {"Agua en cascada",{"Llena el tubo de agua vacío en la Poza de la Luna de Auberdine y luego examina el cristal rojo a lo largo de la pared montañosa oriental de Costa Oscura."}}
D[4813] = {"Los trozos del interior",{"Vuelve a Auberdine e informa de lo que has averiguado a la centinela Glynda Nal'Shea."}}
D[4821] = {"Un huevo extraño",{"Devuélvele el huevo extraño a Hagar Tronapezuña, que está en el Poblado Viento Libre."}}
D[4822] = {"¡Quiero un heladooooo!",{"Consigue helado de fresa para tu pupilo. Parece que el favorito del muchacho es el helado de Tigule y Foror."}}
D[4841] = {"Apaciguar al centauro",{"Mata a 12 exploradores Galak, 10 vaqueros Galak y 6 cazavientos Galak, y después ve a ver de nuevo a Vigiarisco Cuernolargo al Poblado Viento Libre."}}
D[4842] = {"Fuentes extrañas",{"Sigue las indicaciones de Donova Cubilnevado y vuelve a informarle."}}
D[4861] = {"Lechúcico salvaje iracundo",{"Localiza el campamento arrasado y los suministros de Jaron Tallapiedras en la parte sur de Cuna del Invierno."}}
D[4862] = {"Bestia amaestrada",{"Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler","","Yo diría que se pueden encontrar estos huevos cerca de arañas."}}
D[4863] = {"Lechúcico salvaje iracundo",{"Encuentra el carro destrozado de Jaron Tallapiedras."}}
D[4864] = {"Lechúcico iracundo",{"Recoge de la nieve los Suministros de Jaron y encuentra al lechúcico salvaje que robó el amuleto del que te habló Jaron","","Lleva los Suministros de Jaron y el Amuleto de plumas azules a Jaron Tallapiedras en el refugio de Cuna del Invierno."}}
D[4865] = {"Venganza",{"Cuéntale a Motega Pirocabello lo que has descubierto."}}
D[4866] = {"La leche de la madre",{"En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti."}}
D[4867] = {"Urok Aullapocalipsis",{"Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh."}}
D[4881] = {"Complot de asesinato",{"Avisa a Kanati Nubegris, que está en el Campamento del Tramo Blanco, acerca de la conspiración para acabar con su vida."}}
D[4882] = {"Guardar un secreto",{"Lleva el Collar de plumas azules a Trull Fallarruina en el Puesto del Veneno."}}
D[4883] = {"Guardar un secreto",{"Lleva el Collar de plumas azules a Nara Bravacrín."}}
D[4901] = {"Guardianes del altar",{"Protege a Ranshalla mientras intenta reactivar el Altar de Elune. Informa sobre tus descubrimientos a Erelas Cieloámbar de Aldea Rut'theran."}}
D[4902] = {"Lechúcico salvaje de Elune",{"Habla con el archidruida Fandral Corzocelada de Darnassus."}}
D[4903] = {"La orden del Señor de la Guerra",{"Mata al Alto señor Omokk, al maestro de guerra Voone y al Señor Supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión."}}
D[4904] = {"Al fin libre",{"Saca a Lakota Murmullo de Cumbre de la Nube Negra y después habla con Thalia Pielámbar, que está en el Poblado Viento Libre."}}
D[4906] = {"Más corrupción",{"Eridan Vientoazul de Frondavil quiere que mates a 8 clamainfernos Fuego de Jade, 8 traidores Fuego de Jade, 8 timadores Fuego de Jade y a Xavaric. Vuelve con Eridan cuando lo hayas hecho."}}
D[4907] = {"Tinkee Vaporio",{"Habla con Tinkee Vaporio."}}
D[4921] = {"Perdida en la batalla",{"Encuentra a la esposa de Mankrik y llévala a El Cruce."}}
D[4941] = {"La sabiduría de Eitrigg",{"Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall","","Recuerdas haber visto a Eitrigg en la Cámara de Thrall."}}
D[4961] = {"La purificación del orbe de Orahil",{"Mata al demonio del orbe y luego habla con Tabetha."}}
D[4962] = {"Fragmento de can manáfago",{"Coge el rubí de Felhas y úsalo en uno de los canes manáfagos de Desolace. Cuando lo consigas, llévale el rubí de Felhas y el espíritu del can manáfago capturado a Menara Nadiz en Los Baldíos."}}
D[4963] = {"Fragmento de infernal",{"Coge la esmeralda de Infus y úsala en uno de los infernales de Desolace. Cuando lo consigas, llévale la esmeralda de Infus y el espíritu del infernal capturado a Menara Nadiz en Los Baldíos."}}
D[4964] = {"El orbe completo de Dar'Orahil",{"Espera a Menara Nadiz para completar el orbe de Dar'Orahil y vuelve entonces a hablar con ella."}}
D[4965] = {"El conocimiento del orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4966] = {"Defensa de Kanati Nubegris",{"Defiende a Kanati Nubegris contra el ataque de los centauros."}}
D[4967] = {"El conocimiento del orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4968] = {"El conocimiento del orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4969] = {"El conocimiento del Orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4970] = {"Provisiones Sable de Hielo",{"Recoge 5 carnes de Dentoesquirla y 5 carnes de Orvallo para Rivern Ventogélido de Cuna del Invierno."}}
D[4971] = {"Una cuestión de tiempo",{"Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales","","Mata a 10 parásitos temporales y devuélvele el desplazador temporal a Cromi en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4972] = {"Contar el tiempo",{"Localiza 5 relojes de Andorhal, los encontrarás en cajas fuertes entre las ruinas de la ciudad. Cuando los tengas regresa con Cromi, en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4973] = {"Contar el tiempo",{"Localiza 5 relojes de Andorhal entre las ruinas de la ciudad y llévaselos a Cromi, en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4974] = {"¡Por la Horda!",{"Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar."}}
D[4975] = {"El orbe completo de Noh'Orahil",{"Espera a Menara Nadiz para completar el orbe de Noh'Orahil y vuelve entonces a hablar con ella."}}
D[4976] = {"Devolver el orbe purificado",{"Llévale el orbe infernal limpio a Menara Nadiz en Los Baldíos."}}
D[4981] = {"La espía Bijou",{"Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou."}}
D[4982] = {"Las pertenencias de Bijou",{"Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad."}}
D[4983] = {"El informe de reconocimiento de Bijou",{"Llévale el informe de reconocimiento de Bijou al maestro mayor Lexlort en Kargath."}}
D[4984] = {"La naturaleza también sufre",{"Destruye 8 lobos malsanos y regresa con Mulgris Riohondo en El Tormento, en las Tierras de la Peste del Oeste."}}
D[4985] = {"La naturaleza también sufre",{"Destruye 8 pardos malsanos y regresa con Mulgris Riohondo en El Tormento, en las Tierras de la Peste del Oeste."}}
D[4986] = {"Rama de roble con inscripciones",{"Según la magia con la que está encantada La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion en Darnassus. Pide ayuda a uno de los druidas que encontrarás allí."}}
D[4987] = {"Rama de roble con inscripciones",{"Según la magia con la que está encantada de La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion de Cima del Trueno. Pide ayuda a uno de los druidas que encontrarás allí."}}
D[5001] = {"Las pertenencias de Bijou",{"Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!"}}
D[5002] = {"Un mensaje para Maxwell",{"Viaja a Las Estepas Ardientes y dale la información sobre Bijou al mariscal Maxwell."}}
D[5021] = {"Más vale tarde que nunca",{"Entre lamentos, la mujer fantasmal recordaba tener que entregar un paquete. Según ella estaba junto a su caballo. No puedes entender dónde está el caballo o dónde había que entregar el paquete."}}
D[5022] = {"Más vale tarde que nunca",{"Consulta con los agentes reales de Ventormenta para averiguar el paradero de una tal Emma Piedra Mácula. Suele haber un oficial del censo en el Ayuntamiento."}}
D[5023] = {"Más vale tarde que nunca",{"Consulta con los supervisores reales de Entrañas para averiguar el paradero de Jeremiah Piedra Mácula. Suele haber un oficial del censo junto a la oficina de registro de hermandades y tabardos."}}
D[5041] = {"Suministros para El Cruce",{"Encuentra los cajones de suministros de El Cruce y devuélveselos a Thork en Los Baldíos."}}
D[5042] = {"La fuerza de Agamaggan",{"Necesitaré 4 esquirlas de sangre si quieres tener la fuerza de Agamaggan, <raza>","","Si se te concediera esta bendición, tus enemigos se encogerán ante tu fuerza","","¡Los más gloriosos guerreros Crines de Acero están imbuidos de tal poder!"}}
D[5043] = {"La agilidad de Agamaggan",{"Se dice que la precisión de los mejores exploradores de mis tribus no tiene parangón y ningún granuja <gruñe> estaría a la altura de su rapidez en el combate","","Tráeme 4 esquirlas de sangre y haré que seas aún más ágil que cualquier jabaespín."}}
D[5044] = {"La sabiduría de Agamaggan",{"El chamán y los geománticos de las tribus jabaespín <gruñe> recurren a la fuerza de Agamaggan para que les ayude en la batalla y en sus rituales, <raza>","","Si quieres el poder adicional de la bendición de Agamaggan con tus hechizos, tráeme 4 esquirlas de sangre y Quebrantadientes te ayudará."}}
D[5045] = {"Fortaleza de espíritu",{"Todos los tipos de <clase> necesitan fortaleza de espíritu. Te empuja a mayores proezas cuando se ha perdido toda esperanza. Es algo a lo que están acostumbrados los Crines de Acero. Somos una tribu espiritual, estamos más orgullosos de nuestra conexión con Agamaggan que de nuestras proezas en la batalla","","Tráeme 4 esquirlas de sangre y bendeciré tu espíritu para el combate."}}
D[5046] = {"Cerropiel",{"Todos los que <gruñe> entran en combate necesitan protección. Sus huesos han de ser resistentes. Su piel, curtida <Gruñe> Mi tribu sabe esto muy bien y para reforzar la protección natural de nuestras púas y piel, <gruñe> con frecuencia recurrimos a Agamaggan para que nos proteja de los daños antes de entrar en combate","","Tráeme 4 fragmentos ensangrentados <gruñe> y te otorgaré la misma protección."}}
D[5047] = {"¡Finkle Unicornín, a tu servicio!",{"Habla con Malyfous Martilloscuro en Vista Eterna."}}
D[5048] = {"El buen carácter de Emma",{"Encuentra a la Vieja Emma en Ventormenta y descubre si realmente es Emma Piedra Mácula. Si lo es, quizás quiera el paquete que Janice Piedra Mácula hizo para ella."}}
D[5049] = {"La depre de Jeremiah",{"Encuentra a Jeremiah Payson en Entrañas y averigua si en realidad es Jeremiah Piedra Mácula. Si es así, quizás quiera el paquete que Janice Piedra Mácula preparó para él."}}
D[5050] = {"Talismán de buena suerte",{"Devuelve a Janice Piedra Mácula en las Tierras de la Peste del Oeste su Medio talismán de buena suerte."}}
D[5051] = {"Dos mitades hacen una",{"Localiza la otra mitad del talismán de la suerte en algún lugar de la Granja de Piedra Mácula, en las Tierras de la Peste del Oeste, y recomponlo","","Dale el talismán de la suerte a Janice Piedra Mácula en la Granja de Piedra Mácula, en las Tierras de la Peste del Oeste."}}
D[5052] = {"Esquirlas de sangre de Agamaggan",{"Llévale una esquirla de sangre a Quebrantadientes en el Campamento Taurajo en Los Baldíos","","Reúne más esquirlas de sangre si quieres que te bendiga con el poder de Agamaggan."}}
D[5054] = {"Ursius de los Dentoesquirla",{"Ventisca Pezumbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Ursius."}}
D[5055] = {"Brumerán de los Orvallo",{"Ventisca Pezumbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Brumerán."}}
D[5056] = {"Shi-Rotam",{"Ventisca Pezumbría de Vista Eterna, en Cuna del Invierno, quiere que acabes con Shi-Rotam."}}
D[5057] = {"Esfuerzos del pasado",{"Lleva la Señal de Ventisca Pezumbría a Melor Pezuñapétrea de Cima del Trueno."}}
D[5058] = {"El diario de la señorita Dalson",{"Un diario con páginas que comienzan a amarillear descansa abierto por la última entrada:","","\"No sé lo que va a ocurrir ahora que Harold se ha transformado. Gasté todas mis fuerzas en arrastrarlo hasta el único lugar que pude encontrar y en el que pudiera quedar encerrado. Escondí en mí la llave y ruego porque funcione..","","Espero poder salir de aquí, pero necesito dinero para hacerlo. Creo que todas nuestras cosas están en el armario... y ahora que lo pienso, ¿no tiene Harold la llave con él?","","Descansaré, estoy terriblemente cansada.\""}}
D[5059] = {"Encierro",{"La puerta de la letrina ha comenzado a astillarse en los bordes del marco, como si hubieran intentado forzarla varias veces y con insistencia. En este momento está cerrada desde fuera","","¡Cuando mueves la puerta oyes un gemido gutural en el interior! Sea lo que sea, no parece muy amistoso."}}
D[5060] = {"Encierro",{"Tienes ante ti un armario extremadamente fuerte y robusto, cerrado con un candado. La parte delantera del armario tiene marcas y arañazos muy profundos. Podría pensarse que son el resultado de numerosos y violentos intentos fallidos por desvelar los secretos que encierra el armario","","Si quieres abrirlo tendrás que encontrar la llave."}}
D[5061] = {"Forma acuática",{"Vuelve a Darnassus y enséñale el colgante del león marino a Mathrengyl Garroso."}}
D[5062] = {"El fuego Sagrado",{"Recoge 10 montones de pitas incendiarias y después pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno."}}
D[5063] = {"Almete del Sabio Escarlata",{"Para crear el Almete del Sabio Escarlata deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 5 costuras desgarradas de abominación; 8 cristales Arcanos; 5 hilos escarlata encantados","","También tendrás que pagar 50 piezas de oro para la elaboración del almete."}}
D[5064] = {"Espiando a los Tótem Siniestro",{"Localiza y reúne las 3 notas secretas que hay en Cumbre de la Nube Negra."}}
D[5065] = {"Las tablillas perdidas Mosh'aru",{"Llévale la tercera y cuarta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris."}}
D[5066] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al comandante Ashlam Puñovalor. Su campamento base está situado en el Campamento del Orvallo, al norte de las Montañas de Alterac."}}
D[5067] = {"Leotardos de Arcana",{"Para crear los leotardos arcana deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 5 costuras desgarradas de abominación; 5 barras de arcanita; 5 líquidos de embalsamar de Levescarcha","","También tendrás que pagar 50 piezas de oro para la elaboración del almete."}}
D[5068] = {"Coraza Sed de Sangre",{"Para crear la coraza Sed de Sangre deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 10 costuras desgarradas de abominación; 5 barras de arcanita; 5 pieles de Sombra","","También tendrás que pagar 50 piezas de oro para la elaboración del almete."}}
D[5081] = {"La misión de Maxwell",{"Viaja a la Cumbre de Roca Negra y destruye al maestro de guerra Voone, al alto señor Omokk y al Señor Supremo Vermiothalak. Vuelve junto al mariscal Maxwell cuando hayas acabado tu trabajo."}}
D[5082] = {"La amenaza de los Nevada",{"Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 vigías del cubil Nevada y 8 totémicos Nevada."}}
D[5083] = {"Aguardiente de los Nevada",{"Lleva el Frasco vacío de aguardiente a Donova Cubilnevado de Cuna del Invierno."}}
D[5084] = {"Sucumbir a la corrupción",{"Busca una pista en el campamento fúrbolg Muertobosque en el norte de Frondavil."}}
D[5085] = {"Baba misteriosa",{"Informa sobre tus descubrimientos a Donova Cubilnevado."}}
D[5086] = {"Horrores tóxicos",{"Recoge 3 gotitas horror tóxico para Donova Cubilnevado de Cuna del Invierno."}}
D[5087] = {"Corredores Nevada",{"Encuentra a los corredores Nevada y detenlos antes de que entreguen su cargamento en Poblado Nevada."}}
D[5088] = {"Arikara",{"Mata a Arikara. Llévale sus restos y el polvo de incendiaria a Motega Pirocabello al Campamento del Tramo Blanco como prueba de tus actos."}}
D[5089] = {"Orden del general Drakkisath",{"Llévale la orden del general Drakkisath al mariscal Maxwell en Las Estepas Ardientes."}}
D[5090] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al comandante Ashlam Puñovalor; su campamento base está en Campamento del Orvallo, al norte de las Montañas de Alterac."}}
D[5091] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac."}}
D[5092] = {"Despejando el camino",{"Mata 10 despellejadores esqueléticos y 10 necrófagos esclavizantes en la Colina de las Penas","","Vuelve con el comandante Ashlam Puñovalor en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5093] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas."}}
D[5094] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas."}}
D[5095] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas."}}
D[5096] = {"Distracción Escarlata",{"Adéntrate en el campamento base de la Cruzada Escarlata entre el Campo de Piedramácula y el Llanto de Dalson y destruye su tienda de mando","","Coloca el estandarte de la Plaga en el campamento y vuelve con el Sumo Ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5097] = {"Todas las atalayas",{"Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla","","Cuando estén marcadas las cuatro atalayas devuelve la antorcha de aviso al comandante Ashlam Puñovalor del Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5098] = {"Todas las atalayas",{"Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla","","Cuando estén marcadas las cuatro atalayas, devuelve la antorcha de aviso al Sumo Ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5101] = {"Lee's Ultimate Test Quest... of Doom!",{"Mata 6 ovejas para Benny ¡y corre como el demonio!","","Es una broma... Lo de correr como un demonio."}}
D[5102] = {"Muerte al general Drakkisath",{"Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath. Vuelve junto al mariscal Maxwell cuando hayas acabado tu trabajo."}}
D[5103] = {"Muerte abrasadora",{"Alguien en este mundo debe de saber qué hacer con estos guanteletes. ¡Suerte!"}}
D[5121] = {"Gran Jefe Nevada",{"Donova Cubilnevado de Cuna del Invierno quiere que derrotes al Gran Jefe Nevada."}}
D[5122] = {"El medallón de Fe",{"El poder de esta capilla me da la fuerza para resistir la corrupción que habita en mi corazón. Si cedo, me convertiré en un caballero de la muerte. Pero hay un medallón, el medallón de fe, que me dará la fuerza que necesito para partir","","Por favor, <nombre>, recupera el medallón. Está en manos de Malor el Fanático, un miembro demente de la Hermandad Escarlata, que reside en las profundidades del Bastión Escarlata en Stratholme occidental."}}
D[5123] = {"La pieza final",{"Lleva el Diario mal escrito a Donova Cubilnevado de Cuna del Invierno."}}
D[5124] = {"Guanteletes de placas ígneas",{"Lleva a Malyfous Martilloscuro 6 barras de torio encantado, 2 esencias de fuego y 4 rubíes estrellados. También tendrás que entregarle tus guanteletes de placas sin templar."}}
D[5125] = {"La estimación de Aurius",{"<nombre>, me estoy muriendo... pero mi alma está salvada. Por eso, te debo más de lo que jamás podré expresar. Por favor, acepta esto, ¡y sigue luchando... valiente <clase>!"}}
D[5126] = {"La historia de Lorax",{"Habla con Lorax. Escucha todo lo que tiene que decirte."}}
D[5127] = {"La forja demoníaca",{"Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pico manchado de sangre sobre su cadáver. Cuando hayas absorbido su alma, el pico estará manchado de alma","","También debes encontrar la coraza cubierta de runas sin forjar","","Lleva el pico manchado de alma y la coraza cubierta de runas sin forjar a Lorax en Cuna del Invierno."}}
D[5128] = {"Las palabras del Gran Jefe",{"Lleva el Diario mal escrito a Kelek Guardacielo en el sur de Frondavil."}}
D[5141] = {"Peletería dragontina",{"Consigue 2 corazas resistentes de escórpido, 2 guantes resistentes de escórpido, y 10 escamas de dragón desgastadas para Peter Galen, en Azshara","","Si completas esta misión tendrás acceso al arte de la peletería dracónica","","Si lo haces, también dejarás de tener acceso a la peletería elemental y tribal. Tienes que asegurarte de querer seguir este camino antes de completarla."}}
D[5142] = {"La pequeña Pamela",{"Encuentra a Pamela Rutagrana."}}
D[5143] = {"Peletería tribal",{"Lleva 1 jubón de cuero salvaje y 1 casco de cuero salvaje a Caryssia Cazaluna a Feralas","","Si completas esta misión, tendrás acceso a las artes de Peletería tribal","","Si lo haces, no podrás aprender peletería dragontina ni peletería elemental; asegúrate de que este es el camino que deseas seguir antes de completar la misión."}}
D[5144] = {"Peletería elemental",{"Lleva 2 corazones de fuego, 2 globos de agua, 2 núcleos de tierra y 2 alientos de viento a Sarah Peletero a La Garganta de Fuego","","Al completar esta tarea aprenderás peletería elemental","","Si te dedicas a este arte, no podrás aprender peletería dragontina ni peletería tribal; piénsatelo bien antes de decidirte."}}
D[5145] = {"Peletería dragontina",{"Consigue 2 corazas resistentes de escórpido, 2 guantes resistentes de escórpido, y 10 escamas de dragón desgastadas para Thorkaf Dragonojo, en las Tierras Inhóspitas","","Si completas esta misión tendrás acceso al arte de la peletería dracónica","","Si lo haces, también dejarás de tener acceso a la peletería elemental y tribal. Tienes que asegurarte de querer seguir este camino antes de completarla."}}
D[5146] = {"Peletería elemental",{"Llévale 2 corazones de fuego, 2 globos de agua, 2 núcleos de tierra y 2 alientos de viento a Brumm Pezuña Invernal en las Tierras Altas de Arathi","","Cuando completes esta misión tendrás acceso a las artes de peletería elemental","","Si completas esta misión, no podrás aprender peletería dragontina ni peletería tribal; asegúrate de que este es el camino que deseas seguir antes de tomarlo."}}
D[5147] = {"Se busca: Arnak Tótem Siniestro",{"Mata a Arnak Tótem Siniestro y llévale una prueba de tu hazaña a Vigiarisco Cuernolargo, que está en el Poblado Viento Libre."}}
D[5148] = {"Peletería tribal",{"Lleva un jubón de cuero salvaje y un casco de cuero salvaje a Se'Jib en la Vega de Tuercespina","","Completar esta misión te proporcionará acceso a las artes de la peletería tribal","","Completar esta misión evitará que aprendas peletería dragontina y peletería elemental. Asegúrate que este es el camino que quieres seguir antes de hacerlo."}}
D[5149] = {"La muñeca de Pamela",{"Encuentra la muñeca de Pamela."}}
D[5150] = {"¡Dadanga tiene hambre!",{"Dadanga te observa mientras te acercas a ella. Parece que espera algo..","","¡Probablemente esté hambrienta!","","Seguro que en el cráter hay algo que le puede servir de aperitivo a una gran herbívora como ella. Ten en cuenta que es una chica muy grande así que, traigas lo que traigas, ¡que sea en abundancia!"}}
D[5151] = {"Hipercondensador",{"Acaba con la bestia y trae de regreso el hipercapacitor y la llave de la jaula a Wizlo Rodabrillante."}}
D[5152] = {"Tía Marlene",{"Habla con Marlene. Está al sur de las Ruinas de Andorhal."}}
D[5153] = {"Una extraña historiadora",{"Lleva la alianza de Joseph a Cromi."}}
D[5154] = {"Los Anales de Villa Darrow",{"Lleva el libro Anales de Villa Darrow a Cromi a Andorhal."}}
D[5155] = {"Las fuerzas de Jaedenar",{"Entra en Jaedenar y mata a 4 canes Jaedenar, 4 guardianes Jaedenar, 6 adeptos Jaedenar y 6 fieles Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil."}}
D[5156] = {"Investigación acerca de la corrupción",{"Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen agua vil corrupta, vuelve con Taronn Plumarroja a Frondavil."}}
D[5157] = {"Una muestra de agua corrupta",{"Lleva la cantimplora vacía a la Poza de la Luna que hay en el centro de Jaedenar y llénala antes de volver con Greta Pezuñamusgo a Frondavil."}}
D[5158] = {"Buscando ayuda espiritual",{"Lleva el agua de la Poza de la Luna corrupta a Islen Vident'aqua a Los Baldíos."}}
D[5159] = {"El agua purificada vuelve a Frondavil",{"Lleva el agua de la Poza de la Luna purificada a Greta Pezuñamusgo en Frondavil."}}
D[5160] = {"El Protectorado de la matrona",{"Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee."}}
D[5161] = {"La cólera del Vuelo Azul",{"Habla con Haleh si quieres continuar."}}
D[5162] = {"La cólera del Vuelo Azul",{"Habla con Jeziba en las Tierras de la Peste. Vive en Andorhal."}}
D[5163] = {"Yeti... ¿ya hemos llegado?",{"Coge el yeti mecánico de Umi y asusta con él a sus amigos:","","Legacki en Vista Eterna (Cuna del Invierno)","","Roxio en Gadgetzan (Tanaris)nQuixxil en el Refugio de Marshal (Cráter de Un'Goro)","","Cuando hayas terminado, devuelve el yeti mecánico a Umi."}}
D[5164] = {"Catálogo del Díscolo",{"Lee el Catálogo del Díscolo."}}
D[5165] = {"Sofocar las llamas de protección",{"Utiliza el agua de la Poza de la Luna purificada para apagar las llamas de los cuatro Blandones de Protección de la Guarida Sombría de Frondavil y vuelve con Greta Pezuñamusgo al Santuario Esmeralda."}}
D[5166] = {"Coraza del Vuelo Cromático",{"Para forjar la coraza del Vuelo Cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos:","","1 caparazón cromático","","10 escamas cromáticas luminosas","","10 sangres de héroes","","10 costuras desgarradas de abominación."}}
D[5167] = {"Quijotes del Desafiante cromático",{"Para forjar los quijotes del desafiante cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos:","","1 caparazón cromático","","10 escamas cromáticas luminosas","","10 sangres de héroes","","5 pieles de Sombra."}}
D[5168] = {"Los héroes de Villa Darrow",{"Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana."}}
D[5181] = {"Los villanos de Villa Darrow",{"Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz."}}
D[5201] = {"Intrusión Nevada",{"Rivern Ventogélido quiere que mates 5 chamanes Nevada y 5 ursas Nevada."}}
D[5202] = {"Una extraña llave roja",{"Recorre Jaedenar y descubre para qué se utiliza la llave roja de sangre."}}
D[5203] = {"El rescate en Jaedenar",{"Escolta a Arko'narin hasta el lugar en el que están Forjaluz y su equipo y protégela en la huida de la Guarida Sombría. Después, busca a Jessir Arcolunar en Frondavil para contarle lo que les ha ocurrido a sus amigos."}}
D[5204] = {"La reprensión de la Luz",{"Vuelve a Jaedenar y mata al súcubo Rakaiah antes de encontrar los Restos de Trey Forjaluz."}}
D[5206] = {"Los merodeadores de Villa Darrow",{"Lleva 5 calaveras resonadoras y el cristal místico a Carlin Rutagrana a las Tierras de la Peste del Este."}}
D[5210] = {"Carlin, el hermano de Joseph",{"Lleva los anales ampliados de Villa Darrow a Carlin Rutagrana a las Tierras de la Peste del Este."}}
D[5211] = {"Los defensores de Villa Darrow",{"Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana."}}
D[5212] = {"La carne no miente",{"Recoge 10 muestras de carne apestada de Stratholme y vuelve con Betina Bigglezink. Sospechas que podrías obtener una muestra de cualquier criatura de Stratholme."}}
D[5213] = {"El agente activo",{"Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink."}}
D[5214] = {"El gran Fras Siabi",{"Encuentra la Tienda de humo de Fras Siabi en Stratholme y recupera una caja del tabaco de calidad de Siabi. Cuando lo hayas hecho, vuelve con Smokey LaRue."}}
D[5215] = {"Las calderas de la Plaga",{"Habla con la suma sacerdotisa MacDonnell en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5216] = {"Objetivo: Campo de Piedramácula",{"Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5217] = {"El regreso al Campamento del Orvallo",{"Lleva la Botella rellena del Campo de Piedramácula a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5218] = {"El caldero del Campo de Piedramácula"}
D[5219] = {"Objetivo: Llanto de Dalson",{"Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5220] = {"El regreso al Campamento del Orvallo",{"Lleva la botella del Llanto de Dalson llena a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5221] = {"La caldera del Llanto de Dalson"}
D[5222] = {"Objetivo: El Tormento",{"Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5223] = {"El regreso al Campamento del Orvallo",{"Lleva la Botella llena de El Tormento a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5224] = {"El caldero de El Tormento"}
D[5225] = {"Objetivo: Gangrena de Gahrron",{"Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5226] = {"El regreso al Campamento del Orvallo",{"Lleva la botella llena de la Gangrena de Gahrron a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5227] = {"El caldero de la Gangrena de Gahrron"}
D[5228] = {"Los calderos de la Plaga",{"Habla con la sacerdotisa de las Sombras Vandis en el Baluarte, en las Tierras de la Peste del Oeste."}}
D[5229] = {"Objetivo: Campo de Piedramácula",{"Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5230] = {"El regreso a El Baluarte",{"Lleva la Botella rellena del Campo de Piedramácula a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5231] = {"Objetivo: Llanto de Dalson",{"Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5232] = {"El regreso a El Baluarte",{"Lleva la botella del Llanto de Dalson llena a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5233] = {"Objetivo: El Tormento",{"Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5234] = {"El regreso a El Baluarte",{"Lleva la Botella llena de El Tormento a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5235] = {"Objetivo: Gangrena de Gahrron",{"Ve a la Gangrena de Gahrron en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de la Gangrena de Gahrron para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5236] = {"El regreso a El Baluarte",{"Lleva la botella llena de la Gangrena de Gahrron a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5237] = {"¡Misión cumplida!",{"<nombre>, your successful re-engineering of the cauldrons is a tremendous victory for us!","","nnLet all within my presence hear: for service to the Kingdom of Stormwind and to the Alliance above and beyond the call of duty - in the face of overwhelming odds and incredible danger, might I add - I give <nombre> this, and I extend upon her our undying gratitude as a true hero of the Alliance. Cheers, I say!"}}
D[5238] = {"¡Misión cumplida!",{"¡<nombre>, tu éxito cambiando la estructura de las calderas es una enorme victoria para nosotros!","","Que todos los que están en mi presencia lo oigan: por los servicios prestados a los Renegados y a toda la Horda muy por encima de lo que era de esperar y, añado, por haber superado todos los pronósticos y un peligro inenarrable, concedo esto a <nombre>, y le hago llegar nuestra eterna gratitud como un auténtico héroe de la Horda. ¡Lancemos nuestros vítores!"}}
D[5241] = {"Tío Carlin",{"Encuentra a Carlin Rutagrana."}}
D[5242] = {"El golpe final",{"Mata a Moora y Salia y lleva la cabeza de Lord Fel'dan de las Sombras a Greta Pezuñamusgo a Frondavil."}}
D[5243] = {"Las casas de lo sagrado",{"Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido."}}
D[5244] = {"Las Ruinas de Kel'Theril",{"Habla con Jaron Tallapiedras en Aldea Estrella Fugaz."}}
D[5245] = {"Espíritus condenados de Kel'Theril",{"Utiliza el pico de Jaron para encontrar los cuatro trozos de reliquia de los Altonato. Llévaselas a Aurora Llamacielo en las Tierras de la Peste del Este."}}
D[5246] = {"Trozos del pasado",{"Encuentra las escrituras altonatas sagradas del templo de Zin-Malor en Azshara y tráelas para Aurora Llamacielo, en la Torre del Paso Norte en las Tierras de la Peste del Este."}}
D[5247] = {"Trozos del pasado",{"Consigue una barra encantada de torio, 5 cristales de restauración y un vial de agua funesta para Aurora Llamacielo, en la Torre del Paso Norte, en las Tierras de la Peste del Este."}}
D[5248] = {"Atormentados por el pasado",{"Lleva el Cristal de Zin-Malor a Lago Kel'Theril en Cuna del Invierno y encuentra un espíritu Altonato que hable contigo."}}
D[5249] = {"¡A la Cuna del Invierno!",{"Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche."}}
D[5250] = {"Estrella Fugaz",{"Encuentra la Aldea Estrella Fugaz en Cuna del Invierno y habla con Wynd Cazanoche."}}
D[5251] = {"El archivista",{"Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata."}}
D[5252] = {"Altonato arrepentido",{"Habla con Wynd Cazanoche en Aldea Estrella Fugaz y pregúntale por el lugar adecuado para el Cristal de Zin-Malor."}}
D[5253] = {"El cristal de Zin-Malor",{"Entrega el Cristal de Zin-Malor al archidruida Fandral Corzocelada de Darnassus."}}
D[5261] = {"Eagan Desollapelambres",{"Habla con Eagan Desollapelambres."}}
D[5262] = {"La verdad cae del cielo",{"Lleva la cabeza de Balnazzar al Duque Nicolas Zverenhoff en las Tierras de la Peste del Este."}}
D[5263] = {"Por encima y más allá",{"Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff."}}
D[5264] = {"Lord Maxwell Neófitus",{"Habla con Lord Maxwell Neófitus. Está en el interior de la iglesia."}}
D[5265] = {"El Bastión Argenta",{"Abre el Bastión Argenta y reclama tu recompensa."}}
D[5281] = {"Espíritus inquietos",{"Encuentra a Egan. Solo sabes que fue visto por última vez en los alrededores de Stratholme."}}
D[5282] = {"Espíritus inquietos",{"Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre","","Libera 15 almas y regresa a Egan."}}
D[5283] = {"El arte del forjador de armaduras",{"Para convertirte en <forjador/forjadora> de armaduras tienes que fabricar lo siguiente y llevárselo a Grumnus: 4 yelmos de mitril ornamentado, 2 pares de botas de mitril ornamentado y 1 coraza de mitril ornamentado."}}
D[5284] = {"El arte del forjador de armas",{"Para convertirte en <armero/armera> tienes que fabricar lo siguiente y llevárselo a Ironus: 4 espadas anchas de acero lunar, 4 hachas de hierro macizo, 2 hachas de mitril pesado y 2 mazas negras grandes."}}
D[5301] = {"El arte del forjador de armaduras",{"Para convertirte en <forjador/forjadora> de armaduras tienes que fabricar lo siguiente y llevárselo a Okothos: 4 yelmos de mitril ornamentado, 2 pares de botas de mitril ornamentado y 1 coraza de mitril ornamentado."}}
D[5302] = {"El arte del forjador de armas",{"Para convertirte en <forjador/forjadora> de armas tienes que fabricar lo siguiente y llevárselo a Borgosh: 4 espadas anchas de acero lunar, 4 hachas de hierro macizo, 2 hachas de mitril pesado y 2 mazas negras grandes."}}
D[5305] = {"Dulce serenidad",{"Viaja a Stratholme y mata al forjamartillos Carmesí. Consigue el delantal del forjamartillos Carmesí y regresa con Lilith."}}
D[5306] = {"Piedra culebra de la cazadora de las Sombras",{"Viaja a la Cumbre de Roca Negra y mata a la cazadora de las Sombras Vosh'gajin. Recupera la piedra culebra de Vosh'gajin y vuelve con Kilram."}}
D[5307] = {"Corrupción",{"Encuentra al armero Guardia Negra en Stratholme y acaba con él. Recupera la Insignia de la Guardia Negra y regresa con Seril Finiquiplaga."}}
D[5321] = {"El despertar",{"Escolta a Kerlonian Semprumbrío hasta Liladris Rioluna en la Atalaya de Maestra de Vallefresno."}}
D[5341] = {"La fortuna de la familia Barov",{"Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea."}}
D[5342] = {"El último de los Barov",{"Viaja al Campamento del Orvallo, territorio de la Alianza, y asesina a Weldon Barov. Coge su cabeza y regresa con Alexi Barov","","Ten cuidado, Alexi seguramente estará muy protegido por la escoria de la Alianza."}}
D[5343] = {"La fortuna de la familia Barov",{"Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea."}}
D[5344] = {"El último de los Barov",{"Viaja a El Baluarte, territorio de la Horda, y asesina a Alexi Barov. Coge su cabeza y regresa con Weldon Barov","","Ten cuidado, Alexi seguramente estará muy protegido por la escoria de la Horda."}}
D[5361] = {"Árbol genealógico",{"Entrégale el informe de Vigiarisco Cuernolargo a Nataka Cuernolargo que se encuentra en el Campamento del Espíritu Errante de Desolace."}}
D[5381] = {"La Mano de Iruxos",{"Extrae la caja de demonio de la Fortaleza del Hacha de Trueno y llévasela a Taiga Melenasabia a la Aldea Cazasombras junto con el pico de demonio."}}
D[5382] = {"Doctor Theolen Krastinov, el Carnicero",{"Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff."}}
D[5383] = {"Bolsa de los horrores de Krastinov",{"Lleva la Bolsa de los horrores a Eva Sarkhoff en Castel Darrow."}}
D[5384] = {"Kirtonos el Heraldo",{"Vuelve a Scholomance con la Sangre de los inocentes. Busca el Porche y coloca la Sangre de los inocentes en el blandón. Kirtonos acudirá a devorar tu alma","","Lucha con valentía, ¡no cedas ni una pulgada! Destruye a Kirtonos y vuelve con Eva Sarkhoff."}}
D[5385] = {"Restos de Trey Forjaluz",{"Lleva los Restos de Trey Forjaluz a Jessir Arcolunar a Frondavil."}}
D[5386] = {"La pesca del día",{"Habla con Jinar'Zillen, en la Aldea Cazasombras, y luego lleva 2 panzasangres a Nataka Cuernolargo."}}
D[5401] = {"Comisión de El Alba Argenta",{"Todos los que combaten el mal en nombre del Alba Argenta deben vestir nuestra Comisión. Al hacerlo obtendrás el derecho de reclamar recompensas a nuestros intendentes","","Mientras estés bajo nuestra comisión podrás adquirir piedras de la Plaga de sus miembros caídos ya que esas piedras son insignias que a veces llevan consigo. Hazte con esas insignias y tráemelas. Por cada juego que traigas recibirás nuestras señales de heroísmo: las muestras de valor del Alba Argenta","","Sigue tu destino, <clase>, ¡únete hoy mismo a la lucha!"}}
D[5402] = {"Piedras de la Plaga del esbirro",{"Una piedra de la Plaga del esbirro es la insignia de las filas de la Plaga. A veces pueden encontrarse en los miembros más débiles de las tropas destacadas en las Tierras de la Peste, aunque la palabra \"débil\" es muy relativa. La Plaga, da igual de quién se trate, nunca debe ser subestimada","","En este momento el Alba Argenta ofrece una muestra de valor a cambio de veinte de esas insignias... un intercambio que me encantaría hacer, ¡siempre y cuando tengas suficientes piedras de la Plaga!"}}
D[5403] = {"Piedras de la Plaga del invasor",{"Una piedra de la Plaga del invasor es la insignia de las tropas de élite de la Plaga. A veces pueden encontrarse entre los más fuertes de las tropas destacadas en las Tierras de la Peste. Derrotar una criatura así es, sin duda, todo un reto, pero uno del que se disfruta cuando se está comprometido con la aniquilación del mal","","En este momento, el Alba Argenta ofrece una muestra de valor a cambio de diez de esas insignias. Tráemelas y me aseguraré de que recibas tu recompensa."}}
D[5404] = {"Piedras de la Plaga del corruptor",{"Una piedra de la Plaga del corruptor es la insignia de los Señores Supremos de la Plaga. Todo ser poderoso y con autoridad sobre la Plaga posee una de esas piedras. Acabar con una criatura tan malévola sería un gran paso adelante para la causa del Alba Argenta y para todas las causas justas","","En nombre del Alba Argenta te daré una muestra de valor a cambio de una sola de esas insignias. Ten cuidado al obtenerlas, <nombre>... no hay que andar jugando con criaturas tan poderosas."}}
D[5405] = {"Comisión de El Alba Argenta",{"Todos los que combaten el mal en nombre de El Alba Argenta deben vestir nuestra Comisión. Al hacerlo obtendrás el derecho de reclamar recompensas a nuestros intendentes","","Mientras estés bajo nuestra comisión podrás adquirir piedras de la Plaga de sus miembros caídos ya que esas piedras son insignias que a veces llevan consigo. Hazte con esas insignias y tráemelas. Por cada juego que traigas recibirás nuestras señales de heroísmo: las muestras de valor de El Alba Argenta","","Sigue tu destino, <clase>, ¡únete hoy mismo a la lucha!"}}
D[5406] = {"Piedras de la Plaga del corruptor",{"Una piedra de la Plaga del corruptor es la insignia de los Señores Supremos de la Plaga. Todo ser poderoso y con autoridad sobre la Plaga posee una de esas piedras. Acabar con una criatura tan malévola sería un gran paso adelante para la causa de El Alba Argenta y para todas las causas justas","","En nombre de El Alba Argenta te daré una muestra de valor a cambio de una sola de esas insignias. Ten cuidado al obtenerlas, <nombre>... no hay que andar jugando con criaturas tan poderosas."}}
D[5407] = {"Piedras de la Plaga del invasor",{"Una piedra de la Plaga del invasor es la insignia de las tropas de élite de la Plaga. A veces pueden encontrarse entre los más fuertes de las tropas destacadas en las Tierras de la Peste. Derrotar una criatura así es, sin duda, todo un reto, pero uno del que se disfruta cuando se está comprometido con la aniquilación del mal","","En este momento, El Alba Argenta ofrece una muestra de valor a cambio de diez de esas insignias. Tráemelas y me aseguraré de que recibas tu recompensa."}}
D[5408] = {"Piedras de la Plaga del esbirro",{"Una piedra de la Plaga del esbirro es la insignia de las filas de la Plaga. A veces pueden encontrarse en los miembros más débiles de las tropas destacadas en las Tierras de la Peste, aunque la palabra \"débil\" es muy relativa. La Plaga, da igual de quién se trate, nunca debe ser subestimada","","En este momento El Alba Argenta ofrece una muestra de valor a cambio de veinte de esas insignias... un intercambio que me encantaría hacer, ¡siempre y cuando tengas suficientes piedras de la Plaga!"}}
D[5421] = {"Pescado en un balde",{"Recompensaré a cualquiera que haga mi vida un poco más fácil... ¡Mi vida se rige por la ley del mínimo esfuerzo, colega!","","Bajo el embarcadero, aquí en la Aldea Cazasombras, tengo muchas trampas de marisco. Si fueras tan amable... podrías hacer mi trabajo y recoger mi marisco... Y luego yo te doy algo que quieres, ¿pillas el sistema, colega? ¡Por cada 5 mariscos que me traigas, te daré un estupendo panzasangre!"}}
D[5441] = {"Peones vagos",{"Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones y devuélvele la cachiporra al supervisor Thazz'ril en el Valle de los Retos."}}
D[5461] = {"El humano, Ras Levescarcha",{"Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Libro de los Recuerdos. Si lo encuentras llévaselo al magistrado Marduke."}}
D[5462] = {"El moribundo, Ras Levescarcha",{"Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Libro de los Recuerdos y cuéntale todo lo que has descubierto."}}
D[5463] = {"El Obsequio de Menethil",{"Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Libro de los Recuerdos en suelo no consagrado."}}
D[5464] = {"El Obsequio de Menethil",{"Lleva el Libro de Memorias del Alma a Leonid Barthalomew a las Tierras de la Peste del Este."}}
D[5465] = {"El Libro de Memorias del Alma",{"Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale el Libro de Memorias del Alma."}}
D[5466] = {"El exánime, Ras Levescarcha",{"Busca a Ras Levescarcha en Scholomance. Cuando lo hayas encontrado utiliza el Libro de Memorias del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Levescarcha. Lleva la cabeza al magistrado Marduke."}}
D[5481] = {"La tarea de Gordo",{"Recoge 3 hierbas luminiscentes y entrégaselas al boticario de segunda Holland en el cementerio de Rémol."}}
D[5482] = {"Apocalíseas",{"Recoge 10 apocalíseas y entrégaselas al boticario de segunda Holland."}}
D[5501] = {"Recolección de kodos",{"Lleva 10 huesos de kodo del Cementerio de Kodos a Bibbly F'utzhebilla a la Cabaña de Kormek."}}
D[5502] = {"Alcaide de la Horda",{"Lleva a tu pupilo de vuelta al orfanato de Orgrimmar entregándole el silbato de huérfano orco a la supervisora de huérfanos Llantobatalla en el Valle del Honor."}}
D[5503] = {"Comisión de El Alba Argenta",{"Todos los que combaten el mal en nombre del Alba Argenta deben portar nuestra Comisión. Cuando la lleves, tendrás derecho a reclamar las recompensas que ofrezcan nuestras Intendencias","","Y también podrás adquirir piedras de la Peste de miembros de la Peste caídos. Estas piedras son insignias que poseen algunos de ellos. Hazte con esas insignias y tráemelas. Por cada insignia que me entregues, recibirás nuestro símbolo de heroísmo: la muestra de valor del Alba Argenta","","Cumple tu destino, <clase>, ¡únete hoy al combate!"}}
D[5504] = {"Mantos del Alba",{"Lleva 10 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5505] = {"La llave de Scholomance",{"Bien, aquí la tienes <nombre>, la Llave esqueleto. Estoy tan seguro como puedo de que con esta llave podrás adentrarte en los confines de Scholomance. Pero solo hay un modo de asegurarse por completo. No pierdas tiempo intentándolo, te lo aconsejo","","Buena suerte, poderoso héroe. ¡Que sigas llevando la Luz a las tinieblas!"}}
D[5507] = {"Mantos del Alba",{"Lleva 10 muestras de valor de El Alba Argenta al intendente Destello de Luz en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5508] = {"Piedras de la Plaga del corruptor",{"La Piedra de la Plaga de un corruptor es la insignia de los Señores Supremos de la Plaga. Unos seres poderosos que disfrutan de una posición de autoridad en la Plaga. Siempre llevan una. Matar a esas criaturas tan malévolas ayudaría sin duda a la causa del Alba Argenta... ¡y a todas las buenas causas del mundo!","","De parte del Alba Argenta, te daré una muestra de valor a cambio de una sola de estas insignias. Sé prudente cuando quieras hacerte con una, <nombre>, los seres que las poseen son poderosos."}}
D[5509] = {"Piedras de la Plaga del invasor",{"La Piedra de la Plaga de un invasor es la insignia de las tropas de élite de la Plaga. A veces se encuentran en los soldados más fuertes, los que están en las Tierras de la Peste. Matar a uno de ellos es un desafío, pero es uno que se ve compensado por ser una oportunidad para derrotar al mal","","El Alba Argenta ofrece una muestra de valor a cambio de diez de estas insignias. Tráemelas y yo me aseguraré de que recibas tu justa recompensa."}}
D[5510] = {"Piedras de la Plaga del esbirro",{"Una Piedra de la Plaga de un esbirro es la insignia de las tropas de la Plaga. A veces se encuentran en los más débiles de sus filas, las que están en las Tierras de la Peste... aunque el término \"débiles\" debe por supuesto, interpretarse en su contexto. Los miembros de la Plaga, estén donde estén, no deben ser subestimados","","El Alba Argenta ofrece una muestra de valor a cambio de veinte de esas insignias... Es un intercambio que me encantaría hacer, ¡siempre que tengas suficientes Piedras de la Plaga!"}}
D[5511] = {"La llave de Scholomance",{"Bien, aquí estás, <nombre>. Y has completado la llave esqueleto. No tengo dudas de que esta llave te permitirá acceder a los confines de Scholomance. Solo hay una forma de asegurarse por completo de que funcione. Yo diría que no pierdas tiempo en probarla","","Buena suerte, poderoso héroe. ¡Que tus victorias continúen otorgándote fama y poder mientras destruyes Scholomance!"}}
D[5513] = {"Mantos del Alba",{"Lleva 10 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este."}}
D[5514] = {"Molde rima con... ¿oro?",{"Lleva los trozos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan."}}
D[5515] = {"Bolsa de los horrores de Krastinov",{"Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff."}}
D[5517] = {"Manto del Alba cromático",{"Lleva 25 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este."}}
D[5518] = {"El traje de ogro Gordok",{"Lleva 4 madejas de paño rúnico, 8 cueros bastos, 2 hilos rúnicos y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre."}}
D[5519] = {"El traje de ogro Gordok",{"Necesitas otro traje, ¿verdad? Pues mira, como parece que no voy a ir a ninguna parte, tráeme las cosas que te pedí la vez anterior y te haré otro traje de ogro."}}
D[5521] = {"Manto del Alba cromático",{"Lleva 25 muestras de valor de El Alba Argenta al intendente Destello de Luz en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5522] = {"Leonid Barthalomew",{"Lleva los huevos congelados a Leonid Barthalomew a las Tierras de la Peste del Este."}}
D[5524] = {"Manto del Alba cromático",{"Lleva 25 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5525] = {"¡Libera a Knot!",{"Se llama llave de los grilletes de Gordok... bueno, así es como la llaman esos graciosillos. Creo que podría tenerla cualquiera de los ogros, pero no sé cuáles en concreto. Probablemente podrían tenerla los guardias..","","¿Pero qué estoy diciendo? ¡Si tú ya la tienes! ¡¿No?! ¡¿¿No es eso que tienes ahí??!"}}
D[5526] = {"Fragmentos de gangrevid",{"Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de Pureza para guardar el fragmento y llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna."}}
D[5527] = {"Un relicario de Pureza",{"Ve a Silithus a buscar un relicario de Pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna."}}
D[5528] = {"La cata de los Gordok",{"Ahora eres el jefe, ¡así consigues muestras gratis de mis mejores bebidas! ¡Te darán un buen subidón y un potente tirón! Son las buenas, jefe. ¡Prueba y dilo a Kreeg!"}}
D[5529] = {"Crías de dragón apestadas",{"Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz."}}
D[5531] = {"Betina Bigglezink",{"Lleva los huevos congelados a Betina Bigglezink, que está fuera."}}
D[5533] = {"Scholomance",{"Habla con el alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5534] = {"El equipamiento \"perdido\" de Kim'jael",{"Encuentra una runa que los nagas guardan en las Ruinas de Eldarath y llévasela a Kim'jael en Azshara."}}
D[5535] = {"Agitación espiritual",{"Destruye 6 apariciones Altonato y 6 exanimatos Altonato antes de volver junto a Loh'atu en Azshara."}}
D[5536] = {"Una tierra llena de odio",{"Mata 6 sátiros Haldarr, 2 tramposos Haldarr, 2 jurapenas Haldarr y vuelve junto a Loh'atu en la frontera de Vallefresno."}}
D[5537] = {"Trozos esqueléticos",{"Lleva 15 trozos esqueléticos al alquimista Arbington, en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5538] = {"Molde rima con... ¿oro?",{"Lleva los trozos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan."}}
D[5541] = {"Municiones para Estruendo",{"Lleva la munición de Estruendo a Hegnar Estruendo a Dun Morogh."}}
D[5542] = {"Perros demoníacos",{"Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín."}}
D[5543] = {"Cielos sangrientos",{"Mata 30 murcipestes y vuelve con Tirion Vadín."}}
D[5544] = {"Gusanos carroñeros",{"Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero."}}
D[5545] = {"El cumplimiento del plazo",{"Lleva 8 fardos de madera a Raelen al Aserradero de la Vega del Este."}}
D[5561] = {"El rodeo kodo",{"Lleva 5 kodos domados y el kombobulador kodo a Smeed Mezclatornillos, al Campamento de los Mezclatornillos."}}
D[5581] = {"Los portales de la Legión",{"Destruye 6 Portales en el Aquelarre Mannoroc y vuelve a la Aldea Cazasombras a hablar con Taiga Melenasabia."}}
D[5582] = {"Escama de dragón sana",{"Lleva la escama de dragón sana a Betina Bigglezink a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[5601] = {"Pamela, mi hermana",{"Encuentra a Pamela Rutagrana en Villa Darrow."}}
D[5621] = {"Prendas de la luna",{"Encuentra a la centinela Shaya y cura sus heridas utilizando un hechizo de Curación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo a Laurna Luzdelalba a Dolanaar."}}
D[5622] = {"Los caminos de Elune",{"Habla con Laurna Luzdelalba en Teldrassil."}}
D[5623] = {"Al servicio de la Luz",{"Ve al Bosque de Elwynn y habla con la sacerdotisa Josetta."}}
D[5624] = {"Las prendas de la Luz",{"Encuentra al guardia Roberts y cura sus heridas usando Curación inferior (Rango 2). Después, concédele la Palabra de poder: entereza y vuelve a Villadorada a hablar con la sacerdotisa Josetta."}}
D[5625] = {"Las prendas de la Luz",{"Encuentra al montaraz Dolf y cura sus heridas usando la Curación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Kharanos a hablar con Maxan Anvol."}}
D[5626] = {"Al servicio de la Luz",{"Ve a Dun Morogh y habla con Maxan Anvol."}}
