D[5628] = {"La vuelta a casa",{"Ve a Darnassus y habla con la sacerdotisa Alathea."}}
D[5629] = {"La vuelta a casa",{"Ve a Darnassus y habla con la sacerdotisa Alathea."}}
D[5630] = {"La vuelta a casa",{"Ve a Darnassus y habla con la sacerdotisa Alathea."}}
D[5631] = {"La vuelta a casa",{"Ve a Darnassus y habla con la sacerdotisa Alathea."}}
D[5632] = {"La vuelta a casa",{"Ve a Darnassus y habla con la sacerdotisa Alathea."}}
D[5633] = {"La vuelta a casa",{"Ve a Darnassus y habla con la sacerdotisa Alathea."}}
D[5634] = {"Oración desesperada"}
D[5635] = {"Oración desesperada",{"Habla con la suma sacerdotisa Laurena en Ventormenta."}}
D[5636] = {"Oración desesperada",{"Habla con la suma sacerdotisa Laurena en Ventormenta."}}
D[5637] = {"Oración desesperada",{"Habla con la suma sacerdotisa Laurena en Ventormenta."}}
D[5638] = {"Oración desesperada",{"Habla con la suma sacerdotisa Laurena en Ventormenta."}}
D[5639] = {"Oración desesperada",{"Habla con la suma sacerdotisa Laurena en Ventormenta."}}
D[5641] = {"Sin miedo"}
D[5642] = {"Guardia de las Sombras",{"Habla con Ur'kyo en Orgrimmar."}}
D[5643] = {"Guardia de las Sombras",{"Habla con Ur'kyo en Orgrimmar."}}
D[5644] = {"Peste devoradora",{"Habla con Aelthalyste en Entrañas."}}
D[5645] = {"Sin miedo",{"Habla con el sumo sacerdote Rohan en Forjaz."}}
D[5646] = {"Peste devoradora",{"Habla con Aelthalyste en Entrañas."}}
D[5647] = {"Sin miedo",{"Habla con el sumo sacerdote Rohan en Forjaz."}}
D[5648] = {"Prendas de espiritualidad",{"Encuentra al Bruto Kor'ja y cura sus heridas usando la Curación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Cerrotajo a hablar con Tai'jin."}}
D[5649] = {"Al servicio de la espiritualidad",{"Ve a Durotar y habla con Tai'jin."}}
D[5650] = {"Las prendas de la Oscuridad",{"Encuentra al Guardia de la Muerte Kel y cura sus heridas utilizando un hechizo de Curación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo al clérigo oscuro Beryl a Rémol."}}
D[5651] = {"Al servicio de la Oscuridad",{"Habla con el clérigo oscuro Beryl en los Claros de Tirisfal."}}
D[5652] = {"Maleficio de Debilidad"}
D[5654] = {"Maleficio de Debilidad",{"Habla con Ur'kyo en Orgrimmar."}}
