D[6087] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un acechador de pradera. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre."}}
D[6088] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un aguilón. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre."}}
D[6089] = {"Entrenar a la bestia",{"Habla con Holt Astatrueno en el Alto de los Cazadores, en Cima del Trueno."}}
D[6101] = {"Domesticar la bestia",{"Utiliza la fusta de doma para domar a un acechador sable de la noche. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar."}}
D[6102] = {"Domesticar la bestia",{"Utiliza la fusta de doma para domar a un estridador estrígido. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar."}}
D[6103] = {"Domesticar la bestia",{"Habla con Jocaste en el Enclave Cenarion de Darnassus."}}
D[6121] = {"Nuevas lecciones",{"Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar."}}
D[6122] = {"La fuente del envenenamiento",{"Recoge agua de Salto de Fonroca a la entrada de la cueva","","Entrégale la muestra llena de Salto de Fonroca a Alanndarian Arrullanoche; en Auberdine, en Costa Oscura."}}
D[6123] = {"Reunir los ingredientes del remedio",{"Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo."}}
D[6124] = {"Curar la dolencia",{"Utiliza el bálsamo curativo para animales en los 10 ciervos enfermos que hay en Costa Oscura; el bálsamo debería curarlos. Se han avistado ciervos enfermos desde el sur del Río Fonroca hasta el norte de Auberdine y por toda la zona que lleva hasta el sur de Costa Oscura, donde empieza Vallefresno."}}
D[6125] = {"Poder contra el veneno",{"Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion."}}
D[6126] = {"Nuevas lecciones",{"Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar."}}
D[6127] = {"La fuente del envenenamiento",{"Usa el muestrario de Cima Calígine vacío para recoger una muestra de agua de uno de los estanques de la cima","","Luego llévale el muestrario de Cima Calígine lleno a Tonga Runatótem a El Cruce, en Los Baldíos."}}
D[6128] = {"Reunir los ingredientes del remedio",{"Llévale 5 raíces de tierra y 5 cuernos de kodo a Tonga Runatótem en El Cruce para que pueda confeccionar un bálsamo curativo."}}
D[6129] = {"Curar la dolencia",{"Usa el bálsamo animal curativo sobre las 10 gacelas enfermas que se encuentran en la parte norte de Los Baldíos; así se curarán. Hemos recibido informes según los cuales se han avistado gacelas enfermas por la carretera que va de este a oeste en El Cruce."}}
D[6130] = {"Poder contra el veneno",{"Vuelve a Cima del Trueno para hablar con Turak Tótem Rúnico en Alto de los Ancestros."}}
D[6131] = {"Aliado Fauce de Madera",{"Grazle quiere que demuestres lo que vales dando muerte a 5 guerreros Muertobosque, 5 abrecaminos Muertobosque y 5 jardineros Muertobosque."}}
D[6132] = {"¡Sácame de aquí!",{"Escolta a Melizza Zumbala y luego ve a Desolace, al Cementerio de Kodos y habla con Hornizz Zumbala."}}
D[6133] = {"La orden del Señor de forestales",{"Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien","","También tienes que matar a 8 forestales, 8 zancaminos y 8 Leñantros."}}
D[6134] = {"La caza de ectoplasmas",{"Lleva 8 ectoplasmas y la caja de imanes fantasmales a Hornizz Zumbala a Desolace."}}
D[6135] = {"Alatardecer, cómo te odio...",{"Encuentra a Alatardecer y mátalo. Recoge un parche de pelaje de Alatardecer de su cadáver y llévaselo a Nathanos Clamorinfecto","","Se dice que Alatardecer vaga por el campo, al norte de la Hacienda de Marris."}}
D[6136] = {"El corpulento",{"Encuentra a Borelgore en las planicies del norte de las Tierras de la Peste del Este y destrúyelo. Vuelve junto a Nathanos Clamorinfecto cuando hayas cumplido la misión."}}
D[6141] = {"Hermano Anton",{"Habla con el hermano Anton en Desolace."}}
D[6142] = {"Almejas",{"Encuentra 10 piezas de carne de almeja blanda y llévaselas a Mai'Lahii a la Aldea Cazasombras."}}
D[6143] = {"Otros pescados para freír",{"Mata a 7 mirmidones Filozante, 7 nagas Filozante y 5 hechiceras Filozante y luego ve a Cazasombras, en Desolace, a hablar con Drulzegar."}}
D[6144] = {"La llamada del teniente",{"Viaja a Entrañas y habla con Varimathras."}}
D[6145] = {"El mensajero carmesí",{"Vuelve a las Tierras de la Peste del Este y encuentra al mensajero carmesí. Mata al mensajero y recupera la Orden del Gran Cruzado","","Lleva el documento a Nathanos Clamorinfecto y espera sus instrucciones."}}
D[6146] = {"La estratagema de Nathanos",{"Viaja a Mano de Tyr, al sureste de la Hacienda de Marris. Una vez allí, da un mordisco a la manzana podrida. Entrega la Orden del Gran Cruzado al Señor Cruzado Valdemar con la protección de la forma de la Cruzada Escarlata."}}
D[6147] = {"Vuelve con Nathanos",{"Vuelve con Nathanos Clamorinfecto con la nueva información."}}
D[6148] = {"El Oráculo Escarlata, Demetria",{"La Cruzada Escarlata se está moviendo. En algún lugar, a lo largo del camino que va de Mano de Tyr a Stratholme, encontrarás al Oráculo, Demetria, con su escolta. Da caza a Demetria y mátala. Vuelve junto a Nathanos Clamorinfecto si tienes éxito."}}
D[6161] = {"La búsqueda del tesoro de Masatormento",{"Encuentra la llave de plata de Masatormento. Encuentra la llave de oro de Masatormento. Encuentra y abre el cofre de Masatormento."}}
D[6162] = {"La última batalla de un esposo",{"Mata al Señor Supremo Ror y lleva su garra a Dreka'Sur al Puesto del Veneno de Frondavil."}}
D[6163] = {"Ramstein",{"Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos."}}
D[6164] = {"Libro de entradas de Augustus",{"Lleva el libro de entradas de Augustus a Augustus el Agraciado a Valle del Terror."}}
D[6181] = {"Mensajero a toda prisa",{"Lleva la Nota de Lewis a Thor, el maestro de grifos."}}
D[6182] = {"El primero y el último",{"Habla con Mathias Shaw en el Casco Antiguo, en Ventormenta. Vive en los Cuarteles."}}
D[6183] = {"Honrar a los muertos",{"Vuelve a hablar con Mathias Shaw si quieres aceptar esta misión."}}
D[6184] = {"Flint Sombramás",{"Vete al Campamento del Orvallo en las Tierras de la Peste del Oeste y reúnete con tu contacto, Flint Sombramás."}}
D[6185] = {"Las pestes del este",{"Explora las Tierras de la Peste del Este en busca de pistas sobre el \"Clamorinfecto\" y los agentes perdidos del IV:7. Si encuentras alguna insignia del IV:7 llévasela a Flint Sombramás en el Campamento del Orvallo."}}
D[6186] = {"El regreso de Clamorinfecto",{"Regresa a Ventormenta e informa al alto señor Bolvar Fordragon sobre el destino de Nathanos Marris."}}
D[6187] = {"Restaurar el orden",{"Reúne un ejército y viaja a las Tierras de la Peste del Este. Lanza un asalto contra Nathanos Clamorinfecto y cualquier miembro de la Horda que pueda intentar protegerle","","Tienes que permanecer alerta, <nombre>. Los de la Horda defenderán al Señor de exploradores con su vida."}}
D[6221] = {"Los Muertobosque del Norte",{"Nafien desea que mates a 5 vigías del cubil Muertobosque, 5 vengadores Muertobosque y 5 chamanes Muertobosque."}}
D[6241] = {"Actividad Invernal",{"Salfa desea que mates a 6 totémicos Nevada, 6 vigías del cubil Nevada y 6 abrecaminos Nevada."}}
D[6261] = {"Dungar Tragolargo",{"Lleva el Cajón de Osric a Dungar Tragolargo, el maestro de grifos."}}
D[6281] = {"Prosigue hasta Ventormenta",{"Cómprale al maestro de grifos Thor un vuelo en grifo y lleva la Nota de Lewis a Osric Strang, en la tienda Inmunidad Limitada, en el Casco Antiguo de Ventormenta."}}
D[6282] = {"La amenaza de las arpías",{"Maggran Vinculador terrestre en el Refugio Roca del Sol quiere que mates 7 arpías Furia Sangrienta, 7 emboscadoras Furia Sangrienta, 7 destripadoras Furia Sangrienta y 7 malaplumas Furia Sangrienta."}}
D[6283] = {"El linaje Furia Sangrienta",{"Maggran, en el Refugio Roca del Sol, quiere que mates a la desgarradora Furia Sangrienta y le lleves sus restos como prueba de tu hazaña."}}
D[6284] = {"Aracnofobia",{"Mata a Besseleth y lleva el colmillo de Besseleth a Maggran en el Refugio Roca del Sol."}}
D[6285] = {"Regresa con Lewis",{"Compra un vuelo en grifo hasta la Colina del Centinela al maestro de grifos Dungar Tragolargo y lleva el Cajón de Osric a Lewis de la Colina del Centinela."}}
D[6301] = {"El ciclo del renacimiento",{"Tammra Windfield, en el Refugio Roca del Sol, quiere que le consigas 10 semillas de Gaia."}}
D[6321] = {"Suministros para El Sepulcro",{"Lleva el pedido de Podrig a Karos Razok."}}
D[6322] = {"Michael Garrett",{"Lleva el cajón de Gordok a Michael Garrett."}}
D[6323] = {"Vuela a Entrañas",{"Compra un viaje en murciélago a Entrañas al maestro de murciélagos Karos Razok. Después lleva el pedido de Podrig a Gordon Wendham en Entrañas."}}
D[6324] = {"Vuelve con Podrig",{"Compra un viaje en murciélago a El Sepulcro al maestro de murciélagos Michael Garrett. Después lleva el cajón de Gordok al Guardia de la Muerte Podrig en El Sepulcro."}}
D[6341] = {"La prodigalidad de Teldrassil",{"Lleva la colección de Nessa a Vesprystus."}}
D[6342] = {"Vuela a Auberdine",{"Consigue un hipogrifo del maestro de hipogrifos Vesprystus, viaja a Auberdine y lleva la colección de Nessa a Laird."}}
D[6343] = {"Vuelve con Nessa",{"Lleva la respuesta de Laird a Nessa Cantosombrío."}}
D[6344] = {"Nessa Cantosombrío",{"Habla con Nessa Cantosombrío."}}
D[6361] = {"Un fardo de pieles",{"Llévale el fajo de pieles al maestro de jinetes del viento Devrak en El Cruce."}}
D[6362] = {"Un viaje a Cima del Trueno",{"Cómprale un jinete del viento para Cima del Trueno al maestro de jinetes del viento Devrak y llévale entonces el fajo de pieles a Ahanu en Cima del Trueno."}}
D[6363] = {"Tal, maestro de jinetes del viento",{"Lleva los artículos de piel de Ahanu a Tal en Cima del Trueno."}}
D[6364] = {"Volver junto a Jahan",{"Cómprale un jinete del viento para El Cruce al maestro de jinetes del viento Tal y llévale entonces los artículos de piel de Ahanu a Jahan Alalcón."}}
D[6365] = {"Entrega de carne a Orgrimmar",{"Llévale la carne de Zargh a Devrak en El Cruce."}}
D[6381] = {"Nueva vida",{"Planta 10 semillas de Gaia en los Túmulos y lleva las semillas de Gaia encantadas restantes a Tammra en el Refugio Roca del Sol."}}
D[6382] = {"La Caza de Vallefresno",{"Habla con Senani Truenozón en el Puesto del Hachazo, Vallefresno."}}
D[6383] = {"La Caza de Vallefresno",{"Tres legendarias criaturas componen la Caza de Vallefresno; puedes buscarlas y ponerte a prueba frente a su astucia y fuerza. En ese proceso, espero que aprendas algo sobre ti mismo. Estas criaturas son: el oso Ursangous, el felino sable de la noche Shadumbra y el hipogrifo Garrafilada","","Las criaturas de la Caza de Vallefresno son poderosas y es posible que necesites ayuda para derrotarlas. Si llegas a hacerlo, tráeme la prueba de tu caza."}}
D[6384] = {"Un viaje a Orgrimmar",{"Cómprale un jinete del viento al maestro de jinetes del viento Devrak y llévale entonces la carne de Zargh a Gryshka en Orgrimmar."}}
D[6385] = {"Doras, maestro de jinetes del viento",{"Llévale la carta de Gryshka a Doras en Orgrimmar."}}
D[6386] = {"El regreso a El Cruce",{"Cómprale un jinete del viento para El Cruce al maestro de jinetes del viento Doras y llévale entonces la carta de Gryshka a Zargh en El Cruce."}}
D[6387] = {"Estudiantes de honor",{"Lleva la lista de Brock a Thorgrum Borrelson a Thelsamar."}}
D[6388] = {"Gryth Thurden",{"Lleva los picos honoríficos a Gryth Thurden a Forjaz."}}
D[6389] = {"Una Peste en la Cruzada",{"Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Nathaniel Dumah en el Campamento del Orvallo en las Tierras de la Peste del Oeste."}}
D[6390] = {"Una Peste en la Cruzada",{"Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Mickey Levine en El Baluarte en los Claros de Tirisfal."}}
D[6391] = {"Vuela a Forjaz",{"Contrata un vuelo en grifo a Forjaz con el maestro de grifos Thorgrum Borrelson para llevar la lista de Brock a Golnir Dedorroca."}}
D[6392] = {"Vuelve con Brock",{"Contrata un vuelo en grifo a Thelsamar con el maestro de grifos Gryth Thurden para llevar los picos honorarios a Brock Buscapiedras en Thelsamar."}}
D[6393] = {"Guerra elemental",{"Lleva 10 incendritas a Tsunaman en el Refugio Roca del Sol."}}
D[6394] = {"Pico de Thazz'ril",{"Lleva el pico de Thazz'ril al supervisor Thazz'ril."}}
D[6395] = {"El último deseo de Marla",{"Lleva los restos de Samuel Fipps a la tumba de Marla y luego vuelve con la novicia Elreth."}}
D[6401] = {"Kaya está viva",{"Da las buenas noticias a Tammra Campovento en el Refugio Roca del Sol."}}
D[6402] = {"Tienes un cita en Ventormenta",{"Viaja hasta Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al mariscal Windsor sobre tu llegada."}}
D[6403] = {"La gran farsa",{"Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!"}}
D[6421] = {"Barranco del Alud",{"Explora las profundidades de la cueva del Barranco del Alud y lleva 10 cristales de resonita Mor'rogal en el Refugio Roca del Sol para que los investigue."}}
D[6441] = {"Los cuernos de sátiro",{"Reúne 16 cuernos de sátiro para Pixie en el Puesto del Hachazo."}}
D[6442] = {"Nagas en la Ensenada de Zoram",{"Llévale 20 cabezas de Colafuria a Marukai en La Ensenada de Zoram."}}
D[6461] = {"Chupasangres",{"Xen'zilla, en Malaka'Jin, necesita que mates 10 trepadores Musgondo y 7 escupevenenos Musgondo."}}
D[6462] = {"El talismán trol",{"Llévale 8 talismanes trols a Mitsuwa en la Avanzada de Zoram'gar."}}
D[6481] = {"El despertar del terráneo",{"Abre el barril de resonita con el cristal de resonita encantado y, a continuación, mata a Goggeroc. Vuelve a ver a Mor'rogal para contarle lo ocurrido y entregarle el cristal de resonita encantado."}}
D[6482] = {"Liberar a Ruul",{"Escolta a Ruul y después habla con Yama Pezuñablanca en el Puesto del Hachazo."}}
D[6501] = {"El Ojo del Dragón",{"Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del Dragón. La única información que tienes sobre dicho ser es que existe."}}
D[6502] = {"Amuleto Pirodraco",{"Tienes que recuperar la sangre de dragón negro Campeón, la tiene el general Drakkisath. Puedes encontrar a Drakkisath en su sala del trono, tras las Salas de la Ascensión, en la Cumbre de Roca Negra."}}
D[6503] = {"Avanzada de Vallefresno",{"Mata a 9 avanzadas de Vallefresno y vuelve junto a Kuray'bin en el Puesto del Hachazo."}}
D[6504] = {"Las páginas perdidas",{"Encuentra las 12 páginas que faltan del manual de instrucciones de trituradora y vuelve a componer con ellas los 3 primeros capítulos. Devuélvele las páginas a Gurda Cicafuria cerca del Puesto del Hachazo."}}
D[6521] = {"Una alianza impía",{"Lleva la cabeza del embajador Malcin a Varimathras, que está en Entrañas."}}
D[6522] = {"Una alianza impía",{"Lleva el pergamino a Varimathras, que está en Entrañas."}}
D[6523] = {"Protege a Kaya",{"Escolta a Kaya Patatleta hasta el Campamento Aparaje y ve a ver a Makaba Patatleta cerca del límite sureste de Espolón."}}
D[6541] = {"Preséntate ante Kadrak",{"Preséntate ante Kadrak en la torre de vigilancia en los Baldíos del Norte."}}
D[6542] = {"Preséntate ante Kadrak",{"Informa a Kadrak en la torre de vigilancia norte en los Baldíos."}}
D[6543] = {"Los informes Grito de Guerra",{"Abre el fardo de informes. Lleva los informes Grito de Guerra al explorador Grito de Guerra, al corredor Grito de Guerra y al escolta Grito de Guerra. Preséntate ante Kadrak en la torre de vigilancia norte en los Baldíos con la información que te hayan dado."}}
D[6544] = {"El asalto de Torek",{"Escolta a Torek en su ataque sobre la Avanzada Ala de Plata contra Duriel Fuegolunar e informa después a Ertog Colmillorrabioso en el Puesto del Hachazo."}}
D[6545] = {"Novedades de corredor Grito de Guerra",{"¿Has vuelto con mis órdenes? Siempre es bueno ver a nuevos reclutas con una naturaleza desbordante y resueltos","","Más vale que aprendas rápido si esperas seguir a la altura aquí. Aumenta la amenaza de los nagasss, <nombre>. He estado observando y hemos reforzado las defensas frente a varios ataques sobre esta avanzada desde que llegué","","Pero si te apetece arrimar el hombro en esta guerra, habla con alguien de la avanzada."}}
D[6546] = {"Novedades de escolta Grito de Guerra",{"El camino está sembrado de peligros, <nombre>. Tenlo bien presente cuando viajes por estas tierras. La amenaza de la Alianza está bastante cerca","","El enemigo nos rodea por todas partes. Los sátiros son la formidable fuerza predominante al este de Vallefresno. Asimismo, he descubierto que los nagasss se han hecho con una vasta extensión de tierra en Azshara","","Es bueno que seguimos incrementando nuestros efectivos, prepárate para lo que se avecina, <nombre>."}}
D[6547] = {"Novedades de explorador Grito de Guerra",{"Mantén los ojos bien abiertos, no-muerto. Los elfos suelen ocultarse en las sombras..","","Siempre debemos estar vigilantes. Hemos trabajado mucho para conseguir esta tierra y los elfos buscan la más mínima oportunidad para arrebatárnosla","","Supongo que tienes mis siguientes órdenes de Kadrak?"}}
D[6548] = {"Venga mi aldea",{"Mata 8 rufianes Tótem Siniestro y 6 mercenarios Tótem Siniestro. A continuación, ve a ver a Makaba Patatleta cerca del límite sureste de Espolón."}}
D[6561] = {"La vileza de Brazanegra",{"Llévale la cabeza del Señor Crepuscular Kelris a Bashana Runatótem en Cima del Trueno."}}
D[6562] = {"Problemas en las profundidades",{"Habla con Je'neu Sancrea en Vallefresno."}}
D[6563] = {"La esencia de Aku'Mai",{"Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno."}}
D[6564] = {"Lealtad a los dioses antiguos",{"Llévale la nota mojada a Je'neu Sancrea en Vallefresno."}}
D[6565] = {"Lealtad a los dioses antiguos",{"Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve junto a Je'neu Sancrea en Vallefresno."}}
D[6566] = {"Lo que trae el viento",{"Escucha a Thrall."}}
D[6567] = {"El Campeón de la Horda",{"Busca a Rokaro en la Aldea Cazasombras, en Desolace."}}
D[6568] = {"Profesora del engaño",{"Entrega la carta de Rokaro a Myranda la Fada en las Tierras de la Peste del Oeste."}}
D[6569] = {"Ilusiones oculares",{"Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada."}}
D[6570] = {"Brasaliza",{"Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca El Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza."}}
D[6571] = {"Suministros Grito de Guerra",{"Reúne los suministros Grito de Guerra: las espadas dentadas Grito de Guerra, cuerda, aceite Grito de Guerra y el envío de hachas de los Grito de Guerra para Locke Okarr en el Puesto del Hachazo."}}
D[6581] = {"Espadas dentadas Grito de Guerra",{"¡Directamente desde Trinquete, las hojas de sierra de los Grito de Guerra! Sí, las tengo aquí mismo","","¿Pero cómo piensas pagarme? No te las puedes quedar y ya está, ¿sabes? ¡Mi tiempo no es barato!","","Lo que de verdad necesito es una buena arma para llevar en mis viajes. Una chica tiene que protegerse, ¿sabes? Hay una escopeta que me gusta mucho y que estoy segura que un ingeniero podría hacer sin problema","","Así que si me traes un trabuco mortífero, te entregaré el cargamento de hojas de sierra. ¿Trato?"}}
D[6582] = {"La prueba de los cráneos, Arúspice",{"Debes encontrar a Arúspice, el Campeón draco del Vuelo Azul y matarlo. Separa su cráneo de su cuerpo y llévaselo a Brasaliza","","Sabes que puedes encontrar a Arúspice en Cuna del Invierno."}}
D[6583] = {"La prueba de los cráneos, Somnus",{"Destruye al Campeón del Vuelo Verde, Somnus. Lleva su cráneo a Brasaliza."}}
D[6584] = {"La prueba de los cráneos, Chronalis",{"Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su cráneo a Brasaliza."}}
D[6585] = {"La prueba de los cráneos, Axtroz",{"Viaja a Grim Batol y encuentra a Axtroz, el Campeón del Vuelo Rojo. Destrúyelo y hazte con su cráneo. Llévaselo a Brasaliza."}}
D[6601] = {"El ascenso",{"Diría que se acabaron las charadas. Ya sabes que el amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en el interior de la Cumbre de Roca Negra. Quizás deberías buscar a Rokaro y explicarle el apuro en el que te encuentras. Enséñale el amuleto Pirodraco apagado. Con un poco de suerte, él sabrá que hay que hacer ahora."}}
D[6602] = {"La sangre de dragón negro Campeón",{"Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y llévasela a Rokaro."}}
D[6603] = {"Problemas en Cuna del Invierno",{"Encuentra a Donova Cubilnevado cerca de las fuentes termales de Cuna del Invierno."}}
D[6604] = {"Lechúcico iracundo",{"Habla con Jaron Tallapiedras en Aldea Estrella Fugaz."}}
D[6605] = {"Algo extraño",{"Habla con Winna Riessgo en Frondavil."}}
D[6606] = {"Un poco de suerte",{"Habla con la médica bruja Mau'ari en Vista Eterna."}}
D[6607] = {"Nat Pagle, pescador del extremo",{"Nat Pagle quiere que pesques los siguientes peces:","","Mahi mahi juncobruma de la Playa Juncobruma del Pantano de las Penas","","1 artillero Sar'theris de la Playa de Sar'theris de Desolace","","1 Ahi de Feralas del Río Verdantis de Feralas","","Latipinia azul de La Costa Salvaje de Vega de Tuercespina","","Cuando los tengas todos, vuelve a buscar a Nat Pagle."}}
D[6608] = {"¡Qué bueno eres!",{"Parece que Lumak piensa que ya no puede enseñarte nada más sobre la pesca. Ve a buscar a su amigo, Nat Pagle, un humano pescador que vive en una isla al sur de Theramore (o eso parece que ha dicho)."}}
D[6609] = {"¡Me has dejado seco!",{"Ve a Kalimdor, a la ciudad costera de Theramore. Busca una isla hacia el sur. ¡Nat Pagle te espera!"}}
D[6610] = {"Sorpresa de almejate",{"Dirge Hojágil quiere que le consigas lo siguiente:","","12 huevos gigantes. Pueden ser huevos de los rocs que deambulan por Tanaris o de cualquier otro pájaro de grandes dimensiones","","10 piezas de carne de almeja sabrosa. ¡Esta la podrás obtener de las almejas, por supuesto!","","20 piezas de queso curado de Alterac. ¡Podrás encontrarlo en cualquier quesería!","","Consigue todo lo que Dirge necesita y llévaselo."}}
D[6611] = {"Ve a Gadgetzan",{"Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias."}}
D[6612] = {"Conozco a un tío...",{"Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias."}}
D[6621] = {"El rey de los Maderiza",{"Coloca el estandarte de Karang en el montículo del tótem de los Maderiza. No permitas que los fúrbolgs destruyan el estandarte. Derrota al jefe Murgut y lleva el tótem de Murgut a Karang Amakkar en Zoram'gar."}}
D[6622] = {"Orden de gravedad",{"Salva a pacientes asignando vendas identificativas para atender sus heridas por orden de gravedad. Debes salvar a 15 pacientes antes de que 6 mueran a consecuencia de sus heridas","","¡Ten presente el orden de prioridad! Los soldados gravemente heridos mueren antes que los soldados malheridos. Los soldados heridos son los que más tardan en morir y solo hay que salvarlos DESPUÉS de identificar y atender a los soldados gravemente heridos y a los soldados malheridos."}}
D[6623] = {"Dispensario de la Horda",{"Ve a Sentencia, en las Tierras Altas de Arathi, y habla con el doctor Gregory Victor sobre incorporarte al Dispensario de la Horda."}}
D[6624] = {"Orden de gravedad",{"Salva a los pacientes utilizando vendas identificativas para ocuparte de sus heridas en orden de gravedad. Debes salvar a 15 pacientes antes de que 6 de ellos mueran a causa de sus heridas","","¡Recuerda el orden en el que debes atender a los pacientes! Los soldados gravemente heridos mueren antes, seguidos de los soldados malheridos. Los soldados heridos leves tardan más en morir y deben ser salvados DESPUÉS de haber salvado a los soldados gravemente heridos y a los soldados malheridos."}}
D[6625] = {"El Dispensario de la Alianza",{"Ve a Theramore, en el Marjal Revolcafango, y habla con el doctor Gustaf VanHowzen sobre incorporarte al Dispensario de la Alianza."}}
D[6626] = {"Un anfitrión del mal",{"Mata a 8 guardias de batalla de Rajacieno y 8 tejespinas Rajacieno y 8 fieles Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno."}}
D[6627] = {"Prueba de conocimiento",{"Responde la pregunta de Braug Espiritoscuro con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés <listo/lista>."}}
D[6628] = {"Prueba de conocimiento",{"Responde la pregunta de Parqual Fintallas con acierto y después habla con él de nuevo. Se quedará en Entrañas hasta que estés <listo/lista>."}}
D[6629] = {"Mata a Grundig Nube Negra",{"Mata a Grundig Nube Negra y 6 toscos Tótem Siniestro. A continuación, ve a ver a Makaba Patatleta cerca del límite sureste de Espolón."}}
D[6641] = {"Vorsha la Azotadora",{"Mantén a salvo a Muglash en su viaje hacia el blandón. Ayúdalo a apagar el blandón y entonces protégelo frente a los nagas","","Si sales <airoso/airosa>, vuelve a la Avanzada de Zoram'gar e informa al corredor Grito de Guerra sobre la muerte de Vorsha la Azotadora."}}
D[6642] = {"El favor de la Hermandad, mena de hierro negro"}
D[6643] = {"El favor de la Hermandad, núcleos ardientes"}
D[6644] = {"El favor de la Hermandad, núcleo de lava",{"Hermandad del torio, S.A. comprende tu difícil situación, no-muerto. Por eso se ha autorizado a Lokthos a negociar","","Ofréceme 1 núcleo de lava y se te concederá el favor de la Hermandad."}}
D[6645] = {"El favor de la Hermandad, cuero del núcleo"}
D[6646] = {"El favor de la Hermandad, gota de sangre de la montaña"}
D[6661] = {"A por las ratas del tren subterráneo",{"Captura a 5 ratas del subterráneo usando la flauta cazarratas. Guía a las ratas hasta Monty. No te olvides de devolver la flauta cuando hayas acabado."}}
D[6662] = {"Mi hermano Niblis.",{"Lleva la caja de carne misteriosa a Niblis, que está en el Depósito del Tren Subterráneo de Ventormenta."}}
D[6681] = {"Mansión Ravenholdt",{"Lleva el Sello de Ravenholdt a Fahrad, que está en la Mansión Ravenholdt, en las colinas de Trabalomas","","Tendrás que poner a prueba tu ingenio por el camino. Ándate con ojo."}}
D[6701] = {"Emblemas de la Hermandad",{"Hace años que luchamos contra la Hermandad. Lo que les falta en habilidad lo compensan con cantidad; ¡no llegamos a matar los suficientes para reducir su población!","","Hemos descubierto que el mejor método es robar sus emblemas. Cuando algún miembro pierde el suyo, digamos que el propio sistema lo elimina","","Róbales los emblemas y dámelos a mí o a uno de los guardias","","Empieza por Durnholde, al sur de aquí."}}
D[6721] = {"El camino del cazador",{"Habla con Dazalar en Dolanaar."}}
D[6722] = {"El camino del cazador",{"Habla con Dazalar en Dolanaar."}}
D[6741] = {"¡Más botines!",{"¡Necesito más restos de armadura, <nombre>! ¿Tienes alguno?"}}
D[6761] = {"La nueva frontera",{"Ve a Darnassus, al Enclave Cenarion y habla con Mathrengyl Garroso."}}
D[6762] = {"Rabine Saturna",{"Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Rabine Saturna. Claro de la Luna se encuentra entre Frondavil y Cuna del Invierno; para llegar, tienes que seguir el camino que sale del Bastión Fauces de Madera."}}
D[6781] = {"Más restos de armadura",{"<nombre>, ¡necesitamos más restos de armadura para los suministros de nuestros soldados!"}}
D[6801] = {"Lokholar, el Señor del Hielo",{"Vengo de Cima del Trueno, <raza>. El propio Cairne ha decidido que ayude al clan Lobo Gélido en estos amargos tiempos","","Pero no perdamos más el tiempo. Debes atacar a nuestros enemigos y traerme su sangre. Cuando tenga suficiente sangre, podrá empezar el ritual del conjuro","","La victoria estará garantizada cuando el Señor Elemental quede liberado sobre el ejército de los Pico Tormenta."}}
D[6804] = {"Agua envenenada",{"Aplica el aspecto de Neptulon a los elementales infectados de las Tierras de la Peste del Este. Lleva 12 de sus brazales que no van a juego y el aspecto de Neptulon al duque Hydraxis a Azshara."}}
D[6805] = {"Sirocosos y reptarenas",{"Acaba con 15 agitadores sirocosos y 15 estruendores del desierto. Después, regresa con Duque Hydraxis en Azshara."}}
D[6821] = {"Ojo del Brasadivino",{"Lleva el ojo del Brasadivino al duque Hydraxis a Azshara."}}
D[6822] = {"El Núcleo de Magma",{"Mata a 1 señor del Fuego, 1 gigante fundido, 1 can del Núcleo anciano y 1 marea de lava y ve a ver al duque Hydraxis a Azshara."}}
D[6823] = {"Agente de Hydraxis",{"Consigue una mención de honor de los Señores del Agua y habla con el duque Hydraxis en Azshara."}}
D[6824] = {"Las manos de los enemigos",{"Lleva las manos de Lucifron, Sulfuron, Gehennas y Shazzrah al duque Hydraxis a Azshara."}}
D[6825] = {"La llamada del aire: flota de Guse",{"Tenemos que preparar la nueva flota de alas de guerra, <raza>! Mis jinetes están listos para un ataque sobre el campo de batalla central pero primero hay que despertar su apetito… prepararlos para el asalto","","Necesito carne de soldados Pico Tormenta, ¡como para alimentar a una flota! ¡Cientos de kilos! Seguro que puedes encargarte de eso, ¿verdad? ¡Andando!"}}
D[6826] = {"La llamada del aire: flota de Jeztor",{"Has trabajado duro, <nombre>, ¡pero es solo el principio!","","Mis alas de guerra deben probar la misma carne de sus objetivos. ¡Esto garantizará un ataque preciso sobre nuestros enemigos!","","Mi flota es la segunda más potente de nuestro mando aéreo. Por consiguiente, atacarán a los más poderosos de nuestros adversarios. Para ello, necesitan la carne de los tenientes Pico Tormenta","","¡Apúrate, soldado!"}}
D[6827] = {"La llamada del aire: flota de Mulverick",{"He pasado días encerrado en un horrible antro de enanos. ¡Vaya si quiero venganza!","","Debemos planificarlo minuciosamente","","Primero mis alas de guerra necesitan objetivos a los que apuntar, objetivos de alta prioridad. Tendré que alimentarlos con carne de los Comandantes Pico Tormenta. Por desgracia, ¡esos malnacidos están atrincherados muy lejos detrás de las líneas enemigas! Ahí tienes un trabajo a tu medida."}}
D[6843] = {"Da Foo"}
D[6844] = {"Umber, el archivista",{"Lleva el objeto silítido taraceado a Umber, el archivista del Círculo Cenarion, en la aldea de Amparo de la Noche, en el Claro de la Luna."}}
D[6845] = {"El descubrimiento de los secretos del pasado",{"Habla con Rabine Saturna en el poblado Amparo de la Noche, en Claro de la Luna."}}
D[6846] = {"¡Al ataque!"}
D[6847] = {"El ojo que todo lo ve del maestro Ryson",{"Recupera el Ojo que todo lo ve del maestro Ryson en las cuevas de los Hacha Invernal y devuélveselo","","Pero ándate con ojo, al parecer el Ojo que todo lo ve del maestro Ryson ¡está maldito!"}}
D[6848] = {"El ojo que todo lo ve del maestro Ryson",{"Recupera el Ojo que todo lo ve del maestro Ryson en las cuevas de los Hacha Invernal y devuélveselo","","Pero ándate con cuidado, al parecer el Ojo que todo lo ve del maestro Ryson ¡está maldito!"}}
D[6861] = {"La unidad trituradora portátil de Zinfizzlex",{"El maestro ingeniero Zinfizzlex quiere que le lleves lo siguiente:","","*30 barras de torio","","*50 barras de mitril","","*75 barras de hierro","","*1 sierra de vapor."}}
D[6862] = {"La unidad trituradora portátil de Zinfizzlex",{"El maestro ingeniero Zinfizzlex quiere que le lleves lo siguiente:","","*30 barras de torio","","*50 barras de mitril","","*75 barras de hierro","","*1 sierra de vapor."}}
D[6881] = {"Ivus, el Señor del Bosque",{"El clan Lobo Gélido está protegido por una contaminación de energía elemental. Su chamán anda metido con poderes que seguramente nos aniquilarían si no nos ocupamos de ellos","","¡El daño se ha extendido demasiado para que el Círculo lo controle! Tenemos que invocar a Ivus para que nos ayude","","Los soldados Lobo Gélido llevan talismanes de elemental llamados cristales de tormenta. Podemos usar estos talismanes para conjurar a Ivus. ¡Adéntrate hasta ese lugar y recupera esos cristales, <nombre>!"}}
D[6901] = {"Lanzar el ataque"}
D[6921] = {"Entre ruinas",{"Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno."}}
D[6922] = {"Barón Aquanis",{"Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno."}}
D[6941] = {"La llamada del aire: la flota de Vipore",{"¡Hay que ocuparse de las unidades de élite de los Lobo Gélido que vigilan las líneas, soldado! Te encargo que diezmes a esa manada de salvajes. Vuelve aquí con las medallas de sus tenientes y legionarios. Cuando me parezca que hemos despachado a suficiente chusma, desplegaré la fuerza aérea."}}
D[6942] = {"La llamada del aire: la flota de Slidore",{"Mis grifos están listos para atacar a las primeras líneas del frente pero no pueden hacerlo hasta que las líneas se reduzcan algo","","Los guerreros Lobo Gélido, encargados de resistir en las primeras líneas del frente, llevan medallas de servicio que lucen orgullosos en la pechera. Arráncales esas medallas de sus podridos cadáveres y tráemelas","","Cuando la primera línea del frente esté suficientemente diezmada, ¡daré la orden de atacar desde el aire! ¡Muerte desde el cielo!"}}
D[6943] = {"La llamada del aire: la flota de Ichman",{"Los ánimos están decaídos, soldado. Tras el fracaso de nuestro último ataque aéreo contra la Horda, ¡se niegan a volar! De ti depende subirles la moral","","Regresa al campo de batalla y ataca directo al corazón del mando de los Lobo Gélido. Acaba con sus comandantes y guardianes. Vuelve aquí y tráeme sus medallas, ¡todas las que te quepan en la talega! Te lo prometo, cuando mis grifos vean el botín y huelan la sangre de nuestro enemigo, ¡volverán a volar! ¡Ahora vete!"}}
D[6961] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Gran Padre Invierno; está cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar."}}
D[6962] = {"Golosinas para el Gran Padre Invierno",{"Lleva 5 galletas de gengibre y leche fría al Gran Padre Invierno a Orgrimmar."}}
D[6963] = {"El robo de las golosinas del Festival de Invierno",{"Localiza al agente de Pastos de Bosquehumeante desaparecido en las zonas nevadas de las Montañas de Alterac."}}
D[6964] = {"El espíritu de esta fiesta",{"Habla con Sagorne Zancresta en el Valle de la Sabiduría de Orgrimmar sobre el festín del Festival de Invierno."}}
D[6981] = {"El fragmento resplandeciente",{"Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento resplandeciente","","Entrega el fragmento como se te indique."}}
D[6982] = {"Suministros de Dentefrío",{"Lleva 10 suministros de Dentefrío al intendente de la Alianza en Dun Baldar."}}
D[6983] = {"¡Qué ruin!",{"Encuentra los regalitos robados y devuélveselos a Kaymard Cobrellizco en Orgrimmar. Se cree que están en posesión de Grinch el Abominable, que se encuentra en algún lugar de las regiones nevadas de las Montañas de Alterac."}}
D[6984] = {"Un agradecimiento de Pastos de Bosquehumeante",{"Habla con Papá Invierno en Orgrimmar."}}
D[6985] = {"Suministros de Ferrohondo",{"Lleva 10 suministros de Ferrohondo al intendente de la Horda en el Bastión Lobo Gélido."}}
D[7001] = {"Establos vacíos",{"Encuentra a un Lobo Gélido en el Valle de Alterac. Usa el bozal Lobo Gélido cuando estés junto a él para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos de los Lobo Gélido. Habla con el maestro de establos para ganarte el crédito por la captura."}}
D[7002] = {"Arneses para carneros de montar",{"Mientras algunos de nuestros soldados están ocupados en la captura de lobos para el maestro de establos, otros deben encargarse de las necesidades básicas de la monta. Me refiero a los arneses para montar, claro","","Debes atacar a los carneros locales de la región. ¡Los mismísimos carneros que la caballería Pico Tormenta usa de montura!","","Acaba con ellos y tráeme sus pieles. Cuando tengamos suficientes pieles, confeccionaremos los arneses para los jinetes. ¡Los Caballeros Lobo de los Lobo Gélido volverán por sus fueros!"}}
D[7003] = {"Gigantes reducidos",{"Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 15 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Ventipnotizador, al embarcadero de La Costa Olvidada de Feralas."}}
D[7021] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar."}}
D[7022] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Papá Invierno; está cerca de la zona comercial de Pastos de Bosquehumeante, en Forjaz."}}
D[7023] = {"¡El Gran Padre Invierno está aquí!",{"Habla con Papá Invierno. Está cerca de la zona de comercio de los Pastos de Bosquehumeante, en Forjaz."}}
D[7024] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar."}}
D[7025] = {"Golosinas para el Gran Padre Invierno",{"Lleva 5 galletas de gengibre y leche fría a Papá Invierno a Forjaz."}}
D[7026] = {"Arneses para carneros de montar"}
D[7027] = {"Establos vacíos",{"Encuentra un carnero de Alterac en el Valle de Alterac. Usa la collera de entrenamiento de Pico Tormenta cuando estés junto al carnero de Alterac para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos. Habla con el maestro de establos para ganarte el crédito por la captura."}}
D[7028] = {"Los males de Maraudon",{"Recoge 15 tallas de cristal terádrico y llévaselas a Willow a Desolace."}}
D[7029] = {"La corrupción de Lenguavil",{"Llena el vial cerúleo cubierto en el estanque naranja de Maraudon","","Aplica vial cerúleo lleno a la hiedravil para que emerja el vástago tóxico","","Cura 8 plantas eliminando su vástago tóxico e informa a Vark Marcaguerra en la Aldea Cazasombras."}}
D[7041] = {"La corrupción de Lenguavil",{"Llena el vial cerúleo cubierto en el estanque naranja de Maraudon","","Aplica vial cerúleo lleno a la hiedravil para que emerja el vástago tóxico","","Cura 8 plantas eliminando su vástago tóxico e informa a Talendria en Punta de Nijel."}}
D[7042] = {"El robo de las golosinas del Festival de Invierno",{"Localiza al agente de Pastos de Bosquehumeante desaparecido en las zonas nevadas de las Montañas de Alterac."}}
D[7043] = {"¡Qué ruin!",{"Encuentra los regalitos robados y devuélveselos a Wulmort Calderilla en Forjaz. Se cree que están en posesión de Grinch el Abominable, que se encuentra en algún lugar de las regiones nevadas de las Montañas de Alterac."}}
D[7044] = {"Leyendas de Maraudon",{"Recupera las 2 partes del cetro de Celebras: la vara y el diamante de Celebras","","Encuentra el modo de hablar con Celebras."}}
D[7045] = {"Un agradecimiento de Pastos de Bosquehumeante",{"Habla con el Gran Padre Invierno en Forjaz."}}
D[7046] = {"El cetro de Celebras",{"Ayuda a Celebras el Redimido mientras reconstruye el cetro de Celebras","","Habla con él después del ritual."}}
D[7061] = {"El festín del Festival de Invierno",{"Lee el libro \"El Festival de Invierno\" si quieres saber más sobre esta fiesta. Cuando termines, entrégaselo a Cairne Pezuña de Sangre en Cima del Trueno."}}
D[7062] = {"El espíritu de esta fiesta",{"Habla con el historiador Karnik del Festival de Invierno en la Liga de Exploradores de Forjaz."}}
D[7063] = {"El Festival de Invierno",{"Lee el libro \"El Festival de Invierno\" si quieres saber más sobre esta fiesta. Cuando termines, entrégaselo al rey Magni Barbabronce de Forjaz."}}
D[7064] = {"Corrupción de la tierra y de la semilla",{"Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace."}}
D[7065] = {"Corrupción de la tierra y de la semilla",{"Mata a la princesa Theradras y ve a ver al vigilante Marandis a Punta de Nijel, en Desolace."}}
D[7066] = {"La semilla de vida",{"Busca a Remulos en Claro de la Luna y dale la semilla de vida."}}
D[7067] = {"Las instrucciones del Paria",{"Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace."}}
D[7068] = {"Trozos Oscuros",{"Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar."}}
D[7070] = {"Trozos Oscuros",{"Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango."}}
D[7081] = {"Los cementerios del Valle de Alterac",{"Asalta un cementerio y vuelve con el sargento Durgen Pico Tormenta en las Montañas de Alterac."}}
D[7082] = {"Los cementerios de Alterac",{"Asalta un cementerio y vuelve con el cabo Teeka Gruñidosangriento en las Montañas de Alterac."}}
D[7101] = {"Las torres y los búnkeres",{"Captura una torre enemiga y vuelve con el cabo Teeka Gruñidosangriento en las Montañas de Alterac."}}
D[7102] = {"Las torres y los búnkeres",{"Destruye el estandarte de una torre enemiga o de un búnker y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac."}}
D[7121] = {"El intendente",{"Habla con el intendente de Pico Tormenta."}}
D[7122] = {"Capturar una mina",{"Captura una mina que no esté bajo control de los Pico Tormenta y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac."}}
D[7123] = {"Habla con nuestro intendente",{"Habla con el intendente de Lobo Gélido."}}
D[7124] = {"Capturar una mina",{"Captura una mina y vuelve con el cabo Teeka Gruñidosangriento en las Montañas de Alterac."}}
D[7141] = {"La batalla de Alterac",{"Adéntrate en el Valle de Alterac, derrota al general Drek'thar de la Horda y vuelve junto a la prospectora Tallapiedra en las Montañas de Alterac."}}
D[7142] = {"La batalla por Alterac",{"Adéntrate en el Valle de Alterac y derrota al general enano Vanndar Pico Tormenta. Vuelve entonces junto a Voggah Presaletal en las Montañas de Alterac."}}
D[7161] = {"Terreno de pruebas",{"Viaja hasta la Caverna Zarpa Salvaje ubicada al sureste del campamento base en el Valle de Alterac y encuentra el estandarte de Lobo Gélido. Devuélvele el estandarte al maestro de guerra Laggrond."}}
D[7162] = {"Terreno de pruebas",{"Viaja hasta la cueva Ala Gélida ubicada al suroeste de Dun Baldar en el Valle de Alterac y recupera el estandarte de Pico Tormenta. Devuélveselo al teniente Haggerdin en las Montañas de Alterac."}}
D[7163] = {"Ascender y darse a conocer"}
D[7164] = {"Honorable con el clan",{"¡Cómo me alegra verte de nuevo, <clase>! No esperaba que regresaras. No obstante, has demostrado ser un valiente y honorable soldado Lobo Gélido","","Ha llegado de nuevo tu hora, <nombre>. Te has ganado un nuevo rango y con ello, una nueva insignia que refleje este aumento de importancia","","Presenta tu insignia."}}
D[7165] = {"Ganarse una reverencia",{"Tantos muertos. La sangre empapa el campo. Y a pesar de ello… estás viva… Has perseverado. Has conducido a nuestros ejércitos a muchas victorias. Por ello, soldado, te has ganado un nuevo rango","","Presenta tu insignia."}}
D[7166] = {"Héroes legendarios",{"Irradias mando y poder, <clase>. Exaltado a los ojos de los Lobo Gélido, el enemigo se encoge ante la simple mención de tu nombre","","En pie, héroe de los Lobo Gélido. ¡Levántate y recibe los honores!","","Presenta tu insignia."}}
D[7167] = {"El ojo del orden",{"Drek'Thar no tiene más que alabanzas para ti. Por todo Kalimdor se cuentan tus hazañas. El Jefe de Guerra está radiante, tu inquebrantable defensa de nuestro clan le ha complacido sobremanera","","Te has ganado el Ojo del Mando","","Presenta tu insignia, comandante <nombre>."}}
D[7168] = {"Ascender y darse a conocer",{"La mayoría no vive lo suficiente para superar su propia mediocridad. Has demostrado ser un soldado ejemplar, <clase>. Ha llegado la hora","","Presenta tu insignia."}}
D[7169] = {"Honorable con la guardia",{"¡Por toda la base se habla de tus hazañas en la Tierra de Disputa! Le has asestado golpes contundentes a nuestro enemigo, ¡aplastándoles la moral! Por eso, te has ganado un rango de honor entre los Pico Tormenta","","Presenta tu insignia."}}
D[7170] = {"Ganarse una reverencia"}
D[7171] = {"Héroes legendarios"}
D[7172] = {"El ojo del orden"}
D[7181] = {"La leyenda de Korrak",{"Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac","","Si Korrak se digna aparecer, destrúyelo y vuelve con el maestro de guerra Laggrond."}}
D[7201] = {"El último elemento",{"Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los golems y a los creadores de golems. Recuerdas que Vivian Latumba también murmuró entre dientes algo sobre los elementales."}}
D[7202] = {"Korrak el Sanguinario",{"Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac","","Si Korrak se digna aparecer, destrúyelo y vuelve con el teniente Haggerdin en las Montañas de Alterac."}}
D[7221] = {"Habla con la prospectora Tallapiedra",{"Habla con la prospectora Tallapiedra en la plaza fuerte de Dun Baldar."}}
D[7222] = {"Habla con Voggah Presaletal",{"Habla con Voggah en el Bastión Lobo Gélido."}}
D[7223] = {"Los trocitos de armadura",{"Llévale 20 trocitos de armadura a Murgot Forjahonda en Dun Baldar."}}
D[7224] = {"Botín enemigo",{"Llévale 20 trocitos de armadura al herrero Regzar en Aldea Lobo Gélido."}}
D[7241] = {"En defensa de Lobo Gélido",{"Dirígete al Valle de Alterac en las Montañas de Alterac. Encuentra al maestro de guerra Laggrond y habla con él para empezar tu carrera como soldado Lobo Gélido; lo encontrarás en la entrada del túnel. El Valle de Alterac se sitúa al norte de Molino Tarren en la falda de las Montañas de Alterac."}}
D[7261] = {"El imperativo soberano",{"Dirígete al Valle de Alterac en las Laderas de Trabalomas. Delante de la entrada del túnel, encuentra al teniente Haggerdin y habla con él","","¡Por la gloria de Barbabronce!"}}
D[7281] = {"Amor fraternal",{"Viaja hasta el territorio de los Pico Tormenta y mata al comandante Karl Filis. Vuelve con el comandante Luis Filis cuando hayas completado la tarea."}}
D[7282] = {"Amor fraternal",{"Viaja hasta el territorio de los Lobo Gélido y mata al comandante Luis Filis. Vuelve con el comandante Karl Filis cuando hayas completado la tarea."}}
D[7301] = {"Señores del Cielo caídos",{"Viaja hasta el territorio de los Lobo Gélido y busca al Comandante del aire Slidore, al comandante del aire Vipore y al comandante del aire Ichman. Vuelve con el comandante Duffy cuando hayas completado la misión."}}
D[7302] = {"Señores del Cielo caídos",{"Averigua qué fue del comandante del aire Guse, el Comandante del aire Jeztor y el comandante del aire Mulverick. Vuelve con el comandante Mulfort cuando hayas completado la misión."}}
D[7321] = {"Sopa de tortuga reconfortante",{"Llévale 10 trozos de carne de tortuga y algunas especias calmantes a Christoph Yabrigo a Molino Tarren."}}
D[7341] = {"Un trato justo",{"Saludos, <raza>. Yo soy Kolark, un <clase> de tesoros de Cima del Trueno. He viajado mucho por el mundo y he visto también mucho","","Mis viajes por los Mares del Sur me permitieron descubrir la existencia de estas flechas con cabeza de torio. Tengo un sinfín de ellas, pero ya no tengo balas. Y bueno, ningún tauren que se precie andaría por ahí con un endeble arco. ¡Las flechas no sirven para nada!","","Te voy a ofrecer un trato: si me traes proyectiles de torio te las cambio por mis cabezales de flecha de torio. ¿Hecho?"}}
D[7342] = {"Las flechas no valen para nada"}
D[7361] = {"Favor entre los Lanza Negra",{"Se te asignado la tarea de matar a los jugadores elfos de la noche en el Valle de Alterac","","Mata a un elfo de la noche y llévale su cabeza decapitada a Najak Malditor en el Bastión Lobo Gélido."}}
D[7362] = {"Aliado de los Tauren",{"Se te asignado la tarea de matar a los jugadores gnomos en el Valle de Alterac","","Mata a un gnomo y llévale un mechón de la víctima a Ravak Tótem Siniestro en el Bastión Lobo Gélido."}}
D[7363] = {"La condición humana",{"Se te asignado la tarea de matar a los jugadores humanos en el Valle de Alterac","","Mata a un humano y vuelve con el comandante Luis Philips (que deambula entre el frente y el Bastión Lobo Gélido) con un hueso de tu víctima","","¡Al fin se avecina una cura para la condición humana!"}}
D[7364] = {"La recompensa de Gnomeregan",{"Se te asignado la tarea de matar a los jugadores adversarios tauren en el Valle de Alterac","","Mata a un tauren y vuelve con Dirk Estafa a Dun'Baldar con una pezuña tauren."}}
D[7365] = {"Réquiem de Corzocelada",{"Se te asignado la tarea de matar a los jugadores trol en el Valle de Alterac","","Mata a un trol y vuelve con Athramanis a Dun'Baldar con el mojo de un trol Lanza Negra."}}
D[7366] = {"La misericordia del arzobispo",{"Se te asignado la tarea de matar a los jugadores renegados en el Valle de Alterac","","Mata a un renegado y vuelve con el comandante Karl Filis (que deambula entre la Serrería y la Mina) con el corazón de tu víctima."}}
D[7367] = {"Acabar con la amenaza",{"Encuentra al experto en explosivos Lobo Gélido y mátalo. Vuelve con el experto en explosivos de Pico Tormenta cuando hayas acabado este trabajo."}}
D[7368] = {"Acabar con la amenaza",{"Encuentra al experto en explosivos de Pico Tormenta y mátalo. Vuelve con el experto en explosivos Lobo Gélido cuando hayas acabado este trabajo."}}
D[7381] = {"El regreso de Korrak",{"Si Korrak el Sanguinario vuelve por la Tierra de Disputa, encuéntralo y acaba con él","","Llévale la calavera de Korrak al maestro de guerra Laggrond en las Laderas de Trabalomas."}}
D[7382] = {"Korrak el Eterno",{"Si Korrak el Sanguinario vuelve por la Tierra de Disputa, encuéntralo y acaba con él","","Llévale la calavera de Korrak al teniente Haggerdin en las Laderas de Trabalomas."}}
D[7383] = {"La corona de la Tierra",{"Llena la ampolla de amatista y devuélvesela a Corithras Furia Lunar, que está en Dolanaar."}}
D[7385] = {"Un galón de sangre",{"Tienes la posibilidad de ofrecer cantidades mayores de sangre de nuestros enemigos. Será un placer aceptar ofrendas de mayor tamaño, <nombre>."}}
D[7386] = {"Recogida de cristal",{"A veces te puedes encontrar atrincherado en la batalla durante varios días o incluso varias semanas. En esos períodos más largos de actividad, puedes acabar recogiendo grandes bloques de cristales de tormenta de los Lobo Gélido","","El Círculo acepta tales ofrendas, <nombre>."}}
D[7401] = {"SE BUSCA: ¡enanos!",{"Se te asignado la tarea de matar a los jugadores enanos en el Valle de Alterac","","Mata a un enano y sácale la espina dorsal. Llévasela al sargento Yazra Gruñido Sangriento en el Bastión Lobo Gélido."}}
D[7402] = {"Se buscan: ¡ORCOS!",{"Se te asignado la tarea de matar a los jugadores orcos en el Valle de Alterac","","Mata a un orco y llévale un colmillo de la víctima al cabo Noreg Pico Tormenta en Dun Baldar."}}
D[7421] = {"Defensa de los Lanza Negra"}
D[7422] = {"Ve a por más mechones"}
D[7423] = {"Más esquirlas de huesos"}
D[7424] = {"¿Y la pezuña?"}
D[7425] = {"Colecta de mojo de Corzocelada"}
D[7426] = {"El amor de un hombre"}
D[7427] = {"Se buscan: ¡MÁS ENANOS!"}
D[7428] = {"Se buscan: ¡MÁS ORCOS!"}
D[7429] = {"¡Libera a Knot!",{"Se llama llave de los grilletes de Gordok... bueno, así es como la llaman esos graciosillos. Creo que podría tenerla cualquiera de los ogros, pero no sé cuáles en concreto. Probablemente podrían tenerla los guardias..","","¿Pero qué estoy diciendo? ¡Si tú ya la tienes! ¡¿No?! ¡¿¿No es eso que tienes ahí??!"}}
D[7441] = {"Pusillín y el ancestro Azj'Tordin",{"Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de Conjuros de Azj'Tordin, por cualquier medio","","Si consigues hacerte con el libro de Conjuros, vuelve al Pabellón de Lariss de Feralas y busca a Azj'Tordin."}}
D[7461] = {"Locura interior",{"Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará","","Entra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum","","Si consigues completar esta misión, ve al patio a buscar a la ancestra Shen'dralar."}}
D[7462] = {"El tesoro de los Shen'dralar",{"Regresa a El Athenaeum y encuentra el tesoro de Shen'dralar. ¡Reclama tu recompensa!"}}
D[7463] = {"El refresco arcano",{"Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al Tradicionalista Lydros que está en El Athenaeum."}}
D[7481] = {"Leyendas élficas",{"Busca a Kariel Winthalus en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres."}}
D[7482] = {"Leyendas élficas",{"Busca a Kariel Winthalus en La Masacre. Vuelve al Bastión Plumaluna a informar al erudita Runaespina de lo que hayas encontrado."}}
D[7483] = {"El tratado sobre rapidez",{"Lleva 1 tratado sobre rapidez, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 2 sangres de héroes al Tradicionalista Lydros a La Masacre para conseguir un arcanum de rapidez."}}
D[7484] = {"El tratado sobre enfoque",{"Lleva 1 tratado sobre enfoque, 1 diamante negro prístino, 4 fragmentos luminosos grandes y 2 pieles de Sombra al Tradicionalista Lydros a La Masacre para conseguir un arcanum de enfoque."}}
D[7485] = {"El tratado sobre protección",{"Lleva 1 tratado sobre protección, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 1 costura desgarrada de abominación al Tradicionalista Lydros a La Masacre para conseguir un arcanum de protección."}}
D[7486] = {"Una recompensa de héroe",{"Recoge tu recompensa en el arca de Hydraxis."}}
D[7487] = {"La armonización con el núcleo",{"Cruza el portal de entrada del Núcleo de Magma en las Profundidades de Roca Negra y recupera un fragmento de núcleo. Vuelve con Lothos Levantagrietas en la Montaña Roca Negra cuando hayas recuperado el fragmento de núcleo."}}
D[7488] = {"La Membrana de Lethtendris",{"Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas."}}
D[7489] = {"La Membrana de Lethtendris",{"Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas."}}
D[7490] = {"Victoria para la Horda",{"LLeva la cabeza de Onyxia a Thrall a Orgrimmar."}}
D[7491] = {"Para que todos lo vean",{"Busca al Señor Supremo Runthak en el Valle de la Fuerza."}}
D[7492] = {"Campamento Mojache",{"Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida."}}
D[7493] = {"El viaje acaba de empezar"}
D[7494] = {"Bastión Plumaluna",{"Habla con Latronicus Lanzaluna. Lo encontrarás en el Bastión Plumaluna de Feralas."}}
D[7495] = {"Victoria para la Alianza",{"Lleva la cabeza de Onyxia al Alto Señor Bolvar Fordragon, en Ventormenta."}}
D[7496] = {"Celebrar los buenos momentos",{"Busca al mayor Mattingly en el Valle de los Héroes."}}
D[7497] = {"El viaje acaba de empezar"}
D[7498] = {"Garona: Un Estudio sobre el Sigilo y la Traición.",{"Devuelve el libro a sus legítimos dueños."}}
D[7499] = {"Códice de Defensa",{"Devuelve el libro a sus legítimos dueños."}}
D[7500] = {"El libro de cocina del Arcanista",{"Devuelve el libro a sus legítimos dueños."}}
D[7501] = {"La Luz y cómo alterarla",{"Devuelve el libro a sus legítimos dueños."}}
D[7502] = {"Sombras acechadoras",{"Devuelve el libro a sus legítimos dueños."}}
D[7503] = {"La mejor raza de cazadores",{"Devuelve el libro a sus legítimos dueños."}}
D[7504] = {"Sagrada Bologna: lo que la Luz nunca te dirá",{"Devuelve el libro a sus legítimos dueños."}}
D[7505] = {"El choque de Escarcha y tú",{"Devuelve el libro a sus legítimos dueños."}}
D[7506] = {"El Sueño Esmeralda",{"Devuelve el libro a sus legítimos dueños."}}
D[7507] = {"Compendio de Foror",{"Devuelve el Compendium of Dragon Slaying de Foror a El Athenaeum."}}
D[7508] = {"Forjar Quel'Serrar",{"Entrega la hoja élfica desafilada Tradicionalista Lydros."}}
D[7509] = {"Forjar Quel'Serrar",{"Debes conseguir que Onyxia escupa fuego sobre la hoja antigua sin templar. Una vez hecho, recógela: ahora su hoja está candente. Pero ten cuidado: una hoja candente no permanecerá así para siempre, no tienes tiempo que perder","","Antes de volver a mí, tienes que terminar lo empezado: debes matar a la bestia e introducir la hoja candente en su cadáver","","Hazlo y Quel'Serrar será tuya."}}
D[7521] = {"Thunderaan el Hijo del Viento",{"Para liberar a Thunderaan el Hijo del Viento de su cárcel, debes entregarle al alto señor Demitrian la mitad izquierda y la derecha del vínculo del Hijo del Viento, 10 lingotes de elementium y la esencia del Señor del Fuego."}}
D[7522] = {"Examina la vasija",{"Examina la vasija de renacer y devuélvesela al alto señor Demitrian."}}
D[7541] = {"Un servicio para la Horda",{"Nuestros estudiosos tardarán un tiempo en analizar el colgante que nos trajiste. Pero quiero ofrecerte una pequeña recompensa por el trabajo que has hecho para la Horda","","Gracias, <nombre>. Tus actos te honran a ti, y también a nosotros."}}
D[7562] = {"Mor'zul Sangredoble",{"Habla con Mor'zul Sangredoble en Las Estepas Ardientes."}}
D[7563] = {"La ira de sangre",{"Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes."}}
D[7564] = {"Ojosalvajes",{"Llévale el estuche de sangre a Gorzeeki Ojosalvajes en Las Estepas Ardientes."}}
D[7581] = {"Las selladuras de la prisión",{"Viaja a La Masacre en Feralas y consigue 15 muestras de sangre de sátiro del sátiro Mala Hierba que habita en el Barrio Alabeo. Cuando hayas acabado, ve a ver a Daio a la Escara Ímpia."}}
D[7582] = {"El revestimiento de la prisión",{"Viaja a la Garganta Negro Rumor en Cuna del Invierno y recoge 5 Lágrimas de los Hederine de los demonios Hederine que ocupan la garganta. Cuando hayas cumplido tu tarea, ve a ver a Daio a la Escara Ímpia."}}
D[7583] = {"Supresión",{"Aventúrate en la Escara Ímpia y localiza a un comandante Guardia apocalíptico","","Utiliza la prisión de cristal resplandeciente para atrapar al comandante Guardia apocalíptico. Prepárate para una sucesión de ataques pues el demonio intentará escapar","","Si tienes éxito, llévale el Guardia apocalíptico encarcelado a Daio, que está en la Escara Ímpia."}}
D[7601] = {"La orden de Niby",{"Habla con Diblis en Frondavil."}}
D[7602] = {"Esencia inferi pura",{"Diblis de Frondavil te ha pedido que le lleves 3 esencias inferi puras que provengan de 3 lugares distintos","","Los sátiros Legashi de Azshara tienen la esencia inferi pura de su región. Los Legionarios Jaedenar de Jaedenar tienen la esencia inferi pura de su región. Los guardias viles de Las Tierras Devastadas tienen la esencia inferi pura de su región","","Reúne las esencias inferi puras y vuelve con Diblis a Frondavil."}}
D[7603] = {"El núcleo infernal de Kroshius",{"Busca los restos de Kroshius en la Cañada Gran Cicatriz de Frondavil. Cuando localices sus restos, utiliza el fuego inferi cerca de ellos y espera el regreso de Kroshius. Cuando el infernal se haya despertado, acaba con él y extrae de su cuerpo el núcleo infernal de Kroshius","","Lleva el núcleo infernal de Kroshius a Niby el Todopoderoso a Frondavil."}}
D[7604] = {"Un contrato vinculante",{"Entrégale el contrato de La Hermandad del torio a Lokhtos Tratoscuro si quieres recibir los planes de Sulfuron."}}
D[7621] = {"Un aviso"}
D[7622] = {"Equilibrio de Luz y Sombras",{"Salva a 50 campesinos antes de que 15 sean asesinados. Habla con Eris Feleste si tienes éxito","","Puedes ver el Poste de la muerte para ver cuántos campesinos han sido asesinados."}}
D[7623] = {"Lord Pesadilla",{"Cómprale pociones enigmáticas a Gorzeeki en Las Estepas Ardientes","","Usa la pociones para viajar por Jaedenar y habla con Lord Pesadilla."}}
D[7624] = {"Ulathek el Traidor",{"Enfréntate a Ulathek y llévale el corazón del traidor a Lord Pesadilla en Jaedenar."}}
D[7625] = {"Polvo estelar xorothiano",{"Cómprale polvo estelar xorothiano a Ur'dan. Llévaselo a Gorzeeki Ojosalvajes en Las Estepas Ardientes."}}
D[7626] = {"La Campana de Dethmoora",{"Llévale 2 elixires de poder de las sombras a Gorzeeki Ojosalvajes en Las Estepas Ardientes."}}
D[7627] = {"Rueda de la Marcha Negra",{"Llévale 6 fragmentos luminosos grandes y 25 minerales de hierro negro a Gorzeeki Ojosalvajes en Las Estepas Ardientes."}}
D[7628] = {"La Vela del Apocalipsis",{"Lleva 3 escamas de dragón negro a Gorzeeki Ojosalvajes a Las Estepas Ardientes."}}
D[7629] = {"Entrega de diablillo",{"Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el papiro llévale el tarro a Gorzeeki Ojosalvajes."}}
D[7630] = {"La arcanita",{"Lleva una barra de arcanita a Gorzeeki Ojosalvajes a Las Estepas Ardientes."}}
D[7631] = {"Corcel nefasto xorothiano",{"Lee las instrucciones de Mor'zul. Invoca a un corcel nefasto xorothiano, derrótalo y después vincula su espíritu al tuyo."}}
D[7632] = {"La hoja antigua",{"Encuentra al dueño de la hoja petrificada vieja. Buena suerte, <nombre>; este es un mundo enorme..."}}
D[7633] = {"Una presentación"}
D[7634] = {"Carcaj antiguo cosido con tendón",{"Hastat el anciano te ha pedido que le lleves 1 tendón de dragón azul maduro. Si lo encuentras, llévaselo a Hastat a Frondavil."}}
D[7635] = {"La cuerda adecuada",{"Estoma el Anciano te ha pedido que le lleves 1 tendón de dragón negro maduro. Si lo encontraras, llévaselo a Estoma a Frondavil."}}
D[7636] = {"El bastón de los Ancestros",{"Debes encontrar y destruir a estos 4 corruptores demoníacos:","","Simone la Seductora","","Klinfran el Enloquecido","","Solenor el Destripador","","Artorius el Fatídico","","Destruye a estas criaturas, vuelve a Frondavil y entrega sus cabezas a Vartrus el Ancestro","","Busca pistas de su paradero en la corteza petrificada","","DEBES completar esta misión tú <solo/sola>."}}
D[7637] = {"Énfasis en el sacrificio",{"Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo."}}
D[7638] = {"Lord Grayson Quiebrasombras",{"Habla con Lord Grayson Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7639] = {"Mostrarse juicioso",{"Devuelve el incensario de exorcismos a Lord Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7640] = {"Exorcismo en Valle del Terror",{"Utiliza el incensario de exorcismos para expulsar los espíritus que atormentan el Valle del Terror. Cuando hayas matado 25 espíritus del Valle del Terror, vuelve a ver a Lord Grayson Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7641] = {"El trabajo de Grimand Elmore",{"Habla con Grimand Elmore en el Distrito de los Enanos, en Ventormenta."}}
D[7642] = {"Recopilación de artículos",{"Lleva 40 paños rúnicos, 6 lingotes de arcanita, 10 lágrimas de Arthas, 5 frascos de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta."}}
D[7643] = {"El antiguo espíritu equino",{"Consigue comida para caballos para alimentar a un espíritu equino. Por lo visto, Merideth Carlson, en Costasur, tiene esa comida","","Ve a la mazmorra de La Masacre, en Feralas y mata a Tendris Madeguerra. Al hacerlo, liberarás al antiguo espíritu equino. Dale la comida para caballos y lo aplacarás. Por último, dale la gualdrapa de arcanita para que la bendiga."}}
D[7644] = {"La gualdrapa de arcanita bendita",{"Devuelve la gualdrapa de arcanita bendita a Lord Grayson Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7645] = {"Alimento para caballos enriquecido con maná",{"Consigue 20 galletas enriquecidas con maná, ingrediente principal del alimento especial para caballos, y llévaselas a Merideth Carlson a las Laderas de Trabalomas, en Costasur. Solo El Alba Argenta fabrica esas galletas","","También tienes que darle 50 piezas de oro para aplacar su orgullo herido."}}
D[7646] = {"El cristal de adivinación",{"Lleva un diamante de Azeroth y un diamante negro prístino a Lord Grayson Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7647] = {"Juzgar y redimir",{"Utiliza el cristal de adivinación en el centro del sótano de El Gran Osario en Scholomance. Al hacerlo, aparecerán los espíritus que tienes que juzgar. Si derrotas a esos espíritus, aparecerá el Caballero de la Muerte Atracoscuro. Acaba con él y reclama el alma perdida del destrero caído","","Entrega el alma redimida del destrero y la gualdrapa encantada bendecida al destrero caído de Atracoscuro."}}
D[7648] = {"Un trabajo bien hecho",{"Lleva la gualdrapa de arcanita a Lord Grayson Quiebrasombras en el Distrito de la Catedral de Ventormenta para que la inspeccione."}}
D[7649] = {"Las mallas de placas en torio encantado: volumen I",{"Devuelve el libro a sus legítimos dueños."}}
D[7650] = {"Las mallas de placas en torio encantado: volumen II",{"Devuelve el libro a sus legítimos dueños."}}
D[7651] = {"Las mallas de placas en torio encantado: volumen III",{"Devuelve el libro a sus legítimos dueños."}}
D[7652] = {"Una ganga azulada",{"Muy bien, señor, te voy a ofrecer un buen trato","","Quiero deshacerme de estos diseños de esta armadura de placas imperiales y necesito a alguien que cargue con ellos. Todo lo que quiero a cambio es algunas barras de torio. ¿Te parece bien?"}}
D[7653] = {"Cinturón de placas imperiales"}
D[7654] = {"Botas de placas imperiales"}
D[7655] = {"Brazales de placas imperiales"}
D[7656] = {"Peto de placas imperiales"}
D[7657] = {"Yelmo de placas imperiales"}
D[7658] = {"Leotardos de placas imperiales"}
D[7659] = {"Sobrehombros de placas imperiales"}
D[7660] = {"Intercambio de lobos: lobo ártico"}
D[7661] = {"Intercambio de lobos: lobo rojo"}
D[7662] = {"Nuevo kodo: cerceta"}
D[7663] = {"Nuevo kodo: verde"}
D[7664] = {"Sustitución de raptor marfil"}
D[7665] = {"Sustitución de raptor rojo"}
D[7666] = {"El regreso a El Gran Osario"}
D[7667] = {"Asistencia material",{"Si te interesa ayudar a Sagorne Montacresta, llévale 1 diamante de Azeroth y 1 diamante negro prístino al Valle de la Sabiduría, en Orgrimmar."}}
D[7668] = {"La amenaza de Atracoscuro",{"Usa el cristal de adivinación en el corazón del sótano de El Gran Osario en Scholomance. Al hacerlo se presentarán los espíritus a los que tienes que enfrentarte. La derrota de estos espíritus invoca al Caballero de la Muerte Atracoscuro, derrótalo","","Llévale la cabeza de Atracoscuro a Sagorne Zancresta en el Valle de la Sabiduría, en Orgrimmar."}}
D[7669] = {"El regreso a El Gran Osario"}
D[7670] = {"Lord Grayson Quiebrasombras",{"Habla con Lord Grayson Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7671] = {"Sustitución de sable de hielo"}
D[7672] = {"Sustitución de sable de la noche"}
D[7673] = {"Intercambio de carnero de escarcha"}
D[7674] = {"Intercambio de carnero negro"}
D[7675] = {"Sustitución de mecazancudo azul hielo"}
D[7676] = {"Sustitución de mecazancudo blanco"}
D[7677] = {"Intercambio de semental blanco"}
D[7678] = {"Intercambio de palomino"}
D[7681] = {"Hunter test quest",{"Alimenta a tu mascota y luego habla con el asignador de misión."}}
D[7682] = {"Hunter test quest2",{"Alimenta a tu mascota y luego habla con el asignador de misión."}}
D[7701] = {"SE BUSCA: sobrestante Maltorius",{"El traidor Hierro Negro llamado sobrestante Maltorius está en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego","","Mátalo y lleva su cabeza al capitán de vigía Lolo Zancalarga a La Garganta de Fuego para recibir tu recompensa."}}
D[7703] = {"El asunto inacabado de Gordok",{"Encuentra el guante del Poderío de Gordok y llévaselo al capitán Kromcrush a La Masacre","","Según Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok."}}
D[7721] = {"Combustible para el Ultra-reductor",{"Reúne 10 núcleos de elemental de agua de los elementales marinos y los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Ventipnotizador, que está cerca del embarcadero."}}
D[7722] = {"¿Qué pasa con el flujo?",{"Busca la receta de fluido ardiente robada por el vigía Maltorius en La Fosa de la Escoria de La Caldera. Llévasela al maestro herrero Cremación a La Garganta de Fuego."}}
D[7723] = {"¡Malditos dedos gordos!",{"Hansel Manospesadas quiere que mates 20 gólems de guerra pesados","","Suelen estar cerca de La Caldera en La Garganta de Fuego. Después ve a ver a Hansel a La Garganta de Fuego."}}
D[7724] = {"Amenaza abrasadora",{"Hansel Manospesadas quiere que mates 20 arañas de lava superiores en La Garganta de Fuego. Las encontrarás en las mesetas y los estanques de lava de La Garganta de Fuego","","Cuando hayas matado suficientes arañas de lava superiores ve a ver a Hansel Manospesadas a La Garganta de Fuego."}}
D[7725] = {"Encoge más gigantes",{"Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 10 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Ventipnotizador, al embarcadero de La Costa Olvidada de Feralas."}}
D[7726] = {"Más combustible para el Ultra-reductor",{"Reúne 6 núcleos de elemental de agua de los elementales marinos y los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Ventipnotizador, que está cerca del embarcadero."}}
D[7727] = {"¿Incendosaurio? Loqueseasaurio más bien",{"Hansel Manospesadas quiere que mates 20 incendosaurios","","Suelen estar en los estanques de lava de La Fosa de la Escoria. La Fosa de la Escoria está en La Caldera de La Garganta de Fuego","","Cuando hayas matado suficientes incendosaurios ve a ver a Hansel Manospesadas a La Garganta de Fuego."}}
D[7728] = {"OBJETOS ROBADOS: Tobera y catalejo",{"Encuentra la tobera y el catalejo y llévaselos al capataz Scrange a La Garganta de Fuego","","Lo único que sabes es que fueron robados por enanos Hierro Negro. La tobera es una herramienta de herrero y el catalejo es un instrumento muy valioso para los oteadores."}}
D[7729] = {"OPORTUNIDAD LABORAL: Acabar con la competencia",{"Mata a 15 Capataces y 15 esclavistas Hierro Negro y ve a ver al capataz Scrange a La Garganta de Fuego."}}
D[7730] = {"Infestación de Zukk'ash",{"Lleva 20 caparazones Zukk'ash a Hadoken Zancoveloz al Campamento Mojache de Feralas."}}
D[7731] = {"Latigador con aguijón",{"Derrota a latigador con aguijón en Las Galerías Retorcidas y lleva sus glándulas a Hadoken Zancoveloz al Campamento Mojache de Feralas."}}
D[7732] = {"El informe Zukk'ash",{"Entrega a Zilzibin Tambor Sabio el informe del campamento Mojache Zukk'ash. Reside en La Calle Mayor de Orgrimmar."}}
D[7733] = {"Calidad mejorada",{"Lleva 10 pellejos de yeti Cicatriz de Rabia a Pratt McGrubben al Bastión Plumaluna en Feralas."}}
D[7734] = {"Calidad mejorada",{"Lleva 10 pellejos de yeti Cicatriz de Rabia a Jangdor Zancoveloz al Campamento Mojache de Feralas."}}
D[7735] = {"Pellejo de yeti prístino",{"Lleva el pellejo de yeti prístino a Pratt McGrubben al Bastión Plumaluna de Feralas."}}
D[7736] = {"Fabricar flujo ígneo con sangrerregia",{"Mi tiempo es demasiado valioso para perderlo con charlas, <raza>. Quiero fabricar más fluido ardiente","","Para eso, necesito que me traigas lo siguiente:","","*Escamas de incendosaurio","","*Sangrerregia","","*Carbón","","¡Tráeme tanto como puedas!","","Y tan rápido como puedas, si es que quieres ganarte el favor de la Hermandad."}}
D[7737] = {"Ganarse el respeto",{"Has subido los peldaños de la jerarquía de la Hermandad, <raza>. Te estás ganando nuestro favor, ¡lo que es todo un logro!","","Si quieres más trabajo y lograr aún más respeto, escucha","","Podemos refinar el flujo ígneo añadiendo un poco de residuo de hierro negro a la mezcla","","Ve a las Profundidades de Roca Negra y tráeme todo el residuo de hierro negro que encuentres."}}
D[7738] = {"Pellejo de yeti perfecto",{"Lleva los pellejos de yeti perfecto a Jangdor Zancoveloz al Campamento Mojache de Feralas."}}
D[7741] = {"Elogios del Círculo Esmeralda <NYI> <TXT>"}
D[7761] = {"Orden de Puño Negro",{"¡Será estúpido ese orco! Al parecer, tienes que encontrar la enseña y ganar la marca de Drakkisath para poder acceder al orbe de orden","","Según la carta, el general Drakkisath guarda la enseña. Quizás deberías investigarlo."}}
D[7781] = {"Señor de Roca Negra",{"Lleva la cabeza de Nefarian al Alto Señor Bolvar Fordragon, en Ventormenta."}}
D[7782] = {"Señor de Roca Negra",{"Vete al Valle de los Héroes, en Ventormenta, y habla con el alguacil de campo Afrasiabi."}}
D[7783] = {"Señor de Roca Negra",{"LLeva la cabeza de Nefarian a Thrall a Orgrimmar."}}
D[7784] = {"Señor de Roca Negra",{"Habla con el Alto Señor Supremo Colmillosauro en Orgrimmar. Te espera en el Valle de la Fuerza."}}
D[7785] = {"Examina la vasija",{"Lleva la vasija de Renacimiento al Alto Señor Demitrian."}}
D[7786] = {"Thunderaan, el Hijo del Viento",{"Para liberar a Thunderaan Hijo del Viento tienes que llevar sus 2 brazales, 10 barras de elementium y la esencia del Señor del Fuego al Alto Señor Demitrian a Silithus."}}
D[7787] = {"¡Arriba, Trueno Furioso!",{"Lleva la hoja besada por el viento durmiente al Alto Señor Demitrian."}}
D[7788] = {"¡Expulsa al invasor!",{"Entra en la Garganta Grito de Guerra y derrota a la Horda, obtén una marca de Honor de Grito de Guerra y vuelve con la centinela Cantolongo en el Claro Ala de Plata."}}
D[7789] = {"Acaba con los usurpadores Ala de Plata",{"Entra en la Garganta Grito de Guerra y derrota a la Alianza, obtén una marca de Honor de Grito de Guerra y llévasela al capitán Trizacráneo en el Campamento de Mor'shan."}}
D[7791] = {"Un donativo de lana"}
D[7792] = {"Un donativo de lana",{"Estamos recogiendo donaciones de paño de lana. Una donación de 60 retales de paño de lana te hará ganar el reconocimiento Darnassus por tu generosidad. Tenemos el almacén casi vacío. Si tú pudieras donarnos 60 retales y consiguiéramos más de otras gentes del reino, conseguiríamos cumplir nuestro objetivo","","Si tienes los 60 retales de paño de lana y estás dispuesto a donarlos, puedo aceptar tu donativo ahora mismo."}}
D[7793] = {"Un donativo de seda"}
D[7794] = {"Un donativo de tejido mágico"}
D[7795] = {"Un donativo de paño rúnico",{"<nombre>, has contribuido generosamente a nuestra campaña de abastecimiento de telas. Nosotros también estamos trabajando duro, pero aún tenemos escasez de paño rúnico. ¡Y lo necesitamos urgentemente! ¡Espero que puedas ayudarnos, tal y como has hecho otras veces!","","Si deseas ayudar, tráeme todo el paño rúnico que puedas reunir. Empezaremos por aceptar una única donación de 60 retales y luego ya iremos viendo."}}
D[7796] = {"Un donativo extra de paño rúnico",{"Saludos, una vez más, <nombre>. Seguimos necesitando paño rúnico y aceptamos cualquier donativo, si es que deseas colaborar. Si me traes un nuevo donativo de 20 retales de paño rúnico, me aseguraré de que Ventormenta reconozca tus esfuerzos","","Cuando desees entregarme el donativo de paño rúnico, lo aceptaré."}}
D[7797] = {"Desgarrador dimensional: Vista Eterna"}
D[7798] = {"Un donativo de seda"}
D[7799] = {"Un donativo de tejido mágico",{"Nos estamos quedando sin paño mágico, nos vendría bien tu ayuda para reabastecer nuestro almacén. Si contamos a toda la comunidad, solo necesitaríamos que nos donaras 60 retales de paño mágico para alcanzar nuestro objetivo. ¡Y te aseguro que Darnassus no podrá menos que notar tu generosidad!","","Si tienes los 60 retales de paño mágico y estás dispuesto a donarlos, puedo aceptar tu donativo ahora mismo."}}
D[7800] = {"Un donativo de paño rúnico",{"<nombre>, has contribuido generosamente a nuestra campaña de abastecimiento de telas. Nosotros también estamos trabajando duro, pero aún tenemos escasez de paño rúnico. ¡Y lo necesitamos urgentemente! ¡Espero que puedas ayudarnos, tal y como has hecho otras veces!","","Si deseas ayudar, tráeme todo el paño rúnico que puedas reunir. Empezaremos por aceptar una única donación de 60 retales y luego ya iremos viendo."}}
D[7801] = {"Un donativo extra de paño rúnico"}
D[7802] = {"Un donativo de lana",{"Estamos haciendo una colecta de paño de lana. Si nos das 60 piezas de paño de lana, ganarás el reconocimiento de Forjaz por tu generosidad. Con 60 piezas por tu parte es suficiente; conseguiremos más por otros medios","","Si tienes las 60 piezas de paño de lana y las quieres donar, puedo cogerlas ahora."}}
D[7803] = {"Un donativo de seda",{"Nuestras reservas de seda, como las de los demás tejidos, están en su nivel mínimo. Si tú pudieras donarnos 60 paños de seda y consiguiéramos más de otras gentes, lograríamos cumplir nuestro objetivo","","Si me permites, un regalo tan generoso como la seda aumentaría sin duda tu reputación en la comunidad... Si tienes los 60 paños de seda y quieres donarlos, puedo aceptar tu donativo ahora mismo."}}
D[7804] = {"Un donativo de tejido mágico"}
D[7805] = {"Un donativo de paño rúnico"}
D[7806] = {"Un donativo extra de paño rúnico",{"¡Saludos, <nombre>! Seguimos necesitando paño rúnico; si quieres seguir ayudándonos, te lo agradeceremos. Una donación de 20 piezas te valdrá la admiración y el respeto de Forjaz","","Puedes darme el paño rúnico cuando quieras."}}
D[7807] = {"Un donativo de lana"}
D[7808] = {"Un donativo de seda"}
D[7809] = {"Un donativo de tejido mágico"}
D[7810] = {"El maestro de la arena",{"Habla con Corto John Mitril en la Arena de la Vega de Tuercespina."}}
D[7811] = {"Un donativo de paño rúnico"}
D[7812] = {"Un donativo extra de paño rúnico",{"¡Saludos, <nombre>! Seguimos necesitando paño rúnico; si quieres seguir ayudándonos, te lo agradeceremos. Una donación de 20 piezas te valdrá la admiración y el respeto de los Exiliados de Gnomeregan","","Puedes darme el paño rúnico cuando quieras."}}
D[7813] = {"Un donativo de lana",{"Estamos recogiendo donaciones de paño de lana. Una donación de 60 retales de paño de lana te hará ganar el reconocimiento de Entrañas por tu generosidad. Tal y como está nuestro almacén, solo necesitamos que nos entregues 60 retales, pues las otras gentes del reino nos ayudarán a conseguir nuestro objetivo","","Si tienes los 60 retales de paño de lana y estás dispuesta a donarlos, puedo aceptar tu donativo ahora mismo."}}
D[7814] = {"Un donativo de seda",{"Nuestras reservas de seda, como de los demás tejidos, están casi bajo mínimos. Tal y como está nuestro almacén, solo necesitamos que nos entregues 60 retales de seda pues con la ayuda de los demás lograríamos cumplir nuestro objetivo","","Un regalo tan generoso como la seda aumentaría sin duda tu reputación en la comunidad… Si tienes los 60 retales de paño de seda y estás dispuesto a donarlos, puedo aceptarlos ahora mismo."}}
D[7815] = {"Los quijafortes",{"Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates 15 quijafortes marinos. Ve a verlo cuando hayas terminado."}}
D[7816] = {"Gammerita",{"Katoom el Pescador, del Poblado Sañadiente en las Tierras del Interior, quiere que mates a Gammerita y que le saques el cebo del estómago","","Dijo que Gammerita está en la costa con las otras tortugas."}}
