D[8190] = {"Maleficio de mala suerte",{"Zanza puede crear los antiguos encantamientos trol si dispone de los componentes adecuados","","El primero es un ídolo Hakkari primigenio que debe obtenerse de los más poderosos de los tenientes Hakkari: Jin'do y el Señor sangriento","","El segundo es una Muñeca vudú perforada. Las podrás encontrar en las pilas de desechos que cubren ese maldito lugar. Mira en los montones de residuos","","¡Tráeme estas cosas y te crearé un poderoso encantamiento!"}}
D[8191] = {"Aura profética",{"Zanza puede crear los antiguos encantamientos trol si dispone de los componentes adecuados","","El primero es un ídolo Hakkari primigenio que debe obtenerse de los más poderosos de los tenientes Hakkari: Jin'do y el Señor sangriento","","El segundo es una Muñeca vudú perforada. Las podrás encontrar en las pilas de desechos que cubren ese maldito lugar. Mira en los montones de residuos","","¡Tráeme estas cosas y te crearé un poderoso encantamiento!"}}
D[8192] = {"Caricia del animista"}
D[8193] = {"Maestro pescador"}
D[8194] = {"Aprendiz pescador",{"Aunque ya tenemos un ganador del concurso, aún quiero comprarte el pezrico a un precio razonable. ¿Qué dices?"}}
D[8195] = {"Las monedas Zulian, Razzashi y Hakkari",{"Necesito los Dechados de Poder conocidos como Monedas de las Tribus. Son la moneda que utilizan los distintos habitantes de Zul'Gurub y todas ellas están imbuidas con un sutil pero potente mojo","","Hay nueve tipos diferentes. Mis compatriotas buscan algunas de ellas para las distintas armaduras que ofrecen a los héroes Zandalar. Si tuvieras alguna de sobra te la cambiaré tres de ellas por una de nuestras marcas de honor. Puedes utilizar las marcas con Rin'wosho el Mercader, a cambio te ofrecerá objetos especiales."}}
D[8196] = {"Mangos de esencia"}
D[8201] = {"Una colección de cabezas",{"Ata 5 cabezas de los canalizadores y regresa con ellas a Exzhal en la isla Yojamba."}}
D[8221] = {"Pez raro: pez ángel de Keefer"}
D[8222] = {"Sangre de escórpido resplandeciente"}
D[8223] = {"Más sangre de escórpido resplandeciente"}
D[8224] = {"Pez raro: pez reina de Dezian"}
D[8225] = {"Pez raro: azulín a rayas de Brownell"}
D[8227] = {"Cinta métrica de Nat",{"Devuelve la Cinta métrica de Nat a Nat Pagle en el Marjal Revolcafango."}}
D[8228] = {"¿Puedo tener un folleto de pesca?"}
D[8229] = {"¿Puedo tener un folleto de pesca?"}
D[8230] = {"La misión de prueba de Collin"}
D[8231] = {"Los vándalos marinos",{"Llévale 6 escamas de vándalo marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}}
D[8232] = {"El draco verde",{"Llévale el diente de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}}
D[8233] = {"Un pedido sencillo",{"Habla con Lord Jorach Ravenholdt en la Mansión Ravenholdt."}}
D[8234] = {"Bolsa azur sellada",{"Recupera la bolsa azur sellada del chamán Fauces de Madera en Azshara. Llévale entonces la bolsa al archimago Xylem, que también se encuentra en Azshara."}}
D[8235] = {"Los trozos codificados",{"Llévale 10 fragmentos codificados al archimago Xylem en Azshara."}}
D[8236] = {"La llave azur",{"Devuélvele la llave azur a Lord Jorach Ravenholdt."}}
D[8238] = {"Las monedas Gurubashi, Vilrama y Secacorteza",{"Necesito los Dechados de Poder conocidos como Monedas de las Tribus. Son la moneda que utilizan los distintos habitantes de Zul'Gurub y todas ellas están imbuidas con un sutil pero potente mojo","","Hay nueve tipos diferentes. Mis compatriotas buscan algunas de ellas para las distintas armaduras que ofrecen a los héroes Zandalar. Si tuvieras alguna de sobra te la cambiaré tres de ellas por una de nuestras marcas de honor. Puedes utilizar las marcas con Rin'wosho el Mercader, a cambio te ofrecerá objetos especiales."}}
D[8239] = {"Las monedas Furiarena, Machacacráneos y Sangrapellejo",{"Necesito los Dechados de Poder conocidos como Monedas de las Tribus. Son la moneda que utilizan los distintos habitantes de Zul'Gurub y todas ellas están imbuidas con un sutil pero potente mojo","","Hay nueve tipos diferentes. Mis compatriotas buscan algunas de ellas para las distintas armaduras que ofrecen a los héroes Zandalar. Si tuvieras alguna de sobra te la cambiaré tres de ellas por una de nuestras marcas de honor. Puedes utilizar las marcas con Rin'wosho el Mercader, a cambio te ofrecerá objetos especiales."}}
D[8240] = {"Una presea para Zanza",{"Destruye una de las preseas Hakkari que hayas encontrado en Zul'Gurub en el Altar de Zanza en Isla Yojamba. Cuando lo hayas hecho ve a hablar con Vinchaxa."}}
D[8241] = {"Fabricar flujo ígneo con hierro",{"Mi tiempo es demasiado valioso para perderlo con charlas, <raza>. Quiero fabricar más flujo ígneo","","Para eso, necesito que me traigas lo siguiente:","","*Escamas de incendosaurio","","*Barras de hierro","","*Carbón","","¡Tráeme tanto como puedas!","","Y tan rápido como puedas, si es que quieres ganarte el favor de la Hermandad."}}
D[8242] = {"Fabricar flujo ígneo con cuero pesado",{"Mi tiempo es demasiado valioso para perderlo con charlas, <raza>. Quiero fabricar más flujo ígneo","","Para eso, necesito que me traigas lo siguiente:","","*Escamas de incendosaurio","","*Cuero pesado","","*Carbón","","¡Tráeme tanto como puedas!","","Y tan rápido como puedas, si es que quieres ganarte el favor de la Hermandad."}}
D[8243] = {"Los mejunjes potentes de Zanza",{"Gracias a tu estatus entre los de la tribu puedes acceder a algunos de nuestros mejunjes potentes. Mira... estos brebajes reciben su fuerza del mojo, están bendecidos por Zanza y se preparan para los aventureros de todo tipo y procedencia","","Te permitiré elegir uno de los tres tipos de bebida que preparo pero a cambio necesito tres muestras de honor Zandalar. Ten en cuenta que solo pueden fluir por tu espíritu los efectos de un solo brebaje al mismo tiempo","","¡Avísame cuando estés listo para el trueque!"}}
D[8246] = {"Las sortijas de Zandalar",{"<nombre>, tengo algo muy especial para un exaltado como tú entre los Zandalar. Venido directamente desde nuestro hogar en los Mares del Sur... ¡las sortijas de Zandalar! Estas sortijas se utilizan para mejorar cualquier hombrera. Si deseas fuerza, mojo o serenidad, ¡tengo lo que necesitas!","","A cambio de una sortija a tu elección solo te pido 15 muestras de honor Zandalar. Si ya tienes las muestras, ¡podemos pasar al trato!"}}
D[8249] = {"Se necesitan cajas de trastos"}
D[8250] = {"Pura magia",{"Busca a Sanath Lim-yo y obtén permiso para ver al archimago Xylem."}}
D[8251] = {"El polvo mágico",{"Llévale 10 puñados de polvo relumbrante al archimago Xylem."}}
D[8252] = {"El coral de las sirenas",{"Reúne 6 corales encantados y llévaselos al archimago Xylem."}}
D[8253] = {"Destruye a Morphaz",{"Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem."}}
D[8254] = {"Ayuda a Cenarion",{"Busca a Ogtinc en Azshara."}}
D[8255] = {"Los trotadores Pezuñamusgo",{"Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}}
D[8256] = {"El icor de los no-muertos",{"Consigue un icor de los no-muertos para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."}}
D[8257] = {"La sangre de Morphaz",{"Mata a Morphaz en El Templo de Atal'Hakkar anegado y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al Templo Sumergido en el Pantano de las Penas."}}
D[8258] = {"La amenaza de Atracoscuro",{"Usa el cristal de adivinación en el Gran Osario de Scholomance. Aparecerán espíritus con los que tendrás que luchar. Al derrotarlos se invocará el Caballero de la Muerte Atracoscuro; derrótalo","","Lleva su cabeza a Sagorne Zancresta al Valle de la Sabiduría, en Orgrimmar."}}
