D[8271] = {"Héroe de Pico Tormenta"}
D[8272] = {"Héroe de Lobo Gélido",{"¿Qué se siente, <nombre>? ¿Qué se siente al aplastar a los enemigos y ver cómo sus líneas se diseminan? Sienta bien, ¿eh?","","Se te recompensará por este acto heroico, soldado."}}
D[8273] = {"La gratitud Oran",{"¿No te parece interesante? ¿Y dices que encontraste esta tablilla en una pequeña isla desierta en Los Acantilados Dominantes de las Tierras del Interior, <clase>? En verdad resulta interesante","","Te agradezco tus esfuerzos. Nuestra Dama Oscura se alegrará mucho con este hallazgo. Aquí tienes una recompensa a la altura."}}
D[8275] = {"La reconquista de Silithus",{"Habla con Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus."}}
D[8276] = {"La reconquista de Silithus",{"Habla con Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus."}}
D[8277] = {"Veneno mortal del desierto",{"Beetix Castaneo en el Fuerte Cenarion, en Silithus, quiere que consigas 8 aguijoneros de escórpido Latigosólido y 8 colmillos de arácnidos de arena. Vuelve a verla cuando hayas cumplido tu misión."}}
D[8278] = {"La última esperanza de Noggle",{"Beetix Castaneo en el Fuerte Cenarion, en Silithus quiere que consigas 3 aguijoneros de tenazario Latigosólido, 3 aguijoneros de despellejador Latigosólido y 3 colmillos de acechador de piedra."}}
D[8279] = {"El Lexicón Crepuscular",{"Lleva los tres capítulos del Lexicón Crepuscular al Ermitaño Ortell en Silithus."}}
D[8280] = {"Asegurar las rutas de suministros",{"Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus, quiere que mates a 15 golpeadores deslizantes."}}
D[8281] = {"Intensificar la seguridad",{"Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus, quiere que mates a 20 trituradores de arrastre."}}
D[8282] = {"La cartera perdida de Noggle",{"Recupera la Cartera de Noggle en las montañas al sur de Silithus y devuélvesela en el Fuerte Cenarion."}}
D[8283] = {"Se busca: Pinzamorten el Terror de las arenas",{"Lleva la pinza de Pinzamorten a Vish Kozus, Capitán de la guardia."}}
D[8284] = {"El misterio Crepuscular",{"La Geóloga Trotuina en el Fuerte Cenarion, en Silithus, quiere que consigas 8 fragmentos de tablilla Crepuscular."}}
D[8285] = {"El desertor",{"Lleva la tablilla restaurada a Ermitaño Ortell en Silithus."}}
D[8286] = {"Lo que nos depara el futuro",{"Ve a las Cavernas del Tiempo en Tanaris y encuentra a Anacronos, del Linaje de Nozdormu."}}
D[8287] = {"Un propósito terrible",{"Lleva la trascripción de tablilla decodificada al comandante Mar'alith."}}
D[8288] = {"Solo uno puede alzarse",{"Lleva la cabeza de Señor de linaje Capazote a Baristolth del Mar de Dunas al Fuerte Cenarion en Silithus."}}
D[8289] = {"Talismanes del mérito"}
D[8290] = {"Expulsa al invasor",{"Entra en la Garganta Grito de Guerra y derrota a la Horda, obtén una marca de Honor de Grito de Guerra y vuelve con la centinela Cantolongo en el Claro Ala de Plata."}}
D[8291] = {"¡Expulsa al invasor!",{"Entra en la Garganta Grito de Guerra y derrota a la Horda, obtén una marca de Honor de Grito de Guerra y vuelve con la centinela Cantolongo en el Claro Ala de Plata."}}
D[8292] = {"Talismanes del mérito"}
D[8293] = {"Marca de Honor"}
D[8294] = {"Acaba con los usurpadores Ala de Plata",{"Entra en la Garganta Grito de Guerra y derrota a la Alianza, obtén una marca de Honor de Grito de Guerra y llévasela al capitán Trizacráneo en el Campamento de Mor'shan."}}
D[8295] = {"Acaba con los usurpadores Ala de Plata",{"Entra en la Garganta Grito de Guerra y derrota a la Alianza, obtén una marca de Honor de Grito de Guerra y llévasela al capitán Trizacráneo en el Campamento de Mor'shan."}}
D[8296] = {"Marca de Honor"}
D[8297] = {"Los recursos de la Cuenca de Arathi",{"Llévate la victoria en la batalla por la Cuenca de Arathi, consigue una caja de suministros de Arathi y llévasela al sargento Maclear en el Refugio de la Zaga."}}
D[8298] = {"Más cajas de suministros"}
D[8299] = {"Córtale el suministro a la Liga de Arathor",{"Llévate la victoria en la batalla por la Cuenca de Arathi, consigue una caja de suministros de Arathi y llévasela a Mortacechador Mortis en Sentencia."}}
D[8300] = {"Más cajas de suministros"}
D[8301] = {"El camino del honrado",{"Lleva 200 trozos de caparazón de silítido a Baristolth."}}
D[8302] = {"La mano del honrado",{"Lleva 200 trozos de caparazón de silítido a Baristolth."}}
D[8303] = {"Anacronos",{"Busca a Anacronos en las Cavernas del Tiempo de Tanaris."}}
D[8304] = {"Queridísima Natalia",{"El comandante Mar'alith del Fuerte Cenarion de Silithus quiere que interrogues a los habitantes del campamento Barbabronce, que está al sur del Fuerte Cenarion","","Cuando consigas la información ve a ver al comandante Mar'alith."}}
D[8305] = {"Recuerdos olvidados",{"Encuentra la lágrima cristalina en Silithus y mira en sus profundidades."}}
D[8306] = {"En las fauces de la locura",{"El comandante Mar'alith del Fuerte Cenarion de Silithus quiere que encuentres a su amada Natalia. Parece que podría estar en Colmen'Regal, hacia el sur","","No olvides ir a ver a los enanos del campamento Barbabronce antes de ir a la colmena; puede que tengan otras tareas o consejos que darte","","Y, <nombre>, recuerda lo que dijo el comandante: \"Haz lo que tengas que hacer.\""}}
D[8307] = {"Receta del desierto",{"Busca información sobre cómo cocinar carne de gusano de arena en el Campamento del Martillo Crepuscular, al oeste del Fuerte Cenarion."}}
D[8308] = {"La carta perdida de Brann Barbabronce",{"Lleva la carta de Brann Barbabronce al campamento Barbabronce al sur de Silithus."}}
D[8309] = {"Los grabados de los glifos",{"Rutgar Glifoforma del campamento Barbabronce en Silithus quiere que vayas a Colmen'Ashi, Colmen'Regal y Colmen'Zora y calques cristales en cada colmena","","Usa el estuche de trascripción de geólogo para copiar los glifos antiguos. Vuelve a ver a Rutgar cuando hayas terminado la tarea."}}
D[8310] = {"Descifrar el código",{"Frankal Petraponte del campamento Barbabronce en Silithus quiere que le lleves un cerebro silítido de Colmen'Zora, uno de Colmen'Ashi y uno de Colmen'Regal. Vuelve a ver a Frankal cuando hayas terminado la tarea."}}
D[8311] = {"Golosinas de Halloween para Jesper",{"Habla con los taberneros de Ventormenta, Forjaz y Darnassus, así como con Talvash del Kissel en Forjaz. Realiza los trucos que te pidan a cambio de tratos","","Vuelve a ver a Jesper en el orfanato de Ventormenta con un mazapán de Darnassus, una gominola de Gnomeregan un almendrado de Ventormenta y una menta de Forjaz."}}
D[8312] = {"Golosinas de Halloween para Pupas",{"Habla con los posaderos de Orgrimmar, Entrañas y Cima del Trueno y con Kali Remik en el Poblado Sen'jin. Haz lo que te pidan para conseguir los regalitos","","Lleva 1 mazapán de Cima del Trueno, 1 gominola Lanza Negra, 1 almendrado de Orgrimmar y 1 menta de Entrañas a Spoops al Orfanato de Orgrimmar."}}
D[8313] = {"Compartir el conocimiento",{"Lleva la página de receta rota a Calandrath en la taberna del Fuerte Cenarion."}}
D[8314] = {"Desentrañar el misterio",{"Rutgar Glifoforma del campamento Barbabronce quiere que lleves el prisma de cristal con inscripciones a la geóloga Trotuina al Fuerte Cenarion de Silithus."}}
D[8315] = {"La llamada",{"La Geóloga Trotuina del Fuerte Cenarion de Silithus quiere que consigas el mecanismo de desbloqueo de los cristales del emisario qiraji","","Tienes que llevar los glifos a Huesos de Grakkarond, al sur del Fuerte Cenarion, y dibujarlos en la arena. Si aparece el emisario qiraji, mátalo y coge el mecanismo de desbloqueo de los cristales. Si lo consigues, ve a ver a la geóloga Trotuina","","¡Lleva un ejército contigo, <nombre>!"}}
D[8316] = {"Armamentos de guerra"}
D[8317] = {"Echar una mano en la cocina",{"Calandrath, en el Fuerte Cenarion, necesita una entrega de 10 albóndigas del desierto ahumadas."}}
D[8318] = {"Mensajes secretos",{"Lleva 10 textos Crepusculares codificados a Bor Bravacrín en el Fuerte Cenarion."}}
D[8319] = {"Textos Crepusculares codificados",{"Sigue trayéndome textos. Pronto podremos expulsar al Martillo Crepuscular de Silithus."}}
D[8320] = {"Geoseñores Crepusculares",{"Mata 10 geoseñores Crepusculares y, a continuación, ve a ver a Huum Bravacrín en el Fuerte Cenarion."}}
D[8321] = {"Vyral el Vil",{"Lleva el sello de Vyral a Huum Bravacrín en el Fuerte Cenarion."}}
D[8322] = {"Huevos podridos",{"Introduce los huevos podridos en el barril principal que se encuentra en la Taberna Costasur."}}
D[8323] = {"El creyente verdadero",{"Ermitaño Ortell quiere que le lleves 10 textos Crepusculares codificados."}}
D[8324] = {"Seguir creyendo",{"¿Has encontrado más textos encriptados? Tráeme todos los que puedas, este trabajo de descodificación lleva su tiempo."}}
D[8325] = {"Recuperar la Isla del Caminante del Sol",{"Mata 8 vermis de maná; están cerca de los cristales ardientes que hay junto a la torre y la glorieta. Luego ve a ver a la magistrix Erona a la torre de la Isla del Caminante del Sol."}}
D[8326] = {"Medidas extremas",{"Coge 8 colleras de lince de los linces y cachorros Garragil muertos. Luego ve a ver a la magistrix Erona a Isla del Caminante del Sol."}}
D[8327] = {"Informando a Lanthan Perilon",{"Habla con Lanthan Perilon en la Isla del Caminante del Sol. Está cerca del sendero que se aleja de La Aguja del Sol hacia el oeste."}}
D[8328] = {"Entrenamiento de magos",{"Habla con Julia Golpesol, la instructora de magos, en la Aguja del Sol en Isla del Caminante del Sol."}}
D[8329] = {"Instrucción de guerrero",{"Habla con Delios, el instructor de guerreros, en la Aguja del Sol en Isla del Caminante del Sol."}}
D[8330] = {"Las posesiones de Solanian",{"Recoge el orbe de visión, el pergamino de magia de la Plaga y el diario del vigía del pozo Solanian. Están en Isla del Caminante del Sol cerca de la charca, la fuente y de uno de los cristales ardientes. Llévaselo todo a La Aguja del Sol en la Isla del Caminante del Sol."}}
D[8331] = {"Aurel Hojaurea",{"Habla con Aurel Hojaurea en el Fuerte Cenarion."}}
D[8332] = {"Duques del Consejo",{"Lleva 1 fragmento luminoso grande y 3 blasones Abisales a Aurel Hojaurea en el Fuerte Cenarion."}}
D[8333] = {"Medallón de estatus"}
D[8334] = {"Agresividad",{"Mata 7 tiernos y 7 tiernos ferales y ve a ver a Lanthan Perilon en la Isla del Caminante del Sol."}}
D[8335] = {"Felendren el Desterrado",{"Mata 8 ánimas arcanas, 2 ánimas arcanas máculas y a Felendren el Desterrado en Academia Falthrien. Lleva la cabeza de Felendren a Lanthan Perilon a la Isla del Caminante del Sol."}}
D[8336] = {"Por un puñado de esquirlas",{"Coge 6 esquirlas arcanas de los vermis de maná de la isla y llévaselas al arcanista Ithanas a la Isla del Caminante del Sol."}}
D[8338] = {"Esquirla arcana mácula",{"Lleva la esquirla arcana mácula al arcanista Helion a la glorieta de la Aguja del Sol en la Isla del Caminante del Sol."}}
D[8339] = {"Royalty of the Council <NYI> <TXT> UNUSED",{"Lleva los objetos a Aurel Hojaurea en Goldleaf a Fuerte Cenarion."}}
D[8340] = {"Twilight Signet Ring <NYI> <TXT>"}
D[8341] = {"Señores del Consejo",{"Lleva 5 fragmentos luminosos grandes y 3 sellos Abisales a Aurel Hojaurea en el Fuerte Cenarion."}}
D[8342] = {"Anillo de nobleza Crepuscular"}
D[8343] = {"El descubrimiento de Hojaurea",{"Habla con Aurel Hojaurea en el Fuerte Cenarion."}}
D[8344] = {"Ventanas al origen",{"Lleva 4 esencias de ánimas arcanas y 1 esencia de ánima arcana mácula al invocador Teli'Larien a la Aguja del Sol a la Isla del Caminante del Sol."}}
D[8345] = {"Santuario de Dath'Remar",{"Lee la placa del Santuario de Dath'Remar y ve a ver al vigía del pozo Solanian a la Aguja del Sol en la Isla del Caminante del Sol."}}
D[8346] = {"Sed insaciable",{"Realiza 6 Transfusiones de maná en criaturas distintas y ve a ver al arcanista Helion."}}
D[8347] = {"Ayudando a los avanzados",{"Habla con la avanzada Alarion cerca del puente que va al sur de la Isla del Caminante del Sol."}}
D[8348] = {"Sellos de los Duques",{"Lleva el sello Abisal a Bor Bravacrín en el Fuerte Cenarion."}}
D[8349] = {"Bor Bravacrín",{"Habla con Bor Bravacrín en el Fuerte Cenarion."}}
D[8350] = {"El encargo",{"Entrega el paquete de Erona a la tabernera Delaniel en la Plaza Alalcón en el Bosque Canción Eterna."}}
D[8351] = {"Bor quiere hablar contigo",{"Habla con Bor Bravacrín en el Fuerte Cenarion."}}
D[8352] = {"Cetro del Consejo",{"Lleva un Cetro Abisal a Bor Bravacrín en el Fuerte Cenarion."}}
D[8353] = {"Caraquear como un pollo por una menta",{"Haz el pollo para el posadero Vientofuego y te dará una menta de Forjaz."}}
D[8354] = {"Una menta por cacarear como un pollo",{"¡Cacarea como un pollo para el tabernero Norman y a cambio recibirás una menta de Entrañas!"}}
D[8355] = {"¡Truco o trato!",{"Haz el tren para Talvash del Kissel y te dará una gominola de Gnomeregan."}}
D[8356] = {"Saca músculo a cambio de almendrados",{"Saca músculos para la tabernera Allison y, a cambio, recibirás un almendrado de Ventormenta."}}
D[8357] = {"Un baile a cambio de mazapán",{"Baila para la tabernera Saelienne, y, a cambio, recibirás mazapán de Darnassus."}}
D[8358] = {"¡Truco o trato!",{"Haz el tren para Kali Remik y a cambio recibirás una gominola Lanza Negra."}}
D[8359] = {"Saca músculo a cambio de almendrados",{"Saca músculo para la tabernera Gryshka y te dará unos almendrados de Orgrimmar."}}
D[8360] = {"Baliando por mazapanes",{"Baila para el tabernero Pala y, a cambio, recibirás mazapán de Cima del Trueno."}}
D[8361] = {"Contactos Abisales",{"Bor Bravacrín, del Fuerte Cenarion, en Silithus, quiere que destruyas a un Templario Abisal y le lleves un blasón Abisal como prueba de tu logro."}}
