D[8363] = {"Sellos Abisales"}
D[8364] = {"Cetros Abisales"}
D[8365] = {"¡Sombreros de pirata a babor!",{"La modista Jonti quiere que reúnas 20 sombreros de pirata de los Mares del Sur y que se los lleves al Puerto Bonvapor de Tanaris."}}
D[8366] = {"Mamporros en los Mares del Sur",{"El jefe de seguridad Silvaina del Puerto Bonvapor de Tanaris quiere que mates a 10 piratas de los Mares del Sur, 10 filibusteros de los Mares del Sur, 10 portuarios de los Mares del Sur y 10 espadachines de los Mares del Sur."}}
D[8367] = {"Por Gran Honor",{"Entrega 1 marca de Honor del Valle de Alterac, 1 marca de Honor de la Cuenca de Arathi, 1 marca de Honor de la Garganta Grito de Guerra y 1 marca de Honor del Ojo de la Tormenta a un Belisario de la Horda en cualquiera de las capitales de la Horda o en Shattrath."}}
D[8368] = {"La batalla por Garganta Grito de Guerra",{"Entrega 3 marcas de honor de Garganta Grito de Guerra a un Belisario de la Horda fuera de los campos de batalla."}}
D[8369] = {"Invasores del Valle de Alterac",{"Entrega 3 marcas de honor del Valle de Alterac a un Belisario de la Horda fuera de los campos de batalla."}}
D[8370] = {"La conquista de la Cuenca de Arathi",{"Entrega 3 marcas de honor de la Cuenca de Arathi a un Belisario de la Horda fuera de los campos de batalla."}}
