D[8386] = {"Lucha por Garganta Grito de Guerra",{"No olvides que la lucha en la Garganta Grito de Guerra pretende mucho más que la defensa de los árboles. Es por el mantenimiento de una frontera natural entre Vallefresno y Los Baldíos. ¿Traes alguna noticia del campo de batalla, <nombre>?"}}
D[8387] = {"Invasores del Valle de Alterac",{"¡La batalla por Alterac sigue ardiendo! ¡Debes volver al Valle de Alterac y expulsar una vez más a los invasores del territorio de Lobo Gélido, <nombre>!"}}
D[8388] = {"Por Gran Honor",{"Muchos valientes guerreros te admiran, <nombre>. Sigue siendo un ejemplo para todos los que luchan contra la Alianza. ¿Qué noticias traes de tus viajes?"}}
