D[8409] = {"Los barriles dañados",{"Ve a ver de nuevo a Llamasombra Yanka, que está en el Festival del Hombre de Mimbre en los Claros de Tirisfal."}}
D[8410] = {"Maestría elemental",{"Recoge una muestra de aire, fuego, tierra y agua para Bath'rah el Vigía del viento."}}
D[8411] = {"Dominar los elementos",{"Lleva los elementos tierra, aire, fuego y agua a Bath'rah el Vigía del viento."}}
D[8412] = {"Tótem de espíritu",{"Lleva lo necesario para el tótem del espíritu a Bath'rah el Vigía del viento."}}
D[8413] = {"Vudú",{"Lleva las plumas vudú a Bath'rah el Vigía del viento."}}
D[8414] = {"Expulsión de los demonios",{"Recoge 20 Piedras de la Plaga de esbirros y entrégaselas al sumo sacerdote Thel'danis en las Tierras de la Peste del Oeste."}}
D[8415] = {"Campamento del Orvallo",{"Habla con el comandante Ashlam Puñovalor en el Campamento del Orvallo."}}
D[8416] = {"Piedras de la Plaga inertes",{"Lleva la Piedra de la Plaga inerte al comandante Ashlam Puñovalor en el Alto del Orvallo."}}
D[8417] = {"Un espíritu afligido",{"Habla con el Héroe caído de la Horda en la entrada de Las Tierras Devastadas."}}
D[8418] = {"La forja de la piedra de poderío",{"Lleva las plumas vudú a Ashlam Puñovalor."}}
D[8419] = {"Pedido de un diablillo",{"Lleva una pieza de tela vil a Diblis en Frondavil."}}
D[8420] = {"Caliente y picante",{"Lleva un retal de tela vil a Diblis a Frondavil."}}
D[8421] = {"La mercancía equivocada",{"Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil."}}
D[8422] = {"Plumas de trol",{"Reúne un total de 6 plumas vudú en el Templo Sumergido."}}
D[8423] = {"Parentesco guerrero",{"Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al Héroe caído de la Horda."}}
D[8424] = {"La guerra contra los Sombra Jurada",{"Acaba con los Sombra Jurada en las Tierras Devastadas y regresa junto al Héroe Caído de la Horda."}}
D[8425] = {"Plumas Vudú",{"Llévale las plumas vudú de los trols del Templo Sumergido al Héroe caído de la Horda."}}
