D[8446] = {"Inundación de Pesadilla",{"Encuentra a alguien que pueda descifrar el significado del objeto envuelto en pesadillas","","Quizás un druida de gran poder pueda ayudarte."}}
D[8447] = {"Leyendas veraces",{"Espera a que el Guardián Remulos del Claro de la Luna purifique el objeto envuelto en pesadillas."}}
D[8460] = {"Aliado a los Fauces de Madera",{"Grazle quiere que demuestres tu valía matando a 6 guerreros Muertobosque, 6 abrecaminos Muertobosque y 6 jardineros Muertobosque. Cuando lo hayas hecho, vuelve con él al sur de Frondavil, cerca del Santuario Esmeralda."}}
D[8461] = {"Los Muertobosque del Norte",{"Nafien quiere que mates a 6 vigías del cubil Muertobosque, 6 vengadores Muertobosque y 6 chamanes Muertobosque. Luego, vuelve a buscarlo al norte de Frondavil, cerca de la entrada del Bastión Fauces de Madera."}}
D[8462] = {"Habla con Nafien",{"Viaja hacia el norte por el camino principal de Frondavil y habla con el fúrbolg Nafien. Está haciendo guardia en la entrada del Bastión Fauces de Madera."}}
D[8463] = {"Cristales de maná inestables",{"Lleva 6 cristales de maná inestables a Aeldon Marcasol a la Plaza Alalcón."}}
D[8464] = {"Actividad de los Nevada",{"Salfa quiere que mates 8 chamanes Nevada, 8 vigías del cubil Nevada y 8 ursas Nevada. Salfa está a las puertas del Bastión Fauces de Madera en Cuna del Invierno."}}
D[8465] = {"Habla con Salfa",{"Viaja por el Bastión Fauces de Madera y sal a Cuna del Invierno. Habla con Salfa, que está haciendo guardia en la entrada del Bastión Fauces de Madera."}}
D[8466] = {"Plumas para Grazle",{"Aunque a mí ya me has probado tu valía, tendrás que seguir trabajando si quieres ganarte a los recelosos miembros de mi tribu. Quizás yo pueda ayudarte a conseguirlo","","Reduce el número de los furbolgs Muertobosque y recoge el penacho que llevan algunos. Te servirá como prueba de tu hazaña. Tráeme una pluma de cualquiera de los penachos que consigas; por cada grupo de 5 que me traigas, ganarás reconocimiento entre los Fauces de Madera."}}
D[8467] = {"Plumas para Nafien",{"Aunque a mí ya me has probado tu valía, tendrás que seguir trabajando si quieres ganarte a los recelosos miembros de mi tribu. Quizás yo pueda ayudarte a conseguirlo","","Reduce el número de los fúrbolgs Muertobosque y recoge el penacho que llevan algunos. Te servirá como prueba de tu hazaña. Tráeme una pluma de cualquiera de los penachos que consigas; por cada grupo de 5 que me traigas, ganarás reconocimiento entre los Fauces de Madera."}}
D[8468] = {"Se busca a Thaelis el Hambriento",{"Lleva la cabeza de Thaelis al sargento Kan'ren a la Plaza Alalcón, en el Bosque Canción Eterna."}}
D[8469] = {"Cuentas para Salfa",{"Has sabido ganarte mi confianza, <nombre>, pero aún tendrás que ganarte la confianza de mi tribu. Hay algo que puedes hacer para conseguirlo","","Se sabe que los Nevada llevan consigo cuentas de espíritus para protegerse contra los espíritus infectos. Esas cuentas no han cumplido sus propósitos ya que los propios Nevada se han convertido en agentes de corrupción. Tráeme las cuentas de espíritu de los furbolgs Nevada caídos, por cada cinco que me traigas aumentará tu reconocimiento entre los Fauces de Madera."}}
D[8470] = {"El tótem de ritual Muertobosque",{"Lleva el tótem de ritual Muertobosque al interior del Bastión Fauces de Madera. A ver si alguno de los fúrbolgs que hay en él sabe dar uso al objeto. Los Fauces de Madera no hablarán contigo si no tienes un nivel de reputación neutral o superior con ellos."}}
D[8471] = {"Tótem de ritual Nevada",{"Lleva el tótem de ritual Nevada al Bastión Fauces de Madera y averigua si alguno de los fúrbolgs sabe de su utilidad. Los Fauces de Madera no hablarán contigo si tu reputación con ellos no es como mínimo de neutral."}}
D[8472] = {"Avería grave",{"Coge 6 núcleos arcanos de los patrulleros Arcanos que recorren las Ruinas de Ciudad de Lunargenta y llévaselos al magister Jaronis a la Plaza Alalcón en el Bosque Canción Eterna."}}
D[8473] = {"Una tarea dolorosa",{"Mata a 10 jardineros marchitos en La Arboleda Agostada y ve a informar a Larianna Ríobrisa en la torre que está al noroeste de La Arboleda Agostada en el Bosque Canción Eterna."}}
D[8474] = {"El colgante del viejo Cortezablanca",{"Encuentra al artesano que fabricó el colgante del viejo Cortezablanca. Quizás pueda darte información sobre el objeto."}}
D[8475] = {"La Cicatriz Muerta",{"Mata a 8 saqueadores huesopeste e informa a la forestal Jaela en La Cicatriz Muerta, en el Bosque Canción Eterna."}}
D[8476] = {"Asentamiento Amani",{"La teniente Correalba de El Retiro del Errante en el Bosque Canción Eterna quiere que mates a 5 rabias y 5 lanzahachas Amani."}}
D[8477] = {"El martillo del maestro de lanzas",{"Ve a Tor'Watha, al sureste de El Retiro del Errante, para buscar al maestro de lanzas Otembe y lleva el martillo de Otembe a Arathel Forjasol a El Retiro del Errante en el Bosque Canción Eterna."}}
D[8478] = {"Elige un arma"}
D[8479] = {"Zul'Marosh",{"Ven'jashi, el prisionero trol de Tor'Watha, quiere que le lleves la cabeza del jefe Zul'Marosh, que está en Zeb'Watha, al otro lado del Lago Elrendar."}}
D[8480] = {"El armamento perdido",{"Lleva 8 armas sin'dorei a Velendris Albodía al Bosque Canción Eterna."}}
D[8481] = {"La raíz de todos los males",{"Clava la antorcha para invocar demonios en la entrada de la cueva del Gran Jefe Nevada en el Poblado Nevada de los fúrbolgs. Derrota al demonio y consigue la esencia de Xandivious para Monóculo de Gorn del Bastión Fauces de Madera."}}
D[8482] = {"Documentos incriminadores",{"Lleva los documentos incriminadores a Aeldon Marcasol a la Plaza Alalcón en el Bosque Canción Eterna."}}
D[8483] = {"El espía enano",{"Lleva la cabeza del prospector Guardayunque a Aeldon Marcasol a la Plaza Alalcón, en el Bosque Canción Eterna."}}
D[8484] = {"Negociar la paz",{"Llévale la ofrenda de paz de los Fauces de Madera al rey Magni Barbabronce de Forjaz."}}
D[8485] = {"Negociar la paz",{"Llévale la ofrenda de paz de los Fauces de Madera a Thrall, que está en Orgrimmar."}}
D[8486] = {"Inestabilidad arcana",{"La vigilante-Ley Velania quiere que mates 5 espectros de maná y 5 acechadores de maná."}}
D[8487] = {"Tierra corrupta",{"La aprendiza Mirveda del Sagrario del Este en el Bosque Canción Eterna quiere que le lleves 8 muestras de tierra mácula."}}
D[8488] = {"Resultados inesperados",{"Protege a la aprendiza Mirveda de la emboscada de la Plaga."}}
D[8489] = {"El conversor intacto",{"Lleva el conversor arcano intacto a la vigilante-Ley Velania."}}
D[8490] = {"Reforzando las defensas",{"Pon el cristal imbuido en la Piedra rúnica del este y protégelo de la Plaga durante 1 minuto. Devuélvele el cristal al celador de las runas Deryan en el Bosque Canción Eterna y tendrás una recompensa."}}
D[8491] = {"Caza de pelambres",{"Velan Roblebrillante de la Aldea Brisa Pura en el Bosque Canción Eterna quiere que le lleves 6 pelambres de garragil."}}
D[8492] = {"¡La Alianza necesita lingotes de cobre!",{"Llévale 20 lingotes de cobre al alférez Petrocejas en La Sala Militar de Forjaz."}}
D[8493] = {"¡La Alianza necesita más lingotes de cobre!",{"Llévale 20 lingotes de cobre al sargento Petrocejas en la base aérea de Dun Morogh."}}
D[8494] = {"¡La Alianza necesita barras de hierro!",{"Llévale 20 lingotes de hierro al cabo Carnes en La Sala Militar de Forjaz."}}
D[8495] = {"¡La Alianza necesita más barras de hierro!",{"Llévale 20 barras de hierro al cabo Carnes en la base aérea de Dun Morogh."}}
D[8496] = {"Vendas para el campo de batalla",{"Lleva 30 vendas de paño rúnico grueso, 30 vendas de seda gruesa y 30 vendas de tejido mágico grueso a Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas X para poder completar la misión."}}
D[8497] = {"Material de supervivencia en el desierto",{"Lleva 4 globos de agua, 4 contravenenos potentes y 4 albóndigas del desierto ahumadas a Calandrath en la taberna del Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas I para poder completar la misión."}}
D[8498] = {"Órdenes de batalla de Crepusculares",{"Consigue las órdenes de batalla de Crepusculares y llévaselas al comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas tácticas X para poder completar la misión."}}
D[8499] = {"¡La Alianza necesita barras de torio!",{"Llévale 20 lingotes de torio a Dama Trenzado en La Sala Militar de Forjaz."}}
D[8500] = {"¡La Alianza necesita más barras de torio!",{"Llévale 20 barras de torio a Dama Trenzado en la base aérea de Dun Morogh."}}
D[8501] = {"Objetivo: los aguijoneros Colmen'Ashi",{"Mata 30 aguijoneros Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XII para poder completar la misión."}}
D[8502] = {"Objetivo: los trabajadores Colmen'Ashi",{"Mata 30 trabajadores Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate III para poder completar la misión."}}
D[8503] = {"¡La Alianza necesita algas estranguladoras!",{"Llévale 20 algas estranguladoras al soldado Draxlegauge en La Sala Militar de Forjaz."}}
D[8504] = {"¡La Alianza necesita más algas estranguladoras!",{"Llévale 20 algas estranguladoras al soldado Draxlegauge en la base aérea de Dun Morogh."}}
D[8505] = {"¡La Alianza necesita lotos cárdenos!",{"Llévale 20 lotos cárdenos al maestro Arrullanoche en La Sala Militar de Forjaz."}}
D[8506] = {"¡La Alianza necesita más lotos cárdenos!",{"Llévale 20 lotos cárdenos al maestro Arrullanoche en la base aérea de Dun Morogh."}}
D[8507] = {"Servicio de campo",{"Preséntate en el puesto de la Brigada de Forjaz cerca de Colmen'Zora. Prepara tus papeles de servicio de campo sin firmar y consigue tus papeles de servicio de campo firmados del capitán Yunquenegro. A continuación, reúnete con Clamavientos Kaldon en el Fuerte Cenarion, en Silithus","","Nota: curar o lanzar hechizos benéficos a un miembro de la Brigada de Forjaz, te marcará como JvJ."}}
D[8508] = {"Documentos de instrucción de campo"}
D[8509] = {"¡La Alianza necesita lágrimas de Arthas!",{"Llévale 20 lágrimas de Arthas al alférez Germaine en La Sala Militar de Forjaz."}}
D[8510] = {"¡La Alianza necesita más lágrimas de Arthas!",{"Llévale 20 lágrimas de Arthas al Sargento Mayor Germaine en la base aérea de Dun Morogh."}}
D[8511] = {"¡La Alianza necesita cuero semipesado!",{"Llévale 10 piezas de cuero ligero a Bonnie Cazarrocas en La Sala Militar de Forjaz."}}
D[8512] = {"¡La Alianza necesita más cuero semipesado!",{"Llévale 10 piezas de cuero ligero a Bonnie Cazarrocas en la base aérea de Dun Morogh."}}
D[8513] = {"¡La Alianza necesita cuero medio!",{"Llévale 10 piezas de cuero fino al soldado Porter en La Sala Militar de Forjaz."}}
D[8514] = {"¡La Alianza necesita más cuero medio!",{"Llévale 10 piezas de cuero medio al soldado Porter en la base aérea de Dun Morogh."}}
D[8515] = {"¡La Alianza necesita cuero grueso!",{"Llévale 10 piezas de cuero grueso a Marta Bueneje en La Sala Militar de Forjaz."}}
D[8516] = {"¡La Alianza necesita más cuero grueso!",{"Llévale 10 piezas de cuero grueso a Marta Bueneje en la base aérea de Dun Morogh."}}
D[8517] = {"¡La Alianza necesita vendas de lino!",{"Llévale 20 vendas de lino a la centinela Melenargenta en La Sala Militar de Forjaz."}}
D[8518] = {"¡La Alianza necesita más vendas de lino!",{"Llévale 20 vendas de lino a la Centinela Cielargente en la base aérea de Dun Morogh."}}
D[8519] = {"Un peón en el ajedrez de la vida",{"Aprende todo lo que puedas del pasado y habla con Anacronos en las Cavernas del Tiempo de Tanaris."}}
D[8520] = {"¡La Alianza necesita vendas de seda!",{"Llévale 20 vendas de seda a la enfermera Campopétreo en La Sala Militar de Forjaz."}}
D[8521] = {"¡La Alianza necesita más vendas de seda!",{"Llévale 20 vendas de seda a la Enfermera Pedregosa en la base aérea de Dun Morogh."}}
D[8522] = {"¡La Alianza necesita vendas de paño rúnico!",{"Llévale 20 vendas de paño rúnico al vigilante Sombraluna en La Sala Militar de Forjaz."}}
D[8523] = {"¡La Alianza necesita más vendas de paño rúnico!",{"Llévale 20 vendas de paño rúnico al vigilante Sombraluna en la base aérea de Dun Morogh."}}
D[8524] = {"¡La Alianza necesita atún blanco arco iris!",{"Llévale 20 atunes blancos arcoiris al Gastrónomo Salao en La Sala Militar de Forjaz."}}
D[8525] = {"¡La Alianza necesita más atún blanco arco iris!",{"Llévale 20 atunes blancos arcoiris al Gastrónomo Salao en la base aérea de Dun Morogh."}}
D[8526] = {"¡La Alianza necesita raptor asado!",{"Llévale 20 raptores asados a Sarah Silbotriste en La Sala Militar de Forjaz."}}
D[8527] = {"¡La Alianza necesita más raptor asado!",{"Llévale 20 raptores asados a Sarah Silbotriste en la base aérea de Dun Morogh."}}
D[8528] = {"¡La Alianza necesita serviolas moteadas!",{"Llévale 20 serviolas moteadas a la cazadora Río Veloz en La Sala Militar de Forjaz."}}
D[8529] = {"¡La Alianza necesita más serviolas moteadas!",{"Llévale 20 serviolas moteadas a la cazadora Río Veloz en la base aérea de Dun Morogh."}}
D[8530] = {"¡La Alianza necesita piedras nuclearias abrasadas!",{"Llévale 50 piedras nuclearias abrasadas al comandante Martillopujante en la base aérea de Dun Morogh."}}
D[8532] = {"¡La Horda necesita lingotes de cobre!",{"Llévale 20 lingotes de cobre al Minero Cromwell en el Valle de los Espíritus de Orgrimmar."}}
D[8533] = {"¡La Horda necesita más lingotes de cobre!",{"Llévale 20 lingotes de cobre al Minero Cromwell en Durotar."}}
D[8534] = {"Informe de exploración de Colmen'Zora",{"Contacta con el explorador Cenarion Azenel en Colmen'Zora y entrega el informe de exploración de Colmen'Zora a Clamavientos Cuernorgullo en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VI para poder completar la misión."}}
D[8535] = {"Templario vetusto",{"Invoca y mata a un Templario vetusto y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas IV para poder completar la misión."}}
D[8536] = {"Templario de tierra",{"Invoca y mata a un Templario de tierra y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas III para poder completar la misión."}}
D[8537] = {"Templario Carmesí",{"Invoca y mata a un templario Carmesí y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas II para poder completar la misión."}}
D[8538] = {"Los cuatro Duques",{"Invoca y mata al Duque de las Brasas, al Duque de las Profundidades, al Duque de los Céfiros y al Duque de las Esquirlas y preséntate ante el comandante Mar'alith en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas V para poder completar la misión."}}
D[8539] = {"Objetivo: las hermanas de la colmena Colmen'Zora",{"Mata 30 hermanas de la colmena Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate V para poder completar la misión."}}
D[8540] = {"Botas para la guardia",{"Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión."}}
D[8541] = {"Piedra de pulir para la guardia",{"Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión."}}
D[8542] = {"¡La Horda necesita lingotes de estaño!",{"Llévale 20 lingotes de estaño al bruto Maug en el Valle de los Espíritus de Orgrimmar."}}
D[8543] = {"¡La Horda necesita más lingotes de estaño!",{"Llévale 20 lingotes de estaño al bruto Maug en Durotar."}}
D[8544] = {"Las bufas de conquistador",{"Llévale las ataduras de mando qiraji, 2 ídolos de la noche, 5 escarabajos de piedra y 5 escarabajos de terracota a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación neutral ante el Linaje de Nozdormu para completar esta misión."}}
D[8545] = {"¡La Horda necesita barras de mitril!",{"Llévale 20 barras de mitril al sargento jefe T'kelah en el Valle de los Espíritus de Orgrimmar."}}
D[8546] = {"¡La Horda necesita más barras de mitril!",{"Sí, m’alegro qu’hayas venío, colega. M’has ayudao antes y ahora vuelvo a necesitarte. Entoavía hay que traer más lingotes de mitril pa’ los preparativos de la guerra; vamos a construir un montón d’armaduras, armas y tal y tal pa' aplastar a esos bichos d’Ahn'Qiraj","","Si eres un amiga de verdad, tráeme más pilas de lingotes de mitril. Me lo quedaré to' hasta qu'alcancemos nuestro cupo. ¿No tendrás algunos pa’ mí ahora?"}}
D[8547] = {"¡Bienvenido!",{"Lleva el vale regalo de la Plaza Alalcón a Marsilla Estrella del Alba en la Plaza Alalcón."}}
D[8548] = {"Equipamiento de Voluntario",{"Lleva 5 distintivos de combate Cenarion, 3 distintivos de logística Cenarion y 7 distintivos de táctica Cenarion a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación amistoso con el Círculo Cenarion para poder completar esta misión."}}
D[8549] = {"¡La Horda necesita flores de paz!",{"Llévale 20 flores de paz al herborista Plumorgullo en el Valle de los Espíritus de Orgrimmar."}}
D[8550] = {"¡La Horda necesita más flores de paz!"}
D[8551] = {"El cofre del Capitán",{"Lleva el cofre de Smotts a Hecklebury Smotts en la Bahía del Botín."}}
D[8552] = {"La banda con monograma",{"Devuelve la banda con monograma a su propietario."}}
D[8553] = {"El alfanje del Capitán",{"Habla con Tardo."}}
D[8554] = {"Enfréntate a Negolash",{"Lleva 10 Alas de águila ratonera a la parrilla y 5 botellas de vino de vid de jungla al barco salvavidas del capitán Smotts","","Mata a Negolash y lleva el alfanje de Smotts al capitán Smotts en Tuercespina."}}
D[8555] = {"Encomienda a los Vuelos"}
D[8556] = {"El sello de fuerza implacable",{"Llévale 1 anillo de magistrado qiraji, 2 ídolos luminiscentes, 5 escarabajos de bronce y 5 escarabajos de marfil a Clamavientos Yessendra en Silithus. También debes alcanzar la reputación de honorable ante el Círculo Cenarion para completar esta misión."}}
D[8557] = {"El mantón de fuerza implacable",{"Llévale 1 mantón marcial qiraji, 2 ídolos de ónice, 5 escarabajos de plata y 5 escarabajos de hueso a Keyl Patacerce en Silithus. También debes alcanzar la reputación de venerado ante el Círculo Cenarion para completar esta misión."}}
D[8558] = {"La hoz de fuerza implacable",{"Llévale 1 empuñadura con púas qiraji, 2 ídolos de porcelana, 5 escarabajos de cristal y 5 escarabajos de piedra al celador Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión."}}
D[8559] = {"Las grebas de conquistador",{"Llévale las ataduras de mando qiraji, 2 ídolos de la guerra, 5 escarabajos de marfil y 5 escarabajos de oro a Kandrostrasz en Ahn'Qiraj. Esta misión requiere la reputación neutral con la facción Linaje de Nozdormu."}}
D[8560] = {"Las musleras de conquistador",{"Llévale la piel intacta de Ouro, 2 ídolos de muerte, 5 escarabajos de bronce y 5 escarabajos de marfil a Kandrostrasz en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}}
D[8561] = {"La corona de conquistador",{"Llévale el aro de Vek'lor, 2 ídolos del sol, 5 escarabajos de piedra y 5 escarabajos de cristal a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}}
D[8562] = {"La coraza de conquistador",{"Llévale el caparazón del dios antiguo, 2 ídolos de la guerra, 5 escarabajos de plata y 5 escarabajos de hueso a Vethsera en Ahn'Qiraj. También debes alcanzar la reputación de honorable ante el Linaje de Nozdormu para completar esta misión."}}
D[8563] = {"Entrenamiento de brujos",{"Habla con el invocador Teli'Larien, el instructor de brujos, en la Aguja del Sol en la Isla del Caminante del Sol."}}
D[8564] = {"Entrenamiento de sacerdotes",{"Habla con la matrona Arena, la instructora de sacerdotes, en la Aguja del Sol en la Isla del Caminante del Sol."}}
D[8565] = {"Victorias del pasado en Arathi"}
D[8566] = {"Victorias del pasado en Arathi"}
D[8567] = {"Victorias del pasado en Garganta Grito de Guerra"}
D[8568] = {"Victorias del pasado en Garganta Grito de Guerra"}
D[8569] = {"Esfuerzos del pasado en Garganta Grito de Guerra"}
D[8570] = {"Esfuerzos del pasado en Garganta Grito de Guerra"}
D[8572] = {"Equipamiento de Veterano",{"Lleva 7 distintivos de combate Cenarion, 4 distintivos de logística Cenarion y 4 distintivos de táctica Cenarion a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación de honorable con el Círculo Cenarion para poder completar esta misión."}}
D[8573] = {"Equipamiento de Campeón",{"Lleva 15 distintivos de combate Cenarion, 20 distintivos de logística Cenarion, 20 distintivos de táctica Cenarion y 1 Marca de Cenarius a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación exaltado con el Círculo Cenarion para poder completar esta misión."}}
D[8574] = {"Equipamiento de adepto",{"Lleva 15 distintivos de combate Cenarion, 20 distintivos de logística Cenarion, 17 distintivos de táctica Cenarion y 1 Marca de Remulos a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación venerado con el Círculo Cenarion para poder completar esta misión."}}
D[8575] = {"El libro de contabilidad mágico de Azuregos",{"Entrega el libro de contabilidad mágico de Azuregos a Narain Sabelotodo de Tanaris."}}
D[8576] = {"La traducción del libro de contabilidad"}
D[8577] = {"Guisón, ex mejor amigo",{"Narain Sabelotodo quiere que encuentres a su ex mejor amigo de toda la vida, Guisón, y que recuperes las gafas que le robó."}}
D[8578] = {"¿Unas gafas? ¡Sin problemas!",{"Encuentra las gafas de visión de Narain y llévaselas a Tanaris."}}
D[8579] = {"Campeones mortales",{"Presentimos la presencia de nuestra estirpe esclavizada en el interior de Ahn'Qiraj; y ni un ejército de dragones bastarían para rescatarlos, <raza>","","Si nos acercamos un poco más, el mismo hechizo que los retiene nos colocaría firmemente bajo el control de C'Thun","","El dios antiguo ha anticipado nuestra llegada. Toda esperanza es vana. ¿Qué diferencia podría suponer un simple mortal como tú?"}}
D[8580] = {"¡La Horda necesita flores de fuego!",{"Llévale 20 flores de fuego a Jinete de Murciélagos Pele'keiki en el Valle de los Espíritus de Orgrimmar."}}
D[8581] = {"¡La Horda necesita más flores de fuego!"}
D[8582] = {"¡La Horda necesita lotos cárdenos!",{"Llévale 20 lotos cárdenos a la boticaria Jezel en el Valle de los Espíritus de Orgrimmar."}}
D[8583] = {"¡La Horda necesita más lotos cárdenos!",{"De hecho, al parecer necesitamos aún más loto cárdeno, <clase>. Aunque mis nuevas investigaciones no hayan permitido todavía descubrir nuevas aplicaciones de utilidad para esta hierba, aún quedan metodologías ciertas y probadas que aprovechar","","Necesito que vayas de nuevo al campo y recolectes al menos 20 ejemplares de loto cárdeno. Cuando los tengas, tráemelos aquí."}}
D[8584] = {"¡Nunca me preguntes por mi negocio!",{"Narain Sabelotodo de Tanaris quiere que hables con Dirge Hojágil de Gadgetzan."}}
D[8585] = {"La Isla del Terror",{"Lleva el cadáver de Lakmaeran y 20 solomillos tiernos de quimerok a Dirge Hojágil a Tanaris."}}
D[8586] = {"Fabulosos solomillos de quimerok de Dirge",{"Dirge Hojágil de Gadgetzan quiere que le lleves 20 combustibles de cohete goblin y 20 sales de roca."}}
D[8587] = {"Vuelve con Narain",{"Entrega el pollo de 500 kilos a Narain Sabelotodo de Tanaris."}}
D[8588] = {"¡La Horda necesita cuero pesado!",{"Llévale 10 piezas de cuero pesado al desollador Jamani en el Valle de los Espíritus de Orgrimmar."}}
D[8589] = {"¡La Horda necesita más cuero pesado!",{"Así es, <clase>, aún necesito más cuero pesado. Los pedidos de los generales y sus intendentes no se acaban nunca. ¡Y eso no es nada comparado con lo que los maestros de zepelín están pidiendo!","","Tengo que completar mi cupo a paso ligero. <nombre>, tráeme más pilas de cuero pesado ¡tan pronto como puedas!"}}
D[8590] = {"¡La Horda necesita cuero grueso!",{"Llévale 10 piezas de cuero grueso al sargento Umala en el Valle de los Espíritus de Orgrimmar."}}
D[8591] = {"¡La Horda necesita más cuero grueso!",{"<clase>, como ves, necesito recolectar aún más cuero pesado. Una vez más te pido tu ayuda para esta tarea y prometo que si la completas, se te reconocerá tu dedicación","","¡El tiempo es vital! ¡Vuelve aquí cuando tengas el cuero pesado para que pueda acabar nuestros preparativos para la guerra, heroína!"}}
D[8592] = {"La tiara del Oráculo",{"Llévale el aro de Vek'lor, 2 ídolos del sabio, 5 escarabajos de plata y 5 escarabajos de hueso a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}}
D[8593] = {"Las calzas del Oráculo",{"Llévale la piel intacta de Ouro, 2 ídolos de la vida, 5 escarabajos de oro y 5 escarabajos de terracota a Kandrostrasz en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}}
D[8594] = {"El manto del Oráculo",{"Llévale las ataduras de mando qiraji, 2 ídolos de renacimiento, 5 escarabajos de plata y 5 escarabajos de marfil a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación neutral ante el Linaje de Nozdormu para completar esta misión."}}
D[8595] = {"Campeones mortales",{"Matar a un señor qiraji es un logro notable para un mortal, <nombre>. Sin embargo, son muchos y poderosos. Sigue derrotándolos y demuestra lo que vales como nuestro Campeón."}}
D[8596] = {"Los borceguíes del Oráculo",{"Llévale las ataduras de mando qiraji, 2 ídolos de muerte, 5 escarabajos de bronce y 5 escarabajos de oro a Kandrostrasz en Ahn'Qiraj. Esta misión requiere la reputación neutral con la facción Linaje de Nozdormu."}}
D[8597] = {"Dracónico para torpes",{"Encuentra el libro de Narain Sabelotodo. Está enterrado en una isla de los Mares del Sur."}}
D[8598] = {"ReScaTe",{"Lleva la carta de rescate a Narain Sabelotodo a Tanaris."}}
D[8599] = {"Una canción de amor para Narain",{"Lleva la carta de amor de Meridith a Narain Sabelotodo a Tanaris."}}
D[8600] = {"¡La Horda necesita pieles de cuero basto!",{"Llévale 10 piezas de cuero basto al doctor Serratus en el Valle de los Espíritus de Orgrimmar."}}
D[8601] = {"¡La Horda necesita más pieles de cuero basto!",{"Los preparativos para la próxima guerra de Ahn'Qiraj están en curso, <clase>. Sin embargo, para garantizar que no nos quedamos rezagados, o al menos que no sea yo quien nos retrase, quiero que traigas otra pila de cuero basto. Si le concedes la prioridad a este asunto, te estaremos infinitamente agradecidos, <nombre>."}}
D[8602] = {"Los espaldares de clamatormentas",{"Llévale las ataduras de dominancia qiraji, 2 ídolos de la vida, 5 escarabajos de oro y 5 escarabajos de cristal a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación neutral ante el Linaje de Nozdormu para completar esta misión."}}
D[8603] = {"Las vestimentas del Oráculo",{"Llévale la coraza del dios antiguo, 2 ídolos de muerte, 5 escarabajos de hueso y 5 escarabajos de cristal a Vethsera en Ahn'Qiraj. También debes alcanzar la reputación de honorable ante el Linaje de Nozdormu para completar esta misión."}}
D[8604] = {"¡La Horda necesita vendas de lana!",{"Llévale 20 vendas de lana mágica al sanador Largocamino en el Valle de los Espíritus de Orgrimmar."}}
D[8605] = {"¡La Horda necesita más vendas de lana!",{"¡Qué alegría volver a verte, <clase>! Seguimos trabajando en los preparativos para la guerra y aún me vendría bien cualquier contribución en recolectar vendas de lana. Cualquier ayuda será inmensamente agradecida. Solo espero que nuestros esfuerzos sean suficientes. He perdido demasiadas almas nobles en pasadas contiendas para no hacer todo lo que esté en mis manos para que no vuelva a ocurrir."}}
D[8606] = {"¡Señuelo!",{"Narain Sabelotodo de Tanaris quiere que viajes a Cuna del Invierno y coloques la bolsa de oro en el punto de entrega indicado por los secuestralibros."}}
D[8607] = {"¡La Horda necesita vendas de tejido mágico!",{"Llévale 20 vendas de tejido mágico a Lady Callow en el Valle de los Espíritus de Orgrimmar."}}
D[8608] = {"¡La Horda necesita más vendas de tejido mágico!",{"“¿De vuelta? Interesante. Como puedes ver, aún estoy reuniendo cosas para los “”preparativos”” de la guerra de Ahn'Qiraj. Lo cual significa que vuelvo a necesitarte para que salgas a buscar una pila de vendas de paño mágico. Espero con impaciencia tu regreso, <clase>.”"}}
D[8609] = {"¡La Horda necesita vendas de paño rúnico!",{"Llévale 20 vendas de tejido mágico a Pezuñarcilla Garrapetra en el Valle de los Espíritus de Orgrimmar."}}
D[8610] = {"¡La Horda necesita más vendas de paño rúnico!",{"Cada vez más cercana está la hora de lanzarnos de lleno en la conflagración con Ahn'Qiraj, <clase>. Pero primero debemos unificar nuestras fuerzas y prepararnos para poder sobrevivir a la masacre de los insectos y sus maestros","","Si has vuelto, seguro que querrás realizar otra contribución de vendas de paño rúnico para los preparativos de guerra, ¿no? Hazlo cuanto antes y vuelve aquí."}}
D[8611] = {"¡La Horda necesita escalopines de lobo!",{"Llévale 20 escalopines de lobo al guardasangre Alquicrudo en el Valle de los Espíritus de Orgrimmar."}}
D[8612] = {"¡La Horda necesita más escalopines de lobo!"}
D[8613] = {"¡La Horda necesita serviolas moteadas!",{"Llévale 20 serviolas moteadas al pescador Len'do en el Valle de los Espíritus de Orgrimmar."}}
D[8614] = {"¡La Horda necesita más serviolas moteadas!",{"Pues como puedes ver, aún hace falta mogollón d’esos pescaditos. Los combatientes de la próxima guerra d’Ahn'Qiraj necesitarán un montón de comida, así que m’hará falta toda la serviola moteada que se pueda conseguir. Las pescas, las cocinas y me las traes aquí, y la Horda y yo t'estaremos agradecíos pa' siempre."}}
D[8615] = {"¡La Horda necesita salmón asado!",{"Llévale 20 salmones al horno al Jefe Garrafilo en el Valle de los Espíritus de Orgrimmar."}}
D[8616] = {"¡La Horda necesita más salmón asado!"}
D[8618] = {"¡La Horda necesita más piedras nuclearias chamuscadas!"}
D[8619] = {"Alborhondo el Ancestro"}
D[8620] = {"La única receta",{"Recupera los 8 capítulos perdidos de Dracónico para torpes, únelos con la encuadernación de libro mágico y devuelve el libro completo Dracónico para torpes: Volumen II a Narain Sabelotodo de Tanaris."}}
D[8621] = {"Los guardapiés de Clamatormentas",{"Llévale las ataduras de dominancia qiraji, 2 ídolos del sabio, 5 escarabajos de bronce y 5 escarabajos de terracota a Kandrostrasz en Ahn'Qiraj. Esta misión requiere la reputación neutral con la facción Linaje de Nozdormu."}}
D[8622] = {"El camisote de clamatormentas",{"Consigue el caparazón de un dios antiguo, 2 ídolos del sabio, 5 escarabajos de plata y 5 escarabajos de hueso a Vethsera, dentro de Ahn'Qiraj. También debes tener reputación de honorable con el Linaje de Nozdormu para completar esta misión."}}
D[8623] = {"La diadema de clamatormentas",{"Consigue la diadema de Vek'lor, 2 ídolos de renacimiento, 5 escarabajos de piedra y 5 escarabajos de cristal para ANdorgos en Ahn'Qiraj. También debes tener reputación Amistosa con el Linaje de Nozdormu para completar esta misión."}}
D[8624] = {"Los leotardos de clamatormentas",{"Llévale la piel del gran gusano de arena, 2 ídolos de la disputa, 5 escarabajos de bronce y 5 escarabajos de marfil a Kandrostrasz en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}}
