D[8728] = {"Buenas y malas noticias",{"Narain Sabelotodo de Tanaris quiere que le lleves 20 barras de arcanita, 10 menas de elementium, 10 diamantes de Azeroth y 10 zafiros azules."}}
D[8729] = {"La cólera de Neptulon",{"Utiliza la boya de arcanita en La Vorágine espiral de la Bahía de la Tempestad de Azshara."}}
D[8730] = {"La corrupción de Nefarius",{"Mata a Nefarian y recupera del fragmento de cetro rojo. Llévaselo a Anacronos a las Cavernas del Tiempo, en Tanaris.","Tienes 5 horas para completar esta tarea."}}
D[8731] = {"Servicio de campo",{"Preséntate ante Krug Machacacráneos en la Avanzada de la Legión de Orgrimmar delante de Colmen'Regal. Prepara tus documentos de obligación de campo sin firmar, consigue los los documentos de servicio de campo firmados y llévaselos a Clamavientos Kaldon en el Fuerte Cenarion","","Nota: curar o lanzar hechizos benéficos a un miembro de la Legión de Orgrimmar, te marcará como JvJ."}}
D[8732] = {"Documentación de instrucción de campo"}
D[8733] = {"Eranikus, el Tirano del Sueño",{"Viaja al continente de Teldrassil y busca al agente de Malfurion. Lo encontrarás a lo largo de los muros de Darnassus."}}
D[8734] = {"Tyrande y Remulos",{"Ve a Claro de la Luna y habla con el guardián Remulos."}}
D[8735] = {"La corrupción de Pesadilla",{"Ve a los 4 Portales del Sueño Esmeralda de Azeroth y recoge un fragmento de Corrupción de Pesadilla en cada uno. Habla otra vez con el guardián Remulos en Claro de la Luna cuando hayas completado la tarea."}}
D[8736] = {"La Pesadilla se manifiesta",{"Defiende Amparo de la Noche de Eranikus. No dejes morir al guardián Remulos. No mates a Eranikus. Defiéndete. Espera a Tyrande."}}
D[8737] = {"Templario azur",{"Invoca y mata a un Templario azur y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas I para poder completar la misión."}}
D[8738] = {"Informe de exploración de Colmen'Regal",{"Contacta con el explorador Cenarion Landion en Colmen'Regal y entrega el informe de exploración de Colmen'Regal a Clamavientos Cuernorgullo en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VII para poder completar la misión."}}
D[8739] = {"Informe de exploración de Colmen'Ashi",{"Contacta con el explorador Cenarion Jalia en Colmen'Ashi y entrega el informe de exploración de Colmen'Ashi a Clamavientos Cuernorgullo en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VIII para poder completar la misión."}}
D[8740] = {"Los merodeadores Crepusculares",{"Mata a la maleante Crepuscular Morna y a 2 maleantes Crepusculares. Informa a Clamavientos Cuernorgullo cuando hayas completado tu misión. También debes llevar el Informe de tareas tácticas IX para poder completar la misión."}}
D[8741] = {"El regreso del Campeón",{"Lleva el fragmento de cetro verde a Anacronos a las Cavernas del Tiempo, en Tanaris."}}
D[8742] = {"El poder de Kalimdor"}
D[8743] = {"Golpear el gong"}
D[8744] = {"Un regalo bien envuelto",{"La etiqueta de este regalo dice:","","Para <nombre>,nn¡Que pases unas dulces y felices fiestas del Gran Invierno!"}}
