D[8767] = {"Un regalo un poco agitado",{"Parece que han agitado este regalo un par de veces. Su etiqueta dice:","","Para un <raza> <clase> muy especial."}}
D[8768] = {"Un regalo con envoltorio alegre",{"El regalo está envuelto con motivos propios de estas fiestas y tiene tu nombre","","Espera, ¿no acaba de moverse?"}}
D[8769] = {"Un regalo que hace tic tac",{"Tus amigos de los Pastos de Bosquehumeante te desean unas felices fiestas del Gran Invierno."}}
D[8770] = {"Objetivo: los defensores Colmen'Ashi",{"Mata 30 defensores Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate I para poder completar la misión."}}
D[8771] = {"Objetivo: los acecharenas Colmen'Ashi",{"Mata 30 acecharenas Colmen'Ashi y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate II para poder completar la misión."}}
D[8772] = {"Objetivo: los oteadores Colmen'Zora",{"Mata 30 oteadores Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VI para poder completar la misión."}}
D[8773] = {"Objetivo: los atracadores Colmen'Zora",{"Mata 30 atracadores Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IV para poder completar la misión."}}
D[8774] = {"Objetivo: los emboscadores Colmen'Regal",{"Mata 30 emboscadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate VIII para poder completar la misión."}}
D[8775] = {"Objetivo: los escupefuegos Colmen'Regal",{"Mata 30 escupefuegos Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate IX para poder completar la misión."}}
D[8776] = {"Objetivo: los esclavizadores Colmen'Regal",{"Mata 30 esclavizadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate X para poder completar la misión."}}
D[8777] = {"Objetivo: los perforadores Colmen'Regal",{"Mata 30 perforadores Colmen'Regal y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XI para poder completar la misión."}}
D[8778] = {"La Brigada de Forjaz necesita explosivos",{"Lleva 6 aceites de inmolación, 5 combustibles de cohete goblin y 10 unidades de pólvora densa al arcanista Bocafuente cerca de Colmen'Zora en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión."}}
D[8779] = {"Materiales de visión",{"Lleva 1 fragmento luminoso grande, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión."}}
D[8780] = {"Refuerzos para armadura para el campo de batalla",{"Lleva 8 complementos bastos para armadura y 8 complementos pesados para armadura a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, cerca de Colmen'Zora, en Silithus. También debes llevar el Informe de tareas logísticas VII para poder completar la misión."}}
D[8781] = {"Armas para el campo de batalla",{"Lleva 2 espadas de acero lunar a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, en las afueras de Colmen'Zora. También debes llevar el Informe de tareas logísticas VI para poder completar la misión."}}
D[8782] = {"Suministros para uniformes",{"Lleva 1 tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión."}}
D[8783] = {"Materiales encantados",{"Lleva 2 barras de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión."}}
D[8784] = {"Los secretos de los qiraji",{"Llévale el artefacto antiguo qiraji a los dragones ocultos cerca de la entrada del templo."}}
D[8785] = {"¡La Legión de Orgrimmar necesita mojo!",{"Lleva 6 mojos potentes, 6 frascos de gran mojo y 8 aceites de inmolación a la sacerdotisa de las Sombras Shai cerca de Colmen'Regal, en Silithus. También debes llevar el Informe de tareas logísticas IV para poder completar la misión."}}
D[8786] = {"Armas para el campo de batalla",{"Lleva 3 hachas de hierro macizo a Merok Zancolargo en el campamento de la Legión de Orgrimmar, en las afueras de Colmen'Regal. También debes llevar el Informe de tareas logísticas VI para poder completar la misión."}}
D[8787] = {"Refuerzos para armadura para el campo de batalla",{"Lleva 8 refuerzos para armadura bastos y 8 refuerzos para armadura pesados a Merok Zancolargo, cerca de Colmen'Regal. También debes llevar el Informe de tareas logísticas VII para poder completar la misión."}}
D[8788] = {"Un regalo un poco agitado",{"Parece que han agitado este regalo un par de veces. Su etiqueta dice:","","Para un <raza> <clase> muy especial."}}
D[8789] = {"Armamentos imperiales qiraji",{"Arygos en el Templo de Ahn'Qiraj creará armamento imbuido de Elementium para ti si le llevas armamento imperial qiraji y 3 menas de Elementium."}}
D[8790] = {"Atavío imperial qiraji",{"Merithra del Sueño en el Templo de Ahn'Qiraj creará armamento imbuido de Elementium para ti si le llevas regalos imperiales qiraji y 3 menas de Elementium."}}
D[8791] = {"La caída de Osirio",{"Entrégale la cabeza de Osirio el Sinmarcas al comandante Mar'alith de Fuerte Cenarion en Silithus."}}
D[8792] = {"¡La Horda te necesita!",{"Habla con el Señor de la Guerra Gorchuk en el Valle de los Espíritus de Orgrimmar."}}
D[8793] = {"¡La Horda te necesita!",{"Habla con el Señor de la Guerra Gorchuk en el Valle de los Espíritus de Orgrimmar."}}
D[8794] = {"¡La Horda te necesita!",{"Habla con el Señor de la Guerra Gorchuk en el Valle de los Espíritus de Orgrimmar."}}
D[8795] = {"¡La Alianza te necesita!",{"Habla con el alguacil de campo Nevanur en La Sala Militar de Forjaz."}}
D[8796] = {"¡La Alianza te necesita!",{"Habla con el alguacil de campo Nevanur en La Sala Militar de Forjaz."}}
D[8797] = {"¡La Alianza te necesita!",{"Habla con el alguacil de campo Nevanur en La Sala Militar de Forjaz."}}
D[8798] = {"Un yeti propio",{"¡Vaya! ¡¿Sabes qué?! ¡Tú también eres ingeniero! Como me ayudaste a darles una lección a mis amigos, ¡voy a enseñarte a hacer tu propio yeti mecánico! ¡Ahora la diversión no va a parar nunca y podrás asustar a quien quieras! Siempre que puedas conseguir los componentes, claro","","¿Qué dices, <nombre>? ¿Quieres aprender los secretos para hacer un yeti mecánico?"}}
D[8799] = {"El héroe del día",{"Lleva 1 porción de sal de roca y 5 monedas de oro al conservante de acebo; recibirás 5 acebos conservados."}}
D[8800] = {"Equipamiento de Cenarius",{"Habla con Vargus en el Fuerte Cenarion, en Silithus."}}
D[8801] = {"El legado de C'Thun",{"Llévale el ojo de C'Thun a Caelastrasz en el Templo de Ahn'Qiraj."}}
D[8802] = {"La salvación de Kalimdor",{"Llévale el ojo de C'Thun a Anacronos en las Cavernas del Tiempo."}}
D[8803] = {"Un regalo de festividad",{"La nota de este regalo dice:","","Para <nombre>,nncon la esperanza de que te ayude a repartir calor y felicidad por todo Azeroth","","De parte de Papá Invierno."}}
D[8804] = {"Material de supervivencia en el desierto",{"Lleva 4 globos de agua, 4 contravenenos potentes y 4 albóndigas del desierto ahumadas a Calandrath en la taberna del Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas I para poder completar la misión."}}
D[8805] = {"Botas para la guardia",{"Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión."}}
D[8806] = {"Piedra de pulir para la guardia",{"Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión."}}
D[8807] = {"Materiales de visión",{"Lleva 1 fragmento luminoso grande, 1 fragmento radiante grande y 1 esmeralda enorme a la Geóloga Trotuina en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas V para poder completar la misión."}}
D[8808] = {"Suministros para uniformes",{"Lleva 1 tela lunar, 2 madejas de paño rúnico y 1 seda de araña Tejehierro a Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas VIII para poder completar la misión."}}
D[8809] = {"Materiales encantados",{"Lleva 2 barras de torio encantado y 2 cueros encantados a Vargus en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas IX para poder completar la misión."}}
D[8810] = {"Vendas para el campo de batalla",{"Lleva 30 vendas de paño rúnico grueso, 30 vendas de seda gruesa y 30 vendas de tejido mágico grueso a Clamavientos Cuernorgullo en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas X para poder completar la misión."}}
D[8811] = {"Un sello de honor",{"Si los aventureros solo tienen un sello de honor, se les entrega a cambio una pequeña cantidad de reputación con Darnassus","","Por favor, no olvides que es mejor entregarme diez sellos al mismo tiempo, tus esfuerzos se verán mejor recompensados. Permitimos el intercambio de un solo sello como servicio para aquellos que no pueden completar un juego de diez","","Dicho esto, ya puedo ayudarte si sigues queriendo entregar un solo sello."}}
