D[8856] = {"Material de supervivencia en el desierto",{"Lleva 4 globos de agua, 4 contravenenos potentes y 4 salmones al horno a Calandrath, que está en la posada del Fuerte Cenarion, en Silithus."}}
D[8857] = {"Los secretos de los Colosos: Ashi",{"Lleva la coraza del coloso de Ashi a Oglethorpe Obnoticus a Bahía del Botín."}}
D[8858] = {"Los secretos de los Colosos: Regal",{"Lleva la coraza del coloso de Regal al sobrestante Puñaceite a La Garganta de Fuego."}}
D[8859] = {"Los secretos de los Colosos: Zora",{"Lleva la coraza del coloso de Zora a Lord Maxwell Neófitus a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[8860] = {"¡Las fiestas de Año Nuevo!",{"Lleva la comida de Pastos de Bosquehumeante a la posadera Allison de Ventormenta."}}
D[8861] = {"¡Las fiestas de Año Nuevo!",{"Lleva la comida de Pastos de Bosquehumeante a la posadera Pala de Cima del Trueno."}}
D[8862] = {"Vela de Elune"}
D[8863] = {"Albóndigas festivas"}
D[8864] = {"Vestidos para el Festival Lunar"}
D[8865] = {"Trajes para el Festival Lunar"}
D[8866] = {"Barbabronce el Ancestro",{"Me alegra saber que la gente de estas tierras sigue prestando homenaje a las antiguas razas. Te deseo todo lo mejor, <nombre>, y te ofrezco esta muestra..."}}
D[8867] = {"Fuegos artificiales lunares",{"Dispara 8 fuegos artificiales lunares y 2 cohetes y acude a una presagista del Festival Lunar de cualquier capital."}}
D[8868] = {"La bendición de Elune",{"Invoca a Augurio y derrótalo para ganar la bendición de Elune. Ve a ver a Valadar Cantoestelar a Amparo de la Noche."}}
D[8869] = {"La dulce Serenidad",{"Viaja a Stratholme y mata al forjamartillos Carmesí. Recupera el delantal del forjamartillos Carmesí y vuelve a Lilith."}}
D[8870] = {"El Festival Lunar",{"Habla con la embajadora del Festival Lunar en la Sala Mística de Forjaz. También puedes hablar con la embajadora del Festival Lunar en otras capitales."}}
D[8871] = {"El Festival Lunar",{"Habla con el presagista del Festival Lunar en el Distrito del Parque, en Ventormenta. También puedes hablar con otros presagistas del Festival Lunar de otras capitales."}}
