D[8883] = {"Valadar Cantoestelar",{"Utiliza tu Invitación al Festival Lunar en la Luz de Luna y viaja al Claro de la Luna. Cuando llegues, habla con Valadar Cantoestelar en Amparo de la Noche."}}
D[8884] = {"Aquí, pescadito...",{"Consigue 8 cabezas de murlocs Malaescama. Llévaselas a Hathvelion Mirasol en el Bosque Canción Eterna, encima de la Orilla Tranquila."}}
D[8885] = {"El anillo de Mmmrrrggglll",{"Consigue el anillo de Mmmrrrggglll de las garras sin vida del jefe Malaescama. Llévaselo a Hathvelion Mirasol en el Bosque Canción Eterna, en el acantilado que domina la Orilla Tranquila."}}
D[8886] = {"¡Piratas Malaescama!",{"Recupera 6 piezas de la carga de la capitana Kelisendra y llévaselas al campamento fortificado que hay al este del Fondeadero Vela del Sol en el Bosque Canción Eterna."}}
D[8887] = {"Rutas perdidas de la capitana Kelisendra",{"Devuelve los planes de navegación perdidos a la capitana Kelisendra, que está en el campamento fortificado que hay al este del Fondeadero Vela del Sol, en el Bosque Canción Eterna."}}
D[8888] = {"La aprendiza",{"Habla con la aprendiza Loralthalis cerca de la Aguja Ocaso Marchito en el Bosque Canción Eterna."}}
D[8889] = {"Desactivando la Aguja",{"Desactiva las 3 fuentes de poder de la Aguja Ocaso Marchito. Después devuelve la joya desactivadora a la aprendiza Loralthalis en el Bosque Canción Eterna."}}
D[8890] = {"Un mensaje de la Aguja",{"Regresa junto al magister Ocaso Marchito en El Retiro del Errante, en el Bosque Canción Eterna."}}
D[8891] = {"Investigación abandonada",{"Devuélvele su diario al magister Ocaso Marchito, que se encuentra en El Retiro del Errante, en el Bosque Canción Eterna."}}
D[8892] = {"Problemas en el Fondeadero Vela del Sol",{"Mata a 5 matones y 5 gamberros Desdichados e informa al forestal Degolien en el Bosque Canción Eterna."}}
D[8893] = {"El Superhuevomático",{"El Superhuevomático es uno de los últimos inventos de Curgle Saltamanivela. Se trata de una máquina impresionante","","El Superhuevomático chisporrotea cuando te acercas al panel de control."}}
D[8894] = {"Limpieza a fondo",{"Mata 6 serpientes de maná y 6 malignos de éter y ve a ver al encargado Wyllithen a las Tierras Ocaso Marchito, en el Bosque Canción Eterna."}}
D[8895] = {"Entrega para el Sagrario del Norte",{"Entrégale la carta sin marcar al vigilante-Ley Caidanis en el Sagrario del Norte en el Bosque Canción Eterna."}}
D[8896] = {"El espía enano",{"Encuentra al prospector Guardayunque en el Sagrario del Norte, mátalo, y vuelve a informar a Aeldon Marcasol en el Bosque Canción Eterna."}}
D[8897] = {"Queridísima Colara:",{"Entrega la carta del general Heldric a Colara Dean, que está junto al banco de Ventormenta."}}
