D[8921] = {"El destilador ectoplásmico",{"Vuelve a ver a Mux Montamaná a Gadgetzan cuando tengas 1 conversor de arcanita delicado, 4 esencias eternas superiores, 10 unidades de aceite de escama pétrea, 25 cenizas volcánicas y 40 piezas de oro."}}
D[8922] = {"Un artefacto sobrenatural",{"Lleva el frasco de sangre sellado a Mux Montamaná a Gadgetzan, en Tanaris."}}
D[8923] = {"Un artefacto sobrenatural",{"Lleva el frasco de veneno sellado a Mux Montamaná a Gadgetzan."}}
D[8924] = {"Caza de ectoplasmas",{"Utiliza el destilador ectoplásmico cerca de los no-muertos incorpóreos y consigue 12 ectoplasmas agostados en Silithus, 12 ectoplasmas helados en Cuna del Invierno y 12 ectoplasmas estables en las Tierras de la Peste del Este. Llévaselos, junto con el destilador ectoplásmico, a Mux Montamaná a Gadgetzan."}}
D[8925] = {"Fuente de energía portátil",{"Encuentra al Señor del Magma Bokk en Las Estepas Ardientes, consigue el núcleo de arrabio y llévaselo a Mux Montamaná a Gadgetzan."}}
