D[9022] = {"La despedida de Anthion",{"Lleva 1 par de botas, 1 par de quijotes y 1 par de bufas del valor a Mokvar a Orgrimmar."}}
D[9023] = {"El veneno perfecto",{"Dirk Truenedera quiere que le lleves glándulas de veneno de Venoxis y Kurinnaxx al Fuerte Cenarion."}}
D[9024] = {"El presentimiento de Aristan",{"Lleva 1 frasco de colonia y 1 de perfume a Morgan Mortero, que está en el Distrito de Mercaderes de Ventormenta."}}
D[9025] = {"El descubrimiento de Morgan",{"Ve a ver a Aristan Mottar, que está junto al banco en el Distrito de Mercaderes de Ventormenta."}}
D[9026] = {"Rastrear la fuente",{"Habla con la posadera Allison en la Rosa Áurea, en el Distrito de Mercaderes de Ventormenta."}}
D[9027] = {"Rastrear la fuente",{"Habla con Evert Sorisam en El Paño Fino, junto a los canales de Ventormenta."}}
D[9028] = {"El descubrimiento de la fuente",{"Encuentra al boticario Staffron Lerent en las Laderas de Trabalomas, detrás de la Mansión Ravenholdt."}}
D[9029] = {"Un caldero burbujeante"}
D[9030] = {"La despedida de Anthion",{"Habla con Deliana en Forjaz."}}
D[9032] = {"El triste destino de Bodley",{"Viaja hasta la Montaña Roca Negra y usa el detector de fantasmas extradimensionales para encontrar a Bodley cerca de la Cumbre de Roca Negra."}}
D[9033] = {"Ecos de Guerra",{"El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere que mates 5 monstruosidades vivientes, 5 gárgolas piel de piedra, 8 capitanes Caballero de la Muerte y 3 acechadores venenosos."}}
