D[9119] = {"Disfunción en el Sagrario del Oeste",{"Habla con la vigilante-Ley Velania en el Sagrario del Oeste, en el Bosque Canción Eterna."}}
D[9120] = {"La caída de Kel'Thuzad",{"Lleva la filacteria de Kel'Thuzad a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9121] = {"La ciudadela del terror: Naxxramas",{"La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 5 cristales Arcanos, 2 cristales Nexus, 1 orbe recto y 60 piezas de oro. También tienes que ser considerado Honorable con El Alba Argenta."}}
D[9122] = {"La ciudadela del terror: Naxxramas",{"La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 2 cristales Arcanos, 1 cristal Nexus y 30 piezas de oro. También tienes que ganar la admiración de El Alba Argenta."}}
D[9123] = {"La ciudadela del terror: Naxxramas",{"La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, se ofrece a costear tu capa arcana. También tienes que ganar el respeto de El Alba Argenta."}}
D[9124] = {"La armadura Acechacriptas no se hace sola...",{"El montero Leopold, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 trozos de maligno de cripta."}}
D[9125] = {"Trozos de maligno de cripta"}
D[9126] = {"Excavaciones para la armadura Segahuesos",{"Rohan el Asesino, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 trozos de huesos."}}
D[9127] = {"Trozos de hueso",{"Con este oficio, nunca tengo demasiados fragmentos de hueso, <nombre>. Siempre que tengas fragmentos de más, tráemelos y te recompensaré con otra insignia."}}
D[9128] = {"La ecuación elemental",{"La archimaga Ángela Dosantos, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 núcleos de elementos."}}
D[9129] = {"Núcleo de elementos"}
D[9130] = {"Mercancía de Ciudad de Lunargenta",{"Entrégale la nota de embarque del intendente Lymel al maestro del cielo Alasol en Tranquillien."}}
D[9131] = {"Armar el Acorator",{"Korfax, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 fragmentos de Hierro Negro."}}
D[9132] = {"Fragmentos de hierro negro",{"Por cada brazada de restos que me traigas, te daré una insignia. Cuantos más restos traigas, mejor. Y ahora, fuera de mi vista, ¡antes de que te parta en dos!"}}
D[9133] = {"Vuelo a la Ciudad de Lunargenta",{"Compra un vuelo a la Ciudad de Lunargenta y entrégale la nota de embarque del intendente Lymel a Sathren Azurocaso en la Ciudad de Lunargenta."}}
D[9134] = {"La maestra del cielo Anochecer",{"Lleva el envío del intendente Lymel a la maestra del cielo Anochecer, que está junto a la Puerta del Pastor en Ciudad de Lunargenta."}}
D[9135] = {"Regreso junto al intendente Lymel",{"Compra un vuelo de vuelta a Tranquillien, en las Tierras Fantasma, y allí entrégale al intendente Lymel sus bienes en Tranquillien, en las Tierras Fantasma."}}
D[9136] = {"Flora salvaje",{"Rayne, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 hojas salvajes."}}
D[9137] = {"Hojas salvajes"}
D[9138] = {"La Aldea Corona del Sol",{"Mata a 10 guardias Nerubis y después regresa junto al arcanista Vandril en Tranquillien, en las Tierras Fantasma."}}
D[9139] = {"Aldea de Bruma Dorada",{"Derrota a 6 fantasmas y 4 apariciones Quel'dorei en la Aldea de Bruma Dorada y luego ve a ver al arcanista Vandril a Tranquillien en las Tierras Fantasma."}}
D[9140] = {"La Aldea Brisaveloz",{"Recolecta 6 sustancias fantasmales y 4 fragmentos de gárgola. Vuelve junto al arcanista Vandril en Tranquillien, en las Tierras Fantasma."}}
D[9141] = {"Me llaman \"El Gallo\"",{"El comandante de despachos Metz de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere una muestra de valor de El Alba Argenta."}}
D[9142] = {"Libranza del artesano"}
D[9143] = {"Encargarse de Zeb'Sora",{"Lleva 6 orejas de trol de Zeb'Sora a la forestal Valanna a las Tierras Fantasma."}}
D[9144] = {"Desaparecido en las Tierras Fantasma",{"Sigue el camino hacia el sur desde la Aldea Brisa Pura y busca al mensajero Caminalba mientras te acercas a las Tierras Fantasma."}}
D[9145] = {"¡Ayuda a la forestal Valanna!",{"Encuentra a la forestal Valanna y al teniente Tomathren en la orilla del Lago Elrendar, en las Tierras Fantasma cerca de la Aldea Corona del Sol."}}
D[9146] = {"Informar al capitán Helios",{"Habla con el capitán Helios en el Enclave del Errante, en la orilla sur del Lago Elrendar en las Tierras Fantasma."}}
D[9147] = {"El mensajero caído",{"La boticaria Thedra en el Bosque Canción Eterna quiere que le lleves 4 muestras de sangre apestada de las bestias de las Tierras Fantasma."}}
D[9148] = {"Entrega en Tranquillien",{"Llévale la carta de Lunargenta al arcanista Vandril en Tranquillien, en las Tierras Fantasma."}}
D[9149] = {"La costa apestada",{"Llévale 6 espinas dorsales de múrloc apestado al boticario Renzithen en Tranquillien, en las Tierras Fantasma."}}
D[9150] = {"Al rescate del pasado",{"El magister Darenis quiere que vayas al Sagrario de la Luna al oeste de Tranquillien y recuperes 8 esencias de maná cristalizado de los devoradores arcanos y de los conmutadores de maná que pueblan la estructura."}}
D[9151] = {"El Sagrario del Sol",{"Ve al Sagrario del Sol en las Tierras Fantasma y habla con el magister Idonis."}}
D[9152] = {"Los suministros de Tumbero",{"Recupera los suministros de Rathis Tumbero y llévaselos a Tranquillien, en las Tierras Fantasma."}}
D[9153] = {"Bajo la Sombra",{"Busca en tu mapa una zona que esté bajo el ataque de la Plaga. Ve y derrota a los miembros de la Plaga que custodian la necrópolis. Lleva 10 runas necróticas al comandante Thomas Helleran a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9154] = {"Capilla de la Esperanza de la Luz",{"Lleva la llamada a las armas al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9155] = {"Limpiar La Cicatriz Muerta",{"Mata 10 hambrientos resucitados y 10 caníbales gangliosos en La Cicatriz Muerta. Ve a ver al mortacechador Rathiel a Tranquillien para recibir una recompensa."}}
D[9156] = {"Se busca a Putrenudillos y Luzran",{"Busca a Putrenudillos y Luzran en las Tierras Fantasma. Lleva sus cabezas al mortacechador Rathiel a Tranquillien y recibirás una recompensa."}}
D[9157] = {"Rituales olvidados",{"Lleva 8 medallones rompeolas a Geranis Albodía a las Tierras Fantasma."}}
D[9158] = {"Transmisores de la Peste",{"La errante Sedina del Enclave del Errante en las Tierras Fantasma quiere que mates 10 linces garrafantasma."}}
D[9159] = {"Control de plagas",{"La errante Sedina del Enclave del Errante en las Tierras Fantasma quiere que mates 8 rondadores husaraña y 10 murciélagos brumosos vampiros."}}
D[9160] = {"Explorando An'daroth",{"Investiga la zona en An'daroth, mata a 12 espías centinela y ve a ver a la Dama Auriferous a Tranquillien en las Tierras Fantasma."}}
D[9161] = {"La sombra del traidor",{"Ve a la Aguja de la Estrella del Alba en las Tierras Fantasma y busca pistas sobre el pasado de Dar'Khan."}}
D[9162] = {"Huellas del pasado",{"Lleva el diario de Dar'Khan a la forestal Vynna al Enclave del Errante."}}
D[9163] = {"En territorio ocupado",{"Roba los Planes de los elfos de la noche: An'daroth, los Planes de los elfos de la noche: An'owyn y los Planes de los elfos de la noche: Espiar a los Sin'dorei, y llévaselos a Dama Auriferous en Tranquillien en las Tierras Fantasma."}}
D[9164] = {"Cautivos en Muerthogar",{"Lleva el jarabe vigorizante de Renzithen a Muerthogar y rescata al aprendiz Varnis, a la boticaria Enith y al forestal Vedoran. Ve a ver a la arcanista Janeda al Sagrario del Sol y recibirás una recompensa."}}
D[9165] = {"La libranza de salvoconducto",{"Entrega la libranza de salvoconducto firmado al comandante de despachos Metz que está en la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este."}}
D[9166] = {"Entregando los planes a An'telas",{"Entrega los planes de los elfos de la noche al magister Sylastor en An'telas en las Tierras Fantasma."}}
D[9167] = {"La muerte del traidor",{"Mata a Dar'Khan Drathir en Muerthogar y lleva su cabeza al magister Kaendris al Sagrario del Sol en las Tierras Fantasma."}}
D[9168] = {"El corazón de Muerthogar",{"Aniquila a 8 ojos de Dar'Khan e informa al magister Idonis en el Sagrario del Sol en las Tierras Fantasma."}}
D[9169] = {"Desactivando An'owyn",{"Recupera el orbe de control y úsalo para desactivar el cristal lunar de los elfos de la noche en An'owyn. Después ve a ver al magister Sylastor a An'telas en las Tierras Fantasma."}}
D[9170] = {"Los tenientes de Dar'Khan",{"El magister Idonis quiere que vayas a Muerthogar para matar a Masophet el Negro, Jurion el Falsario, Borgoth Letra de Sangre y Mirdoran el Caído. Cuando hayas terminado, vuelve a verle en el Sagrario del Sol en las Tierras Fantasma."}}
D[9171] = {"Texturas crujientes",{"Lleva 5 patas de araña crujientes al maestro cocinero Mouldier a Tranquillien en las Tierras Fantasma."}}
D[9172] = {"Informa al magister Kaendris",{"Lleva el diario de Dar'Khan al magister Kaendris al Sagrario del Sol en las Tierras Fantasma."}}
D[9173] = {"Recuperar Aguja Brisaveloz",{"Mata a 8 acólitos de Muerthogar y a 10 forestales caídas y ve a ver al sumo ejecutor Mavren a Tranquillien en las Tierras Fantasma."}}
D[9174] = {"Derrotar a Aquantion",{"Geranis Albodía quiere que nades hasta el fondo del lago al este de la Aldea Corona del Sol y uses los medallones ante el Altar del Dominio de las Mareas. Invoca al elemental llamado Aquantion, ejecútalo y regresa junto a Geranis."}}
D[9175] = {"El collar de Sylvanas",{"Llévale el collar de Sylvanas al Sumo Ejecutor Mavren en Tranquillien, en las Tierras Fantasma."}}
D[9176] = {"Los zigurats gemelos",{"Dirígete al Zigurat Sangrante y al Zigurat Aullante y recupera la piedra de luz y la piedra de llama. Regresa junto al magister Kaendris en el Sagrario del Sol tras recuperar los objetos."}}
D[9177] = {"Viaje a Entrañas",{"Ve al Barrio Real, en Entrañas, y entrégale el collar de Sylvanas a Lady Sylvanas Brisaveloz."}}
D[9178] = {"Libranza del artesano: contrapeso denso",{"Entrega 120 contrapesos densos y la libranza del artesano: contrapeso denso al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
