D[9203] = {"Libranza del artesano: frasco de petrificación",{"Entrega 1 frasco de petrificación y la libranza del artesano: frasco de petrificación al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9204] = {"Libranza del artesano: anguila escama pétrea",{"Entrega 40 anguilas escama pétrea y la libranza del artesano: anguila escama pétrea al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9205] = {"Libranza del artesano: pez coraza de placas",{"Entrega 30 peces coraza de placas y la libranza del artesano: pez coraza de placas al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9206] = {"Libranza del artesano: anguila relámpago",{"Entrega 30 anguilas relámpago y la libranza del artesano: anguila relámpago al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9207] = {"Muestras de mena de Sondaluz",{"Reúne 6 menas de Sondaluz y entrégaselos al magister Quallestis en el Sagrario del Sol, en las Tierras Fantasma."}}
D[9208] = {"La guardia salvaje: arcanum de protección",{"Zanza el Incansable de Zul'Gurub quiere un arcanum de protección."}}
D[9209] = {"La guardia salvaje: arcanum de rapidez",{"Zanza el Incansable de Zul'Gurub quiere un arcanum de rapidez."}}
D[9210] = {"La guardia salvaje: arcanum de enfoque",{"Zanza el Incansable de Zul'Gurub quiere un arcanum de enfoque."}}
D[9211] = {"El guardahielo",{"Mataus el Colérico, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 10 insignias de la Cruzada y 30 piezas de oro."}}
D[9212] = {"Huída de las catacumbas",{"Escolta a la forestal Lilatha junto al capitán Helios hasta el Enclave del Errante en las Tierras Fantasma."}}
D[9213] = {"El guardasombras",{"Mataus el Colérico, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 10 insignias de la Cruzada y 30 piezas de oro."}}
D[9214] = {"Armas Sombrapino",{"Reúne 3 hachas de rebanacabezas, 3 mazas de taumaturgo oscuro, 3 zarpas de señor de los felinos y 3 bastones de aojador. Llévaselos al capitán Helios en el Enclave del Errante, en las Tierras Fantasma."}}
D[9215] = {"¡Tráeme la cabeza de Kel'gash!",{"Llévale la cabeza de Kel'gash el Malvado al capitán Helios en el Enclave del Errante, en las Tierras Fantasma."}}
