D[9341] = {"Tabardo del Alba Argenta",{"Has contribuido mucho a nuestra causa, <nombre>. Si lo deseas, te daré el tabardo de Alba Argenta. Nos enorgullece contar contigo."}}
D[9342] = {"Revientacortezas merodeadores",{"El supervisor Razelcraz, de las minas que están cerca de Thrallmar, quiere que mates a quince revientacortezas merodeadores. Los gusanos tienen tendencia a atacar de repente desde sus túneles, que están bajo tierra."}}
D[9343] = {"Tabardo del Alba Argenta"}
D[9344] = {"Una salida apresurada",{"La clarividente Regulkult quiere que encuentres el rastro de su estudiante Grelag."}}
D[9345] = {"Preparar el bálsamo",{"Reúne doce plantas de Espinelas de Fuego Infernal para un bálsamo y vuelve con Grelag al Avanzada Rompeloma."}}
D[9346] = {"Cuando los jabinfernos vuelen",{"El comandante de vigilancia Krunk de Thrallmar quiere que le lleves 10 carcasas de jabinferno cebado de los jabinfernos hambrientos."}}
