D[9351] = {"Abisarios enloquecidos",{"Llévale 10 esencias de abisario condensado a \"Alaridos\" Screed Sinsuerte en el Zepelín Caído."}}
D[9352] = {"Intrusiones darnasianas",{"Ve al Sagrario del Oeste, al suroeste de la Plaza Alalcón y derrota a cualquier intruso que se encuentre allí. Informa del resultado a la vigilante-Ley Velania."}}
D[9355] = {"Un trabajo para alguien inteligente",{"Mata 15 revientacortezas merodeadores y vuelve a hablar con el supervisor Biggums en el Bastión del Honor."}}
D[9356] = {"Suave como una pluma",{"Llévale 12 alas de águila ratonera rellena a Legassi en el Zepelín Caído."}}
D[9357] = {"Informar a Aeldon Marcasol",{"Preséntate ante Aeldon Marcasol en la Puerta Elfa Interior, en el Bosque Canción Eterna."}}
D[9358] = {"La forestal Sareyn",{"Informa a la forestal Sareyn en las afueras de Aldea Brisa Pura en el Bosque Canción Eterna."}}
D[9359] = {"El Retiro del Errante",{"Informa a la teniente Correalba en el Retiro del Errante, en el Bosque Canción Eterna."}}
D[9360] = {"La invasión Amani",{"Entrega los planes de la invasión Amani a la teniente Correalba en El Retiro del Errante."}}
D[9361] = {"Huevos fritos con jabinferno",{"Legassi en el Zepelín Caído quiere que consigas 8 unidades de carne purificada de jabinferno. Para purificar la carne, utiliza la mezcla purificadora en la carne de jabinferno máculo que consigas encontrar."}}
D[9362] = {"Señor de la Guerra Krellian",{"Recupera la concha centelleante para el archimago Xylem. El archimago vive en una torre en lo alto del precipicio de Azshara."}}
D[9363] = {"Aviso a la Aldea Brisa Pura",{"Dirígete a Aldea Brisa Pura en el Bosque Canción Eterna y habla con el forestal Degolien."}}
D[9364] = {"Magia fragmentada",{"Aplica el hechizo polimórfico al Látigo de Ira de Azshara y mata a los clones que aparezcan pasados unos segundos. Cuando hayas matado a suficientes, vuelve junto al archimago Xylem en Azshara."}}
D[9365] = {"Una recompensa de ladrón"}
D[9366] = {"Se busca: sangrevil",{"Ryathen el Sombrío en la Avanzada del Halcón, en la Península del Fuego Infernal, quiere que le lleves 6 muestras de sangrevil de los terroadictos que viven en las Pozas de Aggonar."}}
D[9367] = {"El Festival del Fuego",{"Toca las hogueras de Ventormenta, Forjaz y Darnassus y habla con un maestro del Conocimiento del festival en cada capital."}}
D[9368] = {"El Festival del Fuego",{"Toca las hogueras de Orgrimmar, Cima del Trueno y Entrañas y habla con un Cuentacuentos en cada capital."}}
D[9369] = {"Recargar los cristales de sanación",{"Consigue 8 viales de sangre de polilla del valle y llévaselos a Proenitus a Lugar del Accidente en Valle Ammen."}}
D[9370] = {"Detengamos la purificación",{"Coloca la gema de señalización cerca del Altar de Aggonar en las Pozas de Aggonar y derrota a los anacoretas draenei que respondan a tu invocación. Luego lleva la gema a Ryathen el Sombrío a la Avanzada del Halcón."}}
D[9371] = {"La botánica Taerix",{"Habla con la botánica Taerix en el Lugar del Accidente en el Valle Ammen."}}
D[9372] = {"Contaminación demoníaca",{"Thiah Melenarroja en el Puesto Cenarion, en la Península del Fuego Infernal, te ha pedido que consigas 6 muestras de sangre de jabinfernos de los jabinfernos descomunales."}}
D[9373] = {"Carta perdida",{"Llévale el estuche de cuero erosionado a Thiah Melenarroja, que está acampado cerca de las Ruinas de Sha'naar, al oeste de la Península del Fuego Infernal."}}
D[9374] = {"El diario de Arelion",{"La magistrix Carinda de la Avanzada del Halcón en la Península del Fuego Infernal quiere que vayas a las Pozas de Aggonar y recuperes el diario de Arelion."}}
D[9375] = {"Hacia la Avanzada del Halcón",{"Protege a la peregrina elfa de sangre herida en su viaje a la Avanzada del Halcón, luego habla con Taleris Observalba."}}
D[9376] = {"Una peregrina afligida",{"A la peregrina elfa de sangre herida la atacaron los devastadores jabacolmillo cuando deambulaba por el Barranco Pluma Polvorienta. Encuentra los devastadores y mátalos hasta que recuperes la talega desaparecida de la peregrina."}}
D[9378] = {"DND FLAG La ciudadela del terror: Naxxramas",{"La archimaga Angela Dosantos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, se ofrece a costear tu velo Arcano. Debes ser Exaltado con El Alba Argenta."}}
D[9380] = {"A seguir cazando canes",{"Reúne 6 cadáveres de can distorsionado intactos y llévaselos al prospector Murantus en el Bastión del Honor."}}
D[9381] = {"Esas flechas sí que vuelan",{"Recolecta 8 plumas de cola de limpiahuesos de buitres limpiahuesos y llévaselos a la halconera Drenna Ríobrisa Avanzada del Halcón."}}
D[9382] = {"El sino de los uñagrietas",{"Mata a 15 uñagrietas lomohirsutos y regresa junto a Amaan el Sabio en el Templo de Telhamat."}}
D[9383] = {"Un plan ambicioso",{"Usa el cristal santificado contra un abisario sin control herido y ve a ver a Elsaana al Templo de Telhamat."}}
D[9385] = {"Devastadores descontrolados",{"Mata 10 devastadores jabacolmillo y ve a ver a Gremni Barbalarga a la Península del Fuego Infernal."}}
D[9386] = {"Una luz en la oscuridad",{"Toca las hogueras de Cumbre de Roca Negra, La Masacre, Scholomance y Stratholme y ve a ver al guardián de la llama del Festival."}}
D[9387] = {"El origen de la corrupción",{"Viaja a las Ruinas de Sha'naar en la Península del Fuego Infernal y consigue 5 esencias demoníacas de los capataces illidari. Vuelve a ver al boticario Azethen a la Avanzada del Halcón cuando hayas completado la tarea."}}
D[9388] = {"La oscilación de las llamas de Kalimdor",{"Toca las hogueras de Vallefresno, Los Baldíos, Costa Oscura y Sierra Espolón y ve a ver al guardián de la llama del Festival."}}
D[9389] = {"La oscilación de las llamas de los Reinos del Este",{"Toca las hogueras de Laderas de Trabalomas, Bosque de Argénteos, Páramos de Poniente y Los Humedales y ve a ver al guardián de la llama del Festival."}}
D[9390] = {"En busca de Sedai",{"El anacoreta Obadei quiere que busques a su hermano, Sedai, al este de la Península del Fuego Infernal."}}
D[9391] = {"Iluminar el camino",{"El capitán forestal Venn'ren de la Avanzada del Halcón quiere que vayas a La Gran Fisura en la Península del Fuego Infernal y enciendas la Baliza del Sur, la Baliza Occidental y la Baliza Central. Vuelve junto a él con la antorcha encendida después de completar esta tarea."}}
D[9392] = {"Entrenamiento de pícaros",{"Habla con el acechacaminos Kariel, el instructor de pícaros, en la Aguja del Sol en la Isla del Caminante del Sol."}}
D[9393] = {"Instrucción de cazador",{"Habla con la forestal Sallina, la instructora de clase de cazadores, en La Aguja del Sol en la Isla del Caminante del Sol."}}
D[9394] = {"¿Dónde está Wyllithen?",{"Encuentra al encargado Wyllithen en las Tierras Ocaso Marchito, en el Bosque Canción Eterna."}}
D[9395] = {"El Refugio de Saltheril",{"Ve a Refugio de Saltheril en el Bosque Canción Eterna y habla con Lord Saltheril."}}
D[9396] = {"La magia de los arakkoas",{"Ve a la Avanzada del Halcón, en la Península del Fuego Infernal, y llévale 4 pergaminos Haal'eshi al arcanista Calesthris Estrella del Alba."}}
D[9397] = {"En compañía de pájaros",{"Ve a El Cubil de Haal'esh en la Península del Fuego Infernal y busca en los nidos de kaliri una cría de kaliri hembra. Usa la jaula de pájaros vacía para capturarla y llévasela a la halconera Drenna Ríobrisa en la Avanzada del Halcón."}}
D[9398] = {"Depredadores letales",{"La exploradora Vanura del Templo de Telhamat en la Península del Fuego Infernal quiere que mates 8 crías de guadaña de piedra y 4 alfas guadaña de piedra."}}
D[9399] = {"Capataces crueles",{"Mata a 4 capataces de Illidari en las Ruinas de Sha'naar y vuelve a ver a Ikan en el Templo de Telhamat, en la Península del Fuego Infernal."}}
D[9400] = {"El asesino",{"Nazgrel quiere que vayas por la carretera al norte de la Ciudadela del Fuego Infernal en busca de un asesino llamado Krun Rompeloma."}}
D[9401] = {"Un arma inusual",{"Lleva el hacha de piedra pesada a Nazgrel en Thrallmar en la Península del Fuego Infernal."}}
D[9402] = {"¡Tráeme una cosita!",{"Bucea hasta el fondo de la Charca Plácido Susurro y recupera la ampolla azur para el instructor Antheol."}}
D[9403] = {"El agua más pura",{"El instructor Antheol quiere que llenes la ampolla azur en las Cascadas Elrendar."}}
D[9404] = {"Recientemente vivo",{"Mata a los jardineros Canción Eterna hasta que entreguen una rama viva para el instructor Antheol."}}
D[9405] = {"El mandato del jefe de guerra",{"Lleva el hacha pesada de piedra al clarividente Regulkult a Thrallmar, en la Península del Fuego Infernal."}}
D[9406] = {"Los Mag'har",{"Entrega la carta de los Mag'har a Nazgrel en Thrallmar, en la Península del Fuego Infernal."}}
D[9407] = {"A través de El Portal Oscuro",{"Ve hasta El Portal Oscuro y encuentra al teniente general Orion. Te aguarda en el otro lado, en Terrallende."}}
D[9408] = {"Héroes olvidados",{"Habla con el Comandante en Jefe Danath Aterratrols en el Bastión del Honor."}}
D[9409] = {"Entrega urgente",{"Entrega el juego de viales a Zalduun en el Lugar del Accidente en el Valle Ammen."}}
D[9410] = {"Un espíritu guía",{"Usa el Tótem de lobo en el lugar donde encontraste el cuerpo de Krun Rompeloma y sigue al espíritu de lobo ancestral."}}
D[9415] = {"Preséntate ante el alguacil Murazul",{"Habla con el alguacil Murazul en el campamento de la Alianza cerca de Colmen'Zora."}}
D[9416] = {"Preséntate ante el general Kirika",{"Habla con el general Kirika en el campamento de la Horda cerca de Colmen'Regal."}}
D[9417] = {"La amenaza arakkoa",{"Gremni Barbalarga de la Península del Fuego Infernal quiere que mates a 4 surcadores del viento y 6 garraguardas Haal'eshi."}}
D[9418] = {"El orbe de Avruu",{"Lleva el orbe de Avruu al altar Haal'eshi al sureste de El Cubil de Haal'esh en la Península del Fuego Infernal y dáselo a Aeranas cuando quede libre."}}
D[9419] = {"Peinando el desierto",{"Encuentra y entrega la silitista al extractor de silitista y después habla con el alguacil Murazul en el campamento de la Alianza cerca de Colmen'Zora."}}
D[9420] = {"Las plumas más finas",{"Mirren Barbalarga de la Península del Fuego Infernal quiere que le lleves 8 plumas de kaliri de El Cubil de Haal'esh."}}
D[9421] = {"Entrenamiento de chamán",{"Soy Firmanvaar y haces bien en buscarme. Es mi tarea instruir a los chamanes, especialmente los que están empezando","","Solo ahora se está volviendo a aprender el chamanismos entre los <raza>, <nombre>. Eres valiente al seguir un camino que no es tan popular entre los de tu clase","","Estaré aquí cuando creas estar lista para más instrucción."}}
D[9422] = {"Peinando el desierto",{"Encuentra y entrega la silitista al extractor de silitista y después habla con el general Kirika en el campamento de la horda cerca de Colmen'Regal."}}
D[9423] = {"Retorno a Obadei",{"Informa al anacoreta Obadei del Templo de Telhamat, en la Península del Fuego Infernal, de la muerte de Sedai."}}
D[9424] = {"La venganza de Makuru",{"Makuru del Templo de Telhamat, en la Península del Fuego Infernal, quiere que le lleves 10 cuentas ancestrales Mag'har."}}
D[9425] = {"Informando en Molino Tarren",{"Ve a Molino Tarren, en las Laderas de Trabalomas, y habla con la consejera Nochealba."}}
D[9426] = {"Las Pozas de Aggonar",{"Amaan el Sabio quiere que vayas a las Pozas de Aggonar y mates 6 terroadictos y 6 putrefacciones virulentas."}}
D[9427] = {"Limpiando las aguas",{"Amaan el Sabio quiere que vayas a las Pozas de Aggonar y uses el vial de limpieza en el cadáver de Aggonar. Ve a ver a Amaan cuando el agua esté limpia de la esencia de Aggonar."}}
D[9428] = {"Misión en Puesto del Hachazo",{"Ve al Puesto del Hachazo en Vallefresno y habla con el consejero Jurasol."}}
D[9429] = {"Viaje a Villa Oscura",{"Ve a Villa Oscura en el Bosque del Ocaso y habla con el anacoreta Delan."}}
D[9430] = {"Las reliquias de Sha'naar",{"Amaan el Sabio del Templo de Telhamat en la Península del Fuego Infernal quiere que vayas a las Ruinas de Sha'naar y recuperes 10 reliquias de Sha'naar."}}
D[9431] = {"Un enfoque diferente",{"Recolecta 2 puñados de tierra purificante de Rocoso tronador y llévaselos a Wizlo Rodabrillante, en el Campamento del Tramo Blanco."}}
D[9432] = {"Viaje a Astranaar",{"Ve a Astranaar en Vallefresno y habla con el vindicador Palais."}}
D[9433] = {"En la Poza de la Luna",{"Usa la unidad de control del Robotrón cerca de la consola de control oculta en unos arbustos en el borde de la aguja más cercana a Thalanaar para tomar control del Robotrón 3000. Conduce al robot al extremo oeste de Las Mil Agujas, donde está la avanzada de la Alianza de Thalanaar. Usa el robot para recoger una muestra de agua de la Poza de la Luna y devuélveselo a Wizlo Rodabrillante en el Campamento del Tramo Blanco."}}
D[9434] = {"Probando el tónico",{"Entrega el cajón de componentes a la magistrix Elosai en el Poblado Viento Libre."}}
D[9435] = {"Los cristales desaparecidos",{"Recupera el envío de cristales raros de los Renegados y devuélveselo a Huraan en Costasur."}}
D[9436] = {"Técnicas Sangrapellejo",{"Nemeth Ojohalcón del campamento Grom'gol quiere que le lleves el tótem de un chamán Sangrapellejo."}}
D[9437] = {"El surcador del ocaso",{"Balandar Estrellaclara de Poblado Murohelecho quiere que rescates el carguero El surcador del ocaso y a su compañera Ithania de las tropas de Theramore en la Torre de la Punta Norte."}}
D[9438] = {"Mensaje para Thrall",{"Ve a Orgrimmar y entrega a Thrall la carta de Nazgrel."}}
D[9439] = {"Equipaje perdido",{"Recupera el paquete de consejero y el estoque de consejero en la Fortaleza de Angor y devuélveselos al consejero Sarophas en Kargath."}}
D[9440] = {"Bocaditos peligrosos",{"Da la comida mácula a los animales de Los Perdidos. Llévale las sobras a Cersei Serenata a Rocal en el Pantano de las Penas."}}
D[9441] = {"Tributo a los Mag'har",{"Thrall quiere que vayas a ofrecerle tus servicios a Gorkan Puñosangre en el Puesto Mag'har en la Península del Fuego Infernal."}}
D[9442] = {"Enfermedad debilitante",{"Clamor de Tierra Ryga del Puesto Mag'har en la Península del Fuego Infernal quiere que le lleves 1 champiñón capuseca de una cueva de La Gran Fisura."}}
D[9443] = {"La marca del Iluminado",{"Consigue la marca del Iluminado y llévasela a Mehlar Hojalba a El Baluarte en las Tierras de la Peste del Oeste."}}
D[9444] = {"Profanar la Tumba de Uther",{"Profana la Tumba de Uther y ve a ver a Mehlar Hojalba a El Baluarte en las Tierras de la Peste del Oeste."}}
D[9446] = {"La Tumba del Iluminado",{"Acompaña al anacoreta Truuen a la Tumba de Uther en las Tierras de la Peste del Oeste. Después habla con la suma sacerdotisa MacDonnell en el Campamento del Orvallo en las Tierras de la Peste del Oeste."}}
D[9447] = {"El bálsamo",{"Clamor de Tierra Ryga quiere que administres el bálsamo de sanación a 10 brutos Mag'har debilitados cerca del Puesto Mag'har en la Península del Fuego Infernal."}}
D[9448] = {"Piedad para los malditos",{"Mata a 3 Perdidos malditos y ve a ver al anacoreta Avuun a El Puerto en el Pantano de las Penas."}}
D[9449] = {"La llamada de la Tierra",{"Habla con el Espíritu del Valle en La Arboleda Sagrada en el Valle Ammen."}}
D[9450] = {"La llamada de la Tierra",{"Mata a 4 elementales de Tierra inquietos y ve a ver al Espíritu del Valle a La Arboleda Sagrada en el Valle Ammen."}}
D[9451] = {"La llamada de la Tierra",{"Entrega el cristal de Tierra a Firmanvaar en el Lugar del Accidente en el Valle Ammen."}}
D[9452] = {"Delicioso pargo rojo",{"Usa la red de pescar draenei para pescar 10 pargos rojos. Lleva la red y el pescado a Diktynna a la Isla Bruma Azur."}}
D[9453] = {"Busca a Acteon",{"Entrega la caja de pargo rojo a Acteon en la Avanzada Azur."}}
D[9454] = {"La caza de venados lunares",{"Lleva 6 solomillos de venado lunar a Acteon a la Avanzada Azur."}}
D[9455] = {"Extraños hallazgos",{"Entrega el cristal resplandeciente al exarca Menelaous en la Avanzada Azur."}}
D[9456] = {"Eliminando acechadores en la isla 2",{"El exarca Menelaous de la Avanzada Azur quiere que mates 8 cachorros de acechador nocturno infectado."}}
D[9457] = {"Un patrón inusual",{"Usa el don de Naias cerca del Altar de Naias para invocar al elemental de agua Naias. Derrótalo y lleva su corazón a Nemeth Ojohalcón al campamento Grom'gol."}}
D[9460] = {"Aunando fuerzas",{"Keltus Hojaoscura quiere que le robes el pañuelo bordado al jefe de centinelas y se lo lleves."}}
D[9461] = {"La llamada del Fuego",{"Busca al profeta Velen en El Exodar en la Isla Bruma Azur."}}
D[9462] = {"La llamada del Fuego",{"Busca a Tuluun en la Avanzada Azur en la Isla Bruma Azur."}}
D[9463] = {"Propiedades curativas",{"La anacoreta Fateema de la Avanzada Azur quiere que le lleves 8 ramas de atraparraíces."}}
D[9464] = {"La llamada del Fuego",{"Habla con Templar en El Claro de Ascuas en la Isla Bruma Azur."}}
D[9465] = {"La llamada del Fuego",{"Recupera la antorcha ritual y devuélvesela a Templar en El Claro de Ascuas en la Isla Bruma Azur."}}
D[9466] = {"Se busca: Garranegra el Salvaje",{"Lleva la zarpa de Garranegra al capitán forestal Venn'ren en la Avanzada del Halcón en la Península del Fuego Infernal."}}
D[9467] = {"La llamada del fuego",{"Recolecta las cenizas de Prepotencia y devuélveselas junto con la antorcha ritual a Templar en El Claro de Ascuas, en la Isla Bruma Azur. Recuerda que puedas utilizar el orbe de retorno para teletransportarte junto a Templar cuando tengas las cenizas."}}
D[9468] = {"La llamada del Fuego",{"Entrega las cenizas de Prepotencia a Tuluun en la Avanzada Azur en Isla Bruma Azur."}}
D[9469] = {"El apoyo de Barbapluma",{"Ve al Cobertizo de Barbapluma y habla con el enano si está en casa. Si no está, busca alguna pista sobre dónde puede estar."}}
D[9470] = {"Un gesto de buena fe",{"El embajador Rualeth de Pico Nidal quiere que mates al médico brujo Mai'jin y a su mascota araña Tcha'kaz."}}
D[9471] = {"A la caza de los depredadores",{"El embajador Rualeth de Pico Nidal quiere que mates 10 melenargentas sarnosos y 5 lobos melenargenta."}}
D[9472] = {"La amante de Arelion",{"La magistrix Carinda de la Avanzada del Halcón quiere que alejes a Viera Suspirosol del asentamiento y que uses el pergamino de Reprensión de Carinda."}}
D[9473] = {"La alternativa a la alternativa",{"Daedal de la Avanzada Azur quiere que le lleves 5 bulbos de boca de dragón azur."}}
D[9474] = {"La marca del Iluminado",{"Consigue la marca del Iluminado y devuélvesela al anacoreta Truuen en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[9475] = {"Reclamar los huevos",{"Recolecta 5 huevos de grifo y regresa junto al embajador Rualeth de Pico Nidal."}}
D[9476] = {"En busca de Barbapluma",{"Ve a Shadra'Alor y busca huellas de Barbapluma."}}
D[9483] = {"Los placeres de la vida",{"No por estar de peregrinación tenemos que renunciar a todo. Hace siglos que no me tomo un buen vino","","¡Mataría por una botella de licor Cenarion!","","Sí, ya sé que no queda bien que me guste una especialidad de los elfos de la noche."}}
D[9484] = {"Domar a la bestia",{"Usa la fusta de doma para domar un dracohalcón enloquecido y vuelve junto a la teniente Correalba."}}
D[9485] = {"Domar a la bestia",{"Usa la fusta de doma para domar un murciélago brumoso y vuelve junto a la teniente Correalba."}}
D[9486] = {"Domar a la bestia",{"Usa la fusta de doma para domar un garragil mayor y vuelve junto a la teniente Correalba."}}
D[9487] = {"Atracadores Arcanos",{"El arcanista Vandril quiere que reúnas 10 fragmentos arcanos para él."}}
D[9488] = {"Una toga sencilla",{"El arcanista Vandril quiere que le lleves 15 piezas de paño de lino y 1 glándula de seda de husaraña."}}
D[9489] = {"Limpiar La Cicatriz",{"Lanza Palabra de poder: entereza a 6 forestales Canción Eterna en La Cicatriz Muerta."}}
D[9490] = {"La matriarca despellejadora de roca",{"Consigue una garra de Garranegra la Indómita en La Gran Fisura y llévasela a Ikan en el Templo de Telhamat, en la Península del Fuego Infernal."}}
D[9491] = {"Avaricia",{"Eralan de Tranquillien quiere que encuentres el anillo de oro marcado en las Catacumbas Amani."}}
D[9492] = {"Girando las tornas",{"Lleva el puño del jefe de guerra Kargath al Comandante en Jefe Danath Aterratrols al Bastión del Honor."}}
D[9493] = {"El orgullo de la Horda vil",{"El comandante de campo Romus del Bastión del Honor quiere que mates a 8 legionarios Mano Destrozada, 4 centuriones Mano Destrozada y 4 campeones Mano Destrozada."}}
D[9494] = {"Ascuas viles",{"La magus Zabraxis del Bastión del Honor quiere que le lleves ascuas viles."}}
D[9495] = {"La voluntad del Jefe de Guerra",{"Lleva el puño del Jefe de Guerra Kargath a Nazgrel a Thrallmar."}}
D[9496] = {"El orgullo de la Horda vil",{"El cazador de las Sombras Ty'jin de Thrallmar quiere que mates a 8 legionarios Mano Destrozada, 4 centuriones Mano Destrozada y 4 Campeones Mano Destrozada."}}
D[9498] = {"La Avanzada del Halcón",{"Preséntate ante el capitán forestal Venn'ren en la Avanzada del Halcón en la Península del Fuego Infernal."}}
D[9499] = {"La Avanzada del Halcón",{"Ve a la Avanzada del Halcón al suroeste de la Península del Fuego Infernal y preséntate ante el capitán forestal Venn'ren."}}
D[9500] = {"La llamada del agua",{"Habla con el clarividente Nobundo en La Sala de Cristal dentro de El Exodar, en la Isla Bruma Azur."}}
D[9501] = {"La llamada del agua",{"Ve a El Arrecife Oculto, en la Isla Bruma de Sangre, y habla con Acuosa"}}
D[9502] = {"La llamada del agua",{"Habla con el clarividente Nobundo en La Sala de Cristal dentro de El Exodar, en la Isla Bruma Azur."}}
D[9503] = {"La llamada del agua",{"Reúne 6 viales de esencia hedionda y llévaselas a Acuosa en El Arrecife Oculto, en la Isla Bruma de Sangre."}}
D[9504] = {"La llamada del Agua",{"Llena la bota y llévasela a Acuosa a El Arrecife Oculto en la Isla Bruma de Sangre."}}
D[9505] = {"La profecía de Velen",{"Daedal quiere que vayas hacia el sur y busques al pueblo que mencionó la criatura herida."}}
D[9506] = {"Un pequeño susto",{"El almirante Odesyus del Desembarco de Odesyus quiere que recuperes la rosa náutica y el mapa náutico robados por Ventura y Cía."}}
D[9508] = {"La llamada del agua",{"Lleva la cabeza de Tel'athion a Acuosa en El Arrecife Oculto, en la Isla Bruma de Sangre"}}
D[9509] = {"La llamada del agua",{"Llévale el frasco del agua más pura al clarividente Nobundo en El Exodar, en la Isla Bruma Azur."}}
D[9510] = {"Pellejos de uñagrieta lomohirsuto",{"El proveedor Braknar del Puesto Mag'har, en la Península del Fuego Infernal, quiere que le lleves 5 pellejos de uñagrieta lomohirsuto."}}
D[9511] = {"Los planes de guerra de Kargath"}
D[9512] = {"El jumbo gumbo de Cocinitas",{"\"Cocinitas\" MacSalsafloja en Desembarco de Odesyus quiere que le lleves 6 piezas de carne de reptador sigiloso."}}
D[9513] = {"Recuperar las ruinas",{"La sacerdotisa Kyleen Il'dinare en el Desembarco de Odesyus, en la Isla Bruma Azur, quiere que mates 5 mirmidones Escama de Cólera, 5 nagas Escama de Cólera y 5 sirenas Escama de Cólera."}}
D[9514] = {"Tablilla cubierta de runas",{"Llévale la tablilla cubierta de runas a la sacerdotisa Kyleen Il'dinare a Desembarco de Odesyus en Isla Bruma Azur."}}
D[9515] = {"El Señor de la Guerra Sriss'tiz",{"La sacerdotisa Kyleen Il'dinare en el Desembarco de Odesyus, en la Isla Bruma Azur, quiere que mates al Señor de la Guerra Sriss'tiz."}}
D[9516] = {"Destruye a la Legión",{"Mata 6 azotadoras Mannoroc, 6 guardias viles y 6 infernales abrasadores, y regresa junto al vindicador Vedaar en Canción del Bosque, en Vallefresno."}}
D[9517] = {"¡Sería una lástima desperdiciarlo!",{"Llévale 15 piezas de madera Grito de Guerra y 5 piezas de madera vil de Satyrnaar a Gnarl a la Canción del Bosque."}}
D[9518] = {"Agentes de destrucción",{"La centinela Luciel Susurrestelar de Canción del Bosque quiere que mates al sobrestante Gorthak, 2 machacadores Grito de Guerra, 5 deforestadores de la Horda y 10 exploradores de la Horda."}}
D[9519] = {"El cáliz perdido",{"Llévale el Cáliz de Elune a Kayneth Ventoleve en la Canción del Bosque."}}
D[9520] = {"Planes diabólicos",{"Entrega los planes diabólicos al vindicador Vedaar en Canción del Bosque, en Vallefresno."}}
D[9521] = {"Informe del frente norte",{"Entrega el informe de la centinela Luciel a la centinela Cantolongo en el Claro Ala de Plata."}}
D[9522] = {"¡Nunca más!",{"Mata a Gorgannon y a Diathorus el Buscador, y regresa junto al vindicador Vedaar en Canción del Bosque, en Vallefresno."}}
D[9523] = {"Material frágil y valioso, manipúlese con cuidado",{"El arqueólogo Adamant Coracero en el Desembarco de Odesyus, en la Isla Bruma Azur, quiere que le lleves 8 reliquias antiguas."}}
D[9524] = {"Encarcelados en la Ciudadela",{"Rescata a la capitana Alina del interior de la Ciudadela del Fuego Infernal antes de que la ejecuten","","Esta misión se debe completar en dificultad de mazmorra heroica."}}
D[9525] = {"Imprisoned in the Citadel",{"Rescue Captain Boneshatter inside Hellfire Citadel before he is executed","","This quest must be completed in Heroic dungeon difficulty."}}
D[9526] = {"Recuperar el Cerro Lumbrevil",{"in"}}
D[9527] = {"Solo quedan los restos",{"Cowlen, de la Isla Bruma Azur, quiere que recuperes los restos de su familia."}}
D[9528] = {"Una llamada de socorro",{"Escolta a Magwin por la isla hasta su casa."}}
D[9529] = {"La piedra",{"Consigue una piedra del vacío de La Cicatriz Muerta."}}
D[9530] = {"Hay un traidor",{"El almirante Odesyus en el Desembarco de Odesyus, en la Isla Bruma Azur, quiere que le lleves 1 árbol hueco y 5 pilas de hojas."}}
D[9531] = {"En compañía de árboles",{"El almirante Odesyus en el Desembarco de Odesyus, en la Isla Bruma Azur, quiere que vigiles la reunión que tendrá lugar entre Geezle y el traidor","","Regresa junto a él cuando sepas la identidad del traidor."}}
D[9532] = {"Encuentra a Keltus Hojaoscura",{"Encuentra a Keltus Hojaoscura."}}
D[9533] = {"Una mano amiga",{"Dirígete a Canción del Bosque y habla con el arquitecto Nemos."}}
D[9534] = {"Destruir a la Legión",{"Mata a 6 azotadoras Mannoroc, 6 guardias viles y 6 infernales abrasadores y ve a ver a Valusha al Puesto del Hachazo en Vallefresno."}}
D[9535] = {"Planes diabólicos",{"Entrega los planes diabólicos a Valusha en el Puesto del Hachazo en Vallefresno."}}
D[9536] = {"¡Nunca más!",{"Mata a Gorgannon y a Diathorus el Buscador y ve a ver a Valusha al Puesto del Hachazo en Vallefresno."}}
D[9537] = {"Justicia para el gnomo",{"El almirante Odesyus de El Desembarco de Odesyus quiere que le saques información al traidor ingeniero \"Chispik\" Pasarrosca."}}
D[9538] = {"Aprendizaje de lenguas",{"Lee el manual de lengua fúrbolg de Semprepino que Aurren te dio e interactúa con el Tótem de Akida en la Avanzada Azur."}}
D[9539] = {"El Tótem de Coo",{"Encuentra el Tótem de Coo con las pistas que tienes."}}
D[9540] = {"El Tótem de Tikti",{"Encuentra el Tótem de Tikti con las pistas que tienes."}}
D[9541] = {"El Tótem de Yor",{"Encuentra el Tótem de Yor con las pistas que tienes."}}
D[9542] = {"El Tótem de Vark",{"Encuentra el Tótem de Vark con las pistas que tienes."}}
D[9543] = {"Expiación",{"Habla con Amaan el Sabio en el Templo de Telhamat en la Península del Fuego Infernal."}}
D[9544] = {"La profecía de Akida",{"Libera a 8 cautivos Semprepino de las jaulas que se encuentran en la Aldea Brazolanudo. Vuelve junto a Arugoo de los Semprepino, en la Avanzada Azur, cuando completes esta tarea."}}
D[9545] = {"La reliquia del vidente",{"Amaan el Sabio del Templo de Telhamat en la Península del Fuego Infernal quiere que vayas al cadáver de Sedai al noreste del Templo y uses la reliquia del vidente allí. Después vuelve a ver a Amaan."}}
D[9547] = {"La llamada del aire",{"Habla con el clarividente Nobundo en La Sala de Cristal dentro de El Exodar, en la Isla Bruma Azur."}}
D[9548] = {"Equipamiento robado",{"Lleva el equipamiento de Clopper a Clopper Zumbibang, que se oculta en un caparazón de tortuga en la playa."}}
D[9549] = {"Los artefactos de los Cienonegro",{"Lleva tres ídolos múrlocs rudimentarios y seis cuchillos múrlocs rudimentarios a Clopper Zumbibang, que se esconde en el caparazón de una tortuga de la playa."}}
D[9550] = {"Un mapa con destino desconocido",{"Encuentra el pabellón descrito en el mapa y busca lo que el cartógrafo intentaba registrar."}}
D[9551] = {"La llamada del aire",{"Habla con el clarividente Nobundo, que está en la Sala de Cristal, dentro de El Exodar, en la Isla Bruma Azur."}}
D[9552] = {"La llamada del aire",{"Habla con Velaada en la Cima Ventosalvaje, en la Isla Bruma Azur."}}
D[9553] = {"La llamada del aire",{"Habla con Susurrus en la Cima Ventosalvaje, en la Isla Bruma Azur."}}
D[9554] = {"La llamada del aire",{"Vuelve junto al clarividente Nobundo en El Exodar, en la Isla Bruma Azur, con la espiral de aire"}}
D[9555] = {"La llamada del Fuego",{"Habla con el clarividente Nobundo en El Exodar en la Isla Bruma Azur."}}
D[9556] = {"Al victori...",{"Hazte con una botella de agua Sagrada de Stratholme en la ciudad con el mismo nombre y entrégala al mago de Lordaeron en el Barrio de los Magos de Ventormenta o Entrañas una vez consigas la victoria para tu bando en las Tierras de la Peste."}}
D[9557] = {"Descifrar el libro",{"Llévale el diario antiguo al Anacoreta Paetheus en la Avanzada de Sangre."}}
D[9558] = {"Los Barbalarga",{"Busca a Gremni Barbalarga al noroeste de El Cubil de Haal'esh, hacia el oeste del Bastión del Honor en la Península del Fuego Infernal."}}
D[9559] = {"El Bastión Semprepino",{"Habla con el gran jefe Semprepino en el Bastión Semprepino."}}
D[9560] = {"¡Las bestias del apocalipsis!",{"Moordo del Bastión Semprepino, en la Isla Bruma Azur, quiere que le lleves 8 pellejos de devastador."}}
D[9561] = {"Las palabras de Nolkai",{"Encuentra la ubicación descrita en el diario de Nolkai y descubre sus pertenencias enterradas desde hace tiempo."}}
D[9562] = {"Múrlocs... ¿Por qué?",{"Gurf del Bastión Semprepino en la Isla Bruma Azur quiere que recuperes 5 sacos de grano Semprepino."}}
D[9563] = {"Ganar la confianza de Mirren",{"Mirren Barbalarga quiere que le lleves 1 cerveza de Nethergarde. También debes alcanzar la reputación de amistoso ante el Bastión del Honor para completar esta misión."}}
D[9564] = {"La dignidad de Gurf",{"Devuélvele a Gurf su dignidad en el Bastión Semprepino en la Isla Bruma Azur."}}
D[9565] = {"Registra el Bastión Semprepino",{"Busca pistas en el Bastión Semprepino."}}
D[9566] = {"Cristales de sangre",{"Habla con el gran jefe Semprepino en el Bastión Semprepino."}}
D[9567] = {"Conoce a tu enemigo",{"Encuentra el monumento de Nazzivus en Nazzivian y recupera un glifo de dicho monumento. Regresa junto a la vindicadora Aalesia en la Avanzada de Sangre cuando tengas uno de los glifos."}}
D[9568] = {"A la ofensiva",{"La vindicadora Aalesia en la Avanzada de Sangre quiere que mates a 10 sátiros Nazzivus, 5 pícaros Nazzivus y 5 jurapenas Nazzivus."}}
D[9569] = {"Contener la amenaza",{"Mata a 5 acechasombras Axxarien, 5 clamainfernos Axxarien y a Zevrax, recolecta entonces 5 cristales corruptos y llévaselos a la vindicadora Aalesia en la Avanzada de Sangre."}}
D[9570] = {"El Kurken acecha",{"Kurz el Revelador del Bastión Semprepino en la Isla Bruma Azur quiere que mates a El Kurken y que le lleves su pellejo."}}
D[9571] = {"El pellejo de El Kurken",{"Entrega el pellejo de El Kurken a Moordo en el Bastión Semprepino."}}
D[9572] = {"Debilitar la muralla",{"Mata al guardián vigía Gargolmar, a Omor el Sinmarcas y el draco, Nazan. Llévale la mano de Gargolmar, la pezuña de Omor y la cabeza de Nazan a Caza'rez en Thrallmar, en la Península del Fuego Infernal."}}
D[9573] = {"El cabecilla Oomooroo",{"Semprepino el Menor del Bastión Semprepino en la Isla Bruma Azur quiere que mates al cabecilla Oomooroo y a 9 lechúcico salvaje enloquecido."}}
D[9574] = {"Víctimas de la corrupción",{"Llévale 6 trozos de corteza cristalizada a Morae en la Avanzada de Sangre."}}
D[9575] = {"Debilitar la muralla",{"Mata al guardián vigía Gargolmar, a Omor el Sinmarcas y el draco, Nazan. Llévale la mano de Gargolmar, la pezuña de Omor y la cabeza de Nazan a Pistolete en el Bastión del Honor, en la Península del Fuego Infernal."}}
D[9576] = {"El colgante de Cruelfin",{"Llévale el colgante de cristal rojo a Morae en la Avanzada de Sangre."}}
D[9578] = {"En busca de Galaen",{"Busca al marido de Morae, Galaen."}}
D[9579] = {"El sino de Galaen",{"Llévale el amuleto de Galaen a Morae en la Avanzada de Sangre."}}
D[9580] = {"Las necesidades del oso",{"Llévale 8 costillares de oso marrón adulto al rastreador Lyceon en la Avanzada de Sangre."}}
D[9581] = {"Las lecciones de los cristales",{"Consigue una muestra de cristal del lugar del accidente usando el pico de minero de cristales en el cristal del lugar del accidente y llévalo al presagista Mikolaas de la Avanzada de Sangre."}}
D[9582] = {"La fuerza de uno solo",{"Abre la jaula del devastador, mata al devastador de la Muerte, y regresa junto a Ruada en la Avanzada Azur, en la Isla Bruma Azur."}}
D[9584] = {"La segunda muestra",{"Consigue una muestra de cristal alterado utilizando el pico de minero de cristal en el cristal de Bruma de Sangre modificado al presagista Mikolaas de la Avanzada de Sangre."}}
D[9585] = {"La última muestra",{"Consigue una muestra de cristal Axxarien utilizando el Pico de minero de cristales en el cristal axxarien y llévaselo al heraldo en la Avanzada de Sangre."}}
D[9586] = {"Ayudar a Tavara",{"Guvan de la Avanzada Azur quiere que encuentres a Tavara y cures sus heridas."}}
D[9587] = {"Aciagas nuevas",{"Ve al Bastión del Honor, en la Península del Fuego Infernal, y entrégale al Comandante en Jefe Danath Aterratrols la carta agorera."}}
D[9588] = {"Aciagas nuevas",{"Lleva la carta agorera a Nazgrel en Thrallmar en la Península del Fuego Infernal."}}
D[9589] = {"La sangre es vida",{"Reúne 10 viales de sangre de orco vil y regresa junto a Pistolete en el Bastión del Honor, en la Península del Fuego Infernal."}}
D[9590] = {"La sangre es vida",{"Consigue 10 viales de sangre de orcos viles y llévaselos al centurión Caza'rez en Thrallmar, en la Península del Fuego Infernal."}}
D[9591] = {"Domar a la bestia",{"Usa el Tótem de doma para domesticar un reptador con púas y vuelve junto a la cazadora Kella Arconocturno cuando lo hayas conseguido."}}
D[9592] = {"Domar a la bestia",{"Usa el Tótem de doma para domesticar un maderazancudo superior y vuelve junto a la cazadora Kella Arconocturno."}}
D[9593] = {"Domar a la bestia",{"Usa el Tótem de doma para domesticar un acechador nocturno y vuelve junto a la cazadora Kella Arconocturno."}}
D[9594] = {"Signos de la Legión",{"Mata a ocho sátiros Nazzivus y a ocho Jurapenas Nazzivus, y lleva la placa de armadura de Tzerak a la vindicadora Aalesia de la Avanzada de Sangre."}}
D[9595] = {"Control",{"Mata múrlocs de La Costa de Cieno para invocar a la ánima maga quel'dorei. Destrúyela y ve a hablar con Bati en El Arca de las Luces de El Exodar."}}
D[9598] = {"Redención",{"Estudia el Libro de Divinidad y habla con Jol."}}
D[9599] = {"<UNUSED>",{"Habla con Jol en El Exodar."}}
D[9600] = {"Redención",{"Jol quiere que resucites al chamán fúrbolg joven con el Símbolo de la Vida y después se lo devuelvas."}}
D[9601] = {"Hacia El Baluarte",{"Habla con Mehlar Hojalba en El Baluarte."}}
D[9602] = {"Líbralos del mal...",{"Entrega la comunicación del traidor al exarca Menelaous en la Avanzada Azur."}}
D[9603] = {"Camas, vendas y algo más",{"Llévale la lista de Topher a Laando, el maestro de hipogrifos de la Avanzada de Sangre."}}
D[9604] = {"En alas de un hipogrifo",{"Cómprale a Laando un viaje en hipogrifo a El Exodar. Cuando aterrices, llévale la lista de Topher a Nurguni en el Trono de los Naaru, en El Exodar."}}
D[9605] = {"El maestro de hipogrifos Stephanos",{"Encuentra a Stephanos en las afueras de El Exodar y compra un viaje en hipogrifo para volver a la Avanzada de Sangre."}}
D[9606] = {"Regreso junto a Topher Loaal",{"Habla con Stephanos para comprar un viaje en hipogrifo de vuelta a la Avanzada de Sangre. Cuando llegues, entrégale los suministros de Nurguni al cuidador Topher Loaal."}}
D[9607] = {"Corazón furioso",{"Investiga a fondo El Horno de Sangre y después informa al Comandante en Jefe Danath Aterratrols en el Bastión del Honor, en la Península del Fuego Infernal."}}
D[9608] = {"Corazón furioso",{"Investiga a fondo El Horno de Sangre y después informa a Nazgrel en Thrallmar en la Península del Fuego Infernal."}}
D[9609] = {"Ayuda al vigía Biggs",{"Encuentra al vigía Biggs en el Pantano de las Penas."}}
D[9610] = {"Charca de Lágrimas",{"Consigue 10 artefactos Atal'ai y llévaselos a Holaaru en El Puerto del Pantano de las Penas."}}
D[9612] = {"¡Gracias de corazón!",{"Habla con el exarca Menelaous en la Avanzada Azur."}}
D[9616] = {"¡Bandidos!",{"Llévale la comunicación del elfo de sangre al exarca Menelaous en la Avanzada Azur."}}
D[9617] = {"Busca a los errantes",{"Habla con la teniente Correalba en El Retiro del Errante."}}
D[9618] = {"Devuelve los informes",{"Lleva los informes de Keltus Hojaoscura a Zelanis en la Ciudad de Lunargenta."}}
D[9619] = {"La runa de invocación",{"Usa la piedra de vacío para invocar a un abisario en la Aldea de Bruma Dorada, derrótalo, y regresa junto a Talionia en la Ciudad de Lunargenta."}}
D[9620] = {"El equipo de investigación desaparecido",{"El presagista Mikolaas quiere que encuentres al equipo de reconocimiento que había enviado a las Ruinas de Loreth'Aran y les ayudes en todo lo que puedas."}}
D[9621] = {"Envío para la Horda",{"Llévale la carta de Lor'themar Theron a Lady Sylvanas Brisaveloz en Entrañas, la capital de los Renegados, en los Claros de Tirisfal."}}
D[9622] = {"Avisar a tu pueblo",{"Habla con el exarca Menelaous en la Avanzada Azur."}}
D[9623] = {"Madurez",{"El exarca Menelaous en la Avanzada Azur ha pedido que entregues las órdenes del exarca a Torallius el Controlador de la Manada que se encuentra a las afueras de El Exodar."}}
D[9624] = {"Un caprichito goloso",{"Aonar de la Encrucijada de Kessel quiere que le lleves 10 peras de arena."}}
D[9625] = {"Con los elekks no se bromea",{"Habla con Vorkhan el Pastor de elekks, en la Isla Bruma de Sangre."}}
D[9626] = {"Encuentro con el Jefe de Guerra",{"Lady Sylvanas Brisaveloz quiere que lleves la carta con su sello a Thrall en Orgrimmar, capital de Durotar."}}
D[9627] = {"Fidelidad a la Horda",{"Vuelve a la Ciudad de Lunargenta y habla con Lor'themar Theron."}}
D[9628] = {"Recuperar los datos",{"Consigue el cristal de datos de la expedición de la Escama de Cólera cerca de los cartógrafos muertos y regresa junto al presagista Mikolaas en la Avanzada de Sangre."}}
D[9629] = {"Aquí te pillo, aquí te marco",{"Morae, de la Avanzada de Sangre, quiere que 'marques' a 6 exploradores Cienonegro con el hierro múrloc."}}
D[9630] = {"El diario de Medivh",{"El archimago Alturus, del Paso de la Muerte, quiere que vayas a Karazhan y hables con Wravien."}}
D[9631] = {"La ayuda de una compañera",{"Lleva el trozo de hueso carbonizado a Kalynna Lathrojo en el Área 52 en Tormenta Abisal."}}
D[9632] = {"Aliados inesperados",{"Llévale la carta de presentación a la cazadora Kella Arconocturno."}}
D[9633] = {"Camino de Auberdine",{"Lleva el barco desde el embarcadero próximo a la cazadora Kella Arconocturno hasta Auberdine. Cuando llegues a Auberdine, lleva la carta de presentación a Thundris Tejevientos."}}
D[9634] = {"Depredadores alienígenas",{"Mata 10 proles de Bruma de Sangre y vuelve a hablar con Vorkhan el pastor de elekks en la Encrucijada de Kessel en la Isla Bruma de Sangre."}}
D[9635] = {"¡El extractor de motas Zapacelerador!",{"Llévale 15 piezas de bomba de vapor a Mack Diver en Zabra'jin, en la Marisma de Zangar."}}
D[9636] = {"¡El extractor de motas Zapacelerador!",{"Llévale 15 piezas de bomba de vapor a K. Lee Fritito en Telredor, en la Marisma de Zangar."}}
D[9637] = {"La petición de Kalynna",{"Kalynna Lathrojo quiere recuperar el Escrito del Ocaso del brujo supremo Malbisal en Las Salas Arrasadas de la Ciudadela del Fuego Infernal y el Libro de los Nombres Olvidados de Tejeoscuro Syth en las Salas Sethekk de Auchindoun","","Esta misión debe ser completada en dificultad heroica."}}
D[9638] = {"En buenas manos",{"Habla con Gradav en la Biblioteca del Guardián, en Karazhan."}}
D[9639] = {"Kamsis",{"Habla con Kamsis en la Biblioteca del Guardián, en Karazhan."}}
D[9640] = {"La sombra de Aran",{"Consigue el diario de Medivh y vuelve junto a Kamsis en la Biblioteca del Guardián, en Karazhan."}}
D[9641] = {"Fragmentos de cristal irradiado",{"El vindicador Boros de la Avanzada de Sangre quiere que le lleves diez fragmentos de cristal radioactivo."}}
D[9642] = {"Más fragmentos de cristal irradiado",{"Si tienes más fragmentos de cristal irradiado, con mucho gusto te los cambiaré por uno de mis cristales."}}
D[9643] = {"Parras constrictoras",{"El rastreador Lyceon en la Avanzada de Sangre quiere que le lleves 6 parras constrictoras espinosas."}}
D[9644] = {"Nocturno",{"Ve a El Bancal del Maestro en Karazhan y usa la urna de Kalynna para invocar a Nocturno. Recupera la esencia arcana intangible del cadáver de Nocturno y llévasela al archimago Alturus."}}
D[9645] = {"El Bancal del Maestro",{"Ve a El Bancal del Maestro en Karazhan y lee el diario de Medivh."}}
D[9646] = {"SE BUSCA: Garraletal",{"Lleva la garra de Garraletal al presagista Mikolaas en la Avanzada de Sangre."}}
D[9647] = {"Sacrificar a los aleteadores",{"El rastreador Lyceon en la Avanzada de Sangre quiere que mates 10 aleteadores azul real."}}
D[9648] = {"La colección de champiñones de Mac'Aree",{"Jessera de Mac'Aree en la Avanzada de Sangre quiere 1 cuernohediondo acuático, 1 champiñón sanguino, 1 poliespora ruinosa y 1 hongo de bellota vil."}}
D[9649] = {"Las lágrimas de Ysera",{"Jessera de Mac'Aree en la Avanzada de Sangre quiere 2 lágrimas de Ysera."}}
D[9663] = {"La carrera de Kessel",{"Kessel de la Encrucijada de Kessel, en la Isla Bruma de Sangre, quiere que avises al gran jefe Semprepino del Bastión Semprepino, al exarca Menelaous de la Avanzada Azur y al almirante Odesyus del Desembarco de Odesyus sobre la inminente invasión de los elfos de sangre. Tienes 15 minutos. Regresa junto a Kessel cuando hayas completado esta tarea. (Asegúrate de que no toque el agua)."}}
D[9664] = {"Nuevas avanzadas",{"Captura la Torre de la Guardia de la Corona, la Torre de la Muralla del Este, la Torre del Paso Norte y la Torre del Bosque de la Peste en las Tierras de la Peste del Este. Tras hacerlo, regresa y habla con el Emisario Barbablanca en la Capilla de la Esperanza de la Luz."}}
D[9665] = {"Fortalecimiento de nuestras defensas",{"Captura la Torre de la Guardia de la Corona, la Torre de la Muralla del Este, la Torre del Paso Norte y la Torre del Bosque de la Peste en las Tierras de la Peste del Este. Tras hacerlo, regresa y habla con el Emisario Gormok en la Capilla de la Esperanza de la Luz."}}
D[9666] = {"Declaración de poder",{"Kessel de la Encrucijada de Kessel, en la Isla Bruma de Sangre, quiere que mates a Lord Xiz, de la Guarida Escama de Cólera, y atravieses su cadáver con el estandarte draenei."}}
D[9667] = {"Salvar a la princesa Semprepino",{"Libera a la Princesa Semprepino de su jaula y habla después con el embajador Semprepino Frasaboo, en la Avanzada de Sangre","","Tienes que matar al gran jefe Erizapúas para conseguir la llave de la jaula."}}
D[9668] = {"Informar al exarca Admetius",{"Habla con el exarca Admetius en la Avanzada de Sangre."}}
D[9669] = {"La expedición desaparecida",{"Mata 8 brumahiladoras, 8 brumasanguijuela y a su líder, Zarakh. Vuelve a ver a Achelus en la Avanzada de Sangre cuando hayas completado la tarea."}}
D[9670] = {"¡Viven! A lo mejor...",{"El investigador Cornelius ha pedido que liberes 5 investigadores de la expedición."}}
D[9671] = {"Entrega urgente"}
D[9672] = {"El legado de la Sangre Maldita",{"El almirante Odesyus quiere que encuentres al capitán Edward Hanes."}}
D[9673] = {"Doma de bestias",{"Ve a la Ciudad de Lunargenta y habla con Halthenis."}}
D[9674] = {"Los nagas Sangre Maldita",{"El capitán Edward Hanes de la Isla Cicatriz de Vermis quiere que mates a 10 nagas Sangre Maldita."}}
D[9675] = {"Doma de bestias",{"Habla con Ganaar en La Grada de los Mercaderes de El Exodar."}}
D[9676] = {"Entrenamiento de paladín",{"Habla con Jesthenis Golpesol, el instructor de clase de paladines, en La Aguja del Sol en la Isla del Caminante del Sol."}}
D[9677] = {"El llamamiento del Lord caballero Sangrevalor",{"Habla con el Lord caballero Sangrevalor en la Plaza del Errante de la Ciudad de Lunargenta."}}
D[9678] = {"La primera prueba",{"Viaja a la isla que el Lord caballero Sangrevalor describió, encuentra la caverna, y enciende el blandón. Cuando acabe la primera prueba vuelve junto al Lord caballero Sangrevalor en la Ciudad de Lunargenta."}}
D[9680] = {"Resucitar el pasado",{"El archimago Alturus quiere que vayas a las montañas al sur de Karazhan en el Paso de la Muerte y consigas un trozo de hueso carbonizado."}}
D[9681] = {"Un estudio sobre el poder",{"Habla con el magister Astalor Jurasangre en la cámara oculta debajo del cuartel general de los Caballeros de sangre."}}
D[9682] = {"Los Desesperados...",{"El capitán Edward Hanes de la Isla Cicatriz de Vermis quiere que consigas 4 almas de Sangre Maldita."}}
D[9683] = {"El fin de la Sangre Maldita",{"El capitán Edward Hanes de la Isla Cicatriz de Vermis quiere que destruyas la estatua de la reina Azshara y mates a Atoph, el Sangre Maldita."}}
D[9684] = {"Buscando la Luz",{"Llena la vasija refulgente en magistri elfos de sangre y llévasela al Lord caballero Sangrevalor a Ciudad de Lunargenta."}}
D[9685] = {"Redimir a los muertos",{"Lleva la vasija refulgente llena a la posada de la Ciudad de Lunargenta y utiliza su magia para resucitar a Sangrias Hojafirme."}}
D[9686] = {"La segunda prueba",{"Completa la segunda prueba derrotando a los Campeones Furiasangre, Pautaluz, Hojágil y Golpesol en el pabellón cerca del maestro Kelerun Lamento de Sangre."}}
D[9687] = {"Recuperando huesos sacros",{"El príncipe Toreth de Isla Cicatriz de Vermis quiere que le lleves 8 huesos de dragón."}}
D[9688] = {"Entrando en el Sueño",{"El príncipe Toreth de Isla Cicatriz de Vermis quiere que mates 5 crías y 5 estirpes viridianas."}}
D[9689] = {"Tajobuche",{"El Príncipe Toreth de la Isla Cicatriz de Vermis ha pedido que mates a Tajobuche."}}
D[9690] = {"La segunda prueba",{"Preséntate ante el maestro Kelerun Lamento de Sangre."}}
D[9691] = {"Retorno a Lunargenta",{"Ve a ver al Lord caballero Sangrevalor en Ciudad de Lunargenta."}}
D[9692] = {"El camino de los adeptos",{"Lleva 1 gema kor corrupta, 1 caja de lingotes forjados con sangre, sangre del Colérico y 1 insignia de Caballero de sangre al Lord caballero Sangrevalor a Ciudad de Lunargenta."}}
D[9693] = {"¿Qué es Argus para ti?",{"El exarca Admetius de la Avanzada de Sangre quiere que hables con el vindicador Boros."}}
