D[9696] = {"Traducciones",{"Lleva la misiva de los halcones del Sol a la interrogadora Elysia a la Avanzada de Sangre."}}
D[9697] = {"La vigía Leesa'oh",{"Ve al Puesto de Vigilancia Cenarion de la Marisma de Zangar y habla con la vigía Leesa'oh."}}
D[9698] = {"Audiencia con el Profeta",{"Lleva la traducción de la carta de los Halcón del Sol al profeta Velen a El Exodar."}}
D[9699] = {"Verdad o mentira",{"Lleva las órdenes de Velen al vindicador Boros a la Avanzada de Sangre."}}
D[9700] = {"Disparando magia en la oscuridad",{"El vindicador Boros de la Avanzada de Sangre quiere que encuentres el portal del Sol y mates 5 anomalías del vacío."}}
D[9701] = {"Observación de esporinos",{"Investiga La Cañada Emergente en la Marisma de Zangar e informa a la vigía Leesa'oh del Puesto de Vigilancia Cenarion en la Marisma de Zangar de tus pesquisas."}}
D[9702] = {"Cuestión de glotonería",{"Recoge 10 restos de alimentos y llévaselas al vigía Leesa'oh al Puesto de Vigilancia Cenarion de la Marisma de Zangar."}}
D[9703] = {"El Crionúcleo",{"El vindicador Kuros de la Avanzada de Sangre quiere que recuperes 12 cajas de suministros médicos."}}
D[9704] = {"Ejecutados por los desdichados",{"Ve hacia el sur a las Ruinas de Ciudad de Lunargenta y busca a la avanzada asesinada en Calle del Alba."}}
D[9705] = {"Recuperación de paquete",{"Regresa junto a la avanzada Alarion con el paquete de Erona."}}
D[9706] = {"El diario de Galaen: El destino del vindicador Saruan",{"Lleva el diario de Galaen al vindicador Kuros a la Avanzada de Sangre."}}
D[9707] = {"Forjando el arma",{"Lleva el cajón de materiales a Bemarrin a Ciudad de Lunargenta."}}
D[9708] = {"Ese hongo me suena",{"Recolecta 15 muestras de champiñones y llévaselas a la vigía Leesa'oh al Puesto de Vigilancia Cenarion de la Marisma de Zangar."}}
D[9709] = {"Volver a robar los champiñones",{"Recolecta 10 cajas de champiñones y llévaselas a la vigía Leesa'oh al Puesto de Vigilancia Cenarion en la Marisma de Zangar."}}
D[9710] = {"La corcesca templada en sangre",{"Espera mientras Bemarrin forja tu arma."}}
D[9711] = {"Matis el Cruel",{"El vindicador Kuros de Avanzada de Sangre quiere que captures a Matis el Cruel."}}
D[9712] = {"El caballo de guerra thalassiano",{"Habla con el Lord caballero Sangrevalor para aprender a invocar a tu caballo de guerra thalassiano."}}
D[9713] = {"Recogiendo fluochampiñones"}
D[9714] = {"¡Tráeme otra mata!"}
D[9715] = {"¡Otra mata!",{"Recolecta 5 hibiscos sanguinos y llévaselos a Gzhun'tt en Esporaggar en la Marisma de Zangar."}}
D[9716] = {"Problemas en el Lago Umbropantano",{"Investiga el origen de la pérdida de agua en Lago Umbropantano. Luego ve a ver a Ysiel Vientocantor al Refugio Cenarion, en la Marisma de Zangar."}}
D[9717] = {"El esqueje",{"Recolecta un esqueje de sotoespora y llévaselo a T'shu a Esporaggar en la Marisma de Zangar."}}
D[9718] = {"A vuelo de pájaro",{"Ysiel Vientocantor quiere que uses el amuleto de cuervo tormentoso para explorar los lagos principales de la Marisma de Zangar."}}
D[9719] = {"El acechador acechado",{"Lleva el cerebro de la acechadora negra a Khn'nix en Esporaggar en la Marisma de Zangar."}}
D[9720] = {"Restaurar el equilibrio",{"Ysiel Vientocantor quiere que utilices las semillas de Parraférrea en los controles de las bombas de vapor en el Lago Serpiente, el Lago Umbropantano, el Lago Luz Pantanosa y La Laguna. A continuación vuelve a verla al Refugio Cenarion en la Marisma de Zangar y llévale las sobras que tengas."}}
D[9721] = {"Lord Solanar te convoca",{"Habla con Lord Solanar Sangre Colérica en la Ciudad de Lunargenta."}}
D[9722] = {"El camino del maestro",{"Habla con Lord Solanar Sangre Colérica y acepta su ofrecimiento de patrocinio."}}
D[9723] = {"Un gesto de entrega",{"Lleva 40 paños rúnicos, 6 barras de arcanita, 10 soleas, 5 runas oscuras y 150 piezas de oro a Lord Solanar Sangre Colérica en la Ciudad de Lunargenta."}}
D[9724] = {"Aviso al Círculo Cenarion",{"Habla con Amythel Caminaniebla en el Puesto Cenarion, en la Península del Fuego Infernal."}}
D[9725] = {"Una demostración de lealtad",{"Lord Solanar Sangre Colérica en la Ciudad de Lunargenta quiere que destruyas 3 carros de carne de la Plaga y mates a 15 ingenieros de asedio de la Plaga."}}
D[9726] = {"Ahora que somos amigos...",{"Mata a 12 explotadores Escamas de Sangre y a 6 encantadoras Escamas de Sangre, y vuelve junto a Gzhun'tt en Esporaggar, en la Marisma de Zangar."}}
D[9727] = {"Ahora que aún somos amigos...",{"Mata a 12 explotadores Escamas de Sangre y a 6 encantadoras Escamas de Sangre, y vuelve junto a Gzhun'tt en Esporaggar, en la Marisma de Zangar."}}
D[9728] = {"Una cálida bienvenida",{"El celador Hamoot del Refugio Cenarion quiere que le lleves 30 garras de naga."}}
D[9729] = {"¡Fhwoor da el golpe!",{"Escolta a Fhwoor hasta la zona de la bomba de vapor de la Luz Pantanosa para recuperar el Arca de Ssslith. Asegúrate de que Fhwoor y el arca vuelven sin peligro e informa a Gzhun'tt en Esporaggar, en la Marisma de Zangar."}}
D[9730] = {"El líder de los Cumbre Oscura",{"Mata al rajá Brujobruma en La Laguna y regresa junto al celador Hamoot de la Expedición Cenarion, en la Marisma de Zangar, por tu recompensa."}}
D[9731] = {"Planos de conducto",{"Busca en el fondo del Lago Serpiente signos de un conducto. Regresa junto a Ysiel Vientocantor en el Refugio Cenarion con las noticias de lo que descubras."}}
D[9732] = {"Regreso a la marisma",{"Regresa junto a Ysiel Vientocantor en el Refugio Cenarion, en la Marisma de Zangar."}}
D[9733] = {"Advertir al Círculo Cenarion",{"Habla con Mahuram Pezuñarrecia en Thrallmar, en la Península del Fuego Infernal."}}
D[9734] = {"Retorno a la marisma",{"Ve a ver a Ysiel Vientocantor al Refugio Cenarion en la Marisma de Zangar."}}
D[9735] = {"Verdaderos maestros de la Luz",{"Lord Solanar Sangre Colérica, en la Ciudad de Lunargenta, quiere le lleves 1 vial de agua sagrada de la Mano de Tyr."}}
D[9736] = {"Verdaderos maestros de la Luz",{"Lord Solanar Sangre Colérica de Ciudad de Lunargenta quiere que le lleves 1 catalizador arcano, 1 partículas Crepusculares, 1 diamante de Azeroth y 1 diamante negro prístino."}}
D[9737] = {"Verdaderos maestros de la Luz",{"Utiliza la mezcla de extinción cerca de la llama eterna de la Capilla de Alonsus para eliminar la protección de la Luz. Prepárate para luchar contra cualquiera que pretenda defender la capilla."}}
D[9738] = {"Desaparecidos en combate",{"Averigua qué le ha ocurrido al vinculador terrestre Rayge, al naturalista Mordisco, al desherbador Pulgarverde y al clamavientos Zarpa. Después, vuelve junto al vigía Jhang en la Reserva Colmillo Torcido, en la Marisma de Zangar."}}
D[9739] = {"La aflicción de los esporinos",{"Fahssn, de La Cañada Emergente, quiere que reúnas 10 bolsas de esporas maduras."}}
D[9740] = {"El portal solar",{"El vindicador Aesom de la Avanzada de Sangre quiere que destruyas el portal solar."}}
D[9741] = {"Alimañas del vacío",{"Mata 12 alimañas del vacío e informa luego al vindicador Aesom en la Avanzada de Sangre."}}
D[9742] = {"Más bolsas de esporas"}
D[9743] = {"Enemigos naturales",{"Fahssn, de La Cañada Emergente en la Marisma de Zangar, quiere que le lleves 6 zarcillos de señor de la marisma."}}
D[9744] = {"¡Más zarcillos!"}
