D[9747] = {"La tribu Umbropantano",{"Ikeyen del Refugio Cenarion quiere que vayas a la Aldea Umbropantano y mates a Kataru, 8 videntes de Umbropantano, 6 médicos brujos de Umbropantano y 6 oráculos de Umbropantano."}}
D[9748] = {"Agua que no has de beber...",{"El vindicador Aesom de la Avanzada de Sangre quiere que uses el frasco para recoger una muestra de agua de Bruma de Sangre."}}
D[9749] = {"¡Viven! A lo mejor...",{"El investigador Cornelius ha pedido que liberes 5 investigadores de la expedición."}}
