D[9776] = {"El Puerto Orebor",{"Habla con Ikuti en el Puerto Orebor."}}
D[9777] = {"Esporas refulgentes",{"Lleva 6 esporas refulgentes a Ruam en Telredor."}}
D[9778] = {"El celador Hamoot",{"Informa al celador Hamoot en el Refugio Cenarion, en la Marisma de Zangar."}}
