D[9793] = {"El destino de Tuurem",{"Lleva la carta del vindicador Idaar a Andarl en el Bastión Allerian, en el Bosque de Terokkar."}}
D[9794] = {"No hay tiempo para la curiosidad",{"Lleva la carta de Timothy a Kialon en Sylvanaar, en las Montañas Filospada."}}
D[9795] = {"La amenaza de los ogros",{"Ve al Bastión Señor del Trueno en las Montañas Filospada y habla con Nekthar."}}
D[9796] = {"Noticias de la Marisma de Zangar",{"Habla con Mokasa en el Bastión Rompepedras, en el Bosque de Terokkar."}}
D[9797] = {"Refuerzos para Garadar",{"Habla con el capitán Kroghan en Garadar, en Nagrand."}}
D[9798] = {"Planes de los elfos de sangre",{"Lleva los planes de los elfos de sangre al vindicador Aldar en el Lugar del Accidente, en el Valle Ammen."}}
D[9799] = {"Trabajo de campo",{"Recolecta 3 flores corruptas y llévaselas a la aprendiza Vishael a Lugar del Accidente, en Valle Ammen."}}
D[9800] = {"Una extraña judía",{"El elementalista Lo'ap en El Trono de los Elementos, en Nagrand, quiere que le consigas 15 anacardos digeridos."}}
D[9801] = {"Recogiendo componentes",{"El anacoreta Ahuurn de Telredor quiere que le lleves 4 ojos de esporiélago y 4 tentáculos de zancudo pantanoso."}}
D[9802] = {"Plantas de Marisma de Zangar",{"Lleva 10 partes de plantas sin identificar a Lauranna Thar'well al Refugio Cenarion en Marisma de Zangar."}}
D[9803] = {"Mensajero de los Feropantanos",{"Bebe el elixir de Ahuurn cuando estés en las Ruinas Boha'mu. Habla con el ancestro Kuruti cuando hayas adoptado la forma de un arakkoa."}}
D[9804] = {"Espíritus agitados de Sol Celeste",{"El elementalista Lo'ap en El Trono de los Elementos, en Nagrand, quiere que destruyas 12 espíritus del lago."}}
D[9805] = {"Bendición de Incineratus",{"El elementalista Lo'ap en El Trono de los Elementos, en Nagrand, quiere que destruyas la Cabaña Grande, la Cabaña del Oeste, la Cabaña del Sur y la Cabaña del Este en la Aldea Junco Alabeado","","Devuelve el fuego viviente al elementalista Lo'ap cuando hayas completado tu tarea."}}
D[9806] = {"Esporas fértiles",{"Gshaff quiere que reúnas 6 esporas fértiles entre los esporiélagos y los caminantes de marismas de la Marisma de Zangar. Vuelve a ver a Ghsaff en Esporaggar cuando hayas completado la tarea."}}
D[9807] = {"Más esporas"}
D[9808] = {"Fluochampiñones",{"Lleva 10 fluochampiñones a Msshi'fn a Esporaggar en Marisma de Zangar."}}
D[9809] = {"Más fluochampiñones"}
D[9810] = {"El espíritu contaminado",{"El elementalista Lo'ap en El Trono de los Elementos, en Nagrand, quiere que destruyas la esencia contaminada de Watoosun y 10 mareas del lago."}}
D[9811] = {"Amigos de los sin'dorei",{"Lleva la cabeza de Dar'Khan a Lor'themar Theron a Ciudad de Lunargenta."}}
D[9812] = {"Enviado de la Horda",{"Lleva la carta de Lor'themar Theron a Lady Sylvanas Brisaveloz en Entrañas, la capital de los Renegados, en los Claros de Tirisfal."}}
D[9813] = {"Encuentro con el Jefe de Guerra",{"Lady Sylvanas Brisaveloz quiere que lleves la carta sellada por Sylvanas a Thrall en Orgrimmar, capital de Durotar."}}
D[9814] = {"¡Champiñones fulminantes, colega!",{"Lleva al médico brujo Tor'gash 6 champiñones fulminantes."}}
D[9815] = {"Bucear en lodo",{"El elementalista Lo'ap en El Trono de los Elementos, en Nagrand, quiere que consigas 5 núcleos de lodo."}}
D[9816] = {"Mascotas adorables",{"Coloca la jaula de múrlocs en la piedra plana cerca de la Aldea Dagapantano."}}
D[9817] = {"Líder de los Escamas de Sangre",{"Mata a Rajis Fyashe en el Lago Serpiente y ve a ver al celador Hamoot en el Refugio Cenarion, en la Marisma de Zangar para obtener la recompensa."}}
D[9818] = {"Bajo la tierra",{"Comunícate con Gordawg."}}
D[9819] = {"La tierra torturada",{"Gordawg de El Trono de los Elementos en Nagrand ha pedido que destruyas a 15 espíritus de tierra torturados."}}
D[9820] = {"SE BUSCA: jefe Grog'ak",{"Lleva la cabeza del jefe Grog'ak al cazador de las Sombras Denjai en Zabra'jin."}}
D[9821] = {"Comiendo condenación",{"Gordawg en El Trono de los Elementos, en Nagrand, te ha pedido que le lleves 15 núcleos de trituradores iracundos."}}
D[9822] = {"Ataque inminente",{"Lleva los planes de ataque de Ango'rosh al cazador de las Sombras Denjai en Zabra'jin."}}
D[9823] = {"Nosotros o ellos",{"Mata al Señor Supremo Puño Sajante, 10 aplastadores Ango'rosh y 10 devoralmas Ango'rosh y preséntate ante el cazador de las Sombras Denjai en Zabra'jin."}}
D[9824] = {"Alteraciones arcanas",{"Utiliza el cristal de visión violeta cerca de fuentes subterráneas de agua en El Sótano del Maestro y vuelve a ver al archimago Alturus en las afueras de Karazhan."}}
D[9825] = {"Actividad incansable",{"Lleva 10 esencias fantasmales al archimago Alturus en las afueras de Karazhan."}}
D[9826] = {"Contacto de Dalaran",{"Lleva el informe de Alturus al archimago Cedric en la afueras de Dalaran."}}
D[9827] = {"Basidio marchito",{"Lleva el basidio marchito a Ruam en Telredor."}}
D[9828] = {"Basidio marchito",{"Lleva el basidio marchito a Reavij en la Avanzada Rata del Pantano."}}
D[9829] = {"Khadgar",{"Lleva el informe de Alturus a Khadgar en la Ciudad de Shattrath, en el Bosque de Terokkar."}}
D[9830] = {"Veneno letal",{"Lleva 6 unidades de veneno de sangrador Luz pantanosa a Puluu en el Puerto Orebor."}}
D[9831] = {"La entrada a Karazhan",{"Khadgar quiere que entres en el Laberinto de las Sombras en Auchindoun y recuperes el primer trozo de la llave de un contenedor arcano que está escondido allí."}}
D[9832] = {"El segundo y tercer trozo",{"Consigue el segundo trozo de la llave, que está en un contenedor arcano en la Reserva Colmillo Torcido, y el tercer trozo de la llave, que está en otro contenedor arcano en El Castillo de la Tempestad. Vuelve a ver a Khadgar en la Ciudad de Shattrath cuando lo hayas hecho."}}
D[9833] = {"Líneas de comunicación",{"Puluu, en el Puerto Orebor quiere que mates 12 cercenadores Colmillo de la marisma."}}
D[9834] = {"Armadura natural",{"Lleva 8 pellejos de Zarpacieno a Maktu en el Puerto Orebor."}}
D[9835] = {"Invasión de los Ango'rosh",{"Mata 10 ogros Ango'rosh y 5 chamanes Ango'rosh. Después vuelve a ver a Ikuti en el Puerto Orebor."}}
