D[9845] = {"Competición de pesca",{"Mata 10 vándalos Zarpacieno y vuelve a ver a Zurjaya en Zabra'jin."}}
D[9846] = {"Espíritus de los Feropantanos",{"Entrega 10 tótems de protección Feropantano al vidente Janidi en Zabra'jin."}}
D[9847] = {"¿Un espíritu aliado?",{"Lleva el Tótem Feropantano hasta el pie de las escaleras de las Ruinas Boha'mu y colócalo en el suelo. Informa sobre tus descubrimientos al vidente Janidi en Zabra'jin."}}
