D[9849] = {"Rompiendo el velo",{"Gordawg de El Trono de los Elementos en Nagrand te ha pedido que mates a 30 esbirros de Gurok."}}
D[9850] = {"Cacería de uñagrietas",{"Mata a 30 uñagrietas dominantes y ve a hablar con Hemet Nesingwary en el Safari Nesingwary, en Nagrand, sobre tu progreso."}}
D[9851] = {"Cacería de uñagrietas",{"Consigue el cuerno de Banthar y llévaselo a Hemet Nesingwary en el Safari Nesingwary, en Nagrand."}}
