D[9854] = {"Cacería de vientorrocs",{"Mata 30 vientorrocs y después vuelve a ver a Fitz en el Safari Nesingwary de Nagrand."}}
D[9855] = {"Cacería de vientorrocs",{"Caza 30 vientorrocs voraces y regresa entonces junto a Fitz en el Safari Nesingwary de Nagrand."}}
