D[9885] = {"Beneficios de los miembros"}
D[9886] = {"Beneficios de los miembros"}
D[9887] = {"Beneficios de los miembros",{"The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services","","The quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us."}}
D[9888] = {"El líder impotente",{"Jorin Mortojo te ha pedido que encuentres a Kilrath."}}
D[9889] = {"No mates al gordo",{"Kilrath en el Bosque de Terokkar te ha pedido que mates a 10 invasores Puño de Roca y golpees a Unkor el Despiadado hasta hacerle hablar."}}
D[9890] = {"¡Éxito!",{"Ve al Bosque de Terokkar y cuéntale a Kilrath lo que le has hecho a Unkor."}}
D[9891] = {"Porque Kilrath es un cobarde",{"Ve a Garadar, en Nagrand, y cuéntale a Jorin Mortojo que has vencido a Unkor."}}
D[9892] = {"Más abalorios de guerra de obsidiana",{"¿Has conseguido más abalorios de guerra? Encontrarás muchos ogros al norte, cerca de la frontera con la Marisma de Zangar."}}
