D[9989] = {"Espíritus extraños",{"Lleva 30 plumas de arakkoa a Malukaz en el Bastión Rompepedras."}}
D[9990] = {"Investigación de Tuurem",{"Encuentra la caja sellada y entrégasela al vinculador terrestre Tavgren justo fuera del Matorral Cenarion en el Bosque de Terokkar."}}
D[9991] = {"Inspeccionar la tierra",{"Siéntate y disfruta del paseo. Habla con Altruis cuando hayas terminado la inspección."}}
D[9992] = {"Semillas de olemba",{"Consigue 30 semillas de olemba y llévaselas a Ros'eleth en el Bastión Allerian."}}
D[9993] = {"Aceite de semilla de olemba",{"Lleva 30 semillas de olemba a Rakoria, en el Bastión Rompepedras."}}
D[9994] = {"¿Qué son estas cosas?",{"Lleva la caja de piezas a Jenai Susurrestelar en el Bastión Allerian, en el Bosque de Terokkar."}}
D[9995] = {"¿Qué son estas cosas?",{"Lleva la caja de piezas a Tooki en el Bastión Rompepedras, en el Bosque de Terokkar."}}
D[9996] = {"Ataque en el Alto Ala de Fuego",{"Mata a 10 defensores Ala de Fuego, 10 depositarios de sangre Ala de Fuego y 10 brujos Ala de Fuego. Después, informa al teniente Meridiano en el Puesto Allerian del Bosque de Terokkar."}}
D[9997] = {"Ataque en el Alto Ala de Fuego",{"Mata a 10 defensores Ala de Fuego, 10 depositarios de sangre Ala de Fuego y 10 brujos Ala de Fuego. Después, informa al sargento Chawni en el Campamento Rompepedras del Bosque de Terokkar."}}
D[9998] = {"Vecinos indisciplinados",{"Mata a 12 peones distorsionados e informa a Theloria Capasombría del Puesto Allerian."}}
D[9999] = {"Tiempo extra",{"Altruis el Sufridor, al oeste de Nagrand, te ha pedido que mates a 2 legionarios guardia vil, 3 ingenieros Mo'arg y 8 manitas Gan'arg."}}
D[10000] = {"Una presencia inoportuna",{"Mata 12 peones distorsionados y después preséntate ante el acechasombras Kaide."}}
D[10001] = {"El maestro planificador",{"Altruis el Sufridor, en la parte oeste de Nagrand te ha pedido que consigas los planos del maestro planificador."}}
D[10002] = {"El contacto Ala de Fuego",{"Localiza y mata a Lisaile Tejefuego y, a continuación, vuelve a ver a Theloria Capasombría."}}
D[10003] = {"El contacto Ala de Fuego",{"Localiza y mata a Lisaile Tejefuego y, a continuación, vuelve a ver al acechasombras Kaide."}}
D[10004] = {"Paciencia y comprensión",{"Altruis el Sufridor, en el oeste de Nagrand, quiere que lleves los planos del maestro planificador a Sal'salabim en la Ciudad de Shattrath y convéncele para que te ayude."}}
D[10005] = {"Informar al vinculador terrestre Tavgren",{"Habla con el vinculador terrestre Tavgren justo fuera del Matorral Cenarion, en el Bosque de Terokkar."}}
D[10006] = {"Informar al vinculador terrestre Tavgren",{"Habla con el vinculador terrestre Tavgren justo fuera del Matorral Cenarion, en el Bosque de Terokkar."}}
D[10007] = {"Disminuir las filas",{"Mata 10 devastadores Mascahuesos y 6 partedorsales Mascahuesos y ve a ver a Theloria Capasombría."}}
D[10008] = {"Lo que pasa en Terokkar, se queda en Terokkar",{"El acechasombras Kaide quiere que mates a 10 arrasadores Mascahuesos y 6 partedorsales Mascahuesos."}}
D[10009] = {"Aplastar unas calaveras",{"Sal'salabim de la Ciudad de Shattrath quiere que recuperes la deuda de Raliq, la deuda de Coosh'coosh y la deuda de Floon."}}
D[10010] = {"¿Es así de fácil?",{"Sal'salabim en la Ciudad de Shattrath quiere que vayas a ver a Altruis el Sufridor en la parte oeste de Nagrand."}}
D[10011] = {"Campamento Forja: aniquilado",{"Altruis el Sufridor, al oeste de Nagrand, te ha pedido que destruyas el Campamento Forja: Odio y el Campamento Forja: Miedo."}}
D[10012] = {"Planes de orcos viles",{"Lleva los planes de los orcos viles a Bertelm en el Bastión Allerian."}}
D[10013] = {"Una mano invisible",{"Lleva los planes de orcos viles a Rokag en el Bastión Rompepedras."}}
D[10014] = {"El proyecto del Alto Ala de Fuego",{"Roba cuatro hojas de código de bomba de maná y entrégaselas al teniente Meridiano en la Puesto Allerian del Bosque de Terokkar."}}
D[10015] = {"El proyecto del Alto Ala de Fuego",{"Roba cuatro hojas de código de bomba de maná y entrégaselas al sargento Chawni en el Campamento Rompepedras del Bosque de Terokkar."}}
