D[10027] = {"Alteraciones mágicas",{"Mata 10 acechadores de distorsión y vuelve a ver a Kurgatok en el Bastión Rompepedras."}}
D[10028] = {"Vasijas de poder",{"Lleva 8 vasijas draenei a Ros'eleth en el Bastión Allerian."}}
D[10029] = {"Los espíritus llaman",{"La anacoreta Lyteera quiere que encuentres a su asistente, Soolaveen, en la Caravana de Refugiados de El Vertedero de Huesos en el Bosque de Terokkar","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10030] = {"Recuperar los huesos",{"Consigue 10 huesos de Sin Sosiego y llévaselos a Ramdor el Loco, del lado oeste del Círculo de la Observancia de Auchindoun, en medio de El Vertedero de Huesos, en el Bosque de Terokkar."}}
D[10031] = {"Ayudando a Los Perdidos a encontrar su camino",{"Destruye 10 espíritus perdidos y 10 esqueletos partidos y ve a ver a Soolaveen en la Caravana de Refugiados de El Vertedero de Huesos, en el Bosque de Terokkar."}}
D[10033] = {"Se busca: Atizahuesos. Muertos.",{"Mata 20 Atizahuesos y después preséntate ante Taela Semprerguida en el Bastión Allerian, en el Bosque de Terokkar."}}
D[10034] = {"Se busca: Atizahuesos. Muertos.",{"Mata 20 Atizahuesos y, a continuación, ve a ver a Mawg Tirosiniestro en el Bastión Rompepedras, en el Bosque de Terokkar."}}
D[10035] = {"¡Torgos!",{"Llama a Torgos con el cadáver de Trachela. Consigue una pluma de la cola de Torgos y llévasela a Taela Semprerguida en el Bastión Allerian, en el Bosque de Terokkar."}}
D[10036] = {"¡Torgos!",{"Invoca a Torgos con el cadáver de Trachela. Consigue una pluma de la cola de Torgos y vuelve a ver a Mawg Tirosiniestro en el Bastión Rompepedras del Bosque de Terokkar."}}
