D[10046] = {"A través de El Portal Oscuro",{"Viaja a través de El Portal Oscuro y habla con Nazgrel en Thrallmar."}}
D[10047] = {"El Camino a la Gloria",{"Purifica 8 esqueletos pisoteados en El Camino a la Gloria con agua sagrada draenei y vuelve a ver al arúspice de distorsión Kryv en el Bastión del Honor."}}
D[10048] = {"Un puñado de polvo mágico",{"Reúne 7 puñados de polvo pacificador para Andarl en el Bastión Allerian."}}
D[10049] = {"Un puñado de polvo mágico",{"Reúne 7 puñados de polvo pacificador para Kurgatok en el Bastión Rompepedras."}}
