D[10406] = {"Entregar el mensaje",{"La imagen del comandante Ameer, en el Punto de Escala de El Etereum: Transpondedor de El Etereum Zeta, quiere que escoltes al demoledor de protectorado a Forja de Maná Ultris y lo cubras mientras sabotea las tuberías."}}
D[10407] = {"La sombra de Socrethar",{"La Anacoreta Karja del Área 52 quiere que recuperes la primera mitad de la piedra de Socrethar del maestro de forja Morug en la Base Forja: Olvido y la segunda mitad de la piedra de Socrethar de Silroth en la Base Forja: Gehenna","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10408] = {"El rey-nexo Salhadaar",{"La imagen del comandante Ameer, en el Punto de Escala Etereum: Transpondedor de etereum zeta, quiere que uses el perturbador de Protectorado para neutralizar los campos de fuerza de Salhadaar y destruir después al rey-nexo Salhadaar."}}
D[10409] = {"Golpe mortal a la Legión",{"La suma sacerdotisa Ishanah quiere que vayas al teletransportador de la Legión del extremo noroeste de Tormenta Abisal y lo uses para teletransportarte al Trono de Socrethar. Una vez allí, derrota a Socrethar","","A medida que completas tareas para los Aldor disminuye tu nivel de reputación con los Arúspices."}}
D[10410] = {"La ayuda de Ishanah",{"Llévale la piedra de teletransporte de Socrethar a la suma sacerdotisa Ishanah del Santuario de Luz Inagotable, en el Alto Aldor de la Ciudad de Shattrath","","A medida que completas tareas para los Aldor disminuye tu nivel de reputación con los Arúspices."}}
D[10411] = {"¡Divino electrochoque!",{"El investigador Navuud, de la Avanzada del Protectorado en la Tormenta Abisal, ha pedido que destruyas 30 glóbulos de residuo del vacío y 30 glóbulos de lodo acuoso."}}
