D[10701] = {"Infiltrarse en la Roca Abisal",{"Mata a Roca Abisal y preséntate después al jefe de cohetes Fuselaje del Área 52, en la Tormenta Abisal."}}
D[10702] = {"Un trabajo ingrato...",{"El Señor Supremo Or'barokh de la Aldea Sombraluna, en el Valle Sombraluna, quiere que mates a 20 ejemplares de la fauna y flora del Valle Sombraluna","","Entre estas criaturas encontrarás el jabalí vil, la quimera Alavil y el tenazario de caparazón agostado. Cualquier combinación valdrá."}}
D[10703] = {"Ponte las rodilleras...",{"El Señor feudal Yoregar en el Bastión Martillo Salvaje, en el Valle Sombraluna, quiere que mates 20 animales del Valle Sombraluna","","Tiene que haber algún jabalí vil, quimera Alavil y tenazario caparazón quemado. Cualquier combinación será correcta."}}
D[10704] = {"Cómo infiltrarse en El Arcatraz",{"A'dal te ha encargado que recuperes los fragmentos inferior y superior de la llave de Arcatraz. Devuélveselos y con ellos recreará la llave de El Arcatraz para ti."}}
D[10705] = {"El vidente Udalo",{"Encuentra al vidente Udalo en el interior de El Arcatraz, en El Castillo de la Tempestad."}}
D[10706] = {"Un misterioso portento",{"Regresa junto a Akama en la Jaula de la Guardiana, en el Valle Sombraluna."}}
D[10707] = {"El bancal de Ata'mal",{"Sube a lo más alto del Bancal de Ata'mal en el Valle Sombraluna y consigue el corazón de furia. Regresa junto a Akama, a Jaula de la Guardiana en el Valle Sombraluna cuando completes la misión."}}
D[10708] = {"La promesa de Akama",{"Llévale el medallón de Karabor a A'dal en la Ciudad de Shattrath."}}
D[10709] = {"Reunión",{"Vuelve a ver a Rexxar en el Bastión Señor del Trueno, en las Montañas Filospada."}}
D[10710] = {"Vuelo de prueba: La Cresta Canto",{"Firma la renuncia de Tally y, después, habla con Rally Pillazas para usar el Cefirium Capacitorium."}}
D[10711] = {"Vuelo de prueba: Zona de Aterrizaje Razaan",{"Habla con Rally Pillazas para usar el Cefirium Capacitorium."}}
D[10712] = {"Vuelo de prueba: La Foresta Ruuan",{"Habla con Rally Pillazas para usar el Cefirium Capacitorium. Mientras vuelas a la Foresta Ruuan, gira la veleta abisal. Entrega la veleta giratoria abisal a O'Mally Pillazas en Soto Eterno."}}
D[10713] = {"...y tiempos de acción",{"Adéntrate en la Foresta de Ruuan y mata a 10 taladores del culto vermis y luego regresa junto al depositario de árboles Chawn en Soto Eterno en las Montañas Filospada."}}
D[10714] = {"Las alas de Espíritu",{"Busca a un capataz Machacasangre y a un veritas Machacasangre que estén hablando. Después utiliza el silbato de Rexxar para invocar a Espíritu para que los espíe. Cuando lo hayas hecho, vuelve a ver a Rexxar en la Aldea Señor del Trueno, en las Montañas Filospada."}}
D[10715] = {"En el interior de la Garganta Bulliciosa",{"El Barón Sablecrín te ha dicho que, para hacer el veneno que Rexxar necesita, debes conseguir 7 glándulas de tósigo de revientacortezas. Ve a verle al Anillo de Sangre, en las Montañas Filospada cuando lo hayas hecho."}}
D[10716] = {"Vuelo de prueba: El Bosque del Cuervo <needs reward>",{"Habla con Rally Pillazas para usar el Cefirium Capacitorium. Regresa junto a Tally Pillazas en la Estación de Toshley."}}
D[10717] = {"Robar a un ladrón",{"Samia Pálpito ha pedido que consigas 5 redes del culto vermis y se las lleves a Soto Eterno en las Montañas Filospada."}}
D[10718] = {"Los espíritus tienen voces",{"Garm Hermanolobo te ha dicho donde están los Mok'Nathal, el pueblo de Rexxar. Cuéntaselo a Rexxar en el Bastión Señor del Trueno, en las Montañas Filospada."}}
D[10719] = {"¿Has conseguido la nota?",{"Entrega la nota de cita al depositario de árboles Chawn en Soto Eterno en las Montañas Filospada."}}
D[10720] = {"Las criaturas más pequeñas",{"Utiliza el tambor de pellejo de kodo en la madriguera de marmotas. Cuando estés controlando a la marmota, envenena los tres barriles del Campamento Machacasangre. Cuando lo hayas hecho, ve a ver a Rexxar en el Bastión Señor del Trueno en las Montañas Filospada."}}
D[10721] = {"Un jabalí para Grulloc",{"Consigue el saco de Grulloc y llévaselo al Barón Sablecrín en el Anillo de Sangre, en las Montañas Filospada."}}
D[10722] = {"Encuentro en el Aquelarre Alanegra",{"Recolecta suficientes retales de los trajes de varios fieles del culto vermis para crear un disfraz de sobrestante. Usa el disfraz para asistir a la reunión con Kolphis Escamaoscura y vuelve a Soto Eterno en las Montañas Filospada a informar de lo que averigües al depositario de árboles Chawn."}}
D[10723] = {"Gorgrom el Comedragones",{"Ve a Peña'mok y coge 3 Tótems repelentes de los ogros Peña'mok. Utiliza la trampa de Sablecrín en el altar de Gorgrom para colocar la trampa, invocar y matar a Gorgrom el Comedragones","","Cuando Gorgrom esté muerto, coloca los 3 Tótems repelentes cerca de su cadáver y después vuelve a ver a Rexxar en el Bastión Señor del Trueno, en las Montañas Filospada."}}
D[10724] = {"Prisionero de los Aguja del Filo",{"Mata a ogros Aguja del Filo para conseguir la llave de la jaula del dracoleón. Cuando la tengas, ve a la jaula y utiliza el silbato de Espíritu para invocar a Espíritu, que abrirá la jaula. Cuando Leokk haya sido liberado, vuelve a ver a Rexxar en la Aldea Señor del Trueno, en las Montañas Filospada."}}
D[10725] = {"Eminencia ante El Ojo Violeta",{"Entrega tu sello Violeta a la archimaga Leryda en el Paso de la Muerte tras obtener reputación exaltada con El Ojo Violeta."}}
D[10726] = {"Eminencia ante El Ojo Violeta",{"Entrega tu sello Violeta a la archimaga Leryda en el Paso de la Muerte tras obtener reputación exaltada con El Ojo Violeta."}}
D[10727] = {"Eminencia ante El Ojo Violeta",{"Entrega tu sello Violeta a la archimaga Leryda en el Paso de la Muerte tras obtener reputación exaltada con El Ojo Violeta."}}
D[10728] = {"Eminencia ante El Ojo Violeta",{"Entrega tu sello Violeta a la archimaga Leryda en el Paso de la Muerte tras obtener reputación exaltada con El Ojo Violeta."}}
