D[11104] = {"Ya no es restaurador"}
D[11105] = {"Ya no es Campeón"}
D[11106] = {"Ya no es defensor"}
D[11107] = {"Inclínate ante el Alto Señor",{"Habla con el señor supremo Mor'ghor en el Campamento Faucedraco en el Valle Sombraluna."}}
