D[11386] = {"SE BUSCA: el proyector de Pathaleon",{"El comerciante de viento Zhareem te ha pedido que consigas el proyector de Pathaleon. Llévaselo al Bajo Arrabal de la Ciudad de Shattrath para conseguir la recompensa","","Esta misión solo se puede realizar en dificultad heroica."}}
D[11387] = {"SE BUSCA: destructores de Forja de Tempestad",{"El acechador abisal Mah'duun te ha pedido que mates 5 destructores de Forja de Tempestad. Vuelve a verle al Bajo Arrabal de Shattrath cuando estén todos muertos para cobrar la recompensa."}}
D[11388] = {"SE BUSCA: el pergamino de Cieloriss",{"El comerciante de viento Zhareem te ha pedido que consigas el pergamino de Cieloriss. Llévaselo al Bajo Arrabal de la Ciudad de Shattrath para conseguir la recompensa","","Esta misión solo se puede realizar en dificultad heroica."}}
D[11389] = {"SE BUSCA: centinelas de Arcatraz",{"El acechador abisal Mah'duun te ha pedido que mates a 5 centinelas de Arcatraz. Vuelve a verle al Bajo Arrabal de Shattrath cuando estén todos muertos para cobrar la recompensa."}}
D[11392] = {"Invoca al Jinete decapitado",{"Lleva una vela lóbrega a la tierra ligeramente revuelta."}}
D[11400] = {"Carneros de montar de la Fiesta de la cerveza",{"Enseña el sello de \"Cervecero Honorario\" a Pol Semperámbar, que se encuentra cerca de la entrada a la zona de la Fiesta de la cerveza en Dun Morogh."}}
D[11401] = {"Invoca a El Jinete decapitado",{"Lleva una vela lóbrega a la tierra ligeramente revuelta."}}
D[11403] = {"¡Por fin libre!",{"Lleva el Escrito de Thomas Thomson a una supervisora de huérfanos enmascarada a Durotar, Rémol o Plaza Alalcón."}}
D[11404] = {"Invoca al Jinete decapitado",{"Lleva una vela lóbrega a la tierra ligeramente revuelta."}}
D[11405] = {"Invoca al Jinete decapitado",{"Lleva una vela lóbrega a la tierra ligeramente revuelta."}}
D[11407] = {"¡Grita por la destilería de Drohn!",{"Informa sobre la Fiesta de la Cerveza en las banderas fuera de la casa de subastas, en el Valle de la Fuerza, el Valle del Honor, el Valle de la Sabiduría y el Valle de los Espíritus."}}
D[11408] = {"¡Grita por la Cervecería vudú de T'chali!",{"Informa sobre la Fiesta de la Cerveza en las banderas fuera de la casa de subastas, en el Valle de la Fuerza, el Valle del Honor, el Valle de la Sabiduría y el Valle de los Espíritus."}}
D[11409] = {"Carrera de carneros... o algo parecido",{"Tienes 4 minutos para montar el carnero y mantener 3 niveles de velocidad diferentes durante 8 segundos."}}
D[11412] = {"Historia de una ida y una vuelta",{"Coge el barril del goblin que se ha quedado tirado en el camino a la Bahía de Garrafilada y llévaselo al asistente del maestro de carneros Rayo. Si pierdes a tu carnero, pídele otro al maestro de carneros Rayo."}}
D[11413] = {"¿Alguien dijo \"souvenir?\"",{"Entrega el vale de jarra de la Fiesta de la Cerveza a Blix Chirimbolo en la parte trasera del campamento de la Fiesta de la Cerveza."}}
D[11419] = {"Carneros de montar de la Fiesta de la cerveza",{"Enseña el sello de \"Cervecero Honorario\" a Driz Pataplaf, que se encuentra cerca de la entrada a la zona de la Fiesta de la cerveza en Durotar."}}
D[11425] = {"Test Quest - Craig",{"Vermin, gotta hate 'em."}}
D[11431] = {"¡Atrapa al wolpertinger salvaje!",{"El \"enano\" Glodrak Guasa te ha pedido que captures 5 wolpertingers aturdidos usando la red de wolpertinger. Ha mencionado que tienes que estar borracho para verlos."}}
D[11439] = {"Prácticas para bomberos",{"Echa cubos de agua en 5 fuegos y después vuelve para hablar con la matrona de huérfanos disfrazada."}}
D[11440] = {"Prácticas para bomberos",{"Echa cubos de agua en 5 fuegos y después vuelve para hablar con la matrona de huérfanos disfrazada."}}
