D[11447] = {"¡Bienvenido a la Fiesta de la Cerveza!",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11449] = {"Entrenamiento de bomberos",{"Echa cubos de agua en 5 hogueras y ve a hablar con la matrona de huérfanos enmascarada de Rémol."}}
D[11450] = {"Entrenamiento de bomberos",{"Echa cubos de agua en 5 hogueras y habla con la matrona de huérfanos enmascarada en Plaza Alalcón."}}
D[11451] = {"El poema de Alicia",{"Debes llevar el poema de Alicia a Caylee Dak en Ciudad de Shattrath, Terrallende."}}
D[11454] = {"Busca a los saboteadores",{"Encuentra a Coren Cerveza Temible en Tragapenas, dentro de las Profundidades de Roca Negra."}}
D[11481] = {"Crisis en La Fuente del Sol",{"Adyen el Celador de la Luz del Alto Aldor, en la Ciudad de Shattrath, te ha pedido que viajes hasta la Meseta de La Fuente del Sol para hablar con Larethor."}}
D[11482] = {"El deber llama",{"Dathris Golpesol de la Grada del Arúspice, en la Ciudad de Shattrath, ha insistido en que viajes a Azeroth inmediatamente y te presentes ante Larethor en La Fuente del Sol."}}
D[11486] = {"La mejor de las cervezas",{"Lleva el barril de cerveza Hierro Negro a Ipfelkofer Barril de Hierro en Dun Morogh."}}
D[11487] = {"La mejor de las cervezas",{"Lleva el barril de cerveza Hierro Negro a Espitador Barritimo en Durotar."}}
D[11488] = {"El Bancal del Magister",{"El exarca Larethor de la Zona de Escala de Sol Devastado quiere que registres el Bancal del Magister y encuentres a Tyrith, un espía elfo de sangre."}}
D[11490] = {"El cristal de adivinación del arúspice",{"Tyrith quiere que uses el orbe en el balcón del Bancal del Magister."}}
D[11492] = {"Duro de matar",{"Kalecgos te ha pedido que derrotes a Kael'thas en el Bancal del Magister. Coge la cabeza de Kael y preséntate ante Larethor en la Zona de Escala de Sol Devastado."}}
D[11496] = {"Los resguardos del sagrario",{"El capitán Theris Albahogar en la Zona de Escala de Sol Devastado quiere que consigas 4 despojos de maná de malignos desdichados y devoradores desdichados y que los uses como fuente de energía para alguno de los resguardos de cristal que rodean el Sagrario de Tramo del Sol al este."}}
D[11497] = {"Aprendiendo a volar",{"Habla con Ilsa Bravuconada en Bastión Martillo Salvaje en el Valle Sombraluna."}}
D[11498] = {"Aprendiendo a volar",{"Habla con Olrokk en la Aldea Sombraluna en el Valle Sombraluna."}}
D[11499] = {"SE BUSCA: el sello del príncipe Kael'thas",{"El comerciante de viento Zhareem te ha pedido que consigas el sello del príncipe Kael'thas. Llévaselo al Bajo Arrabal de la Ciudad de Shattrath para conseguir la recompensa","","Esta misión solo se puede realizar en el Bancal del Magister en dificultad heroica."}}
D[11500] = {"SE BUSCA: hermanas del Tormento",{"El acechador abisal Mah'duun te ha pedido que mates 4 Hermanas del Tormento. Vuelve a verle al Bajo Arrabal de Shattrath cuando estén todos muertos para cobrar la recompensa."}}
D[11502] = {"En defensa de Halaa",{"Derrota a 10 jugadores enemigos en Halaa y vuelve a ver a Lakoor en Telaar."}}
D[11503] = {"Enemigos, viejos y nuevos",{"Derrota a 10 jugadores enemigos en Halaa y vuelve a ver a Karrtog en Garadar."}}
D[11505] = {"Espíritus de Auchindoun",{"Ayuda a la Alianza a proteger una torre en El Vertedero de Huesos."}}
D[11506] = {"Espíritus de Auchindoun",{"Ayuda a la Horda a proteger una torre del Espíritu en El Vertedero de Huesos."}}
D[11513] = {"Interceptar las células de maná",{"Consigue 10 células de maná de contrabando y vuelve a ver al exarca Nasuun en el Bancal de la Luz, en la Ciudad de Shattrath."}}
D[11514] = {"Hay que mantener el Portal de La Fuente del Sol",{"Consigue 10 células de maná de contrabando y vuelve a ver al exarca Nasuun en el Bancal de la Luz, en la Ciudad de Shattrath."}}
D[11515] = {"Sangre por sangre",{"La magistrix Seyla en el Trono de Kil'jaeden quiere que mates 4 Sangrevil demacrados usando el sifón vil sobre ellos. Necesitarás sangre demoníaca de los Heraldos de cólera cercanos para propulsar el sifón vil."}}
D[11516] = {"Destroza el portal",{"La magistrix Seyla del Trono de Kil'jaeden quiere que uses las brasas muy calientes para invocar a una centella viva y asesinar chispas viles incandescentes cerca de ella hasta que se convierta en una centella viva inestable. Vuelve al portal de la Legión con la centella viva inestable para destruirlo."}}
D[11517] = {"Informa a Nasuun",{"El Proveedor Portanuus te ha pedido que hables con el exarca Nasuun en el Bancal de la Luz de la Ciudad de Shattrath."}}
D[11518] = {"Bandera diaria del portal de La Fuente del Sol"}
D[11520] = {"Descubriendo tus raíces",{"Mar'nah, en el Puerto de Tramo del Sol, quiere que viajes al Alto Rajaespina en Terrallende, recojas 5 raíces de Rajaespina y vuelvas junto a ella."}}
D[11521] = {"Redescubriendo tus raíces",{"Mar'nah, en el Puerto de Tramo del Sol, quiere que viajes al Alto Rajaespina en Terrallende, recojas 5 raíces de Rajaespina y vuelvas junto a ella."}}
D[11523] = {"¡Armad los resguardos!",{"El capitán Theris Albahogar de la Zona de Escala de Sol Devastado quiere que obtengas 4 restos de maná de devoradores desdichados y malignos desdichados y que los uses para energizar uno de los resguardos de cristal que rodean las estructuras del Tramo del Sol."}}
D[11524] = {"Comportamiento errático",{"La vindicadora Xayann de la Zona de Escala de Sol Devastado quiere que coloques núcleos de cristal armonizado dentro de 5 avizores erráticos derrotados para convertirlos en unidades amistosas."}}
D[11525] = {"Más transformaciones",{"La vindicadora Xayann de la Zona de Escala de Sol Devastado quiere que coloques núcleos de cristal armonizado dentro de 5 avizores erráticos derrotados para convertirlos en unidades amistosas."}}
D[11526] = {"La magistrix desaparecida",{"Usa el pergamino de la Legión capturado cerca del portal de La Plaza Crepuscular. Cuando hayas atravesado el portal, busca a la magistrix Seyla."}}
D[11528] = {"Un regalo del Festival de Invierno"}
D[11531] = {"La pieza de motor extraña",{"Lleva la pieza de motor extraña a K. Lee Fritito en Telredor."}}
D[11532] = {"Distracción en La Cicatriz Muerta",{"La maga de batalla Arynna quiere que hables con Ayren Rompenubes cuando estés <preparado/preparada> para volar a La Cicatriz Muerta. Una vez allí usa las cargas Arcanas para matar a 2 Señores Supremos del foso, 3 hechiceros eredar y 12 déspotas de cólera."}}
D[11533] = {"Los ataques aéreos deben continuar",{"La maga de batalla Arynna quiere que hables con Ayren Rompenubes cuando estés <preparado/preparada> para volar a La Cicatriz Muerta. Una vez allí usa las cargas Arcanas para matar a 2 Señores Supremos del foso, 3 hechiceros eredar y 12 déspotas de cólera."}}
D[11534] = {"Informa a Nasuun",{"El Proveedor Portanuus te ha pedido que hables con el exarca Nasuun en el Bancal de la Luz de la Ciudad de Shattrath."}}
D[11535] = {"Preparándose",{"La herrera Hauthaa, en el Arsenal de Tramo del Sol, quiere que mates mirmidones Espina Siniestra al este y que uses sus llaves para robar 3 menas de sus cofres."}}
D[11536] = {"No te pares ahora",{"La herrera Hauthaa, en el Arsenal de Tramo del Sol, quiere que mates mirmidones Espina Siniestra al este y que uses sus llaves para robar 3 menas de sus cofres."}}
D[11537] = {"La batalla debe continuar",{"El presagista Inuuro quiere que mates a 6 demonios de la Legión Ardiente y al emisario del Odio en La Plaza Crepuscular. Usa el estandarte de Sol Devastado para empalar el cadáver del emisario del Odio."}}
D[11538] = {"La batalla por el Arsenal de Tramo del Sol",{"El presagista Inuuro quiere que mates a 6 demonios de la Legión Ardiente y al emisario del Odio en La Plaza Crepuscular o en el Arsenal de Tramo del Sol. Usa el estandarte de Sol Devastado para empalar el cadáver del emisario del Odio."}}
D[11539] = {"Tomar el puerto",{"El Magister Ilastar en el Arsenal de Tramo del Sol quiere que mates a 6 invocadores Hojalba, a 6 Caballeros de sangre Hojalba y a 3 tiradores Hojalba."}}
D[11540] = {"Aplasta a los Hojalba",{"El Magister Ilastar en el Arsenal de Tramo del Sol quiere que mates a 6 invocadores Hojalba, a 6 Caballeros de sangre Hojalba y a 3 tiradores Hojalba."}}
D[11541] = {"Perturbar la Costa Branquia Verde",{"La capitana Valindria quiere que liberes a 10 esclavos Branquia Verde. Vuelve junto a ella a bordo del Orgullo de Lunargenta en el Puerto de Tramo del Sol cuando hayas terminado."}}
D[11542] = {"Interceptar a los refuerzos",{"El Vindicador Kaalan del Arsenal de Tramo del Sol quiere hables con Ayren Rompenubes y que vueles sobre la flota de refuerzo de Hojalba. Usa el aceite en llamas para incendiar las velas de los barcos mientras los sobrevuelas y cuando aterrices, mata a 6 reservistas Hojalba."}}
D[11543] = {"Mantén al enemigo a raya",{"El Vindicador Kaalan del Arsenal de Tramo del Sol quiere hables con Ayren Rompenubes y que vueles sobre la flota de refuerzo de Hojalba. Usa el aceite en llamas para incendiar las velas de los barcos mientras los sobrevuelas y cuando aterrices, mata a 6 reservistas Hojalba."}}
D[11544] = {"Armamento de Ata'mal",{"La herrera Hauthaa necesita que crees 5 metales de Ata'mal purificados. Puedes crearlos destruyendo armamento de Ata'mal en su yunque en el Arsenal de Tramo del Sol en la Isla de Quel'Danas."}}
D[11545] = {"Una donación caritativa",{"La anacoreta Ayuri de Tramo del Sol, en la Isla de La Fuente del Sol, quiere que dones 10 oros."}}
D[11546] = {"Abierto al negocio",{"Mar'nah del Puerto de Tramo del Sol quiere que recojas 5 bayas de sangre de los arbustos de Quel'Danas."}}
D[11547] = {"Conoce tus líneas Ley",{"El astromante Darnarian, en el Sagrario de Tramo del Sol, quiere que uses el cristal de astromante en el cristal de sangre, el portal de La Plaza Crepuscular y el sagrario naga en la Costa Branquia Verde."}}
D[11548] = {"Tu incesante apoyo",{"La anacoreta Ayuri de Tramo del Sol, en la Isla de La Fuente del Sol, quiere que dones 10 oros."}}
D[11549] = {"Un benefactor magnánimo",{"El anacoreta Kairthos quiere que dones 1000 oros para ayudar a la causa de la anacoreta Ayuri. Si completas esta misión, serás conocido como <nombre> del Sol Devastado."}}
D[11550] = {"Adelante, Falsario...",{"Preséntate ante el archimago Ne'thul en la Isla de Quel'Danas, al norte de Quel'Thalas","","Los maestros de vuelo de Forjaz y de Ciudad de Lunargenta te llevarán hasta tu destino."}}
D[11554] = {"Un amigo en primera línea",{"Tu ayuda en la ofensiva no ha pasado desapercibida, <nombre>. Combinadas, las fuerzas de los Aldor y de los Arúspices te expresan su agradecimiento."}}
D[11555] = {"Honrado por tus aliados",{"Sigues demostrando tu valía en esta batalla de gran importancia, <nombre>. Acepta esto como prenda de nuestra constante gratitud."}}
D[11556] = {"Venerado en el campo de batalla",{"No podríamos haber llegado hasta aquí sin tu ayuda, <nombre>. Las fuerzas combinadas de los Aldor y los Arúspices no son suficiente para aplastar a la Legión y a Kael. Es una suerte que podamos contar con aliados de tu talla entre nosotros."}}
D[11557] = {"Exaltado entre todos los combatientes",{"Eres una de las mejores, <nombre>. Tu nombre será conocido entre nuestras filas durante años","","Acepta este pequeño presente de parte de nuestras fuerzas."}}
D[11558] = {"Amor peligroso",{"Lleva una tarjeta mohosa de guardián a Fenstad Argila a Entrañas."}}
