D[11880] = {"La investigación multifase",{"El presagista Haronem de la Ciudad de Shattrath quiere que uses las gafas espectrográficas multifase para obtener 6 lecturas multifase."}}
D[11882] = {"Jugando con fuego",{"Habla con un maestro tragafuegos en cualquiera de las capitales de la Alianza."}}
D[11883] = {"¿Danza con fuego?",{"Habla con un maestro de danza del fuego en cualquier capital de la Horda."}}
D[11885] = {"Sangre adversaria",{"Encuentra los montones de cráneos en el centro de los círculos de invocación de Skettis. Invoca y derrota a cada uno de los descendientes usando 10 Pergaminos perdidos en el Tiempo en el montón de cráneos. Vuelve a ver a Hazzik al Alto de los Vientonegro."}}
D[11886] = {"Actividad sospechosa",{"Ve hasta el nuevo Campamento Crepúsculo al sur de la entrada a las Cavernas de Brazanegra en La Ensenada de Zoram de Vallefresno y recupera la correspondencia Crepuscular de los fieles. Después, pide la ayuda del guía Anillo de la Tierra mediante la baliza totémica."}}
D[11891] = {"Un disfraz inofensivo",{"Utiliza el orbe del reptador para espiar en el nuevo Campamento Crepuscular al oeste de la entrada de las Cavernas de Brazanegra en La Ensenada de Zoram en Vallefresno, luego invoca al guía del Anillo de la Tierra usando la baliza totémica."}}
D[11915] = {"Jugando con fuego",{"Habla con un maestro tragallamas en cualquiera de las capitales de la Horda."}}
D[11917] = {"El contraataque",{"Mata al teniente Olaescarcha que invoques desde la piedra de hielo situada en La Ensenada de Zoram en Vallefresno. Después, ve a ver al anciano del Anillo de la Tierra en alguna de las capitales."}}
D[11921] = {"Más lanzamiento de antorchas",{"Gana la prueba de lanzamiento de antorchas y ve a hablar con el maestro tragafuegos."}}
D[11922] = {"Lanzamiento de antorchas",{"Gana la prueba de lanzamiento de antorchas y ve a hablar con el maestro tragallamas."}}
