(function() local D = SUIQuestScopeData.L10n.frFR.Quest
D[1] = {"La quête d'Alexander",{"Trouvez l'endroit oublié et lancez un sort."}}
D[2] = {"La griffe de Serres-tranchantes",{"Apporter la griffe de Serres-tranchantes à Senani Cœur-de-tonnerre, au poste de Bois-brisé, en Orneval."}}
D[5] = {"L'estomac qui gargouille",{"Parler au chef Grual."}}
D[6] = {"La prime pour Garrick Padfoot",{"Tuer Garrick Ladétrousse et rapporter sa tête à l'Adjoint Willem de l'Abbaye de Comté-du-nord."}}
D[7] = {"Nettoyer le camp des kobolds",{"Tuer 10 Vermines kobold, puis revenir voir le maréchal McBride."}}
D[8] = {"Un marché de voleur",{"Livrer une Lettre à Renée dans les Clairières de Tirisfal."}}
D[9] = {"Les champs de mort",{"Le Fermier Saldean veut que vous tuiez 20 Gardiens des moissons."}}
D[10] = {"La rédemption de Scrimshank",{"Découvrir ce qu'est devenu le géomètre Scrimshank, et rapporter son équipement topographique au grand géomètre Radiésthéflop à Gadgetzan."}}
D[11] = {"Prime pour les gnolls Rivepatte",{"Apporter 8 Brassards peints de gnoll à l'Adjoint Rainer à la Caserne."}}
D[12] = {"La milice du peuple",{"Tuer 15 Trappeurs défias et 15 Contrebandiers défias pour Gryan Roidemantel, puis retourner le voir sur la Colline des sentinelles."}}
D[13] = {"La milice du peuple",{"Tuer 15 Pilleurs défias et 15 Pillards défias pour Gryan Roidemantel, puis retourner le voir sur la Colline des sentinelles."}}
D[14] = {"La milice du peuple",{"Tuer 15 Malandrins défias, 5 Eclaireurs défias et 5 Truands défias pour Gryan Roidemantel, puis retourner le voir sur la Colline des sentinelles."}}
D[15] = {"Enquête sur la crête aux échos",{"Tuer 10 Ouvriers kobolds, puis revenir faire son rapport au maréchal McBride."}}
D[16] = {"Procurer de l'eau à Gerard",{"Cultiver la terre est un travail difficile et qui donne diablement soif, je suis toujours partant pour un peu d'eau claire et fraîche.","","Si vous en avez, eh bien ! je ferai bien affaire avec vous."}}
D[17] = {"Rechercher les composants à Uldaman",{"Apporter 12 Champignons magenta à Ghak Touchesoins à Thelsamar."}}
D[18] = {"La confrérie des voleurs",{"Apporter 12 Masques rouges à l'Adjoint Willem à l'extérieur de l'Abbaye de Comté-du-nord."}}
D[19] = {"Tharil'zun",{"Rapporter la Tête de Tharil'zun au maréchal Marris, dans les Carmines."}}
D[20] = {"La menace des Blackrock",{"Rapporter 10 Haches détériorées au maréchal Marris de Comté-du-lac."}}
D[21] = {"La bataille de la Crête aux échos",{"Tuer 12 Travailleurs kobold, puis revenir voir le maréchal McBride, à l'Abbaye de Comté-du-nord."}}
D[22] = {"La tourte au foie de broche-tripes",{"Salma Saldean a besoin de 8 Foies de broche-tripes pour faire une Tourte au foie de broche-tripes."}}
D[23] = {"La patte d'Ursangous",{"Apporter la Patte d'Ursangous à Senani Cœur-de-tonnerre, au Poste de Bois-brisé, à Orneval."}}
D[24] = {"La tête de Shadumbra",{"Apporter la Tête de Shadumbra à Senani Cœur-de-tonnerre, au Poste de Bois-brisé, dans Orneval."}}
D[25] = {"Impasse aux Serres-Rocheuses",{"Tuer 12 Elémentaires d'eau corrompus au lac Mystral, à l'est de la Perce des Serres, et au sud-ouest du poste de Bois-brisé.","","Faire une reconnaissance sur le kiosque du lac Mystral ; celui qui a vue sur l'avant-poste de l'Alliance.","","Retourner voir Mastok Torvesiffle, au poste de Bois-brisé, dans Orneval."}}
D[26] = {"Une leçon à apprendre",{"Parler à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune."}}
D[27] = {"Une leçon à apprendre",{"Parler à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune."}}
D[28] = {"L'épreuve du lac",{"Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l'apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.","","Vous devez parler à Tajarri, au sanctuaire, afin de terminer l'épreuve."}}
D[29] = {"L'épreuve du lac",{"Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.","","Vous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve."}}
D[30] = {"L'épreuve du lion de mer",{"Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.","","Reformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.","","Apporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune."}}
D[31] = {"Forme aquatique",{"Retourner aux Pitons du Tonnerre et montrer le Pendentif du lion de mer à Turak Totem-runique."}}
D[32] = {"L'ascension des silithides",{"Apporter le rapport à Zilzibin Kongadok à Orgrimmar."}}
D[33] = {"Les loups derrière la frontière",{"Apporter 8 pièces de Viande de loup coriace à Eagan Tannepeau, à l'extérieur de l'Abbaye de Comté-du-nord."}}
D[34] = {"Un indésirable",{"Martie Jainrose de Comté-du-lac veut que vous tuiez Fouailleventre. Ramenez-lui ses défenses comme preuve."}}
D[35] = {"Inquiétudes supplémentaires",{"Le maréchal Dughan veut que vous parliez au garde Thomas."}}
D[36] = {"Le ragoût de la marche de l'Ouest",{"Verna Froncebouille veut que vous apportiez la Recette du ragoût de la marche de l'Ouest à Salma Saldean."}}
D[37] = {"Trouver les gardes disparus",{"Le garde Thomas veut que vous alliez vers le nord, le long de la rivière, à la recherche de deux gardes disparus, Rolf et Malakai."}}
D[38] = {"Le ragoût de la marche de l'Ouest",{"Salma Saldean veut 3 morceaux de Viande filandreuse de vautour, 3 Groins de broche-tripes, 3 Yeux de murloc et 3 Okras."}}
D[39] = {"Remettre le rapport de Thomas",{"Avertir le maréchal Dughan de Comté-de-l'or."}}
D[40] = {"Péril en la rivière",{"Remy \"Deux fois\" veut que vous parliez au maréchal Dughan à Comté-de-l'or."}}
D[45] = {"La destinée de Rolf",{"Fouiller le village des murlocs pour trouver Rolf ou des traces de sa mort."}}
D[46] = {"Des primes pour les murlocs",{"Ramener 8 Ailerons de murloc au garde Thomas au Pont est d'Elwynn."}}
D[47] = {"L'échange de poussière d'or",{"Rapporter 10 Poussières d'or à Remy \"Deux fois\" à Comté-de-l'or. La Poussière d'or se récupère sur les kobolds dans la forêt d'Elwynn."}}
D[48] = {"Doux whisky",{"Rapporter de l'Eau de source sacrée à Tristevin Tonnebière."}}
D[49] = {"Doux whisky",{"Tristevin Tonnebière veut un Sac d'orge, un Sac de seigle et un Sac de maïs."}}
D[50] = {"Doux whisky",{"Tristevin Tonnebière veut du Vrai-argent."}}
D[51] = {"Doux whisky",{"Apporter une Branche de sycomore à Tristevin Tonnebière."}}
D[52] = {"Protéger la frontière",{"Tuer 8 Rôdeurs et 5 Jeunes ours des forêts, et revenir voir le garde Thomas au pont, à l'est d'Elwynn."}}
D[53] = {"Doux whisky",{"Apporter un Fagot de chêne à Grimbooze Thunderbrew."}}
D[54] = {"Rapport pour Goldshire",{"Apporter les documents du maréchal McBride au maréchal Dughan de Comté-de-l'or."}}
D[55] = {"Morbent Fel",{"Utiliser le Fléau de Morbent sur Morbent Lagangrène, le tuer, puis rapporter le Fléau de Morbent à Sven, dans son camp."}}
D[56] = {"Les Veilleurs",{"Le commandant Althea Bouclenoire de Sombre-comté veut que vous tuiez 8 Guerriers squelettes et 6 Mages squelettes."}}
D[57] = {"Les Veilleurs",{"Le commandant de Sombre-comté, Althea Bouclenoire, veut que vous tuiez 15 Démons squelettes et 15 Squelettes infernaux."}}
D[58] = {"Les Veilleurs",{"Le commandant de Sombre-comté, Althea Bouclenoire, veut que vous tuiez 20 Répandeurs de peste dans le mausolée est de Colline-aux-Corbeaux."}}
D[59] = {"Les armures de cuir et d'étoffe",{"Donner le Bon pour une pièce d'armure de Hurlevent à Sara Timberlain."}}
