D[61] = {"Une cargaison pour Hurlevent",{"Livrer la Cargaison de William à Morgan Pilon dans le Quartier commerçant de Hurlevent."}}
D[62] = {"La mine de Fondugouffre",{"Explorer la mine de Fondugouffre, puis revenir voir le maréchal Dughan de Comté-de-l'or."}}
D[63] = {"L'appel de l'eau",{"Vaincre la Manifestation d'eau corrompue et placer les Bracelets de manifestation corrompue avec le reste d'eau pure sur le brasero d'Everfount dans la forêt des Pins argentés."}}
D[64] = {"Le cadeau oublié",{"Le fermier Froncebouille désire que vous retrouviez sa Montre qui se trouve dans la penderie de sa ferme près du champ de citrouilles à l'ouest."}}
D[65] = {"La Confrérie défias",{"Gryan Roidemantel veut que vous parliez à Wiley à Comté-du-lac."}}
D[66] = {"La légende de Stalvan",{"Aller voir le Greffier Daltry à l'hôtel de ville de Sombre-comté."}}
D[67] = {"La légende de Stalvan",{"Voyager jusqu'à l'école de Ruisselune et rapporter des informations récentes sur Stalvan au Greffier Daltry."}}
D[68] = {"La légende de Stalvan",{"Rapporter la Lettre poussiéreuse au greffier Daltry."}}
D[69] = {"La légende de Stalvan",{"Aller à l'Auberge de la Fierté du lion pour apprendre si quelqu'un a entendu parler de Stalvan."}}
