D[181] = {"Les yeux dans les étoiles",{"Localiser Zzarc'Vul dans le tertre des ogres au sud du bois de la Pénombre et rapporter son Monocle à Viktori de Sombre-comté."}}
D[182] = {"La caverne des trolls",{"Grelin Blanchebarbe aimerait que vous tuiez 14 Jeunes trolls Crins-de-givre."}}
D[183] = {"Chasseur de sangliers",{"Talin Œil-perçant aimerait que vous tuiez 12 Petits sangliers des rochers."}}
D[184] = {"Titre de propriété de Froncebouille",{"Rapporter son titre de propriété au Fermier Froncebouille."}}
D[185] = {"Maîtrise de la chasse au tigre",{"Ajeck Rouack de l'Expédition de Nesingwary veut que vous chassiez 10 Jeunes tigres de Strangleronce."}}
D[186] = {"Maîtrise de la chasse au tigre",{"Ajeck Rouack de l'Expédition de Nesingwary veut que vous chassiez 10 Tigres de Strangleronce."}}
D[187] = {"Maîtrise de la chasse au tigre",{"Ajeck Rouack de l'Expédition de Nesingwary veut que vous chassiez 10 Anciens tigres de Strangleronce."}}
D[188] = {"Maîtrise de la chasse au tigre",{"Ajeck Rouack de l'Expédition de Nesingwary veut que vous tuiez Sin'Dall et que vous rapportiez sa Patte."}}
D[189] = {"Oreilles de Scalps-rouges",{"Obtenir 15 Oreilles de trolls Scalp-rouge et les apporter à Kebok, à Baie-du-Butin."}}
D[190] = {"Maîtrise de la chasse à la panthère",{"Le sire S. J. Erlgadin de l'Expédition de Nesingwary veut que vous tuiez 10 Jeunes panthères."}}
D[191] = {"Maîtrise de la chasse à la panthère",{"Le sire S. J. Erlgadin de l'Expédition de Nesingwary veut que vous tuiez 10 Panthères."}}
D[192] = {"Maîtrise de la chasse à la panthère",{"Le sire S. J. Erlgadin de l'Expédition de Nesingwary veut que vous tuiez 10 panthères Ombregueule."}}
D[193] = {"Maîtrise de la chasse à la panthère",{"Le sire S. J. Erlgadin de l'Expédition de Nesingwary veut que vous lui rapportiez un Croc de Bhag'thera."}}
D[194] = {"Contrôler la population des raptors",{"Hemet Nesingwary Jr veut que vous tuiez 10 Raptors de Strangleronce."}}
D[195] = {"Maîtrise de la chasse aux raptors",{"Hemet Nesingwary Jr veut que vous tuiez 10 Raptors flagellants."}}
D[196] = {"Maîtrise de la chasse aux raptors",{"Hemet Nesingwary Jr veut que vous tuiez 10 Traqueurs de la jungle."}}
D[197] = {"Contrôler la population des raptors",{"Hemet Nesingwary Jr veut que vous tuiez Téthis, un raptor farouche et dangereux de Strangleronce."}}
D[198] = {"Les marchandises du soldat Thorsen",{"Remettre les marchandises des gobelins au soldat Thorsen."}}
D[199] = {"Une sombre menace se dessine",{"Retourner voir l'ingénieur en chef Hinderweir et lui montrer l'indice que vous avez découvert."}}
D[200] = {"Hérode la Paperasse",{"Trouver les registres de Hérode la Paperasse."}}
D[201] = {"L'enquête au camp",{"Trouver le camp des chasseurs et communiquer sa position à Krazek à Baie-du-Butin."}}
D[202] = {"Le colonel Kurzen",{"Tuer 6 Troupes d'élite, 4 Lieutenants et rapporter la tête de Kurzen au lieutenant Doren au camp rebelle."}}
D[203] = {"La seconde rébellion",{"Tuer 15 Guerriers de la jungle.","","Retourner voir le sergent Yohwa au Camp rebelle."}}
D[204] = {"Mauvaise médecine",{"Apporter 7 Remèdes tropicaux et 1 Extrait de fougère vénéneuse au sergent Yohwa au Camp rebelle."}}
D[205] = {"Sorcellerie troll",{"Apporter 4 Fétiches Casse-crâne à frère Nimetz au Camp rebelle."}}
D[206] = {"Mai'Zoth",{"Apporter la Vue de l'Esprit au frère Nimetz au Camp rebelle."}}
D[207] = {"Le mystère de Kurzen",{"Trouver les 4 tablettes et rapporter ces légendes au frère Nimetz."}}
D[208] = {"La chasse au gros gibier",{"Hemet Nesingwary Jr veut que vous lui rameniez la tête du roi Bangalash, le grand tigre blanc."}}
D[209] = {"Les défenses Casse-crâne",{"Acquérir 18 Défenses de trolls Casse-crâne et les apporter à Kebok."}}
D[210] = {"La cuisine de Krazek",{"Apporter la Cocotte ébréchée de Krazek à Krazek le gobelin."}}
D[211] = {"Hélas, Andorhal",{"Apporter l'Éclat phylactère d'Araj au commandant Ashlam Vaillepoing, au camp du Noroît, dans les Maleterres de l'ouest."}}
D[212] = {"Un repas servi froid",{"Tuer un basilic Œil-de-glace, collecter un Cuissot de basilic glacé, et le rapporter à Angus Stern, au Solitaire bleu."}}
D[213] = {"Une ponction musclée",{"Retrouver 8 Cristaux réduits et les apporter à Kebok à Baie-du-Butin."}}
D[214] = {"Les masques rouges en soie",{"L'Eclaireur Riell de la tour de la Colline des sentinelles veut que vous lui rameniez 10 masques rouges en soie."}}
D[215] = {"Les secrets de la jungle",{"Parler au lieutenant Doren au Camp rebelle."}}
D[216] = {"Entre un roc et un Crin-de-Chardon",{"Tuer 8 Vengeurs Crins-de-Chardon et 8 Chamans Crins-de-Chardon ; la plupart d'entre eux se trouvent à l'est de la grève de Zoram, dans le village des Crins-de-Chardon. Retourner voir Karang Amakkar, à l'avant-poste de Zoram'gar, à Orneval, une fois que vous aurez terminé."}}
D[217] = {"À la défense des terres du roi",{"Tuer le chef des troggs, Grawmug, et ses deux gardes, Grinceur et Bagarreur, puis rendre compte de la situation au capitaine Rudagite à la Tour de garde méridionale."}}
D[218] = {"Le journal volé",{"Grelin Blanchebarbe veut que vous tuiez Grik'nir le Froid et que vous lui rapportiez son journal."}}
D[219] = {"Porté disparu",{"Protéger le caporal Keeshan sur le chemin des Carmines."}}
D[220] = {"L'appel de l'eau",{"Apporter la Fiole d'eau la plus pure à Islen Waterseer dans les Tarides."}}
D[221] = {"Worgens dans les bois",{"Tuer 12 worgens Messagers Plaie-de-nuit pour Calor de Sombre-comté."}}
D[222] = {"Worgens dans les bois",{"Tuer 8 Crocs noirs Plaie-de-nuit et 8 Contaminés Plaie-de-nuit pour Calor de Sombre-comté."}}
D[223] = {"Worgens dans les bois",{"Apporter la note de Calor à Jonathan Carevin."}}
D[224] = {"À la défense des terres du roi",{"Le Montagnard Pave-silex de la Tour de garde méridionale veut que vous tuiez 10 Troggs et 10 Eclaireurs Brisepierre."}}
D[225] = {"La tombe effritée",{"Parler à Sirra Von'Indi à Sombre-comté."}}
D[226] = {"Des loups aux trousses",{"Tuer 12 Loups redoutables affamés et 8 Loups redoutables enragés, puis retourner auprès de Lars au camp de Sven à la frontière ouest du bois de la Pénombre."}}
D[227] = {"Morgan Ladimore",{"Parler au commandant Althea Bouclenoire à Sombre-comté."}}
D[228] = {"Mor'Ladim",{"Tuer Mor'Ladim, puis rapporter son crâne au commandant Althea Bouclenoire à Sombre-comté."}}
D[229] = {"La fille qui survécut",{"Parler au Gardien Sarah Ladimore à Sombre-comté."}}
D[230] = {"Le camp de Sven",{"Apporter à Sven le Livre de la ferme de Sven."}}
D[231] = {"L'amour d'une fille",{"Déposer la bague de Sarah Ladimore sur la tombe de Morgan Ladimore."}}
D[232] = {"Course pour l'apothicaire Zinge",{"Apporter le bon de commande à Alessandro Luca à Fossoyeuse."}}
D[233] = {"La distribution du courrier de la Vallée des Frigères",{"Apporter la pile de lettres à Talin Œil-perçant."}}
D[234] = {"La distribution du courrier de la Vallée des Frigères",{"Remettre la lettre à Grelin Blanchebarbe."}}
D[235] = {"La Chasse d'Orneval",{"Parler à Senani Cœur-de-tonnerre, au Poste de Bois-brisé, à Orneval."}}
D[237] = {"À la défense des terres du roi",{"Le Montagnard Gravegalle de la Tour de garde méridionale veut que vous tuiez 10 Brise-crâne et 10 Prophètes Brisepierre, puis que vous retourniez le voir."}}
D[238] = {"Course pour l'Apothicaire Zinge",{"Apportez une Trousse d'analyse de terrain à l'Apothicaire Zinge à Undercity."}}
D[239] = {"Au secours de la garnison du ruisseau de l'ouest !",{"Se rendre à la garnison du ruisseau de l'ouest et parler à l'Adjoint Rainer."}}
D[240] = {"Retour vers la Tremblotte",{"Retourner voir la Tremblotte avec des Gâteaux au crabe brun."}}
D[243] = {"Sur le terrain",{"Parler à l'Ingénieur en chef Bilgewhizzle à Gadgetzan afin d'obtenir une source d'énergie pour la trousse d'analyse."}}
D[244] = {"Des gnolls encombrants",{"Informer l'Adjoint Feldon."}}
D[245] = {"Les plaies à huit pattes",{"Tuer 15 Araignées Tisse-venin pygmées, puis rendre compte au Gardien Dodds au bois de la Pénombre."}}
D[246] = {"L'appréciation du danger",{"Tuer 10 Bâtards des Carmines et 6 Braconniers des Carmines, et aller faire un rapport à l'Adjoint Feldon à Comté-du-lac."}}
D[247] = {"La chasse achevée",{"<nom>, vous avez tué les trois bêtes qui composent la Chasse d'Ashenvale. Vous m'avez apporté les preuves de leur mort ; je ne doute plus de votre force ni de votre ténacité. Le sang d'un chasseur coule dans vos veines, et je vous en félicite !","","S'il vous plaît, acceptez ceci pour vous récompenser de la prouesse que vous avez accomplie pour la Horde, à Ashenvale. Que vos ancêtres vous protègent !"}}
D[248] = {"En regardant plus loin",{"Escalader la Tour de guet intacte près du Donjon Guet-de-Pierre.","","Trouver un contenant adéquat pour le Glyphe d'Azora."}}
D[249] = {"Morganth",{"Battre Morganth.","","Apporter sonBring his Pendentif des ombres à Theocritus à la Tour d’Azora dans la Forêt d'Elwynn."}}
D[250] = {"Une sombre menace se dessine",{"Enquêter près de la rampe est du barrage et rapporter à l'ingénieur en chef Hinderweir un indice qui permettrait de deviner les intentions des nains Sombrefer."}}
D[251] = {"La traduction de la lettre d'Abercrombie",{"Remettre la Lettre à Ello à Sirra Von'Indi."}}
D[252] = {"La traduction pour Ello",{"Remettre la lettre traduite au seigneur Ello Bouclenoire."}}
D[253] = {"La fiancée de l'Embaumeur",{"Trouver la tombe d'Eliza, retrouver le cœur de l'Embaumeur, puis retourner voir Ello Bouclenoire."}}
D[254] = {"En creusant la terre",{"Vous creusez dans la saleté molle au-dessus de la tombe... et vous trouvez les restes d'un cercueil.","","Vous sentez le cercueil vibrer sous l'effet de ce qui semble être des griffes qui raclent à l'intérieur, et vous entendez le grincement de dents en décomposition...","","Allez-vous ouvrir le cercueil et récupérer le cœur de l'Embaumeur ?"}}
D[255] = {"Mercenaires",{"Le magistrat Courtnez de Thelsamar vous a <embauché/embauchée> pour tuer 4 Ogres, 4 Brutes et 4 Massacreurs Mo'grosh."}}
D[256] = {"ON RECHERCHE : Chok'sul",{"Tuer Chok'sul et rapporter sa tête au Magistrat Courtnez de Thelsamar."}}
D[257] = {"La fanfaronnade d'un chasseur",{"Tuer 6 Busards des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en moins de 15 minutes."}}
D[258] = {"Le défi d'un chasseur",{"Tuer 5 Anciens sangliers des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en 12 minutes."}}
D[261] = {"Sur le chemin écarlate",{"Détruire 30 Ravageurs morts-vivants, puis retourner voir Frère Anton, à la Combe de Nijel."}}
D[262] = {"L'obscure silhouette",{"Montrer le livre que vous avez trouvé à la ferme de Sven aux habitants de Sombre-comté."}}
D[263] = {"À la défense des terres du roi",{"Le Montagnard Cognemur de la Tour de garde méridionale veut que vous tuiez 10 Chamans et 10 Briseurs d'Os Brisepierre."}}
D[264] = {"Jusqu'à ce que la mort nous sépare",{"Placer le pendentif de Clarice sur la tombe de Yuriv, dans la forêt des Pins argentés."}}
D[265] = {"L'obscure recherche se poursuit",{"Voir si d'autres habitants ont des indices concernant l'obscure silhouette."}}
D[266] = {"Une enquête à l'auberge",{"Chercher à l'auberge des indices concernant l'obscure silhouette."}}
D[267] = {"La menace trogg",{"Apporter 8 Dents de pierre de troggs au capitaine Rudagite à la Tour de garde méridionale."}}
D[268] = {"Retourner voir Sven",{"Retourner voir Sven avec le journal complété de la Tremblotte."}}
D[269] = {"À la recherche de la sagesse",{"Donner le Journal complété de la Tremblotte à l'évêque Farthing à Hurlevent."}}
D[270] = {"La Flotte perdue",{"Aller au port de Menethil, dans les Paluns, et parler à Glorin Front-d'acier."}}
D[271] = {"La vengeance de Vyrin",{"Tuer le Vieux Noiraud puis montrer le résultat à Daryl le Jeune au pavillon des Pérégrins."}}
D[272] = {"L'épreuve du lion de mer",{"Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l'endroit où ces objets se trouvent.","","Reformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire ceci.","","Apporter le Pendentif reformé à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune."}}
D[273] = {"Approvisionnement du site de fouilles",{"Aller voir Huldar."}}
D[274] = {"Une sombre menace se dessine",{"Ashlan Rictus-de-pierre vous demande de retourner voir l'Ingénieur en chef Hinderweir pour l'informer de la nouvelle découverte."}}
D[275] = {"Fièvre sur le pays",{"Tuer 12 Rampants des tourbières, puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns."}}
D[276] = {"Piétinements de pattes",{"Tuer 15 Gnolls Poils-moussus et 10 Bâtards Poils-moussus puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns."}}
D[277] = {"Feu interdit",{"Rapporter à Rethiel, le Gouverneur vert, 9 Silex bruts."}}
D[278] = {"Une sombre menace se dessine",{"Collecter du Venin de rôdeuse, un Cristal mo'grosh et une Larme de crocilisque pour l'Ingénieur en chef Hinderweir."}}
D[279] = {"Griffes des profondeurs",{"Tuer 12 Murlocs Branchies-bleues.","","Tuer Enfourneur et prendre sa tête.","","L'apporter à Karl Boran au port de Menethil."}}
D[280] = {"Une sombre menace se dessine",{"L'Ingénieur en chef Hinderweir vous demande de nager jusqu'à la base du barrage pour localiser le tonnelet de poudre et d'y verser la mixture de désamorçage pour empêcher une explosion."}}
D[281] = {"Récupération de marchandises",{"Rechercher les caisses et les barils dans les camps murlocs le long de la côte."}}
D[282] = {"Les observations de Senir",{"Aller voir le Montagnard Thalos."}}
D[283] = {"Une sombre menace se dessine",{"La Mixture de désamorçage semble avoir fonctionné. Retourner voir l'Ingénieur en chef Hinderweir pour lui annoncer la bonne nouvelle."}}
D[284] = {"La recherche continue",{"Rechercher la Statuette de Menethil."}}
D[285] = {"À la recherche d'autres taudis",{"Continuer à fouiller les taudis des murlocs pour retrouver la Statuette de Menethil."}}
D[286] = {"Rapporter la statuette",{"Apporter la Statuette de Menethil à Karl Boran."}}
D[287] = {"Le repaire des Frostmane",{"Explorer le repaire des Crins-de-givre et tuer 5 Chasseurs de tête Crins-de-givre pour Senir Blanchebarbe à Kharanos."}}
D[288] = {"La IIIe flotte",{"Acheter une Cruche d'hydromel pour le Premier officier Fitzsimmons."}}
D[289] = {"L'équipage maudit",{"Tuer 13 Marins maudits, 5 Soldats de marine maudits et le Premier officier Snellig. Rapporter la Tabatière de Snellig au Premier officier Fitzsimmons au port de Menethil."}}
D[290] = {"Levée de la malédiction",{"Obtenir du capitaine Halyndor la Clé du coffre-fort de \"l'Intrépide\".","","Utiliser la clé pour ouvrir le Coffre verrouillé de l'Intrépide."}}
D[291] = {"Les rapports",{"Livrer le rapport de Senir au Sénateur Barin Rougepierre à Forgefer."}}
D[292] = {"L'Œil de Paleth",{"Apporter l'Oeil maudit de Paleth à Glorin Steelbrow."}}
D[293] = {"Purifier l'Œil",{"Apporter l'Oeil maudit de Paleth à l'archevêque Benedictus, à la cathédrale de la Lumière de la ville de Stormwind."}}
D[294] = {"La vengeance d'Ormer",{"Ormer Tressefer, à l'Excavation de Whelgar, vous demande de tuer 10 Hurleurs tachetés et 10 Raptors tachetés."}}
D[295] = {"La vengeance d'Ormer",{"Tuer 10 Faucheurs tachetés et 10 Tranchegueules tachetés pour Ormer Tressefer, puis aller le voir à l'excavation de Whelgar."}}
D[296] = {"La vengeance d'Ormer",{"Ormer Tressefer, de l'Excavation de Whelgar, vous demande de tuer Grondecroc et de revenir avec l'une de ses serres une fois la tâche accomplie."}}
D[297] = {"Réunir les idoles",{"Apporter 8 Idoles de pierre sculptée à Magmar Tombebranche."}}
D[298] = {"Compte rendu d'avancement des fouilles",{"Apporter le Compte rendu d'avancement de Baguefer à Jern Casque-à-cornes à Thelsamar."}}
D[299] = {"Découverte du passé",{"À la demande du prospecteur Whelgar, parcourir les Excavations à la recherche des 4 fragments de tablette manquants : Ados, Modr, Golm et Neru."}}
D[301] = {"Rapport à Forgefer",{"Porter le Compte rendu d'avancement de Baguefer au Prospecteur Foudrepique."}}
D[302] = {"De l'explosif pour Baguefer",{"Parler à Jern Casque-à-cornes à Thelsamar."}}
D[303] = {"La guerre contre les Sombrefer",{"Motley Garmaçon de Dun Modr vous demande de tuer 10 Nains Sombrefer, 5 Tunneliers Sombrefer, 5 Saboteurs Sombrefer et 5 Démolisseurs Sombrefer."}}
D[304] = {"Une tâche sinistre",{"Tuer Balgaras le Crasseux et rapporter son oreille à Tresse-longue le Macabre à Dun Modr."}}
D[305] = {"À la recherche de l'équipe de fouilles",{"À la demande de Tarrel Tisseroche, aller jusqu'aux Excavations et entrer en contact avec Merrin Tisseroche."}}
D[306] = {"À la recherche de l'équipe de fouilles",{"Retourner voir Tarrel Tisseroche avec la lettre de Merrin."}}
D[307] = {"Bas les pattes !",{"Aller à la Mine du Ru d'argent pour prendre 4 lots d'Equipement de mineur.","","Retourner voir le Montagnard Foudrepique."}}
D[308] = {"Distraire Jarven",{"Hum ! Toute cette boisson stockée là, et dire que j'ai l'interdiction formelle d'y toucher ! Si seulement je pouvais goûter un peu de notre Thunder Ale... Ça me donnerait un esprit plus vif, sans mentir !"}}
D[309] = {"Protection de la cargaison",{"S'assurer que Miran et la cargaison parviennent au Site de fouilles puis en informer le Prospecteur Baguefer."}}
D[310] = {"Bières rivales",{"Aller au sous-sol de la distillerie Tonnebière à Kharanos et remplacer un Tonneau de Thunder Ale par un Tonneau de Brasselorge Scalder."}}
D[311] = {"Retour chez Marleth",{"Apporter le Tonneau de Thunder Ale à Marleth Brasselorge au Village de Brassetout."}}
D[312] = {"La réserve volée de Tundra MacGrann",{"Récupérer la caisse de viande séchée de Tundra MacGrann dans la Caverne du Vieux Barbeglace."}}
D[313] = {"L'antre Gris",{"Réunir 8 Peaux de wendigo et les apporter au Pilote Engrepierre."}}
D[314] = {"Protection du troupeau",{"Sur demande de Rudra Distillambre, tuer Vagash et rapporter un de ses crocs à la ferme des Distillambre."}}
D[315] = {"La bière brune parfaite",{"Apporter 6 Brins de chatoyante à Rejold Brasselorge, au village de Brassetout."}}
D[317] = {"Ravitailler le Crache-vapeur",{"Réunir 4 morceaux de Viande de sanglier et 2 Fourrures d'ours épaisses et les livrer au pilote Claquesoufflet au dépôt de Grillacier."}}
D[318] = {"L'éternol",{"Demander un tonneau d'Eternol à Rejold Brasselorge au village de Brassetout."}}
D[319] = {"Une faveur pour un tonneau d’Evershine",{"Tuer 6 Ours Griffeglace, 8 Anciens sangliers des rochers et 8 Léopards des neiges, puis retourner voir Rejold Brasselorge à Brassetout."}}
D[320] = {"Retour vers Bellowfiz",{"Donner le Tonneau d'éternol au Pilote Claquesoufflet au Dépôt de Grillacier."}}
D[321] = {"Le fer de sancteforge",{"Fouiller l'épave de l'Albatros, dans les Paluns."}}
D[322] = {"Béni soit ce bras",{"Apporter la Caisse de lingots de sancteforge à Grimand Elmore, à Stormwind."}}
D[323] = {"Prouver votre valeur",{"Tuer 15 Écumeurs squelettes, 3 Soigneurs squelettes et 3 Gardiens squelettes puis retourner voir Sven."}}
D[324] = {"Les lingots perdus",{"Collecter 5 Lingots de sancteforge puis retourner voir Glorin Front-d'acier, dans les Paluns."}}
D[325] = {"En armes et prêt",{"Apporter le Fléau de Morbent à Sven, dans le bois de la Pénombre."}}
D[328] = {"La clé cachée",{"Utiliser la Petite Clé en cuivre pour ouvrir le Coffre-fort d'Hérode la Paperasse."}}
D[329] = {"L'espion découvert !",{"Apporter la Note maculée de boue au lieutenant Doren, au Camp rebelle."}}
D[330] = {"Composition des patrouilles",{"Parler au caporal Sethman."}}
D[331] = {"Rapport au lieutenant Doren",{"Parler au lieutenant Doren."}}
D[332] = {"Publicité pour la cave à vins Gallina",{"Aller au Vignoble de Gallina et apporter à Suzetta Gallina le Bon pour une bouteille de vin gratuite."}}
D[333] = {"Harlan a besoin d'être approvisionné",{"Aller à la Boutique de tailleur du canal et donner à Rema Schneider la Demande de tissu, pour Harlan Bagley."}}
D[334] = {"Un paquet pour Thurman",{"Aller chez les Couturiers Larson, dans le quartier des mages de Hurlevent, pour donner à Thurman Schneider son Matériel de couture."}}
D[335] = {"Un noble brassage",{"Zardeth de la Griffe noire veut que vous lui rapportiez une Larme de Tilloa de Sombre-comté et une Racine de Musquash des Paluns."}}
D[336] = {"Un noble brassage",{"Apporter la Bière brune de la Griffe noire au seigneur Wishock dans la Chambre du requérant."}}
D[337] = {"Un vieux livre d'histoire",{"Rendre le livre « l'Histoire de Hurlevent » à la Bibliothèque de Hurlevent."}}
D[338] = {"« Les vertes collines de Strangleronce »",{"Rassembler les pages manquantes du manuscrit des « Vertes collines de Strangleronce ». Une fois les quatre chapitres complétés, les rendre à Barnil."}}
D[339] = {"Chapitre I",{"Rapporter les pages 1, 4, 6 et 8 des Vertes collines de Strangleronce de Nesingwary à Barnil Potepierre pour achever le Chapitre I."}}
D[340] = {"Chapitre II",{"Rapporter les pages 10, 11, 14 et 16 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Potepierre pour achever le Chapitre II."}}
D[341] = {"Chapitre III",{"Rapporter les pages 18, 20, 21 et 24 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Potepierre pour achever le Chapitre III."}}
D[342] = {"Chapitre IV",{"Rapporter les pages 25, 26 et 27 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Potepierre pour achever le Chapitre IV."}}
D[343] = {"En parlant de fermeté",{"Allez à la Bibliothèque royale dans le Donjon de Stormwind pour parler à Milton Sheaf. Il trouvera le livre sur la métallurgie dont Frère Kristoff a besoin pour son discours."}}
D[344] = {"Frère Paxton",{"Parler au frère Paxton, à l'Abbaye de Comté-du-nord."}}
D[345] = {"Provisions d'encre",{"Aller voir le contremaître Oslow de Comté-du-lac et lui demander du minerai de rethban."}}
