D[866] = {"Les échantillons de racines",{"Apporter 8 Échantillons de Racines à Mebok Mizzyrix, à Cabestan."}}
D[867] = {"Les harpies pillardes",{"Collecter 8 Griffes d'Ensorçaile.","","Les apporter à Darsok Vivedague à la Croisée."}}
D[868] = {"La chasse aux œufs",{"Apporter 12 Œufs de silithide et la Griffe d'excavation à Korran, à la Croisée."}}
D[869] = {"Les raptors voleurs",{"Apporter 12 Têtes de raptor à Gazrog, à la Croisée."}}
D[870] = {"Les Bassins oubliés",{"Rendre compte de vos découvertes à Tonga Totem-runique."}}
D[871] = {"Stopper les attaques des hurans",{"Dans la tribu Tranchecrin, tuer 8 Sourciers, 8 Tisseuses d'épines et 3 Chasseurs, puis retourner voir Thork."}}
D[872] = {"La perturbation cesse",{"Tuer 8 Géomanciennes Tranchecrin, 8 Défenseurs Tranchecrin et Kreenig Grondegroin.","","Puis apporter la Défense de Kreenig Grondegroin à Thork à la Croisée."}}
D[873] = {"Isha Awak",{"Apporter le Cœur d'Isha Awak à Mahren Skyseer."}}
D[874] = {"Mahren Skyseer",{"Parler à Mahren Oeil-des-cieux."}}
D[875] = {"Lieutenants harpies",{"Rassembler 6 Anneaux de lieutenant harpie sur des Tueuses Ensorçaile et les apporter à Darsok Vivedague à la Croisée."}}
D[876] = {"Serena Plumesang",{"Tuer Serena Plumesang et apporter sa tête à Darsok Vivedague à la Croisée."}}
D[877] = {"L'oasis stagnante",{"Retourner voir Tonga Totem-runique à la Croisée, après avoir enquêté à l'Oasis stagnante."}}
D[878] = {"Tribus en guerre",{"Tuer 6 Sourciers Dos-hirsute, 12 Tisseurs d'épines Dos-hirsute et 12 Géomanciennes Dos-hirsute puis retourner auprès de Mutiledent au camp Taurajo dans les Tarides."}}
D[879] = {"Une trahison de l'intérieur",{"Tuer Nak, Kuz et Lok Plaie-des-orcs et apporter leurs crânes à Mutiledent au Camp Taurajo dans les Tarides."}}
D[880] = {"Source de vie",{"Apporter 8 Carapaces de Gueules d'acier altérées à Tonga Totem-runique à la Croisée."}}
D[881] = {"Echeyakee",{"Apporter la Peau d'Echeyakee à Sergra Sombreronce à la Croisée."}}
D[882] = {"Ishamuhale",{"Apporter le Croc d'Ishamuhale à Jorn au Camp Taurajo."}}
D[883] = {"Lakota'mani",{"Apporter le Sabot de Lakota'mani à Jorn au Camp Taurajo."}}
D[884] = {"Owatanka",{"Apporter l'Epine caudale d'Owatanka à Jorn au Camp Taurajo."}}
D[885] = {"Washte Pawne",{"Apporter la Plume de Washte Pawne à Jorn Oeil-des-cieux au Camp Taurajo."}}
D[886] = {"Les oasis des Tarides",{"Parler à Tonga Totem-runique à la Croisée."}}
D[887] = {"Les flibustiers des Mers du sud",{"Tuer 12 Brigands et 6 Canonniers des Mers du Sud pour Gazleu de Cabestan."}}
D[888] = {"Course à la lentille",{"Retrouver la Cargaison de bottes et la Lentille de télescope pour Gazleu de Cabestan."}}
D[889] = {"L'esprit du vent",{"Apportez 10 Joyaux de sang à Mangletooth et je vous doterai d'une vitesse impressionnante. Vous courrez avec les zhévras et le vent vous jalousera.","","Cela ne durera pas longtemps, mais cela devrait suffire à vous faire traverser les Tarides."}}
D[890] = {"La livraison perdue",{"Apporter le Grand Livre de Gazleu au Maître des quais Tournoupette."}}
D[891] = {"Sous le feu de l'ennemi",{"Le capitaine Thalo'thas Brillesoleil de Cabestan veut que vous collectiez 10 Médailles de Theramore et que vous tuiez le Capitaine Beaumont, le Canonnier Whessan et le Canonnier Smythe."}}
D[892] = {"La livraison perdue",{"Rapporter le Grand Livre de Gazleu à Gazleu à Cabestan."}}
D[893] = {"Des armes de choix",{"Apporter un Poignard tranchecrin, une Baguette tranchecrin carbonisée et un Bouclier tranchecrin à Tatternack Forgacier au camp Taurajo dans les Tarides."}}
D[894] = {"Samophlange",{"Accéder à la Console de contrôle au Centre de recherches de la KapitalRisk."}}
D[895] = {"ON RECHERCHE : baron de Longrivage",{"Apporter la tête du baron de Longrivage à Gazleu à Cabestan."}}
D[896] = {"La bonne fortune d'un mineur pauvre",{"Prendre l'Emeraude œil-de-chat à l'un des Surveillants ou l'un des Massacreurs de la KapitalRisk pour le Maître des quais Tournoupette à Cabestan."}}
D[897] = {"Le Moissonneur",{"Apporter la Tête du Moissonneur à Jorn Oeil-des-cieux."}}
D[898] = {"Hors du fort",{"Escorter en toute sécurité Gilthares Ramefeu jusqu'au capitaine Brillesoleil à Cabestan."}}
D[899] = {"Consumé par la haine",{"Apporter 60 Défenses de huran Dos-hirsute à Mankrik, à la Croisée."}}
D[900] = {"Samophlange",{"Fermer la Valve de contrôle du carburant, la Valve de réglage et la Valve de contrôle principale, puis utiliser à nouveau la console de contrôle."}}
D[901] = {"Samophlange",{"Obtenir la Clé de la console du bricoleur Brokarde, puis l'utiliser sur la console de contrôle."}}
D[902] = {"Samophlange",{"Rapporter le Samophlange à Krachevalve à Cabestan."}}
D[903] = {"Les rôdeurs des Tarides",{"Collecter 7 Griffes de Rôdeur des savanes pour Sergra Sombreronce à la Croisée."}}
D[905] = {"Les Faucheurs furieux",{"Tuer des raptors solécaille et récupérer leurs plumes. Placer ces plumes dans les 3 nids de Faucheurs solécaille, puis retourner voir Sergra Sombreronce à la Croisée."}}
D[906] = {"Une trahison de l'intérieur",{"Apporter le Crâne de Lok à Thork à la Croisée des Tarides."}}
D[907] = {"Les lézards-tonnerre enragés",{"Apporter 3 doses de Sang de lézard-tonnerre à Jorn Oeil-des-cieux, au Camp Taurajo."}}
D[908] = {"Parmi les ruines",{"Apporter le Noyau de la Brasse à Je'neu Sancrea, à l'Avant-poste de Zoram'gar, dans Orneval."}}
D[909] = {"Baron Aquanis",{"Apporter le Globe d'eau étrange à Je'neu Sancrea, à l'Avant-poste de Zoram'gar, dans Orneval."}}
D[910] = {"Un tour sur les quais",{"Emmenez votre protégé sur les quais de Cabestan, dans les Tarides."}}
D[911] = {"L'accès vers la frontière",{"Emmenez votre protégé au Rempart de Mor'shan dans la région nord des Tarides, juste à l'entrée d'Orneval."}}
D[913] = {"Le cri du faucon-tonnerre",{"Trouver et tuer un faucon-tonnerre, et rapporter ses ailes à Jorn Oeil-des-cieux, au Camp Taurajo."}}
D[914] = {"Les druides du Croc",{"Apporter les Gemmes de Cobrahn, d'Anacondra, de Pythas et de Serpentis à Nara Wildmane à Thunder Bluff."}}
D[915] = {"Je veux une glaaaaace !",{"Allez chercher de la glace à la fraise pour votre protégé. Le gamin semble préférer la marque de glace Aguilor & Dagharn."}}
D[916] = {"Le venin des Tissebois",{"Apporter 10 Glandes à venin Tissebois à Gilshalan Marche-vent, à Aldrassil."}}
D[917] = {"L'œuf d'araignée Tissebois",{"Apporter un Œuf d'araignée Tissebois à Gilshalan à Aldrassil."}}
D[918] = {"Les graines de sylvain",{"Apporter 8 Graines de sylvain à Denalan au lac Al'Ameth."}}
D[919] = {"Les pousses de sylvain",{"Apporter 12 Pousses de sylvain à Denalan au lac Al'Ameth."}}
D[920] = {"Les appels de Tenaron",{"Parler à Tenaron Poignorage au sommet d'Aldrassil à Sombrevallon."}}
D[921] = {"La couronne de la Terre",{"Remplir la Fiole de cristal et la rapporter à Tenaron Poignorage au sommet d'Aldrassil."}}
D[922] = {"Rellian Vertecime",{"Apporter une Graine de sylvain à Rellian Vertecime à Darnassus."}}
D[923] = {"Tumeurs",{"Apporter 5 Tumeurs moussues à Rellian Vertecime à Darnassus."}}
D[924] = {"La Graine démoniaque",{"Prendre une Pierre de puissance imparfaite. L'apporter à l'autel de feu avant que le pouvoir de la pierre n'expire, puis revenir à Ak'Zeloth."}}
