D[926] = {"Pierre de puissance imparfaite",{"Ces pierres sont imprégnées d'énergie magique, mais d'une énergie affaiblie, volontairement. Elles sont très instables et une fois prises sur la table, elles se consumeront très rapidement."}}
D[927] = {"Le cœur moussu",{"Apporter le Cœur moussu à Denalan au lac Al'Ameth."}}
D[928] = {"La couronne de la Terre",{"Apporter le Récipient à moitié rempli à Corithras Ragelune à Dolanaar."}}
D[929] = {"La couronne de la Terre",{"Remplir la Fiole de jade et la rapporter à Corithras Ragelune à Dolanaar."}}
D[930] = {"Le fruit luminescent",{"Apporter le Fruit luminescent à Denalan au lac Al'Ameth."}}
D[931] = {"Les racines flamboyantes",{"Apporter les Racines flamboyantes à Denalan au lac Al'Ameth."}}
D[932] = {"Haine folle",{"Tuer le seigneur Melenas et apporter sa tête à Tallonkai Viveracine à Dolanaar."}}
D[933] = {"La couronne de la Terre",{"Remplir la Fiole de tourmaline et la rapporter à Corithras Ragelune à Dolanaar."}}
D[934] = {"La couronne de la Terre",{"Remplir la Fiole d'améthyste et la rapporter à Corithras Ragelune à Dolanaar."}}
D[935] = {"La couronne de la Terre",{"Apporter le Récipient rempli à l'archidruide Fandral Forteramure à Darnassus."}}
D[936] = {"L'aide à l'archidruide Totem-runique",{"Parler à l'archidruide Hamuul Totem-runique aux Pitons du Tonnerre."}}
D[937] = {"La clairière enchantée",{"Acquérir 6 Ceintures plumesang et les apporter à la Sentinelle Arynia Eclairciel à la clairière de l'Oracle."}}
D[938] = {"Brume",{"Escorter Brume vers la Sentinelle Arynia Eclairciel au puits de lune, près de l'arbre-oracle."}}
D[939] = {"Flûte de Xavaric",{"Apporter la Flûte de Xavaric et 5 échantillons de Lien maudit Jadefeu à Eridan Ventebleu, dans le sud de Gangrebois."}}
D[940] = {"Teldrassil",{"Remettre le rapport de l'arbre-oracle à l'archidruide Fandral Forteramure à Darnassus."}}
D[941] = {"Une belle plante",{"Planter le Cœur corrompu dans le Pot de Denalan."}}
D[942] = {"Les absences du Prospecteur",{"Apporter le mystérieux Fossile à l'Archéologue Outrepanse au port de Menethil."}}
