D[949] = {"Le camp du Marteau du crépuscule",{"Trouver un indice au Camp du Marteau du crépuscule au Glaive du Maître."}}
D[950] = {"La page qui rend fou",{"Apporter les Gribouillages déments à Onu."}}
D[951] = {"Les Reliques de Mathystra",{"Apporter 6 Reliques de Mathystra à Onu, au Bosquet des Anciens."}}
D[952] = {"Bosquet des Anciens",{"Livrer le message de Fandral à Onu, au bosquet des Anciens, à Sombrivage, au sud d’Auberdine."}}
D[953] = {"La Chute d'Ameth'Aran",{"Étudier les tablettes qui parlent d'Ameth'Aran et de sa chute, puis retourner voir la Sentinelle Tysha Lamelune à Sombrivage."}}
D[954] = {"Bashal'Aran",{"Trouver la source de l'aura bleue dans les Ruines de Bashal'Aran."}}
D[955] = {"Bashal'Aran",{"Acquérir 8 Boucles d'oreilles de grell pour Asterion à Bashal'Aran."}}
D[956] = {"Bashal'Aran",{"Obtenir l'Ancien sceau de pierre de lune et l'apporter à Asterion à Bashal'Aran."}}
D[957] = {"Bashal'Aran",{"Détruire l'Ancien sceau de pierre de lune à la flamme antique qui se trouve dans Ameth'Aran, puis retourner voir Asterion à Bashal'Aran."}}
D[958] = {"Les outils des Bien-nés",{"Retrouver 7 Reliques de Bien-né pour Thundris Tissevent à Auberdine."}}
D[959] = {"Fuite de porto aux docks",{"Le grutier Bigglefuzz de Cabestan veut que vous repreniez la Bouteille de porto vieille de 99 ans à Magglish le Dingue, qui se cache dans les Cavernes des lamentations."}}
