D[963] = {"Un amour éternel",{"Libérer l'esprit d'Anaya Coursaurore et rapporter son pendentif à Cerellean Blanchegriffe à Auberdine."}}
D[964] = {"Fragments de squelette",{"Apporter 15 Fragments de squelette à l'Apothicaire Dithers à la Barricade, dans les Maleterres de l'ouest."}}
D[965] = {"La Tour d'Althalaxx",{"Trouver Balthule Frappelombre près de la Tour d'Althalaxx à Sombrivage."}}
D[966] = {"La Tour d'Althalaxx",{"Collecter 4 Parchemins passés pour Balthule Frappelombre près de la Tour d'Althalaxx."}}
D[967] = {"La Tour d'Althalaxx",{"Remettre la Lettre de Balthule à Delgren le Purificateur dans la forêt d'Orneval."}}
D[968] = {"Les puissances d'en bas",{"Apporter le Livre : Les puissances d'en bas à Gerrig Poigne-d'os, dans la Caverne lugubre de Forgefer."}}
D[969] = {"Que la chance soit avec vous",{"Collecter 4 Éclats cognegivre pour le sorcier-docteur Mau'ari à Long-guet."}}
D[970] = {"La Tour d'Althalaxx",{"Trouver une Gemme d'âme luminescente et la rapporter à Delgren le Purificateur au poste de Maestra."}}
D[971] = {"La connaissance des profondeurs",{"Apporter le « Manuscrit de Lorgalis » à Gerrig Poigne-d'os dans la Caverne lugubre de Forgefer."}}
D[972] = {"Le sapta d'eau",{"Prenez le sapta d'eau et trouvez l'étendue d'eau corrompue dans la forêt des Pins argentés, <nom>. J'ai une grande confiance en vos compétences."}}
D[973] = {"La Tour d'Althalaxx",{"Apporter le Tome d'Ilkrud Magthrull à Delgren le Purificateur au Poste de Maestra."}}
D[974] = {"À la recherche de la source",{"Krakle, au cratère d'Un'Goro, vous demande de découvrir la zone la plus chaude de la crête de la Fournaise.","","Quand vous trouvez une zone de chaleur, cliquez avec le bouton droit de la souris sur le thermomètre afin de prendre la température. Continuez vos recherches jusqu'à avoir trouvé la zone la plus chaude."}}
D[975] = {"Cache de Mau'ari",{"Attendre un instant, puis reparler au sorcier-docteur Mau'ari pour recevoir le Charme de chance."}}
D[976] = {"De l’approvisionnement pour Auberdine",{"Parler à Delgren le Purificateur, au Poste de Maestra, après avoir escorté Feero à travers la Forêt d'Orneval."}}
D[977] = {"Yéti ? Y es-tu ?",{"Collecter 2 Cornes de yéti en parfait état pour Umi Sarcafroisse, à Long-guet"}}
D[978] = {"Les Indomptables lunaires",{"Collecter 10 Plumes de Chouettard lunaire au Berceau-de-l'Hiver, puis retourner voir Erelas Ambreciel, à Rut'theran."}}
D[979] = {"Trouver Ranshalla",{"Trouver Ranshalla dans l'est du Berceau-de-l'Hiver."}}
D[980] = {"Les nouvelles sources",{"Voyager jusqu'au Berceau-de-l'Hiver et parler à Donova Antreneige."}}
D[981] = {"La Tour d'Althalaxx",{"Aller voir Delgren le Purificateur au Poste de Maestra."}}
D[982] = {"Océan profond, mer immense",{"Récupérer le Coffret de l'Aube argentée et le Coffret du Voile de brume, pour Gorbold Main-d'acier, à Auberdine. Ces deux objets se trouvent à bord des épaves des navires respectifs, au nord du village."}}
D[983] = {"Bigobox 827",{"Réunir 6 Pattes de clampants et les mettre dans la bigobox 827."}}
D[984] = {"Quelle est l'ampleur de la menace ?",{"Trouver un camp de furbolgs corrompus à Sombrivage et retourner voir Terenthis dans Auberdine."}}
D[985] = {"Quelle est l'ampleur de la menace ?",{"Tuer 8 Guides et 5 Messagers du vent Noirbois puis retourner voir Terenthis à Auberdine."}}
D[986] = {"Un maître perdu",{"Trouver 5 Belles peaux de traquelune et les apporter à Terenthis, à Auberdine."}}
D[990] = {"Voyage vers Ashenvale",{"Trouver Raene Mène-loup dans Orneval."}}
D[991] = {"Le nettoyage selon Raene",{"Trouver Teronis dans Orneval."}}
D[992] = {"Étude des eaux de Gadgetzan",{"Utiliser la Fiole de sourcier vide à la mare près du Guet de Tristesable. Une fois l'échantillon récolté, remettre la Fiole de sourcier pleine au grand géomètre Radiésthéflop à Gadgetzan."}}
D[993] = {"Un maître perdu",{"Trouver Volcor, à Sombrivage, et lui donner la Cape enchantée de traquelune."}}
D[994] = {"Évasion par la force",{"Protéger Volcor jusqu'à la route puis aller voir Terenthis à Auberdine."}}
D[995] = {"Évasion par la ruse",{"S'échapper de la grotte des furbolgs et aller voir Terenthis à Auberdine."}}
D[996] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[997] = {"La terre de Denalan",{"Rapporter le paquet de Terre rare à Denalan au lac Al'Ameth."}}
D[998] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
