D[1002] = {"Bigobox 323",{"Trouver 6 Crocs de traquelune et les mettre dans la bigobox 323."}}
D[1003] = {"Bigobox 525",{"Se procurer 4 Scalps vieillis sur de Vieux ours des chardons au sud d'Auberdine et les placer dans la Bigobox 525."}}
D[1004] = {"La nouvelle frontière",{"Parler à l'archidruide Hamuul Totem-runique, sur la Cime des Anciens des Pitons du Tonnerre. Évoquer l'appel du Cercle cénarien concernant l'exploration des frontières de Kalimdor."}}
