D[1006] = {"Ce qui est au-delà"}
D[1007] = {"L'ancienne statuette",{"Apporter l'Ancienne Statuette à Talen, dans son camp près de la grève de Zoram."}}
D[1008] = {"La grève de Zoram",{"Apporter 20 Têtes d'Irequeue à Shindrell Prestefeu, à Astranaar."}}
D[1009] = {"Ruuzel",{"Apporter l'Anneau de Zoram à Talen près de la grève de Zoram."}}
D[1010] = {"Les Cheveux de Bathran",{"Rapporter 5 Cheveux de Bathran à Orendil Largefeuille dans Orneval."}}
