D[1018] = {"La nouvelle frontière",{"Parler à l'archidruide Hamuul Totem-runique, sur la Cime des Anciens des Pitons du Tonnerre. Évoquer l'appel du Cercle cénarien concernant l'exploration des frontières de Kalimdor."}}
D[1019] = {"La nouvelle frontière",{"Parler à l'archidruide Fandral Forteramure, dans l'Enclave cénarienne, à Darnassus. Évoquer l'appel du Cercle cénarien concernant l'exploration des frontières de Kalimdor."}}
D[1020] = {"Jouvence d'Orendil",{"Apporter la Jouvence d'Orendil à Pelturas Blanchelune dans Astranaar."}}
D[1021] = {"Vil satyre ! dryades en danger !",{"Trouver Anilia dans Xavian."}}
D[1022] = {"Le Val hurlant",{"Allez au Val hurlant et étudiez le Tome de Mel'Thandris, puis retournez voir la Sentinelle Melyria Ombregivre au Chant des forêts."}}
D[1023] = {"Le nettoyage selon Raene",{"Trouver la Gemme luminescente et retourner voir Raene Mène-loup dans Astranaar avec le Journal de Teronis."}}
