D[1027] = {"Le nettoyage selon Raene",{"Trouver le dernier morceau du Bâtonnet de Dartol et retourner voir Shael'dryn au puits de lune."}}
D[1028] = {"Le nettoyage selon Raene",{"Trouver l'Autel caché et recharger le Bâtonnet de Dartol."}}
D[1029] = {"Le nettoyage selon Raene",{"Retourner voir Raene Wolfrunner à Astranaar."}}
D[1030] = {"Le nettoyage selon Raene",{"Trouver un furbolg non corrompu et lui parler en utilisant le pouvoir du Bâtonnet de transformation de Dartol."}}
D[1031] = {"La branche de Cénarius",{"Tuer Geltharis et rendre la Branche de Cénarius à Illiyana au Chant des forêts."}}
