D[1153] = {"Un nouveau minerai",{"Trouver un échantillon de minerai brut sur un Mineur ou un Géomètre Mufle-de-gravier et l'apporter à Tatternack Forgacier, au Camp Taurajo dans les Tarides."}}
D[1154] = {"L'épreuve de la Connaissance",{"Trouver l'Héritage des Aspects et l'apporter à Braug Esprit-troublé, à côté de l'entrée de la Perce des Serres, dans les Serres-Rocheuses."}}
D[1159] = {"L'épreuve de la Connaissance",{"Trouver Parqual Fintallas à Fossoyeuse."}}
