D[1690] = {"Châtier les Bat-le-désert",{"Abattre 10 Bandits et 10 Larrons Bat-le-désert à l'est de Gadgetzan, puis revenir au rapport auprès de l'ingénieur en chef Vizisanie."}}
D[1691] = {"Continuer à châtier les Bat-le-désert",{"Tuer 10 Mages de l'ombre Bat-le-désert, 8 Voleurs Bat-le-désert et 6 Assassins Bat-le-désert pour l'ingénieur en chef Vizisanie à Gadgetzan."}}
D[1692] = {"Forgeron Mathiel",{"Apporter la Caisse d'élunite au Forgeron Mathiel."}}
D[1693] = {"Armes en Elunite",{"<nom>, j'ai fabriqué ces armes avec l'Elunite que vous m’avez apportée. Prenez celle qui vous convient.","","Et je dois vous remercier. Car travailler l'Elunite est un honneur et un plaisir."}}
D[1698] = {"Yorus Barleybrew",{"Parler à Yorus Brasselorge."}}
D[1699] = {"Le défi de Rethban",{"Entrer dans les Cavernes de Rethban jusqu'à la première fourche, et revenir voir Brasselorge dans le temps imparti.","","Vous ne devez pas mourir et libérer votre esprit."}}
D[1700] = {"Grimand Elmore",{"Porter les Notes de Furen à Grimand Elmore."}}
D[1701] = {"Une cotte de mailles en acier trempé",{"Réunir les matériaux dont Furen Barbe-longue a besoin et lui apporter à Hurlevent."}}
D[1702] = {"Fabricant de bouclier",{"Apporter la Barrique de Scalder à Furen Barbe-longue."}}
D[1703] = {"Mathiel",{"Apporter les Notes de Furen à Mathiel."}}
D[1704] = {"Pléthorloge Cléventail",{"Apporter les Notes de Furen à Pléthorloge Cléventail."}}
D[1705] = {"Le sang ardent",{"Rapporter 20 Fioles de sang ardent et 1 Roc ardent à Grimand Elmore à Hurlevent."}}
D[1706] = {"L'armure de Grimand",{"Je peux à peine le croire ! La technique de Furen fonctionne, et cette armure peut résister à des coups incroyables.","","Voilà pour vous, <nom>. Et merci. Je n'y aurais pas cru si vous ne m'aviez pas apporté les éléments nécessaires pour le tester moi-même."}}
D[1707] = {"Prime de la poche à eau",{"Apporter 5 Outres de Bat-le-désert à l'Opérateur du robinet Trimballot à Gadgetzan."}}
D[1708] = {"Le corail de fer",{"Apporter 20 Coraux torrides à Pléthorloge Cléventail à Forgefer."}}
D[1709] = {"La création de Pléthorloge",{"Voilà votre armure, <nom>. Le procédé de Furen fonctionne à la perfection ! À la perfection ! Merveilleux, vraiment !","","Vous pourriez rouler sur cette armure avec un engin de siège, elle reprendrait sa forme en un instant !"}}
D[1710] = {"Coquilles desséchées au soleil",{"Apporter 20 Coquilles desséchées au soleil à Mathiel à Darnassus."}}
D[1711] = {"L'armure de Mathiel",{"J'ai fini votre armure, et j'en suis satisfait. Les techniques de Furen cadrent parfaitement avec les miennes et je suis sûr que cette armure est extrêmement résistante.","","Merci, <nom>. Et qu'elle vous serve pour vos combats futurs !"}}
