D[1780] = {"Le Tome de divinité",{"Parler à Duthorian Rall à Hurlevent."}}
D[1781] = {"Le Tome de divinité",{"Porter le Symbole de vie à Gazin Tenorm à Hurlevent."}}
D[1782] = {"L'armure de Furen",{"Voici votre armure, <nom>. Elle résistera au plus dur des coups ou je ne m'appelle pas Furen Longbeard !","","Et je dois vous remercier. J'ai beaucoup appris en travaillant les matériaux que vous m'avez apportés. Je pense que je ferai une autre découverte capitale un de ces jours !","","Je vais transmettre ce que j'ai appris aux autres forgerons de l'Alliance.","","Je leur dirai que vous m'avez été d'une grande aide, et peut-être qu'ils vous récompenseront."}}
D[1783] = {"Le Tome de divinité",{"Prendre le Symbole de vie et ressusciter Narm Faulk dans Dun Morogh."}}
D[1784] = {"Le Tome de divinité",{"Récupérer un Script des nains Sombrefer près du lac du Lit d'Helm et le rapporter à Muiredon Forgeguerre à Forgefer."}}
D[1785] = {"Le Tome de divinité",{"Parler à Tiza Forgeguerre à Forgefer."}}
D[1786] = {"Le Tome de divinité",{"Apporter le Symbole de vie et ressusciter Henze Faulk à Elwynn."}}
D[1787] = {"Le Tome de divinité",{"Retrouver un Script Défias sur les Sorciers-voleurs défias d'Elwynn et le rapporter à Gazin Tenorm à Hurlevent."}}
D[1788] = {"Le Tome de divinité",{"Parler à Duthorian Rall à Hurlevent."}}
D[1789] = {"Le Symbole de vie"}
D[1790] = {"Le Symbole de vie",{"Hâtez-vous, <nom>, de nombreuses vies seront en danger si vous échouez.","","Si pour une raison quelconque vous n'arrivez pas à aider Gazin et Henze, revenez me voir et je vous donnerai un autre Symbole de vie pour cette entreprise.","","Ne prenez pas cela pour de la charité : vous devez prouver que vous êtes un <classe> aussi brave que les autres, et des échecs répétés auraient des répercussions plus tard."}}
D[1791] = {"La Vigie des vents",{"Parler à Bath'rah la Vigie des vents."}}
D[1792] = {"Arme Tourbillon",{"J'ai le Cœur de tourbillon, et je suis prêt à le placer dans le réceptacle de votre choix.","","Choisissez l'arme, <nom>, et sachez que ce pouvoir est le pouvoir du Cyclonien."}}
D[1793] = {"Le Tome de la bravoure",{"Il a été prouvé que la Lumière était avec vous, <nom>, mais en ces temps de grands dangers, il est primordial de savoir quelles sont vos forces. Parce que des démons, des dragons et toutes sortes de créatures malfaisantes convoitent nos terres, votre courage sera mis à l'épreuve. Serez-vous assez fort ?","","La bravoure, quelle que soit la situation, est une part importante de la voie du <classe>, au même titre que la Lumière, votre armure et votre arme. Quand vous étudiez dans la cathédrale de la Lumière, les deux leçons que vous devez apprendre sont : protéger les faibles et ne jamais perdre la foi."}}
D[1794] = {"Le Tome de la bravoure"}
D[1795] = {"Le lien",{"Utiliser le Tome de la Cabale pour invoquer et soumettre un Chasseur corrompu, puis rapporter le Tome de la Cabale à Strahad Farsan, à Cabestan."}}
D[1796] = {"Les composants de la robe sanglante dorée enchantée",{"Apporter une Robe d'Arcana à Menara Taillevide, dans les Tarides."}}
D[1798] = {"À la recherche de Strahad",{"Parler à Strahad Farsan dans les Tarides."}}
D[1799] = {"Fragments de l'Orbe d'Orahil",{"Parler aux acolytes de Menara dans la tour qui domine Cabestan et choisir de suivre l'une de leurs voies.","","Ensuite, apporter un Orbe infernal à Tabetha, dans le marécage d'Âprefange."}}
D[1800] = {"La salle du trône de Lordaeron",{"Emmenez votre protégé à la vieille salle du trône de Lordaeron, qui se trouve juste avant l'endroit où il faut descendre pour aller à Fossoyeuse."}}
