D[1843] = {"Gantelets de brutalité",{"Merci, <nom>. Ces Gantelets sont ma plus belle réussite. Prenez-les. En les portant, vous nous honorerez, moi et mes ancêtres."}}
D[1844] = {"La corne de chimère",{"Apporter une Corne galvanisée à Orm Sabot-de-pierre aux Pitons du Tonnerre."}}
D[1845] = {"Camail de brutalité",{"Je vous donne ce casque.","","Ce sont vos actes héroïques qui vous ont conduit jusqu'à moi, <nom>, et la volonté de notre Mère la Terre... Des actes encore plus héroïques vous attendent."}}
D[1846] = {"Les tibias de Dragonmaw",{"Apporter 8 Solides tibias de Gueule-de-dragon à Velora Nitely, à Fossoyeuse."}}
D[1847] = {"Jambières de brutalité",{"Voici vos jambières, <nom>. Dites-moi si cela vous convient ou si vous avez besoin de modifications. J'essaie toujours de satisfaire mon client ! Du moins j'essayais.","","En ce moment, je ne me soucie pas beaucoup de mon métier. Mais ça met hors jeu d'être un stupide pion du Fléau !","","Je suppose…"}}
D[1848] = {"Le haubert de brutalité",{"Je sais que vous avez enduré beaucoup de privations et versé beaucoup de sang à mon service, <nom>. Voici le fruit de votre dur labeur.","","Puissiez-vous bien le porter et revenir ici un jour pour me conter les services qu'il vous aura rendus."}}
D[1858] = {"La Main brisée",{"Voler la Clé de Tazan puis l'utiliser pour ouvrir sa Sacoche et livrer son contenu à Therzok dans la Faille de l'ombre à Orgrimmar."}}
D[1859] = {"Therzok",{"Aller voir Therzok dans la Faille de l'ombre à Orgrimmar."}}
D[1860] = {"Parler à Jennea",{"Parler à Jennea Cannon à Hurlevent."}}
D[1861] = {"Le lac Miroir",{"Apporter un échantillon d'Eau du lac Miroir à Jennea Cannon à Hurlevent."}}
D[1878] = {"Prime de la poche à eau",{"Vous revoici, <nom> ? Si vous avez cinq outres de Bat-le-désert de plus, alors j'ai un paquet qui porte votre nom !"}}
D[1879] = {"Parler à Bink",{"Parler à Bink à Forgefer."}}
D[1880] = {"Le Bidulotron de youplala",{"Rapporter à Bink son Bidulotron de Youplala."}}
D[1881] = {"Parler à Anastasia",{"Aller voir Anastasia Hartwell."}}
D[1882] = {"La ferme des Balnir",{"Apporter des Gueules-de-loup du jardin des Balnir à Anastasia Hartwell dans le Quartier des mages de Fossoyeuse."}}
D[1883] = {"Parler à Un'thuwa",{"Aller voir Un'thuwa."}}
D[1884] = {"Les Tas de Ju-Ju",{"Détruire 4 Tas de Ju-Ju, puis retourner voir Un'thuwa au village de Sen'jin."}}
D[1885] = {"Mennet Carkad",{"Aller voir Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}}
D[1886] = {"Les Traqueurs noirs",{"Trouver la Lettre de recommandation d'Astor et l'apporter à Mennet Carkad dans le Quartier des voleurs."}}
D[1898] = {"Les Traqueurs noirs",{"Aller voir Andron Gant à Fossoyeuse."}}
D[1899] = {"Les Traqueurs noirs",{"Apporter le Grand Livre d'Andron à Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}}
D[1918] = {"Les éléments souillés",{"Apporter le Globe d'eau souillée à Mastok Torvesiffle, au Poste de Bois-brisé, à Orneval."}}
D[1919] = {"Rendre compte à Jennea",{"Parler à Jennea Cannon à Hurlevent."}}
D[1920] = {"Trouver le Solitaire bleu",{"Obtenir un Chant de manifestation et une Caisse de coffres de retenue placée derrière Jennea Cannon. Apporter 3 Coffres de retenue remplis à Jennea Cannon au Sanctuaire du sorcier."}}
D[1921] = {"Rassembler les matériaux",{"Apporter 10 morceaux d'Etoffe de lin et 6 Gemmes chargées de la faille à Wynne Larson à Hurlevent."}}
D[1938] = {"Traité d'Ur sur la Magie des Ombres",{"Apporter le « Traité d'Ur sur la magie des Ombres » au Grand Sorcier Andromath à Hurlevent."}}
D[1939] = {"Grand sorcier Andromath",{"Aller voir le Grand Sorcier Andromath."}}
D[1940] = {"Soie d'araignée en parfait état",{"Apporter 8 Soies d'araignée en parfait état à Wynne Larson à Hurlevent."}}
D[1941] = {"La robe en tisse-mana",{"Voici votre robe. C'est l’une des plus belles que j'ai confectionnées ! Portez-la avec fierté. Et si les gens vous interrogent, dites-leur qu'elle sort de l’atelier des couturiers Larson !"}}
D[1942] = {"L'Habit du noeud astral",{"Votre habit est prêt. Cette soie que vous avez apportée était si belle... Ça ne vous fait rien si je l'ai cousu un peu court pour pouvoir en conserver un morceau ?","","Mais non, je plaisante ! Il vous ira comme un gant, au plus fort de l'aventure comme dans les occasions plus mondaines ! Profitez-en bien !"}}
D[1943] = {"Parler à Deino",{"Aller voir Deino."}}
D[1944] = {"Les Eaux de Xavian",{"Apporter l'Échantillon d'Eau de Xavian à Deino à Orgrimmar."}}
D[1945] = {"Les sœurs rieuses",{"Apporter 12 Cheveux de sœurs rieuses à Kil'hala à la Croisée."}}
D[1946] = {"L'Habit du néant",{"Voici votre robe du Néant, <nom>. À la fois confortable et solide, elle contient la magie des cheveux des sœurs rieuses.","","Si elle vous plaît, parlez-en à Deino. C'est un <classe> d'une telle puissance que je préfère être de son côté !"}}
D[1947] = {"Voyager vers le Marais",{"Aller voir Tabetha."}}
D[1948] = {"Les Objets de Puissance",{"Apporter 1 Jade et le Roncier de foudre à Tabetha, dans le marécage d'Âprefange."}}
D[1949] = {"Des secrets cachés",{"Parler au magus Tirth dans les Salines."}}
D[1950] = {"Trouver le Scoop",{"Trouver l'Incantation pour ouvrir le coffre-fort de Tirth puis retourner voir Tirth."}}
D[1951] = {"Rituels du Pouvoir",{"Apporter le livre des « Rituels du pouvoir » à Tabetha dans le marécage d'Âprefange."}}
D[1952] = {"La baguette du mage",{"Parler à Tabetha après son rituel."}}
D[1953] = {"Retourner dans le Marais",{"Aller voir Tabetha."}}
D[1954] = {"L'orbe infernal",{"Apporter un Orbe infernal à Tabetha dans le marécage d'Âprefange."}}
D[1955] = {"L'Exorcisme",{"Tuer le démon de l'Orbe puis parler à Tabetha."}}
D[1956] = {"L'Energie d'Uldaman",{"Récupérer une Source d'énergie en obsidienne et la rapporter à Tabetha dans le marécage d'Âprefange."}}
D[1957] = {"Les éruptions de mana",{"Tuer 12 Eruptions de mana dans la limite de temps imposée."}}
D[1958] = {"L'énergie céleste",{"Vous pouvez ressentir de la fierté, <nom>. Bien des mages auraient échoué face aux créatures que vous avez affrontées !","","L'Orbe céleste est prêt. Je peux aussi le fixer sur un bâton, c'est à vous de choisir. Moi, je choisirais l'Orbe, mais qui suis-je pour avoir un avis ?"}}
D[1959] = {"Rendre compte à Anastasia",{"Aller voir Anastasia Hartwell."}}
D[1960] = {"Enquêter dans le magasin de l'Alchimiste",{"Obtenir une Incantation de Manifestation et une Caisse de Coffres de retenue placée derrière Anastasia Hartwell. Apporter 3 Coffres de retenue remplis, la Caisse de Coffres de retenue et l'Incantation de Manifestation à Anastasia Hartwell à Undercity."}}
D[1961] = {"Rassembler les matériaux",{"Apporter 10 morceaux d'Etoffe de lin et 6 Gemmes de mana de Dalaran à Josef Gregorian."}}
D[1962] = {"Robe du feu-sorcier",{"Voici votre robe, <nom>. Portez-la bien."}}
D[1963] = {"La Main brisée",{"Tuer Tazan et apporter sa Sacoche à Therzok, à la Faille de l'ombre à Orgrimmar."}}
D[1978] = {"Les Traqueurs noirs",{"Livrer le Grand Livre d'Andron à Varimathras au Hall de la Dame noire à Fossoyeuse."}}
D[1998] = {"Fenwick Thatros",{"Tuer Fenwick Thatros et rapporter sa Tête à Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}}
D[1999] = {"Les outils du métier",{"Trouver le Rapport de situation de Dalaran et le remettre à Mennet Carkad dans le Quartier des voleurs de Fossoyeuse."}}
D[2000] = {"Rokar Ombrelame",{"Aller voir Rokar Ombrelame en Durotar."}}
D[2018] = {"L'épreuve de Rokar",{"Tuer le Surveillant Glibby et apporter son Sifflet à Rokar Ombrelame en Durotar."}}
D[2019] = {"Les outils du métier",{"Retourner voir Therzok à la Faille de l'Ombre à Orgrimmar."}}
D[2038] = {"Les fournitures perdues de Bingles",{"Trouver et rapporter à Bingles son matériel :","","La Clé de Bingles, le Tournevis de Bingles, le Marteau de Bingles et le Capsuleur soufflant de Bingles."}}
D[2039] = {"Trouvez Bingles",{"Trouver Bingles Explonheimer, au Loch Modan."}}
D[2040] = {"Assaut souterrain",{"Récupérer l'Indicateur Gnoam dans les mortemines et le ramener à Shoni la Silencieuse à Hurlevent."}}
D[2041] = {"Allez voir Shoni",{"Aller voir Shoni la Silencieuse à Hurlevent."}}
D[2078] = {"La vengeance de Gyromast",{"Trouver le Premier officier de Gelkak, le Destructomembreur 4100, et le ramener à Gelkak."}}
D[2098] = {"La recherche de Gyromast",{"Trouver et rapporter les 3 Morceaux de la clé de Gelkak à Gelkak Gyromast."}}
D[2118] = {"Terres malades",{"Capturer vivant un Ours des chardons enragé, puis le ramener à Tharnariun."}}
D[2138] = {"Nettoyage de l'infection",{"Débarrasser la forêt de 20 Ours des chardons enragés et retourner voir Tharnariun Soigneflore, à Sombrivage."}}
D[2139] = {"Espoir de Tharnariun",{"Trouver et tuer la Mère de la tanière."}}
D[2158] = {"Repos et détente",{"Parler à l'aubergiste Farley, à l'auberge de la Fierté du lion."}}
D[2159] = {"Livraison à Dolanaar",{"Apporter la Livraison de Dolanaar à l'aubergiste Keldamyr."}}
D[2160] = {"Des provisions pour Tannok",{"Livrer la Caisse de ravitaillement à l'auberge de Tannok Martel-de-givre à Kharanos."}}
D[2161] = {"Un Fardeau de Péon",{"Apporter le Fardeau d'Ukor à l'aubergiste Grosk à Tranchecolline."}}
D[2178] = {"Brouet de trotteur",{"Apporter 5 morceaux de Viande de trotteur à Alanndarian Chantenuit, à Auberdine."}}
D[2198] = {"Le Collier brisé",{"Chercher celui qui a fabriqué le Collier brisé pour découvrir sa valeur potentielle."}}
D[2199] = {"Le Prix de la Connaissance",{"Apporter 5 Barres d'Argent à Talvash del Kissel, à Forgefer."}}
D[2200] = {"Retour à Uldaman",{"Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l'avoir porté."}}
D[2201] = {"Trouver les Gemmes",{"Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Fiole de divination qu’il vous a donnée précédemment.","","C'est dans le journal, vous savez...","* Le rubis a été caché dans une zone barricadée des Ombreforge.","* La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance.","* Le saphir est en possession du chef trogg, Grimlok."}}
D[2202] = {"Rechercher les composants à Uldaman",{"Apporter 12 Champignons magenta à Jarkal Fondemousse à Kargath."}}
D[2203] = {"Les réactifs des Terres ingrates II",{"Utiliser les 3 Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Jarkal Fondemousse à Kargath."}}
D[2204] = {"Réparer le Collier",{"Obtenir une Source d'énergie de la construction la plus puissante que vous pouvez trouver à Uldaman, puis la remettre à Talvash del Kissel à Ironforge."}}
D[2205] = {"Chercher le SI:7",{"Remettre le colis de Keryn Sylvius à maître Mathias Shaw à la Caserne de Hurlevent."}}
D[2206] = {"Effraction",{"Trouver le maître des docks défias et récupérer le programme d'embarquement, pour le compte de maître Mathias Shaw."}}
D[2218] = {"La voie du salut",{"Parler à Hulfdan Barbe-noire à Forgefer."}}
D[2238] = {"Simple subterfuge",{"Trouver Onin MacHammar à Gnomeregan."}}
D[2239] = {"Rapport d'Onin",{"Porter le rapport d'Onin à Hulfdan à Forgefer."}}
D[2240] = {"La Chambre secrète",{"Lire le journal de Baelog, explorer la Chambre secrète, puis rendre compte au Prospecteur Foudrepique."}}
D[2241] = {"Pomme d'amour",{"Porter la Rose de Jannok à Syurna à Darnassus."}}
D[2242] = {"L'appel du destin",{"Trouver Sethir l'Ancien et rapporter tout indice découvert à Syurna."}}
D[2258] = {"Les réactifs des Terres ingrates",{"Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche à Jarkal Fondemousse, à Kargath, dans les Terres ingrates."}}
D[2259] = {"Erion Murmombre",{"Contacter Erion Murmombre à Darnassus."}}
D[2260] = {"L'ordre d'Erion",{"Voyager vers Hurlevent pour y rencontrer Renzik \"le Kriss\"."}}
D[2278] = {"Les Disques de platine",{"Parler au Gardien des pierres pour connaître le Savoir qu'il défend. Une fois découvert ce qu'ils peuvent offrir, activer les Disques de Norgannon."}}
D[2279] = {"Les Disques de platine",{"Apporter la version miniature des Disques de Norgannon à la Ligue des Explorateurs à Forgefer."}}
D[2280] = {"Les Disques de platine",{"Apporter la version miniature des Disques de Norgannon à l'un des Sages de Thunder Bluff."}}
D[2281] = {"Le Rendez-vous des Carmines",{"S'aventurer vers Comté-du-lac dans les Carmines et parler à Lucius."}}
D[2282] = {"La scierie d'Alther",{"Ouvrir le Coffret de Lucius, récupérer le Gage de voleur et le rapporter à Lucius à Comté-du-lac."}}
D[2283] = {"Réparer le Collier",{"Rechercher dans l'excavation d'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé."}}
D[2284] = {"Réparer le Collier, deuxième prise",{"Trouver, dans les profondeurs d'Uldaman, des indices sur la localisation des Gemmes."}}
D[2298] = {"Kingly Shakedown",{"Aller à Hurlevent et chercher Renzik \"le Kriss\"."}}
D[2299] = {"Cap sur Hulfdan !",{"Se rendre à Forgefer et parler à Hulfdan Barbe-noire."}}
D[2300] = {"SI:7",{"Aller à Hurlevent et chercher Renzik \"le Kriss\"."}}
D[2318] = {"La Traduction du Journal",{"Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates."}}
D[2338] = {"La traduction du Journal",{"Laisser Jarkal emprunter le Collier en échange de la traduction du Journal."}}
D[2339] = {"Trouver les Gemmes et la Source d'énergie",{"Récupérer, dans Uldaman, les trois gemmes et une source d'énergie pour le collier, puis les rapporter à Jarkal Fondemousse, à Kargath. Jarkal pense que vous pouvez trouver une source d'énergie sur la machine la plus puissante d'Uldaman.","","C'est dans le journal, vous savez...","* Le rubis a été caché dans une zone barricadée des Ombreforge.","* La topaze a été dissimulée dans une urne, dans l'une des zones trogg, pas très loin de nains de Alliance.","* Le saphir est possession du chef trogg, Grimelok."}}
D[2340] = {"Livrer les Gemmes",{"Apporter Les gemmes et le collier récupérés à Dran Droffers, à Orgrimmar."}}
D[2341] = {"Réparer le collier, troisième prise",{"Rendre visite à Jarkal Fondemousse à Kargath pour constater (ou non) son succès."}}
D[2342] = {"Des Trésors à recouvrer",{"Rapporter à Patrick Garrett, à Fossoyeuse, son Trésor de famille, qui se trouve dans le Coffre de famille dans les communs du sud d'Uldaman."}}
D[2358] = {"Cornes de Nez'ra",{"Rapporter les Cornes de Nez'ra à Arantir, à Comté-du-Lac."}}
D[2359] = {"La Tour de Klaven",{"Voler la Clé de la Tour défias, pénétrer dans la Tour et trouver ce que contient le Coffre du bois de la Pénombre. Rapporter les informations à Mathias Shaw à Hurlevent. Lire le journal de Kearnen pour savoir ce qui se passe dans la tour."}}
D[2360] = {"Mathias et les Défias",{"Se rendre dans la marche de l'Ouest et trouver l'Agent Kearnen pour un débriefing."}}
D[2361] = {"Réparer le Collier",{"C'est avec joie que je vous donne ce collier, <classe>. Vous m'avez rendu un service inestimable. Portez-le avec fierté et n'hésitez pas à citer fréquemment et à voix haute le nom du fabriquant !","","Et si vous pouviez préciser au passage qu'il n'est pas maudit, ce serait parfait."}}
D[2378] = {"Trouver la Main brisée",{"Voyager vers Orgrimmar pour y parler à Shenthul, dans la Faille de l'ombre."}}
D[2379] = {"Zando'zan",{"Parler à Zando'zan à la Faille de l'ombre."}}
D[2380] = {"Cap sur Orgrimmar !",{"S'adresser à Shenthul à la Faille de l'ombre à Orgrimmar."}}
D[2381] = {"Piller les Pilleurs",{"Rapporter le Trésor des Mers du sud à Wrenix le Misérable à Cabestan. Ne pas oublier d'obtenir un B.G.A.C. et des Outils de voleur de l'Appareil bidulotronique de Wrenix. Ces deux éléments sont nécessaires pour accomplir la mission.","","En cas d'attaque par des perroquets particulièrement hostiles, utiliser le B.G.A.C.!"}}
D[2382] = {"Wrenix de Ratchet",{"Aller jusqu'à Cabestan pour voir Wrenix le Misérable."}}
D[2383] = {"Parchemin simple",{"Lire le Simple parchemin, et parler à Frang, dans la Vallée des épreuves."}}
D[2398] = {"Les nains perdus",{"Trouver Baelog dans Uldaman."}}
D[2399] = {"Les racines ont poussé",{"Les racines que Denalan a plantées dans son jardin ont poussé et grandi. Elles tremblent, désireuses d'être choisies..."}}
D[2418] = {"Les pierres de puissance",{"Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates."}}
D[2438] = {"Le Capturêve d'émeraude",{"Apporter le Capturêve d'émeraude à Tallonkai Viveracine à Dolanaar."}}
D[2439] = {"Les Disques de platine",{"Apporter le Bon de récompense à Dinita Mantepierre à la Chambre forte de Forgefer."}}
D[2440] = {"Les Disques de platine",{"Apporter le Bon de récompense à Bena Sabot-d'hiver aux Pitons du Tonnerre."}}
D[2458] = {"Sous le couvert de la nuit",{"Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l'agent secret de la Main brisée, le sous-chef Fizzule.","","Une fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s'approcher du sous-chef Fizzule et faire le Salut brisé (/salut).","","Respecter l'ordre de ces actions, car Fizzule attaque et tue toute personne qu'il ne peut pas identifier."}}
D[2459] = {"Ferocitas le Mangeur de rêves",{"Tallonkai Viveracine, de Dolanaar, vous demande de tuer 7 Mystiques Pins-tordus et retrouver le Bijou disparu."}}
D[2460] = {"Le Salut brisé",{"Faire le Salut brisé à Shenthul."}}
D[2478] = {"Mission : possible mais non probable",{"Voler la Clé de la tour de Silixiz au Contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk.","","Assassiner le Grand contremaître Bisbiwix et prendre sa tête. Ouvrir le coffre de Bisbiwix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Bisbiwix à Shenthul à Orgrimmar, et attendre de nouvelles instructions."}}
D[2479] = {"L'aide d'Hinott",{"Aller à Moulin-de-Tarren dans les contreforts de Hautebrande et livrer l'Échantillon de la mixture de Zanzil à Serge Hinott.","","Pour rejoindre Moulin-de-Tarren, prenez le zeppelin à Fossoyeuse et suivez la route du sud, à travers les Pins argentés et vers Hautebrande. Suivez les panneaux !"}}
D[2480] = {"L'aide d'Hinott",{"Attendre Serge Hinott pour achever le remède."}}
D[2498] = {"Retour vers Denalan",{"Rellian Vertecime vous demande d'aller parler à Denalan au lac Al'Ameth."}}
D[2499] = {"Froncechêne",{"Denalan, au lac Al'Ameth, vous demande d'ôter la Tumeur gargantuesque de Froncechêne."}}
D[2500] = {"Les réactifs des Terres ingrates",{"Aller chercher les réactifs dont Ghak Healtouch a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar."}}
D[2501] = {"Les réactifs des Terres ingrates II",{"Utiliser les Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Ghak Touchesoins à Thelsamar."}}
D[2518] = {"Les larmes de la Lune",{"Apporter les Filières d'argent de dame Sathrah à la prêtresse A'moora, au temple de la Lune, à Darnassus."}}
D[2519] = {"Le Temple de la Lune",{"Sœur Aquinne veut que vous parliez à la prêtresse A'moora, au temple de la Lune."}}
D[2520] = {"Sacrifice de Sathrah",{"La prêtresse A'moora vous demande de placer les Filières d'argent de dame Sathrah dans la fontaine à l'intérieur du temple, puis de retourner la voir."}}
D[2521] = {"Au service de Kum'isha",{"Si vous trouvez une sphère de draenéthyste sans défaut au hasard des voyages dans les Terres foudroyées, apportez-la à Kum'isha le Collecteur.","","Cette gemme, l'une des plus rares de tout Azeroth, peut être détenue par n'importe qui dans le pays.","","Une récompense sera donnée pour chaque sphère de draenéthyste sans défaut trouvée et rapportée."}}
D[2522] = {"Les efforts de Kum'isha",{"Trouver une Sphère de draenéthyste sans défaut et l'apporter à Kum'isha le Collecteur."}}
D[2523] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[2541] = {"Le druide endormi",{"Rapporter un Charme vaudou de chaman à Oben Grifferage dans le Refuge des saisons de Ban'ethil."}}
D[2561] = {"Le druide de la Griffe",{"Oben Grifferage vous demande de tuer son corps privé d'âme et d'utiliser ensuite le Charme vaudou."}}
D[2581] = {"Joues de Raillecroc",{"Apporter 3 Joues de Raillecroc, 2 Poumons de sanglier éclatés et 1 Pince de scorpok au Mage de sang Drazial."}}
D[2582] = {"La colère des âges",{"Apporter 3 Joues de Raillecroc, 2 Poumons de sanglier éclatés et 1 Pince de scorpok au Mage de sang Drazial."}}
D[2583] = {"La vitalité du sanglier",{"Apporter 3 Poumons de sanglier éclatés, 2 Pinces de scorpok et 1 Cerveau de basilic au Mage de sang Drazial."}}
D[2584] = {"L'esprit du sanglier",{"Apporter 3 Poumons de sanglier éclatés, 2 Pinces de scorpok et 1 Cerveau de basilic au Mage de sang Drazial."}}
D[2585] = {"Le coup décisif",{"Apporter 3 Pinces de scorpok, 2 Gésiers de vautour et 1 Poumon de sanglier éclaté au mage de sang Drazial."}}
D[2586] = {"Le sel de scorpok",{"Apporter 3 Pinces de scorpok, 2 Gésiers de vautour et 1 Poumon de sanglier éclaté au mage de sang Drazial."}}
D[2601] = {"La morsure du basilic",{"Apporter 10 Cerveaux de basilic et 2 Gésiers de vautour au Mage de sang Lynnore."}}
D[2602] = {"Un esprit infaillible",{"Apporter 10 Cerveaux de basilic et 2 Gésiers de vautour au Mage de sang Lynnore."}}
D[2603] = {"La vigueur du vautour",{"Apporter 10 Gésiers de vautour et 2 Joues de Raillecroc au Mage de sang Lynnore."}}
D[2604] = {"Domination spirituelle",{"Apporter 10 Gésiers de vautour et 2 Joues de Raillecroc au Mage de sang Lynnore."}}
D[2605] = {"Le gobelin assoiffé",{"Trouver une Glande à rosée remplie et l'apporter à Marin Brouillecaboche à Gadgetzan."}}
D[2606] = {"De bon goût",{"Marin Brouillecaboche vous demande d'aller voir Saupoudr à Gadgetzan."}}
D[2607] = {"Le toucher de Zanzil",{"Aller voir le docteur Mixilpixil dans la Cave de la caserne."}}
D[2608] = {"Le toucher de Zanzil",{"S'allonger (/coucher) pour être <examiné/examinée> par le docteur Mixilpixil. Comment peut-il trouver le remède s'il ne peut pas trouver la cause ?"}}
D[2609] = {"Le toucher de Zanzil",{"Apporter au docteur Mixilpixil une Brassée de Fleurs sauvages simples, une Fiole plombée, un Tube en Bronze et une Bobine de Fil de soie chartreuse. Le itis ne guérit pas tout seul."}}
D[2621] = {"Le déshonoré",{"Aller voir le commandant d'ordonnance Ruag dans Pierrêche."}}
D[2622] = {"Les ordres disparus",{"Aller voir Bengor."}}
D[2623] = {"Le Parleur des marécages",{"Retrouver les Ordres du Chef de guerre et les rendre au Héros de la Horde tombé au combat."}}
D[2641] = {"L'ingrédient secret de Sprinkle",{"Saupoudr, de Gadgetzan, vous demande de cueillir un Tragan violet et de le lui apporter."}}
D[2661] = {"Livraison pour Marin",{"Saupoudr vous demande d'apporter la Poudre violette à Marin Brouillecaboche à Gadgetzan."}}
D[2662] = {"Elixir Brouillecaboche",{"Retourner voir Marin Brouillecaboche une fois qu'il aura créé son élixir."}}
D[2681] = {"Les pierres qui nous lient",{"Libérer 9 Serviteurs de Razelikh, 3 Serviteurs de Sevine, 3 Serviteurs d'Allistarj et 3 Serviteurs de Grol. Retourner voir le Héros de la Horde tombé au combat une fois la tâche terminée. Il faut rester à proximité des pierres ou le processus échouera."}}
D[2701] = {"Les héros des Anciens",{"Ouvrir le coffre et prendre la récompense."}}
D[2702] = {"Les héros des Anciens",{"Aller voir le caporal Thund Sabot-fendu."}}
D[2721] = {"Kirith",{"Découvrir ce qui est arrivé au Lieutenant Kirith."}}
D[2741] = {"Le Super-Oeuf-O-Matic",{"Le Super-Oeuf-O-Matic est la dernière des inventions de Curgle Cranklehop. C'est une machinerie très impressionnante.","","Le Super-Oeuf-O-Matic bafouille quelque chose lorsque vous vous approchez du panneau de commande."}}
D[2742] = {"Rin'ji est pris au piège !",{"Escorter Rin'ji hors du Gîte de Quel'Danil, puis découvrir son secret caché sur les Hauts-Surplombs, à l'est."}}
D[2743] = {"Le couvert de l'obscurité",{"Retourner voir le Héros déchu de la Horde avec ces découvertes."}}
D[2744] = {"Le chasseur de démons",{"Aller voir Loramus Thalipedes à Azshara."}}
D[2745] = {"En infiltrant le Château",{"Aller voir Tyrion au Château de Hurlevent."}}
D[2746] = {"Des objets d’une certaine importance",{"Apporter 3 Etoffes de soie et 2 Pommes fraîches de Clara à Tyrion à Hurlevent."}}
D[2747] = {"Un œuf extraordinaire",{"J'ai rarement vu des œufs récupérés en Feralas dans un état satisfaisant. Ces œufs comptent parmi les plus rares…"}}
D[2748] = {"Un œuf de premier choix",{"Un œuf de premier choix est un œuf qui, dans des conditions idéales, va éclore libre des effets néfastes des incantations des ogres Gordunni."}}
D[2749] = {"Un œuf ordinaire",{"Les œufs ordinaires d'hippogryphes éclosent une fois sur deux. Nous faisons de notre mieux pour les élever et avec une petite chance, ils écloront."}}
D[2750] = {"Un mauvais œuf",{"Ces œufs-là ne peuvent pas être sauvés : ils n'écloront jamais."}}
D[2751] = {"Remparts barbares",{"Apporter 2 Brassards guillochés en bronze, 2 Glaives en bronze et 2 Griffes aiguisées à Orokk Omosh à Orgrimmar."}}
D[2752] = {"Épaulettes en fer",{"Apporter 4 Haches de guerre en bronze et 4 Marteaux de guerre en bronze à Orokk Omosh à Orgrimmar."}}
D[2753] = {"Piétinés",{"Apporter 4 Heaumes en fer émeraude, 4 Brassards en fer émeraude et 2 Jambières en fer émeraude à Orokk Omosh à Orgrimmar."}}
D[2754] = {"Les cornes de Frénésie",{"Apporter 2 Solides maillets en fer, 2 Bottes en bronze argenté et 2 Gantelets en bronze argenté à Orokk Omosh à Orgrimmar."}}
D[2755] = {"Les joies des Omosh",{"Regarder et apprendre la Danse de joie des Omosh."}}
D[2756] = {"Les vieilles voies",{"Apporter 4 Cuirasses en acier et 4 Heaumes en plaques d'acier à Aturk l'Enclume à Orgrimmar."}}
D[2757] = {"Baie-du-Butin ou la mort !",{"Aller voir McGavan à Baie-du-Butin."}}
D[2758] = {"Les origines de la forge",{"Apporter 6 Brassards en écailles dorées à Hank le Marteau à Hurlevent."}}
D[2759] = {"À la recherche de Galvan",{"Aller voir McGavan à Baie-du-Butin."}}
D[2760] = {"L'ordre du Mithril",{"Aller voir Galvan l'Ancien dans la vallée de Strangleronce."}}
D[2761] = {"Ça fond, ça ne fond pas",{"Apporter 40 Barres de mithril et 40 Barres de fer à Galvan l'Ancien à Strangleronce."}}
D[2762] = {"Le vif-argent n’est pas de l'argent",{"Apporter 40 Barres de mithril et 5 Barres de vrai-argent à Galvan l'Ancien à Strangleronce."}}
D[2763] = {"L'art de l'imprégnation",{"Apporter 40 Barres de mithril et 4 Citrines à Galvan l'Ancien à Strangleronce."}}
D[2764] = {"Le meilleur disciple de Galvan",{"Parler à Trenton Martelume à Gadgetzan."}}
D[2765] = {"Maître Forgeron !",{"Réclamez votre récompense à Galvan l'Ancien !"}}
D[2766] = {"Trouvez OOX-22/FE !",{"Placer la balise de détresse dans le robot d'Orguignard qui se trouve dans une caverne près du val des Griffes farouches."}}
D[2767] = {"Sauvez OOX-22/FE !",{"Escorter OOX-22/FE au dock le long de la Côte oubliée, puis faire votre rapport à Orguignard Odipnoticus à Baie-du-Butin."}}
D[2768] = {"Le bâtonnet divino-matic",{"Rapporter le Bâtonnet divino-matic à l'Ingénieur en chef Vizisanie, à Gadgetzan."}}
D[2769] = {"Les frères Brassbolts",{"Parler à Wizzle Brassbolts dans les Salines."}}
D[2770] = {"Gahz'rilla",{"Rapporter l'Ecaille électrifiée de Gahz'rilla à Lachnouf Zéboulon dans les Salines."}}
D[2771] = {"Une tête bien faite sur les épaules",{"Rapporter deux Camails en mithril et une paire d'Epaulières ornées en mithril à Trenton Martelume."}}
D[2772] = {"Le monde à vos pieds",{"Rapporter deux paires de Bottes en mithril lourd et un Pantalon orné en mithril à Trenton Martelume."}}
D[2773] = {"Le gars du mithril",{"Rapporter deux Cuirasses lourdes en mithril et une paire de Gants ornés en mithril à Trenton Martelume."}}
D[2781] = {"ON RECHERCHE : Caliph Dard-de-scorpide",{"Apporter la tête de Caliph Dard-de-scorpide à l'Ingénieur en chef Vizisanie à Gadgetzan."}}
D[2782] = {"Secret de Rin'ji",{"Oran Serpenroule, une érudite réputée pour sa connaissance des us et coutumes des trolls Fânécorces, pourrait peut-être déchiffrer la tablette. Elle habite le Quartier de la magie à Fossoyeuse."}}
D[2783] = {"Querelles mesquines",{"Parler au Héros de la Horde tombé au combat à la frontière des Terres foudroyées et du marais."}}
D[2784] = {"Perte d'honneur",{"Écouter le Héros de la Horde tombé au combat raconter son histoire."}}
D[2801] = {"Une histoire de chagrin",{"Écouter le Héros de la Horde tombé au combat raconter son histoire."}}
D[2821] = {"La marque de la qualité",{"Rapporter 10 Peaux de yéti épaisses à Pratt McGrubben au bastion de Pennelune."}}
D[2822] = {"La marque de la qualité",{"Apporter 10 Peaux de yéti épaisses à Jangdor Rôdeur-agile au Camp Mojache."}}
D[2841] = {"Guerre des plates-formes",{"Obtenir la Combinaison du coffre de Thermojoncteur, prendre les Plans de la plate-forme et les apporter à Nogg à Orgrimmar."}}
