D[2843] = {"Gnomer-paaarti !",{"Attendre que Scooty calibre le Transpondeur gobelin."}}
D[2844] = {"Le garde géant",{"Retrouver la jeune elfe de la nuit perdue."}}
D[2845] = {"Shay l'égarée",{"Prendre la Cloche de Shay dans le coffre.","","Escorter Shay Coursefeuille au Camp de Croque-roc."}}
