D[2864] = {"Tran'rek",{"Parler à Tran'rek à Gadgetzan."}}
D[2865] = {"Les carapaces de scarabées",{"Rapporter 5 Carapaces de scarabée intactes à Tran'rek à Gadgetzan."}}
D[2866] = {"Les ruines de Solarsal",{"Explorer les ruines de Solarsal et enquêter sur la présence des nagas dans le secteur."}}
