D[2870] = {"Contre le Seigneur Shalzaru",{"Éliminer le seigneur Shalzaru et rapporter la Mystérieuse relique qu'il a découverte à Latronicus Lancelune au bastion de Pennelune."}}
D[2871] = {"Livraison de la relique",{"Porter la Relique mystérieuse à Vestia Lancelune au bastion de Pennelune."}}
D[2872] = {"Les dettes de Stoley",{"Parler à Stoley, à Port Gentepression."}}
D[2873] = {"La cargaison de Stoley",{"Apportez la Cargaison de Stoley à Port Gentepression et remettez-la à Stoley."}}
D[2874] = {"Livraison à MacKinley",{"Porter la Bouteille de Stoley à MacKinley \"Loup des mers\" à Baie-du-Butin."}}
D[2875] = {"ON RECHERCHE : André Barbe-en-feu",{"Rapporter la tête d'André au Chef de la sécurité Vizisanie à Port Gentepression."}}
D[2876] = {"Horaires des bateaux",{"Présenter les Horaires des bateaux aux autorités de Port Gentepression."}}
D[2877] = {"Nettoyer le rocher de l'Affût",{"Tuer 10 Limaces vertes et 10 Limons de jade puis faire votre rapport à Fraggar Tonnemante au Nid-de-l'Aigle."}}
D[2878] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[2879] = {"Le Bâton d'Equinex",{"Dynamiser le Bâton de Troyas et trouver le Monolithe d'Equinex."}}
D[2880] = {"Chasse au collier troll",{"Rapporter 5 Colliers tribaux trolls à Fraggar Tonnemante au Nid-de-l'Aigle."}}
D[2881] = {"Chasse aux colliers trolls",{"Vous l'avez déjà fait, mais nous continuerons d'accepter tous les Colliers tribaux que vous trouverez. En me les donnant, vous continuerez d'accroître votre prestige parmi les Wildhammer ; si vous désirez vous battre pour nous, nous pourrons nous battre pour vous !","","J'ai besoin de cinq colliers tribaux trolls, <nom>."}}
D[2882] = {"L'or de Cuergo",{"Trouvez l'or de Cuergo !"}}
D[2902] = {"Enquête chez les Griffebois",{"Trouver les Plans de bataille des gnolls dans les camps gnolls du sud du Camp Mojache."}}
D[2903] = {"Les plans de bataille",{"Rapporter les Plans de bataille des Griffebois à Hadoken Rôdeur-agile au Camp Mojache."}}
D[2904] = {"Une jolie pagaille",{"Escorter Kernobee jusqu'à la sortie de la Fuite du temps, puis faire un rapport à Scooty, à Baie-du-Butin."}}
D[2922] = {"Sauver le cerveau de Techbot !",{"Rapporter la Mémoire principale de Techbot au maître-artisan Suprétincelle à Forgefer."}}
D[2923] = {"Maître-bricoleur Suprétincelle",{"Parler au maître-artisan Suprétincelle à Forgefer."}}
D[2924] = {"Les cerveaux mécaniques",{"Rapporter 12 Cerveaux mécaniques à Pléthorloge Cléventail à Forgefer."}}
D[2925] = {"Les cerveaux mécaniques de Klockmort",{"Parler à Pléthorloge Cléventail à Forgefer."}}
D[2926] = {"Gnogaine",{"Utiliser la Flasque plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Virevolt à Kharanos."}}
D[2927] = {"Le jour d'après",{"Parler à Ozzie Virevolt à Kharanos."}}
D[2928] = {"Excavateurs gyrodrilmatiques",{"Rapporter 24 Entrailles mécaniques de robot à Shoni à Hurlevent."}}
D[2929] = {"La grande trahison",{"Aller à Gnomeregan et tuer le mekgénieur Thermojoncteur. Puis retourner voir le Grand Bricoleur Mekkanivelle."}}
D[2930] = {"Sauvetage de données",{"Apporter une Carte perforée prismatique au Maître mécanicien Fontuyau, à Forgefer."}}
D[2931] = {"Du travail pour Castpipe",{"Parler au Maître mécanicien Fontuyau, à Forgefer."}}
D[2932] = {"Sinistre message",{"Collecter des Crânes de Fânécorce et les placer sur la Pique de Nimboya. Poser la Pique de Nimboya préparée dans l'un des Villages Fânécorce, dans les Hinterlands, puis retourner voir Nimboya, à Strangleronce."}}
D[2933] = {"Bouteilles de venin",{"Apporter une Bouteille de venin à un apothicaire, au Moulin-de-Tarren."}}
D[2934] = {"Glande à venin intacte",{"Rapporter une Glande à venin intacte à l'Apothicaire Lydon, au Moulin-de-Tarren."}}
D[2935] = {"Consulter Maître Gadrin",{"Parler à Maître Gadrin au village de Sen'jin."}}
D[2936] = {"Le dieu-araignée",{"Lire la Tablette de Theka pour connaître le véritable nom du dieu-araignée des Fânécorces, puis retourner voir Maître Gadrin."}}
D[2937] = {"L'invocation de Shadra",{"Terrasser Shadra, à l'autel de Shadra'Alor, puis rapporter son venin à l'Apothicaire Lydon, au Moulin-de-Tarren."}}
D[2938] = {"Du venin pour Fossoyeuse",{"Apporter le Colis de Faranell au maître apothicaire Faranell, à Fossoyeuse."}}
D[2939] = {"En savoir plus",{"Parler à Daryn Calmevent, au village de Rut'theran."}}
D[2940] = {"Feralas : une histoire",{"Demander à Daryn Calmevent si vous pouvez emprunter son livre."}}
D[2941] = {"Le prêt",{"Apporter la lettre à Gruzouille Sautelevier, à Tanaris."}}
D[2942] = {"La Pierre du matin",{"Rapporter la Pierre étincelante et le Bâton d'Equinex à Troyas Lunebise, dans le bastion de Pennelune."}}
D[2943] = {"Troyas",{"Apporter le livre à Troyas Lunebise, dans le bastion de Pennelune."}}
D[2944] = {"Le Preneur d'images FX",{"Utiliser le Preneur d'images FX pour prendre un cliché de Gammerita, puis retourner voir Daryn Calmevent à Rut'theran."}}
D[2945] = {"Anneau sali",{"Trouver un moyen de nettoyer l'Anneau sali."}}
D[2946] = {"Questions sans réponses",{"Porter les Disques de platine miniatures aux Portes d'Uldum, à Tanaris et chercher les indices de la connexion qui existe entre eux."}}
D[2947] = {"Le retour de l'anneau",{"Vous pouvez soit garder l'anneau, soit retrouver la personne désignée par les lettres qui sont gravées à l'intérieur."}}
D[2948] = {"Amélioration gnomique",{"Apporter l'Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d'argent à Talvash del Kissel, à Forgefer."}}
D[2949] = {"Le retour de l'anneau",{"Vous pouvez soit garder l'anneau, soit retrouver la personne désignée par les lettres qui sont gravées à l'intérieur."}}
D[2950] = {"Nogg améliore l'anneau",{"Apporter l'Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d'argent à Nogg, à Orgrimmar."}}
D[2951] = {"Le Décapeur 5200 !",{"Insérer un Objet sali dans le Brille-o-Matic 5200, sans oublier de jeter trois pièces d'argent dans la fente, pour démarrer la machine."}}
D[2952] = {"Le Décapeur 5200 !",{"D'un coup le Décapeur 5200 s'arrête net. Un petit carillon émet un \"ding\" clair et la trappe de l'appareil s'ouvre. À l'intérieur de la machine vous découvrez une petite boîte garnie d'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n'a pas fonctionné.","","Bon, il n'y a qu'un seul moyen de savoir si l'objet à bel et bien été nettoyé ou non..."}}
D[2953] = {"Le Décapeur décape encore",{"Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer."}}
D[2954] = {"Le Gardien des pierres",{"Apprendre le but du Gardien des pierres de Norgannon, puis interagir avec le Socle d'Uldum, dans le désert de Tanaris."}}
D[2962] = {"Encore plus de Lueur verte !",{"Voyager à Gnomeregan et rapporter de la Matière radioactive à haut potentiel. Attention, la matière radioactive est instable et se désactive rapidement.","","Après le travail, conserver la Flasque plombée lourde, pour Ozzie."}}
D[2963] = {"Prodiges d'Uldum",{"Parler à l'Historien Karnik dans le Hall des explorateurs, à Forgefer."}}
D[2964] = {"Travail imminent",{"Parler au Grand Explorateur Magellas, à Forgefer."}}
D[2965] = {"Prodiges d'Uldum",{"Aller à la Cime des Anciens, aux Pitons du Tonnerre et parler à Nara Crin-sauvage."}}
D[2966] = {"Questions sans réponses",{"Porter les Disques de platine miniatures aux Portes d'Uldum, à Tanaris et chercher les indices de la connexion qui existe entre eux."}}
D[2967] = {"Le retour à Thunder Bluff",{"Parler à Nara Wildmane, dans Thunder Bluff."}}
D[2968] = {"Travail imminent",{"Parler au Sage Recherche-la-vérité, aux Pitons du Tonnerre."}}
D[2969] = {"Liberté pour toutes les créatures",{"À l'aide de la Clé de la cage en bambou, libérer les Fées fléchetteuses de l'enclos dans le Camp du Totem-sinistre. Au moins 6 Fées fléchetteuses et Kindal Tisselune doivent survivre.","","Vous avez 6 minutes avant que Kindal décide qu'il est temps de battre en retraite et que vous échouiez dans votre quête."}}
D[2970] = {"Justice de châtiment",{"Tuer 12 Naturalistes du Totem-sinistre, 10 Écumeurs du Totem-sinistre et 6 Chamans du Totem-sinistre avant de retourner voir Jer'kai Tisselune, en Féralas."}}
