D[2974] = {"Une découverte sinistre",{"Apporter 20 Cornes de Totem-sinistre à Krueg Casse-crâne au Camp Mojache."}}
D[2975] = {"Les ogres de Féralas",{"Tuer 10 Ogres Gordunni, 10 Ogre-magi Gordunni et 5 Brutes Gordunni pour Rok Orhan, du Camp Mojache."}}
D[2976] = {"Une découverte sinistre",{"Apporter la Caisse de Cornes de Totem-sinistre à Belgrom Cogneroche, Orgrimmar."}}
D[2977] = {"Retour à Forgefer",{"Parler à l'Historien Karnik, à Forgefer."}}
D[2978] = {"Le parchemin gordunni",{"Apporter le Parchemin gordunni à Rok Orhan, au Camp Mojache."}}
D[2979] = {"Sombre cérémonie",{"Rok Orhan, du Camp Mojache, veut que vous trouviez un Orbe Gordunni."}}
