D[2982] = {"Les Plateaux sauvages",{"Tuer 8 Démonistes Gordunni, 8 Chamans Gordunni et 8 Brutes Gordunni pour Angelas Lunebise."}}
D[2983] = {"L'appel du feu",{"Trouver Kranal Fiss dans les Tarides."}}
D[2984] = {"L'appel du feu",{"Trouver Kranal Fiss dans les Tarides."}}
D[2985] = {"L'appel de l'eau",{"Trouver Islen Oeil-des-rivières dans les Tarides."}}
D[2986] = {"L'appel de l'eau",{"Trouver Islen Oeil-des-rivières dans les Tarides."}}
D[2987] = {"Cobalt Gordunni",{"Collecter 12 échantillons de Cobalt Gordunni pour Orwin Azztuche, du Camp Mojache."}}
D[2988] = {"Les cages Witherbark",{"Inspecter les cages dans les deux villages Fânécorce, puis retourner auprès du Maître des griffons Hachegriffe."}}
D[2989] = {"L'autel de Zul",{"Regarder sur le dessus de l'autel de Zul, puis retourner auprès du Maître des griffons Hachegriffe."}}
D[2990] = {"Thadius Sinissombre",{"Apporter la Plume de Bec-tranchant à Thadius Sinissombre, dans les Terres foudroyées."}}
D[2991] = {"Le médaillon de Nekrum",{"Apporter le Médaillon de Nekrum à Thadius Sinissombre, dans les Terres foudroyées."}}
D[2992] = {"La Divination",{"Attendre que Grimshade ait fini de pratiquer son rituel de divination."}}
D[2993] = {"Retour dans les Hinterlands",{"Parler au Maître des gryphons Talonaxe."}}
D[2994] = {"Sauver Bec-tranchant",{"Combattre jusqu'au sommet de Jintha'Alor, tuer la vile prêtresse Maléficia pour obtenir la clé de la cage de Bec-tranchant, et sauver Bec-tranchant."}}
D[2995] = {"Lignes de communication",{"Oran Serpenroule, de Fossoyeuse, vous demande de vous rendre dans les Hinterlands et d'y brûler les Registres du Haut-val, le Rapport du Haut-val et les Notes du Haut-val."}}
D[2996] = {"À la recherche de Strahad",{"Parler à Strahad Farsan, à Cabestan."}}
D[2997] = {"Le Tome de divinité",{"Parler à Tiza Forgeguerre à Forgefer."}}
D[2998] = {"Le Tome de divinité",{"Parler à Duthorian Rall à Hurlevent."}}
D[2999] = {"Le Tome de divinité",{"Parler à Tiza Forgeguerre, à Forgefer."}}
D[3000] = {"Le Tome de divinité",{"Parler à Tiza Forgeguerre à Forgefer."}}
D[3001] = {"À la recherche de Strahad",{"Trouver Strahad Farsan, à Cabestan."}}
D[3002] = {"L'Orbe Gordunni",{"Apporter l'Orbe Gordunni à Uthel'nay, au pavillon de Buissombre, à Orgrimmar."}}
D[3022] = {"À manipuler avec soin",{"Apporter la Caisse soigneusement empaquetée à Erelas Ambreciel, au village de Rut'theran."}}
D[3042] = {"Agent durcissant troll",{"Apporter 20 Fioles d'agent durcissant troll à Trenton Martelume, à Gadgetzan."}}
D[3062] = {"Cœur noir",{"Rapporter le Coeur noir d'Edana Serrehaine à Talo Sabot-de-ronce, au Camp Mojache."}}
D[3063] = {"Se venger des Ruissenord",{"Tuer 4 Harpies Ruissenord, 4 Volplumes Ruissenord, 4 Imploratrices célestes Ruissenord et 4 Pourfendeuses Ruissenord pour Talo Sabot-de-ronce."}}
D[3065] = {"Tablette simple",{"Lire la Tablette simple, et parler à Frang, dans la Vallée des épreuves."}}
D[3082] = {"Tablette gravée",{"Parler à Jen'shan dans la Vallée des épreuves."}}
D[3083] = {"Tablette codée",{"Lire la Tablette codée, et parler à Rwag, dans la Vallée des épreuves."}}
D[3084] = {"Tablette runique",{"Parler à Shikrik dans la Vallée des épreuves."}}
D[3085] = {"Tablette bénie",{"Lire la Tablette bénie, et parler à Ken'jai, à l'extérieur de l'Antre, dans la Vallée des épreuves."}}
D[3086] = {"Tablette glyphée",{"Lire la Tablette glyphée, et parler à Mai'ah, près de l'entrée de l'Antre, dans la Vallée des épreuves."}}
D[3087] = {"Parchemin gravé",{"Lire le Parchemin gravé, et parler à Jen'shan, dans la Vallée des épreuves."}}
D[3088] = {"Parchemin codé",{"Lire le Parchemin codé, et parler à Rwag, dans la Vallée des épreuves."}}
D[3089] = {"Parchemin runique",{"Lire le Parchemin runique, et parler à Shikrik, dans la Vallée des épreuves."}}
D[3090] = {"Parchemin contaminé",{"Lire le Parchemin contaminé, et parler à Nartok, à l'intérieur de l'Antre, dans la Vallée des épreuves."}}
D[3091] = {"Note simple",{"Lire la Note simple, et parler à Harutt Corne-tonnerre, au Camp Narache."}}
D[3092] = {"Note gravée",{"Lire la Note gravée, et parler à Lanka Vise-loin, sur la Mesa de Nuage rouge."}}
D[3093] = {"Note runique",{"Lire la Note runique, et parler à Meela Dawnstrider, à Camp Narache."}}
D[3094] = {"Note verdoyante",{"Lire la Note verdoyante, et parler à Gart Cours-la-brume, au Camp Narache."}}
D[3095] = {"Parchemin simple",{"Lire le Parchemin simple, et parler à Dannal Stern, au Glas."}}
D[3096] = {"Parchemin codé",{"Lire le Parchemin codé, et parler à David Trias, au Glas."}}
D[3097] = {"Parchemin béni",{"Lire le Parchemin béni, et parler au sombre clerc Duesten, dans l'église du Glas."}}
D[3098] = {"Parchemin glyphé",{"Lire le Parchemin glyphé, et parler à Isabella, dans l'église du Glas."}}
D[3099] = {"Rouleau contaminé",{"Lire le Rouleau contaminé, et parler à Maximillion, au Glas."}}
D[3100] = {"Lettre simple",{"Lire la Lettre simple et parler à Llane Beshere, à l'Abbaye de Comté-du-nord."}}
D[3101] = {"Lettre consacrée",{"Lire la Lettre consacrée, et parler à Frère Sammuel, à l'Abbaye de Comté-du-nord."}}
D[3102] = {"Lettre codée",{"Lire la Lettre codée, et parler à Jorik Kerridan, dans l'écurie, derrière l'Abbaye de Comté-du-nord."}}
D[3103] = {"Lettre bénie",{"Lire la Lettre bénie, et parler à la prêtresse Anetta, à l’abbaye de Northshire."}}
D[3104] = {"Lettre glyphée",{"Lire la Lettre glyphée, et parler à Khelden Bremen, à l'intérieur de l'Abbaye de Comté-du-nord."}}
D[3105] = {"Lettre contaminée",{"Lire la Lettre contaminée, et parler à Drusilla La Salle, à proximité de l'Abbaye de Comté-du-nord."}}
D[3106] = {"Rune simple",{"Lire la Rune simple, et parler à Thran Khorman, dans la Vallée des Frigères."}}
D[3107] = {"Rune consacrée",{"Lire la Rune consacrée, et parler à Bromos Grummneur, dans la Vallée des Frigères."}}
D[3108] = {"Rune gravée",{"Lire la Rune gravée, et parler à Thorgas Grimson, dans la Vallée des Frigères."}}
D[3109] = {"Rune codée",{"Lire la Rune codée, et parler à Solm Hargrin, dans la Vallée des Frigères."}}
D[3110] = {"Rune bénie",{"Lire la Rune bénie, et parler à Branstock Khalder, à Courbenclume."}}
D[3112] = {"Note de service simple",{"Lire la Note de service simple, et parler à Thran Khorman, dans la Vallée des Frigères."}}
D[3113] = {"Note de service codée",{"Lire la Note de service codée, et parler à Solm Hargrin, dans la Vallée des Frigères."}}
D[3114] = {"Note de service glyphée",{"Lire la Note de service glyphée, et parler à Marryk Nurribit, dans Courbenclume, au-dessus de la Vallée des Frigères."}}
D[3115] = {"Note de service contaminée",{"Lire la Note de service contaminée, et parler à Alamar Grimm, dans Courbenclume, au-dessus de la Vallée des Frigères."}}
D[3116] = {"Sceau simple",{"Lire le Sceau simple, et parler à Alyissia, à Sombrevallon."}}
D[3117] = {"Sceau gravé",{"Lire le Sceau gravé, et parler à Ayanna Vassanfin, au sommet d'Aldrassil, dans Sombrevallon."}}
D[3118] = {"Sceau codé",{"Lire le Sceau codé et parler à Frahun Murmombre, à Sombrevallon."}}
D[3119] = {"Sceau béni",{"Lire le Sceau béni, et parler à Shanda, à Aldrassil."}}
D[3120] = {"Sceau verdoyant",{"Lire le Sceau verdoyant, et parler à Mardant Chênefort, dans l'arbre Aldrassil de Sombrevallon."}}
D[3121] = {"Une Requête étrange",{"Porter la Tête réduite à Neeru Lamefeu à Orgrimmar."}}
D[3122] = {"Retourner voir le sorcier-docteur Uzer'i",{"Livrer une Poche d'herbes de Neeru au Sorcier-docteur Uzer'i, en Féralas."}}
D[3123] = {"Test du récipient",{"Partez pour les Hinterlands et localisez les Indomptables. Tuez-en 10, puis utilisez le Récipient de muisek pour faire rétrécir et capturer les Indomptables vaincus.","","Ramenez 10 Indomptables miniaturisés et le Récipient d'Indomptables miniaturisés au sorcier-docteur Uzer'i, en Féralas."}}
D[3124] = {"Hippogryphe miniaturisé",{"Tuer 10 Hippogriffes Aigreplume de n'importe quel type, puis utiliser le Vaisseau de muisek pour les faire rétrécir et les capturer."}}
D[3125] = {"Dragon féérique miniaturisé",{"Tuer 8 Fées fléchetteuses ou Petits dragons féeriques. Utiliser le Vaisseau de muisek pour faire rétrécir et capturer les dragons féeriques vaincus."}}
D[3126] = {"Tréant miniaturisé",{"Tuer 3 Marcheurs des bois errants. Utiliser le Vaisseau de muisek pour faire rétrécir et pour capturer les tréants vaincus."}}
D[3127] = {"Géant des montagnes miniaturisé",{"Tuer 7 Marcheurs des terres ou Géants des falaises. Utiliser le Récipient de muisek pour faire rétrécir et pour capturer les Géants des montagnes."}}
D[3128] = {"Matériaux naturels",{"Apporter 2 Bûches fendues, 6 Minerais incrustés, 20 Morceaux de tendons résistants et 40 Fragments métalliques au sorcier-docteur Uzer'i au Camp Mojache."}}
D[3129] = {"Armes de l'Esprit",{"Le sorcier-docteur Uzer'i veut que vous patientez pendant qu'il prépare les armes."}}
D[3130] = {"Contre les Hainecrête",{"Se présenter devant Latronicus Lancelune au bastion de Pennelune."}}
D[3141] = {"Loramus",{"Écouter l'histoire de Loramus Thalipedes."}}
D[3161] = {"La gahz'ridienne",{"Marvon Chercherivet à Tanaris veut que vous collectiez 30 Ornements en gahz'ridienne."}}
D[3181] = {"La corne de la bête",{"Porter la Corne Gigantesque de Margol à la Montagnarde Minigravillon."}}
D[3182] = {"Titre de propriété",{"Porter la Corne gigantesque de Margol au conservateur en chef Thorius à Forgefer."}}
D[3201] = {"Enfin !",{"Apporter le document de preuve à la Montagnarde Minigravillon."}}
D[3221] = {"Parler à Renferrel",{"Parler à l'apothicaire Renferrel au Sépulcre."}}
D[3261] = {"Jorn Skyseer",{"Parler à Jorn Oeil-des-cieux, au Camp Taurajo."}}
D[3281] = {"Argent volé",{"Rapportez l'Argent volé à Gazrog à la Croisée."}}
D[3301] = {"Mura Runetotem",{"Parler à Mura Totem-runique au Sépulcre."}}
D[3321] = {"Est-ce que ceci est à vous ?",{"Attendre que Trenton ait terminé son travail."}}
D[3341] = {"L'anéantissement",{"Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne."}}
D[3361] = {"Les malheurs d'un réfugié",{"Apporter la Boîte de Felix, le Coffre de Felix et le Seau de boulons de Felix à Felix Chouineboulon, à Courbenclume."}}
D[3362] = {"La vallée des Chardonniers",{"Tran'rek, à Gadgetzan, voudrait que vous tuiez 8 Chardonniers noueux et 8 Chardonniers taille-racines."}}
D[3363] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[3364] = {"Une livraison de thé brûlant",{"Apporter un Thé brûlant à Durnan Coupefourrure, dans Courbenclume, dans les cinq minutes imparties avant qu'il ne refroidisse !"}}
D[3365] = {"Rapporter la Tasse",{"Apporter la Chope de Nori à Nori Fièroblique."}}
D[3366] = {"L'Éclat luminescent",{"Aller à Cabestan pour trouver la raison d'être de l'Éclat de cauchemar."}}
D[3367] = {"Les pierres de Suntara",{"Aider Dorius à retourner à Ironforge."}}
D[3368] = {"Les pierres de Suntara",{"Apporter la Lettre roussie à Thorius à Forgefer. Il se trouve dans le Hall des Explorateurs."}}
D[3369] = {"Au coeur des cauchemars",{"Apporter l'Éclat de cauchemar à Hamuul Totem-runique à la Cime des Anciens."}}
D[3370] = {"Au coeur des cauchemars",{"Apporter l'Eclat de cauchemar à Mathrengyl Bearwalker à Darnassus."}}
D[3371] = {"La justice des nains",{"Retourner à la Gorge des Vents brûlants et trouver l'Equipe d'archéologues de Dorius."}}
D[3372] = {"La libération",{"Trouver l'Artefact mystérieux gardé par les Idolâtres du Marteau du crépuscule dans le quart nord-est de la Gorge des Vents brûlants et ramenez-le à l'Autel de Suntara dans la Fosse aux scories."}}
D[3373] = {"L'Essence d'Eranikus",{"Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti."}}
D[3374] = {"L'Essence d'Eranikus",{"Apporter la Pierre de voeu des dragons d'Ysera et l'Essence d'Eranikus enchaînée à Itharius au marais des Chagrins. C'est là que vous choisirez d'aider ou non les dragons d'Ysera."}}
D[3375] = {"La fiole de remplacement",{"Apporter une Potion de mana, du Charbon, et du Nectar sucré à Talvash del Kissel à Forgefer pour remplacer la Fiole de divination de Talvash."}}
D[3376] = {"La fin de Brochaigu !",{"Apporter la Tête du chef Brochaigu Mantépine à Brave Plume-des-vents à la mesa de Nuage rouge."}}
D[3377] = {"Prière à Elune",{"Écouter le récit de Zamael."}}
D[3378] = {"Prière à Elune",{"Trouver la Prière à Elune et l'apporter à Astarii Cherchétoile à Darnassus."}}
D[3379] = {"Les tisseuses d'ombre",{"Tuer le groupe de braconniers Ombresoie qui rôde dans la gorge des Vents brûlants. Nilith a de bonnes raisons de croire qu'ils doivent être exterminés tous les cinq. Retourner voir Nilith dans la gorge des Vents brûlants lorsque vous aurez terminé."}}
D[3380] = {"Le Temple englouti",{"Trouver Marvon Chercherivet à Tanaris."}}
D[3381] = {"Une rencontre avec le maître",{"Apporter 2 Plumes d'hippogriffe sans défaut à Sanath Lim-yo, en Azshara, si vous souhaitez parler à son maître."}}
D[3382] = {"Doux whisky",{"Défendre la capitaine Vanessa Beltis, son équipage et les passagers de \"l'Horizon\" contre l'attaque des nagas. La capitaine Vanessa Beltis doit survivre."}}
D[3385] = {"Le Sous-marché",{"Tuer le Maître d'artisanat Kovic et son agent Clonk. Récupérer sur son corps la Sacoche du marchand et l'apporter à Nilith."}}
D[3402] = {"Le Sous-marché",{"Parler à Vizzklick à Gadgetzan."}}
D[3421] = {"Le voyage de retour",{"Je vais vous renvoyer au camp de Sanath à présent.","","Ne faites pas attention à ses mauvaises manières. Il est brusque envers tout le monde, sauf envers le maître. Peut-être apprendra-t-il la leçon un jour ?"}}
D[3441] = {"Châtiment divin",{"Écouter le récit de Kalaran Lamevent."}}
D[3442] = {"La flamme parfaite",{"Réunir 4 Cœurs des flammes et 4 globes d'Huile de golem puis rapporter ces objets à Kalaran Lamevent."}}
D[3443] = {"Forger le manche",{"Apporter 8 Dagues plaquées en thorium à Kalaran Lamevent."}}
D[3444] = {"Le Cercle de pierres",{"Récupérer le Cercle de pierres à l'Atelier de Marvon Chercherivet à Cabestan."}}
D[3445] = {"Le Temple englouti",{"Trouver Marvon Chercherivet à Tanaris."}}
D[3446] = {"Dans les profondeurs",{"Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins."}}
D[3447] = {"Le secret du cercle",{"Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues."}}
D[3448] = {"La transmission du fardeau",{"Parler au mage Tymor à Forgefer."}}
D[3449] = {"Les runes des arcanes",{"À l'aide de la Trousse de dessin, effectuer des reproductions de la Rune de Beth'Amara, de la Rune de Jin'yael, de la Rune de Markri, de la Rune de Sael'hai, puis se diriger vers la petite île près de la Péninsule méridionale d'Azshara et signaler au Pilote Xiggs Allumèche de venir les prendre."}}
D[3450] = {"Une collecte facile",{"Parler à Xiggs Allumèche à Forgefer."}}
D[3451] = {"Signal de la récupération",{"Parler à Xiggs Allumèche à Forgefer et en obtenir un Lance-fusée standard."}}
D[3452] = {"L'enveloppe de la flamme",{"Trouver et apporter un Symbole de Ragnaros à Kalaran Lamevent."}}
D[3453] = {"La Torche de vindicte",{"Attendre que Kalaran Lamevent termine la Torche de vindicte."}}
D[3454] = {"La Torche de vindicte",{"Prendre la Torche de vindicte."}}
D[3461] = {"Le retour vers Tymor",{"Rapporter la Trousse de dessin du mage Tymor au mage Tymor, à Forgefer."}}
D[3462] = {"L'écuyer Maltrake",{"Parler à l'écuyer Maltrake."}}
D[3463] = {"Allumer le feu !",{"Mettre le feu aux Tours de garde nord, sud, est et ouest en utilisant la Torche de vindicte à l'intérieur de chaque tour."}}
D[3481] = {"Bibelots...",{"Ouvrir le coffre."}}
D[3482] = {"<NYI> <TXT> The Pocked Black Box",{"Porter la boîte à Kravel."}}
D[3483] = {"Signal de la récupération",{"Oh, un autre lance-fusées, hein ? Je peux le faire.","","N'oubliez pas, la pointe sud d'Azshara. C'est une toute petite île transformée en piste d'atterrissage. Vous ne pouvez pas la manquer si vous êtes au bon endroit."}}
D[3501] = {"Tout se compte en grandes quantités",{"Apporter des Fragments imparfaits de draenéthyste à Kum'isha et toucher une récompense pour chaque fragment rapporté."}}
D[3502] = {"Au rebut pour les draeneï",{"Apporter des Fragments imparfaits de draenéthyste à Kum'isha. N'importe quel monstre des Terres foudroyées peut détenir un fragment."}}
D[3503] = {"Réunion avec le Maître",{"Autrefois, je pouvais demander tout ce que je voulais à ceux qui souhaitaient voir mon maître. À présent, vous n'avez qu'à demander et je vous enverrai à lui.","","Cela me chagrine mais je ne discute pas ses ordres. Le seul plaisir qu'il me reste est de me moquer des vêtements ridicules que vous portez et de votre mine pitoyable. Même cela m'ennuie...","","Mêmes ces bavardages m'ennuient ! Souhaitez-vous voir mon maître ou non ?"}}
D[3504] = {"Trahison",{"Apporter la Lettre scellée à Ag'tor Poing-de-sang en Azshara."}}
D[3505] = {"Trahison",{"Tuer 10 Vengeurs elfes de sang et 10 Géomètres elfes de sang avant de rechercher le campement du magus Rimtori. Une fois le camp trouvé, chercher quelque chose d'important pour elle et qui peut être utilisé pour l'obliger à se battre."}}
D[3506] = {"Trahison",{"Détruire le Cristal de focalisation des arcanes lié au magus Rimtori et l'assassiner ensuite. Puis apporter la tête du magus Rimtori à Ag'tor Poing-de-sang en Azshara."}}
D[3507] = {"Trahison",{"Aller voir Belgrom Cogneroche à Orgrimmar."}}
D[3508] = {"Briser l'Amulette",{"Attendre que Loramus ait achevé le rituel de Lumière."}}
D[3509] = {"Le nom de la bête",{"Aller voir le seigneur Arkkoroc en Azshara. Commencer la recherche au bord de l'eau pour trouver le temple d'Arkkoran."}}
D[3510] = {"Le nom de la bête",{"Assassiner Hetaera et apporter la Tête ensanglantée d'Hetaera, la Tête battue d'Hetaera et la Tête meurtrie d'Hetaera au seigneur Arkkoroc."}}
D[3511] = {"Le nom de la bête",{"Rapporter le durcisseur à Loramus Thalipedes."}}
D[3512] = {"Par les mots d'Eranikus",{"Se rendre dans la partie orientale du Berceau-de-l'Hiver et aller voir Umbranse l'implorateur d'esprit."}}
D[3513] = {"Le Parchemin runique",{"Apporter le Parchemin runique à la tour de garde Nord dans les Tarides."}}
D[3514] = {"Présence de la Horde",{"Tuer le chef de l'Antre des Serres, Rynthariel le Maître des clés."}}
D[3517] = {"L'art du vol",{"Trouver la Tablette de Beth'Amara, la Tablette de Jin'yael, la Tablette de Markri et la Tablette de Sael'hai puis retourner voir Jediga en Azshara."}}
D[3518] = {"Livraison à Magatha",{"Apporter la Tablette de Beth'Amara à Magatha aux Pitons du Tonnerre."}}
D[3519] = {"Un ami dans le besoin",{"Parler à Dirania Brillargent, à Sombrevallon."}}
D[3520] = {"Esprits de Hurleurs",{"Capturer l'Esprit de 3 Hurleurs en Féralas, puis retourner voir Yeh'kinya à Port Gentepression."}}
D[3521] = {"L'antidote d'Iverron",{"Trouver 7 Champignons jacinthe, 4 Lys pétales de lune et 1 Ichor d'araignée Tissebois pour Dirania Brillargent dans Sombrevallon."}}
D[3522] = {"Antidote d'Iverron",{"Apporter l'Antidote d'Iverron à Iverron avant que la limite de temps ne soit atteinte. Iverron se trouve près de la grotte, au nord."}}
D[3523] = {"Le Fléau des Souilles",{"Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu'il vous avait donnée."}}
D[3524] = {"Echouage",{"Récupérer des Os de créature marine sur la créature échouée, au sud d'Auberdine, puis les apporter à Gwennyth Bly'Leggonde, à Auberdine."}}
D[3525] = {"L'extinction de l'idole",{"Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge.","","Protéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole."}}
D[3526] = {"Ingénierie des gobelins",{"Pour en apprendre davantage sur l'ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Elastirouage dans Gadgetzan."}}
D[3527] = {"La prophétie de Mosh'aru",{"Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris."}}
D[3528] = {"Le dieu Hakkar",{"Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris."}}
D[3541] = {"Livraison pour Jes'rimon",{"Apporter la Tablette de Jin'yael à Jes'rimon à Orgrimmar."}}
D[3542] = {"Livraison à Andron Gant",{"Apporter la Tablette de Markri à Andron Gant à Fossoyeuse."}}
D[3561] = {"Livraison à l'archimage Xylem",{"Apporter la Tablette de Sael'hai à l'archimage Xylem en Azshara."}}
D[3562] = {"Le Paiement de Magatha à Jediga",{"Apporter la Note de Magatha à Jediga dans Azshara."}}
D[3563] = {"Le Paiement de Jes'rimon à Jediga",{"Apporter la Note de Jes'rimon à Jediga en Azshara."}}
D[3564] = {"Le Paiement d'Andron à Jediga",{"Apporter la Note d'Andron à Jediga en Azshara."}}
D[3565] = {"Le Paiement de Xylem à Jediga",{"Apporter la Note de Xylem à Jediga en Azshara."}}
D[3566] = {"Debout, Obsidion !",{"Assassiner Lathoric le Noir et Obsidion, puis retourner voir Thorius, à Forgefer, avec la Tête de Lathoric le Noir et le Coeur d'Obsidion."}}
D[3567] = {"Au sommet",{"Souhaitez-vous admirer la vue depuis le sommet de l'un des Colosses jumeaux ? Je peux vous y envoyer, <race>.","","Réfléchissez quand même à la façon de redescendre. C'est un voyage que l'on ne peut faire que dans un seul sens."}}
D[3568] = {"Corruption Suintante",{"Avant de retourner voir le Chimiste Cuely, remplir les 4 Fioles vides dans les cuvettes de marées le long de la côte des Ruines d'Eldarath, en Azshara."}}
D[3569] = {"Corruption Suintante",{"Donner l'élixir de Cuely à Thersa Chant-du-vent, à Fossoyeuse."}}
D[3570] = {"Corruption Suintante",{"Je n'aurais jamais rêvé que l'élixir puisse prendre forme aussi rapidement. Merci, <nom>. Je vais travailler sur le reste de ces échantillons tout de suite. Je suis sûr qu'ils seront bientôt utilisables par Dame Sylvanas et les Réprouvés."}}
D[3601] = {"Kim'jael évidemment !",{"Fouiller le Camp de base thalassien pour trouver la Boussole, la Lunette, le Poulet farci et le Wizzlegoober de Kim'Jael, puis les lui rapporter en Azshara."}}
D[3602] = {"Azsharite",{"Trouver 20 Azsharites cristallisées au sud d'Azshara. Utiliser éventuellement le gangrechien pour 'renifler' l'emplacement où sont intelligemment cachés les dépôts.","","Retourner voir Loramus une fois votre tâche accomplie."}}
D[3621] = {"La Formation de Felbane",{"Apporter la cargaison à Galvan l'Ancien dans la vallée de Strangleronce."}}
D[3625] = {"Armes Fel en Azsharite enchantée",{"Attendre que Galvan ait fini de forger les armes."}}
D[3626] = {"Retour aux Terres foudroyées",{"Retourner voir le Héros de la Horde tombé au combat."}}
D[3627] = {"Réunir les morceaux de l'Amulette brisée.",{"Assassiner Grol le Destructeur, dame Sevine et l'archimage Allistarj. Prendre sur leurs cadavres l'Amulette de Grol, l'Amulette de Sevine et l'Amulette d'Allistarj.","","N'oubliez pas d'UTILISER vos armes gangrenées en azsharite enchantée pour affaiblir la triade (ils ne peuvent pas être tués autrement), mais faites-le sagement..."}}
D[3628] = {"Vous êtes Rakh'likh, démon",{"Détruire Razelikh le Souilleur et apporter la Corne brisée du Souilleur au Héros de la Horde tombé au combat. Rendre aussi l'Amulette du Souilleur au Héros pour qu'il puisse la détruire, afin de l'empêcher de tomber dans de mauvaises mains."}}
D[3629] = {"Ingénierie des gobelins",{"Pour en apprendre davantage sur l'ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Elastirouage dans Gadgetzan."}}
D[3630] = {"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Suprétincelle, à Forgefer."}}
D[3631] = {"Invocation d'un palefroi corrompu",{"Parler à Strahad Farsan, dans les Tarides."}}
D[3632] = {"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Suprétincelle, à Forgefer."}}
D[3633] = {"Ingénierie des gobelins",{"Pour en apprendre davantage sur l'ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Elastirouage, à Gadgetzan."}}
D[3634] = {"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Suprétincelle, à Forgefer."}}
D[3635] = {"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie à Orguignard Odipnoticus à Baie-du-Butin."}}
D[3636] = {"Apportez la Lumière",{"Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l'Archevêque Benedictus."}}
D[3637] = {"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie à Orguignard Odipnoticus à Baie-du-Butin."}}
D[3638] = {"Le Vœu du secret",{"Pour devenir un Ingénieur gobelin, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Nixx Elastirouage dans Gadgetzan."}}
D[3639] = {"Montrez votre travail",{"Apporter 20 Grandes Bombes en fer, 20 Dynamites Solides et 5 Moutons Explosifs à Nixx Elastirouage dans Gadgetzan."}}
D[3640] = {"Le Vœu du secret",{"Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore le maître-artisan Suprétincelle, à Forgefer."}}
D[3641] = {"Montrez votre travail",{"Apporter 6 Tubes en mithril, 1 Lunette de précision et 2 Leurres perfectionnés au Maître artisan Suprétincelle à Forgefer."}}
D[3642] = {"Le Vœu du secret",{"Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Oglethrope Odipnoticus à Baie-du-Butin."}}
D[3643] = {"Montrez votre travail",{"Apporter 6 Tubes en mithril, 1 Lunette de précision et 2 Leurres perfectionnés à Orguignard Odipnoticus à Baie-du-Butin."}}
D[3644] = {"Le renouvellement de la Carte de membre",{"Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or."}}
D[3645] = {"Le renouvellement de la Carte de membre",{"Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or."}}
D[3646] = {"Le renouvellement de la Carte de membre",{"Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or."}}
D[3647] = {"Le renouvellement de la Carte de membre",{"Pour renouveler votre carte de membre, vous devez vous acquitter du prix de renouvellement qui est de deux pièces d'or."}}
D[3661] = {"Dans les faveurs d'Elune ?",{"Collecter 15 Plumes d'Indomptable dans les Hinterlands, pour Erelas Ambreciel au village de Rut'theran."}}
D[3681] = {"Le Tome de divinité",{"Parler à Duthorian Rall à Hurlevent."}}
D[3701] = {"Les ruines fumantes de Thaurissan",{"Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l'Historienne royale Archesonus."}}
D[3702] = {"Les ruines fumantes de Thaurissan",{"Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan."}}
D[3721] = {"Un OOX rien que pour vous",{"Vous avez récupéré trois de mes robots guidés OOX ! Vous avez fait bien plus que le nécessaire, aussi vais-je vous donner quelque chose de spécial pour vous remercier. C'est une version miniature du robot qu'à présent vous devez connaître et aimer : l'OOX !","","Normalement, je ne laisserais à personne un appareil aux capacités si dangereuses, mais vous m'avez été d'un réel secours. De plus, les mécanismes de combat et le système de guidage ont été mis hors service.","","Mais il n'en reste pas moins qu'il s'agit bien là d'un OOX, bon sang !"}}
D[3741] = {"Le collier d'Hilary",{"Trouver le Collier d'Hilary et le rapporter à Hilary à Comté-du-Lac."}}
D[3761] = {"L'humus d'Un'Goro",{"Apporter 20 Échantillons d'humus d'Un'Goro à Ghede, aux Pitons du Tonnerre."}}
D[3762] = {"L'aide à l'archidruide Totem-runique",{"Parler à l'archidruide Hamuul Totem-runique aux Pitons du Tonnerre."}}
D[3763] = {"L'aide à l'archidruide Forteramure",{"Parler à l'archidruide Fandral Forteramure à Darnassus."}}
D[3764] = {"L'humus d'Un'Goro",{"Apporter 20 échantillons d'Humus d'Un'Goro à Jenal dans l'Enclave cénarienne à Darnassus."}}
D[3765] = {"La dépravation au loin",{"Aller voir Gershala Murmenuit à Auberdine."}}
D[3781] = {"Recherches sur la fibre d'aurore",{"Apporter le Bon pour des graines de l'archidruide à Mathrengyl Pasdelours dans l'Enclave cénarienne à Darnassus."}}
D[3782] = {"La recherche sur la Fibre d'aurore",{"Apporter le Bon pour des graines à Bashana Totem-runique aux Pitons du Tonnerre."}}
D[3783] = {"Yéti ? Y es-tu ?",{"Collecter 10 Fourrures épaisses de yéti pour Umi Sarcafroisse, à Long-guet."}}
D[3784] = {"L'aide à l'archidruide Totem-runique",{"Parler à l'archidruide Hamuul Totem-runique aux Pitons du Tonnerre."}}
D[3785] = {"Recherches sur la Fibre d'aurore",{"Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.","","Apporter 10 Fibres d'aurore à Mathrengyl Bearwalker à Darnassus."}}
D[3786] = {"Recherches sur la Fibre d'aurore",{"Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Echantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.","","Apporter 10 Fibres d'aurore à Bashana Runetotem à Thunder Bluff."}}
D[3787] = {"La requête de Gentecime",{"Parler à Quintis Gentecime dans le bastion de Pennelune."}}
D[3788] = {"La requête de Gentecime",{"Parler à Quintis Gentecime dans le bastion de Pennelune."}}
D[3789] = {"Assister l'archidruide Staghelm",{"Parler à l'archidruide Fandral Forteramure à Darnassus."}}
D[3790] = {"Assister l'archidruide Staghelm",{"Parler à l'archidruide Fandral Forteramure à Darnassus."}}
D[3791] = {"Le Mystère des Fibres d'aurore",{"Apporter 10 Fibres d'aurore à Quintis Jonespyre au bastion de Feathermoon."}}
D[3792] = {"De la Fibre d'aurore au bastion de Feathermoon",{"Je vous salue à nouveau, <nom>. Mes recherches progressent plutôt bien, mais si vous aviez cinq Fibres d'aurore supplémentaires, je serais heureux de vous en débarrasser. Mais “heureux” n'est qu'une figure de style. Plus j'en ai autour de moi, et plus je me sens mal à l'aise. Mes recherches nécessitent cependant que je me hâte et que j'en finisse."}}
D[3801] = {"Héritage Sombrefer",{"Parler à Franclorn Le Forgebusier si obtenir une clé de la Cité majeure vous intéresse."}}
D[3802] = {"Héritage Sombrefer",{"Tuer Fineous Sombrevire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Le Forgebusier."}}
D[3803] = {"De la fibre d'aurore pour Darnassus",{"L'archidruide cherche davantage de Fibres d'aurore pour que le Cercle cénarien puisse poursuivre ses recherches. Nous les prenons par lot de dix. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence."}}
D[3804] = {"Des Fibres d'aurore pour les Pitons du Tonnerre",{"L'archidruide cherche davantage de Fibre d'aurores pour que le Cercle cénarien puisse poursuivre ses recherches sur le cratère d'Un'Goro. Nous récompenserons votre cueillette par des objets qui pourront être utiles. Lorsque vous en aurez dix, faites-le-moi savoir et je vous récompenserai en conséquence."}}
D[3821] = {"Le Rocher des Cognepeurs",{"S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Fière-défense."}}
D[3822] = {"Krom'Grul",{"Récupérer l'Anneau de nez de Sha'ni sur Krom'Grul, et le rapporter à Thal'trak, à Kargath. Fouiller les différentes grottes et mines du Rocher des Cognepeurs."}}
D[3823] = {"Exterminer les Brûlentrailles",{"Tuer 15 Ogres-mages Brûlentrailles, 7 Ogres Brûlentrailles et 7 Brutes Brûlentrailles, puis retourner voir Oralius."}}
D[3824] = {"Le seigneur-brute Gor'tesh",{"Trouver Gor'tesh, quelque part à l'ouest du rocher des Cognepeurs. Le tuer et rapporter la Tête coupée de Gor'tesh à Oralius, dans les Steppes ardentes."}}
D[3825] = {"Une tête d'ogre au bout d'une pique = une fête",{"Prendre la Tête coupée de Gor'tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique."}}
D[3841] = {"Un orphelin à la recherche d'un foyer",{"Parler à Quentin aux Mille pointes."}}
D[3842] = {"Une courte incubation",{"Apporter 2 Elixirs de Robustesse à Quentin, aux Mille pointes."}}
D[3843] = {"Un tout nouveau membre dans la famille",{"Emmenez votre Oeuf fragile de Fée fléchetteuse dans les Hinterlands et parlez à Agnar Beastamer. Dépêchez-vous, vous n’avez qu’une heure pour le trouver avant que le petit ne meure dans l’oeuf."}}
D[3844] = {"C'est un secret pour tout le monde",{"Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé."}}
D[3845] = {"C'est un secret pour tout le monde",{"Examiner les objets du paquet et les apporter à leur propriétaire."}}
D[3861] = {"COT-COT-CODEC !",{"Trouver de la Nourriture spéciale pour poulet et l'apporter à la poule que vous voulez aider. Lorsque vous l'aurez trouvée, encouragez-la (/acclame) avant d'essayer de lui donner la Nourriture spéciale pour poulet."}}
D[3881] = {"Le sauvetage de l'expédition",{"Apporter une Caisse de nourriture et de l'Equipement de recherche à Williden Marshal dans le Cratère d'Un'Goro."}}
D[3882] = {"Faites rouler les os",{"Apporter 8 Os de dinosaure à Etincelle Minerien, au cratère d'Un'Goro."}}
D[3883] = {"Écologie étrangère",{"Utiliser la Fiole de raclement pour récolter un Échantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l'intérieur du cratère d'Un'Goro. Chercher les chambres qui contiennent des larves suspendues.","","Apporter l'Échantillon de paroi de la ruche à Hol'anyee Marshal dans le cratère d'Un'Goro."}}
D[3884] = {"Le journal de Williden",{"Rapporter le Journal à Williden Marshal quelque part dans le Cratère d'Un'Goro."}}
D[3901] = {"Faites cliqueter les thorax !",{"Tuez 12 Squelettes Cliquethorax, puis retournez voir le Prêtre des ombres Sarvis au Glas."}}
D[3902] = {"La chasse aux trésors",{"Fouiller Le Glas et ses alentours pour trouver 6 caisses de Fournitures de récupération, et les ramener au Nécrogarde Saltain."}}
D[3903] = {"Milly Osworth",{"Parler à Milly Osworth."}}
D[3904] = {"Les vendanges de Milly",{"Apporter 8 seaux de la récolte de Milly à Milly Osworth à l'Abbaye de Comté-du-nord."}}
D[3905] = {"Manifeste des vendanges",{"Apporter le Manifeste des vendanges à Frère Neals dans l'Abbaye de Comté-du-nord."}}
D[3906] = {"Discordance des flammes",{"Partir pour la carrière dans le mont Rochenoire et tuer le Grand seigneur Pyron. Retourner voir Cœur-de-tonnerre une fois votre mission accomplie."}}
D[3907] = {"Discordance des flammes",{"Pénétrez dans les Profondeurs de Rochenoire et traquez le Seigneur Incendius. Tuez-le puis donner tous les renseignements que vous pourrez trouver à Cœur-de-tonnerre."}}
D[3908] = {"C'est un Secret pour tout le monde",{"Apporter l'Epée de Linken à Donova Antreneige au Berceau-de-l'Hiver."}}
D[3909] = {"L'élixir de Videre",{"Rechercher Gregan Gerbebière au nord de Féralas. Apprendre de lui comment vous pouvez acquérir l'élixir de Videre, puis retourner voir Donova Antreneige, au Berceau-de-l'Hiver."}}
D[3911] = {"Le dernier élément",{"Partir pour les Profondeurs de Rochenoire et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires."}}
D[3912] = {"Rendez-vous à la tombe",{"Se rendre au cimetière au-dehors de Gadgetzan et boire l'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan."}}
D[3913] = {"Une situation grave",{"Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver."}}
D[3914] = {"L'épée de Linken",{"Remettre l'Epée excellente de Linken à Linken dans le cratère d'Un'Goro."}}
D[3921] = {"Wenikee Boltbucket",{"Apporter le Samophlange cassé à Wenikee Bakaboulon."}}
D[3922] = {"Les Petites pièces",{"Apporter 15 Rondelles de métal à Wenikee Bakaboulon dans les Tarides."}}
D[3923] = {"Rilli Greasygob",{"Apporter le Samophlange cassé à Rilli Grassougob à Orgrimmar."}}
D[3924] = {"Manuel du Samophlange",{"Apporter le Manuel du Samophlange à Rilli Grassougob à Orgrimmar."}}
D[3941] = {"Un gnome dans le besoin",{"Trouver J.D. Collie dans la caverne du refuge des Marshal."}}
D[3942] = {"Les souvenirs de Linken",{"Trouver Eridan Ventebleu dans le sud de Gangrebois."}}
D[3961] = {"L'aventure de Linken",{"Apporter le Totem d'argent d'Aquementas à Linken au refuge des Marshal."}}
D[3962] = {"C'est dangereux d'y aller seul",{"Partir pour la crête de la Fournaise, au sud du refuge des Marshal.","","Trouver Coursembrase et utiliser le Totem pour dissiper son aura protectrice. Une fois Coursembrase vaincu, se procurer la Flamme dorée."}}
D[3981] = {"Le commandant Gor'shak",{"Trouver le commandant Gor'shak dans les Profondeurs de Rochenoire.","","Vous vous souvenez que le dessin maladroit représentait également des barreaux au-dessus du portrait. Peut-être devriez-vous rechercher un genre de prison."}}
D[3982] = {"Que se passe-t-il ?",{"Défendre Gor'shak."}}
D[4001] = {"Que se passe-t-il ?",{"Parler à Kharan Force-martel et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Barbe-de-bronze. Apporter ces renseignements à Thrall à Orgrimmar.","","Gor'shak a dit que Kharan était détenu dans une cellule proche."}}
D[4002] = {"Les Royaumes de l'est",{"Parler à Thrall si vous êtes <prêt/prête> à vous charger de la mission qu'il a prévue."}}
D[4003] = {"Un sauvetage royal",{"Tuer l'Empereur Thaurissan et libérer la Princesse Moira Barbe-de-bronze de son sort maléfique."}}
D[4004] = {"La Princesse sauvée ?",{"Retourner voir Thrall !"}}
D[4005] = {"Aquementas",{"Apporter le Livre d'Aquor, les Griffes argentées et le Coeur d'Arbrefer à Tanaris.","","Utiliser le Livre d'Aquor pour invoquer Aquementas.","","Après avoir terminé le totem, l'apporter à J.D. Collie au refuge des Marshal."}}
D[4021] = {"La contre-attaque !",{"Apporter un Morceau de la bannière de Krom'zar à Regthar Seuil-de-mort, à l'ouest de la Croisée."}}
D[4022] = {"Un goût de flammes",{"Montrer à Cyrus Therepentous l'Ecaille des dragons noirs que vous avez reçue de Kalaran Windblade."}}
D[4023] = {"Un goût de flammes",{"Montrer à Cyrus Lerepenti une preuve de votre valeur.","","Vous avez le sentiment que Cyrus sait déjà que vous êtes indigne."}}
D[4024] = {"Un goût de flammes",{"Partez pour les Profondeurs de Rochenoire et tuez Bael'Gar.","","Vous savez seulement que le géant demeure à l'intérieur des Profondeurs de Rochenoire. N'oublier pas d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence flamboyante.","","Apporter l'Essence flamboyante enchâssée à Cyrus Lerepenti."}}
D[4041] = {"L'élixir de Videre",{"Apportez-moi de l'Evoroot, et je vous ferai de l'élixir de Videre sans problème.","","Je connais toutes sortes de choses à propos des herbes et de l'alchimie… Tenez, par exemple, laissez-moi vous raconter la fois où j'ai transformé le fromage que j'étais sur le point de manger au déjeuner en or... Hé... Où allez-vous ?"}}
D[4061] = {"La révolte des machines",{"S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania.","","Theodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments."}}
D[4062] = {"La révolte des machines",{"Apporter l'Échantillon de fragment d'élémentaire à Lotwil Veriatus.","","Theodora vous a dit qu'il se trouvait dans un camp à l'est."}}
D[4063] = {"La révolte des machines",{"Trouver et tuer le Seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium."}}
D[4081] = {"TUER À VUE : nains Sombrefer",{"Pénétrez dans les Profondeurs de Rochenoire et tuez les vils agresseurs !","","Le chef de guerre Sangredent veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie."}}
D[4082] = {"TUER À VUE : Officiers de haut rang Sombrefer",{"Pénétrez dans les Profondeurs de Rochenoire et tuez les vils agresseurs !","","Le Chef de guerre Sangredent veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie."}}
D[4083] = {"Le Calice spectral",{"Le Calice spectral flotte dans les airs, descendant et remontant tout doucement… au rythme d'un cœur agonisant."}}
D[4084] = {"Coeur d'argent",{"Trouver 11 Griffes d'argent et 1 Cœur d'Arbrefer pour Eridan Ventebleu à Gangrebois."}}
D[4101] = {"Purifiez Gangrebois",{"Apporter 15 Ambres de sang à Arathandris Argeciel à Gangrebois."}}
D[4102] = {"Purifiez Gangrebois",{"Apporter 15 Ambres de sang à Maybess Brise-des-rivières à Gangrebois."}}
D[4103] = {"Du baume en chassant",{"Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.","","En échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé."}}
D[4104] = {"Du baume par la pioche",{"Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.","","Si vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé."}}
D[4105] = {"Du baume contre une récolte",{"Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l'insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.","","Lorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j'ai déjà préparé."}}
D[4106] = {"Du baume contre des peaux",{"Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !","","Lorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve."}}
D[4107] = {"Du baume contre des désenchantements",{"Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.","","Je n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !"}}
D[4108] = {"Du baume en chassant",{"Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.","","En échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé."}}
D[4109] = {"Du baume par la pioche",{"Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.","","Si vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé."}}
D[4110] = {"Du baume contre une récolte",{"Grâce à une balise cénarienne, les herboristes expérimentés peuvent distinguer l'insidieuse gangrimpante, un parasite malfaisant produit par la corruption de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le baume végétal cénarien.","","Lorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les brins de gangrimpante si vous avez la balise cénarienne. En échange je vous donnerai du baume cénarien que j'ai déjà préparé."}}
D[4111] = {"Du baume contre des peaux",{"Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparamment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !","","Lorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve."}}
D[4112] = {"Du baume contre des désenchantements",{"Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.","","Je n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !"}}
D[4113] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4114] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4115] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4116] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4117] = {"La navetille corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4118] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4119] = {"Dragon nocrturne corrompu",{"Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal."}}
D[4120] = {"La force de la corruption",{"Talo Sabot-de-ronce, du Camp Mojache en Féralas, voudrait que vous tuiez 12 Grizzlys de la griffe colérique et 12 Ravageurs Gangrepatte, à Gangrebois."}}
D[4121] = {"Situation précaire",{"Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Rochenoire, jusqu'à la gorge des Vents brûlants.","","Rappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark.","","On vous demandera également de remettre vos chaînes en thorium à Lexlort."}}
D[4122] = {"Grark Lorkrub",{"Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort vous a dit qu'il a été vu pour la dernière fois dans une imposante forteresse des Rochenoires.","","Une fois que vous aurez trouvé Grark Lorkrub, enchaînez-le avec les chaînes en thorium, puis ramenez-le par le mont Rochenoire jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté et le mettront sous bonne garde."}}
D[4123] = {"Le Coeur de la montagne",{"Apporter le Cœur de la montagne à Maxwort Uberbrille dans les Steppes ardentes."}}
D[4124] = {"Le messager disparu",{"Parler à Ginro Attisâtre dans le bastion de Pennelune."}}
D[4125] = {"Le messager disparu",{"Localiser le bateau du messager quelque part le long de la côte de Féralas."}}
D[4126] = {"Hurley Blackbreath",{"Apporter la Recette perdue de la Tonnebière à Ragnar Tonnebière à Kharanos."}}
D[4127] = {"Débris de bateau",{"Retourner au bastion de Pennelune et montrer à Ginro Attisâtre le Couteau perdu que vous avez découvert."}}
D[4128] = {"Ragnar Thunderbrew",{"Parler à Ragnar Tonnebière."}}
D[4129] = {"Le couteau révélé",{"Apporter le Couteau perdu à Quintis Gentecime au bastion de Pennelune."}}
D[4130] = {"La lecture psychométrique",{"Parler à Ginro Attisâtre dans le bastion de Pennelune."}}
D[4131] = {"Les gnolls Griffebois",{"Fouiller les Camps des gnolls Griffebois dans la partie sud de Féralas pour trouver des indices sur les possessions du messager ou sur le messager lui-même."}}
D[4132] = {"Opération : Mort à Forgehargne",{"Voyagez jusqu'aux Profondeurs de Rochenoire et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Sangredent."}}
D[4133] = {"Vivian Lagrave",{"Parler à la maîtresse des ombres Vivian Lagrave à Kargath."}}
D[4134] = {"La recette perdue de la Tonnebière",{"Apporter la Recette perdue de la Tonnebière à Vivian Lagrave à Kargath."}}
D[4135] = {"Le Gouffre grouillant",{"À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le Gouffre grouillant. D'après le message, il se trouve au sud des camps des gnolls Griffebois."}}
D[4136] = {"Ribbly Fermevanne",{"Apporter la Tête de Ribbly à Yuka Fermevanne dans les Steppes ardentes."}}
D[4141] = {"Muigin et Larion",{"Récolter 15 Pétales-de-sang et retourner voir Muigin."}}
D[4142] = {"Visite à Gregan",{"Apporter une Pétale-de-sang à Gregan Gerbebière en Féralas."}}
D[4143] = {"Brouillard maléfique",{"Récupérer 5 Échantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro."}}
D[4144] = {"Les pousses de Pétales-de-sang",{"Voici ce que nous allons faire, <nom>. Procurez-vous des pousses de Pétales-de-sang. De jeunes plantes, pas encore parvenues au stade adulte, vous comprenez ? Puis apportez-les ici. Alors je verrai ce dont la brume atal'ai est capable.","","Vous pourriez penser que c'est le désir de vengeance qui me guide, mais… vous auriez raison…nnEn vérité, je connais le chemin pour nous sortir d'ici, mais tant que Larion n'admet pas que j'ai raison, je ne bouge pas !","","C'est assez : partez et trouvez des pousses de Pétales-de-sang afin que nous nous amusions un peu !"}}
D[4145] = {"Larion et Muigin",{"Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal."}}
D[4146] = {"Carburant de baguette",{"Remettre la Baguette déchargée et 5 Échantillons de brume atal'ai à Larion au refuge des Marshal."}}
D[4147] = {"Atelier de Marvon",{"Se rendre à l'Atelier de Marvon Chercherivet à Cabestan."}}
D[4148] = {"La baguette Pétale-de-sang",{"Pour faire fonctionner la baguette, nous avons besoin d'un spécimen de ses futures victimes. Rendez-vous dans le cratère et rapportez une pousse de Pétale-de-sang. Je pourrai alors régler l’appareil pour qu'il prenne soin des petits camarades de Muigin…nnS'il n'était pas si obstiné, nous serions déjà sur le chemin du retour… En attendant, je ne peux que lui montrer que ses gamineries ne me perturbent aucunement…"}}
D[4161] = {"Une recette kaldorei",{"Collecter 7 Petites pattes d'araignée pour Zarrin, à Dolanaar."}}
D[4181] = {"Ingénierie des gobelins",{"Apporter le Manuel d'ingénierie à Nixx Elastirouage à Gadgetzan si vous souhaitez en apprendre davantage sur l'ingénierie gobeline."}}
D[4182] = {"La menace des draconiens",{"Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Ruissecorne une fois la tâche accomplie."}}
D[4183] = {"Les véritables maîtres",{"Voyager jusqu'à Comté-du-Lac et remettre la Lettre d'Helendis Ruissecorne au Magistrat Salomon."}}
D[4184] = {"Les véritables maîtres",{"Voyager jusqu'à Hurlevent et remettre la Demande d'aide de Salomon au généralissime Bolvar Fordragon.","","Bolvar demeure dans le Donjon de Hurlevent."}}
D[4185] = {"Les véritables maîtres",{"Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor."}}
D[4186] = {"Les véritables maîtres",{"Apporter le Décret de Bolvar au Magistrat Salomon à Comté-du-Lac."}}
D[4201] = {"Le philtre d'amour",{"Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Rochenoire."}}
D[4221] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4222] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4223] = {"Les véritables maîtres",{"Parler au maréchal Maxwell dans les Steppes ardentes."}}
D[4224] = {"Les véritables maîtres",{"Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche.","","Vous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord."}}
D[4241] = {"Maréchal Windsor",{"Partir pour le mont Rochenoire au nord-ouest et pénétrer dans les Profondeurs de Rochenoire. Découvrir ce qu'il est advenu du Maréchal Windsor.","","Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison."}}
D[4242] = {"Espoir abandonné",{"Donner les mauvaises nouvelles au maréchal Maxwell."}}
D[4243] = {"À la poursuite d'A-mi 01",{"Trouver A-mi 01 dans le Cratère d'Un'Goro."}}
D[4244] = {"À la poursuite d'A-mi 01",{"Trouver une Armature en mithril et retourner auprès d'A-mi 01 dans le Cratère d'Un'Goro."}}
D[4245] = {"À la poursuite d'A-mi 01",{"Escorter A-mi 01 sur le chemin du retour jusqu'à Karna Songerrance dans le Cratère d'Un'Goro."}}
D[4261] = {"Esprit d'un ancien",{"Escorter Arei jusqu'à un lieu sûr, puis parler à Kayneth Mortebrise au Chant des forêts, dans l'est d'Orneval."}}
D[4262] = {"Grand seigneur Pyron",{"Tuer le Grand seigneur Pyron et retourner voir Jalinda Brindille.","","Jalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?"}}
D[4263] = {"Incendius !",{"Trouver le Seigneur Incendius dans les Profondeurs de Rochenoire et le détruire !"}}
D[4264] = {"Une Note chiffonnée",{"Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout..."}}
D[4265] = {"L'évasion de la ruche",{"Libérer Raschal de la ruche de Zukk'ash.","","Revenir voir Ginro Attisâtre au bastion de Pennelune et lui dire que Raschal est sain et sauf."}}
D[4266] = {"Accueil d'un héros",{"Parler à Shandris Pennelune dans le bastion de Pennelune."}}
D[4267] = {"L'ascension des silithides",{"Apporter le Rapport de Raschal à Gracina Forcesprit à Darnassus."}}
D[4281] = {"La livraison à Thalanaar",{"Apporter le Vieux colis à Falfindel Gardevoie, à Thalanaar."}}
D[4282] = {"Un espoir en lambeaux",{"Rapporter les Informations égarées du maréchal Windsor.","","Le maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne."}}
D[4283] = {"CINQUANTE ! OUI !",{"Oralius veut 50 Médaillons de Rochenoire. Il y a de fortes chances de trouver ces médaillons sur les orcs des Steppes ardentes."}}
D[4284] = {"Cristaux de puissance",{"Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal."}}
D[4285] = {"Le Pylône nord",{"Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro."}}
D[4286] = {"Du beau matériel",{"Se rendre dans les Profondeurs de Rochenoire et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Rochenoire."}}
D[4287] = {"Le Pylône est",{"Trouver l'emplacement du Pylône de cristal est dans le Cratère d'Un'Goro."}}
D[4288] = {"Le Pylône ouest",{"Découvrir l'emplacement du Pylône de cristal ouest."}}
D[4289] = {"Les gorilles d'Un'Goro",{"Apporter 2 Peaux de gorille d'Un'Goro, 2 Peaux de marteleur d'Un'Goro et 2 Peaux de foudroyeur d'Un'Goro à Torwa le Guide à l'entrée du cratère d'Un'Goro."}}
D[4290] = {"La nourriture de Lar'korwi",{"Trouver la dernière victime de Lar'korwi et voler un Morceau de carcasse d'un battrodon, puis retourner voir Torwa le Guide au Cratère d'Un'Goro."}}
D[4291] = {"Un parfum pour Lar'korwi",{"Apporter 2 Glandes de phéromone de ravasaure à Torwa le Guide près de l'entrée du Cratère d'Un'Goro."}}
D[4292] = {"Un appât pour Lar'korwi",{"En utilisant le contenu de la Sacoche de Torwa, appeler Lar'korwi et le vaincre. Puis apporter la Tête de Lar'korwi à Torwa le Guide près de l'entrée du Cratère d'Un'Goro."}}
D[4293] = {"Un échantillon de gelée...",{"Ramassez des Échantillons de gelée de Gangrebois sur n'importe quel type de gelée de Gangrebois. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du chimiste Fuely à Fossoyeuse, décelez les échantillons le plus corrompus. Apportez 5 Échantillons corrompus de Gangrebois que vous aurez obtenus au Chimiste Fuely."}}
D[4294] = {"... et une fournée de limon",{"Ramassez des Échantillons de gelée d'Un'Goro sur sur n'importe quel type de gelée du Cratère d'Un'Goro. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du chimiste Fuely à Fossoyeuse, décelez les échantillons les plus purs. Apporter 5 Échantillons purs d'Un'Goro que vous aurez obtenus au Chimiste Fuely."}}
D[4295] = {"La bière de Rocknot",{"Oh, de la bière ! Je tuerais pour une bonne bière de Sombrefer, <nom> ! Vite, je deviens sobre ! Je le sais car la sobriété trouble ma vision… et cela vous fait ressembler à celui que j'ai massacré la semaine dernière !"}}
D[4296] = {"Tablette des Sept",{"Apporter la Transcription de la tablette à Maxwort Uberbrille dans les Steppes ardentes."}}
D[4297] = {"Nourriture pour bébé",{"Apporter 5 Flanchets de traqueur Crins-d'argent à Agnar Domptebêtes dans les Hinterlands."}}
D[4298] = {"L'amour d'un parent",{"Parler à Agnar Domptebêtes dans les Hinterlands."}}
D[4300] = {"Les armes aux lames d'os",{"Apporter 8 Griffes blanches de ravasaure à Jes'rimon à Orgrimmar."}}
D[4301] = {"Le puissant U'cha",{"Apporter la Peau d'U'cha à Torwa le Guide à l'entrée du Cratère d'Un'Goro."}}
D[4321] = {"Ceci explique cela",{"Parler à J.D. Collie dans un moment."}}
D[4322] = {"Evasion !",{"Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell."}}
D[4324] = {"Yuka Fermevanne",{"Parler à Yuka Fermevanne dans les Steppes ardentes."}}
D[4341] = {"Kharan Force-martel",{"Aller dans les Profondeurs de Rochenoire et trouver Kharan Force-martel.","","Le roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison."}}
D[4342] = {"Légende de Kharan",{"Écouter Kharan Force-martel raconter son histoire."}}
D[4343] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4361] = {"Le porteur des mauvaises nouvelles",{"Retourner à Forgefer et apporter la mauvaise nouvelle au Roi Magni Barbe-de-bronze."}}
D[4362] = {"Le destin du Royaume",{"Retourner dans les Profondeurs de Rochenoire et secourir la Princesse Moira Barbe-de-bronze, prisonnière de l'Empereur Dagran Thaurissan."}}
D[4363] = {"La surprise de la Princesse",{"Retourner à Forgefer et parler au roi Magni Barbe-de-bronze."}}
D[4381] = {"Cristal de restauration",{"Le Pilon vous permet de combiner les cristaux de puissance verts avec les jaunes.","","Si on se réfère au manuel de J.D., cette combinaison sert à vous soigner, vous et vos alliés."}}
D[4382] = {"Cristal de concentration",{"Le Pilon vous permet de combiner les cristaux de puissance verts avec les bleus.","","Si on se réfère au manuel de J.D., cette combinaison sert à augmenter l'Esprit."}}
D[4383] = {"Cristal de protection",{"Le Pilon vous permet de combiner les cristaux de puissance verts avec les rouges.","","Si on se réfère au manuel de J.D., cette combinaison sert à augmenter la protection contre les dégâts physiques."}}
D[4384] = {"Cristal de réduction",{"Le Pilon vous permet de combiner les cristaux de puissance rouges avec les bleus.","","Si on se réfère au manuel de J.D., cette combinaison sert à réduire la Défense de l'adversaire."}}
D[4385] = {"Cristal d'explosion",{"Le Pilon vous permet de combiner les cristaux de puissance rouges avec les jaunes.","","Si on se réfère au manuel de J.D., cette combinaison peut être utilisée pour créer une grande explosion qui inflige des dégâts à vos ennemis."}}
D[4386] = {"Cristal de rétribution",{"Le Pilon vous permet de combiner les cristaux de puissance bleus avec les jaunes.","","Si on se réfère au manuel de J.D., cette combinaison sert à créer un bouclier qui inflige des dégâts aux ennemis."}}
D[4401] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4402] = {"Surprise aux pommes de cactus de Galgar",{"Apportez à Galgar 10 Pommes de cactus. Il vous a précisé qu'elles se trouvaient souvent à côté des cactus."}}
D[4403] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4421] = {"La corruption des Jadefeu",{"Tuer 11 Gangreliges Jadefeu, 9 Traqueurs des ombres Jadefeu, 9 Voleurs Jadefeu et Xavathras. Retourner voir Eridan Ventebleu, à Gangrebois, quand la mission est terminée."}}
D[4441] = {"Anciens corrompus",{"Aller à Darnassus et utiliser la Fiole d'Eridan dans le Temple de la Lune, pour obtenir une Fiole d'eau bénite. Retourner voir Eridan avec la Fiole pleine."}}
D[4442] = {"Purifié !",{"Attendre un moment avant de reparler à Eridan."}}
D[4443] = {"La navetille corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4444] = {"La navetille corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4445] = {"La navetille corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4446] = {"La navetille corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4447] = {"Dragon nocturne corrompu",{"Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal."}}
D[4448] = {"Dragon nocturne corrompu",{"Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal."}}
D[4449] = {"Piégé !",{"Tuer 8 Géologues Sombrefer et rapporter 15 morceaux d'Etoffe de soie à la personne enfermée dans les toilettes de la gorge des Vents brûlants."}}
D[4450] = {"Grand livre de Tanaris",{"Prendre la copie du Livre de Bonnacier, puis collecter les objets qui y sont listés avant d'aller voir Froisse Bonnacier, à Tanaris."}}
D[4451] = {"La Clé de la liberté",{"Aller dans la gorge des Vents brûlants et trouver une utilisation à la Clé des toilettes de Crasseboue que vous avez trouvée."}}
D[4461] = {"La navetille corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une navetille Les ramures visibles en sont coriaces et tannées, et un voile visqueux en pend. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4462] = {"Dragon nocturne corrompu",{"Vous avez découvert la version malade et souffreteuse d'une plante, le dragon nocturne. Les fruits qui pendent de la plante sont pourris et empoisonnés. La plante a désespérément besoin de soins pour retrouver son état normal."}}
D[4463] = {"Libram de rumination",{"Présentez les composants, mortel.","","J'exige également trente pièces d'or en paiement de cette création."}}
D[4464] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4465] = {"La fleur-de-chant corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-chant. Une odeur âcre et malsaine émane de la plante. Celle-ci a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4466] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4467] = {"La fleur-de-vent corrompue",{"Vous avez découvert une version maladive et souffreteuse de ce qui s'avère être une fleur-de-vent. Les baies qui en pendent sont pourries et empoisonnées. La plante a désespérément besoin de soins pour avoir une chance de recouvrer son état normal."}}
D[4481] = {"Libram de constitution",{"Chaque chose a son prix en ce monde. Le prix de l'article précis que vous cherchez est de trente pièces d'or.","","Naturellement, je garderai la majorité des composants que vous avez ramassés. Mais pas d'inquiétude, vous aurez votre bijou."}}
D[4482] = {"Libram de ténacité"}
D[4483] = {"Libram de résilience",{"Si c'est de la résistance que vous désirez, c'est trente pièces d'or que je demande."}}
D[4484] = {"Libram de voracité",{"Ne me faites pas perdre mon temps, <nom>. Donnez-moi ce que je demande. Trente pièces d'or et les composants."}}
D[4485] = {"Le Tome de noblesse",{"Parler à Duthorian Rall, à Stormwind."}}
D[4486] = {"Le Tome de noblesse",{"Parler à Duthorian Rall, à Hurlevent."}}
D[4487] = {"Invocation d'un palefroi corrompu",{"Parler à Strahad Farsan, à Cabestan."}}
D[4488] = {"Invocation d'un palefroi corrompu",{"Parler à Strahad Farsan, à Cabestan."}}
D[4489] = {"Invocation d'un palefroi corrompu",{"Parler à Strahad Farsan, à Cabestan."}}
D[4490] = {"Invocation d'un palefroi corrompu",{"Parler à Strahad Farsan, à Cabestan pour apprendre à invoquer un Palefroi corrompu."}}
D[4491] = {"Un peu d'aide de mes amis",{"Conduire Ringo auprès de Spraggle Frock, au refuge des Marshal.","","Si Ringo s'évanouit, utiliser la Gourde de Spraggle pour le réanimer."}}
D[4492] = {"Perdu !",{"Trouver Ringo sur la crête de la Fournaise."}}
D[4493] = {"La marche des silithides",{"Parler à l'Alchimiste Pilonzugg à Gadgetzan."}}
D[4494] = {"La marche des silithides",{"Parler à l'Alchimiste Pilonzugg à Gadgetzan."}}
D[4495] = {"Un bon ami",{"Trouver Iverron près de la grotte au nord."}}
D[4496] = {"Fiasco dans la jungle",{"Apporter une Glande olfactive Gorishi et 5 Échantillons d'humus d'Un'Goro à l'Alchimiste Pilonzugg, à Gadgetzan."}}
D[4501] = {"Attention aux pterreurdactyles",{"Tuer 10 Pterreurdactyles et 15 Pterreurdactyles frénétiques, puis parler à Spraggle Frock, au refuge des Marshal."}}
D[4502] = {"Activité volcanique",{"Collecter 9 échantillons de Cendres d'Un'Goro sur les Élémentaires de feu autour du volcan du Cratère d'Un'Goro, puis les apporter à Liv Rafistolier, à Cabestan."}}
D[4503] = {"La machine volante de Shizzle",{"Apporter 8 Ecailles étoilées de dimeurtrodon et 8 Ecailles étoilées de pterreurdactyles à Shizzle, au refuge des Marshal."}}
D[4504] = {"Ultra collant",{"Collecter 12 échantillons de Goudron ultra collant pour Tran'rek, à Gadgetzan."}}
D[4505] = {"Puits de la corruption",{"Collecter un échantillon d'eau corrompue dans le puits de lune des satyres Jadefeu, puis le rapporter à Winna Hazzard, au Poste de la Vénéneuse."}}
D[4506] = {"Sabres corrompus",{"Amener le chaton de Winna au puits de lune corrompu, le relâcher, puis le rapporter à Winna.","","Une fois de retour auprès de Winna, cliquer sur le chat pour le lui rendre."}}
D[4507] = {"Le pion prend la reine",{"Invoquer la Reine gorishi et la vaincre.","","Apporter le Cerveau de reine gorishi à l'alchimiste Pilonzugg, à Gadgetzan."}}
D[4508] = {"Le calme avant la tempête",{"Apporter le Rapport de Pilonzugg sur Un'Goro à Gracina Forcesprit, à Darnassus."}}
D[4509] = {"Le calme avant la tempête",{"Apporter le Rapport de Pilonzugg sur Un'Goro à Zilzibin Kongadok, à Orgrimmar."}}
D[4510] = {"Le calme avant la tempête",{"Apporter le Reçu bancaire à Idriana, à la banque de Darnassus."}}
D[4511] = {"Le calme avant la tempête",{"Apporter le Reçu bancaire à Karus, à la banque d'Orgrimmar."}}
D[4512] = {"Un grand périple pour une petite gelée",{"Apporter 6 Pots de Limons maudits remplis et 6 Pots de Limons corrompus remplis à Laris Bringuefourbi, à Forgefer."}}
D[4513] = {"Un grand périple pour une petite Gelée",{"Apporter 10 Pots remplis d'échantillon pur à Laris Bringuefourbi, à Forgefer.","","Si vous éprouvez des difficultés à les trouver, allez voir Laris pour obtenir plus d'indices."}}
D[4521] = {"Gardiens sauvages",{"Trull Faillemort de Gangrebois veut que vous tuiez 15 Chouettards déchaînés et 15 Chouettards éreintés."}}
D[4542] = {"Un message pour le poste de Librevent",{"Apporter le Message urgent au garde-falaise Longue-corne au Poste de Librevent."}}
D[4561] = {"Test pour impuretés, le Cratère d'Un'Goro",{"Vous prenez un échantillon de gelée du Cratère d'Un'Goro et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de Pétri, vos échantillons de Gelée d'Un'Goro purifiés et d'autres restes."}}
D[4581] = {"Kayneth Mortebrise",{"Apporter la Note de Shindrell à Kayneth Mortebrise au Chant des Forêts."}}
D[4601] = {"Le Brille-o-Matic 5200 !",{"Insérer un Objet sali dans le Brille-o-Matic 5200 et s'assurer d'avoir trois pièces d'argent pour démarrer la machine."}}
D[4602] = {"Le Brille-o-Matic 5200 !",{"Insérer un Objet sali dans le Brille-o-Matic 5200 et s'assurer d'avoir trois pièces d'argent pour démarrer la machine."}}
D[4603] = {"Le Brille-o-Matic décape encore",{"Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer !"}}
D[4604] = {"Le Décapeur décape encore",{"Le Décapeur 5200 est vide et attend un objet à nettoyer ainsi que trois pièces d'argent pour démarrer !"}}
D[4605] = {"Le Brille-o-Matic 5200 !",{"D'un coup le Décapeur 5200 s'arrête net. Un petit carillon émet un \"ding\" clair et la trappe de l'appareil s'ouvre. À l'intérieur de la machine vous découvrez une petite boîte garnie d'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n'a pas fonctionné.","","Bon, il n'y a qu'un seul moyen de savoir si l'objet à bel et bien été nettoyé ou non..."}}
D[4606] = {"Le Brille-o-Matic 5200 !",{"D'un coup le Décapeur 5200 s'arrête net. Un petit carillon émet un \"ding\" clair et la trappe de l'appareil s'ouvre. À l'intérieur de la machine vous découvrez une petite boîte garnie d'un noeud. Il semble que la machine emballe les objets après les avoir nettoyés et qu'elle se donne la peine de les empaqueter dans une jolie boîte même quand elle n'a pas fonctionné.","","Bon, il n'y a qu'un seul moyen de savoir si l'objet à bel et bien été nettoyé ou non..."}}
D[4621] = {"En avant toute, amiral !",{"Tuer l'amiral Corne-de-mer et le baron Revilgaz de Baie-du-Butin, puis retrouver l'amiral Firallon à bord du Voile cramoisi, au large des côtes de la vallée de Strangleronce."}}
D[4641] = {"Votre place en ce monde",{"Parler à Gornek. Souvenez-vous que Kaltunk vous a indiqué où il se trouvait sur votre carte et vous a dit que Gornek résidait dans l'Antre, un bâtiment vers l'ouest."}}
D[4642] = {"Trafic d'influences",{"Apporter un Échantillon de Limon mélangé au Chimiste Fuely à Fossoyeuse."}}
D[4661] = {"Test de corruption, Gangrebois",{"Vous prenez un échantillon de gelée de Gangrebois et le placez dans les différents tubes et vases à bec qui sont sur la table. La gelée se met à bouillir et change de couleur. Lorsque la réaction prend fin, vous apercevez dans la petite boîte de pétri, vos échantillons de Gelée de Gangrebois altérés et d'autres restes."}}
D[4681] = {"Échouage",{"Récupérer les Restes de tortue de mer sur le Squelette de la tortue de mer, dans les eaux à l’ouest d’Auberdine, puis parler à Gwennyth Bly'Leggonde, à Auberdine."}}
D[4701] = {"Abattez-la",{"Allez au Pic Rochenoire et anéantissez la source de la menace. Quand vous avez quitté Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs."}}
D[4721] = {"Les gardiens sauvages",{"Trull Faillemort à Gangrebois veut que vous chassiez 10 Chouettards berserk au Berceau-de-l'Hiver."}}
D[4722] = {"La tortue de mer échouée",{"Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine."}}
D[4723] = {"La créature marine échouée",{"Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."}}
D[4724] = {"La maîtresse de meute",{"Tuer Halycon, la maîtresse de la meute des worgs Hache-sanglante."}}
D[4725] = {"La tortue de mer échouée",{"Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine."}}
D[4726] = {"L'essence de rejeton",{"Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Brikolette Toutevapeur à la Corniche des flammes dans les Steppes ardentes."}}
D[4727] = {"La tortue de mer échouée",{"Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine."}}
D[4728] = {"La créature marine échouée",{"Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."}}
D[4729] = {"Les animaux exotiques de Kibler",{"Aller au Pic Rochenoire et trouver de Jeunes worgs Hache-sanglante. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler."}}
D[4730] = {"La créature marine échouée",{"Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."}}
D[4731] = {"La tortue de mer échouée",{"Apporter la Boîte aux marques étranges à Gwennyth Bly'Leggonde à Auberdine."}}
D[4732] = {"La tortue de mer échouée",{"Apporter les Restes de tortue de mer à Gwennyth Bly'Leggonde à Auberdine."}}
D[4733] = {"La créature marine échouée",{"Apporter les Os de créature marine à Gwennyth Bly'Leggonde à Auberdine."}}
D[4734] = {"Un oeuf congelé",{"Utiliser le Prototype d'Oeufilloscope sur un oeuf dans la Colonie."}}
D[4735] = {"La collecte d'oeufs",{"Apporter 8 Œufs de dragon collectés et le Module collectronique à Brikolette Toutevapeur à la Corniche des flammes dans les Steppes Ardentes."}}
D[4736] = {"À la recherche de Menara Voidrender",{"Parler à Menara Taillevide dans les Tarides."}}
D[4737] = {"À la recherche de Menara Taillevide",{"Parler à Menara Taillevide dans les Tarides."}}
D[4738] = {"À la recherche de Menara Voidrender",{"Parler à Menara Taillevide dans les Tarides."}}
D[4739] = {"À la recherche de Menara Taillevide",{"Parler à Menara Taillevide dans les Tarides."}}
D[4740] = {"On recherche : Fondeboue !",{"Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau.","","Annoncer la mort de Fondeboue à la Sentinelle Glynda Nal'Shea à Auberdine."}}
D[4741] = {"Les gardiens sauvages",{"Trull Faillemort à Gangrebois veut que vous chassiez 13 Chouettards lunaires."}}
D[4742] = {"Le Sceau d'ascension",{"Trouver les trois gemmes de commandement : la Gemme de Brûleronce, la Gemme de Pierre-du-pic et la Gemme de Hache-sanglante. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan.","","Les généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Brûleronce ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Hache-sanglante."}}
D[4743] = {"Le sceau de l'ascension",{"Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée.","","À cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !"}}
D[4761] = {"Thundris Tissevent",{"Parler à Thundris Tissevent, à Auberdine."}}
D[4762] = {"La Bondissante",{"Aller au nord d'Auberdine, à la première chute d'eau, le long de la Bondissante et prélever un échantillon de l'eau de l'étang.","","Retourner voir Thundris Tissevent, à Auberdine, avec le Prélèvement de la Bondissante."}}
D[4763] = {"La corruption des Noirbois",{"Remplir le Bol de purification vide au Puits de lune d'Auberdine.","","Collecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois.","","Mélanger les échantillons de nourriture à l'eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur.","","Prendre son Talisman de corruption et l'apporter à Thundris Tissevent, à Auberdine."}}
D[4764] = {"Le fermoir de Frèteruine",{"Apporter le Fermoir de Frèteruine à Mayara Luisaile, dans les Steppes ardentes."}}
D[4765] = {"La livraison à Bellornière",{"Apporter la Caisse de Bellornière à Remington Bellornière, à Hurlevent."}}
D[4766] = {"Mayara Luisaile",{"Parler à Mayara Luisaile, dans les Steppes Ardentes."}}
D[4767] = {"Le coursier du vent",{"Apporter 10 Œufs de wyverne de Haut-perchoir à Elu au poste de Librevent."}}
D[4768] = {"La tablette de Sombrepierre",{"Apporter la Tablette de Sombrepierre à l'ombremage Vivian Lagrave à Kargath."}}
D[4769] = {"Vivian Lagrave et la tablette de Sombrepierre",{"Parler à l'ombremage Vivian Lagrave."}}
D[4770] = {"Vers le pays natal",{"Escorter Pao'ka Montagne-agile à partir de Haut-perchoir, puis parler à Motega Crin-de-feu au poste de Blanc-relais."}}
D[4771] = {"Le gambit de l'aube",{"Placer le Gambit de l'aube dans la Chambre des visions de la Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink."}}
D[4781] = {"Les composants de la robe sanglante dorée enchantée",{"Apporter une Barre d'or à Xizk Beaupiqué dans la vallée de Strangleronce."}}
D[4782] = {"Les composants de la robe sanglante dorée enchantée",{"Retourner voir Menara Taillevide dans les Tarides."}}
D[4783] = {"Les composants de la robe sanglante dorée enchantée",{"Apporter 10 Fioles de sang de Fielfurie et 1 Pierre infernale inférieure à Menara Taillevide dans les Tarides."}}
D[4784] = {"Les composants de la robe sanglante dorée enchantée",{"Apporter du Fil d'or fin, 2 Charbons ardents et un Fragment d'âme à Menara Taillevide dans les Tarides."}}
D[4785] = {"Fil d'or fin",{"Voilà, <nom>. Et s'il vous plaît, dites à Menara que nous la saluons.","","Nous espérons beaucoup de vous. Peut-être que, lorsque la Légion sera à genoux, votre nom et votre puissance seront loués haut et fort. Je suis impatient !"}}
D[4786] = {"La Robe terminée",{"Attendre que Menara Taillevide ait terminé votre robe puis lui parler de nouveau."}}
D[4787] = {"L'œuf antique",{"Apporter l'Oeuf antique à Yeh'kinya à Tanaris."}}
D[4788] = {"Les dernières tablettes",{"Apporter la Cinquième et la Sixième tablette Mosh'aru au Prospecteur Botte-de-fer à Tanaris."}}
D[4801] = {"L'E'ko des Sabres-de-givre",{"Au Berceau-de-l'Hiver, vous combattrez de grands félins appelés \"sabres-de-givre\". Ces bêtes sont incroyablement rapides et vicieuses. Si vous voulez gagner la vitesse des sabres-de-givre, apportez-moi l'Eko que vous trouverez sur eux.","","Souvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko."}}
D[4802] = {"L'E'ko des Tombe-hiver",{"Au Berceau-de-l'Hiver, vous combattrez des créatures perdues connues sous le nom de furbolgs Tombe-hiver. Sous l'égide de leur maître, ils ont gagné une force incroyable. Si vous voulez acquérir la puissance des Tombe-hiver, apportez-moi l'E'ko que vous leur prendrez.","","Souvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko."}}
D[4803] = {"L'E'ko des Crocs acérés",{"Au Berceau-de-l'Hiver, vous trouverez de grands ours à la peau très épaisse. Ces ours aux crocs acérés sont bien protégés et peuvent supporter beaucoup. Si vous souhaitez gagner la résistance au feu, apportez-moi l'E'ko que vous trouverez auprès des Crocs acérés.","","Souvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko."}}
D[4804] = {"L'E'ko de Noroît",{"Au Berceau-de-l'Hiver, vous combattrez de grandes créatures ailées nommées des Noroît. Ces bêtes peuvent se servir de la magie de glace. Si vous voulez devenir résistant à la glace, apportez-moi l'E'ko que vous leur prendrez.","","Souvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko."}}
D[4805] = {"L'E'ko des Chardons de Glace",{"Au Berceau-de-l'Hiver, vous combattrez de grandes créatures nommées yétis Chardon de glace. Ces bêtes sont lentes mais capables d'éviter de nombreux coups grace à l'épaisseur de leur fourrure. Si vous voulez gagner le pouvoir d'esquiver les attaques, apportez-moi l'E'ko que vous leur prendrez.","","Souvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko."}}
D[4806] = {"L'E'ko de Cognegivre",{"Au Berceau-de-l'Hiver, vous affronterez des grands géants des glaces, les Cognegivre. Ils sont la force et la puissance incarnées. Si vous voulez vous imprégner de la force des Cognegivre, rapportez-moi les E'kos que vous trouverez sur eux.","","Souvenez-vous, le charme de Mau'ari doit être dans votre inventaire pour chasser les E'kos."}}
D[4807] = {"L'E'ko des Indomptables",{"Au Berceau-de-l'Hiver, vous combattrez des créatures qui semblent posséder des pouvoirs magiques innés. Ces Indomptables sont dotés de grands pouvoirs magiques. Si vous voulez voir votre intelligence augmenter, apportez-moi l'E'ko que vous trouverez sur l'un de ces chouettards.","","Souvenez-vous, il vous faut la cache de Mau'ari dans votre inventaire si vous voulez chasser l'E'ko."}}
D[4808] = {"Felnok Ressordacier",{"Donner la Lettre de Brikolette à Felnok Ressordacier."}}
D[4809] = {"Cornes de Noroît",{"Apporter 8 Cornes intactes de Noroît à Felnok Ressordacier."}}
D[4810] = {"Retourner voir Brikolette",{"Apporter le Paquet de Felnok à Brikolette Toutevapeur dans les Steppes ardentes."}}
D[4811] = {"Le cristal rouge",{"Voyager en direction de l'est en partant d'Auberdine et chercher un gros cristal rouge le long de la chaîne de montagne est de Sombrivage. Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine."}}
D[4812] = {"Comme l'eau tombe en cascade",{"Remplir le Tube d'eau vide au Puits de lune d'Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l'est de Sombrivage."}}
D[4813] = {"Les fragments à l'intérieur",{"Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine."}}
D[4821] = {"L'œuf étrange",{"Rapporter l'Œuf étrange à Hagar Sabot-de-foudre au Poste de Librevent."}}
D[4822] = {"Je veux une glaaaaace !",{"Allez chercher de la Glace à la fraise pour votre protégé. Le gamin semble préférer la marque de glace Aguilor & Dagharn."}}
D[4841] = {"Pacifier les centaures",{"Tuer 12 Eclaireurs galak, 10 Querelleurs galak, et 6 Chasse-vent galak, puis retourner auprès du garde-falaise Longue-corne au Poste de Librevent."}}
D[4842] = {"Sources étranges",{"Suivre les instructions de Donova Antreneige, puis faire un rapport."}}
D[4861] = {"Les Indomptables enragés",{"Localiser le camp démoli et les fournitures de Jaron Sculptepierre, au sud du Berceau-de-l'Hiver."}}
D[4862] = {"Mauvais",{"Aller au Pic Rochenoire et ramasser 15 Œufs d'araignée du pic pour Kibler.","","Ces œufs peuvent être trouvés à proximité des araignées."}}
D[4863] = {"Les Indomptables enragés",{"Trouver le chariot saccagé de Jaron Stoneshaper."}}
D[4864] = {"Les Indomptables enragés",{"Ramasser les Fournitures de Jaron dans la neige, puis trouver l'Indomptable qui a volé l'amulette dont Jaron a parlé.","","Rapporter les fournitures de Jaron et l'Amulette de la plume bleue à Jaron Sculptepierre dans son pavillon au Berceau-de-l'Hiver."}}
D[4865] = {"Serpent sauvage",{"Faire un rapport de vos trouvailles à Motega Crin-de-feu."}}
D[4866] = {"Le lait matriarcal",{"Vous trouverez la Matriarche Couveuse au cœur du pic Rochenoire. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois <empoisonné/empoisonnée>, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon."}}
D[4867] = {"Urok Hurleruine",{"Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh."}}
D[4881] = {"Complot d'assassinat",{"Prévenir Kanati Nuage-gris au Poste de Blanc-relais qu'un complot le menace."}}
D[4882] = {"Secrets gardés",{"Apporter le Collier de plumes bleues à Trull Faillemort au Poste de la Vénéneuse."}}
D[4883] = {"Secrets gardés",{"Apporter le Collier de plumes bleues à Nara Crin-sauvage."}}
D[4901] = {"Les gardiens de l'autel",{"Protéger Ranshalla pendant qu'elle s'efforce de réactiver l'Autel d'Elune. Faire un rapport de vos découvertes à Erelas Ambreciel, au village de Rut'theran."}}
D[4902] = {"Les Indomptables d'Elune",{"Parler à l'archidruide Fandral Forteramure, à Darnassus."}}
D[4903] = {"Ordre du chef de guerre",{"Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Rochenoire. Retourner voir le chef de guerre Sangredent à Kargath une fois la mission accomplie."}}
D[4904] = {"Libre, enfin !",{"Escorter Lakota Chant-du-vent hors de la Cime de Noir-nuage, puis parler à Thalia Peau-d'ambre au Poste de Librevent."}}
D[4906] = {"Plus de corruption",{"Eridan Ventebleu de Gangrebois veut que vous tuiez 8 Implorateurs de l'enfer Jadefeu, 8 Traîtres Jadefeu, 8 Entourloupeurs Jadefeu et Xavaric. Revenez auprès d'Eridan une fois la tâche accomplie."}}
D[4907] = {"Tinkee Steamboil",{"Parler à Brikolette Toutevapeur."}}
D[4921] = {"Disparition au combat",{"Trouver la femme de Mankrik puis retourner le voir à la Croisée."}}
D[4941] = {"Sagesse d'Eitrigg",{"Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.","","Vous avez déjà vu Eitrigg dans les Appartements de Thrall."}}
D[4961] = {"La purification de l'Orbe d'Orahil",{"Tuer le Démon de l'Orbe, puis parler à Tabetha."}}
D[4962] = {"Un éclat de gangrechien",{"Prendre le Rubis de Felhas et l'utiliser sur l'un des gangrechiens de Désolace. Quand vous aurez réussi, rapporter le Rubis de Felhas et l'Esprit de gangrechien emprisonné à Menara Taillevide, dans les Tarides."}}
D[4963] = {"Eclat d'Infernal",{"Prendre l'Emeraude d'Infus et l'utiliser sur l'un des Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l'Emeraude d'Infus et l'Esprit d'Infernal emprisonné à Menara Taillevide, dans les Tarides."}}
D[4964] = {"L'Orbe complet de Dar'Orahil",{"Attendre que Menara Taillevide termine l'Orbe de Dar'Orahil, puis lui reparler."}}
D[4965] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Taillevide dans les Tarides."}}
D[4966] = {"Protéger Kanati Greycloud",{"Protéger Kanati Nuage-gris contre l'attaque centaure."}}
D[4967] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Taillevide dans les Tarides."}}
D[4968] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Taillevide dans les Tarides."}}
D[4969] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Taillevide dans les Tarides."}}
D[4970] = {"Provisions de sabres-de-givre",{"Collecter 5 morceaux de Viande de Croc acéré et 5 morceaux de Viande de Noroît pour Rivern Givrevent du Berceau-de-l'Hiver."}}
D[4971] = {"Une question de temps",{"Utiliser le Déplaceur temporel à côté de l'un des silos d'Andorhal pour révéler des Parasites temporels.","","Tuer 10 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l'auberge d'Andorhal, dans les Maleterres de l'ouest."}}
D[4972] = {"Arrêt du temps",{"Trouver 5 Montres d'Andorhal, dans des coffrets qui se trouvent parmi les décombres de la ville, et les rapporter à Chromie à l'Auberge d'Andorhal, dans les Maleterres de l'ouest."}}
D[4973] = {"Arrêt du temps",{"Trouver 5 Montres d'Andorhal parmi les décombres de la ville et les rapporter à Chromie à l'Auberge d'Andorhal, dans les Maleterres de l'ouest."}}
D[4974] = {"Pour la Horde !",{"Aller au Pic Rochenoire et tuer le Chef de guerre, Rend Main-noire. Prendre sa tête et retourner à Orgrimmar."}}
D[4975] = {"L'Orbe complet de Noh'Orahil",{"Attendre que Menara Taillevide ait terminé l'Orbe de Noh'Orahil, puis lui reparler."}}
D[4976] = {"Rapporter l'Orbe purifié",{"Rapporter l'Orbe infernal purifié à Menara Taillevide, dans les Tarides."}}
D[4981] = {"Agent Bijou",{"Aller au Pic Rochenoire et découvrir ce qui est arrivé à Bijou."}}
D[4982] = {"Les affaires de Bijou",{"Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville."}}
D[4983] = {"Rapport de reconnaissance de Bijou",{"Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath."}}
D[4984] = {"La faune et la flore souffrent aussi",{"Détruire 8 Loups malades, puis retourner voir Mulgris Rivière-profonde, au Repaire putride dans les Maleterres de l'ouest."}}
D[4985] = {"La faune et la flore en souffrent aussi",{"Détruire 8 Grizzlys malades, puis retourner voir Mulgris Rivière-profonde au Repaire putride, dans les Maleterres de l'ouest."}}
D[4986] = {"La branche de chêne à glyphes",{"D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l'assistance de l'un des druides, là-bas."}}
D[4987] = {"La branche de chêne à glyphes",{"D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, aux Pitons du Tonnerre. Aller solliciter l'assistance de l'un des druides, là-bas."}}
D[5001] = {"Les affaires de Bijou",{"Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !"}}
D[5002] = {"Message à Maxwell",{"Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell."}}
D[5021] = {"Mieux vaut tard que jamais",{"Le discours incohérent de la femme fantomatique indique qu'elle a besoin qu'on livre un colis pour elle. Elle a dit que le colis se trouvait là où se trouve son cheval. Le fantôme est incompréhensible lorsqu'il s'agit de préciser où se trouve son cheval ou l'endroit où le paquet doit être livré."}}
D[5022] = {"Mieux vaut tard que jamais",{"Rendre visite aux Facteurs royaux de Hurlevent pour apprendre l'adresse d'une certaine Emma Gangrepierre. En général, il y a un officier du recensement à l'Hôtel de ville."}}
D[5023] = {"Mieux vaut tard que jamais",{"Se renseigner auprès des Surveillants royaux de Fossoyeuse pour apprendre l'adresse d'un certain Jeremiah Gangrepierre. En général, il y a un officier du recensement près du bureau d'inscription des guildes et tabards."}}
D[5041] = {"Ravitaillement pour la Croisée",{"Trouver et rapporter les Caisses de ravitaillement de la Croisée à Thork dans les Tarides."}}
D[5042] = {"La force d'Agamaggan",{"J'aurai besoin de quatre Joyaux de sang si vous voulez la force d'Agammagan, <nom>.","","Vos ennemis s'enfuiront devant votre pouvoir si vous avez cette bénédiction.","","Les plus grands guerriers Tranchecrin sont d'une telle puissance !"}}
D[5043] = {"L'agilité d'Agammagan",{"Les meilleurs éclaireurs de ma tribu ont la réputation d'être d'une précision sans rivale, et nul ne peut égaler leur rapidité au combat.","","Apportez-moi 4 Joyaux de sang et je vous rendrai plus agile que n'importe quel huran."}}
D[5044] = {"La sagesse d'Agammagan",{"Les chamans et les géomanciens des tribus huranes <grogne> invoquent la force d'Agammagan pour les aider au combat et dans leurs rituels, <nom>.","","Si vous voulez la bénédiction d'un surcroît de pouvoir d'Agammagan dans vos sorts, apportez-moi 4 Joyaux de sang et Mangletooth vous aidera."}}
D[5045] = {"L'essor de l'esprit",{"Tous les guerriers, quels qu'ils soient, <grogne> ont besoin d'un esprit fort. Il vous conduit à l'exploit quand tout espoir est perdu. Ceci n'est pas ignoré <grogne> des Tranchecrins. Nous sommes une tribu spirituelle - nous sommes plus fiers de notre lien à Agammagan que de nos prouesses <grogne> au combat.","","Apportez-moi quatre Joyaux de sang et je bénirai votre esprit de lutte.<grogne>"}}
D[5046] = {"Peau tranchante",{"Tous ceux qui <grogne> se battent ont besoin de protection. Leurs os doivent être solides. Leur peau résistante.<grogne> Ma tribu le sait bien, et pour renforcer les protections naturelles de nos plumes et de nos dards <grogne> nous faisons appel à la protection d'Agammagan avant de partir pour la guerre.","","Apportez-moi 4 Joyaux de sang <grogne> et je vous obtiendrai cette même protection."}}
D[5047] = {"Finkle Einhorn, à votre service !",{"Parler à Malyfous Sombremartel à Long-guet."}}
D[5048] = {"Emma la bonne pâte",{"Trouver la vieille Emma à Stormwind, et découvrir si elle est en fait Emma Felstone. Si c’est le cas, elle appréciera peut-être le colis que Janice Felstone lui a préparé."}}
D[5049] = {"Le blues de Jeremiah",{"Trouver Jeremiah Payson à Fossoyeuse et découvrir s'il est en fait Jeremiah Gangrepierre. Si c'est le cas, il appréciera peut-être le colis que Janice Gangrepierre lui a préparé."}}
D[5050] = {"Charme porte-bonheur",{"Rapporter son Demi-charme porte-bonheur à Janice Felstone dans les Maleterres de l’ouest."}}
D[5051] = {"Deux moitiés deviennent Une",{"Trouver l'autre moitié du Charme porte-bonheur quelque part dans le périmètre de la Ferme Gangrepierre dans les Maleterres de l'ouest et le recoller.","","Donner le Charme porte-bonheur à Janice Gangrepierre à la Ferme Gangrepierre, dans les Maleterres de l'ouest."}}
D[5052] = {"Joyaux de sang d'Agammagan",{"Apporter un Joyau de sang à Mutiledent, au Camp Taurajo, dans les Tarides.","","Collectez plus de Joyaux de sang si vous souhaitez qu'il vous gratifie de la puissance d'Agamaggan."}}
D[5054] = {"Ursius des Crocs acérés",{"Storm Sabot-d'ombre, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Ursius."}}
D[5055] = {"Brumeran des Noroît",{"Storm Sabot-d'ombre, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Brumeran."}}
D[5056] = {"Shy-Rotam",{"Storm Sabot-d'ombre, à Long-guet au Berceau-de-l'Hiver, veut que vous triomphiez de Shy-Rotam."}}
D[5057] = {"Essais passés",{"Apporter le Marqueur de Storm Sabot-d'ombre à Melor Sabot-de-pierre aux Pitons du Tonnerre."}}
D[5058] = {"Journal de Mme Dalson",{"Un journal aux pages jaunies est ouvert à sa dernière page :","","\"Je ne sais pas ce qui va se passer maintenant que Harold a changé. J'ai dû faire de gros efforts pour le mettre dans le seul endroit où je savais qu'il serait enfermé pour de bon. J'ai la clé sur moi, et je prie que ça marche...","","J'espère pouvoir sortir d'ici, mais j'ai besoin d'argent pour ça... Nos affaires sont dans le cabinet, je pense... Et maintenant que j'y pense, Harold en a la clé sur lui ?","","Je vais me reposer, je suis morte de fatigue...\""}}
D[5059] = {"Enfermé",{"La porte des toilettes a commencé à se briser dans son pourtour comme si on avait essayé encore et encore de la forcer. Actuellement, elle est solidement verrouillée de l'extérieur.","","Quand vous secouez la porte, vous entendez un gémissement guttural ! La créature qui est à l'intérieur, quelle qu'elle soit, n'a pas l'air amicale."}}
D[5060] = {"Enfermé",{"Un meuble très solide est en face de vous, hermétiquement clos par une serrure intégrée. Le devant du meuble est très rayé et abîmé. Cela pourrait venir de nombreuses et violentes tentatives pour percer les secrets que le meuble dissimule.","","Si vous voulez ouvrir ce meuble, il vous faudra trouver la clé."}}
D[5061] = {"Forme aquatique",{"Retourner à Darnassus et montrer le Pendentif du lion de mer à Mathrengyl Pasdelours."}}
D[5062] = {"Feu sacré",{"Ramasser 10 boisseaux d'agave d'Incendia, puis consulter Magatha Totem-sinistre sur la Cime des Anciens dans les Pitons du Tonnerre."}}
D[5063] = {"La coiffe du savant écarlate",{"Pour créer la Coiffe du savant écarlate, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 8 Cristaux des arcanes ; 5 Fils écarlates enchantés.","","Il faudra aussi payer 50 pièces d'or pour le travail de fabrication."}}
D[5064] = {"Espionner le Totem-sinistre",{"Trouver et récupérer les trois Notes Secrètes à la Cime de Noir-nuage."}}
D[5065] = {"Les tablettes perdues de Mosh'aru",{"Apporter la Troisième et la Quatrième tablette Mosh'aru au Prospecteur Botte-de-fer à Tanaris."}}
D[5066] = {"Un appel aux armes : les Maleterres",{"Trouver le commandant Ashlam Vaillepoing. Son camp de base est situé au camp du Noroît, au nord des montagnes d'Alterac."}}
D[5067] = {"Jambières d'Arcana",{"Pour fabriquer les Jambières d'Arcana, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Liquides d'embaumement de Murmegivre.","","Il faudra également payer 50 pièces d'or pour le travail de fabrication."}}
D[5068] = {"La cuirasse carnassière",{"Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 10 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Peaux des ombres.","","Il faudra également payer 50 pièces d'or pour le travail de fabrication."}}
D[5081] = {"Mission de Maxwell",{"Se rendre au Pic Blackrock et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak. Retourner auprès du maréchal Maxwell quand la tâche a été accomplie."}}
D[5082] = {"La menace des Tombe-hiver",{"Donova Antreneige du Berceau-de-l'Hiver veut que vous tuiez 8 Guides, 8 Protecteurs et 8 Totémiques de la tribu Tombe-hiver."}}
D[5083] = {"L'eau de feu des Tombe-hiver",{"Apporter le Flacon d'eau de feu vide à Donova Antreneige du Berceau-de-l'Hiver."}}
D[5084] = {"Corrompu",{"Chercher un indice dans le camp des furbolgs Mort-bois, dans le nord de Gangrebois."}}
D[5085] = {"Gelée mystère",{"Aller faire un rapport de vos trouvailles à Donova Antreneige."}}
D[5086] = {"Horreurs toxiques",{"Récolter 3 Gouttelettes d'Horreur toxique pour Donova Antreneige au Berceau-de-l'Hiver."}}
D[5087] = {"Les messagers des Tombe-hiver",{"Trouver les Messagers Tombe-hiver et les empêcher de livrer leur cargaison au village Tombe-hiver."}}
D[5088] = {"Arikara",{"Tuer Arikara. Rapporter sa dépouille et de la poudre d'incendia à Motega Crin-de-feu au Poste de Blanc-relais comme preuve de votre acte."}}
D[5089] = {"Ordres du général Drakkisath",{"Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes."}}
D[5090] = {"Un appel aux armes : les Maleterres",{"Trouver le commandant Ashlam Vaillepoing. Son camp de base est le Camp du Noroît, au nord des montagnes d'Alterac."}}
D[5091] = {"Un appel aux armes : les Maleterres",{"Trouver le commandant Ashlam Vaillepoing. Il s'est établi au Camp du Noroît, au nord des montagnes d'Alterac."}}
D[5092] = {"Nettoyer le passage",{"Tuer 10 Ecorcheurs Squelettes et 10 Goules écumantes sur la Colline des chagrins.","","Retourner auprès du commandant Ashlam Vaillepoing au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5093] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l'est des Clairières de Tirisfal et de Fossoyeuse."}}
D[5094] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l'est des Clairières de Tirisfal et de Fossoyeuse."}}
D[5095] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l'est des Clairières de Tirisfal et de Fossoyeuse."}}
D[5096] = {"Diversions écarlates",{"Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Gangrepierre et les Larmes de Dalson et détruire leur tente d'état-major.","","Placer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l'ouest."}}
D[5097] = {"Tout au long des tours de guet",{"À l'aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l'embrasure de la porte de la tour pour pouvoir la marquer.","","Quand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Vaillepoing au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5098] = {"Tout au long des tours de guet",{"À l'aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l'embrasure de la porte de la tour pour pouvoir la marquer.","","Quand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l'ouest."}}
D[5101] = {"Lee's Ultimate Test Quest... of Doom!",{"Tuer 6 moutons pour Benny puis prendre les jambes à son cou !","","Non, c'est une blague... pour ce qui est de courir."}}
D[5102] = {"La reddition du général Drakkisath",{"Rendez-vous au Pic Rochenoire et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell."}}
D[5103] = {"Mort brûlante",{"Quelqu'un dans ce monde doit bien savoir à quoi servent ces gantelets. Bonne chance !"}}
D[5121] = {"Le grand chef Tombe-hiver",{"Donova Snowden du Berceau-de-l'Hiver veut que vous triomphiez du Grand chef Tombe-hiver."}}
D[5122] = {"Le médaillon de foi",{"Le pouvoir de cette chapelle me donne la force de résister à la corruption qui envahit mon coeur. Si je la quitte, je deviendrai un Chevalier de la mort. Mais il existe un médaillon de la foi qui me donnera la force dont j'ai besoin pour partir.","","S'il vous plaît, <nom>, trouvez le médaillon. Il est gardé par Malor le Zélé, un membre fou de la Croisade écarlate qui réside aux tréfonds du Bastion écarlate à l'ouest de Stratholme."}}
D[5123] = {"Le dernier morceau",{"Apporter le Journal mal écrit à Donova Snowden au Berceau-de-l'Hiver."}}
D[5124] = {"Gantelets en plaques de feu",{"Apporter à Malyfous Sombremartel 6 Barres de thorium enchanté, 2 Essences de feu, et 4 Rubis étoilés. Lui remettre également vos Gantelets en plaques inachevés."}}
D[5125] = {"L'estimation d'Aurius",{"<nom>, je me meurs… mais mon âme est sauve, et pour cela je vous dois plus que les mots peuvent exprimer. Je vous en prie, prenez ceci… et continuez le combat, brave <classe> !"}}
D[5126] = {"L'histoire de Lorax",{"Parler à Lorax. Écouter ce qu'il a à dire."}}
D[5127] = {"La forge démoniaque",{"Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.","","Trouver aussi la Cuirasse couverte de runes inachevée.","","Rapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver."}}
D[5128] = {"Paroles du Grand Chef",{"Rapporter le Journal mal écrit à Kelek Gardeciel dans le sud de Gangrebois."}}
D[5141] = {"Travail du cuir d'écailles de dragon",{"Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Peter Galen, en Azshara.","","Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.","","Terminer cette quête avec succès vous interdira l'apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision."}}
D[5142] = {"La petite Pamela",{"Retrouver Pamela Senterouge."}}
D[5143] = {"Travail du cuir tribal",{"Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Caryssia Moonhunter en Feralas.","","L’accomplissement de cette quête donne accès aux arts du travail du cuir tribal.","","L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix."}}
D[5144] = {"Travail du cuir élémentaire",{"Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Sarah Tanner dans la Gorge des Vents brûlants.","","L'accomplissement de cette quête donne accès aux arts du Travail du cuir élémentaire.","","L'accomplissement de cette quête vous empêchera d'apprendre le Travail du cuir de dragon et le Travail du cuir tribal ; il faut être sûr du chemin que l'on veut suivre avant de faire ce choix."}}
D[5145] = {"Travail du cuir de dragon",{"Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Thorkaf Oeil-de-dragon, dans les Terres ingrates.","","Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.","","Terminer cette quête avec succès vous interdira l'apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision."}}
D[5146] = {"Travail du cuir élémentaire",{"Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Brumn Winterhoof dans les montagnes d’Arathi.","","L’accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire.","","L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix."}}
D[5147] = {"On recherche : Arnak Totem-sinistre",{"Tuer Arnak Totem-sinistre et apporter une preuve de votre acte au garde-falaise Longue-corne au Poste de Librevent."}}
D[5148] = {"Travail du cuir tribal",{"Apporter un Gilet en cuir fauve et un Casque en cuir fauve à Se'Jib dans la vallée de Strangleronce.","","L'accomplissement de cette quête donne accès aux arts du travail du cuir tribal.","","L'accomplissement de cette quête vous empêchera d'apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l'on veut suivre avant de faire ce choix."}}
D[5149] = {"Poupée de Pamela",{"Trouver la poupée de Pamela."}}
D[5150] = {"Dadanga a faim !",{"Dadanga vous regarde alors que vous l'approchez. Elle semble espérer quelque chose…nnElle a probablement faim !","","Il y a certainement quelque chose qui pousse dans le cratère et qui ferait un parfait en-cas pour un herbivore de grande taille. Dadanga est une grande fille : quoi que vous lui apportiez, il faudra que ce soit en grosse quantité !"}}
D[5151] = {"Hypercapaciteur bidulotron",{"Tuer la bête et rapporter l'Hypercapaciteur et la Clé de la cage de la panthère à Wizlo Braquecoquard."}}
D[5152] = {"Tante Marlene",{"Parler à Marlene, au sud des ruines d'Andorhal."}}
D[5153] = {"Un étrange historien",{"Apporter l'Alliance de Joseph à Chromie."}}
D[5154] = {"Les annales de Darrowshire",{"Apporter les Annales de Comté-de-Darrow à Chromie, à Andorhal."}}
D[5155] = {"Les forces de Jaedenar",{"Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Sabot-de-mousse dans Gangrebois."}}
D[5156] = {"Enquête sur la corruption",{"Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d'eau corrompue, retourner auprès de Taronn Plume-rouge dans Gangrebois."}}
D[5157] = {"Recueillir de l'eau souillée",{"Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Sabot-de-mousse dans Gangrebois."}}
D[5158] = {"À la recherche de soutien spirituel",{"Apporter l'Eau de Puits de lune corrompue à Islen Oeil-des-rivières dans les Tarides."}}
D[5159] = {"L'eau purifiée retourne à Gangrebois",{"Apporter l'Eau de Puits de lune purifiée à Greta Sabot-de-mousse dans Gangrebois."}}
D[5160] = {"Le Protectorat de la matrone",{"Aller jusqu'au Berceau-de-l'Hiver et trouver Haleh. Lui donner l'Ecaille d'Awbee."}}
D[5161] = {"La colère du vol bleu",{"Si vous souhaitez continuer, parlez à Haleh."}}
D[5162] = {"La colère du vol bleu",{"Parler à Jeziba dans les Maleterres. Il vit à Andorhal."}}
D[5163] = {"Yéti ? Y es-tu ?",{"Prendre le yéti mécanique d'Umi et effrayer ses amis avec :","","Legacki, à Long-guet (Berceau-de-l'Hiver)nSaupoudr, à Gadgetzan (Tanaris)nQuixxil, au refuge des Marshal (Cratère d'Un'Goro)","","Quand vous aurez terminé, rapporter le yéti mécanique à Umi."}}
D[5164] = {"Guide de l'Indocile",{"Lire le Guide de l'Indocile."}}
D[5165] = {"Éteindre les flammes de protection",{"À l'aide de l'Eau de Puits de lune purifiée, éteignez les flammes des quatre braseros de protection à l'intérieur du Fort des ombres dans Gangrebois. Retournez ensuite auprès de Greta Sabot-de-mousse au Sanctuaire d'émeraude."}}
D[5166] = {"La cuirasse du vol chromatique",{"Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le \"Sculpteur\" :","","1 Carapace chromatique.","","10 Ecailles chromatiques brillantes.","","10 doses de Sang des héros.","","10 Coutures d'Abomination effilochées."}}
D[5167] = {"Les cuissards de duelliste chromatique",{"Pour forger les Cuissards de duelliste chromatique, il faut apporter les éléments suivants à Jeziba le \"Sculpteur\" :","","1 Carapace chromatique.","","10 Ecailles chromatiques brillantes.","","10 doses de Sang des héros.","","5 Peaux des ombres."}}
D[5168] = {"Les héros de Comté-de-Darrow",{"Apporter le Libram de Davil et le Bouclier de Senterouge à Carlin Senterouge."}}
D[5181] = {"Vilains de Darrowshire",{"Rapporter le Crâne d'Horgus et l'Epée brisée de Marduk à Carlin Senterouge à la chapelle de l'Espoir de Lumière."}}
D[5201] = {"L'incursion des Tombe-hiver",{"Rivern Givrevent veut que vous tuiez 5 Chamans Tombe-hiver et 5 Ursas Tombe-hiver."}}
D[5202] = {"Une étrange clé rouge",{"Chercher dans Jaedenar à quoi sert la Clé rouge sang."}}
D[5203] = {"Sauvetage à Jaedenar",{"Escorter Arko'narin à l'endroit où Sancteforge et son équipement sont détenus, puis la protéger lors de l'évasion du Fort des ombres. Ensuite, aller trouver Jessir Arquelune dans Gangrebois pour lui apprendre ce qui est arrivé à ses amis."}}
D[5204] = {"Le châtiment de la Lumière",{"Revenir à Jaedenar et tuer la succube Rakaiah avant de trouver le Cadavre de Trey Sancteforge."}}
D[5206] = {"Les maraudeurs de Comté-de-Darrow",{"Apporter 5 Crânes résonants et le Cristal mystique à Carlin Senterouge, dans les Maleterres de l'est."}}
D[5210] = {"Frère Carlin",{"Apporter les Annales complètes de Comté-de-Darrow à Carlin Senterouge dans les Maleterres de l'est."}}
D[5211] = {"Les défenseurs de Comté-de-Darrow",{"Libérer 15 Esprits de Comté-de-Darrow et retourner auprès de Carlin Senterouge."}}
D[5212] = {"La chair ne ment pas",{"Récupérer 10 Échantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair."}}
D[5213] = {"L'agent actif",{"Se rendre jusqu'à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink."}}
D[5214] = {"Le grand Fras Siabi",{"Trouver le magasin de tabac de Fras Siabi dans Stratholme et récupérer une boîte de Tabac de Siabi. Retourner auprès de Smokey LaRue quand le travail est fait."}}
D[5215] = {"Les chaudrons du Fléau",{"Parler à la grande prêtresse MacDonnell à la pointe du Noroît, dans les Maleterres de l'ouest."}}
D[5216] = {"Cible : le Champ de Gangrepierre",{"Se rendre au Champ de Gangrepierre dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve. Il aura peut-être une clé qui permet d'accéder au chaudron. Il faut se munir de la Bouteille du Champ de Gangrepierre vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron."}}
D[5217] = {"Retour au camp du Noroît",{"Apporter une Bouteille du Champ de Gangrepierre remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5218] = {"Le chaudron du champ de Gangrepierre",{"Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.","","Puisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste."}}
D[5219] = {"Cible : les Larmes de Dalson",{"Se rendre aux Larmes de Dalson dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des Larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron."}}
D[5220] = {"Retour au camp du Noroît",{"Apporter la Bouteille des Larmes de Dalson remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5221] = {"Le chaudron des Larmes de Dalson",{"Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.","","Puisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste."}}
D[5222] = {"Cible : le Repaire putride",{"Se rendre au Repaire putride dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille du Repaire putride vide pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron."}}
D[5223] = {"Retour au camp du Noroît",{"Apporter la Bouteille du Repaire putride remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5224] = {"Le chaudron du Repaire putride",{"Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.","","Puisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste."}}
D[5225] = {"Cible : la Flétrissure de Gahrron",{"Se rendre à la Flétrissure de Gahrron dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille de la Flétrissure de Gahrron vide pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron."}}
D[5226] = {"Retour au camp du Noroît",{"Apporter la Bouteille de la Flétrissure de Gahrron remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5227] = {"Le chaudron de la Flétrissure de Gahrron",{"Le chaudron de la peste du Fléau est devant vous, répandant d'énormes masses de toxine dans les airs. À la base de la vaste plate-forme du chaudron se trouve un petit panneau d'accès anodin.","","Puisque vous avez déjà vaincu le gardien du chaudron et pris sa clé, vous pouvez ajouter les composants appropriés dans le chaudron pour fabriquer un contre-agent à la peste."}}
D[5228] = {"Les chaudrons du Fléau",{"Parler à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."}}
D[5229] = {"Cible : le Champ de Felstone",{"Se rendre au Champ de Gangrepierre, dans les Maleterres de l'ouest, pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve. Il aura peut-être une clé qui permet d'accéder au chaudron. Il faut se munir de la Bouteille du Champ de Gangrepierre vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron."}}
D[5230] = {"Retour à la Barricade",{"Apporter la Bouteille du Champ de Gangrepierre remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."}}
D[5231] = {"Cible : les Larmes de Dalson",{"Se rendre aux Larmes de Dalson dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron."}}
D[5232] = {"Retour à la Barricade",{"Apporter la Bouteille des Larmes de Dalson remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5233] = {"Cible : le Repaire putride",{"Se rendre au Repaire putride dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron."}}
D[5234] = {"Retour à la Barricade",{"Ramener la Bouteille du Repaire putride remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5235] = {"Cible : la Flétrissure de Gahrron",{"Se rendre à la Flétrissure de Gahrron dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron."}}
D[5236] = {"Retour à la Barricade",{"Apporter la Bouteille de la Flétrissure de Gahrron remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5237] = {"Mission accomplie !",{"<nom>, votre travail couronné de succès sur les chaudrons est une immense victoire pour nous !","","nnQue tout le monde le sache : pour services rendus au Royaume de Stormwind et à l'Alliance et pour avoir fait bien plus que son devoir, face à un danger incroyable et contre tout espoir, je remets ceci à <nom> en même temps que je l'assure de notre gratitude. Félicitations !"}}
D[5238] = {"Mission accomplie !",{"<nom>, votre travail couronné de succès sur les chaudrons est une immense victoire pour nous !","","nnQue tout le monde le sache : pour services rendus aux Réprouvés et à la Horde et pour avoir fait bien plus que son devoir, face à un danger incroyable et contre tout espoir, je remets ceci à <nom> en même temps que je l'assure de notre gratitude. Félicitations !"}}
D[5241] = {"Oncle Carlin",{"Trouver Carlin Senterouge."}}
D[5242] = {"Un coup final",{"Tuer Moora et Salia, et rapporter la Tête du Seigneur des ténèbres Gangr'dan à Greta Sabot-de-mousse dans Gangrebois."}}
D[5243] = {"Les demeures du Sacré",{"Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni."}}
D[5244] = {"Les ruines de Kel'Theril",{"Parler à Jaron Sculptepierre au village de Pluie-d'Étoiles."}}
D[5245] = {"Les Esprits troublés de Kel'Theril",{"Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est."}}
D[5246] = {"Fragments du passé",{"Trouver les Écrits sacrés des Bien-nés dans le temple de Zin-Malor en Azshara et les apporter à Aurora Mandeciel à la tour du Col du nord, dans les Maleterres de l'est."}}
D[5247] = {"Fragments du passé",{"Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Mandeciel à la tour du Col du nord, dans les Maleterres de l'est."}}
D[5248] = {"Tourmentée par le passé",{"Amener le Cristal de Zin-Malor au lac Kel'Theril dans le Berceau-de-l'Hiver et trouver un esprit Bien-né qui veuille bien vous parler."}}
D[5249] = {"Au Berceau-de-l'Hiver",{"Trouver le village de Pluie-d'Étoiles au Berceau-de-l'Hiver, et parler à Wynd Pistenuit."}}
D[5250] = {"Pluie-d'Étoiles",{"Trouver le village de Pluie-d'Étoiles au Berceau-de-l'Hiver et parler à Wynd Pistenuit."}}
D[5251] = {"L'archiviste",{"Voyager jusqu'à Stratholme et trouver l'Archiviste Galford de la Croisade écarlate. L'abattre et brûler les Archives écarlates."}}
D[5252] = {"Une Bien-née pleine de remords",{"Parler à Wynd Pistenuit au village de Pluie-d'Étoiles et lui demander quel est le bon endroit pour le Cristal de Zin-Malor."}}
D[5253] = {"Le Cristal de Zin-Malor",{"Apporter le Cristal de Zin-Malor à l'archidruide Fandral Forteramure à Darnassus."}}
D[5261] = {"Eagan Tannepeau",{"Parler à Eagan Tannepeau."}}
D[5262] = {"La vérité vient du ciel",{"Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l'est."}}
D[5263] = {"Au-dessus et au-delà",{"S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff."}}
D[5264] = {"Seigneur Maxwell Tyrosus",{"Parler au seigneur Maxwell Tyrosus. Il est à l'intérieur de l'église."}}
D[5265] = {"Le Coffre d'argent",{"Ouvrez le Coffre d'argent et prenez votre récompense."}}
D[5281] = {"Âmes tourmentées",{"Trouver Egan. Vous savez seulement qu'on l'a vu pour la dernière fois aux alentours de Stratholme."}}
D[5282] = {"Âmes tourmentées",{"Se servir de la Pétoire d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau la Pétoire - ils seront enfin libres !","","Libérer 15 Esprits sans repos puis retourner auprès d'Egan."}}
D[5283] = {"L'art de l'armurier",{"Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants et les rapporter à Grumnus : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril."}}
D[5284] = {"La voie du Forgeron d'armes",{"Pour devenir un Fabricant d'armes, il faut fabriquer les éléments suivants et les rapporter à Ferronus : 4 Epées d'acier lunaire, 4 Haches massives en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires."}}
D[5301] = {"L'art de l'armurier",{"Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants puis les apporter à Okothos : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril."}}
D[5302] = {"La voie du Forgeron d'armes",{"Pour devenir un Fabricant d'armes, vous devez fabriquer les éléments suivants et les rapporter à Borgosh : 4 Epées d'acier lunaire, 4 Haches massives en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires."}}
D[5305] = {"Douce sérénité",{"Aller jusqu'à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le rapporter à Lilith."}}
D[5306] = {"Pierre du serpent de la chasseresse des ombres",{"Aller jusqu'au Pic Rochenoire et abattre la Chasseresse des ombres Vosh'gajin. Récupérer la Pierre du serpent de Vosh'gajin et la rapporter à Kilram."}}
D[5307] = {"Corruption",{"Trouver le Fabricant d'épées de la Garde noire à Stratholme et le tuer. Récupérer l'Insigne de la Garde noire et retourner auprès de Seril Plaie-du-Fléau."}}
D[5321] = {"Le dormeur s'est éveillé",{"Escorter Kerlonian Evershade jusqu’à Liladris Moonriver au Poste de Maestra à Ashenvale."}}
D[5341] = {"Fortune de la famille Barov",{"S'aventurer jusqu'à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d'Austrivage. Revenir auprès d'Alexi Barov quand la tâche est accomplie."}}
D[5342] = {"Le dernier Barov",{"Voyagez jusqu'au Camp du Noroît, dans le territoire de l'Alliance, et assassinez Weldon Barov. Prenez sa tête et revenez auprès d'Alexi Barov.","","Attention : Weldon sera probablement bien protégé par la racaille de l'Alliance."}}
D[5343] = {"Fortune de la famille Barov",{"S'aventurer jusqu'à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d'Austrivage. Revenir auprès de Weldon Barov quand la tâche est accomplie."}}
D[5344] = {"Le dernier Barov",{"Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.","","Attention : Alexi sera probablement bien protégé par les vandales de la Horde."}}
D[5361] = {"Arbre familial",{"Apporter le Rapport du garde-falaise Longue-corne à Nataka Longue-corne au poste de Rôdeur-fantôme en Désolace."}}
D[5381] = {"La Main d'Iruxos",{"Récupérer la Boîte démoniaque dans la forteresse de Hache-Tonnerre, puis la rapporter à Taiga Crin-sage, à Proie-de-l'Ombre."}}
D[5382] = {"Docteur Theolen Krastinov, le boucher",{"Trouver le docteur Theolen Krastinov à l'intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d'Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d'Eva Sarkhoff quand la tâche est accomplie."}}
D[5383] = {"Sac des horreurs de Krastinov",{"Apporter le Sac des horreurs à Eva Sarkhoff à Caer Darrow."}}
D[5384] = {"Kirtonos le héraut",{"Retournez à la Scholomance avec le Sang des innocents. Trouvez le porche et placez le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.","","Combattez vaillamment, sans perdre un pouce de terrain ! Détruisez Kirtonos et retournez auprès d'Eva Sarkhoff."}}
D[5385] = {"Le cadavre de Trey Sancteforge",{"Rapporter le Cadavre de Trey Sancteforge à Jessir Arquelune dans Gangrebois."}}
D[5386] = {"La prise du jour",{"Parler à Jinar'Zillen à Proie-de-l'Ombre, puis apporter 2 poissons Ventre-rouge à Nataka Longue-corne."}}
D[5401] = {"Brevet de l'Aube d'argent",{"Tous ceux qui combattent le mal au nom de l'Aube d'argent doivent recevoir un brevet et arborer notre insigne. Cela leur donne le droit de demander à nos intendants les récompenses dont ils ont la garde.","","Lorsque vous aurez votre brevet, vous pourrez récupérer des pierres du Fléau sur les membres du Fléau abattus ; ce sont des insignes qu'ils ont, parfois. Procurez-vous ces insignes et apportez-les-moi. Pour chaque insigne rapporté, vous recevrez notre marque d'héroïsme - la marque de valeur de l'Aube d'argent.","","Accomplissez votre destin, <classe> - rejoignez le combat dès aujourd'hui !"}}
D[5402] = {"Pierres du Fléau des serviteurs",{"Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.","","L'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureuse d'effectuer si vous avez amassé suffisamment de pierres du Fléau."}}
D[5403] = {"Pierres du Fléau des envahisseurs",{"Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.","","L'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense."}}
D[5404] = {"Pierres du Fléau des corrupteurs",{"Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !","","Au nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance."}}
D[5405] = {"Brevet de l'Aube d'argent",{"Tous ceux qui combattent le mal au nom de l'Aube d'argent doivent recevoir un brevet et arborer notre insigne. Cela leur donne le droit de demander à nos intendants les récompenses dont ils ont la garde.","","Lorsque vous aurez votre brevet, vous pourrez récupérer des pierres du Fléau sur les membres du Fléau abattus ; ce sont des insignes qu'ils ont, parfois. Procurez-vous ces insignes et apportez-les-moi. Pour chaque insigne rapporté, vous recevrez notre marque d'héroïsme - la marque de valeur de l'Aube d'argent.","","Accomplissez votre destin, <classe> - rejoignez le combat dès aujourd'hui !"}}
D[5406] = {"Pierres du Fléau des corrupteurs",{"Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !","","Au nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance."}}
D[5407] = {"Pierres du Fléau des envahisseurs",{"Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.","","L'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense."}}
D[5408] = {"Pierres du Fléau des serviteurs",{"Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur les plus faibles de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.","","L'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d'effectuer si vous avez amassé suffisamment de pierres du Fléau."}}
D[5421] = {"Poisson dans un seau",{"Je récompense ceux qui me facilitent la vie… J'aime en faire le moins possible, mon ami !","","Sous les quais de Proie-de-l'Ombre, j'ai placé de nombreux casiers à crustacés. Si vous avez la gentillesse de faire mon travail à ma place et de relever les casiers, je vous récompenserai en vous donnant quelque chose que vous voulez... Voyez où je veux en venir, l'ami ? Je vous donnerai un beau Ventre-Rouge pour 5 crustacés rapportés !"}}
D[5441] = {"Les péons paresseux",{"Utiliser la Matraque du contremaître sur les Péons paresseux, lorsqu'ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Matraque du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves."}}
D[5461] = {"L'humain, Ras Murmegivre",{"Voyager jusqu'aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l'objet au magistrat Marduke."}}
D[5462] = {"Le moribond, Ras Murmegivre",{"Voyager jusqu'à l'Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert."}}
D[5463] = {"Le cadeau de Menethil",{"Voyager jusqu'à Stratholme et trouver le Don de Menethil. Placer le Souvenir de la mémoire sur le sol impie."}}
D[5464] = {"Le Don de Menethil",{"Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l'est."}}
D[5465] = {"Souvenir lié",{"Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié."}}
D[5466] = {"La Liche, Ras Murmegivre",{"Trouver Ras Murmegivre dans Scholomance. Après l'avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l'abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke."}}
D[5481] = {"La tâche de Gordo",{"Récolter 3 Herbes des ténèbres et les apporter à l'Apprenti Apothicaire Holland au Cimetière de Brill."}}
D[5482] = {"Herbe maléfique",{"Récolter 10 Herbes maléfiques et les apporter à l'apprenti apothicaire Holland."}}
D[5501] = {"Collectionneur d'os",{"Apporter à Bibbly F'ibulleur à la Hutte de Kormek 10 Os de kodo provenant du Cimetière des kodos."}}
D[5502] = {"Un surveillant de la Horde",{"Ramenez votre protégé à l'orphelinat d'Orgrimmar, en rendant le sifflet d'orphelin orc à la directrice de l'orphelinat, Plainteguerre, dans la Vallée de l'Honneur."}}
D[5503] = {"Brevet de l'Aube d'argent",{"Tous ceux qui combattent le mal au nom de l'Aube d'argent doivent recevoir un brevet et arborer notre insigne. Cela leur donne le droit de demander à nos intendants les récompenses dont ils ont la garde.","","Lorsque vous aurez votre brevet, vous pourrez récupérer des pierres du Fléau sur les membres du Fléau abattus ; ce sont des insignes qu'ils ont, parfois. Procurez-vous ces insignes et apportez-les-moi. Pour chaque insigne rapporté, vous recevrez notre marque d'héroïsme - la marque de valeur de l'Aube d'argent.","","Accomplissez votre destin, <classe> - rejoignez le combat dès aujourd'hui !"}}
D[5504] = {"Les mantelets de l'Aube",{"Apporter 10 Marques de valeur de l'Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l'ouest"}}
D[5505] = {"La clé de Scholomance",{"Et bien voilà, <nom> - la Clé squelette terminée. Je suis aussi certain que possible que cette clé vous permettra d'entrer dans les confins de Scholomance. Toutefois il n'y a qu'un moyen de vérifier son efficacité. Ne perdez pas de temps et essayez-la, c'est ce que je dis.","","Bonne chance, puissant héros. Puissiez-vous continuer à apporter la lumière dans les ténèbres !"}}
D[5507] = {"Les mantelets de l'aube",{"Apporter 10 Marques de valeur de l'Aube d'argent au quartier-maître Feuzopoudre au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5508] = {"Pierres du Fléau des corrupteurs",{"Une Pierre du Fléau des Corrupteurs est l'insigne des Seigneurs du Fléau. Tout être puissant occupant une position d'autorité au sein du Fléau en possède une. Détruire l'une de ces créatures malfaisantes ferait sans doute avancer la cause de l'Aube d'argent, et toutes les bonnes causes !","","Au nom de l'Aube d'argent, je vous remettrai une marque de valeur en échange de l'un de ces insignes. Soyez prudent dans votre quête, <nom> - on ne plaisante pas avec des êtres d'une telle puissance."}}
D[5509] = {"Pierres du Fléau des envahisseurs",{"Une pierre de Fléau des envahisseurs est l'insigne des troupes d'élite du Fléau. On les trouve parfois sur les soldats les plus aguerris stationnés dans les Maleterres. Abattre une telle créature est sans conteste un défi, mais un défi bien agréable pour ceux qui ont accepté notre brevet pour combattre le mal.","","L'Aube d'argent offre actuellement une marque de valeur en échange de dix de ces insignes. Apportez-les-moi, et je ferai en sorte que vous receviez votre juste récompense."}}
D[5510] = {"Pierres du Fléau des serviteurs",{"Une Pierre du Fléau des serviteurs est l'insigne du rang et de la classe du Fléau. Elles se trouvent parfois sur le plus faible de leurs troupes positionnées dans les Maleterres, bien que le terme \"faible\" mérite d'être replacé dans son contexte.Les membres du Fléau, où qu'ils soient, ne devraient jamais être sous-estimés.","","L'Aube d'argent offre à présent une marque de valeur pour 20 de ces insignes - un échange que je serai heureux d'effectuer si vous avez amassé suffisamment de pierres du Fléau."}}
D[5511] = {"La clé de Scholomance",{"Eh bien voilà, <nom> - la Clé squelette terminée. Je suis aussi certain que possible que cette clé vous permettra d'entrer dans les confins de Scholomance. Toutefois il n'y a qu'un moyen de vérifier son efficacité. Ne perdez pas de temps et essayez-la, c'est ce que je dis.","","Bonne chance, puissant héros. Puissent vos victoires continuer de vous apporter gloire et pouvoir alors que vous semez la désolation à Scholomance !"}}
D[5513] = {"Les mantelets de l'aube",{"Apporter 10 Marques de valeur de l'Aube d'argent à l'intendante Coinceculasse, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."}}
D[5514] = {"Moisissure rime avec…",{"Apporter les Fragments de squelette imprégnés et 15 pièces d'or à Froisse Bonnacier à Gadgetzan."}}
D[5515] = {"Sac des horreurs de Krastinov",{"Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff."}}
D[5517] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l'Aube d'argent à l'intendante Coinceculasse, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."}}
D[5518] = {"La tenue d'ogre gordok",{"Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Noué Dédodevie. Il est actuellement enchaîné dans l'aile gordok de Hache-tripes."}}
D[5519] = {"La tenue d'ogre gordok",{"Besoin d’une autre tenue, hein ? Bon, je ne vais nulle part, de toute façon. Amenez-moi les mêmes éléments que l’autre fois, et je vous en ferai une autre."}}
D[5521] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l'Aube d'argent au quartier-maître Feuzopoudre au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5522] = {"Leonid Barthalomew",{"Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l'est."}}
D[5524] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l'Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l'ouest."}}
D[5525] = {"Libérez Noué !",{"C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…nnMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?"}}
D[5526] = {"Fragment de la Gangrevigne",{"Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu'après la mort d'Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit."}}
D[5527] = {"Un reliquaire de pureté",{"Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune."}}
D[5528] = {"La dégustation gordok",{"V’z’êtes le grand patron maintenant, alors z’avez le droit de goûter mes alcools. Ils rendent fort ET font tourner la tête ! C’est d’la bonne, chef… essayez, vous pourrez l’dire à Kreeg !"}}
D[5529] = {"Portée contaminée",{"Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l'Espoir de Lumière."}}
D[5531] = {"Betina Bigglezink",{"Apporter les Œufs congelés à Betina Bigglezink."}}
D[5533] = {"Scholomance",{"Parler à l'alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l'ouest."}}
D[5534] = {"L'équipement \"manquant\" de Kim'jael",{"Trouver \"une rune\" détenue par les nagas dans les ruines d'Eldarath et la rapporter à Kim'jael, en Azshara."}}
D[5535] = {"Agitation spirituelle",{"Détruire 6 Apparitions de Bien-nés et 6 Jeunes liches bien-nées avant de retourner auprès de Loh'atu en Azshara."}}
D[5536] = {"Un pays plein de haine",{"Tuer 6 Satyres Haldarr, 2 Entourloupeurs Haldarr, et 2 Gangreliges Haldarr puis revenir voir Loh'atu à la frontière d'Orneval."}}
D[5537] = {"Fragments de squelette",{"Apporter 15 Fragments de squelette à l'alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l'ouest."}}
D[5538] = {"Moisissure rime avec…",{"Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan."}}
D[5541] = {"Munitions pour Grondetrait",{"Apporter les Munitions de Grondetrait à Hegnar Grondetrait à Dun Morogh."}}
D[5542] = {"Chiens-démons",{"Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring quand la mission sera terminée."}}
D[5543] = {"Ciel couleur de sang",{"Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring."}}
D[5544] = {"Larve putride",{"Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées."}}
D[5545] = {"Un sac d'embrouilles",{"Apporter 8 fagots de bois à Raelen au Camp de bûcherons du Val d'est."}}
D[5561] = {"Le rassemblement des kodos",{"Ramener cinq Kodos domptés et le Kombobulateur kodo à Smeed Fouillevis au camp de Fouillevis."}}
D[5581] = {"Les portails de la Légion",{"Bannir 6 Portails, dans le convent de Mannoroc, puis retourner voir Taiga Crin-sage, à Proie-de-l'Ombre."}}
D[5582] = {"L'écaille de dragon luisante",{"Apporter l'Ecaille de dragon luisante à Betina Bigglezink à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[5601] = {"Pamela, ma sœur",{"Trouver Pamela Senterouge à Comté-de-Darrow."}}
D[5621] = {"Vêtements de la lune",{"Trouver la Sentinelle Shaya et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Laurna Clairematin, à Dolanaar."}}
D[5622] = {"Au service d'Elune",{"Parler à Laurna Clairematin à Teldrassil."}}
D[5623] = {"Au service de la Lumière",{"Parler à la prêtresse Josetta dans la Forêt d'Elwynn."}}
D[5624] = {"Vêtements de la Lumière",{"Trouver le garde Roberts et soigner ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir la prêtresse Josetta, à Comté-de-l'or."}}
D[5625] = {"Vêtements de la Lumière",{"Trouver le Montagnard Dolf et guérir ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Maxan Anvol, à Kharanos."}}
D[5626] = {"Au service de la Lumière",{"Parler à Maxan Anvol à Dun Morogh."}}
D[5627] = {"Etoiles d'Elune"}
D[5628] = {"Retour à la maison",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5629] = {"Retour à la maison",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5630] = {"Retour à la maison",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5631] = {"Retour à la maison",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5632] = {"Retour à la maison",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5633] = {"Retour à la maison",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5634] = {"Prière du désespoir",{"Vous avez rendu un grand service à la Lumière en devenant un exemple remarquable pour ceux qui voyagent dans et au-delà de ces contrées dangereuses. S'il vous plaît, veuillez accepter cette leçon en remerciement de tout ce que vous avez fait."}}
D[5635] = {"Prière du désespoir",{"Parler à la grande prêtresse Laurena à Hurlevent."}}
D[5636] = {"Prière du désespoir",{"Parler à la grande prêtresse Laurena à Hurlevent."}}
D[5637] = {"Prière du désespoir",{"Parler à la grande prêtresse Laurena à Hurlevent."}}
D[5638] = {"Prière du désespoir",{"Parler à la grande prêtresse Laurena à Hurlevent."}}
D[5639] = {"Prière du désespoir",{"Parler à la grande prêtresse Laurena à Hurlevent."}}
D[5641] = {"Un manque de peur",{"Vous avez tout ce qui fait un grand <classe>, <nom>. Continuez à faire du bon travail !","","Vous avez montré que vous pouviez partir au combat. Peut-être est-t-il temps de vous apprendre un petit quelque chose de plus."}}
D[5642] = {"Garde des ténèbres",{"Parler à Ur'kyo à Orgrimmar."}}
D[5643] = {"Garde de l'ombre",{"Parler à Ur'kyo à Orgrimmar."}}
D[5644] = {"Peste dévorante",{"Parler à Aelthalyste à Fossoyeuse."}}
D[5645] = {"Un manque de peur",{"Parler au grand prêtre Rohan à Forgefer."}}
D[5646] = {"Peste dévorante",{"Parler à Aelthalyste à Fossoyeuse."}}
D[5647] = {"Un manque de peur",{"Parler au grand prêtre Rohan à Forgefer."}}
D[5648] = {"Vêtements de la spiritualité",{"Trouver le grunt Kor'ja et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Tai'jin, sur Tranchecolline."}}
D[5649] = {"Au service de la spiritualité",{"Parler à Tai'jin en Durotar."}}
D[5650] = {"Vêtements des ténèbres",{"Trouver le Nécrogarde Kel et le guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir le sombre clerc Beryl, à Brill."}}
D[5651] = {"Au service des ténèbres",{"Parler au sombre clerc Beryl dans les Clairières de Tirisfal."}}
D[5652] = {"Le maléfice de faiblesse",{"Vous feriez bien de tenir compte de cette leçon. Le maléfice de faiblesse vous servira grandement lors de combats. Plus tard, j'aurai d'autres épreuves à vous faire passer qui vous serviront et permettront de prouver votre valeur à la tribu."}}
D[5654] = {"Le maléfice de faiblesse",{"Parler à Ur'kyo à Orgrimmar."}}
D[5655] = {"Le maléfice de faiblesse",{"Parler à Ur'kyo à Orgrimmar."}}
D[5656] = {"Le maléfice de faiblesse",{"Parler à Ur'kyo à Orgrimmar."}}
D[5657] = {"Le maléfice de faiblesse",{"Parler à Ur'kyo à Orgrimmar."}}
D[5658] = {"Toucher de faiblesse",{"Ah jeune <classe> ! Je suis ravie de vous revoir. Je vais vous enseigner quelque chose que vous n'êtes pas près d'oublier. D'accord ?"}}
D[5660] = {"Toucher de faiblesse",{"Parler à Aelthalyste à Fossoyeuse."}}
D[5661] = {"Toucher de faiblesse",{"Parler à Aelthalyste à Fossoyeuse."}}
D[5662] = {"Toucher de faiblesse",{"Parler à Aelthalyste à Fossoyeuse."}}
D[5663] = {"Toucher de faiblesse",{"Parler à Aelthalyste à Undercity."}}
D[5672] = {"Grâce d'Elune"}
D[5673] = {"Grâce d'Elune",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5674] = {"Grâce d'Elune",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5675] = {"Grâce d'Elune",{"Parler à la prêtresse Alathea à Darnassus."}}
D[5676] = {"Retour d'information de l'Arcane",{"Nous avons été obligés d'apprendre un peu de magie pour nous protéger de ce que nous appelons communément notre plus grand ennemi : l'Arcane.","","Je vous enseignerai un sort qui vous aidera à vous protéger, vous et vos compagnons, contre ceux qui détiennent ce genre de pouvoir."}}
D[5677] = {"Retour d'information de l'Arcane",{"Parler à la grande prêtresse Laurena à Hurlevent."}}
D[5679] = {"Peste dévorante",{"Si vous le désirez, je peux vous apprendre la Peste dévorante, <nom>. Un sort puissant, utile dans vos prochains combats. Entraînez-vous, vous serez mise à l'épreuve plus tard."}}
D[5680] = {"Garde des ténèbres",{"Vos rites arriveront bien assez tôt. Pour l'instant je vais vous enseigner un sort qui vous sera très utile pendant les combats."}}
D[5713] = {"Un tir. Un tué.",{"Protéger la Sentinelle Aynasha, puis parler à Onaeya au poste de Maestra, en Orneval."}}
D[5721] = {"La bataille de Comté-de-Darrow",{"Placer la paquet de reliques sur la place centrale de Comté-de-Darrow.","","Empêcher la mort de Davil Lumefeu, jusqu'à la mort de Horgus.","","Empêcher la mort du capitaine Senterouge, jusqu'à ce que Senterouge le Corrompu apparaisse.","","Vaincre Senterouge le Corrompu.","","Parler à l'esprit de Joseph Senterouge, quand il apparaîtra sur la place centrale, puis parler à Pamela, dans sa maison."}}
D[5722] = {"À la recherche de la sacoche perdue",{"Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Totem-sinistre et tout élément intéressant."}}
D[5723] = {"Tester la force de l'ennemi",{"Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro aux Pitons du Tonnerre."}}
D[5724] = {"Rapporter la sacoche perdue",{"Apporter la Sacoche du Totem-sinistre à Rahauro aux Pitons du Tonnerre."}}
D[5725] = {"Le pouvoir de détruire...",{"Apporter les livres de Sorts des Ombres et d'Incantations du Néant à Varimathras, à Fossoyeuse."}}
D[5726] = {"Ennemis cachés",{"Apporter un Insigne de lieutenant à Thrall à Orgrimmar."}}
D[5727] = {"Ennemis cachés",{"Apporter l'Insigne du Lieutenant à Neeru Lamefeu et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar."}}
D[5728] = {"Ennemis cachés",{"Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar."}}
D[5729] = {"Ennemis cachés",{"Parler à Neeru Lamefeu à Orgrimmar."}}
D[5730] = {"Ennemis cachés",{"Parler à Thrall à Orgrimmar et lui dire ce que vous avez appris."}}
D[5741] = {"Sceptre de lumière",{"Prendre le Sceptre de lumière et le rapporter à Azore Aldamort, dans la tour d'Ethel Rethor."}}
D[5742] = {"Rédemption",{"Écouter ce que Tirion Fordring a à dire."}}
D[5761] = {"Tuer la bête",{"Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Lamefeu à Orgrimmar."}}
D[5762] = {"Hemet Nesingwary",{"Apporter la Caisse de Kravel à Hemet Nesingwary Jr. à Strangleronce."}}
D[5763] = {"Chasse à Strangleronce",{"Apporter la Corne de kodo de Roon à Hemet Nesingwary Jr. à Strangleronce."}}
D[5781] = {"Aux mémoires perdues",{"Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l'est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission."}}
D[5801] = {"Forgée dans la Fournaise",{"Emporter le Moule de Clé squelette et 2 Barres de thorium au sommet de la crête de la Fournaise dans le cratère d’Un'Goro. Utiliser le Moule de Clé squelette au lac de lave pour forger la Clé squelette inachevée.","","Apporter la Clé squelette inachevée à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest."}}
D[5802] = {"Forgée dans la Fournaise",{"Prendre le moule de la Clé squelette et deux barres de thorium au sommet de la crête de la Fournaise dans le cratère d'Un'Goro. Se servir du moule de la Clé squelette pour forger la Clé squelette inachevée.","","Apporter la Clé squelette inachevée à l'Apothicaire Dithers à la Barricade, dans les Maleterres de l'ouest."}}
D[5803] = {"Le Scarabée d'Araj",{"Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest."}}
D[5804] = {"Le Scarabée d'Araj",{"Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l'apothicaire Dithers à la Barricade, dans les Maleterres de l'ouest."}}
D[5805] = {"Bienvenue !",{"Apporter le Bon-cadeau de Comté-de-l'or à Merissa Morpuits, à Comté-de-l'or."}}
D[5821] = {"Garde du corps à recruter",{"Escorter la Caravane de Gizelton et l'aider à passer le village des centaures Kolkar. Parler à Smeed, au camp de Fouillevis, pour toucher la récompense."}}
D[5841] = {"Bienvenue !",{"Apporter le Bon-cadeau de Kharanos à Yori Craqueheaume, à Kharanos."}}
D[5842] = {"Bienvenue !",{"Apporter le Bon-cadeau de Dolanaar à Orenthil Murmevent."}}
D[5843] = {"Bienvenue !",{"Apporter le Bon-cadeau de Tranchecolline à Magga."}}
D[5844] = {"Bienvenue !",{"Apporter le Bon-cadeau de Sabot-de-sang à Vorn Oeil-des-cieux au village de Sabot-de-sang."}}
D[5845] = {"De l'honneur perdu",{"Se rendre à Valnord, dans la région nord-est des Maleterres de l'est, et récupérer le Symbole de l'honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie."}}
D[5846] = {"L'amour et la famille",{"Voyager jusqu'à l'île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l'emplacement du tableau."}}
D[5847] = {"Bienvenue !",{"Apporter le Bon-cadeau de Brill à Claire Willower, au Glas."}}
D[5848] = {"De l'amour et de la famille",{"Se rendre à Stratholme, dans la partie nord des Maleterres. C'est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.","","Rapporter le tableau à Tirion Fordring."}}
D[5861] = {"Trouver Myranda",{"Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion."}}
D[5862] = {"Le subterfuge écarlate",{"Parlez à Myranda pour obtenir l'Illusion écarlate. Allez à Âtreval pendant que vous êtes sous l'effet de l'Illusion écarlate, et apportez le Don de Tirion au généralissime Taelan Fordring.","","Âtreval se trouve au nord, et Taelan devrait se trouver à l'intérieur du Donjon de Mardenholde."}}
D[5863] = {"La base des Cognedunes",{"Andi Lynn de Gadgetzan veut que vous détruisiez la Base des Cognedunes en tuant 10 Brutes Cognedunes, 10 Massacreurs Cognedunes, et Gor'marok le Ravageur."}}
D[5881] = {"Puiser dans les réserves",{"Maggran voudrait que vous apportiez une lettre à Grish Long-coureur, à la Grande élévation, dans les Tarides."}}
D[5882] = {"Du baume en chassant",{"Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.","","En échange de ces fragments, je vous donnerai du Baume que j'ai déjà préparé."}}
D[5883] = {"Du baume par la pioche",{"Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.","","Si vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé."}}
D[5884] = {"Du baume contre une récolte",{"Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.","","Lorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j'ai déjà préparé."}}
D[5885] = {"Du baume contre des peaux",{"Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !","","Lorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve."}}
D[5886] = {"Du baume contre des désenchantements",{"Le pouvoir d'un objet magique désenchanté est éprouvé par l'essence qu'il crée. J'ai conçu un moyen de transformer l'essence brute utilisée par les enchanteurs en un réactif qui permet de créer du Baume végétal cénarien. Vous n'avez pas besoin de Balise cénarienne dans ce cas. N'importe quel objet désenchanté qui produit des essences inférieures fera parfaitement l'affaire.","","Je n'ai besoin que d'une seule essence inférieure. En échange, je vous donnerai du Baume végétal cénarien. L'essence est très puissante. Il en faut peu pour faire beaucoup !"}}
D[5887] = {"Du baume en chassant",{"Si vous possédez une Balise cénarienne, vous pourrez discerner un fragment d'esprit corrompu sur les bêtes souillées que nous supprimons pour le plus grand bien de tous. Je broie ces fragments jusqu'à obtenir un réactif dont je me sers pour confectionner le Baume végétal cénarien qui permet de rendre santé et vigueur à ces plantes corrompues.","","En échange de ces fragments, je vous donnerai du Baume cénarien que j'ai déjà préparé."}}
D[5888] = {"Du baume par la pioche",{"Si vous avez une Balise cénarienne et que vous minez dans Gangrebois, peut-être trouverez-vous du Vitriol contaminé dans un filon de minerai brut. Je sais comment purifier ce vitriol et le transformer en un composant qui sert à faire du Baume végétal cénarien. Vous pourrez ensuite l'utiliser pour libérer les plantes corrompues que vous rencontrerez.","","Si vous avez collecté du Vitriol contaminé, je vous l'échange contre du Baume végétal cénarien que j'ai déjà préparé."}}
D[5889] = {"Du baume contre une récolte",{"Une Balise cénarienne permet aux herboristes expérimentés de repérer les créatures corrompues de Gangrebois. Mon travail ici m'a appris à les purifier avec un réactif... utilisé dans ce que nous appelons le Baume végétal cénarien.","","Lorsque vous cueillerez des herbes à Gangrebois, vous devriez remarquer les créatures corrompues si vous avez la Balise cénarienne. En échange je vous donnerai du Baume cénarien que j'ai déjà préparé."}}
D[5890] = {"Du baume contre des peaux",{"Une balise cénarienne permet à un dépeceur bien entraîné de repérer des morceaux de peau contaminée dans le butin ramassé à Gangrebois. Je transforme ces morceaux apparemment inutiles en pâte épaisse qui sert d'agent accélérateur au baume végétal cénarien. Quand vous dépecez vos prises ici à Gangrebois, assurez-vous d'avoir toujours une balise sur vous !","","Lorsque vous ramassez des morceaux de peau contaminée, apportez-les-moi et je vous donnerai des doses de baume végétal cénarien que j'ai en réserve."}}
