D[5892] = {"Fournitures de Gouffrefer",{"Apporter 10 Fournitures de Gouffrefer à l'Intendant de l'Alliance de Dun Baldar."}}
D[5893] = {"Fournitures de Froide-dent",{"Apporter 10 Fournitures de Froide-dent à l'intendant de la Horde, au donjon Loup-de-givre."}}
D[5901] = {"Une Plaie sur la Croisade",{"Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l'est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal."}}
D[5902] = {"Une Plaie sur la Croisade",{"Trouver un endroit judicieux au centre de la scierie de la Crête du nord, dans les Maleterres de l'ouest, pour placer le Tonneau de Termites des Maleterres."}}
D[5903] = {"Une Plaie sur la Croisade",{"Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l'est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5904] = {"Une Plaie sur la Croisade",{"Trouver un endroit propice, au centre de la scierie de la Crête du nord, dans les Maleterres de l'ouest, pour placer le Tonneau de Termites des Maleterres."}}
D[5921] = {"Reflet-de-Lune",{"Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Brasétoile, au village de Havrenuit."}}
D[5922] = {"Reflet-de-Lune",{"Utiliser le sort \"Téléportation : Reflet-de-Lune\" pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Brasétoile, au village de Havrenuit."}}
D[5923] = {"Écouter l'appel",{"Parler à Mathrengyl Pasdelours, dans l'Enclave cénarienne, à Darnassus."}}
D[5924] = {"Écouter l'appel",{"Parler à Mathrengyl Pasdelours, dans l'Enclave cénarienne, à Darnassus."}}
D[5925] = {"Écouter l'appel",{"Parler à Mathrengyl Pasdelours, dans l'Enclave cénarienne, à Darnassus."}}
D[5926] = {"Écouter l'appel",{"Parler à Turak Totem-runique, sur la Cime des Anciens des Pitons du Tonnerre."}}
D[5927] = {"Écouter l'appel",{"Parler à Turak Totem-runique, sur la Cime des Anciens des Pitons du Tonnerre."}}
D[5928] = {"Écouter l'appel",{"Parler à Turak Totem-runique, sur la Cime des Anciens des Pitons du Tonnerre."}}
D[5929] = {"L'esprit du Grand ours",{"Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Brasétoile, à Havrenuit, dans Reflet-de-Lune."}}
D[5930] = {"Esprit du Grand ours",{"Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Brasétoile, à Havrenuit, dans Reflet-de-Lune."}}
D[5931] = {"Retour à Darnassus",{"Retourner à Darnassus et parler à Mathrengyl Pasdelours, dans l'Enclave cénarienne."}}
D[5932] = {"Retour vers les Pitons du Tonnerre",{"Retourner aux Pitons du Tonnerre, et parler à Turak Totem-runique, sur la Cime des Anciens."}}
D[5941] = {"Retourner voir Chromie",{"Apporter la Liasse de reliques à Chromie, à Andorhal."}}
D[5942] = {"Trésors cachés",{"Utiliser la Clé de Joseph sur le Coffre de Joseph."}}
D[5943] = {"La caravane de Gizelton",{"Escorter la caravane de Gizelton à travers le convent de Mannoroc. Parler à Smeed, au camp de Fouillevis, pour toucher la récompense."}}
D[5944] = {"En rêves",{"Escortez Taelan Fordring jusqu'à la sortie d'Âtreval."}}
D[5961] = {"Le champion de la reine banshee",{"Parler à Nathanos le Flétrisseur, dans les Maleterres de l'est. Il se trouve actuellement à la ferme des Marris."}}
D[5981] = {"Géants déchaînés",{"Rivern Givrevent voudrait que vous tuiez 4 Géants Cognegivre et 4 Protecteurs Cognegivre."}}
D[6001] = {"Corps et cœur",{"Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d'Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu'il possède.","","Quand cela est fait, parler à Mathrengyl Pasdelours, à Darnassus."}}
D[6002] = {"Corps et cœur",{"Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu'il possède.","","Quand cela est fait, parler à Turak Totem-runique, aux Pitons du Tonnerre."}}
D[6004] = {"Un travail inachevé",{"Tuer deux Médecins écarlates, deux Chasseurs écarlates, deux Magi écarlates et deux Chevaliers écarlates avant de revenir vers Kirsta Fondombre dans les Maleterres de l'ouest."}}
D[6021] = {"Zaeldarr le Banni",{"Apporter la Tête de Zaeldarr au Conservateur Alen, à la chapelle de l'Espoir de Lumière."}}
D[6022] = {"Tuer utile",{"Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez 7 morceaux de Pourriture vivante en moins de 10 minutes. Utilisez le Mortier et le Pilon pour réduire la Pourriture vivante en Pourriture coagulée."}}
D[6023] = {"Un travail inachevé",{"Tuer le veneur Radley et le cavalier Durgen, avant de retourner voir Kirsta Fondombre, dans les Maleterres de l'ouest."}}
D[6024] = {"L'appel d'Hameya",{"Tuer l'Infiltrateur Hameya. Utiliser sa clé sur le Monticule de poussière, derrière le caveau de Zaeldarr."}}
D[6025] = {"Un travail inachevé",{"Aller à Âtreval, et trouver un poste d'observation élevé d'où voir la ville et jauger les forces de la Croisade écarlate, puis retourner voir Kirsta Fondombre, dans les Maleterres de l'ouest."}}
D[6026] = {"Voilà qui est beaucoup demander",{"Smokey LaRue veut que vous lui apportiez 2 Barres de thorium, 1 Bâtonnet doré, 8 Bombes explosives et 8 Déclencheurs instables.","","Vous devrez trouver un forgeron et un ingénieur pour obtenir ces objets."}}
D[6027] = {"Le Livre des Anciens",{"Obtenir le Livre des Anciens, puis le rapporter à Azore Aldamort, dans la tour d'Ethel Rethor."}}
D[6028] = {"Le rapport de Long-guet",{"Apportez le Rapport de Long-guet à l'officier de l'Aube d'argent Purecarde au Camp du Noroît, dans les Maleterres de l'ouest."}}
D[6029] = {"Le rapport de Long-guet",{"Livrer le Rapport de Long-guet à l'officier Garush de l'Aube d'argent, à la Barricade, dans les Maleterres de l'ouest."}}
D[6030] = {"Le duc Nicholas Zverenhoff",{"Apportez le livre \" Etudes sur la langue des Esprits \" au duc Nicholas Zverenhoff, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."}}
D[6031] = {"L'étoffe runique",{"Apportez 30 pièces d'étoffe runique à Meilosh au Repaire des Grumegueules."}}
D[6032] = {"Le vêtement sacré",{"Apporter 2 pièces d'Etoffe lunaire à Meilosh, au Repaire des Grumegueules."}}
D[6041] = {"Quand Smokey chante, je deviens violent",{"Aller à Pestebois, au nord-ouest de la chapelle de l'Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs.","","Une fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération.","","Garder en tête que le Mélange spécial de Smokey est très... instable."}}
D[6042] = {"Les petits soucis de la non-vie",{"Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait."}}
D[6061] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Crin-tranchant, à Sabot-de-sang."}}
D[6062] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline."}}
D[6063] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar."}}
D[6064] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Cœur-sauvage, à Kharanos."}}
D[6065] = {"La voie du chasseur",{"Parler à Yaw Crin-tranchant, à Sabot-de-sang."}}
D[6066] = {"La voie du chasseur",{"Parler à Yaw Sharpmane, au village Bloodhoof."}}
D[6067] = {"La voie du chasseur",{"Parler à Yaw Crin-tranchant, à Sabot-de-sang."}}
D[6068] = {"La voie du chasseur",{"Parler à Thotar, à Tranchecolline."}}
D[6069] = {"La voie du chasseur",{"Parler à Thotar, à Tranchecolline."}}
D[6070] = {"La voie du chasseur",{"Parler à Thotar, à Tranchecolline."}}
D[6071] = {"La voie du chasseur",{"Parler à Dazalar, à Dolanaar."}}
D[6072] = {"La voie du chasseur",{"Parler à Dazalar, à Dolanaar."}}
D[6073] = {"La voie du chasseur",{"Parler à Dazalar, à Dolanaar."}}
D[6074] = {"La voie du chasseur",{"Parler à Grif Cœur-sauvage, à Kharanos."}}
D[6075] = {"La voie du chasseur",{"Parler à Grif Cœur-sauvage, à Kharanos."}}
D[6076] = {"La voie du chasseur",{"Parler à Grif Cœur-sauvage, à Kharanos."}}
D[6081] = {"Entraîner la bête",{"Adressez-vous à Ormak Trait-sinistre à Orgrimmar."}}
D[6082] = {"Dompter la bête",{"Domptez un Scorpide blindé à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Thotar à Tranchecolline."}}
D[6083] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Clampant de l'écume. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar, à Tranchecolline."}}
D[6084] = {"Dompter la bête",{"Domptez un Léopard des neiges à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Cœur-sauvage à Kharanos."}}
D[6085] = {"Dompter la bête",{"Domptez un ours Griffeglace à l'aide du Bâtonnet de domptage. Entraînez-vous puis retournez voir Grif Cœur-sauvage à Kharanos."}}
D[6086] = {"Entraîner la bête",{"Adressez-vous à Belia Tonnegranit à Forgefer."}}
D[6087] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Crin-tranchant, à Sabot-de-sang."}}
D[6088] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Rapace. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Crin-tranchant, à Sabot-de-sang."}}
D[6089] = {"Entraîner la bête",{"Parler à Holt Corne-tonnerre, sur la Cime des Chasseurs, aux Pitons du Tonnerre."}}
D[6101] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar."}}
D[6102] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar."}}
D[6103] = {"Entraîner la bête",{"Parler à Jocaste, à l'Enclave cénarienne de Darnassus."}}
D[6121] = {"Nouvelles leçons",{"Aller à Reflet-de-Lune, et parler à Dendrite Brasétoile, au village de Havrenuit."}}
D[6122] = {"Le principe originel",{"Utiliser une Fiole d'échantillon des Chutes de la Bondissante vide pour collecter un échantillon d'eau, à l'entrée de la grotte, à proximité des Chutes.","","Apporter la Fiole d'échantillon des Chutes de la Bondissante remplie à Alanndarian Chantenuit, à Auberdine, dans Sombrivage."}}
D[6123] = {"Rassembler les ingrédients du remède",{"Apporter 5 Terrestrines et 12 Champignons lunaires à Alanndarian Chantenuit, à Auberdine ; elle pourra ainsi commencer à préparer son remède."}}
D[6124] = {"Soigner la maladie",{"Utiliser le Remède pour animaux sur 10 Daims malades qui se trouvent dans Sombrivage ; ceci les soignera. Les Daims malades ont été aperçus d'abord entre le sud de la rivière Bondissante et le nord d'Auberdine ; on en trouve également tout au sud de Sombrivage, à la frontière d'Orneval."}}
D[6125] = {"Pouvoir contre le poison",{"Retourner voir Mathrengyl Pasdelours, dans l'Enclave cénarienne, à Darnassus."}}
D[6126] = {"Nouvelles leçons",{"Aller à Reflet-de-Lune, et parler à Dendrite Brasétoile, au village de Havrenuit."}}
D[6127] = {"Le principe originel",{"Utiliser la Fiole d'échantillon vide du Pic de Brume-funeste pour collecter un échantillon de l'eau d'un bassin, au sommet du Pic de Brume-funeste.","","Apporter ensuite la Fiole d'échantillon remplie à Tonga Totem-runique, à la Croisée, dans les Tarides."}}
D[6128] = {"Rassembler les ingrédients du remède",{"Apporter 5 Terrestrines et 5 Cornes de kodo à Tonga Totem-runique, à la Croisée, pour qu'il puisse préparer un baume curatif."}}
D[6129] = {"Soigner la maladie",{"Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée."}}
D[6130] = {"Pouvoir contre le poison",{"Retourner voir Turak Totem-runique, sur la Cime des Anciens, aux Pitons du Tonnerre."}}
D[6131] = {"Allié des Grumegueules",{"Grifleur veut que vous prouviez votre valeur en tuant 5 Guerriers Mort-bois, 5 Guides Mort-bois et 5 Jardiniers Mort-bois."}}
D[6132] = {"Faites-moi sortir de là !",{"Escorter Melizza Razzkankan, puis parler à Hornizz Razzkankan au cimetière des Kodos en Désolace."}}
D[6133] = {"L'ordre du seigneur forestier",{"Aller vers la frontière nord des Maleterres de l'est et récupérer le Registre de Quel'Thalas. L'objet se trouve quelque part dans le gîte de Quel'Lithien.","","Tuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons."}}
D[6134] = {"Chasse à l'ectoplasme",{"Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Razzkankan, en Désolace."}}
D[6135] = {"Crépuscaile, oh comme je te hais !",{"Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l'apporter à Nathanos le Flétrisseur.","","Il paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris."}}
D[6136] = {"Le corpulent",{"Trouver Creusechair, dans les terres au nord des Maleterres de l'est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée."}}
D[6141] = {"Frère Anton",{"Adressez-vous au frère Anton, en Désolace."}}
D[6142] = {"Des praires comme appât",{"Trouver 10 morceaux de Chair de praire et les apporter à Mai'Lahii, à Proie-de-l'Ombre."}}
D[6143] = {"D'autres poissons-chats à fouetter",{"Tuer 7 Myrmidons Ondulame, 7 Nagas Ondulame et 5 Sorcières Ondulame, puis parler à Drulzegar, à Proie-de-l'Ombre, en Désolace."}}
D[6144] = {"L'appel du commandement",{"Aller à Fossoyeuse et parler à Varimathras."}}
D[6145] = {"Le messager cramoisi",{"Retourner dans les Maleterres de l'est et traquer le Messager cramoisi, le tuer et récupérer les Ordres du Grand croisé.","","Apporter les Ordres à Nathanos le Flétrisseur pour obtenir des instructions supplémentaires."}}
D[6146] = {"La ruse de Nathanos",{"Aller à la Main de Tyr, au sud-est de la ferme des Marris. Une fois sur place, mordre dans la Pomme pourrie. Profiter d'avoir revêtu l'apparence d'un membre de la Croisade écarlate pour apporter les Ordres du Grand Croisé au Grand maître Valdelmar."}}
D[6147] = {"Retourner voir Nathanos",{"Retourner voir Nathanos le Flétrisseur avec la nouvelle information."}}
D[6148] = {"L'Oracle écarlate, Demetria",{"La Croisade écarlate fait mouvement. Quelque part le long de la route, entre la Main de Tyr et Stratholme, vous trouverez l'Oracle Demetria et sa fratrie. La tuer et retourner voir Nathanos le Flétrisseur."}}
D[6161] = {"Revendiquer le trésor de Rackmore !",{"Trouver la Clé d'argent de Rackmore. Trouver la Clé d'or de Rackmore. Trouver et ouvrir le Coffre de Rackmore."}}
D[6162] = {"La dernière bataille d'un mari",{"Tuer le Seigneur Ror et apporter sa Griffe à Dreka'Sur, au Poste de la Vénéneuse, en Gangrebois."}}
D[6163] = {"Ramstein",{"Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos."}}
D[6164] = {"Le livre de compte d'Augustus",{"Apporter le Livre de compte d'Augustus à Augustus le Touché à Val-Terreur."}}
D[6181] = {"Un message rapide",{"Apporter la Note de Lewis à Thor, le Maître des griffons."}}
D[6182] = {"Le premier et le dernier",{"Parler à Mathias Shaw, dans la vieille ville de Hurlevent. Il se trouve dans la caserne."}}
D[6183] = {"Honorer la mort",{"Reparlez à Mathias Shaw, quand vous aurez décidé d'accepter son travail."}}
D[6184] = {"Flint Shadowmore",{"Allez au camp du Noroît, dans les Maleterres de l’ouest, et rencontrez votre contact, Flint Shadowmore."}}
D[6185] = {"Les Maleterres de l'Est",{"Fouillez les Maleterres de l'est pour trouver des indices relatifs au \"Flétrisseur\" et aux agents du SI:7 portés disparus. Si vous trouvez un quelconque Insigne du SI:7, rapportez-le à Flint Ombrelongue, au camp du Noroît."}}
D[6186] = {"La venue du Flétrisseur",{"Retourner à Hurlevent et informer le généralissime Bolvar Fordragon du destin de Nathanos Marris."}}
D[6187] = {"L'ordre doit être rétabli",{"Montez une armée et portez-vous vers les Maleterres de l'est. Lancez un assaut total sur Nathanos le Flétrisseur et détruisez tout misérable élément de la Horde qui tenterait de le défendre.","","Gardez votre présence d'esprit, <nom> : la Horde le défendra jusqu'à la mort."}}
D[6221] = {"Les Mort-bois du nord",{"Nafien veut que vous tuiez 5 Protecteurs Mort-bois, 5 Vengeurs Mort-bois et 5 Chamans Mort-bois."}}
D[6241] = {"Les Tombe-hiver s'agitent",{"Salfa voudrait que vous tuiez 6 Totémiques, 6 Gardes et 6 Guides de la tribu Tombe-hiver."}}
D[6261] = {"Dungar Grangodet",{"Apportez la Caisse d'Osric à Dungar Grangodet, le Maître des griffons."}}
D[6281] = {"Continuer vers Stormwind",{"Achetez un voyage en griffon à Thor, Maître des griffons, puis apportez la Note de Lewis à Osric Strang au magasin \"Immunité limitée\", dans la vieille ville de Hurlevent."}}
D[6282] = {"La menace des harpies",{"Maggran Lieur-de-terre, de la Retraite de Roche-Soleil, vous demande de tuer sept Harpies, sept Embusquées, sept Tueuses et sept Volplumes Rougefuries."}}
D[6283] = {"La lignée Rougefurie",{"Maggran, à la Retraite de Roche-Soleil, vous demande de détruire la Déchiqueteuse Rougefurie et de rapporter son corps comme preuve de votre exploit."}}
D[6284] = {"Arachnophobie",{"Tuer Besseleth et apporter le Croc de Besseleth à Maggran, à la Retraite de Roche-Soleil."}}
D[6285] = {"Aller voir Lewis",{"Achetez un voyage en griffon pour la Colline des sentinelles à Dungar Grangodet, Maître des griffons, puis apportez la Caisse d'Osric à Lewis à la Colline des sentinelles."}}
D[6301] = {"Cycle de la renaissance",{"Tammra Champ-des-vents, de la Retraite de Roche-Soleil, vous demande de récolter 10 Graines de Gaïa."}}
D[6321] = {"Approvisionner le Sépulcre",{"Apporter l'Ordre de Podrig à Karos Razok."}}
D[6322] = {"Michael Garrett",{"Apporter la Caisse de Gordon à Michael Garret."}}
D[6323] = {"Voyage vers Undercity",{"Acheter un voyage en chauve-souris pour Fossoyeuse, auprès du Maître des chauves-souris, Karos Razok, puis apporter l'Ordre de Podrig à Gordon Wendham, à Fossoyeuse."}}
D[6324] = {"Retour vers Podrig",{"Acheter un voyage en chauve-souris pour le Sépulcre, auprès du Maître des chauves-souris Michael Garret, puis apporter la Caisse de Gordon au Nécrogarde Podrig, au Sépulcre."}}
D[6341] = {"Le don de Teldrassil",{"Apporter la Collection de Nessa à Vesprystus."}}
D[6342] = {"Vol vers Auberdine",{"Prenez un hippogriffe vers Auberdine chez le maître des hippogriffes Vesprystus, puis apportez la Collection de Nessa à Laird."}}
D[6343] = {"Retourner à Nessa",{"Réponse de Laird à Nessa Chantelombre."}}
D[6344] = {"Nessa Chantelombre",{"Parler à Nessa Chantelombre."}}
D[6361] = {"Un tas de peaux",{"Apporter le Tas de peaux au Maître des coursiers du vent Devrak, à la Croisée."}}
D[6362] = {"Voyage vers les Pitons du Tonnerre",{"Acheter un voyage pour les Pitons du Tonnerre, auprès du Maître des coursiers du vent, Devrak, puis apporter le Tas de peaux à Ahanu, aux Pitons du Tonnerre."}}
D[6363] = {"Tal le Maître des Cavaliers célestes",{"Apporter les Marchandises en cuir d'Ahanu à Tal, aux Pitons du Tonnerre."}}
D[6364] = {"Retourner vers Jahan",{"Acheter un voyage pour la Croisée auprès du maître des coursiers du vent Tal, puis apporter les Marchandises en cuir d'Ahanu à Jahan Aile-de-faucon."}}
D[6365] = {"Viandes vers Orgrimmar",{"Apporter la Chair de Zargh à Devrak, à la Croisée."}}
D[6381] = {"Nouvelle vie",{"Planter 10 Graines de Gaïa sur les Monticules de Gaïa, puis rapporter les Graines de Gaïa enchantées restantes à Tammra, à la Retraite de Roche-Soleil."}}
D[6382] = {"La Chasse d'Ashenvale",{"Parler à Senani Cœur-de-tonnerre, au Poste de Bois-brisé, à Orneval."}}
D[6383] = {"La Chasse d'Orneval",{"Pour clore la Chasse d’Ashenvale, vous devrez affronter trois créatures légendaires. Vous allez devoir les rechercher et vous mesurer à leur malice et leur force. En accomplissant cela, vous apprendrez des choses sur vous. Ces créatures sont : l'ours Ursangous, le sabre-de-nuit Shadumbra et l'hippogryphe Serres-tranchantes.","","Les créatures de la Chasse d'Ashenvale sont puissantes, et vous aurez peut-être besoin d'aide pour les vaincre. Si vous les battez, apportez-en-moi la preuve."}}
D[6384] = {"Trajet vers Orgrimmar",{"Acheter un voyage pour Orgrimmar, auprès du Maître des coursiers du vent, Devrak, puis apporter la Chair de Zargh à Gryshka, à Orgrimmar."}}
D[6385] = {"Doras le Maître des Cavaliers célestes",{"Apporter la Lettre de Gryshka à Doras, à Orgrimmar."}}
D[6386] = {"Retour à la Croisée",{"Acheter un voyage pour la Croisée auprès du Maître des coursiers du vent Doras, puis apporter la Lettre de Gryshka à Zargh, à la Croisée."}}
D[6387] = {"L'honneur des étudiants",{"Apportez la Liste de Brock à Thorgrum Borrelson à Thelsamar."}}
D[6388] = {"Gryth Thurden",{"Apportez les Pioches d'honneur à Gryth Thurden à Forgefer."}}
D[6389] = {"Une Plaie sur la Croisade",{"Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l'ouest, avec le Tonneau de Termites des Maleterres."}}
D[6390] = {"Une Plaie sur la Croisade",{"Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal, avec le Tonneau de Termites des Maleterres."}}
D[6391] = {"Voyage vers Ironforge",{"Acheter un billet de griffon pour Forgefer, auprès du Maître des griffons, Thorgrum Borrelson, puis apporter la Liste de Brock à Golnir Rochorteil, à Forgefer."}}
D[6392] = {"Retourner vers Brock",{"Acheter un billet de griffon pour Thelsamar, auprès du Maître des griffons Gryth Thurden, puis apporter les Pioches d'honneur à Brock Cherchepierre, à Thelsamar."}}
D[6393] = {"Guerre élémentaire",{"Apporter 10 Incendrites à Tsunaman à la Retraite de Roche-Soleil."}}
D[6394] = {"La pioche de Thazz'ril",{"Apportez la Pioche de Thazz'rill au contremaître Thazz'rill."}}
D[6395] = {"La dernière volonté de Marla",{"Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la Novice Elreth."}}
D[6401] = {"Kaya est en vie",{"Apprendre la bonne nouvelle à Tammra Champ-des-vents à la Retraite de Roche-Soleil."}}
D[6402] = {"Le rendez-vous à Stormwind",{"Voyagez jusqu'à Hurlevent et rendez-vous aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée."}}
D[6403] = {"La grande mascarade",{"Suivre Reginald Windsor dans Hurlevent. Le protéger contre toute menace !"}}
D[6421] = {"Le ravin des Éboulis",{"Explorer la grotte du ravin des Éboulis et apporter 10 Cristaux de résonite à Mor'rogal à la Retraite de Roche-Soleil."}}
D[6441] = {"Cornes de satyre",{"Collecter 16 Cornes de satyre pour Pixel, au Poste de Bois-brisé."}}
D[6442] = {"Des nagas sur la grève de Zoram",{"Apporter 20 Têtes d'Irequeue à Marukai, le long de la grève de Zoram."}}
D[6461] = {"Suceurs de sang",{"Xen'zilla, à Malaka'Jin, voudrait que vous tuiez 10 Rampants des mousses profondes et 7 Venimeux des mousses profondes."}}
D[6462] = {"Charme troll",{"Apporter 8 Charmes trolls à Mitsuwa, à l'Avant-poste de Zoram'gar."}}
D[6481] = {"Un Terrestre se lève",{"Ouvrir la Gangue de résonite avec le Cristal de résonite enchanté, puis tuer Goggeroc. Retourner voir Mor'rogal pour l'informer et lui rapporter le Cristal de résonite enchanté."}}
D[6482] = {"Liberté pour Ruul",{"Escorter Ruul, puis parler à Yama Sabot-de-neige, au Poste de Bois-brisé."}}
D[6501] = {"L'Œil de dragon",{"Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c'est qu'elle existe."}}
D[6502] = {"Amulette drakefeu",{"Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Rochenoire."}}
D[6503] = {"Les estafettes d'Orneval",{"Tuer 9 Estafettes d'Orneval, puis retourner voir Kuray'bin, à l'avant-poste de Bois-brisé."}}
D[6504] = {"Les pages perdues",{"Trouver les 12 pages manquantes du Manuel d'utilisation du Déchiqueteur, puis les rassembler pour constituer les Chapitres 1, 2, et 3. Ramener les pages à Gurda Ragentaille près du poste de Bois-brisé."}}
D[6521] = {"Une alliance impie",{"Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Fossoyeuse."}}
D[6522] = {"Une alliance impie",{"Apporter le Petit parchemin à Varimathras, à Fossoyeuse."}}
D[6523] = {"Protéger Kaya",{"Escorter Kaya Sabot-plat au Camp Aparaje, puis retourner voir Makaba Sabot-plat, à côté de la frontière sud-est des Serres-Rocheuses."}}
D[6541] = {"Rapport à Kadrak",{"Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides."}}
D[6542] = {"Rapport à Kadrak",{"Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides."}}
D[6543] = {"Les rapports Chanteguerre",{"Apporter les Rapports du clan Chanteguerre à l'Eclaireur Chanteguerre, au Messager Chanteguerre et au Voltigeur Chanteguerre. Rapporter leurs comptes rendus mis à jour à Kadrak, dans la tour de guet nord, dans les Tarides."}}
D[6544] = {"L'assaut de Torek",{"Escorter Torek lors de son attaque contre l'Avant-poste d'Aile-argent et Duriel Lunéclat, puis faire un rapport à Ertog Ragembroche, au Poste de Bois-brisé."}}
D[6545] = {"Mise à jour du Messager Warsong",{"Donc vous êtes ici avec mes ordres ? C'est toujours un plaisir de voir une nouvelle recrue avec une nature exubérante et qui persévère.","","Vous devez apprendre vite si vous voulez rester ici. La menace que représentent les nagas grandit, <nom>. Je me suis occupé de la défense lors de plusieurs attaques contre cet avant-poste depuis que je suis ici.","","Mais si vous voulez vous y atteler, parlez à quelqu'un d'autre à l'avant-poste."}}
D[6546] = {"Mise à jour du voltigeur Warsong",{"Il y a beaucoup de dangers sur ce chemin, <nom>. Vous avez intérêt à ne pas l'oublier quand vous traverserez ces terres. La menace que représente l'Alliance est très proche.","","Nous avons des ennemis sur tous les fronts. Les satyres sont une force redoutable et très répandue dans l'est d'Ashenvale. De plus, j'ai découvert que les nagas ont envahi une grande partie des terres d'Azshara.","","Il est réconfortant de voir que nos effectifs augmentent. Il faut se préparer à ce qui nous attend, <nom>."}}
D[6547] = {"Mise à jour de l'Eclaireur Warsong",{"Gardez l'oeil ouvert, <nom>. Les elfes se cachent souvent dans les ombres...","","Nous devons toujours être à l'affût. Nous avons travaillé dur pour gagner cette terre, et les elfes cherchent à nous la voler.","","J'imagine que vous m'avez apporté mes prochains ordres provenant de Kadrak ?"}}
D[6548] = {"Vengez mon village !",{"Tuez 8 Forbans du Totem-sinistre et 6 Mercenaires du Totem-sinistre, puis retournez voir Makaba Sabot-plat, près de la lisière sud-est des Serres-Rocheuses."}}
D[6561] = {"L'infamie de Brassenoire",{"Apporter la tête du Seigneur du crépuscule Kelris à Bashana Totem-runique, aux Pitons du Tonnerre."}}
D[6562] = {"Problèmes dans les profondeurs",{"Parler à Je'neu Sancrea, à Orneval."}}
D[6563] = {"L'Essence d'Aku'Mai",{"Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Orneval."}}
D[6564] = {"Allégeance aux Dieux très anciens",{"Apporter la Note humide à Je'neu Sancrea, à Orneval."}}
D[6565] = {"Allégeance aux Dieux très anciens",{"Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Orneval."}}
D[6566] = {"Ce que le vent apporte",{"Écouter Thrall."}}
D[6567] = {"Le Champion de la Horde",{"Chercher Rokaro au village Proie-de-l'Ombre en Désolace."}}
D[6568] = {"Maîtresse en tromperie",{"Apporter la Lettre de Rokaro à Myranda la Mégère, dans les Maleterres de l'ouest."}}
D[6569] = {"Illusions d'Occulus",{"Aller au Pic Rochenoire et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère quand la tâche sera terminée."}}
D[6570] = {"Brandeguerre",{"Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l'intérieur, porter l'Amulette de subversion draconique, et parler à Brandeguerre."}}
D[6571] = {"Fournitures Chanteguerre",{"Collecter les Fournitures Chanteguerre : Lames du clan Chanteguerre, Huile Chanteguerre, et la Cargaison de Haches chanteguerres ayant pour destinataire Locke Okarr, au Poste de Bois-brisé."}}
D[6581] = {"Lames du clan Warsong",{"En provenance directe de Ratchet, des lames du clan Warsong ! Ouais, je les ai ici.","","Mais qu'avez-vous en contrepartie pour moi ? Vous ne pouvez pas les emporter comme ça, vous savez ! Mon temps coûte cher !","","Ce dont j'ai besoin, c'est d'une bonne arme à feu pour mes voyages. Une fille doit se protéger savez-vous ? Il y en a une que j'aime particulièrement, et je suis sûre qu'un ingénieur n'aura aucun problème à la fabriquer.","","Voilà, si vous m'apportez un Tromblon mortel, je vous donnerai la cargaison de lames. Alors, marché conclu ?"}}
D[6582] = {"L'épreuve des crânes, Clairvoyant",{"Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.","","Clairvoyant se trouve au Berceau-de-l'Hiver."}}
D[6583] = {"L'épreuve des crânes, Somnus",{"Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre."}}
D[6584] = {"L'épreuve des crânes, Chronalis",{"Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre."}}
D[6585] = {"L'épreuve des crânes, Axtroz",{"Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l'apporter à Brandeguerre."}}
D[6601] = {"Ascension...",{"Il semble que la comédie soit finie. Vous savez que l'Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l'intérieur du pic Rochenoire. Peut-être devriez-vous trouver Rokaro et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire."}}
D[6602] = {"Le sang du champion des dragons noirs",{"Aller au Pic Rochenoire, et tuer le général Drakkisath. Récupérer son sang et l'apporter à Rokaro."}}
D[6603] = {"Troubles au Berceau-de-l'Hiver",{"Trouver Donova Antreneige, à côté des sources chaudes du Berceau-de-l'Hiver."}}
D[6604] = {"Les Indomptables enragés",{"Parler à Jaron Sculptepierre, au village de Pluie-d'Étoiles."}}
D[6605] = {"Une étrange personne",{"Parler à Winna Hazzard, à Gangrebois."}}
D[6606] = {"Un peu de chance",{"Parler à la Mau'ari, à Long-guet."}}
D[6607] = {"Nat Pagle, pêcheur de l'extrême",{"Nat Pagle voudrait que vous attrapiez les poissons suivants :","","Le Mahi Mahi de Brumejonc, de la grève de Brumejonc, dans le marais des Chagrins.","","Un Frappeur de Sar'theris, de la grève de Sar'theris en Désolace.","","L'Ahi de Féralas, de la rivière Verdantis de Féralas.","","Le Sailfin bleu de la Côte sauvage, de la Côte sauvage de la vallée de Strangleronce.","","Retournez voir Nat Pagle quand la collecte sera terminée."}}
D[6608] = {"Vous êtes trop bon",{"Vous pensez que Lumak essaie de vous dire qu'il ne peut plus vous aider à améliorer votre compétence de pêche. Vous devriez essayer de vous adresser maintenant à son ami, Nat Pagle, un pêcheur humain des îles au sud de Theramore (c'est du moins ce que vous croyez comprendre du discours de Lumak)."}}
D[6609] = {"Il ne me reste rien !",{"Aller à Kalimdor, dans la ville côtière de Theramore. À partir de là, chercher une île au sud de la ville principale. Nat Pagle vous attend !"}}
D[6610] = {"Surprise de palourdes",{"Dirge Hachillico voudrait que vous lui apportiez les objets suivants :","","12 Oeufs géants. Vous les trouverez sur les Rocs qui hantent Tanaris ou sur toute autre espèce de grand oiseau.","","10 morceaux de Chair de palourde piquante. Vous pouvez trouver la chair de palourde sur... les palourdes, naturellement !","","20 Emmentals d'Alterac. Vous les trouverez dans une fromagerie !","","Collectez tous ces objets, puis retournez voir Dirge."}}
D[6611] = {"Vers Gadgetzan vous allez !",{"Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Hachillico."}}
D[6612] = {"Je connais un gars...",{"Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Hachillico."}}
D[6621] = {"Le roi des Vile-sylve",{"Placer la Bannière de Karang sur le Monticule du totem Vile-sylve. Ne pas laisser les furbolgs détruire la Bannière. Tuer le chef Murgut, et apporter le Totem de Murgut à Karang Amakkar, à Zoram'gar."}}
D[6622] = {"Triage",{"Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d'entre eux ne meurent de leurs blessures.","","Rappelez-vous l'ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRÈS ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait."}}
D[6623] = {"Service de traumatologie de la Horde",{"Aller au Trépas-d'Orgrim, dans les hautes-terres d'Arathi, et évoquer avec le docteur Gregory Victor la possibilité de rejoindre les rangs des médecins de la Horde."}}
D[6624] = {"Triage",{"Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d'entre eux ne meurent de leurs blessures.","","Rappelez-vous l'ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait."}}
D[6625] = {"Service de traumatologie de l'Alliance",{"Aller à Theramore, dans le marécage d'Âprefange, et parler au docteur Gustaf VanHowzen de la possibilité de rejoindre les rangs des médecins de l'Alliance."}}
D[6626] = {"L'hôte du mal",{"Tuer 8 Gardes de guerre de Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Chantelune, à l'entrée des Souilles de Tranchebauge."}}
D[6627] = {"L'épreuve de la Connaissance",{"Réussir à répondre à la question de Braug Esprit-troublé, puis lui reparler. Il se trouve dans les Serres-Rocheuses."}}
D[6628] = {"L'épreuve de la Connaissance",{"Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Fossoyeuse."}}
D[6629] = {"Tuer Grundig Noir-nuage",{"Tuer Grundig Noir-nuage et 6 Brutes du Totem-sinistre, puis retourner voir Makaba Sabot-plat, à côté de la frontière sud-est des Serres Rocheuses."}}
D[6641] = {"Vorsha la Flagellante",{"Garantir la sécurité de Muglash tandis qu'il voyage vers le brasero. L'aider à éteindre le brasero, puis le protéger, en combattant les nagas.","","En cas de réussite, retourner à l'avant-poste de Zoram'gar et informer le messager Chanteguerre de la mort de Vorsha la Flagellante."}}
D[6642] = {"Faveur auprès de la Confrérie, Minerai de sombrefer",{"Le sombre fer, bien qu'il soit répandu dans les Profondeurs, est toujours considéré comme un produit de valeur pour la Confrérie. Les armes sacrées de Ragnaros nécessitent du sombre fer.","","Pour chaque 10 morceaux de Minerai de sombre fer que vous offrirez, une faveur vous gagnerez."}}
D[6643] = {"Faveur auprès de la Confrérie, Noyau de feu",{"Malheur à ceux qui défient le destin au Cœur du Magma ! La mort frappe rapidement ! Le châtiment est sans pitié.","","De nombreux membres de la Confrérie ont disparu en recherchant des Noyaux de feu.","","Donnez 1 Noyau de feu et vous obtiendrez une faveur de la part de la Confrérie."}}
D[6644] = {"Faveur auprès de la Confrérie, Noyau de lave",{"La Confrérie du Thorium comprend vos difficultés, <nom>. C'est pour cela que Lokthos a reçu les pleins pouvoirs pour négocier.","","Donnez 1 Noyau de lave et vous recevrez une faveur de la part de la Confrérie."}}
D[6645] = {"Faveur auprès de la Confrérie, Cuir du Magma",{"Beaucoup de recettes sacrées exigent du cuir des familiers personnels de Ragnaros.","","Donnez 2 Cuirs du Magma, provenant du corps des Chiens du Magma, et vous recevrez une faveur de la Confrérie."}}
D[6646] = {"Faveur auprès de la Confrérie, Sang de la montagne",{"Les larmes du Seigneur du feu sont vraiment très rares.","","Offrez 1 Sang de la montagne et une faveur vous sera accordée par la Confrérie."}}
D[6661] = {"Chasse au rat dans les profondeurs",{"Capturer 5 Rats des profondeurs en utilisant le Pipeau du dératiseur. Conduire les Rats vers Monty. N'oubliez pas de rendre le Pipeau quand vous aurez terminé."}}
D[6662] = {"Mon frère, Nipsy",{"Apporter le Carton de viande mystère à Nipsy, au Dépôt du Tram des profondeurs de Hurlevent."}}
D[6681] = {"Ravenholdt, le manoir",{"Apporter le Sceau de Ravenholdt à Fahrad, au Manoir de Ravenholdt, dans les collines de Hautebrande.","","Votre sagacité sera mise à l'épreuve tout au long de la route. Préparez-vous."}}
D[6701] = {"Emblèmes du Syndicat",{"Nous sommes en guerre avec le Syndicat depuis des années. Ils compensent par leur nombre leur manque de compétences. Nous n'arrivons pas à les tuer assez rapidement pour que cela ait un impact notable sur leur population !","","Nous avons découvert que le meilleur moyen de gérer leur nombre est de voler leurs Emblèmes. Chaque membre qui la perd est 'puni' en interne.","","Détroussez-les et rapportez les Emblèmes à moi ou aux autres Gardes.","","Commencez à Durnholde, au sud d'ici."}}
D[6721] = {"La voie du chasseur",{"Parler à Dazalar, à Dolanaar."}}
D[6722] = {"La voie du chasseur",{"Parler à Dazalar, à Dolanaar."}}
D[6741] = {"Plus de butin !",{"J'ai besoin de plus de Morceaux d'armure, <nom> ! Vous en avez ?"}}
D[6761] = {"La nouvelle frontière",{"Parler à Mathrengyl Pasdelours, dans l'Enclave cénarienne de Darnassus."}}
D[6762] = {"Rabine Saturna",{"Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules."}}
D[6781] = {"Plus de morceaux d'armure !",{"<nom>, nous avons besoin de davantage de Morceaux d’armure pour équiper nos troupes !"}}
D[6801] = {"Lokholar le Seigneur des Glaces",{"Je viens de Thunder Bluff, <nom>. Cairne en personne m’a diligenté afin que j’assiste le clan Frostwolf en ces temps difficiles.","","Mais ne perdons pas plus de temps. Vous devez abattre nos ennemis et me rapporter un peu de leur sang. Une fois que le sang aura été collecté, le rituel d’invocation pourra commencer.","","La victoire sera certaine lorsque le Seigneur élémentaire sera lâché sur l’armée des Stormpike."}}
D[6804] = {"Eau empoisonnée",{"Utiliser l'Aspect de Neptulon sur les élémentaires empoisonnés des Maleterres de l'est. Apporter 12 Bracelets discordants et l'Aspect de Neptulon au duc Hydraxis, en Azshara."}}
D[6805] = {"Tempêtes",{"Tuer 15 Tempétueux de poussière et 15 Grondeurs du désert, puis retourner voir le duc Hydraxis, en Azshara."}}
D[6821] = {"Œil du Prophète ardent",{"Apporter l'Oeil du Prophète ardent au duc Hydraxis, en Azshara."}}
D[6822] = {"Le Cœur du Magma",{"Tuer 1 Seigneur du feu, 1 Géant de lave, 1 Chien antique du Magma et 1 Surgisseur de lave, puis retourner voir le duc Hydraxis, en Azshara."}}
D[6823] = {"Agent de Hydraxis",{"Parvenir au niveau de réputation Honoré auprès des Hydraxiens, puis parler au duc Hydraxis, en Azshara."}}
D[6824] = {"Les mains de l'ennemi",{"Apporter les Mains de Lucifron, de Sulfuron, de Gehennas et de Shazzrah au duc Hydraxis, en Azshara."}}
D[6825] = {"L'appel des airs - l'escadrille de Guse",{"Nous devons préparer la nouvelle flotte des Chevaucheurs de guerre, <nom> ! Mes Chevaucheurs sont prêts pour combattre au centre du champ de bataille, mais d’abord nous devons les mettre en appétit et les préparer à l’assaut.","","Il me faut suffisamment de chair de soldats Stormpike pour nourrir la flotte ! Des centaines de kilos de viande ! Je suis sûr que vous pouvez vous occuper de ça, n’est-ce pas ?"}}
D[6826] = {"L'appel des airs - l'escadrille de Jeztor",{"Vous avez bien travaillé, <nom>, mais nous ne faisons que commencer !","","Mes Chevaucheurs de guerre doivent goûter à la chair de leurs cibles. Cela permettra d’obtenir comme qui dirait une frappe chirurgicale contre nos ennemis !","","Ma flotte est la seconde plus puissante de toute notre force aérienne. Ce sont eux qui frapperont les plus puissants de nos adversaires. Pour cela, je le répète, il nous faut de la chair des Lieutenants de l'Alliances.","","Faites vite !"}}
D[6827] = {"L'appel des airs - l'escadrille de Mulverick",{"J’ai subi un emprisonnement inhumain dans ce trou à rats. Vous pouvez me croire quand je vous dis que je n’aspire qu’à la vengeance !","","Nous devons agir avec prudence, néanmoins.","","D’abord, mes Chevaucheurs de guerre ont besoin de cibles, de cibles prioritaires. Je me dois de les nourrir avec la chair des commandants de l'Alliance. Malheureusement, ces petits couards sont retranchés loin derrière leurs lignes. Vous avez du pain sur la planche, on peut le dire !"}}
D[6843] = {"Da Foo"}
D[6844] = {"Umber, Archiviste",{"Apporter l'Objet silithide incrusté à Umber, l'archiviste du Cercle cénarien, au village de Havrenuit, à Reflet-de-Lune."}}
D[6845] = {"Les secrets du passé",{"Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune."}}
D[6846] = {"Que l'attaque commence !"}
D[6847] = {"L'Œil qui voit tout de maître Ryson",{"Récupérer l'Oeil-qui-voit-tout de Maître Ryson dans les Grottes Hache-d'hiver, puis le rapporter à Maître Ryson.","","Sachez que l'on dit de l'Oeil-qui-voit-tout de Maître Ryson qu'il contient une terrible malédiction !"}}
D[6848] = {"L'Œil-qui-voit-tout de maître Ryson",{"Récupérez l'Oeil-qui-voit-tout de Maître Ryson dans les Grottes Hache-d'hiver, puis rapportez-le à Maître Ryson.","","Sachez que l'on dit de l'Oeil-qui-voit-tout de Maître Ryson qu'il contient une terrible malédiction !"}}
D[6861] = {"Le Déchiqueteur portatif de Zinfoirux",{"Le Maître Ingénieur Zinfoirux veut que vous lui apportiez les matériaux suivants :","","*30 Barres de thorium.","","*50 Barres de Mithril.","","*75 Barres de fer.","","*1 Scie à vapeur."}}
D[6862] = {"Le Déchiqueteur portatif de Zinfoirux",{"Le Maître Ingénieur Zinfoirux veut que vous lui apportiez les matériaux suivants :","","*30 Barres de thorium.","","*50 Barres de Mithril.","","*75 Barres de fer.","","*1 Scie à vapeur."}}
D[6881] = {"Ivus le Seigneur des forêts",{"Le clan Frostwolf est protégé par un poison constitué d'énergie élémentaire. Leurs chamans ont développé des pouvoirs qui nous détruiront jusqu'au dernier, si on laisse les choses suivre leur cours.","","La menace est maintenant trop importante pour le Cercle. Ivus doit être appelé à l'aide.","","Les soldats Frostwolf portent des charmes élémentaires, appelés Cristaux de tempête. Nous pouvons utiliser ces charmes pour invoquer Ivus. Partez maintenant et récupérez ces cristaux, <nom> !"}}
D[6901] = {"Lancez l'attaque !"}
D[6921] = {"Parmi les ruines",{"Apporter le Noyau de la brasse à Je'neu Sancrea, à l'Avant-poste de Zoram'gar, dans Orneval."}}
D[6922] = {"Baron Aquanis",{"Apporter le Globe d'eau étrange à Je'neu Sancrea, à l'Avant-poste de Zoram'gar, dans Orneval."}}
D[6941] = {"L'appel des airs - l'escadrille de Vipore",{"Les troupes d'élite de la Horde en faction sur la ligne de front doivent être engagées ! Je vous demande de tailler dans cette bande de sauvages et d'en faire chuter les effectifs. Revenez me voir avec les Médailles de leurs Lieutenants et de leurs Légionnaires. Lorsque un nombre suffisant de cette racaille aura étouffé dans son propre sang, je ferai déployer la force aérienne."}}
D[6942] = {"L'appel des airs - l'escadrille de Slidore",{"Mes gryphons sont en place pour donner l'assaut frontal, mais ils ne peuvent pas le faire tant que les rangs ennemis n'auront pas été réduits préalablement.","","Les guerriers de la Horde chargés de tenir la ligne de front portent des Médailles qu'ils arborent fièrement sur leurs poitrines. Arrachez ces Médailles à leurs cadavres et rapportez-les-moi.","","Une fois que les effectifs ennemis de la ligne de front auront été suffisamment réduits, je ferai donner la force aérienne !"}}
D[6943] = {"L'appel des airs - l'escadrille d'Ichman",{"Leur moral est au plus bas. Depuis l'échec cuisant de notre dernière attaque aérienne contre la Horde, ils refusent de voler ! C'est à vous maintenant de remonter leur moral.","","Retournez sur le champ de bataille et frappez le coeur du commandement de la Horde. Abattez leurs commandants et leurs gardiens. Revenez me voir quand vous aurez récupéré autant de Médailles que peut en contenir votre sac ! Je vous promets que lorsque mes gryphons verront ce butin et qu'ils sentiront l'odeur de leur sang sur les Médailles, ils seront prêts à reprendre le combat. Partez maintenant !"}}
D[6961] = {"Grand-père Hiver est ici !",{"Parler à Grand-père Hiver. Il se trouve près des Gourmandises Fumebois à Orgrimmar."}}
D[6962] = {"Des friandises pour Grand-père Hiver",{"Apporter 5 Biscuits en pain d'épice et un Verre de lait glacé au Grand-père Hiver, à Orgrimmar."}}
D[6963] = {"Friandises volées de la fête du Voile d'hiver",{"Trouver l'enquêteur des Gourmandises Fumebois qui est porté disparu dans les montagnes d'Alterac."}}
D[6964] = {"L'esprit de cette fête",{"Parler à Sagorne Rôdeur-des-crêtes, dans la Vallée de la Sagesse d'Orgrimmar, au sujet de la fête du Voile d'hiver."}}
D[6981] = {"L'Éclat luminescent",{"Allez à Cabestan pour trouver quelqu'un qui puisse vous en dire plus sur l'Éclat luminescent.","","Puis livrez l'Éclat, selon les instructions."}}
D[6982] = {"Fournitures de Froide-dent",{"Apporter 10 Fournitures de Froide-dent à l'intendant de l'Alliance, à Dun Baldar."}}
D[6983] = {"La méchanceté vous habite...",{"Localiser les friandises, et les ramener à Béachevé Chipsou, à Orgrimmar. C'est l'abominable Grinche, vivant quelque part dans les régions enneigées des montagnes d'Alterac, qui les détiendrait."}}
D[6984] = {"Un grand merci des Gourmandises Fumebois !",{"Parler à Grand-père Hiver à Orgrimmar."}}
D[6985] = {"Fournitures de Gouffrefer",{"Apporter 10 Fournitures de Gouffrefer à l'Intendant de la Horde, au donjon Loup-de-givre."}}
D[7001] = {"Ecuries vides",{"Trouvez un Loup des glaces dans la vallée d'Alterac. Servez-vous de la Muselière de loup des glaces pour « dompter » la bête. Lorsque ce sera fait, le loup des glaces vous suivra jusqu'au Maître des écuries Loup-de-givre. Parlez au Maître des écuries Loup-de-givre pour être crédité de cette capture."}}
D[7002] = {"Harnais en cuir de bélier",{"Certains de nos soldats sont occupés à capturer des loups pour le maître des écuries. D’autres doivent nous fournir les accessoires nécessaires à la monte. Je parle des harnais, bien sûr.","","Vous devez vous procurer les matières premières sur les béliers de la région. Oui, ceux-là même que les Stormpike utilisent comme montures !","","Tuez-les et ramenez-moi leurs peaux. Lorsque vous en aurez assez, nous fabriquerons des harnais, et les Chevaucheurs de loups Frostwolf entreront dans la bataille !"}}
D[7003] = {"Géants rétrécis",{"Utilisez l'Ultra-réducteur de Zorbin sur des géants de n'importe quel type en Féralas afin les rendre plus faciles à gérer. Apportez 15 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Poudrozieu aux docks de la Côte oubliée en Féralas."}}
D[7021] = {"Grand-père Hiver est ici !",{"Parler à Grand-père Hiver ; il se trouve près des Gourmandises Fumebois, à Orgrimmar."}}
D[7022] = {"Grand-père Hiver est ici !",{"Parler à Grand-père Hiver ; il se trouve près des Gourmandises Fumebois, à Forgefer."}}
D[7023] = {"Grand-père Hiver est ici !",{"Parler à Grand-père Hiver ; il se trouve près des Gourmandises Fumebois, à Forgefer."}}
D[7024] = {"Grand-père Hiver est ici !",{"Parler à Grand-père Hiver. Il se trouve près des Gourmandises Fumebois à Orgrimmar."}}
D[7025] = {"Des friandises pour Grand-père Hiver",{"Apporter 5 Biscuits en pain d'épice et un verre de Lait glacé au Grand-père Hiver à Forgefer."}}
D[7026] = {"Harnais pour béliers",{"La brigade Stormpike ne peut pas charger à cru ! Il nous faut des harnais pour nos montures. Après tout, nous ne sommes pas des sauvages.","","Nous pourrions tuer les béliers qui s'aventurent près de notre base pour fabriquer ces harnais, mais ce serait idiot : nous en avons besoin comme montures.","","Vous devez attaquer la base ennemie, tuer leurs loups de monte et prendre leur peaux. Ramenez-les-moi, et nous en ferons des harnais pour la cavalerie. Allez !"}}
D[7027] = {"Écuries vides",{"Trouvez un Bélier d'Alterac dans la vallée d'Alterac. Lorsque vous serez à proximité, servez-vous du Collier d'entraînement Foudrepique pour le \"dompter\". Une fois dompté, le Bélier d'Alterac vous suivra jusqu'au Maître des écuries. Parlez au Maître des écuries pour être crédité de cette capture."}}
D[7028] = {"Forces maléfiques retorses",{"Collecter 15 Ciselures de Cristaux Théradriques pour Saule, en Désolace."}}
D[7029] = {"La corruption de Vylelangue",{"Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.","","En faire usage sur les Vignes de Vylevrille pour forcer les Engeances Noxcives corrompues à en sortir.","","Soigner 8 plantes en tuant les Engeances Noxcives, puis retourner voir Vark Balafre-glorieuse, à Proie-de-l'Ombre."}}
D[7041] = {"La corruption de Vylelangue",{"Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon.","","En faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.","","Soigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel."}}
D[7042] = {"Friandises volées de la fête du Voile d'hiver",{"Localiser l'enquêteur des Gourmandises Fumebois qui a été porté disparu dans les montagnes d'Alterac."}}
D[7043] = {"La méchanceté vous habite...",{"Trouver les Friandises volées, et les ramener à Karfour Tintinnabourse, à Forgefer. C'est l'Abominable Grinche qui aurait le chargement en sa possession, il résiderait dans les régions neigeuses des montagnes d'Alterac."}}
D[7044] = {"Légendes de Maraudon",{"Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras.","","Trouvez un moyen de parler à Celebras."}}
D[7045] = {"Un grand merci des Gourmandises Fumebois !",{"Parler à Grandpère Hiver à Ironforge."}}
D[7046] = {"Le sceptre de Celebras",{"Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras.","","Parlez-lui après la réussite du rituel."}}
D[7061] = {"La fête du Voile d'hiver",{"Prenez le temps de lire ce livre, \"La fête du Voile d'hiver\", pour en apprendre plus sur cette période de fête. Quand vous en aurez fini avec le livre, apportez-le à Cairne Sabot-de-sang, dans la ville des Pitons du Tonnerre."}}
D[7062] = {"L'esprit de cette fête",{"Parlez à l'historien Karnik de la fête du Voile d'hiver, en vous rendant à la Ligue des Explorateurs de Forgefer."}}
D[7063] = {"La fête du Voile d'hiver",{"Prenez le temps de lire le livre \"La fête du Voile d'hiver\" pour en apprendre plus sur cette période sainte. Quand vous en aurez fini avec le livre, apportez-le au roi Magni Barbe-de-bronze, à Forgefer."}}
D[7064] = {"Corruption de la terre et de la graine",{"Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace."}}
D[7065] = {"Corruption de la terre et de la Graine",{"Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace."}}
D[7066] = {"La graine de la vie",{"Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de la vie."}}
D[7067] = {"Les instructions du paria",{"Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au paria centaure, dans le sud de Désolace."}}
D[7068] = {"Fragments d'Ombréclat",{"Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar."}}
D[7070] = {"Fragments d'Ombréclat",{"Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange."}}
D[7081] = {"Les cimetières de la vallée d'Alterac",{"Attaquez un cimetière, puis présentez-vous au sergent Durgen Foudrepique dans les montagnes d'Alterac."}}
D[7082] = {"Les cimetières d'Alterac",{"Attaquez un cimetière, puis présentez-vous au caporal Teeka Gronde-sang dans les montagnes d'Alterac."}}
D[7101] = {"Tours et fortins",{"Prenez une tour ennemie, puis présentez-vous au caporal Teeka Gronde-sang dans les montagnes d'Alterac."}}
D[7102] = {"Tours et fortins",{"Détruisez la bannière d'une tour ou d'un fortin ennemi, puis présentez-vous au sergent Durgen Foudrepique à Dun Baldar."}}
D[7121] = {"L'intendant",{"Parlez à l'Intendant Foudrepique."}}
D[7122] = {"Prendre une mine",{"Prenez une mine que les Foudrepiques ne contrôlent pas, puis présentez-vous au sergent Durgen Foudrepique dans les montagnes d'Alterac."}}
D[7123] = {"Parlez à notre Intendant",{"Parlez à l'Intendant Loup-de-givre."}}
D[7124] = {"Prendre une mine",{"Prenez une mine, puis présentez-vous au caporal Teeka Gronde-sang dans les montagnes d'Alterac."}}
D[7141] = {"La bataille d'Alterac",{"Entrez dans la vallée d'Alterac, tuez Drek'Thar, le général de la Horde, puis retournez voir la Prospectrice Taillepierre dans les montagnes d'Alterac."}}
D[7142] = {"La bataille pour Alterac",{"Entrez dans la vallée d'Alterac, tuez Vanndar Foudrepique, le général nain, puis retournez voir Voggah Mortepoigne dans les montagnes d'Alterac"}}
D[7161] = {"Montrer sa valeur",{"Rendez-vous dans les cavernes des Follepattes, au sud-est de la base principale, et récupérez la Bannière Loup-de-givre qui s'y trouve. Ramenez-la au Maître de guerre Laggrond."}}
D[7162] = {"Montrer sa valeur",{"Rendez-vous dans les cavernes de l'Aile de glace, au sud-ouest de Dun Baldar dans la vallée d'Alterac, et récupérez la Bannière Foudrepique. Ramenez-la au lieutenant Haggerdin dans les montagnes d'Alterac."}}
D[7163] = {"Ascension et reconnaissance"}
D[7164] = {"Honoré au sein du clan"}
D[7165] = {"Montée en grade",{"Tant de morts. Un champ saturé de sang. Mais vous êtes en vie. Vous avez persévéré. Vous avez mené nos armées à la victoire. Et pour cela, soldat, vous avez mérité de monter en grade.","","Présentez votre insigne."}}
D[7166] = {"Héros de légende",{"Puissance et autorité émanent de vous, <classe>. Vous êtes exalté aux yeux des Frostwolf – l’ennemi se cache à la seule mention de votre nom.","","Debout, Héros des Frostwolf. Debout et soyez honoré !","","Présentez votre insigne."}}
D[7167] = {"L'Œil du commandement",{"Drek’Thar chante vos louanges. Kalimdor résonne du bruit de vos exploits. Le chef de guerre sourit – votre héroïque défense de notre clan l’a grandement satisfait.","","Vous avez mérité l’Œil du Commandement.","","Présentez votre insigne, commandant <nom>."}}
D[7168] = {"Ascension et reconnaissance",{"La plupart des gens ne vivent pas assez longtemps pour s’élever au-dessus de leur propre médiocrité. Vous avez montré que vous êtes un soldat exemplaire, <classe>. L’heure est venue.","","Présentez votre insigne."}}
D[7169] = {"Honoré au sein de la Garde",{"Toute la base parle de vos exploits sur le Champ sanglant ! Vous avez porté des coups sévères à l’ennemi – et à son moral ! Pour cela, vous avez mérité de progresser au sein des Stormpike.","","Présentez votre insigne."}}
D[7170] = {"Montée en grade",{"Je m’interroge, <nom>. Lorsque vous regardez dans les yeux de l’ennemi, y voyez-vous la peur ? Se cachent-ils plutôt que de vous faire face ? Ils doivent bien se rendre compte qu’ils sont vaincus !","","Vous avez mérité que la Garde vous traite avec révérence. Présentez votre insigne !"}}
D[7171] = {"Héros de légende",{"Devant moi se tient un héros de l’Alliance.","","<Le Lieutenant Haggerdin salue.>","","Rares sont ceux qui ont obtenu un tel grade parmi les Stormpike. J’ai vu l’ennemi tomber devant vous. J’ai vu leur résolution s’effondrer devant votre présence. Lorsque vous entrez dans la mêlée, vous devenez un point de ralliement pour nos forces !","","Présentez votre insigne."}}
D[7172] = {"L'Œil du commandement"}
D[7181] = {"La légende de Korrak",{"D'après la légende, le chef des puissants trolls Haches-d'hiver se montre quand il le décide pour semer la destruction chez les habitants de la vallée d'Alterac.","","Si Korrak apparaît, détruisez-le et présentez-vous au Maître de guerre Laggrond."}}
D[7201] = {"Le dernier élément",{"Partir pour les Profondeurs de Rochenoire et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires."}}
D[7202] = {"Korrak le Ragesang",{"D'après la légende, le chef des puissants trolls Haches-d'hiver se montre quand il le décide pour semer la destruction chez les habitants de la vallée d'Alterac.","","Si Korrak apparaît, détruisez-le et présentez-vous au Lieutenant Haggerdin dans les montagnes d'Alterac."}}
D[7221] = {"Discuter avec la prospectrice Stonehewer",{"Discutez avec la Prospectrice Taillepierre à la Garnison de Dun Baldar."}}
D[7222] = {"Discuter avec Voggah Deathgrip",{"Parlez à Voggah au donjon Loup-de-givre."}}
D[7223] = {"Morceaux d'armures",{"Apportez 20 Morceaux d'armure à Murgot Forge-profonde à Dun Baldar."}}
D[7224] = {"Pris à l'ennemi",{"Apportez 20 Morceaux d'armure au forgeron Regzar au village Loup-de-givre."}}
D[7241] = {"La défense des Loups-de-givre",{"Rendez-vous dans la vallée d'Alterac, à l'intérieur des montagnes d'Alterac. Trouvez le maître de guerre Laggrond à l'extérieur du tunnel d'entrée, parlez-lui et commencez votre carrière comme soldat Loup-de-givre. Vous trouverez la vallée d'Alterac au nord de Moulin-de-Tarren à la base des montagnes d'Alterac."}}
D[7261] = {"L'impératif souverain",{"Voyagez jusqu'à la vallée d'Alterac, dans les contreforts de Hautebrande. Présentez-vous au lieutenant Haggerdin à l'extérieur du tunnel d'entrée.","","Pour la gloire de Barbe-de-bronze !"}}
D[7281] = {"Amour fraternel",{"Pénétrez en territoire Foudrepique et tuez le commandant Karl Philips. Lorsque ce sera fait, présentez-vous au commandant Louis Philips."}}
D[7282] = {"Amour fraternel",{"Pénétrez en territoire Loup-de-givre et tuez le commandant Louis Philips. Lorsque ce sera fait, présentez-vous au commandant Karl Philips."}}
D[7301] = {"Les ailes brisées",{"Enfoncez-vous en territoire Loup-de-givre à la recherche des chefs d'escadrille Slidore, Vipore et Ichman. Si vous les retrouvez, présentez-vous au commandant Duffy."}}
D[7302] = {"Les ailes brisées",{"Découvrez ce qui est arrivé aux chefs d'escadrille Guse, Jetzor et Mulverick. Lorsque vous les aurez retrouvés, présentez-vous au commandant Mulfort."}}
D[7321] = {"Bisque de tortue apaisante",{"Apporter 10 morceaux de Viande de tortue et des Epices apaisantes à Christoph Jeffcoat au Moulin-de-Tarren."}}
D[7341] = {"Un marché honnête",{"Bonjour, <race>. Je suis Kolark, <classe> de primes de Thunderbluff. J’ai beaucoup voyagé de par le monde et j’ai beaucoup vu.","","Au cours de mes voyages dans les mers du Sud, j’ai découvert ces merveilleuses flèches à pointes de thorium. Hélas, j’ai des flèches à ne plus savoir quoi en faire, mais j’ai épuisé ma provision d’obus. Aucun tauren qui se respecte ne se ferait prendre à se servir d’un arc – trop fragile. Ces flèches ne me servent à rien !","","Je vous propose un marché : vous m’apportez des obus en thorium, et je vous donne un nombre égal de flèches à pointes de thorium. Entendu ?"}}
D[7342] = {"Les flèches, c'est pour les mauviettes",{"Vous y croyez, vous ? Les gars qui ont fait le dernier chargement de munitions de Kharanos ont cochonné le boulot ! Tout ce que nous avons comme munitions, ce sont ces saletés de flèches bonnes à rien ! Qu’est-ce que je suis censé faire avec 500 000 flèches à pointes de thorium, vous pouvez me le dire ?","","Je vais vous dire. Si vous pouvez m’amener des obus en thorium, je vous file ces flèches à pointe de thorium, et tout de suite ! Entendu ?"}}
D[7361] = {"En faveur auprès des Sombrelances",{"Vous avez été <chargé/chargée> de tuer les personnages Elfes de la nuit présents dans la vallée d’Alterac.","","Tuez un Elfe de la nuit et présentez-vous à Najak Maléficas avec une Tête coupée d’Elfe de la nuit."}}
D[7362] = {"Allié des Taurens",{"Vous avez été <chargé/chargée> de tuer les personnages gnomes présents dans la vallée d’Alterac.","","Tuez un Gnome et présentez-vous à Ravak Totem-Sinistre au donjon Loup-de-givre avec une Touffe de cheveux de Gnome."}}
D[7363] = {"La condition humaine",{"Vous avez été <chargé/chargée> de tuer les personnages humains présents dans la vallée d’Alterac.","","Tuez un humain et présentez-vous au commandant Louis Philips (qui fait la navette entre le front et le donjon Loup-de-givre) avec un Bout d’os humain.","","Un remède à la condition humaine est à portée de main !"}}
D[7364] = {"Au service de Gnomeregan",{"Vous avez été <chargé/chargée> de tuer les personnages taurens présents dans la vallée d’Alterac.","","Tuez un Tauren et présentez-vous à Dirk Lembrouille à Dun Baldar avec un Sabot de Tauren."}}
D[7365] = {"Le requiem de Forteramure",{"Vous avez été <chargé/chargée> de tuer les personnages trolls présents dans la vallée d’Alterac.","","Tuez un Troll et présentez-vous à Athramanis à Dun Baldar avec un Mojo de Troll sombrelance."}}
D[7366] = {"La pitié de l'archevêque",{"Vous avez été <chargé/chargée> de tuer les personnages Réprouvés présents dans la vallée d’Alterac.","","Tuez un Réprouvé et présentez-vous au commandant Karl Philips (qui fait la navette entre le scierie et la mine) avec un Cœur de Réprouvé."}}
D[7367] = {"Désarmer les mines",{"Trouvez l'Expert en explosifs Loup-de-givre et tuez-le. Lorsque ce sera fait, présentez-vous à l'Expert en explosifs Foudrepique."}}
D[7368] = {"Désarmer les mines",{"Trouvez l'Expert en explosifs Foudrepique et tuez-le. Lorsque ce sera fait, présentez-vous à l'Expert en explosifs Loup-de-givre."}}
D[7381] = {"Le retour de Korrak",{"Si Korrak le Ragesang devait réapparaître dans le Champ sanglant, traquez-le et tuez-le.","","Apportez le Crâne de Korrak au Maître de guerre Laggrond dans les contreforts de Hautebrande."}}
D[7382] = {"Korrak l'Indestructible",{"Si Korrak le Ragesang réapparaît dans le Champ sanglant, traquez-le et tuez-le.","","Apportez le Crâne de Korrak au lieutenant Haggerdin dans les Contreforts de Hautebrande."}}
D[7383] = {"La couronne de la Terre",{"Remplir la Fiole d'améthyste et la rapporter à Corithras Ragelune à Dolanaar."}}
D[7385] = {"Quelques litres de sang",{"Vous avez la possibilité d’offrir des quantités de sang prises à l’ennemi plus importantes. Je serais content d’accepter des offrandes de quelques litres, <nom>."}}
D[7386] = {"Grappes de cristaux",{"Parfois, vous serez bloqué dans la bataille pendant des jours ou des semaines. Profitez de ces longues périodes d’activité pour ramasser des grappes de cristaux de tempête Frostwolf.","","Le Cercle accepte de telles offrandes, <nom>."}}
D[7401] = {"ON RECHERCHE : des Nains !",{"Vous avez été <chargé/chargée> de tuer les personnages nains présents dans la vallée d’Alterac.","","Tuez des Nains et arrachez-leur la colonne vertébrale. Apportez les Colonnes vertébrales de Nains au sergent Yazra Gronde-Sang au donjon Loup-de-givre."}}
D[7402] = {"On recherche : ORCS !",{"Vous avez été chargé de tuer les personnages orcs présents dans la Vallée d’Alterac.","","Tuez un orc et remettez les Dents d’orc au caporal Noreg Foudrepique à Dun Baldar."}}
D[7421] = {"La défense des Sombrelances"}
D[7422] = {"Pour une poignée de cheveux"}
D[7423] = {"Toujours plus de bouts d'os !"}
D[7424] = {"Chasse aux sabots !"}
D[7425] = {"La collection de mojos de Forteramure"}
D[7426] = {"L'amour d'un homme"}
D[7427] = {"On recherche : PLUS DE NAINS !"}
D[7428] = {"On recherche : PLUS D'ORCS !"}
D[7429] = {"Libérez Noué !",{"C’est la Clé des menottes gordok – en tous cas, c’est comme ça que l’appellent ces patapoufs. Je ne sais pas qui l’a. Ils le peuvent tous, j’imagine. Les gardes, sans doute…nnMais qu’est-ce que je raconte ? Vous l’avez déjà, n’est-ce pas ? Vous l’avez sur vous ?"}}
D[7441] = {"Pusillin et l'Ancien Azj'Tordin",{"Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d'Incantations d'Azj'Tordin.","","Si vous parvenez à le récupérer, retournez voir Azj'Tordin au Pavillon de Lariss, en Féralas."}}
D[7461] = {"Folie intérieure",{"Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d'Immol'thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol'thar se dissipera.","","Entrez dans la Prison d'Immol'thar et éradiquez l'infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l'Athenaeum.","","Lorsque vous aurez terminé, retournez voir l'Ancienne des Shen'dralar dans la cour."}}
D[7462] = {"Le trésor des Shen'dralar",{"Retournez à l'Athenaeum et trouvez le Trésor des Shen'dralar. Prenez votre récompense !"}}
D[7463] = {"Rafraîchissement arcanique",{"Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l'élémentaire de l'eau. Retournez voir le Gardien du savoir Lydros à l'Athenaeum avec l'Essence d'Hydrogénos."}}
D[7481] = {"Légendes elfiques",{"Fouillez Hache-tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les au Sage Korolusk de Camp Mojache."}}
D[7482] = {"Légendes elfiques",{"Fouillez Hache-tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les à l'Erudite Roncerune, à Pennelune."}}
D[7483] = {"Libram de Rapidité",{"Apportez un Libram de rapidité, 1 Diamant noir parfait, 2 Grands éclats brillants et 2 doses de Sang des héros au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de rapidité."}}
D[7484] = {"Libram de focalisation",{"Apportez un Libram de focalisation, 1 Diamant noir en parfait état, 4 Grands éclats brillants et 2 Peaux des ombres au Gardien du savoir Lydros à Hache-tripes pour recevoir un arcanum de focalisation."}}
D[7485] = {"Libram de Protection",{"Apportez un Libram de protection, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 1 Couture d'abomination effilochée au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de protection."}}
D[7486] = {"La récompense du héros",{"Allez chercher votre récompense dans le Coffre d'Hydraxis."}}
D[7487] = {"Harmonisation avec le Cœur du Magma",{"Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Rochenoire et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Ouvrefaille au mont Rochenoire."}}
D[7488] = {"Le filet de Lethtendris",{"Ramenez le Filet de Lethtendris à Latronicus Lancelune au bastion de Pennelune en Féralas."}}
D[7489] = {"Le filet de Lethtendris",{"Ramenez le Filet de Lethtendris à Talo Sabot-de-ronce au Camp Mojache, en Féralas."}}
D[7490] = {"Victoire pour la Horde !",{"Apportez la Tête d'Onyxia à Thrall à Orgrimmar."}}
D[7491] = {"Pour que tous voient",{"Allez voir le seigneur Runthak dans la vallée de la Force."}}
D[7492] = {"Camp Mojache",{"Parlez à Talo Sabot-de-ronce au Camp Mojache, en Féralas."}}
D[7493] = {"Le voyage commence à peine",{"Tueur de dragons et artisan du cuir expérimenté ? Vous ne cessez pas de m'émerveiller, héros. Je m'incline devant votre supériorité.","","Je vous prie d'accepter mon enseignement. Ce savoir pourrait vous rendre de grands services si vous entreprenez de détruire ce qui reste du Vol noir.","","Servez-vous des écailles de leur mère pou créer une cape. Elle vous protègera, vous et vos alliés, du souffle incendiaire du seigneur de Blackrock… Nefarian."}}
D[7494] = {"Le bastion de Pennelune",{"Parlez à Latronicus Lancelune au bastion de Pennelune en Féralas."}}
D[7495] = {"Victoire pour l'Alliance !",{"Apportez la Tête d'Onyxia au généralissime Bolvar Fordragon à Hurlevent."}}
D[7496] = {"Célébrer le triomphe",{"Allez voir le major Mattingly dans la vallée des Héros."}}
D[7497] = {"Le voyage commence à peine",{"Tueur de dragons et artisan du cuir expérimenté ? Vous ne cessez pas de m'émerveiller, héros. Je m'incline devant votre supériorité.","","Je vous prie d'accepter mon enseignement. Ce savoir pourrait vous rendre de grands services si vous entreprenez de détruire ce qui reste du Vol noir.","","Servez-vous des écailles de leur mère pour créer une cape. Elle vous protègera, vous et vos alliés, du souffle incendiaire du seigneur de Blackrock… Nefarian."}}
D[7498] = {"Garona : une étude en discrétion et en trahison",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7499] = {"Le codex de défense",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7500] = {"Les recettes de l'arcaniste",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7501] = {"La lumière et comment l'altérer",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7502] = {"Contrôler les ombres",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7503] = {"La plus grande race de chasseurs",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7504] = {"Sainte Bolognaise : Ce que la lumière ne vous dit pas",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7505] = {"Le Horion de givre et vous",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7506] = {"Le Rêve d'Emeraude…",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7507] = {"Le guide de Dagharn",{"Rendez \"Le guide de Dagharn du tueur de dragons\" à l'Athenaeum."}}
D[7508] = {"Forger Quel'Serrar",{"Donnez la Lame elfique inachevée au Gardien du savoir Lydros."}}
D[7509] = {"Forger Quel'Serrar",{"Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important.","","Avant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre.","","Si vous y parvenez, Quel'Serrar sera à vous."}}
D[7521] = {"Tonneraan le Cherchevent",{"Pour libérer Tonneraan le Cherchevent de sa prison, vous devez présenter au généralissime Demitrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d'élémentium, et l'Essence du seigneur du Feu."}}
D[7522] = {"Examiner le Calice",{"Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian."}}
D[7541] = {"Un service pour la Horde",{"Il faudra du temps pour que nos savants étudient le pendentif que vous nous avez rapporté. J'aimerais vous offrir un petit témoignage de notre reconnaissance, pour le service que vous avez rendu à la Horde.","","Merci, <nom>. Vos actions vous font honneur."}}
D[7562] = {"Mor'zul Porte-sang",{"Parler à Mor'zul Porte-sang dans les Steppes ardentes."}}
D[7563] = {"Rage de sang",{"Apporter 30 bouteilles de Sang de bêtes déchaînées à Mor'zul Porte-sang dans les Steppes ardentes."}}
D[7564] = {"Gorzeeki Wildeyes",{"Apporter la Caisse de sang à Gorzeeki Fouregard dans les Steppes ardentes."}}
D[7581] = {"Les ancrages de la prison",{"Rendez-vous à Hache-tripes en Féralas et récupérez 15 doses de Sang de satyre sur les satyres Follengeance qui habitent le quartier de Crochebois. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure."}}
D[7582] = {"Les parois de la prison",{"Rendez-vous à la gorge du Sombre murmure, au Berceau-de-l'Hiver, et récupérez 5 Larmes de l'Hederine sur les démons Hederine qui occupent la gorge. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure."}}
D[7583] = {"Suppression",{"Pénétrez dans la Balafre impure et localisez un Commandant de la garde funeste.","","Servez-vous de la Prison de cristal luminescente sur lui. Attendez-vous à être sauvagement <attaqué/attaquée>, car le démon fera l'impossible pour éviter d'être capturé.","","Si vous réussissez, amenez le garde funeste emprisonné à Daio à la Balafre impure."}}
D[7601] = {"Les Commandements de Niby",{"Parlez à Démonet à Gangrebois."}}
D[7602] = {"La gangressence parfaite",{"Démonet vous a demandé de lui apporter trois Gangressences parfaites, venant de trois régions distinctes.","","Les satyres Legashi d'Azshara, les légionnaires de Jaedenar et les gangregardes sentinelles des Terres foudroyées détiennent la Gangressence parfaite de leur région.","","Récupérez les Gangressences parfaites et rapportez-les à Démonet, à Gangrebois."}}
D[7603] = {"Le noyau infernal de Kroshius",{"Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l'Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre.","","Rapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois."}}
D[7604] = {"Un contrat contraignant",{"Apportez le Contrat de la Confrérie du Thorium à Lokhtos Sombrescompte, si vous voulez recevoir les plans du marteau de sulfuron."}}
D[7621] = {"Un avertissement",{"<classe> vous allez subir une série d’épreuves au cours desquelles tous vos talents seront poussés à leurs limites.","","Écoutez attentivement mon histoire.","","Attention, vous devrez achever cette tâche seul. Je conseille à vos alliés de rester à distance. Toute intervention extérieure entraînera un châtiment sévère.","","Le Destin vous a conduit ici, vous et vous seul. Battez-vous avec honneur. Que la Lumière vous protège !"}}
D[7622] = {"L’équilibre de la Lumière et de l’Ombre",{"Sauvez 50 Paysans avant que 15 d'entre eux aient été tués. Si vous y parvenez, allez parler à Eris Havrefeu.","","Consultez le Panneau des morts pour voir combien de paysans ont été tués."}}
D[7623] = {"Le seigneur Creuseplaie",{"Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes.","","Servez-vous-en pour vous rendre à Jaedenar, et parlez au seigneur Creuseplaie."}}
D[7624] = {"Ulathek le traître",{"Affrontez Ulathek, puis apportez le Cœur du traître au seigneur Creuseplaie à Jaedenar."}}
D[7625] = {"Poussière d'étoile xorothienne",{"Acheter de la Poussière d'étoile xorothienne à Ur'dan. L'apporter à Gorzeeki Fouregard dans les Steppes ardentes."}}
D[7626] = {"La Cloche de Dethmoora",{"Apportez 2 Elixirs de puissance de l'ombre à Gorzeeki Fouregard dans les Steppes ardentes."}}
D[7627] = {"La Roue de la Marche noire",{"Apportez 6 Grands éclats brillants et 25 charges de Minerai de sombrefer à Gorzeeki dans les Steppes ardentes."}}
D[7628] = {"La Chandelle de l'apocalypse",{"Apportez 3 Ecailles de dragon noir à Gorzeeki Fouregard dans les Steppes ardentes."}}
D[7629] = {"Livraison de diablotin",{"Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, rapportez la bouteille à Gorzeeki Fouregard."}}
D[7630] = {"L'arcanite",{"Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes."}}
D[7631] = {"Le destrier de l'effroi de Xoroth",{"Lisez les Instructions de Mor'zul. Invoquez un Destrier de l'effroi xorothien, vainquez-le, et liez son esprit."}}
D[7632] = {"La feuille ancienne",{"Trouvez le propriétaire de la Feuille ancienne pétrifiée. Bonne chance, <nom>, le monde est vaste."}}
D[7633] = {"Une rencontre",{"Votre dilligence et votre intégrité ont été notées, <classe>.","","Nous sommes les Anciens, les protecteurs de cette forêt qui fut grande, autrefois. Nos formes physiques ont été détruites il y a dix mille ans lorsqu’Archimonde et la Légion ardente ont marché sur le mont Hyjal. Malgré tout, nos esprits demeurent intacts.","","Nous avons des tâches à vous proposer. Des tâches qui vous donneront accès à nos secrets, si vous les accomplissez.","","Si vous y parvenez, revenez à ce rocher et nous répondrons à votre appel."}}
D[7634] = {"Feuille d'Ancien cousue de tendons",{"L'Ancien Hastat vous demande de lui ramener un Tendon de dragon bleu adulte. Si vous en trouvez un, ramenez-le-lui à Gangrebois."}}
D[7635] = {"La bonne corde",{"L'Ancien Stoma vous demande de lui ramener un Tendon de dragon noir adulte. Si vous en trouvez un, ramenez-le à Stoma à Gangrebois."}}
D[7636] = {"Le bâton des Anciens",{"Vous devez trouver et tuer quatre corrupteurs démoniaques :","","Simona la Séductrice.","","Klinfran l'Enragé.","","Solenor le Tueur.","","Artorius le Néfaste.","","Détruisez ces créatures et retournez voir l'Ancien Vartus à Gangrebois.","","Vous trouverez des indices sur leurs faits et gestes sur l'Ecorce pétrifiée qui se trouve dans votre inventaire.","","Vous DEVEZ agir seul."}}
D[7637] = {"L'accent sur le sacrifice",{"Rendez-vous à Forgefer et procurez-vous l'Encensoir d'exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d'or."}}
D[7638] = {"Le seigneur Grayson Shadowbreaker",{"Parler au seigneur Grayson Brisombre dans le Quartier de la cathédrale de Hurlevent."}}
D[7639] = {"Des preuves de jugement",{"Ramener l'Encensoir d'exorcisme au seigneur Grayson Brisombre, dans le Quartier de cathédrale de Hurlevent."}}
D[7640] = {"Exorciser Val-Terreur",{"Servez-vous de l'Encensoir d'exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Brisombre dans le Quartier de la cathédrale de Hurlevent."}}
D[7641] = {"L'œuvre de Grimand Elmore",{"Parlez à Grimand Elmore dans le Quartier des nains de Hurlevent."}}
D[7642] = {"Une ribambelle d'objets",{"Apporter 40 Etoffes runiques, 6 Barres d'arcanite, 10 Larmes d'Arthas, 5 Fioles d'eau sacrée de Stratholme, et 150 pièces d'or à Grimand Elmore, au Quartier des nains de Hurlevent."}}
D[7643] = {"L'ancien esprit équin",{"Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Austrivage, sache en fabriquer.","","Ensuite, rendez-vous au donjon de Hache-tripes en Féralas, et tuez Tendris Crochebois. Sa mort libérera l'Ancien esprit équin. Nourrissez-le avec l'aliment spécial afin de l'apaiser. Enfin, donnez-lui le Caparaçon d'arcanite pour qu'il le bénisse."}}
D[7644] = {"Le caparaçon en arcanite béni",{"Retourner dans le quartier de la cathédrale de Hurlevent avec le Caparaçon en arcanite béni pour voir le seigneur Grayson Brisombre."}}
D[7645] = {"Fourrage enrichi en manne",{"Récupérer 20 Biscuits de manne enrichis, l'ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson de Southore dans les contreforts de Hautebrande. L'Aube d'argent est la seule à fabriquer ces biscuits.","","Vous devrez également lui donner 50 pièces d'or pour apaiser sa susceptibilité."}}
D[7646] = {"Le Clairvoyant",{"Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind."}}
D[7647] = {"Jugement et rédemption",{"Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu'ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l'âme du destrier déchu.","","Ensuite, donnez l'Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre."}}
D[7648] = {"Le chef d'œuvre de Grimand",{"Présentez le Caparaçon d'arcanite au seigneur Grayson Brisombre dans le Quartier de la cathédrale de Hurlevent, pour inspection."}}
D[7649] = {"Les plates en thorium enchanté - Volume I",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7650] = {"Les plates en thorium enchanté - Volume II",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7651] = {"Les plates en thorium enchanté - Volume III",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7652] = {"Une affaire en thorium",{"Voilà, messire, j’ai une superbe affaire à vous proposer.","","Je veux me débarrasser d’un certain nombre de plans pour des pièces d’armure impériales en plaques. Je cherche quelqu’un qui voudrait les prendre. En échange, tout ce qu’il me faut, ce sont quelques barres de thorium. Cela vous tente ?"}}
D[7653] = {"La ceinture impériale en plaques",{"Les plans de la ceinture vont vous coûter 20 barres de thorium."}}
D[7654] = {"Les bottes impériales en plaques",{"Pour le plan des bottes, mon prix est de 40 barres de thorium. Ouais, 40. Vous n’allez pas pleurer, quand même ? Vous voulez un mouchoir ?","","<Derotain ricane.>"}}
D[7655] = {"Les bracelets impériaux en plaques",{"Pour les plans des bracelets, il me faudra 20 Barres de thorium..","","Vous vous sentez bien, mon gars? Vous êtes tout rouge."}}
D[7656] = {"La pansière impériale",{"Pour les plans de la pansière, il va me falloir 60 barres de thorium.","","Oh bon, c’est reparti. Vous allez courir voir vos vieux dieux bleus et leur demander pourquoi ils vous ont rejeté ? Allez, haut les cœurs ! Personne n’a dit que la vie était juste !"}}
D[7657] = {"Le heaume impérial en plaques",{"Vous n'avez qu'à aligner 50 barres de thorium et les plans du heaume sont à vous."}}
D[7658] = {"Les jambières impériales en plaques",{"Pour les plans des protège-pattes, c’est 60 barres de thorium.","","Oui, je sais, c’est horrible, je vous ruine et tout et tout. On me l’a déjà faite, alors gardez vos histoires pour vous, d’accord ?"}}
D[7659] = {"Les épaulières impériales en plaques",{"Pour le plan des épaulières, ça ira chercher dans les 20 barres de thorium."}}
D[7660] = {"Echange de loup arctique"}
D[7661] = {"Echange de loup - Loup rouge"}
D[7662] = {"Un nouveau kodo bleu"}
D[7663] = {"Un nouveau kodo vert"}
D[7664] = {"Remplacement de raptor ivoire"}
D[7665] = {"Remplacement de raptor rouge"}
D[7666] = {"Retour au Grand ossuaire"}
D[7667] = {"Assistance matérielle",{"Si vous voulez aider Sagorne Rôdeur-des-crêtes de la vallée de la Sagesse d'Orgrimmar, apportez-lui un Diamant d'Azeroth et un Diamant noir en parfait état."}}
D[7668] = {"La menace de Ravassombre",{"Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.","","Ramenez la Tête de Ravassombre à Sagorne Rôdeur-des-crêtes de la vallée de la Sagesse, à Orgrimmar."}}
D[7669] = {"Retour au Grand ossuaire"}
D[7670] = {"Le seigneur Grayson Brisombre",{"Parler au seigneur Grayson Brisombre dans le Quartier de la cathédrale de Hurlevent."}}
D[7671] = {"Un nouveau sabre-de-givre"}
D[7672] = {"Remplacement de sabre-de-nuit"}
D[7673] = {"Echange de bélier de givre"}
D[7674] = {"Echange de bélier noir"}
D[7675] = {"Remplacement de mécanotrotteur bleu clair"}
D[7676] = {"Remplacement de mécanotrotteur blanc"}
D[7677] = {"Echange d'étalon blanc"}
D[7678] = {"Echange de palomino"}
D[7681] = {"Hunter test quest",{"Nourrissez votre familier, puis parlez à votre donneur de quête."}}
D[7682] = {"Hunter test quest2",{"Nourrissez votre familier, puis parlez à votre donneur de quête."}}
D[7701] = {"ON RECHERCHE : Surveillant Maltorius",{"Loin dans les profondeurs de la Fosse aux scories dans le Chaudron, dans la Gorge des Vents brûlants, vous trouverez le nain traître du clan Sombrefer répondant au nom de surveillant Maltorius.","","Tuez le surveillant Maltorius et prenez sa tête. Apportez-la au capitaine de guet Lolo Heurteloin dans la Gorge des Vents brûlants pour la récompense."}}
D[7703] = {"Affaires inachevées chez les Gordok",{"Trouvez le Gantelet de puissance gordok et rendez-le au Capitaine Kromcrush à Hache-tripes.","","Selon Kromcrush, les histoires des « vieux » racontent que Tortheldrin - un « vilain » elfe qui se fait appeler prince - l'a volé à l'un des rois gordok."}}
D[7721] = {"Du carburant pour la zappette",{"Récupérez 10 Noyaux élémentaires d'eau sur les Elémentaires marins et les Embruns le long de la Côte oubliée de Féralas, et rapportez-les à Zorbin Poudrozieu, près du quai là-bas."}}
D[7722] = {"Le Flux embrasé",{"Quelque part dans la Fosse aux scories du Chaudron, vous trouverez les Plans secrets : Flux embrasé dérobés par le surveillant Maltorius. Trouvez ces plans et rapportez-les au Maître forgeron Brûlotin dans la gorge des Vents brûlants."}}
D[7723] = {"Maudits gros doigts",{"Hansel Lourdemains veut que vous tuiez 20 Golems de guerre lourds.","","Les golems de guerre lourds errent dans les régions qui entourent le Chaudron dans la Gorge des Vents brûlants. Quand vous en aurez tué assez, revenez voir Hansel dans la Gorge des Vents brûlants."}}
D[7724] = {"Une menace incandescente",{"Hansel Lourdemains veut que vous tuiez 20 Grandes araignées de lave dans la gorge des Vents brûlants. Vous pouvez trouver les Grandes araignées de lave dans les plateaux et les mares de lave de la gorge des Vents brûlants.","","Revenez voir Hansel dans la gorge des Vents brûlants quand vous aurez tué assez de Grandes araignées de lave."}}
D[7725] = {"Le retour des géants rétrécis",{"Utilisez l'Ultra-réducteur de Zorbin sur des géants de n'importe quel type en Féralas afin les rendre plus faciles à gérer. Apportez 10 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Poudrozieu aux docks de la Côte oubliée en Féralas."}}
D[7726] = {"Encore du carburant pour la zappette",{"Récupérez 6 Noyaux élémentaires d'eau sur les Elémentaires marins et les Embruns le long de la Côte oubliée de Féralas, et rapportez-les à Zorbin Poudrozieu, près du quai."}}
D[7727] = {"Incendosaures ? N'importosaures, plutôt",{"Hansel Lourdemains veut que vous tuiez 20 Incendosaures.","","On peut les trouver dans les bassins de lave de la Fosse aux scories, qui occupe une partie du Chaudron de la gorge des Vents brûlants.","","Retournez voir Hansel Lourdemains dans la gorge des Vents brûlants lorsque vous aurez tué suffisamment d'Incendosaures."}}
D[7728] = {"OBJETS VOLES : Tuyère et longue-vue",{"Trouvez la Tuyère de forge et la Longue-vue du guetteur et rapportez-les au sous-chef Scrange dans la gorge des Vents brûlants.","","Les seules informations dont vous disposez sur ces objets sont les suivantes : ils ont été dérobés par les nains Sombrefer, la Tuyère de forge est un outil utilisé par les forgerons et la Longue-vue du guetteur est un outil de surveillance inestimable pour les guetteurs."}}
D[7729] = {"OFFRE D'EMPLOI : Réduire la concurrence",{"Tuez 15 Sous-chefs Sombrefer et 15 Esclavagistes Sombrefer. Revenez voir le sous-chef Scrange dans la gorge des Vents brûlants quand vous aurez accompli cette tâche."}}
D[7730] = {"Infestation de Zukk'ash",{"Rapportez 20 Carapaces de Zukk'ash à Hadoken Rôdeur-agile au Camp Mojache en Féralas."}}
D[7731] = {"Fouet-cuisant",{"Battez Fouet-cuisant dans le Gouffre grouillant et rapportez ses glandes à Hadoken Swiftstrider au Camp Mojache en Feralas."}}
D[7732] = {"Le rapport sur les Zukk'ash",{"Apportez le rapport sur les Zukk'ash du Camp Mojache à Zilzibin Kongadok. Il réside à la Herse d'Orgrimmar."}}
D[7733] = {"Qualité améliorée",{"Fournir 10 Peaux de yéti Griffe Féroce à Pratt McGrubben au bastion de Pennelune, en Féralas."}}
D[7734] = {"Qualité améliorée",{"Fournir 10 Peaux de yéti Griffe Féroce à Jangdor Rôdeur-agile au Camp Mojache, en Féralas."}}
D[7735] = {"Une peau de yéti en parfait état",{"Apporter la Peau de yéti en parfait état à Pratt McGrubben au bastion de Pennelune, en Féralas."}}
D[7736] = {"Réapprovisionnement en flux embrasé (Sang-royal)",{"Assez perdu de temps à bavarder, <race>. Il est temps de nous concentrer sur le réapprovisionnement de nos réserves de flux embrasé qui s'amenuisent.","","Voici ce que je veux que vous me rapportiez :","","*Ecailles d'incendosaure.","","*Sang-royal.","","*Charbon.","","Je prendrai tout ce que vous me donnerez !","","Et vous le ferez vite si vous voulez bien vous entendre avec la Confrérie."}}
D[7737] = {"Se faire accepter",{"Vous avez monté les barreaux de l'échelle de la Confrérie, <race>. Nous commençons à avoir de vous une opinion favorable. Voilà un bel exploit !","","Si vous souhaitez gagner davantage encore de notre respect, écoutez bien.","","Nous pouvons raffiner le flux embrasé en ajoutant simplement un résidu de sombre fer au mélange. On peut trouver les résidus de sombre fer dans les Profondeurs de Blackrock.","","Apportez-moi tous les résidus de sombre fer que vous trouverez !"}}
D[7738] = {"Une peau de yéti parfaite",{"Apporter la Peau de yéti parfaite à Jangdor Rôdeur-agile au Camp Mojache, en Féralas."}}
D[7741] = {"Praise from the Emerald Circle <NYI> <TXT>"}
D[7761] = {"Les ordres de Main-noire",{"Cet orc est stupide. Il semble que vous deviez trouver un moyen d'obtenir la Marque de Drakkisath pour accéder à l'Orbe de commandement.","","D'après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter."}}
D[7781] = {"Le seigneur de Rochenoire",{"Apporter la Tête de Nefarian au généralissime Bolvar Fordragon à Hurlevent."}}
D[7782] = {"Le seigneur de Rochenoire",{"Allez à la vallée des Héros de Hurlevent et parlez au grand maréchal Afrasiabi."}}
D[7783] = {"Le seigneur de Rochenoire",{"Apportez la Tête de Nefarian à Thrall à Orgrimmar."}}
D[7784] = {"Le seigneur de Blackrock",{"Parlez au Haut seigneur Saurcroc à Orgrimmar. Il vous attend dans la vallée de la Force."}}
D[7785] = {"Examiner le Calice",{"Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian."}}
D[7786] = {"Tonneraan le Cherchevent",{"Pour libérer Tonneraan le Cherchevent de sa prison, vous devez présenter au généralissime Demitrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d'élémentium, et l'Essence du Seigneur du feu."}}
D[7787] = {"Éveille-toi, Lame-tonnerre !",{"Présenter la Lame du baiser du vent dormante au généralissime Demitrian."}}
D[7788] = {"Triomphez des envahisseurs !",{"Entrez dans le goulet des Chanteguerres, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Chanteguerres. Puis revenez voir la sentinelle Chanteloin au bosquet d'Aile-argent."}}
D[7789] = {"Écrasez les usurpateurs d'Aile-argent",{"Entrez dans le goulet des Warsong, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Warsong. Puis revenez voir le capitaine Shatterskull au campement de Mor'shan."}}
D[7791] = {"Un don de laine"}
D[7792] = {"Un don de laine"}
D[7793] = {"Un don de soie"}
D[7794] = {"Un don de tisse-mage"}
D[7795] = {"Un don d'étoffe runique",{"<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?","","Si vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons."}}
D[7796] = {"Encore de l'étoffe runique",{"Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Stormwind soient reconnus à leur juste valeur.","","Lorsque vous serez prête à me les remettre, je les accepterai volontiers."}}
