D[7823] = {"Un don d'étoffe runique",{"<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?","","Si vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons."}}
D[7824] = {"Un don d'étoffe runique",{"<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?","","Si vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons."}}
D[7825] = {"Encore de l'étoffe runique",{"Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur de Thunder Bluff soient reconnus à leur juste valeur.","","Lorsque vous serez prêt à me les remettre, je les accepterai volontiers."}}
D[7826] = {"Un don de laine"}
D[7827] = {"Un don de soie"}
D[7828] = {"Traquer les traqueurs",{"Le veneur Markhor du village des Vengebroches, dans les Hinterlands, veut que vous tuiez 10 Traqueurs Crins-d'argent et 10 Hurleurs Crins-d'argent. Retournez le voir lorsque vous aurez terminé.","","D'après Markhor, les loups se cachent dans les régions sauvages des Hinterlands."}}
D[7829] = {"Chasser les sauvages",{"Le veneur Markhor du village des Vengebroches des Hinterlands veut que vous tuiez 20 Chouettards sauvages. Retournez le voir lorsque vous aurez terminé.","","Markhor a mentionné que les Chouettards sauvages vivaient dans les régions sauvages des Hinterlands."}}
D[7830] = {"Venger les victimes",{"Le veneur Markhor, du village des Vengebroches des Hinterlands, veut que vous tuiez un Seigneur du ciel Bec-rasoir et que vous récupériez une Plume de Seigneur du ciel. Revenez le voir lorsque vous aurez terminé votre tâche.","","D'après Markhor, les Seigneurs du ciel Bec-rasoir sont des créatures rares qui vivent dans les régions sauvages des Hinterlands."}}
D[7831] = {"Un don de tisse-mage"}
D[7832] = {"Encore de l'étoffe runique",{"Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur d’Orgrimmar soient reconnus à leur juste valeur.","","Lorsque vous serez prêt à me les remettre, je les accepterai volontiers."}}
D[7833] = {"Un don de laine"}
D[7834] = {"Un don de soie"}
D[7835] = {"Un don de tisse-mage"}
D[7836] = {"Un don d'étoffe runique",{"<nom>, vous avez déjà beaucoup contribué à notre recherche d’étoffe. Nous travaillons d’arrache-pied à reconstituer nos réserves, cependant nous manquons encore cruellement d'un type de tissu : l'étoffe runique. Nous en avons désespérément besoin. Pourriez-vous nous aider, comme vous nous avez aidés dans le passé ?","","Si vous acceptez, apportez-moi toute l'étoffe runique dont vous pouvez vous séparer. Nous accepterons un don initial de soixante unités, et ensuite, nous aviserons."}}
D[7837] = {"Encore de l'étoffe runique",{"Je vous salue une nouvelle fois, <nom> ! Nous avons sans cesse besoin d'étoffe runique, et si vous voulez vous séparer de quelques morceaux supplémentaires, nous en aurons l’usage. Si vous nous donnez 20 nouvelles étoffes runiques, je veillerai à ce que vos efforts en faveur des trolls Darkspear soient reconnus à leur juste valeur.","","Lorsque vous serez prêt à me les remettre, je les accepterai volontiers."}}
D[7838] = {"Grand maître de l'arène"}
D[7839] = {"Les voyous Vilebranche",{"Le forgeron Boiscorie du village des Vengebroches, dans les Hinterlands, vous demande de retrouver les Outils perdus de Boiscorie. Retournez le voir lorsque vous les aurez.","","Il a laissé entendre qu'ils pourraient se trouver dans l'un des temples des Vilebranches, au nord-est des Hinterlands. Vous devriez aussi jeter un coup d'œil au rocher de l'Affût."}}
D[7840] = {"Lard a perdu son déjeuner !",{"Lard, du village des Vengebroches, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait.","","D'après Lard, il l'aurait laissé dans l'île, au nord. Prenez garde aux trolls Vilebranche !"}}
D[7841] = {"Un message pour les Marteaux-hardis",{"Otho Moji'ko du village des Vengebroches dans les Hinterlands veut que vous massacriez 15 Estafettes du Haut-val, 15 Eclaireurs du Haut-val, 15 Tireurs d'élite du Haut-val et 15 Forestiers du Haut-val. Revenez le voir lorsque vous aurez terminé.","","Vous pouvez trouver les elfes du Haut-val au Gîte de Quel'Danil, au nord-ouest des Hinterlands."}}
D[7842] = {"Encore un message pour les Marteaux-hardis",{"Otho Moji'ko, du village des Vengebroches dans les Hinterlands, vous demande de lui ramener 10 Longues plumes élégantes prélevées sur les griffons qui vivent dans les Hinterlands. Retournez le voir lorsque vous les aurez.","","On trouve des griffons dans tous les Hinterlands."}}
D[7843] = {"Le message final pour les Wildhammer",{"Otho Moji'ko, du village des Vengebroches dans les Hinterlands, vous demande de vous rendre au Nid-de-l'Aigle, à l'ouest des Hinterlands. Vous devez placer le Message final pour les Marteaux-hardis près du puits, au cœur de la ville. Retournez le voir lorsque vous aurez accompli votre tâche.","","Faites attention aux nains Marteaux-hardis, qui risquent de mal le prendre, et aux autres membres de l'Alliance."}}
D[7844] = {"Les cousins cannibales",{"Yayo'jin la Mystique, du village des Vengebroches des Hinterlands, veut que tuiez 15 Scalpeurs Vilebranche et 10 Devins Vilebranche. Retournez la voir lorsque vous aurez terminé.","","D'après Yayo'jin, ces trolls se trouvent près des temples de Shaol'watha et d'Agol'watha, au nord-nord-est des Hinterlands."}}
D[7845] = {"L'ancien Brocherompue a été enlevé !",{"L'Aînée Brocherompue du village des Vengebroches des Hinterlands vous demande de libérer son compagnon, l'Ancien Brocherompue, de Jintha'alor.","","Vous savez qu'il est prisonnier au sommet de Jintha'alor, la capitale des Vilebranches, qui se trouve au sud des Hinterlands."}}
D[7846] = {"Récupérez la clé !",{"L'Ancien Brocherompue, à Jintha'alor, veut que vous tuiez Hitah'ya la Gardienne afin de récupérer la Clé des menottes qui le retiennent. Lorsque vous aurez cette clé, retournez voir l'Ancien Brocherompue."}}
D[7847] = {"Retourner voir l’Aînée Torntusk",{"L'Ancien Brocherompue, à Jintha'alor, veut que vous retourniez voir l'Aînée Brocherompue du village des Vengebroches et que vous lui appreniez qu'il est sauvé."}}
D[7848] = {"Harmonisation avec le Cœur du Magma",{"Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Rochenoire et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Ouvrefaille au mont Rochenoire."}}
D[7849] = {"L'angoisse de la séparation",{"Le veneur Markhor du village des Vengebroches, dans les Hinterlands, veut que vous récupériez les restes de son frère jumeau. Trouvez le Crâne du veneur Malkhor et les Os du veneur Malkhor, et ramenez-les au veneur Markhor.","","Markhor vous a dit que les restes de son frère avaient été abandonnés aux limons et aux loups des Vilebranches. Il a également mentionné l'existence d'une décharge remplie de limons à Jintha'alor, ainsi que celle d'un enclos à loups. Tous deux se trouvent près du sommet du temple."}}
D[7850] = {"Les calices ténébreux",{"L'Aînée Brocherompue du village des Vengebroches, dans les Hinterlands, veut que vous récupériez 10 Calices de sang corrompu à Jintha'alor. Retournez voir l'Aînée Brocherompue lorsque vous aurez terminé."}}
D[7861] = {"On recherche : la vile prêtresse Maléficia et ses sbires",{"Vous avez reçu l'ordre de tuer la vile prêtresse Maléficia et 10 Gardes Aman'zasi Vilebranches. Lorsque vous aurez terminé, allez voir l'Aînée Brocherompue au village des Vengebroches, dans les Hinterlands.","","La vile prêtresse Maléficia et la garde Aman'zasi ont leurs quartiers au sommet de Jintha'alor, dans les Hinterlands."}}
D[7862] = {"Offre d'emploi : capitaine de la garde du village des Vengebroches",{"Vous avez été <chargé/chargée> de liquider 10 Berserkers Vilebranche, 5 Chasseurs des ombres Vilebranche, 5 Sanguinaires Vilebranche et 5 Mangeurs d'âmes Vilebranche.","","Lorsque vous aurez terminé, allez parler à l'Aînée Brocherompue, du village des Vengebroches dans les Hinterlands."}}
D[7863] = {"Paquetage de base de Sentinelle"}
D[7864] = {"Paquetage ordinaire de Sentinelle"}
D[7865] = {"Paquetage amélioré de Sentinelle",{"Vous avez commencé à faire vos preuves à nos yeux, <nom>. En récompense, prenez ce paquetage ! Vous y trouverez des rations et des bandages, dont vous ne pourrez vous servir que dans le goulet des Warsong.","","Si vous restez dans le goulet, vous finirez par avoir la possibilité d’acheter ces objets. Les rations vous seront proposées lorsque nous serons Amicaux à votre égard, et les bandages lorsque vous serez Honoré."}}
D[7866] = {"Paquetage de base de Voltigeur"}
D[7867] = {"Paquetage ordinaire de Voltigeur"}
D[7868] = {"Paquetage amélioré de Voltigeur"}
D[7871] = {"Triomphez des envahisseurs !",{"Entrez dans le goulet des Chanteguerres, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Chanteguerres. Puis revenez voir la sentinelle Chanteloin au bosquet d'Aile-argent."}}
D[7872] = {"Triomphez des envahisseurs !",{"Entrez dans le goulet des Chanteguerres, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Chanteguerres. Puis revenez voir la sentinelle Chanteloin au bosquet d'Aile-argent."}}
D[7873] = {"Triomphez des envahisseurs !",{"Entrez dans le goulet des Chanteguerres, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Chanteguerres. Puis revenez voir la sentinelle Chanteloin au bosquet d'Aile-argent."}}
D[7874] = {"Écrasez les usurpateurs d'Aile-argent",{"Entrez dans le goulet des Chanteguerres, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Chanteguerres. Puis revenez voir le capitaine Fracasse-crâne au campement de Mor'shan."}}
D[7875] = {"Écrasez les usurpateurs d'Aile-argent",{"Entrez dans le goulet des Chanteguerres, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Chanteguerres. Puis revenez voir le capitaine Fracasse-crâne au campement de Mor'shan."}}
D[7876] = {"Écrasez les usurpateurs d'Aile-argent",{"Entrez dans le goulet des Chanteguerres, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Chanteguerres. Puis revenez voir le capitaine Fracasse-crâne au campement de Mor'shan."}}
D[7877] = {"Le trésor des Shen'dralar",{"Retournez à l'Athenaeum et trouvez le Trésor des Shen'dralar. Prenez votre récompense !"}}
D[7881] = {"Des bottes pour les forains",{"Nous autres forains de la foire de Sombrelune marchons beaucoup. Nous marchons d'un site à l'autre... en fait, vous ne nous verrez jamais assis ! Pas étonnant que nous usions autant de bottes ! Nous avons besoin de bottes qui soient à la fois robustes et élégantes, et les bottes en cuir estampé correspondent bien à cette description.","","Vous ! Vous êtes un artisan du cuir : faites-moi des bottes en cuir estampé et je vous donnerai un bon de la foire de Sombrelune pour votre peine."}}
D[7882] = {"Des tuniques pour les forains"}
D[7883] = {"Le gnome le plus grand du monde !"}
D[7884] = {"L'enfant crocilisque et le murloc barbu"}
D[7885] = {"Renforts d'armure",{"Vous ne le savez peut-être pas, mais faire fonctionner une foire ambulante est très coûteux ! Tout s'use si vite que c'est un miracle si nous faisons des bénéfices.","","En raison de tous ces coûts cachés, nous sommes toujours à la recherche de moyens d'entretenir notre matériel à moindres frais. Nos tentes, par exemple, se déchirent souvent, mais les renforts d'armure en cuir sont parfaits pour les raccommoder. Pouvez-vous m'apporter des renforts d'armure ? Cela nous ferait faire de sacrées économies ! Si vous pouvez faire ça pour moi, je vous donnerai une poignée de bons de la foire de Sombrelune..."}}
D[7886] = {"Talismans de vaillance"}
D[7887] = {"Talismans de vaillance"}
D[7888] = {"Talismans de vaillance"}
D[7889] = {"La pierre de lest grossière",{"Être la femme la plus forte du monde demande beaucoup de travail ! Mon ensemble de poids commence à être trop léger et pour rester en forme il m'en faut plus !","","Croyez-vous que vous pourriez me procurer des cailloux ? Si oui, je vous donnerai un bon de la foire de Sombrelune."}}
D[7890] = {"Silex à aiguiser lourd",{"Pour mon entraînement, j'aime fixer un bâton entre des silex à aiguiser lourds puis soulever le bâton au-dessus de ma tête. Ce n'est pas facile, mais on ne devient pas la femme la plus forte du monde en restant assise !","","Pouvez-vous m'aider ? Il me faut plus de silex à aiguiser, apportez-m'en et je vous donnerai des bons de la foire de Sombrelune."}}
D[7891] = {"Brassards en fer émeraude",{"Je travaille à un nouveau costume pour quand j'aurai mon propre stand de femme la plus forte du monde ! En ce moment, je cherche des bracelets. Ils ne doivent pas être trop grands parce que les gens veulent voir mes muscles, mais je veux quand même qu'il y ait de la couleur, vous comprenez ?","","Pourquoi pas des bracelets en fer émeraude, <nom> ? Pouvez-vous me faire des bracelets en fer émeraude ? Si oui, j'aurai un beau paquet de bons de la foire de Sombrelune pour vous."}}
D[7892] = {"Grande masse noire",{"Pour mon numéro de femme la plus forte du monde, j'ai prévu de demander des objets au public et de les écraser avec une grande masse noire !","","Pouvez-vous me faire une grande masse noire, <nom> ?"}}
D[7893] = {"Rituels de force",{"<nom>, dans ma quête pour devenir la femme la plus forte du monde, j'ai parcouru le monde et appris les secrets de musculation de lointains maîtres des poids, de gourous de la force et de manuels anciens. Je connais maintenant des exercices interdits qui tueraient les faibles et estropieraient les non-initiés !","","Ces prouesses de force et de conditionnement requièrent un entraînement à l'aide des pierres à aiguiser les plus denses. <nom>, pouvez-vous trouver ou fabriquer ces pierres et me les apporter ? Je vous donnerai des bons en échange…"}}
D[7894] = {"Modulateurs en cuivre",{"Yebb travaille à une nouvelle attraction pour l'Etonnante Ménagerie qui stupéfiera et ravira les visiteurs ! Mais cela demandera beaucoup de travail et beaucoup de matériel...","","Y compris des Modulateurs de cuivre. Il nous faut beaucoup de modulateurs pour les parties mécaniques de l'attraction. Apportez-moi des Modulateurs de cuivre et je vous donnerai un bon de la foire de Sombrelune en échange."}}
D[7895] = {"Bidules bourdonnants en bronze",{"Mon nouveau stand sera quelque chose à ne pas manquer, oui monsieur ! Et pour quelques chanceux, quelque chose à toucher aussi !","","J'entends déjà les Bidules bourdonnants en bronze entonnant un chant d'extase mécanique quand les clients entreront dans mon stand pour tester leur habileté !","","Ah... maintenant il me faut les bidules pour que mon rêve devienne réalité. S'il vous plaît, <nom>, apportez-moi des Bidules bourdonnants en bronze... et des bons de la foire de Sombrelune vous attendront !"}}
D[7896] = {"Feux d'artifice vert",{"Quand j'aurai enfin mon stand, je voudrai m'offrir de la publicité ! Quel meilleur moyen y aurait-il pour cela que des feux d'artifice ?","","Oui, certains pensent sûrement que l'odeur d'un chaudron bouillonnant rempli des têtse de vos ennemis serait une meilleure idée pour attirer les foules, mais... nous ne sommes pas seuls ici. Il faudra donc que ce soit des feux d'artifice !","","Apportez-moi des feux d'artifice verts, <nom>, et j'aurai plein de bons de la foire de Sombrelune pour vous."}}
D[7897] = {"Trousses de réparation mécanique",{"La principale raison pour laquelle je ne peux pas ouvrir mon stand, c'est que... rien n'est en état de marche ! Il me faut des trousses de réparation mécanique pour réparer tout ça !","","Pouvez-vous m'apporter ces trousses, <nom> ? En échange, je vous donnerai... des trousses de bons de la foire de Sombrelune. Qu'en dites-vous ?"}}
D[7898] = {"Les rouages en thorium",{"Yebb Nebblegear, comme moi, travaille à une nouvelle attraction. D'après Nebb, elle est tellement stupéfiante qu'elle attirera des gens du monde entier... et elle nous rendra tous très, très riches !","","Il dit qu'il lui faut des rouages en thorium pour sa construction et il veut que je me les procure pour lui. Qu'en pensez-vous, <nom> ? Savez-vous où je pourrais en trouver ? Si vous êtes ingénieur, pourriez-vous en fabriquer ? Voulez-vous en échanger contre des bons de la foire de Sombrelune ?"}}
D[7899] = {"Petites pattes en fourrure",{"Pour attirer beaucoup de monde, il faut avant tout appâter les gens avec des gadgets et des bibelots ! Pouvez-vous m'aider ?","","J'ai besoin de petites pattes en fourrure pour en faire des lots. Vous pouvez les trouver sur les félins des Tarides ou de Sombrivage....","","Apportez-moi des pattes et je vous les échangerai contre un bon de la foire de Sombrelune."}}
D[7900] = {"Peaux d'ours déchirées"}
D[7901] = {"Queues fournies soyeuses",{"C'est vraiment incroyable, ce à quoi les gens peuvent trouver de la valeur ! Prenez par exemple un bâton en bois avec une Queue fournie soyeuse attachée après. Vous et moi savons qu'une choses pareille n'a pas grande valeur... mais si vous donnez à cette camelote un chouette nom du genre de \"Queue sauvage\" et la mettez dans une belle boîte, les gens croiront que ça a de la valeur. La pacotille devient un trésor !","","Cherchez pour moi des Queues fournies soyeuses sur les loups de Désolace et des Terres ingrates, et je vous donnerai des bons de la foire de Sombrelune."}}
D[7902] = {"Plumes vibrantes",{"L'imagination est une chose incroyable. Grâce à elle, la moindre colline peut sembler être la plus haute montagne. L'ombre la plus inoffensive peut paraître sortie d'une terrible cauchemar !","","Ici, à la foire de Sombrelune, nous laissons libre court à l'imagination de nos visiteurs ! Mais pour les aider à laisser s'épanouir leur imagination... nous devons parfois faire preuve de ruse.","","Il me faut des plumes vibrantes pour une de mes attractions. Vous pouvez les prendre sur les oiseaux des régions les plus dangereuses d'Azeroth. Apportez-moi les plumes et vous recevrez beaucoup de bons !"}}
D[7903] = {"Yeux de chauve-souris maléfique",{"Vous arrive-t-il parfois d'errer dans une grotte, tard la nuit, à la recherche d'aventures ? Oui ? Vraiment ? Alors vous avez sûrement vu les yeux menaçants des chauves-souris qui vous fixent d'en haut, attendant que vous baissiez votre garde pour sucer votre sang !","","C'est effrayant, vous ne trouvez pas ? Bien sûr ! Évidemment les yeux des chauves-souris sont effrayants !","","Voulez-vous me rapporter des yeux de chauve-souris maléfique, <nom>? Il me les faut pour... quelque chose que je suis en train de mettre au point. Quelque chose d'effrayant.","","Vous pouvez les trouver sur les chauves-souris des Maleterres de l'est."}}
D[7905] = {"La foire de Sombrelune",{"Donnez le Coupon pour des bons gratuits à Gelvas Crasseporte, qui se trouve dans la foire de Sombrelune."}}
D[7906] = {"Cartes de Sombrelune - Fauves"}
D[7907] = {"Suite de Fauves de Sombrelune",{"Rapporter la suite de Fauves à la foire de Sombrelune quand elle reviendra en ville."}}
D[7908] = {"Le maître de l'arène",{"Parler à Court John Mithril dans l'arène de Strangleronce."}}
