D[7936] = {"50 bons - Mouton de l'an dernier"}
D[7937] = {"Une surprise vous attend...",{"Allez dans le Camp de bûcherons du Val d'est dans la Forêt d'Elwynn pour trouver la surprise qui vous attend."}}
D[7938] = {"Une surprise vous attend...",{"Allez dans les Mortemines dans la marche de l'Ouest pour trouver la surprise qui vous attend."}}
D[7939] = {"Plus de silex à aiguiser denses",{"<nom>, je vous remercie de toute l’aide que vous m’avez apporté. Sincèrement, je ne vous remercierai jamais assez.","","Et même si j’en ai moins besoin maintenant, si vous me fournissez d’autres pierres à aiguiser denses, il se pourrait que je vous donne d’autres bons de la foire de Sombrelune."}}
D[7940] = {"1200 bons - Orbe de Sombrelune",{"Avancez, avancez ! Si vous avez des bons de la foire de Sombrelune à échanger, il suffit de le dire ! Vous pouvez échanger vos bons contre différents lots plus merveilleux et fantastiques les uns que les autres. Ne soyez pas timide, venez tenter votre chance ! !"}}
D[7941] = {"Plus de renforts d'armure"}
D[7942] = {"Plus de rouages en thorium",{"<nom>, vous m’avez bien rendu service en m’amenant tout cela sans jamais vous lasser. Vous avez toute ma gratitude.","","Nous avons moins besoin de rouages en thorium qu’à une certaine époque, mais si vous m’en amenez d’autres, je vous les échangerai contre des bons de la foire de Sombrelune."}}
D[7943] = {"Plus d’yeux de chauve-souris",{"<nom>, l’attraction que je suis en train de créer sera la chose la plus effrayante qu’on ait vue depuis la chute de Gnomeregan ! Et c’est largement grâce à tout ce que vous m’avez apporté. Merci, merci mille fois !","","Je n’ai plus besoin de grand-chose mais… si vous m’apportez encore des yeux de chauve-souris maléfiques pris sur les chauve-souris des Maleterres de l’est… je pourrais avoir d’autres bons de la foire de Sombrelune pour vous."}}
D[7944] = {"Une surprise vous attend...",{"Allez dans les Cavernes des lamentations dans les Tarides pour trouver la surprise qui vous attend."}}
D[7945] = {"Une surprise vous attend...",{"Allez au Rocher des crins-pâles pour trouver la surprise qui vous attend."}}
D[7946] = {"Le rejeton de Jubjub",{"Je suis si content que Jubjub ait été retrouvée. Elle aime tellement la bière Sombrefer que lorsque je n’en ai plus… elle s’enfuit pour en chercher !","","Maintenant que Jubjub est revenue, je veux stocker toute la bière que je peux trouver ! Je ne veux pas que Jubjub s’enfuie à nouveau !","","Vous avez de la bière Sombrefer ? Si c’est le cas, je vous l’échange l’un des œufs de ma grenouille Jubjub contre une chope."}}
D[7961] = {"Gredins de lapins !",{"Tuer 5 lapins et revenir voir Jon LeCraft près de la forge sur l'Ile des concepteurs."}}
D[7981] = {"1200 bons - Amulette de la Sombrelune"}
D[8001] = {"Voltigeurs Chanteguerre <NYI> <TXT>"}
D[8002] = {"Sentinelles d'Aile-argent <NYI> <TXT>"}
D[8021] = {"Echanger les bons iCoke"}
D[8023] = {"Echanger les bons iCoke"}
D[8026] = {"Echanger les bons iCoke"}
D[8041] = {"La force du mont Mugamba",{"Salut, <classe>. je suis Jin’rokh le Briseur, un troll de Mugamba. La tribu de Zandalar reconnaît la valuer de vos exploits. Nous saluons votre ténacité la et la force de votre volonté.","","Portez ce talisman autour de votre cou, <classe>. Laissez la force du Mont Mugamba s’écouler dans votre être. Que sa force vous aider à frapper nos ennemis !"}}
D[8042] = {"La force du mont Mugamba",{"C’est bon de vous voir en bonne santé, <nom>. Les combats glorieux que vous avez menés affectent tous les êtres vivants de cette planète. Hakkar doit rester à jamais dans les confins de Zul’Gurub, sinon le monde succomberait sous les assauts de son insatiable faim.","","Donnez-moi votre talisman, et j’amplifierai sa force. Utilisez la Force de Mugamba pour punir nos ennemis !"}}
D[8043] = {"La force du mont Mugamba",{"Maître <nom>, vous êtes revenu ! Molthor a transmis au roi le récit de vos exploits. Votre nom est désormais connu jusqu’aux Mers du sud. Peut-être qu’un jour vous deviendrez un héros légendaire - et que votre histoire qui traversera les siècles.","","Donnez-moi votre talisman pour que je puisse une fois encore augmenter son pouvoir."}}
D[8044] = {"La rage de Mugamba",{"Le roi Rastakhan vous transmet ses meilleures salutations, maître <nom>. Un tel honneur n’a encore jamais été accordé à une personne n’appartenant pas à la tribu Zandalar.","","Donnez-moi votre talisman pour que je puisse l’améliorer une nouvelle fois. Sachez que la Rage de Mugamba est maintenant intrinsèquement liée à votre âme."}}
D[8045] = {"La marque du païen",{"Sachez ceci, incroyant. Si une catastrophe nous a réunis, vos manières impies ne sont ni comprises ni appréciées de Zandalar. Mais nous sommes un peuple juste. Portez cette marque autour du cou. Elle servira à la fois d’avertissement à nos ennemis et de symbole de l’amitié de Zandalar.","","Si vous continuez à servir notre peuple, j’augmenterai la puissance de la marque."}}
D[8046] = {"La marque du païen",{"J’ai peut-être été trop hâtif dans mon jugement, <classe>. Il semblerait que votre foi aveugle dans cette Lumière ait un peu de mérite, après tout.","","Donnez-moi votre marque et j’amplifierai son pouvoir."}}
D[8047] = {"La marque du païen",{"Je dois avouer que je ne croyais pas que vous auriez la détermination pour mener cette cause à bien, <classe>. Zandalar vous considère maintenant comme un allié de valeur. Bien joué,nnDonnez-moi votre marque et j’amplifierai une nouvelle fois son pouvoir."}}
D[8048] = {"La marque du héros",{"Le roi a reconnu votre existence, <classe>. Vous êtes la première étrangère à être accepté par Rastakhan comme une  véritable alliée  de Zandalar.","","Vous serez grandement récompensée  de vos efforts. Présentez votre marque et je lui apporterai l’amplification finale."}}
D[8049] = {"L'œil de Zuldazar",{"Acceptez ce talisman en témoignage de notre gratitude, <classe>.","","L’Œil de Zuldazar grandira en pouvoir en même temps que grandira votre lien avec les trolls de Zandalar. Revenez me voir de temps en temps, pour que j’imprègne le joyau."}}
D[8050] = {"L'œil de Zuldazar",{"Bienvenue, <classe>. L’énergie pulse dans l’Œil de Zuldazar. Vous êtes prêt pour la prochaine étape. Confiez-moi le talisman et je réaliserai l’imprégnation."}}
D[8051] = {"L'œil de Zuldazar",{"Les vents murmurent le récit de vos combats contre les Gurubashi, prêtresse . Même la cour royale commence à entendre parler de vos exploits. D’après la rumeur, le roi Rastakhan lui-même a mentionné votre nom.","","Le temps est venu d’imprégner l’Œil. Confiez-moi le talisman et je m’en occuperai."}}
D[8052] = {"L'Œil omnivoyant de Zuldazar",{"Si seulement nous avions dix mille personnes comme vous, <nom>. Les armées d’Hakkar seraient dispersées aux quatre vents en un clin d’œil.","","Hélas, l’Œil est prêt à atteindre son plein potentiel."}}
D[8053] = {"Parangons de puissance : les garde-bras de libre-penseur",{"Ramenez des Manchettes primordiales hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8054] = {"Parangons de puissance : la ceinture de libre-penseur",{"Ramenez un Châle primordial hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8055] = {"Parangons de puissance : la cuirasse de libre-penseur",{"Ramenez un Tabard primordial hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
