D[8064] = {"Parangons de puissance : la ceinture d'haruspice",{"Ramenez une Echarpe primordiale hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l'île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Honorer (au minimum)."}}
D[8065] = {"Parangons de puissance : la tunique d'haruspice",{"Ramenez un Tabard primordial hakkari à Maywiki de Zuldazar. Maywiki de Zuldazar se trouve sur l'île de Yojamba, dans la vallée de Strangleronce. La tribu Zandalar doit aussi vous Révérer (au minimum)."}}
D[8066] = {"Parangons de puissance : la ceinture de prédateur",{"Ramenez un Châle primordial hakkari à Falthir le Sans-vue. La tribu Zandalar doit aussi vous Honorer (au minimum).","","Falthir le Sans-vue se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
