D[8077] = {"Parangons de puissance : la robe de démoniaque",{"Ramenez une Casaque primordiale hakkari à Al'tabim Qui-voit-tout. La tribu Zandalar doit aussi vous Révérer (au minimum).","","Al'tabim Qui-voit-tout se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8078] = {"Parangons de puissance : la ceinture de redresseur de torts",{"Ramenez un Ceinturon primordial hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8079] = {"Parangons de puissance : la cuirasse de redresseur de torts",{"Ramenez une Casaque primordiale hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8080] = {"Les ressources du bassin d'Arathi",{"Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière."}}
D[8081] = {"Plus de caisses de ressources"}
D[8101] = {"Le caillou de Kajaro",{"<nom>, le caillou enchâssé dans la monture de ce talisman provient du mont Kajaro, dans les Mers du sud. Le mont Kajaro souffre d’une grande instabilité, car il est secoué par des éruptions volcaniques fréquentes, et souvent magiques.","","Quand votre lien avec les trolls de Zandalar grandira, la puissance de ce caillou fera de même. Utilisez son pouvoir pour frapper nos ennemis. Soyez comme la montagne : vif, explosif, mortel…"}}
D[8102] = {"Le caillou de Kajaro",{"Bienvenue de nouveau, <classe>. Je vois que le caillou a beaucoup servi. Un grand nombre de nos ennemis a succombé devant vos capacités surnaturelles. Leurs souffrances ont été grandes. Il est temps que j’augmente la puissance du caillou. Donnez-le-moi."}}
D[8103] = {"Le caillou de Kajaro",{"Les Hakkari vous craignent, <nom>. Ils parlent d’horreurs qu’ils croyaient n’être l’apanage que de leur dieu sans visage. Vous les avez brûlés grâce à la force de Kajaro. Ils connaissent maintenant la peur en deux endroits.","","Il est temps maintenant de renforcer le caillou. Donnez-moi le talisman."}}
D[8104] = {"Le joyau de Kajaro",{"Donnez-moi le talisman, <nom>. Je dois vous montrer quelque chose."}}
D[8105] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}}
D[8106] = {"La souillure de Kezan",{"Acceptez ce talisman, <classe>. Acceptez-le et utilisez son pouvoir pour abattre nos ennemis communs.","","Sachez que vous portez autour du cou un morceau d’histoire. Kezan était autrefois un immense territoire de l’empire Zandalar. Hélas, la souillure des princes marchands gobelins a fini par chasser mes fiers frères et sœurs de cette région.","","Kezan est maintenant le site de la capitale gobeline d’Undermine ; mais sachez qu’avant d’être souillée, elle abritait la grandeur. Même aujourd’hui, Kezan est considérée comme une terre sacrée par mon peuple."}}
D[8107] = {"La souillure de Kezan",{"L’honneur se mérite chez les trolls de Zandalar, <nom>. Avec l’honneur viennent les récompenses : l’amitié, les alliances… nnDonnez-moi le talisman pour que je puisse renforcer son pouvoir."}}
D[8108] = {"La souillure de Kezan",{"Je suis prêt, <classe>. Je vais une nouvelle fois améliorer votre talisman. Je vous demande seulement de continuer votre destruction d’Hakkar et de ses séides.","","Donnez-moi le talisman."}}
D[8109] = {"La souillure irrésistible de Kezan",{"Appelez vos démons, <classe>. Qu’ils se baignent dans l’énergie de la Souillure de Kezan. Commandez-les sur le champ de bataille ! Décimez nos ennemis !","","Oui… Le temps est venu d’apporter l’amélioration finale à la Souillure de Kezan. Donnez-moi le talisman."}}
D[8110] = {"Le varech enchanté des Mers du sud",{"Vous voyez cette algue ? Elle vient des Mers du sud. Nous lui ajoutons juste un peu de mojo et de magie, et elle gagne les propriétés qui sont les plus utiles à son porteur.","","Vous êtes un <classe>, alors ce sera facile. Enroulez-la simplement autour de votre cou, et pensez à la nature, aux écureuils, ou à n’importe quelle chose qu’aiment les gens de votre peuple."}}
D[8111] = {"Le varech enchanté des Mers du sud",{"Salut ! C’est bien sympathique de revenir nous voir. Toute la tribu raconte comment vous avez tué les Hakkari et tout ça. Molthor m’a fait passer le mot, et m'a demandé de rajouter plus de mojo dans votre talisman. Donnez-le-moi, et Maywiki l’améliorera."}}
D[8112] = {"Le varech enchanté des Mers du sud",{"Comment va votre talisman ? On dirait que c’est l’heure d’ajouter un petit peu plus de magie et de mojo à ses feuilles. Il a besoin d’une petite fleur dans son desséchement. Donnez-le-moi et Maywiki le réparera."}}
D[8113] = {"Le varech enchanté des Mers du sud en parfait état"}
D[8114] = {"Contrôler quatre bases",{"Entrez dans le bassin d'Arathi, capturez et contrôlez quatre bases simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}}
D[8115] = {"Prendre cinq bases",{"Contrôlez 5 bases du bassin d'Arathi simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}}
D[8116] = {"Vision de Voodress",{"Vous et Maywiki avez quelque chose en commun, gamin. Nous sommes des chamans ! Mais bon, Maywiki est plutôt une mystique, et vous un second couteau. Enfin, nous savons tous deux ce qu’apportent les grands esprits.","","Je vous offre cet orbe, pour que vous le portiez en collier. Regardez à l’intérieur, et vous verrez le village de Voodress dans les Mers du sud ! Qu’il élève vos esprits !"}}
D[8117] = {"Vision de Voodress",{"Cha-lut ! Maywiki a fait une blague !","","<Maywiki rit.>","","Eh bien, vous avez utilisé les esprits et les éléments contre nos ennemis à Zul’Gurub, hein ? Loués soient les esprits !","","Maywiki va faire briller votre orbe. Donnez-le-moi, <nom>."}}
D[8118] = {"Vision de Voodress",{"Bonnes nouvelles, <nom>. Molthor a chanté vos louanges, récemment. Il raconte comment vous êtes en train de devenir une grande héroïne de Zandalar.","","Il a aussi demandé à Maywiki d’améliorer une nouvelle fois votre orbe ! Donnez-le-moi pour que Maywiki puisse éclairer la vision."}}
D[8119] = {"La vision limpide de Voodress"}
D[8120] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et l'écurie du bassin d'Arathi, puis revenez voir le Maître de la mort Dwire, au Trépas-d'Orgrim."}}
D[8121] = {"Prendre quatre bases",{"Contrôlez quatre bases du bassin d'Arathi simultanément, puis revenez voir le Maître de la mort Dwire, au Trépas-d'Orgrim."}}
D[8122] = {"Prendre cinq bases",{"Contrôlez 5 bases du bassin d'Arathi simultanément, puis revenez voir le Maître de la mort Dwire, au Trépas-d'Orgrim."}}
D[8123] = {"Couper les voies de ravitaillement d'Arathor",{"Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au nécrotraqueur Mortis au Trépas-d'Orgrim."}}
D[8124] = {"Plus de caisses de ressources"}
D[8141] = {"Le talisman d'ombre zandalarien",{"Vous progressez rapidement, jeune <classe>. Il est sans doute temps de vous initier pour vous faire entrer dans le Shera Ali’kh - la Main de la Mort, en zandalari. Pendant des milliers d’années, nous avons été les assassins de l’empire Zandalar. Mais nous sommes restés oisifs pendant trop longtemps, permettant aux Hakkari d’accroître leurs forces. Aujourd’hui, nous devons à nouveau affronter Hakkar, mais cette fois sans le soutien d’une nation troll unifiée. Ce sont vous et vos alliés qui devez nous aider à vaincre le Dieu du Sang et ses séides !","","Portez ce talisman, qui vous aidera dans vos pérégrinations."}}
D[8142] = {"Talisman d'ombre zandalarien",{"J’ai le sentiment que vous avez infligé d’innombrables pertes aux Hakkari, <nom>. Vous portez sur vous la puanteur de leur mojo.","","Je suppose que le talisman d’ombre a bien participé au massacre… Donnez-le-moi et permettez-moi d’augmenter son pouvoir."}}
D[8143] = {"Le Talisman d'ombre zandalarien",{"Impressionnant, <nom>. Vous avez un don pour le meurtre que je n’ai pas ressenti chez quelqu’un depuis de longues années. Même Molthor est conscient du travail que vous avez effectué pour Zandalar. Il est temps d’améliorer une nouvelle fois votre talisman. Donnez-le-moi."}}
D[8144] = {"Le talisman de maîtrise de l'ombre zandalarien",{"Le talisman brûle d’envie de grandir, <nom>. Il a absorbé tout ce que vous avez accompli. Les milliers de cadavres de trolls qui jonchent Zul’Gurub ont alimenté son pouvoir. Donnez-le-moi, et j’accomplirai l’amélioration finale."}}
D[8145] = {"Les Vrilles du maelström",{"Chez les Zandalariens, la profession de <classe> est tenue en très haute estime. Nos plus grands chasseurs voyagent jusqu’au bord du Maelström pour prouver leur résolution.","","Ils tirent des entrailles de la mer des rubans de varech, que l’on nomme les Vrilles du Maelström. Le varech est tressé pour confectionner un talisman qui, une fois enchanté, augmente la précision et la puissance de leurs attaques.","","Je vous offre aujourd’hui cette simple tresse de Vrilles du Maelström. Quand votre lien avec Zandalar aura grandi, je tisserai plus de puissance dans le talisman."}}
D[8146] = {"Les Vrilles du maelström",{"Ah, <nom>, c’est bon de sentir votre odeur à nouveau.","","Vous devez me pardonner mon sens de l’humour. Il peut être assez noir, par moment.","","J’ai cru comprendre que vous avez infligé de terribles angoisses à nos ennemis. Les troupes d’Hakkar, folles de colère, maudissent votre nom. C’est excellent.","","Vous avez gagné un nouvel enchantement de votre talisman. Donnez-le-moi."}}
D[8147] = {"Les Vrilles du maelström",{"J’entends d’ici le bruit de nos volées de flèches qui dévastent les rangs de nos ennemis. Leurs cris d’agonie y font écho.","","Vous vous êtes fait un nom chez les trolls de Zandalar, <nom>. Nous vous sommes reconnaissant de tout ce que vous avez fait.","","Donnez-moi votre talisman pour que je puisse y ajouter un nouvel enchantement."}}
D[8148] = {"Le courroux du maelström",{"Molthor nous a transmis la parole du roi Rastakhan, <nom>. La cour royale est très impressionnée par votre décimation des forces hakkari. Je dois vous récompenser par l’enchantement final de votre talisman. Donnez-le-moi."}}
D[8149] = {"En l'honneur d'un héros",{"Rendez-vous au tombeau d'Uther dans les Maleterres de l'ouest, puis utilisez l'Offrande à Uther sur sa statue, avant de retourner voir Wagner Frappemartel à l'extérieur de Forgefer, avant la fin de la Fête des moissons."}}
D[8150] = {"En l'honneur d'un héros",{"Rendez-vous au monument de Grom dans le canyon de la Malechute en Orneval, puis utilisez l'Offrande à Grom à la base du monument. Ensuite, retournez voir Javnir Nashak à l'extérieur d'Orgrimmar, avant la fin de la Fête des moissons."}}
D[8151] = {"Le charme du chasseur",{"Parlez à Ogtinc en Azshara."}}
D[8153] = {"La ramure de coursier",{"Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d'Eldarath."}}
D[8154] = {"Les ressources du bassin d'Arathi",{"Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière."}}
D[8155] = {"Les ressources du bassin d'Arathi",{"Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière."}}
