D[8166] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}}
D[8167] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}}
D[8168] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}}
D[8169] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et l'écurie du bassin d'Arathi, puis revenez voir le Maître de la mort Dwire, au Trépas-d'Orgrim."}}
D[8170] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et l'écurie du bassin d'Arathi, puis revenez voir le Maître de la mort Dwire, au Trépas-d'Orgrim."}}
D[8171] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et l'écurie du bassin d'Arathi, puis revenez voir le Maître de la mort Dwire, au Trépas-d'Orgrim."}}
D[8181] = {"La confrontation avec Yeh'kinya",{"Parlez à Yeh'kinya."}}
D[8182] = {"La main de Rastakhan",{"Parlez à Molthor à Strangleronce."}}
D[8183] = {"Le cœur d'Hakkar",{"Donnez le Cœur d'Hakkar à Molthor sur l'île de Yojamba."}}
D[8184] = {"La présence de la puissance",{"Zanza peut créer les anciens enchantements des trolls s’il dispose des composants appropriés.","","Le premier est une idole primordiale hakkari qui doit être prise sur les plus puissants des lieutenants Hakkari : Jin’do et le Seigneur sanglant.","","Le second est une poupée vaudou percée. On peut en trouver dans les piles d’ordures qui jonchent cet endroit ignoble. Cherchez dans les piles de déchets.","","Ramenez-moi ces choses et je vous façonnerai un enchantement puissant !"}}
