D[8431] = {"La bataille du goulet des Chanteguerres",{"La bataille continue de faire rage dans le goulet des Warsong, <nom>. Faites votre part pour chasser les sentinelles d'Aile-argent de nos terres !"}}
D[8432] = {"La bataille du goulet des Chanteguerres",{"La bataille continue de faire rage dans le goulet des Warsong, <nom>. Faites votre part pour chasser les sentinelles d'Aile-argent de nos terres !"}}
D[8433] = {"La bataille du goulet des Chanteguerres",{"La bataille continue de faire rage dans le goulet des Warsong, <nom>. Faites votre part pour chasser les sentinelles d'Aile-argent de nos terres !"}}
