D[8921] = {"L'alambic ectoplasmique",{"Retournez voir Mux Brouillemana à Gadgetzan avec 1 Convertisseur d'arcanite délicat, 4 Essences éternelles supérieures, 10 Huiles de pierre-écaille, 25 Cendres volcaniques et 40 pièces d'or."}}
D[8922] = {"Un objet surnaturel",{"Remettre le Récipient de sang scellé à Mux Brouillemana, à Gadgetzan en Tanaris."}}
D[8923] = {"Un objet surnaturel",{"Remettez le Récipient de venin scellé à Mux Brouillemana, à Gadgetzan."}}
D[8924] = {"La chasse aux ectoplasmes",{"Utilisez l'Alambic ectoplasmique à proximité de morts-vivants désincarnés pour recueillir 12 Ectoplasmes brûlés en Silithus, 12 Ectoplasmes glacés au Berceau-de-l'hiver et 12 Ectoplasmes stables dans les Maleterres de l'est. Remettez à Mux Brouillemana à Gadgetzan. Il veut aussi récupérer l'Alambic ectoplasmique."}}
D[8925] = {"Une source d’énergie portable",{"Trouvez le Seigneur-magma Bokk dans les Steppes ardentes, prenez son Coeur de magma et rapportez-le à Mux Brouillemana, à Gadgetzan."}}
D[8926] = {"Une juste compensation",{"Apportez une Ceinture du Coeur-sauvage et une paire de Gants du Cœur-sauvage à Deliana à Ironforge."}}
D[8927] = {"Une juste compensation",{"Apportez une Ceinture du Coeur-sauvage et une paire de Gants du Cœur-sauvage à Mokvar à Orgrimmar."}}
D[8928] = {"Un marchand à éclipses",{"Trouvez un diablotin qui vivrait dans une caverne à l'entrée de la gorge du Sombre murmure, au sud du Berceau-de-l'hiver. Achetez-lui un Bâtonnet élémentaire de corruption, puis retournez voir Mux Brouillemana à Gadgetzan."}}
D[8929] = {"À la recherche d'Anthion",{"Utilisez le Révélateur de fantômes extradimensionnel à l'entrée de Stratholme et parlez au fantôme d'Anthion Harmon."}}
D[8930] = {"À la recherche d'Anthion",{"Utilisez le Révélateur de fantômes extradimensionnel à l'entrée de Stratholme, et parlez au fantôme d'Anthion Harmon."}}
