D[8945] = {"La supplique du mort",{"Entrez à Stratholme et sauvez Ysida Harmon du baron Vaillefendre."}}
D[8946] = {"Une preuve de vie",{"Remettre le Médaillon d’Ysida à Anthion Harmon, dans les Maleterres de l’est."}}
D[8947] = {"L'étonnante requête d'Anthion",{"Remettre 3 Barres de sombrefer, 20 Cuirs enchantés, 3 Etoffes lunaires et 4 Peaux robustes traitées à Anthion Harmon dans les Maleterres de l'est."}}
D[8948] = {"Le vieil ami d'Anthion",{"Apportez la Bannière de provocation incomplète à Falrin Sculpteflore, dans la bibliothèque de Hache-tripes."}}
D[8949] = {"La vendetta de Falrin",{"Collecter 25 Perles de guerre ogres à l'intérieur de Hache-tripes ou du Pic Rochenoire, puis revenir voir Falrin Sculpteflore, à l'intérieur de l'Athenaeum à Hache-tripes."}}
D[8950] = {"L'enchantement du provocateur",{"Apportez les choses suivantes à Falrin Sculpteflore dans Hache-tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants."}}
D[8951] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Ironforge avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage."}}
D[8952] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Forgefer avec des Bottes de bestiaire, un Pantalon de bestiaire et un Mantelet de bestiaire."}}
D[8953] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Forgefer avec des Bottes de magistère, des Jambières de magistère et un Mantelet de magistère."}}
D[8954] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Forgefer avec des Bottes de Sancteforge, des Cuissards de Sancteforge et des Spallières de Sancteforge."}}
D[8955] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Forgefer avec des Sandales de dévot, une Jupe de dévot et un Mantelet de dévot."}}
D[8956] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Forgefer avec des Bottes Sombreruse, un Pantalon Sombreruse et des Spallières Sombreruse."}}
D[8957] = {"Les adieux d'Anthion",{"Retournez voir Mokvar à Orgrimmar avec des Bottes des éléments, un Kilt des éléments et des Espauliers des éléments."}}
D[8958] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Ironforge avec des Sandales de Brume-funeste, des Jambières de Brume-funeste et un Mantelet de Brume-funeste."}}
D[8959] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Forgefer avec des Bottes de vaillance, des Cuissards de vaillance et des Spallières de vaillance."}}
D[8960] = {"Le triste destin de Bodley",{"Rendez-vous au mont Blackrock, près du pic Blackrock, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley."}}
D[8961] = {"Les trois rois des flammes",{"Récupérez l'Incendicite d'Incendius, la Braise du prophète ardent sur le pyrogarde Prophète ardent et les Cendres de Cendres, ainsi qu'un Brasero béni, puis retournez voir Bodley au mont Rochenoire."}}
D[8962] = {"Des composants importants",{"Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l'intérieur du mont Rochenoire."}}
D[8963] = {"Des composants importants",{"Procurez-vous une Relique de Brise-stellaire et rapportez-la à Bodley, à l'intérieur du mont Rochenoire."}}
D[8964] = {"Des composants importants",{"Procurez-vous une Epée brillante de fanatisme, puis rapportez-la à Bodley, à l'intérieur du mont Rochenoire."}}
D[8965] = {"Des composants importants",{"Prélevez des Cendres d’âme de banni, puis retournez voir Bodley à l’intérieur du mont Blackrock."}}
D[8966] = {"Le morceau gauche de l'amulette du seigneur Valthalak",{"Utilisez le Brasero de signal pour invoquer l'esprit de Mor Sabot-gris, puis tuez-le. Ensuite, retournez voir Bodley à l'intérieur du mont Rochenoire avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal."}}
D[8967] = {"Le morceau gauche de l'amulette du seigneur Valthalak",{"Utilisez le Brasero de signal pour invoquer l'esprit d'Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal."}}
D[8968] = {"Le morceau gauche de l'amulette du seigneur Valthalak",{"Utilisez le Brasero de signal pour invoquer Jarien et Sothos et les tuer. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal."}}
D[8969] = {"Le morceau gauche de l'amulette du seigneur Valthalak",{"Utilisez le Brasero de signal pour invoquer l'esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal."}}
D[8970] = {"Votre avenir passe par l'île d'Alcaz",{"Récupérez 20 Varechs de sang sur les nagas Strashaz, puis retournez voir Bodley au mont Rochenoire."}}
D[8977] = {"Retourner voir Deliana",{"Apportez le Révélateur de fantômes extradimensionnel à Deliana à Ironforge."}}
D[8978] = {"Retourner voir Mokvar",{"Retournez voir Mokvar à Orgrimmar avec le Révélateur de fantômes extradimensionnel."}}
