D[8980] = {"L'évaluation de Zinge",{"Retourner voir Fenstad Argyle, devant la banque de Fossoyeuse."}}
D[8981] = {"Faire des cadeaux",{"Êtes-vous venu offrir un présent d’amour et d’adoration à votre chef préféré ?"}}
D[8982] = {"Remonter à la source",{"Parler à l'aubergiste Norman de Fossoyeuse."}}
D[8983] = {"Remonter à la source",{"Parlez à Mara Rennick, à la boutique du tailleur du quartier des mages de Fossoyeuse."}}
