D[9109] = {"La ceinture de pestecoeur",{"Mataus la Voix du courroux, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera une Ceinture de pestecoeur si vous lui ramenez 1 Ceinture désacralisée, 8 Débris d'armure en tissu, 2 Cristaux des arcanes et 2 Etoffes lunaires."}}
D[9110] = {"Les manchettes de pestecoeur",{"Mataus la Voix du courroux, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Manchettes de pestecoeur si vous lui ramenez 1 paire de Manchettes désacralisées, 6 Débris d'armure en tissu, 1 Cristal des arcanes et 1 Cristal de nexus."}}
D[9111] = {"La robe de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera une Robe de foi si vous lui ramenez 1 Robe désacralisée, 25 Débris d'armure en tissu, 4 Etoffes lunaires et 2 Cristaux de nexus."}}
D[9112] = {"Les jambières de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Jambières de foi si vous lui ramenez 1 paire de Jambières désacralisées, 20 Débris d'armure en tissu, 4 Etoffes lunaires et 2 Cristaux de nexus."}}
D[9113] = {"Le diadème de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera un Diadème de foi si vous lui ramenez 1 Diadème désacralisé, 15 Débris d'armure en tissu, 3 Etoffes lunaires et 3 Cristaux de nexus."}}
D[9114] = {"Le protège-épaules de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Protège-épaules de foi si vous lui ramenez 1 paire de Protège-épaules désacralisés, 12 Débris d'armure en tissu, 2 Etoffes lunaires et 3 Peaux robustes traitées."}}
D[9115] = {"Les sandales de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Sandales de foi si vous lui ramenez 1 paire de Sandales désacralisées, 12 Débris d'armure en étoffe, 2 Etoffes lunaires et 3 Peaux robustes traitées."}}
D[9116] = {"Les gants de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Gants de foi si vous lui ramenez 1 paire de Gants désacralisés, 8 Débris d'armure en tissu et 4 Etoffes lunaires."}}
D[9117] = {"La ceinture de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera une Ceinture de foi si vous lui ramenez 1 Ceinture désacralisée, 8 Débris d'armure en tissu, 2 Cristaux des arcanes et 2 Etoffes lunaires."}}
D[9118] = {"Les manchettes de foi",{"Le père Inigo Montoy, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Manchettes de foi si vous lui ramenez 1 paire de Manchettes désacralisées, 6 Débris d'armure en tissu, 1 Cristal des arcanes et 1 Cristal de nexus."}}
D[9119] = {"Panne au sanctum occidental",{"Parler à la telluriste Velania, au Sanctum occidental du bois des Chants éternels."}}
D[9120] = {"La chute de Kel'Thuzad",{"Apportez le Phylactère de Kel'Thuzad à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9121] = {"Naxxramas, la citadelle de l'effroi",{"L'archimage Angela Dosantos à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est veut 5 Cristaux des arcanes, 2 Cristaux de nexus, 1 Orbe de piété et 60 pièces d'or. Vous devez aussi être <Honoré/Honorée> auprès de l'Aube d'argent."}}
D[9122] = {"Naxxramas, la citadelle de l'effroi",{"L'archimage Angela Dosantos à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est veut 2 Cristaux des arcanes, 1 Cristal de nexus et 30 pièces d'or. Vous devez aussi être <Révéré/Révérée> auprès de l'Aube d'argent."}}
D[9123] = {"Naxxramas, la citadelle de l'effroi",{"L'archimage Angela Dosantos à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est vous accordera gratuitement l'Occultation arcanique. Vous devez être <Exalté/Exaltée> auprès de l'Aube d'argent."}}
D[9124] = {"L'armure de traqueur des cryptes ne se fabrique pas toute seule",{"Le veneur Leopold, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut que vous lui apportiez 30 Morceaux de démon des cryptes."}}
D[9125] = {"Des morceaux de démon des cryptes",{"Votre travail pour le premier lot a été exemplaire, <nom>. Si vous en avez plus, je peux les prendre maintenant. Pour chaque lot que vous rapporterez, je vous récompenserai avec un insigne."}}
D[9126] = {"Des morceaux pour la faucheuse d'os",{"Rohan l'assassin, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut 30 Fragments d'os."}}
D[9127] = {"Des fragments d'os",{"Dans mon métier, un homme ne peut jamais avoir trop de fragments d'os, <nom>.Chaque fois que vous aurez un surplus de fragments, apportez-les-moi, je vous récompenserai avec un autre insigne."}}
D[9128] = {"L'équation élémentaire",{"L'archimage Angela Dosantos à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est veut 30 Noyaux des éléments."}}
D[9129] = {"Le noyau des éléments",{"À vrai dire, j’utilise les noyaux pour créer des armures de givrefeu. C’est l’armure que portent les mages qui se battent dans Naxxramas. Sans vous et quelques autres, nous serions incontestablement en train de perdre cette guerre.","","Ceci dit, vous pouvez m’apporter encore des noyaux et je vous octroierai d’autres insignes."}}
D[9130] = {"Des marchandises de Lune-d'argent",{"Remettre le Bordereau de chargement de l'intendante Lymel au maître du ciel Vol-solaire, à Tranquillien."}}
D[9131] = {"Armer un cuirassier",{"Korfax, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut 30 Morceaux de sombrefer."}}
D[9132] = {"Des morceaux de sombrefer",{"Pour chaque brassée de ces morceaux que vous m'apporterez, je vous donnerai un insigne - le plus sera le mieux. Hors de ma vue maintenant, avant que je vous tranche en deux !"}}
D[9133] = {"Un vol jusqu'à Lune-d'argent",{"Acheter un vol pour Lune-d'argent et remettre le Bordereau de chargement de l'intendante Lymel à Sathren Aube-azur, à Lune-d'argent."}}
D[9134] = {"La maîtresse du ciel Tombejour",{"Apporter la Cargaison de l'intendante Lymel à la maîtresse du ciel Tombejour, à l'extérieur de la Porte du berger à Lune-d'argent."}}
D[9135] = {"Retour à l'intendante Lymel",{"Acheter un vol de retour vers Tranquillien dans les Terres fantômes, et remettre la Cargaison de l'intendante Lymel à l'intendante Lymel, à Tranquillien."}}
D[9136] = {"La flore sauvage",{"Rayne de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est veut 30 Palmes sauvages."}}
D[9137] = {"Des palmes sauvages",{"Pour chaque fagot de palmes que vous me livrerez, je vous payerai avec un insigne de votre choix, de l’Aube ou de la Croisade.","","Les insignes peuvent être échangés auprès des intendants contre toutes sortes de récompenses."}}
D[9138] = {"Le village de Solcouronne",{"Tuez 10 Gardes nérubis, puis retournez voir l'arcaniste Vandril à Tranquillien dans les Terres fantômes."}}
D[9139] = {"Brume-d'or",{"Vaincre 6 Fantômes quel'dorei et 4 Âmes en peine quel'dorei au village de Brume-d'or, puis retourner voir l'arcaniste Vandril à Tranquillien, dans les Terres fantômes."}}
D[9140] = {"Coursevent",{"Collectez 6 Substances fantasmatiques et 4 Fragments de gargouille. Rapportez-les à l'arcaniste Vandril à Tranquillien dans les Terres fantômes."}}
D[9141] = {"On m'appelle \"Le Coq\"",{"Le commandant d'ordonnance Metz, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut une Marque de valeur de l'Aube d'argent."}}
D[9142] = {"Commission d'artisan",{"Vous savez comment ça se passe, mon petit. Pour une marque de valeur, vous recevez une commission d'artisan."}}
D[9143] = {"S'occuper de Zeb'Sora",{"Collecter 6 Oreilles de trolls de Zeb'Sora et les remettre au Forestier Valanna dans les Terres fantômes."}}
D[9144] = {"Disparu dans les terres Fantômes",{"Suivez la route qui part du village de Brise-Clémente vers le sud. Lorsque vous approcherez les Terres Fantômes, cherchez le Courrier Aube-glorieuse."}}
D[9145] = {"Il faut aider le forestier Valanna !",{"Trouver le forestier Valanna et le lieutenant Tomathren sur la rive du lac Elrendar, dans les Terres fantômes, près du village de Solcouronne."}}
D[9146] = {"Un rapport pour le capitaine Hélios",{"Parler au capitaine Hélios à l'enclave des Pérégrins, sur la rive sud du lac Elrendar, dans les Terres fantômes."}}
D[9147] = {"Le courrier blessé",{"L'apothicaire Thedra du bois des Chants éternels veut que vous lui apportiez 4 Échantillons de sang pestiféré pris sur les bêtes des Terres fantômes."}}
D[9148] = {"Livraison à Tranquillien",{"Apportez la Lettre de Lune-d’Argent à l’arcaniste Vandril à Tranquillien, dans les Terres Fantômes."}}
D[9149] = {"La côte pestiférée",{"Apportez 6 Epines dorsales de murlocs pestiférés à l'apothicaire Renzithen, à Tranquillien dans les Terres fantômes."}}
D[9150] = {"Les dépouilles du passé",{"Le magistère Darenis veut que vous vous rendiez au sanctum de la Lune, à l'ouest de Tranquillien, et que vous récupériez 8 Essences de mana cristallisées sur les Dévoreurs arcaniques et les Changemana qui occupent les lieux."}}
D[9151] = {"Le sanctum du Soleil",{"Parlez au magistère Idonis au sanctum du Soleil dans les Terres fantômes."}}
D[9152] = {"Les marchandises de Tombal",{"Retrouver la Marchandise de Rathis Tombal et la lui rapporter à Tranquillien dans les Terres fantômes."}}
D[9153] = {"Sous les ombres",{"Surveillez votre carte pour trouver une région subissant une attaque du Fléau. Allez-y et endommagez une nécropole en exterminant les créatures du Fléau aux alentours. Rapportez ensuite 10 de leurs Runes nécrotiques au commandant Thomas Helleran, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9154] = {"La chapelle de l'Espoir de Lumière",{"Apportez l'Annonce de l'appel aux armes au gardien des registres, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9155] = {"Dans la Malebrèche",{"Tuez 10 Affameurs ressuscités et 10 Cannibales dégingandés dans la Malebrèche. Retournez voir le nécrotraqueur Rathiel à Tranquillien dans les Terres fantômes pour obtenir une récompense."}}
D[9156] = {"On recherche : Putrepoing et Luzran",{"Recherchez Putrepoing et Luzran dans les Terres fantômes et tuez-les. Rapportez leurs têtes au nécrotraqueur Rathiel à Tranquillien pour empocher une prime."}}
D[9157] = {"Rituels oubliés",{"Apportez 8 Médaillons du front de mer à Geranis Blancmatin, dans les Terres fantômes."}}
D[9158] = {"Les porteurs de la peste",{"Le pérégrin Sedina, à l'enclave des pérégrins des Terres fantômes, veut que vous tuiez 10 Lynx Griffes-fantômes."}}
D[9159] = {"Circonscrire l'épidémie",{"Le pérégrin Sedina à l'enclave des Pérégrins dans les Terres fantômes veut que vous tuiez 8 Rôdeuses filetoiles et 10 Brumoptères vampiriques."}}
D[9160] = {"Enquête à An'daroth",{"Enquêter dans la région d'An'daroth, tuer 12 Espions des Sentinelles et retourner voir dame Auriférias à Tranquillien dans les Terres fantômes."}}
D[9161] = {"L'ombre du traître",{"Allez à la Flèche d'Aubétoile dans les Terres fantômes et cherchez des indices sur le passé de Dar'Khan."}}
D[9162] = {"Vestiges du passé",{"Retournez voir le forestier Vynna à l'Enclave des pérégrins avec le Journal de Dar'Khan."}}
D[9163] = {"En territoire occupé",{"Volez les Plans des elfes de la nuit : An'daroth, les Plans des elfes de la nuit : An'owyn, et les Plans des elfes de la nuit : Divination contre les sin'dorei, puis retournez voir Dame Auriférias à Tranquillien dans les Terres fantômes."}}
D[9164] = {"Prisonniers de Mortholme",{"Apportez le Breuvage de restauration de Renzithen à Mortholme et venez au secours de l'apprenti Varnis, de l'apothicaire Enith et du forestier Vedoran. Puis retournez voir l'arcaniste Janeda au sanctum du Soleil pour recevoir une récompense."}}
D[9165] = {"Le sauf-conduit",{"Apportez le Sauf-conduit signé au commandant d'ordonnance Metz à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9166] = {"Livrer les plans à An'telas",{"Livrez les Plans des elfes de la nuit au magistère Sylastor à An'telas, dans les Terres fantômes."}}
D[9167] = {"La destruction du Traître",{"Abattez Dar'Khan Drathir à Mortholme et rapportez sa tête au magistère Kaendris, au sanctum du Soleil dans les Terres fantômes."}}
D[9168] = {"Au cœur de Mortholme",{"Détruisez 8 Yeux de Dar’Khan et rendez compte au magistère Idonis, au Sanctum du Soleil dans les Terres fantômes."}}
D[9169] = {"Désactiver An'owyn",{"Récupérez l'Orbe de contrôle du cristal et utilisez-la pour désactiver le Cristal de lune des elfes de la nuit à An'owyn. Retournez ensuite auprès du magistère Sylastor à An'telas, dans les Terres fantômes."}}
D[9170] = {"Les lieutenants de Dar'Khan",{"Le magistère Idonis veut que vous alliez à Mortholme pour tuer Masophet le Noir, Jurion le Menteur, Borgoth le Saigneur et Mirdoran le Déchu. Allez ensuite lui rendre compte du succès de votre mission au sanctum du Soleil, dans les Terres fantômes."}}
D[9171] = {"Il faut que ça croustille !",{"Collectez 5 Pattes d'araignée croustillantes et ramenez-les au maître cuisinier Mouldier à Tranquillien dans les Terres fantômes."}}
D[9172] = {"Un rapport pour le magistère Kaendris",{"Remettre le Journal de Dar'Khan au magistère Kaendris au sanctum du Soleil, dans les Terres fantômes."}}
D[9173] = {"Reprendre la flèche de Coursevent",{"Tuez 8 Acolytes de Mortholme et 10 Forestières déchues, puis retournez voir le Grand exécuteur Mavren à Tranquillien, dans les Terres fantômes."}}
D[9174] = {"Vaincre Aquantion",{"Geranis Blancmatin veut que vous nagiez au fond du lac à l'est de Solcouronne et que vous utilisiez le Paquet de médaillons sur l'Autel de la maîtrise des flots. Invoquez et détruisez l'élémentaire appelé Aquantion, puis retournez voir Geranis."}}
D[9175] = {"Le collier de la Dame",{"Apportez le Collier de la Dame au Grand exécuteur Mavren à Tranquillien dans les Terres fantômes."}}
D[9176] = {"Les ziggourats jumelles",{"Rendez-vous à la Ziggourat sanguinolente et à la Ziggourat hurlante et retrouvez la Pierre de lumière et la Pierre de flammes. Retournez voir le magistère Kaendris au Sanctum du Soleil après avoir récupéré les objets."}}
D[9177] = {"En route pour Fossoyeuse",{"Apportez le Collier de la Dame à dame Sylvanas Coursevent dans le Quartier royal de Fossoyeuse."}}
D[9178] = {"Commission d'artisan - Pierres de lest denses",{"Livrer 120 Pierres de lest denses et la Commission d'artisan - Pierres denses au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9179] = {"Commission d'artisan - Pansières impériales",{"Livrer 3 Pansières impériales et la Commission d'artisan - Pansières impériales au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9180] = {"En route pour Fossoyeuse",{"Apportez le Collier de la Dame à dame Sylvanas Coursevent dans le Quartier Royal de Fossoyeuse."}}
D[9181] = {"Commission d'artisan - Marteaux volcaniques",{"Livrer 3 Marteaux volcaniques et la Commission d'artisan - Marteaux volcaniques au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9182] = {"Commission d'artisan - Haches d'armes énormes en thorium",{"Livrer 3 Haches d'armes énormes en thorium et la Commission d'artisan - Haches d'armes énormes en thorium au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9183] = {"Commission d'artisan - Diadèmes radieux",{"Livrer 3 Diadèmes radieux et la Commission d'artisan - Diadèmes radieux au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9184] = {"Commission d'artisan - Bandeaux corrompus en cuir",{"Livrer 10 Bandeaux corrompus en cuir et la Commission d'artisan - Bandeaux corrompus en cuir au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9185] = {"Commission d'artisan - Renforts d'armure robustes",{"Livrer 25 Renforts d'armure robustes et la Commission d'artisan - Renforts d'armure robustes au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9186] = {"Commission d'artisan - Ceintures corrompues en cuir",{"Livrer 9 Ceintures corrompues en cuir et la Commission d'artisan - Ceintures corrompues en cuir au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9187] = {"Commission d'artisan - Pantalons runiques en cuir",{"Livrer 4 Pantalons runiques en cuir et la Commission d'artisan - Pantalons runiques en cuir au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9188] = {"Commission d'artisan - Pantalons en étoffe lumineuse",{"Livrer 6 Pantalons en étoffe lumineuse et la Commission d'artisan - Pantalons en étoffe lumineuse au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9189] = {"Une livraison au Sépulcre",{"Apporter les Ordres sin'dorei scellés au conseiller Sorrelon au Sépulcre dans la forêt des Pins argentés."}}
D[9190] = {"Commission d'artisan - Bottes en étoffe runique",{"Livrer 8 Bottes en étoffe runique et la Commission d'artisan - Bottes en étoffe runique au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9191] = {"Commission d'artisan - Sacs en étoffe runique",{"Livrer 8 Sacs en étoffe runique et la Commission d'artisan - Sacs en étoffe runique au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9192] = {"Des problèmes aux mines de Terradiance",{"Tuez 8 Gnolls pattenoires, 6 Charognards pattenoires et 4 Chamans pattenoires, puis retournez voir le nécrotraqueur Maltendis à Tranquillien dans les Terres fantômes."}}
D[9193] = {"Enquête dans les catacombes des Amani",{"Enquêter dans les catacombes des Amani et brûler 10 Restes de trolls momifiés, puis retourner voir la Conseillère Valwyn à Tranquillien dans les Terres fantômes."}}
D[9194] = {"Commission d'artisan - Robes en étoffe runique",{"Livrer 8 Robes en étoffe runique et la Commission d'artisan - Robes en étoffe runique au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9195] = {"Commission d'artisan - Charges de sapeur gobelin",{"Livrer 20 Charges de sapeur gobelin et la Commission d'artisan - Charges de sapeur gobelin au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9196] = {"Commission d'artisan - Grenades en thorium",{"Livrer 20 Grenades en thorium et la Commission d'artisan - Grenades en thorium au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9197] = {"Commission d'artisan - Coqs de combat gnome",{"Livrer 4 Coqs de combat gnome et la Commission d'artisan - Coqs de combat gnome au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9198] = {"Commission d'artisan - Tubes en thorium",{"Livrer 14 Tubes en thorium et la Commission d'artisan - Tubes en thorium au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9199] = {"Les jujus trolls",{"Amassez 8 Jujus trolls et rapportez-les au nécrotraqueur Maltendis, à Tranquillien dans les Terres fantômes."}}
D[9200] = {"Commission d'artisan - Potions de mana majeures",{"Livrer 10 Potions de mana majeure et la Commission d'artisan - Potions de mana majeures au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9201] = {"Commission d'artisan - Potions de protection contre les Arcanes supérieures",{"Livrer 15 Potions de protection contre les Arcanes supérieure et la Commission d'artisan - Potions de protection contre les Arcanes supérieures au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9202] = {"Commission d'artisan - Potions de soins majeures",{"Livrer 20 Potions de soins majeure et la Commission d'artisan - Potions de soins majeures au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9203] = {"Commission d'artisan - Flacon de pétrification",{"Livrer 1 Flacon de pétrification et la Commission d'artisan - Flacon de pétrification au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9204] = {"Commission d'artisan - Anguilles pierre-écaille",{"Livrer 40 Anguilles pierre-écaille et la Commission d'artisan - Anguilles pierre-écaille au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9205] = {"Commission d'artisan - Poissons cuirassés",{"Livrer 30 Poissons cuirassés et la Commission d'artisan - Poissons cuirassés au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9206] = {"Commission d'artisan - Anguilles électriques",{"Livrer 30 Anguilles électriques et la Commission d'artisan - Anguilles électriques au maître-fourrier Navrepierre, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9207] = {"Des échantillons de minerai de Terradiance",{"Récupérer 6 charges de Minerai de Terradiance et les apporter au magistère Quallestis au sanctum du Soleil dans les Terres fantômes."}}
D[9208] = {"La Garde sauvage - Arcanum de protection",{"Zanza le Sans-Repos, de Zul'Gurub, veut un Arcanum de protection."}}
D[9209] = {"La Garde sauvage - Arcanum de rapidité",{"Zanza le Sans-Repos, de Zul'Gurub, veut un Arcanum de rapidité."}}
D[9210] = {"La Garde sauvage - Arcanum de focalisation",{"Zanza le Sans-Repos, de Zul'Gurub, veut un Arcanum de focalisation."}}
D[9211] = {"La Garde-glace",{"Mataus la Voix du courroux, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut 10 Insignes de la Croisade et 30 pièces d'or."}}
D[9212] = {"L'évasion des catacombes",{"Escorter le forestier Lilatha jusqu'au capitaine Hélios, à l'enclave des Pérégrins dans les Terres fantômes."}}
D[9213] = {"L'Ombregarde",{"Mataus la Voix du courroux, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut 10 Insignes de la Croisade et 30 pièces d'or."}}
D[9214] = {"Les armes des Ombrepins",{"Récupérer 3 Haches de chasseur de tête, 3 Masses d'exhalombre, 3 Giffres de seigneur des fauves et 3 Bâtons de maléficieur. Rapportez-les au capitaine Hélios, à l'enclave des Pérégrins des Terres fantômes."}}
D[9215] = {"Ramenez-moi la tête de Kel'gash !",{"Remettre la Tête de Kel'gash le Malfaisant au capitaine Hélios, à l'enclave des Pérégrins, dans les Terres fantômes."}}
D[9216] = {"Les cœurs pourrissants",{"Rapporter 10 Cœurs pourrissants à la magistrice Aminel à Tranquillien."}}
D[9217] = {"Encore des cœurs pourrissants"}
D[9218] = {"Poussière de vertèbres",{"Rapportez 10 doses de Poussière de vertèbres à la magistrice Aminel à Tranquillien."}}
D[9219] = {"Encore de la poussière de vertèbres"}
D[9220] = {"La guerre contre Mortholme",{"Tuez 5 Yeux de Dar'Khan, 6 Centurions nérubis et 6 Pleureuses à Mortholme, puis retournez voir le magistère Idonis au sanctum du Soleil dans les Terres fantômes."}}
D[9221] = {"Armes de bataille excellentes - Ami de l'Aube",{"En échange de 30 Insignes de l'Aube et 30 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9222] = {"Armes de bataille épiques - Ami de l'Aube",{"En échange de 110 Insignes de l'Aube et 110 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9223] = {"Armes de bataille excellentes - Honoré auprès de l'Aube",{"En échange de 20 Insignes de l'Aube et 20 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9224] = {"Armes de bataille épiques - Honoré auprès de l'Aube",{"En échange de 75 Insignes de l'Aube et 75 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9225] = {"Armes de bataille épiques - Révéré auprès de l'Aube",{"En échange de 45 Insignes de l'Aube et 45 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9226] = {"Armes de bataille excellentes - Révéré auprès de l'Aube",{"En échange de 7 Insignes de l'Aube et 7 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9227] = {"Armes de bataille excellentes - Exalté auprès de l'Aube",{"En échange de 6 Insignes de l'Aube et 6 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9228] = {"Armes de bataille épiques - Exalté auprès de l'Aube",{"En échange de 27 Insignes de l'Aube et 27 Insignes de la Croisade, vous pouvez choisir un objet du trésor de guerre de l'Aube d'argent."}}
D[9229] = {"Le destin de Ramaladni",{"Entrez dans Naxxramas et découvrez le Destin de Ramaladni."}}
D[9230] = {"L'étreinte de glace de Ramaladni",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut que vous lui rameniez 1 Rune de givre, 1 Saphir bleu et 1 Barre d'arcanite."}}
D[9232] = {"C'est tout ce que j'ai à mon répertoire...",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 2 Runes de givre, 2 Essences d'eau, 2 Saphirs bleus et 30 pièces d'or."}}
D[9233] = {"Le recueil d'Omarion",{"Remettre le Recueil d'Omarion à l'artisan Wilhelm à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9234] = {"Les gantelets plaie-de-glace",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 5 Runes de givre, 12 barres de thorium, 2 barres d'arcanite, 2 Essences d'eau et 200 pièces d'or."}}
D[9235] = {"Les brassards plaie-de-glace",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 4 Runes de givre, 12 barres de thorium, 2 barres d'arcanite, 2 Essences d'eau et 200 pièces d'or."}}
D[9236] = {"La cuirasse plaie-de-glace",{"L’artisan Wilhelm de la chapelle de l’Espoir de Lumière, dans les Maleterres de l’est, veut 8 Runes de givre, 16 barres de thorium, 2 barres d'arcanite, 4 Essences d'eau et 300 pièces d’or. Vous devez aussi être <Exalté/Exaltée> par l’Aube d’argent."}}
D[9237] = {"La cape glaciaire",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 5 Runes de givre, 4 Rouleaux d'étoffe runique, 2 Essences d'eau, 4 Soies d'araignée toilacier et 200 pièces d'or. Vous devez aussi être <Exalté/Exaltée> par l'Aube d'argent."}}
D[9238] = {"Les poignets glaciaires",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 4 Runes de givre, 2 Rouleaux d'étoffe runique, 2 Essences d'eau, 2 Soies d'araignée toilacier et 200 pièces d'or."}}
D[9239] = {"Les gants glaciaires",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 5 Runes de givre, 4 Rouleaux d'étoffe runique, 4 Essences d'eau, 2 Soies d'araignée toilacier et 200 pièces d'or."}}
D[9240] = {"Le gilet glaciaire",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 8 Runes de givre, 8 Rouleaux d'étoffe runique, 6 Essences d'eau, 4 Soies d'araignée toilacier et 300 pièces d'or. Vous devez aussi être <Exalté/Exaltée> par l'Aube d'argent."}}
D[9241] = {"Les brassards polaires",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 4 Runes de givre, 12 Cuirs enchantés, 3 Essences d'eau, 3 Peaux robustes traitées et 200 pièces d'or."}}
D[9242] = {"Les gants polaires",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 5 Runes de givre, 12 Cuirs enchantés, 3 Essences d'eau, 3 Peaux robustes traitées et 200 pièces d'or."}}
D[9243] = {"La tunique polaire",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 8 Runes de givre, 16 Cuirs enchantés, 5 Essences d'eau, 5 Peaux robustes traitées et 300 pièces d'or. Vous devez aussi être <Exalté/Exaltée> par l'Aube d'argent."}}
D[9244] = {"Les brassards glacécaille",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 4 Runes de givre, 16 Ecailles de scorpide épaisses, 5 Essences d'eau, 3 Peaux robustes traitées et 200 pièces d'or."}}
D[9245] = {"Les gantelets glacécaille",{"L’artisan Wilhelm de la chapelle de l’Espoir de Lumière, dans les Maleterres de l’est, veut 5 Runes de givre, 16 Ecailles de scorpide épaisses, 5 Essences d'eau, 3 Peaux robustes traitées et 200 pièces d’or."}}
D[9246] = {"La cuirasse glacécaille",{"L'artisan Wilhelm de la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est, veut 8 Runes de givre, 24 Ecailles de scorpide épaisses, 7 Essences d'eau, 5 Peaux robustes traitées et 300 pièces d'or. Vous devez aussi être <Exalté/Exaltée> par l'Aube d'argent."}}
D[9247] = {"L'appel du Gardien",{"Rapportez cette lettre au gardien des registres, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9248] = {"Une humble offrande",{"Aurel Feuilledor du Fort cénarien, en Silithus, veut que vous lui apportiez 1 Sceptre abyssal. Vous devez également être Honoré par le Cercle cénarien."}}
D[9249] = {"40 bons - Schéma : Commande de chariotte à vapeur"}
D[9250] = {"La hampe d'Atiesh",{"Trouvez quelqu'un pour vous aider à récupérer les deux dernières parties du bâton, et pour le débarrasser du mal qui l'habite."}}
D[9251] = {"Atiesh, le grand bâton souillé",{"Anachronos, aux Grottes du temps en Tanaris, veut la Tête d’Atiesh et le Talon d’Atiesh."}}
D[9252] = {"La défense de Brise-Clémente",{"Tuer 4 Maraudeurs moignons-pourris et 4 Sombres âmes en peine, puis retourner voir le forestier Sareyn au village de Brise-Clémente dans le bois des Chants éternels."}}
D[9253] = {"Le garderune Deryan",{"Parler au garderune Deryan, dans le bois des Chants éternels, près de la frontière des Terres Fantômes."}}
D[9254] = {"L'apprentie égarée",{"Parler à l'apprentie Mirveda au Sanctum oriental dans le bois des Chants éternels."}}
D[9255] = {"Les notes de recherche",{"Apporter les Notes de recherche à la magistrice Landra Aube-glorieuse au village de Brise-clémente, dans le bois des Chants éternels."}}
D[9256] = {"Le village de Brise-Clémente",{"Parler au forestier Degolien, au village de Brise-Clémente, dans le bois des Chants éternels."}}
D[9257] = {"Atiesh, le grand bâton du Gardien",{"Anachronos, aux Grottes du temps en Tanaris, veut que vous emportiez Atiesh, le grand bâton du Gardien, à Stratholme et que vous le placiez sur la Terre consacrée. Abattez l’entité qui sera extraite du bâton et retournez le voir."}}
D[9258] = {"Le bosquet incendié",{"Trouver Larianna Ruissevent près du Bosquet incendié, au sud-ouest du bois des Chants éternels."}}
D[9259] = {"Un traître envers la Voile sanglante"}
D[9260] = {"Enquêter au sujet du Fléau à Stormwind",{"Se procurer trois Pierres nécrotiques pâles du Fléau à l'extérieur de Hurlevent et enquêter au sujet des cercles runiques lumineux près du campement."}}
D[9261] = {"Enquêter au sujet du Fléau à Forgefer",{"Se procurer trois Pierres nécrotiques pâles du Fléau à l'extérieur de Forgefer et enquêter au sujet des cercles runiques lumineux près du campement."}}
D[9262] = {"Enquêter au sujet du Fléau à Darnassus",{"Se procurer trois Pierres nécrotiques pâles du Fléau à l'extérieur de Darnassus et enquêter au sujet des cercles runiques lumineux près du campement."}}
D[9263] = {"Enquêter au sujet du Fléau à Orgrimmar",{"Se procurer trois Pierres nécrotiques pâles du Fléau à l'extérieur d'Orgrimmar et enquêter au sujet des cercles runiques lumineux près du campement."}}
D[9264] = {"Enquêter au sujet du Fléau aux Pitons du Tonnerre",{"Se procurer trois Pierres nécrotiques pâles du Fléau à l'extérieur des Pitons du Tonnerre et enquêter au sujet des cercles runiques lumineux près du campement."}}
D[9265] = {"Enquêter au sujet du Fléau à Fossoyeuse",{"Se procurer trois Pierres nécrotiques pâles du Fléau à l'extérieur de Fossoyeuse et enquêter au sujet des cercles runiques lumineux près du campement."}}
