D[9272] = {"L'habit fait le boucanier"}
D[9274] = {"Les esprits des noyés",{"Le forestier Krenn'an, à l'enclave des Pérégrins dans les Terres fantômes, veut que vous tuiez 8 Apparitions vengeresses et 8 Apparitions voraces dans le lac voisin."}}
D[9275] = {"Une petite pointe d'assaisonnement",{"Empoisonnez la nourriture de troll aux camps de Zeb'Nowa, puis retournez voir l'apothicaire Venustus à l'enclave des Pérégrins, dans les Terres fantômes."}}
D[9276] = {"L'attaque de Zeb'Tela",{"Tuez 8 Exhalombres Ombrepins et 8 Chasseurs de têtes Ombrepins, puis retournez voir le pérégrin Solanna à l'enclave des Pérégrins des Terres fantômes."}}
D[9277] = {"L'assaut de Zeb'Nowa",{"Tuez 10 Seigneurs des fauves Ombrepins et 10 Maléficieurs Ombrepins, puis retournez voir le pérégrin Solanna à l'enclave des Pérégrins des Terres fantômes."}}
D[9278] = {"Bienvenue !",{"Apporter le Bon-cadeau du Guet d'azur à Jaeleil au Guet d'azur."}}
D[9279] = {"Vous avez survécu !",{"Parler à Proenitus au Point d'impact, dans le val d'Ammen."}}
D[9280] = {"Recharger les cristaux de soin",{"Extraire 8 Fioles de sang de phalène sur les Phalènes du val, puis les donner à Proenitus, au Point d'impact du val d'Ammen."}}
D[9281] = {"Faire place nette",{"L'apprenti Vor'el, au domaine d'Andilien dans les Terres fantômes, veut que vous tuiez 10 Filetoiles supérieures et 10 Ravageurs Griffes-fantômes."}}
D[9282] = {"L'enclave des Pérégrins",{"Le magistère Kaendris du sanctum du Soleil veut que vous parliez au forestier Vynna, à l'enclave des Pérégrins des Terres fantômes."}}
D[9283] = {"Sauvez les rescapés !",{"Servez-vous du Don des naaru sur l'un des Survivants draeneï éparpillés dans le val d'Ammen, puis retournez voir Zalduun au Point d'impact du val d'Ammen."}}
