D[9291] = {"La formation du prêtre"}
D[9292] = {"Cristal nécrotique fêlé",{"Apportez le Cristal nécrotique fêlé au lieutenant Orrin à l'extérieur des portes de Hurlevent."}}
D[9293] = {"Ce qui doit être fait...",{"Rassemblez 10 Échantillons de fouette-racines et rapportez-les à la botaniste Taerix, au point d'impact du val d'Ammen."}}
D[9294] = {"Guérir le lac",{"Répandez le Produit neutralisant près du Cristal de puissance irradié. Ensuite, retournez voir la botaniste Taerix au point d'impact du val d'Ammen."}}
D[9295] = {"Une lettre du front",{"Apportez la Lettre déchirée au gardien des registres à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9299] = {"Une note du front",{"Apportez la Note détériorée au gardien des registres à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9300] = {"Une page du front",{"Apportez la Page abîmée au gardien des registres à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9301] = {"Une enveloppe du front",{"Apportez l'Enveloppe tachée de sang au gardien des registres à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9302] = {"Une missive du front",{"Apportez la Missive froissée au gardien des registres à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9303] = {"Inoculation",{"Utilisez le Cristal d'inoculation sur 6 Chouettides nidebois. Retournez ensuite auprès du redresseur de torts Aldar au Point d'impact du val d'Ammen."}}
D[9304] = {"Un document du front",{"Apportez le Document taché au gardien des registres à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[9305] = {"Pièces de rechange",{"Récupérez 4 Pièces de rechange pour l'émetteur puis rapportez-les à la technicienne Zhanaa au Point d'impact du val d'Ammen."}}
D[9309] = {"L'éclaireur disparu",{"Trouvez Tolaan sur l'Ombrecrête du val d'Ammen et parlez-lui."}}
D[9310] = {"Cristal nécrotique voilé",{"Apportez le Cristal nécrotique voilé au lieutenant Rukag dans la cour de Fossoyeuse."}}
D[9311] = {"L'espionne elfe de sang",{"Tuez la Géomètre Candress, puis allez rendre compte au redresseur de torts Aldar, au Point d'impact du val d'Ammen."}}
D[9312] = {"L'émetteur",{"Parlez à la technicienne Zhanaa au point d'impact dans le val d'Ammen."}}
D[9313] = {"En route pour le Guet d'azur",{"Parlez au technicien Dyvuun au Guet d'azur, sur l'île de Brume-azur."}}
D[9314] = {"Une demande du Guet d'azur",{"Parlez à l'hôtesse Chellan au Guet d'azur sur l'île de Brume-azur."}}
D[9315] = {"Anok'suten",{"Tuez Anok'suten et retournez voir l'arcaniste Vandril, à Tranquillien dans les Terres fantômes."}}
D[9317] = {"Pierre à aiguiser consacrée",{"Si vous m’apportez huit runes nécrotiques des envahisseurs du Fléau, je vous fournirais une pierre à aiguiser consacrée. Elle devrait vous être d’une grande utilité pour vos combats contre les serviteurs du roi-liche."}}
D[9318] = {"Huile de sorcier bénite",{"En échange des runes nécrotiques des envahisseurs du Fléau, l’Aube d’argent vous donnera une fiole d’huile de sorcier bénite."}}
D[9319] = {"Une lumière au sein des ombres",{"Trouvez et touchez les feux de joie situés au pic Rochenoire, à Hache-tripes, dans la Scholomance et à Stratholme. Puis retournez voir le gardien des flammes de la fête."}}
D[9320] = {"Potion de mana majeure"}
D[9321] = {"Potion de soins majeure"}
D[9322] = {"Feux sauvages en Kalimdor",{"Visitez les campements du solstice d'été en Azshara, en Silithus, au cratère d'Un'Goro et à Berceau-de-l'Hiver, puis revenez voir le Gardien des flammes."}}
D[9323] = {"Feux sauvages dans les Royaumes de l'est",{"Rendez visite aux campements de la fête du Feu situés dans les Terres foudroyées, les Maleterres de l'est, les Hinterlands, et la gorge des Vents brûlants, puis allez parler au gardien des flammes de la fête."}}
D[9324] = {"Voler la flamme d'Orgrimmar",{"Rapportez la Flamme d'Orgrimmar au Maître des traditions."}}
D[9325] = {"Voler la flamme de Thunder Bluff",{"Rapportez la flamme des Pitons du Tonnerre au Maître des traditions."}}
D[9326] = {"Voler la flamme de Fossoyeuse",{"Rapportez la flamme de Fossoyeuse au Maître des traditions."}}
D[9327] = {"Les Réprouvés",{"Allez parler au Grand exécuteur Mavren à Tranquillien, dans les Terres fantômes."}}
D[9328] = {"Un héros parmi les Sin'dorei",{"Apportez la Tête de Dar’Khan à Lor’themar Theron, à Lune-d’Argent."}}
D[9329] = {"Les Réprouvés",{"Allez parler au Grand exécuteur Mavren à Tranquillien, dans les Terres Fantômes."}}
D[9330] = {"Voler la flamme de Stormwind",{"Rapportez la flamme de Hurlevent au Conteur de la fête."}}
D[9331] = {"Voler la flamme d'Ironforge",{"Rapportez la flamme de Forgefer au Conteur de la fête."}}
D[9332] = {"Voler la flamme de Darnassus",{"Rapportez la flamme de Darnassus au Conteur de la fête."}}
D[9333] = {"Les gants de l'Aube d'argent",{"Si vous m'apportez trente runes nécrotiques, je vous donnerai en échange une pièce d'armure de main au choix. Vous devriez les trouver très pratiques pour vous battre contre les morts-vivants du Fléau."}}
D[9334] = {"Huile de sorcier bénite",{"En échange des runes nécrotiques des envahisseurs du Fléau, l’Aube d’argent vous donnera une fiole d’huile de sorcier bénite."}}
D[9335] = {"Pierre à aiguiser consacrée",{"Si vous m’apportez huit runes nécrotiques des envahisseurs du Fléau, je vous fournirai une pierre à aiguiser consacrée. Elle devrait vous être d’une grande utilité pour vos combats contre les serviteurs du roi-liche."}}
D[9336] = {"Potion de soins majeure"}
D[9337] = {"Potion de mana majeure",{"En plus de nos autres fournitures, nous disposons de quelques potions de mana majeures qui pourraient vous être utiles. Je vous en donnerai une en échange de quinze runes nécrotiques."}}
D[9338] = {"Allégeance au Cercle cénarien",{"Même si vous n'avez pas besoin des récompenses matérielles que nous proposons, ces badges sont la marque de notre amitié et de notre confiance mutuelle.","","Apportez-les-moi. Je ne manquerai pas de prendre note des services que vous nous rendrez s'ils allaient au-delà de l'appel du devoir."}}
D[9339] = {"La récompense d'un voleur"}
D[9340] = {"La Grande fissure",{"Le capitaine des forestiers Venn'ren du Guet de l'épervier veut que vous tuiez 8 Jeunes fauchepierre et 3 Alphas fauchepierre à la Grande fissure, à l'est du Guet de l'épervier."}}
D[9341] = {"Tabard de l'Aube d'argent",{"Vous avez grandement aidé notre cause, <nom>. Si vous le souhaitez, je peux vous procurer le tabard de l'Aube d'argent. Nous sommes fiers de vous compter parmi nos alliés."}}
D[9342] = {"Les perceurs de croûte maraudeurs",{"Le contremaître Razelcraz, des mines près de Thrallmar, veut que vous tuiez 15 Perceurs de croûte maraudeurs. Les vers ont tendance à attaquer brutalement à partir de leurs tunnels souterrains."}}
D[9343] = {"Tabard de l'Aube d'argent",{"Vous avez grandement aidé notre cause, <nom>. Si vous le souhaitez, je peux vous procurer le tabard de l'Aube d'argent. Nous sommes fiers de vous compter parmi nos alliés."}}
D[9344] = {"Un départ précipité",{"La prophétesse Regulkut veut que vous retrouviez son élève Grelag."}}
D[9345] = {"Préparation du baume",{"Cueillez 12 Atrics des flammes infernales pour un baume et retournez voir Grelag au Poste de Brise-échine."}}
D[9346] = {"Quand les sangliers voleront",{"Le commandant de la garde Krunk, de Thrallmar, veut 10 Carcasses dodues de sanglier infernal, prises sur les Sangliers infernaux affamés."}}
D[9349] = {"Ramasser les œufs de ravageurs",{"Récupérez 12 Œufs de ravageurs pour le compte de Legassi, de l'épave du zeppelin dans la péninsule des Flammes infernales."}}
D[9351] = {"Les marcheurs du Vide sauvages",{"Remettez 10 Essences de marcheur du Vide condensées à Laïus \"Brailleur\" Airbuse à l'épave du zeppelin."}}
D[9352] = {"Les intrusions darnassiennes",{"Rendez-vous au Sanctum occidental, au sud-ouest de la Place de l'Épervier, et tuez les intrus s'il y en a. Ensuite, allez faire votre rapport à la telluriste Velania."}}
D[9355] = {"Un boulot pour un type intelligent",{"Tuer 15 Perceurs de croûte maraudeurs, puis retourner voir le contremaître Biggums au bastion de l'Honneur."}}
D[9356] = {"Les doigts dans le nez",{"Apportez 12 Ailes de busard dodues à Legassi à l'épave du zeppelin."}}
D[9357] = {"Se présenter à Aeldon Signesol",{"Présentez-vous à Aeldon Signesol à la porte elfique intérieure, dans le bois des Chants éternels."}}
D[9358] = {"Le forestier Sareyn",{"Présentez-vous au forestier Sareyn, à l’extérieur du village de Brise-Clémente, dans le bois des Chants éternels."}}
D[9359] = {"La Retraite des pérégrins",{"Présentez-vous au lieutenant Coursaurore à la Retraite des Pérégrins, dans le bois des Chants éternels."}}
D[9360] = {"L'invasion des Amani",{"Remettre les Plans d'invasion amani au lieutenant Coursaurore à la Retraite des pérégrins."}}
D[9361] = {"On se régale avec le sanglier infernal !",{"Legassi de l'Épave du zeppelin veut que vous récupériez 8 morceaux de Viande de sanglier infernal purifiée. Pour purifier la viande, utilisez la Mixture de purification sur la Viande de sanglier infernal contaminée que vous prendrez sur des Sangliers infernaux."}}
D[9362] = {"Le seigneur de guerre Krellian",{"Récupérez la Coquille prismatique pour l'archimage Xylem. L'archimage réside dans une tour au sommet des falaises d'Azshara."}}
D[9363] = {"Avertir le village de Brise-clémente",{"Rendez-vous au village de Brise-clémente dans le bois des Chants éternels et parlez au forestier Degolien."}}
D[9364] = {"Magie morcelée",{"Métamorphosez les Fouette-bile d'Azshara, puis tuez les clones qui apparaissent quelques instants plus tard. Quand vous aurez tué 50 clones de métamorphose, retournez voir l'archimage Xylem en Azshara."}}
D[9365] = {"La récompense d'un voleur"}
D[9366] = {"Il nous faut du gangresang",{"Ryathen le Sombre, du Guet de l'épervier dans la péninsule des Flammes infernales, veut que vous lui procuriez 6 Échantillons de grangresang prélevés sur les Fiels de la terreur qui vivent aux bassins d'Aggonar."}}
D[9367] = {"La fête du Feu",{"Touchez les feux de joie à l'intérieur de Hurlevent, Forgefer et Darnassus, puis parlez à n'importe quel Maître des traditions de la fête dans une des capitales."}}
D[9368] = {"La fête du Feu",{"Touchez les feux de joie à l'intérieur d'Orgrimmar, des Pitons du Tonnerre et de Fossoyeuse, puis parlez à n'importe quel Maître des traditions de la fête dans une des capitales."}}
D[9369] = {"Recharger les cristaux de soin",{"Extraire 8 Fioles de sang de phalène sur les Phalènes du val, puis les rapporter à Proenitus, au Point d'impact du val d'Ammen."}}
D[9370] = {"Il faut arrêter la purification",{"Placez la Gemme de signalisation près de l'autel d'Aggonar, aux bassins d'Aggonar, et triomphez de tous les anachorètes draeneï qui répondront à vos invocations. Retournez voir Ryathen le Sombre au Guet de l'épervier avec la Gemme de signalisation quand vous en aurez terminé."}}
D[9371] = {"La botaniste Taerix",{"Parlez à la botaniste Taerix au Point d'impact dans le val d'Ammen."}}
D[9372] = {"Contamination démoniaque",{"Thiah Crin-rouge, du Poste cénarien dans la péninsule des Flammes infernales, vous a demandé de récupérer 6 Échantillons de sang de sanglier infernal sur des Sangliers infernaux massifs."}}
D[9373] = {"La missive manquante",{"Remettre l'Etui en cuir rongé à Thiah Crin-rouge, qui campe près des ruines de Sha'naar, dans l'ouest de la péninsule des Flammes infernales."}}
D[9374] = {"Le journal d'Arelion",{"La magistrice Carinda, au Guet de l'épervier de la péninsule des Flammes infernales, veut que vous vous rendiez aux bassins d'Aggonar pour y récupérer le Journal d'Arelion."}}
D[9375] = {"La route du Guet de l'épervier",{"Protégez le Pèlerin elfe de sang blessé sur la route du Guet de l'épervier, puis parlez à Taleris Mirelaube."}}
D[9376] = {"Les souffrances du pèlerin",{"Le Pèlerin elfe de sang blessé a été attaqué par des Ravageurs Plumecroc alors qu'il se trouvait dans le ravin de Plumepoussière. Trouvez son campement et fouillez-le à la recherche de son sac manquant."}}
D[9378] = {"DND FLAG Naxxramas, la citadelle de l'effroi",{"L'archimage Angela Dosantos à la chapelle de l'Espoir de Lumière dans les Maleterres de l'Est vous accordera gratuitement l'Occultation arcanique. Vous devez être <Exalté/Exaltée> auprès de l'Aube d'argent."}}
D[9380] = {"La multiplication des molosses",{"Récupérer 6 Cadavres de molosses dimensionnels intacts et les remettre au prospecteur Murantus au bastion de l'Honneur."}}
D[9381] = {"Les flèches infaillibles",{"Récupérez 8 Plumes de queue de gratte-les-os sur des vautours Gratte-les-os, et remettez-les au fauconnier Drenna Ruissevent du Guet de l'épervier."}}
D[9382] = {"Le sort des sabots-fourchus",{"Tuer 15 Sabots-fourchus poil-hirsute, puis retourner voir Amaan le sage au temple de Telhamat."}}
D[9383] = {"Un plan ambitieux",{"Utilisez le Cristal sanctifié sur un marcheur du Vide incontrôlé blessé, puis retournez voir Elsaana au temple de Telhamat."}}
D[9385] = {"Les ravageurs déchaînés",{"Tuez 10 Ravageurs Plumecroc et retournez voir Gremni Barbe-longue dans la péninsule des Flammes infernales."}}
D[9386] = {"Une Lumière au sein des ombres",{"Trouvez et touchez les feux de joie situés au pic Rochenoire, à Hache-tripes, dans la Scholomance et à Stratholme, puis parlez au gardien des flammes de la fête."}}
D[9387] = {"La source de la corruption",{"Allez aux ruines de Sha'naar, dans la péninsule des Flammes infernales, et obtenez 5 Essences démoniaques sur les Sous-chefs illidari. Retournez voir l'apothicaire Azethen au Guet de l'épervier une fois ce travail terminé."}}
D[9388] = {"Flammes vacillantes en Kalimdor",{"Rendez-vous aux feux de joie d'Orneval, des Tarides, de Sombrivage et des Serres-Rocheuses, puis parlez au Gardien des flammes de la fête."}}
D[9389] = {"Flammes vacillantes dans les Royaumes de l'est",{"Rendez-vous aux feux de joie des contreforts de Hautebrande, de la forêt des Pins argentés, de la Marche de l'ouest et des Paluns, puis parlez au Gardien des flammes de la fête."}}
D[9390] = {"À la recherche de Sedaï",{"L'anachorète Obadeï veut que vous partiez à la recherche de son frère Sedaï dans les alentours, vers l'est, dans la péninsule des Flammes infernales."}}
D[9391] = {"Jalonner le chemin",{"Le capitaine des forestiers Venn’ren, du Guet de l’épervier, veut que vous alliez dans la Grande fissure de la péninsule des Flammes infernales et que vous allumiez la Balise du sud, la Balise de l’ouest, et la Balise centrale. Retournez le voir avec la Torche allumée quand vous aurez accompli cette tâche."}}
D[9392] = {"La formation de voleur",{"Parlez à l'éclaireur Kariel, le maître des voleurs, à l'intérieur de la Flèche solaire de l'île de Haut-soleil."}}
D[9393] = {"La formation de chasseur",{"Parlez au forestier Sallina, le maître des chasseurs, à l'intérieur de la Flèche solaire de l'île de Haut-soleil."}}
D[9394] = {"Où est Wyllithen ?",{"Retrouver le paysagiste Wyllithen sur les Terres de Ternesoir dans le bois des Chants éternels."}}
D[9395] = {"Le havre de Saltheril",{"Parler au seigneur Saltheril au havre de Saltheril dans le bois des Chants éternels."}}
D[9396] = {"La magie des arakkoa",{"L'arcaniste Calesthris Aubétoile, du Guet de l'épervier de la péninsule des Flammes infernales, veut que vous lui rameniez 4 Parchemins haal'eshi."}}
D[9397] = {"Fermez, fermez la cage aux oiseaux",{"Rendez-vous à la tanière des Haal'esh dans la péninsule des Flammes infernales et fouillez les nids de kaliris à la recherche d'une Jeune femelle kaliri. Utilisez la Cage à oiseaux vide pour la capturer et apportez-la au fauconnier Drenna Ruissevent au Guet de l'épervier."}}
D[9398] = {"Prédateurs mortels",{"L'éclaireur Vanura du temple de Telhamat dans la péninsule des Flammes infernales veut que vous tuiez 8 Jeunes fauchepierre et 4 Alphas fauchepierre."}}
D[9399] = {"De cruels sous-chefs",{"Tuez 4 Sous-chefs illidari aux ruines de Sha'naar, puis retournez voir Ikan au temple de Telhamat, dans la péninsule des Flammes infernales."}}
D[9400] = {"L'assassin",{"Nazgrel veut que vous suiviez la route qui passe au nord de la citadelle des Flammes infernales, à la recherche d'un assassin nommé Krun Brise-échine."}}
D[9401] = {"Une arme étrange",{"Remettre la Hache lourde en pierre à Nazgrel, à Thrallmar dans la péninsule des Flammes infernales."}}
D[9402] = {"Va chercher !",{"Nagez jusqu'au fond de l'étang des Murmures-sereins et récupérez la Fiole azur pour l'instructeur Antheol."}}
D[9403] = {"L'eau pure",{"[Instructor Antheol wants you to fill the Azure Phial at Elrendar Falls.]"}}
D[9404] = {"Fraîchement coupée",{"Tuez les Gardes verts des Chants éternels jusqu'à ce que vous trouviez une Branche vivante pour l'instructeur Antheol."}}
D[9405] = {"Le mandat du chef de guerre",{"Apporter la Hache lourde en pierre à la prophétesse Regulkut, à Thrallmar dans la péninsule des Flammes infernales."}}
D[9406] = {"Les Mag'har",{"Remettez la lettre des Mag’har à Nazgrel, à Thrallmar dans la péninsule des Flammes infernales."}}
D[9407] = {"À travers la Porte des ténèbres",{"Traversez la Porte des ténèbres et allez trouver le général de division Orion. Il attend votre arrivée de l'autre côté, en Outreterre."}}
D[9408] = {"Héros oubliés",{"Parler au commandant Danath Trollemort au bastion de l'Honneur."}}
D[9409] = {"Livraison urgente",{"Livrer le Paquet de fioles à Zalduun au Point d'impact du val d'Ammen."}}
D[9410] = {"Un guide spirituel",{"Utilisez le Totem du loup à l'endroit où vous avez trouvé le corps de Krun Brise-échine et suivez l'Esprit ancestral du loup."}}
D[9415] = {"Se présenter au maréchal Murbleu",{"Parlez au maréchal Murbleu au campement de l'Alliance, près de la Ruche'Zora."}}
D[9416] = {"Se présenter au général Kirika",{"Parlez au général Kirika au campement de la Horde, près de la Ruche'Regal."}}
D[9417] = {"La menace des arakkoa",{"Gremni Barbe-longue veut que vous tuiez 4 Marche-vent haal'eshi et 6 Gardes-serres haal'eshi."}}
D[9418] = {"L'orbe d'Avruu",{"Apportez l'Orbe d'Avruu à l'Autel haal'eshi, au sud-est de la tanière des Haal'esh, sur la péninsule des Flammes infernales. Remettez-le à Aeranas lorsqu'il sera libre."}}
D[9419] = {"Passer le désert au peigne fin",{"Trouver de la Silithyste et la livrer à l' Extracteur de silithyste, puis parler au maréchal Murbleu au campement de l'Alliance près de la Ruche'Zora."}}
D[9420] = {"Les plus belles plumes",{"Mirren Barbe-longue, de la péninsule des Flammes infernales, veut que vous lui rapportiez 8 Plumes de kaliri, prises sur les kaliris de la Tanière des Haal'esh."}}
D[9421] = {"La formation de chaman"}
D[9422] = {"Passer le désert au peigne fin",{"Trouver de la Silithyste et la livrer à un Extracteur de silithyste, puis parler au général Kirika au campement de la Horde près de Ruche'Regal."}}
D[9423] = {"Retourner voir Obadeï",{"Retournez voir l'anachorète Obadeï au temple de Telhamat dans la péninsule des Flammes infernales, et apprenez-lui la mort de Sedaï."}}
D[9424] = {"La vengeance de Makuru",{"Makuru, au temple de Telhamat dans la péninsule des Flammes infernales, veut que vous lui rameniez 10 Perles ancestrales Mag'har."}}
D[9425] = {"Présentez-vous au Moulin-de-Tarren",{"Rendez-vous à Moulin-de-Tarren, dans les contreforts de Hautebrande, et parlez à la conseillère Brunaurore."}}
D[9426] = {"Les bassins d'Aggonar",{"Amaan le Sage veut que vous vous rendiez aux bassins d'Aggonar pour y tuer 6 Fiels de la terreur et 6 Pourritures caustiques."}}
D[9427] = {"Purifier les eaux",{"Amaan le Sage veut que vous vous rendiez aux Bassins d’Aggonar et que vous utilisiez la Fiole de purification sur le cadavre d’Aggonar. Retournez le voir lorsque l’eau aura purifié l’essence d’Aggonar."}}
D[9428] = {"Présentez-vous au poste de Bois-brisé",{"Rendez-vous au poste de Bois-brisé en Orneval et parlez au conseiller Ligesol."}}
D[9429] = {"En route pour Sombre-comté",{"Rendez-vous à Sombre-comté dans le bois de la Pénombre et parlez à l'anachorète Delan."}}
D[9430] = {"Les reliques de Sha'naar",{"Amaan le Sage, au Temple de Telhamat dans la Péninsule des Flammes infernales, veut que vous vous rendiez aux ruines de Sha'naar pour y récupérer 10 Reliques de Sha'naar."}}
D[9431] = {"Une nouvelle approche",{"Récupérez 2 poignées de Terre purificatrice sur les Eboulides fulminants, et remettez-les à Wizlo Braquecoquard au poste de Blanc-relais."}}
D[9432] = {"En route pour Astranaar",{"Rendez-vous à Astranaar en Orneval, et parlez au redresseur de torts Palanaar."}}
D[9433] = {"A Dip in the Moonwell",{"Use the Robotron Control while standing near the Concealed Command Console hidden in a small cluster of bushes on the rim of the needle closest to Thalanaar to take command of a Robotron 3000. Pilot the robot to the western edge of Thousand Needles where the Alliance outpost of Thalanaar is located. Use the robot to collect a sample of the moonwell's water and return it to Wizlo Bearingshiner at Whitereach Post."}}
D[9434] = {"Tester le tonique",{"Livrez la Caisse de composants à la magistrice Elosai au poste de Librevent."}}
D[9435] = {"Les cristaux manquants",{"Reprenez le Chargement de cristaux rares aux Réprouvés et rapportez-le à Huraan à Austrivage."}}
D[9436] = {"Étudier les Scalps-rouges",{"Nemeth Œil-de-faucon au campement Grom’gol veut que vous lui rameniez un Totem scalp-rouge pris sur un Chaman scalp-rouge."}}
D[9437] = {"Le crépuscule du Coureur de l'aube",{"Balandar Brillétoile, à Mur-de-Fougères, veut que vous récupériez la Cargaison du Coureur de l’aube et que vous sauviez son second, Ithania, des troupes de Theramore à la Tour de la halte nord."}}
D[9438] = {"Messenger to Thrall",{"Travel to Orgrimmar and give Thrall the Letter from Nazgrel."}}
D[9439] = {"Des bagages non réclamés",{"Récupérez le Sac du conseiller et la Rapière du conseiller qui se trouvent dans la forteresse d’Angor, et rendez-les au conseiller Sarophas, à Kargath."}}
D[9440] = {"De petites bouchées",{"Donnez des Bouchées gangrenées aux animaux capturés par les Perdus. Ramenez les restes à Cersei Chantebrune, à Pierrêche, dans le marais des Chagrins."}}
D[9441] = {"Émissaire auprès des Mag'har",{"Thrall veut que vous retourniez voir Gorkan Poing-de-sang au poste Mag'har de la péninsule des Flammes infernales, et que vous lui offriez vos services."}}
D[9442] = {"Une maladie débilitante",{"L’imploratrice de la terre Ryga, au poste de Mag'har de la péninsule des Flammes infernales, veut que vous lui rameniez 1 Champignon tête-sèche cueilli dans une caverne de la Grande fissure."}}
D[9443] = {"La pseudo-marque du Porteur de Lumière",{"Obtenez la Marque du Porteur de Lumière et ramenez-la à Mehlar Aubelame à la Barricade dans les Maleterres de l'ouest."}}
D[9444] = {"Profaner la tombe d'Uther",{"Profaner la Tombe d’Uther puis retourner voir Mehlar Aubelame à la Barricade des Maleterres de l’Ouest."}}
D[9446] = {"La tombe d'Uther",{"Escorter l’Anachorète Truuen à la tombe d’Uther, dans les Maleterres de l’ouest. Ensuite, parler avec la grande prêtresse MacDonnell au camp du Noroît dans les Maleterres de l’Ouest."}}
D[9447] = {"Administrer le baume de guérison",{"L’Imploratrice de la terre Ryga veut que vous administriez le Baume de guérison à 10 Grunts Mag'har affaiblis proches du poste Mag'har, dans la péninsule des Flammes infernales."}}
D[9448] = {"Pitié pour les maudits",{"Tuez 3 Perdus maudits avant de retourner voir l'anachorète Avuun au Havre boueux, dans le marais des Chagrins."}}
D[9449] = {"L'appel de la terre",{"Parlez à l’Esprit du val au Bosquet sacré du val d’Ammen."}}
D[9450] = {"L'appel de la terre",{"Tuez 4 Esprits de terre sans repos, puis retournez voir l’Esprit du val au Bosquet sacré du val d’Ammen."}}
D[9451] = {"L'appel de la terre",{"Donnez le Cristal de terre à Firmanvaar, au Point d’impact du val d’Ammen."}}
D[9452] = {"Le lutjan rouge, c'est bon !",{"Utilisez le Filet de pêche draeneï pour attraper 10 Lutjans rouges. Ensuite, retournez voir Diktynna sur l'île de Brume-azur, rendez-lui le filet et donnez-lui les poissons."}}
D[9453] = {"Trouvez Actéon !",{"Livrer la Caisse de lutjans rouges à Actéon au Guet d'azur."}}
D[9454] = {"La grande chasse aux frôle-lune",{"Apportez 6 Filets de cerfs frôle-lune à Actéon du Guet d'azur."}}
D[9455] = {"Une étrange trouvaille",{"Remettez le Cristal luisant faiblement à l'exarque Menelaous, au Guet d'azur."}}
D[9456] = {"Nettoyage des traquenuits, île n°2",{"L'exarque Meleanous du Guet d'azur vous a demandé de tuer 8 Traquenuits chétifs infectés."}}
D[9457] = {"Un protecteur inhabituel",{"Servez-vous du Cadeau de Naïas près de l’Autel de Naïas pour invoquer l’élémentaire d’eau Naïas. Lorsque vous l’aurez vaincu, retournez voir Nemeth Œil-de-faucon au campement Grom’gol avec le Cœur de Naïas."}}
D[9460] = {"Associer ses forces",{"Keltus Sombrefeuille veut que vous fassiez les poches du Chef des Sentinelles, que vous y récupériez un Mouchoir en dentelle et que vous le lui remettiez."}}
D[9461] = {"L'appel du feu",{"Allez voir le prophète Velen, à la Voûte des lumières, à bord de l'Exodar."}}
D[9462] = {"L'appel du feu",{"Allez voir Tuluun au Guet d'Azur, sur l’île de Brume-azur."}}
D[9463] = {"Usage médical",{"L'anachorète Fateema au Guet d'azur veut que vous lui apportiez 8 Vrilles de piègeracine."}}
D[9464] = {"L'appel du feu",{"Parlez à Hargne à la clairière des braises, sur l'île de Brume-d'azur."}}
D[9465] = {"L'appel du feu",{"Récupérez la Torche rituelle et rapportez-la à Hargne à la clairière des braises sur l'île de Brume-d'azur."}}
D[9466] = {"On recherche : Griffe-noire la Sauvage",{"Apportez les Griffes de Griffe-noire au capitaine des forestiers Venn'ren au Guet de l'épervier dans la péninsule des Flammes infernales."}}
D[9467] = {"L'appel du feu",{"Récupérez les Cendres d'Arrogance et rapportez-les avec la Torche rituelle à Hargne, à la clairière des braises sur l'île de Brume-d'azur. N'oubliez pas que vous pouvez utiliser l'Orbe de retour pour vous téléporter auprès de Hargne une fois que vous aurez les cendres."}}
D[9468] = {"L'appel du feu",{"Apportez les Cendres d'Arrogance à Tuluun, au Guet d'azur, sur l'île de Brume-azur."}}
D[9469] = {"L'appui de Barbe-de-plumes",{"Rendez-vous au Taudis de Barbe-de-plumes et allez voir le nain s'il est chez lui. S'il n'est pas là, cherchez des indices pour savoir où vous pourriez le trouver."}}
D[9470] = {"Un geste de bonne volonté",{"L'ambassadeur Rualeth au Nid-de-l'Aigle veut que vous tuiez le Féticheur Mai'jin et son araignée familière Tcha’kaz."}}
D[9471] = {"Faire sa proie des prédateurs",{"L'ambassadeur Rualeth au Nid-de-l'Aigle veut que vous tuiez 10 Crins-d'argent galeux et 5 Loups Crins-d'argent."}}
D[9472] = {"La maîtresse d'Arelion",{"La magistrice Carinda, au Guet de l'épervier, veut que vous attiriez Viera Murmesoleil hors de la ville, puis que vous utilisiez le Parchemin de vindicte de Carinda sur elle."}}
D[9473] = {"Une tentative alternative",{"Daedal au Guet d'azur veut que vous lui apportiez 5 Bulbes de gueules-de-loup azurées."}}
D[9474] = {"La marque du Porteur de Lumière",{"Récupérez la Marque du Porteur de Lumière et rapportez-la à l'anachorète Truuen au camp du Noroît, dans les Maleterres de l'ouest."}}
D[9475] = {"La récupération des œufs",{"[Gather 5 Gryphon Eggs and return them to Ambassador Rualeth at Aerie Peak.]"}}
D[9476] = {"À la poursuite de Barbe-de-plumes",{"Rendez-vous à Shadra'Alor et cherchez-y les traces de Barbe-de-plumes."}}
D[9483] = {"Les plaisirs de la vie"}
D[9484] = {"Dompter la bête",{"Utilisez le Bâtonnet de domptage pour apprivoiser un Faucon-dragon affolé, puis retournez voir le lieutenant Coursaurore."}}
D[9485] = {"Dompter la bête",{"Utilisez le Bâtonnet de domptage pour apprivoiser une Brumoptère, puis retournez voir le lieutenant Coursaurore."}}
D[9486] = {"Dompter la bête",{"Utilisez le Bâtonnet de domptage pour apprivoiser un Ancien Preste-patte, puis retournez voir le lieutenant Coursaurore."}}
D[9487] = {"Les saccageurs des arcanes",{"L'arcaniste Vandril veut que vous récupériez 10 Fragments arcaniques pour son compte."}}
D[9488] = {"Une robe simple",{"L'arcaniste Vandril a besoin de 15 Étoffes de lin et d’une Glande à soie de filetoile."}}
D[9489] = {"Purifier la Malebrèche",{"Lancez Prière de Robustesse sur 6 Forestiers des Chants éternels dans la Malebrèche."}}
D[9490] = {"La matriarche des écorche-roc",{"Prenez les Griffes de Griffe-noire la Sauvage dans la Grande fissure et remettez-les à Ikan, au temple de Telhamat la Péninsule des flammes infernales."}}
D[9491] = {"Cupidité",{"Erelan, à Tranquillien, veut que vous retrouviez la Bague ébréchée en or dans les catacombes des Amani."}}
D[9492] = {"L'heure du tournant",{"Apportez le Poing du chef de guerre Kargath au commandant Danath Trollemort, au Bastion de l'Honneur."}}
D[9493] = {"L'orgueil de la Gangr'horde",{"Le commandant Romus du Bastion de l'Honneur veut que vous alliez tuer 8 Légionnaires de la Main brisée, 4 Centurions de la Main brisée et 4 Champions de la Main brisée."}}
D[9494] = {"Les gangrebraises",{"Le magus Zabraxis du Bastion de l'Honneur veut que vous lui rapportiez une Gangrebraise."}}
D[9495] = {"La volonté du Chef de guerre",{"Nazgrel à Thrallmar veut que vous lui rameniez le Poing du chef de guerre Kargath."}}
D[9496] = {"L'orgueil de la Gangr'horde",{"Le chasseur des ombres Ty'jin, de Thrallmar, veut que vous tuiez 8 Légionnaires de la Main brisée, 4 Centurions de la Main brisée et 4 Champions de la Main brisée."}}
D[9498] = {"Le Guet de l'épervier",{"Présentez-vous au capitaine des forestiers Venn'ren au Guet de l'épervier de la péninsule des Flammes infernales."}}
D[9499] = {"Le Guet de l'épervier",{"Rendez-vous au Guet de l'épervier au sud-ouest de la péninsule des Flammes infernales et présentez-vous au capitaine des forestiers Venn'ren."}}
D[9500] = {"L'appel de l'eau",{"Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur."}}
D[9501] = {"L'appel de l'eau",{"Parlez à Aqueuse, à l’intérieur du Récif caché, près de l’île de Brume-sang."}}
D[9502] = {"L'appel de l'eau",{"Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur."}}
D[9503] = {"L'appel de l'eau",{"Récupérer 6 Essences infectes et les remettre à Aqueuse, au Récif caché, près de l’île de Brume-sang."}}
D[9504] = {"L'appel de l'eau",{"Remplir la Gourde en peau vide et retourner voir Aqueuse, au Récif caché, près de l’île de Brume-sang."}}
D[9505] = {"La prophétie de Velen",{"Daedal veut que vous alliez au sud, à la recherche des gens mentionnés par la créature blessée."}}
D[9506] = {"Il faut bien commencer quelque part",{"L'amiral Odesyus, au Point d'accostage d'Odesyus, veut que vous récupériez le Compas de marine et la Carte nautique volés par la KapitalRisk."}}
D[9508] = {"L'appel de l'eau",{"Apportez la Tête de Tel'athion à Aqueuse, du récif caché près de l'île de Brume-sang."}}
D[9509] = {"L'appel de l'eau",{"Remettez la Flasque de l'eau la plus pure au long-voyant Nobundo à l’intérieur de l’Exodar sur l’île de Brume-azur."}}
D[9510] = {"Les peaux de sabots-fourchus poil-hirsute",{"L’approvisionneur Braknar au poste de Mag'har dans la péninsule des Flammes infernales veut que vous lui rameniez 5 Peaux de sabots-fourchus poil-hirsute."}}
D[9511] = {"Les plans de bataille de Kargath"}
D[9512] = {"Jumbo gumbo du cuistot",{"« Cuistot » McFadesauce, au Point d'accostage d'Odesyus, veut que vous lui rapportiez 6 Chairs de clampant grouillant."}}
D[9513] = {"Reconquérir les ruines",{"La Prêtresse Kyleen Il'dinare, au Point d'accostage d'Odesyus sur l'île de Brume-azur, veut que vous tuiez 5 Myrmidons Irécaille, 5 Nagas Irécaille et 5 Sirènes Irécaille."}}
D[9514] = {"Tablette couverte de runes",{"Apportez la Tablette couverte de runes à la Prêtresse Kyleen Il'dinare au Point d'accostage d'Odesyus, sur l'île de Brume-azur."}}
D[9515] = {"Le seigneur de guerre Sriss'tiz",{"La Prêtresse Kyleen Il'dinare, au Point d'accostage d'Odesyus sur l'île de Brume-azur, veut que vous tuiez le chef de guerre Sriss'tiz."}}
D[9516] = {"Détruire la Légion",{"Tuez 15 démons de n’importe quel type sur la Colline Gangrefeu, dans le Canyon de la Malechute et sur la Crête de la Malechute."}}
D[9517] = {"Un gaspillage honteux",{"Rassemblez 5 fagots de Bois gangrené de Satyrnaar."}}
D[9518] = {"Les agents de la destruction",{"Tuez le Surveillant Gorthak et 12 autres membres de la Horde du Camp de bûcherons Chanteguerre."}}
D[9519] = {"Le calice perdu",{"Récupérez le Calice d’Élune."}}
D[9520] = {"Les plans diaboliques",{"Apportez les Plans diaboliques au Redresseur de torts Vedaar au Camp de bûcherons Chanteguerre, en Orneval."}}
D[9521] = {"Un rapport du front nord",{"Apportez le Rapport de la Sentinelle Melyria à la Sentinelle Chanteloin au Bosquet d’Aile-argent, en Orneval."}}
D[9522] = {"Plus jamais !",{"Récupérez l’Épée de flammes de Gorgannon et la Gangrelance du Chercheur."}}
D[9523] = {"Fragile et précieux - à manipuler avec précaution",{"L'archéologue Adamant Cœur-de-fer, au point d'accostage d'Odesyus sur l'île de Brume-azur, veut que vous lui rameniez 8 Reliques anciennes."}}
D[9524] = {"Prisonnière de la citadelle",{"Sauver le capitaine Alina, à l’intérieur de la citadelle des Flammes infernales, avant son exécution.","","Cette quête doit être accomplie en mode de difficulté du donjon Héroïque."}}
D[9525] = {"Imprisoned in the Citadel",{"Rescue Captain Boneshatter inside Hellfire Citadel before he is executed.","","This quest must be completed in Heroic dungeon difficulty."}}
D[9526] = {"Reprendre la colline Gangrefeu",{"Planter 8 Boutures d'arbre dans les Monticules de terre fertile, puis retourner voir Noueux au Chant des forêts, en Orneval."}}
D[9527] = {"Tout ce qui reste",{"Cowlen, de l'île de Brume-azur, veut que vous retrouviez les Restes de la famille de Cowlen."}}
D[9528] = {"Un appel à l'aide",{"Escorter Magwin à travers l'île, jusqu'à chez elle."}}
D[9529] = {"La Pierre",{"Trouvez une Pierre de Vide dans la Malebrèche."}}
D[9530] = {"Un plan bourgeonne",{"L'amiral Odesyus, au Point d'accostage d'Odesyus sur l'île de Brume-azur, veut que vous lui rameniez un Arbre creux et 5 Piles de feuilles."}}
D[9531] = {"L'art du camouflage ne se perd pas",{"L'amiral Odesyus, au Point d'accostage d'Odesyus de l'île de Brume-azur, veut que vous observiez la rencontre entre Geezle et le traître.","","Retournez le voir lorsque vous connaîtrez l'identité du traître."}}
D[9532] = {"Trouver Keltus Sombrefeuille",{"Trouvez Keltus Sombrefeuille."}}
D[9533] = {"La main tendue",{"Rendez-vous au Chant des forêts, et parlez à l'architecte Nemos."}}
D[9534] = {"Destroy the Legion",{"Slay 15 of any demon type at Felfire Hill, Demon Fall Canyon, or demon Fall Ridge and then return to Valusha at Splintertree Post in Ashenvale."}}
D[9535] = {"Les plans diaboliques",{"Apporter les Plans diaboliques à Valusha au poste de Bois-Brisé en Orneval."}}
D[9536] = {"Plus jamais !",{"Tuer Gorgannon et Diathorus le Chercheur, puis retourner voir Valusha au poste de Bois-brisé en Orneval."}}
D[9537] = {"Le gnominé est...",{"L'amiral Odesyus, du point d'accostage d'Odesyus, veut que vous récupériez la Communication du traître sur l'ingénieur Finemouture, dit « l'Étincelle »."}}
D[9538] = {"Apprendre la langue",{"Lisez le Manuel de langue furbolg calmepin qui vous a été remis par Aurren, puis examinez le Totem d'Akida au Guet d'azur."}}
D[9539] = {"Le totem de Coo",{"Grâce aux indices qui vous ont été fournis, trouvez le totem de Coo."}}
D[9540] = {"Le totem de Tikti",{"Grâce aux indices qui vous ont été fournis, trouvez le totem de Tikti."}}
D[9541] = {"Le totem de Yor",{"Grâce aux indices qui vous ont été fournis, trouvez le totem de Yor."}}
D[9542] = {"Le totem de Vark",{"Grâce aux indices qui vous ont été fournis, trouvez le totem de Vark."}}
D[9543] = {"Expiation",{"Parler à Amaan le Sage, au temple de Telhamat dans la péninsule des Flammes infernales."}}
D[9544] = {"La prophétie d'Akida",{"Libérez 8 Captifs Calmepins des cages du village des Bras-hirsutes. Retournez voir Arugoo des Calmepins au Guet d'azur quand vous aurez accompli cette tâche."}}
D[9545] = {"La relique du prophète",{"Amaan le Sage, du Temple de Telhamat dans la Péninsule des Flammes infernales, veut que vous retourniez auprès du Cadavre de Sedaï, au nord-est du Temple de Telhamat, et que vous utilisiez la Relique du prophète à cet endroit. Revenez le voir quand ce sera fait."}}
D[9547] = {"L'appel de l'air",{"Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur."}}
D[9548] = {"L'équipement chapardé",{"Rapportez l'Equipement de Clopper à Clopper Crackboum, qui se cache dans une carapace de tortue échouée."}}
D[9549] = {"Les artéfacts des Vase noire",{"Apportez 3 Idoles murlocs grossières et 6 Couteaux murlocs grossiers à Clopper Crackboum, qui se cache dans une carapace de tortue échouée."}}
D[9550] = {"Une carte pour où ?",{"Trouvez le pavillon décrit par la carte, et découvrez ce que celui qui l’a dessinée essayait de représenter."}}
D[9551] = {"L'appel de l'air",{"Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur."}}
D[9552] = {"L'appel de l'air",{"Parlez à Velaada au pic Vent-sauvage, sur l’île de Brume-azur."}}
D[9553] = {"L'appel de l'air",{"Parlez à Susurrus au pic Vent-sauvage, sur l’île de Brume-azur."}}
D[9554] = {"L'appel de l'air",{"[Return to Farseer Nobundo at the Exodar on Azuremyst Isle with the Whorl of Air.]"}}
D[9555] = {"L'appel du feu",{"Parlez au long-voyant Nobundo dans le Hall de Cristal, à bord de l'Exodar."}}
D[9556] = {"Au vainqueur...",{"Récupérez une bouteille d'Eau sacrée de Stratholme à l'intérieur de Stratholme, et remettez-la au Mage de Lordaeron, au quartier des mages de Hurlevent ou de Fossoyeuse, lorsque votre camp aura vaincu."}}
D[9557] = {"Déchiffrer le livre",{"Apportez l'Ancien journal de bord à l'Anachorète Paetheus au Guet du sang."}}
D[9558] = {"Les Barbe-longue",{"Cherchez Gremni Barbe-longue au nord-ouest de la tanière des Haal’esh, loin à l’ouest du bastion de l’Honneur de la péninsule des Flammes infernales."}}
D[9559] = {"Le repaire des Calmepins",{"Parlez au Grand chef Calmepin au repaire des Calmepins."}}
D[9560] = {"Les bêtes de l'Apocalypse !",{"Moordo, du repaire des Calmepins de l'île de Brume-azur, veut que vous lui rapportiez 8 Peaux de ravageurs."}}
D[9561] = {"Les mots de Nolkai",{"Trouvez l’endroit décrit dans le journal de Nolkai et découvrez les biens qu’il a enterrés il y a longtemps."}}
D[9562] = {"Pourquoi les murlocs ?",{"Gurf, du repaire des Calmepins sur l'île de Brume-azur, veut que vous retrouviez 5 sacs de Céréales calmepins."}}
D[9563] = {"Gagner la confiance de Mirren",{"Mirren Barbe-longue veut que vous lui procuriez 1 Bière amère de Rempart-du-Néant. Pour achever cette quête, les gens du bastion de l'Honneur doivent être Amicaux envers vous."}}
D[9564] = {"La dignité de Gurf",{"Rapportez la Dignité de Gurf à Gurf au repaire des Calmepins sur l'île de Brume-azur."}}
D[9565] = {"Fouillez le repaire des Calmepins",{"Fouillez le repaire des Calmepins à la recherche d'indices."}}
D[9566] = {"Les cristaux de sang",{"Parlez au Grand chef Calmepin au repaire des Calmepins."}}
D[9567] = {"Connais ton ennemi",{"Trouvez le Monument de Nazzivus à Nazzivian et récupérez un Glyphe du monument de Nazzivus. Lorsque vous l'aurez, retournez voir le redresseur de torts Aalesia au Guet du sang."}}
D[9568] = {"À l'offensive",{"Le redresseur de torts Aalesia du Guet du sang veut que vous tuiez 10 Satyres Nazzivus, 5 Voleurs Nazzivus et 5 Gangreliges Nazzivus."}}
D[9569] = {"Contenir la menace",{"Tuez 5 Traqueurs des ombres axxariens, 5 Implorateurs de l'enfer axxariens et Zevrax, puis récupérez 5 Cristaux corrompus et retournez auprès du Redresseur de torts Aalesia au Guet du sang."}}
D[9570] = {"Le Kurken se cache dans le coin",{"Kurz le Révélateur, du repaire des Calmepins de l'île de Brume-azur, veut que vous tuiez le Kurken et que vous lui rameniez la Peau du Kurken."}}
D[9571] = {"La peau du Kurken",{"Donnez la Peau du Kurken à Moordo, au repaire des Calmepins."}}
D[9572] = {"Affaiblir les remparts",{"Tuez le gardien des guetteurs Gargolmar, Omor l'Intouché et le drake Nazan. Rapportez la Main de Gargolmar, le Sabot d'Omor et la Tête de Nazan à Caza'rez, à Thrallmar dans la péninsule des Flammes infernales."}}
D[9573] = {"Le chef Oomooroo",{"Calmepin le Jeune, du repaire des Calmepins de l'île de Brume-azur, veut que vous tuiez le chef Oomooroo et 9 Indomptables affolés."}}
D[9574] = {"Victimes de la corruption",{"Apportez 6 morceaux d’Ecorce cristallisée à Morae, au Guet du sang."}}
D[9575] = {"Affaiblir les remparts",{"Tuez le gardien des guetteurs Gargolmar, Omor l'Intouché et le drake Nazan. Rapportez la Main de Gargolmar, le Sabot d’Omor et la Tête de Nazan à Flingot, du bastion de l'Honneur dans la péninsule des Flammes infernales."}}
D[9576] = {"Le collier d'Aileron-cruel",{"Rapportez le Pendentif de cristal rouge à Morae au Guet du sang."}}
D[9578] = {"À la recherche de Galaen",{"Retrouvez Galaen, le mari de Morae."}}
D[9579] = {"Le destin de Galaen",{"Remettez l’Amulette de Galaen à Morae au Guet du sang."}}
D[9580] = {"Les premiers sec-ours",{"Le pisteur Lyceon, du Guet du sang, veut 8 Flanchets d'anciens ours bruns."}}
D[9581] = {"Ce qu'apprennent les cristaux",{"Procurez-vous un Échantillon de cristal du site de l'impact en utilisant la Pioche à cristaux sur le Cristal du site de l'impact et apportez-le au messager Mikolaas au Guet du sang."}}
D[9582] = {"La force de l’Un",{"Ouvrez la Cage du ravageur et tuez le Ravageur de la mort qui s’y trouve, puis retournez voir Ruada au Guet d’azur, sur l’île de Brume-Azur."}}
D[9584] = {"Le deuxième échantillon",{"Procurez-vous un Échantillon de cristal altéré en utilisant la Pioche à cristaux sur le Cristal de Brume-Sang altéré et apportez-le au messager Mikolaas au Guet du sang."}}
D[9585] = {"Le dernier échantillon",{"Procurez-vous un Échantillon de cristal axxarien en utilisant la Pioche à cristaux sur le Cristal axxarien et apportez-le au messager Mikolaas au Guet du sang."}}
D[9586] = {"Aider Tavara",{"Guvan du Guet d’azur veut que vous trouviez Tavara et que vous guérissiez ses blessures."}}
D[9587] = {"De sombres nouvelles",{"Apportez la Lettre inquiétante au commandant Danath Trollemort au bastion de l'Honneur dans la péninsule des Flammes infernales."}}
D[9588] = {"De sombres nouvelles",{"Apportez la Lettre inquiétante à Nazgrel, à Thrallmar dans la péninsule des Flammes infernales."}}
D[9589] = {"Le sang, c'est la vie",{"Récupérez 10 Fioles de sang de gangr'orc et rapportez-les à Flingot au bastion de l'Honneur dans la péninsule des Flammes infernales."}}
D[9590] = {"Le sang, c'est la vie",{"Collectez 10 Fioles de sang de gangr'orc et rapportez-les au centurion Caza'rez à Thrallmar dans la péninsule des Flammes infernales."}}
D[9591] = {"Dompter la bête",{"Utilisez le Totem de domptage pour apprivoiser un Clampant barbelé et revenez voir la chasseresse Kella Arquenuit lorsque vous aurez réussi."}}
D[9592] = {"Dompter la bête",{"Utilisez le Totem de domptage pour apprivoiser un Trotteur des bois supérieur et retournez voir la chasseresse Kella Arquenuit."}}
D[9593] = {"Dompter la bête",{"Utilisez le Totem de domptage pour apprivoiser un Traquenuit et revenez voir la chasseresse Kella Arquenuit."}}
D[9594] = {"Les signes de la Légion",{"Tuez 8 Satyres Nazzivus et 8 Gangreliges Nazzivus, puis apportez la Plaque d'armure de Tzerak au redresseur de torts Aalesia, au Guet du sang."}}
D[9595] = {"Contrôle",{"Tuez des Murlocs sur le Rivage envasé pour invoquer une Âme en peine quel'dorei magicienne, puis détruisez-la. Allez ensuite parler à Bati à la Voûte des lumières de l'Exodar."}}
D[9598] = {"Rédemption",{"Étudiez le Tome de divinité et parlez à Jol."}}
D[9599] = {"<UNUSED>",{"Parlez à Jol, à l'Exodar."}}
D[9600] = {"Rédemption",{"Jol veut que vous vous serviez du Symbole de vie pour ressusciter un Jeune chaman furbolg avant de revenir la voir."}}
D[9601] = {"En route pour la Barricade",{"Parlez à Mehlar Aubelame à la Barricade."}}
D[9602] = {"Délivrez-les du mal...",{"Remettre la Communication du traître à l'exarque Menelaous au Guet d'azur."}}
D[9603] = {"Des lits, des bandages, etc.",{"Remettez la Liste de Topher à Laando, le maître des hippogriffes du Guet du sang."}}
D[9604] = {"Sur les ailes d'un hippogriffe",{"Acheter à Laando un vol en hippogriffe jusqu'à l'Exodar. À votre arrivée, remettez la Liste de Topher à Nurguni, au Siège du naaru dans l'Exodar."}}
D[9605] = {"Le maître des hippogriffes Stephanos",{"Allez trouver Stephanos à l'extérieur de l'Exodar et achetez-lui un vol à dos d'hippogriffe pour rentrer au Guet du sang."}}
D[9606] = {"Retourner voir Topher Loaal",{"Achetez à Stephanos un vol en hippogriffe pour rentrer au Guet du sang. Une fois <arrivé/arrivée>, livrez les Fournitures de Nurguni à l'Hôte Topher Loaal."}}
D[9607] = {"Cœur de rage",{"Faire une enquête exhaustive sur la Fournaise du sang, puis en faire un rapport au commandant de corps Danath Trollemort, au bastion de l’Honneur dans la péninsule des Flammes infernales."}}
D[9608] = {"Cœur de rage",{"Faire une enquête exhaustive sur la Fournaise du sang, puis en faire un rapport à Nazgrel, à Thrallmar dans la péninsule des Flammes infernales."}}
D[9609] = {"Aidez le gardien Biggs",{"Trouvez le gardien Biggs dans le marais des Chagrins."}}
D[9610] = {"Le bassin des larmes",{"Procurez-vous 5 Artéfacts atal'ai et remettez-les à Holaaru, au Havre boueux du marais des Chagrins."}}
D[9612] = {"Merci du fond du cœur !",{"Parlez à l'exarque Menelaous au Guet d'azur."}}
D[9616] = {"Bandits !",{"Remettez la Communication des elfes de sang à l'exarque Menelaous au Guet d'azur."}}
D[9617] = {"Aller voir les pérégrins",{"Parlez au lieutenant Coursaurore à la retraite des Pérégrins."}}
D[9618] = {"Remettre les rapports",{"Transmettez les Rapports de Keltus Sombrefeuille à Zelanis, à Lune-d'argent."}}
D[9619] = {"La rune d'invocation",{"Servez-vous de la Pierre de Vide pour invoquer un Marcheur du Vide au village Brume-d'or, vainquez-le puis retournez voir Talionia à Lune-d’Argent."}}
D[9620] = {"Les explorateurs disparus",{"Le messager Mikolaas veut que vous retrouviez l'équipe d'explorateurs qu'il a envoyé dans les ruines de Loreth'Aran, et que vous les aidiez de votre mieux."}}
D[9621] = {"Emissaire auprès de la Horde",{"Remettez la Lettre de Lor'themar Theron à dame Sylvanas Coursevent à Fossoyeuse, la capitale des Réprouvés dans les clairières de Tirisfal."}}
D[9622] = {"Avertir votre peuple",{"Parlez à l'exarque Menelaous au Guet d'azur."}}
D[9623] = {"Il est temps de grandir",{"L'exarque Menelaous, du Guet d'azur, veut que vous remettiez les Ordres de l'exarque à Torallius le Pâtre, qui se trouve hors de l'Exodar."}}
D[9624] = {"La meilleure des gâteries",{"Aonar, à la Croisée de Kessel, veut que vous lui rameniez 10 Poires des sables."}}
D[9625] = {"On ne plaisante pas avec les elekk",{"Parlez à Vorkhan le berger des elekk sur l'île de Brume-sang."}}
D[9626] = {"Rencontre avec les Orcs",{"Dame Sylvanas Coursevent veut que vous remettiez la Lettre scellée par Sylvanas au Haut seigneur Saurcroc, à Orgrimmar, la capitale de Durotar."}}
D[9627] = {"L'allégeance à la Horde",{"Retournez à Lune-d’Argent et allez faire votre rapport à Lor’themar Theron."}}
D[9628] = {"Récupérer des données",{"Récupérez le Cristal de données du relevé sur les Nagas irécailles près des cartographes morts et remettez-le au messager Mikolaas, au Guet du sang."}}
D[9629] = {"Attraper... relâcher...",{"Morae, du Guet du sang, veut que vous « marquiez » 6 Eclaireurs Vase noir avec le Marqueur de murlocs."}}
D[9630] = {"Le journal de Medivh",{"L’archimage Alturus, du défilé de Deuillevent, veut que vous entriez dans Karazhan et que vous parliez à Wravien."}}
D[9631] = {"L'aide d'une collègue",{"Remettez le Fragment d'os carbonisé à Kalynna Rougelatte, dans la Zone 52 de Raz-de-Néant."}}
D[9632] = {"De nouveaux alliés",{"Remettez la Lettre d'introduction à la chasseresse Kella Arquenuit, à l'Île de Brume-Azur."}}
D[9633] = {"En route pour Auberdine",{"Prenez le bateau pour Auberdine. Il part du quai qui se trouve près de la chasseresse Kella Arquenuit. Lorsque vous serez à Auberdine, présentez votre Lettre d’introduction à Thundris Tissevent."}}
D[9634] = {"Des prédateurs d'outre-monde",{"Tuez 10 Jeunes Brume-sang, puis retournez voir Vorkhan le berger des elekk à la Croisée de Kessel sur l'île de Brume-sang."}}
D[9635] = {"L'extracteur de granules Zappeur-Gazier !",{"Apportez 15 Pièces détachées de la pompe à vapeur à Mack Diver, à Zabra'jin dans le marécage de Zangar."}}
D[9636] = {"L'extracteur de granules Zappeur-Gazier !",{"Apportez 15 Pièces détachées de la pompe à vapeur à Manue Fretin, à Telredor dans le marécage de Zangar."}}
D[9637] = {"La requête de Kalynna",{"Kalynna Rougelatte veut que vous récupériez le Tome de la pénombre sur le Grand démoniste Néanathème dans la citadelle des Flammes infernales, et le Livre des noms oubliés sur le Sombre tisseur Syth dans les salles des Sethekk à Auchindoun.","","Cette quête doit être accomplie en mode de difficulté Héroïque."}}
D[9638] = {"En de bonnes mains",{"Parler avec Gradav dans la Bibliothèque du gardien, à Karazhan."}}
D[9639] = {"Kamsis",{"Parler avec Kamsis dans la Bibliothèque du gardien, à Karazhan."}}
D[9640] = {"L'ombre d'Aran",{"Obtenez le Journal de Medivh et retournez voir Kamsis dans la Bibliothèque du Gardien de Karazhan."}}
D[9641] = {"Les éclats de cristal irradié",{"Le redresseur de torts Boros du Guet du sang veut que vous lui apportiez 10 Éclats de cristal irradiés."}}
D[9642] = {"Encore des éclats de cristal irradié",{"Si vous avez d’autres éclats de cristal irradiés, je serai ravi de les échanger contre l’un de mes cristaux."}}
D[9643] = {"Les lianes étrangleuses",{"Le pisteur Lyceon, du Guet du sang, veut que vous lui rameniez 6 Lianes étrangleuses épineuses."}}
D[9644] = {"Plaie-de-nuit",{"Allez sur la Terrasse du Maître à Karazhan et utilisez l'Urne noircie pour invoquer Plaie-de-nuit. Récupérez l'Essence arcanique voilée sur le cadavre de Plaie-de-nuit, et rapportez-la à l'archimage Alturus."}}
D[9645] = {"La terrasse du Maître",{"Allez sur la Terrasse du Maître à Karazhan et lisez le Journal de Medivh."}}
D[9646] = {"Avis de recherche : Griffe-de-mort",{"Apportez la Patte de Griffe-de-mort au Messager Mikolaas au Guet du sang."}}
D[9647] = {"Réduire les bruissements",{"Le pisteur Lyceon au Guet du sang veut que vous tuiez 10 Virevolteurs bleus royaux."}}
D[9648] = {"Ménagerie mycologique de Mac'Aree",{"Jessera de Mac'Aree au Guet du sang veut 1 Satyre puant aquatique, 1 Champignon de sang, 1 Polypore des ruines et 1 Collybie gangrenée."}}
D[9649] = {"Les larmes d'Ysera",{"Jessera de Mac'Aree au Guet du sang veut 2 Larmes d'Ysera."}}
D[9663] = {"La tournée de Kessel",{"Kessel, à la croisée de Kessel, veut que vous alliez prévenir de l'invasion imminente des elfes de sang le Grand chef Calmepin au repaire des Calmepins, l'Exarque Menelaous au Guet d'azur et l'Amiral Odesyus au Point d'accostage d'Odesyus. Revenez voir Kessel lorsque vous aurez terminé cette tâche. Vous avez 15 minutes. (Attention à ne pas aller dans l'eau.)"}}
D[9664] = {"Fonder de nouveaux avant-postes",{"Capturez la Tour de la garde de la couronne, la Tour du Mur d'est, la Tour du Col du nord et la Tour de Pestebois dans les Maleterres de l'est. Revenez ensuite voir l'émissaire Blanchebarbe à la Chapelle de l'Espoir de Lumière."}}
D[9665] = {"Renforcer nos défenses",{"Capturez la Tour de la garde de la couronne, la Tour du Mur d'est, la Tour du Col du nord et la Tour de Pestebois dans les Maleterres de l'est. Revenez ensuite voir l'émissaire Gormok à la Chapelle de l'Espoir de Lumière."}}
D[9666] = {"Déclaration de puissance",{"Sur ordre de Kessel, à la Croisée de Kessel sur l'Île de Brume-sang, allez tuer le Seigneur Xiz au Repaire des Irécailles et plantez la Bannière draeneï sur son cadavre."}}
D[9667] = {"Il faut sauver la princesse Calmepin",{"Faites sortir la Princesse Calmepin de sa cage, puis allez parler à l'ambassadeur Calmepin Frasaboo au Guet du sang.","","Vous devez tuer le Grand chef Bras-hirsute pour obtenir la clé qui ouvre la cage."}}
D[9668] = {"Rapport à l'exarque Admetius",{"Parlez à l'Exarque Admetius au Guet du sang."}}
D[9669] = {"L'expédition disparue",{"Tuez 8 Tisseuses de brume, 8 Sangsues de brume et leur chef Zarakh. Revenez voir Achelus au Guet du sang quand votre mission sera achevée."}}
D[9670] = {"Ils sont vivants ! Peut-être...",{"Le Chercheur Cornelius vous a demandé de libérer 5 Chercheurs de l’expédition."}}
D[9671] = {"Une livraison urgente"}
D[9672] = {"L'héritage du sang maudit",{"L’amiral Odesyus vous a demandé de trouver le Capitaine Edward Hanes et de lui parler."}}
D[9673] = {"La formation de dresseur",{"Parlez à Halthenis à Lune-d’Argent."}}
D[9674] = {"Les nagas au sang maudit",{"Le capitaine Edward Hanes, sur l'île Balafre-du-ver, veut que vous tuiez 10 Nagas du sang maudit."}}
D[9675] = {"La formation de dresseur",{"Parlez à Ganaar à l'Étage des commerces de l'Exodar."}}
D[9676] = {"La formation du paladin",{"Parlez à Jesthenis Heurtesoleil, le maître des paladins, à l'intérieur de la Flèche solaire, sur l'île de Haut-soleil."}}
D[9677] = {"Le chevalier-seigneur Vaillessang vous réclame",{"Parlez au chevalier-seigneur Vaillessang, place des Pérégrins, à Lune-d'argent."}}
D[9678] = {"La première épreuve",{"Voyagez jusqu'à l'île que le chevalier-seigneur a décrite, trouvez la caverne et allumez le brasero. Lorsque la Première épreuve sera terminée, retournez voir le chevalier-seigneur Vaillessang à Lune-d'argent."}}
D[9680] = {"Exhumer le passé",{"L'archimage Alturus veut que vous vous rendiez dans les montagnes au sud de Karazhan dans le défilé de Deuillevent et que vous y récupériez un Fragment d'os carbonisé."}}
D[9681] = {"Une étude du pouvoir",{"Parlez au magistère Astalor Ligessang dans la chambre secrète sous les quartiers généraux des chevaliers de sang."}}
D[9682] = {"Les sans-espoir…",{"Le capitaine Edward Hanes de l'île Balafre-du-ver veut que vous récupériez 4 Âmes au sang maudit."}}
D[9683] = {"Mettre un terme à la malédiction du sang",{"Le capitaine Edward Hanes de l'île Balafre-du-ver veut que vous détruisiez la Statue de la reine Azshara et éliminiez Atoph du Sang maudit."}}
D[9684] = {"Revendiquer la Lumière",{"Utilisez le Calice chatoyant sur les Magistères elfes de sang pour le remplir et retournez voir le chevalier-seigneur Vaillessang à Lune-d’Argent."}}
D[9685] = {"La rédemption des morts",{"Apportez le Calice chatoyant rempli à l'auberge de Lune-d’Argent et utilisez ses pouvoirs magiques pour ressusciter Sangrias Mortelame."}}
D[9686] = {"La deuxième épreuve",{"Achevez la seconde épreuve en battant le Champion Hargnessang, le Champion Brise-Lumière, le Champion Vivelame et le Champion Heurtesoleil dans le pavillon situé à côté de maître Kelerun Deuillessang."}}
D[9687] = {"Rétablir la tranquillité",{"Le prince Toreth de l'île Balafre-du-ver veut que vous rapportiez 8 Os de dragon."}}
D[9688] = {"Vers le Rêve",{"Le prince Toreth de l'île Balafre-du-ver vous a demandé de tuer 5 Jeunes virides et 5 Rejetons virides."}}
D[9689] = {"Tranchegueule",{"Le prince Toreth de l'île Balafre-du-ver vous a demandé de tuer Tranchegueule."}}
D[9690] = {"La deuxième épreuve",{"Présentez-vous au maître Kelerun Deuillessang."}}
D[9691] = {"Retour à Lune-d'argent",{"Retournez voir le chevalier-seigneur Vaillessang à Lune-d’Argent."}}
D[9692] = {"La voie de l'adepte",{"Apportez une Gemme de Kor corrompue, une Caisse de lingots de forge-sang, une bonne mesure de Sang du Courroucé et un Insigne de chevalier de sang au Chevalier-seigneur Vaillessang, à Lune-d’Argent."}}
D[9693] = {"Ce qu'Argus signifie pour moi",{"L'exarque Admetius du Guet du sang vous a demandé de parler au redresseur de torts Boros."}}
D[9694] = {"Le Guet du sang",{"Le redresseur de torts Boros au Guet du sang veut que vous tuiez 10 Espions Epervier du soleil."}}
D[9696] = {"Traductions…",{"Apportez la Missive des Eperviers du soleil à l'interrogatrice Elysia au Guet du sang."}}
D[9697] = {"La gardienne Leesa'oh",{"Parlez à la gardienne Leesa'oh au Poste de garde cénarien dans le marécage de Zangar."}}
D[9698] = {"Une audience avec le Prophète",{"Apportez la Missive des Eperviers du soleil traduite au prophète Velen à l'Exodar."}}
D[9699] = {"Vérité ou fiction",{"Apportez les Ordres de Velen au redresseur de torts Boros, au Guet du sang."}}
D[9700] = {"Des traits de magie dans l'obscurité",{"Le redresseur de torts Boros du Guet du sang veut que vous trouviez l'emplacement du Portail du soleil et que vous tuiez 5 Anomalies du Vide."}}
D[9701] = {"L'observation des sporelins",{"Examiner le Vallon des pontes dans le marécage de Zangar, puis rapporter vos découvertes à la gardienne Leesa'oh au Poste de garde cénarien dans le marécage de Zangar."}}
D[9702] = {"Un problème de gloutonnerie",{"Récupérez 10 morceaux d’Aliments abandonnés puis revenez voir la gardienne Leesa'oh au Poste de garde cénarien, dans le marécage de Zangar."}}
D[9703] = {"Le cryocœur",{"Le redresseur de torts Kuros au Guet du sang veut que vous récupériez 12 boîtes de Fournitures médicales."}}
D[9704] = {"Tuée par les Déshérités",{"Allez au sud dans les ruines de Lune-d’Argent et cherchez l’Estafette morte dans l'allée du Point-du-jour."}}
D[9705] = {"Récupérer un paquet",{"Retournez voir l’estafette Alarion avec le Paquet d’Erona."}}
D[9706] = {"Le journal de Galaen - Le destin du redresseur de torts Saruan",{"Apportez le Journal de Galaen au redresseur de torts Kuros au Guet du sang."}}
D[9707] = {"Forger l'arme",{"Apportez la Caisse de matériaux à Bemarrin à Lune-d’Argent."}}
D[9708] = {"Des champignons familiers",{"Collectez 15 Échantillons de champignon et apportez-les à la gardienne Leesa'oh au Poste de garde cénarien dans le marécage de Zangar."}}
D[9709] = {"Voler aux voleurs",{"Récupérez 10 Boîtes de champignons et rapportez-les à la gardienne Leesa'oh au Poste de garde cénarien dans le marécage de Zangar."}}
D[9710] = {"La corsèque à la trempe de sang",{"Attendez pendant que Bemarrin forge votre arme."}}
D[9711] = {"Matis le Cruel",{"Le redresseur de torts Kuros du Guet du sang veut que vous capturiez Matis le Cruel."}}
D[9712] = {"Le cheval de guerre thalassien",{"Parlez au chevalier-seigneur Vaillessang pour apprendre comment invoquer votre cheval de guerre thalassien."}}
D[9713] = {"Drapeau pour la récolte des chapeluisants"}
D[9714] = {"Rapportez-moi un autre jardinet !"}
D[9715] = {"Rapportez-moi un jardinet !",{"Récupérez 5 Hibiscus sanguins et rapportez-les à Gzhun’tt à Sporeggar dans le marécage de Zangar."}}
D[9716] = {"Des ennuis au lac Umbretourbe",{"Déterminez la cause de la diminution de l'eau au lac Umbretourbe. Puis retournez voir Ysiel Chantelevent au Refuge cénarien dans le marécage de Zangar."}}
D[9717] = {"Oh, alors s’ils veulent la guerre…",{"Cueillez une Palme de sporielle et rapportez-la à T'shu à Sporeggar dans le marécage de Zangar."}}
D[9718] = {"À vol d'oiseau",{"Ysiel Chantelevent veut que vous vous serviez de l'Amulette du corbeau des tempêtes pour explorer chacun des principaux lacs du Marécage de Zangar."}}
D[9719] = {"Traquer la traqueuse",{"Apportez le Cerveau de la Traqueuse noire à Khn'nix à Sporeggar dans le marécage de Zangar."}}
D[9720] = {"L'équilibre doit être préservé",{"Ysiel Chantelevent veut que vous utilisiez les Graines de vignefer sur les Commandes de pompe à vapeur au Lac des serpents, au Lac Umbretourbe, au Lac des furoles et au Lagon. Retournez ensuite lui rendre les graines qu'il vous reste au Refuge cénarien dans le marécage de Zangar."}}
D[9721] = {"Le seigneur Solanar vous réclame",{"Parlez au seigneur Solanar Hargnessang à Lune-d’Argent."}}
D[9722] = {"La voie du maître",{"Allez revoir le seigneur Solanar Hargnessang pour accepter son offre de parrainage."}}
D[9723] = {"Un geste d'engagement",{"Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Soleillettes, 5 Runes ténébreuses et 150 pièces d'or au seigneur Solanar Hargnessang, à Lune-d’Argent."}}
D[9724] = {"Prévenir le Cercle cénarien",{"Parlez à Amythiel Marche-brume au Poste cénarien dans la péninsule des Flammes infernales."}}
D[9725] = {"Une preuve de loyauté",{"Le seigneur Solanar Hargnessang, à Lune-d’Argent, veut que vous détruisiez 3 Chariots à viande du Fléau et que vous tuiez 15 Ingénieurs de machines de siège du Fléau."}}
D[9726] = {"Puisque nous sommes entre amis...",{"Tuez 12 Esclavagistes écailles-sanglantes et 6 Enchanteresses écailles-sanglantes, puis retournez voir Gzhun'tt à Sporeggar dans le marécage de Zangar."}}
D[9727] = {"Puisque nous sommes toujours entre amis...",{"Tuez 12 Esclavagistes écailles-sanglantes et 6 Enchanteresses écailles-sanglantes, puis retournez voir Gzhun'tt à Sporeggar dans le marécage de Zangar."}}
D[9728] = {"Un accueil chaleureux",{"Le gardien Hamoot du Refuge cénarien veut que vous lui apportiez 30 Griffes de naga."}}
D[9729] = {"Fhwoor écrabouiller !",{"Escortez Fhwoor près de la pompe à vapeur des Furoles pour récupérer l’Arche de Ssslith. Ramenez Fhwoor avec l’arche jusqu’à un endroit sûr, puis allez faire votre rapport à Gzhun'tt, à Sporeggar dans le marécage de Zangar."}}
D[9730] = {"Le chef des Sombrecrêtes",{"Tuez Rajah Haghazed au Lagon et retournez voir le gardien Hamoot de l'Expédition cénarienne dans le marécage de Zangar pour chercher votre récompense."}}
D[9731] = {"Plan des canalisations",{"Explorez le Lac des Serpents à la recherche d'un drain. Retournez voir Ysiel Chantelevent au Refuge cénarien pour présenter vos découvertes."}}
D[9732] = {"Retour au marécage",{"Retournez voir Ysiel Chantelevent au Refuge cénarien dans le marécage de Zangar."}}
D[9733] = {"Prévenir le Cercle cénarien",{"Parlez à Mahuram Sabot-robuste à Thrallmar dans la péninsule des Flammes infernales."}}
D[9734] = {"Retour au marécage",{"Retournez voir Ysiel Chantelevent au Refuge cénarien dans le marécage de Zangar."}}
D[9735] = {"Les vrais maîtres de la Lumière",{"Le seigneur Solanar Hargnessang de Lune-d'argent veut que vous lui apportiez une fiole d'Eau bénite de la Main de Tyr."}}
D[9736] = {"Les vrais maîtres de la Lumière",{"Le seigneur Solanar Hargnessang de Lune-d’Argent veut que vous lui apportiez 1 Catalyseur arcanique, 1 Poudre crépusculaire, 1 Diamant d'Azeroth et 1 Diamant noir parfait."}}
D[9737] = {"Les vrais maîtres de la Lumière",{"Utilisez la Mixture d'extinction près de la flamme éternelle dans la chapelle d'Alonsus pour ôter la protection de la Lumière. Vainquez quiconque tentera de défendre la chapelle."}}
D[9738] = {"Disparus au combat",{"Découvrez ce qui est arrivé au lieur de terre Rayge, au naturaliste Morsure, à l'Échardonneur Vertemain et à l'implorateur céleste Griffe. Retournez ensuite voir la guetteuse Jhang au réservoir de Glissecroc dans le marécage de Zangar."}}
D[9739] = {"Les malheurs des sporelins",{"Fahssn au vallon des pontes veut que vous collectiez 10 Sacs de spores mûres."}}
D[9740] = {"Le portail du soleil",{"Le redresseur de torts Aesom du Guet du sang veut que vous détruisiez le Portail du soleil."}}
D[9741] = {"Les bestioles du vide",{"Tuez 12 Bestioles du Vide et faites votre rapport au redresseur de torts Aesom au Guet du sang."}}
D[9742] = {"Encore des sacs de spores"}
D[9743] = {"Ennemis par nature",{"Fahssn, du vallon des pontes du marécage de Zangar, veut que vous lui rameniez 6 Vrilles de seigneurs-tourbe."}}
D[9744] = {"Plus de vrilles !",{"Vous avez tué de nombreux géants, mais il en reste encore beaucoup. Et ils attaquent toujours nos sacs de spores !"}}
D[9746] = {"Les limites de l'épuisement physique",{"Le redresseur de torts Aesom au Guet du sang veut que vous tuiez 10 Pyromanciens Epervier du soleil et 10 Défenseurs Epervier du soleil."}}
D[9747] = {"La tribu Umbretourbe",{"Ikeyen du Refuge cénarien veut que vous vous rendiez au village Umbretourbe pour y tuer Kataru, 8 Prophètes d'Umbretourbe, 6 Sorciers-docteurs d'Umbretourbe et 6 Oracles d'Umbretourbe."}}
D[9748] = {"Ne buvez pas l'eau",{"Le redresseur de torts Aesom au Guet du sang veut que vous utilisiez le Flacon d'échantillon d'eau pour obtenir un Échantillon d'eau de Brume-sang."}}
D[9749] = {"Ils sont vivants ! Peut-être...",{"Le Chercheur Cornelius a demandé que vous libériez 5 Chercheurs de l'expédition."}}
D[9750] = {"UNUSED Urgent Delivery"}
D[9751] = {"L'héritage du sang maudit",{"L’amiral Odesyus vous a demandé de trouver le Capitaine Edward Hanes et de lui parler."}}
D[9752] = {"L'évadée d'Umbretourbe",{"Escortez Kayra Long-crin jusqu'au Refuge cénarien dans le marécage de Zangar. Présentez-vous à Ysiel Chantelevent lorsque vous aurez accompli cette tâche."}}
D[9753] = {"Ce que nous savons...",{"Parlez à l'exarque Admetius au Guet du sang."}}
D[9756] = {"Ce que nous ne savons pas…",{"Parlez à un agent Epervier du soleil capturé au Guet du sang et obtenez des informations secrètes des Eperviers du soleil. Retournez auprès de l'exarque Admetius quand vous aurez terminé cette tâche."}}
D[9757] = {"Aller trouver la chasseresse Kella Arquenuit",{"Parlez à la chasseresse Kella Arquenuit près de l'Amarrage de Valaar."}}
D[9758] = {"Retourner voir l'arcaniste Vandril",{"Retournez voir l'arcaniste Vandril à Tranquillien dans les Terres fantômes."}}
D[9759] = {"La fin de leur monde",{"Suivez et protégez le démolisseur Legoso pendant qu'il essaye de détruire la Bobine vectorielle et tuer Sironas. Retournez voir l'exarque Admetius au Guet du sang si vous réussissez cette mission."}}
D[9760] = {"Le Repos du redresseur de torts",{"Parlez au redresseur de torts Corin au Repos du redresseur de torts sur l'île de Brume-Sang."}}
D[9761] = {"Ouvrir la voie",{"Le redresseur de torts Corin au Repos du redresseur de torts veut que vous tuiez 8 Saboteurs Epervier du soleil et 8 Agents Epervier du soleil."}}
D[9762] = {"Une prophétie à écrire"}
D[9763] = {"Le repaire du seigneur de guerre",{"La guetteuse Jhang veut que vous trouviez et exécutiez le seigneur de guerre Kalithresh à l'intérieur du réservoir de Glissecroc."}}
D[9764] = {"Les ordres de dame Vashj",{"Apportez les Ordres de dame Vashj à Ysiel Chantelevent au Refuge cénarien dans le marécage de Zangar."}}
D[9765] = {"Les préparatifs de guerre",{"Procurez-vous des Armes de Glissecroc sur les nagas du réservoir de Glissecroc et apportez-les à Ysiel Chantelevent au Refuge cénarien dans le marécage de Zangar."}}
D[9766] = {"Les armes de Glissecroc"}
D[9767] = {"Connais ton adversaire",{"Procurez-vous un Grimoire de Glissecroc sur les nagas du réservoir de Glissecroc et apportez-le à Ashyen au Refuge cénarien dans le marécage de Zangar."}}
D[9769] = {"La mode, ça ne s'explique pas",{"Apportez 8 Ailes diaphanes de n'importe quelles lucioles du marécage de Zangar à Magasha au poste du Rat des marais."}}
D[9770] = {"Les crocs-du-marais menaçants",{"Reavij du Poste du rat des marais veut que vous alliez tuer 10 Eventreurs Croc-du-marais."}}
D[9771] = {"À la recherche de l'éclaireur Jyoba",{"Partez à la recherche de l'éclaireur Jyoba à la Morte-bourbe, au Marécage de Zangar."}}
D[9772] = {"Le rapport de Jyoba",{"Reprenez le Rapport de l'éclaireur Jyoba aux Géants flétris et rapportez-le à Zurai au poste du Rat des marais."}}
D[9773] = {"Plus de champignons !",{"Prélever 8 Filets d'anguilles sur des Anguilles d'Umbretourbe et les apporter à Magasha, au poste du Rat des marais."}}
D[9774] = {"Les écailles d'hydre épaisses",{"Zurai, au poste du Rat des marais, veut que vous lui apportiez 12 Écailles d'hydre épaisses."}}
D[9775] = {"Aller voir le chasseur des ombres Denjai",{"Apporter le Rapport de Zurai chasseur des ombres Denjai à Zabra'jin."}}
D[9776] = {"Le Havre d'Orebor",{"Parlez à Ikuti au Havre d'Orebor."}}
D[9777] = {"Les spores de fulgor",{"Apportez 6 Spores de fulgor à Ruam, à Telredor."}}
D[9778] = {"Le gardien Hamoot",{"Allez vous présenter au gardien Hamoot au Refuge cénarien dans le marécage de Zangar."}}
D[9779] = {"L'interception des messages",{"Tuez assez d’Elfes Eperviers du soleil pour trouver la Missive des Éperviers du soleil et rapportez-la au Redresseur de torts Boros, au Guet du sang."}}
D[9780] = {"Les filets d'anguilles d'Umbretourbe",{"Noraani, à Telredor, veut que vous lui apportiez 8 Filets d'anguille."}}
D[9781] = {"Trop de bouches à nourrir",{"Tuez 10 Hydres du bourbier et retournez voir Haalrun à Telredor."}}
D[9782] = {"La Morte-bourbe",{"Apportez un Échantillon de terre de Morte-bourbe au Redresseur de torts Idaar, à Telredor."}}
D[9783] = {"Une sécheresse peu naturelle",{"Le redresseur de torts Idaar, à Telredor, veut que vous tuiez 12 Géants flétris."}}
D[9784] = {"L'identification des morceaux de plantes",{"Il me faudrait encore d'autres morceaux de plantes. Avec la baisse du niveau des eaux, j'ai l'impression que le nombre d'espèces envahissantes augmente. J'ai cependant besoin d'un échantillon plus large pour appuyer ma théorie."}}
D[9785] = {"La bénédiction des anciens",{"L'imploratrice céleste Sabot-noir veut que vous alliez parler aux anciens Ashyen et Keleth au Refuge cénarien, pour obtenir leur bénédiction."}}
D[9786] = {"Les ruines de Boha'mu",{"L'anachorète Ahuurn de Telredor veut que vous exploriez les Ruines de Boha'mu."}}
D[9787] = {"Les idoles des Tourbe-farouches",{"Récupérez 6 Idoles Tourbe-farouche et rapportez-les à l'anachorète Ahuurn à Telredor."}}
D[9788] = {"Un lieu sombre et humide",{"Cherchez les affaires d'Ikeyen à l'intérieur d'une caverne au sud d'Umbretourbe. Rapportez-les à Ikeyen au Refuge cénarien dans le marécage de Zangar."}}
D[9789] = {"Maîtrise de la chasse aux sabots-fourchus",{"Chassez 30 Sabots-fourchus et retournez voir Hemet Nesingwary au safari de Nesingwary, en Nagrand, pour prouver votre valeur."}}
D[9790] = {"Ailes diaphanes",{"Haalrun de Telredor veut que vous lui rameniez 8 Ailes diaphanes de n'importe quelles lucioles du marécage de Zangar."}}
D[9791] = {"Les crocs-du-marais menaçants",{"Tuez 10 Eventreurs Croc-du-marais et retournez voir Noraani à Telredor."}}
D[9792] = {"Un message pour Telaar",{"Parlez au Gardien Moi’bff Jill à Telaar, en Nagrand."}}
D[9793] = {"La destinée de Tuurem",{"Apportez la Lettre du redresseur de torts Idaar à Andarl au Bastion allérien dans la forêt de Terokkar."}}
D[9794] = {"La curiosité est un vilain défaut",{"Apportez la Lettre de Timothy à Kialon à Sylvanaar dans les Tranchantes."}}
D[9795] = {"La menace ogre",{"Rendez-vous au bastion des Sire-tonnerre dans les Tranchantes, et parlez à Nekthar."}}
D[9796] = {"Des nouvelles du marécage de Zangar",{"Parlez à Mokasa, au fort des Brise-pierres, dans la forêt de Terokkar."}}
D[9797] = {"Des renforts pour Garadar",{"Parlez au capitaine Kroghan à Garadar en Nagrand."}}
D[9798] = {"Les plans des elfes de sang",{"Apportez les Plans des elfes de sang au redresseur de torts Aldar au point d'impact du val d'Ammen."}}
D[9799] = {"Un travail de botanique",{"Cueillez 3 Fleurs corrompues et apportez-les à l'apprentie Vishael au point d'impact du val d'Ammen."}}
D[9800] = {"Une graine rare",{"L'Elémentalise Lo'ap, au Trône des éléments de Nagrand, veut que vous lui apportiez 15 Caracolis digérés"}}
D[9801] = {"Rassembler les composants",{"L’anachorète Ahuurn, de Telredor, veut que vous lui rameniez 4 Yeux de sporoptères et 4 Tentacules de trotteur des tourbières."}}
D[9802] = {"Les plantes du marécage de Zangar",{"Apportez 10 Morceaux de plantes non identifiées à Lauranna Thar'well, au Refuge cénarien dans le marécage de Zangar."}}
D[9803] = {"Un message pour Tourbe-farouche",{"Une fois dans les ruines de Boha’mu, buvez l’Élixir d’Ahuurn. Lorsque vous serez sous forme d’arakkoa, allez parler à l’Ancien Kuruti."}}
D[9804] = {"Esprits agités de Chanteciel",{"L'élémentaliste Lo'ap, du Trône des éléments en Nagrand, veut que vous détruisiez 8 Esprits du lac."}}
D[9805] = {"La bénédiction d'Incineratus",{"L’Elémentaliste Lo’ap, au Trône des éléments, en Nagrand, veut que vous détruisiez la Grande hutte, la Hutte de l’ouest, la Hutte du sud et la Hutte de l’est à Ventejonc.","","Rendez le Feu vivant à l’Elémentaliste Lo’ap quand vous aurez terminé votre tâche."}}
D[9806] = {"Des spores fertiles",{"Gshaff veut que vous récoltiez 6 Spores fertiles sur les Sporoptères et Marcheurs des marais du marécage de Zangar. Revenez voir Gshaff à Sporeggar quand vous aurez terminé cette tâche."}}
D[9807] = {"Plus de spores fertiles",{"Nous avons toujours l’usage de spores fertiles, <race>. Les Grands-pieds sont des champignons extrêmement utiles. Pouvoir les cultiver nous permet de faire d’innombrables choses."}}
D[9808] = {"Les chapeluisants",{"Apportez 10 Chapeluisants à Msshi'fn de Sporeggar, dans le marécage de Zangar."}}
D[9809] = {"Plus de chapeluisants",{"Je vous prendrai tous les chapeluisants que vous pourrez trouver. Notre village en a toujours besoin."}}
D[9810] = {"L'esprit pollué",{"L’Elémentaliste Lo’ap, au Trône des éléments, en Nagrand, veut que vous détruisiez l’Essence polluée de Watoosun et 8 Surgisseurs du lac."}}
D[9811] = {"L'amitié des Sin'dorei",{"Apportez la Tête de Dar'Khan à Lor'themar Theron, à Lune-d'argent."}}
D[9812] = {"Emissaire auprès de la Horde",{"Remettez la Lettre de Lor'themar Theron à dame Sylvanas Coursevent à Fossoyeuse, la capitale des Réprouvés dans les clairières de Tirisfal."}}
D[9813] = {"Rencontre avec les Orcs",{"Dame Sylvanas Coursevent veut que vous remettiez la Lettre scellée par Sylvanas au Haut seigneur Saurcroc, à Orgrimmar, la capitale de Durotar."}}
D[9814] = {"Des têtes-tonnantes, mon pote !",{"Le sorcier-docteur Tor'gash veut 6 Têtes-tonnantes."}}
D[9815] = {"Un plongeon dans la boue",{"L'Elémentaliste Lo'ap, au Trône des éléments, en Nagrand, veut que vous récupériez 5 Noyaux couverts de boue."}}
D[9816] = {"Ouvrez, ouvrez la cage aux…",{"Prenez la Cage à Murlocs et posez-la sur le rocher plat, près de Tourbedague."}}
D[9817] = {"Le chef des Écailles-sanglantes",{"Tuez Rajis Fyashe au Lac des Serpents et revenez voir le gardien Hamoot au refuge cénarien dans le marécage de Zangar pour recevoir votre récompense."}}
D[9818] = {"Les entrailles de la terre",{"Communiquer avec Gordawg."}}
D[9819] = {"La terre torturée",{"Gordawg, du Trône des Éléments en Nagrand, vous a demandé de détruire 10 Esprits de la terre torturés."}}
D[9820] = {"ON RECHERCHE : Boss Grog'ak",{"Le chasseur des ombres Denjai, de Zabra'jin, veut que vous lui apportiez la Tête du boss Gorg'ak."}}
D[9821] = {"Damnation au menu",{"Gordawg, au Trône des éléments, en Nagrand, vous a demandé de lui apporter 10 Noyaux d'écraseur enragé."}}
D[9822] = {"Une attaque imminente",{"Le chasseur des ombres Denjai, de Zabra’jin, veut que vous lui apportiez les Plans d’attaque des Ango’rosh."}}
D[9823] = {"Eux ou nous",{"Tuez le Suzerain Poing-sanglant, 10 Marteleurs Ango'rosh et 10 Mangeurs-d'âmes Ango'rosh, et faites votre rapport au chasseur des ombres Denjai à Zabra'jin."}}
D[9824] = {"Troubles arcaniques",{"Utilisez le Cristal de divination pourpre près des sources d'eau souterraines dans la Cave du maître, puis retournez voir l'archimage Alturus à l'extérieur de Karazhan."}}
D[9825] = {"L'agitation des sans-repos",{"Apportez 10 Essences fantomatiques à l'Archimage Alturus, à l'extérieur de Karazhan."}}
D[9826] = {"Un envoyé de Dalaran",{"Apportez le Rapport d’Alturus à l’Archimage Cédric, à la périphérie du Cratère de Dalaran."}}
D[9827] = {"Le baside racorni",{"Apportez le Baside racorni à Ruam à Telredor."}}
D[9828] = {"Le baside racorni",{"Apportez le Baside racorni à Reavij au poste du Rat des marais."}}
D[9829] = {"Khadgar",{"Remettez le Rapport d’Alturus à Khadgar, à Shattrath, dans la forêt de Terokkar."}}
D[9830] = {"Venin d'aiguillonneur",{"Apportez 6 doses de Venin de suce-sang des Furoles à Puluu, au Havre d’Orebor."}}
D[9831] = {"L'entrée de Karazhan",{"Khadgar veut que vous entriez dans le Labyrinthe des Ombres d'Auchindoun pour récupérer le Premier fragment de la clé, dans le Récipient arcanique qui y est caché."}}
D[9832] = {"Le deuxième et le troisième fragments",{"Trouver le Deuxième fragment de la clé dans un récipient arcanique à l’intérieur du Réservoir de Glissecroc, et le Troisième fragment de la clé dans un récipient arcanique au Donjon de la tempête. Une fois que ce sera fait, revenir auprès de Khadgar à Shattrath."}}
D[9833] = {"Les lignes de communication",{"Puluu, du Havre d’Orebor, veut que vous tuiez 12 Trancheurs Croc-du-marais."}}
D[9834] = {"Une armure naturelle",{"Apportez 8 Peaux de tourbegriffes à Maktu au Havre d’Orebor."}}
D[9835] = {"Les empiètements des Ango'rosh",{"Tuez 10 Ogres Ango'rosh et 5 Chamans Ango'rosh, puis retournez voir Ikuti au Havre d'Orebor."}}
D[9836] = {"Le toucher du maître",{"Rendez-vous aux Grottes du temps et persuadez Medivh d’accepter votre Clé de l’apprenti réparée."}}
D[9837] = {"Retour vers Khadgar",{"Retournez voir Khadgar à Shattrath, et montrez-lui à la Clé du maître."}}
D[9838] = {"L’Œil pourpre",{"Parlez à l'archimage Alturus à l'extérieur de Karazhan."}}
D[9839] = {"Le suzerain Poing-sanglant",{"Ikuti veut que vous tuiez le Suzerain Poing-sanglant et 10 Marteleurs Ango’rosh. Lorsque vous aurez terminé cette quête, retournez au Havre d’Orebor."}}
D[9840] = {"Évaluer la situation",{"Trouvez Koren à l'intérieur de Karazhan."}}
D[9841] = {"Aiguillonner les dards",{"Tuez 8 Suce-sang des furoles et retournez voir Gambarinka à Zabra'jin."}}
D[9842] = {"Les lames les mieux affûtées",{"Apportez 10 Lames de trancheurs Croc-du-marais à Gambarinka à Zabra'jin."}}
D[9843] = {"Le journal de Keanna",{"Fouillez les Appartements des hôtes à l'intérieur de Karazhan à la recherche du Journal de Keanna, et apportez-le à l'archimage Alturus à l'extérieur de Karazhan."}}
D[9844] = {"Une présence démoniaque",{"L'Archimage Alturus veut que vous détruisiez la Présence démoniaque au sommet de Karazhan."}}
D[9845] = {"À la pêche aux ennuis",{"Tuez 10 Vandales tourbegriffe, puis retournez voir Zurjaya à Zabra'jin."}}
D[9846] = {"Esprits des Tourbe-farouche",{"Apportez 10 Totems de protection Tourbe-farouche au prophète Janidi à Zabra'jin."}}
D[9847] = {"Un esprit allié ?",{"Plantez le totem Tourbe-farouche dans le sol au pied de l’escalier des ruines de Boha’mu. Ensuite, allez raconter vos découvertes à la Prophétesse Janidi, à Zabra’jin."}}
D[9848] = {"Les secrets des Tourbedagues",{"Timothy Daniels, du Havre d'Orebor, veut que vous lui rameniez le Manuel de poison Tourbedague et une Fiole de poison Tourbedague."}}
D[9849] = {"Briser le voile",{"Gordawg, du Trône des éléments en Nagrand, vous a demandé de tuer 30 Serviteurs de Gurok."}}
D[9850] = {"Maîtrise de la chasse aux sabots-fourchus",{"Tuez 12 Étalons sabots-fourchus, puis allez raconter vos exploits à Hemet Nesingwary, au safari de Nesingwary en Nagrand."}}
D[9851] = {"Maîtrise de la chasse aux sabots-fourchus",{"Hemet Nesingwary, du safari de Nesingwary en Nagrand, veut que vous lui rameniez la Corne de Banthar."}}
D[9852] = {"Le plus gros des gibiers",{"Apportez le Cœur de Longues-défenses à Hemet Nesingwary au safari de Nesingwary en Nagrand."}}
D[9853] = {"Gurok l'Usurpateur",{"Gordawg, du Trône des éléments en Nagrand, vous a demandé de détruire Gurok l’Usurpateur et de lui ramener la Tête de terre de Gurok."}}
D[9854] = {"Maîtrise de la chasse aux venterocs",{"Tuez 30 Venterocs et retournez voir Fitz au safari de Nesingwary en Nagrand."}}
D[9855] = {"Maîtrise de la chasse aux venterocs",{"Abattez 12 Venterocs voraces, puis retournez voir Fitz au safari de Nesingwary en Nagrand."}}
D[9856] = {"Maîtrise de la chasse aux venterocs",{"Fitz, du safari de Nesingwary en Nagrand, veut que vous lui rameniez l'Œil d'Arrache-tripes."}}
D[9857] = {"Maîtrise de la chasse aux talbuks",{"Tuez 30 Cerfs talbuks, puis retournez voir Harold Lane, au safari de Nesingwary en Nagrand."}}
D[9858] = {"Maîtrise de la chasse aux talbuks",{"Chassez 12 Talbuks Broutépine, puis retournez voir Harold Lane, au safari de Nesingwary en Nagrand."}}
D[9859] = {"Maîtrise de la chasse aux talbuks",{"Récupérez le Sabot de Bach'lor et remettez-le à Harold Lane, au safari de Nesingwary en Nagrand."}}
D[9860] = {"La nouvelle directive",{"Parlez à l’Archimage Cédric à la périphérie du Cratère de Dalaran."}}
D[9861] = {"Le vent hurlant",{"Trouvez quelqu'un qui parle le kalimag au Trône des éléments et montrez-lui le Vent hurlant."}}
D[9862] = {"Les corrupteurs bourbesang",{"L’élémentaliste Morgh, du Trône des éléments en Nagrand, veut que vous tuiez 5 Putréfacteurs bourbesang."}}
D[9863] = {"Vile idolâtrie",{"Le long-voyant Kurkush, de Garadar en Nagrand, veut que vous lui rameniez 20 Idoles bourbesang."}}
D[9864] = {"La troupe manquante",{"Tentez de retrouver la troupe de Garadar manquante."}}
D[9865] = {"L'âme des guerriers",{"Tuez 20 Charognards bourbesang et 10 Écumeurs bourbesang."}}
D[9866] = {"Et il parcourra la Terre...",{"Apportez la nouvelle au Long-voyant Corhuk, à Garadar."}}
D[9867] = {"Les chefs Bourbesang...",{"Le long-voyant Margadesh à Garadar en Nagrand veut que vous lui rameniez la Tête d'Ortor de Bourbesang."}}
D[9868] = {"Le totem de Kar'dash",{"Escortez le Captif Mag'har hors du poste de Berceau-de-l'été. Si vous y parvenez, allez parler à Garrosh, à Garadar."}}
D[9869] = {"Le Trône des éléments",{"L'élémentaliste Ioki veut que vous vous rendiez au Trône des éléments et que vous parliez à l'élémentaliste Sharvak."}}
D[9870] = {"Le Trône des éléments",{"L'élémentaliste Yal'hah veut que vous vous rendiez au Trône des éléments et que vous parliez à l'élémentaliste Sharvak."}}
D[9871] = {"Les envahisseurs bourbesang",{"Apportez les Plans d'invasion bourbesang à Arechron."}}
D[9872] = {"Les envahisseurs bourbesang",{"Apportez les Plans d'invasion bourbesang à Garrosh."}}
D[9873] = {"Ortor, mon vieil ami…",{"Arechron, de Telaar en Nagrand, veut que vous tuiez Ortor de Bourbesang."}}
D[9874] = {"Arrêter la contamination",{"Otonbu le Sage, à Telaar en Nagrand, veut que vous utilisiez la Torche de feu liquide pour détruire 10 Cadavres de villageois du Berceau-de-l'été. Lorsque vous aurez terminé, rendez-lui la Torche de feu liquide."}}
D[9875] = {"Une espèce non cataloguée",{"Apportez l'Espèce non cataloguée à Lauranna Thar'well au Refuge cénarien dans le marécage de Zangar."}}
D[9876] = {"Une incursion manquée",{"Ysiel Chantelevent veut que vous recherchiez des signes des druides de l'Expédition cénarienne près de l'entrée du réservoir de Glissecroc, au Marécage de Zangar."}}
D[9877] = {"Un breuvage de restauration",{"Parlez à l'apothicaire Renzithen à Tranquillien."}}
D[9878] = {"La résolution du problème",{"Poli'lukluk le Malin, de Telaar en Nagrand, veut que vous tuiez 20 Charognards bourbesang et 10 Écumeurs bourbesang."}}
D[9879] = {"Le totem de Kar'dash",{"Escortez le Captif kurenaï hors du poste de Berceau-de-l'été. Si vous y parvenez, allez parler à Arechron, à Telaar."}}
D[9882] = {"Voler les voleurs",{"Procurez-vous 10 Fragments de cristal d’Oshu’gun et remettez-les à Gezhe, au Point d'ancrage Aeris en Nagrand."}}
D[9883] = {"Encore des fragments de cristal"}
D[9884] = {"Les avantages des membres",{"The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.","","The quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us."}}
D[9885] = {"Les avantages des membres",{"The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.","","The quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us."}}
D[9886] = {"Les avantages des membres",{"The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.","","The quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us."}}
D[9887] = {"Les avantages des membres"}
D[9888] = {"Le chef impuissant",{"Jorin Œil-mort vous a demandé de trouver Kilrath et de lui parler."}}
D[9889] = {"Ne tuez pas le gros",{"Kilrath, dans la forêt de Terokkar, vous a demandé de tuer 10 Envahisseurs rochepoings, et de frapper Unkor le Brutal jusqu’à ce qu’il parle."}}
D[9890] = {"Victoire !",{"Transmettez à Kilrath, dans la forêt de Terokkar, les informations arrachées à Unkor."}}
D[9891] = {"Parce que Kilrath est un lâche",{"Transmettez les informations arrachées à Unkor à Jorin Œil-mort, à Garadar en Nagrand."}}
D[9892] = {"Encore des perles de guerre en obsidienne"}
D[9893] = {"Les perles de guerre d'obsidienne",{"Apportez 10 Perles de guerre d'obsidienne à Gezhe, du Point d'ancrage Aeris en Nagrand."}}
D[9894] = {"Protéger les guetteurs",{"Tuez le Seigneur Klaq et retournez voir l’Imploratrice céleste Sabot-Noir au Refuge Cénarien."}}
D[9895] = {"L'équilibre se meurt",{"Trouvez Fouettourbe et occupez-vous de lui, puis retournez voir Lethyn Lunéclat au Refuge cénarien."}}
D[9896] = {"La mort d'Aiguillon-noir",{"Apportez l'Aiguillon d'Aiguillon-noir au prospecteur Conall à Telredor."}}
D[9897] = {"Je suis sauvée !",{"Donnez le Paquet de peaux à Harold Lane, au safari de Nesingwary en Nagrand."}}
D[9898] = {"Un gros dard est une belle preuve d'amour",{"Apportez l’Aiguillon d’Aiguillon-noir à Reavij, au poste du Rat des marais."}}
D[9899] = {"Un boulot pas fini",{"Magasha, au poste du Rat des marais, veut que vous tuiez Sporailée."}}
D[9900] = {"Gava'xi",{"Tuez Gava'xi près d'Oshu'gun, puis retournez voir Zerid au Point d'ancrage Aeris, en Nagrand."}}
D[9901] = {"Un travail inachevé",{"Le prospecteur Conall de Telredor veut que vous tuiez Sporailée."}}
D[9902] = {"La terreur du lac des furoles",{"Tuez Griffe de terreur et retournez voir Puluu au Havre d’Orebor."}}
D[9903] = {"Le plus gros de tous",{"Tuez Mragesh et retournez voir Zurjaya à Zabra’jin."}}
D[9904] = {"À la poursuite de Griffe de terreur",{"Tuez Griffe de terreur et retournez voir Zurjaya à Zabra’jin."}}
D[9905] = {"La vengeance de Maktu",{"Trouvez et tuez Mragesh, puis retournez voir Maktu au Havre d’Orebor."}}
D[9906] = {"Un message dans une bataille",{"Jorin Œil-mort, de Garadar en Nagrand, vous a demandé de tuer 8 Écraseurs rochepoings et 8 Mystiques rochepoings."}}
D[9907] = {"Une avancée audacieuse",{"Jorin Œil-mort, de Garadar en Nagrand, vous a demandé de tuer 10 Guerriers rochepoings et 10 Mages rochepoings."}}
D[9910] = {"Étendards au vent...",{"Elkay'gan le Mystique, de Garadar en Nagrand, veut que vous placiez des Étendards de bataille des Mag’har au Premier, Deuxième, et Troisième bûchers de la Lame-Ardente. Lorsque vous aurez terminé, allez lui rendre les Étendards de bataille des Mag'har restants."}}
D[9911] = {"Le comte des marécages",{"Remettez la Mandibule du \"Comte\" Ungula à la gardienne Leesa'oh."}}
D[9912] = {"L'Expédition cénarienne",{"Parlez à Ysiel Chantelevent, au Refuge cénarien du marécage de Zangar."}}
D[9913] = {"Le Consortium a besoin de vous !",{"Présentez-vous à Gezhe au Point d'ancrage Aeris en Nagrand."}}
D[9914] = {"De l'ivoire plein la tête",{"Récupérez 3 Paires de défenses d'ivoire et rapportez-les à Shadrek, au Point d'ancrage Aeris en Nagrand."}}
D[9915] = {"Encore plus d'ivoire plein la tête"}
D[9916] = {"Les caisses de fournitures de l'Orbite-Sanglante",{"Elkay'gan le Mystique, de Garadar en Nagrand, veut que vous récupériez 10 Caisses de fournitures de l'Orbite-Sanglante."}}
D[9917] = {"Est-ce que je rêve...",{"La chasseresse Bintook, de Telaar en Nagrand, veut que vous récupériez les Plans rochepoing."}}
D[9918] = {"Pas de ça chez moi !",{"La chasseresse Bintook, de Telaar en Nagrand, veut que vous parliez à Gros-tas. Retournez la voir lorsque vous aurez obtenu les informations dont elle a besoin."}}
D[9919] = {"Sporeggar",{"Allez à Sporeggar, au Marécage de Zangar, au nord du vallon des pontes, et apportez les Sacs de spores récupérés à Msshi'fn."}}
D[9920] = {"Mo'mor le Briseur",{"La chasseresse Bintook, à Telaar en Nagrand, veut que vous parliez à Mo’mor le Briseur."}}
D[9921] = {"Les ruines de la Lame-Ardente",{"Mo'mor le Briseur, à Telaar en Nagrand, veut que vous tuiez 8 Écraseurs rochepoings et 8 Mystiques rochepoings."}}
D[9922] = {"Les failles jumelles de Nagrand",{"Mo'mor le Briseur, à Telaar en Nagrand, veut que vous tuiez 10 Guerriers rochepoings et 10 Mages rochepoings."}}
D[9923] = {"AU SECOURS !",{"Trouvez la Clé rochepoing et libérez Corki. Parlez avec Arechron, à Telaar, si vous réussissez."}}
D[9924] = {"Corki a encore disparu !",{"Arechron, de Telaar, vous a demandé de retrouver et de libérer Corki."}}
D[9925] = {"Des questions de sécurité",{"Zerid, du Point d'ancrage Aeris en Nagrand, veut que vous tuiez 12 Rejetons du Vide près d'Oshu'gun."}}
D[9926] = {"FLAG Shadow Council/Warmaul Questline"}
D[9927] = {"Une ruse impitoyable",{"Lantresor de la Lame, aux Ruines de la Lame-Ardente en Nagrand, veut que vous plantiez 10 Bannières des Ogres Cogneguerre dans le corps de soldats de Kil'sorrau, à la forteresse Kil'sorrau.","","Rapportez les Bannières des Ogres Cogneguerre que vous n’aurez pas utilisées."}}
D[9928] = {"Les armes du subterfuge",{"Lantresor de la Lame, des Ruines de la Lame-Ardente en Nagrand, veut que vous récupériez 10 Armes de Kil'sorrau."}}
D[9929] = {"Le marchand disparu",{"Suivez la route de Shattrath vers le nord-ouest et cherchez des indices concernant ce qui est arrivé à Dugar."}}
D[9930] = {"Le marchand disparu",{"Suivez la route de Shattrath vers le nord-ouest et cherchez des indices concernant ce qui est arrivé à Deirom."}}
D[9931] = {"Un prêté pour un rendu",{"Lantresor de la Lame, aux Ruines de la Lame-Ardente en Nagrand, veut que vous plantiez 10 Bannières de Kil'sorrau dans les cadavres d’ogres Cogneguerre, aux Ruines du clan du Crâne-Ricanant.","","Rapportez-lui toutes les bannières de Kil'sorrau que vous n’aurez pas utilisées."}}
D[9932] = {"Le corps du délit",{"Lantresor de la Lame, des ruines de la Lame-Ardente en Nagrand, veut que vous utilisiez la Couverture de laine humide sur le Bûcher ardent cogneguerre dans la Cour du Crâne-Ricanant afin d’envoyer un signal à ses Ogres."}}
D[9933] = {"Un message pour Telaar",{"Apporter l’Offrande de paix de la Lame-Ardente à Arechron, à Telaar, en Nagrand."}}
D[9934] = {"Un message pour Garadar",{"Apporter l’Offrande de paix de la Lame-Ardente à Garrosh, à Garadar."}}
D[9935] = {"On recherche : Giselda la Mégère",{"Tuez Giselda la Mégère et n'importe quelle combinaison de 15 Agents de Kil'sorrau. Retournez voir le gardien Bullrok à Garadar si vous parvenez à accomplir cette tâche."}}
D[9936] = {"On recherche : Giselda la Mégère",{"Tuez Giselda la Mégère et n'importe quelle combinaison de 15 Agents de Kil'sorrau. Retournez voir le gardien Moi'bff Jill à Telaar si vous parvenez à accomplir cette tâche."}}
D[9937] = {"ON RECHERCHE : Durn l’Affameur",{"Tuez Durn l'Affameur. Retournez voir le gardien Bullrok si vous parvenez à accomplir cette tâche."}}
D[9938] = {"On recherche : Durn l'Affameur",{"Tuez Durn l'Affameur. Retournez voir le gardien Moi'bff Jill si vous parvenez à accomplir cette tâche."}}
D[9939] = {"On recherche : Zorbo le Conseiller",{"Tuez Zorbo le Conseiller, 10 Chamans Cogneguerre et 10 Ravageurs Cogneguerre. Retournez voir le gardien Bullrok si vous parvenez à accomplir cette tâche."}}
D[9940] = {"On recherche : Zorbo le Conseiller",{"Tuez Zorbo le Conseiller, 10 Chamans Cogneguerre et 10 Ravageurs Cogneguerre. Retournez voir le gardien Moi'bff Jill si vous parvenez à accomplir cette tâche."}}
D[9941] = {"À la recherche des coupables",{"Continuez à chercher des signes de la présence de Deirom dans le village arakkoa, au nord du chariot brisé."}}
D[9942] = {"À la recherche des coupables",{"Continuez à chercher des signes de la présence de Dugar dans le village arakkoa, au nord du chariot brisé."}}
D[9943] = {"Retourner voir Thander",{"Retournez voir Thander au Bastion allérien pour lui rapporter vos découvertes."}}
D[9944] = {"La procession mag'hari disparue",{"Cherchez la procession mag'hari disparue."}}
D[9945] = {"La guerre contre les Cogneguerre",{"L'ancien Yorley de la procession Mag'hari en Nagrand vous a demandé de tuer 8 Brutes Cogneguerre et 8 Démonistes Cogneguerre."}}
D[9946] = {"Cho'war le Pilleur",{"L’Ancien Yorley, de la Procession mag’hari en Nagrand, vous a demandé de tuer Cho’war le Pilleur, et de récupérer la Tête de Cho'war."}}
D[9947] = {"Retourner voir Rokag",{"Retournez voir Rokag au fort des Brise-pierres pour lui rapporter vos découvertes."}}
D[9948] = {"À la recherche des survivants",{"L'ancien Ungriz, à la Procession mag'hari en Nagrand, vous a demandé de libérer 15 Prisonniers mag'har."}}
D[9949] = {"À vol d'oiseau",{"Andarl du Bastion allérien veut que vous lui rapportiez l’Œil du Voile Skith, l’Œil du Voile Shienor et l’Œil du Voile Reskk."}}
D[9950] = {"À vol d'oiseau",{"Apportez l’Œil du Voile Skith, l’Œil du Voile Shienor et l’Œil du Voile Reskk à Kurgatok au fort des Brise-pierres."}}
D[9951] = {"Il vous regarde !",{"Tuez Naphthal'ar puis retournez auprès du gardien Arblos au Fourré cénarien dans la forêt de Terokkar."}}
D[9952] = {"Le prospecteur Balmoral",{"Trouvez le prospecteur Balmoral et parlez-lui."}}
D[9953] = {"Le guetteur Nodak",{"Trouvez le guetteur Nodak et parlez-lui."}}
D[9954] = {"La rançon de Corki",{"Arechron veut que vous retrouviez Corki sur la colline des Cogneguerre."}}
D[9955] = {"Cho'war le Pilleur",{"Corki veut que vous récupériez la Clé de Cho'war pour le faire sortir de sa cage. Si vous parvenez, allez voir Arechron à Telaar."}}
D[9956] = {"La caravane dévastée",{"La chasseresse Kima de Telaar en Nagrand, veut que vous récupériez 20 Caisses de fournitures de Telaar."}}
D[9957] = {"Que se passe-t-il au Fourré cénarien ?",{"Parlez à l'un des druides du Fourré cénarien dans la forêt de Terokkar."}}
D[9958] = {"Reconnaissance des défenses",{"Approchez-vous du Voile Shalas et examinez les défenses de la ville."}}
D[9959] = {"Reconnaissance des défenses",{"Approchez-vous du Voile Shalas et découvrez quels sortilèges protègent la ville."}}
