D[9961] = {"Que se passe-t-il au Fourré cénarien ?",{"Parlez à l'un des druides du Fourré cénarien dans la forêt de Terokkar."}}
D[9962] = {"L'arène de sang : Brisorteil",{"Triomphez de Brisorteil. Si vous l'emportez, allez parler à Wodin le Serviteur-troll pour chercher votre récompense."}}
D[9963] = {"Chercher de l'aide à la source",{"Trouvez Kokorek au Voile Lithic et parlez-lui."}}
D[9964] = {"Chercher de l'aide à la source",{"Trouvez Kokorek au Voile Lithic et parlez-lui."}}
D[9965] = {"Une preuve de bonne volonté",{"Apportez la Tête de Mug'gok à Kokorek au Voile Lithic."}}
D[9966] = {"Une preuve de bonne volonté",{"Apportez la Tête de Mug'gok à Kokorek au Voile Lithic."}}
D[9967] = {"L'arène de sang : les Grands Bleus",{"Battre les Jumeaux bourbesang, qui se font appeler les Grands Bleus. Si vous l'emportez, allez parler à Wodin le Serviteur-troll pour chercher votre récompense."}}
D[9968] = {"Énergie étrange",{"Collectez 4 Spécimens de terophalènes et 4 Spécimens de terophalènes vicieux. Puis retournez auprès du lieur de terre Tavgren juste à l'extérieur du Fourré cénarien dans la forêt de Terokkar."}}
D[9969] = {"Les derniers composants",{"Apportez 5 Essences de chasseur dimensionnel et 30 Airelles de Terokkar à Kokorek au Voile Lithic."}}
D[9970] = {"L'arène de sang : Rokdar le Seigneur scindé",{"Battre Rokdar le Seigneur scindé. Si vous l'emportez, allez parler à Wodin le Serviteur-troll pour chercher votre récompense."}}
D[9971] = {"Des indices au Fourré",{"Examinez l'Objet étrange à côté du Cadavre de Roué pour découvrir ce qui a pu frapper le Fourré cénarien. Puis retournez auprès du lieur de terre Tavgren juste à l'extérieur du fourré dans la forêt de Terokkar."}}
D[9972] = {"L'arène de sang : Skra'gath",{"Battre Skra'gath. Si vous l'emportez, allez parler à Wodin le Serviteur-troll pour chercher votre récompense."}}
D[9973] = {"L'arène de sang : le champion Cogneguerre",{"Battre le Champion Cogneguerre. Si vous l'emportez, allez parler à Wodin le Serviteur-troll pour chercher votre récompense."}}
D[9974] = {"Les derniers composants",{"Apportez 5 Essences de chasseur dimensionnel et 30 Airelles de Terokkar à Kokorek au Voile Lithic."}}
D[9975] = {"Magie primordiale",{"Utilisez le Talisman de Kokorek près des totems qui gardent la route du Voile Shalas, puis parlez au prospecteur Balmoral."}}
D[9976] = {"Magie primordiale",{"Utilisez le Talisman de Kokorek près des totems qui gardent la route du Voile Shalas, puis parlez au guetteur Nodak."}}
D[9977] = {"L'arène de sang : l'ultime défi",{"Battre Mogor, héros des Cogneguerre. Si vous l'emportez, allez parler à Wodin le Serviteur-troll pour chercher votre récompense."}}
D[9978] = {"Par tous les moyens nécessaires",{"Trouvez Empoor sur la route entre Tuurem et Shattrath, dans la Forêt de Terokkar. Puis convainquez-le de vous dire ce qu'il sait."}}
D[9979] = {"Le marchand des vents Lathrai",{"Parlez au Marchand des vents Lathrai près de la Taverne de la Fin du monde dans la Ville basse à Shattrath."}}
D[9980] = {"Sauvez Deirom !",{"Pénétrez dans le Voile Shalas, tuez Luanga et libérez Deirom. Faites votre rapport à dame Dena Kennedy au Bastion allérien lorsque vous aurez accompli votre mission."}}
D[9981] = {"Sauvez Dugar !",{"Pénétrez dans le Voile Shalas, tuez Luanga et libérez Dugar. Faites votre rapport à Rokag au fort des Brise-pierres lorsque vous aurez accompli votre mission."}}
D[9982] = {"Il se fait appeler Altruis...",{"Si vous cherchez à affronter la Légion ardente, allez trouver Altruis le Souffrant dans l'ouest de Nagrand."}}
D[9983] = {"Il se fait appeler Altruis...",{"Si vous cherchez à affronter la Légion ardente, allez trouver Altruis le Souffrant dans l'ouest de Nagrand."}}
