D[10008] = {"Ce qui se passe à Terokkar reste à Terokkar",{"Le traqueur des ombres Kaide veut que vous alliez tuer 10 Dévastateurs Mâche-les-os et 6 Brise-dos Mâche-les-os."}}
D[10009] = {"Casser des crânes",{"Sal'salabim de Shattrath veut que vous récupériez la Dette de Raliq, la Dette de Coosh'coosh et la Dette de Floon."}}
D[10010] = {"C'est si facile ?",{"Sal'salabim de Shattrath veut que vous retourniez voir Altruis le Souffrant dans l'ouest de Nagrand."}}
D[10011] = {"Le camp de forge : Anéanti",{"Altruis le Souffrant dans l'ouest de Nagrand vous a demandé de détruire le Camp de forge Haine et le Camp de forge Peur."}}
D[10012] = {"Les plans des Gangr’orcs",{"Apportez les Plans des Gangr’orcs à Bertelm au Bastion allérien, dans la Forêt de Terokkar."}}
D[10013] = {"Une main invisible",{"Apportez les Plans des Gangr’orcs à Rokag au Fort des Brise-Pierres, dans la Forêt de Terokkar."}}
D[10014] = {"Le projet de la halte Aile-de-feu",{"Volez les quatre Feuilles de code de la bombe de mana et apportez-les au lieutenant Meridian au Poste allérien dans la forêt de Terokkar."}}
D[10015] = {"Le projet de la halte Aile-de-feu",{"Volez les quatre Feuilles de code de la bombe de mana et apportez-les au sergent Chawni au camp des Brise-pierres dans la forêt de Terokkar."}}
D[10016] = {"Les queues de worgs des bois",{"Bertelm du Bastion allérien veut que vous lui apportiez 12 Queues de worgs des bois. Vous pouvez prendre ces queues soit sur des worgs des bois, soit sur des worgs Alpha des bois."}}
D[10017] = {"Des réserves durement sollicitées",{"Apportez 8 Glandes à venin de croc-d'effroi à Sha'nir à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10018] = {"Les habits de l'esprit du loup",{"Apportez 12 Fourrures de worg des bois à Malukaz au fort des Brise-pierres."}}
D[10019] = {"Plus de glandes à venin"}
D[10020] = {"Un remède pour Zahlia",{"Apportez le Sang de Regard-de-pierre à Sha'nir à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10021] = {"Rétablir la Lumière",{"Ishanah veut que vous vous rendiez à l'avant-poste arakkoa à l'est de Shattrath et que vous utilisiez la Fiole bénite pour purifier l'Autel de l'est, l'Autel de l'ouest et l'Autel du nord.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
