D[10023] = {"Le patriarche Gueule-de-fer",{"Apportez la Fourrure de Gueule-de-fer à Malukaz au fort des Brise-Pierres."}}
D[10024] = {"Les visions de Voren'thal",{"Apportez 8 Yeux de basilic trempécaille à l'arcaniste Adyria à Shattrath.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10025] = {"Plus d'yeux de basilic",{"Il faut beaucoup d'yeux de basilic pour faire ne serait-ce qu'une petite dose d'élixir de Voren'thal. Si vous m'en apportiez plus, cela vous attirerait sans nul doute la faveur des Clairvoyants."}}
D[10026] = {"Perturbations magiques",{"Andarl du Bastion allérien veut que vous alliez tuer 10 Traqueurs dimensionnels."}}
D[10027] = {"Perturbations magiques",{"Tuez 10 Traqueurs dimensionnels et retournez voir Kurgatok au fort des Brise-pierres."}}
D[10028] = {"Calices de puissance",{"Apportez 8 Calices draeneï à Ros'eleth au Bastion allérien."}}
D[10029] = {"L'appel des esprits",{"L'anachorète Lyteera veut que vous trouviez son assistant, Soolaveen, à la Caravane des réfugiés dans le désert des Ossements de la forêt de Terokkar.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10030] = {"La récupération des os",{"Récupérez 10 Ossements sans repos. Apportez-les à Ramdor le Fol, juste à côté du côté ouest du Cercle d'observance à Auchindoun, qui se trouve au milieu du désert des Ossements de la forêt de Terokkar."}}
D[10031] = {"Aider les Perdus à trouver leur chemin",{"Détruisez 10 Esprits perdus et 10 Squelettes roués, puis parlez à Soolaveen à la Caravane de réfugiés, dans le désert des Ossements de la forêt de Terokkar."}}
D[10033] = {"On recherche : des Fouette-radius morts !",{"Tuez 20 Fouette-radius puis retournez voir Taela Vassanfin au Bastion allérien dans la forêt de Terokkar."}}
D[10034] = {"On recherche : des Fouette-radius morts !",{"Tuez 20 Fouette-radius puis retournez voir Mawg Trait-sinistre au fort des Brise-pierres dans la forêt de Terokkar."}}
D[10035] = {"Torgos !",{"Faites venir Torgos à l'aide de la Carcasse de Trachela. Procurez-vous une Plume de la queue de Torgos et rapportez-la à Taela Vassanfin au Bastion allérien dans la forêt de Terokkar."}}
D[10036] = {"Torgos !",{"Faites venir Torgos à l'aide de la Carcasse de Trachela. Procurez-vous une Plume de la queue de Torgos et apportez-la à Mawg Trait-sinistre au fort des Brise-Pierres dans la forêt de Terokkar."}}
D[10037] = {"J'préférerais aller à la pêche",{"Apportez 8 Anguilles Scintécaille en parfait état à Seth à Shattrath."}}
D[10038] = {"Parler au soldat Weeks",{"Trouvez le soldat Weeks près de l'entrée nord de Grangol'var dans la forêt de Terokkar et parlez-lui."}}
D[10039] = {"Parler à l'éclaireur Neftis",{"Trouvez l'éclaireur Neftis près de l'entrée sud de Grangol'var dans la forêt de Terokkar et parlez-lui."}}
D[10040] = {"Qui sont-ils ?",{"Parlez avec l'Initié ténébreux, le Travailleur ténébreux et le Conseiller ténébreux en portant le déguisement. Puis retournez voir le soldat Weeks à Grangol'var dans la forêt de Terokkar."}}
D[10041] = {"Qui sont-ils ?",{"Parlez avec l'Initié ténébreux, le Travailleur ténébreux et le Conseiller ténébreux en portant le déguisement. Puis retournez voir l'éclaireur Neftis à Grangol'var dans la forêt de Terokkar."}}
D[10042] = {"Tuer le Conseil des ombres !",{"Tuez 10 Exécuteurs ténébreux, 10 Invocateurs ténébreux et le Maître d'ombre Dolent, puis retournez auprès du lieutenant Gravillemartel au Bastion allérien dans la forêt de Terokkar."}}
D[10043] = {"Tuer le Conseil des ombres !",{"Tuez 10 Exécuteurs ténébreux, 10 Invocateurs ténébreux et le Maître d'ombre Dolent, puis retournez auprès de la conseillère Faila au fort des Brise-Pierres dans la forêt de Terokkar."}}
D[10044] = {"Une visite à la grande-mère",{"Parlez à la grande-mère Geyah et écoutez ce qu'elle a à vous dire."}}
D[10045] = {"Composants matériels",{"La grande-mère Geyah de Garadar en Nagrand vous a demandé de cueillir 1 Racine d'Olemba, 1 Canneberge, 1 Palme telaari et 1 Épine-de-dragon."}}
D[10046] = {"À travers la Porte des ténèbres",{"Traversez la Porte des ténèbres et parlez à Nazgrel à Thrallmar."}}
D[10047] = {"Le sentier de la Gloire",{"Purifiez 8 Squelettes piétinés sur le Sentier de la Gloire avec de l'Eau bénite draeneï, puis retournez voir le Scrute-dimensions Kryv au bastion de l'Honneur."}}
D[10048] = {"Une poignée de poussière magique",{"Récoltez 7 poignées de Poudre pacifiante pour Andarl au Bastion allérien."}}
D[10049] = {"Une poignée de poussière magique",{"Récoltez 7 poignées de Poudre pacifiante pour Kurgatok au fort des Brise-pierres."}}
D[10050] = {"Âmes Inflexibles",{"Le garde d'honneur Wesilow veut que vous vainquiez 12 Fantassins inflexibles, 10 Ensorceleurs inflexibles et 5 Chevaliers inflexibles à l'Armurerie de l'expédition, au sud."}}
D[10051] = {"L'évasion de la halte Aile-de-feu",{"Escortez Isla Tressétoile jusqu'à un lieu sûr puis faites votre rapport au capitaine Auric Courresoleil au Bastion allérien dans la forêt de Terokkar."}}
D[10052] = {"L'évasion de la halte Aile-de-feu",{"Escortez Isla Tressétoile jusqu'à un lieu sûr puis faites votre rapport à la conseillère Faila au fort des Brise-pierres dans la forêt de Terokkar."}}
D[10053] = {"S'occuper de Zeth'Gor",{"Tuez Grillok « Sombroeil » et fouillez son repaire à la recherche des Plans d'attaque de l'Orbite-sanglante."}}
D[10054] = {"Désastre imminent",{"Tuez 15 Grunts de l'Orbite-sanglante, 10 Nécrolytes de l'Orbite-sanglante, 5 Péons de l'Orbite-sanglante et le seigneur de guerre Morkh, puis faites votre rapport au lieutenant Amadi dans la tour ouest du bastion de l'Honneur."}}
D[10055] = {"Faut pas gâcher",{"Apportez 8 morceaux de Métal récupéré et 8 morceaux de Bois récupéré à Dumphry au bastion de l'Honneur."}}
D[10056] = {"Les fournitures de l'Orbite-sanglante",{"Détruisez 6 piles de Fournitures de l'Orbite-sanglante et faites votre rapport au lieutenant Amadi au bastion de l'Honneur."}}
D[10057] = {"Se tourner vers les chefs",{"Triomphez des fantômes de l'archimage Xintor et du lieutenant-commandant Thalvos, puis retournez voir le garde d'honneur Wesilow à la tour au nord-ouest du bastion de l'Honneur."}}
D[10058] = {"Un cadeau ancien",{"Récupérez les « Mystères de la Lumière » et rapportez-le au père Malgor Devidicus au bastion de l’Honneur."}}
D[10059] = {"S'occuper de Zeth'Gor",{"Tuez Grillok « Sombroeil » et fouillez son repaire à la recherche des Plans d'attaque de l'Orbite-sanglante."}}
D[10060] = {"Désastre imminent",{"Tuez 15 Grunts de l'Orbite-sanglante, 10 Nécrolytes de l'Orbite-sanglante, 5 Péons de l'Orbite sanglante et le seigneur de guerre Morkh. Puis faites votre rapport au garde de pierre Ambelan sur la crête Brise-épine."}}
D[10061] = {"Les Inflexibles",{"Grelag veut que vous vainquiez 12 Fantassins inflexibles, 10 Ensorceleurs inflexibles et 5 Chevaliers inflexibles à l'Armurerie de l'expédition, au sud du bastion de l'Honneur."}}
D[10062] = {"Tourné vers le commandement",{"Triomphez des fantômes de l'archimage Xintor et du lieutenant-commandant Thalvos, puis retournez voir Grelag sur la Crête brise-échine."}}
D[10063] = {"La Ligue des explorateurs ? C'est pas un truc de gnomes ?",{"Trouvez Clopper Crackboum, qui campe dans une vieille carapace de tortue sur la côte au nord du Guet du sang."}}
D[10064] = {"Parle à la main",{"Présentez-vous à l'éclaireur Jorli au Repos du redresseur de torts."}}
D[10065] = {"Ouvrir un chemin",{"Tuez 10 Ravageurs enragés puis retournez voir l'éclaireur Jorli au Repos du redresseur de torts."}}
D[10066] = {"Oh, quelle toile embrouillée...",{"Tuez 8 Noueurs mutés et faites votre rapport au redresseur de torts Corin au Repos du redresseur de torts."}}
D[10067] = {"Les élémentaires d'eau souillée",{"Tuez 6 Élémentaires d'eau souillés et retournez voir le redresseur de torts Corin au Repos du redresseur de torts."}}
D[10068] = {"Nova de givre",{"Atteignez le Niveau 3 pour apprendre la Nova de givre, puis cherchez un Mannequin d’entraînement près de la Flèche solaire et utilisez ce nouveau sort 2 fois."}}
D[10069] = {"Le veilleur du puits Solanian",{"Parlez au veilleur du puits Solanian à la Flèche solaire sur l'île de Haut-soleil."}}
D[10070] = {"Le tir assuré",{"Atteignez le Niveau 3 pour apprendre le Tir assuré, puis trouvez un Mannequin d’entraînement près de la Flèche solaire et utilisez le Tir assuré contre lui à cinq reprises."}}
D[10071] = {"L'éviscération",{"Atteignez le Niveau 3 pour apprendre l’Éviscération, puis trouvez un Mannequin d’entraînement près de la Flèche Solaire et utilisez l’Éviscération sur lui à trois reprises."}}
D[10072] = {"Apprendre le mot",{"Atteignez le niveau 3 pour apprendre Mot de l’ombre : Douleur. Utilisez-le 5 fois sur un Mannequin d’entraînement à côté."}}
D[10073] = {"Corruption",{"Atteignez le niveau 3 pour apprendre Corruption. Trouvez un Mannequin d’entraînement devant la Flèche solaire et utilisez 5 fois Corruption."}}
D[10074] = {"La poudre de cristal d'Oshu'gun",{"La directrice de recherche Amereldine de Halaa veut 20 Échantillons de poudre de cristal d'Oshu'gun."}}
D[10075] = {"La poudre de cristal d'Oshu'gun",{"Cette base était le principal centre de recherche où les draeneï étudiaient les cristaux naaru.","","Nous avons découvert une véritable mine d’or sous la forme de notes consacrées aux cristaux de la « montagne de diamant », Oshu’gun. On dirait que tout, dans la région, contient une parcelle de pouvoir des cristaux d’Oshu’gun. Si vous trouvez de la poudre lorsque vous sillonnerez la région, remettez-la-moi. En échange, je vous donnerai un petit quelque chose qui vous permettra de faire des achats auprès de notre service d’intendance."}}
D[10076] = {"La poudre de cristal d'Oshu'gun",{"Le directeur de recherche Kartos de Halaa veut 20 Échantillons de poudre de cristal d'Oshu'gun."}}
D[10077] = {"La poudre de cristal d'Oshu'gun",{"Cette base était le principal centre de recherche où les <race> étudiaient les cristaux naaru.","","Nous avons découvert une véritable mine d’or sous la forme de notes consacrées aux cristaux de la « montagne de diamant », Oshu’gun. On dirait que tout, dans la région, contient une parcelle de pouvoir des cristaux d’Oshu’gun. Si vous trouvez de la poudre lorsque vous sillonnerez la région, remettez-la-moi. En échange, je vous donnerai un petit quelque chose qui vous permettra de faire des achats auprès de notre service d’intendance."}}
D[10078] = {"Anéantir les indésirables",{"Utilisez la Torche enflammée pour brûler les Lance-lames de la Horde surplombant le sentier de la Gloire. Puis apportez la Torche enflammée à Dumphry au bastion de l'Honneur."}}
D[10079] = {"Mineur, tu dors, ton wagon va trop vite",{"Tuez 12 Sapeurs gan'arg puis retournez voir le contremaître Biggums."}}
D[10081] = {"Rencontrer Mère Kashur",{"La Grande-mère Geyah veut que vous parliez avec Mère Kashur."}}
D[10082] = {"Les ancêtres agités",{"Mère Kashur vous a demandé de donner le repos à 8 Esprits orcs agités."}}
D[10084] = {"L'attaque de Mageddon",{"Tuez le Seigneur de la nuit Malphas à la Base de forge Mageddon, et retournez auprès du Commandant Danath Trollemort au Bastion de l'Honneur."}}
D[10085] = {"Une visite aux ancêtres",{"Mère Kashur des Terres ancestrales en Nagrand vous a demandé de visiter le Poste de Berceau-de-l’Été, les Ruines du Crâne-Ricanant, Garadar et les Ruines de l'Orbite-Sanglante."}}
D[10086] = {"Je travaille... Pour la Horde !",{"Apportez 8 morceaux de Métal récupéré et 8 morceaux de Bois récupéré à Megzeg Phalanjette à Thrallmar."}}
D[10087] = {"Brûlez-les... Pour la Horde !",{"Utilisez la Torche enflammée pour brûler le Canon est de l'Alliance et le Canon ouest de l'Alliance, puis revenez voir Megzeg Phalanjette à Thrallmar."}}
D[10088] = {"Mineur, tu dors, ton wagon va trop vite",{"Tuez 12 Sapeurs gan'arg et retournez voir le contremaître Razelcraz."}}
D[10089] = {"Camps de forge de la Légion",{"Tuez 10 Serviteurs gan'arg, 5 Légionnaires du camp de forge et 5 Sœurs de la peine, puis fouillez le camp de forge Rage à la recherche d'indices concernant les intentions de la Légion."}}
D[10090] = {"Les plans de la Légion",{"Récupérez les Plans du camp de forge Dépit et apportez-les au suzerain Hun Mutilepoing au Trépas du saccageur."}}
D[10091] = {"Les machines à âmes",{"Volez 5 Machines à âmes puis apportez-les à la maître-espionne Mehlisah Hautecouronne sur la terrasse de la Lumière à Shattrath."}}
D[10092] = {"L'attaque de Mageddon",{"Tuez le Seigneur de la nuit Malphas à la Base de forge Mageddon, et retournez auprès du Suzerain Hun Mutilepoing au Trépas du saccageur."}}
D[10093] = {"Le temple de Telhamat",{"Parlez à Amaan le Sage au Temple de Telhamat dans l'ouest de la Péninsule des Flammes infernales."}}
D[10094] = {"Le codex de sang",{"Lisez le Codex de sang dans le Labyrinthe des ombres d'Auchindoun."}}
D[10095] = {"Au cœur du labyrinthe",{"Détruisez Marmon, puis allez à la terrasse de la Lumière à Shattrath pour faire un rapport de ce qui s'est passé dans le Labyrinthe des ombres à la maître-espionne Mehlisah Hautecouronne."}}
D[10096] = {"Sauver les Sporeloks",{"Tuez 10 Drague-marais et 10 Rôdeurs des marais, puis retournez voir Lauranna Thar'well au Refuge cénarien dans le marécage de Zangar."}}
D[10097] = {"Frère contre frère",{"Tuez le tisseur d'ombre Syth dans les salles des Sethekk, puis libérez Lakka. Retournez voir Isfar à l'extérieur des salles des Sethekk lorsque vous aurez réussi à la sauver."}}
D[10098] = {"L'héritage de Terokk",{"Apportez le Masque de Terokk, la Rémige de Terokk et la Saga de Terokk à Isfar à l'extérieur des salles des Sethekk."}}
D[10099] = {"Le cerveau",{"Trouvez et tuez Z'kral dans les mines sous le bastion de l'Honneur, puis faites votre rapport au contremaître Biggums."}}
D[10100] = {"Le cerveau",{"Trouvez et tuez Urga'zz dans les mines sous Thrallmar, puis faites votre rapport au contremaître Razelcraz."}}
D[10101] = {"Lorsque les esprits parlent",{"Mère Kashur des Terres ancestrales en Nagrand vous a demandé de partir à la recherche de la vision que vous avez eue. Trouvez K'ure à Oshu'gun."}}
D[10102] = {"Un secret dévoilé",{"Parlez à A'dal à Shattrath."}}
D[10103] = {"Faire son rapport à Zurai",{"Présentez-vous à Zurai au poste du Rat des marais dans le marécage de Zangar."}}
D[10104] = {"Des soucis à Tuurem",{"Parlez à Andarl au Bastion allérien dans la forêt de Terokkar."}}
D[10105] = {"Des nouvelles pour Rakoria",{"Parlez à Rakoria, au fort des Brise-pierres dans la forêt de Terokkar."}}
D[10106] = {"Les fortifications des Flammes infernales",{"Prendre le Surplomb, le Stade et la Colline brisée, puis retourner voir l'adjudante Tracy Fièrepuits au bastion de l'Honneur dans la péninsule des Flammes infernales."}}
D[10107] = {"Mesures diplomatiques",{"Jorin Œil-mort de Garadar en Nagrand vous a demandé de trouver Lantresor de la Lame dans les ruines de la Lame-Ardente et de lui parler."}}
D[10108] = {"Mesures diplomatiques",{"Mo'mor le Briseur, de Telaar en Nagrand, vous a demandé de trouver Lantresor de la Lame dans les ruines de la Lame-Ardente et de lui parler."}}
D[10109] = {"Il me les faut !",{"Koissa, qui se trouve en face du Guet des clans dans le sud de Nagrand, veut que vous lui apportiez 3 Gaz d'élémentaires d'air."}}
D[10110] = {"Les fortifications des Flammes infernales",{"Prendre le Surplomb, le Stade et la Colline brisée, puis retourner voir le Crieur-de-guerre Coquard à Thrallmar."}}
D[10111] = {"Rapportez-moi cet œuf !",{"Koissa, de Nagrand, veut que vous utilisiez le Bond-o-tron 4000 pour parvenir jusqu'au nid de l'arbre tout proche et voler l'Œuf mystérieux."}}
D[10112] = {"Une faveur personnelle",{"Récupérez 5 des Marchandises volées de Lathrai. Rapportez-les au marchand des vents Lathrai près de la Taverne de la Fin du monde dans le quartier de la Ville basse de Shattrath."}}
D[10113] = {"Le safari de Nesingwary",{"Jones \"Fusil\" veut que vous parliez à Hemet Nesingwary au safari de Nesingwary, en périphérie du nord-est de Nagrand."}}
D[10114] = {"Le safari de Nesingwary",{"Ohlorn Pérégrin veut que vous parliez à Shado \"Fitz\" Pérégrin au safari de Nesingwary en Nagrand."}}
D[10115] = {"La déviance des Tourbedague",{"Tuez 3 Assassins Tourbedague et 15 Marche-boue Tourbedague."}}
D[10116] = {"On recherche : chef Mummaki",{"Apportez le Totem du chef Mummaki à Ikuti au Havre d'Orebor."}}
D[10117] = {"On recherche : chef Mummaki",{"Apportez le Totem du chef Mummaki au chasseur des ombres Denjai."}}
D[10118] = {"Un message pour les Tourbedague",{"Tuez 3 Assassins tourbedagues et 15 Marche-boue tourbedagues, puis retournez voir le Chasseur des ombres Denjai à Zabra'jin."}}
D[10119] = {"À travers la Porte des ténèbres",{"Traversez la Porte des ténèbres et allez trouver le commandant Duron. Il attend votre arrivée de l'autre côté - en Outreterre."}}
D[10120] = {"Arrivée en Outreterre",{"Le général de division Orion à la Porte des ténèbres dans la péninsule des Flammes infernales veut que vous apportiez le Rapport d'Orion à Vlagga Fileplume."}}
D[10121] = {"Éradiquer la Légion ardente",{"Parlez au sergent Fracasse-crâne à la Caravane de ravitaillement, juste à l'extérieur de Thrallmar, à l'est."}}
D[10122] = {"À portée de la citadelle",{"Fouillez le camp le plus au nord le long du Rempart du sud à la recherche de traces du soldat Imarion."}}
D[10123] = {"Le Ravin de Gangrétincelle",{"Le sergent Fracasse-crâne de la Caravane de ravitaillement à l'est de Thrallmar dans la péninsule des Flammes infernales veut que vous alliez tuer 4 Diablotins Attise-flammes, 6 Porteguerres infernaux et 1 Mande-effroi."}}
D[10124] = {"Poste avancé : Trépas du saccageur",{"Présentez-vous au commandant des lignes avancées To'arch au Trépas du saccageur."}}
D[10125] = {"Mission : Brouiller les communications",{"Le commandant des lignes avancées To'arch du Trépas du saccageur dans la péninsule des Flammes infernales vous a demandé d'utiliser les Explosifs de To'arch et de détruire l'Antenne de la Légion : Mépris, l'Antenne de la Légion : Haine, et l'Antenne de la Légion : Peur."}}
D[10126] = {"Les ordres de Nekrogg le Mène-guerre",{"Voyagez vers le sud le long du côté ouest du Rempart du sud et fouillez le prochain camp à la recherche de signes du soldat Imarion."}}
D[10127] = {"Mission : Couper le cordon",{"Le commandant des lignes avancées To'arch du Trépas du saccageur dans la péninsule des Flammes infernales vous a demandé de tuer 4 Dresseurs gangrenés, 8 Garde-courroux et le Dominateur Shi'aziv."}}
D[10128] = {"Il faut sauver le soldat Imarion",{"Poursuivez vers le sud le long du Rempart du sud et cherchez l'endroit où le mène-guerre Nekrogg détient le soldat Imarion."}}
D[10129] = {"Mission : Portes Murketh et Shaadraz",{"Parlez au chef d'escadrille Brack, bombardez la Porte Murketh et la Porte Shaadraz, puis retournez voir le commandant des lignes avancées To'arch au Trépas du saccageur."}}
D[10130] = {"Le flanc ouest",{"Tuez 10 Gardes de la Main brisée, 10 Berserkers de la Main brisée et 5 Acolytes de la Main brisée, puis faites votre rapport au lieutenant Amadi dans la tour de garde ouest du bastion de l'Honneur."}}
D[10131] = {"Préparation de l'évasion",{"Tuez un Grenadier de la Main brisée et apportez ses Explosifs rudimentaires au soldat Imarion à l'avant-poste de Gor'gaz."}}
D[10132] = {"Menace colossale",{"Tuez 5 Colosses déchaînés puis retournez voir Tola'thion au Poste cénarien dans la péninsule des Flammes infernales."}}
D[10133] = {"Mission : Tuer le messager",{"Le commandant des lignes avancées To'arch du Trépas du saccageur dans la péninsule des Flammes infernales vous a demandé de trouver et tuer Arix'malidash et de récupérer la Missive de la Légion."}}
D[10134] = {"Un indice de cristal cramoisi",{"Apportez l'Éclat de cristal cramoisi à Tola'thion au Poste cénarien dans la péninsule des Flammes infernales."}}
D[10135] = {"Mission : Être le messager",{"Apportez la Missive de la Légion à Nazgrel, à Thrallmar dans la péninsule des Flammes infernales."}}
D[10136] = {"Les Liaisons cruelles",{"Tuez Arazzius le Cruel, puis retournez voir Nazgrel à Thrallmar."}}
D[10137] = {"Provoquer le Mène-guerre",{"Utilisez les Explosifs rudimentaires pour semer le trouble et attirer le mène-guerre Nekrogg hors de sa tour. Tuez-le, prenez la clé de Nekrogg et utilisez-la pour ouvrir la cage du soldat Imarion. Une fois que vous aurez libéré Imarion, présentez-vous au lieutenant Amadi."}}
D[10138] = {"Sous les ordres de qui ?",{"Tuez 20 Grunts de la Main brisée et 10 Démonistes de la Main brisée, et emparez-vous des Ordres du maître de manœuvre Zurok. Puis retournez voir le lieutenant Amadi à la tour de garde ouest du bastion de l'Honneur."}}
D[10139] = {"Liquider le commandant",{"Tuez le commandant de corps Gorax et faites votre rapport au lieutenant Amadi dans la tour ouest du bastion de l'Honneur."}}
D[10140] = {"En route pour le bastion de l'Honneur",{"Volez jusqu'au bastion de l'Honneur et apportez le Rapport de Duron au maréchal Isildor."}}
D[10141] = {"La renaissance de la Légion",{"Parlez au sergent Altumus à la Caravane de ravitaillement de l'est, juste à l'extérieur du bastion de l'Honneur, à l'est."}}
D[10142] = {"Le chemin de l'Angoisse",{"Le sergent Altumus de la Caravane de ravitaillement de l'est, qui se trouve à l'est du bastion de l'Honneur dans la péninsule des Flammes infernales, vous a demandé de tuer 4 Diablotins attise-flammes, 6 Porteguerres infernaux et 1 Mande-effroi."}}
D[10143] = {"La halte de l'expédition",{"Présentez-vous au commandant des lignes avancées Kingston à la Halte de l'expédition."}}
D[10144] = {"Couper l'ennemi de ses renforts",{"Tuez des ennemis du Portail Grimh et du Portail Kaalez pour collecter des Pierres runiques démoniaques.","","Utilisez les Amorces de Kingston à l'intérieur du Portail Grimh et du Portail Kaalez.","","Retournez voir le commandant des lignes avancées Kingston avec les explosifs restants."}}
D[10145] = {"Mission: Sever the Tie UNUSED",{"Le commandant des lignes avancées Kingston de la Halte de l'expédition dans la péninsule des Flammes infernales vous a demandé de tuer 4 Dresseurs gangrenés, 8 Garde-courroux et le Dominateur Yalqiz."}}
D[10146] = {"Mission : Portes Murketh et Shaadraz",{"Parlez au Chef d'escadrille Dabir'ee, bombardez la Porte Murketh et la Porte Shaadraz, puis retournez voir le Commandant des lignes avancées Kingston à la Halte de l'expédition."}}
D[10147] = {"Mission : Tuer le messager",{"Le commandant des lignes avancées Kingston de la Halte de l'expédition dans la péninsule des Flammes infernales vous a demandé de trouver et tuer Arix'malidash et de récupérer la Missive de la Légion."}}
D[10148] = {"Mission : Être le messager",{"Apportez la Missive de la Légion au commandant de corps Danath Trollemort, au bastion de l'Honneur dans la péninsule des Flammes infernales."}}
D[10149] = {"Mission : Point final",{"Le commandant de corps Danath Trollemort au bastion de l'Honneur dans la péninsule des Flammes infernales vous a demandé de tuer Arazzius le Cruel."}}
D[10150] = {"À portée de la citadelle",{"Fouillez le camp le plus au nord le long du Rempart du nord à la recherche de traces de l'éclaireur Makha."}}
D[10151] = {"Les ordres de Nekrogg le Mène-guerre",{"Voyagez vers le sud le long du côté ouest du Rempart du nord et fouillez le prochain camp à la recherche de signes de l'éclaireur Makha."}}
D[10152] = {"Le flanc ouest",{"Tuez 10 Gardes de la Main brisée, 10 Berserkers de la Main brisée et 5 Acolytes de la Main brisée, puis faites votre rapport au garde de pierre Ambelan au Poste de Brise-échine près de Zeth'Gor."}}
D[10153] = {"Il faut sauver l'éclaireur Makha",{"Poursuivez vers le sud en traversant le sentier de la Gloire vers le Rempart du sud et cherchez l'endroit où le mène-guerre Nekrogg détient l'éclaireur Makha."}}
D[10154] = {"Préparation de l'évasion",{"Trouvez un Grenadier de la Main brisée et apportez ses Explosifs rudimentaires à l'éclaireur Makha à l'avant-poste de Gor'gaz."}}
D[10155] = {"Provoquer le Mène-guerre",{"Utilisez les Explosifs rudimentaires pour semer le trouble et attirer le mène-guerre Nekrogg hors de sa tour. Tuez-le, prenez la clé de Nekrogg et utilisez-la pour ouvrir la cage de l'éclaireur Makha. Une fois que vous aurez libéré Makha, présentez-vous au garde de pierre Ambelan au Poste de Brise-échine près de Zeth'Gor."}}
D[10156] = {"Sous les ordres de qui ?",{"Tuez 20 Grunts de la Main brisée et 10 Démonistes de la Main brisée, et emparez-vous des Ordres du maître de manœuvre Zurok. Puis retournez voir le garde de pierre Ambelan au Poste de Brise-échine."}}
D[10157] = {"Liquider le commandant",{"Tuez le commandant de corps Gorax et faites votre rapport au chasseur des ombres Ty'jin à Thrallmar."}}
D[10158] = {"Les fournitures de l'Orbite-sanglante",{"Détruisez 6 piles de Fournitures de l'Orbite-sanglante et faites votre rapport au garde de pierre Ambelan au Poste de Brise-échine."}}
D[10159] = {"Nettoyer la colline de Roncecroc",{"Tuez 8 Ravageurs Roncecroc et 8 Crache-venin Roncecroc, puis retournez voir Mahuram Sabot-robuste au Poste cénarien dans la péninsule des Flammes infernales."}}
D[10160] = {"Connais ton adversaire",{"Parlez au lieutenant Amadi à la vieille tour de garde juste à l'ouest du bastion de l'Honneur."}}
D[10161] = {"En cas d'urgence...",{"« Retrouvez 30 Débris de zeppelin et rapportez-les à Laïus « Brailleur » Airbuse à l'Épave du zeppelin. »"}}
D[10162] = {"Mission : La saillie abyssale",{"Le commandant des lignes avancées To'arch du Trépas du saccageur dans la péninsule des Flammes infernales vous demande de détruire 20 Péons gan'arg, 5 Surveillants mo'arg et 5 Gangrecanons."}}
D[10163] = {"Mission : La saillie abyssale",{"Le chef d'escadrille Griffongar de la Halte de l'expédition dans la péninsule des Flammes infernales vous a demandé de détruire 20 Péons gan'arg, 5 Surveillants mo'arg et 5 Gangrecanons."}}
D[10164] = {"Tout va bien se passer",{"Grandpère Aldrimus, à l'extérieur des Cryptes Auchenaï d'Auchindoun, vous a demandé d'entrer dans les Cryptes Auchenaï et de détruire l'Exarque Maladaar."}}
D[10165] = {"Casser les prix",{"Le prince-nexus Haramad, qui se trouve à l'extérieur des Tombes-mana, veut que vous alliez tuer le prince-nexus Shaffar et que vous lui rapportiez le Cafetan de Shaffar."}}
D[10166] = {"La mémoire de Blanchécorce",{"Larianna Ruissevent veut que vous placiez le Pendentif du vieux Blanchécorce près de la pierre runique au Bosquet incendié."}}
D[10167] = {"Auchindoun...",{"Voyagez jusqu'aux Cryptes Auchenaï dans le désert des Ossements de la forêt de Terokkar et tuez l’Exarque Maladaar pour libérer l'esprit de D'ore."}}
D[10168] = {"Par les yeux de l'âme...",{"Trouvez un Miroir des âmes quelque part dans les cryptes Auchenaï et utilisez-le pour invoquer un Esprit assombri issu des Ancêtres d'anciens orcs en Nagrand. Détruisez 15 Esprits assombris afin que les ancêtres puissent reposer en paix.","","Retournez voir Mère Kashur dans les Terres ancestrales lorsque vous aurez terminé cette tâche."}}
D[10169] = {"Il faut savoir perdre",{"Le magistère Falris de Shattrath veut que vous apportiez la Fiole de sérum sédatif sur la Terrasse de la Lumière et que vous la versiez dans la Marmite du régiment d'Haronem."}}
D[10170] = {"Retourner voir la grande-mère",{"Retournez à Garadar et parlez à la grande-mère Geyah."}}
D[10171] = {"Le chef inconsolable",{"La grande-mère Geyah à Garadar vous a demandé de parler à Garrosh."}}
D[10172] = {"Il n'y a plus d'espoir",{"Parlez à la grande-mère Geyah et rapportez-lui les propos de Garrosh."}}
D[10173] = {"Le bâton de l'archimage",{"Reprenez le Bâton de l'archimage Vargoth à Ekkorash l'Inquisitrice et apportez-le à Ravandwyr dans la Zone 52. Pour faire sortir Ekkorash de sa cachette, répandez la Poudre d'abjuration sur le brasero au centre des ruines."}}
D[10174] = {"La malédiction de la Tour pourpre",{"Utilisez le Bâton de l'archimage Vargoth pour entrer en contact avec ce dernier.","","Si vous perdez le Bâton de l’archimage Vargoth, allez voir Ravandwyr dans la Zone 52 pour obtenir un double."}}
D[10175] = {"Thrall, fils de Durotan",{"Rendez-vous à Orgrimmar et apportez le message de Geyah à Thrall."}}
D[10176] = {"Ar'kelos le Gardien",{"Entrez dans la Tour pourpre au centre de Kirin'Var et triomphez d'Ar'kelos, puis parlez à l'archimage Vargoth."}}
D[10177] = {"Troubles à Auchindoun",{"Présentez-vous au commandant Mahfuun à l'entrée du Labyrinthe des ombres à Auchindoun dans la forêt de Terokkar."}}
D[10178] = {"Trouver l'espion To'gun",{"Trouvez l'espion To'gun dans le Labyrinthe des ombres d'Auchindoun."}}
D[10179] = {"Le protecteur de Kirin'Var",{"Parlez au Protecteur Valemort à Kirin'Var."}}
D[10180] = {"Incapable de rester à l'écart",{"Parlez à Isfar, qui se trouve près de l'entrée des salles des Sethekk à Auchindoun."}}
D[10182] = {"Le mage de bataille Dathric",{"Trouvez le domicile du mage de bataille Dathric dans l'Allée des sorciers et replacez sa Lame sur le râtelier d'armes. Puis parlez au protecteur Valemort à Kirin Var."}}
D[10183] = {"En route pour la Zone 52",{"Apportez les Notes du néantologue au chef-de-fusée Karlingue dans la Zone 52 au Raz-de-Néant."}}
D[10184] = {"Vestiges malveillants",{"Le protecteur Valemort de Kirin'Var veut que vous vainquiez 20 Esprits disjoints de la Place centrale de Kirin'Var."}}
D[10185] = {"Un sort pire que la mort",{"Tuez 10 Pourfend-mage et 10 Chercheurs de mana puis retournez voir le protecteur Valemort à Kirin'Var."}}
D[10186] = {"On vous engage !",{"Ramassez 10 Cristaux de matrice d'etherlithium et apportez-les au chef-de-fusée Karlingue dans la Zone 52 au Raz-de-Néant."}}
D[10187] = {"Un message pour l'archimage",{"Parlez à l'archimage Vargoth en haut de la Tour pourpre."}}
D[10188] = {"Le cachet de Krasus",{"Reprenez le Cachet de Krasus à la Lieuse de sort Maryana à la Manaforge Coruu, au nord-ouest de la Tour Pourpre."}}
D[10189] = {"Manaforge B'naar",{"Le maître-espion Thalodien de la Zone 52 veut que vous vous rendiez dans les environs de la manaforge B'naar et que vous récupériez le Tableau de service du personnel de B'naar sur le capitaine Arathyn.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10190] = {"Recharger les batteries",{"Utilisez la Pétoire charge-batterie sur assez de chasseurs phasiques pour faire monter le niveau de recharge de la batterie jusqu'à 10. Ensuite, rapportez-la à la robotologue Alley aux ruines d'Enkaat au Raz-de-Néant."}}
D[10191] = {"Le Mod. V vit !",{"Escortez le Maxx A. Million Mod. V dans les ruines d'Enkaat jusqu'à son retour en sécurité. Ensuite, allez voir la robotologue Alley à la sortie des ruines d'Enkaat au Raz-de-Néant."}}
D[10192] = {"Le compendium de Krasus",{"Récupérez le Compendium de Krasus - Chapitre 1, le Compendium de Krasus - Chapitre 2 et le Compendium de Krasus - Chapitre 3 sur la Place centrale de Kirin'Var."}}
D[10193] = {"Cibles majeures",{"Le maître-espion Thalodien de la Zone 52 veut que vous alliez à la manaforge B'naar pour y tuer 2 Maîtres-dimensionnels solfurie, 6 Ingénieurs dimensionnels solfurie et 8 Géologues solfurie.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10194] = {"Vol furtif",{"Parlez à Veronia à l'extérieur de la Zone 52 et volez jusqu'à la manaforge Coruu.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10195] = {"Mercenaire voir, mercenaire faire",{"Apportez 30 Plumes d'arakkoa à Ros'eleth au Bastion allérien."}}
D[10196] = {"Plus de plumes d'arakkoa",{"Apportez 30 Plumes d'arakkoa à Malukaz au fort des Brise-pierres."}}
D[10197] = {"Un déguisement convaincant",{"Procurez-vous une Robe d'arcaniste solfurie, une paire de Gants de chercheur solfurie et un Médaillon de garde solfurie et apportez-les à Caledis Brillaube à la manaforge Coruu au Raz-de-Néant.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10198] = {"Rassembler des informations",{"Utilisez le déguisement de Solfurie pour vous rendre à la Manaforge Coruu et écouter la conversation entre le Commandant Forgelaube et l'Arcaniste Ardonis.","","Accomplir des tâches pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10199] = {"Un petit coup de fouet",{"Procurez-vous 5 Aiguillons de raie du Néant pour Bottes dans la Zone 52 du Raz-de-Néant."}}
D[10200] = {"Retourner voir Thalodien",{"Retournez voir le maître-espion Thalodien dans la Zone 52 du Raz-de-Néant."}}
D[10201] = {"Et maintenant, l'instant de vérité",{"Trouvez Grek et demandez-lui d'essayer l'huile sur son arme. Une fois qu'il l'aura testée, retournez décrire le résultat à Rakoria."}}
D[10202] = {"Un déserteur",{"Allez à la manaforge Ara et parlez au magistère Theledorn.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10203] = {"Zapper des atouts inestimables",{"Utilisez le Zappeur d'ultra-déconsolidation pour renvoyer le Creus-O-Matic ultra-rotatif, la Griffe de drague servopneumatique, l'Analyseur de terrain multispectral et le Gros chariot rempli d'explosifs dans la Zone 52 au Raz-de-Néant. Présentez-vous ensuite au Sapeur en chef Failonfeu à l'extrémité est de la fissure qui parcourt la Zone 52 au Raz-de-Néant."}}
D[10204] = {"Cristaux de gemmes de sang",{"La magistrice Larynna veut que vous alliez à la manaforge B'naar pour vous y procurer un Éclat de gemme de sang sur un Magistère solfurie. Utilisez-le près des grands Cristaux de gemme de sang et retournez la voir dans la Zone 52.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10205] = {"L'écumeur-dimensionnel Nesaad",{"Tuez l'Écumeur-dimensionnel Nesaad, puis retournez voir le traqueur-du-Néant Khay'ji dans la Zone 52 de Raz-de-Néant."}}
D[10206] = {"Prendre sa part",{"Récupérez 10 modèles de Technologie éthérienne et rapportez-les à Papa Roulette, dans la Zone 52 au Raz-de-Néant."}}
D[10207] = {"Forward Base: Reaver's Fall REUSE",{"Présentez-vous au commandant des lignes avancées To'arch au Trépas du saccageur."}}
D[10208] = {"Perturber leurs renforts",{"Terrassez les ennemis qui se trouvent autour des portails Xilus et Kruul pour rassembler des Pierres runiques démoniaques.","","Utilisez une Amorce de To'arch à l'intérieur des portails Xilus et Kruul.","","Rapportez les Amorces restantes à To'arch au Trépas du saccageur dans la péninsule des Flammes infernales."}}
D[10209] = {"Le trophée de l'invocateur Kanthin",{"Triomphez de l'invocateur Kanthin à la manaforge Duro, sur l'île au nord du bastion des Solfurie, et reprenez-lui la Pierre de Glacius."}}
D[10210] = {"A'dal",{"Parlez à A'dal, le chef des Sha'tar, au centre de la Terrasse de la Lumière."}}
D[10211] = {"Ville de Lumière",{"Suivez le serviteur de Khadgar et écoutez son histoire. Retournez ensuite voir Khadgar."}}
D[10212] = {"Héros des Mag'har",{"Retournez voir la grande-mère Geyah à Garadar en Nagrand."}}
D[10213] = {"Enquêter au sujet de l'accident",{"Cherchez des survivants de l'accident."}}
D[10214] = {"Mineur, tu dors, ton wagon va trop vite",{"Tuez 15 Sapeurs gan'arg et retournez voir le contremaître Razelcraz."}}
D[10216] = {"La sécurité avant tout",{"L'artificier Morphalius veut que vous alliez tuer 10 Écumeurs de crypte éthériens, 5 Ensorceleurs éthériens, 5 Traqueurs de nexus et 5 Lieurs de sort éthériens.","","Lorsque ce sera fait, trouvez le Transporteur éthérien dans la salle avant celle de Shaffar et activez-le."}}
D[10218] = {"Le dur labeur des autres",{"Escortez le cryo-ingénieur Sha'heen dans les tombes-mana pour qu'il puisse recueillir l'éther contenu dans les collecteurs d'éther de Shaffar.","","Allez voir le prince-nexus Haramad au campement du Consortium à l'extérieur des tombes-mana une fois votre mission accomplie."}}
D[10219] = {"Sortir le chien"}
D[10220] = {"Les forcer à écouter",{"Mordiba veut que vous vainquiez 12 Fantassins inflexibles, 8 Chevaliers inflexibles et 6 Ensorceleurs inflexibles à l'Armurerie de l'expédition à l'ouest du Poste de Brise-échine."}}
D[10221] = {"Dr Boum !",{"Tuez Dr Boum puis rapportez la bonne nouvelle au sapeur en chef Failonfeu dans la Zone 52 au Raz-de-Néant."}}
D[10222] = {"La garnison Solfurie",{"Le Protecteur Valemort à Kirin'Var veut que vous tuiez 10 Archers solfurie."}}
D[10223] = {"Mort à Daellis",{"Le protecteur Valemort de Kirin'Var veut que vous alliez tuer le maître Daellis Heurtelaube."}}
D[10224] = {"De l'essence pour les moteurs",{"Collectez 7 Essences d'âmes en peine de mana et rapportez-les à l'ingénieur en chef Trep à la Zone 52 au Raz-de-Néant."}}
D[10225] = {"Rapport à l'ingénierie",{"Apportez le Cristal de matrice d'etherlithium à l'Ingénieur en chef Trep dans la Zone 52 au Raz-de-Néant."}}
D[10226] = {"Extraction de puissance élémentaire",{"Extrayez 5 Puissances élémentaires et apportez-les à l’Ingénieur en chef Trep, dans la Zone 52 au Raz-de-Néant."}}
D[10227] = {"Je vois des draeneï morts",{"Parlez à Ramdor le Fol, qui se trouve sur le tas d'os à l'extérieur des cryptes Auchenaï."}}
D[10228] = {"Ezekiel",{"Trouvez Ezekiel dans la ville de Shattrath, et parlez-lui."}}
D[10229] = {"Déchiffrer le tome",{"Apportez le Tome mystérieux à Althen l'Historien au Poste de Brise-échine."}}
D[10230] = {"Le cor de bataille",{"Prenez le Cor de bataille des Inflexibles au lieutenant-commandant Thalvos et apportez-le à Althen l'Historien au Poste de Brise-échine."}}
D[10231] = {"Quel livre ? Je ne vois pas de livre.",{"Ezekiel dit que le livre a été volé. Votre meilleure piste serait de trouver les ruffians et de voir s'ils ont des informations à ce sujet."}}
D[10232] = {"Ferrailler contre la Légion",{"Tuez 5 Forgerons funestes mo'arg et 15 Ingénieurs gan'arg. Puis retournez voir Papa Roulette dans la Zone 52 du Raz-de-Néant."}}
D[10233] = {"Incendier le bastion des Solfurie",{"À l'aide d'une Torche enflammée, détruisez 4 Balistes Solfurie et 4 Tentes Solfurie, puis retournez voir le lieutenant-ensorceleur Morran à Kirin'Var."}}
D[10234] = {"Le malheur d'un démon…",{"Rassemblez 10 Pièces de saccageur gangrené et apportez-les à Mama Roulette au comptoir des Terres-médianes à l'intérieur de l'écodôme Terres-médianes au Raz-de-Néant."}}
D[10235] = {"Dégriffer Griffe-funeste",{"Procurez-vous la Main de Griffe-funeste et apportez-la à Mama Roulette au comptoir des Terres-médianes à l'intérieur de l'écodôme Terres-médianes au Raz-de-Néant."}}
D[10236] = {"L'Outreterre, c'est nul  !",{"Trouvez 6 Pièces de déchiqueteur et retournez voir le contremaître Razelcraz près de la mine au nord-ouest de Thrallmar."}}
D[10237] = {"Avertir la Zone 52 !",{"Annoncez la mauvaise nouvelle au chef-de-fusée Karlingue dans la Zone 52 au Raz-de-Néant."}}
D[10238] = {"Comment servir le gobelin",{"Sauvez Manni, Moh et Jakk des camps des gangr'orcs et retournez voir le contremaître Razelcraz près de la mine au nord-ouest de Thrallmar."}}
D[10239] = {"Une source d'énergie potentielle",{"Le lieutenant-ensorceleur Morran de Kirin'Var veut que vous vous empariez de 10 Cubes d'isolation à énergie dans les exploitations des Elfes de sang de la manaforge Coruu."}}
D[10240] = {"Établir un périmètre",{"Utilisez le Mécanisme d'activation des runes près de la Rune est, la Rune nord-est et la Rune ouest. Ces runes se trouvent quelque part autour des quartiers de l'Allée des sorciers et de la Place centrale de Kirin'Var. Retournez voir le lieutenant-ensorceleur Morran une fois que vous aurez accompli cette tâche."}}
D[10241] = {"Diversion à la manaforge B'naar",{"Tuez 8 Magistères Solfurie et 8 Garde-sang Solfurie puis retournez voir l'exarque Orelis dans la Zone 52.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10242] = {"Le poste de Brise-échine",{"L'Apothicaire Zelana du Trépas du saccageur vous a demandé de parler au Chef d'escadrille Brack et de prendre une wyverne pour rallier le Poste de Brise-échine, puis de remettre l'Échantillon de sang de l'Orbite-sanglante à l'apothicaire Albreck au Poste de Brise-échine."}}
D[10243] = {"Technologie naaru",{"Entrez dans la manaforge B'naar et trouvez la Console de contrôle B'naar.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10244] = {"R.T.F.M.C.S.",{"Apportez le Manuel de construction du saccageur gangrené à Mama Roulette au comptoir des Terres-médianes à l'intérieur de l'écodôme Terres-médianes au Raz-de-Néant."}}
D[10245] = {"La transcription de la console de B'naar",{"Apportez la Transcription de la console de B'naar à l'anachorète Karja dans la Zone 52 au Raz-de-Néant.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10246] = {"Attaquer la manaforge Coruu",{"Partez pour la manaforge Coruu et tuez 8 Arcanistes solfurie et 5 Chercheurs solfurie. Retournez voir l'exarque Orelis lorsque vous aurez accompli cette tâche.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10247] = {"Le docteur Vomisa, Ph.T.",{"Allez voir le docteur Vomisa, Ph.T. au Terrain d'essai du Raz-de-Néant."}}
D[10248] = {"Toi, le robot",{"Activez les Commandes du saccageur ferrailleur X6000 et testez-en les fonctionnalités. Puis faites part de vos impressions au docteur Vomisa, Ph.T. sur le Terrain d'essai de Raz-de-Néant. Réglez tout problème qui se ferait jour."}}
D[10249] = {"On retourne voir le chef !",{"Retournez voir immédiatement le Chef-de-fusée Karlingue, dans la Zone 52 de Raz-de-Néant !"}}
D[10250] = {"Vengeance sanglante",{"Sonnez le Cor de bataille des Inflexibles près de la bannière de l'Alliance. Tuez Urtrak puis retournez voir Althen l'Historien au Poste de Brise-échine."}}
D[10251] = {"Le Grand Dessein Du Maître ?",{"Trouvez Nitrin l'Instruit à l'Armurerie abandonnée en Nagrand."}}
D[10252] = {"Vision des morts",{"Nitrin, à l'Armurerie abandonnée en Nagrand, veut que vous lui rameniez 1 Globe oculaire de Gronn des montagnes, 1 Bec de Venteroc supérieur sans défaut et 1 Poche de graisse de vieux sabot-fourchu."}}
D[10253] = {"Levixus le Mandeur d'âme",{"Tuez Levixus et prenez-lui le Livre des morts.","","Apportez le Livre des morts à Ramdor le Fol à l'extérieur des Cryptes Auchenaï, à l'entrée d'Auchindoun.","","Vous aviez passé un marché, vous vous souvenez ?"}}
D[10254] = {"Le commandant Danath",{"Le maréchal Isildor veut que vous vous présentiez au commandant de corps Danath Trollemort au bastion de l'Honneur."}}
D[10255] = {"Tester l'antidote",{"Administrez l'Antidote cénarien à un Sanglier infernal massif et observez le résultat. Une fois l'expérience terminée, retournez voir Thiah Crin-rouge au Poste cénarien dans la péninsule des Flammes infernales."}}
D[10256] = {"Trouver le Maître des clés",{"Trouvez Apex et procurez-vous un Focalisateur en cristal d'Apex. Retournez à la Tour pourpre et utilisez le Focalisateur à proximité de l'Orbe de l'archimage Vargoth pour découvrir qui détient la clé qui permettra de lever la malédiction pesant sur la tour."}}
D[10257] = {"S'emparer de la Pierre cruciale",{"Entrez dans la Botanica du donjon de la Tempête et prenez la Pierre cruciale au commandant Sarannis. Apportez-la à l'archimage Vargoth à la Tour pourpre."}}
D[10258] = {"Honorer les morts",{"Présentez-vous au commandant Hogarth à l'Armurerie de l'expédition."}}
D[10259] = {"Dans la brèche",{"Tuez 6 Gangregardes de l'invasion et retournez voir l'émissaire de l'Aube d'argent Fièrepuits."}}
D[10260] = {"Pokernikus le néantologue",{"Parlez au néantologue Pokernikus sur le pont qui conduit au Raz-de-Néant depuis les Tranchantes."}}
D[10261] = {"On recherche : servomoteur d'annihilateur !",{"Procurez-vous un Servomoteur d'annihilateur et apportez-le à Papa Roulette dans la Zone 52 au Raz-de-Néant."}}
D[10262] = {"Un monceau d'éthériens",{"Collectez 10 Insignes de Zaxxis et apportez-les au Traqueur-du-Néant Khay'ji dans la Zone 52 de Raz-de-Néant."}}
D[10263] = {"Aider le Consortium",{"Parlez au traqueur-du-Néant Khay'ji dans la Zone 52 au Raz-de-Néant."}}
D[10264] = {"Aider le Consortium",{"Parlez au Traqueur-du-Néant Khay'ji dans la Zone 52 au Raz-de-Néant."}}
D[10265] = {"La collection de cristaux du Consortium",{"Procurez-vous un artéfact cristallin d'Arklon et rapportez-le au traqueur-du-Néant Khay'ji à la Zone 52 au Raz-de-Néant."}}
D[10266] = {"Demande d'assistance",{"Trouvez Gahruj et proposez-lui vos services. Il se trouve au comptoir des Terres-médianes dans l'Écodôme Terres-médianes au Raz-de-Néant."}}
D[10267] = {"Récupérer ce qui nous revient de droit",{"Récupérez 10 Boîtes d'équipement topographique et rapportez-les à Gahruj au comptoir des Terres-médianes dans l'Écodôme Terres-médianes au Raz-de-Néant."}}
D[10268] = {"Une audience avec le prince",{"Remettez l'Équipement topographique à l'image du prince-nexus Haramad à la Foudreflèche au Raz-de-Néant."}}
D[10269] = {"Point de triangulation numéro un",{"Utilisez l'Appareil de triangulation pour vous indiquer la direction du premier point de triangulation. Une fois que vous l'aurez trouvé, donnez-en l'emplacement au camelot Hazzin au poste de garde du Protectorat dans l'île de la manaforge Ultris au Raz-de-Néant."}}
D[10270] = {"Une proposition pas si modeste",{"Récupérez le Bloc d'alimentation du téléporteur et apportez-le à la Plate-forme de téléportation éthérienne sur la Crête céleste à l'est de la manaforge Ultris. Activez la plate-forme et donnez le Bloc d'alimentation du téléporteur à l'Image du marchand des vents Marid pour qu'il puisse l'installer."}}
D[10271] = {"Passer aux choses sérieuses",{"Chargez le Récolteur d’essence en l’utilisant sur des Drakes du Néant ou sur des Dragons du Néant de la Crête Céleste, puis retournez dans la zone de la Plateforme de téléportation éthérienne."}}
D[10272] = {"Un départ prometteur",{"Récoltez 15 Œufs de draconiens du Néant, puis retournez auprès de Tyri et Jorad sur la Crête céleste."}}
D[10273] = {"Malencontreuses distractions",{"Parlez au Marchand des vents Marid et attirez-le à l'écart de son commerce. Débarrassez-vous de lui puis retournez auprès de Tyri et Jorad sur la Crête céleste."}}
D[10274] = {"S'emparer de la Crête céleste",{"Utilisez le Défi du Vol bleu pour provoquer Veraku en duel sur le bord sud de la Crête céleste. Triomphez de lui et retournez voir Tyri et Jorad sur la Crête céleste."}}
D[10275] = {"Point de triangulation numéro deux",{"Utilisez l'Appareil de triangulation pour vous indiquer la direction du deuxième point de triangulation. Une fois que vous l'aurez trouvé, donnez-en l'emplacement au marchand des vents Tuluman au Point d'ancrage de Tuluman, juste de l'autre côté du pont vers l'île de la manaforge Ara au Raz-de-Néant."}}
D[10276] = {"Le triangle est triangulé",{"Récupérez le Cristal d'Ata'mal et rapportez-le à l'image du prince-nexus Haramad à la Foudreflèche au Raz-de-Néant."}}
D[10277] = {"Les Grottes du temps",{"Andormu vous demande de suivre la Protectrice du temps dans les Grottes du temps."}}
D[10278] = {"Les failles dimensionnelles",{"Utilisez le Générateur de faille dimensionnelle instable dans les Champs de distorsion. Récupérez 3 Néants dimensionnels sur des Marcheurs du Vide instables, puis retournez voir Ogath le Fol au poste de Brise-échine."}}
D[10279] = {"Dans le repaire du maître",{"Parlez à Andormu dans les Grottes du temps."}}
D[10280] = {"Livraison spéciale à Shattrath",{"Apportez le cristal d'Ata'mal à A'dal sur la Terrasse de la Lumière à Shattrath."}}
D[10281] = {"Présentation formelle",{"Retrouvez Tyri à la pointe nord de la Crête céleste et allez lui parler."}}
D[10282] = {"Hautebrande d'antan",{"Andormu des Grottes du temps vous demande de vous aventurer dans le Hautebrande d'antan et d'aller voir Erozion."}}
D[10283] = {"La diversion de Taretha",{"Rendez-vous au bastion de Fort-de-Durn et placez 5 charges incendiaires dans les tonneaux situés dans chacun des pavillons d'internement grâce au Paquet de bombes incendiaires qui vous a été donné par Erozion.","","Parlez à Thrall dans les oubliettes du bastion de Fort-de-Durn une fois les Pavillons d'internement incendiés."}}
D[10284] = {"Évasion de Fort-de-Durn",{"Faites signe à Thrall lorsque vous serez <prêt/prête> à continuer. Suivez-le dans son évasion du bastion de Fort-de-Durn et aidez-le à libérer Taretha et à accomplir son destin.","","Allez parler à Erozion au Hautebrande d'antan si vous parvenez à accomplir cette tâche."}}
D[10285] = {"Retour vers Andormu",{"Retournez voir le jeune dragon Andormu, aux Grottes du temps dans le désert de Tanaris."}}
D[10286] = {"Le secret d'Arelion",{"La magistrice Carinda veut que vous interrogiez le magistère Aledis, qui a été vu pour la dernière fois quittant le Guet de l'épervier pour se rendre dans le marécage de Zangar."}}
D[10287] = {"La maîtresse dévoilée",{"Retournez voir la magistrice Carinda au Guet de l'épervier, à la Péninsule des Flammes infernales."}}
D[10288] = {"Arrivée en Outreterre",{"Le commandant Duron à la Porte des ténèbres dans la péninsule des Flammes infernales veut que vous apportiez le Rapport de Duron à Amish Marteau-hardi."}}
D[10289] = {"En route pour Thrallmar",{"Voyagez sur le coursier du vent de Vlagga Fileplume jusqu'à Thrallmar. Apportez le Rapport d'Orion au général Krakork."}}
D[10290] = {"En quête de farahlite",{"Récoltez 4 morceaux de Farahlite brute et retournez voir Zuben Elgenubi à la Foudreflèche."}}
D[10291] = {"Se présenter à Nazgrel",{"Le général Krakork de Thrallmar veut que vous parliez à Nazgrel."}}
D[10292] = {"Plus de puissance !",{"Zuben Elgenubi veut que vous preniez 8 Canons de la Légion et que vous les rapportiez à la Foudreflèche."}}
D[10293] = {"Toucher le Gros-lot",{"Zuben Elgenubi de la Foudreflèche veut que vous vous procuriez un Noyau de farahlite."}}
D[10294] = {"La crête du Vide",{"Allez sur la crête du Vide et tuez les créatures que vous y trouverez. Réunissez 40 Éclats d'âme de la crête du Vide et apportez-les à Ogath le Fol au Poste de Brise-échine."}}
D[10295] = {"Du fond des abysses",{"Tuez le baron du Vide Galaxis et récupérez l'Éclat de son âme. Apportez l'éclat à Ogath le Fol au Poste de Brise-échine."}}
D[10296] = {"Le Noir marécage",{"Voyagez à travers les Grottes du temps jusqu'au Noir marécage pendant l'ouverture de la Porte des ténèbres et parlez à Sa'at."}}
D[10297] = {"L'ouverture de la Porte des ténèbres",{"Sa'at, à l'intérieur du Noir marécage des Grottes du temps, vous a demandé de défendre Medivh jusqu'à ce qu'il parvienne à ouvrir la Porte des ténèbres.","","Retournez voir Sa'at si vous parvenez à accomplir cette tâche."}}
D[10298] = {"Héros de la progéniture",{"Retournez voir l'enfant, Andormu, aux Grottes du temps dans le désert de Tanaris."}}
D[10299] = {"Extinction de la manaforge B'naar",{"Retournez à la manaforge B'naar et prenez le Cristal d'accès de B'naar au Surveillant Theredis. Utilisez-le à la console de contrôle de la manaforge B'naar pour l'éteindre et faites votre rapport à l'anachorète Karja.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10300] = {"La reconstruction du bâton",{"Obtenez 4 Éclats de cristal sans défaut sur les fantômes des ruines d'Enkaat et rapportez-les à Ravandwyr dans la Zone 52."}}
D[10301] = {"Déverrouiller le compendium",{"Prenez l'Oculus héliotrope à la Saccage-sort Marathelle au bastion des Solfurie."}}
D[10302] = {"Mutations volatiles",{"Tuez 8 Mutations volatiles, puis retournez voir la botaniste Taerix au Point d'impact dans le val d'Ammen."}}
D[10303] = {"Les elfes de sang",{"Tuez 10 Eclaireurs elfes de sang, puis retournez voir Tolaan sur l'Ombrecrête du val d'Ammen."}}
D[10304] = {"Le redresseur de torts Aldar",{"Parlez au redresseur de torts Aldar au point d'impact au val d'Ammen."}}
D[10305] = {"L'abjuriste Belmara",{"Trouvez la maison de l'abjuriste Belmara dans l'Allée des sorciers et replacez le livre sur l'Étagère de livres. Puis parlez au protecteur Valemort à Kirin'Var."}}
D[10306] = {"L'adjurateur Luminrath",{"Trouvez le domicile de l'adjurateur Luminrath dans l'allée des sorciers et replacez le mantelet dans sa Commode. Puis parlez au protecteur Valemort à Kirin'Var."}}
D[10307] = {"Cohlien Tissegivre",{"Trouvez le domicile de Cohlien Tissegivre dans l'Allée des sorciers et replacez le chapeau dans sa Cantine. Puis parlez au protecteur Valemort à Kirin'Var."}}
D[10308] = {"Un autre monceau d'éthériens",{"Il Consorzio è molto interessato all'eliminazione di tutti i ribelli Zaxxis del Cumulo a sud.","","<classe>, se desideri entrare ulteriormente nelle nostre grazie, vai laggiù e portaci altri loro fregi."}}
D[10309] = {"C'est un saccageur gangrené, mais avec un cœur",{"Récupérez le Cœur du saccageur gangrené et apportez-le à N. D. Malacamp, au Monceau au Raz-de-Néant."}}
D[10310] = {"Sabotez le portail dimensionnel !",{"Escortez Drijya jusqu'au portail dimensionnel au Site d'invasion Destructeur, et faites en sorte qu'il reste en sécurité pendant qu'il tente de le saboter. Puis parlez à Gahruj au comptoir des Terres-médianes à l'intérieur de l'écodôme Terres-médianes au Raz-de-Néant."}}
D[10311] = {"Drijya a besoin de votre aide",{"Parlez à Drijya près du Site d'invasion Destructeur au Raz-de-Néant."}}
D[10312] = {"Les annales de Kirin'Var",{"Récupérez les Annales de Kirin'Var à l'hôtel de ville de Kirin'Var et rapportez-les au protecteur Valemort."}}
D[10313] = {"Mesurer les énergies dimensionnelles",{"L'exarque Orelis de la Zone 52 veut que vous emportiez l'Orbe d'harmonisation interdimensionnelle à la manaforge B'naar et que vous l'utilisiez à l'extrémité de ses quatre pipelines.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10314] = {"Le doute subsiste...",{"Récupérez 10 Restes répugnants sur les esprits retors de la Cour de la chapelle de Kirin'Var et apportez-les au protecteur Valemort."}}
D[10315] = {"Neutraliser les néantomanciens",{"Tuez 15 Néantomanciens solfurie puis retournez voir le traqueur-du-Néant Oazul au Point d'ancrage de Tuluman au Raz-de-Néant."}}
D[10316] = {"À la recherche de preuves",{"Fouillez la Cour de la chapelle de Kirin'Var à la recherche d'indices au sujet de l'identité de la personne responsable de la manipulation des esprits."}}
D[10317] = {"S'occuper du contremaître",{"Occupez-vous du contremaître Tombesoleil à l'intérieur de la mine de Trelleum, qui se trouve sous la manaforge Ara au Raz-de-Néant."}}
D[10318] = {"S'occuper du contremaître",{"Tuez le Grand seigneur Grincegarr. Retournez ensuite auprès du marchand des vents Tuluman au Point d'ancrage de Tuluman de Raz-de-Néant."}}
D[10319] = {"La capture du phylactère",{"Récupérez le Phylactère de Naberius dans le quartier de la Cour de la chapelle de Kirin'Var et apportez-le au protecteur Valemort."}}
D[10320] = {"Détruisez Naberius !",{"Le protecteur Valemort de Kirin'Var vous demande d'affronter Naberius et de le vaincre dans la Cour de la chapelle du village."}}
D[10321] = {"Extinction de la manaforge Coruu",{"Voyagez jusqu'à la manaforge Coruu, à l'est de la Zone 52, et prenez le Cristal d'accès de Coruu à la surveillante Seylanna. Utilisez-le à la console de la manaforge Coruu pour l'éteindre.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10322] = {"Extinction de la manaforge Duro",{"L'anachorète Karja vous demande de vous rendre à la manaforge Duro et de vous procurer le Cristal d'accès de Duro porté par le surveillant Athanel. Utilisez-le sur la Console de la manaforge Duro pour déclencher l'extinction.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10323] = {"Extinction de la manaforge Ara",{"Voyagez jusqu'à la manaforge Ara et prenez le Cristal d'accès d'Ara sur le contremaître Azarad. Utilisez-le à la console de la manaforge Ara pour l'éteindre.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10324] = {"La grande chasse aux frôle-lune",{"Apportez 6 Peaux de chevreuil frôle-lune à Acteon au Guet d'azur."}}
D[10325] = {"Les marques de Kil'jaeden",{"Remettre 10 Marques de Kil'jaeden à Adyen le Gardelumière, à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10326] = {"De nouvelles marques de Kil'jaeden"}
D[10327] = {"Une marque de Kil'jaeden",{"S’il vous reste d'autres insignes, ils m'intéressent. Ne vous en faites pas, vos actions seront dûment rapportées."}}
D[10328] = {"Briefing des Solfurie",{"Allez à la manaforge Duro et procurez-vous le Briefing militaire solfurie et le Briefing des arcanes solfurie auprès des soldats en poste. Retournez voir l'exarque Orelis une fois cette tâche accomplie.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10329] = {"Extinction de la manaforge B'naar",{"Retournez à la manaforge B'naar et prenez le Cristal d'accès de B'naar au Surveillant Theredis. Utilisez-le à la console de contrôle de la manaforge B'naar pour l'éteindre et faites votre rapport au maître-espion Thalodien.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10330] = {"Extinction de la manaforge Coruu",{"Procurez-vous le Cristal d'accès de Coruu sur la surveillante Seylanna. Utilisez-le à la console de contrôle de Coruu pour éteindre la manaforge et retournez voir Caledis Brillaube.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès des Aldor."}}
D[10331] = {"Des outils indispensables",{"Reprenez le Marteau de forge aux apprentis de Kirin'Var et rapportez-le à l'apprenti Andrethan à Kirin'Var."}}
D[10332] = {"Le maître forgeron Rhonsus",{"L'apprenti Andrethan de Kirin'Var veut que vous alliez tuer le fantôme de Rhonsus, le maître forgeron de la ville."}}
D[10333] = {"Aider Mama Roulette",{"Parlez à Mama Roulette au comptoir des Terres-médianes à l'intérieur de l'écodôme Terres-médianes au Raz-de-Néant."}}
D[10334] = {"Plus de clochettes",{"Trouver Marguerite dans les champs près de la colline de la chapelle de Kirin'Var."}}
D[10335] = {"Cartographier les ruines",{"Placez les trois Repères de géomètre puis revenez voir Zéphyrion à la Foudreflèche au Raz-de-Néant."}}
D[10336] = {"Les serviteurs de Culuthas",{"Tuez 10 Molosses de Culuthas et 5 Yeux de Culuthas, puis retournez voir le Traqueur-du-Néant Nauthis à la Foudreflèche au Raz-de-Néant."}}
D[10337] = {"Marguerite rentre au pays",{"Escortez Marguerite pour la ramener saine et sauve à son propriétaire, Thadell."}}
D[10338] = {"Extinction de la manaforge Duro",{"Retournez à la manaforge Duro et prenez le Cristal d'accès de Duro au surveillant Athanel. Utilisez-le à la console de contrôle de Duro pour l'éteindre et allez faire votre rapport au maître-espion Thalodien.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10339] = {"L'Ethereum",{"Le commandant Ameer veut que vous tuiez 5 Assassins de l'Ethereum, 5 Troupiers de choc de l'Ethereum, 2 Chercheurs de l'Ethereum et le capitaine Zovax puis que vous activiez le Transpondeur zéta de l'Ethereum."}}
D[10340] = {"La halte du Fracas",{"Le commandant des lignes avancées Kingston veut que vous parliez au chef d'escadrille Dabir'ee, que vous preniez un griffon pour la halte du Fracas et que vous vous présentiez à Runetog Marteau-Hardi."}}
D[10341] = {"Cognez-les maintenant qu'ils sont à terre",{"Tuez 8 Adjurateurs solfurie, 6 Franc-archers solfurie et 4 Centurions solfurie. Retournez voir la magistrice Larynna dans la Zone 52 lorsque vous aurez achevé cette tâche.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10342] = {"Dégoter de la lauze de peau-de-schiste",{"Collectez 5 Lauzes de peau-de-schiste et apportez-les à Bottes dans la Zone 52 au Raz-de-Néant."}}
D[10343] = {"L'invasion sans fin",{"Fouillez la zone de Kirin'Var infestée de créatures de mana à la recherche d'un Fragment de bombe de mana et apportez-le au lieutenant-ensorceleur Morran."}}
D[10344] = {"Le chef d'escadrille Griffongar",{"Parlez au Chef d'escadrille Griffongar à la Halte du Fracas."}}
D[10345] = {"La chair ment...",{"Utilisez le Boute-feu du Protectorat sur 12 Cadavres flétris. Lorsque vous aurez fini, rendez le Boute-feu du Protectorat à l'agent Araxes à l'extérieur du Puits d'accès Zéon."}}
D[10346] = {"Retour à la saillie abyssale",{"Le griffonnier Soufflevent de la halte du Fracas dans la péninsule des Flammes infernales vous demande de détruire 20 Péons gan'arg, 5 Surveillants mo'arg et 5 Gangrecanons."}}
D[10347] = {"Retour à la saillie abyssale",{"Le chef d'escadrille Brack du Trépas du saccageur dans la péninsule des Flammes infernales vous demande de détruire 20 Péons gan'arg, 5 Surveillants mo'arg et 5 Gangrecanons."}}
D[10348] = {"De nouvelles opportunités",{"Cueillez 15 Clochettes d'ivoire et retournez voir Mihrdad au comptoir des Terres-médianes."}}
D[10349] = {"La lieuse de terre",{"Apportez l'Éclat de cristal cramoisi à la lieuse de terre Galandria Noctebrise au Poste cénarien dans la péninsule des Flammes infernales."}}
D[10350] = {"Behomat",{"Allez parler à Behomat, à l’Étage des commerces de l’Exodar."}}
D[10351] = {"Remèdes naturels",{"Utilisez la Graine de revitalisation au Cercle de la lieuse de terre pour guérir la terre autour du cristal. Ensuite, retournez voir la lieuse de terre Galandria Noctebrise au Poste cénarien dans la péninsule des Flammes infernales avec toutes les informations que vous aurez."}}
D[10352] = {"Un don de laine"}
D[10353] = {"Arconus l'Insatiable",{"L'agent Ya-six du puits d'accès Zéon du Raz-de-Néant vous a demandé de tuer Arconus l'Insatiable puis de retourner voir le commandant Ameer au Poste de garde du Protectorat au Raz-de-Néant."}}
D[10354] = {"Un don de soie"}
D[10355] = {"Chair flétrie",{"Réunissez 5 Échantillons d'hydre desséchée et 5 Échantillons de seigneur-tourbe flétri et apportez-les à Ruam à Telredor."}}
D[10356] = {"Un don de tisse-mage"}
D[10357] = {"Un don d'étoffe runique"}
D[10358] = {"Encore de l'étoffe runique"}
D[10359] = {"Un don de laine"}
D[10360] = {"Un don de soie"}
D[10361] = {"Un don de tisse-mage"}
D[10362] = {"Un don d'étoffe runique"}
D[10363] = {"Encore de l'étoffe runique",{"For another stack of twenty runecloth, I will see to it that you are recognized for your continuing efforts on behalf of Silvermoon.","","Simply hand it to me when you're ready."}}
D[10364] = {"Caedmos",{"Allez parler à Caedmos, à la Voûte des lumières de l’Exodar."}}
D[10365] = {"Extinction de la manaforge Ara",{"Voyagez jusqu'à la manaforge Ara et prenez le Cristal d'accès d'Ara sur le contremaître Azarad. Utilisez-le à la console de la manaforge Ara pour l'éteindre.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10366] = {"Jol",{"Allez parler à Jol, au Sanctum des anachorètes de l'Exodar."}}
D[10367] = {"Un traître parmi nous",{"Naladu, aux ruines de Sha'naar, veut que vous vous procuriez la Clé de Sha'naar dans une hutte des alentours."}}
D[10368] = {"Les Anciens crapuches",{"Libérez Morod le Touillevent, Akoru le Mandefeu et Aylaan le Troublelonde aux ruines de Sha'naar. Retournez voir Naladu lorsque ce sera fait."}}
D[10369] = {"La fin d'Arzeth",{"Utilisez le Bâton des anciens crapuches contre Arzeth le Sans-clémence et tuez-le lorsqu'il aura perdu ses pouvoirs. Retournez voir Naladu aux ruines de Sha'naar lorsque ce sera fait."}}
D[10370] = {"Les ordres de Nazgrel <TXT>"}
D[10371] = {"Yorus Brasselorge",{"Parler à Yorus Brasselorge."}}
D[10372] = {"Une demande discrète",{"Parlez à Eralan à Tranquillien."}}
D[10373] = {"Un appel aux armes : les Maleterres",{"Trouvez le commandant Ashlam Vaillepoing. Il s'est installé au Camp du Noroît, au nord des montagnes d'Alterac."}}
D[10374] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l'est des Clairières de Tirisfal et de Fossoyeuse."}}
D[10375] = {"Les perles de guerre d'obsidienne"}
D[10377] = {"Rien à craindre"}
D[10379] = {"Toucher de faiblesse"}
D[10380] = {"Un sombre pacte",{"Kaylaan, du Point d'ancrage de Tuluman à Raz-de-Néant, veut que vous alliez tuer 6 Bricoleurs-dimensionnels gan'arg, 3 Filles de la Destinée et 3 Maîtres-dimensionnels mo'arg.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10381] = {"L'Aldor c'est mort",{"Retournez voir l'exarque Orelis dans la Zone 52.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10382] = {"Partir pour le front",{"Prenez le griffon pour la halte de l'Honneur et parlez au grand maréchal Brock."}}
D[10383] = {"This is a Breadcrumb!",{"Speak with Jonathan LeCraft about the wabbits."}}
D[10384] = {"Les données de l'Ethereum",{"L'Image du commandant Ameer du lieu de rassemblement de l'Ethereum - Transpondeur zéta de l'Ethereum - veut que vous récupériez la cellule de données de l'Ethereum."}}
D[10385] = {"Risque de dommages cérébraux : élevé",{"L'image du commandant Ameer au Transpondeur zéta du lieu de rassemblement de l'Ethereum vous demande de lui rapporter 15 recueils de Données de relais de l'Ethereum."}}
D[10386] = {"Le tueur de saccageurs gangrenés",{"Parler au suzerain Hun Mutilepoing."}}
D[10387] = {"Le tueur de saccageurs gangrenés",{"Parler au suzerain Hun Mutilepoing."}}
D[10388] = {"Retour à Thrallmar",{"Retournez à Thrallmar et allez parler à Nazgrel."}}
D[10389] = {"Agonie et ténèbres",{"Le magistère Faucon-de-sang veut que vous alliez tuer 10 Fiels de la terreur dans les bassins d'Aggonar."}}
D[10390] = {"Le camp de forge Mageddon",{"Nazgrel de Thrallmar vous demande d'attaquer le Camp de forge Mageddon, de tuer 10 Serviteurs gan'arg et de revenir avec la tête de Tranchescie."}}
D[10391] = {"Les canons de la rage",{"Détruisez 3 Gangrecanons Mod.I au Camp de forge Rage et retournez voir Nazgrel à Thrallmar."}}
D[10392] = {"Une porte vers l'abîme",{"Tuez Arix'Amal pour vous emparer de la Clé du portail de la Légion ardente. Utilisez cette clé sur la Rune de Mépris, puis retournez voir Nazgrel à Thrallmar."}}
D[10393] = {"Plans abjects",{"Apportez la Missive de la Légion ardente au Magistère Faucon-de-sang à Thrallmar."}}
D[10394] = {"Une perturbation : le camp de forge Mageddon",{"Tuez 10 Serviteurs gan'arg et Tranchescie au Camp de forge Mageddon puis retournez voir le Commandant des lignes avancées Brock à la halte de l'Honneur."}}
D[10395] = {"La sombre missive",{"Apportez la Missive au Scrute-dimensions Kryv dans le donjon principal du bastion de l'Honneur."}}
D[10396] = {"Ennemi de mon ennemi…",{"Détruisez 3 Gangrecanons Mod.I au Camp de forge Rage, puis retournez voir le Grand maréchal Brock à la halte de l'Honneur."}}
D[10397] = {"Le site d'invasion Annihilateur",{"Tuez Arix'Amal. Prenez la Clé du portail de la Légion ardente et utilisez-la sur la Rune de Mépris."}}
D[10398] = {"Retour au bastion de l'Honneur",{"PH: Go to Honor Hold."}}
D[10399] = {"Le cœur des ténèbres",{"Tuez 10 Fiels de la terreur dans les Bassins d'Aggonar et retournez voir le Scrute-dimensions Kryv au donjon principal du Bastion de l'Honneur."}}
D[10400] = {"Suzerain",{"Tuez Arazzius le Cruel aux bassins d'Aggonar puis retournez voir le commandant de corps Danath Trollemort dans le donjon du bastion de l'Honneur."}}
D[10401] = {"Mission : Point final",{"Nazgrel, à Thrallmar dans la péninsule des Flammes infernales, vous a demandé de tuer Arazzius le Cruel."}}
D[10403] = {"Naladu",{"Allez trouver Naladu à l'intérieur des ruines de Sha'naar."}}
D[10404] = {"Contre la Légion",{"L'exarque Orelis de la Zone 52 veut que vous vous rendiez à la Base de forge Oubli et à la Base de forge Géhenne pour y tuer 12 Assistants-forgerons gan'arg, 6 Seigneurs de la forge mo'arg et 6 Porte-courroux.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10405] = {"S-A-B-O-T-A-G-E",{"L'image du commandant Ameer au Transpondeur zéta du lieu de rassemblement de l'Ethereum vous demande de lui rapporter un Linceul de l'Ethereum préparé."}}
D[10406] = {"Faire passer le message",{"L'Image du commandant Ameer du lieu de rassemblement de l'Ethereum - Transpondeur zéta de l'Ethereum - veut que vous escortiez le démolisseur du Protectorat jusqu'à la canalisation de la manaforge Ultris et que vous le protégiez pendant qu'il sabote le pipeline."}}
D[10407] = {"L'ombre de Socrethar",{"L'anachorète Karja de la Zone 52 veut que vous vous procuriez la Première moitié de la pierre de Socrethar sur le maître-forge Morug à la base de forge Oubli et la Seconde moitié de la pierre de Socrethar sur Silroth à la base de forge Géhenne.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10408] = {"Le roi-nexus Salhadaar",{"L'Image du commandant Ameer du lieu de rassemblement de l'Ethereum - Transpondeur zéta de l'Ethereum - veut que vous utilisiez le Disrupteur du Protectorat pour désactiver les champs de force de Salhadaar puis détruire le roi-nexus Salhadaar."}}
D[10409] = {"Un coup fatal à la Légion",{"La grande prêtresse Ishanah veut que vous alliez au Téléporteur de la Légion dans le coin nord-ouest de Raz-de-Néant et que vous l'utilisiez pour vous téléporter au siège de Socrethar. Une fois là-bas, triomphez de Socrethar.","","Accomplir des quêtes pour les Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10410] = {"L'aide d'Ishanah",{"Apportez la Pierre de téléportation de Socrethar à la grande prêtresse Ishanah au Sanctuaire de la Lumière perpétuelle sur l'Éminence de l'Aldor à Shattrath.","","Accomplir des quêtes pour les Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10411] = {"Le bien-fondé des électrochocs !",{"Le chercheur Navuud du poste de garde du Protectorat au Raz-de-Néant vous a demandé de détruire 30 Globules de rebut du Vide et 30 Globules de vase suintante."}}
D[10412] = {"Les chevalières Aile-de-feu",{"La magistrice Fyalenn de Shattrath veut que vous lui apportiez 10 Chevalières Aile-de-feu.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10413] = {"Les horreurs de la pollution",{"Apportez le Flacon de limon d'horreur du Vide au chercheur Navuud du poste de garde du Protectorat de Raz-de-Néant."}}
D[10414] = {"Une chevalière Aile-de-feu",{"Même la plus petite contribution à notre cause est dûment notée, <nom>. Nos ennemis sont nombreux, mais nous vaincrons !"}}
D[10415] = {"De nouvelles chevalières Aile-de-feu"}
D[10416] = {"Synthèse de puissance",{"Voren'thal le Voyant de Shattrath veut que vous vous procuriez un Tome des arcanes.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10417] = {"Faire un diagnostic !",{"Récupérez les Résultats du diagnostic et apportez-les à Mihrdad au comptoir des Terres-médianes."}}
D[10418] = {"S'occuper des saboteurs",{"Mihrdad du comptoir des Terres-médianes veut que vous alliez tuer 8 Crocilisques Ecailles-barbelées."}}
D[10419] = {"Tomes des Arcanes"}
D[10420] = {"Une Lumière purificatrice",{"Apportez une Arme gangrenée à Ishanah à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10421] = {"Armes gangrenées",{"Avez-vous trouvé des armes gangrenées dernièrement ? Laissez la Lumière faire son travail, <nom>. Ne permettez pas à ces objets maléfiques de rester dans ce monde."}}
D[10422] = {"Le capitaine Tyralius",{"Le manieur de chair Viridius au poste de garde du Protectorat de Raz-de-Néant vous a demandé de trouver et libérer le Capitaine Tyralius."}}
D[10423] = {"À la Foudreflèche",{"Parlez à Ghabar à la Foudreflèche, au Raz-de-Néant."}}
D[10424] = {"Diagnostic : critique",{"Utilisez la Machine à diagnostic en vous tenant près du Générateur de l'écodôme Sudron et apportez les Résultats du diagnostic à Ghabar à la Foudreflèche."}}
D[10425] = {"L'évasion du lieu de rassemblement",{"Escortez l'Avant-garde du Protectorat capturé jusqu'au Poste de garde du Protectorat au Raz-de-Néant."}}
D[10426] = {"La flore des écodômes",{"Utilisez le Modulateur de champ d'énergie sur des Flagellants de Farahlon. Observez les résultats et allez voir Aurine Braselune à la Foudreflèche lorsque vous aurez conduit 10 tests."}}
D[10427] = {"Créatures des écodômes",{"Marquez 12 Talbuks pour Aurine Braselune à la Foudreflèche. Vous pouvez marquer soit des Talbuks étalons soit des Talbuks femelles à l'aide du Marqueur de talbuk."}}
D[10428] = {"Le pêcheur disparu",{"Trouvez Cowlen sur le quai, au sud-ouest de l'Île de Brume-argent, au large de la côte de Brume-azur."}}
D[10429] = {"Quand la nature va trop loin",{"Aurine Braselune de la Foudreflèche veut que vous lui apportiez un Cœur d'hydre massive."}}
D[10430] = {"Tester le prototype",{"Apportez l'Appareil de réparation à Tashar à l'écodôme Champlointain, au Raz-de-Néant."}}
D[10431] = {"Une aide extérieure",{"Allez au Point d'ancrage de Tuluman au nord de la Zone 52 et parlez à Kaylaan.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10432] = {"Preuves accablantes",{"Procurez-vous 8 Ordres de Kael'thas sur les démons de la manaforge Ara et apportez-les au Maître-espion Thalodien dans la Zone 52.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10433] = {"Sauvez les apparences",{"Apportez 10 Fourrures de lynx arrache-crocs à Shauly Pore au comptoir des Terres-médianes."}}
D[10434] = {"Le duo dynamique",{"Allez parler à Audi la Pointe à la Foudreflèche, au Raz-de-Néant."}}
D[10435] = {"Récupérer les marchandises",{"Audi la Pointe de Foudreflèche veut que vous lui apportiez 10 Segments du générateur du dôme."}}
D[10436] = {"Tout est prêt !",{"Tashar, en poste à l'écodôme Champlointain, vous demande de tuer 12 Raptors Fauche-dent."}}
D[10437] = {"Une recette de destruction",{"Le professeur Dabiri du poste de garde du Protectorat de Raz-de-Néant veut que vous récupériez 8 Fragments de Dimensius."}}
D[10438] = {"Sur des ailes néantines",{"Le professeur Dabiri, du Poste de garde du Protectorat de Raz-de-Néant, veut que vous utilisiez votre Disrupteur de phase lorsque vous serez à portée du Conduit du Vide du sommet d'Ultris. Larguez autant de charges du disrupteur de phase que possible pour vous assurer de sa destruction totale. Les charges du disrupteur de phase atteignent automatiquement le conducteur du Vide du moment que vous êtes assez près pour l'utiliser.","","Retournez voir le professeur Dabiri si vous réussissez !"}}
D[10439] = {"Dimensius l'Omni-dévoreur",{"Le professeur Dabiri du poste de garde du Protectorat au Raz-de-Néant vous demande d'aller parler au capitaine Saeed et de suivre son armée à la manaforge Ultris pour tuer Dimensius l'Omni-dévoreur !"}}
D[10440] = {"Victoire !",{"Retournez voir Ghabar à la Foudreflèche, au Raz-de-Néant."}}
D[10441] = {"Colporter la marchandise",{"Parlez à Aurine Braselune en bas de la Foudreflèche."}}
D[10442] = {"Venir en aide au Poste cénarien",{"Le fauconnier Drenna Ruissevent vous demande de proposer vos services à Thiah Crin-rouge au Poste cénarien dans la Péninsule des Flammes infernales."}}
D[10443] = {"Venir en aide au Poste cénarien",{"Amaan le Sage voudrait que vous proposiez vos services à Thiah Crin-rouge au Poste cénarien dans la péninsule des Flammes infernales."}}
D[10444] = {"Rapport au Poste allérien",{"Jenai Murmétoile veut que vous vous présentiez au lieutenant Meridian au Poste allérien dans la forêt de Terokkar."}}
D[10445] = {"Les fioles d'éternité",{"Soridormi aux Grottes du temps vous demande de récupérer le Reste de la fiole de Vashj auprès de Dame Vashj au réservoir de Glissecroc et le Reste de la fiole de Kael auprès de Kael'thas Haut-soleil au donjon de la Tempête."}}
D[10446] = {"Le code final",{"Le lieutenant Meridian vous demande d'utiliser le Code final pour désamorcer la Bombe de mana. Faites ensuite votre rapport à Jenai Murmétoile au Bastion allérien dans la forêt de Terokkar."}}
D[10447] = {"Le code final",{"Le sergent Chawni vous demande d'utiliser le Code final pour désamorcer la Bombe de mana. Faites ensuite votre rapport à Tooki au fort des Brise-Pierres dans la forêt de Terokkar."}}
D[10448] = {"Rapport au camp des Brise-Pierres",{"Tooki veut que vous vous présentiez au sergent Chawni au camp des Brise-Pierres dans la forêt de Terokkar."}}
D[10449] = {"L'apothicaire Zelana",{"Vurtok Brise-hache de Thrallmar vous demande d'apporter les Échantillons de sang de Mâche-les-os à l'apothicaire Zelana au Trépas du saccageur."}}
D[10450] = {"Le sang de Mâche-les-os",{"Apportez 12 Fioles de sang de Mâche-les-os à Vurtok Brise-hache à Thrallmar."}}
D[10451] = {"L'évasion de la citerne de Glissentaille",{"Escortez la Soigneterre Wilda hors de la Citerne de Glissentaille puis allez trouver le Soigneterre Torlok à l'Autel de la damnation, qui se trouve à l'ouest de la Main de Gul'dan."}}
D[10454] = {"DRAPEAU - HORS DES RAILS"}
D[10455] = {"Une nature envahissante",{"Rina Sourcelune souhaite que vous tuiez 12 Lynx traquebosquet en toute hâte puis que vous retourniez la voir à Sylvanaar dans les Tranchantes."}}
D[10456] = {"Les loups en maraude",{"Rapportez 4 Queues de loup redoutable sire-tonnerre."}}
D[10457] = {"Pour protéger les nôtres",{"Utilisez le Rameau de Rina sur 5 Boutures du Bosquet pour faire apparaître des défenseurs du Bosquet vivant."}}
D[10458] = {"Esprits de feu et de terre enragés",{"Le soigneterre Torlok à l'Autel de la damnation dans la vallée d'Ombrelune veut que vous utilisiez le Totem des esprits pour capturer 8 Âmes terrestres et 8 Âmes flamboyantes."}}
D[10459] = {"Révéré par l'Expédition cénarienne",{"Ysiel Chantelevent du Refuge cénarien veut que vous deveniez <Révéré/Révérée> par l'Expédition cénarienne."}}
