D[10461] = {"Le serment du guérisseur"}
D[10462] = {"Le serment du champion"}
D[10463] = {"Le serment du sage"}
D[10464] = {"Le vœu du sage",{"Apportez votre Bague d'éternité à Soridormi, aux Grottes du temps, après être <devenu Honoré/devenue Honorée> auprès de la Balance des sables."}}
