D[10466] = {"Le vœu du champion",{"Apportez votre Bague d'éternité à Soridormi aux Grottes du temps après être <devenu Honoré/devenue Honorée> auprès de la Balance des sables."}}
D[10467] = {"Le vœu du défenseur",{"Apportez votre Bague d'éternité à Soridormi aux Grottes du temps après être <devenu Honoré/devenue Honorée> auprès de la Balance des sables."}}
D[10468] = {"La promesse du sage",{"Apportez votre Bague d'éternité à Soridormi aux Grottes du temps après être <devenu Révéré/devenue Révérée> par la Balance des sables."}}
