D[10472] = {"L'engagement du sage",{"Apportez votre Bague d'éternité à Soridormi aux Grottes du temps après être <devenu Exalté/devenue Exaltée> auprès de la Balance des sables."}}
D[10473] = {"L'engagement du guérisseur",{"Apportez votre Bague d'éternité à Soridormi aux Grottes du temps après être <devenu Exalté/devenue Exaltée> auprès de la Balance des sables."}}
D[10474] = {"L'engagement du champion",{"Apportez votre Bague d'éternité à Soridormi aux Grottes du temps après être <devenu Exalté/devenue Exaltée> auprès de la Balance des sables."}}
D[10475] = {"L'engagement du défenseur",{"Apportez votre Bague d'éternité à Soridormi aux Grottes du temps après être <devenu Exalté/devenue Exaltée> auprès de la Balance des sables."}}
D[10476] = {"Ennemis féroces",{"Le gardien Moi'bff Jill de Telaar veut que vous vous procuriez 10 Perles de guerre d'obsidienne sur les différents ogres qui habitent Nagrand."}}
D[10477] = {"Plus de perles de guerre"}
D[10478] = {"Plus de perles de guerre !"}
D[10479] = {"Prouver votre force",{"Le gardien Bullrok de Garadar veut que vous vous procuriez 10 Perles de guerre d'obsidienne sur les différents ogres qui habitent Nagrand."}}
D[10480] = {"Esprits des eaux enragés",{"Le soigneterre Torlok à l'Autel de la damnation dans la vallée d'Ombrelune veut que vous utilisiez le Totem des esprits pour capturer 5 Âmes aquatiques."}}
D[10481] = {"Esprits des airs enragés",{"Le soigneterre Torlok à l'Autel de la damnation dans la vallée d'Ombrelune veut que vous utilisiez le Totem des esprits pour capturer 10 Âmes aériennes."}}
D[10482] = {"Les charognards gangr'orcs",{"Tuez 20 Orcs Mâche-les-os et retournez voir Amadi au Bastion de l'honneur."}}
D[10483] = {"De mauvais présages",{"Le lieutenant Amadi du bastion de l'Honneur vous a demandé d'apporter 1 Talisman maudit au Caporal Crêtefer, à la Halte de l'expédition."}}
D[10484] = {"Talismans maudits",{"Rapportez 12 Talismans maudits au Caporal Crêtefer à la Halte de l'expédition."}}
D[10485] = {"Le seigneur de guerre de l'Orbite-Sanglante",{"Apportez l'Armure brisée du seigneur de guerre Morkh au Caporal Crêtefer à la Halte de l'expédition."}}
D[10486] = {"Une nature envahissante",{"Gor'drek vous a demandé de tuer 12 Saigneurs Aile-rasoir. Retournez le voir au bastion des Sire-tonnerre dans les Tranchantes lorsque ce sera fait."}}
D[10487] = {"La poussière des drakes",{"Procurez-vous 4 Poussières des Drakes-faë."}}
D[10488] = {"Pour protéger les nôtres",{"Utilisez la Pommade de Gor'drek sur 5 des Loups redoutables sires-tonnerres."}}
D[10489] = {"Abattre un vieil arbre",{"Procurez-vous le Tronc de Fermebranche Basseracines et apportez-le à Tor'chunk Doublegriffes au Bastion des Sire-tonnerre dans les Tranchantes."}}
D[10490] = {"L'appel de l'eau",{"Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur."}}
D[10491] = {"L'appel de l'air",{"Parlez au long-voyant Nobundo, dans le Hall de Cristal, à l’intérieur de l’Exodar sur l’île de Brume-azur."}}
D[10492] = {"Une proposition sérieuse",{"Procurez-vous 15 Échantillons de sang du Berceau-de-l’Hiver et 20 pièces d’or, et apportez-les avec une paire de Manchettes des éléments à Deliana à Forgefer."}}
D[10493] = {"Une proposition sérieuse",{"Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d'or, et apportez-les avec une paire de Brassards de Sancteforge à Mokvar, à Orgrimmar."}}
D[10494] = {"Une juste compensation",{"Apportez une Corde des éléments et une paire de Gantelets des éléments à Deliana à Forgefer."}}
D[10495] = {"Une juste compensation",{"Apportez une Ceinture de Sancteforge et une paire de Gantelets de Sancteforge à Mokvar à Orgrimmar."}}
D[10496] = {"Les adieux d'Anthion",{"Retournez voir Deliana à Forgefer avec des Bottes des éléments, un Kilt des éléments et des Espauliers des éléments."}}
D[10497] = {"Les adieux d'Anthion",{"Retournez voir Mokvar à Orgrimmar avec des Bottes de Sancteforge, des Cuissards de Sancteforge et des Spallières de Sancteforge."}}
D[10498] = {"Garder le meilleur pour la fin",{"Donnez votre Coiffe des éléments et votre Haubergeon des éléments à Deliana."}}
D[10499] = {"Garder le meilleur pour la fin",{"Donnez votre Casque de Sancteforge et votre Cuirasse de Sancteforge à Mokvar."}}
D[10500] = {"La Horde a besoin de votre aide !",{"Parler au seigneur de guerre Gorchuk, dans la vallée des Esprits d'Orgrimmar."}}
D[10501] = {"L'Alliance a besoin de votre aide !",{"Parler au grand maréchal Tombeneige dans la Garde militaire de Forgefer."}}
D[10502] = {"Les ogres de la Masse-sanglante",{"Le Commandant Ombreciel vous a donné pour tâche de détruire 30 Ogres de la Masse-sanglante à l'Avant-poste de la Masse-sanglante. Retournez le voir à Sylvanaar dans les Tranchantes une fois votre répugnante mission accomplie."}}
D[10503] = {"La menace des Flèchelame",{"Tor'chunk Doublegriffes vous a <chargé/chargée> de détruire 30 Ogres de Flèchelame et 10 Raptors de Flèchelame au bastion de Flèchelame et dans les Terres de la Flèchelame. Retournez le voir au bastion des Sire-tonnerre dans les Tranchantes une fois votre tâche achevée."}}
D[10504] = {"Les Ogres de Flèchelame",{"Tuez 30 Ogres de Flèchelame au Bastion de Flèchelame et sur les Terres de la Flèchelame."}}
D[10505] = {"Les Ogres de la Masse-Sanglante",{"Tuez 30 Ogres de la Masse-Sanglante à l'Avant-poste de la Masse sanglante."}}
D[10506] = {"Un redoutable problème",{"Appliquez la Poudre diminutive de Rina pour rapetisser 5 Loups redoutables de la Masse-Sanglante, à l'Avant-poste Masse-Sanglante et dans le Ravin de Masse-Sanglante."}}
D[10507] = {"Un moment décisif",{"Utilisez la Pierre de téléportation de Socrethar au site d'invasion Suzerain, au nord de la Base de forge Oubli pour transporter votre groupe jusqu'à l'aire de Socrethar. Une fois là-bas, utilisez la Présence de Voren'thal pour vaincre Socrethar.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10508] = {"Un cadeau pour Voren'thal",{"Le maître-espion Thalodien de la Zone 52 veut que vous vous procuriez la Première moitié de la pierre de Socrethar auprès du maître-forge Morug à la base de forge Oubli, et la Seconde moitié de la pierre de Socrethar auprès de Silroth à la base de forge Géhenne.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10509] = {"En route pour la gloire",{"Apportez la Pierre de téléportation de Socrethar à Voren'thal le Voyant sur le Degré des Clairvoyants à Shattrath.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10510] = {"Dans la mine de draenéthyste",{"Bronwyn Rudemartel vous a demandé de collecter 5 Cristaux de mine de draenéthyste puis de retourner la voir à Sylvanaar dans les Tranchantes."}}
D[10511] = {"Une étrange bière",{"Borgrim Rudemartel veut que vous vous procuriez 11 Foudroyantes-des-brutes de la Masse-sanglante pour lui. Lorsque ce sera fait, retournez le voir à Sylvanaar dans les Tranchantes."}}
D[10512] = {"Pinter les Flèchelame",{"Utilisez le Tonneau de foudroyante-des-brutes de la Masse-Sanglante pour tenter d'enivrer 5 Ogres de Flèchelame."}}
D[10513] = {"Oronok Cœur-fendu",{"Partez à la recherche d’Oronok Cœur-fendu sur la Saillie brisée, au nord de la Citerne de Glissentaille."}}
D[10514] = {"J'ai tenu bien des rôles…",{"Oronok Cœur-fendu, à la Ferme d'Oronok dans la vallée d'Ombrelune, veut que vous ramassiez 10 Tubercules d'Ombrelune dans les Plaines brisées.","","Il vous demande aussi de rapporter le Sifflet à sanglier d'Oronok lorsque vous aurez terminé."}}
D[10515] = {"Une leçon bien apprise",{"Oronok Cœur-fendu, à la Ferme d'Oronok dans la vallée d'Ombrelune, veut que vous détruisiez 10 Œufs d'écorcheurs voraces dans les Plaines brisées."}}
D[10516] = {"Les atours d'un redresseur de torts",{"Récupérez la Lame du redresseur de torts Vuuleen et le Bouclier du redresseur de torts Vuuleen. Rapportez-les au redresseur de torts Vuuleen au bastion de Flèchelame dans les Tranchantes."}}
D[10517] = {"Gorr'niaud, ton heure est venue...",{"Tuez Gorr'niaud, chef des Ogres du bastion de Flèchelame."}}
D[10518] = {"Planter la bannière",{"Utilisez la Bannière de Flèchelame au sommet de la Tour Nord-sanglante pour attirer Babin Graillebâfre. Récupérez la Bannière du clan Flèchelame et le Heaume de Babin Graillebâfre."}}
D[10519] = {"La Formule de damnation - vérité et histoire",{"Oronok Cœur-fendu à la ferme d'Oronok dans la vallée d'Ombrelune veut que vous écoutiez son histoire. Parlez à Oronok pour commencer à écouter son histoire."}}
D[10520] = {"L'aide à l'archidruide Forteramure",{"Parler à l'archidruide Fandral Forteramure à Darnassus."}}
D[10521] = {"Grom'tor, fils d'Oronok",{"Trouvez Grom'tor, fils d'Oronok à la Halte de Glissentaille dans la vallée d'Ombrelune."}}
D[10522] = {"La Formule de damnation - la charge de Grom'tor",{"Grom'tor, fils d'Oronok, de la Halte de Glissentaille dans la vallée d'Ombrelune, veut que vous récupériez le Premier fragment de la Formule de damnation."}}
D[10523] = {"La Formule de damnation - Premier fragment retrouvé",{"Apportez le coffret de Grom'tor à Oronok Cœur-fendu à la Ferme d'Oronok dans la vallée d'Ombrelune."}}
D[10524] = {"Artefacts du clan Sire-tonnerre",{"Récupérez le Tambour du clan Sire-tonnerre, la Flèche du clan Sire-tonnerre et la Tablette du clan Sire-tonnerre. Rapportez-les avec l'Artefact du clan Sire-tonnerre à Rokgah Poigne-sang au bastion des Sire-tonnerre dans les Tranchantes."}}
D[10525] = {"Guide de vision",{"Utilisez le Fragment d'âme flamboyante pour transformer votre esprit en un guide de vision qui vous dévoilera la position de la dernière relique Sire-tonnerre."}}
D[10526] = {"La Pointe du tonnerre",{"Récupérer la Pointe du tonnerre."}}
D[10527] = {"Ar'tor, fils d'Oronok",{"Trouvez Ar'tor, fils d'Oronok à la Halte Illidari dans la vallée d'Ombrelune."}}
D[10528] = {"Prisons de cristal démoniaque",{"Trouvez la Maîtresse de la douleur Gabrissa à la Halte Illidari et tuez-la, puis rapportez le cadavre d'Ar'tor, fils d'Oronok avec la Clé cristalline."}}
D[10529] = {"La voie du chasseur",{"Parlez au lieutenant Coursaurore à la retraite des Pérégrins."}}
D[10530] = {"La voie du chasseur",{"Parlez au lieutenant Coursaurore à la retraite des Pérégrins."}}
D[10531] = {"La bataille pour le bassin d'Arathi !",{"Attaquez la mine, la scierie, la forge et la ferme, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}}
D[10532] = {"Couper les voies de ravitaillement d'Arathor",{"Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au nécrotraqueur Mortis au Trépas-d'Orgrim."}}
D[10533] = {"Plus de caisses de ressources"}
D[10534] = {"Retourner chez soi",{"Caedmos de l'Exodar vous demande de venir le voir."}}
D[10535] = {"Les ressources du bassin d'Arathi",{"Gagnez la bataille pour le bassin d'Arathi, obtenez une Caisse de resssources d'Arathi et rapportez-la au sergent Maclear au Refuge de l'Ornière."}}
D[10536] = {"Plus de caisses de ressources"}
D[10537] = {"Lohn'goron, arc du Cœur-fendu",{"L'Esprit d'Ar'tor à la Halte Illidari dans la vallée d'Ombrelune veut que vous repreniez Lohn'goron, arc du Cœur-fendu aux démons de la région."}}
D[10538] = {"Sang bouillonnant",{"Utilisez le Sang de l'Orbite-sanglante au Chaudron maudit pour fabriquer du Sang bouilli. Apportez 12 mesures de Sang bouilli à l'Apothicaire Albreck au Poste de Brise-échine."}}
D[10539] = {"Retourner chez soi",{"Caedmos de l’Exodar vous demande de venir le voir."}}
D[10540] = {"La Formule de damnation - la charge d'Ar'tor",{"L'Esprit d'Ar'tor à la Halte Illidari dans la vallée d'Ombrelune veut que vous récupériez le Second fragment de la formule de damnation sur Veneratus le Multiple.","","Les créatures attaquées par le Chasseur d'esprit ou qui subissent des dégâts infligés par lui ne rapportent ni butin ni expérience."}}
D[10541] = {"La Formule de damnation - Second fragment retrouvé",{"Apportez le Coffret d'Ar'tor à Oronok Cœur-fendu à la Ferme d'Oronok dans la vallée d'Ombrelune."}}
D[10542] = {"On m'a piqué mon narguilé et mes bibines !",{"Récupérez le Narguilé de T'chali et 10 Foudroyantes-des-brutes de la Masse-sanglante. Apportez-les à T'chali le Sorcier-docteur au Ravin de la Masse-sanglante dans les Tranchantes."}}
D[10543] = {"Grimnok et Korgaah, je viens vous chercher !",{"Tuez Grimnok Champ-d'honneur et Korgaah."}}
D[10544] = {"Malédiction sur vos deux clans !",{"Utilisez le Fétiche salement fortiche pour maudire 5 bâtiments ou tours du Bastion de Flèchelame et 2 de l'avant-poste Masse-Sanglante."}}
D[10545] = {"Beuverie chez les Flèchelame",{"Utilisez le Tonneau de foudroyante-des-brutes de la Masse-Sanglante pour saouler 5 Ogres de Flèchelame."}}
D[10546] = {"Borak, fils d'Oronok",{"Trouvez Borak, fils d'Oronok près de la Halte de l'éclipse dans la vallée d'Ombrelune."}}
D[10547] = {"Des chardonomanes et des œufs",{"Borak, fils d'Oronok, sur le pont au nord de la Halte de l'éclipse, veut que vous trouviez un Œuf d'arakkoa pourri et que vous l'apportiez à Tobias le Goinfre-crasse à Shattrath, qui se trouve au nord-ouest de la forêt de Terokkar."}}
D[10548] = {"La triste vérité",{"Erelan, à Tranquillien, veut que vous retrouviez la Tête d'archéologue réduite dans l'un des coffres de Zeb'Tela ou Zeb'Nowa."}}
D[10550] = {"Le fagot de chardons sanglants",{"Rapportez le Fagot de chardons sanglants à Borak, fils d'Oronok sur le pont près de la Halte de l'éclipse dans la vallée d'Ombrelune."}}
D[10551] = {"Allégeance aux Aldor"}
D[10552] = {"Allégeance aux Clairvoyants"}
D[10553] = {"Voren'thal le Voyant",{"Parlez à Voren'thal le Voyant à l'intérieur de la Bibliothèque du Voyant sur le Degré des Clairvoyants à Shattrath.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10554] = {"Ishanah",{"Parlez à Ishanah à l'intérieur du Sanctuaire de la Lumière perpétuelle sur l'Éminence de l'Aldor à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10555] = {"Malaise",{"Réunissez 18 Plumes lashh'an arrachées, puis lisez le Tome lashh'an dans les cimes des arbres du Voile Lashh."}}
D[10556] = {"Égratignures",{"Utilisez la Poignée de plumes dans le Cercle magique lashh'an."}}
D[10557] = {"Vol d'essai : le Zephyrium Capacitorium",{"Parlez à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium. Puis retournez voir Tally Rossecoquin au Poste de Toshley."}}
D[10558] = {"Révéré par le bastion de l'Honneur",{"Le commandant de corps Danath Trollemort du bastion de l'Honneur dans la péninsule des Flammes infernales veut que vous deveniez <Révéré/Révérée> par le bastion de l'Honneur en combattant des Gangr'orcs à l'intérieur des Salles brisées de la citadelle des Flammes infernales."}}
D[10559] = {"Révéré par Thrallmar",{"Nazgrel, à Thrallmar dans la péninsule des Flammes infernales, veut que vous deveniez <Révéré/Révérée> par Thrallmar en combattant les Gangr'orcs à l'intérieur des Salles brisées de la citadelle des Flammes infernales."}}
D[10560] = {"Révéré par les Sha'tar",{"A'dal, de Shattrath, veut que vous deveniez <Révéré/Révérée> par les Sha'tar en vainquant les forces de Kael'thas à l'intérieur du Donjon de la Tempête."}}
D[10561] = {"Révéré par les Gardiens du temps",{"Andormu à l'intérieur des Grottes du temps à Tanaris veut que vous deveniez <Révéré/Révérée> par les Gardiens du temps en continuant à défendre les événements de Hautebrande d'antan et du Noir Marécage à l'intérieur des Grottes du temps."}}
D[10562] = {"Assiégés !",{"Le chef d'escadrille Nuainn, à l'extérieur du bastion des Marteaux-hardis, vous demande de tuer 10 Attaquants infernaux."}}
D[10563] = {"Vers le bastion de la Légion",{"Rendez-vous au Bastion de la Légion et localisez le Système de communication de la Légion. Quand vous serez près de lui, utilisez votre déguisement pour apprendre les plans de la Légion. Retournez voir le chef d'escadrille Nuainn, au bastion des Marteaux-Hardis, quand vous aurez accompli votre mission."}}
D[10564] = {"Au diable les infernaux !",{"Placez-vous sur le glyphe vert des fortifications du bastion de la Légion et utilisez la Gangrebombe. Ensuite, revenez faire votre rapport au chef d'escadrille Nuainn, au bastion des Marteaux-Hardis."}}
D[10565] = {"Les pierres de Vekh'nir",{"Récupérez un Cristal vekh'nir et utilisez-le au Cercle magique vekh'nir, puis rapportez le Cristal vekh'nir chargé à Dertrok au village Mok'Nathal."}}
D[10566] = {"Par tâtonnements",{"Essayez chacune des baguettes de Dertrok sur un Ogre esclave des arakkoa. Chaque utilisation d'une baguette nécessite un Cristal vekh'nir imprégné."}}
D[10567] = {"Créer le pendentif",{"Procurez-vous 6 Griffes de Ruuan'ok et utilisez-les au Cercle d'oracle ruuan'ok pour invoquer un Messager du Corbeau. Tuez-le et rapportez son Pendentif de messager à Timeon dans la Sylve Ruuan."}}
D[10568] = {"Les tablettes de Baa'ri",{"L'anachorète Ceyla de l'Autel de Sha'tar veut que vous récupériez 12 Tablettes baa'ri sur le sol et sur les Ouvriers cendrelangues aux Ruines de Baa'ri.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10569] = {"Les débris de Sketh'lon",{"Récupérez le Journal du commandant de Sketh'lon - Page 1, le Journal du commandant de Sketh'lon - Page 2 et le Journal du commandant de Sketh'lon - Page 3 détenues par les arakkoa du sombre Conclave aux Débris sketh'lon, puis rapportez-les au Chevaucheur de griffons Kieran."}}
D[10570] = {"Pour une poignée de chardons",{"Borak, fils d'Oronok, du pont qui se trouve près de la halte de l'Éclipse dans la vallée d'Ombrelune, vous demande de récupérer la Missive de Hurlorage."}}
D[10571] = {"Oronu l'Ancien",{"L'anachorète Ceyla de l'Autel de Sha'tar veut que vous vous procuriez les Ordres d'Akama sur Oronu l'Ancien aux Ruines de Baa'ri.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10572] = {"La préparation de la bombe",{"Procurez-vous une Batterie de saccageur gangrené et une Plaque de blindage de saccageur gangrené. Apportez-les au Chef d'escadrille Nuainn au Bastion des Marteaux-Hardis."}}
D[10573] = {"La Forgemort",{"Présentez-vous à Ewan Aile-sauvage le Tempétueux à la Tour de la Forgemort."}}
D[10574] = {"Les corrupteurs cendrelangues",{"Procurez-vous les quatre fragments du médaillon sur Haalum, Eykenen, Lakaan et Uylaru et rapportez-les à l'anachorète Ceyla à l'Autel de Sha'tar dans la vallée d'Ombrelune.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10575] = {"La Cage de la gardienne",{"L'anachorète Ceyla veut que vous entriez dans la Cage de la gardienne, au sud des ruines de Baa'ri, et que vous interrogiez Sanoru pour apprendre où se trouve Akama.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10576] = {"Le bonneteau d'Ombrelune",{"Borak, fils d'Oronok, du pont qui se trouve près de la halte de l'Éclipse dans la vallée d'Ombrelune, vous demande de récupérer 6 pièces d'Armure éclipsion."}}
D[10577] = {"Ce qu'Illidan veut, Illidan l'obtient…",{"Borak, fils d'Oronok, du pont qui se trouve près de la halte de l'Éclipse dans la vallée d'Ombrelune, vous demande de remettre le message d'Illidan au grand commandant Ruusk à la halte de l'Éclipse."}}
D[10578] = {"La Formule de damnation - la charge de Borak",{"Borak, fils d'Oronok, du pont qui se trouve près de la halte de l'Éclipse dans la vallée d'Ombrelune, vous demande de prendre la Troisième partie de la formule de damnation à Ruul l'Assombrisseur.","","Cette mission nécessite un groupe."}}
D[10579] = {"La Formule de damnation - Troisième fragment retrouvé",{"Apportez le coffret de Borak à Oronok Cœur-fendu à la Ferme d'Oronok dans la vallée d'Ombrelune."}}
D[10580] = {"Où sont passés ces fichus Gnomes ?",{"Fouillez la zone sud de la Crête dentelée, dans les Tranchantes pour y trouver des indices quant à l'endroit où pourraient se trouver Toshley et les autres Gnomes."}}
D[10581] = {"Suivre les miettes",{"Suivez la piste de pièces détachées tombées le long de la rampe vers la Tranchecrête. Parlez à Toshley au poste de Toshley, dans les Tranchantes."}}
D[10582] = {"Les séides du Conseil des ombres",{"Ewan Aile-sauvage le Tempétueux à la Tour de la Forgemort veut que vous tuiez 10 Gardiens de la Forgemort et 5 Invocateurs de la Forgemort."}}
D[10583] = {"Le destin de Flanis",{"Ewan Aile-sauvage le Tempétueux, à la Tour de la Forgemort, veut que vous alliez fouiller la Forgemort à la recherche de Flanis Aile-vive et que vous récupériez le Sac de Flanis."}}
D[10584] = {"Récupérer quelques convertisseurs de puissance",{"Utilisez le Collecteur magnétique proto-voltaïque pour récupérer 5 Electromentaires."}}
D[10585] = {"La chambre d'invocation",{"Procurez-vous un Déplaceur élémentaire sur un Forgeron de la Forgemort ou un Bricoleur de la Forgemort et utilisez-le pour interrompre le rituel dans la chambre d'invocation. Faites votre rapport à Ewan Aile-sauvage le tempétueux à la Tour de la Forgemort lorsque vous aurez accompli cette tâche."}}
D[10586] = {"Abattez le porteguerre !",{"Tuez le porteguerre Razuun, récupérez les Ordres de Razuun et retournez voir le chef d'escadrille Nuainn, au bastion des Marteaux-Hardis."}}
D[10587] = {"Les terrains d'entraînement de Karabor",{"L'exarque Onaala de l'Autel de Sha'tar veut que vous vous procuriez 8 Glaives solfurie sur les Suppliants chasseurs de démons et les Initiés chasseurs de démons aux Ruines de Karabor, au sud-est de l'Autel de Sha'tar.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10588] = {"La formule de damnation",{"Utilisez la Formule de damnation à l'Autel de la damnation pour invoquer Cyrukh le seigneur du Feu.","","Détruisez Cyrukh le seigneur du Feu puis parlez au Soigneterre Torlok, qui se trouve aussi à l'Autel de la damnation."}}
D[10589] = {"Obtenir un accès",{"Apportez une Commande du téléporteur de la Légion au chef d'escadrille Nuainn au bastion des Marteaux-Hardis. On sait que les Fabricants d'armes mo'arg du bastion de la Légion portent ces appareils."}}
D[10590] = {"Sachez prouver votre haine",{"Mehlar Aubelame, à la Barricade, veut que vous lui apportiez 20 Pierres du Fléau des serviteurs."}}
D[10592] = {"La sagesse de la reine banshee",{"Apportez les Fragments de pierre du Fléau à dame Sylvanas Coursevent à Fossoyeuse."}}
D[10593] = {"Un mal ancien",{"Percez les secrets du Temple d’Atal’Hakkar pour libérer Atal'alarion et récupérer dans sa chair la Liane putride. Retournez voir Melhar à la Barricade quand vous aurez terminé cette tâche."}}
D[10594] = {"Mesurer la fréquence de résonance",{"Placez les Scanners à fréquence oscillante de telle sorte que, lorsque vous vous tenez en leur centre, vous vous trouvez dans le chevauchement de cinq champs d'oscillation."}}
D[10595] = {"Assiégés !",{"Le garde de sang Gulmok, à l'extérieur du village d'Ombrelune, vous demande de tuer 10 Attaquants infernaux."}}
D[10596] = {"Vers le bastion de la Légion",{"Rendez-vous au Bastion de la Légion, localisez le Système de communication de la Légion et utilisez votre déguisement pour apprendre les plans de la Légion. Retournez voir le garde de sang Gulmok, au village d'Ombrelune, quand vous aurez accompli votre mission."}}
D[10597] = {"La préparation de la bombe",{"Procurez-vous une Batterie de saccageur gangrené et une Plaque de blindage de saccageur gangrené. Apportez-les au garde de sang Gulmok au village d'Ombrelune."}}
D[10598] = {"Au diable les infernaux !",{"Utilisez la Gangrebombe en vous tenant dans le glyphe vert dans le Bastion de la Légion afin de détruire les Infernaux, puis venez faire votre rapport au garde de sang Gulmok, au village d'Ombrelune."}}
D[10599] = {"La Forgemort",{"Présentez-vous à l'éclaireur Zagran au Guet des scories."}}
D[10600] = {"Les séides du Conseil des ombres",{"L’Eclaireur Zagran au Guet des scories veut que vous tuiez 10 Gardiens de la Forgemort et 5 Invocateurs de la Forgemort."}}
D[10601] = {"Le destin de Kagrosh",{"L'éclaireur Zagran du Guet des scories veut que vous alliez fouiller la Forgemort à la recherche de Kagrosh et que vous récupériez le Sac de Kagrosh."}}
D[10602] = {"La chambre d'invocation",{"Procurez-vous un Déplaceur élémentaire sur un Forgeron de la Forgemort ou un Bricoleur de la Forgemort et utilisez-le pour interrompre le rituel dans la chambre d'invocation. Faites votre rapport à l'éclaireur Zagran au Guet des scories lorsque vous aurez terminé votre mission."}}
D[10603] = {"Abattez le porteguerre !",{"Tuez le porteguerre Razuun, récupérez les Ordres de Razuun et retournez voir le garde de sang Gulmok, au village d'Ombrelune."}}
D[10604] = {"Obtenir un accès",{"Apportez une Commande du téléporteur de la Légion au garde de sang Gulmok, au village d'Ombrelune. On sait que les Fabricants d'armes mo'arg du bastion de la Légion portent ces appareils."}}
D[10605] = {"L'appel de Carendin",{"Parlez à Carendin Halgar à Fossoyeuse."}}
D[10606] = {"L'art de l'entretien des saccageurs gangrenés",{"Tuez le Docteur Gutrick et procurez-vous la Clé du docteur. Utilisez la clé pour ouvrir le Coffre-fort du docteur, récupérez L'Art de l'entretien des saccageurs gangrenés, et apportez le livre à Plexi au Site d'invasion Cataclysme."}}
D[10607] = {"Les murmures du dieu corbeau",{"Tuez un arakkoa Grishna pour obtenir la Compréhension du corvidien pendant 2 minutes. Tant que vous serez sous l’effet de ce sort, vous pourrez trouver et recevoir la prophétie des quatre sanctuaires."}}
D[10608] = {"Clair comme le cristal",{"Clignecoche le Métro-gnome veut que vous alliez tuer 10 Écorcheurs de cristal puis que vous retourniez le voir au Poste de Toshley dans les Tranchantes."}}
D[10609] = {"Qui est apparu en premier, l'œuf ou le drake ?",{"Collectez 3 Essences de proto-drake du Néant, 3 Essences de jeune drake du Néant et 3 Essences de drake du Néant adulte. Rapportez-les à Fizit « Doc » Cliquetic au poste de Toshley dans les Tranchantes."}}
D[10610] = {"La prospection des matières premières"}
D[10611] = {"L’Art de l’entretien des saccageurs gangrenés",{"Tuez le Docteur Maleficus et procurez-vous la Clé du docteur. Utilisez la clé pour ouvrir le Coffre-fort du docteur, récupérez L'Art de l'entretien des saccageurs gangrenés, et apportez le livre à Nakansi au Site d'invasion Cataclysme."}}
D[10612] = {"La guerre des boutons",{"Utilisez une Console de contrôle de saccageur gangrené pour prendre le contrôle d'une Sentinelle saccageur gangrené. Détruisez 60 Infernaux mortforgés avant que votre saccageur gangrené ne cesse de fonctionner. Quand votre mission sera achevée, faites votre rapport à Plexi au Site d'invasion : Cataclysme."}}
D[10613] = {"La guerre des boutons",{"Utilisez une Console de contrôle de saccageur gangrené pour prendre le contrôle d'une Sentinelle saccageur gangrené. Détruisez 60 Infernaux mortforgés avant que votre saccageur gangrené ne cesse de fonctionner. Quand votre mission sera achevée, faites votre rapport à Nakansi au Site d'invasion : Cataclysme."}}
D[10614] = {"Des murmures dans le vent",{"Parlez à Leoroxx à Mok’Nathal, dans les Tranchantes."}}
D[10615] = {"La sylve Ruuan",{"Parlez à Timeon au Bosquet éternel, dans la Sylve Ruuan des Tranchantes."}}
D[10617] = {"Cocons d'aile-de-soie",{"Taerek, de Mok'Nathal, veut que vous collectiez 8 Cocons d'aile-de-soie sur des Larves d'aile-de-soie.","","Tuez rapidement les larves, ou elles se changeront en Ailes-de-soie, ce qui détruirait leurs cocons."}}
D[10618] = {"Les ailes les plus douces",{"Silmara, de Mok'Nathal, veut que vous collectiez 12 Ailes iridescentes."}}
D[10619] = {"La tribu cendrelangue",{"Le redresseur de torts Aluumen veut que vous partiez pour les Ruines de Baa'ri afin d'y tuer 3 Dresseurs cendrelangues, 4 Guerriers cendrelangues et 6 Chamans cendrelangues.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation envers les Clairvoyants."}}
D[10620] = {"La menace crêtéchine",{"Tuez 10 Traqueuses crêtéchine."}}
D[10621] = {"Éclat plaie-des-Illidari",{"Apportez l'Éclat plaie-des-Illidari à Ordinn Tonnepoing au bastion des Marteaux-hardis."}}
D[10622] = {"Preuve d'allégeance",{"Tuez Zandras à la Cage de la gardienne dans la vallée d'Ombrelune et retournez voir Sanoru."}}
D[10623] = {"Éclat plaie-des-Illidari",{"Apportez l'Éclat plaie-des-Illidari à Grokom Oeil-de-mort au village d'Ombrelune."}}
D[10624] = {"L'histoire hantée",{"L'Apothicaire en chef Hildagard du Village d'Ombrelune vous demande de lui rapporter 15 échantillons de Cendre semperardente."}}
D[10625] = {"Lunectoplasmes",{"L'Apothicaire en chef Hildagard du village d'Ombrelune dans la vallée d'Ombrelune vous demande de tuer 12 Zélotes ombrelunes."}}
D[10626] = {"S'emparer des armes",{"Ordinn Tonnepoing du bastion des Marteaux-Hardis veut que vous lui apportiez le Glaive de Makazradon et le Glaive de Morgroron."}}
D[10627] = {"S'emparer des armes",{"Grokom Œil-de-mort du village d'Ombrelune veut que vous lui apportiez le Glaive de Makazradon et le Glaive de Morgroron."}}
D[10628] = {"Akama",{"Parler à Akama à l'intérieur de la chambre cachée de la Cage de la gardienne."}}
D[10629] = {"Un boulot de m...",{"\"Utilisez le Sifflet à gangrechien pour invoquer un Gangrechien. Promenez le gangrechien et tuez des Sangliers infernaux dérangés. Cherchez les Clés du déchiqueteur dans la \"livraison\" du gangrechien. Rapportez les Clés du déchiqueteur au contremaître Razelcraz près de la mine au nord-ouest de Thrallmar."}}
D[10630] = {"Sous Thrallmar",{"Tuez Urga'zz puis retournez voir le contremaître Razelcraz près de la mine au nord-ouest de Thrallmar."}}
D[10632] = {"Couper quelques crocs...",{"Récupérez 5 Dents de Crocs-lames extrêmement affûtées."}}
D[10633] = {"Teron Fielsang - Mythes et légendes",{"L'apothicaire en chef Hildagard du village d'Ombrelune dans la vallée d'Ombrelune vous demande de trouver l'Esprit ancien d'Ombrelune.","","Si vous perdez vos Lunectoplasmes, l'apothicaire en chef Hildagard peut vous en faire une nouvelle paire."}}
D[10634] = {"Divination: l'armure de Fielsang",{"L'Esprit ancien d'Ombrelune à l'Autel des Ombres dans le sud-est de la vallée d'Ombrelune vous demande de récupérer l'Armure de Fielsang."}}
D[10635] = {"Divination: la cape de Fielsang",{"L'Esprit ancien d'Ombrelune à l'Autel des Ombres dans le sud-est de la vallée d'Ombrelune vous demande de récupérer la Cape de Fielsang."}}
D[10636] = {"Divination : l'assommoir de Fielsang",{"L'Esprit ancien d'Ombrelune à l'Autel des Ombres dans le sud-est de la vallée d'Ombrelune vous demande de récupérer l'Assommoir de Fielsang."}}
D[10637] = {"Une diversion nécessaire",{"L'exarque Onaala de l'Autel de Sha'tar veut que vous retourniez aux Ruines de Karabor et que vous trouviez un moyen de lâcher Azaloth sur ceux qui le tiennent enfermé.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10638] = {"CECI N'EST PAS UNE QUÊTE",{"Allez voir <NOM> dans le <QUARTIER> de Lune-d’Argent."}}
D[10639] = {"Teron Fielsang, je suis...",{"L'Esprit ancien d'Ombrelune s'est joué de vous ! Maintenant que vous avez les objets dont il avait besoin, il vous a révélé être Teron Fielsang. Pour vous libérer de sa possession, vous devez faire ce qu'il ordonne et tuer Karsius l'Antique Guetteur.","","Si vous y parvenez, retournez voir l'Apothicaire en chef Hildagard au village d'Ombrelune."}}
D[10640] = {"Altruis",{"Voyagez jusqu'au Nagrand occidental et allez trouver Altruis le souffrant.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10641] = {"Contre la Légion",{"Altruis le Souffrant veut que vous obteniez du Sang fraîchement versé d’une Prêtresse de colère à la Base de forge Géhenne, à Raz-de-Néant. Versez-le sur le sol et tuez l’Avatar de Sathal. Revenez voir Altruis quand vous aurez accompli votre mission."}}
D[10642] = {"Le fantôme dans la machine",{"Zorus l'adjudicateur du bastion des Marteaux-hardis dans la vallée d'Ombrelune veut que vous lui apportiez 15 Échantillons de cendre semperardente."}}
D[10643] = {"Messagers d'Ombrelune",{"Zorus le Judicateur du bastion des Marteaux-Hardis dans la vallée d'Ombrelune veut que vous alliez tuer 12 Messagers ombrelunes."}}
D[10644] = {"Teron Fielsang - Mythes et légendes",{"Zorus le Judicateur du bastion des Marteaux-Hardis dans la vallée d'Ombrelune vous demande de trouver l'Esprit ancien d'Ombrelune.","","Si vous perdez vos Lunectoplasmes, Zorus l'adjudicateur peut vous en fabriquer une nouvelle paire."}}
D[10645] = {"Teron Fielsang, je suis...",{"L'Esprit ancien d'Ombrelune s'est joué de vous ! Maintenant que vous avez les objets dont il avait besoin, il vous a révélé être Teron Fielsang. Pour vous libérer de sa possession, vous devez faire ce qu'il ordonne et tuer Karsius l'Antique Guetteur.","","Si vous y parvenez, retournez voir Zorus l'adjudicateur au Bastion des Marteaux-hardis."}}
D[10646] = {"Le disciple d'Illidan",{"Écoutez l'histoire d'Altruis."}}
D[10647] = {"Avis de recherche : Uvuros, Fléau d'Ombrelune",{"Tuez Uvuros et récupérez la Crinière flamboyante d'Uvuro. Rapportez-la à Sardon Frantaille le Hurleguerre au village d'Ombrelune dans la vallée d'Ombrelune."}}
D[10648] = {"Avis de recherche : Uvuros, Fléau d'Ombrelune",{"Tuez Uvuros et récupérez la Crinière flamboyante d'Uvuro. Rapportez-la à Musebière le Hurleguerre au Bastion des Marteaux-hardis dans la vallée d'Ombrelune."}}
D[10649] = {"Le Livre des noms gangrenés",{"Entrez dans le Labyrinthe des Ombres d'Auchindoun et procurez-vous le Livre des noms gangrenés sur Cœur-noir le Séditieux. Retournez voir Altruis en Nagrand une fois cette tâche accomplie."}}
D[10650] = {"Retour à l'Aldor",{"Parlez à l'exarque Onaala à l'Autel de Sha'tar dans la vallée d'Ombrelune.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10651] = {"Il faut arrêter Varedis",{"L’exarque Onaala veut que vous vous rendiez aux ruines de Karabor et que vous tuiez Alandien, Theras, Netharel et Varedis. Utilisez le Livre des noms gangrenés quand Varedis utilisera sa métamorphose, pour l’affaiblir. Retournez voir l'exarque Onaala avec le Livre des noms gangrenés lorsque vous aurez terminé cette tâche.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10652] = {"Derrière les lignes ennemies",{"Parlez à Veronia lorsque vous serez <prêt/prête> à partir pour la Manaforge Coruu. Une fois là-bas, parlez à Caledis Brillaube.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10653] = {"Les marques de Sargeras",{"Remettre 10 Marques de Sargeras à Adyen le Gardelumière, à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10654] = {"De nouvelles marques de Sargeras",{"Do you bear more of our enemies' insignias, <classe>? The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them."}}
D[10655] = {"Une marque de Sargeras",{"S’il vous reste d'autres insignes, ils m'intéressent. Ne vous en faites pas, vos actions seront dûment rapportées."}}
D[10656] = {"Les chevalières Solfurie",{"La magistrice Fyalenn de Shattrath veut que vous lui apportiez 10 Chevalières Solfurie.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de la faction Aldor."}}
D[10657] = {"Chevauche la foudre",{"Utilisez la Magnéto-sphère repolarisée pour absorber 25 décharges de foudre des Serpents ailécailles. Collectez également 5 Glandes d’éclair ailécailles."}}
D[10658] = {"De nouvelles chevalières Solfurie"}
D[10659] = {"Une chevalière Solfurie",{"Even the smallest contribution to our cause is noted, <nom>. Our enemies are many, but we shall prevail!"}}
D[10660] = {"Quelles étranges créatures...",{"Le chercheur Tiorus du village d'Ombrelune dans la vallée d'Ombrelune veut que vous vous procuriez 8 Rates de gangrefeu."}}
D[10661] = {"Ex-rate-ordinaires !",{"Gnomus du bastion des Marteaux-hardis dans la vallée d'Ombrelune veut que vous récupériez 8 Rates gangrefeu."}}
D[10662] = {"L'ermite forgeron",{"Apportez la Boîte de lingots à David Wayne au Refuge de Wayne dans la forêt de Terokkar."}}
D[10663] = {"L'ermite forgeron",{"Apportez la Boîte de lingots à David Wayne au Refuge de Wayne, dans la forêt de Terokkar."}}
D[10664] = {"Matériel supplémentaire",{"David Wayne du Refuge de Wayne veut que vous lui apportiez une Structure en adamantite, 4 Cuirs granuleux lourds et un Totem de sauvegarde contre les démons."}}
D[10665] = {"Tout frais du Méchanar",{"David Wayne du Refuge de Wayne veut que vous lui apportiez une Cellule de mana surchargée."}}
D[10666] = {"Le Lexicon Demonica",{"Procurez-vous le Lexicon Demonica sur le Grand Maître Vorpil et apportez-le à David Wayne au Refuge de Wayne."}}
D[10667] = {"De la terre du monde souterrain",{"Obtenez une Fiole de terre du monde souterrain de l'hydromancienne Thespia et apportez-la à David Wayne au Refuge de Wayne."}}
D[10668] = {"Contre les Illidari",{"Altruis le Souffrant veut que vous alliez tuer Lothros à la Halte Illidari dans la vallée d'Ombrelune."}}
D[10669] = {"Contre toute attente",{"Altruis le Souffrant veut que vous preniez la Lance en argent imprégné et que vous l'utilisiez dans la Clairière du portail près du Lac des furoles du marécage de Zangar pour réveiller Xeleth. Retournez voir Altruis lorsque vous aurez tué le démon."}}
D[10670] = {"La Larme de la Terre-Mère",{"Reprenez la Larme de la Terre-Mère au Porteguerre O’mrogg et apportez-la à David Wayne au Refuge de Wayne."}}
D[10671] = {"Plus d'une livre de chair",{"Collectez 5 morceaux de Chair éthernergisée."}}
D[10672] = {"Franchement, ça n'a aucun sens…",{"Le chercheur Tiorus du village d'Ombrelune dans la vallée d'Ombrelune vous demande de voyager jusqu'aux coulées de lave près des ruines de Baa'ri, d'utiliser l'Unité d'arcano-contrôle pour prendre le contrôle d'un Arcano-Scorp, de nager dans la lave à l'aide de l'Arcano-Scorp et de marquer 8 Grands Dimeurtrodons de gangrefeu."}}
D[10673] = {"Gangréchine la Très-Grande",{"Le chercheur Tiorus du village d'Ombrelune dans la vallée d'Ombrelune vous demande de tuer Gangréchine la Très-Grande et de récupérer la Peau de Gangréchine."}}
D[10674] = {"Et la lumière fut... piégée",{"Utilisez le Piège à lumière pour attraper 15 Orbes de lumière razaani."}}
D[10675] = {"Dégnomez-les tous !",{"Récupérez la Collection d’âmes."}}
D[10676] = {"La plaie des Illidari",{"Attendez que David Wayne ait terminé de forger une épée pour vous."}}
D[10677] = {"Le deuxième service...",{"Gnomus du bastion des Marteaux-Hardis dans la vallée d'Ombrelune veut que vous récupériez 1 Gésier de gangrefeu surdéveloppé."}}
D[10678] = {"Le plat principal !",{"Gnomus du bastion des Marteaux-Hardis dans la vallée d'Ombrelune veut que vous récupériez la Peau de Gangréchine."}}
D[10679] = {"Tremper la lame",{"Voyagez jusqu'aux Bassins Brûlants situés près du sommet de la Main de Gul’dan et utilisez la Lame plaie-des-Illidari forgée pour la tremper dans les bassins de lave. Une fois que vous aurez la Lame plaie-des-Illidari trempée, retournez auprès de David Wayne au Refuge de Wayne."}}
D[10680] = {"La main de Gul'dan",{"Parlez au soigneterre Torlok à l'Autel de la damnation dans la vallée d'Ombrelune."}}
D[10681] = {"La main de Gul'dan",{"Parlez au soigneterre Torlok à l'Autel de la damnation dans la vallée d'Ombrelune."}}
D[10682] = {"Un temps pour la négociation...",{"Le Gardien des arbres Chawn vous a demandé de négocier avec le Surveillant Nuaar. Ensuite, retournez voir le gardien des arbres au Bosquet éternel dans les Tranchantes."}}
D[10683] = {"Tablettes de Baa'ri",{"L'arcaniste Thelis du Sanctum des Étoiles veut que vous collectiez 12 Tablettes baa'ri aux Ruines de Baa'ri.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10684] = {"Oronu l'Ancien",{"L'arcaniste Thelis du Sanctum des Étoiles veut que vous preniez les Ordres d'Akama à Oronu l'Ancien aux Ruines de Baa'ri.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10685] = {"Les corrupteurs cendrelangues",{"Procurez-vous les quatre fragments du médaillon sur Haalum, Eykenen, Lakaan et Uylaru et rapportez-les à l'arcaniste Thelis au Sanctum des Étoiles dans la vallée d'Ombrelune.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10686] = {"La Cage de la gardienne",{"L'arcaniste Thelis veut que vous entriez dans la Cage de la gardienne, au sud des ruines de Baa'ri, et que vous interrogiez Sanoru pour apprendre où se trouve Akama.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10687] = {"Les terrains d'entraînement de Karabor",{"Larissa Heurtesoleil au Sanctum des Étoiles veut que vous vous procuriez 8 Vouges solfurie sur les Suppliants solfurie et les Initiés solfurie aux Ruines de Karabor, au nord-est du Sanctum des étoiles.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10688] = {"Une diversion nécessaire",{"Larissa Heurtesoleil veut que vous retourniez aux Ruines de Karabor et que vous trouviez un moyen de lâcher Azaloth sur ses geôliers.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10689] = {"Altruis",{"Voyagez jusqu'au Nagrand occidental et allez trouver Altruis le Souffrant.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10690] = {"La Mère de la tanière",{"Tuez Rema puis informez-en le commandant Ombreciel à Sylvanaar dans les Tranchantes."}}
D[10691] = {"Retour chez les Clairvoyants",{"Parlez à Larissa Heurtesoleil au Sanctum des Étoiles dans la vallée d’Ombrelune.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10692] = {"Il faut arrêter Varedis",{"Larissa Heurtesoleil veut que vous vous rendiez aux ruines de Karabor et que vous tuiez Alandien, Theras, Netharel et Varedis. Utilisez le Livre des noms gangrenés quand Varedis utilisera sa métamorphose, pour l’affaiblir. Retournez voir Larissa Heurtesoleil avec le Livre des noms gangrenés lorsque vous aurez terminé cette tâche.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l’Aldor."}}
D[10693] = {"Une chevalière de mérite"}
D[10694] = {"Dix chevalières de mérite"}
D[10695] = {"Une chevalière de mérite"}
D[10696] = {"Dix chevalières de mérite"}
D[10697] = {"Une chevalière de mérite"}
D[10698] = {"Dix chevalières de mérite"}
D[10699] = {"Une chevalière de mérite"}
D[10700] = {"Dix chevalières de mérite"}
D[10701] = {"Briser Néantroche",{"Tuez Néantroche, puis présentez-vous au Chef-de-fusée Karlingue dans la Zone 52 de Raz-de-Néant."}}
D[10702] = {"Un travail de grunt...",{"Le suzerain Or'barokh du village d'Ombrelune dans la vallée d'Ombrelune vous demande de tuer 20 spécimens de la Faune de la vallée d'Ombrelune.","","Ces créatures comprennent les Sangliers gangrenés, les Chimères Ailevile et les Pinceurs Brûlecoquille. N'importe quelle combinaison conviendra."}}
D[10703] = {"Mettez des bottes...",{"Le thane Yoregar du bastion des Marteaux-hardis dans la vallée d'Ombrelune vous demande de tuer 20 spécimens de la faune de la vallée d'Ombrelune.","","Ces créatures comprennent les Sangliers gangrenés, les Chimères Ailevile et les Pinceurs Brûlecoquille. N'importe quelle combinaison fera l'affaire."}}
D[10704] = {"Comment pénétrer dans l’Arcatraz",{"A’dal vous a <chargé/chargée> de récupérer la Pièce supérieure et la Pièce inférieure de la clé de l’Arcatraz. Rapportez-les-lui et il s’en servira pour vous confectionner la Clé de l’Arcatraz."}}
D[10705] = {"Le voyant Udalo",{"Trouvez le voyant Udalo à l'intérieur de l'Arcatraz au Donjon de la Tempête."}}
D[10706] = {"Un mystérieux présage",{"Retournez voir Akama à la Cage de la gardienne dans la vallée d'Ombrelune."}}
D[10707] = {"La terrasse ata'mal",{"Allez au sommet de la Terrasse Ata'mal dans la vallée d’Ombrelune, et procurez-vous le Cœur de fureur. Retournez voir Akama à la Cage de la gardienne dans la vallée d'Ombrelune quand vous aurez accompli cette tâche."}}
D[10708] = {"La promesse d'Akama",{"Apportez le Médaillon de Karabor à A'dal, à Shattrath."}}
D[10709] = {"Réunion",{"Parlez à Rexxar, au bastion des Sire-tonnerre, dans les Tranchantes."}}
D[10710] = {"Vol d'essai : la Crête chantante",{"Signez la Décharge de Tally, puis allez parler à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium."}}
D[10711] = {"Vol d'essai : le point d'ancrage de Razaan",{"Parlez à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium."}}
D[10712] = {"Vol d'essai : la sylve Ruuan",{"Parlez à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium. Lors du vol vers la Sylve Ruuan, faites tourner la Girouette néantine. Remettez la Girouette néantine tournoyante à O'Mally Rossecoquin au Bosquet éternel."}}
D[10713] = {"… et un temps pour l'action",{"Tuez 10 Elagueurs du culte du Ver."}}
D[10714] = {"Sur les ailes de l'Esprit",{"Trouvez un Sous-chef de la Masse-Sanglante et un Devin de la Masse-Sanglante en pleine conversation, et utilisez le Sifflet de Rexxar pour appeler Esprit, afin qu’il les espionne."}}
D[10715] = {"Dans le Goulet bouillonnant",{"Procurez-vous 7 Glandes à venin de perceur de croûte."}}
D[10716] = {"Test Flight: Raven's Wood <needs reward>",{"Parlez à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium. Puis retournez voir Tally Rossecoquin au Poste de Toshley."}}
D[10717] = {"Du braconnage chez les braconniers",{"Procurez-vous 5 Filets du culte du Ver."}}
D[10718] = {"Les esprits entendent des voix...",{"Parlez à Rexxar au Bastion des Sire-tonnerre, dans les Tranchantes."}}
D[10719] = {"Vous avez eu la note ?",{"Apportez la Note de rendez-vous au Gardien des arbres Chawn au Bosquet éternel dans les Tranchantes."}}
D[10720] = {"Les plus petites des créatures",{"Utilisez le Tambour en cuir de kodo au Terrier des marmottes. Quand vous aurez pris le contrôle de la Marmotte, empoisonnez les trois tonneaux dans le camp des Masse-Sanglante."}}
D[10721] = {"Un tour de cochon pour Grulloc",{"Procurez-vous le Sac de Grulloc."}}
D[10722] = {"Rendez-vous au convent de l'Aile noire",{"Rassemblez suffisamment de Guenilles sur les différents sectateurs du Ver pour vous fabriquer un Déguisement de surveillant. Utilisez ce déguisement pour vous rendre au rendez-vous de Kolphis Sombrécaille."}}
D[10723] = {"Gorgrom le Mange-dragon",{"Procurez-vous 3 Totems macabres sur les Ogres de Roche'mok. Utilisez le Piège de Sablecrin à l'Autel de Gorgrom pour invoquer et tuer Gorgrom le Mange-dragon.","","Une fois Gorgrom mort, placez les 3 Totems macabres près de son cadavre."}}
D[10724] = {"Prisonnier de la Flèchelame",{"Tuez des Ogres de Flèchelame pour vous procurer la Clé de la cage à wyverne. Une fois que vous l'aurez, allez à la Cage à wyverne et utilisez le Sifflet d'Esprit pour appeler Esprit, qui déverrouillera la cage. Une fois Leokk libéré, revenez voir Rexxar au village des Sire-tonnerre dans les Tranchantes."}}
D[10725] = {"L'excellence auprès de l'Œil pourpre",{"Apportez votre Chevalière pourpre à l’archimage Leryda au défilé de Deuillevent après être <devenu Exalté/devenue Exaltée> auprès de l’Œil pourpre."}}
D[10726] = {"L'excellence auprès de l'Œil pourpre",{"Apportez votre Chevalière pourpre à l’archimage Leryda au défilé de Deuillevent après être <devenu Exalté/devenue Exaltée> auprès de l’Œil pourpre."}}
