D[11447] = {"Bienvenue à la fête des Brasseurs !",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11449] = {"L'entraînement au combat du feu",{"[Toss buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.]"}}
D[11450] = {"L'entraînement au combat du feu",{"Jetez de l'eau sur 5 feux, puis parlez à nouveau à la Directrice d'orphelinat masquée sur la Place de l'épervier."}}
D[11451] = {"Le poème d'Alicia",{"Alicia vous a demandé d'apporter son poème à Caylee Dak à Shattrath en Outreterre."}}
D[11454] = {"Trouver les saboteurs",{"Trouver Coren Navrebière dans le Sinistre écluseur, à l'intérieur des Profondeurs de Rochenoire."}}
D[11481] = {"Crise au Puits de soleil",{"Adyen le Gardelumière, de l'Éminence de l'Aldor à Shattrath, veut que vous vous rendiez au Plateau du Puits de soleil pour parler à Larethor."}}
D[11482] = {"L'appel du devoir",{"Dathris Heurtesoleil, de la Terrasse des Clairvoyants de Shattrath, insiste pour que vous retourniez immédiatement en Azeroth et que vous vous présentiez à Larethor au Puits de soleil."}}
D[11486] = {"La meilleure des bières",{"Apportez le Tonneau de bière sombrefer à Ipfelkofer Baril-de-fer en Dun Morogh."}}
D[11487] = {"La meilleure des bières",{"Apportez le Tonneau de bière sombrefer à Perce Fauchebaril en Durotar."}}
D[11488] = {"La terrasse des Magistères",{"L'exarque Larethor, de la Zone de rassemblement du Soleil brisé, vous demande d'explorer la Terrasse des magistères à la recherche de Tyrith, un espion elfe de sang."}}
D[11490] = {"Clairvoyance pour les Clairvoyants",{"Tyrith veut que vous utilisiez l'orbe sur le balcon de la Terrasse des Magistères."}}
D[11492] = {"L'increvable",{"Kalecgos vous a demandé de vaincre Kael'thas sur la Terrasse des Magistères. Vous devrez ramasser la tête de Kael avant de faire votre rapport à Larethor à la Zone de rassemblement du Soleil brisé."}}
D[11496] = {"Les protections du sanctum",{"Le Capitaine Theris Âtraurore, de la Zone de rassemblement du Soleil brisé, vous demande de vous procurer 4 Restes de mana sur les Fielleux déshérités et les Dévoreurs déshérités et de vous en servir pour alimenter un des Cristaux de protection qui entoure le Sanctum des Confins du soleil, à l'est."}}
D[11497] = {"Apprendre à voler",{"Parlez à Ilsa Fulminebière au Bastion des Marteaux-Hardis dans la Vallée d'Ombrelune."}}
D[11498] = {"Apprendre à voler",{"Parlez à Olrokk au Village d'Ombrelune dans la Vallée d'Ombrelune."}}
D[11499] = {"ON RECHERCHE : la chevalière du prince Kael’thas",{"Le Marchand des vents Zhareem vous a demandé de vous procurer la Chevalière du prince Kael'thas. Apportez-la-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu’à la Terrasse des Magistères en mode Héroïque."}}
D[11500] = {"On recherche : les sœurs du tourment",{"Le Traqueur-du-Néant Mah'duun vous a <chargé/chargée> de tuer 4 Sœurs du tourment. Revenez le voir à la Ville basse de Shattrath lorsque ce sera fait pour recevoir votre prime."}}
D[11502] = {"La défense de Halaa",{"Vaincre 10 joueurs ennemis à Halaa, puis retourner voir Lakoor à Telaar."}}
D[11503] = {"Ennemis, anciens et nouveaux",{"Abattez 10 joueurs ennemis à Halaa, puis retournez voir Karrtog à Garadar."}}
D[11505] = {"Les esprits d'Auchindoun",{"Aidez l'Alliance à prendre le contrôle d'une tour dans le désert des Ossements."}}
D[11506] = {"Les esprits d'Auchindoun",{"Aidez la Horde à prendre le contrôle d'une Tour des esprits dans le désert des Ossements."}}
D[11513] = {"Intercepter des cellules de mana",{"Procurez-vous 10 Cellules de mana de contrebande et apportez-les à l'Exarque Nasuun sur la Terrasse de la Lumière à Shattrath."}}
D[11514] = {"Maintenir le portail du Puits de soleil",{"Procurez-vous 10 Cellules de mana de contrebande et apportez-les à l'Exarque Nasuun sur la Terrasse de la Lumière à Shattrath."}}
D[11515] = {"Sang pour sang",{"La Magistrice Seyla, au Trône de Kil'jaeden, vous demande de tuer 4 Gangresangs émaciés en utilisant le gangresiphon sur eux. Vous aurez besoin de sang démoniaque, qui s’obtient sur les Hérauts de courroux des alentours, pour alimenter le siphon."}}
D[11516] = {"Détruire la porte",{"La Magistrice Seyla, au Trône de Kil'jaeden, vous demande d'utiliser les Braises grésillantes pour invoquer une Fusée vivante et de tuer les Gangrétincelles incandescentes près d'elle jusqu'à ce qu'elle devienne une Fusée vivante instable. Retournez à la Porte de la Légion avec la Fusée vivante instable pour la détruire."}}
D[11517] = {"Se présenter à Nasuun",{"Le Commerçant Portonuus veut que vous parliez à l'Exarque Nasuun, à la Terrasse de la Lumière de Shattrath."}}
D[11518] = {"Drapeau quotidien portail puits de soleil"}
D[11520] = {"À la découverte de vos racines",{"Mar'nah, au Port des Confins du soleil, vous demande de vous rendre sur l'Éminence de Tranchépine en Outreterre et de réunir 5 Racines de Tranchépine avant de revenir la voir."}}
D[11521] = {"À la redécouverte de vos racines",{"Mar'nah, du port des Confins du soleil, vous demande de vous rendre sur l'Éminence de Tranchépine en Outreterre et de vous procurer 5 Racines de Tranchépine avant de retourner la voir."}}
D[11523] = {"Armez les protections !",{"Le Capitaine Theris Âtraurore, de la Zone de rassemblement du Soleil brisé, vous demande de vous procurer 4 Restes de mana sur les Fielleux déshérités et les Dévoreurs déshérités et de vous en servir pour alimenter un des Cristaux de protection qui entoure les bâtiments des Confins du soleil."}}
D[11524] = {"Comportement erratique",{"Le redresseur de torts Xayann, de la Zone de rassemblement du Soleil brisé, vous demande de placer les Noyaux cristallins en phase à l’intérieur de 5 Factionnaires erratiques vaincus afin d’en faire des unités alliées."}}
D[11525] = {"Plus de conversions",{"Le redresseur de torts Xayann, de la Zone de rassemblement du Soleil brisé, vous demande de placer les Noyaux cristallins en phase à l’intérieur de 5 Factionnaires erratiques vaincus afin d’en faire des unités alliées."}}
D[11526] = {"La magistrice disparue",{"Servez-vous du Parchemin de la Légion capturé près du portail de la place du Point-du-jour. Lorsque vous aurez franchi le portail, trouvez la magistrice Seyla."}}
D[11528] = {"Un cadeau pour la fête du Voile d'hiver"}
D[11531] = {"Pièce de moteur étrange",{"Apportez la Pièce de moteur étrange à Manue Fretin à Telredor."}}
D[11532] = {"Diversion à la Malebrèche",{"La mage de bataille Arynna vous demande de parler à Ayren Brisenuée quand vous serez <prêt/prête> à survoler la Malebrèche. Une fois là-bas, utilisez les Charges arcaniques pour tuer 2 Suzerains des abîmes, 3 Ensorceleurs érédars et 12 Massacreurs de courroux."}}
D[11533] = {"Les frappes aériennes doivent continuer",{"La mage de bataille Arynna vous demande de parler à Ayren Brisenuée quand vous serez <prêt/prête> à survoler la Malebrèche. Une fois là-bas, utilisez les Charges arcaniques pour tuer 2 Suzerains des abîmes, 3 Ensorceleurs érédars et 12 Massacreurs de courroux."}}
D[11534] = {"Se présenter à Nasuun",{"Le Commerçant Portonuus veut que vous parliez à l'Exarque Nasuun, à la Terrasse de la Lumière de Shattrath."}}
D[11535] = {"Préparatifs",{"Le forgeron Hauthaa, de l’armurerie des Confins du soleil, veut que vous tuiez des Myrmidons Sombréchine, à l’est, et que vous utilisiez leurs clés pour dérober trois morceaux de minerai dans leurs coffres."}}
D[11536] = {"Ne vous arrêtez pas…",{"Le forgeron Hauthaa, de l’armurerie des Confins du soleil, veut que vous tuiez des Myrmidons Sombréchine, à l’est, et que vous utilisiez leurs clés pour dérober trois morceaux de minerai dans leurs coffres."}}
D[11537] = {"La bataille doit continuer",{"Le Messager Inuuro vous demande de tuer 6 Démons de la Légion ardente et l'Émissaire de haine sur la place du Point-du-jour. Utilisez la Bannière du Soleil brisé pour empaler le cadavre de l'Émissaire de haine."}}
D[11538] = {"La bataille pour l'Armurerie des Confins du soleil",{"Le Messager Inuuro vous demande de tuer 6 Démons de la Légion ardente et l'Emissaire de haine sur la place du Point-du-jour ou à l'armurerie des Confins du soleil. Utilisez la Bannière du Soleil brisé pour empaler le cadavre de l'Emissaire de haine."}}
D[11539] = {"Prendre le port",{"Le Magistère Ilastar, de l'Armurerie des Confins du soleil, vous demande de tuer 6 Invocateurs de la Lame de l'aube, 6 Chevaliers de sang de la Lame de l'aube et 3 Archers de la Lame de l'aube."}}
D[11540] = {"Écraser la Lame de l'aube",{"Le Magistère Ilastar, de l'Armurerie des Confins du soleil, vous demande de tuer 6 Invocateurs de la Lame de l'aube, 6 Chevaliers de sang de la Lame de l'aube et 3 Archers de la Lame de l'aube."}}
D[11541] = {"Déstabilisation de la Côte de Verte-branchie",{"Le capitaine Valindria vous demande de libérer 10 Esclaves verte-branchie. Retournez la voir au bord de la Fierté de Lune-d'argent au port des Confins du soleil quand ce sera fait."}}
D[11542] = {"Intercepter les renforts",{"Le redresseur de torts Kaalan, de l'Armurerie des Confins du soleil, vous demande de parler à Ayren Brisenuée et de survoler la flotte de renforts de la Lame de l'aube. Utilisez l'Huile enflammée pendant votre vol pour mettre le feu aux voiles des navires, et après avoir atterri, tuez 6 Réservistes de la Lame de l'aube."}}
D[11543] = {"Tenir l'ennemi à distance",{"Le Redresseur de torts Kaalan, de l'Armurerie des Confins du soleil, vous demande de parler à Ayren Brisenuée et de survoler la flotte de renforts de la Lame de l'aube. Utilisez l'Huile incendiaire pendant votre vol pour mettre le feu aux voiles des navires, et après avoir atterri, tuez 6 Réservistes de la Lame de l'aube."}}
D[11544] = {"Les armes d'Ata'mal",{"Le Forgeron Hauthaa vous demande de produire 5 morceaux de Métal ata'mal purifié. Pour ce faire, cassez des Armes d'Ata'mal sur son enclume à l'Armurerie des Confins du soleil sur l'île de Quel'Danas."}}
D[11545] = {"Un don charitable",{"L'Anchorète Ayuri, des Confins du Soleil sur l'Île du Puits de soleil, vous demande de faire un don de 10 pièces d'or."}}
D[11546] = {"On est ouvert",{"Mar'nah, du Port des Confins du soleil, vous demande de cueillir 5 Sangrelles sur les buissons de Quel'Danas."}}
D[11547] = {"Les lignes telluriques et vous",{"L'astromancien Darnarian du Sanctum des Confins du soleil vous demande d'utiliser le Cristal de l'astromancien sur le Cristal-sanglant, le portail de la place du Point-du-jour et le sanctuaire naga de la Côte de Verte-branchie."}}
D[11548] = {"Votre soutien indéfectible",{"L'Anachorète Ayuri aux Confins du Soleil dans l'Île du Puits de soleil veut que vous fassiez don de 10 pièces d'or."}}
D[11549] = {"Un bienfaiteur magnanime",{"L'Anachorète Kairthos vous demande de faire don de 1000 pièces d'or pour soutenir l'action de l'anachorète Ayuri. Vous serez <connu/connue> sous le nom |2 <nom> du Soleil brisé si vous accomplissez cette quête."}}
D[11550] = {"Le Trompeur entre en scène",{"Présentez-vous à l'Archimage Ne'thul sur l'Île de Quel'Danas, au nord de Quel'Thalas.","","Les maîtres de vol de Forgefer et de Lune-d’Argent peuvent vous y envoyer."}}
D[11554] = {"Un ami sur le front",{"Votre contribution à l'opération n'est pas passée inaperçue, <nom>. Les forces unies de l'Aldor et des Clairvoyants vous remercient."}}
D[11555] = {"Honoré par vos alliés",{"Vous continuez de faire vos preuves dans cette bataille de la plus haute importance, <nom>. Veuillez accepter ceci en gage de notre gratitude."}}
D[11556] = {"Révéré sur le champ de bataille",{"Nous ne serions jamais arrivés là où nous sommes sans votre aide, <nom>. Les forces combinées de l'Aldor et des Clairvoyants ne suffisent pas à écraser Kael et la Légion. Nous sommes heureux d'avoir des alliés de votre force."}}
D[11557] = {"Exalté parmi tous les combattants",{"Vous êtes parmi nos meilleurs atouts, <nom>. Votre nom résonnera parmi nos rangs pendant très longtemps.","","Je vous prie d'accepter ce cadeau de la part de nos troupes."}}
D[11558] = {"Les périls de l'amour",{"Obtenez une Carte de garde moisie et ramenez-là à Fenstad Argyle, à Fossoyeuse."}}
D[11577] = {"WoW Collector's Edition: - DEM - E - FLAG"}
D[11580] = {"Désacralisez ce feu !"}
D[11581] = {"Désacralisez ce feu !",{"Desecrate the Alliance's Westfall bonfire!"}}
