D[11875] = {"Prendre l'avantage",{"Apportez 8 Résidus de Néant à l’Émissaire Mordin, à Shattrath."}}
D[11877] = {"Les plans d'attaque solfurie",{"Le Seigneur Torvos, à Shattrath, veut que vous vous empariez des Plans d’attaque solfurie."}}
D[11880] = {"L’examen multiphase",{"Le Messager Haronem, à Shattrath, veut que vous utilisiez les Lunettes spectographiques multiphases pour prendre 6 Relevés multiphases."}}
D[11882] = {"Jouer avec le feu",{"Parlez à un Maître cracheur de feu dans n'importe quelle capitale de l'Alliance."}}
D[11883] = {"La danse de feu",{"Parlez à un Maître danseur de feu dans n'importe quelle capitale de la Horde."}}
D[11885] = {"Lignées antagonistes",{"Trouvez les Piles de crânes au milieu des cercles d'invocation de Skettis. Invoquez et vainquez chacun des descendants des adversaires de Terokk en utilisant 10 Parchemins perdus dans le temps à la Pile de crâne. Retournez ensuite auprès de Hazzik au Raie'odrome de Noirvent."}}
D[11886] = {"Une activité inhabituelle",{"Rendez-vous au nouveau Camp du Crépuscule, au sud de l'entrée des Profondeurs de Brassenoire sur la grève de Zoram, dans Orneval, et récupérez la Correspondance du crépuscule sur les sectateurs. Puis appelez le Guide du Cercle terrestre en utilisant la Balise totémique."}}
D[11891] = {"Un déguisement innocent",{"Servez-vous de l’Orbe du clampant pour espionner le nouveau Camp du Crépuscule, à l’ouest des Profondeurs de Brassenoire, sur la grève de Zoram, en Orneval. Ensuite, invoquez le Guide du Cercle terrestre à l'aide de la Balise totémique."}}
D[11915] = {"Jouer avec le feu",{"Parlez à un Maître avaleur de flammes dans n'importe quelle capitale de la Horde."}}
D[11917] = {"Contre-attaquer",{"Tuez le Lieutenant Vaguegivre invoqué par la Pierre de glace située sur la grève de Zoram, en Orneval, puis retournez voir un Ancien du Cercle terrestre dans l'une des capitales."}}
D[11921] = {"Lancer plus de torches",{"Gagnez le jeu de lancer de torches, puis parlez au Maître cracheur de feu."}}
D[11922] = {"Lancer des torches",{"Gagnez le jeu de lancer de torches, puis parlez au Maître avaleur de flammes."}}
D[11923] = {"Attraper des torches",{"Attrapez 4 torches de suite, puis parlez au Maître avaleur de flammes."}}
D[11924] = {"Attraper plus de torches",{"Attrapez 10 torches de suite, puis parlez au Maître cracheur de feu."}}
D[11925] = {"Attraper plus de torches",{"Attrapez 10 torches de suite, puis parlez au Maître avaleur de flammes."}}
D[11926] = {"Lancer plus de torches",{"Gagnez le jeu de lancer de torches, puis parlez au Maître avaleur de flammes."}}
D[11933] = {"Voler la flamme de l'Exodar",{"Rapportez la Flamme de l'Exodar au Conteur de la fête."}}
D[11935] = {"Voler la flamme de Lune-d'argent",{"Rapportez la Flamme de Lune-d'argent au Maître des traditions de la fête."}}
D[11937] = {"MARQUEUR - Toutes les quêtes des torches sont terminées"}
D[11947] = {"Contre-attaquer",{"Tuez le Lieutenant Grêlon invoqué par la Pierre de glace située à Ethel rethor en Désolace, puis retournez voir un Ancien du Cercle terrestre dans l'une des capitales."}}
D[11948] = {"Contre-attaquer",{"Tuez le Lieutenant Noroît invoqué par la Pierre de glace située sur l’île de l’élémentaire d’eau à l’ouest de la Vallée de Strangleronce, puis retournez voir un Ancien du Cercle terrestre dans l'une des capitales."}}
D[11952] = {"Contre-attaquer",{"Tuez le Lieutenant algide invoqué par la Pierre de glace située dans la caverne sous la Crête de Guet-du-feu, au nord-ouest de la Gorge des Vents brûlants, puis retournez voir un Ancien du Cercle terrestre dans l'une des capitales."}}
D[11953] = {"Contre-attaquer",{"Tuez le Lieutenant glaciaire invoqué par la Pierre de glace située dans le défilé du Crépuscule, au nord de Silithus, puis retournez voir un Ancien du Cercle terrestre dans l'une des capitales."}}
D[11954] = {"Contre-attaquer",{"Tuez le Templier glaciaire invoqué par la Pierre de glace située près de la Porte des ténèbres dans la Péninsule des flammes infernales, puis retournez voir un Ancien du Cercle terrestre dans l'une des capitales."}}
D[11955] = {"Ahune, le seigneur du Givre",{"Voyagez jusqu'à l'Enclos aux esclaves, dans le Réservoir de Glissecroc, au Marécage de Zangar, et parlez à Numa Sœur-des-nuages."}}
D[11964] = {"De l'encens pour les brûletins de l'été",{"Le maître des traditions de la fête vous demande d'apporter de l'Encens estival à un Brûletin d'été à l'extérieur de n'importe quelle ville de l'Alliance."}}
D[11966] = {"De l'encens pour les brûletins de la fête",{"Le conteur de la fête vous demande d'apporter de l'Encens estival à un Brûletin de la fête à l’extérieur de n’importe quelle ville de la Horde."}}
D[11970] = {"Le maître des traditions estivales",{"Parlez au Maître des traditions de la fête dans n'importe quelle capitale de l'Alliance."}}
D[11971] = {"Le conteur des légendes estivales",{"Parlez au Conteur de la fête dans n'importe quelle capitale de la Horde."}}
D[11972] = {"Éclats d'Ahune",{"Apportez les Eclats de glace à Luma Mère-des-cieux."}}
D[11975] = {"Et maintenant, quand je serai grande...",{"Conduisez votre orpheline, Salandria, à la promenade des Anciens de Lune-d'argent pour voir les Elite Tauren Chieftains. Si elle n'est pas présente lorsque vous serez sur place, n'oubliez pas de l'appeler."}}
D[11976] = {"Éclats de glace",{"Apportez les Eclats de glace à Luma Mère-des-cieux."}}
D[12012] = {"Informez l'Ancien",{"Voyagez jusqu'à une capitale et parlez à un Ancien du Cercle terrestre."}}
D[12020] = {"Et une fois, quand j'étais ivre…",{"Parlez à Boxey Tournécrou au campement de la fête des Brasseurs."}}
D[12022] = {"Buvez, éliminez !",{"Utilisez le Tastebière-cadeau pour toucher la C.E.R.V.O.I.S.E. 5 fois, puis revenez parler à Boxey Tournécrou."}}
D[12062] = {"Insulter Coren Navrebière",{"Parlez à Coren Navrebière."}}
D[12191] = {"Buvez, éliminez !",{"Utilisez le Tastebière sans alcool de la fête des Brasseurs pour toucher la C.E.R.V.O.I.S.E. à 5 reprises."}}
D[12193] = {"Dites, il n'y aurait pas un souvenir cette année ?",{"Échangez le bon-cadeau à Belbi Coupecircuit dans le campement de la fête des Brasseurs."}}
D[12194] = {"Dites, il n'y aurait pas un souvenir, cette année ?",{"Échangez le Bon pour un bock de la fête des Brasseurs à Blix Réparouage à l'arrière du campement de la fête des Brasseurs."}}
D[12278] = {"Le club de la Bière du mois",{"Apporter le bulletin d'adhésion du club de la « Bière du mois » à Larkin Tonnebière à la taverne de Brûlepierre à Forgefer."}}
D[12306] = {"Le club de la Bière du mois",{"Apporter le bulletin d'adhésion du club de la « Bière du mois » à Ray'ma au pavillon de Buissombre dans la vallée des Esprits d'Orgrimmar."}}
D[12318] = {"Sauvez la fête des Brasseurs !",{"Parlez avec l’Espion de la fête des Brasseurs, au Sinistre écluseur dans les Profondeurs de Rochenoire."}}
D[12491] = {"La navre-bière de Navrebière",{"Donnez la Navre-bière de Navrebière à Ipfelkofer Baril-de-fer au camp de la fête des Brasseurs près de Forgefer."}}
D[12492] = {"La navre-bière de Navrebière",{"Donnez la navre-bière de Navrebière à Perce Fauchebaril au camp de la fête des Brasseurs près d'Orgrimmar."}}
D[12513] = {"Un joli chapeau...",{"Donc Carlos vous a malencontreusement défié de vaincre son jeune alter ego de la Hautebrande d'antan. Lorsque ce sera fait, apportez le Chapeau de don Carlos à Don Carlos, à Tanaris, comme preuve de votre victoire."}}
D[12515] = {"Un joli chapeau...",{"Donc Carlos vous a malencontreusement défié de vaincre son jeune alter ego de la Hautebrande d'antan. Lorsque ce sera fait, apportez le Chapeau de don Carlos à Don Carlos, à Tanaris, comme preuve de votre victoire."}}
D[63866] = {"Revendiquer la Lumière",{"Utilisez le Calice chatoyant sur M’uru pour le remplir et retournez voir le chevalier-seigneur Vaillessang à Lune-d'argent."}}
D[64028] = {"Un nouveau départ",{"Trouvez un Maître pour <classe> à Hurlevent."}}
D[64031] = {"Les outils de la survie",{"Ouvrez le Kit de survie et équipez-vous d’une Arme."}}
D[64034] = {"Entraînement au combat",{"Parlez à un Maître pour <classe> pour vous entraîner à lancer un Sort."}}
D[64035] = {"Quel talent !",{"Activez l’interface des Talents et dépensez 5 Points de talent."}}
D[64037] = {"Maleterres de l’est",{"Rendez-vous dans les Maleterres de l’Est et trouvez Leonid Barthalomew. Il vous attend à la Chapelle de l’Espoir de Lumière."}}
D[64038] = {"La Porte des ténèbres",{"Trouvez le Commandant de la garde Vroncier Déclin-du-Néant dans les Terres Foudroyées. Il attend votre arrivée devant la Porte des ténèbres."}}
D[64046] = {"Un nouveau départ",{"Allez voir un Maître pour <classe> à Orgrimmar."}}
D[64047] = {"Un nouveau départ",{"Allez voir un Maître pour <classe> aux Pitons-du-Tonnerre."}}
