D[64063] = {"La Porte des ténèbres",{"Trouvez le Seigneur de guerre Dar’toon dans les terres Foudroyées. Il attend votre arrivée près de la Porte des ténèbres."}}
D[64064] = {"Maleterres de l’Est",{"Rendez-vous dans les Maleterres de l’Est et trouvez Leonid Barthalomew. Il vous attend à la Chapelle de l’Espoir de Lumière."}}
D[64319] = {"Une étude du pouvoir",{"Parlez au magistère Astalor Ligessang dans la chambre secrète sous les quartiers généraux des chevaliers de sang."}}
D[65593] = {"Les cœurs des amoureux",{"Apportez les Cœurs d’Avelina Lilly et d’Isaac Pearson à Carendin Halgar dans le Temple des Damnés."}}
D[65597] = {"Le lien",{"Utilisez les Coeurs des amoureux pour invoquer et soumettre un incube, puis rapportez les Coeurs des amoureux à Carendin Halgar, dans le Quartier de la magie à Fossoyeuse."}}
D[65601] = {"Les affres de l’amour",{"Parlez à Magar, à Orgrimmar."}}
D[65602] = {"Qu’est-ce que l’amour ?",{"Récupérez la Figurine en bois et rapportez-la à Gakin le Tisse-noir, au Quartier des mages de Hurlevent."}}
D[65603] = {"Le lien",{"Utilisez la Figurine en bois pour invoquer et asservir un incube, puis rapportez l’objet à Gakin le Tisse-noir à l’Agneau assassiné."}}
D[65604] = {"Le lien",{"Utilisez l’Écharpe flétrie pour invoquer et asservir un Incube, puis rapportez-la à Gan’rul Œil-sanglant, à Orgrimmar."}}
D[65610] = {"Comme tu me manques",{"Explorez le Lac Tombeciel en Orneval et rendez compte de vos découvertes à Gan’rul Œil-sanglant, à Orgrimmar."}}
