(function() local D = SUIQuestScopeData.L10n.ruRU.Quest
D[1] = {"Alexander's Quest",{"Find the forgotten location and cast the magical spell."}}
D[2] = {"Коготь гиппогрифа Острокогтя",{"Принесите коготь гиппогрифа Острокогтя Сенани Громовое Сердце на заставу Расщепленного Дерева в Ясеневом лесу."}}
D[5] = {"Урчащий живот Трясунчика",{"Поговорите с шеф-поваром Груалем."}}
D[6] = {"Награда за голову Гаррика Тихокрада",{"Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья."}}
D[7] = {"Нападение на лагерь кобольдов",{"Уничтожьте 10 кобольдов-вредителей. Вернитесь к маршалу Макбрайду."}}
D[8] = {"Выгодная сделка",{"Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах."}}
D[9] = {"Поля смерти",{"Убейте 20 дозорных полей по просьбе фермера Сальдена."}}
D[10] = {"Спасение Холстомера",{"Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск."}}
D[11] = {"Награда за гноллов из стаи Речной Лапы",{"Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру."}}
D[12] = {"Народное ополчение",{"Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву."}}
D[13] = {"Народное ополчение",{"Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм."}}
D[14] = {"Народное ополчение",{"Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой холм."}}
D[15] = {"Разведка в руднике Горного эха",{"Уничтожьте 10 кобольдов-рабочих и вернитесь к маршалу Макбрайду."}}
D[16] = {"Жажда Джерарда",{"Работа фермера тяжела, от нее здорово пересыхает в глотке.","","Если ты дашь мне родниковой воды, могу предложить кое-что взамен."}}
D[17] = {"В Ульдаман за реактивом",{"Принесите 12 грибов-малиновиков Гхаку Целителю в Телcамар."}}
D[18] = {"Братство воров",{"Принесите 12 красных холщовых бандан заместителю судьи Виллему к Аббатству Североземья."}}
D[19] = {"Тарил'зун",{"Принесите маршалу Маррису в Красногорье голову Тарил'зуна."}}
D[20] = {"Угроза Черной горы",{"Принесите маршалу Маррису в Приозерье 10 иззубренных топоров."}}
D[21] = {"Схватка у рудника Горного эха",{"Уничтожьте 12 кобольдов-работников и вернитесь к маршалу Макбрайду."}}
D[22] = {"Рецепт пирожка из печени жутеклыка",{"Принесите Сальме Сальден 8 кусков печени жутеклыка, чтобы она могла испечь пирог."}}
D[23] = {"Лапа Топтыжня",{"Принесите лапу Топтыжня Сенани Громовое Сердце на заставу Расщепленного Дерева в Ясеневом лесу."}}
D[24] = {"Голова Тенумбры",{"Принесите голову Тенумбры Сенани Громовое Сердце на заставу Расщепленного Дерева в Ясеневом лесу."}}
D[25] = {"Остановка у Каменного Когтя",{"Истребите 12 злобных элементалей воды на озере Мистраль, что к востоку от Туннеля Когтя и к юго-западу от заставы Расщепленного Дерева.","","Исследуйте беседку на озере Мистраль, из которой открывается вид на соседний форт Альянса.","","Вернитесь к Мастоку Райльшипу на заставу Расщепленного Дерева в Ясеневом лесу."}}
D[26] = {"Необходимый урок",{"Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне."}}
D[27] = {"Необходимый урок",{"Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне."}}
D[28] = {"Испытание озера",{"Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.","","Потом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание."}}
D[29] = {"Испытание озера",{"Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.","","Потом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание."}}
D[30] = {"Испытание Морского Льва",{"Найдите половинку подвески ловкости водяного облика и половинку подвески выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.","","Сложите из половинок подвеску морского льва. Для этого вам надо находиться рядом со святилищем Ремула.","","Отнесите собранную подвеску Дендриту Блеску Звезд в деревню Ночная Гавань, что на Лунной поляне."}}
D[31] = {"Водный облик",{"Возвращайтесь в Громовой Утес и покажите Тюраку Руническому Тотему подвеску Морского Льва."}}
D[32] = {"Появление силитидов",{"Отнесите отчет Зилзибину Барабанному Бою в Оргриммар."}}
D[33] = {"Волки на границе",{"Принесите 8 кусков жесткой волчатины Игану Меховщику к Аббатству Североземья."}}
D[34] = {"Незваный гость",{"Убейте Грубобрюха. Принесите Марти Джанроз клык вепря."}}
D[35] = {"Новые заботы",{"Поговорите со стражником Томасом."}}
D[36] = {"Похлебка Западного края",{"Отнесите Сальме Сальден рецепт похлебки Западного края."}}
D[37] = {"Пропавшие стражи",{"Отправляйтесь на север по реке и отыщите следы пропавших стражников – Рольфа и Малакаи."}}
D[38] = {"Похлебка Западного края",{"Принесите Сальме Сальден 3 куска жилистого мяса стервятника, 3 рыла жутеклыка, 3 глаза мурлока и 3 окры."}}
D[39] = {"Донесение Томаса",{"Доставьте донесение в Златоземье маршалу Дугхану."}}
D[40] = {"Водяная нечисть",{"Реми Повторюх просит вас найти в Златоземье маршала Дугхана и поговорить с ним."}}
D[45] = {"Судьба Рольфа",{"Обыщите поселение мурлоков и найдите Рольфа – или подтверждение его смерти."}}
D[46] = {"Награда за мурлоков",{"Принесите 8 плавников мурлоков к восточному мосту Элвиннского леса и отдайте их стражнику Томасу."}}
D[47] = {"Золотая пыль",{"Принесите 10 порций Золотой пыли в Златоземье Реми Повторюху. Золотую пыль можно добыть у кобольдов в Элвиннском лесу."}}
D[48] = {"Янтарное сладкое",{"Принесите Мрачнобуху Громовару воду святого источника."}}
D[49] = {"Янтарное сладкое",{"Принесите Мрачнобуху Громовару мешок ячменя, мешок ржи и мешок кукурузы."}}
D[50] = {"Янтарное сладкое",{"Принесите Мрачнобуху Громовару истинное серебро."}}
D[51] = {"Янтарное сладкое",{"Принесите Мрачнобуху Громовару ветку смоковницы."}}
D[52] = {"Защита границы",{"Убейте 8 лесных хищников и 5 молодых лесных медведей. Затем вернитесь к стражнику Томасу у восточного моста Элвиннского леса."}}
D[53] = {"Янтарное сладкое",{"Принесите Мрачнобуху Громовару вязанку обуглившихся дубовых поленьев."}}
D[54] = {"Донесение в Златоземье",{"Отнесите документы маршала Макбрайда маршалу Дугхану в Златоземье."}}
D[55] = {"Морбент Скверн",{"Примените Проклятье Морбента против Морбента Скверна, убейте его и верните Проклятье Морбента в лагерь Свена."}}
D[56] = {"Ночной дозор",{"Убейте 8 скелетов-воинов и 6 магов-скелетов по просьбе командира Алтеи Чернодрев."}}
D[57] = {"Ночной дозор",{"Убейте 15 скелетов-губителей и 15 ужасных скелетов по просьбе командира Алтеи Чернодрев."}}
D[58] = {"Ночной дозор",{"Убейте 20 распространителей чумы в восточном мавзолее Вороньего холма по просьбе командира Алтеи Чернодрев."}}
D[59] = {"Броня из кожи и ткани",{"Отдайте Саре Тимберлейн знак брони Штормграда."}}
D[60] = {"Свечи кобольдов",{"Принесите 8 больших свечей в Златоземье Вильяму Песту."}}
