D[956] = {"Башал'Аран",{"Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал'Аран."}}
D[957] = {"Башал'Аран",{"Уничтожьте древнюю печать из лунного камня у древнего огня в Амет'Аране, затем вернитесь к Астериону в Башал'Аран."}}
D[958] = {"Инструменты высокорожденных",{"Добудьте 7 реликвий высокорожденных для Тандриса Ветропряда в Аубердине."}}
