D[963] = {"Во имя вечной любви",{"Освободите дух Анайи Вестницы Рассвета и принесите ее подвеску Кириллиану Белому Когтю в Аубердин."}}
D[964] = {"Фрагменты скелетов",{"Принесите 15 фрагментов скелетов аптекарю Дитерсу в Бастион в Западных Чумных землях."}}
