D[1657] = {"Чем пахнет в Южнобережье",{"Бросьте три бомбы-вонючки Отрекшихся в центр Южнобережья в Хилсбраде и вернитесь к призывательнице тьмы Янке на фестиваль Плетеного человека в Тирисфальских лесах."}}
D[1658] = {"Сорвать праздник Плетеного человека",{"Отыщите место проведения фестиваля Плетеного человека в Тирисфальских лугах и возвращайтесь в Южнобережье к сержанту Хартману."}}
D[1661] = {"Фолиант Благородства",{"Поговорите с Даторианом Раллом в Штормграде."}}
D[1665] = {"Кружка Бартлби",{"Отнесите кружку Бартлби Берлгарду."}}
D[1666] = {"Маршал Хаггард",{"Поговорите с маршалом Хаггардом."}}
D[1667] = {"Джек Мертвозуб",{"Добыть знак маршала Хаггарда из лагеря Джека Мертвозуба и вернуться к маршалу Хаггарду."}}
D[1678] = {"Веджрек",{"Принесите голову Веджрека Марену Грозовой Вершине в Стальгорн."}}
D[1679] = {"Марен Грозовая Вершина",{"Поговорите с Мареном Грозовой Вершиной."}}
D[1680] = {"Тормус Подземная Кузня",{"Поговорите с Тормусом Подземной Кузней."}}
D[1681] = {"Мастерская Сталекрута",{"Принесите мрачную руду Тормусу Подземной Кузне в Стальгорн."}}
D[1682] = {"Оружие из серой стали",{"Вот тебе оружие, только что с наковальни. На него пошла добытая тобой мрачная руда!","","Что же, Хрофтгор, выбирай!"}}
D[1683] = {"Ворлус Подлое Копыто",{"Принесите рог Ворлуса Эланарии из Дарнасса."}}
D[1684] = {"Эланария",{"Поговорите с Эланарией."}}
D[1685] = {"Приглашение Гакина",{"Обратитесь к Гакину Темнопряду в квартал магов Штормграда."}}
D[1686] = {"Тень Элуры",{"Принесите 8 партий элунитовой руды и медальон Элуры Эланарии из Дарнасса."}}
D[1687] = {"Маяк с привидениями",{"Отведите сироту к маяку на побережье Западного Края."}}
D[1688] = {"Сурена Каледон",{"Верните колье Кровавого камня Гакину Темной Вязи в Штормград."}}
D[1689] = {"Связывание",{"С помощью колье кровавого камня призовите и подчините демона Бездны, затем верните колье кровавого камня Гакину Темнопряду."}}
D[1690] = {"Расправа над Скитальцами Пустыни",{"Убейте 10 бандитов и 10 воров из шайки Скитальцев Пустыни на востоке от Прибамбасска и возвращайтесь к главному инженеру Чепухастеру."}}
D[1691] = {"Еще одна расправа над Скитальцами Пустыни",{"Убейте 10 темных магов, 8 разбойников и 6 убийц из шайки Скитальцев Пустыни по поручению главного инженера Чепухастера из Прибамбасска."}}
D[1692] = {"Кузнец Матиль",{"Отнесите сундук элунита кузнецу Матилю."}}
D[1693] = {"Оружие из элунита",{"Это оружие я выковал из принесенного тобой элунита. Можешь взять себе любое.","","Большое спасибо. Работать с элунитом – не только удовольствие, но и великая честь."}}
D[1698] = {"Йорус Ячменовар",{"Поговорите с Йорусом Ячменоваром."}}
D[1699] = {"Ретбанский вызов",{"Войдите в пещеры Ретбана, доберитесь до первой развилки и вернитесь к Йорусу Ячменовару за отведенное время.","","Вы не должны умирать и освобождать свой дух."}}
D[1700] = {"Гриманд Элмор",{"Отнесите записки Фьюрена Гриманду Элмору."}}
D[1701] = {"Закаленный доспех",{"Соберите все необходимые материалы для Фьюрена Длинноборода и отнесите их в Штормград."}}
D[1702] = {"Щитник",{"Отнесите бочонок жгучего пива Фьюрену Длиннобороду."}}
D[1703] = {"Матиль",{"Отнесите Матилю записки Фьюрена."}}
D[1704] = {"Клацморт Гайкокрут",{"Отнесите записки Фьюрена Клацморту Гайкокруту."}}
D[1705] = {"Пылающая кровь",{"Принесите 20 сосудов горящей крови и 1 горящий камень Гриманду Элмору из Штормграда."}}
D[1706] = {"Доспехи Гриманда",{"Глазам своим не верю! Технология Фьюрена оказалась удачной, и этот доспех способен выдержать серьезную нагрузку.","","Держи, Ишт. И огромное тебе спасибо. Если бы ты не принес мне все необходимые материалы, я бы так и не поверил в открытие Фьюрина."}}
D[1707] = {"Награда за воду",{"Принесите 5 бурдюков Скитальцев Пустыни оператору крана Тормозиллеру в Прибамбасск."}}
D[1708] = {"Железный коралл",{"Принесите 20 партий выжженного коралла Клацморту Гайкокруту в Стальгорн."}}
D[1709] = {"Творение Клацморта",{"Вот твои доспехи, Бронетазик. Идея Фьюрена отлично сработала. Идеально! Чудесно, если правду сказать!","","По этой броне можно осадные орудия прокатить, и она сохранит форму!"}}
D[1710] = {"Высохшая скорлупа",{"Принесите 20 кусков высохшей на солнце скорлупы Матилю из Дарнасса."}}
D[1711] = {"Доспехи Матиля"}
D[1712] = {"Циклониан",{"Принесите Бат'ра Ветростражу все предметы из его списка."}}
D[1713] = {"Призыв",{"Отнести сердце Вихря Бат-ра Ветростражу."}}
D[1714] = {"Субстанция Изгнанников",{"Котел бурлит, и его пары так и манят..."}}
D[1715] = {"Таверна \"Забитый ягненок\"",{"Обратитесь к Гакину Темнопряду в квартал магов Штормграда."}}
D[1716] = {"Пожирательница душ",{"Поговорите с Такаром Провидцем в Степях."}}
D[1717] = {"Приглашение Гакина",{"Обратитесь к Гакину Темнопряду в квартал магов Штормграда."}}
D[1718] = {"Островитянин",{"Поговорите с Кланноком Маклеодом."}}
D[1719] = {"Побоище",{"Убейте Большого Билла и поговорите с Кланноком Маклеодом на Острове Битв."}}
D[1738] = {"Сердцедрево",{"Раздобудьте в Ясеневом лесу сердцедрево и принесите его Гакину Темнопряду в Квартал магов Штормграда."}}
D[1739] = {"Связывание",{"Призовите и подчините суккуба, используя сердцевину сердцедрева, затем верните сердцевину сердцедрева Гакину Темнопряду. Он будет ждать вас в \"Забитом ягненке\"."}}
D[1740] = {"Шар Соран'рука",{"Соберите 3 фрагмента Соран'рука и 1 большой фрагмент Соран'рука и принесите их Доану Кархану в Степи."}}
D[1758] = {"Фолиант Заговора",{"Поговорите с Кромом Крепкоруком в Стальгорне."}}
D[1778] = {"Фолиант Божественности",{"Поговорите с Тизой Кузнебой в Стальгорне."}}
D[1779] = {"Фолиант Божественности",{"Возьмите знак жизни и поговорите с Майридоном Кузнебоем в Стальгорне."}}
D[1780] = {"Фолиант Божественности",{"Поговорите с Даторианом Раллом в Штормграде."}}
D[1781] = {"Фолиант Божественности",{"Отнесите знак Жизни Газину Тенорму в Штормград."}}
D[1782] = {"Доспехи Фьюрена",{"Вот твои доспехи, Ишт. Они выдержат любой удар, не будь я Фьюрен Длиннобород!","","И спасибо большое. Я многому научился, работая с принесенными тобой материалами. Думаю, в один прекрасный день я совершу новое открытие!","","А результаты этого я отправлю другим кузнецам Альянса.","","Я скажу им, что ты мне очень помог, может быть, они тоже решат отблагодарить тебя."}}
D[1783] = {"Фолиант Божественности",{"Возьмите знак Жизни и воскресите Нарма Фолка в Дун Мороге."}}
D[1784] = {"Фолиант Божественности",{"Добудьте приказ клана Черного Железа у дворфов из клана Черного Железа возле Хельмова Ложа и вернитесь к Майридону Кузнебою в Стальгорн."}}
D[1785] = {"Фолиант Божественности",{"Поговорите с Тизой Кузнебой в Стальгорне."}}
D[1786] = {"Фолиант Божественности",{"Возьмите знак Жизни, пойдите в Элвиннский лес и воскресите Хенза Фолка."}}
D[1787] = {"Фолиант Божественности",{"Найдите волшебников из Братства Справедливости в Элвиннском лесу, заберите у них бумаги и отнесите их Газину Тенорму в Штормград."}}
D[1788] = {"Фолиант Божественности",{"Поговорите с Даторианом Раллом в Штормграде."}}
D[1789] = {"Знак Жизни"}
D[1790] = {"Знак Жизни",{"Поспеши, Болвар! Слишком много жизней зависит от твоего успеха или неудачи.","","Если ты не сумеешь помочь Газину и Хензу, возвращайся: я дам тебе новый знак Жизни.","","Не думай, что я помогаю тебе просто так, нет: тебе, как и всякому другому паладину, нужно доказать, что ты достоин своего звания. Постоянные неудачи – не лучшая рекомендация..."}}
D[1791] = {"Ветростраж",{"Поговорите с Бат'ра Ветростражем."}}
D[1792] = {"Оружие Смерча",{"У меня есть сердце Вихря, и я могу подобрать ему вместилище по твоему выбору.","","Возьми любое оружие, и знай, что его сила – сила Циклониана."}}
D[1793] = {"Фолиант Доблести",{"Теперь доказано, что ты – приверженец сил Света, Палинус, но времена наступают все более опасные, и поэтому важно знать, какая сила скрывается в твоем сердце. Когда демоны, драконы или какое другое зло ступят на нашу землю, тогда и подвергнется испытанию твой дух. Достанет ли у тебя сил?","","Храбрость в любой ситуации – такая же неотъемлемая часть сущности паладина, как Свет, доспех и оружие. Необходимость защищать слабых и не терять веры – вот еще два урока, которые ты должен усвоить, пока проходишь обучение в Соборе Света."}}
D[1794] = {"Фолиант Доблести",{"Что же, теперь нет сомнений, что благодать Света пребывает с тобой, Отхилюотпорю, но чем опаснее времена, тем важнее знать, какую силу скрывает плоть. Когда на твои земли ступят демоны, драконы или иное зло, твоя доблесть подвергнется испытанию. Достанет ли тебе сил?","","Не бывает паладина без отваги в любой ситуации, как не бывает паладина без Света, доспеха и оружия. Защищай слабых, не теряй веры – вот два урока, которые тебе следует усвоить во время обучения в Соборе Света."}}
D[1795] = {"Связывание",{"Призовите и одолейте охотника скверны при помощи фолианта Заговора и верните фолиант Страхаду Фарсану из Кабестана."}}
D[1796] = {"Материалы для зачарованной золотой кроводежды",{"Принесите одеяния Аркана Менаре Расщепительнице Бездны в Степи."}}
D[1798] = {"На поиски Страхада",{"Поговорите со Страхадом Фарсаном в Степях."}}
D[1799] = {"Части шара Орахила",{"Поговорите с послушниками Менары в башне над Кабестаном и изберите свой путь.","","После этого принесите Табете в Пыльную трясину сферу Подземного огня."}}
D[1800] = {"Тронный зал Лордерона",{"Отведите своего подопечного в старый тронный зал Лордерона, который находится как раз у входа в Подгород."}}
D[1801] = {"Фолиант Заговора",{"Поговорите с Джорахом Аннисоном в Подгороде."}}
D[1802] = {"Фолиант Заговора",{"Добудьте заплесневелый фолиант и потрепанный манускрипт для Крома Крепкорука из Стальгорна."}}
D[1803] = {"Фолиант Заговора",{"Отыщите заплесневелый фолиант и потрепанный манускрипт для Йораха Аннисона из Подгорода."}}
D[1804] = {"Фолиант Заговора",{"Принесите восстановленный фолиант и три жезла направления Страхаду Фарсану в Кабестан."}}
D[1805] = {"Фолиант Заговора",{"Принесите восстановленный фолиант и три жезла направления Страхаду Фарсану в Кабестан."}}
D[1806] = {"Испытание доблести",{"Подождите, пока Джордан Стилвелл не закончит изготовление оружия."}}
D[1818] = {"Разговор с Диллинджером",{"Поговорите со стражем смерти Диллинджером в Брилле."}}
D[1819] = {"Улаг Колун",{"Убейте Улага Колуна и поговорите со стражем смерти Диллинджером."}}
D[1820] = {"Разговор с Колманом",{"Поговорите с Колманом Фартингом."}}
D[1821] = {"Наследие Агамондов",{"Принесите Колману Фартингу фамильный топор Агамондов, фамильный меч Агамондов, фамильную палицу Агамондов, фамильный кинжал Агамондов."}}
D[1822] = {"Фамильное оружие",{"Я оставлю принесенное тобой оружие на память о понесенных потерях. Впрочем, ты можешь выбрать наиболее полюбившуюся тебе вещь и оставить ее себе.","","Да послужит она тебе лучше, чем прежним проклятым владельцами."}}
D[1823] = {"Разговор с Ругой",{"Поговорите с Ругой Тотемом Ярости."}}
D[1824] = {"Испытание на Полях Великанов",{"Принесите 5 дергающихся усиков Руге Тотему Ярости в Лагерь Таурахо."}}
D[1825] = {"Разговор с Тун'гримом",{"Поговорите с Тун'гримом Огневзором из Степей."}}
D[1838] = {"Доспехи Жестокости",{"Принесите Тун'гриму Огневзору 15 закопченных железных слитков, 10 мер толченого азурита, 10 железных слитков и сосуд флогистона."}}
D[1839] = {"Ула'елек и рукавицы Жестокости",{"Поговорите с Ула'елеком из Дуротара."}}
D[1840] = {"Орм Каменное Копыто и шлем Жестокости",{"Обратитесь к Орму Каменному Копыту из Громового Утеса."}}
D[1841] = {"Велора Нители и Набедренники Жестокости",{"Поговорите с Велорой Нители из Подгорода."}}
D[1842] = {"Копыта сатиров",{"Принесите 7 целых копыт сатиров Ула'елеку в Дуротар, в деревню Сен'джин."}}
D[1843] = {"Рукавицы Жестокости",{"Спасибо, Коммибро. Эти рукавицы – мое величайшее достижение. Возьми их. Ты окажешь мне честь, если пойдешь в них в бой."}}
D[1844] = {"Рог химеры",{"Принести Орму Каменному Копыту из Громового Утеса гальванизированный рог."}}
D[1845] = {"Шлем Жестокости",{"Возьми этот шлем.","","Тебя привели ко мне великие свершения, и если Матери-земле будет угодно... тебе предстоит немало подвигов."}}
D[1846] = {"Берцовые кости",{"Принесите 8 крепких берцовых костей Драконьей Пасти Велоре Нители в Подгород."}}
D[1847] = {"Набедренники Жестокости",{"Вот твои набедренники, Большойзмей. Ну как, подходят? Или надо что-то менять? Мне хочется угодить заказчику! По крайней мере всегда хотелось.","","Теперь ремесло утратило прежнюю прелесть. Но все лучше, чем быть безмозглым рабом Плети!","","Наверное."}}
D[1848] = {"Хауберк Жестокости",{"Тебе несомненно пришлось пролить немало крови, чтобы справиться с моим заданием, Коммибро. Вот плод твоих трудов.","","Носи с удовольствием. Как-нибудь заходи, расскажешь, как он тебе пригодился в бою."}}
D[1858] = {"Изувеченная Длань",{"Украдите ключ Тазана, откройте сумку Тазана и отнесите содержимое сумки Терзоку в расселину Теней в Оргриммаре."}}
D[1859] = {"Терзок",{"Поговорите с Терзоком в расселине Теней в Оргриммаре."}}
D[1860] = {"Поговорите с Джиннией",{"Поговорите с Джиннией Пушкой в Штормграде."}}
D[1861] = {"Зеркальное озеро",{"Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда."}}
D[1878] = {"Награда за воду",{"Опять ты здесь? Если ты несешь еще пять бурдюков с водой Скитальцев Пустыни, то тебя ждет еще один именной полевой набор!"}}
D[1879] = {"Поговорите с Бинк",{"Поговорите с Бинк из Стальгорна."}}
D[1880] = {"Маг-тастический гизмонитор",{"Верните Бинк маг-тастический гизмонитор."}}
D[1881] = {"Разговор с Анастасией",{"Поговорите с Анастасией Хартвелл."}}
D[1882] = {"Ферма Балнира",{"Принесите львиный зев Бальнира Анастасии Хартвелл в Магический Квартал Подгорода."}}
D[1883] = {"Разговор с Ун'Тувой",{"Поговорите с Ун'Тувой."}}
D[1884] = {"Груды джуджу",{"Уничтожьте 4 груды джуджу и вернитесь к Ун'Туве из деревни Сен'джин."}}
D[1885] = {"Меннит Каркад",{"Поговорите с Меннитом Каркадом в Квартале Разбойников Подгорода."}}
D[1886] = {"Стражи смерти",{"Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода."}}
D[1898] = {"Стражи смерти",{"Поговорите с Андроном Гантом в Подгороде."}}
D[1899] = {"Стражи смерти",{"Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода."}}
D[1918] = {"Оскверненная стихия",{"Отнесите оскверненную водяную сферу Мастоку Райльшипу на заставу Расщепленного Дерева в Ясеневый лес."}}
D[1919] = {"Задание Джиннии",{"Поговорите с Джиннией Пушкой в Штормграде."}}
D[1920] = {"Синий Отшельник",{"Возьмите свиток заклятия Проявления и ящик с шкатулками-духоловками за спиной у Джиннии Пушки. Принесите 3 заполненных шкатулки-духоловки Джиннии в Башню магов."}}
D[1921] = {"Сбор материалов",{"Отнесите 10 кусков льна и 6 заряженных самоцветов Расселины Уинн Ларсон в Штормград."}}
D[1938] = {"Трактат Ура по темной магии",{"Принесите Трактат Ура по темной магии верховному колдуну Андромату из Штормграда."}}
D[1939] = {"Верховный колдун Андромат",{"Поговорите с верховным колдуном Андроматом."}}
D[1940] = {"Безупречная паутина",{"Принесите 8 кусков безупречной паутины Уинн Ларсон в Штормград."}}
D[1941] = {"Одеяние из ткани маны",{"Вот твое одеяние. Один из моих шедевров! Носи на здоровье, а если тебя спросят, кто шил... Посоветуй им обратиться в суконную лавку Ларсона!"}}
D[1942] = {"Одеяние волшебного плетения",{"Твое одеяние готово! Отличный шелк тебе достался... Ты уж прости, одеяние получилось довольно короткое, часть шелка я себе оставила.","","Шучу, шучу. Оно тебе идеально подойдет, причем будет уместно смотреться как в бою, так и на торжественном обеде. Наслаждайся!"}}
D[1943] = {"Разговор с Дейно",{"Поговорите с Дейно."}}
D[1944] = {"Воды Ксавиана",{"Принесите пробу воды из Ксавиана Дейно в Оргриммар."}}
D[1945] = {"Смеющиеся сестры",{"Принесите 12 волос Смеющихся сестер Кил'хале с Перекрестка."}}
D[1946] = {"Одеяние из кружева Пустоты",{"Вот твое пустокружево. Оно прочное и удобное и хранит в себе магию волос Смеющейся сестрички.","","Наслаждайся. Если понравится, не забудь упомянуть об этом в разговоре с Дейно. Вот уж с кем бы не хотелось ссориться..."}}
D[1947] = {"Путь в болото",{"Поговорите с Табетой."}}
D[1948] = {"Волшебные предметы",{"Принесите 1 нефрит и шипастый жезл Молний Табете в Пыльную трясину."}}
D[1949] = {"Великие тайны",{"Поговорите с волхвом Тиртом на Мерцающей равнине."}}
D[1950] = {"Волшебное слово",{"Узнайте волшебные слова, отпирающие сейф Тирта и вернитесь к Тирту."}}
D[1951] = {"Обряды силы",{"Принесите книгу \"Обряды силы\" Табете в Пыльную трясину."}}
D[1952] = {"Магический жезл",{"Поговорите с Табетой по завершении ритуала."}}
D[1953] = {"Назад в болото",{"Поговорите с Табетой."}}
D[1954] = {"Сфера Подземного огня",{"Принесите сферу Подземного огня Табете из Пылевых топей."}}
D[1955] = {"Поединок с демоном",{"Убейте демона сферы, а потом поговорите с Табетой."}}
D[1956] = {"Сила Ульдамана",{"Добудьте обсидиановый источник силы и принесите его Табете в Пыльную трясину."}}
D[1957] = {"Волнолов маны",{"Убейте 12 волноловов маны за отведенное время."}}
D[1958] = {"Небесная сила"}
D[1959] = {"Задание Анастасии",{"Поговорите с Анастасией Хартвелл."}}
D[1960] = {"Лавка алхимика",{"Возьмите свиток заклятия Проявления и ящик с шкатулками-духоловками за спиной у Анастасии Хартвелл. Принесите 3 заполненных шкатулки-духоловки, ящик со шкатулками духоловками и заклинание Проявления Анастасии в Подгород."}}
D[1961] = {"Сбор материалов",{"Принесите 10 кусков льна и 6 даларанских самоцветов маны Джозефу Грегориану."}}
D[1962] = {"Одеяние из чароткани",{"Вот твое новое одеяние, Тузвколоде. Носи на здоровье."}}
D[1963] = {"Изувеченная Длань",{"Убейте Тазана и принесите его сумку Терзоку в расселину Теней в Оргриммаре."}}
D[1978] = {"Стражи смерти",{"Отнесите гроссбух Андрона Вариматрасу в Зал Темной Госпожи в Подгороде."}}
D[1998] = {"Фенвик Татрос",{"Убейте Фенвика Татроса и принесите его голову Менниту Каркаду в Квартал Разбойников Подгорода."}}
D[1999] = {"Предметы торговли",{"Отыщите отчет о состоянии Даларана и отдайте его Менниту Каркаду в Квартале Разбойников Подгорода."}}
D[2000] = {"Рокар Тень Клинка",{"Поговорите с Рокаром Тенью Клинка в Дуротаре."}}
D[2018] = {"Испытание Рокара",{"Убейте надзирателя Глибби и отдайте его свисток Рокару Тени Клинка в Дуротаре."}}
D[2019] = {"Профессиональные инструменты",{"Вернитесь к Терзоку в Расселину Теней в Оргриммаре."}}
D[2038] = {"Пропавшее снаряжение Бинглза",{"Найдите и верните Бинглзу гаечный ключ Бинглза, отвертку Бинглза, молот Бинглза и сорвиголовку Бинглза."}}
D[2039] = {"Найти Бинглза",{"Найдите Бинглза Покрышкинса в Лок Модане."}}
D[2040] = {"Битва под землей",{"Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей."}}
D[2041] = {"Разговор с Шони",{"Поговорите с Шони Молшуньей в Штормграде."}}
D[2078] = {"Месть Гиромачта",{"Найдите первого помощника Гелхака, Бешенатора 4100, и отведите его к Гелхаку."}}
D[2098] = {"Помощь Гиромачту",{"Отыщите три фрагмента ключа и отнесите их Гелхаку Гиромачту."}}
D[2118] = {"Зачумленные земли",{"Поймайте бешеного колючешерстного медведя отведите его Тарнариуну.","","Если вам не удастся поймать зверя и вы потеряете ловушку, вернитесь к Тарнариуну Целителю Деревьев и попросите у него еще одну."}}
D[2138] = {"Избавление от заразы",{"Очистите лес от 20 бешеных колючешерстных медведей и возвращайтесь к Тарнариуну Исцелителю Деревьев на Темный Берег."}}
D[2139] = {"Надежда Тарнариуна",{"Найдите и убейте мать-медведицу."}}
D[2158] = {"Отдых и покой",{"Побеседуйте с Фарли, хозяином \"Гордости льва\"."}}
D[2159] = {"Посылка в Доланаар",{"Отнесите посылку хозяину таверны Кельдамиру в Доланааре."}}
D[2160] = {"Припасы для Таннока",{"Отнесите ящик с припасами хозяину таверны Танноку Молоту Стужи в Караносе."}}
D[2161] = {"Ноша батрака",{"Отнесите сумку Укора хозяину таверны Гроску в Колючий Холм."}}
D[2178] = {"Спокойная жизнь долгоногов",{"Принесите 5 кусков мяса долгонога Аландариан Песне Ночи в Аубердин."}}
D[2198] = {"Порванное ожерелье",{"Найдите создателя ожерелья, чтобы узнать, чего оно стоит."}}
D[2199] = {"Мудрость за деньги",{"Принесите пять серебряных слитков Талвашу де Кисселю в Стальгорн."}}
D[2200] = {"Назад в Ульдаман",{"Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья."}}
D[2201] = {"Время собирать камни",{"Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем де Кисселем, используя фиал Видения, который он предоставил.","","Из дневника вы узнали следующее:","*Рубин укрыт в забаррикадированной Кузне Теней.","*Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса.","","*Сапфир присвоил себе Гримлок, лидер троггов."}}
D[2202] = {"В Ульдаман за реактивом",{"Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат."}}
D[2203] = {"Пробежка по Бесплодным землям-2",{"Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Джаркалу Замшелому Клыку в Каргат."}}
D[2204] = {"Восстановление ожерелье",{"Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу де Кисселю в Стальгорн."}}
D[2205] = {"Выход на ШРУ",{"Доставьте пакет от Керина Сильвиуса мастеру Матиасу Шоу в казармы Штормграда."}}
D[2206] = {"Держи-хватай!",{"Найдите портового начальника из Братства Справедливости и добудьте расписание поставок для мастера Матиаса Шоу."}}
D[2218] = {"Путь к спасению",{"Поговорите с Хальфданом Чернобородом в Стальгорне."}}
D[2238] = {"Простая уловка",{"Найдите Онина Макмолота в Гномрегане."}}
D[2239] = {"Донесение Онина",{"Доставьте донесение Онина Хальфдану в Стальгорн."}}
D[2240] = {"Потайной чертог",{"Прочитайте журнал Балеога, исследуйте, потайной чертог и потом доложите об увиденном геологу Грозовой Вершине."}}
D[2241] = {"Катись, яблочко...",{"Отнесите розу Джаннока Сиарне в Дарнасс."}}
D[2242] = {"Зов судьбы",{"Найдите Сетира Древнего и принесите все, что сумеете найти, Сиарне."}}
D[2258] = {"Пробежка по Бесплодным землям",{"Принесите 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей Джаркалу Смешанному Лишайнику в Каргат."}}
D[2259] = {"Эрион Шепот Тени",{"Встретьтесь в Дарнассе с Эрионом Шепотом Тени."}}
D[2260] = {"Директива Эриона",{"Отправляйтесь в Штормград и посоветуйтесь с Рензиком Ножом."}}
D[2278] = {"Платиновые диски",{"Поговорите с каменным Стражем и запомните все, что он передаст вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона."}}
D[2279] = {"Платиновые диски",{"Отнесите миниатюрную копию дисков Норганнона в Лигу исследователей в Стальгорне."}}
D[2280] = {"Платиновые диски",{"Отнесите миниатюрную копию дисков Норганнона кому-то из мудрецов с Громового Утеса."}}
D[2281] = {"Встречи в Красногорье",{"Отправляйтесь в Приозерье, что в Красногорье, и поговорите с Люцием."}}
D[2282] = {"Лесопилка Альтера",{"Откройте сундук Люция, достаньте руну воровства и вернитесь к Люцию в Приозерье."}}
D[2283] = {"Пропавшее ожерелье",{"Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу."}}
D[2284] = {"Пропавшее ожерелье, этап 2",{"Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана."}}
D[2298] = {"Королевская облава",{"Отправляйтесь в Штормград и найдите Рензика Ножа."}}
D[2299] = {"К Хальфдану!",{"Отправляйтесь в Стальгорн и поговорите с Хальфданом Чернобородом."}}
D[2300] = {"ШРУ",{"Отправляйтесь в Штормград и разыщите Рензика Ножа."}}
D[2318] = {"Трудности перевода",{"Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях."}}
D[2338] = {"Трудности перевода",{"Одолжите ожерелье Джаркалу. Взамен он переведет дневник."}}
D[2339] = {"Найти самоцветы и источник энергии",{"Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане.","","Из дневника следует...","* Рубин спрятан на огражденной завалами территории Кузни Теней.","*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.","*Сапфир забрал Гримлок, старейшина троггов."}}
D[2340] = {"Принести самоцветы",{"Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар."}}
D[2341] = {"Пропавшее ожерелье, этап 3",{"Навестите Джаркала Замшелого Клыка в Каргате."}}
D[2342] = {"Возвращенные сокровища",{"Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана."}}
D[2358] = {"Рога Незры",{"Верните рога Незры Арантиру в Приозерье."}}
D[2359] = {"Башня Клейвена",{"Добудьте ключ от башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кирнен, чтобы больше узнать о башне."}}
D[2360] = {"Матиас и Братство Справедливости",{"Найдите посланницу Кеарнен в Западном Крае и поговорите с ней."}}
D[2361] = {"Восстановление ожерелье",{"Я с великой радостью вручаю тебе это ожерелье, могучий |3-6(Жрец). Ты оказал мне неоценимую услугу, и я благодарен тебе за это. Носи же его с гордостью и не забывай при этом все время упоминать о том, кто сделал его для тебя!","","Да, если еще добавишь, что на ожерелье нет проклятия, это будет великолепно."}}
D[2378] = {"Поиски Изувеченной Длани",{"Отправляйтесь в Оргриммар и поговорите с Шентулом в Расселине Теней."}}
D[2379] = {"Зандо'зан",{"Поговорите с Зандо'заном в расселине Теней."}}
D[2380] = {"В Оргриммар!",{"Поговорите с Шентулом в расселине Теней в Оргриммаре."}}
D[2381] = {"Грабь награбленное",{"Принесите Рениксу Презренному из Кабестана сокровище Южного моря. Не забудьте взять из гизмотронного аппарата Реникса ХОЧУ и отмычки. Они понадобятся для выполнения задания.","","Если на вас нападут необычайно враждебные попугаи, воспользуйтесь ХОЧУ!"}}
D[2382] = {"Реникс из Кабестана",{"Поговорите с Рениксом Презренным в Кабестане."}}
D[2383] = {"Записка на пергаменте",{"Прочтите пергамент и поговорите с Франгом в долине Испытаний."}}
D[2398] = {"Потерянные дворфы",{"Найдите Бейлога в Ульдамане."}}
D[2399] = {"Росток папоротника",{"Папоротник, который Деналан посадил у себя в саду, проклюнулся и вырос. Ростки так и просят, чтобы их скорее собрали..."}}
D[2418] = {"Камни Силы",{"Принесите 8 дентриевых камней Силы и 8 энелиевых камней Силы Ригглфаззу в Бесплодные земли."}}
D[2438] = {"Изумрудный ловец снов",{"Принесите изумрудного ловца снов Таллонкаю Гибкому Корню в Доланаар."}}
D[2439] = {"Платиновые диски",{"Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна."}}
D[2440] = {"Платиновые диски",{"Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес."}}
D[2458] = {"Надежное прикрытие",{"Отыщите башню Торговой компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.","","Возле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и продемонстрируйте приветствие Изувеченной Длани (команда /честь).","","Все нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным."}}
D[2459] = {"Фероситас Пожиратель Снов",{"Таллонкай Гибкий Корень из Доланаара хочет, чтобы вы убили 7 мистиков из племени Кривой Сосны и нашли пропавший самоцвет."}}
D[2460] = {"Приветствие Изувеченной Длани",{"Повторите приветствие Раздробленной Руки вслед за Шентулом."}}
D[2478] = {"Миссия: выполнима, но с трудом",{"Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой компании, двух патрульных Торговой компании и двух смотрителей Торговой компании.","","Ликвидируйте старшего мастера Галливикса, взломайте замок на его ящике и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания."}}
D[2479] = {"Помощь Хинотта",{"Отправляйтесь в Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.","","Сядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками."}}
D[2480] = {"Помощь Хинотта",{"Дождитесь, пока Серж Хинотт доделает лекарство."}}
D[2498] = {"Возвращение к Деналану",{"Релиан Зеленый Костер хочет, чтобы вы поговорили с Деналаном у озера Аль'Амет."}}
D[2499] = {"Дубохмур",{"Деналан с озера Аль'Амет хочет, чтобы вы сняли гигантскую опухоль с Дубохмура."}}
D[2500] = {"Пробежка по Бесплодным землям",{"Добудьте в Бесплодных землях реактивы для Гхака Целителя и отнесите их ему в Телcамар."}}
D[2501] = {"Пробежка по Бесплодным землям-2",{"Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар."}}
D[2518] = {"Слезы Луны",{"Жрица А'моора из дарнасского храма Луны хочет, чтобы вы принесли ей серебряные паутинные железы леди Сатры."}}
D[2519] = {"Храм Луны",{"Сестра Аквинна хочет, чтобы вы поговорили со жрицей А'моорой из Храма Луны."}}
D[2520] = {"Жертвоприношение Сатры",{"Жрица А'моора просит вас положить серебряные паутинные железы леди Сатры у фонтана в храме и затем вернуться к ней."}}
D[2521] = {"Служба для Кум'иша",{"Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренетиста, отнесите ее Кум'ише Коллекционеру.","","Будьте внимательны – этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренетиста.","","Вы будете вознаграждены за каждую безупречную сферу из дренетиста, которую доставите Кум-ише."}}
D[2522] = {"Попытки Кум'иша",{"Найдите безупречную сферу из дренетиста и верните ее Кум'ише Коллекционеру."}}
D[2523] = {"Оскверненный песнецвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[2541] = {"Спящий друид",{"Принесите шаманский оберег вуду Обену Яростному Когтю в обитель Бен'этиль."}}
D[2561] = {"Друид-медведь",{"Обен Яростный Коготь просит, чтобы вы уничтожили его лишенное души тело, а затем воспользовались оберегом вуду."}}
D[2581] = {"Челюсти гиены-хохотуна",{"Принесите три челюсти гиены, два обожженных легких вепря и клешню скорпока магу крови Дразиалу."}}
D[2582] = {"Ярость веков",{"Принесите три челюсти гиены, два обожженных легких вепря и клешню скорпока магу крови Дразиалу."}}
D[2583] = {"Жизненная сила вепря",{"Принесите три обожженных легких вепря, две клешни скорпока и мозг василиска магу крови Дразиалу."}}
D[2584] = {"Дух вепря",{"Принесите три обожженных легких вепря, две клешни скорпока и мозг василиска магу крови Дразиалу."}}
D[2585] = {"Решительный удар",{"Принесите три клешни скорпока, две порции потрохов стервятника и обожженное легкое вепря магу крови Дразиалу."}}
D[2586] = {"Скорпоковая соль",{"Принесите три клешни скорпока, две порции потрохов стервятника и обожженное легкое вепря магу крови Дразиалу."}}
D[2601] = {"Укус василиска",{"Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре."}}
D[2602] = {"Непогрешимый разум",{"Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре."}}
D[2603] = {"Стойкость стервятника",{"Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре."}}
D[2604] = {"Духовное превосходство",{"Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре."}}
D[2605] = {"Жаждущий гоблин",{"Добудьте насыщенную влагой железу и принесите ее Синю Гогельмогелю в Прибамбасск."}}
D[2606] = {"Хороший вкус",{"Поговорите с Поливалкой в Прибамбасске по поручению Синя Гогельмогеля."}}
D[2607] = {"Прикосновение Занзила",{"Поговорите с Доком Миксиль-Пиксилем в подвале казарм."}}
D[2608] = {"Прикосновение Занзила",{"Лягте на землю (действие /lay) для осмотра Доком Миксиль-Пиксилем – он не сможет подобрать лекарство, пока не найдет причину болезни."}}
D[2609] = {"Прикосновение Занзила",{"Принесите Доку Миксиль-Пиксилю один букетик простых полевых цветов, одну освинцованную колбу, одну бронзовую трубку и одну катушку светлого зеленовато-желтого шелка. Чтотит, знаете ли, сам собой не проходит."}}
D[2621] = {"Опозоренный",{"Поговорите с командиром разведотряда Руагом в Каменоре."}}
D[2622] = {"Пропавшие приказы",{"Поговорите с Бенгором."}}
D[2623] = {"Болотный говорун",{"Заберите приказы вождя и верните их павшему герою Орды."}}
D[2641] = {"Маленький секрет Поливалки",{"Найдите фиалковый траган и вернитесь к Поливалке в Прибамбасск."}}
D[2661] = {"Посылка для Синя",{"Отнесите фиалковый порошок Синю Гогельмогелю в Прибамбасск."}}
D[2662] = {"Эликсир Ноггенфоггера",{"Синь Гогельмогель хочет поговорить с вами после завершения работы над эликсиром."}}
D[2681] = {"Камни, что связывают нас",{"Освободите девять слуг Разелиха, трех слуг Севины, трех слуг Аллистария и трех слуг Грола. Когда ваша задача будет выполнена, возвращайтесь к павшему герою. Вы должны оставаться поблизости от камней, иначе процесс не будет завершен."}}
D[2701] = {"Герои древних времен",{"Откройте шкатулку и возьмите награду."}}
D[2702] = {"Герои древних времен",{"Поговорите с капралом Тундом Треснувшим Копытом."}}
D[2721] = {"Кирит",{"Узнайте, что стало с лейтенантом Киритом."}}
D[2741] = {"Супер Яйц-О-Матик",{"Супер Яйц-О-Матик – последнее изобретение Кургль Поскакушки. Очень впечатляющее устройство.","","Приближаясь к панели управления, вы слышите, как машина яростно гудит."}}
D[2742] = {"Рин'джи в ловушке",{"Выведите Рин'джи из Сторожки Кель'Данил, а потом найдите то, что он спрятал в Отвесных скалах, на востоке."}}
D[2743] = {"Покров Тьмы",{"Вернитесь к павшему герою Орды со своими находками."}}
D[2744] = {"Охотник на демонов",{"Поговорите в Азшаре с Лорамусом Многоногом."}}
D[2745] = {"Проникновение в крепость",{"Поговорите с Тирионом в крепости Штормграда."}}
D[2746] = {"Все по порядку",{"Принесите Тириону в Штормград 3 отреза шелка и 2 свежих яблока Клары."}}
D[2747] = {"Необычное яйцо",{"Редко удается принести яйца из Фераласа в таком необыкновенном состоянии. Они очень редко встречаются..."}}
D[2748] = {"Хорошее яйцо",{"Из хороших яиц при правильных условиях вылупляются гиппогрифы, не пораженные заклинаниями огров клана Гордунни."}}
D[2749] = {"Обычное яйцо",{"Обычные яйца гиппогрифа вылупляются только в половине случаев. Мы будем тщательно ухаживать за ними, и при удаче кто-нибудь из них вылупится."}}
D[2750] = {"Плохое яйцо",{"Яйца вроде этого не спасти – из них никто не вылупится."}}
D[2751] = {"Варварские доспехи",{"Принесите 2 узорчатых бронзовых боевых браслета, 2 бронзовых больших меча и 2 острых когтя Орокку Омошу в Оргриммар."}}
D[2752] = {"За железными наплечниками",{"Принесите Орокку Омошу в Оргриммар 4 бронзовых боевых топора и 4 бронзовых боевых молота."}}
D[2753] = {"Тяжелая поступь",{"Принесите 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей Орокку Омошу в Оргриммар."}}
D[2754] = {"Рога безумия",{"Принесите Орокку Омошу в Оргриммар 2 прочных железных кувалды, 2 пары посеребренных бронзовых сапог и 2 пары посеребренных бронзовых рукавиц."}}
D[2755] = {"Радости Омоша",{"Научитесь танцу Радости Омошей."}}
D[2756] = {"Старые обычаи",{"Принесите 4 стальные кирасы и 4 стальных латных шлема Атурку Наковальне в Оргриммар."}}
D[2757] = {"Вперед, в Пиратскую Бухту!",{"Поговорите с Макгеваном в Пиратской бухте."}}
D[2758] = {"Происхождение кузнечного искусства",{"Принесите 6 пар золотых чешуйчатых наручей Хэнку Молоту в Штормград."}}
D[2759] = {"В поисках Гальвана",{"Поговорите с Макгеваном в Пиратской бухте."}}
D[2760] = {"Орден Мифрила",{"Поговорите с Гальваном Древним в Тернистой долине."}}
D[2761] = {"Плавим, не плавим, плавим, не плавим…",{"Принесите сорок мифриловых слитков и сорок железных слитков Гальвану Древнему из Тернистой долины."}}
D[2762] = {"Обманное серебро",{"Принесите сорок мифриловых слитков и сорок слитков истинного серебра Гальвану Древнему из Тернистой долины."}}
D[2763] = {"Могущество камней",{"Принесите сорок мифриловых слитков и 4 цитрина Гальвану Древнему из Тернистой долины."}}
D[2764] = {"Лучший ученик Гальвана",{"Поговорите с Трентоном Молотом Света из Прибамбасска."}}
D[2765] = {"Кузнец-умелец!",{"Получите награду у Гальвана Древнего!"}}
D[2766] = {"Найти ККX-22/FE!",{"Отнесите аварийный маяк к автономному роботу Карлса, в пещеру рядом с Долиной Свирепого Утеса."}}
D[2767] = {"Спасти ККX-22/FE!",{"Проводите OOX-22/FE в порт на Забытом Берегу, затем сообщите об этом Карлсу Пропеллерзу в Пиратской бухте."}}
D[2768] = {"Изыскательский жезл",{"Принесите изыскательский жезл главному инженеру Чепухастеру в Прибамбасск."}}
D[2769] = {"Братья Латунный Болт",{"Поговорите с Виззлом Медноштифом на Мерцающей равнине."}}
D[2770] = {"Газ'рилла",{"Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину."}}
D[2771] = {"Голова на плечах",{"Принесите два мифриловых капюшона и изысканный мифриловый наплечник Трентону Молоту Света."}}
D[2772] = {"Мир у твоих ног",{"Принесите две пары тяжелых мифриловых сапог и изысканные мифриловые штаны Трентону Молоту Света."}}
D[2773] = {"Мифриловый парень",{"Принесите две тяжелых мифриловых кирасы и изысканные мифриловые перчатки Трентону Молоту Света."}}
D[2781] = {"Разыскивается: Калиф Жало Скорпида",{"Принесите голову Калифа Жало Скорпида главному инженеру Чепухастеру в Прибамбасск."}}
D[2782] = {"Секрет Рин'джи",{"Отнесите табличку Оран Змеиные Кольца в Квартал Магов Подгорода. Оран – известная ученая, изучающая троллей из племени Сухокожих, и она наверняка сумеет прочесть надписи на табличке."}}
D[2783] = {"Мелкие раздоры",{"Поговорите с павшим героем Орды на границе Выжженных земель и болот."}}
D[2784] = {"Попавший в немилость",{"Послушайте, как павший герой Орды рассказывает свою историю."}}
D[2801] = {"Горестная повесть",{"Послушайте, как павший герой Орды рассказывает свою историю."}}
