D[2822] = {"Знак качества",{"Принесите 10 толстых шкур йети Джангору Быстрому Страннику в Лагерь Мохаче."}}
D[2841] = {"Техновойны",{"Добудьте в Гномрегане чертежи боевой машины и код от сейфа Термоштепселя в Гномрегане и принесите их Ноггу в Оргриммар."}}
D[2842] = {"Главный инженер Скути",{"Поговорите со Скути в Пиратской бухте."}}
D[2843] = {"Поехалиии!",{"Дождитесь, пока Скути настроит гоблинский импульсный повторитель."}}
D[2844] = {"Великан-опекун",{"Найдите потерявшуюся ночную эльфийку."}}
D[2845] = {"Шай-бродяжница",{"Достаньте из сундучка колокольчик Шай.","","Проводите Шай Листогон в лагерь Камнедробителя."}}
