D[2854] = {"Доспехи из дикой кожи",{"Принесите 10 кусков плотной кожи Джангору Быстрому Страннику в Лагерь Мохаче."}}
D[2855] = {"Наплечники из дикой кожи",{"Принесите 6 накладок из толстой кожи и дикую лозу Джангору Быстрому Страннику в лагерь Мохаче."}}
D[2856] = {"Жилет из дикой кожи",{"Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикую лозу Джангору Быстрому Страннику в лагерь Мохаче."}}
D[2857] = {"Шлем из дикой кожи",{"Принесите 2 ночных мундира, 2 ночных головных повязки и дикую лозу Джангору Быстрому Страннику в лагерь Мохаче."}}
D[2858] = {"Сапоги из дикой кожи",{"Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 диких лозы Джангору Быстрому Страннику в лагерь Мохаче."}}
D[2859] = {"Поножи из дикой кожи",{"Принесите два черепашьих чешуйчатых шлема, две пары черепашьих чешуйчатых наручей и две дикие лозы Джангору Быстрому Страннику в лагерь Мохаче."}}
D[2860] = {"Мастер школы Дикаря",{"Отдайте письмо Джангора Уне, главному кожевнику Громового Утеса."}}
D[2861] = {"Миссия Табеты",{"Поговорите с Табетой в Пылевых топях."}}
D[2862] = {"Война с племенем Древолапов",{"Принесите 10 грив гноллов-древолапов Хадокену Быстрому Страннику в Лагере Мохаче."}}
D[2863] = {"Истребление вожаков",{"Убейте в течение часа 5 вожаков стаи Древолапов и вернитесь к Хадокену Быстрому Страннику."}}
D[2864] = {"Тран'рек",{"Поговорите с Тран'реком в Прибамбасске."}}
D[2865] = {"Панцири скарабеев",{"Принести 5 целых панцирей скарабея Тран'реку в Прибамбасск."}}
D[2866] = {"Руины Соларсаля",{"Обследуйте руины Соларсаля на предмет присутствия наг."}}
