D[2869] = {"Борьба с Гребнем Ненависти",{"Принесите 10 штук чешуи наг из клана Гребня Ненависти Латроникусу Лунному Копью в Крепость Оперенной Луны."}}
D[2870] = {"Борьба с лордом Шалзару",{"Убейте лорда Шалзару и принесите обнаруженную им таинственную реликвию Латроникусу Лунному Копью в Крепость Оперенной Луны."}}
D[2871] = {"Доставка реликвии",{"Доставьте таинственную реликвию Вестии Лунное Копье в Крепость Оперенной Луны."}}
D[2872] = {"Долг Столи",{"Поговорите со Столи из Порта Картеля."}}
D[2873] = {"Посылка Столи",{"Отыщите партию товара Столи и возвратите ее хозяину в Порт Картеля."}}
D[2874] = {"Ром для Маккинли",{"Отнесите бутылку Столи \"Морскому волку\" МакКинли в Пиратскую Бухту."}}
D[2875] = {"Разыскивается: Андре Огнебородый",{"Принесите голову Андре Огнебородого начальнику отдела безопасности Чепухастеру в Порт Картеля."}}
D[2876] = {"Расписание кораблей",{"Сообщите о корабельном расписании руководству Порта Картеля."}}
D[2877] = {"Зачистка Осклизлой скалы",{"Убейте 10 зеленых слякочей и 10 нефритовых слизнюков, после чего доложитесь Фраггару Громовой Мантии на Заоблачном Пике."}}
D[2878] = {"Оскверненный песнецвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[2879] = {"Посох равноденствия",{"Зарядите посох Трояса и отыщите Монолит Равноденствия."}}
D[2880] = {"Ожерелья троллей",{"Принесите 5 тролльих ожерелий Фраггару Громовой Мантии на Заоблачный пик."}}
D[2881] = {"Ожерелья троллей",{"Вы уже выполнили мое задание, но если вы захотите принести мне еще тролльих ожерелий, то я с радостью приму их. Это поможет вам заслужить хорошее отношение Громового Молота – если вы нам помогаете, то и мы с радостью поможем вам!","","Приносите по пять ожерелий, Медведик."}}
D[2882] = {"Золото Куэрго",{"Найдите золото Куэрго!"}}
D[2902] = {"Разведка планов Древолапов",{"Найдите гноллские боевые планы в гноллских лагерях к югу от Лагеря Мохаче."}}
