D[3635] = {"Гномское инженерное дело",{"Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту."}}
D[3636] = {"Нести свет",{"Убейте Амненнара Хладовея на Курганах Иглошкурых."}}
D[3637] = {"Гномское инженерное дело",{"Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту."}}
D[3638] = {"Договор о неразглашении",{"Если вы согласны заниматься гоблинским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Никсу Шепружину в Прибамбасске."}}
D[3639] = {"Покажи свою работу",{"Принесите 20 больших железных бомб, 20 шашек плотного динамита и 5 взрывоопасных овец Никсу Шепружину в Прибамбасск."}}
D[3640] = {"Договор о неразглашении",{"Щелкните ПКМ по Договору о неразглашении и еще раз обратитесь к мехмастеру Замыкальцу в Стальгорне."}}
D[3641] = {"Покажи свою работу",{"Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн."}}
D[3642] = {"Договор о неразглашении",{"Если вы согласны заниматься гномским инженерным делом, щелкните ПКМ по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской Бухте."}}
D[3643] = {"Покажи свою работу",{"Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую Бухту."}}
D[3644] = {"Продление членского билета",{"Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых."}}
D[3645] = {"Продление членского билета",{"Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых."}}
D[3646] = {"Продление членского билета",{"Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых."}}
D[3647] = {"Продление членского билета",{"Чтобы продлить членский билет, вам придется заплатить два золотых в качестве пошлины за продление."}}
D[3661] = {"Любимцы Элуны?",{"Собрерите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут'теран."}}
D[3681] = {"Фолиант Божественности",{"Разыщите в Штормграде Даториана Ралла и поговорите с ним."}}
D[3701] = {"Дымящиеся руины Тауриссана",{"Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону."}}
D[3702] = {"Дымящиеся руины Тауриссана",{"Узнайте от королевского историка Аркессона историю Тауриссана."}}
D[3721] = {"Собственный ККХ",{"Тебе удалось выручить всех трех моих роботов серии ООХ! Ты сделал все, что требовалось и даже больше, поэтому я хочу особым образом отблагодарить тебя за помощь. Это миниатюрная версия того же робота, с которым ты провел так много времени и полюбил, ООХ!","","Обычно я никому не дарю такие опасные устройства, но ты оказал мне неоценимую помощь. Кроме того у этой тварюшки отключены боевые механизмы и устройство самонаведения.","","А в остальном это полноценный ООХ!"}}
D[3741] = {"Ожерелье Хилари",{"Найдите ожерелье Хилари и верните его Хилари в Приозерье."}}
D[3761] = {"Почва Ун'Горо",{"Принесите 20 образцов земли из Кратера Ун'Горо Геду на Вершину Старейшин Громового Утеса."}}
D[3762] = {"Помощь верховному друиду Руническому Тотему",{"Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса."}}
D[3763] = {"Помощь верховному друиду Оленьему Шлему",{"Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе."}}
D[3764] = {"Почва Ун'Горо",{"Принесите 20 образцов земли из кратера Ун'Горо Дженалю в дарнасский анклав Кенария."}}
D[3765] = {"Проблема за морем",{"Отправляйтесь в Аубердин к Гершалу Шепоту Ночи."}}
D[3781] = {"Изучение рассветницы",{"Отнесите расписку верховного друида в получении семян Матренгилу Медвежьей Лапе в дарнасский анклав Кенария."}}
D[3782] = {"Изучение рассветницы",{"Отнесите расписку в получении семян Башане Рунический Тотем в Громовой Утес."}}
D[3783] = {"Йети где-то рядом…",{"Соберите 10 толстых кусков меха йети для Уми Смехотреп из Круговзора."}}
D[3784] = {"Помощь верховному друиду Руническому Тотему",{"Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса."}}
D[3785] = {"Изучение рассветницы",{"При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун'Горо попытайтесь прорастить рассветницу.","","Принесите 10 рассветниц Матренгилу Медвежьей Лапе в Дарнасс."}}
D[3786] = {"Изучение рассветницы",{"При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун'Горо попытайтесь прорастить рассветницу.","","Принесите 10 рассветниц Башане Рунический Тотем в Громовой Утес."}}
D[3787] = {"Кинтис Пламень",{"Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны."}}
D[3788] = {"Кинтис Пламень",{"Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны."}}
D[3789] = {"Помощь верховному друиду Оленьему Шлему",{"Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе."}}
D[3790] = {"Помощь верховному друиду Оленьему Шлему",{"Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе."}}
D[3791] = {"Тайна рассветницы",{"Принесите 10 рассветниц друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны."}}
D[3792] = {"Рассветница для Крепости Оперенной Луны",{"А, здравствуйте, Серыйаскет! Мои исследования продвигаются неплохо, но, если у вас найдется еще пять рассветниц, я бы с удовольствием их у вас приобрел. Хотя, конечно, с удовольствием – это только фигура речи: чем больше я имею с нею дело, тем сильнее мне не по себе. И тем не менее я не намерен отказываться от дальнейших экспериментов!"}}
D[3801] = {"Наследие Черного Железа",{"Чтобы получить ключ от города, поговорите с Франклорном Искусником."}}
D[3802] = {"Наследие Черного Железа",{"Убейте Финия Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника."}}
D[3803] = {"Рассветница для Дарнасса",{"Верховному друиду постоянно не хватает рассветницы для проведения исследований Круга Кенария. Мы принимаем ее партиями по десять пучков и в награду даем несколько полезных вещей. Когда соберешь десять пучков, сообщи мне, и я достойно награжу тебя."}}
D[3804] = {"Рассветница для Громового Утеса",{"Верховный друид постоянно ищет дополнительные источники рассветницы для исследовательского проекта Круга Кенария в Кратере Ун'Горо. Мы берем их партиями по десять штук и в награду даем несколько полезных вещей. Когда наберешь десять штук, сообщи мне, и я достойно награжу тебя."}}
D[3821] = {"Скала Молота Ужаса",{"Отправляйтесь в Пылающие степи и выясните, что сталось с Ша'ни Гордым Клыком."}}
D[3822] = {"Кром'Грул",{"Заберите ноздревое кольцо Ша'ни у Кром'Грула и верните его Тал'траку из Каргата. Обыщите различные пещеры и рудники скалы Молота Ужаса."}}
D[3823] = {"Угасание Огненного Чрева",{"Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева. По выполнении задания вернитесь к Орелиусу."}}
D[3824] = {"Гор'теш Жестокий",{"Найдите Гор'теша на западе от скалы Молота Ужаса. Убейте Гор'теша и отнесите его голову Орелиусу в Пылающие степи."}}
D[3825] = {"Голова огра на палочке = вечеринка",{"Отнесите голову Гор'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику."}}
D[3841] = {"Бездомный сиротка",{"Поговорите с Квентином в Тысяче Игл."}}
D[3842] = {"Инкубатор",{"Принесите 2 эликсира стойкости Квентину в Тысячу Игл."}}
D[3843] = {"Новый член семьи",{"Отнесите хрупкое яйцо летучего хамелеона во Внутренние земли и поговорите с Агнаром Зверопасом. У вас есть на это всего 1 час. В противном случае детеныш в яйце умрет."}}
D[3844] = {"Тайна, покрытая мраком",{"Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот."}}
D[3845] = {"Тайна, покрытая мраком",{"Изучите найденное в сумке и верните владельцу."}}
D[3861] = {"Куд-кудаааа!",{"Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете ее, /поклонитесь ей прежде, чем накормить ее специальным цыплячьим кормом."}}
D[3881] = {"Спасение экспедиции",{"Принесите ящик с провизией и исследовательское оборудование Виллидену Маршалу в Кратер Ун'Горо."}}
D[3882] = {"Игра в кости",{"Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун'Горо."}}
D[3883] = {"Экология чужих",{"Воспользуйтесь фиалом для образцов, чтобы взять образец материала стены улья из одного из инкубаторов Гориши в Кратере Ун'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок.","","Принесите образец материала стены улья Холании Маршал в Кратер Ун'Горо."}}
D[3884] = {"Дневник Вилидена",{"Верните дневник Виллидену Маршалу, который находится где-то в Кратере Ун'Горо."}}
D[3901] = {"Игрушки-погремушки",{"Убейте 12 скелетов-костетрясов, а затем вернитесь к жрецу Тьмы Сарвису в Могильник."}}
D[3902] = {"Поиски старой одежды",{"Обыщите Могильник и его окрестности и найдите 6 ящиков с добычей и передайте их стражу смерти Салтену."}}
D[3903] = {"Милли Осворт",{"Поговорите с Милли Осворт."}}
D[3904] = {"Урожай Милли",{"Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья."}}
D[3905] = {"Уведомление о поставке винограда",{"Отнесите уведомление о поставке винограда брату Нилзу в Аббатство Североземья."}}
D[3906] = {"Дисгармония пламени",{"Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду."}}
D[3907] = {"Дисгармония пламени",{"Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию."}}
D[3908] = {"Тайна, покрытая мраком",{"Отнесите меч Линкена Донове Снегоноре."}}
D[3909] = {"Эликсир Видере",{"Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре."}}
D[3911] = {"Последняя Стихия",{"Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей."}}
D[3912] = {"Встречаемся на кладбище",{"Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана."}}
D[3913] = {"Замогильная история",{"Воскресните, найдите могильный камень, о котором говорил Гаэриан."}}
D[3914] = {"Меч Линкена",{"Доставьте превосходный меч Линкена Линкену в Кратер Ун'Горо."}}
D[3921] = {"Венаки Бенике",{"Отнесите сломанный самофланж Венаки Бенике."}}
D[3922] = {"Металлические заготовки",{"Принесите 15 металлических заготовок для деталей Венаки Бенике в Степи."}}
D[3923] = {"Рилли Грязегоб",{"Отнесите разбитый и сломанный самофланж Рилли Грязегобу в Оргриммар."}}
D[3924] = {"Руководство по самофланжу",{"Отнесите руководство по самофланжу Рилли Грязегобу в Оргриммар."}}
D[3941] = {"Помощь гномов",{"Найдите Джей Ди Колли в Укрытии Маршалла."}}
D[3942] = {"Память Линкена",{"Найдите Эридану Грусть Ветра на юге Оскверненного леса."}}
D[3961] = {"Приключения Линкена",{"Отнесите серебряный тотем Аквамонтоса Линкену в Укрытие Маршалла."}}
D[3962] = {"Один в поле не воин",{"Отправляйтесь к Вулкану Огненного Венца, к югу от Укрытия Маршалла.","","Найдите Яропламеня и разрушьте его защитную ауру с помощью тотема. Когда дух будет сражен, заберите из пещеры Золотое пламя."}}
D[3981] = {"Командир Гор'шак",{"Найдите командира Гор'шака в Глубинах Черной горы.","","Судя по рисунку в записке, искать следует в темнице где-то вроде того."}}
D[3982] = {"Что происходит?",{"Защитите Горшака."}}
D[4001] = {"Что происходит?",{"Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.","","Карана держат в темнице напротив."}}
D[4002] = {"Восточные королевства",{"Поговорите с Траллом."}}
D[4003] = {"Спасение принцессы",{"Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия."}}
D[4004] = {"Спасенная принцесса",{"Вернитесь к Траллу."}}
D[4005] = {"Аквамонтос",{"Отнесите книгу Аквора, серебристые когти и сердце Железнолесья в Танарис.","","Воспользуйтесь книгой для призыва Аквамонтоса.","","По получении тотема, отнести его Джей Ди Колли в Укрытие Маршалла."}}
D[4021] = {"Контратака!",{"Принесите кусок знамени Кром'зара Регтару Вратам Смерти. Его можно найти на западе от Перекрестка."}}
D[4022] = {"Вкус пламени",{"Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Каларана Ветрореза."}}
D[4023] = {"Вкус пламени",{"Покажите Цирусу Раскаивателю доказательство своих деяний.","","Возникает чувство, что Цирус заранее сомневается в ваших качествах."}}
D[4024] = {"Вкус пламени",{"Отправьтесь в глубины Черной горы и убейте Бейл'Гара.","","Известно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гара его огненную сущность.","","Отнесите сущность Цирусу Раскаивателю."}}
D[4041] = {"Эликсир Видере",{"Эликсир Видере? Ну да, смогу, конечно, только принеси сначала мне эвокорень.","","В травках и алхимии я разбираюсь неплохо... Вот послушай, как я однажды трансмутировал в золото сыр, которым собирался пообедать... Эй, ты куда?"}}
D[4061] = {"Восстание машин",{"Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании.","","Теодора упоминала, что осколки можно найти у элементалей и големов."}}
D[4062] = {"Восстание машин",{"Отнесите образец осколка элементаля Лотвилю Вериатусу.","","Теодора упоминала, что его лагерь находится на востоке."}}
D[4063] = {"Восстание машин",{"Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилю. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии."}}
D[4081] = {"УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа",{"Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров!","","По приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания."}}
D[4082] = {"УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа",{"Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров!","","По приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания."}}
D[4083] = {"Призрачный кубок",{"Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца."}}
D[4084] = {"Серебряное сердце",{"Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра."}}
D[4101] = {"Очищение Оскверненного леса",{"Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес."}}
D[4102] = {"Очищение Оскверненного леса",{"Принесите 15 кровавых янтарей Майбессе Речному Ветру в Оскверненный лес."}}
D[4103] = {"Лекарство из охотничьих трофеев",{"Тот, кто имеет при себе Маяк Кенария, может оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.","","За эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений."}}
D[4104] = {"Лекарство из минералов",{"Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.","","Если ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений."}}
D[4105] = {"Лекарство из оскверненных трав",{"Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.","","Во время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового бальзама Кенария."}}
D[4106] = {"Лекарство из оскверненных шкур",{"Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!","","Когда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений."}}
D[4107] = {"Лекарство из распыленных предметов",{"Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.","","Мне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам бальзама исцеления Кенария. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!"}}
D[4108] = {"Лекарство из охотничьих трофеев",{"Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.","","За эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений."}}
D[4109] = {"Лекарство из минералов",{"Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.","","Если ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений."}}
D[4110] = {"Лекарство из оскверненных трав",{"Маяк Кенария позволяет опытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться превращать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.","","Во время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие \"Маяк Кенария\". За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама."}}
D[4111] = {"Лекарство из оскверненных шкур",{"Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженной порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!","","Когда соберешь испорченные куски, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений."}}
D[4112] = {"Лекарство из распыленных предметов",{"Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.","","Мне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!"}}
D[4113] = {"Оскверненный песнецвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4114] = {"Оскверненный песнецвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4115] = {"Оскверненный ветроцвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4116] = {"Оскверненный песнецвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4117] = {"Оскверненный кнутокорень",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4118] = {"Оскверненный песнецвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4119] = {"Оскверненный ночной дракон",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4120] = {"Сила порчи",{"Убейте 12 гризли злобных когтей и 12 опустошителей-сквернолапов в Оскверненном лесу по просьбе Тало Тернового Копыта из лагеря Мохаче."}}
D[4121] = {"Опасное положение",{"Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.","","Лекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.","","Также отдайте Лекслорту ториевые оковы."}}
D[4122] = {"Грарк Лоркруб",{"Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы.","","По обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника."}}
D[4123] = {"Сердце горы",{"Принесите сердце горы Максворту Суперблеску в Пылающие степи."}}
D[4124] = {"Пропавший курьер",{"Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны."}}
D[4125] = {"Пропавший курьер",{"Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа."}}
D[4126] = {"Харли Чернопых",{"Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос."}}
D[4127] = {"Разбитая лодка",{"Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли."}}
D[4128] = {"Рагнар Громовар",{"Переговорите с Рагнаром Громоваром."}}
D[4129] = {"Тайна ножа",{"Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны."}}
D[4130] = {"Сверхзнание",{"Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны."}}
D[4131] = {"Гноллы из стаи Древолапов",{"Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера."}}
D[4132] = {"Операция:смерть Кузне Гнева",{"Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания."}}
D[4133] = {"Вивиана Лягроб",{"Переговорите с тенемагом Вивиан Лаграв в Каргате."}}
D[4134] = {"Украденный рецепт громоварского",{"Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат."}}
D[4135] = {"Гудящая Бездна",{"Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов."}}
D[4136] = {"Риббли Крутипроб",{"Принесите голову Риббли Юке Крутипроб в Пылающие степи."}}
D[4141] = {"Майджин и Ларион",{"Соберите 15 кровоцветов и принесите их Майджину."}}
D[4142] = {"Визит к Грегану",{"Отнесите кровоцвет Грегану Пивоплюю в Фералас."}}
D[4143] = {"Туман зла",{"Соберите 5 образцов тумана Аталаи и принесите их Майджину в Кратер Ун'Горо."}}
D[4144] = {"Побеги кровоцвета",{"Слушай мой план, Драгунов: пойди и собери для меня немного побегов кровоцвета – молодых, которые еще не успели полностью развиться. А потом посмотрим, как они отреагируют на туман Аталаи.","","Ты думаешь, я слишком злопамятен? Ну, в общем так и есть.","","На самом деле, я знаю дорогу отсюда, но пока Ларион не признает мою правоту, я отсюда не уйду.","","Ну, иди, принеси мне побегов, и мы славно повеселимся!"}}
D[4145] = {"Ларион и Майджин",{"Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла."}}
D[4146] = {"Питание для шокера",{"Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла."}}
D[4147] = {"Мастерская Марвона",{"Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане."}}
D[4148] = {"Разряд кровоцвета",{"Чтобы шокер заработал, необходим образец его цели – кровоцвета. Отправляйся в кратер и принеси мне побег кровоцвета, а я уж настрою прибор на милых маленьких дружков Майджина...","","Если бы он не был так упрям, мы давно уже выбрались бы из этого проклятого места... Но пока я должен показать ему, что его шуточки меня ничуть не беспокоят!"}}
D[4161] = {"Рецепт кальдораев",{"Принесите 7 маленьких паучьих лапок Заррину в Доланаар."}}
D[4181] = {"Гоблинское инженерное дело",{"Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск."}}
D[4182] = {"Драконья угроза",{"Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу."}}
D[4183] = {"Подлинные хозяева",{"Отправьтесь в Приозерье и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону."}}
D[4184] = {"Подлинные хозяева",{"Передайте обращение Соломона верховному лорду Болвару Фордрагону.","","Болвар Фордрагон пребывает в Крепости Штормграда."}}
D[4185] = {"Подлинные хозяева",{"Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор."}}
D[4186] = {"Подлинные хозяева",{"Отнесите указ Болвара мировому судье Соломону в Приозерье."}}
D[4201] = {"Приворотное зелье",{"Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы."}}
D[4221] = {"Оскверненный ветроцвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4222] = {"Оскверненный ветроцвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4223] = {"Подлинные хозяева",{"Поговорите с маршалом Максвеллом в Пылающих степях."}}
D[4224] = {"Подлинные хозяева",{"Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу.","","Кажется, маршал Максвелл говорил, что Джона следует искать в пещере на севере."}}
D[4241] = {"Маршал Винздор",{"Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором.","","Кажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу."}}
D[4242] = {"Утраченная надежда",{"Сообщите маршалу Максвеллу плохие новости."}}
D[4243] = {"В поисках Чи-Та 3",{"Найдите Чи-Та 3 в Кратере Ун'Горо."}}
D[4244] = {"В поисках Чи-Та 3",{"Найдите мифриловую обшивку и вернитесь к Чи-Та 3 в Кратер Ун'Горо."}}
D[4245] = {"В поисках Чи-Та 3",{"Доставьте Чи-Та 3 назад Карне Сомнамбулер в Кратер Ун'Горо."}}
D[4261] = {"Древний дух",{"Сопроводите Арая в безопасное место, затем поговорите с Кайнетом Штилем в Лесной Песне на востоке Ясеневого леса."}}
D[4262] = {"Подчинитель Пирон",{"Убейте подчинителя Пирона и вернитесь к Джалинде Тирлипуньке.","","Кажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?"}}
D[4263] = {"Опалитель!",{"Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!"}}
D[4264] = {"Измятая записка",{"Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива."}}
D[4265] = {"Освобожденный из улья",{"Освободите Раскала из улья Цуккаш.","","Вернитесь к Гинро Пылающему Очагу в Крепости Оперенной Луны и сообщите ему, что Раскал жив и здоров."}}
D[4266] = {"Благодарность за отвагу",{"Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной Луны."}}
D[4267] = {"Появление силитидов",{"Отнесите донесение Раскала Грацине Силе Духа в Дарнассе."}}
D[4281] = {"Посылка в Таланаар",{"Отнесите недоставленную посылку Хранителю дорог Фалфиндеру в Таланаар."}}
D[4282] = {"Проблеск надежды",{"Верните маршалу Виндзору утерянную информацию.","","Маршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева."}}
D[4283] = {"ПЯТЬДЕСЯТ! АГА!",{"Орелиусу нужны 50 медальонов Черной горы. Скорее всего их можно найти у орков Пылающих степях."}}
D[4284] = {"Кристаллы Силы",{"Соберите по 7 кристаллов Силы каждого цвета: красных, синих, желтых и голубых. Принесите их Джей Ди Колли в Укрытие Маршалла."}}
D[4285] = {"Северный пилон",{"Отыщите Северный хрустальный пилон в Кратере Ун'Горо."}}
D[4286] = {"Хороший товар",{"Отправьтесь в глубины Черной горы и принесите 20 поясных сумок дворфов Черного Железа. По выполнении задания вернуться к Орелиусу. Предположительно поясные сумки можно отобрать у дворфов Черного Железа в глубинах Черной горы."}}
D[4287] = {"Восточный пилон",{"Отыщите Восточный хрустальный пилон в Кратере Ун'Горо."}}
D[4288] = {"Западный пилон",{"Отыщите Западный хрустальный пилон."}}
D[4289] = {"Обезьяны Ун'Горо",{"Принесите 2 шкуры Ун'Горской гориллы, 2 шкуры Ун'Горского топтуна и 2 шкуры Ун'Горского рокотуна землепроходцу Торве к входу в Кратер Ун'Горо."}}
D[4290] = {"Добыча Лар'корви",{"Найдите последнюю добычу Лар'корви, украдите кусок трупа жесткозуба и вернитесь к землепроходцу Торве в Кратер Ун'Горо."}}
D[4291] = {"Запах Лар'корви",{"Принесите 2 феромонные железы равазавра землепроходцу Торве в преддверие Кратера Ун'Горо."}}
D[4292] = {"Приманка для Лар'корви",{"С помощью предметов из мешочка Торвы выманите Лар'корви и сразите его. Принесите голову Лар'корви землепроходцу Торве ко входу в Кратер Ун'Горо."}}
D[4293] = {"Проба слизи...",{"Возьмите на пробу образцы слизи из Оскверненного леса. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему."}}
D[4294] = {"...и образцы слизнюков",{"Возьмите на пробу образцы слизи из кратера Ун'Горо. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему."}}
D[4295] = {"Эль для Каменного Узла",{"Кружечка доброго эля Черного Железа была бы сейчас очень кстати! Быстрее, а то я уже начинаю трезветь! А когда я трезвею, у меня сразу мутится зрение... и все расплывается... и ты почему-то становишься очень похожим на того |3-6(человек), которого я грохнул на прошлой неделе."}}
D[4296] = {"Табличка Семерых",{"Принесите переписанный с таблички текст Максворту Суперблеску в Пылающие степи."}}
D[4297] = {"Покормить малыша",{"Принесите 5 окороков среброгривого бродяги Агнару Зверопасу во Внутренних землях."}}
D[4298] = {"У вас появился малыш!",{"Поговорите с Агнаром Зверопасом во Внутренних землях."}}
D[4300] = {"Костяные клинки",{"Принесите 8 белых когтей равазавра Джес'римону в Оргриммаре."}}
D[4301] = {"Могучая Уча",{"Принесите шкуру Учи землепроходцу Торве ко входу в Кратер Ун'Горо."}}
D[4321] = {"Давай-ка разберемся",{"Поговорите с Джей Ди Колли через пару минут."}}
D[4322] = {"Побег!",{"Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции."}}
D[4324] = {"Юка Крутипроб",{"Переговорите с Юкой Крутипроб в Пылающих степях."}}
D[4341] = {"Каран Могучий Молот",{"Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.","","Король упомянул, что Каран сидит там в плену – может, стоит поискать темницу."}}
D[4342] = {"Рассказ Карана",{"Выслушайте рассказ Карана Могучего Молота."}}
D[4343] = {"Оскверненный ветроцвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4361] = {"Недобрые вести",{"Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду."}}
D[4362] = {"Судьба королевства",{"Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана."}}
D[4363] = {"Королевский сюрприз",{"Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом."}}
D[4381] = {"Кристалл восстановления",{"Табличка пилона позволяет сочетать зеленые и желтые кристаллы Силы.","","Согласно книге Джей Ди, это сочетание можно использовать для исцеления себя или своих союзников."}}
D[4382] = {"Кристалл силы духа",{"Табличка пилона позволяет сочетать зеленые и синие кристаллы Силы.","","Согласно книге Джей Ди, это сочетание можно использовать для укрепления своего духа."}}
D[4383] = {"Кристалл-хранитель",{"Табличка пилона позволяет сочетать зеленые и красные кристаллы Силы.","","Согласно книге Джей Ди, это сочетание можно использовать для усиления защиты от физических повреждений."}}
D[4384] = {"Хрустальный удар",{"Табличка пилона позволяет сочетать красные и синие кристаллы Силы.","","Согласно книге Джей Ди, это сочетание можно использовать для ослабления обороны противника."}}
D[4385] = {"Хрустальный заряд",{"Табличка пилона позволяет сочетать красные и желтые кристаллы Силы.","","Согласно книге Джей Ди, это сочетание можно использовать для производства мощного взрыва, наносящего серьезный ущерб силам противника."}}
D[4386] = {"Хрустальная спираль",{"Табличка пилона позволяет сочетать синие и желтые кристаллы Силы.","","Согласно книге Джей Ди, это сочетание можно использовать для создания щита, наносящего повреждения противнику."}}
D[4401] = {"Оскверненный песнецвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4402] = {"Кактусовый десерт Галгара",{"Принесите Галгару 10 плодов кактуса."}}
D[4403] = {"Оскверненный ветроцвет",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
D[4421] = {"Порча нефритового огня",{"Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания."}}
D[4441] = {"Дерева в узах скверны",{"Отправляйтесь в Дарнасс и наберите в фиал Эриданы благословенной воды из храма Луны. Возвращайтесь к Эридане с полным фиалом."}}
D[4442] = {"Очищение явлено!",{"Через мгновение заговорите с Эриданой."}}
D[4443] = {"Оскверненный кнутокорень",{"Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться."}}
