D[7907] = {"Карты Новолуния: Звери",{"Принесите колоду Зверей на ярмарку Новолуния."}}
D[7908] = {"Мастер Арены",{"Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины."}}
