D[8064] = {"Знаки Силы: пояс гаруспика",{"Принесите Майвики из Зулдазара изначальный кушак племени Хаккари. Майвики из Зулдазара находится на острове Йоджамба, в Тернистой долине. Требуется уважение племени Зандалар"}}
D[8065] = {"Знаки Силы: мундир гаруспика",{"Принесите Майвики из Зулдазара изначальную гербовую накидку племени Хаккари.","","Майвики из Зулдазара находится на острове Йоджамба, в Тернистой долине."}}
D[8066] = {"Знаки Силы: пояс хищника",{"Принесите Фальтиру Слепому изначальную лацерну племени Хаккари. Требуется уважение племени Зандалар.","","Фальтир Слепой живет на острове Йоджамба, в Тернистой долине."}}
D[8067] = {"Знаки Силы: оплечье хищника",{"Принесите Фальтиру Слепому изначальную эгиду племени Хаккари. Требуется почтение племени Зандалар.","","Фальтир Слепой живет на острове Йоджамба, в Тернистой долине."}}
