D[8078] = {"Знаки Силы: пояс блюстителя",{"Принесите Джин'року Разрушителю изначальный ремень племени Хаккари. Требуется уважение племени Зандалар.","","Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине."}}
D[8079] = {"Знаки Силы: кираса блюстителя",{"Принесите Джин'року Разрушителю изначальную рубашку племени Хаккари. Требуется почтение племени Зандалар.","","Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине."}}
D[8080] = {"Ресурсы Низины Арати",{"Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт."}}
D[8081] = {"Новые ящики с ресурсами"}
D[8101] = {"Камешек Каджаро",{"Знаешь ли ты, что это, |3-6(гном)? Это – камешек с горы Каджаро в Южных морях. Там, где находится эта гора, постоянно происходят извержения вулканов, сама земля течет и меняется.","","Сила камня будет расти по мере того, как будет крепнуть твоя связь с троллями Зандалара. Используй его силу, чтобы стереть наших врагов с лица земли. В битве будь подобен вулкану: пусть никто не спасется от смертоносной мощи твоего гнева..."}}
D[8102] = {"Камешек Каджаро",{"Снова здравствуй, |3-6(Маг). Я вижу, камешек пригодился. Благодаря его сверхъестественной силе тебе удалось одолеть множество врагов, и они умерли в ужасных мучениях. Пришло время увеличить силу камня. Дай его мне."}}
D[8103] = {"Камешек Каджаро",{"Хаккари боятся тебя, Вертекс. Они боятся тебя едва ли не больше, чем своего собственного безликого Кровавого бога. Ты уничтожил множество приспешников Хаккара с помощью силы Каджаро.","","Пришло время усилить камень. Дай мне свой талисман."}}
D[8104] = {"Самоцвет Каджаро",{"Дай мне свой талисман, Вертекс. Я покажу тебе кое-что."}}
D[8105] = {"Битва за Низину Арати",{"Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт."}}
D[8106] = {"Ожерелье Кезанского порока",{"Прими этот талисман, |3-6(Чернокнижник). Используй его силу, чтобы уничтожить наших общих врагов.","","Знай, что он – частичка нашей истории. В свое время Кезан был частью огромной Зандаларской империи. К сожалению, гоблины выжили оттуда моих братьев и сестер...","","Теперь в Кезане находится столица гоблинов Нижняя шахта, а ведь в давние времена он славился своим величием! До сих пор Кезан считается нашей священной землей."}}
D[8107] = {"Ожерелье Кезанского порока",{"В Зандаларе уважение следует заслужить, Фронгли. Тролли предлагают свою дружбу и заключают союзы только с теми, кого они уважают.","","Дай мне свой талисман, я наполню его силой."}}
D[8108] = {"Ожерелье Кезанского порока"}
D[8109] = {"Ожерелье вечного Кезанского порока",{"Призови своих демонов, |3-6(Чернокнижник). Пусть энергия Кезанского порока напитает их. Придет время, и ты сможешь использовать их на поле боя, чтобы уничтожить своих врагов.","","Да... Пришло время окончательно улучшить ожерелье Кезанского порока. Дай мне свой талисман."}}
D[8110] = {"Зачарованные водоросли Южных морей",{"Видишь эти водоросли, золотце? Они из Южных морей. Мы всего лишь добавили немного заклинаний и немного магии, чтобы они лучше служили своему владельцу.","","Ты ведь |3-6(Друид), так что для тебя это будет совсем просто. Оберни их вокруг шеи и подумай о птичках, белочках – в общем, о чем-нибудь для тебя приятном."}}
D[8111] = {"Зачарованные водоросли Южных морей",{"Привет, непоседа! Приятно тебя видеть снова. В племени только и разговоров, что о твоих победах в Зул-Гурубе. Молтор обмолвился, что неплохо бы добавить силы твоему талисману. Дай-ка его Майвики, посмотрим, сможет ли она его улучшить."}}
D[8112] = {"Зачарованные водоросли Южных морей",{"Как себя чувствует твой талисман, золотце? Похоже, пришло время добавить немного магии и колдовства в его листья... А то что-то они поникли. Дай-ка мне его, Майвики сейчас все исправит."}}
D[8113] = {"Безупречные зачарованные водоросли Южных морей",{"Давно не виделись, Антизог! Известно ли тебе, что сам король Растахан приказал добавить последний магический штрих к твоему талисману? Да-да, именно так! Я бы не поверила, если бы не слышала собственными ушами. Давай талисман сюда."}}
D[8114] = {"Контроль над четырьмя базами",{"Отправляйтесь в низину Арати, захватите и удержите контроль над четырьмя базами одновременно, затем возвращайтесь к фельдмаршалу Освету в Опорный пункт."}}
D[8115] = {"Контроль над пятью базами",{"Возьмите под контроль одновременно все 5 баз в низине Арати, а затем возвращайтесь к фельдмаршалу Освету в Опорный пункт."}}
D[8116] = {"Ожерелье видений Вудресса",{"У тебя есть много общего со старой Майвики, золотце. Мы оба – шаманы! Правда, Майвики больше занимается мистикой, а ты в основном выполняешь за других грязную работу. Зато мы оба знаем, что могут даровать великие духи.","","Я дам тебе этот шар, носи его на шее. Загляни в него, и увидишь деревню Вудресс в Южных морях. Пусть это укрепит твой дух!"}}
D[8117] = {"Ожерелье видений Вудресса"}
D[8118] = {"Ожерелье видений Вудресса"}
D[8119] = {"Незамутненное ожерелье видений Вудресса"}
D[8120] = {"Битва за Низину Арати",{"Захватите рудник, лесопилку, кузницу и стойла и возвращайтесь к повелительнице смерти Двайр в Павший Молот."}}
D[8121] = {"Захват четырех баз",{"Удерживайте одновременно четыре базы в низине Арати, а затем возвращайтесь к повелительнице смерти Двайр в Павший Молот."}}
D[8122] = {"Занять пять баз",{"Захватите и удерживайте все пять баз в низине Арати, затем возвращайтесь к повелительнице смерти Двайр в Павший Молот."}}
D[8123] = {"Перекрыть линии поставок Аратора",{"Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот."}}
D[8124] = {"Новые ящики с ресурсами"}
D[8141] = {"Зандаларский талисман тени",{"Ты быстро растешь, юный |3-6(Разбойник). Пришло время принять тебя в Шера Алик. На нашем языке это название означает \"Рука смерти\". Тысячи лет мы были наемными убийцами Зандаларской империи. Слишком долго мы сидели сложа руки и смотрели, как Хаккар набирает силу. Настала пора сразиться с ним, но теперь за нами нет объединенных сил троллей. Только ты и подобные тебе могут помочь нам в борьбе с Кровавым богом и его приспешниками.","","Носи этот талисман, и пусть он поможет тебе в твоих странствиях."}}
D[8142] = {"Зандаларский талисман тени"}
D[8143] = {"Зандаларский талисман тени"}
D[8144] = {"Зандаларский талисман власти над тенями"}
D[8145] = {"Нить Водоворота",{"В Зандаларе профессия охотника весьма уважаема. Наши лучшие охотники уплывают к самому краю Водоворота, чтобы доказать свою отвагу.","","Там, в сердце моря, они добывают водоросль, известную как \"нить Водоворота\". Из нее плетут талисманы, увеличивающие силу и меткость.","","Я дам тебе одну нить Водоворота. По мере того как будет расти твоя связь с Зандаларом, я буду вплетать новые нити в твой талисман."}}
D[8146] = {"Нить Водоворота"}
D[8147] = {"Нить Водоворота"}
D[8148] = {"Ярость Водоворота"}
D[8149] = {"Почести герою",{"Пойдите к гробнице Утера в Западных Чумных землях, положите подношения у подножия его статуи и вернутсья к Вагнеру Молотобойцу в Стальгорн до конца Недели урожая."}}
D[8150] = {"Почести герою",{"Отправляйтесь к памятнику Грому Зычногласому в Каньон Гибели Демона в Ясеневом лесу и положите подношения у подножия памятника. Вернитесь к Явниру Нашаку в Оргриммар до конца Недели урожая."}}
D[8151] = {"Талисман охотника",{"Поговорите с Огтинком из Азшары."}}
D[8153] = {"Рога и копыта",{"Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}}
