D[8383] = {"Помни Альтеракскую долину!",{"Битва в Альтеракской долине идет, не утихая! Давно ли ты вступал в бой, Драккард?"}}
D[8384] = {"Завоевание Низины Арати"}
D[8385] = {"В едином порыве",{"А, Хлуси. Я надеюсь, что ты еще не раз вступишь в бой на разных полях битвы. Многие юноши и девушки стараются подражать закаленным бойцам вроде тебя."}}
D[8386] = {"Битва за ущелье Песни Войны"}
D[8387] = {"Вторжение в Альтеракскую долину",{"Битва за Альтерак продолжается! Возвращайся в Альтеракскую долину и выгони наглых захватчиков с исконных земель клана Северного Волка, Ксаер!"}}
D[8388] = {"Великая честь",{"Многие храбрые воины стараются брать с тебя пример, бросаясь в бой против Альянса. Что нового тебе встретилось в странствиях?"}}
D[8389] = {"Битва за ущелье Песни Войны",{"Битва в Ущелье Песни Войны идет, не прекращаясь. Внеси свой вклад в изгнание часовых из клана Среброкрылых с наших земель!"}}
D[8390] = {"Завоевание Низины Арати"}
D[8391] = {"Завоевание Низины Арати"}
D[8392] = {"Завоевание Низины Арати",{"У нас подходят к концу все припасы, Огневар. Нам не выстоять против Орды, если мы не захватим Низину Арати. Эта низина – настоящая кладовая природы. Ты уже внес свой вклад в борьбу за нее?"}}
