D[8409] = {"Поломанные бочки",{"Вернитесь к Янке Зовущей Тьму на фестиваль Плетеного человека на Тирисфальских лугах."}}
D[8410] = {"Покорение стихий",{"Соберите образцы воздуха, огня, земли и воды по поручению Бат'ры Ветростража."}}
D[8411] = {"Покорение Стихий",{"Принесите стихии Земли, Воздуха, Огня и Воды Бат'ре Ветростражу."}}
D[8412] = {"Тотем духов",{"Принесите части тотема Духа Бат'ре Ветростражу."}}
D[8413] = {"Вуду",{"Принесите вудуистские перья Бат'ре Ветростражу."}}
D[8414] = {"Борьба со злом",{"Принесите 20 камней Плети приспешников верховному жрецу Тель'данису в Западные Чумные земли."}}
D[8415] = {"Лагерь Промозглого Ветра",{"Обратитесь к командиру Ашламу Отважному Кулаку в Лагерь Промозглого Ветра."}}
D[8416] = {"Бездействующие камни Плети",{"Отнесите бездействующий камень командиру Асламу Отважному Кулаку на Берег Промозглого Ветра."}}
D[8417] = {"Неупокоенный дух",{"Поговорите с павшим героем Орды у входа в Выжженные земли."}}
D[8418] = {"Создание камня силы",{"Принесите вудуистские перья Ашламу Отважному Кулаку."}}
D[8419] = {"Просьба беса",{"Принесите отрез ткани Скверны Бесенку в Оскверненный лес."}}
D[8420] = {"Пробирает!",{"Принесите отрез ткани Скверны Бесенку в Оскверненный лес."}}
D[8421] = {"Бросовый материал",{"Принесите 10 кусков гнилой древесины и 4 порции экстракта Отравленной Крови Бесенку в Оскверненный лес."}}
D[8422] = {"Тролли Пера",{"Принесите 6 вудуистских перьев троллей из затонувшего храма."}}
D[8423] = {"Воинское испытание",{"Убейте 7 зловепрей в Выжженных землях и вернитесь к павшему герою Орды."}}
D[8424] = {"Война против Приверженцев Тени",{"Убейте приверженцев тени в Выжженных землях и вернитесь к павшему герою Орды."}}
D[8425] = {"Вудуистские перья",{"Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем храме."}}
