D[8440] = {"Завоевание Низины Арати",{"Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине битвы. Низина Арати должна отойти к нам!"}}
D[8441] = {"Завоевание Низины Арати",{"Нам не выиграть войну против презренного Альянса без снабжения! Не позволим нашим складам опустеть к середине сражения. Низина Арати должна отойти к нам!"}}
