D[8703] = {"Кольцо Вечной справедливости",{"Принесите киражское кольцо власти, 2 багровых идола, 5 серебряных и 5 костяных скарабеев Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария."}}
D[8704] = {"Перстень Незримого пути",{"Принесите киражское церемониальное кольцо, 2 янтарных идола, 5 золотых и 5 глиняных скарабеев Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария."}}
D[8705] = {"Чекан Беспредельной мудрости",{"Принесите киражскую изысканную рукоять, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8706] = {"Молот надвигающейся бури",{"Принесите киражскую шипастую рукоять, 2 янтарных идола, 5 скарабеев из слоновой кости и 5 бронзовых скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8707] = {"Клинок Погребенных тайн",{"Принесите киражскую изысканную рукоять, 2 обсидиановых идола, 5 серебряных и 5 костяных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8708] = {"Палица Бесконечной жизни",{"Принесите киражскую изысканную рукоять, 2 яшмовых идола, 5 хрустальных и 5 каменных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8709] = {"Кинжал Скрытых Теней",{"Принесите киражскую шипастую рукоять, 2 багровых идола, 5 золотых и 5 глиняных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8710] = {"Крис Неназванных имен",{"Принесите киражскую изысканную рукоять, 2 ониксовых идола, 5 золотых и 5 глиняных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8711] = {"Клинок Вечной справедливости",{"Принесите киражскую шипастую рукоять, 2 янтарных идола, 5 бронзовых скарабеев и 5 скарабеев из слоновой кости Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8712] = {"Коса Незримого пути",{"Принесите киражскую шипастую рукоять, 2 лазурных идола, 5 серебряных и 5 каменных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария."}}
D[8713] = {"Старейшина Звездная Песня",{"В небесах, в бессчетных созвездиях, записана разгадка всех наших земных тайн. Смогут ли мудрые – и удачливые – обратить взор к небесной тверди и узнать правду?"}}
