D[9198] = {"Задание мастера: ториевая труба",{"Доставьте 14 ториевых труб и соответствующее задание мастера караванщику Камнетесу в часовню Последней Надежды в Восточные Чумные земли."}}
D[9199] = {"Джуджу троллей",{"Соберите 8 джуджу троллей и принесите их стражу смерти Малтендису в Транквиллион в Призрачных землях."}}
