D[9303] = {"Прививка",{"Сделайте прививку шести совунам с Совиных холмов при помощи особого кристалла. Затем вернитесь к воздаятелю Алдару на место крушения в долине Аммен."}}
D[9304] = {"Документ с фронта",{"Отнесите испачканный документ хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9305] = {"Запасные части",{"Соберите 4 запчасти для передатчика и отнесите их технику Жанае на место крушения в долине Аммен."}}
D[9309] = {"Пропавший разведчик",{"Найдите Толаана у хребта Теней в долине Аммен и поговорите с ним."}}
D[9310] = {"Тусклый некротический кристалл",{"Отнесите тусклый некротический кристалл лейтенанту Рукагу во внутренний двор Подгорода."}}
D[9311] = {"Шпион эльфов крови",{"Убейте геодезиста Кандресс и расскажите о случившемся воздаятелю Алдару на месте крушения в долине Аммен."}}
