D[9315] = {"Анок'сутен",{"Убейте Анок'сутен и возвращайтесь к чародею Вандрилу в Транквиллион, что в Призрачных землях."}}
D[9317] = {"Освященное точило",{"Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича."}}
D[9318] = {"Благословенное волшебное масло",{"В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла."}}
D[9319] = {"Свет в темных местах",{"Найдите костры, размещенные в пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени."}}
D[9320] = {"Сильнейшее зелье маны",{"Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун."}}
D[9321] = {"Хорошее лечебное зелье"}
D[9322] = {"Костры Калимдора",{"Посетите лагеря праздника Огненного солнцеворота, размещенные в Азшаре, Силитусе, Кратере Ун'Горо и Зимних Ключах, затем вернитесь к хранителю праздничного пламени."}}
D[9323] = {"Костры Восточных королевств",{"Посетите лагеря Праздника Огня, размещенные в Выжженных землях, Восточных Чумных землях, во Внутренних землях и Тлеющем ущелье, затем поговорите с хранителем праздничного пламени."}}
D[9324] = {"Похищение пламени Оргриммара",{"Верните Пламя Оргриммара хранителю мудрости Праздника."}}
D[9325] = {"Похищение пламени Громового Утеса",{"Верните Пламя Громового Утеса хранителю мудрости Праздника."}}
D[9326] = {"Похищение пламени Подгорода",{"Верните Пламя Подгорода хранителю мудрости Праздника."}}
D[9327] = {"Отрекшиеся",{"Поговорите с верховным вершителем Мавреном в Транквиллионе, что в Призрачных землях."}}
D[9328] = {"Герой син'дорай",{"Принесите голову Дар'Хана Лор'темару Терону в Луносвет."}}
D[9329] = {"Отрекшиеся",{"Поговорите с верховным вершителем Мавреном в Транквиллионе, что в Призрачных землях."}}
D[9330] = {"Похищение пламени Штормграда",{"Верните Пламя Штормграда Праздничному Сказителю."}}
D[9331] = {"Похищение пламени Стальгорна",{"Верните Пламя Стальгорна Праздничному Сказителю."}}
D[9332] = {"Похищение пламени Дарнасса",{"Верните пламя Дарнасса праздничному сказителю."}}
D[9333] = {"Перчатки Серебряного Рассвета",{"Если принесешь мне тридцать некротических рун, я подарю тебе защитные перчатки для рук, по твоему выбору. Они оказались очень ценными в борьбе против нежити Плети"}}
D[9334] = {"Благословенное волшебное масло",{"В обмен на некротические руны Плети Серебряный Рассвет дарует тебе один фиал благословенного волшебного масла."}}
D[9335] = {"Освященное точило",{"Если ты принесешь мне восемь некротических рун, отобрав их у захватчиков из Плети, я дам тебе освященное точило. Оно способно помочь тебе в борьбе против приспешников Короля-лича."}}
D[9336] = {"Хорошее лечебное зелье"}
D[9337] = {"Сильнейшее зелье маны",{"Помимо других поставок, у нас есть немного сильнейших зелий маны, которые могут тебе пригодиться. Я дам тебе одну порцию зелья в обмен на пятнадцать некротических рун."}}
D[9338] = {"Верность Кругу Кенария"}
D[9339] = {"Награда вора"}
D[9340] = {"Глубокий Разлом",{"Ступайте на восток от Соколиного дозора, к Глубокому разлому, и убейте 8 детенышей камнеруба и 3 камнерубов-вожаков по приказу капитана следопытов Венн'рена."}}
D[9341] = {"Гербовая накидка Серебряного Рассвета",{"Твоя помощь в нашем деле была очень ценной, Трансмастер. Если пожелаешь, я могу сделать так, что ты получишь гербовую накидку Серебряного Рассвета. Мы гордимся тем, что ты в числе наших союзников."}}
D[9342] = {"Хищный землерой",{"Убейте 15 хищных землероев по просьбе штейгера Разлкраза. Эти черви предпочитают нападать неожиданно, из-под земли."}}
D[9343] = {"Гербовая накидка Серебряного Рассвета"}
D[9344] = {"Поспешный отъезд",{"Разыщите Грелага, ученика провозвестницы Регулкут."}}
D[9345] = {"Изготовление мази",{"Соберите 12 листьев пламенного шиполиста и возвращайтесь к Грелагу на Заставу Хребтолома."}}
D[9346] = {"Зловепрь – птица гордая",{"Принесите командиру стражи Кранку из Траллмара 10 раздутых трупов голодных зловепрей."}}
D[9349] = {"Сбор яиц опустошителей",{"Принесите 12 яиц опустошителей Легасси на место крушения дирижабля на полуострове Адского Пламени."}}
D[9351] = {"Дикие демоны Бездны",{"Принесите 10 конденсированных сущностей демона Бездны \"Крикуну\" Скриду Многослову на место крушения дирижабля."}}
D[9352] = {"Вторжение из Дарнасса",{"Отправляйтесь в Западное святилище, к юго-западу от площади Соколиных Крыльев, и уничтожьте всех чужаков, которых вы там встретите. Затем сообщите о результатах хранительнице энергии Велании."}}
D[9355] = {"Работа для сообразительных",{"Убейте 15 хищных землероев и возвращайтесь к штейгеру Большие Десны в Оплот Чести."}}
D[9356] = {"Летать как птица",{"Принесите 12 мясистых крыльев канюка Легасси на место крушения дирижабля."}}
D[9357] = {"Задание Аэльдона Озаренного Солнцем",{"Поговорите с Аэльдоном Озаренным Солнцем у Внутренних эльфийских ворот в Лесах Вечной Песни."}}
D[9358] = {"Следопыт Сарейн",{"Поговорите со следопытом Сарейн у деревни Легкий Ветерок, что в лесах Вечной Песни."}}
D[9359] = {"Обитель Странников",{"Поговорите с лейтенантом Вестницей Зари в обители Странников, что в лесах Вечной Песни."}}
D[9360] = {"Вторжение племени Амани",{"Доставьте планы вторжения племени Амани лейтенанту Вестнице Зари в обитель Странников."}}
D[9361] = {"Зловепрь – тоже мясо",{"Легасси требует принести ему 8 кусков мяса зловепря на место крушения дирижабля. Убейте зловепря, добудьте порченое мясо зловепря, а затем очистите его с помощью микстуры очищения."}}
D[9362] = {"Полководец Креллиан",{"Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары."}}
D[9363] = {"Предупреждение деревне Легкий Ветерок",{"Отправляйтесь в деревню Легкий Ветерок в лесах Вечной Песни и поговорите со следопытом Деголиеном."}}
D[9364] = {"Частицы магии",{"Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару."}}
D[9365] = {"Награда вора"}
D[9366] = {"Оскверненная кровь",{"Принесите 6 образцов оскверненной крови исчадий ужаса, обитающих у прудов Аггонара, Риатену Мрачному из Соколиного дозора на полуострове Адского Пламени."}}
D[9367] = {"Праздник Огня",{"Прикоснитесь к пламени праздничных костров в Штормграде, Стальгорне и Дарнассе, затем поговорите с хранителем мудрости праздника в столичных городах."}}
D[9368] = {"Праздник Огня",{"Прикоснитесь к пламени праздничных костров в Оргриммаре, Громовом Утесе и Подгороде, затем поговорите с Праздничным сказителем в столичных городах."}}
D[9369] = {"Исцеляющие кристаллы",{"Добудьте 8 фиалов с кровью мотылька из долинных мотыльков и принесите их Проэнитусу на место крушения в долине Аммен."}}
D[9370] = {"Остановить очищение",{"Поставьте сигнальный самоцвет на алтарь Аггонара, рядом с прудами Аггонара, и уничтожьте дренейского анахорета и всех, кто явится на сигнал. После выполнения задания заберите самоцвет и возвращайтесь к Риатену Мрачному в Соколиный дозор."}}
D[9371] = {"Ботаник Таэрикс",{"Поговорите с ботаником Таэрикс на месте крушения в долине Аммен."}}
D[9372] = {"Распространение демонической скверны",{"Соберите 6 образцов крови зловепря у крупных зловепрей по просьбе Тии Рыжей Гривы с Кенарийской заставы на полуострове Адского Пламени."}}
D[9373] = {"Потерянное послание",{"Доставьте подпорченный кожаный чехол Тие Рыжей Гриве, которая стоит лагерем рядом с руинами Ша'наара на западе полуострова Адского Пламени."}}
D[9374] = {"Записи Арелиона",{"Отправляйтесь к прудам Аггонара и найдите записи Арелиона по просьбе магистра Каринды из Соколиного дозора на полуострове Адского Пламени."}}
D[9375] = {"Дорога к Соколиному дозору",{"Помогите израненной эльфийке крови – пилигриму добраться до Соколиного дозора, затем поговорите с Талерисом Созерцателем Рассвета."}}
D[9376] = {"Скарб пилигрима",{"Перозубые опустошители напали на израненную эльфийку крови – пилигрима, когда она остановилась в Лощине Пыльного Пера. Разыщите ее стоянку и потерянные вещи."}}
D[9378] = {"DND FLAG Цитадель ужаса – Наксрамас",{"Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова бесплатно наложить на вас заклинание чародейского покрова. Вы должны заслужить полное доверие Серебряного Рассвета."}}
D[9380] = {"В погоне за большим",{"Соберите 6 неповрежденных трупов астральных гончих и доставьте в Оплот Чести геологу Мурантусу."}}
D[9381] = {"Стрелы, бьющие без промаха",{"Принесите 8 хвостовых перьев стервятника-костеклюя сокольничему Дренне Речной Ветер в Соколиный дозор."}}
D[9382] = {"Жестокий рок копытня",{"Убейте 15 щетинистых копытней и возвращайтесь к Амаану Мудрейшему в Храм Телхамата."}}
D[9383] = {"Честолюбивый план",{"Используйте освященный кристалл против раненого неконтролируемого демона Бездны, затем возвращайтесь к Элсаане в храм Телхамат."}}
D[9385] = {"Разъяренные Опустошители",{"Убейте 10 перозубых опустошителей и возвращайтесь к Гремни Длиннобороду на полуострове Адского Пламени."}}
D[9386] = {"Свет в темных местах",{"Найдите костры, размещенные в пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени."}}
D[9387] = {"Источник порчи",{"Отправляйтесь в руины Ша'наара на полуострове Адского Пламени и добудьте из иллидари-надсмотрщиков 5 демонических сущностей. После завершения задания возвращайтесь к аптекарю Азетену в Соколиный дозор."}}
D[9388] = {"Мерцающие огни Калимдора",{"Посетите праздничные костры в Ясеневом лесу, Степях, на Темном Берегу и в Когтистых горах, затем поговорите с хранителем праздничного пламени."}}
D[9389] = {"Мерцающие огни Восточных королевств",{"Посетите праздничные костры в предгорьях Хиллсбрада, в Серебряном бору, Западном Крае и Болотине, затем поговорите с хранителем праздничного пламени."}}
D[9390] = {"Найти Седаи",{"Разыщите Седаи, брата анахорета Обадия. Седаи может находиться где-то поблизости, на востоке, на полуострове Адского Пламени."}}
D[9391] = {"Осветить путь",{"Отправляйтесь к Глубокому разлому на полуострове Адского Пламени и зажгите южный маяк, западный маяк и центральный маяк. После выполнения задания возвращайтесь к капитану следопытов Венн'рену из Соколиного дозора вместе с зажженным факелом."}}
D[9392] = {"Обучение разбойника",{"Поговорите с наставником разбойников следопытом Кариэлем в Солнечном Шпиле на острове Солнечного Скитальца."}}
D[9393] = {"Обучение охотника",{"Поговорите с следопытом Саллиной в Солнечном Шпиле на острове Солнечного Скитальца."}}
D[9394] = {"Куда подевался Виллитен?",{"Найдите смотрителя Виллитена в землях Блеклых Сумерек, что в лесах Вечной Песни."}}
D[9395] = {"Вилла Салтерила",{"Поговорите с лордом Салтерилом на вилле Салтерила в лесах Вечной Песни."}}
D[9396] = {"Магия араккоа",{"Принесите 4 свитка племени Хаал'эш чародею Калестрису Утренней Звезде в Соколиный дозор на полуострове Адского Пламени."}}
D[9397] = {"Пух и перья",{"Отправляйтесь в логово Хаал'эш на полуострове Адского Пламени и найдите молодую самку калири в гнезде калири. Посадите птенца в пустую клетку и принесите сокольничему Дренне Речной Ветер в Соколиный дозор."}}
D[9398] = {"Смертельно опасные хищники",{"Убейте 8 детенышей камнеруба и 4 камнерубов-вожаков по просьбе разведчицы Вануры из храма Телхамат на полуострове Адского Пламени."}}
D[9399] = {"Безжалостные десятники",{"Убейте 4 иллидари-надсмотрщиков на руинах Ша'наара и возвращайтесь к Икану в храм Телхамат на полуострове Адского Пламени."}}
D[9400] = {"Убийца",{"Ступайте по дороге к северу от цитадели Адского Пламени и разыщите убийцу по имени Крун Хребтолом по просьбе Назгрела."}}
D[9401] = {"Странное оружие",{"Принесите тяжелый каменный топор Назгрелу в Траллмар на полуострове Адского Пламени."}}
D[9402] = {"Апорт!",{"Нырните на дно пруда Тихого Шелеста и добудьте лазурный фиал для инструктора Антеола."}}
D[9403] = {"Чистейшая вода",{"Наполните лазурный флакон водой из водопада Элрендар для Антеола."}}
D[9404] = {"Живая ветка",{"Убивайте хранителей лесов Вечной Песни, пока не найдете животворную ветвь для инструктора Антеола."}}
D[9405] = {"Поручение Вождя",{"Принесите тяжелый каменный топор провозвестнице Регулкут в Траллмар на полуострове Адского Пламени."}}
D[9406] = {"Маг'хары",{"Доставьте письмо маг'харов Назгрелу в Траллмар на полуострове Адского Пламени."}}
D[9407] = {"Через Темный портал",{"Пройдите через Темный портал и найдите генерал-лейтенанта Ориона. Он ждет вашего прибытия на другой стороне, в Запределье."}}
D[9408] = {"Забытые герои",{"Поговорите с командиром армии Данатом Троллебоем в Оплоте Чести."}}
D[9409] = {"Срочная доставка",{"Отнесите сверток с фиалами Залдууну на место крушения в долине Аммен."}}
D[9410] = {"Хранитель душ",{"Установите тотем духа волка на том месте, где вы нашли тело Круна Хребтолома. Когда появится дух древнего волка, следуйте за ним."}}
D[9415] = {"Маршал Синяя Синестен",{"Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора."}}
D[9416] = {"Генерал Кирика",{"Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал."}}
D[9417] = {"Угроза Араккоа",{"Убейте 4 ветроступов и 6 коготарей из племени Хаал'эш по просьбе Гремни Длинноборода с полустрова Адского Пламени."}}
D[9418] = {"Сфера Авруу",{"Отнесите сферу Авруу на алтарь племени Хаал'эш, который находится на юго-востоке от логова Хаал'эш на полуострове Адского Пламени. После того как Аэранас обретет свободу, отдайте ему сферу."}}
D[9419] = {"Истощение пустыни",{"Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора."}}
D[9420] = {"Прекрасное оперение",{"Принесите Миррену Длиннобороду на полуострове Адского Пламени 8 перьев калири от различных калири из логова Хаал'эш."}}
D[9421] = {"Обучение шамана",{"Я Фирманваар. Ты не зря пришел ко мне. Мое призвание - учить молодых шаманов, особенно тех, что лишь теперь ступают на этот путь.","","Дренеи заново открывают для себя шаманизм, Шамакс. Избрание не самого накатанного пути требует особого мужества.","","Я с радостью помогу тебе, как только ты сочтешь, что пришло время снова поучиться."}}
D[9422] = {"Истощение пустыни",{"Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал."}}
D[9423] = {"Возвращение к Обадию",{"Возвращайтесь к анахорету Обадию в храм Телхамат на полуострове Адского Пламени и расскажите о смерти Седаи."}}
D[9424] = {"Месть Макуру",{"Принесите 10 ожерелий предков маг'харов Макуру в храм Телхамат на полуострове Адского Пламени."}}
D[9425] = {"Возвращение в Мельницу Таррен",{"Отправляйтесь в Мельницу Таррен в предгорьях Хилсбрада и поговорите с советником Вечерней Зарей."}}
D[9426] = {"Пруды Аггонара",{"Отправляйтесь к прудам Аггонара и убейте 6 исчадий ужаса и 6 волдырных гнилостней по просьбе Амаана Мудрого."}}
D[9427] = {"Очищение вод",{"Отправляйтесь к прудам Аггонара и используйте фиал очищения над телом Аггонара по просьбе Амаана Мудрого. После того как вода будет очищена от сущности Аггонара, возвращайтесь обратно к Амаану."}}
D[9428] = {"На заставу Расщепленного Дерева",{"Поговорите с советником Верным Солнцу на заставе Расщепленного Дерева в Ясеневом лесу."}}
D[9429] = {"Путешествие в Темнолесье",{"Поговорите с анахоретом Деланом в городе Темнолесье в Сумеречном лесу."}}
D[9430] = {"Реликвии Ша'наара",{"Отправляйтесь в руины Ша'наара и соберите 10 реликвий Ша'наара по просьбе Амаана Мудрого из храма Телхамат на полуострове Адского Пламени."}}
D[9431] = {"Разный подход",{"Соберите 2 горсти очищающей земли с грохочущих камнедоров и отнесите Визло Фингалету на заставу Белого Плеса."}}
D[9432] = {"Дорога в Астранаар",{"Отправляйтесь в Астранаар в Ясеневом лесу и поговорите с воздаятельницей Паланаарой."}}
D[9433] = {"Проба из лунного колодца",{"На каменной игле, ближайшей к границе с Таланааром, в кустах спрятано устройство управления Роботроном 3000. Найдите ее и включите робота при помощи устройства, которое вам дал Визло. Подведите робота к западному краю Тысячи Игл, где находится застава Альянса под названием Таланаар, и прикажите ему набрать немного воды из лунного колодца, после чего вернитесь к Визло Фингалету на заставу Белого Плеса."}}
D[9434] = {"Испытание тоника",{"Доставьте ящик с реагентами магистра Элозай на Заставу Вольного Ветра."}}
D[9435] = {"Пропавшие кристаллы",{"Отберите у нежити посылку с редкими кристаллами и верните ее Ураану из Южнобережья."}}
D[9436] = {"Изучение Кровавого Скальпа",{"Немет Остроглаз из лагеря Гром'гол попросил вас принести ему тотем Кровавого Скальпа, добыв его у шамана из племени Кровавого Скальпа."}}
D[9437] = {"Сумерки \"Гонца Рассвета\"",{"Верните груз с \"Гонца Рассвета\" Балиндару Ясной Звезде в деревню Гиблотопь и спасите его первого помощника Итанию из рук тераморцев, из Северной башни."}}
D[9438] = {"Донесение Траллу",{"Отправляйтесь в Оргриммар и доставьте Траллу письмо Назгрела."}}
D[9439] = {"Потерянный багаж",{"Верните советнику Сарофасу в Каргат вещи советника и рапиру советника из Крепости Ангор."}}
D[9440] = {"Маленькие кусочки",{"Накормите испорченными кусочками мяса домашний скот Заблудших. Потом верните отстатки Серсее Певице Заката в Каменор на Болото Печали."}}
D[9441] = {"Посол к маг'харам",{"Вернитесь к Горкану Кровопалу на заставу маг'харов на полуострове Адского Пламени и предложите ему свои услуги."}}
D[9442] = {"Изнуряющая слабость",{"Принесите гриб-сухошляпку заклинательнице земли Риге с заставы маг'харов на полуострове Адского Пламени. Сухошляпки растут только в пещере внутри Глубокого разлома."}}
D[9443] = {"Так называемый знак Светоносного",{"Добудьте знак Светоносного и принесите его Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях."}}
D[9444] = {"Осквернение гробницы Утера",{"Оскверните гробницу Утера и возвращайтесь к Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях."}}
D[9446] = {"Гробница Светоносного",{"Проводите анахорета Трууна к гробнице Утера в Западные Чумные земли. После поговорите с верховной жрицей Макдонелл из Лагеря Промозглого Ветра."}}
D[9447] = {"Применение целебной мази",{"Нанесите целебную мазь на 10 изнуренных маг'харских рубак рядом с заставой маг'харов на полуострове Адского Пламени по просьбе заклинательницы земли Риги."}}
D[9448] = {"Милость к проклятым",{"Убейте 3 проклятых из племени Заблудших, потом вернитесь к анахорету Авууну в Убежище на Болото Печали."}}
D[9449] = {"Зов земли",{"Поговорите с духом долины в Священной роще в долине Аммен."}}
D[9450] = {"Зов земли",{"Убейте 4 неупокоенных духов земли и возвращайтесь к духу долины в Священную рощу в долине Аммен."}}
D[9451] = {"Зов земли",{"Отнесите кристалл Земли Фирманваару на место крушения в долине Аммен."}}
D[9452] = {"Деликатесный красный луциан",{"Поймайте 10 красных луцианов рыболовной сетью дренеев. Отдайте рыбу и сеть Диктинне на острове Лазурной Дымки."}}
D[9453] = {"Поиски Актеона",{"Отнесите ящик красного луциана Актеону на Лазурную заставу."}}
D[9454] = {"Великая охота на лунных оленей",{"Принесите 6 кусков вырезки лунного оленя Актеону на Лазурную заставу."}}
D[9455] = {"Странные находки",{"Отнесите слабо мерцающий кристалл экзарху Менелаусу на Лазурную заставу."}}
D[9456] = {"Истребление ночных ловцов, остров 2...",{"Уничтожьте 8 зараженных ночных ловцов – недоростков и вернитесь на Лазурную заставу."}}
D[9457] = {"Необычный посетитель",{"Воспользуйтесь даром Найаса неподалеку от алтаря Найаса и призовите этого элементаля воды. Одолейте его и принесите сердце Найаса Немету Остроглазу в лагерь Гром'гол."}}
D[9460] = {"Объединенными усилиями",{"Украдите у предводительницы часовых кружевной носовой платок и принесите его Келтусу Темному Листу."}}
D[9461] = {"Зов огня",{"Найдите пророка Велена в Чертоге Света Экзодара."}}
D[9462] = {"Зов огня",{"Поговорите с Тулууном на Лазурной заставе на острове Лазурной Дымки."}}
D[9463] = {"Ради науки",{"Принесите 8 побегов корнехватов анахоретке Фатиме на Лазурную заставу."}}
D[9464] = {"Зов огня",{"Поговорите с Пламенравом на Тлеющей поляне на острове Лазурной Дымки."}}
D[9465] = {"Зов огня",{"Верните ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки."}}
D[9466] = {"Разыскивается: Свирепая Черноскребка",{"Принесите когти Черноскребки капитану следопытов Венн'рену в Соколиный дозор на полуострове Адского Пламени."}}
D[9467] = {"Зов огня",{"Добудьте пепел Спесивца и принесите его и ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки. Вы можете воспользоваться сферой возвращения, чтобы телепортироваться к Пламенраву."}}
D[9468] = {"Зов огня",{"Отнесите пепел Спесивца Тулууну на Лазурную заставу на острове Лазурной Дымки."}}
D[9469] = {"Встреча с Перобородом",{"Навестите дворфа Пероборода в его лачуге. Если его нет дома, то поищите, где он может быть."}}
D[9470] = {"Жест доброй воли",{"Убейте знахаря Май'джина и его питомца-паука Чаказа по поручению посла Руалета с Заоблачного пика."}}
D[9471] = {"Охота на хищников",{"Убейте 10 облезлых среброгривов и 5 среброгривых волков по поручению посла Руалета с Заоблачного пика."}}
D[9472] = {"Любовница Арелиона",{"Выманите Виеру Шепот Солнца из поселения и примените к ней свиток воздаяния Каринды по приказу магистра Каринды из Соколиного дозора."}}
D[9473] = {"Другое решение",{"Принесите 5 луковиц лазурного львиного зева Дедалу на Лазурную заставу."}}
D[9474] = {"Знак Светоносного",{"Добудьте знак Светоносного и принесите его анахорету Трууну в Лагерь Промозглого Ветра, что Западных Чумных землях."}}
D[9475] = {"Похищенные яйца",{"Соберите 5 яиц грифона и принесите их послу Руалету на Заоблачный пик."}}
D[9476] = {"В поисках Пероборода",{"Отправляйтесь в Шадра'Алор и поищите следы Пероборода."}}
D[9483] = {"Изысканные удовольствия жизни",{"Мы, конечно, отправились в паломничество, но это вовсе не значит, надо отказываться от всех радостей жизни. Кажется, прошло столетие с той поры, как я пробовала хорошее вино.","","Да за бутылку кенарийского настойки я и убить могу!","","Знаю, знаю, я очень опустилась, если готова пить вино ночных эльфов."}}
D[9484] = {"Приручение зверя",{"Приручите безумного дракондора с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Рассвета."}}
D[9485] = {"Приручение зверя",{"Приручите мрачницу с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Рассвета."}}
D[9486] = {"Приручение зверя",{"Приручите взрослого прыголапа с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Рассвета."}}
D[9487] = {"Волшебные разорители",{"Чародей Вандрил хочет, чтобы вы принесли ему 10 осколков тайной магии."}}
D[9488] = {"Простое одеяние",{"Чародей Вандрил хочет, чтобы вы принесли ему 15 кусков льняной ткани и паутинную железу паука-прядильщика."}}
D[9489] = {"Поднять боевой дух",{"Примените \"Слово Силы: Стойкость\" к 6 следопытам из лесов Вечной Песни на Тропе Мертвых."}}
D[9490] = {"Матриарх камнедеров",{"Добудьте когти Свирепой Черноскребки, которая обитает в Глубоком Разломе и принесите их Икану в храм Телхамат на полуострове Адского Пламени."}}
D[9491] = {"Не откажусь",{"Эраланна из Транквиллиона хочет, чтобы вы добыли исцарапанное золотое кольцо из катакомб Амани."}}
D[9492] = {"Новый поворот событий",{"Принесите кулак вождя Каргата боевому командиру Данату Троллебою в Оплот Чести."}}
D[9493] = {"Элита Орды Скверны",{"Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей клана Изувеченной Длани по приказу боевого командира Ромуса из Оплота Чести."}}
D[9494] = {"Угли Скверны",{"Принесите уголь Скверны волхву Забраксис из Оплота Чести."}}
D[9495] = {"Воля Вождя",{"Принесите Кулак Вождя Каргата Назгрелу в Траллмар."}}
D[9496] = {"Элита Орды Скверны",{"Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей из клана Изувеченной Длани по приказу темного охотника Туджина из Траллмара."}}
D[9498] = {"Соколиный дозор",{"Доложитесь капитану следопытов Венн'рену в Соколином дозоре на полуострове Адского Пламени."}}
D[9499] = {"Соколиный дозор",{"Отправляйтесь в Соколиный дозор, на юго-запад полуострова Адского Пламени, и поговорите с капитаном следопытов Венн'реном."}}
D[9500] = {"Зов воды",{"Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним."}}
D[9501] = {"Зов воды",{"Найдите Водяницу у Подводного Рифа возле острова Кровавой Дымки и поговорите с ней."}}
D[9502] = {"Зов воды",{"Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним."}}
D[9503] = {"Зов воды",{"Принесите 6 бутылочек смрадной эссенции на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте Водянице."}}
D[9504] = {"Зов воды",{"Наполните пустой бурдюк, а затем вернитесь на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте бурдюк Водянице."}}
D[9505] = {"Пророчество Велена",{"Отправляйтесь на юг и отыщите народ, о котором говорило раненое существо."}}
D[9506] = {"Начало положено",{"Верните адмиралу Одиссию морской компас и морскую карту, украденные Торговой компанией."}}
D[9508] = {"Зов воды",{"Принесите голову Телатиона на остров Кровавой Дымки в храм Сокрытого Рифа и отдайте Водянице."}}
D[9509] = {"Зов воды",{"Отнесите флакон чистейшей воды предсказателю Нобундо. Его можно найти на острове Лазурной Дымки в Экзодаре."}}
D[9510] = {"Шкура щетинистого копытня",{"Добудьте 5 шкур щетинистого копытня по просьбе поставщика Бракнара с Заставы маг'харов на Полуострове Адского Пламени."}}
D[9511] = {"Боевые планы Каргата"}
D[9512] = {"Крабовый супчик поваренка",{"Принесите 6 кусков мяса шустрых крабов \"Поваренку\" Максоусу в лагерь Одиссия."}}
D[9513] = {"Возвращение руин",{"Убейте 5 мирмидонов, 5 наг и 5 сирен из клана Зловещей Чешуи для жрицы Кайлин Ил'динар."}}
D[9514] = {"Покрытая рунами табличка",{"Отнеcите покрытую рунами табличку жрице Кайлин Ил'динар в лагерь Одиссия на острове Лазурной Дымки."}}
D[9515] = {"Полководец Шрисс'тиз",{"Жрица Кайлин Ил'динар из лагеря Одиссия попросила вас убить полководца Шрисс'тиза."}}
D[9516] = {"Уничтожить Легион!",{"Уничтожьте 6 бичевательниц Маннорока, 6 стражей Скверны и 6 опаляющих инферналов, а затем вернитесь к воздаятелю Ведаару в Лесную Песнь в Ясеневом лесу."}}
D[9517] = {"Напрасные усилия",{"Доставьте 15 связок древесины Песни Войны и 5 связок оскверненной древесины Сатирнаара Кривокрону в Лесную Песнь."}}
D[9518] = {"Пособники разрушения",{"Часовая Люсьель Шепот Звезд из Лесной Песни хочет, чтобы вы убили надзирателя Гортака, 2 пилотов крошшеров клана Песни Войны, 5 ордынских лесозаготовителей и 10 ордынских разведчиков."}}
D[9519] = {"Потерянная чаша",{"Принесите чашу Элуны Кайнету Штилю в Лесную Песнь."}}
D[9520] = {"Демонические планы",{"Доставьте демонические планы воздаятелю Ведаару в Лесную Песнь в Ясеневом лесу."}}
D[9521] = {"Донесение с северного фронта",{"Доставьте донесение часовой Люсьель часовой Дальней Песне в рощу Среброкрылых."}}
D[9522] = {"Больше никогда!",{"Убейте Горганнона и Диатора Ищейку и вернитесь к воздаятелю Ведаару в Лесную Песнь в Ясеневом лесу."}}
D[9523] = {"Хрупкие предметы. Не кантовать!",{"Принесите 8 древних реликвий археологу Адаманту Железному Сердцу в лагерь Одиссия на острове Лазурной Дымки."}}
D[9524] = {"Узник Цитадели",{"Спасите капитана Алину в Цитадели Адского Пламени до того, как ее казнят.","","Это задание выполняется в режиме героической сложности."}}
D[9525] = {"Imprisoned in the Citadel",{"Rescue Captain Boneshatter inside Hellfire Citadel before he is executed.","","This quest must be completed in Heroic dungeon difficulty."}}
D[9526] = {"Возрождение Холма Демонического Огня",{"Посадите 8 древесных саженцев в кучи плодородной земли и вернитесь к Кривокрону в Лесную Песнь в Ясеневом лесу."}}
D[9527] = {"Все, что осталось",{"Верните Коулену останки его семьи."}}
D[9528] = {"Крик о помощи",{"Проводите Магвин через остров до дома."}}
D[9529] = {"Камень",{"Добудьте камень Бездны с Тропы Мертвых."}}
D[9530] = {"Созревший план",{"Принесите выдолбленный ствол и 5 охапок листьев адмиралу Одиссию в лагерь Одиссия на острове Лазурной Дымки."}}
D[9531] = {"У деревьев есть уши",{"Проследите за встречей Гизла с предателем.","","Расскажите обо всем увиденном адмиралу Одиссию."}}
D[9532] = {"Найти Келтуса Темного Листа",{"Найдите Келтуса Темного Листа."}}
D[9533] = {"Рука помощи",{"Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом."}}
D[9534] = {"Уничтожить Легион!",{"Уничтожьте 6 бичевательниц Маннорока, 6 стражей Скверны и 6 опаляющих инферналов, а затем вернитесь к Валуше на заставу Расщепленного Дерева в Ясеневом лесу."}}
D[9535] = {"Демонические планы",{"Доставьте демонические планы Валуше на заставу Расщепленного Дерева, что в Ясеневом лесу."}}
D[9536] = {"Больше никогда!",{"Убейте Горганнона и Диатора Ищейку, затем вернитесь к Валуше на заставу Расщепленного Дерева в Ясеневом лесу."}}
D[9537] = {"Не ведая пощады",{"Добудьте для адмирала Одиссия переписку предателя у инженера \"Искра\" Перемолоттера"}}
D[9538] = {"Изучение языка",{"Изучите пергамент \"Язык фурболгов из племени Тихвой для начинающих\", полученный от Ауррена, а затем изучите тотемом Акиды на Лазурной заставе."}}
D[9539] = {"Тотем Ку",{"Найдите тотем Ку с помощью проводника."}}
D[9540] = {"Тотем Тикти",{"Найдите тотем Тикти с помощью проводника."}}
D[9541] = {"Тотем Йора",{"Найдите тотем Йора с помощью проводника."}}
D[9542] = {"Тотем Варк",{"Найдите тотем Варк с помощью проводника."}}
D[9543] = {"Искупление",{"Поговорите с Амааном Мудрым в храме Телхамат на полуострове Адского Пламени."}}
D[9544] = {"Пророчество Акиды",{"Освободите 8 пленников из племени Тихвой из клеток в деревне Косолапов. Вернитесь к Аругу из племени Тихвой на Лазурную заставу."}}
D[9545] = {"Реликвия ясновидца",{"Вернитесь к телу Седаи, которое находится к северо-востоку от храма Телхамат, и используйте там реликвию ясновидца по просьбе Амаана Мудрого из храма Телхамат на полуострове Адского Пламени. После выполнения задания возвращайтесь к Амаану."}}
D[9547] = {"Зов воздуха",{"Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки."}}
D[9548] = {"Украденное снаряжение",{"Верните Клопперу Бацбаху его оборудование. Клоппера можно найти в старом черепашьем панцире на берегу."}}
D[9549] = {"Артефакты племени Черного Ила",{"Принесите 3 варварских идола и 6 варварских ножа мурлоков Клопперу Бацбаху, который прячется в старом черепашьем панцире на берегу."}}
D[9550] = {"Загадочная карта",{"Найдите павильон, изображенный на карте, и выясните, что в нем необычного."}}
D[9551] = {"Зов воздуха",{"Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки."}}
D[9552] = {"Зов воздуха",{"Поговорите с Велаадой на Штормовом Пике острова Лазурной Дымки."}}
D[9553] = {"Зов воздуха",{"Поговорите с Шептателем на Штормовом Пике острова Лазурной Дымки."}}
D[9554] = {"Зов воздуха",{"Отдайте Завихрение воздуха предсказателю Нобундо в Экзодаре."}}
D[9555] = {"Зов огня",{"Поговорите с предсказателем Нобундо в Кристальном зале Экзодара."}}
D[9556] = {"Вода для мага",{"Найдите бутылку святой воды Стратхольма на улицах Стратхольма и доставьте ее Лордеронскому магу в квартал магов в Штормграде или Подгороде, если вашей стороне удалось одержать верх в Восточных Чумных землях."}}
D[9557] = {"Расшифровка книги",{"Отнесите древние записи на Кровавую заставу и покажите анахорету Пайтеусу."}}
D[9558] = {"Длиннобородые",{"Найдите Гремни Длинноборода на северо-западе от логова Хаал'эш на полуострове Адского Пламени."}}
D[9559] = {"Логово племени Тихвой",{"Поговорите с верховным вождем в логове племени Тихвой."}}
D[9560] = {"Звери Судного дня!",{"Принесите 8 шкур опустошителей Мурдо в логово племени Тихвой."}}
D[9561] = {"Записи Нолкаи",{"Найдите место, описанное в дневнике Нолкаи, и отыщите его тайник."}}
D[9562] = {"Мурлоки... За что нам эта напасть?",{"Верните 5 мешков зерна племени Тихвой."}}
D[9563] = {"Доверие Миррена",{"Принесите Миррену Длиннобороду 1 кружку горькой настойки Стражей Пустоты. Для выполнения этого задания необходимо иметь дружелюбное отношение Оплота Чести."}}
D[9564] = {"Клок шерсти Гурфа",{"Верните Гурфу клок его шерсти в логово племени Тихвой на острове Лазурной Дымки."}}
D[9565] = {"Поиски в логове племени Тихвой",{"Найдите в логове племени Тихвой причины предательства совухов."}}
D[9566] = {"Кровавые кристаллы",{"Поговорите с верховным вождем в логове племени Тихвой."}}
D[9567] = {"Лицо врага",{"Найдите в Наззивиане монумент Наззивуса, возьмите один из иероглифов с монумента и вернитесь к воздаятельнице Аалезии на Кровавую заставу."}}
D[9568] = {"Лучшая защита",{"Воздаятельница Алезия с Кровавой заставы просит убить 10 сатиров, 5 разбойников и 5 скверноподанных из племени Наззивус."}}
D[9569] = {"Противостояние",{"Убейте Зевракса, 5 аксариенских тенеловов и 5 аксариенских призывателей огня, соберите 5 оскверненных кристаллов и отнесите их на Кровавую заставу воздаятельнице Аалезии."}}
D[9570] = {"Куркен-жмуркен",{"Убейте Куркена и принесите его шкуру Курцу Прорицателю в логово племени Тихвой на острове Лазурной Дымки."}}
D[9571] = {"Шкура Куркена",{"Отнесите шкуру Куркена Мурдо в логово племени Тихвой."}}
D[9572] = {"Ослабить оборону валов",{"Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Каза'ресу в Траллмар на Полуострове Адского Пламени."}}
D[9573] = {"Вождь Умуру",{"Убейте вождя Умуру и 9 безумных диких совухов."}}
D[9574] = {"Отравленные скверной",{"Принесите на Кровавую заставу 6 кусков коры, покрытой кристаллами, и отдайте Морэ."}}
D[9575] = {"Ослабить оборону валов",{"Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Пушкаренку в Оплот Чести на полуострове Адского Пламени."}}
D[9576] = {"Ожерелье Жестокого Плавника",{"Покажите подвеску красного кристалла Морэ на Кровавой заставе."}}
D[9578] = {"В поисках Галена",{"Найдите Галена, мужа Морэ."}}
D[9579] = {"Судьба Галена",{"Принесите на Кровавую заставу амулет Галена и отдайте его Морэ."}}
D[9580] = {"Вскормленные медвежатиной",{"Принесите зверолову Лисеону на Кровавую заставу 8 кусков мяса с боков старых бурых медведей."}}
D[9581] = {"Изучение кристаллов",{"Добудьте образец кристалла с места крушения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу."}}
D[9582] = {"Силой единой",{"Откройте клетку смертоносного опустошителя, убейте его и вернитесь к Руаде на Лазурную заставу на острове Лазурной Дымки."}}
D[9584] = {"Второй образец",{"Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте его предвестнику Миколаасу."}}
D[9585] = {"Последний образчик",{"Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу."}}
D[9586] = {"Помощь Таваре",{"Найдите Тавару и исцелите ее раны."}}
D[9587] = {"Предвестье беды",{"Доставьте угрожающее письмо боевому командиру Данату Троллебою в Оплот Чести на полуострове Адского Пламени."}}
D[9588] = {"Предвестье беды",{"Доставьте угрожающее письмо Назгрелу в Траллмар на Полуострове Адского Пламени."}}
D[9589] = {"Кровь есть жизнь",{"Принесите 10 фиалов крови орков Скверны Пушкаренку в Оплот Чести на полуострове Адского Пламени."}}
D[9590] = {"Кровь есть жизнь",{"Принесите 10 фиалов крови орков Скверны центуриону Каза'ресу в Траллмар на Полуострове Адского Пламени."}}
D[9591] = {"Приручение зверя",{"Используйте тотем приручения и приручите колючего краба. Вернитесь к охотнице Келле Тетиве Ночи."}}
D[9592] = {"Приручение зверя",{"Используйте тотем приручения и приручите большого лесонога, после чего вернитесь к охотнице Келле Тетиве Ночи."}}
D[9593] = {"Приручение зверя",{"Используйте тотем приручения и приручите ночного ловца. Вернитесь к охотнице Келле Тетиве Ночи."}}
D[9594] = {"Знаки Легиона",{"Убейте 8 сатиров из племени Наззивус и 8 скверноподданных из племени Наззивус, а затем отнесите латный доспех Тзерака воздаятельнице Аалезии на Кровавую заставу."}}
D[9595] = {"Контроль",{"Убивайте мурлоков с Илистого Берега до тех пор, пока не появится призрак кель'дорайского мага, затем уничтожьте его. После этого поговорите с Бати в Чертоге Света Экзодара."}}
D[9598] = {"Искупление",{"Прочтите Фолиант Божественности и поговорите с Джоль."}}
D[9599] = {"<UNUSED>",{"Speak with Jol in the Exodar."}}
D[9600] = {"Искупление",{"Воскресите молодого фурболга-шамана из племени Тихвой при помощи знака Жизни, а затем вернитесь к Джоль."}}
D[9601] = {"В Бастион",{"Поговорите с Меларом Клинком Рассвета из Бастиона."}}
D[9602] = {"Избавь их от лукавого...",{"Отнесите переписку предателя экзарху Менелаусу на Лазурную заставу."}}
D[9603] = {"Лежанки, лекарства и прочая ерунда",{"Отвезите список Тофера на Кровавую заставу дрессировщику гиппогрифов Лаандо."}}
D[9604] = {"На крыльях гиппогрифа",{"Возьмите у Лаандо гиппогрифа и летите в Экзодар. В Экзодаре отдайте список Тофера Нургуни. Нургуни можно найти у трона Наару в Экзодаре."}}
D[9605] = {"Укротитель гиппогрифов Стефанос",{"Найдите Стефаноса у ворот Экзодара и наймите гиппогрифа для возвращения на Кровавую заставу."}}
D[9606] = {"Возвращение к Тоферу Лоаалу",{"Договоритесь со Стефаносом и наймите у него гиппогрифа для путешествия на Кровавую заставу. На заставе доставьте припасы Нургуни корчмарю Тоферу Ололо."}}
D[9607] = {"В сердце ярости",{"Детально изучите Кузню Крови и доложите об увиденном командиру армии Данату Троллебою в Оплот Чести на полуострове Адского Пламени."}}
D[9608] = {"В сердце ярости",{"Детально изучите Кузню Крови и доложите об увиденном Назгрелу в Траллмар на Полуострове Адского Пламени."}}
D[9609] = {"Помощь дозорному Биггсу",{"Найдите дозорного Биггса на Болоте Печали."}}
D[9610] = {"Озеро Слез",{"Добудьте 10 артефактов Атал'ай и вернитесь с ними к Холаару в Убежище на Болото Печали."}}
D[9612] = {"Большое спасибо!",{"Поговорите с экзархом Менелаусом на Лазурной заставе."}}
D[9616] = {"Бандиты!",{"Отнесите сообщение эльфов крови экзарху Менелаусу на Лазурную заставу."}}
D[9617] = {"На поиски Странников",{"Поговорите с лейтенантом Вестницей Рассвета в обители Странников."}}
D[9618] = {"Возвращение с донесениями",{"Отнесите донесения Келтуса Темного Листа Зеланису в Луносвет."}}
D[9619] = {"Руна Призыва",{"Используйте камень Бездны, чтобы призвать демона Бездны в деревню Золотистой Дымки, одолейте демона и вернитесь к Талионии в Луносвет."}}
D[9620] = {"Пропавшие картографы",{"Предвестник Миколаас просит разыскать группу разведчиков, которую он послал к развалинам Лорет'Арана, и помочь группе чем только возможно."}}
D[9621] = {"Посол к Орде",{"Отнесите письмо от Лор'темара Терона леди Сильване Ветрокрылой в Подгород, столицу Отрекшихся в Тирисфальских лесах."}}
D[9622] = {"Предупреди свой народ",{"Поговорите с экзархом Менелаусом на Лазурной заставе."}}
D[9623] = {"Время пришло",{"Передайте распоряжения экзарха Тораллиусу Пастуху. Он находится у Экзодара, недалеко от входа."}}
D[9624] = {"Любимое блюдо",{"Принесите 10 песчаных груш Аонару в лагерь Кессела."}}
D[9625] = {"Элекки – это серьезно",{"Поговорите с Ворканом Пастухом Элекков на острове Кровавой Дымки."}}
D[9626] = {"Встреча с вождем",{"Отнесите письмо с печатью Леди Сильваны Ветрокрылой Траллу в Оргриммар, столицу Дуротара."}}
D[9627] = {"Верность Орде",{"Возвращайтесь в Луносвет и поговорите с Лор'темаром Тероном."}}
D[9628] = {"Цена знания – жизнь",{"Неподалеку от того места, где были убиты картографы, обитают наги из клана Зловещей Чешуи. Отберите у них кристалл с результатами наблюдений и доставьте его на Кровавую заставу предвестнику Миколаасу."}}
D[9629] = {"Поймать и отпустить",{"Морэ с Кровавой заставы просит вас \"пометить\" 6 разведчиков из племени Черного Ила при помощи маркировщика мурлоков."}}
D[9630] = {"Дневник Медива",{"По поручению верховного мага Альтура на Перевале Мертвого Ветра войдите в Каражан и поговорите с Вравьеном."}}
D[9631] = {"Взаимовыручка",{"Доставьте фрагмент обугленной кости Калинне Латред в Область 52 в Пустоверти."}}
D[9632] = {"Новые союзники",{"Доставьте рекомендательное письмо охотнице Келле Тетиве Ночи."}}
D[9633] = {"Дорога к Аубердину",{"Сядьте на корабль, идущий в Аубердин. Пристань находится неподалеку от дома охотницы Келлы Тетивы Ночи. В Аубердине отдайте рекомендательное письмо Тандрису Ветропряду."}}
D[9634] = {"Чужие-хищники",{"Убейте 10 детенышей опустошителя с острова Кровавой Дымки и вернитесь к Воркану Пастуху Элекков. Воркана можно найти на острове Кровавой Дымки в лагере Кессела."}}
D[9635] = {"Удаленный конденсатор выхлопов!",{"Принесите 15 деталей парового насоса Маку Дайверу в Забра'джин в Зангартопи."}}
D[9636] = {"Удаленный конденсатор выхлопов!",{"Принесите 15 деталей парового насоса К. Ли Мелюзге в Телредор в Зангартопи."}}
D[9637] = {"Требование Калинны",{"Калинна Латред требует отыскать и принести ей фолиант сумерек и книгу забытых имен. Первой владеет главный чернокнижник Пустоклят, его можно найти в Разрушенных залах цитадели Адского Пламени. Вторая принадлежит заклинателю тьмы Ситу, который находится в Сетеккских залах в Аукиндоне.","","Это задание должно быть выполнено на героическом уровне сложности."}}
D[9638] = {"В хороших руках",{"Поговорите с Градавом в Библиотеке стража в Каражане."}}
D[9639] = {"Камсис",{"Поговорите с Камсис в Библиотеке Стража в Каражане."}}
D[9640] = {"Тень Арана",{"Достаньте дневник Медива и верните его Камсис в Библиотеку Стража в Каражане."}}
D[9641] = {"Осколки облученного кристалла",{"Принесите 10 осколков облученного кристалла воздаятелю Боросу на Кровавую заставу."}}
D[9642] = {"И снова облученные кристаллы",{"Если у тебя есть еще облученные осколки, я с радостью обменяю их на свои кристаллы."}}
D[9643] = {"Удушающая лоза",{"Принесите зверолову Лисеону 6 побегов колючей удушающей лозы."}}
D[9644] = {"Ночная Погибель",{"Ступайте на террасу Мастера в Каражане и с помощью урны Калинны призовите Ночную Погибель. Извлеките из тела Ночной Погибели слабую чародейскую сущность и доставьте ее верховному магу Альтуру."}}
D[9645] = {"Терраса Мастера",{"Поднимитесь на террасу Мастера в Каражане и прочитайте дневник Медива. После этого возвращайтесь вместе с дневником к верховному магу Альтуру."}}
D[9646] = {"РАЗЫСКИВАЕТСЯ: Коготь Смерти",{"Принесите лапу Когтя Смерти предвестнику Миколаасу на Кровавую заставу."}}
D[9647] = {"Ловля бражников",{"Зверолов Лисеон просит убить 10 царственных синих бражников."}}
D[9648] = {"Грибная похлебочка из Мак'Ари",{"Джессера из Мак'Ари просит принести ему на Кровавую заставу по одному экземпляру водянистого смрадорога, кровавого гриба, губительной полиспоры и скверноконуса."}}
D[9649] = {"Слеза Изеры",{"Джессера из Мак'Ари просит принести ему на Кровавую заставу 2 экземпляра слезы Изеры."}}
D[9663] = {"Дуга Кессела",{"Сообщите верховному вождю племени Тихвой, экзарху Менелаусу и адмиралу Одиссию о готовящемся вторжении эльфов крови, а затем возвратитесь к Кесселу. У вас есть 15 минут. Элекка следует держать подальше от воды."}}
D[9664] = {"Новые форпосты",{"Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и вернитесь к посланнику Белобороду в Часовню Последней Надежды."}}
D[9665] = {"Укрепим оборону",{"Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и возвращайтесь к посланнику Гормоку в Часовню Последней Надежды."}}
D[9666] = {"Демонстрация силы",{"Проникните в логово клана Зловещей Чешуи, убейте лорда Ксиза и пронзите его тело древком дренейского знамени."}}
D[9667] = {"Спасение принцессы Тихвой",{"Выпустите принцессу Тихвой из клетки, а затем найдите на Кровавой заставе посла племени Тихвой Фрасабу и поговорите с ним.","","Чтобы раздобыть ключ от клетки, убейте верховного вождя племени Косолапов."}}
D[9668] = {"Доклад экзарху Адметиусу",{"Поговорите с экзархом Адметиусом на Кровавой заставе."}}
D[9669] = {"Пропавшая экспедиция",{"Убейте 8 пауков-ткачих, 8 паучих-кровопийц и матриарха пауков – Зарак. По завершении задания вернитесь на Кровавую заставу к Акелусу."}}
D[9670] = {"Они живы! Может быть...",{"Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса."}}
D[9671] = {"Срочная доставка",{"Ты - Вентурианец? Что ж, вовремя! Я уже и не надеялся тебя найти.","","Загляни в почтовый ящик - там тебя ждет срочное письмо. Мне его передал один человек, адмирал с острова Лазурной Дымки. Как же его звали... Одиссей? Одессит?.. Нет, не помню: из головы вылетело. Но он сказал, что ты его непременно вспомнишь.","","<Гермесий пожимает плечами.>"}}
D[9672] = {"Наследие Проклятой Крови",{"Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним."}}
D[9673] = {"Дрессировка",{"Поговорите с Хальтенисом в Луносвете."}}
D[9674] = {"Проклятые наги",{"Капитан Эдвард Хейнс с острова Драконьей Скорби просит убить 10 наг с острова Проклятой Крови."}}
D[9675] = {"Дрессировка",{"Поговорите с Ганааром в Торговом ряду Экзодара."}}
D[9676] = {"Наставник паладинов",{"Поговорите с наставником паладинов Джестенисом Солнцесветом в Солнечном Шпиле на острове Солнечного Скитальца."}}
D[9677] = {"Призыв предводителя рыцарей Кровосмела",{"Поговорите с предводителем рыцарей Кровосмелом на площади Странников в Луносвете."}}
D[9678] = {"Первое испытание",{"Отправляйтесь на остров, описанный предводителем рыцарей Кровосмелом, найдите пещеру и разожгите огонь в жаровне. Пройдя первое испытание, возвращайтесь к предводителю рыцарей Кровосмелу в Луносвет."}}
D[9680] = {"Тайны прошлого",{"Верховный маг Альтур желает, чтобы вы нашли в горах к югу от Каражана на Перевале Мертвого Ветра фрагмент обугленной кости и доставили ему."}}
D[9681] = {"Источник силы",{"Поговорите с магистром Асталором Кровавой Клятвой в тайной зале, расположенной под штабом рыцарей Крови."}}
D[9682] = {"Отчаявшиеся",{"Капитан Эдвард Хейнс с острова Драконьей Скорби просит освободить 4 души с острова Проклятой Крови."}}
D[9683] = {"Избавление от Проклятой Крови",{"Капитан Эдвард Хейнс с острова Драконьей Скорби просит уничтожить статую королевы Азшары и убить Атофа Проклятую Кровь."}}
D[9684] = {"Получение силы Света",{"Используйте мерцающий сосуд на эльфах крови-магистрах, чтобы наполнить его магической силой и возвращайтесь к предводителю рыцарей Кровосмелу в Луносвет."}}
D[9685] = {"Воскрешение",{"Отправляйтесь в таверну Луносвета и воскресите Сангриаса Безмолвного Клинка с помощью силы, заключенной в наполненном мерцающем сосуде."}}
D[9686] = {"Второе испытание",{"Пройдите второе испытание, победив воителя Ярокрова, воителя Светореза, воительницу Быстромеч и воителя Солнцесвета в павильоне у наставника Келерана Алого Взмаха."}}
D[9687] = {"Святотатство",{"Принц Торет с острова Драконьей Скорби просит отыскать 8 костей драконов."}}
D[9688] = {"Дорога в Сон",{"Принц Торет с острова Драконьей Скорби просит убить 5 темно-зеленых дракончиков и 5 детенышей зеленого дракона."}}
D[9689] = {"Острозуб",{"Принц Торет с острова Драконьей Скорби просит убить Острозуба."}}
D[9690] = {"Второе испытание",{"Поговорите с наставником Келераном Алым Взмахом."}}
D[9691] = {"Возвращение в Луносвет",{"Возвращайтесь к предводителю рыцарей Кровосмелу в Луносвет."}}
D[9692] = {"Путь адепта",{"Принесите оскверненный самоцвет Кора, ящик со слитками, закаленными в крови, нужное количество крови разгневненных и знак отличия рыцаря крови предводителю рыцарей Кровосмелу в Луносвет."}}
D[9693] = {"Что для тебя Аргус?..",{"Экзарх Адметиус с Кровавой заставы просит поговорить с воздаятелем Боросом."}}
D[9694] = {"Кровавая застава",{"Убейте 10 шпионов Солнечных Ястребов и сообщите об этом на Кровавую заставу воздаятелю Боросу."}}
D[9696] = {"Переводы...",{"Доставьте послание Солнечных Ястребов дознавательнице Элизии на Кровавую заставу."}}
D[9697] = {"Наблюдательница Лиса'о",{"Поговорите с наблюдательницей Лиса'о у кенарийского караульного поста в Зангартопи."}}
D[9698] = {"Аудиенция у Пророка",{"Доставьте переведенное послание Солнечных Ястребов Пророку Велену в Экзодар."}}
D[9699] = {"Правда или вымысел",{"Доставьте распоряжения Велена воздаятелю Боросу на Кровавую заставу."}}
D[9700] = {"Магия против Тьмы",{"Воздаятель Борос с Кровавой заставы просит найти солнечный портал и убить 5 аномалий Бездны."}}
D[9701] = {"Наблюдение за спорлингами",{"Исследуйте Грибную поляну в Зангартопи, затем вернитесь к наблюдательнице Лиса'о к кенарийскому караульному посту в Зангартопи и расскажите об увиденном."}}
D[9702] = {"Вопросы питания",{"Соберите 10 образцов выброшенного корма и вернитесь к наблюдательнице Лиса'о на кенарийский караульный пост в Зангартопи."}}
D[9703] = {"Криогенный блок",{"Воздаятель Курос хочет, чтобы вы доставили на Кровавую заставу 12 коробок с медицинскими припасами."}}
D[9704] = {"Смерть от рук Презренных",{"Отправляйтесь на юг, в руины Луносвета, и отыщите убитого курьера на Рассветной улице."}}
D[9705] = {"Возвращение посылки",{"Вернитесь к курьеру Аларион с посылкой Эроны."}}
D[9706] = {"Дневник Галена: судьба воздаятеля Саруана",{"Доберитесь до Кровавой заставы и отдайте дневник Галена воздаятелю Куросу."}}
D[9707] = {"Ковка оружия",{"Принесите ящик с материалами Бемаррину в Луносвет."}}
D[9708] = {"Знакомые грибы",{"Соберите 15 образцов грибов и принесите их наблюдательнице Лиса'о на караульный пост Кенария в Зангартопи."}}
D[9709] = {"Ворованные грибы",{"Соберите 10 ящиков грибов и вернитесь с ними к наблюдательнице Лиса'о на караульный пост Кенария в Зангартопи."}}
D[9710] = {"Закаленный кровью протазан",{"Дождитесь, пока Бемаррин смастерит оружие."}}
D[9711] = {"Матис Жестокий",{"Воздаятель Курос с Кровавой заставы требует, чтобы Матис Жестокий был пойман."}}
D[9712] = {"Талассийский боевой конь",{"Поговорите с предводителем рыцарей Доблестной Кровью, чтобы научиться вызывать талассийского боевого коня."}}
D[9713] = {"Включение возможности сбора огнешляпки"}
D[9714] = {"Принеси мне еще одну клумбу!",{"Кровавый гибискус, который можно найти у шаркунов, болотоходов и подболотных скатов в Нижетопи, в резервуаре Кривого Клыка, нам всегда пригодится. Приноси его мне связками по пять штук, я буду очень тебе благодарен!"}}
D[9715] = {"Принеси мне клумбу!",{"Добудьте 5 растений кровавого гибискуса и отнесите их Гзхун'тту в Спореггар в Зангартопи."}}
D[9716] = {"Неприятности на озере Тенетопь",{"Выясните причину убывания воды в озере Тенетопь. Затем вернитесь к Исиэль Песни Ветра в Кенарийский приют в Зангартопи."}}
D[9717] = {"Удачный ход",{"Добудьте ветку подспорника и вернитесь с ней к Т'шу в Спореггар в Зангартопи."}}
D[9718] = {"С высоты птичьего полета",{"Используйте амулет буревестника, чтобы исследовать основные озера Зангартопи по просьбе Исиэли Песни Ветра."}}
D[9719] = {"Охота на Охотницу",{"Принесите мозг Черной Охотницы Кхн'иксу в Спореггар в Зангартопи."}}
D[9720] = {"Необходимо поддерживать равновесие!",{"Осыпьте семенами железной лозы пульты управления паровым насосом в Змеином озере, озере Тенетопь, озере Болотных Огоньков и в Лагуне. Затем вернитесь к Исиэль Песни Ветра в Кенарийский приют в Зангартопи и отдайте ей оставшиеся семена."}}
D[9721] = {"Призыв леди Лиадрин",{"Поговорите с Лордом Соланаром в Луносвете."}}
D[9722] = {"Путь мастера",{"Поговорите с Лордом Соланаром еще раз и примите предложение о покровительстве."}}
D[9723] = {"Жест преданности",{"Принесите лорду Соланару в Луносвет 40 отрезов рунической ткани, 6 арканитовых слитков, 10 солнечников, 5 темных рун и 150 золотых."}}
D[9724] = {"Предупреждение Кругу Кенария",{"Поговорите с Амитиэль Странницей Туманов на Заставе Кенария на полуострове Адского Пламени."}}
D[9725] = {"Доказательство лояльности",{"Лорд Соланар Кровогнев из Луносвета просит уничтожить 3 мясных фургона и убить 15 инженеров Плети."}}
D[9726] = {"Теперь, когда мы друзья...",{"Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун'тту в Спореггар в Зангартопи."}}
D[9727] = {"Раз уж мы по-прежнему друзья...",{"Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун'тту в Спореггар в Зангартопи."}}
D[9728] = {"Теплый прием",{"Принесите стражу Хамуту из Кенарийского приюта 30 когтей наг."}}
D[9729] = {"Фхвур крушить!",{"Проводите Фхвура к паровому насосу на озере Болотных Огоньков, чтобы добыть ковчег Ссслита. Потом доставьте обратно Фхвура и ковчег в целости и сохранности, и вернитесь к Гзхун'тту в Спореггар в Зангартопи."}}
D[9730] = {"Предводитель Темного Гребня",{"Убейте раджу Хагазеда в Лагуне и вернитесь к стражу Хамуту из Кенарийской экспедиции в Зангартопи, чтобы получить награду."}}
D[9731] = {"Схема стоков",{"Найдите в Змеином озере признаки утечки воды. Вернитесь к Исиэль Песни Ветра в Кенарийском приюте и сообщите о своем открытии."}}
D[9732] = {"Назад в болото",{"Вернитесь к Исиэль Песни Ветра в Кенарийском приюте в Зангартопи."}}
D[9733] = {"Предупреждение Кругу Кенария",{"Поговорите с Махурамом Крепким Копытом на Полуострове Адского Пламени, в Траллмаре."}}
D[9734] = {"Назад в болото",{"Вернитесь к Исиэль Песни Ветра в Кенарийском приюте в Зангартопи."}}
D[9735] = {"Истинные владыки Света",{"Принесите фиал святой воды Длани Тира Лорду Соланару Кровогневу в Луносвет."}}
D[9736] = {"Истинные владыки Света",{"Принесите Лорду Соланару Кровогневу в Луносвет 1 чародейский катализатор, 1 меру сумеречного порошка, 1 азеротский алмаз и 1 безупречный черный алмаз."}}
D[9737] = {"Истинные владыки Света",{"Потушите неугасимое пламя часовни Алонсия с помощью огнетушительной смеси и уничтожьте всех, кто попробует защитить часовню."}}
D[9738] = {"Пропавшие без вести",{"Выясните, что стало с заклинателем земли Гневвсом, натуралистом Кусом, культиватором Зеленопалом и призывателем ветров Когтем. Затем возвращайтесь к дозорному Джанг в резервуар Кривого Клыка в Зангартопь."}}
D[9739] = {"Проблемы спорлингов",{"Соберите 10 мешочков зрелых спор по просьбе Фассна с Грибной поляны."}}
D[9740] = {"Солнечные Ворота",{"Воздаятель Эсом с Кровавой заставы хочет, чтобы солнечные врата были уничтожены."}}
D[9741] = {"Твари из Бездны",{"Убейте 12 тварей Бездны и сообщите об этом на Кровавую заставу воздаятелю Эсому."}}
D[9742] = {"Новые мешочки со спорами",{"Что, |3-6(дворф), тебе удалось спасти еще несколько мешочков со спорами?"}}
D[9743] = {"Природные враги",{"Принесите Фассну с Грибной поляны в Зангартопи 6 усиков болотника."}}
D[9744] = {"Еще усиков!",{"Тебе удалось перебить немало великанов, но немало их по-прежнему бродит по болотам. И они по-прежнему охотятся на наши мешочки со спорами!"}}
D[9746] = {"Границы возможного",{"Убейте 10 пиромантов и 10 защитников Солнечных Ястребов и сообщите об этом на Кровавую заставу воздаятелю Эсому."}}
D[9747] = {"Племя Тенетопи",{"Отправляйтесь в деревню Тенетопь и убейте Катару, 8 провидцев, 6 знахарей и 6 оракулов из племени Тенетопи по просьбе Икейена из Кенарийского приюта."}}
D[9748] = {"Не пей эту воду!",{"Воздаятель Эсом на Кровавой заставе попросил вас принести пробу воды с острова Кровавой Дымки во флаконе, который он предоставил."}}
D[9749] = {"Они живы! Может быть...",{"Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса."}}
D[9750] = {"UNUSED Urgent Delivery"}
D[9751] = {"Наследие Проклятой Крови",{"Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним."}}
D[9752] = {"Спасение с озера Тенетопь",{"Проводите Кайру Длинную Гриву в Кенарийский приют в Зангартопи. Выполнив эту задачу, поговорите с Исиэль Песнью Ветра."}}
D[9753] = {"То, что мы знаем...",{"Поговорите с экзархом Адметиусом на Кровавой заставе."}}
D[9756] = {"То, чего мы не знаем...",{"Поговорите с пленным агентом Солнечных Ястребов, которого держат на Кровавой заставе. Передайте полученные сведения экзарху Адметиусу."}}
D[9757] = {"Охотница Келла Тетива Ночи",{"Поговорите с охотницей Келлой Тетивой Ночи рядом с причалом Валаара."}}
D[9758] = {"Возвращение к чародею Вандрилу",{"Возвращайтесь к чародею Вандрилу в Транкивиллион, что в Призрачных землях."}}
D[9759] = {"Отречемся от старого мира",{"Подрывник Легосо собирается разрушить энергоблок и убить Сиронас. Попытайтесь защитить его и, если задание будет успешно выполнено, расскажите об этом экзарху Адметиусу на Кровавой заставе."}}
D[9760] = {"Привал Защитника",{"Поговорите с воздаятельницей Корин в селении Привал Защитника на острове Кровавой Дымки;."}}
D[9761] = {"Расчистка пути",{"Убейте 8 саботажников и 8 посланников из клана Солнечных Ястребов и сообщите об этом воздаятельнице Корин в Привале Защитника."}}
D[9762] = {"Неписаное пророчество"}
D[9763] = {"Убежище врага",{"Дозорный Джанг хочет, чтобы вы нашли и убили полководца Калитреша в резервуаре Кривого Клыка."}}
D[9764] = {"Приказы Леди Вайш",{"Отнесите приказы леди Вайш Исиэль Песни Ветра в Кенарийский приют в Зангартопи."}}
D[9765] = {"Готовится к войне",{"Добудьте оружие клана Кривого Клыка у наг в резервуаре Кривого Клыка и принесите его Исиэль Песни Ветра в Кенарийский приют в Зангартопи."}}
D[9766] = {"Оружие Кривого Клыка",{"Мы выкуем из стали наг оружие, и обратим его против них! Принеси мне все оружие, которое сможешь унести из резервуара Кривого Клыка."}}
D[9767] = {"Врага нужно знать в лицо",{"Добудьте книгу заклинаний клана Кривого Клыка у наг из резервуара Кривого Клыка и принесите ее Ашьену в Кенарийский приют в Зангартопи."}}
D[9769] = {"Мода непредсказуема!",{"Принесите 8 прозрачных крыльев любых видов светлячков, обитающих в Зангартопи, Магаше с заставы Болотной Крысы."}}
D[9770] = {"Опасные болотные клыки",{"Убейте 10 болотных потрошителей по просьбе Реавижа с заставы Болотной Крысы."}}
D[9771] = {"Поиски разведчика Джиобы",{"Ищите разведчика Джиобу."}}
D[9772] = {"Донесение разведчика Джиобы",{"Добудьте донесение разведчика Джиобы у высохших великанов и вернитесь с ним к Зураю на заставу Болотной Крысы."}}
D[9773] = {"Довольно грибов!",{"Добудьте 8 филе угря с угрей из озера Тенетопь и принесите их Магаше на заставу Болотной Крысы."}}
D[9774] = {"Толстая чешуя гидры",{"Принесите Зураю на заставу Болотной Крысы 12 толстых чешуек гидры."}}
D[9775] = {"Донесение темному охотнику Денжаю",{"Отнесите донесение Зурая темному охотнику Денжаю в Забра'джин."}}
D[9776] = {"Прибежище Оребор",{"Поговорите с Икути в прибежище Оребор."}}
D[9777] = {"Споры гриба-блескуна",{"Принесите 6 спор гриба-блескуна Руаму в Телредоре."}}
D[9778] = {"Страж Хамут",{"Поговорите со стражем Хамутом в Кенарийском приюте в Зангартопи."}}
D[9779] = {"Перехват сообщения",{"Найдите послание Солнечных Ястребов. Возможно, для этого придется убить нескольких из них. Послание должно быть доставлено на Кровавую заставу воздаятелю Боросу."}}
D[9780] = {"Филе угрей из озера Тенетопь",{"Принесите Нораани из Телредора 8 филе угря."}}
D[9781] = {"Слишком много ртов!",{"Убейте 10 болотных гидр и вернитесь к Хаалруну в Телредор."}}
D[9782] = {"Мертвая трясина",{"Принесите пробу почвы Мертвой трясины воздаятелю Идаару в Телредоре."}}
D[9783] = {"Неестественная засуха",{"Убейте 12 иссохших великанов по просьбе воздаятеля Идаара из Телредора."}}
D[9784] = {"Определение растений",{"Новые части растений мне всегда пригодятся! Сейчас, когда уровень воды в озерах постоянно снижается, у меня возникает чувство, что на болотах растет число пришлых растений. Однако чтобы подтвердить эту теорию, мне нужны точные цифры!"}}
D[9785] = {"Благословение Древ",{"Призывательница ветров Черное Копыто просит вас поговорить с древами Ашьеном и Келетом в Кенарийском приюте и получить их благословение."}}
D[9786] = {"Руины Боха'му",{"Исследуйте руины Боха'му по просьбе анахорета Ахуурна из Телредора."}}
D[9787] = {"Идолы Дикотопи",{"Соберите 6 идолов Дикотопи и вернитесь с ними к анахорету Ахуурну в Телредор."}}
D[9788] = {"Темное, сырое место",{"Отыщите вещи Икейена в пещере к югу от Тенетопи. Верните их Икейену в Кенарийском приюте в Зангартопи."}}
D[9789] = {"Охота на копытней",{"Убейте 30 копытней и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде."}}
D[9790] = {"Прозрачные крылья",{"Принесите Хаалруну из Телредора 8 прозрачных крыльев любых видов светляков, обитающих в Зангартопи."}}
D[9791] = {"Опасные болотные клыки",{"Убейте 10 болотных потрошителей и вернитесь к Нораани в Телредор."}}
D[9792] = {"Послание в Телаар",{"Поговорите с Нахуудом в Телааре в Награнде."}}
D[9793] = {"Судьба Туурема",{"Отнесите письмо воздаятеля Идаара Андарлу в бастион Аллерии в лесу Тероккар."}}
