D[9798] = {"Планы эльфов крови",{"Отнесите планы эльфов крови воздаятелю Алдару на место крушения в долине Аммен."}}
D[9799] = {"Сбор трав",{"Сорвите 3 оскверненных цветка и вернитесь к ученице Вишаэль на месте крушения в долине Аммен."}}
D[9800] = {"Редкий деликатес",{"Принесите повелителю стихий Ло'апу к Трону стихий в Награнде 15 семян караколлы."}}
