D[9896] = {"Проклятие черной бракониды",{"Принесите жало черной бракониды геологу Коналлу в Телредор."}}
D[9897] = {"Я спасена!",{"Отнесите сверток шкур Гарольду Лейну в лагерь Эрнестуэя в Награнде."}}
D[9898] = {"Лучшее доказательство любви!",{"Принесите жало черной бракониды Реавижу на заставу Болотной Крысы."}}
D[9899] = {"Несделанное дело",{"Убейте Спорокрыла по просьбе Магаши с заставы Болотной Крысы."}}
D[9900] = {"Гава'кси",{"Убейте Гава'кси, который скрывается близ Ошу'гуна, и возвращайтесь к Зериду в Небесный лагерь в Награнде."}}
D[9901] = {"Неоконченное дело",{"Убейте Спорокрыла по просьбе геолога Коналла из Телредора."}}
D[9902] = {"Ужас озера Болотных Огоньков",{"Убейте Жутеклешня и вернитесь к Пулуу в прибежище Оребор."}}
D[9903] = {"Самый здоровенный",{"Убейте Мрагеша и вернитесь к Зурджайе в Забра'джин."}}
D[9904] = {"Охота на Жутеклешня",{"Убейте Жутеклешня и вернитесь к Зурджайе в Забра'джин."}}
D[9905] = {"Месть Макту",{"Найдите и убейте Мрагеша, и вернитесь к Макту в прибежище Оребор."}}
D[9906] = {"Клинок вместо слов",{"Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 15 сокрушителей и 15 мистиков из клана Тяжелого Кулака."}}
D[9907] = {"Дерзкий набег",{"Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 25 воинов и 25 магов из клана Тяжелого Кулака."}}
D[9910] = {"Страх и уважение",{"Установите по одному боевому штандарту маг'харов возле первого, второго и третьего погребальных костров клана Пылающего Клинка. Когда выполните поручение, верните Илкай'гану Мистику оставшиеся штандарты."}}
D[9911] = {"Владыка болот",{"Принесите челюсть \"Графа\" Унгула караульному Лиса'о."}}
D[9912] = {"Кенарийская экспедиция",{"Поговорите с Исиэль Песнью Ветра в Кенарийском приюте в Зангартопи."}}
D[9913] = {"Консорциум ждет вас",{"Обратитесь к Гезхе. Его можно найти в Небесном лагере в Награнде."}}
D[9914] = {"Кость на вес золота",{"Добудьте 3 пары бивней элекков и принесите их Шадреку в Небесный лагерь в Награнде."}}
D[9915] = {"Кость на вес воздуха"}
D[9916] = {"Припасы клана Кровавой Глазницы",{"Найдите 20 ящиков с припасами клана Кровавой Глазницы и принесите их Илкай'гану Мистику."}}
D[9917] = {"Не верь глазам своим",{"Добудьте планы клана Тяжелого Кулака для охотницы Бинтук из Телаара."}}
D[9918] = {"Только не в мою смену!",{"Поговорите с Глыбом. Когда получите необходимые сведения, возвращайтесь к охотнице Бинтук."}}
D[9919] = {"Спореггар",{"Отправляйтесь в Спореггар, к северу от Грибной поляны, и отнесите спасенные мешочки спор Мссхи'фну."}}
D[9920] = {"Мо'мор Разрушитель",{"Охотница Бинтук из Телаара хочет, чтобы вы поговорили с Мо'мором Разрушителем."}}
D[9921] = {"Руины Пылающего Клинка",{"Мо'мор Разрушитель из Телаара желает, чтобы вы убили 15 мистиков и 15 сокрушителей из клана Тяжелого Кулака."}}
D[9922] = {"Расселины Награнда",{"Мо'мор Разрушитель из Телаара желает, чтобы вы убили 25 воинов и 25 магов из клана Тяжелого Кулака."}}
D[9923] = {"На помощь!",{"Найдите ключ клана Тяжелого Кулака и освободите Корки. После этого отправляйтесь к Арехрону в Телаар за наградой."}}
D[9924] = {"Корки снова пропал!",{"Найдите и освободите Корки."}}
D[9925] = {"Вопросы безопасности",{"Убейте 12 отроков Бездны поблизости от Ошу'гуна."}}
D[9926] = {"FLAG Совет Теней/Цепочка заданий Боевой Молот"}
D[9927] = {"Безжалостное коварство",{"Вонзите 20 знамен клана Боевого Молота в тела защитников бастиона Вечной Скорби.","","Верните Лантрезору Клинку оставшиеся знамена."}}
D[9928] = {"Военная хитрость",{"Принесите Лантрезору Клинку в руины Пылающего Клинка 20 ящиков с оружием из бастиона Вечной Скорби."}}
D[9929] = {"Пропавший торговец",{"Отправляйтесь по дороге на северо-запад, по направлению к Шаттрату, и поищите какие-нибудь намеки на то, что могло случиться с Дугаром."}}
D[9930] = {"Пропавший торговец",{"Отправляйтесь по дороге на северо-запад, по направлению к Шаттрату, и поищите какие-нибудь намеки на то, что могло случиться с Дейромом."}}
D[9931] = {"Взаимная вежливость",{"Воткните 20 знамен Вечной Скорби в трупы огров из клана Боевого Молота, обитающих в руинах Веселого Черепа.","","Оставшиеся знамена верните Лантрезору."}}
D[9932] = {"Вещественное доказательство",{"По поручению Лантрезора Клинка из руин Пылающего Клинка в Награнде найдите костер клана Боевого Молота во внутреннем дворе руин Веселого Черепа. С помощью мокрого шерстяного одеяла подайте дымовой сигнал ограм."}}
D[9933] = {"Послание в Телаар",{"Отнесите мирное подношение клана Пылающего Клинка Арехрону в Телаар."}}
D[9934] = {"Послание в Гарадар",{"Отнесите мирное подношение клана Пылающего Клинка Гаррошу в Гарадар."}}
D[9935] = {"Разыскивается: Гизельда Колдунья",{"Убейте Гизельда Колдунью и 15 любых служителей бастиона Вечной Скорби. Получите награду у стража-смотрителя Быккрока в Гарадаре."}}
D[9936] = {"Разыскивается: Гизельда Колдунья",{"Убейте Гизельда Колдунью и 15 любых служителей бастиона Вечной Скорби. Затем вернитесь к стражу-смотрителю Мой'прну Джиллу в Телаар."}}
D[9937] = {"Разыскивается: Дарн Ненасытный",{"Убейте Дарна Ненасытного. Вернитесь к стражу-смотрителю Быккроку и получите награду."}}
D[9938] = {"Разыскивается: Дарн Ненасытный",{"Убейте Дарна Ненасытного. Вернитесь к стражу-смотрителю Мой'прну Джиллу и получите награду."}}
D[9939] = {"Разыскивается: Зорбо Советчик",{"Убейте Зорбо Советчика, 10 шаманов и 10 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Быккрока."}}
D[9940] = {"Разыскивается: Зорбо Советчик",{"Убейте Зорбо Советчика, 10 шаманов и 10 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Мой'прна Джилла."}}
D[9941] = {"Выслеживание преступников",{"Продолжите поиски Дейрома в поселении араккоа к северу от сломанной повозки."}}
