D[9943] = {"Обратно к Тандеру",{"Вернитесь к Тандеру в Бастион Аллерии и расскажите ему о том, что вам удалось обнаружить."}}
D[9944] = {"Пропавший маг'харский караван",{"Найдите пропавший маг'харский караван."}}
D[9945] = {"Войной на Боевой Молот",{"Старейшина Йорли из Маг'харского Каравана в Награнде попросил вас убить 15 громил и 15 чернокнижников клана Боевого Молота."}}
D[9946] = {"Чо'вар Погромщик",{"Убейте Чо'вара Погромщика и принесите его голову старейшине Йорли в Маг'харский Караван."}}
D[9947] = {"Обратно к Рокагу",{"Вернитесь к Рокагу в Форт Камнеломов и расскажите ему о том, что вам удалось обнаружить."}}
D[9948] = {"Спасательная экспедиция",{"Освободите 15 пленных маг'харов."}}
D[9949] = {"Птичьи Глаза",{"Принесите Око Гнездовья Скит, Око Гнездовья Шиенор и Око Гнездовья Рескк Андарлу в Бастион Аллерии."}}
D[9950] = {"Птичьи Глаза",{"Принесите Око Гнездовья Скит, Око Гнездовья Шиенор и Око Гнездовья Рескк Каргатоку в Форт Камнеломов."}}
D[9951] = {"Он следит за тобой!",{"Убейте Нафталара и вернитесь к хранителю Древлосу в перелесок Кенария в лесу Тероккар."}}
D[9952] = {"Геолог Бальморал",{"Найдите геолога Бальморала и поговорите с ним."}}
D[9953] = {"Наблюдатель Нодак",{"Найдите наблюдателя Нодака и поговорите с ним."}}
D[9954] = {"Выкуп за Корки",{"Арехрон просит вас найти Корки на холме Боевого Молота."}}
D[9955] = {"Чо'вар Погромщик",{"Найдите Чо'вара, отберите у него ключ и освободите Корки из клетки. После этого отправляйтесь к Арехрону в Телаар за наградой."}}
D[9956] = {"Разграбленный караван",{"Помогите охотнице Киме вернуть 20 телаарских ящиков с припасами."}}
D[9957] = {"Что случилось в перелеске Кенария?",{"Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар."}}
D[9958] = {"Разведка укреплений",{"Подойдите поближе к Гнездовью Шалас и осмотрите защитные укрепления городка."}}
D[9959] = {"Разведка укреплений",{"Подойдите поближе к Гнездовью Шалас и постарайтесь узнать, что за магия защищает это поселение."}}
D[9960] = {"Что случилось в перелеске Кенария?",{"Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар."}}
D[9961] = {"Что случилось в перелеске Кенария?",{"Поговорите с одним из друидов в перелеске Кенария в лесу Тероккар."}}
D[9962] = {"Кольцо Крови: Хромоног",{"Одержите победу над Хромоногом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду."}}
D[9963] = {"Помощь от врага",{"Найдите Кокорека в Гнездовье Литик и поговорите с ним."}}
D[9964] = {"Помощь от врага",{"Найдите Кокорека в Гнездовье Литик и поговорите с ним."}}
D[9965] = {"Проявление веры",{"Принесите голову Муг'гока Кокореку в Гнездовье Литик."}}
D[9966] = {"Проявление веры",{"Принесите голову Муг'гока Кокореку в Гнездовье Литик."}}
D[9967] = {"Кольцо Крови: братья Блю",{"Одержите победу над близнецами из племени Темной Крови, которые называют себя \"Братья Блю\". После битвы обратитесь к троллю-прислужнику Водину и получите свою награду."}}
D[9968] = {"Странная энергия",{"Соберите 4 образца пухоспинки и 4 образца агрессивной пухоспинки для заклинателя земли Тавгрена. Его можно найти возле перелеска Кенария в лесу Тероккар."}}
D[9969] = {"Последние реагенты",{"Принесите 5 сущностей прыгуаны-охотника и 30 ягод тероккарской черной рябины Кокореку в Гнездовье Литик."}}
D[9970] = {"Кольцо Крови: Камнедар Выщербленный Повелитель",{"Победите Камнедара Выщербленного Повелителя. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду."}}
D[9971] = {"Ответы в чащобе",{"Осмотрите странный предмет рядом с трупом Сломленного и постарайтесь узнать, что случилось в перелеске Кенария. Затем вернитесь к заклинателю земли Тавгрену в лес Тероккар."}}
D[9972] = {"Кольцо Крови: Скрагат",{"Одержите победу над Скрагатом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду."}}
D[9973] = {"Кольцо Крови: чемпион клана Боевого Молота",{"Одержите победу над чемпионом клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду."}}
D[9974] = {"Последние реагенты",{"Принесите 5 сущностей прыгуаны-охотника и 30 ягод тероккарской черной рябины Кокореку в Гнездовье Литик."}}
D[9975] = {"Изначальная магия",{"Используйте талисман Кокорека возле тотемов, охраняющих завесу Шалас, после чего поговорите с геологом Бальморалом."}}
D[9976] = {"Изначальная магия",{"Используйте талисман Кокорека возле тотемов, охраняющих завесу Шалас, после чего поговорите с наблюдателем Нодаком."}}
D[9977] = {"Кольцо Крови: последнее испытание",{"Одержите победу над Могором, героем клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду."}}
D[9978] = {"Любыми средствами",{"Найдите Эмпура и убедите его рассказать вам все, что ему известно."}}
D[9979] = {"Латрай Торговец Ветром",{"Поговорите с торговцем ветром Латраем возле таверны \"На краю земли\" в Нижнем городе Шаттрата."}}
D[9980] = {"Спасите Дейрома!",{"Проберитесь в гнездовье Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Леди Дене Кеннеди в Бастионе Аллерии."}}
D[9981] = {"Спасите Дугара!",{"Проберитесь в завесу Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Рокагу в Форте Камнеломов."}}
D[9982] = {"Его звали Алтруис...",{"Если у вас есть желание сразиться с Пылающим Легионом, разыщите Алтруиса Страдальца в западном Награнде."}}
D[9983] = {"Его звали Алтруис...",{"Если у вас есть желание сразиться с Пылающим Легионом, разыщите Алтруиса Страдальца в западном Награнде."}}
D[9984] = {"Хозяин Сокрытого Города",{"Отнесите приказы Луанги Андарлу в бастион Аллерии, что в лесу Тероккар."}}
D[9985] = {"Хозяин Сокрытого Города",{"Отнесите приказы Луанги Каргатоку в форт Камнеломов."}}
D[9986] = {"Сдержать араккоа",{"Убейте Ашказа в гнездовье Рескк, Аийта в гнездовье Шиенор и Урдака в гнездовье Скит, после чего вернитесь к Тандеру в бастион Аллерии."}}
D[9987] = {"Сдержать араккоа",{"Убейте Ашказа в гнездовье Рескк, Айита в гнездовье Шиенор и Урдака в гнездовье Скит, после чего вернитесь к Рокагу в форт Камнеломов."}}
D[9988] = {"Лучший друг щеголя",{"Принесите 30 перьев араккоа Роз'алете в Бастион Аллерии."}}
D[9989] = {"Неведомые духи",{"Принесите 30 перьев араккоа Малуказу в форт Камнеломов."}}
D[9990] = {"Исследование Туурема",{"Найдите запечатанный ларец и отнесите его заклинателю земли Тавгрену. Тавгрена можно найти около перелеска Кенария в лесу Тероккар."}}
D[9991] = {"Разведка",{"Приведите спинку кресла в вертикальное положение и пристегните ремни безопасности. Приятного полета! Когда закончите осмотр лагерей с воздуха, доложите Алтруису обо всем, что вы видели."}}
D[9992] = {"Семена олембы",{"Соберите 30 семян олембы и отнесите их Роз'алете в бастион Аллерии."}}
D[9993] = {"Масло из семян олембы",{"Принесите 30 семян олембы Ракории в форт Камнеломов."}}
D[9994] = {"Что это такое?",{"Доставьте ящик с деталями Дженайе Шепот Звезд в бастион Аллерии в лесу Тероккар."}}
D[9995] = {"Что это такое?",{"Доставьте ящик с деталями Туки в форт Камнеломов в лесу Тероккар."}}
D[9996] = {"Нападение на лагерь Огнекрылых",{"Убейте 10 защитников, 10 кровавых стражей и 10 чернокнижников из армии Огнекрылых, после чего вернитесь к лейтенанту Меридиану на заставу Аллерии в лесу Тероккар."}}
D[9997] = {"Нападение на лагерь Огнекрылых",{"Убейте 10 защитников, 10 кровавых стражей и 10 чернокнижников из армии Огнекрылых, после чего поговорите с сержантом Чауни в лагере Камнеломов, что в лесу Тероккар."}}
D[9998] = {"Беспокойные соседи",{"Убейте 12 астральных батраков и доложите об этом Телории Плащ Теней на Аллерийскую заставу."}}
D[9999] = {"Выиграть время",{"Убейте 2 стражей Скверны - легионеров, 3 мо'аргов-инжененеров и 8 ган'аргов-ремонтников."}}
D[10000] = {"Нежелательное присутствие",{"Убейте 12 астральных батраков и доложите об этом тенелову Кайду."}}
D[10001] = {"Главный планировщик",{"Алтруис Страдалец из западного Награнда просит вас раздобыть чертежи главного планировщика."}}
D[10002] = {"Посредник Огнекрылых",{"Найдите и убейте Лизель Огнепрядку, после чего вернитесь к Телории Плащ Теней."}}
D[10003] = {"Посредник Огнекрылых",{"Найдите и убейте Лизель Огнепрядку, после чего вернитесь к тенелову Кайду."}}
