D[10091] = {"Инструменты души",{"Украдите 5 инструментов души и доставьте их повелительнице шпионов Мелисе Высокий Венец в Шаттрат на Террасу Света."}}
D[10092] = {"Атака на Магеддон",{"Убейте Владыку Ночи Малфаса, который находится на Кузнечной базе: Магеддон и возвращайтесь к властителю Хану Изуверу в Погибель Сквернобота."}}
D[10093] = {"Храм Телхамат",{"Поговорите с Амааном Мудрым в храме Телхамат, который находится на западе полуострова Адского Пламени."}}
D[10094] = {"Кодекс Крови",{"Прочитайте Кодекс Крови в Темном лабиринте в Аукиндоне."}}
D[10095] = {"В самом сердце Лабиринта",{"Уничтожьте Бормотуна и доложите о том, что произошло внутри Темного лабиринта, повелительнице шпионов Мелисе Высокий Венец, которую можно найти на террасе Света в Шаттрате."}}
D[10096] = {"Спасение спорлоков",{"Убейте 10 болотных черпальщиков и 10 болотных скрытней и вернитесь к Лоранне Тар'велл в Кенарийский приют в Зангартопи."}}
D[10097] = {"Брат на брата",{"Проникните в Сетеккские залы и убейте Темнопрядя Сита. Освободите из плена Лакку. После этого вернитесь к Исфару, который находится неподалеку от входа в Залы Сетека."}}
D[10098] = {"Наследство Терокка",{"Принесите Маску Терокка, Перо Терокка и Сагу о Терокке Исфару, который находится неподалеку от Сетеккских залов."}}
D[10099] = {"Мозговой центр",{"Найдите и убейте З'крала в рудниках под Оплотом Чести, и доложите об этом штейгеру Большие Десны."}}
D[10100] = {"Мозговой центр",{"Найдите и убейте Урга'зза в рудниках под Траллмаром, и доложите об этом штейгеру Разлкразу."}}
D[10101] = {"Когда говорят духи",{"Разыщите К'уре в Ошу'гуне."}}
D[10102] = {"Раскрытая тайна",{"Поговорите с А'далом в Шаттрате."}}
D[10103] = {"Донесение Зураю",{"Поговорите с Зураем на заставе Болотной Крысы в Зангартопи."}}
D[10104] = {"Опасения за судьбу Туурема",{"Поговорите с Андарлом в бастионе Аллерии в Тероккаре."}}
D[10105] = {"Вести для Ракории",{"Поговорите с Ракорией из форта Камнеломов в лесу Тероккар."}}
D[10106] = {"Штурмовые укрепления",{"Захватите обзорную площадку, ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на полуострове Адского Пламени."}}
D[10107] = {"Дипломатическая миссия",{"Джорин Мертвый Глаз из Гарадара в Награнде попросил вас поговорить с Лантрезором Клинком в руинах Пылающего Клинка."}}
D[10108] = {"Дипломатическая миссия",{"Мо'мор Разрушитель из Телаара в Награнде попросил вас поговорить с Лантрезором Клинком в руинах Пылающего Клинка."}}
D[10109] = {"Я их достану!",{"Принесите 3 порции пара элементалей воздуха Вазату в Южный Награнд."}}
D[10110] = {"Штурмовые укрепления",{"Захватите Обзорную площадку, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны."}}
D[10111] = {"Принеси мне яйцо!",{"С помощью Прыготрона-4000 запрыгните в гнездо на ближайшем дереве и украдите оттуда таинственное яйцо."}}
D[10112] = {"Личное одолжение",{"Найдите 5 украденных товаров Латрая и верните их хозяину. Латрая можно найти возле таверны \"На краю земли\" в Нижнем городе Шаттрата."}}
D[10113] = {"Охотничий лагерь Эрнестуэя",{"Поговорите с Хемингом Эрнестуэем в охотничьем лагере Эрнестуэя на северо-восточной границе Награнда."}}
D[10114] = {"Охотничий лагерь Эрнестуэя",{"Олорм Странник просит вас поговорить со Странником Шадо \"Фитцем\" в охотничьем лагере Эрнестуэя в Награнде."}}
D[10115] = {"Искажение Остротопи",{"Убейте 3 убийц Остротопи и 15 грязекопов Остротопи."}}
D[10116] = {"Разыскивается: вождь Муммаки!",{"Принесите тотем вождя Муммаки Икути в прибежище Оребор."}}
D[10117] = {"Разыскивается: вождь Муммаки!",{"Принесите тотем вождя Муммаки темному охотнику Денжаю."}}
D[10118] = {"Разговор с Остротопью",{"Убейте 3 убийц и 15 грязекопов из племени Остротопи, и вернитесь к темному охотнику Денжаю в Забра'джин."}}
D[10119] = {"Через Темный портал",{"Пройдите через Темный портал и найдите командора Дарона. Он ждет вашего прибытия на другой стороне, в Запределье."}}
D[10120] = {"Прибытие в Запределье",{"Доставьте донесение Ориона Влагге Легкоперой у Темного портала на полуострове Адского Пламени."}}
D[10121] = {"Истребить Пылающий Легион",{"Поговорите с сержантом Лободробом, который находится при караване к востоку от Траллмара."}}
D[10122] = {"Вблизи цитадели",{"Найдите следы рядового Имариона у самого северного лагеря орков Скверны, расположенного у Южного бастиона."}}
D[10123] = {"Лощина Вспышки Скверны",{"Убейте 4 бесов-поджигателей, 6 инферналов-завоевателей и 1 вестника Ужаса по просьбе сержанта Лободроба, который находится при караване к востоку от Траллмара."}}
D[10124] = {"Передовая застава: Останки Сквернобота",{"Доложитесь командиру передовой То'арху по прибытии к останкам Сквернобота."}}
D[10125] = {"Задание: разрушить связь",{"Уничтожьте Антенну Легиона: Злоба, Антенну Легиона: Ярость, Антенну Легиона: Ненависть, Антенну Легиона: Страх с помощью взрывчатки То'арха по приказу командира передовой То'арха в Погибели Сквернобота на Полуострове Адского Пламени."}}
D[10126] = {"Приказы боевого командира Некрогга",{"Проследуйте к югу вдоль западной части Южного бастиона и разыщите в одном из лагерей следы рядового Имариона."}}
D[10127] = {"Задание: Ослабить врага",{"Убейте 4 укротителей Скверны, 8 гневостражей и поработительницу Ши'азив по приказу командира передовой То'арха у останков Сквернобота на Полуострове Адского Пламени."}}
D[10128] = {"Спасти рядового Имариона",{"Следуйте дальше к югу вдоль Южного бастиона и постарайтесь найти, где боевой командир Некрогг держит в плену рядового Имариона."}}
D[10129] = {"Задание: Врата Муркет и Шаадраз",{"Поговорите с командиром звена Бракком, разбомбите Врата Муркет и Шаадраз, затем возвращайтесь к командиру передовой То'арху к останкам Сквернобота."}}
D[10130] = {"Западный фланг",{"Убейте 10 стражников, 10 берсерков и 5 послушников из клана Изувеченной Длани. О выполнении задания доложите лейтенанту Амади, которая будет ждать вас в западной сторожевой башне Оплота Чести."}}
D[10131] = {"План побега",{"Убейте гренадера клана Изувеченной Длани и принесите примитивную взрывчатку рядовому Имариону в форт Гор'газ."}}
D[10132] = {"Колоссальная угроза",{"Убейте 5 яростных колоссов и возвращайтесь к Тола'тиону на Кенарийскую заставу на полуострове Адского Пламени."}}
D[10133] = {"Задание: убить гонца",{"Найдите Арикс'малидаша, убейте его и заберите Послание Легиона по приказу командира передовой То'арха у останков Сквернобота."}}
D[10134] = {"Ключ к разгадке алого кристалла",{"Доставьте осколок алого кристалла Тола'тиону на Кенарийскую заставу на полуострове Адского Пламени."}}
D[10135] = {"Задание: доставить послание",{"Доставьте Послание Легиона Назгрелу в Траллмар на Полуострове Адского Пламени."}}
D[10136] = {"Безжалостные планы",{"Убейте Араззиуса Безжалостного и возвращайтесь к Назгрелу в Траллмар."}}
D[10137] = {"Провокация",{"Используйте примитивную взрывчатку, чтобы создать шум и выманить боевого командира Некрогга из его башни. Убейте его, заберите Ключ Некрогга и откройте клетку рядового Имариона. Об освобождении рядового Имариона доложите лейтенанту Амади."}}
D[10138] = {"Кто отдает приказы?",{"Убейте 20 рубак и 10 чернокнижников клана Изувеченной Длани и захватите распоряжения военного инструктора Зурока. После этого возвращайтесь к лейтенанту Амади в западную сторожевую башню Оплота Чести."}}
D[10139] = {"Разжаловать командира",{"Уничтожьте командира соединения Горакса и доложите о выполнении задания лейтенанту Амади, которая находится в западной башне Оплота Чести."}}
D[10140] = {"Путешествие в Оплот Чести",{"Долетите до Оплота Чести и доставьте донесение Дурона маршалу Исилдору."}}
D[10141] = {"Возрожденный Легион",{"Поговорите с сержантом Альтумой, которая находится рядом с восточным караваном, к востоку от Оплота Чести."}}
D[10142] = {"Путь Страданий",{"Убейте 4 бесов-поджигателей, 6 инферналов-завоевателей и 1 вестника ужаса по приказу сержанта Альтумы из восточного каравана, который находится на востоке от Оплота Чести на полуострове Адского Пламени."}}
D[10143] = {"Лагерь экспедиции",{"Доложитесь командиру передовой Кингстону в лагере экспедиции."}}
D[10144] = {"Лишить Легион подкрепления!",{"Уничтожьте врага вокруг порталов Грим и Каалез и соберите камни с рунами демонов.","","Забросьте запалы Кингстона в порталы Грим и Каалез.","","После выполнения задания возвращайтесь к командиру передовой Кингстону вместе с оставшейся взрывчаткой."}}
D[10145] = {"Mission: Sever the Tie UNUSED",{"Уничтожьте 4 укротителя Скверны, 8 гневостражей и Поработителя Ялквиза по приказу командира передовой Кингстона из лагеря экспедиции на Полуострове Адского Пламени."}}
D[10146] = {"Задание: Врата Муркет и Шаадраз",{"Поговорите с командиром звена Даби'ри, разбомбите Врата Муркет и Врата Шаадраз, затем возвращайтесь к командиру передовой Кингстону в Лагерь экспедиции."}}
D[10147] = {"Задание: убить гонца",{"Отыщите Арикс'малидаша, убейте его и заберите Послание Легиона по приказу командира передовой Кингстона из лагеря экспедиции на Полуострове Адского Пламени."}}
D[10148] = {"Задание: доставить послание",{"Доставьте Послание Легиона командиру армии Данату Троллебою в Оплот Чести на Полуострове Адского Пламени."}}
D[10149] = {"Задание: со щитом или на щите",{"Убейте Араззиуса Безжалостного по приказу командира армии Даната Троллебоя из Оплота Чести на Полуострове Адского Пламени."}}
D[10150] = {"Вблизи цитадели",{"Постарайтесь найти следы разведчицы Махи в одном из лагерей, расположенных вдоль Северного бастиона."}}
D[10151] = {"Приказы боевого командира Некрогга",{"Отправляйтесь к югу вдоль западной стороны Северного бастиона и постарайтесь найти следы разведчицы Махи в одном из лагерей."}}
D[10152] = {"Западный фланг",{"Убейте 10 стражников, 10 берсерков и 5 послушников из клана Изувеченной Длани. О выполнении задания доложите каменному стражу Амбелану, который находится на заставе Раздробленного Хребта, рядом с Зет'Гором."}}
D[10153] = {"Спасти разведчицу Маху",{"Следуйте дальше к югу вдоль Южного бастиона и постарайтесь найти, где боевой командир Некрогг держит в плену разведчицу Маху."}}
D[10154] = {"План побега",{"Убейте гренадера клана Изувеченной Длани и принесите примитивную взрывчатку разведчице Махе в форт Гор'газ."}}
D[10155] = {"Провокация",{"Используйте примитивную взрывчатку, чтобы создать шум и выманить боевого командира Некрогга из его башни. Убейте его, заберите Ключ Некрогга и откройте клетку разведчицы Махи. Об освобождении разведчицы Махи доложите каменному стражу Амбелану на Заставу Разрушенного Хребта рядом с Зет'Гором."}}
D[10156] = {"Кто отдает приказы?",{"Убейте 20 рубак и 10 чернокнижников клана Изувеченной Длани и захватите распоряжения военного инструктора Зурока. После этого возвращайтесь к каменному стражу Амбелану на Заставу Хребтолома."}}
D[10157] = {"Разжаловать командира",{"Уничтожьте командира соединения Горакса и доложите о выполнении задания темному охотнику Ти'джину из Траллмара."}}
D[10158] = {"Припасы Кровавой Глазницы",{"Уничтожьте 6 складов припасов клана Кровавой Глазницы и доложите о выполнении задания каменному стражу Амбелану с Заставы Хребтолома."}}
D[10159] = {"Очистить холм Колючего Клыка!",{"Убейте 8 опустошителей Колючего Клыка и 8 ядоплюев Колючего Клыка. После выполнения задания возвращайтесь к Махураму Крепкому Копыту на Кенарийскую заставу на полуострове Адского Пламени."}}
D[10160] = {"Врага нужно знать в лицо",{"Поговорите с лейтенантом Амади в старой сторожевой башне на западе Оплота Чести."}}
D[10161] = {"В случае чрезвычайной ситуации...",{"Соберите 30 обломков дирижабля и принесите Скриду Многослову по прозвищу \"Крикун\" на место крушения дирижабля."}}
D[10162] = {"Задание: Косогор Бездны",{"Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по приказу командира передовой То'арха у останков Сквернобота на полуострове Адского Пламени."}}
D[10163] = {"Задание: Косогор Бездны",{"Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по приказу командира звена Грифонгара с Парящей заставы на полуострове Адского Пламени."}}
D[10164] = {"Все будет в порядке",{"Проникните в Аукенайские гробницы и уничтожьте экзарха Маладаара по просьбе Великого Отца Алдримуса, который находится снаружи Аукенайских гробниц Аукиндона."}}
D[10165] = {"Жестокая вещь – конкуренция",{"Убейте принца нексуса Шаффара по просьбе принца нексуса Харамада, находящегося снаружи Гробниц маны, и принесите ему обмотки Шаффара."}}
D[10166] = {"Память о Белостволе",{"Заройте подвеску Старого Белоствола у рунического камня в Выжженной роще по просьбе Ларианны Речной Ветер."}}
D[10167] = {"Аукиндон...",{"Отправляйтесь в Аукенайские гробницы в Костяных пустошах леса Тероккар, убейте экзарха Маладаара и освободите дух Д'оре."}}
D[10168] = {"Что видит душа",{"Найдите зеркало Души в Аукенайских гробницах и используйте его, чтобы выманить темного духа из древнего орка-предка в Награнде. Уничтожьте 15 темных духов, чтобы орочьи предки могли упокоиться с миром.","","Когда исполните поручение, возвращайтесь к Матери Кашур в Земли Предков."}}
D[10169] = {"Проиграть с честью",{"Вылейте сонную сыворотку в котел Харонема на террасе Света, после чего вернитесь к магистру Фальрису."}}
D[10170] = {"Возвращение к Великой Матери",{"Возвращайтесь в Гарадар и поговорите с великой матерью Гейей."}}
D[10171] = {"Безутешный Вождь",{"Поговорите с Гаррошем."}}
D[10172] = {"Надежды нет",{"Вернитесь к Великой Матери Гейе и передайте ей слова Гарроша."}}
D[10173] = {"Посох верховного мага",{"Отнимите посох верховного мага Варгота у Эккораш Инквизитора и принесите Равандвиру в Зону 52. Чтобы выманить Эккораш из укрытия, бросьте волшебный порошок на жаровню в центре руин."}}
D[10174] = {"Проклятие Аметистовой башни",{"Используйте посох верховного мага Варгота, чтобы связаться с верховным магом Варготом.","","Если вы утратили посох верховного мага Варгота, поговорите с Равандвиром в Зоне 52, чтобы получить замену."}}
D[10175] = {"Тралл, сын Дуротана",{"Отправляйтесь в Оргриммар и передайте Траллу сообщение от Гейи."}}
D[10176] = {"Страж Ар'келос",{"Войдите в Аметистовую башню, расположенную в центре деревни Кирин'Вар, и победите Ар'келоса, затем поговорите с верховным магом Варготом."}}
D[10177] = {"В Аукиндоне неспокойно",{"Доложите о своем прибытии боевому командиру Мафууну, который находится неподалеку от входа в Темный Лабиринт в Аукиндоне в Лесу Тероккар."}}
D[10178] = {"Найти шпиона То'гуна!",{"Найдите шпиона То'гуна в Темном лабиринте в Аукиндоне."}}
D[10179] = {"Смотритель Кирин'Вара",{"Поговорите со смотрителем Дайвортом в деревне Кирин'Вар."}}
D[10180] = {"Неудержимый",{"Поговорите с Исфаром, которого можно найти неподалеку от входа в Сетеккские залы в Аукиндоне."}}
D[10182] = {"Боевой маг Датрик",{"Найдите апартаменты боевого мага Датрика в переулке Волшебников и верните меч в оружейную стойку. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар."}}
D[10183] = {"В Зону 52",{"Передайте записки пустолога ведущему ракетостроителю Фьюзеляжу, находящемуся в Зоне 52 в Пустоверти."}}
D[10184] = {"Зловещие останки",{"Смотритель Дайворт в деревне Кирин'Вар просит вас победить 20 покалеченных духов на площади Кирин'Вара."}}
D[10185] = {"Участь хуже, чем смерть",{"Убейте 10 убийц магов и 10 искателей маны и вернитесь к смотрителю Дайворту в деревню Кирин'Вар."}}
D[10186] = {"Тебя наняли!",{"Соберите 10 астраллитиевых матричных кристаллов и принесите их ведущему ракетостроителю Фьюзеляжу в Зону 52 в Пустоверти."}}
D[10187] = {"Послание для верховного мага",{"Поговорите с Верховным магом Варготом на вершине Сиреневой башни."}}
D[10188] = {"Печать Краса",{"Заберите печать Краса у заклинательницы Марианы, находящейся в манагорне Коруу, к северо-востоку от Аметистовой башни. Когда вы получите печать, используйте посох верховного мага Варгота, чтобы вызвать проекцию верховного мага Варгота и сообщить ему о том, как подвигается дело.","","Если вы утратили посох верховного мага Варгота, поговорите с Равандвиром, находящимся в Зоне 52, чтобы получить замену."}}
D[10189] = {"Манагорн Б'наар",{"Патрон шпионов Талодиен, находящийся в Зоне 52, хочет, чтобы вы направились в окрестности манагорна Б'наар и отобрали список персонала манагорна Б'наар у капитана Аратина.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10190] = {"Перезарядка батарей",{"Используйте зарядное устройство для батарей применительно к достаточному количеству внепространственных охотников, чтобы довести зарядку батарей до уровня 10. Затем вернитесь к роботехнику Элли в руины Энкаата в Пустоверти."}}
D[10191] = {"Робот модели V жив!",{"Сопроводите \"Маккса А. Миллиона V\" через руины Энкаата и обратно, обеспечив ему безопасность. Потом поговорите с роботехником Элли за пределами руин Энкаата в Пустоверти."}}
D[10192] = {"Компендиум Краса",{"Заберите первую, вторую и третью главы компендиума Краса с главной площади деревни Кирин'Вар. Затем используйте посох верховного мага Варгота, чтобы связаться с верховным магом.","","Если вы утратили посох верховного мага Варгота, поговорите с Равандвиром, находящимся в Зоне 52, чтобы получить замену."}}
D[10193] = {"Высокие цели",{"Патрон шпионов Талодиен, находящийся в Зоне 52, просит вас отправиться в манагорн Б'наар и убить 2 мастеров пространственных искривлений, 6 инженеров пространственных искривлений и 8 геологов из клана Ярости Солнца.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10194] = {"Незаметный полет",{"Поговорите с Веронией, находящейся за пределами Зоны 52, и летите к манагорну Коруу.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10195] = {"Наемник видит, наемник делает",{"Принесите 30 перьев араккоа Роз'алете в Бастион Аллерии."}}
D[10196] = {"Больше перьев араккоа",{"Принесите 30 перьев араккоа Малуказу в Форт Камнеломов."}}
D[10197] = {"Убедительная маскировка",{"Добудьте комплект одеяний чародея из армии Ярости Солнца, одну пару перчаток ученого из армии Ярости Солнца и медальон охранника из армии Ярости Солнца и принесите все это Каледису Сияющему Рассвету в манагорн Коруу в Пустоверти.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10198] = {"Сбор информации",{"Используя маскировку армии Ярости Солнца, проникните в манагорн Коруу и подслушайте разговор между командиром Кузней Солнца и чародеем Ардонисом. По завершении задачи доложите о результатах Каледису Сияющему Рассвету.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10199] = {"Дополнительная сила",{"Принесите 5 шипов скатов Пустоты Бутсу, находящемуся в Зоне 52 в Пустоверти."}}
D[10200] = {"Возвращение к Талодиену",{"Вернитесь к патрону шпионов Талодиену в Зону 52 в Пустоверти."}}
D[10201] = {"Момент истины",{"Найдите Грека и попросите его смазать маслом свое оружие, после чего вернитесь к Ракории."}}
D[10202] = {"Дезертир",{"Отправляйтесь в манагорн Ара и поговорите с магистром Теледорном.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10203] = {"Захват бесценного оборудования",{"Используйте ультра-разуплотняющий захват, чтобы доставить гиперротационный Рой-О-Мат, сервоприводную пневматическую землечерпалку, радужный световой анализатор грунта и большой фургон с взрывчаткой обратно в Зону 52. Затем сообщите старшему саперу Бджимбуму, находящемуся на восточном конце расселины, идущей через Зону 52 в Пустоверти."}}
D[10204] = {"Кристаллы камня Крови",{"Магистр Ларинна просит вас отправиться в манагорн Б'наар и отобрать осколок камня крови у магистра из клана Ярости Солнца. Используйте этот осколок поблизости от более крупного кристалла камня крови и возвращайтесь к Ларинне в Зону 52.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10205] = {"Астральный налетчик Несаад",{"Убейте астрального налетчика Несаада, затем возвращайтесь к ловчему Пустоты Кай'джи, находящемуся в Зоне 52 в Пустоверти."}}
D[10206] = {"В погоне за технологиями",{"Соберите 10 астральных технологий и вернитесь с ними к Папаше Колесуну, находящемуся в Зоне 52 в Пустоверти."}}
D[10207] = {"Forward Base: Reaver's Fall REUSE",{"Доложитесь командиру передовой То'арху по прибытии к останкам Сквернобота."}}
D[10208] = {"Лишить Легион подкрепления!",{"Уничтожьте врагов вокруг портала Зилус и портала Круул, соберите камни с рунами демонов.","","Используйте запалы То'арха внутри порталов Зилус и Круул.","","Возвращайтесь к То'арху в Гибель Сквернобота на полуострове Адского Пламени вместе с оставшимися запалами."}}
D[10209] = {"Трофей призывателя Кантина",{"Победите призывателя Кантина, находящегося в манагорне Даро, на острове к северу от форта Ярости Солнца, и заберите у него камень Студенора. Когда заберете камень, используйте посох верховного мага Варгота, чтобы связаться с верховным магом.","","Если вы утратили посох верховного мага Варгота, поговорите с Равандвиром, находящимся в Зоне 52, чтобы получить замену."}}
D[10210] = {"А'дал",{"Поговорите с А'далом, предводителем Ша'тар, в центре террасы Света."}}
D[10211] = {"Город Света",{"Проследуйте за слугой Кадгара и выслушайте историю, которую он вам расскажет, после чего вернитесь к Кадгару."}}
D[10212] = {"Герой маг'харов",{"Вернитесь к великой матери Гейе в Гарадар в Награнде."}}
D[10213] = {"Найти место крушения",{"Отыщите уцелевших в катастрофе."}}
D[10214] = {"Весь рудник ходуном",{"Убейте 15 ган'аргов-саперов и возвращайтесь к штейгеру Разлкразу."}}
D[10216] = {"Прежде всего - безопасность!",{"Убейте 10 эфириалов-осквернителей гробниц, 5 эфириалов-колдунов, 5 ловчих нексуса и 5 эфириалов-чароплетов по просьбе работника Морфалиуса.","","После этого найдите эфириальский телепорт в зале, предшествующем палате Шаффара, и активируйте его."}}
D[10218] = {"Someone Else's Hard Work Pays Off",{"Проводите криоинженера Ша'хина в Гробницы маны, чтобы он мог собрать астральную субстанцию в коллекторах Шаффара.","","В случае успеха явитесь к принцу нексуса Харамаду в лагере Консорциума."}}
D[10219] = {"Выгул собаки"}
D[10220] = {"Заставь их слушать",{"Убейте 12 непреклонных пехотинцев, 8 непреклонных рыцарей и 6 непреклонных колдунов в оружейной экспедиции к западу от заставы Хребтолома по просьбе Мордибы."}}
D[10221] = {"Доктор Бум!",{"Убейте Доктора Бума и возвращайтесь с хорошими новостями к старшему саперу Бджимбуму в Зону 52 в Пустоверти."}}
D[10222] = {"Гарнизон Ярости Солнца",{"Смотритель Дайворт из деревни Кирин'Вар просит вас убить 10 лучников из армии Ярости Солнца."}}
D[10223] = {"Покончить с Даэллисом",{"Смотритель Дайворт из деревни Кирин'Вар просит вас убить наставника Даэллиса Стрелка Рассвета."}}
D[10224] = {"Эссенция для двигателей",{"Соберите 7 единиц эссенции призрака магии и доставьте главному инженеру Трепу в Зону 52 в Пустоверти."}}
D[10225] = {"Рапорт главному инженеру",{"Передайте астраллитиевые матричные кристаллы главному инженеру Трепу, находящемуся в Зоне 52 в Пустоверти."}}
D[10226] = {"Извлечение силы стихии",{"Извлеките 5 единиц силы стихии для главного инженера Трепа, находящегося в Зоне 52 в Пустоверти."}}
D[10227] = {"Я вижу мертвых дренеев",{"Поговорите с Рамдором Безумным, который стоит на груде костей неподалеку от Аукенайских гробниц."}}
D[10228] = {"Иезекииль",{"Найдите Иезекииля из Шаттрата в городе Шаттрат и поговорите с ним."}}
D[10229] = {"Секрет фолианта",{"Отнесите таинственный фолиант Альтену Историку на Заставу Хребтолома."}}
D[10230] = {"Боевой рог",{"Заберите у лейтенанта-командора Талвоса Боевой рог Непреклонных и принесите его Альтену Историку на Заставу Хребтолома."}}
D[10231] = {"Какая книга? Не вижу никакой книги",{"Иезекииль говорит, что книга могла быть украдена. Найдите головорезов и попытайтесь узнать что-нибудь у них."}}
D[10232] = {"Легион – на мусор!",{"Убейте 5 мо'аргов-кузнецов рока и 15 ган'аргов-инженеров. Затем возвращайтесь к Папаше Колесуну в Зону 52 в Пустоверти."}}
D[10233] = {"Пожар в форте Ярости Солнца",{"Используя горящий факел, уничтожьте 4 баллисты и 4 шатра в форте Ярости Солнца, затем вернитесь к лейтенанту-чародею Моррану в деревню Кирин'Вар."}}
D[10234] = {"Что одному демону мусор...",{"Соберите 10 деталей сквернобота и доставьте их Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти."}}
D[10235] = {"Коготь Рока? Вырвать с мясом!",{"Заберите руку Когтя Рока и доставьте ее Мамаше Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти."}}
D[10236] = {"Гадость это ваше Запределье!",{"Найдите 6 частей крошшера и верните их штейгеру Разлкразу на рудник, который находится к северо-западу от Траллмара."}}
D[10237] = {"Предупредить Зону 52!",{"Передайте плохие новости ведущему ракетостроителю Фьюзеляжу в Зоне 52 в Пустоверти."}}
D[10238] = {"Каково работать на гоблинов",{"Спасите Манни, Моха и Джакка из лагерей орков Скверны и доставьте их штейгеру Разлкразу на рудник, который находится к северо-западу от Траллмара."}}
D[10239] = {"Потенциальный источник энергии",{"Лейтенант-чародей Морран из деревни Кирин'Вар просит вас захватить 10 энергетических кубов-изоляторов, используемых эльфами крови в манагорне Коруу."}}
D[10240] = {"Постройка периметра",{"Используйте устройство пробуждения рун поблизости от восточной, северо-восточной и западной руны. Руны можно найти по периметру районов переулка Волшебников и главной площади деревни Кирин'Вар. По завершении задачи вернитесь к лейтенанту-чародею Моррану."}}
D[10241] = {"Отвлекающий маневр в манагорне Б'наар",{"Убейте 8 магистров и 8 кровостражей клана Ярости Солнца, затем возвращайтесь к экзарху Орелису в Зону 52.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10242] = {"Застава Хребтолома",{"Доставьте образец крови орков из клана Кровавой Глазницы аптекарю Альбреку на заставу Хребтолома по просьбе аптекаря Зеланы из Погибели Сквернобота. Чтобы добраться до заставы на виверне, обратитесь к командиру звена Бракку."}}
D[10243] = {"Технология наару",{"Зайдите в манагорн Б'наар и найдите панель управления манагорном.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10244] = {"Учи матчасть!",{"Отнесите инструкцию по созданию сквернобота Мамаше Колесун, находящейся на Заставе срединных земель в заповеднике \"Срединные земли\" в Пустоверти."}}
D[10245] = {"Описание панели управления Б'наара",{"Передайте описание панели управления Б'наара анахорету Карже в Зону 52 в Пустоверти.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10246] = {"Нападение на манагорн Коруу",{"Отправляйтесь к манагорну Коруу и убейте 8 чародеев и 5 ученых из армии Ярости Солнца. По завершении задачи возвращайтесь к экзарху Орелису.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10247] = {"Вомиза, доктор псевдотехнических наук",{"Поговорите с доктором псевдотехнических наук Вомизой на Испытательном полигоне в Пустоверти."}}
D[10248] = {"Ты, робот",{"Активируйте пульт управления \"Утилизатора Х6000\" и проверьте его возможности. Затем передайте результаты доктору псевдотехнических наук Вомице, находящемуся на испытательном полигоне в Пустоверти. Если возникнут проблемы, разберитесь с ними.."}}
D[10249] = {"Обратно к командующему!",{"Немедленно явитесь к ведущему ракетостроителю Фьюзеляжу в Зону 52 в Пустоверти!"}}
D[10250] = {"Кровавая месть",{"Подуйте в боевой рог Непреклонных рядом со знаменем Альянса. Убейте Уртрака и возвращайтесь к Альтену Историку на Заставу Хребтолома."}}
D[10251] = {"Великий замысел господина?",{"Найдите Нитрина Сведущего в Заброшенной оружейной в Награнде."}}
D[10252] = {"Посмотри в глаза мертвым",{"Принесите Нитрину из Заброшенной оружейной Награнда 1 глаз горного гронна, 1 безупречный клюв большого вертуха и 1 сальник старого копытня."}}
D[10253] = {"Левиксус Призыватель Душ",{"Убейте Левиксуса и заберите у него Книгу Мертвых.","","Отнесите Книгу Рамдору Безумному, который находится неподалеку от входа в Аукенайские гробницы в Аукиндоне.","","Вы ведь с ним об этом договаривались, помните?"}}
D[10254] = {"Командир армии Данат",{"Доставьте по приказу маршала Исилдора донесение командиру армии Данату Троллебою в Оплот Чести."}}
D[10255] = {"Проверка противоядия",{"Введите кенарийское противоядие крупному зловепрю и пронаблюдайте за результатом. После проведения эксперимента возвращайтесь к Тие Рыжей Гриве на Кенарийскую заставу на полуострове Адского Пламени."}}
D[10256] = {"Найти Хранителя Ключей",{"Выследите Камнегора и заберите у него кристальное средоточие. Вернитесь к Сиреневой башне и используйте кристальное средоточие Камнегора поблизости от шара верховного мага Варгота для того, чтобы обнаружить, у кого хранятся ключи от проклятия башни."}}
D[10257] = {"Захват краеугольного камня",{"Проникните в Ботанику в Крепости Бурь и заберите ключ у командира Сараннис. Отнесите ключ верховному магу Варготу в Аметистовую башню."}}
D[10258] = {"Честь Павших",{"Явитесь к командиру Хогарду, который находится в оружейной экспедиции."}}
D[10259] = {"Битва в Проломе",{"Убейте 6 вторгшихся стражей Скверны и затем вернитесь к посланнику ордена Серебряного Рассвета Праудвелл."}}
D[10260] = {"Пустолог Медноклеппер",{"Поговорите с Пустологом Медноклеппером у моста, ведущего от Пустоверти к Острогорью."}}
D[10261] = {"Разыскивается: аннигиляторный сервопривод!",{"Заберите аннигиляторный сервопривод и доставьте его Папаше Колесуну в Зону 52 Пустоверти."}}
D[10262] = {"Груда духов Астрала",{"Соберите 10 знаков отличия братства Заксис и принесите их ловчему Пустоты Кай'джи, находящемуся в Зоне 52 в Пустоверти."}}
D[10263] = {"Содействие Консорциуму",{"Поговорите с ловчим Пустоты Кай'джи в Зоне 52 в Пустоверти."}}
D[10264] = {"Содействие Консорциуму",{"Поговорите с ловчим Пустоты Кай'джи в Зоне 52 в Пустоверти."}}
D[10265] = {"Добыча артефакта для Консорциума",{"Заполучите кристаллический артефакт Арклона и верните его ловчему Пустоты Кай'джи, находящемуся в Зоне 52 в Пустоверти."}}
D[10266] = {"Запрос о содействии",{"Найдите Гаруджа и предложите ему свои услуги. Он находится на заставе внутри заповедника \"Срединные земли\" в Пустоверти."}}
D[10267] = {"Изъятие по праву",{"Заберите 10 ящиков с геодезическим снаряжением и верните их Гаруджу, находящемуся на заставе внутри заповедника \"Срединные земли\" в Пустоверти."}}
D[10268] = {"Аудиенция у принца",{"Доставьте геодезическое снаряжение к проекции принца нексуса Харамада в Штормовую Вершину в Пустоверти."}}
D[10269] = {"Триангуляция: точка первая",{"Используйте триангуляционный прибор, чтобы найти путь к первой точке триангуляции. Как только найдете точку, сообщите ее местонахождение дельцу Хаззину, находящемуся на заставе Протектората на острове манагорна Ультрис в Пустоверти."}}
D[10270] = {"Нескромное предложение",{"Найдите аккумулятор для телепортатора и отнесите его к площадке астрального телепорта на Небесной гряде. Активируйте площадку и отдайте аккумулятор проекции торговца ветром Марида, чтобы он мог установить его."}}
D[10271] = {"Деловая активность",{"Соберите 8 единиц эссенции дракона Пустоты, затем возвращайтесь в зону площадки астрального телепорта. Эссенцию дракона Пустоты можно получить из старых или молодых драконов Пустоты."}}
D[10272] = {"Многообещающее начало",{"Соберите 15 яиц драконидов Пустоты, затем возвращайтесь к Тири и Джораду на Небесную гряду."}}
D[10273] = {"Пустые хлопоты",{"Поговорите с торговцем Ветром Маридом и выманите его из торгового поста. Покончите с ним, затем вернитесь к Тири и Джораду на Небесную гряду."}}
D[10274] = {"Безопасность Небесной гряды",{"Используйте вызов синих драконов, чтобы вызвать на бой Вераку, живущего на южном склоне Небесной гряды. Победите его и возвращайтесь к Тири и Джораду, ожидающим на Небесной гряде."}}
D[10275] = {"Триангуляция: точка вторая",{"Используйте триангуляционный прибор, чтобы найти путь ко второй точке триангуляции. Как только найдете точку, сообщите ее местонахождение торговцу ветром Тулуману, находящемуся в лагере Тулумана, по другую сторону моста, ведущего от острова манагорна Ара в Пустоверти."}}
D[10276] = {"Полный треугольник",{"Заберите кристалл Ата'мала и передайте его проекции принца нексуса Харамада, находящейся в Штормовой Вершине в Пустоверти."}}
D[10277] = {"Пещеры Времени",{"Андорму попросил вас пройти по пещерам вместе с хранительницей времени."}}
D[10278] = {"Астральные провалы",{"Используйте нестабильный генератор астральных провалов на Искривленных полях. Соберите три горсти пыли Пустоты с нестабильных демонов Бездны и возвращайтесь к Огафу Безумному на заставу Хребтолома."}}
D[10279] = {"Логово господина",{"Поговорите с Андорму в пещерах Времени."}}
D[10280] = {"Специальный груз в город Шаттрат",{"Передайте кристалл Ата'мала А'далу на террасе Света в городе Шаттрат."}}
D[10281] = {"Формальное представление",{"Найдите Тири на северной оконечности Небесной гряды и поговорите с ней."}}
D[10282] = {"Старый Хилсбрад",{"Отправьтесь по тропе времени в старый Хилсбрад и поговорите с Эрозионом."}}
D[10283] = {"План Тареты",{"Проберитесь в крепость Дарнхольд и заложите пять зажигательных бомб возле бочек внутри каждого из бараков на выселках. Используйте упаковку зажигательных бомб, полученных от Эрозиона.","","После того как подожжете бараки, разыщите Тралла в подземной темнице."}}
D[10284] = {"Побег из Дарнхольда",{"Когда вы будете готовы идти, сообщите об этом Траллу. Помогите ему бежать из крепости Дарнхольд, освободить Тарету и исполнить свое предназначение.","","После этого возвращайтесь к Эрозиону в Старый Хилсбрад."}}
D[10285] = {"Возвращение к Андорму",{"Возвращайтесь к маленькому Андорму в Пещеры Времени."}}
D[10286] = {"Тайна Арелиона",{"Расспросите магистра Аледиса, которого в последний раз видели отправляющимся из Соколиного дозора в Зангартопь, по требованию магистра Каринды."}}
D[10287] = {"Кем оказалась любовница",{"Возвращайтесь к магистру Каринде в Соколиный дозор."}}
D[10288] = {"Прибытие в Запределье",{"Доставьте донесение Дарона Амишу Громовому Молоту по приказу командира Дарона у Темного портала на полуострове Адского Пламени."}}
D[10289] = {"Путешествие в Траллмар",{"Долетите на ветрокрыле Влагги Легкоперой в Траллмар. Доставьте донесение Ориона генералу Кракорку."}}
D[10290] = {"В поисках фаралита",{"Соберите 4 куска сырого фаралита и вернитесь к Зубену Элгенуби в Штормовую Вершину."}}
D[10291] = {"Донесение Назгрелу",{"Поговорите с Назгрелом по приказу генерала Кракорка из Траллмара."}}
D[10292] = {"Больше мощи!",{"Зубен Элгенуби хочет, чтобы вы захватили 8 пушек Легиона и принесли их в Штормовую Вершину."}}
D[10293] = {"Попасть на главную жилу",{"Зубен Элгенуби, находящийся в Штормовой Вершине, хочет, чтобы вы добыли фаралитовую сердцевину."}}
D[10294] = {"Пустынный обрыв",{"Отправляйтесь на Пустынный обрыв и убейте существ, которые там обитают. Соберите 40 осколков душ Пустынного обрыва и возвращайтесь к Огафу Безумному на Заставу Хребтолома."}}
D[10295] = {"Сила бездны",{"Убейте Барона Бездны Галаксиса и добудьте осколок его души. Принесите осколок души Огафу Безумному на Заставу Хребтолома."}}
D[10296] = {"Черные топи",{"Пройдите сквозь Пещеры времени до Черных топей времен открытия Темного портала и поговорите с Са'атом."}}
D[10297] = {"Открытие Темного портала",{"Защищайте Медива, пока он не откроет Темный портал.","","Когда выполните задание, возвращайтесь к Са'ату в Черные топи."}}
D[10298] = {"Герой драконьего племени",{"Возвращайтесь к маленькому Андорму в пустыню Танарис в Пещерах Времени."}}
D[10299] = {"Отключить манагорн Б'наар",{"Вернитесь в манагорн Б'наар и заберите кристалл доступа у надзирателя Тередиса. Используйте его на панели управления манагорна, чтобы выключить его, затем сообщите об этом анахорету Карже.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10300] = {"Восстановление посоха",{"Заберите 4 осколка безупречного кристалла у призраков в руинах Энкаата и принесите Равандвиру в Зону 52."}}
D[10301] = {"Открыть Компендиум",{"Заберите халцедоновое око у разрушительницы чар Маратель, находящейся в форте Ярости Солнца. Когда достигнете цели, используйте посох верховного мага Варгота, чтобы связаться с верховным магом.","","Если вы утратили посох верховного мага Варгота, поговорите с Равандвиром, находящимся в Зоне 52, чтобы получить замену."}}
D[10302] = {"Неустойчивые мутации",{"Убейте 8 неустойчивых мутаций и вернитесь к ботанику Таэрикс на месте крушения в долине Аммен."}}
D[10303] = {"Эльфы крови",{"Убейте 10 эльфов крови – разведчиков и вернитесь к Толаану на хребет Теней в долине Аммен."}}
D[10304] = {"Воздаятель Алдар",{"Поговорите с воздаятелем Алдаром на месте крушения в долине Аммен."}}
D[10305] = {"Клятвопреступница Белмара",{"Найдите апартаменты клятвопреступницы Белмары в переулке Волшебников и верните книгу на полку. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар."}}
D[10306] = {"Кудесник Люминрат",{"Найдите апартаменты кудесника Люминрата в переулке Волшебников и верните плащ в его гардероб. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар."}}
D[10307] = {"Кольен Повелитель Льда",{"Найдите апартаменты Кольена Повелителя Льда в переулке Волшебников и верните шляпу на вешалку. Затем поговорите со смотрителем Дайвортом в деревне Кирин'Вар."}}
D[10308] = {"Еще одна группа духов Астрала"}
D[10309] = {"Это сквернобот, но у него есть сердце!",{"Заберите сердце сквернобота и отнесите Н. Д. Лагерфелту на Груду в Пустоверти."}}
D[10310] = {"Саботаж в портале",{"Сопроводите Дризья до точки вторжения: Разрушитель и проследите за безопасностью во время попыток саботажа. Затем поговорите с Гаруджем на заставе в заповеднике \"Срединные земли\" в Пустоверти."}}
D[10311] = {"Дризья нужна твоя помощь",{"Поговорите с Дризья, находящимся около Места Вторжения \"Разрушитель\" в Пустоверти."}}
D[10312] = {"Анналы Кирин'Вара",{"Заберите анналы Кирин'Вара из ратуши деревни Кирин'Вар и отнесите ее смотрителю Дайворту."}}
D[10313] = {"Измерение энергии Искажения",{"Экзарх Орелис, находящийся в Зоне 52, просит вас отнести настроенный на энергию искривления шар к манагорну Б'наар и использовать шар у окончания четырех трубопроводов.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10314] = {"Длительные подозрения",{"Соберите 10 омерзительных останков искаженных духов во дворе часовни деревни Кирин'Вар и отнесите их смотрителю Дайворту."}}
D[10315] = {"Нейтрализовать чародеев Пустоты",{"Убейте 15 пустомантов клана Ярости Солнца и возвращайтесь к ловчему Пустоты Оазулу в Лагерь Тулумана в Пустоверти."}}
D[10316] = {"В поисках доказательств",{"Поищите во дворе часовни в деревне Кирин'Вар свидетельства того, кто именно манипулирует духами убитых."}}
D[10317] = {"Покончить со штейгером",{"Покончите со штейгером Закатом Солнца, находящимся в руднике Треллеума под манагорном Ара в Пустоверти."}}
D[10318] = {"Покончить с Подчинителем",{"Убейте Подчинителя Гриндгарра. Затем вернитесь к торговцу Ветром Тулуману в Лагерь Тулумана в Пустоверти."}}
D[10319] = {"Захватить талисман",{"Заберите филактерию Набериуса из района часовни деревни Кирин'Вар и принесите его смотрителю Дайворту."}}
D[10320] = {"Уничтожить Набериуса!",{"Смотритель Дайворт в деревне Кирин'Вар просит вас сразиться с Набериусом, находящимся во дворе часовни, и уничтожить его."}}
D[10321] = {"Отключить манагорн Коруу",{"Отправляйтесь в манагорн Коруу к востоку от Зоны 52 и заберите кристалл доступа Коруу у надзирательницы Сейланны. Используйте его на панели управления манагорна Коруу, чтобы отключить манагорн, затем вернитесь к анахорету Карже.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10322] = {"Отключить манагорн Даро",{"Анахорет Каржа просит вас отправиться в манагорн Даро и забрать кристалл доступа у надзирателя Атанеля. Используйте этот кристалл на панели управления манагорном Даро, чтобы отключить его.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10323] = {"Отключить манагорн Ара",{"Отправляйтесь в манагорн Ара и заберите кристалл доступа у надзирателя Азарада. Используйте его на панели доступа манагорна Ара, чтобы отключить его.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10324] = {"Великая охота на лунных оленей",{"Принесите 6 шкур самцов лунного оленя Актеону с Лазурной заставы."}}
D[10325] = {"Знаки Кил'джедена",{"Принесите 10 знаков Кил'джедена Адуину Стражу Света в Шаттрат.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10326] = {"Больше знаков Кил'джедена",{"Вы принесли еще знаков различия наших врагов, |3-6(Охотник)? Пылающий Легион все еще угрожает нам, и мы преследуем его повсеместно."}}
D[10327] = {"Знак Кил'джедена"}
D[10328] = {"Инструкции Ярости Солнца",{"Отправляйтесь в манагорн Даро и заберите военные инструкции Ярости Солнца и чародейские инструкции Ярости Солнца. По завершении задачи возвращайтесь к экзарху Орелису.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10329] = {"Отключить манагорн Б'наар",{"Вернитесь в манагорн Б'наар и заберите кристалл доступа у надзирателя Тередиса. Используйте его на панели управления манагорна Б'наар, чтобы выключить его, затем сообщите об этом патрону шпионов Талодиену.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10330] = {"Отключить манагорн Коруу",{"Заберите кристалл доступа Коруу у надзирателя Сейланны. Используйте его на панели управления Коруу, чтобы отключить манагорн, затем вернитесь к Каледису Сияющему Рассвету.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10331] = {"Необходимые инструменты",{"Заберите кузнечный молот у кирин'варских учеников и отнесите обратно ученику Андретану в деревню Кирин'Вар."}}
D[10332] = {"Мастер-кузнец Ронсус",{"Ученик Андретан из деревни Кирин'Вар просит вас убить призрак Ронсуса, мастера-кузнеца поселения."}}
D[10333] = {"Помощь Мамаше Колесун",{"Поговорите с Мамашей Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти."}}
D[10334] = {"Колокольчик для коровы",{"Найдите Бесси в полях близ Часовенного холма деревни Кирин'Вар."}}
D[10335] = {"Исследование руин",{"Разместите три геодезических знака, затем возвращайтесь к Зефириону в Штормовую Вершину в Пустоверти."}}
D[10336] = {"Приспешники Кулутаса",{"Убейте 10 псов Кулутаса и 5 злобоглазов Кулутаса. Затем вернитесь к ловчему Пустоты Наутису, находящемуся в Штормовой Вершине в Пустоверти."}}
D[10337] = {"Когда коровы возвращаются домой",{"Благополучно сопроводите Бесси к ее владельцу, Таделлу."}}
D[10338] = {"Отключить манагорн Даро",{"Вернитесь в манагорн Даро и заберите кристалл доступа у надзирателя Атанеля. Используйте его на панели управления манагорна Даро, чтобы отключить его, затем сообщите об этом патрону шпионов Талодиену.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10339] = {"Братство Эфириум",{"Командир Амир просит вас уничтожить 5 убийц из Эфириума, 5 штормовиков из Эфириума, 2 ученых Эфириума и капитана Зовакса из Эфириума, затем включить передатчик Эфириума Зета."}}
D[10340] = {"Парящая застава",{"По приказу командира передовой Кингстона поговорите с командиром звена Даби'ри, доберитесь на грифоне до Парящей заставы и поговорите с Рунтогом Громовым Молотом."}}
D[10341] = {"Лежачего не бьют – лежачего пинают",{"Убейте 8 кудесников, 6 лучников и 4 центурионов клана Ярости Солнца. После завершения задачи вернитесь к магистру Ларинне, находящейся в Зоне 52.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10342] = {"Добыча кожи глиношкурых",{"Соберите 5 кусков кожи глиношкурых и отдайте Бутсу в Зоне 52 в Пустоверти."}}
D[10343] = {"Бесконечное вторжение",{"Обыщите кишащий мана-тварями район деревни Кирин'Вар в поисках фрагмента мана-бомбы и принесите его лейтенант-колдуну Моррану."}}
D[10344] = {"Командир звена Грифонгар",{"Поговорите с командиром звена Грифонгаром на Парящей заставе."}}
D[10345] = {"Усеял мертвыми костями...",{"Примените поджигатель Протектората к 12 высохшим трупам. Когда задача будет завершена, верните поджигатель Протектората посланнику Араксису, находящемуся у входа в шахту Зеон."}}
D[10346] = {"Возвращение на Косогор Бездны",{"Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по просьбе грифоньера Ветрорева с Парящей заставы на полуострове Адского Пламени."}}
D[10347] = {"Возвращение на Косогор Бездны",{"Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по просьбе командира звена Бракка из Гибели Сквернобота на полуострове Адского Пламени."}}
D[10348] = {"Новые возможности",{"Соберите 15 \"кремовых колокольчиков\" и вернитесь к Мердаду на Заставу срединных земель."}}
D[10349] = {"Землепряд",{"Отнесите осколок алого хрусталя заклинательнице земли Галандрии Ночной Бриз на Кенарийскую заставу на полуострове Адского Пламени."}}
D[10350] = {"Бехомат",{"Поговорите с Бехоматом в Торговом ряду Экзодара."}}
D[10351] = {"Целительная сила природы",{"Посадите Семя Возрождения в Круге землепряда, чтобы исцелить землю вокруг кристалла. После этого возвращайтесь к землепряду Галандрии Ночной Бриз на Кенарийскую заставу и расскажите о том, что получилось."}}
D[10352] = {"Пожертвование: шерсть",{"Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Дарнасса. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.","","Но если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас."}}
D[10353] = {"Арконус Ненасытный",{"Посланник Иасикс, находящийся у входа в шахту Зеон, просит вас убить Арконуса Ненасытного и вернуться к командиру Амиру на заставу стражи Протектората в Пустоверти."}}
D[10354] = {"Пожертвование: шелк",{"Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.","","Если ты можешь пожертвовать шестьдесят отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!"}}
D[10355] = {"Иссохшее тело",{"Соберите 5 образцов опаленной гидры и 5 образцов ткани высохшего болотника и принесите их Руаму в Телредор."}}
D[10356] = {"Пожертвование: магическая ткань",{"Мы занимаемся сбором магической ткани. Если ты пожертвуешь нам на благие цели 60 отрезов, то заслужишь признательность всего народа.","","Если у тебя есть 60 отрезов, можешь сдать их нам прямо сейчас."}}
D[10357] = {"Пожертвование: руническая ткань",{"Мы занимаемся сбором рунической ткани. Если ты пожертвуешь на благие цели 60 отрезов, то заслужишь признательность всего нашего народа.","","Если у тебя есть 60 отрезов, можешь пожертвовать их прямо сейчас."}}
D[10358] = {"Больше рунической ткани",{"И снова здравствуй, Эльфвоинша. Если ты готова выделить нам еще двадцать отрезов рунической ткани, то, будь уверена я постараюсь, чтобы все узнали о твоей щедрости. Если у тебя есть 20 отрезов рунической ткани, я охотно ее приму."}}
D[10359] = {"Пожертвование: шерсть",{"Принеси 60 отрезов шерстяной ткани. Жители Луносвета будут тебе очень благодарны!","","Если необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас."}}
D[10360] = {"Пожертвование: шелк",{"Принеси 60 отрезов шелка. Жители Луносвета будут тебе очень благодарны!","","Если необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас."}}
D[10361] = {"Пожертвование: магическая ткань",{"Принеси 60 отрезов магической ткани. Жители Луносвета будут тебе очень благодарны!","","Если необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас."}}
D[10362] = {"Пожертвование: руническая ткань",{"Принеси 60 отрезов рунической ткани. Жители Луносвета будут тебе очень благодарны!","","Если необходимое количество ткани у тебя при себе, я с удовольствием приму дар сейчас."}}
D[10363] = {"Больше рунической ткани",{"Рунической ткани много не бывает. Принеси еще 20 отрезов – и получишь бесконечную признательность жителей Луносвета!","","Просто отдай ее мне, когда найдешь нужное количество."}}
D[10364] = {"Кедмос",{"Поговорите с Кедмосом в Чертоге Света Экзодара."}}
D[10365] = {"Отключить манагорн Ара",{"Отправляйтесь в манагорн Ара, заберите кристалл доступа Ара у надзирателя Азарадда. Используйте его на панели управления манагорном Ара, чтобы отключить его.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10366] = {"Джоль",{"Поговорите с Джоль в Святилище поборников в Экзодаре."}}
D[10367] = {"Предатель среди нас",{"Добудьте ключ Ша'наара, спрятанный в лачуге в руинах Ша'наара неподалеку от Наладу."}}
D[10368] = {"Старейшины Отребья",{"Освободите Морода Ветродува, Акору Призывателя Огня и Айлаана Пробуждающего Водув руинах Ша'наара. После выполнения задания возвращайтесь к Наладу."}}
D[10369] = {"Наследие Арзета",{"Используйте посох старейшин племени Отребья против Арзета Безжалостного. После того как Арзет потеряет силу, убейте его. После выполнения задания возвращайтесь к Наладу в руины Ша'наара."}}
D[10370] = {"Приказ Назгрела <TXT>"}
D[10371] = {"Йорус Ячменовар",{"Поговорите с Йорусом Ячменоваром."}}
D[10372] = {"Деликатная просьба",{"Поговорите с Эраланной в Транквиллионе."}}
D[10373] = {"Призыв к оружию: Чумные земли!",{"Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор."}}
D[10374] = {"Призыв к оружию: Чумные земли!",{"Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лугов и Подгорода."}}
D[10375] = {"Обсидиановое боевое ожерелье"}
D[10377] = {"Ничего не бойся"}
D[10379] = {"Прикосновение слабости"}
D[10380] = {"Темный пакт",{"Кайлаан, находящийся в Лагере Тулумана в Пустоверти хочет, чтобы вы убили 6 ган'аргов-астральных ремонтников, 3 Дочерей Судьбы и 3 мо'аргов-мастеров искажения.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10381] = {"Нет больше Алдора",{"Вернитесь с сообщением к Экзарху Орелису в Зону 52.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10382] = {"Отправка на фронт",{"Долетите до Пика Чести на грифоне и поговорите с фельдмаршалом Броком."}}
D[10383] = {"Хлебные крошки!",{"Поговорите с Джонатаном Лекрафтом насчет кроликов."}}
D[10384] = {"Данные Братства Эфириум",{"Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать данные из информационной ячейки Эфириума."}}
D[10385] = {"Риск поражения мозга – высокий",{"Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать 15 передач данных из ретранслятора Эфириума."}}
D[10386] = {"Гроза скверноботов",{"Поговорите с властителем Ханом Изуверским Кулаком."}}
D[10387] = {"Гроза скверноботов",{"Поговорите с властителем Ханом Изуверским Кулаком."}}
D[10388] = {"Назад в Траллмар",{"Возвращайтесь в Траллмар и поговорите с Назгрелом."}}
D[10389] = {"Тьма и агония",{"Убейте 10 исчадий ужаса у прудов Аггонара по приказу магистра Кровавого Ястреба."}}
D[10390] = {"Лагерь Легиона: Магеддон",{"Атакуйте лагерь Легиона: Магеддон, убейте 10 ган'аргов-прислужников и вернитесь с головой Остропила к Назгрелу в Траллмар."}}
D[10391] = {"Пушки Ярости",{"Уничтожьте 3 пушки Скверны первой модели в лагере Легиона: Ярость и возвращайтесь к Назгрелу в Траллмар."}}
D[10392] = {"Дверь в Бездну",{"Убейте Арикс'Амала и заберите ключ врат Пылающего Легиона. Используйте ключ на Руне Злобы и возвращайтесь к Назгрелу в Траллмар."}}
D[10393] = {"Коварные планы",{"Доставьте послание Пылающего Легиона магистру Кровавому Ястребу в Траллмар."}}
D[10394] = {"Уничтожение – лагерь Легиона: Магеддон",{"Убейте 10 ган'аргов-прислужников и Остропила. После выполнения задания возвращайтесь к передовому командиру Броку на заставу Чести."}}
D[10395] = {"Темное послание",{"Доставьте послание Пылающего Легиона провидцу бед Криву в главную крепость Оплота Чести."}}
D[10396] = {"Враг моего врага...",{"Уничтожьте 3 пушки Скверны первой модели в лагере Легиона: Ярость и возвращайтесь к фельдмаршалу Броку на заставу Чести."}}
D[10397] = {"Точка вторжения: Аннигилятор",{"Уничтожьте Арикс'Амала. Заберите ключ врат пылающего Легиона. Примените ключ на Руне Злобы."}}
D[10398] = {"Возвращение в Оплот Чести",{"PH: Вернитесь в Оплот Чести"}}
D[10399] = {"Сердце тьмы",{"Убейте 10 исчадий ужаса у прудов Аггонара и возвращайтесь к провидцу бед Криву в главную крепость Оплота Чести."}}
D[10400] = {"Владыка",{"Убейте Араззиуса Безжалостного у прудов Аггонара и возвращайтесь к командиру армии Данату Троллебою в крепость Оплота Чести."}}
D[10401] = {"Задание: со щитом или на щите",{"Уничтожьте Араззиуса Безжалостного по просьбе Назгрела из Траллмара на Полуострове Адского Пламени."}}
D[10403] = {"Наладу",{"Отыщите Наладу в руинах Ша'наара."}}
D[10404] = {"Против Легиона",{"Экзарх Орелис, находящийся в Зоне 52, просит вас отправиться к кузнечной базе \"Забвение\" и кузнечной базе \"Геенна\" и убить 12 ган'аргов-работников кузни, 6 мо'аргов-начальников кузни и 6 вестников зла.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10405] = {"С-А-Б-О-Т-А-Ж",{"Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас добыть 1 комплект готовых обмоток Эфириума."}}
D[10406] = {"Передать послание",{"Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас сопроводить подрывника из Протектората к трубопроводу манагорна Ультрис и охранять его, пока он готовит диверсию на трубопроводе."}}
D[10407] = {"Тень Сокретара",{"Анахорет Каржа, находящийся в Зоне 52, просит вас забрать первую половину камня Сокретара у начальника кузни Моруга с базы Легиона: Забвение и вторую половину камня Сокретара у Силрота с базы Легиона: Геенна.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10408] = {"Соправитель Салхадаар",{"Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас использовать дезинтегратор Протектората, чтобы отключить защитное поле Салхадаара, а затем уничтожить Соправителя Салхадаара."}}
D[10409] = {"Удар по Легиону",{"Верховная жрица Ишана просит вас отправиться к телепорту Легиона в северо-западной части Пустоверти и использовать его, чтобы переместиться к Трону Сокретара.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10410] = {"Помощь Ишаны",{"Отнесите камень телепортации Сокретара верховной жрице Ишане в святилище Вечного Света на возвышенности Алдоров в Шаттрате.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10411] = {"Слава электрошоку!",{"Ученый Навууд, находящийся на заставе стражей Протектората в Пустоверти просит вас уничтожить 30 каплей отброса Бездны и 30 сочащихся каплей слякоча."}}
D[10412] = {"Перстни Огнекрылых",{"Принесите магистру Файленн 10 перстней Огнекрылых.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10413] = {"Ужасы загрязнения",{"Отнесите фиал со слизью ужаса Бездны к ученому Навууду на заставу стражей Протектората в Пустоверти."}}
D[10414] = {"Перстень Огнекрылых",{"Даже самая маленькая помощь нашему делу не останется незамеченной, Кофемашина. Армия врага велика, но победа будет за нами!"}}
D[10415] = {"Больше перстней Огнекрылых",{"Что вы сделали для нас в последее время, Вродехант? Война против Кель'таса не продолжится сама по себе!"}}
D[10416] = {"Преобразование силы",{"Принесите чародейский фолиант Ворен'талю Предсказателю в Шаттрат.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10417] = {"Провести диагностику",{"Заберите результаты диагностики и доставьте их Мердаду на Заставу срединных земель."}}
D[10418] = {"Покончить с вредителями",{"Мердад, находящийся на Заставе срединных земель, просит вас убить 8 шипастых кроколисков."}}
D[10419] = {"Чародейские фолианты"}
D[10420] = {"Очищающий Свет",{"Принесите латные перчатки Скверны Ишане в Шаттрат.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10421] = {"Латные перчатки Скверны",{"Не попадались ли вам в последнее время латные перчатки Скверны? Нельзя оставлять эти оскверненные вещи в нашем мире, Медвефект. Нужно очистить их."}}
D[10422] = {"Капитан Тиралиус",{"Укротитель плоти Виридиус, находящийся на заставе стражей Протектората в Пустоверти, просит вас найти и освободить капитана Тиралиуса."}}
D[10423] = {"В Штормовую Вершину",{"Поговорите с Габаром в Штормовой Вершине."}}
D[10424] = {"Диагноз: критический",{"Используйте диагностическое устройство, стоя поблизости от генератора экосферы заповедника\"Сатерон\", и отнесите результаты диагностики Габару в Штормовую Вершину."}}
D[10425] = {"Побег с полигона",{"Сопроводите пленного передового бойца Протектората обратно на заставу стражей Протектората в Пустоверти."}}
D[10426] = {"Растительность заповедников",{"Используйте модулятор энергетического поля на фаралонских плеточниках. Пронаблюдайте результаты и после того, как проведете 10 тестов, сообщите результаты Аурин Лунное Сияние, находящейся в Штормовой Вершине."}}
D[10427] = {"Животные заповедников",{"Пометьте 12 талбуков для Аурин Лунное Сияние из Штормовой Вершины. Вы можете метить как самцов, так и самок талбуков, используя метчик для талбуков."}}
D[10428] = {"Пропавший рыбак",{"Найдите Коулена на юго-восточной пристани острова Серебристой Дымки, неподалеку от побережья острова Лазурной Дымки."}}
D[10429] = {"Когда природа заходит слишком далеко",{"Аурин Лунное Сияние из Штормовой Вершины просит вас принести ей сердце гигантской гидры."}}
D[10430] = {"Испытание прототипа",{"Отнесите ремонтный аппарат Ташару в заповедник \"Дальнее поле\"."}}
D[10431] = {"Помощь извне",{"Идите в Лагерь Тулумана, на север от Зоны 52, и поговорите с Кайлааном.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10432] = {"Надежное свидетельство",{"Заберите у демонов, находящихся в манагорне Ара 8 приказов Кель'таса и отнесите их патрону шпионов Талодиену в Зону 52.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10433] = {"Поддерживая видимость",{"Принесите 10 шкур рыси-клыкодера Шоли Пору на Заставу срединных земель."}}
D[10434] = {"Динамический дуэт",{"Поговорите с Оди Иголкой в Штормовой Вершине."}}
D[10435] = {"Сбор деталей",{"Оди Иголка, находящаяся в Штормовой Вершине, просит вас принести ей 10 сегментов генератора защитного купола."}}
D[10436] = {"Все чисто!",{"Ташар, находящийся в заповеднике \"Дальнее поле\", просит вас убить 12 саблезубых ящеров."}}
D[10437] = {"Рецепт уничтожения",{"Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы собрали 8 фрагментов Пространствуса."}}
D[10438] = {"На крыльях Пустоты",{"Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы использовали фазовый дезинтегратор, когда окажетесь вблизи от стержня Бездны наверху Ультриса. Скиньте как можно больше зарядов фазового дезинтегратора, чтобы обеспечить полное уничтожение. Заряды фазового дезинтегратора автоматически попадут в стержень Бездны, если вы будете достаточно близко, чтобы использовать их.","","Если вы преуспеете, возвращайтесь к профессору Дабири!"}}
D[10439] = {"Пространствус Всепоглощающий",{"Профессор Дабири, находящийся на заставе Протектората в Пустоверти, хочет, чтобы вы поговорили с капитаном Саидом, а потом вместе с его армией проследовали к манагорну Ультрис и убили Пространствуса Всепоглощающего!"}}
D[10440] = {"Готово!",{"Вернитесь в Штормовую Вершину и поговорите с Габаром."}}
D[10441] = {"Торговля по мелочам",{"Поговорите с Аурин Лунное Сияние у подножия Штормовой Вершины."}}
D[10442] = {"Помощь Кенарийской заставе",{"Отправьтесь на помощь Тие Рыжей Гриве на Кенарийскую заставу на полуострове Адского Пламени по просьбе сокольничего Дренны Речной Ветер."}}
D[10443] = {"Помощь Кенарийской заставе",{"Отправьтесь на Кенарийскую заставу на полуострове Адского Пламени и предложите помощь Тие Рыжей Гриве по просьбе Амаана Мудрейшего."}}
D[10444] = {"Послание для Заставы Аллерии",{"Доложите обстановку лейтенанту Меридиану на заставе Аллерии в лесу Тероккар по поручению Дженайи Шепот Звезд."}}
D[10445] = {"Сосуды Вечности",{"Соридорми из Пещер времени желает, чтобы вы принесли ей неполный фиал леди Вайш из резервуара Кривого Клыка и неполный фиал Кель'таса из Крепости Бурь."}}
D[10446] = {"Финальный код",{"Используйте финальный код, чтобы активировать мана-бомбу, как велел вам лейтенант Меридиан. После этого поговорите с Дженайей Шепот Звезд в бастионе Аллерии в лесу Тероккар."}}
D[10447] = {"Финальный код",{"Используйте финальный код, чтобы активировать мана-бомбу, как велела вам сержант Чауни. После этого поговорите с Туки в форте Камнеломов в лесу Тероккар."}}
D[10448] = {"Донесение в лагерь Камнеломов",{"Поговорите с сержантом Чауни в лагере Камнеломов в лесу Тероккар по просьбе Туки."}}
D[10449] = {"Аптекарь Зелана",{"Доставьте образцы крови орков из клана Костеглодов аптекарю Зелане в Погибель Сквернобота по просьбе Вартока Топоруба из Траллмара."}}
D[10450] = {"Кровь клана Костеглодов",{"Принесите 12 фиалов крови орков из клана Костеглодов Вартоку Топорубу в Траллмар."}}
D[10451] = {"Спастись из водохранилища Змеиных Колец",{"Выведите целительницу земли Вильду из водохранилища Змеиных Колец и затем разыщите целителя земли Торлока у Алтаря Проклятия, на западной окраине Руки Гул'дана."}}
D[10454] = {"FLAG – OFF THE RAILS"}
D[10455] = {"Угроза хищников",{"Рина Лунный Родник хочет, чтобы вы как можно скорее убили 12 рысей рощи и вернулись к ней в Сильванаар в Острогорье."}}
D[10456] = {"Волчья напасть",{"Рина Лунный Родник просит вас принести ей 4 хвоста лютых волков клана Громоборцев. По выполнении задания вернитесь к ней в Сильванаар в Острогорье."}}
D[10457] = {"Защитить свой дом",{"Взмахните ветвью Рины над 5 саженцами рощи, чтобы призвать на защиту Живой рощи силы природы. Затем вернитесь к Рине Лунный Родник в Сильванаар в Острогорье."}}
D[10458] = {"Разъяренные бесы пламени и земли",{"Поймайте с помощью тотема духов 8 бесов земли и 8 бесов пламени для целителя земли Торлока из Алтаря Проклятия."}}
D[10459] = {"Почтительное отношение Кенарийской экспедиции",{"Исиэль Песнь Ветра из Кенарийского приюта хочет, чтобы вы добились почтительного отношения Кенарийской экспедиции."}}
D[10460] = {"Посвящение в защитники",{"Ты уверен, что хочешь избрать этот путь, Тириш? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.","","В этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи."}}
D[10461] = {"Посвящение в целители"}
D[10462] = {"Посвящение в герои",{"Ты уверен, что хочешь избрать этот путь, Тыж? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.","","В этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи."}}
D[10463] = {"Посвящение в мудрецы",{"Ты уверен, что хочешь избрать этот путь, Монд? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.","","В этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи."}}
D[10464] = {"Обет мудреца",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить уважительное отношение драконов Песчаной Чешуи."}}
D[10465] = {"Обет целителя",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить уважительное отношение драконов Песчаной Чешуи."}}
D[10466] = {"Обет героя",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить уважительное отношение драконов Песчаной Чешуи."}}
D[10467] = {"Обет защитника",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить уважительное отношение драконов Песчаной Чешуи."}}
D[10468] = {"Клятва мудреца",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить почтительное отношение драконов Песчаной Чешуи."}}
D[10469] = {"Клятва целителя",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить почтительное отношение драконов Песчаной Чешуи."}}
D[10470] = {"Клятва защитника",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить почтительное отношение драконов Песчаной Чешуи."}}
D[10471] = {"Клятва защитника",{"Принесите кольцо Вечности Соридорми в пещеры Времени после того, как сумеете заслужить почтительное отношение драконов Песчаной Чешуи."}}
D[10472] = {"Договор мудреца",{"Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи."}}
D[10473] = {"Договор целителя",{"Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи."}}
D[10474] = {"Договор героя",{"Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи."}}
D[10475] = {"Договор защитника",{"Принесите кольцо Вечности Соридорми в пещеры Времени, когда сумеете заслужить полное доверие драконов Песчаной Чешуи."}}
D[10476] = {"Лютые враги",{"Принесите стражу-смотрителю Мой'прну Джиллу 10 обсидиановых боевых ожерелий, снятых с огров из Награнда."}}
D[10477] = {"Боевые ожерелья"}
D[10478] = {"Боевые ожерелья!",{"Ты добыл еще боевых ожерелий, Солэтьюд?"}}
D[10479] = {"Покажи свою силу",{"Принесите 10 обсидиановых боевых ожерелий, снятых с огров, населяющих Награнд, стражу-смотрителю Быккроку в Гарадар."}}
D[10480] = {"Разъяренные бесы воды",{"Используйте тотем духов, чтобы поймать 5 бесов воды для целителя земли Торлока у Алтаря Проклятия в Долине Призрачной Луны."}}
D[10481] = {"Разъяренные бесы воздуха",{"Поймайте с помощью тотема духов 10 бесов воздуха для целителя земли Торлока из Алтаря Проклятия."}}
D[10482] = {"Падальщики орков Скверны",{"Убейте 20 орков из клана Костеглодов и возвращайтесь к Амади в Оплот Чести."}}
D[10483] = {"Дурные предзнаменования",{"Принесите 1 проклятый талисман капралу Железному Хребту в лагерь экспедиции по просьбе лейтенанта Амади в Оплоте Чести."}}
D[10484] = {"Проклятые талисманы",{"Принесите 12 проклятых талисманов капралу Железному Хребту в Лагерь экспедиции."}}
D[10485] = {"Воевода клана Кровавой Глазницы",{"Принесите разбитые доспехи воеводы Морха капралу Железному Хребту в лагерь экспедиции."}}
D[10486] = {"Угроза хищников",{"Гор'дрек просит вас убить 12 острокрылых кровопускателей. Вернитесь к нему в оплот Громоборцев в Острогорье после выполнения задания."}}
D[10487] = {"Пыльца волшебных драконов",{"Гор'дрек хочет, чтобы вы принесли пыльцу с крыльев 4 волшебных драконов. После этого вернитесь к нему в оплот Громоборцев в Острогорье."}}
D[10488] = {"Защитить свой дом",{"Помажьте мазью Гор'дрека 5 лютых волков клана Громоборцев, чтобы сделать их сильнее и укрепить оборону Зазубренной гряды. Затем вернитесь к Горд'дреку в оплот Громоборцев в Острогорье."}}
D[10489] = {"Свалить ходячее древо!",{"Добудьте ствол Лесодрева Глубокорня и доставьте его Тор'чанку Двукогтю на постоялый двор оплота Громоборцев в Острогорье."}}
D[10490] = {"Зов воды",{"Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним."}}
D[10491] = {"Зов воздуха",{"Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки."}}
D[10492] = {"Серьезное предложение",{"Добудьте 15 порций крови животных Зимних Ключей и 20 золотых и отдайте их вместе с наручниками Стихий Делиане в Стальгорне."}}
D[10493] = {"Серьезное предложение",{"Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами из светлостали Моквару в Оргриммар."}}
D[10494] = {"Справедливое вознаграждение",{"Принесите шнурованный ремень Стихий и пару рукавиц Стихий в Стальгорн Делиане."}}
D[10495] = {"Справедливое вознаграждение",{"Принесите Моквару в Оргриммар пояс из светлостали и рукавицы из светлостали."}}
D[10496] = {"Прощальные слова Антиона",{"Вернитесь в Стальгорн к Делиане с сапогами Стихий, килтом Стихий и наплечьем Стихий."}}
D[10497] = {"Прощальные слова Антиона",{"Отдайте Моквару в Оргриммаре сапоги из светостали, ножные латы из светостали и наплеч из светостали."}}
D[10498] = {"Сладкое – на закуску",{"Отдайте Делиане капюшон Стихий и жилет Стихий."}}
D[10499] = {"Сладкое – на закуску",{"Отдайте Моквару шлем из светостали и кирасу из светостали."}}
D[10500] = {"Орде нужна твоя помощь!",{"Поговорите с вождем Горчуком на аллее Духов Оргриммара."}}
D[10501] = {"Альянсу нужна твоя помощь!",{"Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна."}}
D[10502] = {"Клан Кровавого Молота",{"Командир Тень Небес поручает вам уничтожить 30 любых огров из клана Кровавого Молота на заставе Кровавого Молота. По выполнении этого грязного дела вернитесь к нему в Сильванаар в Острогорье."}}
D[10503] = {"Угроза Камнерогов",{"Тор'чанк Двукоготь поручил вам уничтожить 30 любых огров из клана Камнерогов и 10 ящеров в форте Камнерогов и на землях Камнерогов. По выполнении поручения вернитесь в оплот Громоборцев в Острогорье."}}
D[10504] = {"Огры из клана Камнерогов",{"Командир Тень Небес просит вас убить 30 любых огров из клана Камнерогов в форте Камнерогов и на землях Камнерогов. По выполнении вернитесь к нему в Сильванаар в Острогорье."}}
D[10505] = {"Клан Кровавого Молота",{"Тор'чанк Двукоготь просит вас убить 30 любых огров из клана Кровавого Молота на заставе Кровавого Молота. По выполнении вернитесь к нему в оплот Громоборцев в Острогорье."}}
D[10506] = {"Тяжелая ситуация",{"Рина Лунный Родник хочет, чтобы вы взяли ее уменьшающий порошок и посыпали им 5 лютых волков клана Кровавого Молота, которых можно найти на заставе Кровавого Молота и в лощине Кровавого Молота. После этого вернитесь к ней в Сильванаар в Острогорье."}}
D[10507] = {"Поворотная точка",{"Используйте камень телепортации Сокретара в точке вторжения: Властитель к северу от базы Легиона: Забвение, чтобы перенести свой отряд в лагерь Сокретара. Оказавшись там, используйте \"Присутствие Ворен'таля\", чтобы победить Сокретара.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10508] = {"Дар для Ворен'таля",{"Патрон шпионов Талодиен, находящийся в Зоне 52, просит вас забрать первую половину камня Сокретара у начальника кузни Моруга с базы Легиона: Забвение и вторую половину камня Сокретара у Силрота с базы Легиона: Геенна.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10509] = {"И все ради славы",{"Отнесите камень телепортации Сокретара Ворен'талю Предсказателю на ярус Провидцев в Шаттрате.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10510] = {"В дренетистовые копи",{"Бронвин Твердомолот просит вас принести 5 кристаллов из дренетистовых копей и вернуться к ней в Сильванаар в Острогорье."}}
D[10511] = {"Странное пиво",{"Боргрим Твердомолот просит вас добыть ему 11 бочонков забористого пойла клана Кровавого Молота. По выполнении вернитесь к нему в Сильванаар в Острогорье."}}
D[10512] = {"Пусть Камнероги упьются!",{"Возьмите бочонок забористого пойла клана Кровавого Молота и попытайтесь напоить допьяна 5 огров из клана Камнерогов. Если получится, вернитесь к Боргриму в Сильванаар в Острогорье."}}
D[10513] = {"Оронок Горемычный",{"Найдите Оронока Горемычного на Разрушенной Отмели, на северном берегу водохранилища Змеиных Колец."}}
D[10514] = {"Кем только я не был...",{"Принесите 10 клубней долины Призрачной Луны с Разоренных равнин Ороноку Горемычному на его ферму.","","Ему также необходимо вернуть его свисток."}}
D[10515] = {"Усвоенный урок",{"Уничтожьте 10 яиц прожорливого камнедера на Разоренных равнинах для Оронока Горемычного."}}
D[10516] = {"Вещи Поборницы",{"Добудьте клинок и щит воздаятельницы Вуулины. Затем вернитесь к воздаятельнице Вуулине в форт Камнерогов в Острогорье."}}
D[10517] = {"Горр'Дим, твой час пробил...",{"Воздаятельница Вуулина просит вас убить Горр'Дима, вождя огров из форта Камнерогов. По выполнении вернитесь к ней в форт Камнерогов в Острогорье."}}
D[10518] = {"Водружение знамени",{"Водрузите знамя Камнерогов на башне Северного молота, чтобы раздразнить Гурна Обжору. Принесите знамя и шлем Гурна Обжоры командиру Тень Небес в Сильванаар в Острогорье."}}
D[10519] = {"Код Проклятия – правда и миф",{"Поговорите с Ороноком Горемычным на его ферме и выслушайте историю, которую он вам поведает."}}
D[10520] = {"Помощь верховному друиду Оленьему Шлему",{"Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе."}}
D[10521] = {"Гром'тор, сын Оронока",{"Найдите Гром'тора сына Оронока в лагере Змеиных Колец в долине Призрачной Луны."}}
D[10522] = {"Код Проклятия: Вклад Гром'тора",{"Найдите первый фрагмент Кода Проклятия для Гром'тора, сына Оронока из лагеря Змеиных Колец в долине Призрачной Луны."}}
D[10523] = {"Код Проклятия: Первый Фрагмент",{"Принесите Сейф Гром'тора Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны."}}
D[10524] = {"Сокровища клана Громоборцев",{"Добудьте барабан клана Громоборцев, стрелу клана Громоборцев и табличку клана Громоборцев. Принесите их вместе с артефактом клана Громоборцев Рокге Живоглотке в оплот Громоборцев в Острогорье."}}
D[10525] = {"Путеводный огонек",{"При помощи фрагмента пылающей души превратите свой дух в путеводное видение. Поговорите с Рокгой Живоглоткой в оплоте Громоборцев после того. Как видение приведет вас туда, где находится последнее сокровище клана Громоборцев."}}
D[10526] = {"Громовая пика",{"Рокга Живоглотка дала вам поручение добыть громовую пику. Принесите пику ей в оплот Громоборцев в Острогорье."}}
D[10527] = {"Ар'тор, сын Оронока",{"Найдите Ар'тора, сына Оронока, на аванпосте иллидари в долине Призрачной Луны."}}
D[10528] = {"Тюрьма из демонических кристаллов",{"На аванпосте иллидари разыщите и убейте госпожу боли Габриссу и вернитесь к телу Ар'тора, сына Оронока, с хрустальным ключом."}}
D[10529] = {"Путь охотника",{"Поговорите с лейтенантом Вестницей Рассвета в обители Странников."}}
D[10530] = {"Путь охотника",{"Поговорите с лейтенантом Вестницей Рассвета в обители Странников."}}
D[10531] = {"Битва за Низину Арати",{"Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт."}}
D[10532] = {"Перекрыть линии поставок Аратора",{"Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот."}}
D[10533] = {"Новые ящики с ресурсами"}
D[10534] = {"Возвращение домой",{"Кедмос из Экзодара просит вас прийти поговорить с ним."}}
D[10535] = {"Ресурсы Низины Арати",{"Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт."}}
D[10536] = {"Новые ящики с ресурсами"}
D[10537] = {"Лон'горон, лук Горемычного",{"Отберите у демонов Лон'горон, лук Горемычного, и верните его духу Ар'тора на аванпосте иллидари."}}
D[10538] = {"Кипящая кровь",{"Поместите кровь орков из клана Кровавой Глазницы в проклятый котел, чтобы получить кипящую кровь. Принесите 12 образцов кипящей крови аптекарю Альбреку на заставу Хребтолома."}}
D[10539] = {"Возвращение домой",{"Кедмос из Экзодара просит вас прийти и поговорить с ним."}}
D[10540] = {"Код Проклятия: Вклад Ар'тора",{"Заберите вторую часть Кода Проклятия у Венератуса Многого для духа Ар'тора с аванпоста иллидари. Существа, убитые или раненые охотником на духов, не приносят вам ни добычи, ни опыта."}}
D[10541] = {"Код Проклятия – Второй фрагмент",{"Отнесите сейф Ар'тора Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны.","."}}
D[10542] = {"У меня сперли кальян и выпивку!",{"Добудьте кальян Т'чали и 10 кружек забористого пойла клана Кровавого Молота. Принесите все к Т'чали Знахарю в лощину Кровавого Молота в Острогорье."}}
D[10543] = {"Гримнок и Коргаах, я за вами!",{"Т'чали Знахарь просит, чтоб вы убили его главных обидчиков, Гримнока Дитя Войны и Коргааха. По выполнении вернитесь к нему в лощину Кровавого Молота в Острогорье."}}
D[10544] = {"Чума на оба ваших клана!",{"При помощи гибельного сильного фетиша прокляните 5 домов или башен в крепости Камнерогов и 2 на заставе Кровавого Молота. По выполнении задания вернитесь к Т'чали Знахарю в лощину Кровавого Молота в Острогорье."}}
D[10545] = {"Бочонок клана Камнерогов",{"Т'чали просит, чтобы вы отнесли бочонок забористого пойла клана Кровавого Молота и попытались бы напоить им 5 огров из клана Камнерогов. Если все получится, вернитесь к Т'чали Знахарю в лощину Кровавого Молота в Острогорье."}}
D[10546] = {"Борак, сын Оронока",{"Найдите Борака сына Оронока возле лагеря Затмения в долине Призрачной Луны."}}
D[10547] = {"Выгодный обмен",{"Найдите тухлое яйцо араккоа и доставьте его Тобиасу Грязежору в город Шаттрат, расположенный на северо-западе леса Тероккар."}}
D[10548] = {"Горькая правда",{"Эраланна из Транквиллиона просит вас найти усохшую голову археолога в одном из сундуков Зеб'Телы или Зеб'Новы."}}
D[10550] = {"Пучок кровопийки",{"Отнесите пучок кровопийки Бораку сыну Оронока на мост возле лагеря Затмения, в долине Призрачной Луны. n."}}
D[10551] = {"Присяга верности Алдорам",{"Вы уверены в своем выборе, Тунфокс? Алдоры с радостью примут вас в ряды своих союзников, но Провидцы вряд ли смогут вам это простить."}}
D[10552] = {"Присяга верности Провидцам",{"Вы уверены в своем выборе, Солэтьюд? Провидцы с радостью примут вас в ряды своих союзников, но Алдоры вряд ли смогут вам это простить."}}
D[10553] = {"Ворен'таль Предсказатель",{"Поговорите с Ворен'талем в его библиотеке на ярусе Провидцев в Шаттрате.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10554] = {"Ишана",{"Поговорите с Ишаной в святилище Вечного Света на возвышенности Алдоров в Шаттрате.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10555] = {"Недомогание",{"Собрать 18 выдернутых перьев Лашш, затем прочесть фолиант Лашш на вершинах деревьев Гнездовья Лашш."}}
D[10556] = {"Рисунки",{"При помощи горсти перьев в кругу заклинаний Лашш наложите заклинания, затем вернитесь к Даранелле в Сильванаар прежде, чем дух калири покинет вас."}}
D[10557] = {"Испытательный полет: Конденсаторий зефира",{"Поговорите с Ралли Быстроцапом и испытайте Конденсанторий зефира. Вернитесь к Талли Быстроцапу на станцию Тошли."}}
D[10558] = {"Уважительное отношение Оплота Чести",{"Командир армии Данат Троллебой из Оплота Чести на полуострове Адского Пламени желает, чтобы вы заслужили уважительное отношение Оплота Чести, продолжив сражаться с орками Скверны в Разрушенных залах цитадели Адского Пламени."}}
D[10559] = {"Уважительное отношение Траллмара",{"Заслужите уважение Траллмара, сражаясь с орками Скверны в Разрушенных залах цитадели Адского Пламени по совету Назгрела из Траллмара на полуострове Адского Пламени."}}
D[10560] = {"Почтительное отношение Ша'тар",{"Заслужите почтительное отношение Ша'тар, сразившись с силами Кель'таса в Крепости Бурь, после чего поговорите с А'далом в Шаттрате."}}
D[10561] = {"Уважение Хранителей Времени",{"Заслужите уважение Хранителей Времени. Для этого необходимо проследить, чтобы никто не нарушил течение времени и не изменил ход прошлых событий в старом Хилсбраде и в Черных топях в пещерах Времени."}}
D[10562] = {"Окружены!",{"Убейте 10 боевых инферналов для командира звена Нуаинна из цитадели Громового Молота."}}
D[10563] = {"В форт Легиона",{"Отправляйтесь в форт Легиона, найдите там переговорное устройство и, воспользовавшись маскировкой, выведайте планы Легиона. Вернитесь к командиру звена Нуаинну в цитадель Громового Молота, когда выполните задание."}}
D[10564] = {"Перебей инферналов!",{"Используйте бомбу Скверны, находясь в центре зеленого знака в форте Легиона, чтобы уничтожить огненных големов. Доложите о выполнении задания командиру звена Нуаинну из цитадели Громового Молота."}}
D[10565] = {"Камни Векх'ниров",{"Добудьте кристалл век'ниров и отнесите в круг закинаний век'ниров. Затем принесите заряженный кристалл век'ниров Дертроку в деревню Мок'Натал."}}
D[10566] = {"Пробы и ошибки",{"Испытайте все жезлы Дертрока на огре-рабе араккоа, затем возвращайтесь к Дертроку. Для использования каждого жезла понадобится пылающий кристалл Вех'ниров."}}
D[10567] = {"Создание подвески",{"Добудьте 6 когтей араккоа из гнездовья Рууан и положите их круг оракула из предвестника Ворона. Убейте его и отнесите подвеску предвестника Тимеону в чащобу Рууан."}}
D[10568] = {"Таблички Баа'ри",{"Соберите для анахоретки Сейлы 12 табличек Баа'ри. Таблички могут быть где-то закопаны или находиться у Пеплоустов-рабочих.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10569] = {"Развалины Скет'лона",{"Добудьте у темного конклава араккоа и принесите наезднику на грифоне Киерану первую, вторую и третью страницы дневника командира Скет'лона."}}
D[10570] = {"Охота на Посла",{"Заберите письмо Ярости Бури на мосту возле лагеря Затмения для Борака сына Оронока."}}
D[10571] = {"Старец Орону",{"Найдите в руинах Баа'ри приказы Акамы, адресованные Орону Старцу, и принесите их анахоретке Сейле к алтарю Ша'тар.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10572] = {"Сборка бомбы",{"Добудьте энергетический сердечник и часть обшивки сквернобота и принесите материалы командиру звена Нуаинну из цитадели Громового Молота."}}
D[10573] = {"Кузница Смерти",{"Поговорите с штормером Эваном Дикокрылом в башне Кузницы Смерти."}}
D[10574] = {"Осквернители из клана Пеплоустов",{"Добудьте 4 фрагмента медальона у Хаалума, Айкенена, Уйлару, и Лакаана и вернитесь к анахоретке Сейле к алтарю Ша'тар в долине Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10575] = {"Клеть Стражницы",{"Отправляйтесь в Клеть Стражницы, к югу от руин Баа'ри и расспросите Санору о местонахождении Акамы для анахоретки Сейлы.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10576] = {"Уловки Призрачной Луны",{"Принесите 6 фрагментов доспехов из лагеря Затмения Бораку, сыну Оронока, на мост возле лагеря Затмения в долине Призрачной Луны."}}
D[10577] = {"Чего Иллидан хочет, Иллидан получит...",{"Доставьте послание Иллидана главнокомандующему Рууску в лагерь Затмения."}}
D[10578] = {"Код Проклятия – Вклад Борака",{"Отберите для Борака, сына Оронока, третью часть Кода Проклятия у Руула Светокрада.","","Для выполнения этого задания вам потребуются помощники."}}
D[10579] = {"Код Проклятия – Третий фрагмент",{"Принесите сейф Борака Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны."}}
D[10580] = {"Куда подевались эти клятые гномы?",{"Командир Тень Небес просит вас обыскать южные районы Зазубренной гряды Острогорья, чтобы найти, где сейчас Тошли и прочие гномы."}}
D[10581] = {"Иди по крошечкам!",{"Р-3Д0 намекает вам, что если вы пойдете по следу из запчастей вверх по склону на Островерхий гребень, вы найдете гномов в месте, именуемом станция Тошли.","","Если найдете Тошли, поговорите с ним."}}
D[10582] = {"Приспешники Совета Теней",{"Убейте 10 стражей и 5 призывателей из Кузницы Смерти для штормера Эвана Дикокрыла."}}
D[10583] = {"Судьба Фланиса",{"Разыщите Фланиса Быстрокрыла в Кузнице Смерти, и принесите его сумку штормеру Эвану Дикокрылу в башню Кузницы Смерти."}}
D[10584] = {"Спасти преобразователи энергии!",{"Тошли просит вас взять протовольтаический магнетоколлектор и поймать 5 электроменталей. По выполнении вернуться к нему на станцию Тошли в Острогорье."}}
D[10585] = {"Чертог Призыва",{"Раздобудьте стихийный подчинитель у кузнеца или ремонтника из Кузницы Смерти и используйте его, чтобы прервать ритуал в чертоге призыва. Доложите о выполнении задания штормеру Эвану Дикокрылу из башни Кузницы Смерти."}}
D[10586] = {"Смерть вестнику войны!",{"Убейте Разууна Завоевателя, заберите его приказы и вернитесь к командиру звена Нуаинну в цитадель Громового Молота."}}
D[10587] = {"Тренировочная площадка Карабора",{"Отберите для экзарха Онаалы у соискателей и посвященных охотников на демонов, сосредоточенных в руинах Карабора, 8 глеф армии Ярости Солнца.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10588] = {"Код Проклятия",{"Используйте Код Проклятия у Алтаря Проклятия, чтобы призвать Цируха Повелителя Огня.","","Уничтожьте его и пообщайтесь с целителем земли Торлоком, которого вы найдете там же."}}
D[10589] = {"Получение доступа",{"Принесите пульт от телепорта Легиона командиру звена Нуаинну из цитадели Громового Молота. Пульты можно найти у мо'аргов-оружейников в форте Легиона."}}
D[10590] = {"Доказательство ненависти",{"Принесите 20 камней Плети приспешников Мелару Клинку Рассвета из Бастиона."}}
D[10592] = {"Мудрость королевы банши",{"Отнесите фрагменты камня Плети Леди Сильване Ветрокрылой в Подгород."}}
D[10593] = {"Древнее зло",{"Раскройте тайны храма Атал'Хаккар, освободите Атал'алариона и добудьте гнилую лозу из его плоти. По выполнении задания вернитесь к Мелару в Бастион."}}
D[10594] = {"Калибровка резонансной частоты",{"Никвинкль Метрогном хочет, чтобы вы расположили осцилляционные сканеры таким образом, чтобы стоя среди них вы оказались в точке перекрытия пяти осцилляционных полей.","","По выполнении вернитесь к нему на станцию Тошли в Острогорье."}}
D[10595] = {"Окружены!",{"Убейте 10 боевых инферналов для кровавого стража Галмока из деревни Призрачной Луны."}}
D[10596] = {"В форт Легиона",{"Отправляйтесь в форт Легиона, найдите переговорное устройство и, замаскировавшись, выведайте планы Легиона. Вернитесь к кровавому стражу Галмоку в деревню Призрачной Луны, когда выполните задание."}}
D[10597] = {"Сборка бомбы",{"Добудьте энергетический сердечник и часть обшивки сквернобота для кровавого стража Галмока из деревни Призрачной Луны."}}
D[10598] = {"Перебей инферналов!",{"Используйте бомбу Скверны, находясь в центре зеленого знака в форте Легиона, чтобы уничтожить инферналов. Доложите о выполнении кровавому стражу Галмоку из деревни Призрачной Луны."}}
D[10599] = {"Кузница Смерти",{"Поговорите с разведчиком Заграном на Вышке на золе."}}
D[10600] = {"Приспешники Совета Теней",{"Убейте 10 стражей и 5 призывателей из Кузницы Смерти для разведчика Заграна с Вышки на золе."}}
D[10601] = {"Судьба Кагроша",{"Разыщите Кагроша в Кузнице Смерти и принесите его сумку разведчику Заграну на вышку на золе."}}
D[10602] = {"Чертог Призыва",{"Раздобудьте стихийный подчинитель у кузнеца или ремонтника из Кузницы Смерти и используйте его, чтобы прервать ритуал в чертоге призыва. Доложите о выполнении задания разведчику Заграну на Вышке на золе."}}
D[10603] = {"Смерть вестнику войны!",{"Убейте завоевателя Разууна, добудьте у него приказы Разууна и вернитесь к кровавому стражу Галмоку в деревню Призрачной Луны."}}
D[10604] = {"Получение доступа",{"Принесите пульт от телепорта Легиона кровавому стражу Галмоку в деревню Призрачной Луны. Пульты можно найти у мо'аргов-оружейников в форте Легиона."}}
D[10605] = {"Призыв Карендина",{"Поговорите с Карендином Халгаром в Подгороде."}}
D[10606] = {"Искусство ухода за скверноботом",{"Убейте доктора Потрошилло и заберите у него ключ. Откройте этим ключом сейф доктора и заберите книгу \"Искусство ухода за скверноботом\". Принесите ее Плекси в Точку вторжения: Катаклизм."}}
D[10607] = {"Шепот Бога-ворона",{"Убейте араккоа Гришны, чтобы на две минуты обрести Понимание речи Ворона. Находясь под действием этого заклятия, вы можете найти и получить пророчества в четырех святилищах. Вернитесь после посещения всех четырех святилищ."}}
D[10608] = {"Ясно как день!",{"Никвинкль Метрогном желает, чтобы вы убили 10 кристальных камнедеров. По выполнении вернитесь к нему на станцию Тошли в Острогорье."}}
D[10609] = {"Что было первым, дракон или яйцо?",{"Соберите 3 сущностей прародителя драконов Пустоты, 3 субстанции взрослого дракона и 3 субстанции зрелого дракона. Принесите их Физиту Тиктаку по прозвищу Док на станцию Тошли в Острогорье."}}
D[10610] = {"Основы ведения разведки"}
D[10611] = {"Искусство ухода за скверноботом",{"Убейте доктора Потрошиллера и заберите у него ключ. Откройте этим ключом сейф доктора и заберите книгу \"Искусство ухода за скверноботом\". Принесите его Наканси в Точку вторжения: Катаклизм."}}
D[10612] = {"Машина для убийства",{"Используйте панель управления скверноботом, чтобы захватить контроль над скверноботом-часовым. Уничтожьте 60 инферналов из Кузницы Смерти, прежде чем ваш сквернобот падет. По выполнении вернитесь к Плекси в точку вторжения: Катаклизм."}}
D[10613] = {"Машина для убийства",{"Используйте панель управления скверноботом, чтобы захватить контроль над скверноботом-часовым. Уничтожьте 60 инферналов из Кузницы Смерти, прежде чем ваш сквернобот падет. По выполнении вернитесь к Наканси в точку вторжения: Катаклизм."}}
D[10614] = {"Шепот ветра",{"Найдите Леорокса в деревне Мок'Натал в Острогорье."}}
D[10615] = {"Чащоба Рууан",{"Поговорите с Времионом в Вечной роще, что в чащобе Рууан в Острогорье."}}
D[10617] = {"Коконы шелкокрыла",{"Таэрек из деревни Мок'Натал просит вас принести 8 коконов шелкокрыла с личинок шелкокрыла.","","Быстро убейте личинок, чтобы те не начали превращаться в шелкокрылов, прогрызая свои коконы."}}
D[10618] = {"Нежнейшие крылья",{"Силмара из деверни Мок'Натал просит вас принести ей 12 радужных крыльев."}}
D[10619] = {"Клан Пеплоустов",{"Убейте для воздаятеля Алуумена 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10620] = {"Угроза горного хребта",{"Дина Головокружилка просит вас убить 10 пауков высокогорья. По выполнении вернитесь к ней на станцию Тошли в Острогорье."}}
D[10621] = {"Осколок погибели Иллидари",{"Принесите осколок проклятия иллидари Ординну Громовому Кулаку в цитадель Громового Молота."}}
D[10622] = {"Доказательство верности",{"Убейте Зандраса в Клети Стражницы и возвращайтесь к Санору."}}
D[10623] = {"Осколок погибели Иллидари",{"Принесите осколок проклятия иллидари Грокому Мертвому Глазу в деревню Призрачной Луны."}}
D[10624] = {"История про привидений...",{"Принесите главному аптекарю Хильдегард из деревни Призрачной Луны 15 горстей неостывающего пепла."}}
D[10625] = {"Спектроскоп",{"Убейте для главного аптекаря Хильдегард из деревни Призрачной Луны 12 ревнителей из клана Призрачной Луны."}}
D[10626] = {"Сдать оружие!",{"Принесите глефу Маказрадона и глефу Моргророна Ординну Громовому Кулаку в цитадель Громового Молота."}}
D[10627] = {"Сдать оружие!",{"Принесите глефу Мазакрадона и глефу Моргророна Грокому Мертвому Глазу в деревню Призрачной Луны."}}
D[10628] = {"Акама",{"Поговорите с Акамой в тайной комнате Клети Стражницы."}}
D[10629] = {"Шизанутая работенка",{"Используйте свисток гончей Скверны, чтобы призвать гончую. Выведите ее на прогулку и убейте парочку безумных зловепрей. Поищите ключи от крошшера в помете гончей Скверны. Верните ключи штейгеру Разлкразу, который находится на руднике к северо-западу от Траллмара."}}
D[10630] = {"Рядом с Траллмаром",{"Убейте Урга'зза и возвращайтесь к штейгеру Разлкразу на рудник к северо-западу от Траллмара."}}
D[10632] = {"Точи зубы!",{"Разак Сковородкер просит вас принести ему 5 острейших зубов Кинжальной Пасти. Принесите их ему на станцию Тошли в Острогорье."}}
D[10633] = {"Терон Кровожад – Правда и Вымысел",{"Найдите древнего духа долины Призрачной Луны для главного аптекаря Хильдегард из деревни Призрачной Луны в одноименной долине. Если вы потеряете свой спектроскоп, Хильдегард может сделать вам новый."}}
D[10634] = {"Прорицание: Броня Кровожада",{"Завладейте броней Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней."}}
D[10635] = {"Прорицание: Плащ Кровожада",{"Завладейте плащом Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней."}}
D[10636] = {"Прорицание: буздыхан Кровожада",{"Завладейте буздыханом Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней."}}
D[10637] = {"Необходимая уловка",{"Вернитесь в Руины Карабора и освободите для экзарха Онаалы Разрушителя Азалота.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10638] = {"NOT A QUEST",{"Seek <NAME> in the <DISTRICT> of Silvermoon City."}}
D[10639] = {"Терон Кровожад, то есть я...",{"Древний дух долины Призрачной Луны обвел вас вокруг пальца! Вы сделали все, что он просил, но оказалось, что этот дух – сам Терон Кровожад. Чтобы освободиться от его власти вы должны выполнить его распоряжение и убить Карсиуса Дозорного Древности.","","По выполнении задания вернитесь к главному аптекарю Хильдегард в деревню Призрачной Луны."}}
D[10640] = {"Алтруис",{"Отправляйтесь в западный Награнд и найдите Алтруиса Страдальца.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10641] = {"Против Легиона",{"Алтруис Страдалец просит вас добыть свежей крови зловещей жрицы на базе Легиона: Геенна в Пустоверти. Пролейте кровь на землю и убейте аватару Саталь. По выполнении задания вернитесь к Алтруису."}}
D[10642] = {"Дух из машины",{"Принесите 15 горстей неостывающего пепла Зорусу Ревнителю в цитадель Громового Молота в долине Призрачной Луны."}}
D[10643] = {"Вестники Призрачной Луны",{"Убейте 12 предвестников из клана Призрачной Луны для Зоруса Ревнителя из цитадели Громового Молота."}}
D[10644] = {"Терон Кровожад – Правда и Вымысел",{"Найдите древнего духа долины Призрачной Луны для Зоруса Ревнителя в цитадели Громового Молота. Если вы потеряете свой спектроскоп, Зорус может сделать вам новый."}}
D[10645] = {"Терон Кровожад, то есть я...",{"Древний дух долины Призрачной Луны обвел вас вокруг пальца! Вы сделали все, что он просил, но оказалось, что этот дух – сам Терон Кровожад. Чтобы освободиться от его власти вы должны выполнить его распоряжение и убить Карсиуса Дозорного Древности.","","По выполнении задания вернитесь к Зорусу Ревнителю в цитадель Громового Молота."}}
D[10646] = {"Ученик Иллидана",{"Выслушайте рассказ Алтруиса."}}
D[10647] = {"Разыскивается: Увурос, бич долины Призрачной Луны",{"Убейте Увуроса и доставьте его пламенеющую гриву военному глашатаю Сардону Чистому Удару в деревню Призрачной Луны в одноименной долине."}}
D[10648] = {"Разыскивается: Увурос, бич долины Призрачной Луны",{"Убейте Увуроса и доставьте его пламенеющую гриву военному глашатаю Пивному Брюху в цитадель Громового Молота в долине Призрачной Луны."}}
D[10649] = {"Книга Имен Скверны",{"Проберитесь в Темный лабиринт в Аукиндоне и добудьте у Черносерда Подстрекателя Книгу Имен Скверны. После этого вернитесь в Награнд к Алтруису."}}
D[10650] = {"Возвращение к Алдорам",{"Поговорите с экзархом Онаалой у алтаря Ша'тар, в долине Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10651] = {"Варедиса нужно остановить!",{"Отправляйтесь в Руины Карабора и убейте Аландиен, Тераса, Нетариеля и самого Варедиса. Используйте Книгу Имен Скверны, когда Варедис будет перевоплощаться, чтобы ослабить его. Вернитесь к экзарху Онаале с книгой Имен Скверны, по выполнении задания.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10652] = {"В тылу врага",{"Поговорите с Веронией, когда будете готовы отбыть в манагорн Коруу. Оказавшись там, поговорите с Каледисом Сияющим Рассветом.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10653] = {"Знаки Саргераса",{"Принесите 10 знаков Саргераса Адуину Стражу Света в Шаттрат.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10654] = {"Больше знаков Саргераса",{"Вы принесли еще знаков различия наших врагов, |3-6(Жрица)? Пылающий Легион все еще угрожает нам, и мы преследуем его повсеместно."}}
D[10655] = {"Знак Саргераса"}
D[10656] = {"Перстни Ярости Солнца",{"Принесите магистру Файленн 10 перстней Ярости Солнца.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10657] = {"Оседлать молнию",{"Тошли хочет, чтобы вы при помощи реполяризованной магнитной сферы абсорбировали 25 ударов молний от чешуекрылых змеев. Также добудьте 5 молниевых желез чешуекрылых. Доставьте все Тошли в Острогорье."}}
D[10658] = {"Больше перстней Ярости Солнца"}
D[10659] = {"Перстень Ярости Солнца"}
D[10660] = {"Что за странные создания?",{"Добудьте 8 селезенок сквернопламенных деметродонов для ученого Тиоруса в деревне Призрачной Луны в одноименной долине."}}
D[10661] = {"Умопотрошительно!",{"Принесите 8 селезенок сквернопламенных деметродонов Гномусу в цитадель Громового Молота."}}
D[10662] = {"Кузнец–отшельник",{"Принесите ящик со слитками Дэвиду Уэйну в приют Уэйна, который находится в лесу Тероккар."}}
D[10663] = {"Кузнец–отшельник",{"Принесите ящик со слитками Дэвиду Уэйну в приют Уэйна, который находится в лесу Тероккар."}}
D[10664] = {"Дополнительные материалы",{"Принесите адамантитовую рамку, 4 куска толстой узловатой кожи и тотем защиты от демонов Дэвиду Уэйну в Приют Уэйна."}}
D[10665] = {"Новинка из Механара",{"Принесите избыточно заряженный аккумулятор маны Дэвиду Уэйну в Приют Уэйна."}}
D[10666] = {"Лексикон демоника",{"Добудьте книгу \"Лексикон демоника\" у великого мастера Ворпила и принесите его Дэвиду Уэйну в Приют Уэйна."}}
D[10667] = {"Суглинок из Нижнего мира",{"Достаньте фиал с суглинком Нижнего мира у гидромантки Теспии и принесите его Дэвиду Уэйну в приют Уэйна."}}
D[10668] = {"Против иллидари",{"Алтруис Страдалец просит вас убить Лотроса на аванпосте иллидари в долине Призрачной Луны."}}
D[10669] = {"Вопреки всему",{"Алтруис Страдалец хочет, чтобы вы взяли прочное серебряное копье и вонзили его на прогалине с порталом близ озера Болотных Огоньков, чтобы пробудить Кселета. Когда убьете демона, вернитесь к Алтруису."}}
D[10670] = {"Слеза Матери-Земли",{"Добудьте слезу Матери-Земли у О'мрогга Завоевателя и принесите ее Дэвиду Уэйну в приют Уэйна."}}
D[10671] = {"Не только фунт мяса",{"Дина Головокружилка просит вас добыть 5 кусков мяса, напитанного энергией Астрала. По выполнении вернитесь к ней на станцию Тошли в Острогорье."}}
D[10672] = {"Честно говоря, это – бред!",{"Отправляйтесь к потокам лавы возле руин Баа'ри и используйте пульт управления чарами, чтобы контролировать волшебного скорпиона. Переправьтесь на нем через лаву и пометьте 8 больших сквернопламенных деметродонов для ученого Тиоруса."}}
D[10673] = {"Хребтоскверн Старший",{"Убейте Хребтоскверна Старшего и принесите его шкуру ученому Тиорусу в деревню Призрачной Луны в одноименной долине."}}
D[10674] = {"Ловля фантастического света",{"Тошли желает, чтобы вы при помощи световой ловушки поймали 15 световых сфер братства Разаани. По выполнении задания вернитесь к нему на станцию Тошли в Острогорье."}}
D[10675] = {"Попомните гномскую доброту!",{"Тошли хочет, чтобы вы добыли для него коллекцию душ и вернулись к нему на стнацию Тошли в Острогорье."}}
D[10676] = {"Проклятие иллидари",{"Подождите, пока Дэвид Уэйн откует для вас клинок."}}
D[10677] = {"Второе блюдо...",{"Добудьте для Гномуса из цитадели Громового Молота в долине Призрачной Луны потроха крупного деметродона."}}
D[10678] = {"Гвоздь программы",{"Принесите шкуру Хребтоскверна Гномусу в цитадель Громового Молота в долине Призрачной Луны."}}
D[10679] = {"Закалка Меча",{"Отправляйтесь к Жгучим прудам возле подножия Руки Гул'дана, и закалите кованый меч погибели иллидари в озерах лавы. После этого возвращайтесь к Дэвиду Уэйну в приют Уэйна."}}
D[10680] = {"Рука Гул'дана",{"Поговорите с целителем земли Торлоком у Алтаря Проклятия в Долине Призрачной Луны."}}
D[10681] = {"Рука Гул'дана",{"Поговорите с целителем земли Торлоком у Алтаря Проклятия в Долине Призрачной Луны."}}
D[10682] = {"Время для переговоров...",{"Хранитель деревьев Чаун просит вас переговорить с надзирателем Нуааром. После вернитесь к хранителю деревьев в Вечную рощу в Острогорье."}}
D[10683] = {"Таблички Баа'ри",{"Соберите для чародея Тэлиса из святилища Звезд 12 табличек Баа'ри. Таблички могут быть где-то закопаны или находиться у Пеплоустов-рабочих.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10684] = {"Старец Орону",{"Найдите в руинах Баа'ри приказы Акамы, адресованные старцу Орону, и принесите их чародею Телису.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10685] = {"Осквернители из клана Пеплоустов",{"Соберите 4 фрагмента медальона у Хаалума, Айкенена, Уйлару, и Лакаана и вернитесь к чародею Тэлису в святилище Звезд.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10686] = {"Клеть Стражницы",{"Отправляйтесь в Клеть Стражницы, к югу от руин Баа'ри и расспросите Санору о местонахождении Акамы для чародея Телиса.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10687] = {"Тренировочная площадка Карабора",{"Отберите у соискателей и посвященных охотников на демонов, сосредоточенных в руинах Карабора, 8 глеф армии Ярости Солнца. Принесите их Лариссе Солнцесвет в святилище Звезд.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10688] = {"Необходимая уловка",{"Вернитесь в Руины Карабора и освободите Азалота для Лариссы Солнцесвет.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10689] = {"Алтруис",{"Отправляйтесь в западный Награнд и найдите Алтруиса Страдальца.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10690] = {"Мать логова",{"Убейте Рему и сообщите об этом командиру Тень Небес в Сильванаар в Острогорье."}}
D[10691] = {"Возвращение к Провидцам",{"Поговорите с Лариссой Солнцесвет в святилище Звезд в долине Призрачной Луны.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10692] = {"Варедиса нужно остановить!",{"Отправляйтесь в Руины Карабора и убейте Аландиен, Тераса, Нетариеля и самого Варедиса. Используйте Книгу Имен Скверны, когда Варедис будет перевоплощаться, чтобы ослабить его. Вернитесь к Лариссе Солнцесвет с Книгой Имен Скверны по выполнении задания.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10693] = {"Один рекомендательный жетон"}
D[10694] = {"Десять рекомендательных жетонов"}
D[10695] = {"Один рекомендательный жетон"}
D[10696] = {"Десять рекомендательных жетонов"}
D[10697] = {"Один рекомендательный жетон"}
D[10698] = {"Десять рекомендательных жетонов"}
D[10699] = {"Один рекомендательный жетон"}
D[10700] = {"Десять рекомендательных жетонов"}
D[10701] = {"Низвергнуть Глыбня Пустоты",{"Убейте Глыбня Пустоты и сообщите об этом ведущему ракетостроителю Фьюзеляжу, находящемуся в Зоне 52 в Пустоверти."}}
D[10702] = {"Наряд вне очереди",{"Убейте 20 животных, водящихся в долине Призрачной Луны для воеводы Ор'бароха.","","Тварями считаются скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым."}}
D[10703] = {"Зачистка",{"Убейте 20 животных, водящихся в долине Призрачной Луны, для тана Йорегара из цитадели Громового Молота.","","Подойдут скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым."}}
D[10704] = {"Как проникнуть в Аркатрац",{"Принесите А'далу верхний и нижний обломок ключа Аркатраца, чтобы он собрал из них целый ключ."}}
D[10705] = {"Провидец Адало",{"Найдите провидца Адало в Аркатраце в Крепости Бурь."}}
D[10706] = {"Таинственное знамение",{"Вернитесь к Акаме в Клеть Стражницы в долине Призрачной Луны."}}
D[10707] = {"Терраса Ата'мала",{"Отправляйтесь на террасу Ата'мала, в долине Призрачной Луны и раздобудьте Сердце Ярости. По выполнении задания вернитесь к Акаме в Клеть Стражницы."}}
D[10708] = {"Обещание Акамы",{"Принесите медальон Карабора А'далу в Шаттрат."}}
D[10709] = {"Воссоединение",{"Вернитесь к Рексару в оплот Громоборцев в Острогорье."}}
D[10710] = {"Испытательный полет: Звенящий гребень",{"Подпишите отказ от претензий к Талли, затем поговорите с Ралли Быстроцапом насчет Конденсатория зефира. Вернитесь к Талли Цапнабберу на станцию Тошли."}}
D[10711] = {"Испытательный полет: лагерь Разаана",{"Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира. Вернитесь к Талли Быстроцапу на станцию Тошли."}}
D[10712] = {"Испытательный полет: чащоба Рууан",{"Поговорите с Ралли Быстроцапом, чтобы узнать, как использовать конденсаторий зефира. При полете в чащобу Рууан крутите флюгер Пустоты. Передайте флюгер Пустоты О'Малли Быстроцапу, который находится в чащобе Рууан."}}
D[10713] = {"...и время действовать",{"Отправьтесь в чащобу Рууан и убейте 10 лесорубов из культа Змея, затем вернитесь к хранителю деревьев Чауну в Вечную рощу в Острогорье."}}
D[10714] = {"На крыльях Духа",{"Найдите занятых разговором ворожея и надсмотрщика из клана Кровавого Молота, затем при помощи свистка Рексара призовите Духа и проследите за ними. По завершении вернитесь к Рексару в деревню Громоборцев в Острогорье."}}
D[10715] = {"Прогулка в Беспокойную лощину",{"Барон Черногрив говорит вам, что для того, чтобы приготовить яд, нужный Рексару, вы должныдобыть 7 ядовитых желез землероев. Вернитесь к нему в Круг Крови в Острогорье по выполнении."}}
D[10716] = {"Test Flight: Raven's Wood <needs reward>",{"Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира. Вернитесь к Талли Быстроцапу на станцию Тошли."}}
D[10717] = {"Вор у вора...",{"Самия Недомолвка просит вас добыть 5 сетей Культа Змея и принести ей в Вечную рощу в Острогорье."}}
D[10718] = {"У духов есть голоса",{"Гарм Брат Волка поведал вам, где искать Мок'Натал, место, где живет народ Рексара. Расскажите об этом Рексару в оплоте Громоборцев в Острогорье."}}
D[10719] = {"Где записка?",{"Отдайте записку о встрече хранителю деревьев Чауну в Вечную рощу в Острогорье."}}
D[10720] = {"Самые маленькие создания",{"Ударьте в барабан из шкуры кодо возле норы сурка. Держа сурка под контролем, насыпьте яду в три бочонка в лагере клана Кровавого Молота. По выполнении вернитесь к Рексару в оплот Громоборцев в Острогорье."}}
D[10721] = {"Подложим Груллоку свинью",{"Добудьте мешок Груллока и принесите его барону Черногриву в Круг Крови в Острогорье."}}
D[10722] = {"Встреча в пещере Крыла Тьмы",{"Соберите костюм инспектора из деталей одежды, собранных у различных адептов Культа Змея. В этом костюме отправьтесь на встречу с Колфисом Черной Чешуей и расскажите обо всем, что узнаете, хранителю деревьев Чауну в Вечную рощу в Острогорье."}}
D[10723] = {"Горгром Драконоед",{"Отправляйтесь в Камен'мок и добудьте 3 тотема гризли у огров Камен'мока. Поставьте ловушку Черногрива на алтарь Горгрома и убейте Горгрома Драконоеда.","","Когда Горгром будет убит, поставьте 3 тотема гризли возле его туши и вернитесь к Рексару в оплот Громоборцев в Острогорье."}}
D[10724] = {"Пленник Камнерогов",{"Убивайте огров из клана Камнерогов, пока не добудете ключ от клетки виверны. Как только добудете его, идите к клетке виверны и подуйте в свисток, чтобы призвать Духа, который отопрет клетку. После освобождения Леокк, вернитесь в Рексару в деревню Громоборцев в Острогорье."}}
D[10725] = {"Аметистовое Око в восхищении",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока."}}
D[10726] = {"Аметистовое Око в восхищении",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока."}}
D[10727] = {"Аметистовое Око в восхищении",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока."}}
D[10728] = {"Аметистовое Око в восхищении",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока."}}
