D[10736] = {"Путь Аметистового Ока",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум уважительное отношение Аметистового Ока."}}
D[10737] = {"Разрешение учителя",{"Отправляйтесь в Пещеры Времени и уговорите Медива разрешить пользоваться восстановленным ключом ученика."}}
D[10738] = {"Выдающиеся заслуги",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока."}}
D[10739] = {"Выдающиеся заслуги",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока."}}
D[10740] = {"Выдающиеся заслуги",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока."}}
D[10741] = {"Выдающиеся заслуги",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить как минимум почтительное отношение Аметистового Ока."}}
D[10742] = {"Перед выстрелом",{"Протрубите в боевой рог Рексара у алтаря Гока, затем убейте Гока. По выполнении задания вернитесь к Рексару в деревню Громоборцев в Острогорье."}}
D[10744] = {"Вести о Победе",{"Вернитесь в цитадель Громового Молота и поговорите с Курдраном Громовым Молотом."}}
D[10745] = {"Вести о Победе",{"Возвращайтесь в деревню Призрачной Луны и поговорите с воеводой Ор'барохом."}}
D[10747] = {"Дракончики Культа Змея",{"Самия Недомолвка просит вас поймать при помощи сети для ловли дракончиков 10 черных дракончиков Культа Змея. Затем вернитесь к ней в Вечную рощу в Острогорье."}}
D[10748] = {"Да сгинет Макснар!",{"От имени друидов Кенарийской экспедиции из Вечной рощи и ради блага местных жителей чащобы Рууан, хранитель деревьев Чаун просит вас убить Макснара Бледную Пасть. Вернитесь к нему в Вечную рощу в Острогорье по выполнении задания."}}
D[10749] = {"Яд барона Черногрива",{"Доставьте яд барона Черногрива Рексару в оплот Громоборцев в Острогорье."}}
D[10750] = {"Путь Завоевания",{"Отправляйтесь по Пути Завоевания в долине Призрачной Луны. Как только вы произведете предварительную оценку местности, используйте кор'кронское сигнальное ружье, чтобы подать сигнал кор'кронскому наезднику на ветрокрыле.","","Поговорите с воеводой Ор'барохом по выполнении. Если вы потеряете свое сигнальное ружье, можете потребовать новое."}}
D[10751] = {"Перерезанный путь",{"Убейте 20 солдат, 10 кавалеристов и 10 заклинателей из лагеря Затмения, а потом используйте кор'кронское сигнальное ружье, чтобы дать знак другому кор'кронскому наезднику на ветрокрыле, о том, что задание выполнено.","","Поговорите с воеводой Ор'барохом в деревне Призрачной Луны, если вы потеряете сигнальное ружье, чтобы получить новое."}}
D[10752] = {"Вперед, в Ясеневый лес",{"Поговорите с Раэной Волкопас в Астранааре."}}
D[10753] = {"Зачистка пустоши",{"Убейте 4 скверноподданных чешуекрылых змеев, 4 скверноподданных из каньона Кинжальной Пасти и 2 осквернителей."}}
D[10754] = {"Вход в цитадель",{"Принесите форму для отливки ключа командиру армии Данату в Оплот Чести на полуострове Адского Пламени."}}
D[10755] = {"Вход в цитадель",{"Принесите форму для отливки ключа Назгрелу в Траллмар на полуострове Адского Пламени."}}
D[10756] = {"Великий мастер Рохок",{"Принесите форму для отливки ключа Рохоку в Траллмар."}}
D[10757] = {"Просьба Рохока",{"Принесите Рохоку 4 слитка оскверненного железа, 2 горсти чародейской пыли и 4 частицы огня в Траллмар на полуострове Адского Пламени."}}
D[10758] = {"Жарче, чем в пекле",{"Уничтожьте сквернобота на полуострове Адского Пламени и погрузите внутрь него необожженную форму для отливки ключа. Принесите обожженную форму для отливки ключа Рохоку в Траллмар."}}
D[10759] = {"Найти дезертира",{"Найдите Паршаха в Магмовых полях и поговорите с ним."}}
D[10760] = {"Развалины Скет'лона",{"Добудьте у темного конклава араккоа и принесите сержанту Каргулу в деревню Призрачной Луны первую, вторую и третью страницы дневника командира Скет'лона."}}
D[10761] = {"Найти дезертира",{"Найдите Паршаха в Магмовых полях и поговорите с ним."}}
D[10762] = {"Великий Мастер Болтуй",{"Принесите форму для отливки ключа Болтую в Оплот Чести."}}
D[10763] = {"Просьба Болтуя",{"Принесите Болтую 4 слитка оскверненного железа, 2 горсти чародейской пыли и 4 частицы огня в Оплот Чести на полуострове Адского Пламени."}}
D[10764] = {"Жарче, чем в пекле",{"Уничтожьте сквернобота на полуострове Адского Пламени и закалите на его остатках необожженную форму для отливки ключа. Принесите обожженную форму для отливки ключа Болтую в Оплот Чести."}}
D[10765] = {"Война Миров",{"Убейте канцлера Кровавую Листву и Корока Могучего и добудьте приказ Иллидана. Используйте кор'кронское сигнальное ружье, чтобы дать кор'кронскому наезднику на ветрокрыле сигнал о выполнении этого задания.","","Поговорите с воеводой Ор'барохом в деревне Призрачной Луны, если вы потеряете сигнальное ружье, чтобы получить новое."}}
D[10766] = {"Точка вторжения: Катаклизм",{"Доложитесь Плекси в Точке вторжения: Катаклизм."}}
D[10767] = {"Точка вторжения: Катаклизм",{"Доложитесь Наканси в Точке вторжения: Катаклизм."}}
D[10768] = {"Гербовые накидки Иллидари",{"Соберите 10 гербовых накидок иллидари, а потом подайте сигнал наездника на ветрокрыле, с помощью кор'кронского сигнального ружья.","","Поговорите с воеводой Ор'барохом в деревне Призрачной Луны, если вы потеряете сигнальное ружье, чтобы получить новое."}}
D[10769] = {"Удар исподтишка",{"Убейте 5 безумных колоссов в личине эльфа крови – иллидари и потом вернитесь к воеводе Ор'бароху в деревню Призрачной Луны в одноименной долине. Верните ему кор'кронское сигнальное ружье."}}
D[10770] = {"Угольки",{"Замшельник Древний просит вас убить 8 пламенных бесов, а затем вернуться к нему в чащобу Рууан."}}
D[10771] = {"Из пепла",{"Замшельник Древний хочет, чтобы вы отправились в Гарь и посадили семена железнокорня в три кучи плодородной вулканической почвы и вернулись к нему в чащобу Рууан."}}
D[10772] = {"Путь Завоевания",{"Отправляйтесь по Пути Завоевания в долине Призрачной Луны. Как только вы произведете предварительную оценку местности, используйте сигнальное ружье клана Громового Молота, чтобы подать сигнал наезднику на грифоне.","","Поговорите с таном Йорегаром в цитадели Громового Молота в долине Призрачной Луны, если потеряете сигнальное ружье, чтобы получить новое."}}
D[10773] = {"Перерезанный путь",{"Убейте 20 солдат, 10 кавалеристов из лагеря Затмения и 5 сынов Корока, а потом используйте сигнальное ружье клана Громового Молота, чтобы дать знак другому наезднику на грифоне, о том, что задание выполнено.","","Поговорите с таном Йорегаром в цитадели Громового Молота в долине Призрачной Луны, если потеряете сигнальное ружье, чтобы получить новое."}}
D[10774] = {"Великан плюс эльфийка равно...",{"Убейте канцлера Кровавую Листву и Корока Могучего и верните приказ Иллидана. Используйте сигнальное ружье клана Громового Молота, чтобы дать сигнал наезднику на грифоне, что вы закончили выполнение этого задания.","","Поговорите с таном Йорегаром в цитадели Громового Молота в долине Призрачной Луны, если потеряете сигнальное ружье, чтобы получить новое."}}
D[10775] = {"Гербовые накидки Иллидари",{"Соберите 10 гербовых накидок Иллидари, а потом подайте сигнал наезднику на грифоне, с помощью сигнального ружья клана Громового Молота. Поговорите с таном Йорегаром в цитадели Громового Молота в долине Призрачной Луны, если потеряете сигнальное ружье, чтобы получить новое."}}
D[10776] = {"Удар исподтишка",{"Убейте 5 безумных колоссов, находясь в облике посланника Иллидана, потом вернитесь к тану Йорегару в цитадель Громового Молота в долине Призрачной Луны. Верните ему сигнальное ружье клана Громового Молота."}}
D[10777] = {"Тотем Азгара",{"Принесите Паршаху в Магмовые поля военный тотем Скет'лона."}}
D[10778] = {"Жезл Лиантэ",{"Заберите ключ Лиантэ у любого из эльфов крови в лагере Затмения, откройте сейф и заберите жезл Лиантэ. Вернитесь с ветвью к Паршаху в Магмовые поля."}}
D[10779] = {"Путь охотника",{"Поговорите с охотницей Келлой Тетивой Ночи."}}
D[10780] = {"Перья Скет'лона",{"Соберите 8 перьев Скет'лона и принесите их Паршаху в Магмовые поля."}}
D[10781] = {"Битва у Кровавого дозора",{"Сразитесь с войском иллидари возле Кровавого дозора и останьтесь в живых!","","Вернитесь к А'далу в Шаттрат, если сумеете победить."}}
D[10782] = {"Зарядка набалдашника",{"Возьмите в руки Незавершенный Набалдашник. Отправляйтесь к Алтарю Проклятия и используйте его, пока вы находитесь возле Гул'дана. Когда набалдашник зарядится, возвращайтесь к Паршаху в Магмовые Поля."}}
D[10783] = {"Барон Черногрив",{"Поговорите с бароном Черногривом в Круге Крови в Острогорье."}}
D[10784] = {"Уничтожить лагерь Кровавого Молота!",{"Тор'чанк Двукоготь просит вас убить 10 извергов и 5 чернокнижников из клана Кровавого Молота. Потом вернитесь к нему в оплот Громоборцев в Острогорье."}}
D[10785] = {"Ловушка!",{"Отнесите ловушку пламени дракона Рексару в оплот Громоборцев в Острогорье."}}
D[10786] = {"Резня в Камен'моке",{"Убейте 5 громил и 3 шаманов из Камен'мока, затем вернитесь к Тор'чанку Двукогтю в оплот Громоборцев в Острогорье."}}
D[10788] = {"Возвращение к Талионии",{"Поговорите с Талионией в Луносвете."}}
D[10789] = {"Возвращение к Карендину Халгару",{"Поговорите с Карендином Халгаром в Подгороде."}}
D[10790] = {"Возвращение к Ган'рулу Кровавому Глазу",{"Найдите Ган'рула Кровавого Глаза в Оргриммаре и поговорите с ним."}}
D[10791] = {"Приветствие духа Волка",{"Зажгите обрядовые благовония около свечей в хижине Малуказа и наблюдайте за церемонией. По завершении церемонии поговорите с Малуказом еще раз."}}
D[10792] = {"Сжечь Зет'Гор!",{"Убейте батраков из клана Кровавой Глазницы, заберите у них факелы, зажгите факелы в кузне Зет'Гора и забросьте горящие факелы в строения Зет'Гора."}}
D[10793] = {"Записи Вал'зарека: Предвестье Войны",{"Найдите Марка Аврелиона, верховного генерала Ша'тар в Кровавом дозоре.","","Ищите его в кристаллической тюрьме."}}
D[10794] = {"Разбойники Изувеченной Длани",{"Поговорите с Шентулом в Оргриммаре."}}
D[10795] = {"Встреча с Доргоком",{"Командир Гефус Камнестен хочет, чтобы вы убили Доргока в лагере Кровавого Молота. Когда выполните поручение, вернитесь к нему в Вечную рощу в Острогорье."}}
D[10796] = {"Уничтожить лагерь Кровавого Молота!",{"Лейтенант Файрвезер приказывает вам убить 10 извергов и 5 чернокнижников из клана Кровавого Молота. По выполнении вернитесь к ней в Вечную рощу в Острогорье."}}
D[10797] = {"Благоволение гронна",{"Отнесите благоволение Горгрома командиру Гефусу Камнестену в Вечную рощу в Острогорье."}}
D[10798] = {"Визит к барону",{"Поговорите с бароном Черногривом насчет ловушки. Он живет в Круге Крови в Острогорье."}}
D[10799] = {"Прогулка в Беспокойную лощину",{"Барон Черногрив просит вас принести ему 7 ядовитых желез землероев. Вернитесь к нему в Круг Крови в Острогорье по выполнении."}}
D[10800] = {"Спи спокойно, гронн",{"Барон Черногрив хочет, чтобы вы украли мешок Груллока, а затем вернулись к нему в Круг Крови в Острогорье."}}
D[10801] = {"Ловушка!",{"Отнесите ловушку пламени дракона командиру Гефусу Камнестену в Вечную рощу в Острогорье."}}
D[10802] = {"Горгром Драконоед",{"Отправляйтесь в Камен'мок и добудьте 3 тотема гризли у огров Камен'мока. Поставьте ловушку Черногрива на алтарь Горгрома и убейте Горгрома Драконоеда.","","Когда Горгром будет убит, поставьте 3 тотема гризли возле его туши и вернитесь к командиру Гефусу Камнестену в Вечную рощу в Острогорье."}}
D[10803] = {"Резня в Камен'моке",{"Убейте 5 громил и 3 шаманов Камен'мока. Затем вернитесь к лейтенанту Файрвезер в Вечную рощу в Острогорье."}}
D[10804] = {"Доброта",{"Накормите 8 взрослых драконов Пустоты по просьбе Морденая на Полях Крыльев Пустоты."}}
D[10805] = {"Резня в логове Груула",{"Барон Черногрив хочет, чтобы вы с друзьями перебили 10 головорезов, 5 боевых магов, 5 опустошителей из клана Камнерогов и их предводителя, Фингрома. Когда свершите этот подвиг, возвращайтесь к нему в Круг Крови в Острогорье."}}
D[10806] = {"Перед выстрелом",{"Наденьте перстень Черногрива у алтаря Гока, затем убейте Гока. Вернитесь к барону Черногриву в Круг Крови в Острогорье."}}
D[10807] = {"Сломленные из племени Пеплоустов",{"Убейте для Варена Исправителя 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10808] = {"Крах темного конклава",{"Убейте ритуалистов Темного конклава и используйте посох Паршаха, чтобы прервать ритуал призыва. По выполнении задания вернитесь к Паршаху в Магмовые поля."}}
D[10809] = {"Разыскивается: повелитель воргов Крууш",{"Убейте повелителя воргов Крууша и принесите его голову капитану Мрачному Вою на Заставу Хребтолома."}}
D[10810] = {"Поврежденная маска",{"Отнесите поврежденную маску О'Малли Быстроцапу в чащобу Рууан."}}
D[10811] = {"Поиски Нельтараку",{"Найдите Нельтараку, предводителя рода Крыльев Пустоты."}}
D[10812] = {"Тайная маска",{"Отнесите таинственную маску владыке леса Антелариону в чащобу Рууан."}}
D[10813] = {"Очи Гриллока",{"Используйте кристалл Зеззака, чтобы захватить Око Гриллока, затем приблизьтесь к котлу Зеззака, чтобы тот смог извлечь Око. После выполнения задания верните Зеззаку кристалл."}}
D[10814] = {"История Нельтараку",{"Поговорите с Нельтараку и выслушайте его историю."}}
D[10815] = {"Записи Вал'зарека: Предвестье Войны",{"Найдите Марка Аврелиона, верховного генерала Ша'тар, в Кровавом дозоре."}}
D[10816] = {"Восстановление Святых земель",{"Убейте для воздаятеля Алуумена 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10817] = {"Великое воздаяние",{"Убейте для Варена Исправителя 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10818] = {"Барон Черногрив желает вас лицезреть",{"Вы получили приглашение от барона Черногрива. Он желает поговорить с вами о каком-то важном деле. Отправляйтесь к нему в Круг Крови в Острогорье."}}
D[10819] = {"Респиратор Искаженных",{"Наденьте респиратор Верных Скверне и воспользуйтесь переговорным устройством Легиона в лагере Легиона: Злоба."}}
D[10820] = {"Обмануть врага",{"Убейте 4 рабочих Кузни Рока и 4 инженеров Кузни Рока."}}
D[10821] = {"Уволена!",{"Убейте Вестницу Рока и доложите об этом Владыке леса Антелариону в Вечную рощу."}}
D[10822] = {"Перстень Ярости Солнца"}
D[10823] = {"Больше перстней Ярости Солнца"}
D[10824] = {"Перстни Ярости Солнца",{"Принесите 10 перстней армии Ярости Солнца боевому магу Вияре в святилище Звезд.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10825] = {"Тайна сферы",{"Доставьте сферу Гришны хранителю деревьев Чауну в чащобу Рууан в Острогорье."}}
D[10826] = {"Знаки Саргераса",{"Принесите 10 знаков Саргераса предвестнику Саронену в Долину Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10827] = {"Больше знаков Саргераса"}
D[10828] = {"Знак Саргераса"}
D[10829] = {"Древоствол должен знать!",{"Хранитель деревьев Чаун просит вас найти Древоствола, древо мудрости, обитающее в лесу Ворона в Острогорье, и поговорить с ним."}}
D[10830] = {"Экзорцизм для деревьев",{"Найдите 5 гришнатских сфер и 5 перьев лютого ворона и превратите их в перья экзорцизма. При помощи этих перьев изгоните 5 духов кои-кои из листобородов леса Ворона. Как только закончите, вернитесь к Древостволу в лес Ворона в Острогорье."}}
D[10831] = {"Обучение шитью из луноткани",{"Возьмите отрез прочной ткани Пустоты, встаньте в лунный колодец Кенарийского приюта и изготовьте изначальную луноткань. Готовую ткань отнесите Назмаре Песне Луны в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде ткани."}}
D[10832] = {"Обучение шитью из чароткани",{"Принесите образец сущности призрака Пустоты Гидже Чароплетке в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде шитья."}}
D[10833] = {"Обучение шитью из тенеткани",{"Укрепите связь с Алтарем Теней при помощи кристалла Глубоких Теней, после чего вернитесь к Андриону Темнопряду в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде шитья."}}
D[10834] = {"Гриллок \"Пустой Глаз\"",{"Убейте Гриллока Пустого Глаза и принесите Зеззаку на Заставу Хребтолома повязку на глаз Гриллока."}}
D[10835] = {"Аптекарь Антонивич",{"Доставьте послание Албрека аптекарю Антонивичу в Траллмар."}}
D[10836] = {"Переполох в крепости Драконьей Пасти",{"Убейте 15 орков из клана Драконьей Пасти для Нельтараку.","","Засчитывается орк любого ранга."}}
D[10837] = {"На Кряж Крыльев Пустоты!",{"Соберите для Нельтараку 12 кристаллов Лозы Пустоты на Кряже Крыльев Пустоты."}}
D[10838] = {"Демонический кристалл",{"Отнесите демонический кристалл в Яму Адского Пламени, подождите, пока произойдет соединение, и примите сообщение.","","Верните демонический кристалл и его сообщение аптекарю Антонивичу в Траллмар."}}
D[10839] = {"Гнездовье Скит: Темный камень Терокка",{"Очистите темный камень Терокка в гнездовье Скит при помощи жезла очищения, после чего вернитесь к Киррику в караван беженцев в Костяных пустошах."}}
D[10840] = {"Гробница Света",{"Войдите в Гробницу Света и убейте там 10 эфириалов-пустомантов и 10 эфириалов-расхитителей, после чего вернитесь к верховному жрецу Орглуму в Караван беженцев."}}
D[10841] = {"Мстительный предвестник",{"[PH] Активировать устройство."}}
D[10842] = {"Мстительный предвестник",{"Установите могильную реликвию дренеев возле их древнего алтаря в Гробнице Света, как вам велел верховный жрец Орглум.","","Защитите стража гробниц и убейте мстительного предвестника. После завершения ритуала поговорите с дренеем-предком возле алтаря."}}
D[10843] = {"С незапамятных времен...",{"Чтобы получить признание Леорокса из Мок'Натала, убейте по его приказу Гноша Брогната, вождя огров, на заставе Камнерогов. По выполнении вернитесь к Леороксу в деревню Мок'Натал в Острогорье, или не возвращайтесь вовсе."}}
D[10844] = {"Лагерь Легиона: Злоба"}
D[10845] = {"Убить мать драконов",{"Леорокс посылает вас убить Жуткокрылижу. Вернитесь к нему в деревню Мок'Натал, как только умудритесь ее убить."}}
D[10846] = {"Как понять Мок'Натал",{"Чтобы начать понимать Мок'Натал, убейте Веха, предводителя араккоа из племени Вех'нир. Затем вернитесь к Леороксу в деревню Мок'Натал в Острогорье."}}
D[10847] = {"Глаза Скеттиса",{"Принесите Око Рескка и Око Шиенор Рилаку Освобожденному в Нижний город Шаттрата."}}
D[10848] = {"Гнездовье Рейз: неживое зло",{"Убейте 4 духа Когтя Смерти, 4 кричащих духа и 2 духа ворона, после чего вернитесь к Киррику в Караван беженцев."}}
D[10849] = {"Поиски Киррика",{"Отнесите послание Рилака Киррику в караван беженцев в Костяных пустошах."}}
D[10850] = {"Газ хаоса в двигателе",{"Вы находите ответстие, через которое в сквернобот загружается топливо."}}
D[10851] = {"Тотем врага моего",{"Добудьте 5 тотемов клана Камнерогов для вызывателя духов Догара из деревни Мок'Натал в Острогорье."}}
D[10852] = {"Пропавшие друзья",{"Найдите 12 друзей Итана в гнездовье Скит и вернитесь к нему в Караван беженцев."}}
D[10853] = {"Призыв духов",{"Вызыватель духов Догар просит вас при помощи тотемов вызова духов собрать 8 духов младших драконов Пустоты и принести ему в деревню Мок'Натал в Острогорье."}}
D[10854] = {"Силы Нельтараку",{"Освободите для Нельтараку 5 порабощенных драконов Крыльев Пустоты."}}
D[10855] = {"Сквернобот – нет, спасибо!",{"Заберите 5 единиц конденсированного газа Пустоты у ган'аргов-анжинеров на базе Легиона: Забвение, к северо-западу от Штормовой Вершины, и загрузите их в ближайший бездействующий сквернобот. После завершения задачи возвращайтесь к ловчему Пустоты Наутису."}}
D[10856] = {"Наилучшая защита",{"Ловчий Пустоты Наутис просит вас убить 12 вестников гнева на базе Легиона: Геенна к северу от Штормовой Вершины."}}
D[10857] = {"Телепортируй это!",{"Ловчий Пустоты Наутис просит вас применить жезл ментального вмешательства против мо'аргов, находящихся в лагере Легиона: Геенна и использовать их способность взорвать телепорт для того, чтобы уничтожить три телепорта в лагере Легиона."}}
D[10858] = {"Каринаку",{"Найдите Каринаку в крепости клана Драконьей Пасти."}}
D[10859] = {"Собрать шары",{"Вызыватель духов Дохгар просит вас при помощи тотема для собирания сфер собрать 15 световых сфер братства Разаани. По выполнении вернуться к нему в деревню Мок'Натал в Острогорье."}}
D[10860] = {"Лакомства Мок'Натал",{"Сестра Вара дает вам список продуктов для приготовления ее двух любимых блюд. В списке среди прочего 3 ребра ящера и 3 куска змеиного мяса. Принесите их ей в деревню Мок'Натал в Острогорье."}}
D[10861] = {"Гнездовье Литик: превентивный удар",{"Разбейте проклятые яйца в Гнездовье Литик. Освободите 3 птенцов и убейте 3 злобных птенцов, после чего вернитесь к Киррику в Караван беженцев."}}
D[10862] = {"Сдаться Орде",{"Найдите Рилака Освобожденного в Шаттрате и потребуйте, чтобы он и его народ сдались Орде, как велел вам Рокаг."}}
D[10863] = {"Тайны араккоа",{"Найдите Рилака Освобожденного в Шаттрате и попытайтесь выведать у него несколько секретов араккоа по просьбе леди Дены Кеннеди."}}
D[10864] = {"Урожай душ",{"Убейте 20 орков из клана Изувеченной Длани, затем возвращайтесь к аптекарю Антонивичу в Траллмар."}}
D[10865] = {"Доложить Леороксу!",{"Вызыватель духов Догар просит вас рассказать Леороксу о том, что затеяли эфириалы из лагеря Разаана. Его можно найти в деревне Мок'Натал в Острогорье."}}
D[10866] = {"Зулухед Измученный",{"Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку."}}
D[10867] = {"Ответ будет только один",{"Леорокс умоляет вас добыть собрание душ и передать их вызывателю духов Дохгару в деревню Мок'Натал в Острогорье."}}
D[10868] = {"Тропа войны араккоа",{"Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к советнице Файле в форт Камнеломов."}}
D[10869] = {"Уменьшить стаю",{"Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к лейтенанту Булыжному Молоту в бастион Аллерии."}}
D[10870] = {"Союзник Крыльев Пустоты",{"Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты."}}
D[10871] = {"Союзник Крыльев Пустоты",{"Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты."}}
D[10872] = {"Зулухед Измученный",{"Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку."}}
D[10873] = {"Захваченные в ночи",{"Пойдите на Гряду Паутины Пустоты и освободите там 6 опутанных воинов Ша'тар, после чего вернитесь к разведчику Наврину на заставу Ша'тар."}}
D[10874] = {"Гнездовье Шалас: сигнальные огни",{"Потушите четыре сигнальных огня в Гнездовье Шалас по просьбе Киррика, после чего вернитесь к нему в Караван беженцев."}}
D[10875] = {"Донесение Назгрелу",{"Поговорите с Назгрелом в Траллмаре."}}
D[10876] = {"Вступить в цитадель",{"Убейте командира соединения Горакса, положите на его труп Вызов Орды, убейте прислужника Каргата и принесите голову прислужника Каргата Назгрелу в Траллмар."}}
D[10877] = {"Реликвия Ужаса",{"Отыщите Реликвию Ужаса к востоку от Брошенного каравана, после чего вернитесь к Оакуну."}}
D[10878] = {"До наступления тьмы",{"Убейте 8 кабалистов-рыскателей, 4 кабалистов-чаропрядов и 2 кабалистов-посвященных, после чего вернитесь к Мекеде в Караван пустошей."}}
D[10879] = {"Нападение Скеттиса",{"Отбейте атаку, а потом поговорите с Рилаком."}}
D[10880] = {"Распоряжения заговорщиков",{"Принесите кабалистические приказы Мекеде в караван беженцев в лесу Тероккар."}}
D[10881] = {"Гробница Тени",{"Войдите в Гробницу Тени, что к западу от Каравана беженцев и найдите там пелерину Арунена, молот К'алена и свиток Аталора, после чего вернитесь к Мекеде в Караван беженцев."}}
D[10882] = {"Вестник Рока",{"Отправьтесь в спутник Крепости Бурь Аркатрац и убейте там предвестника Скайрисса, после чего вернитесь к А'далу на террасу Света в Шаттрат."}}
D[10883] = {"Ключ Урагана",{"Поговорите с А'далом в Шаттрате."}}
D[10884] = {"Испытание наару: милосердие",{"А'дал из Шаттрата просит добыть неиспользованный топор палача из Разрушенных залов цитадели Адского Пламени.","","Это задание выполняется только в героическом режиме."}}
D[10885] = {"Испытание наару: сила",{"А'дал из Шаттрата просит добыть трезубец Калитреша и сущность Бормотуна.","","Это задание выполняется только в героическом режиме."}}
D[10886] = {"Испытание наару: упорство",{"А'дал из Шаттрата просит спасти Милхауса Манашторма из Аркатраца, что в Крепости Бурь.","","Это задание выполняется только в героическом режиме."}}
D[10887] = {"Побег из гробницы",{"Помогите Акуно добраться до Каравана беженцев, после чего поговорите там с Мекедой."}}
D[10888] = {"Испытание наару: Магтеридон",{"А'дал из Шаттрата просит вас убить Магтеридона."}}
D[10889] = {"Обратно в Шаттрат",{"Доберитесь до Шаттрата и поговорите там с Рилаком."}}
D[10891] = {"Имперские латы",{"Поговорите с Деротайном Грязеглотом в Прибамбасске."}}
D[10892] = {"Имперские латы",{"Поговорите с Деротайном Грязеглотом в Прибамбасске."}}
D[10893] = {"За всем стоит Длиннохвостка",{"Устраните Драаку Длиннохвостку, предводительницу культистов Змея в туннеле Драконьего черепа. Когда сделаете дело, доложите дозорному Лунному Сумраку в туннеле Драконьего черепа в Острогорье."}}
D[10894] = {"Страж Драконьего черепа",{"Передайте записку о встрече дозорному Лунному Сумраку у входа в туннель Драконьего черепа в Острогорье."}}
D[10895] = {"Сжечь Зет'Гор!",{"Установите дымовые маяки у каждой из башен Зет'Гора и возвращайтесь к командиру звена Даби'ри в лагерь экспедиции."}}
D[10896] = {"Зараженные защитники",{"Убейте 25 лесных клещей и вернитесь к Лакотаю в Караван беженцев. Клещи живут в телах гниющих лесных гневней и зараженных корнеходов."}}
D[10897] = {"Мастер-изготовитель зелий",{"Отправляйтесь в Ботанику в Крепости Бурь и добудьте у старшего ботаника Фрейвинна \"Полевой справочник ботаника\". Принесите его Лоранне Тар'велл вместе с 5 отменными лечебными зельями, 5 отменными зельями маны и 5 большими зельями спокойного сна.","","<ВНИМАНИЕ!> Вы можете избрать только одну алхимическую специальность!"}}
D[10898] = {"Небокрыл",{"Проводите Небокрыла и вернитесь к Рилаку Освобожденному в Шаттрат."}}
D[10899] = {"Мастер трансмутации",{"Заревхи, находящийся Штормовой Вершине в Пустоверти просит вас принести ему 4 единицы изначальной мощи.","","ВНИМАНИЕ! Вы можете выбрать только одну алхимическую специализацию."}}
D[10900] = {"Медальон Вайш"}
D[10901] = {"Дубина Кардеша",{"Принесите печати земли и огня Скартису Еретику в Узилище (героический уровень сложности) в резервуар Кривого Клыка."}}
D[10902] = {"Мастер эликсиров",{"Отправляйтесь в Черные топи в Пещерах времени и добудьте 10 кристаллов сути бесконечности с повелителей и хранительниц временных разломов. Затем отнесите кристаллы, 5 хороших эликсиров защиты, 5 эликсиров власти и 5 хороших эликсиров ловкости Лорокиму в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде алхимии."}}
D[10903] = {"Возвращение в Оплот Чести",{"Поговорите с ассистентом Клату. Его можно найти в таверне Оплота Чести."}}
D[10904] = {"Боеприпасы Скверны",{"Друид из Вечной рощи просит вас принести ему 5 ядер пушек Скверны. По выполнении при помощи сигнального огня друидов призовите друида из Вечной рощи к Вратам Смерти в Острогорье."}}
D[10905] = {"Мастер зелий",{"Поговорите с Лоранной Тар'велл в Кенарийском приюте в Зангартопи.","","ВНИМАНИЕ! Вы можете выбрать лишь одно из направлений алхимии!"}}
D[10906] = {"Мастер эликсиров",{"Поговорите с Лорокимом из Нижнего города Шаттрата.","","ВНИМАНИЕ!Вы можете выбрать лишь одно из направлений алхимии!"}}
D[10907] = {"Мастер трансмутации",{"Поговорите с Заревхи из Штормовой Вершины Пустоверти.","","ВНИМАНИЕ!Вы можете выбрать лишь одно из направлений алхимии!"}}
D[10908] = {"Поговорите с Рилаком Освобожденным",{"Поговорите с Рилаком Освобожденным в Нижнем городе Шаттрата по просьбе Киррика Пробужденного."}}
D[10909] = {"Духи Скверны",{"Задействуйте по просьбе Клату из Оплота Чести реликвию анахорета на Заставе Горгаза, к юго-западу от Оплота Чести, и убивайте берсерков из клана Изувеченной Длани рядом с этой реликвией. После этого уничтожьте 10 освобожденных духов Скверны, чтобы отомстить за полковника Джулса."}}
D[10910] = {"Врата Смерти",{"Владыка леса Антеларион поручил вам отправиться к Вратам Смерти. Как только прибудете туда, воспользуйтесь сигнальным огнем друидов, чтобы призвать друида из Вечной рощи и поговорить с ним."}}
D[10911] = {"Открыть огонь!",{"Используйте боеприпасы, наполненные силой природы для установления контроля над пушками Скверны Врат Смерти. При помощи их разрушьте и северный, и южный порталы. Затем при помощи сигнального огня друидов призовите друида из Вечной рощи и доложите ему об успешном выполнении операции."}}
D[10912] = {"Псарь",{"Друид Вечной рощи говорит, что последнее, что вам надо сделать - это убить Балмона Псаря. Потом вернитесь в Вечную рощу в Острогорье и доложите об успехе Владыке леса Антелариону."}}
D[10913] = {"Недостойные похороны",{"Сожгите 8 убитых аукенайских воинов и 8 павших поборников Ша'тар по поручению командира Ра'ваджа. Командира можно найти на заставе Ша'тар в Костяных пустошах в лесу Тероккар."}}
D[10914] = {"Требуется герой",{"Убейте 12 аукенайских посвященных и 5 аукенайских прорицателей по поручению командира Ра'ваджа. Командира можно найти на заставе Ша'тар в Костяных пустошах в лесу Тероккар."}}
D[10915] = {"Падший экзарх",{"Уничтожьте содержимое аукенайского гроба по поручению командира Ра'ваджа. Командира можно найти на заставе Ша'тар в Костяных пустошах в лесу Тероккар."}}
D[10916] = {"Откопать благословенные четки",{"Разыщите дренейские четки и принесите их ассистенту Клату в Оплот Чести."}}
D[10917] = {"Затруднительное положение изгнанника",{"Принесите 30 перьев араккоа Векаксу в Нижний город Шаттрата."}}
D[10918] = {"Больше перьев"}
D[10919] = {"Собачья радость",{"Шар-Ик выжидающе на вас смотрит"}}
D[10920] = {"За павших",{"Убейте 20 жуткопалых черных вдов и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов."}}
D[10921] = {"Тероккарантул",{"Убейте Тероккарантула и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов."}}
D[10922] = {"Костяные раскопки",{"Проводите Летолла и его команду и защищайте их, пока они будут копать. После этого вернитесь к Дворфовитцу на заставу Ша'тар."}}
D[10923] = {"Зло приближается",{"Отнесите Реликвию Ужаса на Перекопанный курган, как вам велел Оакун. В круге убивайте аукенайских вестников смерти и прорицателей, пока не соберете 20 роковых черепов. Затем найдите круг призыва Призрачного Кургана, при помощи Реликвии Ужаса призовите Жутуса Проклятого, убейте его и вернитесь к Оакуну."}}
D[10924] = {"Кровная м... есть!",{"Принесите 8 фиалов крови прыгуаны-ловца Саб'аофу, находящемуся в Космовороте."}}
D[10925] = {"Зло приближается"}
D[10926] = {"Обратно в лагерь Ша'тар",{"Вернитесь в лагерь Ша'тар и поговорите с разведчиком Наврином по воздаятеля Хайлена."}}
D[10927] = {"Убийство пауков",{"Часовая Шепот Луны у туннеля между Зангартопью и Острогорьем просит вас убить 6 пещерных пауков и доложить о выполнении командиру Тень Небес в Сильванааре."}}
D[10928] = {"Убийство пауков",{"Рубака Грак у туннеля между Зангартопью и Острогорьем просит вас убить 6 пещерных пауков и сообщить о выполнении задания Тор'чанку в оплоте Громоборцев."}}
D[10929] = {"Барабанный бой",{"Принесите 8 трупов взрослых просеивателей костей Дворфовитцу в лагерь Ша'тар в Костяных пустошах."}}
D[10930] = {"Большой костяной червь",{"Принесите органы гигантского костяного червя Дворфовитцу в лагерь Ша'тар в Костяных пустошах.","","Заодно верните ему барабан Фампер."}}
D[10931] = {"Возвращение в Экзодар",{"Поговорите с Кедмосом в Экзодаре."}}
D[10932] = {"Возвращение в Экзодар",{"Поговорите с Кедмосом в Экзодаре."}}
D[10933] = {"Возвращение в Луносвет",{"Поговорите с Альдрэ из Луносвета."}}
D[10934] = {"Возвращение в Луносвет",{"Поговорите с Альдрэ из Луносвета."}}
D[10935] = {"Экзорцизм над полковником Джулсом",{"Поговорите с анахоретом Берада. Используйте благословенные четки, чтобы провести ритуал. После окончания ритуала поговорите со спасенным полковником Джулсом. Возвращайтесь к ассистенту Клату."}}
D[10936] = {"Тебя ищет Троллебой",{"Ассистент Клату сообщает, что вас искал командир армии Данат Троллебой. Поговорите с Данатом в казармах Оплота Чести на полуострове Адского Пламени."}}
D[10937] = {"Перемастерить мастера",{"Убейте военного инструктора Зурока, и как можно скорее. Это приказ боевого командира командира армии Даната Троллебоя. После выполнения задания возвращайтесь к Данату в Оплот Чести на полуострове Адского Пламени."}}
D[10938] = {"Колода карт Новолуния: Благословения",{"Принесите колоду Благословений на ярмарку Новолуния."}}
D[10939] = {"Колода карт Новолуния: Вихри",{"Принесите карты Вихрей на ярмарку Новолуния."}}
D[10940] = {"Колода карт Новолуния: Ярость",{"Принесите карты Ярости на ярмарку Новолуния."}}
D[10941] = {"Колода карт Новолуния: Безумие",{"Принесите колоду Безумия на ярмарку Новолуния."}}
D[10942] = {"Детская неделя",{"Дуньте в эльфийскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели."}}
D[10943] = {"Детская неделя",{"Продудите в дренейскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели."}}
D[10944] = {"Тайна под угрозой",{"Отправляйтесь в Клеть Стражницы в Долину Призрачной Луны и поговорите с Акамой."}}
D[10945] = {"Хч'уу и народ грибов",{"Отведите вашу подопечную Саландрию, в Спореггар в Зангартопь. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с Хч'уу."}}
D[10946] = {"Коварство Пеплоустов",{"Отправляйтесь в Крепость Бурь и, облачившись в клобук Пеплоуста, убейте Ал'ара. Затем возвращайтесь к Акаме в Долину Призрачной Луны."}}
D[10947] = {"Артефакт из прошлого",{"Отправляйтесь в пещеры Времени в Танарисе и вступите в битву за гору Хиджал. Сразите Лютого Хлада и принесите амулет из прошлого Акаме в долину Призрачной Луны."}}
D[10948] = {"Пленная душа",{"Отправляйтесь в Шаттрат и расскажите А'далу о просьбе Акамы."}}
D[10949] = {"Вход в Черный храм",{"Отправляйтесь ко входу в Черный храм в Долине Призрачной Луны и поговорите с Кси'ри."}}
D[10950] = {"Аукиндон и Ритуальный Круг",{"Отведите свою подопечную, сиротку Дорнаа, к камню встречи у Ритуального Круга в центра Аукиндона. Аукиндон находится в центре Костяных пустошей, что в лесу Тероккар. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом."}}
D[10951] = {"Путешествие к Темному порталу",{"Отведите свою подопечную, сиротку Саландрию, на Ступени Судьбы, к Темному порталу полуострова Адского Пламени. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом."}}
D[10952] = {"Путешествие к Темному порталу",{"Отведите свою подопечную, сиротку Дорнаа, на Ступени Судьбы, к Темному порталу полуострова Адского Пламени. Обязательно призовите Дорнаа, если по прибытии ее не будет рядом."}}
D[10953] = {"Путешествие к Трону Стихий",{"Отведите свою подопечную, сиротку Саландрию, к Трону Стихий в Награнд. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с повелительницей стихий Шарвак."}}
D[10954] = {"Джил находится в Небесном лагере!",{"Отведите свою подопечную, сиротку Дорнаа, в Небесный лагерь в Награнде. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом. Затем поговорите с Джилом."}}
D[10955] = {"Мортис Шелест Крыла",{"Найдите Мортиса Шелеста Крыла в Кенарийском оплоте в Зангартопи."}}
D[10956] = {"Трон наару",{"Отведите свою подопечную, сиротку Дорнаа, к О'росу, который находится у подножия Трона наару в Экзодаре. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.","","Не забывайте пользоваться картой, чтобы сориентироваться в столице."}}
D[10957] = {"Искупление Пеплоустов",{"Возвратите Акаме власть над его душой, сразив Тень Акамы в Черном храме. Затем возвращайтесь в провидцу Канеи."}}
D[10958] = {"Найти Пеплоустов",{"Найдите Служителей Смерти Акамы в Черном храме."}}
D[10959] = {"Судьба Предателя",{"Провидец Канеи хочет, чтобы вы сразили Иллидана в Черном храме."}}
D[10960] = {"Когда я вырасту...",{"Отведите свою подопечную, сиротку Саландрию, к наставникам паладинов на площадь Странников в Луносвет. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с леди Лиадрин, матриархом рыцарей крови.","","Не забывайте пользоваться картой, чтобы сориентироваться в городе, а найти наставников паладинов вам помогут стражи."}}
D[10961] = {"Зелье пробуждения",{"Принесите 10 топлянников, 10 древних лишайников и 10 цветков сияния грез Мортису Шелесту Крыла в Кенарийский оплот."}}
D[10962] = {"Время посетить Пещеры",{"Отведите свою подопечную, сиротку Дорнаа, к дракону на возвышении в центре пещер Времени, Заладорму. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.","","Купите ей игрушечного дракона у начальника снабжения Хранителей Времени, Алурми, в конце входного туннеля."}}
D[10963] = {"Время посетить Пещеры",{"Отведите свою подопечную, сиротку Саландрию, к дракону на возвышении в центре пещер Времени, Заладорму. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом.","","Купите ей игрушечного дракона у начальника снабжения Хранителей Времени, Алурми, у входа в туннель."}}
D[10964] = {"Пробуждение спящего",{"Разбудите Клинтара Странника Снов при помощи зелья Пробуждения. Когда он придет в себя, поговорите с ним."}}
D[10965] = {"Не просто сон",{"Охраняйте дух Клинтара Странника Снов, пока он будет собирать реликвии Авианы. Потом поговорите с хранителем снов Луросой."}}
D[10966] = {"Возвращение в приют",{"Отведите свою подопечную, сиротку Дорнаа, обратно в приют Шаттрата, вернув дренейскую детскую свистульку попечительнице сирот Миле в Нижнем Городе."}}
D[10967] = {"Возвращение в приют",{"Отведите свою подопечную обратно в приют Шаттрата, вернув эльфийскую детскую свистульку попечительнице сирот Миле в Нижнем Городе."}}
D[10968] = {"Зов предсказателя",{"Отведите свою подопечную, сиротку Дорнаа, к предсказателю Нобундо в Кристальный зал Экзодара. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.","","Не забывайте пользоваться картой, чтобы сориентироваться в городе."}}
D[10969] = {"В поисках Амира",{"Найдите командира Амира на заставе стражей Протектората."}}
D[10970] = {"Миссия милосердия",{"Раздобудьте ключ от найденной темницы Эфириума для командира Амира, находящегося на заставе стражей Протектората в Пустоверти."}}
D[10971] = {"Секреты Эфириума",{"Командир Амир, находящийся на заставе стражей Протектората в Пустоверти, просит вас принести ему бирки пленников Эфириума."}}
D[10972] = {"Каталог бирок пленников Эфириума",{"Мне нужно больше бирок, Монд. Мне удалось обнаружить, что это не просто способ составить каталог узников, но также указание на различные точки размещения!","","Когда шифр будет раскрыт, мы сможем точно узнать, где содержатся наши союзники, и освободить их с минимальными потерями."}}
D[10973] = {"Тысяча миров",{"Командир Амир, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы принесли ему 5 ключей от тюрьмы братства Эфириум."}}
D[10974] = {"Палаты стазиса Баш'ира",{"Используйте табличку-ключ Альфа Эфириума, чтобы открыть палату стазиса Альфа в Лагере Баш'ира в Острогорье.","","Предоставьте свидетельства из палаты Альфа проекции командира Амира в Лагере Баш'ира."}}
D[10975] = {"Очищение палат Баш'ира",{"Мы в безвыходном положении, Бахусий. Собранные тобой данные дают нам достаточно информации для того, чтобы спасти наших союзников, содержащихся в меньших тюрьмах Пустоверти, однако мы должны пойти дальше и изничтожить более крупную угрозу со стороны Братства Эфириум здесь, в лагере Баш'ира.","","Присоединись к сражению против Эфириума! Принеси мне ключи от тюрьмы Эфириума, и я сделаю для тебя ключи от палат стазиса Эфириума, чтобы можно было открыть палаты стазиса Баш'ира."}}
D[10976] = {"Знак короля нексуса",{"Проекция командира Амира, находящеяся в Лагере Баш'ира в Острогорье просит вас принести ему знак короля нексуса."}}
D[10977] = {"Палаты стазиса в Гробницах маны",{"Проекция командира Амира, находящаяся в лагере Баш'ира в Острогорье просит вас использовать ключ от палат стазиса Гробниц маны, чтобы открыть палату стазиса внутри Гробниц маны Аукиндона.","","Это задание можно выполнить только в режиме героической сложности."}}
D[10978] = {"Возвращение к Мортису Шелесту Крыла",{"Отнесите реликвии Авианы Мортису Шелесту Крыла в Кенарийский оплот в Зангартопи."}}
D[10979] = {"В Вечную рощу",{"Поговорите с Арторн Песней Ветра из Вечной рощи, что в Острогорье."}}
D[10980] = {"Книга Ворона",{"Усильте свое зрение при помощи ока летучего ската и камня Провидца и разглядите призраков сторонников культа Ворона. Отыщите на Вершине Смерча старейшину Сай'ккала и расспросите его про книгу Ворона. Затем возвращайтесь к Арторн Песне Ветра."}}
D[10981] = {"Личная палата принца Шаффара",{"Такое предложить могли лишь самые стойкие и закаленные в битвах, Тафгор. Если ты не боишься повстречаться с ужасами второй палаты стазиса в Гробницах Маны, я могу составить ключ. Принеси мне знак знак короля нексуса, и я это сделаю."}}
D[10982] = {"Око Харамада",{"Твои заслуги перед Протекторатом и Консорциумом поистину велики, Бахусий. Так что будет только правильно, если первый из наших ключей будет отдан тебе. Этим ключом ты в любое время можешь открыть личную палату стазиса Шаффара, не утратив при этом сам ключ.","","*Амир кивает.*","","Ключ неотъемлем и пребудет с тобой навечно."}}
D[10983] = {"Мог'дорг Мудрый",{"Сходите к Мог'доргу Мудрому, который живет на вершине башни в Острогорье, сразу за Кругом Крови."}}
D[10984] = {"Разговор с огром",{"Поговорите с огром по имени Грок в Нижнем городе Шаттрата."}}
D[10985] = {"Отвлекающий маневр",{"Убедитесь, что Акама и Майев вошли в Черный храм в Долине Призрачной Луны, после того как войска Кси'ри начнут отвлекающий маневр."}}
D[10986] = {"Небесные очи",{"Поговорите с дозорным Элайрой на Сумеречной гряде в Награнде."}}
D[10987] = {"Поймать скальную пустельгу",{"Поймайте дикую пустельгу при помощи специальной сети и принесите ее дозорному Элайре на Сумеречную гряду."}}
D[10988] = {"Вороньи камни",{"Соберите в Скеттисе 8 вороньих камней и принесите их Арторн Песне Ветра в Вечную рощу в Острогорье."}}
D[10989] = {"Мог'дорг Мудрый",{"Посетите Мог'дорга Мудрого на вершине башни, где стоит Фырк, прямо у Круга Крови в Острогорье."}}
D[10990] = {"Сущность орла",{"Одолейте стража Орла и добудьте у него сущность орла. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.","","Если вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым."}}
D[10991] = {"Сущность сокола",{"Одолейте стража Сокола и добудьте у него сущность сокола. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.","","Если вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым."}}
D[10992] = {"Сущность ястреба",{"Одолейте стража Ястреба и принесите сущность ястреба Арторне Песне Ветра в Вечную рощу."}}
D[10993] = {"Возвращение в Кенарийский оплот",{"Отнесите сверток Арторны Мортису Шелесту Крыла в Кенарийский оплот."}}
D[10994] = {"В поисках лунного камня",{"Принесите лунный камень реки Строптивой Мортису Шелесту Крыла в Кенарийский оплот."}}
D[10995] = {"У Груллока два черепа",{"Добудьте драконий череп Груллока и принесите его Мог'доргу Мудрому на башню Круга Крови в Острогорье."}}
D[10996] = {"Сундук с сокровищами Маггока",{"Добудьте сундук с сокровищами Маггока и доставьте его Мог'доргу Мудрому на башню в Круге Крови в Острогорье."}}
D[10997] = {"Даже у гроннов есть штандарты",{"Добудьте штандарт Слаага и доставьте его к Мог'доргу Мудрому на башню в Круге Крови в Острогорье."}}
D[10998] = {"Черно(книжн)ый бизнес",{"Добудьте гримуар Вимгола Зловещего. Отнесите его Мог'доргу Мудрому на башню в Круге Крови в Острогорье."}}
D[11000] = {"В сердце Разрушителя Душ",{"Добудьте душу Скуллока и принесит ее Мог'доргу Мудрому на вершину башни Круга Крови в Острогорье."}}
D[11001] = {"Изгнание бога-ворона",{"Убейте бога-ворона и возвращайтесь к Мортису Шелесту Крыла в Кенарийский оплот.","","Это задание выполняется в режиме героической сложности."}}
D[11002] = {"Падение Магтеридона",{"Доставьте голову Магтеридона командиру армии Данату Троллебою в Оплот Чести на полуострове Адского Пламени."}}
D[11003] = {"Падение Магтеридона",{"Доставьте голову Магтеридона Назгрелу в Траллмар на полуострове Адского Пламени."}}
D[11004] = {"Мир Теней",{"Проберитесь в Скеттис и добудьте 6 горстей теневой пыли с местных араккоа, после чего отнесите пыль Северину."}}
D[11005] = {"Тайны жрецов Когтя",{"Возьмите у Северина эликсир теней и с его помощью найдите и убейте жрецов Когтя: Ишааля, Скиззика и Зеллека в Скеттисе. После этого вернитесь к командиру Адарису."}}
D[11006] = {"Больше теневой пыли",{"Похоже, командир все же не бредил. Принесите мне еще пыли, и я приготовлю вам другой эликсир."}}
D[11007] = {"Кель'тас и зеленеющая сфера",{"Отнесите зеленеющую сферу А'далу в Шаттрат."}}
D[11008] = {"Огонь над Скеттисом",{"Найдите яйца чудовищных калири на верхушках домов Скеттиса и сбросьте на них взрывчатку Стражи Небес, после чего вернитесь к небесному сержанту Дорину."}}
D[11009] = {"Огрские небеса",{"Мог'дорг Мудрый просит, чтобы вы поговорили с Чу'а'лором в Огри'ла в Острогорье."}}
D[11010] = {"Бомбардировочный заход",{"Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес."}}
D[11011] = {"Вечная бдительность",{"Попросите у Мортиса Шелеста Крыла лунный камень Сущности."}}
D[11012] = {"Клятва в верности Крыльям Пустоты",{"Наши земли потеряны, наши дети похищены под покровом ночи, проданы в рабство, а то и того хуже...","","<Голос Морденая срывается.>","","Пора, мой соратник, пришло время все вернуть! Ты проявил себя как отважный воитель и к тому же отзывчив душою.","","Обещаешь ли ты помочь клану Крыльев Пустоты вернуть наши земли и восстановить наши дома? Клянешься ли ты поддерживать наше племя, пока род не будет продолжен? Поклянись, и мы начнем битву за наши дома и наших близких!"}}
D[11013] = {"В услужении у Иллидари",{"Отправляйтесь на кряж Крыльев Пустоты и доставьте докладные записки Иллидари властителю Мор'гору, в лагере Драконьей Пасти."}}
D[11014] = {"Задание десятника",{"Поговорите с надсмотрщиком Варкулом Дыханием Дракона в лагере клана Драконьей Пасти."}}
D[11015] = {"Кристаллы Крыльев Пустоты",{"Принесите 30 кристаллов Крыльев Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти."}}
D[11016] = {"Шкуры живодеров-пустокопов",{"Принесите 35 шкур живодеров-пустокопов из Копей Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти в долине Призрачной Луны."}}
D[11017] = {"Пыльца пустопраха",{"Принесите 40 порций пыльцы пустопраха надсмотрщику Варкулу Дыханию дракона в лагерь Драконьей Пасти."}}
D[11018] = {"Хаотитовая руда",{"Принесите 40 порций хаотитовой руды надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти в долине Призрачной Луны."}}
D[11019] = {"Друг в тылу врага",{"Не думай, что тебе придется встретиться с армией орков Скверны в одиночку.","","*В глазах Ярзила мерцают синие искры.*","","Так вот мы здесь с тобой, Шушуль. В любой услуге, которую ты сможешь оказать оркам Скверны, действуя во имя отвоевания земель Крыльев Пустоты, мы будем рядом, чтобы удостовериться, что все идет по нашему плану.","","Тебе надо вести себя осторожно и не привлекать к себе нежелательного внимания во время твоих акций саботажа."}}
D[11020] = {"Медленная смерть",{"Возьмите у Язрилла Наемника из долины Призрачной Луны баранину. Смешайте ее с порчеными железами и отравите 12 лагерей батраков из клана Драконьей Пасти."}}
D[11021] = {"Альманах Ишааля",{"Принесите альманах Ишааля небесному командиру Адарису к северу от Скеттиса."}}
D[11022] = {"Разговор с Мог'доргом",{"Поговорите с Мог'доргом Мудрым. Он находится на вершине башни на восточной стороне Круга Крови в Острогорье."}}
D[11023] = {"Еще разок задать им жару!",{"Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес."}}
D[11024] = {"Союзник в Нижнем Городе",{"Принесите альманах Ишааля Рилаку Освобожденному в Нижний Город Шаттрата."}}
D[11025] = {"Кристаллы",{"Чу'а'лор проучил вам добыть 5 осколков апексита. Принесите их ему в Огри'ла на вершинах Острогорья."}}
D[11026] = {"Гони демонов!",{"При помощи кристалла изгоните 15 демонов из лагеря Легиона: Гнев или Ужас в Острогорье."}}
D[11027] = {"Есть у тебя темная руна?"}
D[11028] = {"Оставшееся время",{"Расскажите небесному капитану Адарису о возвращении Терокка. Вы сможете найти его в лагере Черного Ветра в лесу Тероккар."}}
D[11029] = {"Потрепанная маскировка",{"Оденьтесь в потрепанный маскировочный костюм араккоа, возьмите книгу \"Кровная вражда\" у Сахаака и вернитесь к Хаззику."}}
D[11030] = {"Наш мальчик хочет быть следопытом Стражи Небес",{"Добудьте нестабильный настой Зверя."}}
D[11031] = {"Перестать быть верховным магом из Аметистового Ока"}
D[11032] = {"Перестать быть защитником из Аметистового Ока"}
D[11033] = {"Перестать быть убийцей из Аметистового Ока"}
D[11034] = {"Перестать быть исцелителем"}
D[11035] = {"Недружелюбные небеса",{"Верните Язриллу Наемнику в лагере Драконьей Пасти в долине Призрачной Луны 10 реликвий Крыльев Пустоты."}}
D[11036] = {"Еще один пункт долой!",{"Доставьте консервированные фрукты командующему ракетами Фюзеляжу в Зону 52."}}
D[11037] = {"Странное видение",{"Поговорите с ведущим ракетостроителем Фьюзеляжем в Зоне 52."}}
D[11038] = {"Помощь экзарху Орелису",{"Поговорите с экзархом Орелисом в Зоне 52."}}
D[11039] = {"Отчет патрону шпионов Талодиену",{"Доложитесь патрону шпионов Талодиену в Зоне 52."}}
D[11040] = {"Детали для ведущего ракетостроителя",{"Доставить запчасти Босси командующему ракетами Фюзеляжу в Зону 52."}}
D[11041] = {"Неоконченное дело",{"Убейте 10 надземных живодеров и Бараш Мать Стаи. По выполнении вернитесь к властителю Мор'гору в лагерь Драконьей Пасти."}}
D[11042] = {"Таинственное видение",{"Поговорите с ведущим ракетостроителем Фьюзеляжем в Зоне 52."}}
D[11043] = {"Усовершенствованный грифон",{"Поговорите с Брюнном Жаробородом в цитадели Громового Молота."}}
D[11044] = {"Страшные видения",{"Поговорите с командиром звена Нуаинном в цитадели Громового Молота."}}
D[11045] = {"Зорус Ревнитель",{"Поговорите с Зорусом Ревнителем в цитадели Громового Молота."}}
D[11046] = {"Главный аптекарь Хильдегард",{"Поговорите с главным аптекарем Хильдегард в деревне Призрачной Луны."}}
D[11047] = {"Просьба ученика",{"Поговорите с Дамой Буйногривой в деревне Призрачной Луны."}}
D[11048] = {"Рапорт Крогхана",{"Объясните кровавому стражу Галмоку в деревне Призрачной Луны, почему Крогхан не может явиться к нему."}}
D[11049] = {"Большая Охота",{"Найдите яйцо дракона Крыльев Пустоты для Язрилла Наемника, находящегося в лагере Драконьей Пасти, что в долине Призрачной Луны."}}
D[11050] = {"Собрать их все!",{"Мы не хотим, чтобы драконьи яйца попали в чужие руки, Фоммаа. Принеси мне все, сколько сможешь найти.","","Только по возможности тихо и не привлекая к себе внимания."}}
D[11051] = {"Демонов – долой!",{"При помощи кристалла изгоните 15 демонов из лагеря Легиона: Гнев или Ужас в Острогорье."}}
D[11052] = {"Обещание Акамы",{"Принесите медальон Карабора А'далу в Шаттрат."}}
D[11053] = {"Новое назначение",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11054] = {"Ты – инспектор: как делать все правильно",{"Принесите 10 кусков узловатой кожи и прочную шкуру Тирантия надзирателю Грязевику в лагерь Драконьей Пасти в долине Призрачной Луны."}}
D[11055] = {"Ботиранг: лекарство для нерадивых батраков",{"Призовите к порядку 20 ленивых батраков в лагере Драконьей Пасти. Ботиранг нужно будет вернуть надзирателю Грязевику."}}
D[11056] = {"Просьба Хаззика",{"Заберите сверток Хаззика из его дома в восточном Скеттисе и верните сверток хозяину."}}
D[11057] = {"Огрское подполье",{"Чу'а'лор просит вас поговорить с Мог'доргом Мудрым на вершине одной из башен рядом с Кругом Крови в Острогорье."}}
D[11058] = {"Апекситовая реликвия",{"Получите вибрации Апекса от апекситовой реликвии."}}
D[11059] = {"Страж монумента",{"Принесите голову стража апекситов."}}
D[11060] = {"Кристалл с темными рунами"}
D[11061] = {"Отцовский долг",{"Добудьте нестабильный настой волшебника."}}
D[11062] = {"Застава Стражи Небес",{"Поговорите с небесным командиром Келлером на заставе Стражи Небес на вершинах Острогорья."}}
D[11063] = {"Заработай крылья",{"Так ты хочешь примкнуть к усмирителям небес? Ты неплохо себя показал в клане Драконьей Пасти, но это ничего не значит тут, в небесах Запределья. Вопрос в том, умеешь ли ты летать?","","Полет – это не просто взгромоздиться на спину дракону Пустоты и отвезти в форт партию кристаллов, с этим-то любой дурак справится. Полет – это быть лучшим, первым среди орков.","","К западу отсюда есть шесть пилотов, победи их всех – и я пожалую тебе крылья усмирителя небес."}}
D[11064] = {"Гонки Драконьей Пасти: баллада о старине Макстаре",{"Следуйте за \"Стариной\" Маргом Сквернословом, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11065] = {"Ловим летучих скатов!",{"Поймайте 5 летучих скатов при помощи веревочного аркана."}}
D[11066] = {"Нам нужно больше летучих скатов!",{"Поймайте 5 летучих скатов при помощи веревочного аркана."}}
D[11067] = {"Гонки Драконьей Пасти: Троп Смраднорыг",{"Следуйте за Тропом Смраднорыгом, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11068] = {"Гонки Драконьей Пасти: Корлок Ветеринар",{"Следуйте за Корлоком Ветеринаром, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11069] = {"Гонки Драконьей Пасти: командир звена Ромеон",{"Следуйте за командиром звена Ромеоном, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11070] = {"Гонки Драконьей Пасти: командир звена Маэстр",{"Следуйте за командиром звена Маэстром, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11071] = {"Гонки Драконьей Пасти: капитан Небокрушитель",{"Следуйте за капитаном Небокрушителем, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11072] = {"Кровные враги",{"Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттика, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра."}}
D[11073] = {"Падение Терокка",{"Возьмите приготовленное Хаззиком Подношение Затерянного во Времени и отнесите его к груде черепов в центре Скеттиса. С помощью подношения призовите Терокка и сразитесь с ним, после чего вернитесь к небесному командиру Адарису."}}
D[11074] = {"Кровные враги",{"Добудьте у затерянных во времени араккоа их свитки и отнесите их к груде черепов в центре круга призыва в Скеттисе. Вызовите и победите потомков врагов Терокка, после чего отнесите Хаззику коготь Аккарая, хребет Гарокка, чешую Векказа и коготь Геззарака."}}
D[11075] = {"Копи Крыльев Пустоты",{"Найдите Госпожу Копей на Кряже Крыльев Пустоты."}}
D[11076] = {"Собрать по кусочкам...",{"Соберите для Госпожи Копей груз 15 тачек в Долине Призрачной Луны."}}
D[11077] = {"Драконы – это не самое страшное",{"Убейте 15 живодеров-пустокопов и 5 опустошителей-пустокопов из Копей Пустоты для штейгера из клана Драконьей Пасти."}}
D[11078] = {"В небесах останется только один!",{"Добудьте драконьи зубы."}}
D[11079] = {"Бич Скверны для Гахка",{"Добудьте бич Скверны."}}
D[11080] = {"Излучение реликвии",{"Испытайте на себе излучение от апекситовой реликвии."}}
D[11081] = {"Восстание в племени Темной Крови",{"Отнесите планы побега племени Темной Крови Госпоже Копей."}}
D[11082] = {"В поисках правды",{"Найдите надзирателя из племени Темной Крови и допросите его. Вернитесь к Госпоже Копей с информацией об организаторе побега и рукой надзирателя."}}
D[11083] = {"Спятившие и очень опасные...",{"Убейте для Ронага Деспота из копей Крыльев Пустоты безумного штейгера и 5 шахтеров племени Темной Крови."}}
D[11084] = {"Стой прямо, капитан!",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11085] = {"Побег из Скеттиса",{"Проводите плененного Стража Небес в безопасное место, а затем доложите небесному сержанту Дорину."}}
D[11086] = {"Разрушение сумеречного портала",{"По поручению властителя Мор'гора из лагеря Драконьей Пасти в долине Призрачной Луны убейте 20 посланников Смертной Тени."}}
D[11089] = {"Пушка души Рет'хедрона",{"Принесите повелителю Иллидари Балтазу, находящемуся в лагере Драконьей Пасти, 2 слитка оскверненной стали, 1 адамантитовую рамку, 1 кориевый сердечник и 1 безупречную чародейскую сущность."}}
D[11090] = {"Покорить Покорителя",{"Используйте Пушку Души против Рет'хедрона Покорителя в Награнде. Потом верните Пушку Души повелителю Иллидари Балтазу в лагерь Драконьей Пасти, в долине Призрачной Луны."}}
D[11091] = {"Особая благодарность",{"Чу'а'лор предлагает вам поговорить с Джо'нассом в Огри'ла на вершинах Острогорья."}}
D[11092] = {"Приветствую тебя, Командир!",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11093] = {"Пропитание для скатов Пустоты",{"Возьмите клетку для скатов Пустоты в лес к югу от лагеря Черного Ветра и убейте прыгуан-ловцов долины Черного Ветра около голодного ската Пустоты. После этого вернитесь к укротителю Диисаку из Стражи Небес."}}
D[11094] = {"Всех убей, один останься!",{"Доставьте информацию о вашей новой миссии вместе со сигнальным ружьем чародею Тэлису в Святилище Звезд."}}
D[11095] = {"Командир Хобб",{"Отдайте сигнальную ракету клана Драконьей Пасти командиру Хоббу, стоящему у Святилища Звезд в долине Призрачной Луны."}}
D[11096] = {"Атака с воздуха",{"Убейте 20 любых огров из клана Гордунни в Защитных холмах, после чего вернитесь к Юуле в Шаттрат."}}
D[11097] = {"Самая опасная ловушка",{"Помогите Командиру Хоббу защитить Святилище Звезд. Когда войска Драконьей Пасти будут разгромлены, вернитесь к властителю Мор'гору в лагерь Драконьей Пасти с медалями Провидцев."}}
D[11098] = {"В Скеттис!",{"Отнесите упаковку взрывчатки сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом."}}
D[11099] = {"Всех убей, один останься!",{"Доставьте информацию о вашей новой миссии вместе с сигнальным ружьем анахорету Сейле к алтарю Ша'тар."}}
D[11100] = {"Командир Аркус",{"Отдайте сигнальную ракету клана Драконьей Пасти командиру Аркусу у алтаря Ша'тар."}}
D[11101] = {"Самая Опасная Ловушка",{"Помогите Командиру Аркусу защитить алтарь Ша'тар. Когда войска клана Драконьей Пасти будут разгромлены, вернитесь к властителю Мор'гору в лагерь Драконьей Пасти с медалями Алдоров."}}
D[11102] = {"Бомбардировочный заход",{"Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес."}}
D[11103] = {"Отказ мудреца"}
D[11104] = {"Перестать быть исцелителем"}
D[11105] = {"Отказ героя"}
D[11106] = {"Отказ защитника"}
D[11107] = {"Склонитесь перед верховным господином",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11108] = {"Владыка Иллидан Ярость Бури",{"Встретьтесь с Иллиданом Яростью Бури. Найдите Бартамуса в Нижнем Городе Шаттрата, если останетесь в живых."}}
D[11109] = {"Кобальтовый дракон Пустоты Хорус",{"Познакомиться с тобой, Медоке, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.","","Если Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.","","Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить."}}
D[11110] = {"Лиловый дракон Пустоты Малфас",{"Познакомиться с тобой, Гностикмаг, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.","","Если Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.","","Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить."}}
D[11111] = {"Ониксовый дракон Пустоты Ониксиен",{"Познакомиться с тобой, Фоммаа, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.","","Если Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.","","Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить."}}
D[11112] = {"Лазурный дракон Пустоты Сураку",{"Познакомиться с тобой, Амат, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.","","Если Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.","","Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить."}}
D[11113] = {"Пурпурный дракон Пустоты Воранаку",{"Познакомиться с тобой, Йша, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.","","Если ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.","","Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить."}}
D[11114] = {"Зои, изумрудный дракон Пустоты",{"Познакомиться с тобой, Алаверды, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты сделал для племени Крыльев Пустоты.","","Если ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.","","Но ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить."}}
D[11117] = {"Поймать дикого зайцелопа!",{"Глодрак Меткий Охотник попросил вас поймать 5 оглушенных летучих зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения."}}
D[11118] = {"Розовые элекки на марше",{"Отправляйтесь в пивные сады рядом с Штормградом, Дарнассом и Экзодаром, истребите по три элекка в каждом из мест и возвращайтесь к Глодраку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться."}}
D[11119] = {"Налет на Лагерь Баш'ира!",{"Поговорите с учеником эфир-теха на заставе Стражи Небес в Острогорье."}}
D[11120] = {"Розовые элекки на марше",{"Отправляйтесь в пивные сады рядом с Луносветом, Громовым Утесом и Подгородом, истребите по три элекка в каждом из них и возвращайтесь к Глодраку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться."}}
D[11122] = {"Туда и обратно",{"Возьмите бочку у Флинна Огневара в Караносе и доставьте ее Полу Янтарлену. Если баран сбежит от вас, возьмите еще одного у Нейла Рамштайна."}}
D[11123] = {"Исследование пепелища",{"Поговорите с инспектором Таремом у трактира \"Последний привал\"."}}
D[11124] = {"Исследование пепелища",{"Поговорите с инспектором Таремом у трактира \"Последний привал\"."}}
D[11126] = {"Чужой среди своих",{"Прогоните 5 дезертиров-подстрекателей и вернитесь к докам Терамора к Калии Гастингс."}}
D[11128] = {"Пропагандистская война",{"Доставьте дезертирскую пропаганду Калии Гастингс к докам в Тераморе."}}
D[11129] = {"Пропал Кайл!",{"Анаб Пшеничная Грива из деревни Кровавого Копыта в Мулгоре попросил найти его лучшего щенка, Кайла Бесноватого.","","Покормите Кайла нежным мясом долгонога и возвращайтесь к Анабу Пшеничной Гриве."}}
D[11130] = {"Ой, блестяшечки!",{"Жуль хочет, чтобы вы взяли его записку и отнесли ее Бадду в Призрачные земли к Зул'Аману."}}
D[11131] = {"Гаси пожар!",{"Переодетая попечительница сирот просит вас помочь потушить пожар в деревне. Когда пожар будет потушен, снова поговорите с попечительницей сирот."}}
D[11132] = {"Все обещаешь и обещаешь",{"Разыщите карту Бадда Недрека на террасе верховного шамана Налоракка в Зул'Амане и верните ее хозяину."}}
D[11133] = {"Дискредитация вражеской агентуры",{"Калия Гастингс просит вас подбросить листовки с изменениями 6 тераморским стражникам. Затем вернитесь к докам Терамора и доложите Калии о выполнении."}}
D[11134] = {"Конец вражеской пропаганде",{"Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора."}}
D[11135] = {"Всадник без головы",{"Найдите святилище тыквы Всадника без головы."}}
D[11136] = {"Тревожные события",{"Поговорите с капитаном Ваймором на Сторожевом посту."}}
D[11137] = {"Братство Справедливости в Пылевых топях?",{"Добудьте приказы Братства Справедливости у Гарна Маферса и принесите его капитану Ваймору на Сторожевой пост."}}
D[11138] = {"Ренн Макгилл",{"Отнесите приказы Братства Справедливости Ренну Макгиллу. Он плавает недалеко от Зловещего берега."}}
D[11139] = {"Старое водолазное снаряжение",{"Принесите набор инструментов и испорченное водолазное снаряжение Ренну Макгиллу в Пылевые топи."}}
D[11140] = {"Вернуть груз!",{"Принесите 6 поднятых со дна сундуков Ренну Макгиллу в Пылевые топи."}}
D[11141] = {"Джайна должна быть в курсе",{"Поговорите с леди Джайной Праудмур в Тераморе."}}
D[11142] = {"Исследование острова Алькац",{"Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе."}}
D[11143] = {"Мрачные выводы",{"Доложитесь капитану Дариллу в Северной башне."}}
D[11144] = {"Подтвержденные подозрения",{"Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню."}}
D[11145] = {"Пленники Зловещего Тотема",{"Сержант Лукас из Северной башни просит вас спасти 5 тераморских пленников."}}
D[11146] = {"Ловец ящеров",{"Сержант Лукас из Северной башни просит вас поймать 6 ящеров. Вы можете ловить как ящеров Кровавой Топи, так и крикунов Кровавой Топи."}}
D[11147] = {"Боевые ящеры",{"Сержант Лукас из Северной башни хочет, чтобы вы положили приманку на ящера близ ветряной мельницы в деревне Черного Копыта."}}
D[11148] = {"Оружие племени Зловещего Тотема",{"По просьбе капитана Дарилла из Северной башни принесите ему 7 предметов вооружения из деревни Черного Копыта."}}
D[11149] = {"Помощь Табеты",{"Поговорите с Табетой в ее доме."}}
D[11150] = {"Уничтожение заставы Дикого Рога",{"Сожгите северную, восточную и северо-восточную палатки на заставе Дикого Рога, затем вернитесь в усадьбу Табеты."}}
D[11151] = {"Справедливая месть за Хьялей",{"Поговорите с капитаном Гарраном Ваймсом в цитадели в Тераморе."}}
D[11152] = {"Обрести покой",{"По просьбе капитана Гаррана Ваймса из цитадели возложите венок к памятнику семейства Хьяль."}}
D[11156] = {"Налетчики Дикого Рога",{"Убейте 12 тауренов из племени Зловещего Тотема с заставы Дикого Рога и вернитесь к ученику Морланну в усадьбу Табеты."}}
D[11158] = {"Перья Кровавой Топи",{"Принесите 5 перьев Кровавой Топи Броггу в Шестермуть."}}
D[11159] = {"Духи в руинах деревни Каменного Молота",{"Брогг из Шестермути просит вас дать покой 10 духам клана Каменного Молота."}}
D[11160] = {"Знамя Каменного Молота",{"Добудьте знамя Каменного Молота и принесите его Броггу в Шестермуть."}}
D[11161] = {"Сущность вражды",{"Принесите 10 сущностей черного дракона Броггу в Шестермуть."}}
D[11162] = {"Бросить вызов черным драконам",{"Установите знамя Каменного Молота у входа в Логово Ониксии, затем вернитесь к Броггу в Шестермуть."}}
D[11163] = {"Тайная Сестрица",{"Доберитесь до Донны Браско, чтобы получить причитающуюся вам награду. Найти Донну можно на Призрачных Землях, сразу за окраиной Зул'Амана."}}
D[11164] = {"Клыкастые всадники",{"Соберите для Пригмона 10 клыков лесных троллей в Зул'Амане и принесите их ему в лагерь Бадда в Призрачных Землях."}}
D[11165] = {"Тролль в стане троллей",{"Найдите Зунгама и помогите ему выбраться из Зул'Амана."}}
D[11166] = {"Крестом на карте обозначена... твоя смерть!",{"Отправляйтесь в Зул'Аман и посетите чертог Халаззи, платформу Джан'алая и платформу Акил'зона. Заметьте все подробности и по возвращении доложите о них Бадду в его лагере в Призрачных землях."}}
D[11169] = {"Оружие племени Зловещего Тотема",{"Ученик Гарион из усадьбы Табеты хочет, чтобы вы испытали захваченный тотем на 10 крапчатых кроколисках-грязекупах или грязекупах-острозубах."}}
D[11171] = {"Повелитель Проклятий? Пффф!",{"Убейте в Зул'Амане повелителя проклятий Малакрасса и вернитесь к Бадду Недреку на Холмы Томагавков."}}
D[11172] = {"Крушение дирижабля",{"Поговорите с Мокси Сталегриль на месте крушения дирижабля Бизила."}}
D[11173] = {"Подмена реактива",{"Принесите 6 флаконов болотного яда ученику Гариону в усадьбу Табеты."}}
D[11174] = {"Профилактика коррозии",{"Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила."}}
D[11177] = {"Отшельник из сторожки \"Болотный огонек\"",{"Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\"."}}
D[11178] = {"Кровь Вождя",{"Принесите кровь Зул'джина Бадду в его лагерь в Призрачных Землях. За пределами Зул'Амана."}}
D[11180] = {"Что таится на Ведьмином холме?",{"Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы добыли информацию у 10 восставших мертвецов или духов."}}
D[11181] = {"Ведьмина погибель",{"Принесите 9 кустиков ведьминой погибели Морганту Мрачнику в сторожку \"Болотный огонек\"."}}
D[11183] = {"Очищение Ведьминого холма",{"Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы установили факел в конце дока и сразились с тем, что выйдет на свет."}}
D[11184] = {"Разыскивается: Кровокоготь Ненасытный",{"Уничтожьте Кровокогтя Ненасытного и сообщите об этом Драззиту Кранотеку, который находится в Шестермути."}}
D[11185] = {"Письмо аптекаря",{"Отнесите запечатанное письмо привратнику Анделло в усадьбу Табеты."}}
D[11186] = {"Свидетельство предательства?",{"Доставьте запечатанное письмо Назиру Кровавому Копью в Деревню Гиблотопь."}}
D[11191] = {"Этот старый маяк",{"Поговорите с Бабс Шипокруткой на маяке на острове к востоку от Терамора."}}
D[11192] = {"Жир крепкозуба",{"Принесите 4 контейнера жира крепкозуба Бабс Шипокрутке на маяк близ Терамора."}}
D[11193] = {"Подлые обитатели глубин",{"Отнесите книгу \"Подлые обитатели глубин\" в доки Терамора и отдайте \"Весельчаку\" Ленни Полечуду."}}
D[11194] = {"Так это правда?",{"Поговрите с Натом Пэглом в лагере Ната в Заливе Яростных Волн."}}
D[11195] = {"Игра в куклы",{"Отнесите потрепанную куклу вуду Жулю в Шаттрат."}}
D[11196] = {"Вождь Амани",{"Победите нового вождя племени Амани, Даакару."}}
D[11198] = {"Сразить Тетура!",{"Майор Миллз из доков Терамора хочет, чтобы вы покончили с Тетуром."}}
D[11200] = {"Не просто совпадение",{"Крог из Деревни Гиблотопь хочет, чтобы вы принесли ему 7 предметов оружия Черного Копыта."}}
D[11201] = {"Замысел племени Зловещего Тотема",{"Принесите боевые планы племени Зловещего Тотема Крогу в деревню Гиблотопь."}}
D[11203] = {"Найти Табету",{"Поговорите с Табетой в ее доме на Трясине."}}
D[11204] = {"Возвращение к Крогу",{"Поговорите с Крогом в деревне Гиблотопь."}}
D[11205] = {"Уничтожение заставы Дикого Рога",{"Сожгите северную, восточную и северо-восточную палатки на заставе Дикого Рога, а затем вернитесь к Табете в ее усадьбу."}}
D[11206] = {"Акт правосудия",{"Вернитесь к Крогу в деревню Гиблотопь."}}
D[11207] = {"Защитить груз!",{"Мокси Сталегриль попросила вас собрать 8 контейнеров груза с дирижабля и принести ей на место крушения Бизиля."}}
D[11208] = {"Поставка для Драззита",{"Доставьте груз с дирижабля Драззиту Кранотеку в Шестермуть."}}
D[11209] = {"Сделка Ната",{"Нат Пэгл из лагеря Ната хочет, чтобы вы испытали его новую наживку для рыбы."}}
D[11210] = {"Он настоящий!",{"Поговорите с майором Миллзом в доках Терамора."}}
D[11211] = {"Помощь деревне Шестермуть",{"Поговорите с Драззитом Кранотеком в Шестермути."}}
D[11212] = {"Ферма Табеты",{"Поговорите с Табетой в ее доме на Трясине."}}
D[11213] = {"Навестить Табету",{"Поговорите с Табетой в ее усадьбе на Трясине."}}
D[11214] = {"Миссия в Шестермуть",{"Поговорите с Драззитом Кранотеком в Шестермути."}}
D[11215] = {"Помощь Шестермути",{"Поговорите с Драззитом Кранотеком в Шестермути."}}
D[11216] = {"Верховный маг Альтур",{"Поговорите с верховным магом Альтуром близ Каражана на перевале Мертвого Ветра."}}
D[11217] = {"Тяни змею за хвост!",{"Гиззикс Грязебульк из Шестермути проист принести ему 8 стеблей змеехвостки."}}
D[11219] = {"Гаси пожар!",{"Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в маске в городе."}}
D[11220] = {"Всадник без головы",{"Найдите святилище тыквы Всадника без головы."}}
D[11222] = {"Предупредить Болвара!",{"Поговорите с верховным лордом Болваром Фордрагоном в Крепости Штормграда."}}
D[11223] = {"Возвращение к Джайне",{"Поговорите в Тераморе с леди Джайной Праудмур."}}
D[11225] = {"Отшельник с Ведьминого холма",{"Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\"."}}
D[11242] = {"Наконец, свободен!",{"Возьмите книгу Томаса Томсона и отнесите ее переодетой попечительнице сирот в Златоземье, Каранос или на Лазурную заставу."}}
D[11293] = {"Пивоварня Ячменоваров ищет зазывалу!",{"Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах Войны, в Зале Исследователей и в Палатах Магии."}}
D[11294] = {"Пивоварня Громоваров ищет зазывалу!",{"Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах Войны, в Зале Исследователей и в Палатах Магии."}}
D[11318] = {"А теперь гонки на баранах... Или вроде того.",{"У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд."}}
D[11321] = {"Кто сказал \"сувениры\"?",{"Отоварьте свой купон на праздничную кружку у Белби Быстросмен в лагере Хмельного фестиваля."}}
D[11335] = {"Призыв к оружию: низина Арати",{"Победите на поле боя Низины Арати и вернитесь к бригадному генералу сил Альянса в любую из столиц Альянса или в Шаттрат."}}
D[11336] = {"Призыв к оружию: Альтеракская долина",{"Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу сил Альянса в любую из столиц Альянса или в Шаттрат."}}
D[11337] = {"Призыв к оружию: Око Бури",{"Победите в игре на поле боя Ока Бури и вернитесь к бригадному генералу сил Альянса в любую из столиц Альянса или в Шаттрат."}}
D[11338] = {"Призыв к оружию: ущелье Песни Войны",{"Одержите победу в ущелье Песни Войны и вернитесь к бригадному генералу сил Альянса в любую из столиц Альянса или в Шаттрат."}}
D[11339] = {"Призыв к оружию: низина Арати",{"Победите в игре на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды или в Шаттрат."}}
D[11340] = {"Призыв к оружию: Альтеракская долина",{"Победите в игре на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды или в Шаттрат."}}
D[11341] = {"Призыв к оружию: Око Бури",{"Победите в игре на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды или в Шаттрат."}}
D[11342] = {"Призыв к оружию: ущелье Песни Войны",{"Одержите победу в ущелье Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды или в Шаттрат."}}
D[11354] = {"Разыскивается: Ездовой хлыстик Назана",{"Торговец ветром Зарим просит вас добыть ездовой хлыст Назана. Доставьте его ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11356] = {"Переодетая попечительница сирот",{"Поговорите с переодетой попечительницей сирот в Златоземье, Караносе или на Лазурной заставе."}}
D[11357] = {"Попечительница сирот в маске",{"Поговорите с попечительницей сирот в маске в Колючем Холме, Брилле или на площади Соколиных Крыльев."}}
D[11360] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот."}}
D[11361] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Колючем Холме."}}
D[11362] = {"Разыскивается: Украшенный перьями посох Кели'дана",{"Торговец ветром Зарим просит вас добыть украшенный перьями посох Кели'дана. Принесите его ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11363] = {"Разыскивается: печать Острорука",{"Торговец ветром Зарим просит вас добыть печать Острорука. Принесите ее ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11364] = {"Разыскиваются: Центурионы клана Изувеченной Длани",{"Ловчий Пустоты Ма'дуун поручает вам убить 4 центурионов из клана Изувеченной Длани. Вернитесь к нему в Нижний город Шаттрата за наградой, как только перебьете их всех."}}
D[11368] = {"Разыскивается: сердце Квагмирран",{"Добудьте сердце Зыбуна и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение.","","Задание можно выполнить только в героическом режиме."}}
D[11369] = {"Разыскивается: яйцо Черной Охотницы",{"Добудьте яйцо Черной Охотницы и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение.","","Задание можно выполнить только в героическом режиме."}}
D[11370] = {"Требуется: трактат полководца",{"Добудьте трактат полководца и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение.","","Задание можно выполнить только в героическом режиме."}}
D[11371] = {"Разыскиваются: Мирмидоны Резервуара Кривого Клыка",{"Ловчий Пустоты Ма'дуун требует, чтобы вы убили 14 мирмидонов из резервуара Кривого Клыка. По исполнению задания возвращайтесь к Ма'дууну в Нижний город Шаттрата за вознаграждением."}}
D[11372] = {"Разыскиваются: головные перья Айкисса",{"Добудьте перья с головы Айкисса и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11373] = {"Разыскивается: Заговоренный Амулет Шаффара",{"Добудьте заговоренный амулет Шаффара и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11374] = {"Разыскивается: Самоцвет души Экзарха",{"Добудьте самоцвет души экзарха и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11375] = {"Разыскивается: Шепот Бормотуна",{"Добудьте шепот Бормотуна и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11376] = {"Разыскиваются: Злобные инструкторы.",{"Убейте для ловчего Пустоты Ма'дууна 3 злобных инструкторов, по выполнении вернитесь к нему в Нижний город Шаттрата, чтобы получить свою награду."}}
D[11377] = {"Месть сладка",{"Скалл из Нижнего города просит вас приготовить похлебку из калири в его кухонном котелке. По выполнении вернитесь к нему."}}
D[11378] = {"Разыскивается: Голова Охотника Вечности",{"Торговец ветром Зарим просит вас добыть голову Охотника Вечности. Доставьте ее в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11379] = {"Очень горячая похлебка",{"Скалл из Нижнего города просит вас приготовить немного невероятной демонической похлебки в его кухонном котелке. Вернитесь, когда приготовите."}}
D[11380] = {"Мания",{"Скалл из Нижнего города просит вас принести 15 манаягод из заповедников Пустоверти."}}
D[11381] = {"Супчик для души",{"Скалл из Нижнего города просит вас приготовить суп предков в его кухонном котелке. По выполнении вернитесь к нему."}}
D[11382] = {"Разыскиваются: песочные часы Эонуса",{"Торговец ветром Зарим просит вас добыть песочные часы Эонуса. Доставьте их в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11383] = {"Разыскиваются: Повелители временных разломов",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 4 повелителей временных разломов. Вернитесь к нему в Нижний город Шаттрата за наградой, когда они будут убиты."}}
D[11384] = {"Разыскивается: Отросток Узлодревня",{"Торговец ветром Зарим просит вас добыть отросток Узлодревня. Доставьте его ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11385] = {"Разыскиваются: Солнцеловы-чаротворцы",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 6 солнцеловов-чаротворцев. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду."}}
D[11386] = {"Разыскивается: Проектор Паталеона",{"Торговец ветром Зарим просит вас добыть проектор Паталеона. Доставьте его в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11387] = {"Разыскиваются: разрушители из кузни бурь",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы уничтожили 5 разрушителей из кузни бурь. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду."}}
D[11388] = {"Разыскивается: Свиток Скайрисса",{"Торговец ветром Зарим просит вас добыть свиток Скайрисса. Доставьте его в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11389] = {"Разыскиваются: Часовые Аркатраца",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы навсегда деактивировали 5 часовых Аркатраца. Вернитесь к нему в Нижний город Шаттрата, когда выполните задание, чтобы забрать награду."}}
D[11392] = {"Вызов Всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11400] = {"Скаковые бараны Хмельного фестиваля",{"Покажите штамп Полу Янтарлену у входа на территорию Хмельного фестиваля в Дун Мороге."}}
D[11401] = {"Вызов всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11403] = {"Наконец, свободен!",{"Возьмите книгу Томаса Томсона и отнесите ее попечительнице сирот в маске в Дуротар, Брилл или на Площадь Соколиных Крыльев."}}
D[11404] = {"Вызов Всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11405] = {"Вызов Всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11407] = {"Пивоварня Дрона ищет зазывалу!",{"Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов."}}
D[11408] = {"Пивоварня Т'чали Вуду ищет зазывалу!",{"Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов."}}
D[11409] = {"А теперь гонки на баранах... Или вроде того.",{"У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд."}}
D[11412] = {"Туда и обратно",{"Возьмите бочку у гоблина, застрявшего на дороге в бухту Острорука, и отвезите ее помощнику Рэя, погонщика баранов. Если баран сбежит от вас, возьмите еще одного у Рэя, погонщика баранов."}}
D[11413] = {"Кто сказал \"сувениры\"?",{"Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля."}}
D[11419] = {"Скаковые бараны Хмельного фестиваля",{"Покажите штамп Дризу Неуклюге у входа на территорию Хмельного фестиваля в Дуротаре."}}
D[11425] = {"Test Quest - Craig",{"Паразиты, ненавижу!"}}
D[11431] = {"Поймать дикого зайцелопа!",{"\"Дворф\", Глодрак Меткий Охотник попросил вас поймать 5 оглушенных летучих зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения."}}
D[11439] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот."}}
D[11440] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот."}}
D[11441] = {"Хмельной фестиваль!",{"Поговорите с распорядителем Хмельного фестиваля."}}
D[11442] = {"Добро пожаловать на Хмельной фестиваль!",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11446] = {"Хмельной фестиваль!",{"Поговорите с распорядителем Хмельного фестиваля."}}
D[11447] = {"Добро пожаловать на Хмельной фестиваль!",{"[PH] Поговорите с распорядителем Хмельного фестиваля и получите бесплатное пиво."}}
D[11449] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Брилле."}}
D[11450] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске на Площади Соколиных Крыльев."}}
D[11451] = {"Стишок Алисии",{"Вас попросили отнести стишок Алисии Кайли Дак в Шаттрат в Запределье."}}
D[11454] = {"Поиски диверсантов",{"Найдите Худовара в \"Угрюмом обжоре\" в Глубинах Черной горы."}}
D[11481] = {"Чрезвычайная ситуация у Солнечного Колодца",{"Адуин Страж Света с возвышенности Алдоров в Шаттрате поручает вам отправиться на плато Солнечного Колодца и поговорить с Ларетором."}}
D[11482] = {"Зов долга",{"Датрис Солнцесвет из Яруса Провидцев Шаттрата настаивает, чтобы вы отправлись в Азерот немедленно, и доложились Ларетору у Солнечного Колодца."}}
D[11486] = {"Лучшее пиво",{"Отнесите бочонок эля Черного Железа Ипфелькоферу Железному Бочонку в Дун Морог."}}
D[11487] = {"Лучшее пиво",{"Отнесите бочонок эля Черного Железа Слухарю Жмухли в Дуротар."}}
D[11488] = {"Терраса Магистров",{"Экзарх Ларетор с подготовительного плацдарма Расколотого Солнца просит вас найти на Террасе Магистров своего разведчика – эльфа крови Тирита."}}
D[11490] = {"Провидец Провидцев",{"Тирит просит вас использовать шар на балконе террасы Магистров."}}
D[11492] = {"Страшный противник",{"Калесгос велит вам уничтожить Кель'таса на Террасе Магистров. Отрубите Келю голову и вернитесь с донесением к Ларетору на подготовительный плацдарм армии Расколотого Солнца."}}
D[11496] = {"Охрана святилища",{"Капитан Терис Сердце Рассвета с подготовительного плацдарма Расколотого Солнца просит вас добыть 4 клочка маны у презренных-злобней и презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке."}}
D[11497] = {"Орлята учатся летать",{"Поговорите с Илсой Бурное Варево в цитадели Громового Молота в долине Призрачной Луны."}}
D[11498] = {"Орлята учатся летать",{"Поговорите с Олрокком в деревне Призрачной Луны в долине Призрачной Луны."}}
D[11499] = {"Разыскивается: перстень-печатка принца Кель'таса",{"Торговец ветром Зарим хочет, чтобы вы добыли ему перстень-печатку принца Кель'таса. Доставьте ее в Нижний город Шаттрата и получите награду.","","Это задание выполняется на террасе Магистров только в героическом режиме."}}
D[11500] = {"Разыскиваются: сестры Терзаний",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 4 сестер терзаний. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду."}}
D[11502] = {"Защита Халаа",{"Победите 10 игроков вражеской фракции в Халаа и вернитесь в Телаар к Лакуру."}}
D[11503] = {"Враги старые и враги новые",{"Победите 10 игроков вражеской фракции в Халаа и вернитесь в Гарадар к Карртогу."}}
D[11505] = {"Духи Аукиндона",{"Помогите Альянсу удерживать Башню духов в Костяных пустошах."}}
D[11506] = {"Духи Аукиндона",{"Помогите Орде удерживать Башню духов в Костяных пустошах."}}
D[11513] = {"Перехват контейнеров с маной",{"Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на Террасу Света в Шаттрат."}}
D[11514] = {"Поддержка портала Солнечного Колодца",{"Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на Террасу Света в Шаттрат."}}
D[11515] = {"Кровь за кровь",{"Магистр Сейла у трона Кил'джедена велит вам убить 4 истощенных сквернокровов при помощи конденсатора Скверны. Вам понадобится кровь демонов, которая течет по венам находящихся рядом зловещих глашатаев, чтобы наполнить конденсатор Скверны."}}
D[11516] = {"Взрыв врат",{"Магистр Сейла у трона Кил'джедена велит вам взять раскаленные угли, чтобы вызвать живую вспышку и убивать рядом с ней раскаленных искр Скверны, пока она не станет нестабильной живой вспышкой. Вернитесь к вратам Легиона вместе с нестабильной живой вспышкой, чтобы уничтожить врата."}}
D[11517] = {"Встреча с Назууном",{"Торговец Портануус просит вас поговорить с экзархом Назууном на Террасе Света в Шаттрате."}}
D[11518] = {"Еежедневный указатель портала Солнечного Колодца"}
D[11520] = {"Смотри в корень",{"Мар'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа."}}
D[11521] = {"И опять – смотри в корень",{"Мар'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа."}}
D[11523] = {"Подпитка для силового поля",{"Капитан Терис Рассветное Пламя с подготовительного плацдарма Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке."}}
D[11524] = {"Хаотичное поведение",{"Поборница Зейанн на подготовительном плацдарме Расколотого Солнца просит, чтобы вы поместили настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим."}}
D[11525] = {"Дальнейшая перенастройка",{"Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит вас поместить настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим."}}
D[11526] = {"Пропавший магистр",{"При помощи захваченного свитка Легиона, пройдите сквозь портал на Рассветной площади. Как только пройдете сквозь портал, найдите магистра Сейлу."}}
D[11528] = {"Подарок к Зимнему Покрову"}
D[11531] = {"Странная деталь мотора",{"Отнесите странную деталь мотора к К. Ли Мелюзге в Терелдор."}}
D[11532] = {"Отвлекающий маневр на Тропе Мертвых",{"Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов."}}
D[11533] = {"Воздушные атаки должны продолжаться!",{"Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов."}}
D[11534] = {"Встреча с Назууном",{"Торговец Портануус просит вас поговорить с экзархом Назууном на Террасе Света в Шаттрате."}}
D[11535] = {"Подготовка к работе",{"Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков."}}
D[11536] = {"Продолжаем...",{"Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков."}}
D[11537] = {"Битва должна продолжаться!",{"Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти."}}
D[11538] = {"Сражение за оружейную Солнечного Края",{"Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади или в оружейной Солнечного Края. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти."}}
D[11539] = {"Захват гавани",{"Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей и 3 метких стрелков из клана Клинка Рассвета."}}
D[11540] = {"Клинки Рассвета должны быть сокрушены!",{"Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей и 3 метких стрелков из клана Клинка Рассвета."}}
D[11541] = {"Зачистить залив Зеленожабрых!",{"Капитан Валиндрия просит вас освободить 10 зеленожабрых-рабов в Заливе Зеленожабрых. Вернитесь к ней на борт \"Гордости Луносвета\" в гавань Солнечного Края по выполнении задания."}}
D[11542] = {"Перехватить подкрепление",{"Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясное Небо насчет полета до флота Клинка Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из клана Клинка Рассвета."}}
D[11543] = {"Загнать врага в угол",{"Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясное Небо насчет полета до флота Клинка Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса корабля, а приземлившись, убейте 6 резервистов из клана Клинка Рассвета."}}
D[11544] = {"Оружие Ата'мала",{"Кузнец Хаутаа просит вас сделать для нее 5 кусков очищенного металла Ата'мала. Сделайте это, раздробив на ее наковальне оружие Ата'мала в оружейной Солнечного Края на острове Кель'Данас."}}
D[11545] = {"Никто не забыт...",{"Анахорет Оури из Солнечного Края острова Солнечного Колодца просит вас пожертвовать 10 золотых."}}
D[11546] = {"Взаимовыгодный бизнес",{"Мар'на из гавани Солнечного Края просит вас принести ей 5 ягод кровяники с кустов, которые можно найти на Кель'Данасе."}}
D[11547] = {"Знай свою силовую линию!",{"Звездочет Дарнариан из святилища Солнечного Края просит вас при помощи кристалла звездочета настроить кровавый кристалл, портал на Рассветной площади и святилище наг в заливе Зеленожабрых."}}
D[11548] = {"Щедрое пожертвование",{"Анахорет Оури из Солнечного Края острова Солнечного Колодца просит вас пожертвовать 10 золотых."}}
D[11549] = {"Великодушный благодетель",{"Анахорет Каиртос просит вас пожертвовать 1000 золотых на дело анахорета Оури. Вас будут называть <имя> из Расколотого Солнца, если вы это сделаете."}}
D[11550] = {"Входи, Искуситель...",{"Отнесите сообщение верховному магу Нет'улу на остров Кель'Данас, к северу от Кель'Таласа.","","Любой распорядитель полетов в Стальгорне или Луносвете доставит вас до места назначения."}}
D[11554] = {"Солдатская дружба",{"Твоя помощь наступательной группировке была замечена, Монд. Объединенные силы Алдоров и Провидцев благодарят тебя."}}
D[11555] = {"Уважение союзников",{"Ты непрестанно проявляешь себя в этой самой важной из битв, Монд. Прошу – прими это в знак нашей великой благодарности."}}
D[11556] = {"Почтение боевых друзей",{"Без тебя мы не смогли бы сделать того, что сделали, Монд. Объединенных сил Алдоров и Провидцев недостаточно, чтобы сокрушить Легион и Келя. Мы рады, что у нас есть такие могучие союзники, как ты."}}
D[11557] = {"Восхищение всего войска",{"Ты – один из наших лучших бойцов, Монд. Твое имя будут помнить среди нас еще долго.","","Прошу – прими этот небольшой подарок от имени всего войска."}}
D[11558] = {"Опасная любовь",{"Возьмите заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде."}}
D[11577] = {"Коллекционное издание WoW: – DEM – E – FLAG"}
