D[11875] = {"Обретение преимущества",{"Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат."}}
D[11877] = {"План нападения клана Ярости Солнца",{"Лорд Торвос из Шаттрата хочет, чтобы вы захватили планы нападения клана Ярости Солнца."}}
D[11880] = {"Мультифазовый подход",{"Предвестник Харонем из Шаттрата просит вас при помощи мультифазовых спектрографических очков 6 раз провести считывание мультифазовых данных."}}
D[11882] = {"Игра с огнем",{"Поговорите с мастером-огнеглотателем в любой из столиц Альянса."}}
D[11883] = {"Танцы с огнем?",{"Поговорите с мастером огненного танца в любой из столиц Орды."}}
D[11885] = {"Кровные враги",{"Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттиса, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра."}}
D[11886] = {"Необычная активность",{"Отправляйтесь в новый лагерь культа Сумеречного Молота к югу от входа в Непроглядную Пучину на Зорамском взморье, что в Ясеневом лесу, и добудьте сумеречную корреспонденцию, затем при помощи тотема-маяка свяжитесь с проводником из Служителей Земли."}}
D[11891] = {"Невинный маскарад",{"При помощи сферы Краба проникните в новый Сумеречный лагерь к западу от входа в Непроглядную Пучину на Зорамском взморье в Ясеневом лесу, затем вызовите проводника из Служителей Земли при помощи тотема-маяка."}}
D[11915] = {"Игра с огнем",{"Поговорите с пламеглотателем-виртуозом в любой из столиц Орды."}}
D[11917] = {"Ответный удар",{"Убейте лейтенанта Хладоволна, помощника Ахуна, вызвав его при помощи Камня Льда на Зорамском взморье в Ясеневом лесу, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11921] = {"Опять бросаем факелы",{"Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом."}}
D[11922] = {"Жонглирование факелами",{"Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом."}}
D[11923] = {"Поймай факел!",{"Поймайте подряд 4 факела, затем поговорите с пламеглотателем-виртуозом."}}
D[11924] = {"Опять жонглирование факелами",{"Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом."}}
D[11925] = {"Опять жонглирование факелами",{"Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом."}}
D[11926] = {"Опять бросаем факелы",{"Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом."}}
D[11933] = {"Похищение пламени Экзодара",{"Верните Пламя Экзодара Праздничному сказителю."}}
D[11935] = {"Похищение пламени Луносвета",{"Верните пламя Луносвета хранителю мудрости Праздника."}}
D[11937] = {"УКАЗАТЕЛЬ – все факелы возвращены, задание выполнено"}
D[11947] = {"Ответный удар",{"Убейте лейтенанта Градня, помощника Ахуна, вызвав его при помощи Камня Льда к Этель-Ретор в Пустошах, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11948] = {"Ответный удар",{"Убейте лейтенанта Промозглый Ветер, помощника Ахуна, вызвав его при помощи Камня Льда на островке элементалей воды к западу от Тернистой долины, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11952] = {"Ответный удар",{"Убейте лейтенанта Лютостужу, помощника Ахуна, вызвав его при помощи Камня Льда в пещере под горами Огненной стражи на северо-западе от Тлеющего ущелья, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11953] = {"Ответный удар",{"Убейте лейтенанта Хладноглыба, помощника Ахуна, вызвав его при помощи Камня Льда в Сумеречной пещере в северном Силитусе, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11954] = {"Ответный удар",{"Убейте Ледяного Храмовника, помощника Ахуна, вызвав его при помощи Камня Льда к Темному порталу на полуострове Адского Пламени, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11955] = {"Ахун, Повелитель Холода",{"Отправляйтесь в Узилище в Резервуар Кривого Клыка, что в Зангартопи и поговорите с Нумой Сестрой Облаков."}}
D[11964] = {"Благовония для летних пламеней",{"Хранитель мудрости Праздника хочет, чтобы вы отнесли благовония Лета летнему пламеню к любому поселению Альянса."}}
D[11966] = {"Благовония для праздничных сполохов",{"Праздничный сказитель хочет, чтобы вы отнесли благовония Лета праздничному сполоху к любому поселению Орды."}}
D[11970] = {"Хранитель мудрости праздника Середины Лета",{"Поговорите с Хранителем мудрости Празднества в любой из столиц Альянса."}}
D[11971] = {"Сказитель Летнего праздника",{"Поговорите с праздничным сказителем в любой из столиц Орды."}}
D[11972] = {"Осколки Ахуна",{"Принесите ледяные осколки Луме Матери Небес."}}
D[11975] = {"Когда я вырасту...",{"Отведите свою подопечную, сиротку Саландрию, посмотреть на группу \"Вожди тауренов\" в Луносвет на Путь Старейшин. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом."}}
D[11976] = {"Ледяные осколки",{"Принесите ледяные осколки Луме Матери Небес."}}
D[12012] = {"Сообщи старейшинам",{"Отправляйтесь в столицу и поговорите со старейшиной Служителей Земли."}}
D[12020] = {"Однажды, напившись в...",{"Поговорите с Бокси Болтокрутом в лагере Хмельного фестиваля."}}
D[12022] = {"Пей до дна!",{"Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом."}}
D[12062] = {"Оскорбить Корена Худовара",{"Поговорите с Кореном Худоваром."}}
D[12191] = {"Пей до дна!",{"Попадите кружкой из-под безалкогольного пробного напитка Хмельного фестиваля в ССМ 5 раз."}}
D[12193] = {"А не будет ли сувенирчика в нынешнем году?",{"Отоварьте свой купон на праздничную кружку у Белби Быстросмен в лагере Хмельного фестиваля."}}
D[12194] = {"А не будет ли сувенирчика в нынешнем году?",{"Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля."}}
D[12278] = {"Клуб \"Пиво месяца\"",{"Отнесите членскую карточку \"Лучшего пивовара месяца\" Ларкину Громовару в таверну \"Горючий камень\" в Стальгорне."}}
D[12306] = {"Клуб \"Пиво месяца\"",{"Отнесите заполненную членскую карточку \"Лучшего пивовара месяца\" Рай'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов."}}
D[12318] = {"Спасем Хмельной фестиваль!",{"Поговорите со шпионом Хмельного фестиваля в трактире \"Угрюмый обжора\" в Глубинах Черной горы."}}
D[12491] = {"Худое варево Худовара",{"Отнесите худое варево Худовара Ипфелькоферу Железному Бочонку в лагерь Хмельного фестиваля возле Стальгорна."}}
D[12492] = {"Худое варево Худовара",{"Отнесите худое варево Худовара Слухарю Жмухли в лагерь Хмельного фестиваля возле Оргриммара."}}
D[12513] = {"Милая шляпка...",{"Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе."}}
D[12515] = {"Милая шляпка...",{"Сам того не желая, Дон Карлос сподвиг вас сразиться с ним молодым в Старом Хилсбраде. Принесите ему шляпу Дона Карлоса в доказательство вашей победы. Он будет ждать вас в Танарисе."}}
D[63866] = {"Получение силы Света",{"Примените мерцающий сосуд к М'ууру, чтобы наполнить его магической силой, и возвращайтесь к предводителю рыцарей по имени Доблестная Кровь в Луносвет."}}
D[64028] = {"Новое начало",{"Встретьтесь с наставником |3-8(<класс>) в Штормграде."}}
